        [6101809] = {
          ContentTC = "「好吧，好吧，我也不是什麼強人所難的壞傢伙嘛。」\n「那我們下次再見！」",
          DialogueId = 6101809,
          GUID = "0F46760A",
          RougeTalkActorType = 1,
