        [10012014] = {
          ContentTC = "不——！！",
          DialogueId = 10012014,
          DisableMouth = 1,
          Duration = 1.5,
          GUID = "191062E9",
          SpeakNpcId = 100003,
          Subtitle = "No—!!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E9"
        },
        [10012015] = {
          ContentTC = "{nickname}，我來考考你。「眨眼三次」這個暗號——",
          DialogueId = 10012015,
          Duration = 5,
          GUID = "191062F0",
          SpeakNpcId = 100003,
          Subtitle = "Quick question, . The \"three quick blinks\" means—",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F0"
        },
        [10012016] = {
          ContentTC = "用不著貝蕾提醒，我早記住啦！眨眼三次的意思是……",
          DialogueId = 10012016,
          Duration = 6,
          ExStoryInfo = "Player",
          GUID = "191062F1",
          SpeakNpcId = 100001,
          Subtitle = "I've got this, Berry. Three quick blinks means...",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F1"
        },
        [10012017] = {
          ContentTC = "「即使只剩一個人，你也要堅強地活下去。」",
          DialogueId = 10012017,
          DialoguePanelType = "None",
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "191062F2",
          SpeakNpcId = 100001,
          Subtitle = "\"Even if left all alone, you should be brave and live on.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F2"
        },
        [10012018] = {
          ContentTC = "「直到我們再次相逢。」",
          DialogueId = 10012018,
          DialoguePanelType = "None",
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "191062F3",
          SpeakNpcId = 100001,
          Subtitle = "\"Until the day we meet again.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F3"
        },
        [10012101] = {
          ContentTC = "那是……",
          DialogueId = 10012101,
          Duration = 1.5,
          GUID = "19107252",
          NextDialogue = 10012102,
          SpeakNpcId = 100005,
          Subtitle = "That is...",
          VoiceName = "voice/$Locale$/story/1001/100121/19107252"
        },
        [10012102] = {
          ContentTC = "零號的力量明明還未解放，為什麼……",
          DialogueId = 10012102,
          Duration = 2.5,
          GUID = "1910727C",
          NextDialogue = 10012103,
          SpeakNpcId = 100005,
          Subtitle = "No. 0 is not supposed to release all her powers yet. Why...",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727C"
        },
        [10012103] = {
          ContentTC = "不，這不是零號自身的力量，而是他人賦予的「和鳴之力」。",
          DialogueId = 10012103,
          Duration = 3,
          GUID = "1910727D",
          NextDialogue = 10012104,
          SpeakNpcId = 100005,
          Subtitle = "No, that's not her power, it's Resonance.",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727D"
        },
        [10012104] = {
          ContentTC = "……她護著的小鬼……是「和鳴之力」新的宿體？",
          DialogueId = 10012104,
          Duration = 2.5,
          GUID = "191072A6",
          NextDialogue = 10012110,
          SpeakNpcId = 100005,
          Subtitle = "...That brat she's trying to protect... That's the new receptacle for the Power of Resonance?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072A6"
        },
        [10012105] = {
          ContentTC = "「和鳴之力」和「零號」一起重現……到底意味著什麼……",
          DialogueId = 10012105,
          Duration = 3,
          GUID = "191072D0",
          SpeakNpcId = 100005,
          Subtitle = "The reappearance of the \"Power of Resonance\" and \"No. 0\" together... What could this possibly mean...?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D0"
        },
        [10012110] = {
          ContentTC = "這麼說來，那小鬼的相貌也……",
          DialogueId = 10012110,
          GUID = "191072D1",
          NextDialogue = 10012105,
          SpeakNpcId = 100005,
          Subtitle = "Come to think of it,  {性别:his|her} face was...",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D1"
        },
        [10012201] = {
          ContentTC = "快走！",
          DialogueId = 10012201,
          Duration = 2,
          GUID = "191082BA",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201003
          },
          SpeakNpcId = 100003,
          Subtitle = "Run!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BA"
        },
        [10012202] = {
          ContentTC = "別想逃！",
          DialogueId = 10012202,
          Duration = 2,
          GUID = "191082BB",
          SpeakNpcId = 100006,
          Subtitle = "You can't get away!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BB"
        },
        [10012301] = {
          Content = "你的伤……好些没有？",
          DialogueId = 10012301,
          Duration = 2,
          GUID = "19109322",
          NextDialogue = 10012302,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/19109322"
        },
        [10012302] = {
          Content = "好多了，只是还有些头晕……",
          DialogueId = 10012302,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910934C",
          NextDialogue = 10012303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934C"
        },
        [10012303] = {
          Content = "那就好，不要勉强自己。",
          DialogueId = 10012303,
          Duration = 2,
          GUID = "1910934D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934D"
        },
        [10012401] = {
          ContentTC = "這裡好像有什麼人生活過。",
          DialogueId = 10012401,
          ExStoryInfo = "Player",
          GUID = "1910A38A",
          NextDialogue = 10012402,
          SpeakNpcId = 100001,
          Subtitle = "It seems someone used to live here.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A38A"
        },
        [10012402] = {
          ContentTC = "我猜，這是貝蕾曾經的家，對嗎？",
          DialogueId = 10012402,
          ExStoryInfo = "Player",
          GUID = "1910A3B4",
          NextDialogue = 10012403,
          SpeakNpcId = 100001,
          Subtitle = "This was your home, am I right, Berry?",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3B4"
        },
        [10012403] = {
          ContentTC = "……我……",
          DialogueId = 10012403,
          GUID = "1910A3DE",
          NextDialogue = 10012404,
          SpeakNpcId = 100003,
          Subtitle = "...I...",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3DE"
        },
        [10012404] = {
          ContentTC = "……是的，不止是我。這裡是「我們」曾經的家。",
          DialogueId = 10012404,
          GUID = "1910A408",
          NextDialogue = 10012405,
          SpeakNpcId = 100003,
          Subtitle = "...Yes, and no. It was OUR home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A408"
        },
        [10012405] = {
          ContentTC = "我們？可我什麼都想不起來。",
          DialogueId = 10012405,
          ExStoryInfo = "Player",
          GUID = "1910A432",
          NextDialogue = 10012406,
          SpeakNpcId = 100001,
          Subtitle = "Our home? But I don't remember a thing.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A432"
        },
        [10012406] = {
          ContentTC = "……沒關係，這樣更好。等逃出去，我們會建起新的家。",
          DialogueId = 10012406,
          GUID = "1910A433",
          SpeakNpcId = 100003,
          Subtitle = "...It's okay. Maybe it's all for the best. After we make it out, we'll build a new home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A433"
        },
        [10012501] = {
          ContentTC = "任務失敗，請重新開始",
          DialogueId = 10012501,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910B3F2",
          SpeakNpcId = 100001,
          Subtitle = "Quest failed. Try again",
          VoiceName = "voice/$Locale$/story/1001/100125/1910B3F2"
        },
        [10012502] = {
          ContentTC = "任務失敗，請重新開始",
          DialogueId = 10012502,
          Duration = 10,
          ExStoryInfo = "Player",
          GUID = "1910B3F3",
          SpeakNpcId = 100001,
          Subtitle = "Quest failed. Try again"
        },
        [10012601] = {
          Content = "净界岛上的小村，我和贝蕾妮卡一起长大的地方。",
          DialogueId = 10012601,
          Duration = 2.5,
          GUID = "1910C45A",
          NextDialogue = 10012602,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C45A"
        },
        [10012602] = {
          Content = "这些叫做秽兽的怪物究竟从何而来，我们也无从得知；",
          DefaultLookAt = "KeepState",
          DialogueId = 10012602,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C484",
          LookAt = {
            [1] = "100001:n(100003)"
          },
          NextDialogue = 10012603,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C484"
        },
        [10012603] = {
          Content = "只知道，昔日宁和的村庄，一夜之间变成了这副模样。",
          DialogueId = 10012603,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C4AE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C4AE"
        },
        [10012701] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentTC = "你回來了。{nickname}……我的半身、我的倒影、我的回聲。",
          DialogueId = 10012701,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D4EC",
          NextDialogue = 10012702,
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 201001,
            [4] = 304002
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You're back, ... My other half, my reflection, and my echo.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D4EC"
        },
        [10012702] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentTC = "你聽到了我的聲音。你找回了那份屬於你的力量。「和鳴」。",
          DialogueId = 10012702,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D516",
          NextDialogue = 10012703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You heard my voice and retrieved the power that belongs to you. The \"Resonance.\"",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D516"
        },
        [10012703] = {
          Camera = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
          ContentTC = "這份力量什麽都沒能改變。我掉進了海裡，不會再醒來，都結束了。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012703,
          Duration = 5,
          ExStoryInfo = "Player",
          FinalCamera = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D540",
          LookAt = {
            [1] = "100001:n(100014)"
          },
          NextDialogue = 10012704,
          SpeakNpcId = 100001,
          Subtitle = "This power didn't change anything. I fell into the sea and I'll never wake up again. It's all over.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D540"
        },
        [10012704] = {
          Camera = "699.554688,-957.21875,341.90564,0.000407,-14.001368,121.374519,35.0,100000.0,false,Manual,22.0",
          ContentTC = "不。我能看見，你的未來、我們的未來……絕非止步於此。",
          DialogueId = 10012704,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "249.050781,-1061.171875,341.90564,0.00044,-16.201441,91.573235,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D56A",
          NextDialogue = 10012705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "No, I can see it — your future, our future... it doesn't end here.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56A"
        },
        [10012705] = {
          ContentTC = "會有人將你從苦澀的海水中打撈出來，帶向一片苦寒的荒原，命運將在那裡降下真正的淬煉。",
          DialogueId = 10012705,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D56B",
          NextDialogue = 10012706,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Someone will pluck you from the briny waters and lead you to a frozen wilderness, where destiny will pose the ultimate test.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56B"
        },
        [10012706] = {
          Camera = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
          ContentTC = "你是說——我還活著？",
          DefaultLookAt = "KeepState",
          DialogueId = 10012706,
          Duration = 5,
          ExStoryInfo = "Player",
          FinalCamera = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D594",
          LookAt = {
            [1] = "100001:n(100014)"
          },
          NextDialogue = 10012712,
          SpeakNpcId = 100001,
          Subtitle = "Are you saying... I'm still alive?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D594"
        },
        [10012707] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……時間到了。讓我給你最後一份助力吧。",
          DialogueId = 10012707,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D595",
          NextDialogue = 10012708,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "...The time has come. Let me offer you one last gift.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D595"
        },
        [10012708] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentTC = "把手給我，{nickname}。",
          DialogueId = 10012708,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D599",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Here, .",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D599"
        },
        [10012709] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentTC = "這些砂礫是你我二人的，連接著過去、現在、與未來的「記憶」。",
          DialogueId = 10012709,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59A",
          NextDialogue = 10012710,
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 201001,
            [4] = 304002
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "These sands are our shared memories, bridging the past, present, and future."
        },
        [10012710] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentTC = "在這些記憶的流沙裡，你將尋得此行的助力。",
          DialogueId = 10012710,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59B",
          NextDialogue = 10012711,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Within these flowing sands of memory, you shall find strength for your journey.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D59B"
        },
        [10012711] = {
          ContentTC = "願他們成為你此行的助力。",
          DialogueId = 10012711,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59C",
          NextDialogue = 10012712,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "May they be your strength on your journey.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D59C"
        },
        [10012712] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentTC = "該出發了。",
          DialogueId = 10012712,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D596",
          NextDialogue = 10012713,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "It's time to set off.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D596"
        },
        [10012713] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……{nickname}。生命是航行在無盡長夜裡的孤船。河流淚水滿溢，夾岸荊棘叢生。",
          DialogueId = 10012713,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D597",
          NextDialogue = 10012714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = ".... Life is like a lonely cruise through the boundless darkness of the night. The river weeps, overflowing its banks, while the thorny thickets on either side stand as a testament to its sorrow.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D597"
        },
        [10012714] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentTC = "我會一直註視著……彼岸的你，將駛向何方。",
          DialogueId = 10012714,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D598",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "I'll keep watching over you, The One Across the Shore... to see where you're going.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D598"
        },
        [10012801] = {
          ContentTC = "這是我第一次來科賽托斯省。看來，這裡的待客之道頗為獨特啊。",
          DialogueId = 10012801,
          Duration = 8.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E52A",
          RelatedWikiId = {
            [1] = 408002
          },
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "This is my first time in the Cocytus Province. Is this how the people here show their hospitality?",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E52A"
        },
        [10012802] = {
          ContentTC = "我沒有任何惡意，只是想同你做一筆……小小的交易。",
          DialogueId = 10012802,
          Duration = 6.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E57E",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I don't want to bother you, I just want to... strike a small \"bargain.\"",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E57E"
        },
        [10012803] = {
          ContentTC = "我會付給你無法拒絕的報酬，而你要做的，非常簡單。",
          DialogueId = 10012803,
          Duration = 6.5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E5A8",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I'll pay you whatever you want, and all you have to do, well, it will be a piece of cake.",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E5A8"
        },
        [10017801] = {
          Content = "......",
          DialogueId = 10017801,
          Duration = 1,
          GUID = "1914197A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001,
            [4] = 401001,
            [5] = 403001
          },
          VoiceName = "voice/$Locale$/story/1002/100178/1914197A"
        },
        [10017901] = {
          ContentTC = "飛艇在山頂。稍微修整一下，就繼續往上走吧。",
          DialogueId = 10017901,
          DisableMouth = 1,
          Duration = 5,
          GUID = "191429E2",
          SpeakNpcId = 100003,
          Subtitle = "The ship is at the mountaintop. After a short break, we'll push on.",
          VoiceName = "voice/$Locale$/story/1001/100179/191429E2"
        },
        [10017902] = {
          ContentTC = "……這麼快，就要和淨界島告別了。",
          DialogueId = 10017902,
          DisableMouth = 1,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19142A0C",
          SpeakNpcId = 100001,
          Subtitle = "...Can't believe we'll be saying goodbye to Purgatorio Island soon.",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0C"
        },
        [10017903] = {
          ContentTC = "……真是片刻也不讓人清淨。",
          DialogueId = 10017903,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "19142A0D",
          SpeakNpcId = 100003,
          Subtitle = "...You creatures just can't give us a break, can you?",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0D"
        },
        [10018001] = {
          Content = "走。",
          DialogueId = 10018001,
          Duration = 2,
          GUID = "19143A4A",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100180/19143A4A"
        },
        [10018101] = {
          DialogueId = 10018101,
          Duration = 1,
          GUID = "19144AB2",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100181/19144AB2"
        },
        [10018201] = {
          Content = "那天，在毁灭之前，我睁开双眼。瞳孔所见之景，是“无限”。",
          DialogueId = 10018201,
          DialoguePanelType = "None",
          Duration = 13,
          ExStoryInfo = "Player",
          GUID = "19145B1A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B1A"
        },
        [10018202] = {
          Content = "第一次，我感受到了，我是如此真实地活着。",
          DialogueId = 10018202,
          DialoguePanelType = "None",
          Duration = 7,
          ExStoryInfo = "Player",
          GUID = "19145B44",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B44"
        },
        [10018301] = {
          Content = "下坠。我本应朝着漆黑的深渊下坠。",
          DialogueId = 10018301,
          Duration = 2.5,
          GUID = "19146B82",
          NextDialogue = 10018302,
          VoiceName = "voice/$Locale$/story/1001/100183/19146B82"
        },
        [10018302] = {
          Content = "但，我却感觉自己在晨雾的怀抱里飘浮。",
          DialogueId = 10018302,
          Duration = 2.5,
          GUID = "19146BAC",
          NextDialogue = 10018303,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BAC"
        },
        [10018303] = {
          Content = "周身被冰冷的触感包围，但意外的是，那种冰冷并不令人恐惧。",
          DialogueId = 10018303,
          Duration = 4,
          GUID = "19146BD6",
          NextDialogue = 10018304,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BD6"
        },
        [10018304] = {
          Content = "而是一种，奇特的触感……亲切，甚至令人怀念。",
          DialogueId = 10018304,
          Duration = 3,
          GUID = "19146C00",
          VoiceName = "voice/$Locale$/story/1001/100183/19146C00"
        },
        [10018401] = {
          ContentTC = "回答我的，只有不盡流瀉的無垠白沙；以及……",
          DialogueId = 10018401,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "19147BEA",
          NextDialogue = 10018402,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "But up until now, there has been no answer. Only endless flowing quicksand covering my vision, and...",
          VoiceName = "voice/$Locale$/story/1001/100184/19147BEA"
        },
        [10018402] = {
          ContentTC = "{性别:她|他}。",
          DialogueId = 10018402,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "19147C14",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "{性别:her|him}.",
          VoiceName = "voice/$Locale$/story/1001/100184/19147C14"
        },
        [10018501] = {
          Content = "占位文本",
          DialogueId = 10018501,
          GUID = "19148C52",
          VoiceName = "voice/$Locale$/story/1001/100185/19148C52"
        },
        [10018601] = {
          ContentTC = "不要……",
          DialogueId = 10018601,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "19149CBA",
          SpeakNpcId = 100001,
          Subtitle = "No...",
          VoiceName = "voice/$Locale$/story/1001/100186/19149CBA"
        },
        [10018602] = {
          ContentTC = "不要……把……她——",
          DialogueId = 10018602,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19149CE4",
          SpeakNpcId = 100001,
          Subtitle = "Don't... take her...",
          VoiceName = "voice/$Locale$/story/1001/100186/19149CE4"
        },
        [10018603] = {
          Content = "滚开。",
          DialogueId = 10018603,
          Duration = 2,
          GUID = "19144AB3",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100181/19144AB3"
        },
        [10018701] = {
          ContentTC = "——「我是誰？」",
          DialogueId = 10018701,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1914AD22",
          SpeakNpcId = 100001,
          Subtitle = "\"Who am I?\""
        },
        [10018801] = {
          DialogueId = 10018801,
          Duration = 1,
          GUID = "1914BD8A",
          VoiceName = "voice/$Locale$/story/1001/100188/1914BD8A"
        },
        [10018901] = {
          Camera = "445.776367,-604.509766,186.644531,0.000533,7.394103,84.717964,24.0,500.0,false,Disable,22.0",
          ContentTC = "出海指望不上了。看來只能試試那個……",
          DefaultLookAt = "KeepState",
          DialogueId = 10018901,
          FacialId = {
            [1] = "100003:Confident01"
          },
          FinalCamera = "504.098145,26.331055,268.859863,0.000533,7.394103,84.717964,24.0,500.0,false,Disable,22.0",
          GUID = "190F9D5E",
          NextDialogue = 10018902,
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001
          },
          SpeakNpcId = 100003,
          Subtitle = "No chance we're leaving by sea. Guess we'll have to count on that thing...",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D5E"
        },
        [10018902] = {
          Camera = "38.842773,139.664062,126.450684,0.000293,2.606147,-116.596527,40.0,195.358566,false,Manual,2.799999",
          ContentTC = "聽我說，這座島上其實還有一艘「船」，就在山上的遺跡裡。",
          DefaultLookAt = "KeepState",
          DialogueId = 10018902,
          GUID = "190FAD72",
          LookAt = {
            [1] = "100001:n(100003)",
            [2] = "100003:n(100001)"
          },
          NextDialogue = 10018903,
          SpeakNpcId = 100003,
          Subtitle = "Listen, there's actually another \"ship\" on this island, up in the mountain ruins.",
          TurnTo = {
            [1] = "100003:p(-40)"
          },
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD72"
        },
        [10018903] = {
          Camera = "-180.119751,-33.829102,148.040039,0.000356,-7.595668,15.806756,35.000008,201.418701,false,Manual,2.8",
          ContentTC = "船——山上的？",
          DefaultLookAt = "KeepState",
          DialogueId = 10018903,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "190FAD9C",
          NextDialogue = 10018904,
          SpeakNpcId = 100001,
          Subtitle = "A ship... on the mountain?",
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9C"
        },
        [10018904] = {
          Camera = "-719.279663,652.294922,186.867676,0.000371,-7.196232,-42.994892,35.0,131.625381,false,Disable,8.286504",
          ContentTC = "嗯，可以飛在天上的「船」。跟我來。",
          DefaultLookAt = "KeepState",
          DialogueId = 10018904,
          FinalCamera = "-767.170166,696.94043,195.135254,0.000371,-7.196232,-42.994892,35.0,131.625381,false,Disable,8.286504",
          GUID = "190FAD9E",
          SpeakNpcId = 100003,
          Subtitle = "Yes, a \"ship\" that flies. Now follow me.",
          TalkActionId = {
            [1] = "100003:Agree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9E"
        },
        [10019001] = {
          ContentTC = "村子裡什麼人聲都沒有，恐怕他們已經……",
          DialogueId = 10019001,
          Duration = 1.8,
          GUID = "1914DE5A",
          NextDialogue = 10019002,
          SpeakNpcId = 100003,
          Subtitle = "The village is in dead silence. I'm afraid they've probably...",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DE5A"
        },
        [10019002] = {
          ContentTC = "……！！",
          DialogueId = 10019002,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1914DE84",
          NextDialogue = 10019003,
          SpeakNpcId = 100001,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DE84"
        },
        [10019003] = {
          ContentTC = "……我的意思是，他們大多應該乘船逃走了。",
          DialogueId = 10019003,
          Duration = 2.5,
          GUID = "1914DEAE",
          NextDialogue = 10019004,
          SpeakNpcId = 100003,
          Subtitle = "...I mean, they've probably scarpered off by boat.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAE"
        },
        [10019004] = {
          ContentTC = "抓緊回家拿到武器，然後去碼頭吧。這裡現在還很危險。",
          DialogueId = 10019004,
          Duration = 2.5,
          GUID = "1914DEAF",
          NextDialogue = 10019005,
          SpeakNpcId = 100003,
          Subtitle = "We should hurry home and get the weapons, and then get to the wharf. It's still dangerous here.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAF"
        },
        [10019005] = {
          ContentTC = "（……我們現在赤手空拳，得儘量避開穢獸。）",
          DialogueId = 10019005,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "1914DEB1",
          NextDialogue = 10019006,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(We're unarmed right now. We have to avoid those Filthoids as much as possible.)",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB1"
        },
        [10019006] = {
          ContentTC = "還差一點……家就在前面了。",
          DialogueId = 10019006,
          Duration = 2.5,
          GUID = "1914DEB2",
          SpeakNpcId = 100003,
          Subtitle = "Almost there. It's up ahead.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB2"
        },
        [10019007] = {
          ContentTC = "（……我們現在赤手空拳，得儘量避開穢獸。）",
          DialogueId = 10019007,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "1914DEB3",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(We're unarmed right now. We have to avoid those Filthoids as much as possible.)",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB1"
        },
        [10019008] = {
          ContentTC = "還差一點……家就在前面了。",
          DialogueId = 10019008,
          Duration = 2.5,
          GUID = "1914DEB4",
          SpeakNpcId = 100003,
          Subtitle = "Almost there. It's up ahead.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEB2"
        },
        [10019101] = {
          ContentTC = "想起▇▇……▇▇，你必須▇▇▇……",
          DialogueId = 10019101,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EEC2",
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Remem▇▇... ▇▇, you must ▇▇▇...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EEC2"
        },
        [10019102] = {
          ContentTC = "你的▇▇……▇▇之力……",
          DialogueId = 10019102,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EEEC",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Your ▇▇... the power of ▇▇...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EEEC"
        },
        [10019103] = {
          ContentTC = "▇▇▇渴望▇▇……這一切……",
          DialogueId = 10019103,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EF16",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "▇▇▇ wish to ▇ all this...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EF16"
        },
        [10019104] = {
          ContentTC = "你在說什麼……",
          DialogueId = 10019104,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "1914EF17",
          SpeakNpcId = 100001,
          Subtitle = "Wait, I can't hear you...",
          VoiceName = "voice/$Locale$/story/1001/100191/1914EF17"
        },
        [10019201] = {
          Content = "关于那柄剑……除了它从小就在身边之外，我一无所知。",
          DialogueId = 10019201,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1914FF2A",
          NextDialogue = 10019202,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF2A"
        },
        [10019202] = {
          Content = "正如我不知道自己从何而来——我没有与贝蕾相遇之前的任何记忆。",
          DialogueId = 10019202,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "1914FF54",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF54"
        },
        [10019301] = {
          ContentTC = "穢獸沒完沒了的……",
          DialogueId = 10019301,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19150F92",
          NextDialogue = 10019302,
          SpeakNpcId = 100001,
          Subtitle = "How many of them are there...",
          VoiceName = "voice/$Locale$/story/1001/100193/19150F92"
        },
        [10019302] = {
          ContentTC = "向上跑。甩掉它們。",
          DialogueId = 10019302,
          Duration = 4,
          GUID = "19150FBC",
          SpeakNpcId = 100003,
          Subtitle = "Let's get to the top to shake them off.",
          VoiceName = "voice/$Locale$/story/1001/100193/19150FBC"
        },
        [10019401] = {
          ContentTC = "這是我第一次來科賽托斯省。看來，這裡的待客之道頗為獨特啊。",
          DialogueId = 10019401,
          Duration = 8,
          ExStoryInfo = "EXPlayer",
          GUID = "19151FFA",
          RelatedWikiId = {
            [1] = 408002
          },
          SpeakNpcId = 100012,
          Subtitle = "This is my first time in Cocytus Province. Is this how the people here show their hospitality?",
          VoiceName = "voice/$Locale$/story/1001/100194/19151FFA"
        },
        [10019402] = {
          ContentTC = "我沒有任何惡意，只是想同你做一筆……小小的交易。",
          DialogueId = 10019402,
          Duration = 5.3,
          ExStoryInfo = "EXPlayer",
          GUID = "19152024",
          SpeakNpcId = 100012,
          Subtitle = "I don't want to bother you, I just want to... strike a small \"bargain.\"",
          VoiceName = "voice/$Locale$/story/1001/100194/19152024"
        },
        [10019403] = {
          ContentTC = "我會付給你無法拒絕的報酬，而你要做的，非常簡單。",
          DialogueId = 10019403,
          Duration = 6.9,
          ExStoryInfo = "EXPlayer",
          GUID = "1915204E",
          SpeakNpcId = 100012,
          Subtitle = "I'll pay you whatever you want, and all you have to do, well, it will be a piece of cake.",
          VoiceName = "voice/$Locale$/story/1001/100194/1915204E"
        },
        [10019501] = {
          Content = "？？？：不杀了{性别：他|她}吗？",
          DialogueId = 10019501,
          Duration = 2.5,
          GUID = "19153057.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153057"
        },
        [10019502] = {
          Content = "？？？：{性别：他|她}和您一样，拥有决定历史轨迹的力量。不要忘记，您的使命。",
          DialogueId = 10019502,
          Duration = 9,
          GUID = "19153058.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153058"
        },
        [10019503] = {
          Content = "？？？：我会处理。但，现在还不是时候。",
          DialogueId = 10019503,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "19153059.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153059"
        },
        [10019504] = {
          Content = "？？？：收到。将如实提交您的答复。",
          DialogueId = 10019504,
          Duration = 5,
          GUID = "19153060.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153060"
        },
        [10019505] = {
          Content = "？？？：……听着，{NickName}。",
          DialogueId = 10019505,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "19153061.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153061"
        },
        [10019506] = {
          Content = "？？？：“生命是航行在无尽长夜里的孤船。”",
          DialogueId = 10019506,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "19153062.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153062"
        },
        [10019507] = {
          Content = "？？？：“河流泪水满溢，夹岸荆棘丛生。”",
          DialogueId = 10019507,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1915308C",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915308C"
        },
        [10019508] = {
          Content = "？？？：“我会一直注视着……”",
          DialogueId = 10019508,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "191530B6",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530B6"
        },
        [10019509] = {
          Content = "？？？：“来自彼岸之人，你将驶向何方。”",
          DialogueId = 10019509,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "191530E0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530E0"
        },
        [10019510] = {
          Content = "（是谁……）",
          DialogueId = 10019510,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1915310A",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915310A"
        },
        [10025701] = {
          ContentTC = "這場逃亡，是從那場奇異的夢開始的；從小到大，我一直重複著相似的夢。",
          DialogueId = 10025701,
          Duration = 3,
          GUID = "19192992",
          NextDialogue = 10025702,
          Subtitle = [[
This escape was heralded by that odd dream.
I've been plagued by similar ones all my life.]],
          VoiceName = "voice/$Locale$/story/1002/100257/19192992"
        },
        [10025702] = {
          ContentTC = "但不容回想，我知道此刻有更急迫的事——",
          DialogueId = 10025702,
          Duration = 3,
          GUID = "191929BC",
          NextDialogue = 10025703,
          Subtitle = "But now's not the time for reflection...\nThere's something more pressing at the moment—",
          VoiceName = "voice/$Locale$/story/1002/100257/191929BC"
        },
        [10025703] = {
          ContentTC = "必須和貝蕾妮卡一起逃離這座叫做「淨界島」的小島，即使這是我們一起長大的地方。",
          DialogueId = 10025703,
          Duration = 4,
          GUID = "191929E6",
          Subtitle = [[
Berry and I must flee from this isle known as "Purgatorio Island,"
where we spent our childhoods together.]],
          VoiceName = "voice/$Locale$/story/1002/100257/191929E6"
        },
        [10025704] = {
          ContentTC = "因為我們平靜的生活，早已被穢獸的利爪撕碎……",
          DialogueId = 10025704,
          Duration = 3,
          GUID = "19192A10",
          Subtitle = "For the peace we once knew has been torn asunder by the vile claws of Filthoids...",
          VoiceName = "voice/$Locale$/story/1002/100257/19192A10"
        },
        [10025801] = {
          ContentTC = "這些穢獸……死了？",
          DialogueId = 10025801,
          ExStoryInfo = "Player",
          GUID = "191939FA",
          NextDialogue = 10025802,
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/191939FA"
        },
        [10025802] = {
          ContentTC = "看來在我們之前，這裡就有人和穢獸戰鬥過。而且，還沒過去太久。",
          DialogueId = 10025802,
          GUID = "19193A24",
          NextDialogue = 10025803,
          SpeakNpcId = 100003,
          Subtitle = "It seems someone had a fight with them just before we arrived.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A24"
        },
        [10025803] = {
          ContentTC = "難道有村民逃到了這裡……不，那扇門是我們打開的才對。",
          DialogueId = 10025803,
          ExStoryInfo = "Player",
          GUID = "19193A4E",
          NextDialogue = 10025804,
          SpeakNpcId = 100001,
          Subtitle = "Could it be one of the villagers... No, we were the first to open that door.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A4E"
        },
        [10025804] = {
          ContentTC = "不過好在有他幫忙清理，否則穢獸就更難對付了。",
          DialogueId = 10025804,
          ExStoryInfo = "Player",
          GUID = "19193A78",
          NextDialogue = 10025805,
          SpeakNpcId = 100001,
          Subtitle = "Anyway, thanks to that person, we don't have to deal with these Filthoids ourselves.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A78"
        },
        [10025805] = {
          ContentTC = "無論是誰，他的實力都不容小覷。我們也要留心。",
          DialogueId = 10025805,
          GUID = "19193AA2",
          SpeakNpcId = 100003,
          Subtitle = "Whoever it was, they're not to be underestimated. We must be vigilant.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA2"
        },
        [10025806] = {
          ContentTC = "這些穢獸……斷氣了？",
          DialogueId = 10025806,
          ExStoryInfo = "Player",
          GUID = "19193AA3",
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA3"
        },
        [10027501] = {
          ContentTC = "在不遠處",
          DialogueId = 10027501,
          Duration = 2,
          GUID = "191A50E2",
          Subtitle = "A short distance away...",
          VoiceName = "voice/$Locale$/story/1001/100275/191A50E2"
        },
        [10029301] = {
          ContentTC = "無數次，螺旋般往復的夢中，我一遍又一遍地問著。",
          DialogueId = 10029301,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "1914AD4C",
          NextDialogue = 10018401,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "In my dreams that unfold like a double helix, I've asked myself that question countless times.",
          VoiceName = "voice/$Locale$/story/1002/100293/1914AD4C"
        },
        [10029309] = {
          Content = "恭喜你起名完成啦！！！！！",
          DialogueId = 10029309,
          Duration = 3,
          GUID = "1914AD4D",
          VoiceName = "voice/$Locale$/story/1002/100293/"
        },
        [10029401] = {
          ContentTC = "要再休息一會嗎？",
          DialogueId = 10029401,
          GUID = "1914AD4E",
          SpeakNpcId = 100003,
          Subtitle = "Want to rest a bit more?"
        },
        [10030101] = {
          ContentTC = "呼……呼……",
          DialogueId = 10030101,
          Duration = 3,
          GUID = "191BFB72",
          SpeakNpcId = 100001,
          Subtitle = "Huff... huff...",
          VoiceName = "voice/$Locale$/story/1003/100301/191BFB72"
        },
        [10030201] = {
          DialogueId = 10030201,
          Duration = 3,
          GUID = "191C0BDA",
          VoiceName = "voice/$Locale$/story/1003/100302/191C0BDA"
        },
        [10030202] = {
          Content = "打开推理小游戏",
          DialogueId = 10030202,
          GUID = "191C0BDB"
        },
        [10030301] = {
          Camera = "-229.695435,48.554688,189.588501,0.000025,-8.400114,39.796463,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……卡蜜拉？",
          DialogueId = 10030301,
          GUID = "191C1C42",
          SpeakNpcId = 100001,
          Subtitle = "...Camilla?",
          VoiceName = "voice/$Locale$/story/1003/100303/191C1C42"
        },
        [10030302] = {
          ContentTC = "嘴裡的藥，先嚥下去。",
          DialogueId = 10030302,
          GUID = "191C1C6C",
          SpeakNpcId = 200003,
          Subtitle = "Swallow the medicine first.",
          VoiceName = "voice/$Locale$/story/1003/100303/191C1C6C"
        },
        [10030401] = {
          Camera = "67.060974,63.269043,215.128113,0.000134,-36.998093,133.003891,35.000015,115.415909,false,Manual,2.8",
          ContentTC = "你……我這是……",
          DialogueId = 10030401,
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "58.562622,72.381348,205.739349,0.000134,-36.998093,133.003891,35.000015,115.415909,false,Manual,2.8",
          GUID = "191C2CAA",
          LookAt = {
            [1] = "100001:n(200003)",
            [2] = "200003:n(100001)"
          },
          NextDialogue = 10030402,
          SpeakNpcId = 100001,
          Subtitle = "Camilla... why was I...",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2CAA"
        },
        [10030402] = {
          Camera = "86.758911,282.283203,92.856476,0.000175,5.190773,-113.187576,35.000011,284.956726,false,Manual,2.8",
          ContentTC = "睡了五天，運氣不錯。再多一天，這輩子可能都醒不過來了。",
          DialogueId = 10030402,
          FinalCamera = "86.758911,282.283203,92.856476,0.00018,11.790866,-114.790039,35.000011,284.956726,false,Manual,2.8",
          GUID = "191C2CD4",
          NextDialogue = 10030403,
          SpeakNpcId = 200003,
          Subtitle = "You've been unconscious for five days. Lucky you. Another day, and you might never have woken up.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2CD4"
        },
        [10030403] = {
          Camera = "86.758911,282.283203,92.856476,0.000164,14.190912,-114.991394,35.000008,284.956726,false,Manual,2.8",
          ContentTC = "所以，這些天是你在……謝……",
          DialogueId = 10030403,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191C2CFE",
          NextDialogue = 10030404,
          SpeakNpcId = 100001,
          Subtitle = "So, you've been... Thank you...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2CFE"
        },
        [10030404] = {
          Camera = "68.587265,188.526855,131.323135,0.000194,3.19883,-111.220688,35.000015,153.176254,false,Manual,2.8",
          ContentTC = "不用謝我。你現在可今非昔比了，因為上次群星綺晶的事，現在可有不少委託指名讓你去呢。",
          DialogueId = 10030404,
          FinalCamera = "68.587265,188.526855,131.323135,0.000192,7.598797,-111.820282,35.000015,153.176254,false,Manual,2.8",
          GUID = "191C2D28",
          NextDialogue = 10030405,
          SpeakNpcId = 200003,
          Subtitle = "No need to thank me. You're not who you used to be. Since the request involving the Crystallo of Stella, plenty of commissions have come in specifically for you.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2D28"
        },
        [10030405] = {
          Camera = "98.511124,-16.412109,172.841675,0.000205,-11.603302,130.15361,35.000019,202.161392,false,Manual,2.8",
          ContentTC = "可別活還沒幹完，人先沒了。",
          DialogueId = 10030405,
          GUID = "191C2D52",
          NextOptions = {
            [1] = 10030406,
            [2] = 10030408
          },
          SpeakNpcId = 200003,
          Subtitle = "Just make sure you stay alive long enough to finish the gigs.",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100304/191C2D52"
        },
        [10030406] = {
          ContentTC = "卡蜜拉女士真是嘴硬心軟。",
          DialogueId = 10030406,
          GUID = "191C2D7C",
          ImprPlusId = 1008,
          NextDialogue = 10030407,
          Subtitle = "Ms Camilla, you really are tough on the outside but soft on the inside."
        },
        [10030407] = {
          Camera = "42.419052,245.519531,108.856918,0.000246,12.994878,-104.423546,35.000015,203.457535,false,Manual,2.8",
          ContentTC = "油嘴滑舌。跟奧特賽德學的？",
          DialogueId = 10030407,
          GUID = "191C2DA6",
          LookAt = {
            [1] = "200003:n(100001)"
          },
          NextDialogue = 10030411,
          SpeakNpcId = 200003,
          Subtitle = "You little smooth talker. Did you pick that up from Outsider?",
          TalkActionId = {
            [1] = "200003:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100304/191C2DA6"
        },
        [10030408] = {
          ContentTC = "……要不，還是讓我死一會兒？",
          DialogueId = 10030408,
          GUID = "191C2DD0",
          ImprPlusId = 1010,
          NextDialogue = 10030409,
          Subtitle = "...Maybe I should've just stayed dead for a while."
        },
        [10030409] = {
          Camera = "42.419052,245.519531,108.856918,0.000246,12.994892,-104.423515,35.000015,243.87735,false,Manual,2.8",
          ContentTC = "呵，現在後悔被我救下也來不及了。",
          DialogueId = 10030409,
          GUID = "191C2DFA",
          LookAt = {
            [1] = "200003:n(100001)"
          },
          NextDialogue = 10030411,
          SpeakNpcId = 200003,
          Subtitle = "Heh, regretting being saved by me? Too late.",
          TalkActionId = {
            [1] = "200003:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100304/191C2DFA"
        },
        [10030410] = {
          Camera = "236.477112,-183.054688,160.382812,0.000109,-10.003269,137.977005,25.0,142.250885,false,DoNotOverride,3.0",
          DialogueId = 10030410,
