        [10030411] = {
          Camera = "166.64328,-62.497559,178.52565,0.000175,-8.403386,136.948242,35.000011,142.834564,false,Manual,22.0",
          ContentTC = "對了，有個人來看了你幾次——黎瑟·費西爾，衛戍部隊的軍官。",
          DialogueId = 10030411,
          GUID = "191C2E4E",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextDialogue = 10030412,
          Scripts = [[
PARA{
CameraMoveTo{_delay{1.7},TargetPosition{"80.631256,-105.42334,178.525864,0.000194,-10.203278,115.354225,35.000015,142.834564,false,Manual,22.0"},duration{1.3}},
SEQ{
