}]],
          SpeakNpcId = 200003,
          Subtitle = "Anyway, someone came by a few times to check up on you. It's Rhythm Fischer, a warrant officer in the Escort.",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2E4E"
        },
        [10030412] = {
          ContentTC = "我是第六軍團下屬，科賽托斯行省衛戍部隊準尉，黎瑟·費西爾。",
          DialogueId = 10030412,
          GUID = "191C2E78",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030412.T_Story_Recall_10030412'",
          NextDialogue = 10030413,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
