          SpeakNpcId = 100304,
          Subtitle = "Rhythm Fischer, Warrant Officer of the Cocytus Escort, 6th Legion.",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2E78"
        },
        [10030413] = {
          ContentTC = "她託我帶個話，說有事想找你聊聊。",
          DialogueId = 10030413,
          GUID = "191C2EA2",
          NextOptions = {
            [1] = 10030414,
