        [10030701] = {
          Camera = "380.175964,73.087891,134.875,0.000271,-19.394896,-137.947372,35.000011,55.953648,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "太好了，看樣子你已經沒有大礙了。",
          DialogueId = 10030701,
          FinalCamera = "380.175964,73.087891,134.875,0.000278,-2.194144,-169.342743,35.000011,355.630981,false,Manual,3.0",
          GUID = "191C5DE2",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10030702,
          RelatedWikiId = {
            [1] = 201011
          },
          SpeakNpcId = 100304,
          Subtitle = "It's great to see that you're recovering well.",
