          VoiceName = "voice/$Locale$/story/1003/100307/191C5DE2"
        },
        [10030702] = {
          Camera = "-89.270386,-159.456055,192.513672,0.000299,-23.794125,44.6567,35.000015,330.701721,false,Manual,3.0",
          ContentTC = "長官要喝點什麼嗎？今天「冰湖往事」打五折哦。",
          DialogueId = 10030702,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "191C5E0C",
          LookAt = {
            [1] = "100304:n(200002)"
          },
          NextDialogue = 10030703,
          SpeakNpcId = 200002,
          Subtitle = "Would you like something to drink, Officer? Tales of Icelake is on special today — half price!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5E0C"
        },
        [10030703] = {
          Camera = "29.417786,145.418945,56.080078,0.000265,19.004721,-80.540367,35.000011,219.87709,false,Manual,3.0",
          ContentTC = "不用。帝國軍律第142條規定軍人執勤期間不能飲酒，而且我也沒有這個習慣。",
          DialogueId = 10030703,
          FacialId = {
            [1] = "200002:None",
            [2] = "100304:Shock01"
          },
          GUID = "191C5E36",
          NextDialogue = 10030704,
          SpeakNpcId = 100304,
          Subtitle = "No, thanks. Imperial Military Code Article 142 prohibits soldiers from drinking while on duty. Besides, I don't drink anyway.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5E36"
        },
        [10030704] = {
          Camera = "-373.256409,-7.81543,220.638672,0.000206,-19.196136,3.056015,25.0,219.87709,false,Manual,3.0",
          ContentTC = "我直接說正題吧。我是為了調查冰湖城外城近幾日的惡性事件「卡戎狩獵」而來。",
          DialogueId = 10030704,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "-330.987732,-5.65625,205.90625,0.000206,-19.196136,2.856016,25.0,219.87709,false,Manual,3.0",
          GUID = "191C5E60",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10030705,
          SpeakNpcId = 100304,
          Subtitle = "Let's get straight to the point. I'm here to investigate the recent violent incidents in the outer city of Icelake, known as the \"Charon Hunt.\"",
          TalkActionId = {
            [1] = "200002:Explain02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5E60"
        },
        [10030705] = {
          Camera = "-196.299988,-7.27832,128.933594,0.000239,-0.99649,-6.538433,35.000019,254.835373,false,Manual,6.0",
          ContentTC = "這是第一次詢問，我需要按照慣例確認一下你的身份。可以給我看一下<H>通行證</>嗎？",
          DialogueId = 10030705,
          GUID = "191C602F",
          NextDialogue = 10030706,
          SpeakNpcId = 100304,
          Subtitle = "This is your first enquiry. I need to verify your identity according to standard procedure. Could you show me your travel permit?",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C602F"
        },
        [10030706] = {
          Camera = "-16.850769,-112.700195,139.550781,0.000263,-2.797638,120.662224,35.000019,146.760483,false,Manual,6.0",
          ContentTC = "…………！",
          DialogueId = 10030706,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "191C6030",
          NextDialogue = 10030707,
          SpeakNpcId = 100001,
          Subtitle = "...!",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6030"
        },
        [10030707] = {
          ContentTC = "我急著出門，通行證還在家裡，我先回去拿。",
          DialogueId = 10030707,
          GUID = "191C6031",
          NextDialogue = 10030708,
          SpeakNpcId = 100001,
          Subtitle = "I was in such a rush when I left home that I forgot to bring it. Let me go grab it now.",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6031"
        },
        [10030708] = {
          Camera = "20.996643,167.708008,186.025391,0.000272,-16.19771,-130.733917,35.000015,206.537537,false,Manual,3.0",
          ContentTC = "記錯了吧？你通行證前幾天落在我家了，我正準備還給你——喏，長官，在這兒。",
          DialogueId = 10030708,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191C6032",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10030709,
          SpeakNpcId = 200021,
          Subtitle = "Your head must still be foggy from your injuries — you left your travel permit at my place a few days ago. I was just about to return it to you. Here you go, Officer.",
          TalkActionId = {
            [1] = "200021:Give"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6032"
        },
        [10030709] = {
          Camera = "20.996643,167.708008,186.025391,0.000272,-16.19771,-130.733917,35.000015,206.537537,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "……名字，{nickname}。居住城市，科賽托斯省，冰湖城。職業，馴獸師……",
          DialogueId = 10030709,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Passport.T_Guide_Chapter_Passport'}",
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "20.996643,167.708008,186.025391,0.000264,-15.397602,-85.33358,35.000015,310.0784,false,Manual,3.0",
          GUID = "191C6033",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10030710,
          SpeakNpcId = 100304,
          Subtitle = "...Name: . Place of residence: Icelake, Cocytus Region. Occupation: Animal Trainer...?",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100307/191C6033"
        },
        [10030710] = {
          Camera = "-80.779236,-40.317383,131.921875,0.000273,3.401782,-7.736254,35.000023,126.193214,false,Manual,6.0",
          ContentTC = "呃，你不是狩月人嗎？",
          DialogueId = 10030710,
          FacialId = {
            [1] = "100304:Unacceptable01"
          },
          GUID = "191C6034",
          NextDialogue = 10030711,
          SpeakNpcId = 100304,
          Subtitle = "Wait, aren't you a Phoxhunter?",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6034"
        },
        [10030711] = {
          Camera = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
          ContentTC = "那是過去的事了。{性别:他|她}以前是專門給有錢人養狗的，前任主人破產了吃不上飯才來幹這行。",
          DialogueId = 10030711,
          GUID = "191C6035",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10030712,
          SpeakNpcId = 200021,
          Subtitle = "That's the latest development. {性别:He|She} used to take care of dogs for rich folks, but {性别:his|her} last employer went broke and couldn't afford to hire {性别:him|her} anymore. Hence the career change.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6035"
        },
        [10030712] = {
          ContentTC = "不信你去卡蜜拉女士那兒問問，{性别:他|她}就是前幾天才登記成狩月人的。來，{nickname}，給長官展示一下你高超的訓犬技巧。",
          DialogueId = 10030712,
          GUID = "191C6036",
          NextDialogue = 10030713,
          SpeakNpcId = 200021,
          Subtitle = "If you don't believe me, you can ask Ms Camilla — {性别:he|she} just signed up at her tavern to become a Phoxhunter a couple of days ago. Come on, , show Officer Fischer your awesome dog-training skills.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6036"
        },
        [10030713] = {
          Camera = "35.158813,-132.652344,109.820312,0.000287,8.387151,125.228546,35.000023,303.465393,false,Manual,6.0",
          ContentTC = "嘬嘬嘬。",
          DialogueId = 10030713,
          GUID = "191C6037",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = "200021:n(100001)",
            [3] = "100304:n(100001)"
          },
          NextDialogue = 10030714,
          SpeakNpcId = 100001,
          Subtitle = "{性别:|Come on!} Come here, boy!",
          TalkActionId = {
            [1] = "200021:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6037"
        },
        [10030714] = {
          ContentTC = "不是，你對著我嘬什麼啊！",
          DialogueId = 10030714,
          FacialId = {
            [1] = "200021:Shock01"
          },
          GUID = "191C6038",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10030715,
          SpeakNpcId = 200021,
          Subtitle = "What— I'm not a dog!",
          TalkActionId = {
            [1] = "200021:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6038"
        },
        [10030715] = {
          Camera = "-203.567261,147.061523,100.875,0.000257,3.596395,-42.564396,35.000015,382.628754,false,Manual,3.0",
          ContentTC = "……好，通行證我看過沒問題了，謝謝配合。接下來，我們來說襲擊的事吧。",
          DialogueId = 10030715,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "-204.68335,145.84668,116.058594,0.000257,3.596395,-42.564442,35.000019,321.983032,false,Manual,6.0",
          GUID = "191C6039",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "100304:n(100001)"
          },
          NextDialogue = 10030716,
          SpeakNpcId = 100304,
          Subtitle = "...Alright, I've verified the travel permit. Thank you for your cooperation. Now, let's talk about the attack.",
          TalkActionId = {
            [1] = "200021:Shock_End",
            [2] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100307/191C6039"
        },
        [10030716] = {
          Camera = "-70.692688,-985.964844,130.398438,0.000275,-3.004272,85.63118,35.000011,8667.292969,false,Manual,3.0",
          ContentTC = "我想盡快抓住那個襲擊你的兇手，還你們大家一個安全。{nickname}，你是這次連續襲擊中唯一的倖存者，對我們掌握案情至關重要。只是酒館人多眼雜——",
          DialogueId = 10030716,
          FinalCamera = "-68.961426,-964.299805,129.412109,0.000276,-2.604269,85.431206,35.000011,8667.292969,false,Manual,3.0",
          GUID = "191C5E8A",
          NextDialogue = 10030717,
          Scripts = "LookAt{LookAtDescription{\"100304:p(lise_03_looking)\"}}",
          SpeakNpcId = 100304,
          Subtitle = "I want to catch the culprit who attacked you and bring safety back to everyone as soon as possible. As the sole survivor of the incident, your testimony is vital for us to fully understand the case. That said, this tavern is hardly an appropriate place for an enquiry—",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5E8A"
        },
        [10030717] = {
          Camera = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
          ContentTC = "哦，懂了。那我們就找個安靜點的地方聊吧。",
          DialogueId = 10030717,
          GUID = "191C5EB4",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10030718,
          SpeakNpcId = 200021,
          Subtitle = "Ah, got it. Let's get to a quieter place to talk then.",
          TalkActionId = {
            [1] = "200021:AgreeHead",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5EB4"
        },
        [10030718] = {
          Camera = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
          ContentTC = "萬分感謝，請隨我來。",
          DialogueId = 10030718,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191C5EDE",
          NextDialogue = 10030719,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100304:n(100304)"}},   
MoveTo{ActorId{100304},TargetPoint{"lise_03_leave"},MoveSpeed{90},Visibility{"Show"}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "Thank you for understanding. Please come with me.",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5EDE"
        },
        [10030719] = {
          Camera = "-159.366272,-113.829102,114.5625,0.000285,10.592653,64.027985,35.000019,242.113937,false,Manual,6.0",
          ContentTC = "喂，發什麼呆呢？",
          DialogueId = 10030719,
          GUID = "191C5F08",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = "200021:n(100001)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 10030720,
          Scripts = "SetLocation{ActorId{100304},TargetPoint{\"lise_03_leave\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Hey, what are you waiting for?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          TurnTo = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F08"
        },
        [10030720] = {
          ContentTC = "不會是在氣通行證的事吧。那個，咳，熟人手頭的通行證只有馴獸師的了，將就一下。",
          DialogueId = 10030720,
          GUID = "191C603A",
          NextDialogue = 10030721,
          SpeakNpcId = 200021,
          Subtitle = "Don't tell me you're upset about the travel permit. Well, uh, that was the only type I could get for you. Just roll with it, alright?",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C603A"
        },
        [10030721] = {
          Camera = "-6.562927,-65.756836,132.560547,0.000286,2.591954,141.833664,35.000019,103.402161,false,Manual,6.0",
          ContentTC = "…………",
          DialogueId = 10030721,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191C5F32",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10030722,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200021:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F32"
        },
        [10030722] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0",
          ContentTC = "好吧，那你八成還是在為那晚的事生黎瑟·費西爾的氣囖。",
          DialogueId = 10030722,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "191C5F5C",
          NextDialogue = 10030723,
          SpeakNpcId = 200021,
          Subtitle = "Alright, I know. You're probably still bitter about Rhythm Fischer for what happened that night.",
          TalkActionId = {
            [1] = "200021:Explain01_Start",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F5C"
        },
        [10030723] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0",
          ContentTC = "不過，要是能跟費西爾混熟，倒不是件壞事。軍團的情報網四通八達，你<H>找人</>那事，興許會有眉目。",
          DialogueId = 10030723,
          GUID = "191C5FB0",
          NextDialogue = 10030724,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"-22.493896,92.760742,157.833984,0.000282,-9.206241,-123.576553,35.000019,109.330856,false,Manual,3.0\"},duration{0}}",
          SpeakNpcId = 200021,
          Subtitle = "But, it wouldn't be a bad thing to get on good terms with Fischer. I mean, the Legion's got connections everywhere. Your search for somebody might get somewhere.",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB0"
        },
        [10030724] = {
          Camera = "7.651123,-118.004883,114.373047,0.000265,8.99109,120.035538,35.000019,156.230972,false,Manual,6.0",
          ContentTC = "而且，你難道就不想親手抓住那個不講武德，背後偷襲的兇手嗎？",
          DialogueId = 10030724,
          GUID = "191C5FB1",
          NextDialogue = 10030725,
          SpeakNpcId = 200021,
          Subtitle = "Besides, don't you want to take down that dishonorable coward with your own hands?",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB1"
        },
        [10030725] = {
          ContentTC = "至於我嘛，也想快點把「卡戎狩獵」這事解決了。現在整座外城都人心惶惶的，生怕下個就是自己。我家那破門也實在是加不了更多鎖了。",
          DialogueId = 10030725,
          GUID = "191C5F86",
          NextDialogue = 10030726,
          SpeakNpcId = 200021,
          Subtitle = "As for me, I want this whole \"Charon Hunt\" mess resolved as soon as possible, too. The whole outer city's been on edge, and that rickety old door on my house can't take another lock.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F86"
        },
        [10030726] = {
          Camera = "13.800354,86.224609,170.464844,0.000277,-12.408418,-140.354614,35.000015,93.577675,false,Manual,3.0",
          ContentTC = "軍團……貝蕾的消息……",
          DialogueId = 10030726,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "13.800354,86.224609,170.464844,0.000278,-16.20825,-139.955261,35.000019,129.836029,false,Manual,6.0",
          GUID = "191C5FDA",
          NextDialogue = 10030727,
          SpeakNpcId = 100001,
          Subtitle = "The Legion... Berry's whereabout...",
          TalkActionId = {
