        [10030803] = {
          Camera = "938.864258,-1600.42627,644.140015,0.000063,-15.356232,125.519363,35.000008,3496.211426,false,Manual,1.2",
          ContentTC = "「卡戎狩獵」是一起發生在冰湖城的連續兇案，想必你們已經有所耳聞了。",
