          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6EC8"
        },
        [10030805] = {
          Camera = "23.945312,90.854004,160.98999,10.805622,-22.999117,107.011467,25.0,1.5,false,DoNotOverride,1.2",
          ContentTC = "凶案集中發生在東區，這一帶居住的大多是卡戎之民，所以就有了「卡戎狩獵」這個名字。",
          DialogueId = 10030805,
          FacialId = {
            [1] = "100304:Confident01"
