          NextDialogue = 10030807,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Yeah, we've heard about that. What do you need from ?",
