          VoiceName = "voice/$Locale$/story/1003/100308/191C6F1C"
        },
        [10030807] = {
          Camera = "35.023438,-85.893799,135.901367,-0.000122,-1.000022,97.196419,40.0,1.5,false,DoNotOverride,1.2",
          ContentTC = "我需要{nickname}提供盡可能多的案件細節。等一會兒，我會帶你們去五天前{性别:他|她}遇襲的現場，那條街現在已經被軍團封鎖了。",
          DialogueId = 10030807,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "39.05957,-117.875977,136.462891,-0.000122,-1.000022,97.196419,40.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6F46",
          NextDialogue = 10030808,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"Talk01_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I need  to provide as many details about the case as possible. In a while, I'll take you all to the scene where {性别:he|she} was attacked five days ago. That street is currently sealed off by the Legion.",
          TalkActionId = {
            [1] = "100304:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6F46"
        },
        [10030808] = {
