          Scripts = "PARA{PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Shock_End\"},Duration{2}}},SEQ{CameraMoveTo{_delay{2},TargetPosition{\"317.952148,296.217041,241.933594,0.00006,-17.356466,-140.280762,25.000006,1.5,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"392.445312,358.106934,272.203857,0.00006,-17.356466,-140.280762,25.000006,1.5,false,DoNotOverride,1.2\"},duration{10}}}",
