        [10031009] = {
          Camera = "16.606445,-174.10498,173.058594,10.800163,-21.601551,-45.770706,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentTC = "（等一下……我還記得剛走到這條街的時候，風剛停，月亮出來了。看月亮的位置，應該是……<H>凌晨四點到五點之間</>？）",
