        [10031110] = {
          Camera = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22",
          ContentTC = "沒錯……雖然嗓音嘶啞，像破風箱一樣，但它在唱歌，<H>那隻怪物在唱歌</>。",
          DialogueId = 10031110,
          GUID = "191CA0FC",
          NextDialogue = 10031111,
          SpeakNpcId = 100001,
          Subtitle = "Yes, that's it. Its voice was raspy, broken — almost like wind blowing through shattered pipes. But that monster was unmistakably singing.",
          VoiceName = "voice/$Locale$/story/1003/100311/191CA0FC"
        },
        [10031111] = {
          Camera = "105.765625,-455.361328,108.25,0.000137,4.600098,105.407356,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "歌聲？這個還沒有人說過——太好了，是全新的線索！我就知道你那一下不會白挨。",
          DialogueId = 10031111,
          FacialId = {
            [1] = "100304:Happy01"
          },
          GUID = "191CA126",
          NextDialogue = 10031112,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "A singing voice? No one else has mentioned that — Great, this is a brand-new lead! I knew your suffering wouldn't be in vain.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA126"
        },
        [10031112] = {
          Camera = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentTC = "喂，我說長官，人家經歷挺痛苦的，這麼激動不太好吧？",
          DialogueId = 10031112,
          GUID = "191CA150",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10031113,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"200021:n(100304)\"}},PlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Ahem, Officer, that might come across as a bit insensitive, don't you think?",
          TalkActionId = {
            [1] = "100304:Confident_End",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA150"
        },
        [10031113] = {
          Camera = "90.230469,-472.615723,119.978027,0.000191,-0.400393,102.219055,40.0,941.904541,false,DoNotOverride,1.2",
          ContentTC = "……抱歉。剛剛我只是想，案子有了突破口，興許就可以早點結束這場「狩獵」，還大家一個安寧了。我沒有拿你的痛苦回憶取樂的意思，萬分抱歉。",
          DialogueId = 10031113,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191CA17A",
          NextOptions = {
            [1] = 10031114,
            [2] = 10031116
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "...My apologies. I was just thinking that with this new clue, we might finally end this case and restore peace to everyone. I didn't mean to trivialise your pain and suffering. I'm truly sorry.",
          TalkActionId = {
            [1] = "200021:Explain01_End",
            [2] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA17A"
        },
        [10031114] = {
          ContentTC = "我沒有介意。",
          DialogueId = 10031114,
          GUID = "191CA1A4",
          ImprPlusId = 1007,
          NextDialogue = 10031115,
          Subtitle = "It's okay."
        },
        [10031115] = {
          Camera = "58.354492,-249.67041,147.177734,0.000189,-3.600589,110.819168,40.0,941.904541,false,DoNotOverride,1.2",
          ContentTC = "謝謝你的寬容。",
          DialogueId = 10031115,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191CA1CE",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031123,
          SpeakNpcId = 100304,
          Subtitle = "Thank you for your understanding.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA1CE"
        },
        [10031116] = {
          ContentTC = "我要精神損失費。",
          DialogueId = 10031116,
          GUID = "191CA1F8",
          ImprPlusId = 1010,
          NextDialogue = 10031117,
          Subtitle = "I want compensation for emotional damage."
        },
        [10031117] = {
          Camera = "58.354492,-249.67041,147.177734,0.000189,-3.600589,110.819168,40.0,941.904541,false,DoNotOverride,1.2",
          ContentTC = "你需要多少？如果在我可以承受的範圍內……",
          DialogueId = 10031117,
          GUID = "191CA222",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031118,
          SpeakNpcId = 100304,
          Subtitle = "How much do you need? If it's within my means...",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA222"
        },
        [10031118] = {
          Camera = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentTC = "這玩笑都當真？長官小姐，您是個沒怎麼跟外城人打過交道的「桂冠卡戎」吧？",
          DialogueId = 10031118,
          GUID = "191CA24C",
          NextDialogue = 10031119,
          RelatedWikiId = {
            [1] = 407003
          },
          SpeakNpcId = 200021,
          Subtitle = "Seriously? It's obviously a joke... Officer, you must be a Laurelled Charon who's never dealt with the folks in the outer city, right?",
          TalkActionId = {
            [1] = "200021:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA24C"
        },
        [10031119] = {
          ContentTC = "要是把軍團這身行頭脫下來，便裝去貧民窟轉一圈，我看恐怕不等太陽下山，您就得賠得連鞋子都不剩了。",
          DialogueId = 10031119,
          GUID = "191CA276",
          NextDialogue = 10031120,
          SpeakNpcId = 200021,
          Subtitle = "If you walked into the slums in plain clothes, I bet you wouldn't even make it to sundown without getting swindled out of every coin in your pocket.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "200021:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA276"
        },
        [10031120] = {
          Camera = "149.513672,-169.366943,198.691895,0.000219,-21.601578,154.789032,35.0,324.824371,false,DoNotOverride,22",
          ContentTC = "「桂冠卡戎」……很慚愧，現在的我還沒有獲得這份殊榮的資格。",
          DialogueId = 10031120,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CA2A0",
          NextDialogue = 10031121,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "\"Laurelled Charon\"... I'm afraid I haven't earned that honour yet.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2A0"
        },
        [10031121] = {
          Camera = "114.541016,142.993408,51.0,0.000056,8.797734,-105.975571,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentTC = "相反，我自己就是霧區出身。我過過那種日子，知道外城卡戎人的生計有多難。所以，能幫上忙的我會盡量幫。",
          DialogueId = 10031121,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CA2CA",
          NextDialogue = 10031122,
          RelatedWikiId = {
            [1] = 408003
          },
          SpeakNpcId = 100304,
          Subtitle = "Actually, I grew up in Mist Aken myself. I know what it's like — I know how hard it is for Charons in the outer city to make ends meet. So, when I can help, I do what I can.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2CA"
        },
        [10031122] = {
          ContentTC = "更何況剛剛是我說錯話在先，所以……",
          DialogueId = 10031122,
          GUID = "191CA2F4",
          NextDialogue = 10031123,
          SpeakNpcId = 100304,
          Subtitle = "Besides, it was I who spoke out of line earlier, so...",
          TalkActionId = {
            [1] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2F4"
        },
        [10031123] = {
          Camera = "133.141602,-83.859375,106.349609,0.000045,10.39638,-116.369263,35.000011,941.904541,false,DoNotOverride,1.903106",
          ContentTC = "行了，其他事都等「卡戎狩獵」的事完了再說吧。既然長官你費那麼大力氣把我叫來，那就先該調查調查，該問話問話吧。",
          DialogueId = 10031123,
          GUID = "191CA31E",
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Explain01_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's put everything else on hold until the \"Charon Hunt\" case is wrapped up. Since you went to all this trouble to bring me here, let's focus on the investigation and get it done.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA31E"
        },
        [10031201] = {
          Camera = "-802.193359,-200.429199,291.232422,0.000171,-5.395378,13.011268,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "剛才提到的「怪物的歌聲」……你還能試著哼一下那首歌的旋律嗎？",
          DetectiveQuestionId = 1003,
          DialogueId = 10031201,
          FinalCamera = "-802.193359,-200.429199,291.232422,0.000172,-13.395387,14.612322,35.000011,100000.0,false,Manual,22.0",
          GUID = "191CAFEA",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031202,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain01_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "About the \"monster's singing\" you mentioned just now... Do you think you could try humming the melody?",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100304:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CAFEA"
        },
        [10031202] = {
          Camera = "-71.710938,137.977051,125.391113,0.000207,1.204244,-66.988014,35.000023,358.523438,false,DoNotOverride,22",
          ContentTC = "…………",
          DetectiveQuestionId = 1003,
          DialogueId = 10031202,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191CB014",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10031203,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100304:Explain01_End"
          },
          TurnTo = {
            [1] = "100001:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB014"
        },
        [10031203] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,DoNotOverride,22",
          ContentTC = "不行，具體的旋律我哼不出來。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031203,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191CB03E",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10031204,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I couldn't do it. I can't get the tune right.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB03E"
        },
        [10031204] = {
          Camera = "-69.961914,-225.399414,156.75,0.000232,-6.595599,79.803307,35.000023,358.523438,false,Manual,3.0",
          ContentTC = "原來你也和我一樣不擅長音樂。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031204,
          FacialId = {
            [1] = "100304:Ahaha01"
          },
          GUID = "191CB068",
          NextOptions = {
            [1] = 10031205,
            [2] = 10031207
          },
          SpeakNpcId = 100304,
          Subtitle = "I understand. Music isn't my strong suit either.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          TurnTo = {
            [1] = "200021:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB068"
        },
        [10031205] = {
          ContentTC = "沒錯，唱歌好難。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031205,
          GUID = "191CB092",
          ImprPlusId = 1009,
          NextDialogue = 10031206,
          Subtitle = "Yeah, singing is hard."
        },
        [10031206] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "況且我就聽了一遍，記不住旋律。不過，如果能再次聽到那支曲子的話，我大概可以認出來。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031206,
          GUID = "191CB0BC",
          NextDialogue = 10031209,
          SpeakNpcId = 100001,
          Subtitle = "Besides, I only heard it once. It's hard to remember the tune. But if I hear it again, I might be able to recognise it.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB0BC"
        },
        [10031207] = {
          ContentTC = "我才沒五音不全，少來套近乎。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031207,
          GUID = "191CB0E6",
          ImprPlusId = 1010,
          NextDialogue = 10031208,
          Subtitle = "I'm not bad at music. Don't lump me in with you."
        },
        [10031208] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "只是睡太久忘了而已。如果再次聽到那支曲子的話，我一定能認出來的。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031208,
          GUID = "191CB110",
          NextDialogue = 10031209,
          SpeakNpcId = 100001,
          Subtitle = "I've just been in a coma for too long and forgot. If I hear it again, I'll definitely recognise it.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB110"
        },
        [10031209] = {
          Camera = "-53.863281,-63.319824,136.021973,0.000113,2.80494,77.005501,35.000015,100000.0,false,Manual,22.0",
          ContentTC = "那就有勞你多留意了。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031209,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191CB13A",
          SpeakNpcId = 100304,
          Subtitle = "Alright, I'll count on you to keep an ear out for it then.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB13A"
        },
        [10031210] = {
          ContentTC = "這是……一塊布？手感還挺好的。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031210,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MainCurtain.T_Guide_Chapter_MainCurtain'}",
          GUID = "191CB164",
          NextDialogue = 10031211,
          SpeakNpcId = 100001,
          Subtitle = "What's this... a piece of cloth? It feels pretty nice.",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB164"
        },
        [10031211] = {
          ContentTC = "（貝蕾就很喜歡這種毛茸茸的觸感…）",
          DetectiveQuestionId = 1003,
          DialogueId = 10031211,
          DisableMouth = 1,
          GUID = "191CB18E",
          NextDialogue = 10031212,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Berry would definitely love this fuzzy texture...)",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB18E"
        },
        [10031212] = {
          ContentTC = "我看一下……嗯，絲絨的，看花紋和折痕，這塊布像是一塊<H>舞台帷幕</>。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031212,
          GUID = "191CB1B8",
          NextDialogue = 10031213,
          SpeakNpcId = 100304,
          Subtitle = "Let me take a look... Hmm, it's velvet. Judging by the patterns and creases, it looks like a piece of a stage curtain.",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB1B8"
        },
        [10031213] = {
          ContentTC = "這附近有舞台的地方，只有<H>蓋雷亞劇院</>。最近那裡正在為<H>銀燭狂歡</>慶典做準備，人多手雜，有人不小心把廢棄幕布丟掉了也不奇怪。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031213,
          GUID = "191CB1E2",
          NextDialogue = 10031214,
          RelatedWikiId = {
            [1] = 406002,
            [2] = 405006
          },
          SpeakNpcId = 100304,
          Subtitle = "The only place nearby with a stage is the Galea Theatre. They've been preparing for the Silvercandle Carnival, and with all the hustle and bustle, it wouldn't be surprising if someone accidentally discarded an old stage curtain.",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB1E2"
        },
        [10031214] = {
          ContentTC = "（銀燭……慶典，城裡那些裝飾就是因為這個慶典嗎？）",
          DetectiveQuestionId = 1003,
          DialogueId = 10031214,
          DisableMouth = 1,
          GUID = "191CB20C",
          NextDialogue = 10031215,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Silvercandle Carnival... Is that what all the decorations are for?)",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB20C"
        },
        [10031215] = {
          ContentTC = "如果只有這塊布也看不出什麼，但是如果把這條線索和你剛才提到的另一條線索結合起來……",
          DetectiveQuestionId = 1003,
          DialogueId = 10031215,
          GUID = "191CB236",
          NextDialogue = 10031216,
          SpeakNpcId = 100304,
          Subtitle = "This piece of fabric alone doesn't tell us much. But if we connect it with the clue you mentioned earlier...",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB236"
        },
        [10031216] = {
          ContentTC = "（嗯……舞台帷幕，的確和<H>那個線索</>有一定關聯。）",
          DetectiveQuestionId = 1003,
          DialogueId = 10031216,
          DisableMouth = 1,
          GUID = "191CB260",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hmm... A stage curtain. It does seem to connect to that clue somehow.)",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB260"
        },
        [10031301] = {
          ContentTC = "垃圾桶裡有個<H>斷掉的風向標</>哎。唔，看起來好新好新，就這樣扔了嗎……好浪費哦，不如咱們帶走吧！",
          DetectiveQuestionId = 1002,
          DialogueId = 10031301,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Vane.T_Guide_Chapter_Vane'}",
          GUID = "191CC052",
          NextDialogue = 10031302,
          SpeakNpcId = 200002,
          Subtitle = "Hey, look! There's a broken weather vane in this rubbish bin. Wow, it looks practically brand new! Someone just tossed it out like that? What a waste... Let's take it with us!",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC052"
        },
        [10031302] = {
          ContentTC = "你喜歡收集風向標嗎？真是奇怪的愛好。我可以託我下屬買個新的送你，但是這個是證物，不能交給你處置。",
          DetectiveQuestionId = 1002,
          DialogueId = 10031302,
          GUID = "191CC07C",
          NextDialogue = 10031303,
          SpeakNpcId = 100304,
          Subtitle = "Do you collect weather vanes? That's quite an unusual hobby. I could have one of my subordinates get you a new one, but this is a piece of evidence — you can't have it now.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC07C"
        },
        [10031303] = {
          ContentTC = "那、那個……白就是隨口一說！我、我並不是喜歡風向標……",
          DetectiveQuestionId = 1002,
          DialogueId = 10031303,
          GUID = "191CC0A6",
          NextDialogue = 10031304,
          SpeakNpcId = 200002,
          Subtitle = "Uh... I was just saying it offhand. I-It's not like I actually have a thing for weather vanes or anything...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0A6"
        },
        [10031304] = {
          ContentTC = "嗚嗚，頭一次真的有人把白說的話當回事，好感動，嗚嗚嗚……",
          DetectiveQuestionId = 1002,
          DialogueId = 10031304,
          GUID = "191CC0D0",
          NextDialogue = 10031305,
          SpeakNpcId = 200002,
          Subtitle = "Waaah, someone actually took my words seriously for once... I'm so touched, waaah...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0D0"
        },
        [10031305] = {
          ContentTC = "黎瑟長官，這條街是什麼時候開始封鎖的？",
          DetectiveQuestionId = 1002,
          DialogueId = 10031305,
          GUID = "191CC0FA",
          NextDialogue = 10031306,
          SpeakNpcId = 100001,
          Subtitle = "Officer Fischer, when was this street sealed off?",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0FA"
        },
        [10031306] = {
          ContentTC = "「卡戎狩獵」第一起案發的次日清晨。",
          DetectiveQuestionId = 1002,
          DialogueId = 10031306,
          GUID = "191CC124",
          NextDialogue = 10031307,
          SpeakNpcId = 100304,
          Subtitle = "The morning after the first \"Charon Hunt\" incident.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC124"
        },
        [10031307] = {
          ContentTC = "封鎖的還算及時……既然是新的，這枚風向標應該也不是被誰故意丟棄在這裡……",
          DetectiveQuestionId = 1002,
          DialogueId = 10031307,
          GUID = "191CC14E",
          NextDialogue = 10031308,
          SpeakNpcId = 100001,
          Subtitle = "That's fairly prompt... Since this weather vane is practically new, it shouldn't have been discarded on purpose...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC14E"
        },
        [10031308] = {
          ContentTC = "難道是那晚的大風？",
          DetectiveQuestionId = 1002,
          DialogueId = 10031308,
          GUID = "191CC178",
          NextDialogue = 10031309,
          SpeakNpcId = 200021,
          Subtitle = "Could it have been the strong winds that night?",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC178"
        },
        [10031309] = {
          ContentTC = "不，五天前的那場風暴後，治安署的確收到過很多財產損失報告，但這枚風向標並不是被吹下來的，更大的可能是被兇手<H>撞下來的</>。",
          DetectiveQuestionId = 1002,
          DialogueId = 10031309,
          GUID = "191CC1A2",
          NextDialogue = 10031310,
          SpeakNpcId = 100304,
          Subtitle = "No. After the storm five days ago, the Security Bureau did receive numerous reports of property damage, but this weather vane wasn't blown off — it's much more likely knocked down by the perpetrator.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1A2"
        },
        [10031310] = {
          ContentTC = "卡蜜拉女士的證詞說，兇手和她交手之後，跳上了<H>樓頂</>。這枚風向標，就是從那裡掉下來的。",
          DetectiveQuestionId = 1002,
          DialogueId = 10031310,
          GUID = "191CC1CC",
          NextDialogue = 10031311,
          SpeakNpcId = 100304,
          Subtitle = "According to Ms Camilla's account, the perpetrator jumped onto the rooftop after engaging with her. This weather vane must have fallen from up there.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1CC"
        },
        [10031311] = {
          ContentTC = "（樓頂嗎……也順帶去看一下吧。）",
          DetectiveQuestionId = 1002,
          DialogueId = 10031311,
          DisableMouth = 1,
          GUID = "191CC1F6",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The rooftop... might as well check it out.)",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1F6"
        },
        [10031401] = {
          ContentTC = "就是這個了，缺口完全一致。底座的彎折痕跡，比起被風吹斷，更像是人為撞擊所致。",
          DetectiveQuestionId = 1002,
          DialogueId = 10031401,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_VaneBottom.T_Guide_Chapter_VaneBottom'}",
          GUID = "191CD0BA",
          NextDialogue = 10031402,
          SpeakNpcId = 100304,
          Subtitle = "This is it. The break aligns perfectly. Judging by the bending on the base, apparently it was not blown off by the wind — it was struck with force.",
          VoiceName = "voice/$Locale$/story/1003/100314/191CD0BA"
        },
        [10031402] = {
          ContentTC = "從這個彎折角度，不難推測它逃竄的方向。",
          DetectiveQuestionId = 1002,
          DialogueId = 10031402,
          GUID = "191CD0E4",
          SpeakNpcId = 100304,
          Subtitle = "And based on the angle of bending, we can deduce the direction the perpetrator fled.",
          VoiceName = "voice/$Locale$/story/1003/100314/191CD0E4"
        },
        [10031501] = {
          Camera = "-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,3.0-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,22.0",
          ContentTC = "沒錯，你也看出來了。它是往西南方向逃的。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031501,
          FinalCamera = "-300.109375,-328.852295,9.648438,0.000112,13.797432,46.589191,30.0,100000.0,false,Manual,22.0",
          GUID = "191CE122",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10031502,
          SpeakNpcId = 100304,
          Subtitle = "That's right, you saw it too. The perpetrator fled southwest.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100315/191CE122"
        },
        [10031502] = {
          Camera = "-196.082031,-87.382202,123.586182,0.000121,4.399837,29.404526,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "這不是都查到了嗎，那衛戍部隊怎麼不直接去那邊搜？",
          DetectiveQuestionId = 1004,
          DialogueId = 10031502,
          FacialId = {
            [1] = "200021:Think01"
          },
          GUID = "191CE14C",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10031503,
          SpeakNpcId = 200021,
          Subtitle = "If you already know that, why hasn't the Escort gone over there to search?",
          TalkActionId = {
            [1] = "200021:Think_Start",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE14C"
        },
        [10031503] = {
          Camera = "210.840332,-20.857056,160.915527,0.000128,-7.400673,172.395859,35.000011,328.483368,false,Manual,3.0",
          ContentTC = "人手不夠，情報也不夠。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031503,
          FacialId = {
            [1] = "200021:None",
            [2] = "100304:Sad01"
          },
          GUID = "191CE176",
          NextDialogue = 10031504,
          SpeakNpcId = 100304,
          Subtitle = "We're short on manpower, and our intel is incomplete.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE176"
        },
        [10031504] = {
          ContentTC = "西南方向那些工廠、住宅和學校我們也在逐步盤查，但範圍太大了，現在還沒有關鍵性的進展。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031504,
          GUID = "191CE1A0",
          NextDialogue = 10031505,
          SpeakNpcId = 100304,
          Subtitle = "We've been systematically combing through the factories, residences, and schools in the southwest, but the sheer scale of the area has made progress slow. So far, there's been no major breakthrough.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE1A0"
        },
        [10031505] = {
          Camera = "53.891113,3.93689,137.345459,0.00013,-1.601071,-174.00856,35.000011,103.373474,DoNotOverride,22",
          ContentTC = "說來慚愧，這案子只有我和我的幾個下屬在調查……其中一個下屬折在了它手上，就在11月25日的那一批遇害者裡。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031505,
          FinalCamera = "16.574219,0.020508,136.559082,0.00013,-1.201041,-174.00856,35.000011,103.373474,DoNotOverride,22",
          GUID = "191CE1CA",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10031506,
          SpeakNpcId = 100304,
          Subtitle = "To be honest, it's just me and a few of my subordinates working on this case... And one of them was killed by that perpetrator. He was among the victims on November 25.",
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100315/191CE1CA"
        },
        [10031506] = {
          ContentTC = "我們發現他的時候，他渾身上下的內臟都被踩碎了，就像被擀麵杖碾過去的麵團。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031506,
          GUID = "191CE1F4",
          NextDialogue = 10031507,
          SpeakNpcId = 100304,
          Subtitle = "When we found him, all his internal organs had been crushed, like dough flattened under a rolling pin.",
          TalkActionId = {
            [1] = "100304:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE1F4"
        },
        [10031507] = {
          Camera = "-192.28125,-79.032227,113.535645,0.000153,6.002226,26.208307,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "……你節哀。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031507,
          FacialId = {
            [1] = "200021:Sad01"
          },
          GUID = "191CE21E",
          NextDialogue = 10031508,
          SpeakNpcId = 200021,
          Subtitle = "...My condolences.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE21E"
        },
        [10031508] = {
          Camera = "25.955078,-88.894897,153.555908,0.000082,-7.000821,146.786774,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "抓到兇手，才是對所有人最好的交代。但……我們還沒能找到那怪物。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031508,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          GUID = "191CE248",
          NextDialogue = 10031509,
          SpeakNpcId = 100304,
          Subtitle = "Catching the perpetrator is the only way to honour him and deliver true justice and closure to all. But... we haven't found that monster yet.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE248"
        },
        [10031509] = {
          ContentTC = "我幾次向上級請求支援，但申請都被駁回了——呃，確切來說不是駁回，而是我必須調查出兇手的確切藏身地，才能得到支援。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031509,
          GUID = "191CE272",
          NextDialogue = 10031510,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I've requested reinforcements from my superiors multiple times, but my applications keep getting denied — or rather, they say I need to pinpoint the perpetrator's exact hideout before my request can be approved.",
          VoiceName = "voice/$Locale$/story/1003/100315/191CE272"
        },
        [10031510] = {
          Camera = "-75.790039,-151.490479,103.759521,0.000096,7.797897,37.589153,35.000015,320.964508,false,Manual,3.0",
          ContentTC = "我看怕不是案發地點剛好是卡戎聚居區，反正怪物也跑不到內城去，所以你上級根本懶得管？",
          DetectiveQuestionId = 1004,
          DialogueId = 10031510,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "191CE29C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10031511,
          SpeakNpcId = 200021,
          Subtitle = "Let me guess — it happened in a Charon neighbourhood, and the monster isn't headed for the inner city. So your superiors just don't care, right?",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE29C"
        },
        [10031511] = {
          Camera = "234.138672,-54.546997,140.426514,0.000134,-4.200279,171.592026,35.0,328.483368,false,Manual,22.0",
          ContentTC = "我不敢妄自揣測。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031511,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CE2C6",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10031512,
          SpeakNpcId = 100304,
          Subtitle = "I wouldn't dare make such assumptions.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE2C6"
        },
        [10031512] = {
          Camera = "-75.790039,-151.490479,103.759521,0.000096,7.797897,37.589153,35.000015,320.964508,false,Manual,3.0",
          ContentTC = "呵。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031512,
          GUID = "191CE2F0",
          NextDialogue = 10031513,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Heh.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE2F0"
        },
        [10031513] = {
          Camera = "-173.730469,-12.869507,127.995117,0.000144,-0.600647,-13.806776,35.000015,234.613907,false,Manual,3.0",
          ContentTC = "那我們動作再快些吧，幫長官儘快破案。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031513,
          GUID = "191CE31A",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031514,
          SpeakNpcId = 100001,
          Subtitle = "Then let's pick up the pace and help Officer Fischer solve this case as quickly as possible.",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE31A"
        },
        [10031514] = {
          Camera = "129.509766,-215.724609,129.291016,0.000136,-1.800014,129.604965,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "萬分感謝！",
          DetectiveQuestionId = 1004,
          DialogueId = 10031514,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191CE344",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          SpeakNpcId = 100304,
          Subtitle = "Thank you so much!",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE344"
        },
        [10031601] = {
          ContentTC = "這是……藍色的雪？",
          DetectiveQuestionId = 1004,
          DialogueId = 10031601,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MoonWaterOnSnow.T_Guide_Chapter_MoonWaterOnSnow'}",
          GUID = "191CF18A",
          NextDialogue = 10031602,
          SpeakNpcId = 100001,
          Subtitle = "Is this... blue snow?",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF18A"
        },
        [10031602] = {
          ContentTC = "我看過了，這是幾滴<H>月髓液</>，它滴在雪裡會像花一樣暈開。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031602,
          GUID = "191CF1B4",
          NextDialogue = 10031603,
          SpeakNpcId = 100304,
          Subtitle = "I've checked — it's a few drops of Phoxichor. When it seeps into the snow, it spreads out like a flower.",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1B4"
        },
        [10031603] = {
          ContentTC = "很漂亮，不是嗎？每次看到這種藍色的「小花」，就感覺一天的疲憊都消失了。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031603,
          GUID = "191CF1DE",
          NextDialogue = 10031604,
          SpeakNpcId = 100304,
          Subtitle = "Beautiful, isn't it? Every time I see these little blue \"flowers,\" it feels like the day's exhaustion simply melts away.",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1DE"
        },
        [10031604] = {
          ContentTC = "看這顏色，純度還蠻高的啊。有月髓液泄露了？",
          DetectiveQuestionId = 1004,
          DialogueId = 10031604,
          GUID = "191CF208",
          NextDialogue = 10031605,
          SpeakNpcId = 200021,
          Subtitle = "Look at this colour — the purity seems pretty high. Could there have been a Phoxichor leak?",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF208"
        },
        [10031605] = {
          ContentTC = "嗯……的確有可能。不過保險起見，關於月髓液這件事，我需要跟{nickname}確認一下。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031605,
          GUID = "191CF232",
          SpeakNpcId = 100304,
          Subtitle = "Hmm... That is possible. But just to be sure, I need to confirm something with .",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF232"
        },
        [10031701] = {
          Camera = "-606.177734,-381.434937,-17.229248,-0.001038,12.606322,29.999029,35.000015,1068.077393,false,Manual,1.2",
          ContentTC = "月髓液啊……保險起見，我有個問題。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031701,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "-606.177734,-381.434937,-17.229248,-0.001038,10.206399,27.999102,35.000015,1068.077393,false,Manual,1.2",
          GUID = "191D01F2",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10031702,
          SpeakNpcId = 100304,
          Subtitle = "The Phoxichor... Hmm, there's something I need to ask, just to clarify.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100317/191D01F2"
        },
        [10031702] = {
          Camera = "89.222656,-173.515381,134.491943,0.000058,-2.800077,128.408691,35.000008,1068.077393,false,DoNotOverride,1.2",
          ContentTC = "你在遭遇兇手時，有沒有聞到一股刺鼻的氣味，大概像是……80%的油漆混上20%麵包發霉的味道？抱歉，我可能不太擅長比喻……",
          DetectiveQuestionId = 1004,
          DialogueId = 10031702,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "85.961914,-176.022827,134.491943,0.000058,-2.800077,125.808693,35.000008,1068.077393,false,DoNotOverride,1.2",
          GUID = "191D021C",
          NextDialogue = 10031703,
          Scripts = "PlayAnimation{_delay{8},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "When you encountered the perpetrator, did you notice any strange smells? Something sharp and unpleasant — like a mix of 80% paint and 20% mouldy bread? Sorry, I'm not great with analogies...",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D021C"
        },
        [10031703] = {
          Camera = "-86.515625,-65.973633,106.226318,0.000065,7.599678,-10.196134,35.000011,1068.077393,false,DoNotOverride,1.2",
          ContentTC = "（那是什麼味道啊！）",
          DetectiveQuestionId = 1004,
          DialogueId = 10031703,
          DisableMouth = 1,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-85.334961,-59.396606,106.226318,0.000066,7.599678,-13.396557,35.000011,1068.077393,false,DoNotOverride,1.2",
          GUID = "191D0246",
          NextDialogue = 10031704,
          SpeakNpcId = 100001,
          Subtitle = "(What kind of smell is that supposed to be!?)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D0246"
        },
        [10031704] = {
          Camera = "-96.705078,-143.869263,95.202881,0.000087,9.999096,26.805567,35.000008,1068.077393,false,DoNotOverride,1.2",
          ContentTC = "嗯……雖然不知道你說的是什麼味道，但這樣回想起來，兇手撲過來的那一下，我好像的確被什麼嗆到了。",
          DetectiveQuestionId = 1004,
          DialogueId = 10031704,
          FacialId = {
            [1] = "100001:Confident01"
          },
