        },
        [10032525] = {
          Camera = "-52.859375,-596.512695,69.789795,0.000565,3.798207,76.587906,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentTC = "我詢問過那裡的工人，他們當晚所有人都有不在場證明……結合魚叉和魚油這兩條線索，我覺得嫌疑人最有可能是「漁夫」。",
          DialogueId = 10032525,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-43.747559,-598.684082,69.789795,0.000566,3.798207,77.987732,45.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D88F8",
          LookAt = {
            [1] = "200021:n(100304)"
          },
          NextDialogue = 10032531,
          SpeakNpcId = 100304,
          Subtitle = "I've already cleared the workers — they all have solid alibis. Considering the harpoon and the fish oil, I think the suspect is most likely to be a fisherman.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D88F8"
        },
        [10032526] = {
