          GUID = "191D89CA",
          NextDialogue = 10032531,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{1.5},TargetPosition{\"-24.407104,-565.220215,68.926025,0.000549,4.198333,79.992966,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-13.015869,-567.29248,68.926025,0.00055,4.198333,80.392738,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Angry01_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "The honour of the Legion is not to be tarnished. Please don't joke about such things! Considering the harpoon and fish oil, I think the suspect is most likely to be a fisherman.",
