            [3] = [[

100304:n(100321)]],
            [4] = [[

100321:n(100304)]]
          },
          NextDialogue = 10033002,
          SpeakNpcId = 100001,
          Subtitle = "What's going on here?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1003/100330/191DD73A"
        },
        [10033002] = {
          Camera = "-4.990234,-83.879883,129.222412,0.000075,-0.599486,141.201096,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "他和同伴被一隻怪物逼進了下水道，他以為自己肯定活不成了，但那隻怪物突然停止了追擊。",
          DialogueId = 10033002,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-3.224609,-81.675781,129.222412,0.000074,-0.599486,141.601227,35.000008,100000.0,false,Manual,22.0",
          GUID = "191DD764",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10033003,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"100304:n(100001)"}},
PlayAnimation{_delay{2},ActorId{100304},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "He and his friend were driven into the sewers by a monster. He thought they were done for, but the monster suddenly left them alone.",
          TalkActionId = {
            [1] = "100001:Talk03_End",
            [2] = [[

100321:Agree]]
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1003/100330/191DD764"
        },
        [10033003] = {
          Camera = "275.736328,107.594727,170.033081,-3.000002,-7.798368,-166.566574,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "他們雖然撿了一條命，但這片區域到處都是走不通的路和穢獸，就都被困在了這裡。",
          DialogueId = 10033003,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "275.736328,107.594727,165.155518,-3.000002,-7.398337,-166.566345,35.000011,100000.0,false,Manual,22.0",
          GUID = "191DD78E",
          LookAt = {
            [1] = "200021:n(100304)"
          },
          NextDialogue = 10033004,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100304},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{4},ActorId{100304},AnimationId{"ExplainTwo_Start"},Duration{1}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "Though they escaped death, this area is a labyrinth of dead ends teeming with Filthoids, leaving them trapped here.",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1003/100330/191DD78E"
        },
