        [10033317] = {
          ContentTC = "小心！",
          DialogueId = 10033317,
          GUID = "191E0B12",
          NextDialogue = 10033318,
          SpeakNpcId = 100304,
          Subtitle = "Watch out!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B12"
