          VoiceName = "voice/$Locale$/story/1003/100333/191E0B66"
        },
        [10033320] = {
          ContentTC = "我來掩護傷者後撤，大家不要慌張。",
          DialogueId = 10033320,
          GUID = "191E0B90",
          NextDialogue = 10033321,
          SpeakNpcId = 100001,
          Subtitle = "I'll cover the retreat of the wounded. Stay focused — don't lose your nerve!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B90"
        },
        [10033321] = {
          ContentTC = "拜託了。",
          DialogueId = 10033321,
          GUID = "191E0BBA",
          NextDialogue = 10033322,
          SpeakNpcId = 100304,
          Subtitle = "Be careful.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BBA"
        },
        [10033322] = {
          ContentTC = "咳……謝謝。",
          DialogueId = 10033322,
          GUID = "191E0BE4",
          SpeakNpcId = 100344,
          Subtitle = "*coughs* ...Thank you.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BE4"
        },
        [10033323] = {
