        },
        [10033324] = {
          ContentTC = "交给我。",
          DialogueId = 10033324,
          GUID = "191E0C38",
          SpeakNpcId = 200021,
          Subtitle = "I'm on it.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C38"
        },
        [10033325] = {
          ContentTC = "牽制住了。黎瑟！",
