        [10033503] = {
          Camera = "14.822266,-56.511841,90.980835,-0.000244,-13.203759,38.555153,35.000015,157.581314,false,Manual,3.299097",
          ContentTC = "沒關係的，保護市民是我的責任……你們沒事……就好。",
