          GUID = "191E2B64",
          NextDialogue = 10033515,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Just don't stay quiet if something's wrong, okay? Some injuries don't show until you're old — then they hit you like a truck.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2B64"
        },
        [10033515] = {
