          NextDialogue = 10033906,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"142.0,-84.0,101.0,0.000097,5.591923,124.053864,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"133.336426,-89.81842,101.0,0.000097,5.591923,121.254005,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100001,
