        },
        [10034306] = {
          ContentTC = "好的長官。沒問題長官！",
          DialogueId = 10034306,
          GUID = "191EAD54",
          NextDialogue = 10034307,
          Subtitle = "Yes, ma'am!"
        },
        [10034307] = {
          Camera = "58.839844,52.446289,126.007812,0.000087,0.802855,-31.942743,25.000002,134.456573,false,Manual,5.0",
          ContentTC = "……哦！抱歉抱歉，習慣了。用你舒服的方式跟我講講就好。",
          DialogueId = 10034307,
          FacialId = {
            [1] = "100361:Shock01"
          },
          FinalCamera = "59.0,50.0,126.007812,0.000094,0.802855,-31.942778,25.000002,134.456573,false,Manual,5.0",
          GUID = "191EAD7E",
          NextDialogue = 10034308,
          SpeakNpcId = 100361,
          Subtitle = "...Oh! Sorry about that — it's a work habit. Don't mind me, just tell me however you're comfortable.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAD7E"
        },
        [10034308] = {
          Camera = "237.678711,486.936035,581.84375,-5.00003,-45.994049,-110.940186,20.0,134.456573,false,Manual,22.0",
          ContentTC = "她的名字是貝蕾妮卡，來自南方的一座小島，應該是最近加入了第十三軍團。",
          DialogueId = 10034308,
          FacialId = {
            [1] = "100361:None"
          },
          FinalCamera = "188.371094,491.429321,562.693359,-5.000032,-46.394035,-106.540405,20.0,134.456573,false,Manual,22.0",
          GUID = "191EADA8",
          NextDialogue = 10034309,
          SpeakNpcId = 100001,
          Subtitle = "Her name is Berenica, from a small southern island. And I think she may have joined the 13th Legion recently.",
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = [[

200002:Afraid_End]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100343/191EADA8"
        },
        [10034309] = {
          Camera = "55.936523,212.618408,73.029297,0.000063,10.604968,-88.343674,22.000006,243.305359,false,Manual,3.0",
          ContentTC = "她長著銀色的長髮，紅色的眼睛。她很漂亮，但總是把自己打扮得黑漆漆的。",
          DialogueId = 10034309,
          FinalCamera = "55.936523,212.618408,73.029297,0.000058,11.004971,-88.943642,25.0,243.305359,false,Manual,3.0",
          GUID = "191EADD2",
          NextDialogue = 10034310,
          SpeakNpcId = 100001,
          Subtitle = "She has silver hair and red eyes. She's beautiful, but always dresses in dark clothes.",
          TalkActionId = {
            [1] = "100001:Talk03ToThink_Start"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1003/100343/191EADD2"
        },
        [10034310] = {
          Camera = "140.621094,68.844055,145.107422,0.000087,-1.194976,-138.343018,35.0,101.456741,false,Manual,3.0",
          ContentTC = "她天生力氣很大，喜歡摸毛茸茸的東西，會做很難吃的飯……",
          DialogueId = 10034310,
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          FinalCamera = "140.621094,68.844055,145.107422,0.000087,-1.194948,-138.342926,36.0,101.456741,false,Manual,3.0",
          GUID = "191EADFC",
          NextDialogue = 10034311,
          SpeakNpcId = 100001,
          Subtitle = "She's incredibly strong, and loves fluffy things, though her culinary skills leave much to be desired...",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100343/191EADFC"
        },
        [10034311] = {
          Camera = "-52.361816,79.298218,166.8125,0.000117,-15.993126,-21.551489,20.000008,221.402267,false,Manual,3.0",
          ContentTC = "好，我記下了。第十三軍團的消息很嚴密，我會儘量托可靠的熟人打聽。如果找到她，需要我做什麼？跟她遞個話，要她來找你？",
          DialogueId = 10034311,
          FacialId = {
            [1] = "100361:Happy01"
          },
          FinalCamera = "-52.361816,79.298218,162.505859,0.000117,-14.793062,-21.551306,20.000008,221.402267,false,Manual,3.0",
          GUID = "191EAE26",
          NextDialogue = 10034312,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.1},TargetPosition{"-3.022461,60.050598,135.460938,0.000118,-4.393983,-32.965584,25.0,165.142899,false,Manual,3.0"},duration{0}},
CameraMoveTo{TargetPosition{"-1.558594,62.309326,135.460938,0.000118,-4.393983,-32.965584,25.0,163.687469,false,Manual,3.0"},duration{6}},
}
]],
          SpeakNpcId = 100361,
          Subtitle = "Okay, I got it all down. The 13th Legion keeps their information under wraps pretty tightly, but I'll reach out to some reliable contacts. If we find her, what do you want me to do? Should I pass along a message and tell her to come find you?",
          TalkActionId = {
            [1] = "100361:AgreeHead",
            [2] = [[

100001:Explain02_End]]
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAE26"
        },
        [10034312] = {
          Camera = "126.6875,33.446411,128.46875,0.000021,9.599721,-150.740402,20.0,71.86837,false,Manual,5.0",
          ContentTC = "不用了！只要告訴我她現在在哪裡，是否平安就好，剩下的交給我。",
          DialogueId = 10034312,
          FacialId = {
            [1] = "100001:Happy01"
          },
          FinalCamera = "127.149414,32.62323,128.46875,0.000021,9.599721,-150.740402,22.0,71.86837,false,Manual,5.0",
          GUID = "191EAE50",
          NextDialogue = 10034313,
          SpeakNpcId = 100001,
          Subtitle = "No, it's okay. Just let me know where she is and if she's safe. I'll handle the rest myself.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAE50"
        },
        [10034313] = {
          Camera = "128.091309,254.743591,98.091797,0.0001,5.804568,-98.531677,35.0,223.242523,false,Manual,5.0",
          ContentTC = "好。雖然她不在你身邊，但我希望……不，我相信她一定正堅強地生活著，等著和你重逢的那天。就像我和布魯斯一樣。",
          DialogueId = 10034313,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "134.226074,253.823425,98.091797,0.000101,5.804568,-98.531677,35.0,223.242523,false,Manual,5.0",
          GUID = "191EAE7A",
          NextDialogue = 10034314,
          Scripts = [[
PARA{
PlayAnimation{_delay{4.5},ActorId{100361},AnimationId{"DisagreeHead"},Duration{10}},
LookAt{_delay{4.5},LookAtDescription{"100361:n(100361)"}},
SEQ{
CameraMoveTo{_delay{5.1},TargetPosition{"17.925781,79.578247,91.876953,0.000093,13.204217,-30.733114,35.0,133.613724,false,Manual,5.0"},duration{0}},
CameraMoveTo{TargetPosition{"26.682617,74.371826,94.267578,0.000093,13.204217,-30.733145,35.0,133.613724,false,Manual,5.0"},duration{6}},
}
}]],
          SpeakNpcId = 100361,
          Subtitle = "Sure. Even though she's not with you right now, I hope... no, I BELIEVE she's out there, staying strong and waiting for the day you'll reunite. Just like me and Blues.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAE7A"
        },
        [10034314] = {
          Camera = "-146.145508,84.5,194.298828,0.000115,-17.393253,-11.726353,25.000002,211.201675,false,Manual,5.0",
          ContentTC = "啊……抱歉之前可能沒說過，布魯斯是我弟弟，他現在正作為「桂冠卡戎」候補，在內城的第六軍團服役。",
          DialogueId = 10034314,
          FacialId = {
            [1] = "100361:Ahaha01"
          },
          FinalCamera = "-145.09082,89.584778,193.029297,0.000114,-17.193224,-12.92649,25.000002,211.201675,false,Manual,5.0",
          GUID = "191EAEA4",
          LookAt = {
            [1] = "100361:n(100001)"
          },
          NextDialogue = 10034315,
          SpeakNpcId = 100361,
          Subtitle = "Ah... sorry if I came off too blunt. I probably haven't mentioned this before, but Blues is my younger brother. He's currently serving as a Laurelled Charon candidate with the 6th Legion in the inner city.",
          TalkActionId = {
            [1] = "100361:AgreeHead"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAEA4"
        },
        [10034315] = {
          Camera = "142.187012,14.526367,158.126953,0.000148,-1.3962,155.668839,35.000011,185.386246,false,Manual,22.0",
          ContentTC = "「桂冠卡戎」？這可不容易。拿到桂冠資格的都是強者中的強者。",
          DialogueId = 10034315,
          FacialId = {
            [1] = "100361:None"
          },
          FinalCamera = "131.676758,19.278259,160.109375,0.000148,-1.596215,155.669006,35.000011,185.386246,false,Manual,22.0",
          GUID = "191EAECE",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = [[

100361:n(200021)]],
            [3] = [[

200021:n(100361)]]
          },
          NextDialogue = 10034316,
          SpeakNpcId = 200021,
          Subtitle = "Laurelled Charon? That's no small feat. Only the strongest of the strong can make it.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAECE"
        },
        [10034316] = {
          Camera = "290.523926,52.623901,96.710938,0.000174,5.403185,-169.918121,25.000006,291.195435,false,Manual,15.0",
          ContentTC = "嗯，布魯斯他……和我不一樣。雖然都幸運地成為了「骸」，但「骸」之間也天差地別。他從小就很聰明……即使不需要努力練習也能很好地掌控魔法。",
          DialogueId = 10034316,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "291.792969,45.107056,96.710938,0.000173,5.603186,-174.717438,25.000006,291.195435,false,Manual,15.0",
          GUID = "191EAEF8",
          LookAt = {
            [1] = "100001:n(100361)"
          },
          NextDialogue = 10034317,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"200021:n(100361)\"}}",
          SpeakNpcId = 100361,
          Subtitle = "Yes, Blues... he's nothing like me. We were both fortunate enough to awaken as Daimons, but even among Daimons, the difference is stark. He's a gifted child... Even without much practice, magic came to him effortlessly.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAEF8"
        },
        [10034317] = {
          Camera = "50.372559,77.353577,99.699219,0.000192,14.002181,-36.722607,35.000008,127.422424,false,Manual,3.0",
          ContentTC = "但即使如此，他還是很刻苦。所以他才能通過第六軍團萬裡挑一的選拔考試，進入內城服役。",
          DialogueId = 10034317,
          FinalCamera = "57.093262,72.341003,101.791016,0.000192,14.002181,-36.722607,35.000008,115.580086,false,Manual,3.0",
          GUID = "191EAF22",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = [[

100361:n(100361)]]
          },
          NextDialogue = 10034318,
          SpeakNpcId = 100361,
          Subtitle = "But he never took his gift for granted. He worked incredibly hard, and that's why he passed the 6th Legion's brutal selection process — only one in ten thousand can manage it — and earned a place in the inner city.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAF22"
        },
        [10034318] = {
