        [10034320] = {
          Camera = "-96.10498,201.29425,7.722656,0.000082,19.400864,-41.310314,47.0,313.029602,false,Manual,3.0",
          ContentTC = "我明白你的不平。但是我已經滿足了，布魯斯能實現他的夢想，更是我們小時候根本不敢相信的。",
          DialogueId = 10034320,
          FacialId = {
