          SpeakNpcId = 100304,
          Subtitle = "I'll join you once I've finished preparing the investigation report and handed it over to Officer Lynn.",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200002:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100344/191EBD68"
        },
        [10034405] = {
          ContentTC = "嚯，街上全是十三軍團的人，好大陣仗。",
          DialogueId = 10034405,
          GUID = "191EBDBC",
          NextDialogue = 10034406,
          SpeakNpcId = 200021,
          Subtitle = "Huh, the streets are full of soldiers in the 13th Legion. What a grand scene.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBDBC"
        },
        [10034406] = {
          ContentTC = "琳恩長官為什麼獨自向著<H>內城</>走了？",
          DialogueId = 10034406,
          GUID = "191EBDE6",
          NextDialogue = 10034407,
          SpeakNpcId = 100001,
          Subtitle = "Why did Officer Lynn head towards the inner city alone?",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBDE6"
        },
        [10034407] = {
          ContentTC = "煉金院、執政廳、第六軍團駐紮地都在內城，過去無非就是調遣、應酬、問責、敘舊之類的吧。",
          DialogueId = 10034407,
          GUID = "191EBE10",
          NextDialogue = 10034408,
          SpeakNpcId = 200021,
          Subtitle = "The Alchemy Academy, the Council Hall, and the 6th Legion's HQ are all there. Could be anything — logistics, politics, questioning, or maybe just catching up with someone.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE10"
        },
        [10034408] = {
          ContentTC = "反正與我們無關，我的人生準則之一就是，少問多做，才能活得更久。",
          DialogueId = 10034408,
          GUID = "191EBE3A",
          SpeakNpcId = 200021,
          Subtitle = "None of it concerns us. One of my life rules is — the less you ask, the longer you live.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3A"
        },
        [10034410] = {
          ContentTC = "就是在這裡接貨吧！哇啊——怎麼有雪狼！",
          DialogueId = 10034410,
          GUID = "191EBE64",
          NextDialogue = 10034411,
          SpeakNpcId = 200002,
          Subtitle = "This must be the pickup spot! Whoa—! Why are there snow wolves here!?",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE64"
        },
        [10034411] = {
          ContentTC = "你們就是琳恩長官說的本地人小隊吧，貨物還沒來，跟我把這片區域清理出來。",
          DialogueId = 10034411,
          GUID = "191EBE8E",
          NextDialogue = 10034412,
          SpeakNpcId = 100310,
          Subtitle = "You're the local squad Major Lynn sent, right? The shipment hasn't arrived yet. While we wait, help me clear out this area.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE8E"
        },
        [10034412] = {
          ContentTC = "唉，又要多乾一份活嘍。",
          DialogueId = 10034412,
          GUID = "191EBEB8",
          SpeakNpcId = 200021,
          Subtitle = "*sigh* Great... another chore on the pile.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBEB8"
        },
        [10034413] = {
          ContentTC = "警戒線都拉起來，動作快！",
          DialogueId = 10034413,
          GUID = "191EBE3B",
          Subtitle = "Secure the perimeter — now!",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3B"
        },
        [10034414] = {
          ContentTC = "冰湖城這幾日宵禁，沒有許可禁止隨意走動。",
          DialogueId = 10034414,
          GUID = "191EBE3C",
          Subtitle = "Icelake's under curfew. No movement without a permit.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3C"
        },
        [10034415] = {
          ContentTC = "銀燭狂歡之前肯定能結案，這些花花綠綠的裝飾就放著吧。",
          DialogueId = 10034415,
          GUID = "191EBE3D",
          Subtitle = "We'll be done before the Silvercandle Carnival. Just leave the gaudy decorations where they are.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3D"
        },
        [10034416] = {
          ContentTC = "通訊測試，一二三一二三，通訊測試，一二三，能聽到嗎？好，我這兒聽著也沒問題。",
          DialogueId = 10034416,
          GUID = "191EBE3E",
          Subtitle = "Comms check — one, two... one, two. Can you hear me? Good — loud and clear on my end too.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3E"
        },
        [10034417] = {
          ContentTC = "說是宵禁，怎麼白天也不讓出去啊？",
          DialogueId = 10034417,
          GUID = "191EBE40",
          Subtitle = "If it's called a curfew, why aren't we allowed to go out during the day either?",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE40"
        },
        [10034418] = {
          ContentTC = "該死，這批新鮮霜脊魚賣不出去了。",
          DialogueId = 10034418,
          GUID = "191EBE41",
          Subtitle = "Damn it, these fresh Frostspines are going to go to waste.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE41"
        },
        [10034419] = {
          ContentTC = "噢，我心愛的女士，這個夜晚我孤枕難眠，明明我們只隔著兩條街的距離卻無法相見……",
          DialogueId = 10034419,
          GUID = "191EBE42",
          Subtitle = "Ah, my dearest lady, this sleepless night finds me alone with a cold pillow—though merely two streets apart, we remain cruelly divided...",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE42"
        },
        [10034420] = {
          ContentTC = "長官行行好啊，我不過去乾活，全家都要餓死了……",
          DialogueId = 10034420,
          GUID = "191EBE43",
          Subtitle = "Please, sir, let me go. I need to go to work. I got a family to raise...",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE43"
        },
        [10034421] = {
          ContentTC = "怎麼老是你？當心長官送你全家吃牢飯！",
          DialogueId = 10034421,
          GUID = "191EBE44",
          Subtitle = "You again?! Watch it—one more word, and the officer will have your whole family behind bars!",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE44"
        },
