            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100348/191EFFDA"
        },
        [10034810] = {
          Camera = "18.089355,286.953125,108.440918,-0.00174,-21.568111,-73.964584,30.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "仔細一瞧，他們擺得還挺威嚴的！難道他們才是真正的下水道公爵？",
          DialogueId = 10034810,
          FacialId = {
            [1] = "200002:Smile01"
