          GUID = "191F0004",
          NextDialogue = 10034811,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-1.92041,529.060547,193.301636,-0.001741,-23.567587,-85.957458,30.000013,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-14.425781,525.737305,192.27063,-0.00174,-23.367571,-80.557098,30.000013,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 200002,
          Subtitle = "Upon a closer look, they've set this place up pretty majestically! Maybe they're the real Dukes of the Sewers!",
