        },
        [10034825] = {
          ContentTC = "小僕從，這裡有個奇奇怪怪的機關誒！",
          DialogueId = 10034825,
          GUID = "191F0101",
          NextDialogue = 10034826,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, Little Minion — look! There's a weird-looking switch here!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0101"
        },
        [10034826] = {
          ContentTC = "小矮子先別碰，當心有詐！……嗯，還好，只是普通的升降機。",
          DialogueId = 10034826,
          GUID = "191F0102",
          SpeakNpcId = 200021,
          Subtitle = "No, Button Mushroom — don't touch that! Could be a trap... Huh. Looks like it's just a regular lift.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0102"
        },
        [10034827] = {
          ContentTC = "出現了新的路誒！簡直像變魔術一樣！",
          DialogueId = 10034827,
          GUID = "191F0103",
          SpeakNpcId = 200002,
          Subtitle = "Whoa! A new path just opened up — like magic!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0103"
        },
        [10034828] = {
          ContentTC = "嘁，什麼都沒有嘛，我還以為會突然蹦出來啥。",
          DialogueId = 10034828,
          GUID = "191F0104",
          NextDialogue = 10034829,
          SpeakNpcId = 200021,
          Subtitle = "Tch. Nothing at all... I was half expecting something to jump out.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0104"
        },
        [10034829] = {
          ContentTC = "呸呸呸，不許烏鴉嘴！",
          DialogueId = 10034829,
          GUID = "191F0105",
          NextDialogue = 10034830,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Watch your mouth — you'll jinx it!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0105"
        },
        [10034830] = {
          ContentTC = "繼續向上吧。",
          DialogueId = 10034830,
          GUID = "191F0106",
          NextDialogue = 10034832,
          SpeakNpcId = 100001,
          Subtitle = "Let's just keep moving.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0106"
        },
        [10034831] = {
          ContentTC = "嗬，一下就亮起來了。邊邊角角都看得一清二楚。",
          DialogueId = 10034831,
          GUID = "191F0107",
          SpeakNpcId = 200021,
          Subtitle = "Whoa — the whole place just lit up. You can see every corner now.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0107"
        },
        [10034832] = {
          ContentTC = "不得不說，這地方布置得還挺有藝術感的，簡直像個縮小版的劇院舞台。",
          DialogueId = 10034832,
          GUID = "191F0108",
          SpeakNpcId = 200021,
          Subtitle = "Gotta say, this place's got style. Feels like a mini theatre stage.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0108"
