LookAt{_delay{4.5},LookAtDescription{"100304:n(100001)"}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "Yes, I joined the Legion only for peace of mind. But that's exactly why I can't sit back, warming my hands by a fire, while others freeze to death out there in the cold.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100352/191F441A"
        },
        [10035226] = {
          Camera = "-767.976807,-468.421631,1021.622314,0.000127,-46.820312,30.559282,35.0,1471.360107,false,Manual,22.0",
          ContentTC = "你還記得我說過一件事嗎？我的父母是被穢獸殺害的，因為他們收留了一名偽裝成正常人的穢蝕者……",
          DialogueId = 10035226,
          FinalCamera = "-783.698853,-437.067078,1022.494141,0.000135,-46.820293,30.359089,35.0,1471.360107,false,Manual,22.0",
          GUID = "191F4444",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10035227,
          Scripts = [[
