        },
        [10035245] = {
          ContentTC = "重新整理一下目前的線索，看看有沒有什麼被我們遺漏的吧。",
          DialogueId = 10035245,
          GUID = "191F4762",
          SpeakNpcId = 100001,
          Subtitle = "Let's go over what we've found so far. Maybe we missed something important.",
