          VoiceName = "voice/$Locale$/story/1003/100352/191F4888"
        },
        [10035253] = {
          ContentTC = "等等……布魯斯……他就是個狂熱歌劇迷，我記得他在秘密基地裡留下了很多錄音帶！雖然只能用笨辦法全聽一遍，但，說不定能找到那首歌！",
          DialogueId = 10035253,
          GUID = "191F48B2",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035254,
          Scripts = [[
