          GUID = "191F836E",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "There are still enemies over there. Don't stop now.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F836E"
        },
        [10035612] = {
          ContentTC = "數據落後預期了，去把那邊的敵人也清理掉，快。",
          DialogueId = 10035612,
          GUID = "191F8398",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "The numbers are underwhelming. Go and clear out the enemies over there. Now.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8398"
        },
        [10035613] = {
          ContentTC = "加油！加油！",
          DialogueId = 10035613,
          GUID = "191F83C2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Keep it up! Keep it up!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83C2"
        },
        [10035614] = {
          ContentTC = "受傷了？這麼脆弱嗎？",
          DialogueId = 10035614,
          GUID = "191F83EC",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Injured already? Useless worm.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83EC"
        },
        [10035615] = {
          ContentTC = "去那邊哦~",
          DialogueId = 10035615,
          GUID = "191F8416",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Go that way! Hurry up~!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8416"
        },
        [10035616] = {
          ContentTC = "那邊的敵人還有口氣，這種敵人都處理不好嗎？",
          DialogueId = 10035616,
          GUID = "191F8440",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "That one over there is still breathing. Can't you even handle that? Finish it!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8440"
        },
        [10035617] = {
          ContentTC = "測試通過，帶回收容處。我們準備迎接下一批改造體了。",
          DialogueId = 10035617,
          GUID = "191F846A",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Test complete. Return it to the cell. Prepare for the next batch of subjects.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F846A"
        },
        [10035618] = {
          ContentTC = "數據什麼時候出來？等不及了。",
          DialogueId = 10035618,
          GUID = "191F82C7",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "When's the data coming in? I'm running out of patience.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C7"
        },
        [10035619] = {
          ContentTC = "希望這只能成功吧。",
