        },
        [10035706] = {
          Camera = "215.392578,-260.694336,230.287964,0.000079,-5.401976,-49.228199,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentTC = "太好了，我還以為再也遇不到能說話的人了。",
          DialogueId = 10035706,
          FinalCamera = "220.646484,-256.163086,230.287964,0.000079,-5.401976,-49.228199,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9304",
          NextDialogue = 10035707,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"563.330078,-792.032227,144.184875,0.000041,2.194956,119.372292,20.000011,1068.904175,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"538.634766,-804.90332,144.184875,0.000043,2.794913,115.771866,20.000011,1068.904175,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Thank goodness. I thought I'd never meet another person to talk to.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9304"
        },
        [10035707] = {
          Camera = "-131.793945,-64.760742,220.011841,10.800352,-6.20175,-20.624842,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentTC = "我們很熟嗎？",
          DialogueId = 10035707,
          FinalCamera = "-126.806641,-50.629883,217.170044,10.800995,-6.20175,-22.424656,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F932E",
          NextDialogue = 10035708,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Do we know each other?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F932E"
        },
        [10035708] = {
          Camera = "268.87207,-364.642578,243.919006,-0.000123,-11.801576,-35.824482,30.0,335.406189,false,DoNotOverride,1.2",
          ContentTC = "哈哈，總會熟起來的嘛。畢竟我們是這鬼地方僅有的<H>人</>了。",
          DialogueId = 10035708,
          FinalCamera = "274.612305,-357.021484,243.919006,-0.000123,-11.801535,-39.423576,30.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9358",
          NextDialogue = 10035709,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"511.429688,-699.175781,227.014282,-0.000031,-3.401277,122.771469,25.0,335.406189,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"493.702148,-710.414062,227.014282,-0.000031,-3.001281,119.171577,25.0,335.406189,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Haha, not yet, but we'll get there. After all, we're the only humans in this hellhole.",
          TalkActionId = {
            [1] = "100331:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9358"
        },
        [10035709] = {
          Camera = "-187.094727,-308.035156,217.466675,-0.000031,-2.601619,46.970585,25.0,335.406189,false,DoNotOverride,1.2",
          ContentTC = "哈，也就你會覺得我們還算人了。",
          DialogueId = 10035709,
          FinalCamera = "-195.34375,-300.339844,217.466675,-0.000031,-2.601619,46.970585,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9382",
          NextDialogue = 10035710,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Humans? Only you would still think of us that way.",
          TalkActionId = {
            [1] = "100331:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9382"
        },
        [10035710] = {
          Camera = "187.789062,-301.319336,147.267517,-0.000031,6.198061,-41.427723,25.0,335.406189,false,DoNotOverride,1.2",
          ContentTC = "重要的是心",
          DialogueId = 10035710,
          FinalCamera = "197.701172,-290.091797,147.267517,-0.000031,6.198061,-41.427723,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F93AC",
          NextDialogue = 10035711,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "It's what's in the heart that counts.",
          TalkActionId = {
            [1] = "100331:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F93AC"
        },
        [10035711] = {
          Camera = "-141.865234,31.176758,158.599976,-0.000031,13.99628,-38.820576,25.0,335.406189,false,DoNotOverride,1.2",
          ContentTC = "那種東西早就碎在了實驗台上。",
          DialogueId = 10035711,
          FinalCamera = "-132.458984,42.869141,158.599976,-0.000031,13.796285,-42.620617,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F93D6",
          NextDialogue = 10035712,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "The heart? That was torn apart on the operating table long ago.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F93D6"
        },
        [10035712] = {
          Camera = "147.782227,-325.042969,147.337708,0.000036,5.995984,-31.222105,25.0,335.406189,false,DoNotOverride,1.2",
          ContentTC = "那就讓我們把它再次拼起來吧，然後一起以人的身份逃出去。",
          DialogueId = 10035712,
          FinalCamera = "153.202148,-316.107422,147.337708,0.000036,5.995984,-31.222105,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9400",
          NextDialogue = 10035713,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Then let's piece it back together. And once we've done that, we'll get out of here together — as humans.",
          TalkActionId = {
            [1] = "100331:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9400"
        },
        [10035713] = {
          Camera = "255.836914,-351.580078,219.478699,0.000112,-5.004336,131.172974,25.0,374.165375,false,Manual,1.908222",
          ContentTC = "……白日做夢。",
          DialogueId = 10035713,
          FinalCamera = "273.556641,-371.847656,221.835327,0.000112,-5.004336,131.172974,25.0,374.165375,false,Manual,1.908222",
          GUID = "191F942A",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...Keep dreaming.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100328:n(100331)"
          },
          VoiceName = "voice/$Locale$/story/1003/100357/191F942A"
        },
        [10035801] = {
          ContentTC = "測試開始。這次的敵人比較罕見，做好數據紀錄。",
          DialogueId = 10035801,
          GUID = "191FA29A",
          NextDialogue = 10035802,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Test begins. The targets assigned to the subject this time are rare. Ensure the data is recorded in meticulous detail.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA29A"
        },
        [10035802] = {
          ContentTC = "是，老師！",
          DialogueId = 10035802,
          GUID = "191FA2C4",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Yes, Professor!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA2C4"
        },
        [10035803] = {
          ContentTC = "雖然我們被抓了，但是敢給我們武器，那就讓你們嚐嚐神的怒火！",
          DialogueId = 10035803,
          GUID = "191FA2EE",
          NextDialogue = 10035804,
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "We may be prisoners, but now that we're given weapons, we can still show you the wrath of the gods!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA2EE"
        },
        [10035804] = {
          ContentTC = "海伯利亞人，墮落的褻瀆者，竟然造出這樣的怪物！殺了它！",
          DialogueId = 10035804,
          GUID = "191FA318",
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "Hyperboreans, you vile degenerates! How dare you create such a blasphemous monster! Let's kill this abomination!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA318"
        },
        [10035805] = {
          ContentTC = "放，放過我們，我們明明已經投降了啊！",
          DialogueId = 10035805,
          GUID = "191FA342",
          NextDialogue = 10035806,
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "Please, spare us! We've already surrendered!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA342"
        },
        [10035806] = {
          ContentTC = "…………",
          DialogueId = 10035806,
          GUID = "191FA36C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10035807,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA36C"
        },
        [10035807] = {
          ContentTC = "九神啊……！請憐憫我，賜我智慧，賜我力量，賜我庇護……！",
          DialogueId = 10035807,
          GUID = "191FA396",
          NextDialogue = 10035808,
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "O the Great Nine...! Hear me... grant me your mercy, your wisdom, your strength, and your deliverance...",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA396"
        },
        [10035808] = {
          ContentTC = "抱歉。",
          DialogueId = 10035808,
          GUID = "191FA3C0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10035809,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Sorry.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA3C0"
        },
        [10035809] = {
          ContentTC = "啊啊……寬恕我，寬恕我……",
          DialogueId = 10035809,
          GUID = "191FA3EA",
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "O merciful gods... grant me forgiveness, grant me absolution...",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA3EA"
        },
        [10035810] = {
          ContentTC = "上啊，讓我看看你們到底誰才是真正的惡魔，哈哈哈。",
          DialogueId = 10035810,
          GUID = "191FA414",
          NextDialogue = 10035811,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Go on! Let's see which of you truly deserves to be called a demon — haha!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA414"
        },
        [10035811] = {
          ContentTC = "真好用，配合這段時間注射的抑制劑，穩定性也高了不少。",
          DialogueId = 10035811,
          GUID = "191FA43E",
          NextDialogue = 10035812,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Impressive! The suppressants we've been injecting are finally showing results. Stability's never been this high.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA43E"
        },
        [10035812] = {
          ContentTC = "這樣下去把改造實驗推廣向其他軍團也指日可待了。",
          DialogueId = 10035812,
          GUID = "191FA468",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "At this rate, it won't be long before we can roll out these augmentation experiments across the other legions.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA468"
        },
        [10035813] = {
          ContentTC = "實驗數據採集完成，你們自己回去吧，我要去給老師提交報告。",
          DialogueId = 10035813,
          GUID = "191FA492",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Data's all logged. You can head back on your own — I've got to prepare the report for the Professor.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA492"
        },
        [10035814] = {
          ContentTC = "各項數據都在波動範圍之內，這次很有希望！",
          DialogueId = 10035814,
          GUID = "191F942B",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "All readings are within tolerance. This one's showing real promise!",
          VoiceName = "voice/$Locale$/story/1003/100358/191F942B"
        },
        [10035815] = {
          ContentTC = "怎麼還是比不上36號和47號，到底哪裡出了問題……",
          DialogueId = 10035815,
          GUID = "191F942C",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Still not matching Subjects 36 or 47... what's causing the discrepancy?",
          VoiceName = "voice/$Locale$/story/1003/100358/191F942C"
        },
        [10035816] = {
          ContentTC = "可以考慮加大劑量了。",
          DialogueId = 10035816,
          GUID = "191F942D",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Time to raise the dosage.",
