          GUID = "191FB3FE",
          NextDialogue = 10035908,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Save your breath. Surviving the experiments is hard enough.",
          TalkActionId = {
            [1] = "100328:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1003/100359/191FB3FE"
        },
        [10035908] = {
          Camera = "180.489258,-377.827148,235.083801,0.000124,-5.80118,-21.050528,35.0,100000.0,false,Manual,22.0",
          ContentTC = "肉體的疼痛不算什麼。把活生生的人給……！才讓人難受……",
          DialogueId = 10035908,
          GUID = "191FB428",
          NextDialogue = 10035909,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Physical pain doesn't matter. It's what they've turned human into that hurts...",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB428"
        },
        [10035909] = {
          Camera = "410.818359,-586.445312,210.064209,10.811686,-3.001451,107.757263,20.0,927.34375,false,Manual,3",
          ContentTC = "這麼久了，你還認為自己還是人啊。我們是怪物，無知無覺的、任人驅使的怪物。記住這點，你就不難受了。",
          DialogueId = 10035909,
          GUID = "191FB452",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10035910,
          Scripts = [[
SEQ{
MoveTo{ActorId{100328},TargetPoint{"tuosi01_walk"},MoveSpeed{150},Visibility{"Show"}},
CameraMoveTo{_delay{0.6},TargetPosition{"284.339844,-294.831055,217.898376,10.817102,0.598243,129.1483,20.000008,927.34375,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "After all this, you still think we're human? Face it. We're nothing but monsters now — mindless, soulless tools at their command. Accept it, and it won't hurt anymore.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB452"
        },
        [10035910] = {
          Camera = "317.161133,-375.083008,228.198242,0.000137,-7.201799,-39.445698,20.000008,100000.0,false,Manual,22.0",
          ContentTC = "不能……不能變成怪物……如果連心都投降了，就真的變成怪物了。",
          DialogueId = 10035910,
          GUID = "191FB47C",
          NextDialogue = 10035911,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "No... We can't let ourselves become monsters... The day your heart gives up is the day you truly become one.",
          TalkActionId = {
            [1] = "100331:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1003/100359/191FB47C"
        },
        [10035911] = {
          Camera = "299.682617,-302.890625,219.492859,0.000183,-2.405818,132.131363,20.000008,100000.0,false,Manual,22.0",
          ContentTC = "你忘了上次逃跑失敗被按在電椅上了？省省吧，還是你想再挨一次？",
