        },
        [10036016] = {
          Camera = "475.610352,-611.675781,221.689697,0.000148,-7.606269,121.213806,20.0,1261.194092,false,Manual,22.0",
          ContentTC = "什麼？",
          DialogueId = 10036016,
          GUID = "191FC5E0",
          NextDialogue = 10036017,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Huh?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC5E0"
        },
        [10036017] = {
          Camera = "475.610352,-611.675781,221.689697,0.000148,-7.606269,121.213806,20.0,1261.194092,false,Manual,22.0",
          ContentTC = "我曾經的夢想是做個演員。",
          DialogueId = 10036017,
          GUID = "191FC60A",
          NextDialogue = 10036018,
          Scripts = [[
PARA{
MoveTo{ActorId{100328},TargetPoint{"tuosi01_walk4"},MoveSpeed{120},Visibility{"Show"}},
CameraMoveTo{_delay{1},TargetPosition{"-347.200195,-320.677734,160.137878,0.000141,6.99427,50.212906,35.000008,1261.194092,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I used to dream of becoming a performer.",
          TalkActionId = {
            [1] = "100328:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC60A"
        },
        [10036018] = {
          Camera = "-165.179688,-114.144531,207.396362,0.000156,-2.605772,-133.186981,25.0,1261.194092,false,Manual,22.0",
          ContentTC = "參加第六軍團的考核，也是為了有朝一日成為「桂冠卡戎」。只要過上更好的生活，就有機會登上更廣大的舞台……",
          DialogueId = 10036018,
          FinalCamera = "-187.849609,-138.015625,206.04657,0.000155,-1.805758,-134.186615,25.0,1261.194092,false,Manual,22.0",
          GUID = "191FC634",
          NextDialogue = 10036019,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Participating in the 6th Legion's tests was meant to be my first step toward becoming a Laurelled Charon. I thought if I could build a better life, I might one day stand on a grander stage...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC634"
        },
        [10036019] = {
          Camera = "483.212891,-613.606445,221.566162,0.000146,-6.40518,124.602669,25.0,189.198608,false,Manual,22.0",
          ContentTC = "再也不會只能對著舞台上的演員發呆，對著滿屋的錄音帶沉默，只因為卡戎之民沒有資格參加演出，因為頭上那根角會汙了觀眾的眼。",
          DialogueId = 10036019,
          GUID = "191FC65E",
          NextDialogue = 10036020,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I wouldn't have to hide in the shadows anymore, watching others bask in the spotlight, or surround myself with tapes of songs I couldn't even play — all because, as a Charon, my horn was deemed \"sickening\" to the audience.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC65E"
        },
        [10036020] = {
          Camera = "223.780273,-418.617188,192.429321,0.000123,5.795101,-18.393356,35.0,189.198654,false,Manual,2.8",
          ContentTC = "哈，哈哈。",
          DialogueId = 10036020,
          GUID = "191FC688",
          NextDialogue = 10036021,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Ha, hahaha.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC688"
        },
        [10036021] = {
          ContentTC = "很可笑吧。",
          DialogueId = 10036021,
          GUID = "191FC6B2",
          NextDialogue = 10036022,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I know — it's a ridiculous dream.",
          TalkActionId = {
            [1] = "100328:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC6B2"
        },
        [10036022] = {
          ContentTC = "我是覺得很搭。",
          DialogueId = 10036022,
          GUID = "191FC6DC",
          NextDialogue = 10036023,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "No, I just thought of us.",
          TalkActionId = {
            [1] = "100331:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC6DC"
        },
        [10036023] = {
          Camera = "-277.438477,12.542969,206.000488,0.000168,-2.405633,-27.593695,35.000008,989.247986,false,Manual,2.8",
          ContentTC = "我也喜歡歌劇，難怪會和你一見如故。等我們逃出去，我們就搭個舞台，叫來親朋好友，看我們表演。",
          DialogueId = 10036023,
          GUID = "191FC706",
          NextDialogue = 10036024,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I love opera too. No wonder we hit it off. After we get out, we'll set up a stage of our own, invite everyone we know, and put on a wonderful show for them.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC706"
        },
        [10036024] = {
          Camera = "199.172852,-433.332031,223.718994,0.000192,-3.005399,132.20047,35.000008,938.13208,false,Manual,2.8",
          ContentTC = "…………",
          DialogueId = 10036024,
          FinalCamera = "215.05957,-418.922852,223.388977,0.000192,-3.005399,132.20047,35.000008,938.13208,false,Manual,2.8",
          GUID = "191FC730",
          NextDialogue = 10036025,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC730"
        },
        [10036025] = {
          Camera = "198.80957,-348.649414,122.465942,0.000148,16.993544,-28.586533,35.0,302.68161,false,Manual,2.8",
          ContentTC = "不說話我就當你答應了，答應的承諾就得遵守。",
          DialogueId = 10036025,
          GUID = "191FC75A",
          NextDialogue = 10036026,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I'll take that as a yes. And a promise is a promise — I'll hold you to it.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC75A"
        },
        [10036026] = {
          ContentTC = "我有預感，離開的機會就要到了。",
          DialogueId = 10036026,
          GUID = "191FC784",
          LookAt = {
            [1] = "100331:n(100328)"
          },
          NextDialogue = 10036027,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I've got a feeling... our chance to escape is coming.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC784"
        },
        [10036027] = {
          Camera = "-336.173828,-305.694336,191.327087,0.000173,2.392745,50.61248,35.000008,302.68161,false,Manual,2.8",
          ContentTC = "錯覺罷了。",
          DialogueId = 10036027,
          FinalCamera = "-312.927734,-277.383789,192.857788,0.000173,2.392745,50.612766,35.000011,302.68161,false,Manual,2.8",
          GUID = "191FC7AE",
          NextDialogue = 10036028,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "It might be just a delusion.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC7AE"
        },
        [10036028] = {
          Camera = "198.80957,-348.649414,122.465942,0.000148,16.993544,-28.586533,35.0,302.68161,false,Manual,2.8",
          ContentTC = "這可不是錯覺，你沒感覺這些年下來，<H>抑制劑對我們的效果減弱了</>嗎？",
          DialogueId = 10036028,
          GUID = "191FC7D8",
          NextDialogue = 10036029,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "It's not. Haven't you noticed? The suppressants have been growing less effective on us over the years.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC7D8"
        },
        [10036029] = {
          ContentTC = "這就是我們還是人的證明，連身體都在提醒我們，該反抗了！",
          DialogueId = 10036029,
          GUID = "191FC802",
          NextDialogue = 10036030,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "That's proof we're still human — even our bodies are telling us it's time to fight for ourselves!",
          TalkActionId = {
            [1] = "100331:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC802"
        },
        [10036030] = {
          Camera = "-64.507812,-225.208984,216.510254,0.000098,-1.602383,103.814949,20.0,302.68161,false,Manual,2.8",
          ContentTC = "說難聽點，就是這具該死的怪物的身體變異得太成功了。",
          DialogueId = 10036030,
          FinalCamera = "-64.507812,-225.208984,216.510254,0.000069,-43.801937,102.617737,20.0,302.68161,false,Manual,2.8",
          GUID = "191FC82C",
          NextDialogue = 10036031,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Or maybe it's just this cursed, monstrous body mutating for its own survival.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC82C"
        },
        [10036031] = {
          Camera = "201.640625,-253.776367,315.783325,0.000122,-19.205063,-42.193974,35.0,302.68161,false,Manual,2.8",
          ContentTC = "哈哈，煉金術師還沒注意到這種變異，結果來說是好的嘛！我想想，我們得約個行動暗號……",
          DialogueId = 10036031,
          FinalCamera = "221.570312,-272.848633,306.172791,0.000119,-19.20507,-43.193863,35.0,302.68161,false,Manual,2.8",
          GUID = "191FC856",
          NextDialogue = 10036032,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Haha, but the alchemists haven't even noticed it yet. Their negligence is our chance. Let me think... we should come up with a secret signal for when the time comes.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC856"
        },
        [10036032] = {
          Camera = "-268.056641,6.759766,219.209229,0.000128,-4.005373,-26.392078,35.000008,1151.087158,false,Manual,2.8",
          ContentTC = "…………",
          DialogueId = 10036032,
          FinalCamera = "-268.056641,6.759766,219.209229,0.000128,-4.005373,-26.392078,35.000008,166.311462,false,Manual,2.8",
          GUID = "191FC880",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC880"
        },
        [10036033] = {
          ContentTC = "喂，你猜會是幾號？",
          DialogueId = 10036033,
          GUID = "191FC881",
          Subtitle = "Hey, which one do you think it's gonna be this time?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC881"
        },
        [10036034] = {
          ContentTC = "還真不好猜，數據實在是太接近了。",
          DialogueId = 10036034,
          GUID = "191FC882",
          Subtitle = "Hard to say — their metrics are almost identical.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC882"
        },
        [10036035] = {
          ContentTC = "我把今天的工作都推掉了，可別讓我失望啊。",
          DialogueId = 10036035,
          GUID = "191FC883",
          Subtitle = "Cleared my whole schedule for this. They'd better not disappoint.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC883"
        },
        [10036036] = {
          ContentTC = "嘿嘿嘿嘿嘻嘻嘻嘻……我真是興奮到不行了。",
          DialogueId = 10036036,
          GUID = "191FC884",
          Subtitle = "Heeheeheehee... ahahaha... I'm so excited I can barely breathe...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC884"
        },
        [10036101] = {
          ContentTC = "最後測驗開始，來比一比誰才是最成功的改造體吧！",
          DialogueId = 10036101,
          Duration = 7,
          GUID = "191FD3D2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "The final test begins! Let's find out which one of you is the ultimate augmented subject!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD3D2"
        },
        [10036102] = {
          ContentTC = "怎麼會……是我們倆的交戰？！",
          DialogueId = 10036102,
          Duration = 5,
          GUID = "191FD3FC",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What!? They're making us fight each other!?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD3FC"
        },
        [10036103] = {
          ContentTC = "看來我們終究是別無選擇啊……",
          DialogueId = 10036103,
          Duration = 4.5,
          GUID = "191FD426",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "We really don't have a choice, do we?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD426"
        },
        [10036104] = {
          ContentTC = "那就只好，<H>動手吧！</>",
          DialogueId = 10036104,
          Duration = 3.5,
          GUID = "191FD450",
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Guess not. Bring it on, then!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD450"
        },
        [10036105] = {
          ContentTC = "…………？！",
          DialogueId = 10036105,
          Duration = 1.2,
          GUID = "191FD47A",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD47A"
        },
        [10036106] = {
          ContentTC = "記得你要登台演出，別失約。",
          DialogueId = 10036106,
          GUID = "191FD4A4",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Remember, you've got a stage waiting for you.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4A4"
        },
        [10036107] = {
          ContentTC = "做不到的許諾，沒有意義。",
          DialogueId = 10036107,
          GUID = "191FD4CE",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What's the point of making promises you can't keep?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4CE"
        },
        [10036108] = {
          ContentTC = "會有意義的。",
          DialogueId = 10036108,
          GUID = "191FD4F8",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Because someday, they might just be fulfilled.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4F8"
        },
        [10036109] = {
          ContentTC = "36號！！你做什麼！請求支援，改造體狂暴反應，請求支援！",
          DialogueId = 10036109,
          GUID = "191FD522",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "36!! What the hell are you doing!? Subject exhibiting extreme instability! Requesting backup!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD522"
        },
        [10036110] = {
          ContentTC = "什麼……你可沒說過是用這種方式逃出去！",
          DialogueId = 10036110,
          GUID = "191FD54C",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What...!? You never said anything about making it out like this!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD54C"
        },
        [10036111] = {
          ContentTC = "咳……我……絕不食言……",
          DialogueId = 10036111,
          GUID = "191FD576",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "*coughs* I... never go back on my word...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD576"
        },
        [10036112] = {
          ContentTC = "……開了！",
          DialogueId = 10036112,
          GUID = "191FD5A0",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...It's open!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5A0"
        },
        [10036113] = {
          ContentTC = "抱、抱歉老師……我沒想到改造體居然能突破抑制劑的控制……",
          DialogueId = 10036113,
          GUID = "191FD5CA",
          NextDialogue = 10036114,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "P—Professor... I'm sorry! I didn't expect the subjects to resist the suppressant's effect...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5CA"
        },
        [10036114] = {
          ContentTC = "這是所有改造體身上都未曾有過的<H>異變</>，也許這就是我們最成功的傑作！",
          DialogueId = 10036114,
          GUID = "191FD5F4",
          NextDialogue = 10036115,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "This kind of mutation is unprecedented in any of our test subjects. Fascinating... Perhaps they're our greatest masterpiece yet!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5F4"
        },
        [10036115] = {
          ContentTC = "封鎖消息！使用最新的γ型抑制劑！務必活捉改造體！",
          DialogueId = 10036115,
          GUID = "191FD61E",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Lock down all information! Deploy the latest γ-type suppressant — bring the subject in alive, no matter the cost!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD61E"
        },
        [10036116] = {
          ContentTC = "咳、咳……我做到了嗎……",
          DialogueId = 10036116,
          GUID = "191FD648",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036117,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "*coughs* Did I make it...?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD648"
        },
        [10036117] = {
          ContentTC = "做到了，你做到了！",
          DialogueId = 10036117,
          GUID = "191FD672",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036118,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Yes! You made it!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD672"
        },
        [10036118] = {
          ContentTC = "那就，好……",
          DialogueId = 10036118,
          GUID = "191FD69C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036119,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Great...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD69C"
        },
        [10036119] = {
          ContentTC = "逃？這世上除了戰場與實驗室，哪裡有你們怪物的容身之所！",
          DialogueId = 10036119,
          GUID = "191FD6C6",
          NextDialogue = 10036120,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Where do you think you can run off to? Monsters like you have no place in this world — your only purpose is to serve on the battlefield or in a lab!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD6C6"
        },
        [10036120] = {
          ContentTC = "…………",
          DialogueId = 10036120,
          GUID = "191FD6F0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036121,
