        },
        [10036121] = {
          ContentTC = "我們不是怪物。我們是，人……！",
          DialogueId = 10036121,
          GUID = "191FD71A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
