        },
        [10036128] = {
          ContentTC = "太好了……我們……自由了……",
          DialogueId = 10036128,
          GUID = "191FD840",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036128.T_Story_Recall_10036128'",
          NextDialogue = 10036129,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Can't believe we actually made it... We're... finally free...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD840"
        },
        [10036129] = {
          ContentTC = "——呃！",
          DialogueId = 10036129,
          GUID = "191FD86A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036129.T_Story_Recall_10036129'",
