          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Ugh...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD86A"
        },
        [10036130] = {
          ContentTC = "你的傷……接下來交給我。",
          DialogueId = 10036130,
          GUID = "191FD894",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036130.T_Story_Recall_10036130'",
          NextDialogue = 10036131,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "You're hurt... I'll take care of everything from here.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD894"
        },
        [10036131] = {
          ContentTC = "首先，要找個地方藏身……",
          DialogueId = 10036131,
          GUID = "191FD8BE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036131.T_Story_Recall_10036131'",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "First, we need to find a place to hide...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD8BE"
        },
        [10036201] = {
          Camera = "-112.558594,-18.889648,137.671387,0.000057,0.198957,165.584488,35.0,100000.0,false,Manual,22.0",
          ContentTC = "原來下水道那個奇怪的舞台，就是你們一點點搭起來的啊。",
          DialogueId = 10036201,
          FinalCamera = "-112.96875,-20.488281,147.573242,0.000057,0.198957,165.584488,35.0,100000.0,false,Manual,22.0",
          GUID = "191FE43A",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100327)",
            [3] = "200002:n(100327)",
            [4] = "200021:n(100327)",
            [5] = "100327:n(100304)"
          },
          NextDialogue = 10036202,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SpeakNpcId = 200021,
          Subtitle = "So you were the ones who built that strange stage in the sewers?",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE43A"
        },
        [10036202] = {
          Camera = "602.476562,-249.944336,360.538574,0.000065,-25.800716,151.990204,20.0,100000.0,false,Manual,22.0",
          ContentTC = "怎會……為什麼……布魯斯……你……",
          DialogueId = 10036202,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE464",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "200021:n(100304)"
          },
          NextDialogue = 10036203,
          Scripts = "MoveTo{ActorId{100304},MoveSpeed{120},TargetPoint{\"lise_56_walk\"}}",
          SpeakNpcId = 100304,
          Subtitle = "How... why... how could this happen to you... Blues...",
          TalkActionId = {
            [1] = "200021:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE464"
        },
        [10036203] = {
          Camera = "255.566406,-24.741699,131.422363,0.000058,0.598905,163.386917,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……還痛嗎？",
          DialogueId = 10036203,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "223.371094,-15.542969,131.395508,0.000058,1.398898,162.986725,35.0,100000.0,false,Manual,22.0",
          GUID = "191FE48E",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10036204,
          SpeakNpcId = 100304,
          Subtitle = "...Does it still hurt?",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE48E"
        },
        [10036204] = {
          Camera = "-10.363281,-8.108887,102.920898,0.000115,20.997046,15.209096,25.000006,495.125,false,Manual,2.799999",
          ContentTC = "我……還好。",
          DialogueId = 10036204,
          GUID = "191FE4B8",
          NextDialogue = 10036205,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...I'm fine.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE4B8"
        },
        [10036205] = {
          Camera = "90.679688,-10.201172,155.186035,0.000029,19.198732,13.00046,25.000006,233.5448,false,Manual,2.8",
          ContentTC = "只可惜，命運只是，短暫地，垂憐了我們一下。逃出煉金院，不是，新生活的開始，而是，結束……",
          DialogueId = 10036205,
          GUID = "191FE4E2",
          NextDialogue = 10036206,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "But fate only gave us a fleeting moment of mercy — escaping the academy wasn't the start of a new life... but the beginning of the end.",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE4E2"
        },
        [10036206] = {
          ContentTC = "……逃跑時，煉金術師，新型抑制劑……毀掉了，我的，喉嚨，更摧毀了……心智……",
          DialogueId = 10036206,
          GUID = "191FE50C",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10036207,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "During our escape... the alchemists... their new suppressant ruined my voice... and messed up our minds...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE50C"
        },
        [10036207] = {
          ContentTC = "我們時常，發瘋，失控……而我的朋友，<H>36號</>，已經先我一步……",
          DialogueId = 10036207,
          GUID = "191FE536",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036208,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "We couldn't control ourselves... we'd go berserk from time to time... And my friend... 36... has already left this world before me.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE536"
        },
        [10036208] = {
          Camera = "-178.277344,-33.839355,138.938477,0.00009,5.597422,154.782913,50.0,239.778275,false,Manual,22.0",
          ContentTC = "嘖，早就知道煉金院那群煉金術師不是人，沒想到這麼不是人。居然和第六軍團勾結，把魔法資質好的卡戎之民騙去做實驗……",
          DialogueId = 10036208,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "191FE560",
          NextDialogue = 10036209,
          SpeakNpcId = 200021,
          Subtitle = "Ugh, I always knew those alchemists were wicked scum, but this... this is cruelty on an entirely different level. And to think they had the gall to go in cahoots with the 6th Legion, luring Charons with strong magical aptitude just to turn them into test subjects...",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE560"
        },
        [10036209] = {
          Camera = "201.75,1.508789,159.896973,-6.000039,-11.003229,172.177917,25.000006,100000.0,false,Manual,22.0",
          ContentTC = "姐姐，你聽好。",
          DialogueId = 10036209,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE58A",
          NextDialogue = 10036210,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Listen, Sister.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE58A"
        },
        [10036210] = {
          Camera = "55.476562,-24.161621,154.890137,-6.00001,14.795302,12.594482,25.000002,100000.0,false,Manual,22.0",
          ContentTC = "第六軍團，用桂冠卡戎，欺騙我們。",
          DialogueId = 10036210,
          FinalCamera = "55.476562,-24.161621,154.890137,-6.000008,17.595236,12.594818,25.000002,100000.0,false,Manual,22.0",
          GUID = "191FE5B4",
          NextDialogue = 10036211,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The 6th Legion... they use the title of \"Laurelled Charon\"... as a lure to deceive us.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE5B4"
        },
        [10036211] = {
          Camera = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
          ContentTC = "離開，軍團。",
          DialogueId = 10036211,
          GUID = "191FE5DE",
          NextDialogue = 10036212,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "LEAVE... the Legion.",
          TalkActionId = {
            [1] = "100327:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE5DE"
        },
        [10036212] = {
          Camera = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
          ContentTC = "找個，安穩的地方，好好——",
          DialogueId = 10036212,
          GUID = "191FE608",
          NextDialogue = 10036213,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Find a quiet, safe place... and take care of yourse—",
          TalkActionId = {
            [1] = "100327:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE608"
        },
        [10036213] = {
          Camera = "227.824219,31.842285,181.181152,0.000023,-16.404352,178.979095,45.0,100000.0,false,DoNotOverride,22",
          ContentTC = "那你呢，你要怎麼辦？！",
          DialogueId = 10036213,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE632",
          NextDialogue = 10036214,
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"189.578125,-871.764404,19.383301,-0.0,6.995186,93.378288,25.0,100000.0,false,DoNotOverride,22\"},duration{0}}",
          SpeakNpcId = 100304,
          Subtitle = "What about you!?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE632"
        },
        [10036214] = {
          Camera = "86.808594,-88.199707,320.100586,0.000018,-29.605869,33.985477,25.0,100000.0,false,Manual,22.0",
          ContentTC = "我……",
          DialogueId = 10036214,
          FinalCamera = "4.820312,-143.472656,376.284668,0.000023,-32.005917,34.185921,25.0,100000.0,false,Manual,22.0",
          GUID = "191FE65C",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE65C"
        },
        [10036215] = {
          ContentTC = "五天前，下水道出口",
          DialogueId = 10036215,
          GUID = "191FE686",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          Subtitle = "Five Days Ago, Sewer Exit",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE686"
        },
        [10036216] = {
          ContentTC = "我還，以為，你會一直昏到，世界末日。",
          DialogueId = 10036216,
          GUID = "191FE6B0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036217,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SnapShot = "MEMORY",
          Subtitle = "I thought... you were going to... stay unconscious... until the end of the world.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE6B0"
        },
        [10036217] = {
          ContentTC = "都怪我。如果我能早點趕來，你就不會被他們……",
          DialogueId = 10036217,
          GUID = "191FE6DA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036218,
          SnapShot = "MEMORY",
          Subtitle = "It's all my fault. If I'd got here sooner, you wouldn't have been...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE6DA"
        },
        [10036218] = {
          ContentTC = "沒機會，的。我能清醒的時間，在縮短。",
          DialogueId = 10036218,
          GUID = "191FE704",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036219,
          SnapShot = "MEMORY",
          Subtitle = "We wouldn't. We wouldn't have stood a chance. My moments of clarity... are slipping away.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE704"
        },
        [10036219] = {
          ContentTC = "也可能是，如你所說，我的心，真的變成了……怪物。",
          DialogueId = 10036219,
          GUID = "191FE72E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036220,
          SnapShot = "MEMORY",
          Subtitle = "Or perhaps, like you said... my heart has already turned into... that of a monster.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE72E"
        },
        [10036220] = {
          ContentTC = "你是怪物的話，那我又是什麼呢？",
          DialogueId = 10036220,
          GUID = "191FE758",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036221,
          SnapShot = "MEMORY",
          Subtitle = "If you're a monster... then what does that make me?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE758"
        },
        [10036221] = {
          ContentTC = "我們追逐的，那盞燈，原來這麼耀眼，高不可及啊。",
          DialogueId = 10036221,
          GUID = "191FE782",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036222,
          SnapShot = "MEMORY",
          Subtitle = "We chased so hard to catch the light, the dazzling light... only to find it's so... unreachable in the end.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE782"
        },
        [10036222] = {
          ContentTC = "高不可及的東西，讓它墜落到地面來不就好了嗎？",
          DialogueId = 10036222,
          GUID = "191FE7AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036223,
          Scripts = [[
SEQ
{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt03/0080_story_the_abandoned_theme"},RelatedRegionId{101103}}
}]],
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "If something is unreachable, why not pull it down to the ground?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE7AC"
        },
        [10036223] = {
          ContentTC = "當心，<H>他身上有毒</>……你是誰！",
          DialogueId = 10036223,
          GUID = "191FE7D6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036224,
          SnapShot = "MEMORY",
          Subtitle = "Stay back — his body is toxic... Who are you?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE7D6"
        },
        [10036224] = {
          ContentTC = "我有很多個名字，也有很多種身份，但這些說到底只是一個代號。而代號不管怎麼變，我們這被神拋棄的本質都不會更改。",
          DialogueId = 10036224,
          GUID = "191FE800",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036225,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "I have many names, many faces. But in the end, they're all just labels. No matter how those labels shift or change, one truth remains — we have been forsaken by the gods.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE800"
        },
        [10036225] = {
          ContentTC = "說到這裡，聰明的你們應該知道我是誰了吧。",
          DialogueId = 10036225,
          GUID = "191FE82A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036226,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Now, someone as sharp as you should already know who I am.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE82A"
        },
        [10036226] = {
          ContentTC = "我是來向你們發出一個邀請的，加入我們，將那高不可及的索拉之民拖到地上，感受卡戎的怒火。",
          DialogueId = 10036226,
          GUID = "191FE854",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036227,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "I'm here to extend an invitation. Join us. Drag the untouchable Solas down to the ground, and let them feel the wrath of Charons.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE854"
        },
        [10036227] = {
          ContentTC = "別急著拒絕。好好想想帝國對你們的所作所為吧！他們用美好的謊言欺騙你們，用殘忍的刑罰折磨你們，用無盡的絕望籠罩你們。",
          DialogueId = 10036227,
          GUID = "191FE87E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036228,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Don't rush to reject me. Reflect on what the Empire has done to you. They lured you in with sweet lies, broke you with merciless torture, and buried you under an ocean of despair.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE87E"
        },
        [10036228] = {
          ContentTC = "在這條路的盡頭等你們的是什麼？當上「桂冠卡戎」，過上更好的生活，實現更遠的夢想？",
          DialogueId = 10036228,
          GUID = "191FE8A8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036229,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "And what lies at the end of this path? Becoming a Laurelled Charon? A better life? Greater dreams fulfilled?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8A8"
        },
        [10036229] = {
          ContentTC = "不！是被索拉人敲骨吸髓，被同胞中的叛徒追捕，最後死在哪個不知名的角落。",
          DialogueId = 10036229,
          GUID = "191FE8D2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036230,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Absolutely not! What awaits is a slow death — your bones picked clean by the Sola elites, hunted by traitors among our own kind, until you're discarded like trash in some forgotten corner.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8D2"
        },
        [10036230] = {
          ContentTC = "他們用一個簡單的承諾，驅使如你，如我，如所有渴望出人頭地的卡戎，一頭扎進深淵。",
          DialogueId = 10036230,
          GUID = "191FE8FC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036231,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "With a single empty promise, they lure aspiring Charons like you and me straight into the abyss.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8FC"
        },
        [10036231] = {
          ContentTC = "只要第六軍團和煉金院的謊言不被戳破，就不斷會有冰湖城的卡戎之民沿著軍團這條路走下去，一個又一個，踏上和你們一樣的悲劇。",
          DialogueId = 10036231,
          GUID = "191FE926",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036232,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "As long as the 6th Legion and the Alchemy Academy's web of lies remains intact, Charons of Icelake will continue walking this path to ruin, marching straight into the same tragedy as you... again and again.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE926"
        },
        [10036232] = {
          ContentTC = "…………！",
          DialogueId = 10036232,
          GUID = "191FE950",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036233,
          SnapShot = "MEMORY",
          Subtitle = "...!",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE950"
        },
        [10036233] = {
          ContentTC = "我們被帝國奪走了過去，苟活在當下。未來我們也要這樣毫無作為，讓那群畜生碾碎我們所珍視的一切嗎？",
          DialogueId = 10036233,
          GUID = "191FE97A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036234,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "The Empire stripped us of what we once had and left us trapped in this miserable present. Are we really going to let them crush everything we hold dear without putting up a fight?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE97A"
        },
        [10036234] = {
          ContentTC = "看啊，看看現在的你我。帝國貪求我們的力量，為我們套上鐐銬，把我們變成野獸，淪為真正的惡魔。",
          DialogueId = 10036234,
          GUID = "191FE9A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036235,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Look at us. The Empire coveted our strength, shackled us like animals, and twisted us into grotesque monsters — into real demons.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9A4"
        },
        [10036235] = {
          ContentTC = "如今我們好不容易掙脫了枷鎖，那不正是用帝國給予我們的這副獠牙，狠狠咬向他們咽喉的時刻嗎！",
          DialogueId = 10036235,
          GUID = "191FE9CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036236,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "But now, we've broken free of those chains. Isn't it time to turn their own weapons against them? Time we made them pay?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9CE"
        },
        [10036236] = {
          ContentTC = "讓他們記住我們的存在，感受我們的痛苦，再也不敢覬覦我們珍惜的東西！讓他們用鮮血去懺悔，去銘記我們的存在，讓整個帝國呼喚我們的名字！",
          DialogueId = 10036236,
          GUID = "191FE9F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036237,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Let them tremble at the mere thought of us. Let them feel the pain we've endured. Make them never dare to covet what we hold dear again! Let them repent with their blood and remember us for eternity. Let the entire Empire scream our names in terror!",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9F8"
        },
        [10036237] = {
          ContentTC = "<W>神弃者同盟</>……",
          DialogueId = 10036237,
          GUID = "191FEA22",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036238,
          RelatedWikiId = {
            [1] = 101004
          },
          SnapShot = "MEMORY",
          Subtitle = "The Forsakens...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA22"
        },
        [10036238] = {
          ContentTC = "你們可以把它理解成報復，但我更希望你們把它理解成保護，這是只有我們「惡魔」才能做到的責任——清理內城的「垃圾」，還你們的家人一個乾淨的未來。",
          DialogueId = 10036238,
          GUID = "191FEA4C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "You may call it vengeance, but I call it protection. We \"demons\" bear a duty to protect our kind. We'll rid the inner city of its \"filth\" and give your loved ones the cleaner, brighter future they deserve.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA4C"
        },
        [10036239] = {
          Camera = "145.113281,-134.397461,226.663574,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "（神棄者同盟……）",
          DialogueId = 10036239,
          DisableMouth = 1,
          FinalCamera = "149.515625,-128.306641,226.455078,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
          GUID = "191FEA76",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100327)",
            [3] = "200002:n(100327)",
            [4] = "200021:n(100327)"
          },
          NextDialogue = 10036240,
          Scripts = [[
PARA{
SetRotation{SetRotationDescription{"100327:p(180)"}} ,
SetLocation{ActorId{200021},TargetPoint{"aoge_57"},Visibility{"Show"}}
}]],
          SnapShot = "HEART",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(The Forsakens...)",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA76"
        },
        [10036240] = {
          Camera = "419.355469,-129.479492,225.521484,-0.000548,-20.001587,145.330276,25.0,389.646332,false,Manual,2.8",
          ContentTC = "我還有，未竟之事。",
          DialogueId = 10036240,
          FacialId = {
            [1] = "100304:Unacceptable01"
          },
          FinalCamera = "413.167969,-138.438477,274.373047,-0.000549,-20.001587,145.330292,25.0,389.646332,false,Manual,2.8",
          GUID = "191FEAA0",
          NextDialogue = 10036241,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I still have... unfinished business.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FEAA0"
        },
        [10036241] = {
          ContentTC = "布鲁斯！",
          DialogueId = 10036241,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FEACA",
          NextDialogue = 10036242,
          Scripts = "MoveTo{ActorId{100327},TargetPoint{\"tuosi02_57_walk01\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100304,
          Subtitle = "Blues!",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FEACA"
        },
        [10036242] = {
          Camera = "1270.355469,72.632324,16.277832,-0.000549,15.796513,-175.065521,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "不要跟來。",
          DialogueId = 10036242,
          FinalCamera = "1270.355469,72.632324,16.277832,-0.000549,3.996487,-174.865509,35.000011,100000.0,false,Manual,22.0",
          GUID = "191FEAF4",
          Scripts = "MoveTo{ActorId{100327},TargetPoint{\"tuosi02_57_walk02\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Do not follow.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100362/191FEAF4"
        },
        [10036301] = {
          ContentTC = "哇，看他看他，好酷的行頭。",
          DialogueId = 10036301,
          Duration = 5,
          GUID = "191FF4A2",
          SpeakNpcId = 100366,
          Subtitle = "Whoa, check him out! That gear's absolutely wild.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4A2"
        },
        [10036302] = {
          ContentTC = "這盔甲，這頭套！哪裡訂做的，我也想要！",
          DialogueId = 10036302,
          Duration = 7,
          GUID = "191FF4CC",
          SpeakNpcId = 100368,
          Subtitle = "Seriously, where'd he get that? I've got to get one of those too!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4CC"
        },
        [10036303] = {
          ContentTC = "哈哈哈哈你看那邊，還有人裝扮成神棄者和穢獸呢，不要命啦。",
          DialogueId = 10036303,
          Duration = 10,
          GUID = "191FF4F6",
          SpeakNpcId = 100367,
          Subtitle = "Hahaha, look at those guys over there — dressed as the Forsakens and Filthoids! They're insane!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF4F6"
        },
        [10036304] = {
          ContentTC = "怕什麼，在這裡我們沒有身份，沒有名字，沒有種族！只有狂歡，徹夜狂歡！",
          DialogueId = 10036304,
          Duration = 12,
          GUID = "191FF520",
          SpeakNpcId = 100369,
          Subtitle = "Who cares? Here, we have no identities, no names, no races! Only masks, music, and revelry!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF520"
        },
        [10036305] = {
          ContentTC = "(蓋雷亞劇院，我回來了。)",
          DialogueId = 10036305,
          DisableMouth = 1,
          GUID = "191FF54A",
          NextDialogue = 10036306,
          SnapShot = "HEART",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(Galea Theatre. I'm back.)",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF54A"
        },
        [10036306] = {
          ContentTC = "（只可惜是在這愚蠢的狂歡日……這群瘋狂的傢伙對這兒是一種玷汙。）",
          DialogueId = 10036306,
          DisableMouth = 1,
          GUID = "191FF574",
          NextDialogue = 10036307,
          SnapShot = "HEART",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(Shame it's during this ridiculous celebration... Such cacophony of lunacy defiles the sanctity of this place.)",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF574"
        },
        [10036307] = {
          ContentTC = "（……現在不是思考這個的時候。去跟同盟的那傢伙碰面吧。）",
          DialogueId = 10036307,
          DisableMouth = 1,
          GUID = "191FF59E",
          SnapShot = "HEART",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(...Focus. Now isn't the time for sentimentality. I need to meet with the Forsakens' contact.)",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF59E"
        },
        [10036308] = {
          Camera = "64.748032,73.186905,141.25,0.000034,-0.801086,-95.817291,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "居然叫我來這種地方，你還有這般雅興。",
          DialogueId = 10036308,
          FinalCamera = "59.996071,26.498751,140.589844,0.000034,-0.801086,-95.817314,35.000008,100000.0,false,Manual,22.0",
          GUID = "191FF5C8",
          NextDialogue = 10036309,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{101901}}",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Can't believe you chose to meet in a place like this. Never took you for someone who enjoys such frivolities.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF5C8"
        },
        [10036309] = {
          Camera = "47.290932,-282.748688,98.773438,0.000223,12.987468,99.416245,20.0,100000.0,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "我不是說過如無必要減少碰面嗎？現在十三軍團也撤走了，我們得盡快完成此前的約定才是。",
          DialogueId = 10036309,
          FinalCamera = "153.951035,-298.556122,92.078125,-2.0,9.185791,119.818588,20.0,100000.0,false,Manual,22.0",
          GUID = "191FF5F2",
          NextDialogue = 10036310,
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "And didn't I tell you to minimise contact unless absolutely necessary? The 13th Legion is gone. We've got to finish our deal ASAP.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100363/191FF5F2"
        },
        [10036310] = {
          Camera = "48.10738,-52.516705,168.945312,0.00015,15.595841,97.983627,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "沒錯，可以完成，約定了。",
          DialogueId = 10036310,
          GUID = "191FF61C",
          NextDialogue = 10036311,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Yes. It can be... finished now. As we... agreed.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF61C"
        },
        [10036311] = {
          Camera = "59.996071,26.498751,140.589844,0.000034,-0.801086,-95.817314,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "…………？！",
          DialogueId = 10036311,
          GUID = "191FF646",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF646"
        },
        [10036312] = {
          ContentTC = "你……怎麼……唔……呃——！",
          DialogueId = 10036312,
          GUID = "191FF670",
          NextDialogue = 10036313,
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "What are you... why... Urgh... Agh!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF670"
        },
        [10036313] = {
          ContentTC = "協助你，藉此引來，十三軍團，目的，達到。",
          DialogueId = 10036313,
          GUID = "191FF69A",
          NextDialogue = 10036314,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I only... cooperated with you... to draw out... the 13th Legion. Now... it's done.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF69A"
        },
        [10036314] = {
          ContentTC = "但十三軍團，拒絕，揭露真相。",
          DialogueId = 10036314,
          GUID = "191FF6C4",
          NextDialogue = 10036315,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "But the 13th Legion... refused to expose the truth.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF6C4"
        },
        [10036315] = {
          ContentTC = "那麼你，就沒有，利用價值。",
          DialogueId = 10036315,
          GUID = "191FF6EE",
          NextDialogue = 10036316,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "So now, you've outlived... your usefulness.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF6EE"
        },
        [10036316] = {
          ContentTC = "神棄者，也是，禍患。",
          DialogueId = 10036316,
          GUID = "191FF718",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The Forsakens... are just another... plague to cleanse.",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF718"
        },
        [10036317] = {
          ContentTC = "酷啊！這次的演出比往年還逼真！",
          DialogueId = 10036317,
          GUID = "191FF742",
          NextDialogue = 10036318,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Awesome! This year's show is on a whole new level — it looks so real!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF742"
        },
        [10036318] = {
          ContentTC = "喂，怎麼還有人裝扮成軍團士兵的模樣啊？看手裡那傢伙，跟真的一樣啊！",
          DialogueId = 10036318,
          GUID = "191FF76C",
          NextDialogue = 10036319,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Check that out! Someone's really gone all in with that soldier costume. That gear... it looks legit!",
          VoiceName = "voice/$Locale$/story/1003/100363/191FF76C"
        },
        [10036319] = {
