          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/192015F0"
        },
        [10036505] = {
          Camera = "67.845703,-302.296021,112.21875,0.00005,11.194864,-117.729912,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……凶手的身份和動機還未確認，直接擊斃無法向冰湖城的受害者交代！",
          DialogueId = 10036505,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "87.982422,-255.8255,86.699219,0.000067,11.194679,-117.325897,35.000008,100000.0,false,Manual,22.0",
          GUID = "1920161A",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)",
            [4] = "100327:n(100304)"
          },
          NextDialogue = 10036506,
          SpeakNpcId = 100304,
          Subtitle = "...The killer's identity and motive remain unconfirmed. Executing him now will not serve justice for the victims of Icelake!",
          TalkActionId = {
