        },
        [10036508] = {
          Camera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          ContentTC = "你還記得你加入軍團那天，在三頭狼旗下發過的誓言嗎？「將此生奉獻給皇帝陛下，成為海伯利亞的忠誠戰士，至死方休。」",
          DialogueId = 10036508,
          FinalCamera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          GUID = "19201698",
          LookAt = {
            [1] = "100304:n(100310)"
          },
          NextDialogue = 10036509,
          SpeakNpcId = 100310,
          Subtitle = "Do you remember the oath you swore under the banner of the Three Wolves? \"To dedicate my life to His Majesty, to become a loyal soldier of Hyperborea, and to serve until death.\"",
          TalkActionId = {
            [1] = "100310:Angry01_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201698"
        },
        [10036509] = {
          Camera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          ContentTC = "琳恩長官說過，你雖是卡戎之民，卻是難得的人才。她本打算在案子結束後提攜你去皇都。",
          DialogueId = 10036509,
          GUID = "192016C2",
          NextDialogue = 10036510,
          SpeakNpcId = 100310,
          Subtitle = "Major Lynn spoke highly of you — she considered you a very promising soldier, despite your Charon bloodline. She was even planning to recommend you for promotion to the capital once this case was resolved.",
          VoiceName = "voice/$Locale$/story/1003/100365/192016C2"
        },
        [10036510] = {
          Camera = "53.857422,378.744141,188.148438,0.000066,-9.20508,-99.947792,20.0,100000.0,false,Manual,22.0",
          ContentTC = "十三軍團一向惜才，我再給你最後一次證明自己是海伯利亞忠誠戰士的機會。給我讓開。",
          DialogueId = 10036510,
          FinalCamera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
          GUID = "192016EC",
          NextDialogue = 10036511,
          SpeakNpcId = 100310,
          Subtitle = "The 13th Legion values its ace soldiers. I'm giving you one last chance to prove your loyalty to Hyperborea. Step aside.",
          TalkActionId = {
            [1] = "100310:Angry01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/192016EC"
        },
        [10036511] = {
          Camera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
          ContentTC = "……不。",
          DialogueId = 10036511,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          GUID = "19201716",
          LookAt = {
            [1] = "100304:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)"
          },
          NextDialogue = 10036512,
          SpeakNpcId = 100304,
          Subtitle = "...No.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201716"
        },
        [10036512] = {
          Camera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
          ContentTC = "你敢違抗軍令？！",
          DialogueId = 10036512,
          GUID = "19201740",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036513,
          SpeakNpcId = 100310,
          Subtitle = "You dare defy a direct order!?",
          TalkActionId = {
            [1] = "100310:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201740"
        },
        [10036513] = {
          Camera = "144.183594,-290.747986,325.367188,14.401219,-44.003242,-130.524872,35.0,100000.0,false,Manual,22.0",
          ContentTC = "我從小到大一直腦子笨，想不通很多事情。究竟怎麼做才能稱得上「海伯利亞的忠誠戰士」，其實我到現在也沒能想太明白。",
          DialogueId = 10036513,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "126.980469,-310.735382,299.902344,14.401626,-44.003242,-130.724792,35.0,100000.0,false,Manual,22.0",
          GUID = "1920176A",
          LookAt = {
            [1] = "100304:p(lise_ditou)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)",
            [4] = "100327:n(100304)"
          },
          NextDialogue = 10036514,
          SpeakNpcId = 100304,
          Subtitle = "I've always been a slow thinker — never good at understanding complicated ideas. Even now, I still don't know what it means to be a \"loyal soldier of Hyperborea.\"",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/1920176A"
        },
        [10036514] = {
          Camera = "126.980469,-310.735382,299.902344,14.401626,-44.003242,-130.724792,35.0,100000.0,false,Manual,22.0",
          ContentTC = "但我只知道一件事——如果忠於海伯利亞、忠於皇帝陛下，要以踐踏這座我生長的城市、踐踏幫助過我的人、踐踏與我相依為命的骨肉至親為代價……",
          DialogueId = 10036514,
          FacialId = {
            [1] = "100304:Angry01"
          },
          GUID = "19201794",
          NextDialogue = 10036515,
          SpeakNpcId = 100304,
          Subtitle = "But there's one thing I know for sure: if loyalty to Hyperborea, to His Majesty, means trampling the place where I was born and raised, betraying those who've helped me, and turning my back on my loved ones...",
          VoiceName = "voice/$Locale$/story/1003/100365/19201794"
        },
        [10036515] = {
          Camera = "46.298828,-302.022705,104.398438,0.000043,12.393856,-107.324394,35.000008,100000.0,false,Manual,4.0",
          ContentTC = "從此刻起，黎瑟·費西爾將不再是海伯利亞忠誠的戰士！",
          DialogueId = 10036515,
          FacialId = {
            [1] = "100304:Grief"
          },
          FinalCamera = "78.177734,-200.148499,80.761719,0.000044,11.993859,-107.12439,35.000008,100000.0,false,Manual,22.0",
          GUID = "192017BE",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036516,
          SpeakNpcId = 100304,
          Subtitle = "Then from this very moment on, Rhythm Fischer is no longer a loyal soldier of Hyperborea!",
          TalkActionId = {
            [1] = "100304:Lise_Story_Aim_Start"
          },
          ToFinalCameraBlendTime = 0.6,
          VoiceName = "voice/$Locale$/story/1003/100365/192017BE"
        },
        [10036516] = {
          Camera = "438.205078,-272.948975,145.40625,0.000054,0.193151,156.073257,50.0,100000.0,false,Manual,22.0",
          ContentTC = "違抗軍紀，阻礙其他軍團執行任務，依照帝國軍律，同樣就地擊斃。",
          DialogueId = 10036516,
          FinalCamera = "532.177734,-60.53857,145.40625,0.000054,0.193151,155.673569,50.0,100000.0,false,Manual,22.0",
          GUID = "192017E8",
          NextDialogue = 10036517,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3},TargetPosition{"315.181641,-1309.563599,274.621094,10.818109,-9.806095,108.059586,25.0,100000.0,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100310,
          Subtitle = "Disobeying orders. Obstructing a Legion operation. By Imperial law, that's grounds for immediate execution.",
          TalkActionId = {
            [1] = "100310:Confident_End",
            [2] = "100340:Aim_Loop",
            [3] = "100341:Aim_Loop",
            [4] = "100342:Aim_Loop",
            [5] = "100343:Aim_Loop",
            [6] = "100350:Aim_Loop",
            [7] = "100351:Aim_Loop",
            [8] = "100352:Aim_Loop",
            [9] = "100353:Aim_Loop",
            [10] = "100346:Aim_Loop",
            [11] = "100347:Aim_Loop",
            [12] = "100348:Aim_Loop",
            [13] = "100349:Aim_Loop"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100365/192017E8"
        },
        [10036517] = {
          Camera = "89.65625,-483.724762,116.578125,0.000128,20.201172,-99.007301,35.0,100000.0,false,Manual,22.0",
          ContentTC = "這可，不行。",
          DialogueId = 10036517,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "78.884766,-551.646484,141.859375,0.000132,20.201172,-99.007294,35.0,100000.0,false,Manual,22.0",
          GUID = "19201812",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "That won't be... happening.",
          TalkActionId = {
            [1] = "100327:Angry01_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100365/19201812"
        },
        [10036518] = {
          ContentTC = "全部處理掉，一個都不能放出劇院！",
          DialogueId = 10036518,
          GUID = "1920183C",
          NextDialogue = 10036519,
          SpeakNpcId = 100310,
          Subtitle = "Eliminate them all! Don't let any of them leave the theatre alive!",
          VoiceName = "voice/$Locale$/story/1003/100365/1920183C"
        },
        [10036519] = {
          ContentTC = "抱歉了，長官……！",
          DialogueId = 10036519,
          GUID = "19201866",
          NextDialogue = 10036520,
          SpeakNpcId = 100304,
          Subtitle = "I'm sorry, Officer...!",
          VoiceName = "voice/$Locale$/story/1003/100365/19201866"
        },
        [10036520] = {
          ContentTC = "黎瑟撐住！我們也來幫你。",
          DialogueId = 10036520,
          GUID = "19201890",
          NextDialogue = 10036521,
          SpeakNpcId = 100001,
          Subtitle = "Rhythm, hang in there! We'll back you up!",
          VoiceName = "voice/$Locale$/story/1003/100365/19201890"
        }
      }
    end
  },
  {
    MinKey = 10036521,
    MaxKey = 10037615,
    Loader = function()
      return {
        [10036521] = {
          ContentTC = "好吧、好吧。既然都到了這份上，我也只能捨命相陪了！",
          DialogueId = 10036521,
          GUID = "192018BA",
          NextDialogue = 10036522,
          SpeakNpcId = 200021,
          Subtitle = "Well, guess I've got no choice but to throw my lot in too, huh?",
          VoiceName = "voice/$Locale$/story/1003/100365/192018BA"
        },
        [10036522] = {
          ContentTC = "你們、怎麼……",
          DialogueId = 10036522,
          GUID = "192018E4",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "You guys... why would you...",
          VoiceName = "voice/$Locale$/story/1003/100365/192018E4"
        },
        [10036523] = {
