            [1] = "100001:Doubt01"
          },
          GUID = "19201D54",
          NextDialogue = 10036550,
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [10036590] = {
          ContentTC = "背叛軍團的只有我一人，狩月人小隊是無端卷進來的，還請長官不要為難他們。",
          DialogueId = 10036590,
          GUID = "19201AB3",
          NextDialogue = 10036534,
          SpeakNpcId = 100304,
          Subtitle = "I'm the one who betrayed the Legion. The Phoxhunters were merely caught up in it — they're innocent. Please, sir... don't punish them for my mistake.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201AB3"
        },
        [10036601] = {
          Camera = "-468.048828,-114.833618,288.109375,0.000034,-35.421776,40.107498,11.88,100000.0,false,Manual,22.0",
          ContentTC = "這樣就，沒人知道，你們來過。",
          DialogueId = 10036601,
          Duration = 5,
          FinalCamera = "-455.794922,-104.521362,276.699219,0.00003,-35.421753,40.107464,11.88,100000.0,false,Manual,22.0",
          GUID = "192025DA",
          LookAt = {
            [1] = "100327:n(100341)"
          },
          NextDialogue = 10036602,
          Scripts = [[
PARA{
SetLocation{ActorId{100327},TargetPoint{"tuosi02_62"},Visibility{"Show"}},
SetRotation{SetRotationDescription{"100350:p(150)"}},
SetRotation{SetRotationDescription{"100351:p(120)"}},
SetRotation{SetRotationDescription{"100353:p(110)"}},
SetRotation{SetRotationDescription{"100352:p(100)"}},
SetRotation{SetRotationDescription{"100340:p(60)"}},
SetRotation{SetRotationDescription{"100341:p(30)"}},
SetRotation{SetRotationDescription{"100342:p(-30)"}},
SetRotation{SetRotationDescription{"100343:p(-60)"}},
SetRotation{SetRotationDescription{"100348:p(-90)"}},
SetRotation{SetRotationDescription{"100349:p(-100)"}},
SetRotation{SetRotationDescription{"100347:p(-120)"}},
SetRotation{SetRotationDescription{"100346:p(-150)"}},
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "This way, no one will ever know you were here... and attacked the Legion.",
          TalkActionId = {
            [1] = "100310:Onground02",
            [2] = "100340:Onground02",
            [3] = "100341:Onground02",
            [4] = "100342:Onground02",
            [5] = "100343:Onground02",
            [6] = "100350:Onground02",
            [7] = "100351:Onground02",
            [8] = "100352:Onground02",
            [9] = "100353:Onground02",
            [10] = "100346:Onground02",
            [11] = "100347:Onground02",
            [12] = "100348:Onground02",
            [13] = "100349:Onground02"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100366/192025DA"
        },
        [10036602] = {
          ContentTC = "這個秘密，由我……帶進墳墓。",
          DialogueId = 10036602,
          GUID = "19202604",
          NextDialogue = 10036603,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "I'm taking this secret... to the grave.",
          VoiceName = "voice/$Locale$/story/1003/100366/19202604"
        },
        [10036603] = {
          Camera = "-508.236328,-141.803528,-26.71875,-0.001345,50.110828,41.260582,15.0,100000.0,false,Manual,22.0",
          ContentTC = "布魯斯，我完成約定了。",
          DialogueId = 10036603,
          FinalCamera = "-508.236328,-141.803528,-26.71875,-0.001344,55.910446,50.060265,15.0,100000.0,false,Manual,22.0",
          GUID = "1920262E",
          LookAt = {
            [1] = "100327:p(tuosi02_62_lookat)"
          },
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Blues... I've fulfilled my promise.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100327:p(70)"
          },
          VoiceName = "voice/$Locale$/story/1003/100366/1920262E"
        },
        [10036604] = {
          ContentTC = "（士兵的手腕有一道細細的傷痕，稍加辨認便能看出是被利劍所傷。但<H>這個舞台最終留下的，應該只有軍團與「怪物」戰鬥的痕跡才對。</>）",
          DialogueId = 10036604,
          GUID = "1920226A",
          NextOptions = {
            [1] = 10036605
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(A faint cut crosses the soldier's wrist — fine, clean, unmistakably made by a blade. But in this version of the story, only the legionaries and the \"monster\" should've left their marks.)"
        },
        [10036605] = {
          ContentTC = "（毀掉劍痕。）",
          DialogueId = 10036605,
          GUID = "1920226B",
          NextDialogue = 10036606,
          Subtitle = "(Erase the blade cut)"
        },
        [10036606] = {
          ContentTC = "（那道劍傷足夠細，所以傷口的形狀可以輕易被破壞掉。朱紅的露滴滾落，<H>就像從來沒有一位使劍的狩月人來過這裡一樣。</>）",
          DialogueId = 10036606,
          GUID = "1920226C",
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(The cut is fine enough that a simple smear disrupts the shape. Crimson beads well up and roll down — as if no sword-wielding Phoxhunter had ever set foot here.)"
        },
        [10036607] = {
          ContentTC = "（士兵的身上有大面積焦痂，稍加辨認便能看出遭受過電擊。但<H>這個舞台最終留下的，應該只有軍團與「怪物」戰鬥的痕跡才對。</>）",
          DialogueId = 10036607,
          GUID = "1920226D",
          NextOptions = {
            [1] = 10036608
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(The soldier's body is marred with scorched welts — telltale signs of electrical burns. But in this version of the story, only the legionaries and the \"monster\" should've left their marks.)"
        },
        [10036608] = {
          ContentTC = "（扯過電纜。）",
          DialogueId = 10036608,
          GUID = "1920226E",
          NextDialogue = 10036609,
          Subtitle = "(Pull the cable)"
        },
        [10036609] = {
          ContentTC = "（落地燈碎裂，垂落的電纜被攔腰扯斷。電火花跳起快活的小步舞曲，<H>就像從來沒有一位能操縱電流的軍官來過這裡一樣。</>啊，可惜了，那真的是一盞很漂亮的落地燈。）",
          DialogueId = 10036609,
          GUID = "1920226F",
          NextDialogue = 10036610,
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(The floor lamp shatters. A loose cable swings down, severed clean through. Sparks rise in a cheerful little dance — as if no lightning-wielding officer had ever set foot here. A pity, though... it was such a lovely lamp.)"
        },
        [10036610] = {
          ContentTC = "（現在，布景已經完成了：十三軍團一路追查到蓋雷亞劇院，<H>先頭小隊雖然疏散了群眾，卻不幸命喪「怪物」之手。</>隨後趕來的大部隊則成功擊斃「怪物」，為卡戎狩獵一案畫上了休止符——這才是卡戎狩獵最恰如其分的謝幕。）",
          DialogueId = 10036610,
          GUID = "19202270",
          SpeakNpcName = "UI_Npc_Name_Pangbai",
          Subtitle = "(And now, the stage is set: the 13th Legion pursued the creature to the Galea Theatre. The advance team evacuated the civilians — but fell to the \"monster.\" The main force arrived soon after, struck it down, and brought the Charon Hunt to its proper close. A fitting curtain call... as if the tale had always been written this way."
        },
        [10036701] = {
          ContentTC = "神棄者同盟的人走了，布魯斯，你的傷怎麼樣……布魯斯，布魯斯！",
          DialogueId = 10036701,
          GUID = "19203642",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036702,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "The Forsakens guy is gone now... How are you feeling? Blues? Blues!",
          VoiceName = "voice/$Locale$/story/1003/100367/19203642"
        },
        [10036702] = {
          ContentTC = "這具軀體，也不是，鋼筋鐵骨……這帝國煉金院，技術，也不怎麼樣。",
          DialogueId = 10036702,
          GUID = "1920366C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Turns out this body... isn't exactly indestructible after all... So much for the Empire's so-called... alchemical genius.",
          VoiceName = "voice/$Locale$/story/1003/100367/1920366C"
        },
        [10036703] = {
          ContentTC = "姐姐的……槍法還挺準，比以前厲害……多了。看來，她已經可以，保護好，自己……咳！",
          DialogueId = 10036703,
          GUID = "19203696",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036704,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "My sister's aim... has gotten a lot better... Looks like she's capable... of protecting herself now... *coughs*",
          VoiceName = "voice/$Locale$/story/1003/100367/19203696"
        },
        [10036704] = {
          ContentTC = "現在是說這種話的時候嗎！",
          DialogueId = 10036704,
          GUID = "192036C0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Is that what's important right now!?",
          VoiceName = "voice/$Locale$/story/1003/100367/192036C0"
        },
        [10036705] = {
          ContentTC = "哈，哈。",
          DialogueId = 10036705,
          GUID = "192036EA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036706,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Huff... huff...",
          VoiceName = "voice/$Locale$/story/1003/100367/192036EA"
        },
        [10036706] = {
          ContentTC = "撐住，我帶你去找醫生！只要用武力逼迫他們，就算是我們這樣的怪物……",
          DialogueId = 10036706,
          GUID = "19203714",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036707,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Hang in there! I'll take you to a doctor! As long as we use force to coerce them, even monsters like us can—",
          VoiceName = "voice/$Locale$/story/1003/100367/19203714"
        },
        [10036707] = {
          ContentTC = "……沒必要，了",
          DialogueId = 10036707,
          GUID = "1920373E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036708,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "No need for... that.",
          VoiceName = "voice/$Locale$/story/1003/100367/1920373E"
        },
        [10036708] = {
          ContentTC = "你一直，不肯告訴我……但我能猜到，身上，洗不掉的血……是……哪來的……",
          DialogueId = 10036708,
          GUID = "19203768",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036709,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "You refused... to tell me... about all the bloodstains on me... that won't wash off... but I've figured it out...",
          VoiceName = "voice/$Locale$/story/1003/100367/19203768"
        },
        [10036709] = {
          ContentTC = "這樣，死掉，對大家，很好……",
          DialogueId = 10036709,
          GUID = "19203792",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036710,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "It's a good thing... to let me die here... at least it'll bring peace... to everyone...",
          VoiceName = "voice/$Locale$/story/1003/100367/19203792"
        },
        [10036710] = {
          ContentTC = "混蛋，別大家大家的，你自己呢？你忘了自己怎麼說的？等逃出來，我們會搭起舞台，我會教你表演，讓所有親朋好友來看我們的演出！",
          DialogueId = 10036710,
          GUID = "192037BC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036711,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Peace to everyone? What about you!? You idiot! You said after we got out, we'd set up a stage of our own! I'd teach you how to perform, and we'd invite everyone we know to watch our show!",
          VoiceName = "voice/$Locale$/story/1003/100367/192037BC"
        },
        [10036711] = {
          ContentTC = "抱歉……要食言了……",
          DialogueId = 10036711,
          GUID = "192037E6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036712,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Sorry... looks like... I won't be able to keep that promise...",
          VoiceName = "voice/$Locale$/story/1003/100367/192037E6"
        },
        [10036712] = {
          ContentTC = "不……對了，姐姐、你的姐姐！你說過最想念的就是姐姐，你還沒有和她相認！",
          DialogueId = 10036712,
          GUID = "19203810",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036713,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "No... Oh! What about your sister!? You said she's the one you missed the most! You haven't even reunited with her yet!",
          VoiceName = "voice/$Locale$/story/1003/100367/19203810"
        },
        [10036713] = {
          ContentTC = "……我是個，懦夫……嘴上說著，想要與親人團聚的，漂亮話。可，真的見到她，除了……落荒而逃……什麼都，做不了……",
          DialogueId = 10036713,
          GUID = "1920383A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...I'm a coward... I said I wanted to see her again... but when I finally did... I ran like a coward. There was nothing... I could do...",
          VoiceName = "voice/$Locale$/story/1003/100367/1920383A"
        },
        [10036714] = {
          ContentTC = "我、我有個……請求。",
          DialogueId = 10036714,
          GUID = "19203864",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036715,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I... I have one last request.",
          VoiceName = "voice/$Locale$/story/1003/100367/19203864"
        },
        [10036715] = {
          ContentTC = "這條鏈子是……信物。找到姐姐，告訴她……第六軍團……真相……不要，她……也被騙……",
          DialogueId = 10036715,
          GUID = "1920388E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036716,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "This chain... it's a keepsake. Find my sister. Tell her the truth... about the 6th Legion... Don't let her fall into their trap... like I did...",
          VoiceName = "voice/$Locale$/story/1003/100367/1920388E"
        },
        [10036716] = {
          ContentTC = "還有，<H>絕對，別讓她，知道……我死在，她手上。</>她會，受不住……",
          DialogueId = 10036716,
          GUID = "192038B8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036717,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "And... don't ever let her know... that I died... by her hand. She wouldn't... be able to bear it...",
          VoiceName = "voice/$Locale$/story/1003/100367/192038B8"
        },
        [10036717] = {
          ContentTC = "拜託……你了。",
          DialogueId = 10036717,
          GUID = "192038E2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036718,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Please... Promise me...",
          VoiceName = "voice/$Locale$/story/1003/100367/192038E2"
        },
        [10036718] = {
          ContentTC = "布鲁斯……！！",
          DialogueId = 10036718,
          GUID = "1920390C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036719,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Blues...!!",
          VoiceName = "voice/$Locale$/story/1003/100367/1920390C"
        },
        [10036719] = {
          ContentTC = "我答應你。",
          DialogueId = 10036719,
          GUID = "19203936",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036720,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "I promise.",
          VoiceName = "voice/$Locale$/story/1003/100367/19203936"
        },
        [10036720] = {
          ContentTC = "但是……用什麼辦法才能隱瞞你的死因，又讓她相信第六軍團的真相……",
          DialogueId = 10036720,
          GUID = "19203960",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036721,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "But... how do I tell her the truth without letting her know you're gone...?",
          VoiceName = "voice/$Locale$/story/1003/100367/19203960"
        },
        [10036721] = {
          ContentTC = "……我知道了。",
          DialogueId = 10036721,
          GUID = "1920398A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036722,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "...I get it.",
          VoiceName = "voice/$Locale$/story/1003/100367/1920398A"
        },
        [10036722] = {
          ContentTC = "<H>只要讓她以為「布魯斯」還活著，讓「布魯斯」告訴她一切</>……只要這樣……",
          DialogueId = 10036722,
          GUID = "192039B4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "I just need to make her believe Blues is still alive... Let \"Blues\" tell her everything. So...",
          VoiceName = "voice/$Locale$/story/1003/100367/192039B4"
        },
        [10036801] = {
          Camera = "-120.507812,969.508057,189.074219,0.000029,7.583572,-89.405365,40.000011,1878.839111,false,Manual,22.0",
          ContentTC = "布魯斯，我，做到了。謊言，揭穿了。",
          DialogueId = 10036801,
          FinalCamera = "-119.283203,850.649658,204.894531,0.000029,7.583572,-89.405365,40.000011,1878.839111,false,Manual,22.0",
          GUID = "192046AA",
          NextDialogue = 10036802,
