          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CD08"
        },
        [10037621] = {
          Camera = "-211.956055,-567.152344,364.128906,-0.000181,-21.989834,59.208832,40.0,649.933044,false,Manual,1.2",
          ContentTC = "……但是，想要成為真正的英雄，必須學會一件事。",
          DialogueId = 10037621,
          FacialId = {
            [1] = "100005:Angry01"
          },
          FinalCamera = "-195.979004,-576.428711,364.128906,-0.000181,-21.989807,61.208694,40.0,649.933044,false,Manual,1.2",
          GUID = "1920CD32",
          NextDialogue = 10037622,
          Scripts = "PlayAnimation{_delay{4},ActorId{100005},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 100005,
          Subtitle = "But, to become a true hero, there's something one must learn—",
          TalkActionId = {
            [1] = "100005:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CD32"
        },
        [10037622] = {
          Camera = "100.925293,-164.982422,149.0,-0.000183,-1.990174,89.601685,40.000011,649.933044,false,DoNotOverride,1.2",
          ContentTC = "——「捨棄」。",
          DialogueId = 10037622,
          FinalCamera = "100.925293,-164.982422,151.0,-0.000183,-1.990174,89.601685,40.000011,649.933044,false,DoNotOverride,1.2",
          GUID = "1920CD5C",
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-1244.209717,1588.063965,79.138672,-0.000183,2.009968,-51.59568,40.0,649.933044,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-1205.02417,1619.00708,79.138672,-0.000183,2.009968,-52.595875,40.0,649.933044,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100005,
          Subtitle = "\"Sacrifice.\"",
          TalkActionId = {
            [1] = "100005:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CD5C"
        },
        [10037623] = {
          Camera = "-150.297363,-249.219971,159.074219,0.000122,-4.598752,70.801865,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "沒事，我累了，腦袋疼，回去睡覺了。",
          DialogueId = 10037623,
          FacialId = {
            [1] = "100006:None",
            [2] = "200022:Sad02"
          },
          FinalCamera = "-156.845215,-247.038818,159.074219,0.000121,-4.598752,69.002029,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CD86",
          NextDialogue = 10037624,
          Scripts = "SetLocation{ActorId{200022},TargetPoint{\"Cp2Meetingstage01Point01\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200022,
          Subtitle = "Nothing, just tired. My head's killing me. I'm going back to get some sleep. Later.",
          TalkActionId = {
            [1] = "200022:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CD86"
        },
        [10037624] = {
          Camera = "-120.253906,83.223389,109.773438,0.000115,6.400085,-83.788696,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentTC = "哈哈，可算等到你說「休息」了。生命在於休息，你終於聽進去了上司的諄諄教誨，可喜可賀。",
          DialogueId = 10037624,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-130.150879,82.145996,109.773438,0.000111,6.400085,-81.788612,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CDB0",
          NextDialogue = 10037625,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-266.87085,324.740479,109.642578,0.000128,1.800076,-61.188812,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-258.637451,329.45874,109.642578,0.000129,1.800076,-63.189171,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100006,
          Subtitle = "Haha, finally! Been waiting for you to embrace the art of rest. Life lies in relaxation, you know. It's heartwarming to see my wisdom finally passed onto you. I'm so glad.",
          TalkActionId = {
            [1] = "100006:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CDB0"
        },
        [10037625] = {
          Camera = "-162.948242,-70.67041,200.082031,0.000205,-21.197163,70.186539,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentTC = "……等等，還有件事！",
          DialogueId = 10037625,
          FinalCamera = "-169.964355,-68.068848,200.082031,0.000204,-21.397152,67.386734,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CDDA",
          NextDialogue = 10037626,
          Scripts = "PlayAnimation{_delay{2},ActorId{200022},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 200022,
          Subtitle = "...Wait. There's one more thing.",
          TalkActionId = {
            [1] = "200022:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CDDA"
        },
        [10037626] = {
          Camera = "-287.92749,318.541992,203.541016,0.000088,-12.598714,-58.597427,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "怎麼還有！我的假期——",
          DialogueId = 10037626,
          FacialId = {
            [1] = "100006:Shock01"
          },
          FinalCamera = "-300.056641,311.028076,203.541016,0.000088,-12.598714,-56.597031,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CE04",
          NextDialogue = 10037627,
          SpeakNpcId = 100006,
          Subtitle = "There's more!? But I'm taking a vacation in—",
          TalkActionId = {
            [1] = "100006:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE04"
        },
        [10037627] = {
          Camera = "-222.233154,-129.037109,109.875,0.00011,3.401168,61.604328,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "閉嘴，沒你假期。",
          DialogueId = 10037627,
          FacialId = {
            [1] = "100006:None",
            [2] = "200022:Doubt01"
          },
          FinalCamera = "-230.056396,-124.807373,109.875,0.00011,3.401168,59.004227,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CE2E",
          NextDialogue = 10037628,
          SpeakNpcId = 200022,
          Subtitle = "Shut it. No vacation for you.",
          TalkActionId = {
            [1] = "200022:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE2E"
        },
        [10037628] = {
          Camera = "-826.894287,-529.407959,71.751953,0.000124,2.401009,35.401825,35.000008,938.158691,false,Manual,1.2",
          ContentTC = "我們在二號目標的身上發現了這個——這字條皺巴巴的，上面都是一些亂七八糟囉囉嗦嗦的字。",
          DialogueId = 10037628,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-817.608398,-544.271484,71.751953,0.000123,2.401009,37.001122,35.000008,938.158691,false,Manual,1.2",
          GUID = "1920CE58",
          NextDialogue = 10037629,
          SpeakNpcId = 200022,
          Subtitle = "We found this slip of paper on Target No. 2. It's all wrinkled, covered in rambling nonsense.",
          TalkActionId = {
            [1] = "200022:Give"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE58"
        },
        [10037629] = {
          Camera = "-136.407715,-217.994629,158.533203,0.000115,-3.999,74.389717,35.000008,938.158691,false,DoNotOverride,1.2",
          ContentTC = "這些文縐縐的東西我也看不太懂，你研究下吧，別是還有沒發現的密信什麼的。",
          DialogueId = 10037629,
          FacialId = {
            [1] = "200022:Syouganai01"
          },
          FinalCamera = "-141.900879,-216.459717,158.533203,0.000116,-3.999,72.789558,35.000008,938.158691,false,DoNotOverride,1.2",
          GUID = "1920CE82",
          NextDialogue = 10037630,
          SpeakNpcId = 200022,
          Subtitle = "These flowery words don't make sense to me. You look into it. Could be a hidden message we've missed.",
          TalkActionId = {
            [1] = "200022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE82"
        },
        [10037630] = {
          Camera = "-117.756836,88.672852,108.013672,0.000201,6.600804,-84.378052,35.0,938.158691,false,DoNotOverride,1.2",
          ContentTC = "行吧，我看看……「無言的白雪啊，蒼穹的女兒」……",
          DialogueId = 10037630,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-131.584961,87.343506,108.013672,0.000202,6.600804,-81.177704,35.0,938.158691,false,DoNotOverride,1.2",
          GUID = "1920CEAC",
          NextDialogue = 10037631,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-96.188477,-92.051025,148.0,0.000183,0.401035,-92.385239,40.000011,938.158691,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-93.185547,-92.176514,148.0,0.000183,0.201033,-92.385246,40.000011,938.158691,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100006,
          Subtitle = "Fine, let me see... \"The silent silent snow, child of the sky...\"",
          TalkActionId = {
            [1] = "100006:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CEAC"
        },
        [10037631] = {
          Camera = "-155.327637,225.379883,147.050781,0.000117,-3.19924,-74.194122,35.000008,938.158691,false,DoNotOverride,1.2",
          ContentTC = "這好像是，呃，一首詩？還是什麼歌的歌詞？",
          DialogueId = 10037631,
          FinalCamera = "-164.984863,223.086426,147.050781,0.000122,-3.19924,-71.59314,35.000008,938.158691,false,DoNotOverride,1.2",
          GUID = "1920CED6",
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-737.840088,1471.36792,204.878906,0.000128,-1.998384,-68.190025,35.000008,1775.077148,false,Manual,1.527685\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-791.514893,1605.49646,209.912109,0.000128,-1.998384,-68.190025,35.000008,1775.077148,false,Manual,1.527685\"},duration{5}}}",
          SpeakNpcId = 100006,
          Subtitle = "Huh. Sounds like poetry. Or maybe lyrics to some old song?",
          TalkActionId = {
            [1] = "100006:Talk01_End",
            [2] = "200022:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CED6"
        },
        [10037701] = {
          ContentTC = "無言的白雪啊，蒼穹的女兒──",
          DialogueId = 10037701,
          GUID = "1920DA52",
          NextDialogue = 10037702,
          Subtitle = "The silent silent snow, child of the sky",
          VoiceName = "voice/$Locale$/story/1003/100377/1920DA52"
        },
        [10037702] = {
          ContentTC = "為那無名的孩子獻上祈禱吧！",
          DialogueId = 10037702,
          GUID = "1920DA53",
          NextDialogue = 10037703,
          Subtitle = "May the nameless child be bathed in pure light"
        },
        [10037703] = {
          ContentTC = "他已深眠於凍土之下。",
          DialogueId = 10037703,
          GUID = "1920DA54",
          NextDialogue = 10037704,
          Subtitle = "The crystal heart will keep shining through"
        },
        [10037704] = {
          ContentTC = "請記得他的歌謠，他最初的模樣，",
          DialogueId = 10037704,
          GUID = "1920DA55",
          NextDialogue = 10037705,
          Subtitle = "The gentle ballad too, and what we've been through"
        },
        [10037705] = {
          ContentTC = "還有那顆，璀璨無垢的心臟。",
          DialogueId = 10037705,
          GUID = "1920DA56",
          NextDialogue = 10037706,
          Subtitle = "Beneath the snowfield you will find your own peace"
        },
        [10037706] = {
          ContentTC = "——《致無名者的安魂曲》",
          DialogueId = 10037706,
          GUID = "1920DA57",
          Subtitle = "——Requiem for the Nameless"
        },
        [10037801] = {
          ContentTC = "黎瑟·費西爾，進去找到我在墻壁上留下的<H>刻痕</>，等待下一步指示。",
          DialogueId = 10037801,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1920EABA",
          NextDialogue = 10037802,
          SpeakNpcId = 100310,
          Subtitle = "Rhythm Fischer, find the carved mark I left on the wall. Then wait for further instructions.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EABA"
        },
        [10037802] = {
          ContentTC = "刻痕……刻痕……",
          DialogueId = 10037802,
          GUID = "1920EAE4",
          NextDialogue = 10037803,
          SpeakNpcId = 200002,
          Subtitle = "Carved mark... Carved mark...",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EAE4"
        },
        [10037803] = {
          ContentTC = "找到了，那邊墻壁上有刀劃過的痕跡。",
          DialogueId = 10037803,
          GUID = "1920EB0E",
          NextDialogue = 10037804,
          SpeakNpcId = 100304,
          Subtitle = "There it is. A knife mark over there.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB0E"
        },
        [10037804] = {
          ContentTC = "在哪在哪？",
          DialogueId = 10037804,
          GUID = "1920EB38",
          SpeakNpcId = 200002,
          Subtitle = "Where is it? Where is it?",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB38"
        },
        [10037805] = {
          ContentTC = "快到了，銀色和平廣場下方……嗯，就是前面的區域。",
          DialogueId = 10037805,
          GUID = "1920EB62",
          NextDialogue = 10037806,
          SpeakNpcId = 100304,
          Subtitle = "We should be close... Yeah — that's the tunnel right beneath Silverpeace Square.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB62"
        },
        [10037806] = {
          ContentTC = "前面嗎？可是過道都被淹了誒……對了！垃圾桶公主說過可以用<H>水閥</>！",
          DialogueId = 10037806,
          GUID = "1920EB8C",
          NextDialogue = 10037807,
          SpeakNpcId = 200002,
          Subtitle = "This is it? But the whole passage is flooded... Oh! Princess Rubbish Bin said something about a water valve!",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB8C"
        },
        [10037807] = {
          ContentTC = "嗯，啟動那邊的<H>水閥</>排乾淨水再過去吧。",
          DialogueId = 10037807,
          GUID = "1920EBB6",
          SpeakNpcId = 100304,
          Subtitle = "Right. Let's activate that valve to drain the water — then we move on.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBB6"
        },
        [10037808] = {
          ContentTC = "有穢獸，大家小心。",
          DialogueId = 10037808,
          GUID = "1920EBE0",
          NextDialogue = 10037809,
          SpeakNpcId = 100304,
          Subtitle = "Filthoids coming. Watch out, everyone.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBE0"
        },
        [10037809] = {
          ContentTC = "不是說帝國這些年很注重地下設施，怎麼下水道隨便敲一竿子，都能敲出來穢獸啊。",
          DialogueId = 10037809,
          GUID = "1920EC0A",
          NextDialogue = 10037810,
          SpeakNpcId = 200021,
          Subtitle = "All that big talk about tightening up the underground facilities, and a quick whack on a sewer pipe is kicking out more Filthoids than wastewater? Wonderful!",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC0A"
        },
        [10037810] = {
          ContentTC = "抱歉……任務結束後我一定加強下水道的巡邏工作……",
          DialogueId = 10037810,
          GUID = "1920EC34",
          NextDialogue = 10037811,
          SpeakNpcId = 100304,
          Subtitle = "Sorry... I'll definitely be stepping up patrol of the sewers in the future...",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC34"
        },
        [10037811] = {
          ContentTC = "唉，我不是說你——算了算了，先趕緊解決它們吧。",
          DialogueId = 10037811,
          GUID = "1920EC5E",
          SpeakNpcId = 200021,
          Subtitle = "...I was not talking about you— Ugh, forget it. Let's deal with these uninvited guests first.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC5E"
        },
        [10037812] = {
          ContentTC = "呼，好了。那邊還有另一個水閥。",
          DialogueId = 10037812,
          GUID = "1920EC88",
          SpeakNpcId = 100304,
          Subtitle = "Phew, one more valve to go. It's over there.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC88"
        },
        [10037813] = {
          ContentTC = "好了，現在可以進去了。",
          DialogueId = 10037813,
          GUID = "1920ECB2",
          SpeakNpcId = 100304,
          Subtitle = "All done. Now we can get in.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920ECB2"
        },
        [10037995] = {
          ContentTC = "無論他們讓我們做什麼，都別忘了，我們，不是怪物。",
          DialogueId = 10037995,
          GUID = "19210B11",
          SpeakNpcId = 100328,
          Subtitle = "Whatever they demand of us... remember this: we are not monsters.",
          VoiceName = "voice/$Locale$/story/1003/100379/19210B11"
        },
        [10037996] = {
          ContentTC = "克萊夫在風語渡口附近，去那裡找他吧。",
          DialogueId = 10037996,
          GUID = "19210B10",
          SpeakNpcId = 200022,
          Subtitle = "Clive should be near Windwake Pier. Head that way — you'll find him.",
          VoiceName = "voice/$Locale$/story/1003/100379/19210B10"
        },
        [10037997] = {
          ContentTC = "紙筆我來拜托醫生幫忙，印章就麻煩你們去取一趟了。抱歉……這身傷還是拖累大家了。",
          DialogueId = 10037997,
          GUID = "19210B0G",
          SpeakNpcId = 100304,
          Subtitle = "I asked the doctor for a pen and some paper — could you fetch the seal for me? Apologies... this injury's turned me into a burden.",
          VoiceName = "voice/$Locale$/story/1003/100379/19210B0G"
        },
        [10037998] = {
          DialogueId = 10037998,
          FinalCamera = "2935.045898,2450.00293,654.427734,0.000057,-7.99936,-141.003235,35.0,100000.0,false,Manual,22.0",
