          },
          Scripts = [[
PARA{
MoveTo{ActorId{100001},TargetPoint{"P101025Nvzhu1"},MoveSpeed{60}},
MoveTo{ActorId{200002},TargetPoint{"P101025Bai1"},MoveSpeed{60}},
