          SpeakNpcId = 200011,
          Subtitle = "Oh... right!",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A73F2"
        },
        [10102614] = {
          Camera = "73.365112,16.138672,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
          ContentTC = "誒，白剛才聽著好像是，這位大姐姐的錢包被搶走了？",
          DialogueId = 10102614,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "72.002441,21.418945,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
          GUID = "194A741C",
          LookAt = {
            [1] = "200006:n(200011)",
            [2] = "200003:n(100001)",
            [3] = "100001:n(200011)",
            [4] = "200002:n(200011)"
          },
          Scripts = "SetLocation{ActorId{200002},TargetPoint{\"P10102601Bai3\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Snow heard that someone swiped this lady's money.",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101026/194A741C"
        },
        [10102701] = {
          ContentTC = "那位小姐這麽著急，我也一起去幫忙吧。",
          DialogueId = 10102701,
          GUID = "194A8262",
          NextDialogue = 10102702,
          SpeakNpcId = 200006,
          Subtitle = "She seems quite distressed; I can lend a hand too so we can get it back sooner.",
          VoiceName = "voice/$Locale$/story/1002/101027/194A8262"
        },
        [10102702] = {
          ContentTC = "不要插手，這是對我們未來狩月人的簡單考驗。要是沒有吃這碗飯的實力，做狩月人只會害了自己。",
          DialogueId = 10102702,
          GUID = "194A828C",
          NextDialogue = 10102703,
          SpeakNpcId = 200003,
          Subtitle = "No, this is a simple test just for a prospective Phoxhunter. If you don't have the chops for it, becoming a Phoxhunter would kill you.",
          TurnTo = {
            [1] = "2000061:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101027/194A828C"
        },
        [10102703] = {
          ContentTC = "好吧……",
          DialogueId = 10102703,
          GUID = "194A82B6",
          SpeakNpcId = 200006,
          Subtitle = "Okay...",
          VoiceName = "voice/$Locale$/story/1002/101027/194A82B6"
        },
        [10102801] = {
          ContentTC = "你、你真的願意幫我嗎！嗚……謝謝你，陌生人！",
          DialogueId = 10102801,
          GUID = "194A92CA",
          NextDialogue = 10102802,
          SpeakNpcId = 2000111,
          Subtitle = "You'd really help me out? Aww... thank you!",
          TurnTo = {
            [1] = "2000111:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101028/194A92CA"
        },
        [10102802] = {
          ContentTC = "小賊剛才是往西邊去了。但是冰湖城嘛，四通八達，誰知道他到底會竄到哪兒去。等下咱倆先找找線索！",
          DialogueId = 10102802,
          GUID = "194A92F4",
          SpeakNpcId = 2000111,
          Subtitle = "That scoundrel headed west. But you know, Icelake is a maze of streets, so I can't be sure where he might have gone. Let's look for some clues first!",
          VoiceName = "voice/$Locale$/story/1002/101028/194A92F4"
        },
        [10103001] = {
          ContentTC = "原來井蓋下面這麽大、這麽寬敞呀！還比上面暖和好多！就像一個秘密的小王國一樣。",
          DialogueId = 10103001,
          GUID = "194A92F5",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10103002,
          SpeakNpcId = 200011,
          Subtitle = "It's surprisingly roomy down here! And much warmer than above ground — like a secret little kingdom.",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F5"
        },
        [10103002] = {
          ContentTC = "把這些小動物請走，再把異味兒清理幹凈，搬個帳篷就能住人啦！",
          DialogueId = 10103002,
          GUID = "194A92F6",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10103003,
          SpeakNpcId = 200011,
          Subtitle = "Chase away those critters and get rid of the smell, then you could pitch a tent and practically live here!",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F6"
        },
        [10103003] = {
          ContentTC = "對啊對啊！而且，誒{nickname}你看，住在這兒還不用付房租！",
          DialogueId = 10103003,
          ExStoryInfo = "Player",
          GUID = "194A92F7",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10103004,
          SpeakNpcId = 200002,
          Subtitle = "Right! Whoo, , you should live here — it's rent-free!",
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F7"
        },
        [10103004] = {
          ContentTC = "讓我們一起來打跑這些傢伙，搶走他們的國土，我做魔王，冊封你為……",
          DialogueId = 10103004,
          ExStoryInfo = "Player",
          GUID = "194AB3EE",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10103005,
          SpeakNpcId = 200002,
          Subtitle = "Let's turf these critters out, seize their land, and I'll crown myself the Demon King! I'd appoint you as...",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB3EE"
        },
        [10103005] = {
          ContentTC = "「驍勇的獨目勇者，冷酷的冰湖之主，第一代下水道公爵」！",
          DialogueId = 10103005,
          GUID = "194AB418",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103006,
          SpeakNpcId = 200002,
          Subtitle = "\"The Valiant Cyclopean Warrior, the Cold Lord of Icelake, the Inaugural Duke of the Sewers\"!",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB418"
        },
        [10103006] = {
          ContentTC = "（好像稱呼有點太長了，縮短一些比較好……）",
          DialogueId = 10103006,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194AB419",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103007,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(That title's a bit of a mouthful and could use a polish...)",
          VoiceName = "voice/$Locale$/story/1002/101030/194AB419"
        },
        [10103007] = {
          ContentTC = "（等等，怎麽我真的在一本正經思考了。）",
          DialogueId = 10103007,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194AB46C",
          GuideFacialId = "Shock",
