          SpeakNpcId = 200011,
          Subtitle = "Hmm, that was weird... Why did Ms Camilla suddenly freak out like that? She's usually so cool-headed.",
          TalkActionId = {
            [1] = "200011:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF569"
        },
        [10103502] = {
          Camera = "-135.308594,-179.244141,147.530365,0.000016,-7.258025,49.643944,35.000008,1.5,false,Disable,1.2",
          ContentTC = "那個小偷也是，突然就嚇得渾身哆嗦，原來治安署是這麽恐怖的地方嗎！",
          DialogueId = 10103502,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "194AF570",
          NextDialogue = 10103503,
          SpeakNpcId = 200002,
          Subtitle = "And that thief too — shaking like a leaf all of a sudden. Is the Security Bureau really that scary?",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "200011:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF570"
        },
        [10103503] = {
          Camera = "-37.669922,74.164062,136.618378,0.000016,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
          ContentTC = "看來他應該會被好好教訓一番了。唉，我本來只是想追回錢袋，再敲他幾下腦殼就行，沒想鬧那麽大的……",
          DialogueId = 10103503,
          FacialId = {
            [1] = "200011:Unhappy01"
          },
          GUID = "194AF571",
          NextDialogue = 10103504,
          SpeakNpcId = 200011,
          Subtitle = "Looks like he's in for a tough time. All I wanted was to get my money bag back and maybe teach him a lesson — I didn't expect all this.",
          TalkActionId = {
            [1] = "200002:Shock_End",
            [2] = "200011:SpecialHoldHelmet_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF571"
        },
        [10103504] = {
          Camera = "-165.324219,313.250977,140.767822,0.000018,-4.657957,-60.556728,41.027447,1.5,false,Disable,1.2",
          ContentTC = "啊，差點忘了，報酬報酬！給你！",
          DialogueId = 10103504,
          FacialId = {
            [1] = "200011:Smile01"
          },
          GUID = "194AF572",
          NextDialogue = 10103505,
          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Give\"},Duration{1}}",
          SpeakNpcId = 200011,
          Subtitle = "Oh, I almost forgot — here's your reward!",
          TalkActionId = {
            [1] = "200011:SpecialHoldHelmet_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF572"
        },
        [10103505] = {
          ContentTC = "嘿嘿，真是謝謝你啦，我的大恩人，我的異父異母的{性别:親兄弟|親姐妹}！",
          DialogueId = 10103505,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200011:Smile02"
          },
          GUID = "194AF573",
          NextDialogue = 10103506,
          SpeakNpcId = 200011,
          Subtitle = "Thank you so much! You're a lifesaver, my {性别:brother from another mother|sister from another mister}!",
          TalkActionId = {
            [1] = "200011:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF573"
        },
        [10103506] = {
          Camera = "-33.322266,90.494141,136.335449,0.000018,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
          ContentTC = "我先趕緊回去把銅幣分給大伙兒了。我呀，平常就在冰湖城到處「進貨」，你跟貧民窟的人報我瑪爾潔的名號，準能找到我。",
          DialogueId = 10103506,
          GUID = "194AF574",
          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 200011,
          Subtitle = "Well, I gotta go divvy up these coins. I usually do my \"shopping\" all over Icelake. If you need me, just drop my name in the slums, and they'll help you find me.",
          TalkActionId = {
            [1] = "200011:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF574"
        },
        [10103507] = {
          ContentTC = "小僕從，我們也快點回去找卡蜜拉吧！",
          DialogueId = 10103507,
          GUID = "194AF575",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Alright, let's go find Camilla, little minion!",
          VoiceName = "voice/$Locale$/story/1002/101034/194AF575"
        },
        [10103601] = {
          ContentTC = "「水仙平原」就在南邊。",
          DialogueId = 10103601,
          Duration = 3,
          GUID = "194B160A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10103602,
          SpeakNpcId = 200006,
          Subtitle = "The Asphodel is just to the south.",
          VoiceName = "voice/$Locale$/story/1002/101036/194B160A"
        },
        [10103602] = {
          ContentTC = "快來快來！白在廣場等你們！",
          DialogueId = 10103602,
          Duration = 4,
          GUID = "194B1634",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Come on! Snow will be waiting for you in the square!",
          VoiceName = "voice/$Locale$/story/1002/101036/194B1634"
        },
        [10103701] = {
          ContentTC = "這邊，狩月人所有的委托都在這邊的告示板上！",
          DialogueId = 10103701,
          Duration = 3,
          GUID = "194B2672",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Over here, all the commissions for Phoxhunters are listed on this board!",
          VoiceName = "voice/$Locale$/story/1002/101037/194B2672"
        },
        [10103801] = {
          Camera = "172.692993,-479.681641,69.009766,0.001296,4.999999,95.0,25.000006,357.352783,false,DoNotOverride,1.2",
          ContentTC = "喲，這不是白嘛，又在給狩月人幫忙？是不是又抓了幾百個大盜，挫敗了十幾起驚天大陰謀呀？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103801,
          FinalCamera = "158.725586,-480.897461,69.009766,0.001297,4.999999,97.500046,25.000006,357.352783,false,DoNotOverride,1.2",
          GUID = "194B36DA",
          LookAt = {
            [1] = "200002:n(200065)",
            [2] = "200065:n(200002)"
          },
          NextDialogue = 10103802,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201005
          },
          Scripts = [[
