          SpeakNpcId = 200065,
          Subtitle = "Ah, hi Snow! Lending a hand to Phoxhunters again? What is it this time — Nabbed a few hundred bandits, thwarted a dozen dastardly schemes?",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101038/194B36DA"
        },
        [10103802] = {
          Camera = "297.337158,171.632812,207.998047,0.001337,-21.800159,-149.094604,40.000011,379.447693,false,Manual,2.0",
          ContentTC = "今天我比較低調，只抓了一個小偷。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103802,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "194B3704",
          NextDialogue = 10103803,
          Scripts = [[
