},
LookAt{_delay{3.3},LookAtDescription{"200065:n(100001)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "I've never fibbed before! Come here, my little minion. This is Mr Wells, the most hard-working Phoxhunter around here.",
          TalkActionId = {
            [1] = "200065:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B3758"
        },
        [10103805] = {
