            [2] = "200011:n(200002)"
          },
          NextDialogue = 10103815,
          SpeakNpcId = 200002,
          Subtitle = "It was a piece of cake! My little minion and I gave that bad thief a good thrashing — he ended up crying and begging for mercy!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B38D3"
