}]],
          SpeakNpcId = 200065,
          Subtitle = "You serious? Kid, I'm not joking — this is no child's play!",
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A20"
        },
        [10104017] = {
          ContentTC = "謝謝你，我明白的。但是，卡蜜拉女士……",
          DialogueId = 10104017,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "194B5A4A",
          LookAt = {
            [1] = "100001:n(200065)"
          },
          NextDialogue = 10104018,
          Scripts = [[
PARA{
