        },
        [10104402] = {
          Camera = "214.22168,-132.881836,141.021973,0.000037,-1.199094,134.199219,35.0,230.308487,false,Manual,4.0",
          ContentTC = "賽琪？你怎麽跟上來了？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104402,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "194B9974",
          NextDialogue = 10104403,
          SpeakNpcId = 100001,
          Subtitle = "Psyche? What are you doing here?",
          TalkActionId = {
            [1] = "100001:Explain01_Start",
            [2] = "200002:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/101044/194B9974"
        },
        [10104403] = {
          Camera = "-188.268555,-20.25293,121.632812,0.000053,0.600934,2.599361,30.000002,316.328461,false,Manual,2.5",
          ContentTC = "我來幫你們帶路吧。我指的是……去格雷姆废礦的路。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104403,
          FacialId = {
            [1] = "200006:Happy02"
          },
          GUID = "194B999E",
          NextDialogue = 10104404,
          Scripts = "PARA{PlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{4}},SEQ{LookAt{LookAtDescription{\"200006:n(200002)\"}},LookAt{_delay{1},LookAtDescription{\"200006:n(100001)\"}}}}",
          SpeakNpcId = 200006,
          Subtitle = "I thought I'd help show you the way. I mean... to Glevum Pit.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101044/194B999E"
        },
        [10104404] = {
          Camera = "-271.905273,-43.04541,1110.167236,0.000141,-2.599092,-179.809708,25.0,813.98584,false,DoNotOverride,1.2",
          ContentTC = "白認識路！不過……嗯，如果有人一起的話更好了，畢竟這可是出城。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104404,
          FacialId = {
            [1] = "200002:Smile02"
          },
          FinalCamera = "-574.290039,-44.049316,1694.915527,0.000141,-2.599092,-179.809708,25.0,813.98584,false,DoNotOverride,1.2",
          GUID = "194B99C8",
          NextDialogue = 10104405,
          Scripts = [[
SEQ{
PARA{
PlayAnimation{ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}},
LookAt{LookAtDescription{"100001:n(200002)"}},
LookAt{LookAtDescription{"200002:n(200006)"}}
},
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Talk01_End"},Duration{0.1}},
LookAt{LookAtDescription{"100001:n(200006)"}},
LookAt{LookAtDescription{"200002:n(200006)"}},
PlayAnimation{ActorId{200002},AnimationId{"Agree"},Duration{1}}
}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Snow knows the way! But... it's nice to have some company, especially when we're heading out of town.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101044/194B99C8"
        },
        [10104405] = {
          Camera = "-80.464844,-28.455566,146.255371,0.000019,-2.199915,8.608652,35.000008,213.527512,false,Manual,4.0",
          ContentTC = "是啊，外鄉人在城外很容易迷路的。我看到你接了恩里克叔叔……我們的委托，所以我想我還是幫下忙為好。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104405,
          FacialId = {
            [1] = "200006:Smile02"
          },
          GUID = "194B99F2",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextOptions = {
            [1] = 101044051,
            [2] = 101044052
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200006},AnimationId{"AgreeHead"},Duration{2}},
PlayAnimation{ActorId{200006},AnimationId{"SpecialThink_Start"},Duration{2}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "Yeah, outsiders can easily lose their way out there. I saw you accepted Mr Henrik's... our request, so I thought I should help out.",
          VoiceName = "voice/$Locale$/story/1002/101044/194B99F2"
        },
        [10104406] = {
          Camera = "618.545898,-425.736328,165.672852,0.000053,-5.400419,148.00415,25.0,705.171997,false,DoNotOverride,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "剛好，我也想出來走走。我們出發吧？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104406,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "608.34375,-442.196289,165.672852,0.000051,-5.400419,149.999954,25.000002,715.606018,false,DoNotOverride,5.0",
          GUID = "194B9A1C",
          SpeakNpcId = 200006,
          Subtitle = "Actually, I was looking forward to a little walk myself, too. Shall we get going?",
          TalkActionId = {
            [1] = "200006:SpecialThink_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101044/194B9A1C"
        },
        [10104501] = {
          ContentTC = "呼……好久沒來城外了。",
          DialogueId = 10104501,
          Duration = 3,
          GUID = "194BA9B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104502,
          SpeakNpcId = 200006,
          Subtitle = "Whoo... It's been a while since I've stepped out of the city.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9B2"
        },
        [10104502] = {
          ContentTC = "落滿雪的針葉林，望不到邊的冰湖……高個子山峰被天空按住了腦袋……很喜歡。",
          DialogueId = 10104502,
          Duration = 3,
          GUID = "194BA9DC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104503,
          SpeakNpcId = 200006,
          Subtitle = "The snow-draped conifers, the boundless lake... mountains with their peaks in the clouds... I love all this.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9DC"
        },
        [10104503] = {
          ContentTC = "白還是更喜歡城裡面！如果郊外沒有那些到處巡邏的穢獸就好啦。",
          DialogueId = 10104503,
          Duration = 3,
          GUID = "194BAA06",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104504,
          SpeakNpcId = 200002,
          Subtitle = "Snow's more a city soul! If only the outskirts were free of those roaming Filthoids.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA06"
        },
        [10104504] = {
          ContentTC = "裡面更安全些。但是，我喜歡這裡的……空氣。",
          DialogueId = 10104504,
          Duration = 3,
          GUID = "194BAA30",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104505,
          SpeakNpcId = 200006,
          Subtitle = "It's safer inside, indeed. But there's something about the... air out here.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA30"
        },
        [10104505] = {
          ContentTC = "有區別嗎？我聞起來都差不多耶……",
          DialogueId = 10104505,
          Duration = 3,
          GUID = "194BAA5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104506,
          SpeakNpcId = 200002,
          Subtitle = "Is there a difference? All smells the same to me...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA5A"
        },
        [10104506] = {
          ContentTC = "嗯……冰湖城的空氣總是帶著腥味，帶著哭聲。",
          DialogueId = 10104506,
          Duration = 3,
          GUID = "194BAA84",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104507,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... The air in Icelake is always tinged with a scent of blood and echoes of weeping.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA84"
        },
        [10104507] = {
          ContentTC = "而這裡是森林的味道，浮冰的味道，還有駛向遠方的汽笛。這裡偶爾能看到雪白的鹿從林間竄出——",
          DialogueId = 10104507,
          Duration = 3,
          GUID = "194BAAAE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104508,
          SpeakNpcId = 200006,
          Subtitle = "Out here, it's the scent of the forest and drifting ice, and the distant sound of steam whistles. Occasionally, you might catch a glimpse of snow-white deer darting through the trees—",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAAE"
        },
        [10104508] = {
          ContentTC = "而冰湖城街道的角落竄出來的，是小偷、強盜……或者嗚咽的乞丐。",
          DialogueId = 10104508,
          Duration = 3,
          GUID = "194BAAD8",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104509,
          SpeakNpcId = 200006,
          Subtitle = "While around Icelake's alleys, what darts out are thieves or bandits... and sometimes just whimpering beggars.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAD8"
        },
        [10104509] = {
          ContentTC = "{nickname}，你呢？講講你的故鄉吧！那座海島是怎樣的？",
          DialogueId = 10104509,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB02",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104510,
          SpeakNpcId = 200006,
          Subtitle = "What about your hometown, ? Tell us about it! What's that island like?",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB02"
        },
        [10104510] = {
          ContentTC = "那裡的「空氣」是金色的砂礫，海岸的迷叠香……",
          DialogueId = 10104510,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104511,
          SpeakNpcId = 100001,
          Subtitle = "The \"air\" is golden gravel and beachside rosemary...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB2C"
        },
        [10104511] = {
          ContentTC = "是深夜朦朧的海霧，是我和貝……和家人每天眺望的巨大天之樹。",
          DialogueId = 10104511,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB56",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104512,
          SpeakNpcId = 100001,
          Subtitle = "It's misty sea fogs at midnight, and the massive Heaventree that Berr... my family and I used to gaze upon every day.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB56"
        },
        [10104512] = {
          ContentTC = "嗯……那如果你什麽時候回去故鄉，請代我向它們問候~",
          DialogueId = 10104512,
          Duration = 3,
          GUID = "194BAB80",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104513,
          SpeakNpcId = 200006,
          Subtitle = "Mmm... if you ever make it back to your homeland, please send them my regards.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB80"
        },
        [10104513] = {
          ContentTC = "……唔唔，你們兩個的話好難懂哦……",
          DialogueId = 10104513,
          Duration = 3,
          GUID = "194BABAA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104514,
          SpeakNpcId = 200002,
          Subtitle = "...Umm, you two are talking over my head...",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABAA"
        },
        [10104514] = {
          ContentTC = "等你再長大一些就明白啦。",
          DialogueId = 10104514,
          Duration = 3,
          GUID = "194BABD4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104515,
          SpeakNpcId = 200006,
          Subtitle = "You'll get it when you're older.",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABD4"
        },
        [10104515] = {
          ContentTC = "……不過，皎皎之民似乎是長不大的？",
          DialogueId = 10104515,
          Duration = 3,
          GUID = "194BABFE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...But then again, Lunos never really grow older, do you?",
          VoiceName = "voice/$Locale$/story/1002/101045/194BABFE"
        },
        [10104601] = {
