        },
        [10104705] = {
          ContentTC = "那我們在周圍轉轉，看看有沒有其它入口吧。",
          DialogueId = 10104705,
          Duration = 3,
          GUID = "194BCB2A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104706,
