        },
        [10104706] = {
          ContentTC = "白，你的腦袋痛嗎？我來幫你——",
          DialogueId = 10104706,
          Duration = 3,
          GUID = "194BCB54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104707,
          SpeakNpcId = 200006,
          Subtitle = "Snow, does your head hurt? Let me help you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB54"
        },
        [10104707] = {
          ContentTC = "……吹一下就不疼啦。",
          DialogueId = 10104707,
          Duration = 3,
          GUID = "194BCB7E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104708,
          SpeakNpcId = 200006,
          Subtitle = "...There, a little puff to ease the pain.",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCB7E"
        },
        [10104708] = {
          ContentTC = "嗚嗚……你真是個大好人。等本魔王大人徹底占領這裡，就封你——",
          DialogueId = 10104708,
          Duration = 3,
          GUID = "194BCBA8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104709,
          SpeakNpcId = 200002,
          Subtitle = "Awww... you're so nice. When this Demon King conquers this place, I'll appoint you—",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBA8"
        },
        [10104709] = {
          ContentTC = "「溫柔的綠衣法師，睿智的月石主宰，第一代格雷姆礦場大公」！",
          DialogueId = 10104709,
          Duration = 3,
          GUID = "194BCBD2",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104710,
          SpeakNpcId = 200002,
          Subtitle = "\"The Gentle Green-Cloaked Mage, the Wise Master of Phoxene, the Inaugural Grand Duke of Glevum Pit\"!",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBD2"
        },
        [10104710] = {
          ContentTC = "（之前我是下水道公爵……大公是不是比公爵還要高級一點的爵位啊？）",
          DialogueId = 10104710,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCBFC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104711,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I was the Duke of the Sewers... Is a grand duke a higher rank than a duke?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCBFC"
        },
        [10104711] = {
          ContentTC = "（為什麽賽琪的爵位比我高？等等，怎麽我又在一本正經思考了。）",
          DialogueId = 10104711,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BCC26",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(How come Psyche gets a higher title than me? Hold on, why am I seriously mulling this over again?)",
          VoiceName = "voice/$Locale$/story/1002/101047/194BCC26"
        },
        [10104801] = {
          ContentTC = "「在魔王大人白的指引下，剛剛從遠方抵達冰湖城的小僕從，只一天功夫就成為了出色的『狩月人』。」",
          DialogueId = 10104801,
          GUID = "194BDAEA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104802,
          SpeakNpcId = 200002,
          Subtitle = "\"Guided by Snow the Demon King, the little minion who just arrived in Icelake from afar has become a brilliant Phoxhunter in a mere day.\"",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDAEA"
        },
        [10104802] = {
          ContentTC = "本魔王的傳說又可以添上新的篇章啦。",
          DialogueId = 10104802,
          GUID = "194BDB14",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104803,
          SpeakNpcId = 200002,
          Subtitle = "A new chapter in the legend of this Demon King!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB14"
        },
        [10104803] = {
          ContentTC = "「狩月人」這個名字還挺特別的……狩獵月亮？",
          DialogueId = 10104803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDB3E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104804,
          SpeakNpcId = 100001,
          Subtitle = "\"Phoxhunter\" is a cool name... Do they all hunt something called Phox?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB3E"
        },
        [10104804] = {
          ContentTC = "錯了錯了！狩月人這個名字和月亮沒什麽關系，它最早的意思其實是——「月石獵人」！",
          DialogueId = 10104804,
          GUID = "194BDB68",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104805,
          SpeakNpcId = 200002,
          Subtitle = "Nah! Phoxhunters nowadays are actually bounty hunters. It has something to do with Phoxene a long time ago.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB68"
        },
        [10104805] = {
          ContentTC = "嗯，我聽說這個職業就是起源於冰湖城。",
          DialogueId = 10104805,
          GUID = "194BDB92",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104806,
          SpeakNpcId = 200006,
          Subtitle = "Right, I heard it used to refer to a profession that originated right here in Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDB92"
        },
        [10104806] = {
          ContentTC = "似乎是因為，維德弗尼爾山一帶有豐富的天之樹礦脈，上面的月石可以賣出好價錢……",
          DialogueId = 10104806,
          GUID = "194BDBBC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104807,
          SpeakNpcId = 200006,
          Subtitle = "It seemed to all start with the rich Heaventree veins in the Vidofnir Mountains, and the Phoxene on them could be sold for a good price...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBBC"
        },
        [10104807] = {
          ContentTC = "沒錯！所以很久很久以前，就有很多人冒險接受委托去采月石了。",
          DialogueId = 10104807,
          GUID = "194BDBE6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104808,
          SpeakNpcId = 200002,
          Subtitle = "Exactly! So, a long, long time ago, many people braved the risks of collecting Phoxene for money.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDBE6"
        },
        [10104808] = {
          ContentTC = "不過大商人和帝國先後接管了這附近的礦區，普通人就沒什麽機會碰到月石了……",
          DialogueId = 10104808,
          GUID = "194BDC10",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104815,
          SpeakNpcId = 200006,
          Subtitle = "But then the big merchants and the Empire took over the mines around here, and ordinary folk hardly had a chance with Phoxene anymore...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC10"
        },
        [10104809] = {
          ContentTC = "不過靠接取委托為生的狩月人，還是作為一種特色職業保留了下來，只是委托的種類呢就五花八門啦。",
          DialogueId = 10104809,
          GUID = "194BDC3A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104810,
          SpeakNpcId = 200002,
          Subtitle = "While Phoxhunters, who lived off commissions, remained as a profession. It's just that the types of commissions changed a lot since then.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC3A"
        },
        [10104810] = {
          ContentTC = "大到從穢獸的魔爪下保護城市，小到從狗嘴裡搶剛出爐的面包……",
          DialogueId = 10104810,
          GUID = "194BDC64",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104811,
          SpeakNpcId = 200002,
          Subtitle = "There are big ones like protecting the city from the claws of Filthoids, and little ones like getting freshly baked bread back from a dog's mouth...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC64"
        },
        [10104811] = {
          ContentTC = "和狗搶面包？",
          DialogueId = 10104811,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BDC8E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104812,
          SpeakNpcId = 100001,
          Subtitle = "Fighting dogs for bread?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC8E"
        },
        [10104812] = {
          ContentTC = "還有一些更可怕的，比如讓自己討厭的傢伙再也不會出現……",
          DialogueId = 10104812,
          GUID = "194BDCB8",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104813,
          SpeakNpcId = 200002,
          Subtitle = "And some even more terrifying commissions like making sure a certain someone you don't like never shows up again...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCB8"
        },
        [10104813] = {
          ContentTC = "可是，跑一趟水仙平原的功夫，面包不是早就被狗吃掉了嗎？",
          DialogueId = 10104813,
          GUID = "194BDCE2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104814,
          SpeakNpcId = 200006,
          Subtitle = "But by the time you make a trip down to The Asphodel, wouldn't the bread have been gobbled up by the dog already?",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDCE2"
        },
        [10104814] = {
          ContentTC = "你們兩個能不能別再關心狗啦！",
          DialogueId = 10104814,
          GUID = "194BDD0C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "You're both missing the point here!",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDD0C"
        },
        [10104815] = {
          ContentTC = "再後來，這附近的礦脈也漸漸枯竭掉了，比如現在這座格雷姆廢礦……",
          DialogueId = 10104815,
          GUID = "194BDC11",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104816,
          SpeakNpcId = 200006,
          Subtitle = "After that, the local veins gradually ran dry, including this Glevum Pit...",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC11"
        },
        [10104816] = {
          ContentTC = "對呀，好可惜哦！否則小僕從就能靠賣月石大賺一筆了。",
          DialogueId = 10104816,
          GUID = "194BDC12",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104809,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, what a pity! Otherwise my little minion could have made a fortune selling Phoxene.",
          VoiceName = "voice/$Locale$/story/1002/101048/194BDC12"
        },
        [10104901] = {
          ContentTC = "沒事吧？",
          DialogueId = 10104901,
          ExStoryInfo = "Player",
          GUID = "194BEB52",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104902,
          SpeakNpcId = 100001,
          Subtitle = "Everything alright?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB52"
        },
        [10104902] = {
          ContentTC = "……！！",
          DialogueId = 10104902,
          GUID = "194BEB7C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104903,
          SpeakNpcId = 200006,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEB7C"
        },
        [10104903] = {
          ContentTC = "我剛剛突然看不清東西，沒想到竟然驚動了它……抱歉！",
          DialogueId = 10104903,
          GUID = "194BEBA6",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104904,
          SpeakNpcId = 200006,
          Subtitle = "I suddenly couldn't see clearly back there and ended up startling that monster... I'm so sorry!",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBA6"
        },
        [10104904] = {
          ContentTC = "現在好些了嗎？",
          DialogueId = 10104904,
          ExStoryInfo = "Player",
          GUID = "194BEBD0",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104905,
          SpeakNpcId = 100001,
          Subtitle = "Are you feeling better now?",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBD0"
        },
        [10104905] = {
          ContentTC = "嗯，沒問題了。",
          DialogueId = 10104905,
          GUID = "194BEBFA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10104906,
          SpeakNpcId = 200006,
          Subtitle = "Yeah, I think I'm fine now.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEBFA"
        },
        [10104906] = {
          ContentTC = "好。可以戰鬥的話，一起來對付這個大塊頭。",
          DialogueId = 10104906,
          ExStoryInfo = "Player",
          GUID = "194BEC24",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10104907,
          SpeakNpcId = 100001,
          Subtitle = "Great. If you're in the condition to fight, let's take on this monster together.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC24"
        },
        [10104907] = {
          ContentTC = "明白了！我會盡我所能支援你。",
          DialogueId = 10104907,
          GUID = "194BEC4E",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Sure! I'll do my best to support you.",
          VoiceName = "voice/$Locale$/story/1002/101049/194BEC4E"
        },
        [10105001] = {
          ContentTC = "我聽說多兇猛的野獸，只要能找到<H>弱點</>，就能打敗……",
          DialogueId = 10105001,
          GUID = "194BFBB9",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105002,
          SpeakNpcId = 200006,
          Subtitle = "They say even the fiercest beasts can be brought down by targeting their weaknesses...",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBB9"
        },
        [10105002] = {
          ContentTC = "穢獸一定也是這樣！我們冷靜下來……想辦法找找它的弱點吧。",
          DialogueId = 10105002,
          GUID = "194BFBBA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It must be the same with this Filthoid! Let's take a breath and find its weakness.",
          VoiceName = "voice/$Locale$/story/1002/101050/194BFBBA"
        },
        [10105101] = {
          ContentTC = "它變遲鈍了。{nickname}，<H>看起來像肩膀的位置</>就是它的弱點！",
          DialogueId = 10105101,
          ExStoryInfo = "Player",
          GUID = "194C0C4C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "It's slowing down. Looks like those shoulder-looking parts are its weakness!",
          VoiceName = "voice/$Locale$/story/1002/101051/194C0C4C"
        },
        [10105201] = {
          ContentTC = "它停下來了——趁這個機會！",
          DialogueId = 10105201,
          GUID = "194C1C8A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105202,
          SpeakNpcId = 200006,
          Subtitle = "It's stopped — now's our chance!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1C8A"
        },
        [10105202] = {
          ContentTC = "太好了……！",
          DialogueId = 10105202,
          GUID = "194C1CB4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Great...!",
          VoiceName = "voice/$Locale$/story/1002/101052/194C1CB4"
        },
        [10105301] = {
          ContentTC = "群星綺晶……真漂亮！難怪大家都喜歡。",
          DialogueId = 10105301,
          GUID = "194C2CF2",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "Crystallo of Stella... Look at its beauty! No wonder everyone wants a piece of it.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2CF2"
        },
        [10105302] = {
          ContentTC = "剛剛这邊好大的動靜——該不會是你們搞定了那個大傢伙？有兩下子嘛。",
          DialogueId = 10105302,
          GUID = "194C2D1C",
          SpeakNpcId = 200021,
          SpeakNpcName = "UI_Npc_Name_Man_17",
          Subtitle = "What a commotion I just heard. So it was you guys that took out that giant thing? Impressive.",
          VoiceName = "voice/$Locale$/story/1002/101053/194C2D1C"
        },
        [10105401] = {
          Camera = "-29.328125,-255.251953,164.21875,0.001081,-14.107393,94.226692,50.000008,544.145996,false,Manual,5.0",
          ContentTC = "奧特賽德？！你裝什麽傻，綺晶怎麽會在你手裡？是我家小僕從先——",
          DialogueId = 10105401,
          FacialId = {
            [1] = "200021:Smile02",
            [2] = "200002:Angry01"
          },
          FinalCamera = "-3.181641,-258.998047,197.030273,0.001091,-23.507626,104.626007,50.000008,311.108795,false,Manual,5.0",
          GUID = "194C3D5A",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "200006:n(200021)",
            [3] = "200061:n(200021)",
            [4] = "200002:n(200021)"
          },
          NextDialogue = 10105402,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201007,
            [4] = 201005,
            [5] = 301004,
            [6] = 406001,
            [7] = 303004,
            [8] = 201009
          },
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt01/0033_story_humour"}},
SEQ{
MoveTo{ActorId{200002},MoveSpeed{201},TargetPoint{"P101054_BaiMove1"}},
PlayAnimation{ActorId{200002},AnimationId{"Angry01_Start"},Duration{1}}
},
PARA{
MoveTo{ActorId{200021},MoveSpeed{30},TargetPoint{"P101054_AoteMove1"}},
LookAt{_delay{2.5},LookAtDescription{"200021:n(200002)"}}
},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Outsider!? How come the Crystallo is in your hands? It was my little minion who first—",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3D5A"
        },
        [10105402] = {
          Camera = "-72.519531,598.007812,133.294922,0.001335,-3.398285,-86.062561,30.0,755.136902,false,Manual,8.0",
          ContentTC = "它就在這兒，也沒長嘴喊誰「主人」。咱們狩月人幹活又不是排隊買麵包，哪有什麽先來後到。",
          DialogueId = 10105402,
          FacialId = {
            [1] = "200021:Blink"
          },
          FinalCamera = "-72.117188,591.96875,132.942383,0.001335,-3.398285,-86.062561,30.000002,717.98114,false,Manual,8.0",
          GUID = "194C3D84",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105403,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "It was just lying there with no one's name tag on it, wasn't it? Come on, in our line of work, there's no such thing as dibs.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3D84"
        },
        [10105403] = {
          Camera = "-86.927734,166.710938,157.334961,0.001335,-1.398345,-77.243843,50.0,303.408173,false,Manual,8.0",
          ContentTC = "你看著面生，新來的吧？這個道理總會有人教給你們，而我只是湊巧成為了你們的老師。要不，這顆綺晶就當交學費嘍？",
          DialogueId = 10105403,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "-85.015625,158.255859,157.125977,0.001334,-1.398345,-77.242615,50.0,303.408173,false,Manual,8.0",
          GUID = "194C3DAE",
          NextDialogue = 10105404,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200021:n(200061)"}},
SEQ{
TurnTo{_delay{1},TurnToDescription{"200021:n(200061)"}},
PlayAnimation{_delay{0.9},ActorId{200021},AnimationId{"Explain02_Start"},Duration{1.5}},
PlayAnimation{ActorId{200021},AnimationId{"Explain02_End"},Duration{1.2}},
},
SEQ{
CameraMoveTo{_delay{6.1},TargetPosition{"-130.212891,250.267578,144.216797,0.001347,-2.198085,79.348396,50.0,141.617371,false,Manual,8.0"},duration{0}},
CameraMoveTo{TargetPosition{"-127.666016,249.796875,144.216797,0.001348,-2.198085,78.94825,50.0,281.429199,false,Manual,5.0"},duration{4}},
},
}]],
          SpeakNpcId = 200021,
          Subtitle = "And you, you're new here, right? Someone has to teach you this lesson, and that someone just happened to be me today. Consider this Crystallo as tuition, shall we?",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101054/194C3DAE"
        },
        [10105404] = {
          Camera = "-82.755859,381.703125,133.121094,0.001257,1.800014,76.308632,50.000008,149.680878,false,Manual,12.0",
          ContentTC = "請還給我們！這顆綺晶對{nickname}、對我們都很重要！",
          DialogueId = 10105404,
          ExStoryInfo = "Player",
