        [10105433] = {
          Camera = "-201.890625,-594.59375,248.981445,0.001437,-12.600892,74.777382,50.0,368.690277,false,DoNotOverride,8.0",
          ContentTC = "唉，我說，你怎麽茫然得像只剛出殼的鵪鶉。恐怕旁邊那個白色小矮子都比你清楚。",
          DialogueId = 10105433,
          FinalCamera = "-201.890625,-594.59375,235.96582,0.001442,-12.000854,74.976952,50.0,368.690277,false,DoNotOverride,8.0",
          GUID = "194C41C8",
          NextDialogue = 10105434,
          Scripts = "PlayAnimation{_delay{1.2},ActorId{200021},AnimationId{\"Think_Start\"},Duration{1}},",
          SpeakNpcId = 200021,
          Subtitle = "Er, how come you are as clueless as a newly hatched quail? I bet even that little white button mushroom beside you is more informed.",
