          VoiceName = "voice/$Locale$/story/1002/101054/194C4246"
        },
        [10105437] = {
          Camera = "-353.777344,-47.939453,40.262695,0.001464,14.798335,24.421301,40.0,345.303528,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "簡單來說呢，「覺醒」是每個卡戎之民都會經歷的成長階段，大多都發生在成年前後。覺醒的瞬間，身上會發出很亮很亮的光——你肯定有印象的！",
          DialogueId = 10105437,
          ExStoryInfo = "Player",
          FinalCamera = "-360.898438,-30.494141,40.262695,0.001463,14.598415,21.022375,40.0,345.303528,false,Manual,2.8",
          GUID = "194C4270",
          LookAt = {
            [1] = "200061:n(200002)"
          },
          NextDialogue = 10105438,
          Scripts = [[
PARA{
PlayAnimation{_delay{5.2},ActorId{200002},AnimationId{"Explain01_Start"},Duration{4.8}},
PlayAnimation{_delay{10},ActorId{200002},AnimationId{"Explain01_End"},Duration{1.8}},
PlayAnimation{_delay{11.8},ActorId{200002},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Simply put, \"Awakening\" is a stage of growth every Charon goes through, usually around adulthood. During Awakening, their body emits a very bright light — you must have some memory of it!",
          TalkActionId = {
            [1] = "200061:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4270"
        },
        [10105438] = {
          Camera = "-101.375,79.515625,124.116211,0.001489,-19.999441,-142.798492,35.0,124.912491,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "在覺醒之後呢，有些卡戎會變強大許多——就像你們一樣，還會使用特別的魔法！他們就是「骸」。",
          DialogueId = 10105438,
          ExStoryInfo = "Player",
          FinalCamera = "-101.375,79.515625,124.116211,0.001489,-19.999441,-142.798492,37.0,124.912491,false,Manual,8.0",
          GUID = "194C429A",
          NextDialogue = 10105439,
          RelatedWikiId = {
            [1] = 303003
          },
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{5.1},TargetPosition{"-160.910156,18.623047,128.157227,0.00131,4.998906,46.797924,50.0,119.463776,false,Manual,8.0"},duration{0}},
CameraMoveTo{TargetPosition{"-160.910156,18.623047,128.157227,0.001311,5.198894,46.79784,52.0,119.463776,false,Manual,8.0"},duration{3}},
},
LookAt{_delay{0.5},LookAtDescription{"200006:n(200002)"}},
PlayAnimation{_delay{0.3},ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "After Awakening, some Charons become much stronger — like you, and gain the ability to use special magic! They are called \"Daimons.\"",
          TalkActionId = {
            [1] = "200002:Talk02_End",
            [2] = [[

200061:ScratchHead_End]]
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200006:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C429A"
        },
        [10105439] = {
          ContentTC = "（是那個時候……難怪我會覺得身體比以前輕盈多了，身上的傷口也是那時痊愈的吧。）",
          DialogueId = 10105439,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194C42C4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10105434.T_Story_Recall_10105434'",
          NextDialogue = 10105440,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 200061,
          Subtitle = "(It was that moment... No wonder I felt lighter than before, and my wounds must've healed around that time too.)",
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C42C4"
        },
        [10105440] = {
          ContentTC = "（……至於屬於我的魔法……是「和鳴」？）",
          DialogueId = 10105440,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
