PlayFacial{_delay{10},ActorId{100001},FacialId{"Ahaha02"}}
}]],
          SpeakNpcId = 200020,
          Subtitle = "I believe that lady who always used a lot of sugar was also a great magician. So in 's eyes, everything related to her was wonderful, even the unbearably sweet meals.",
          TalkActionId = {
            [1] = "200020:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC23E"
        },
        [10106212] = {
          Camera = "90.803986,-143.320312,134.382812,0.000123,0.599335,20.609505,35.000008,213.622009,false,Manual,7.38829",
          ContentTC = "好吧，菲娜說的都對。所以那個女孩兒現在在哪兒呢？要不你給她打包一份，讓她品嘗一下正常的甜食。",
          DialogueId = 10106212,
          FacialId = {
            [1] = "200021:Smile02"
          },
          GUID = "194CC268",
          NextDialogue = 10106213,
          Scripts = [[
PARA{
LookAt{_delay{2.5},LookAtDescription{"200021:n(100001)"}},
LookAt{_delay{3.5},LookAtDescription{"200020:n(100001)"}},
LookAt{_delay{3.5},LookAtDescription{"100001:n(200021)"}}
}
]],
          SpeakNpcId = 200021,
          Subtitle = "Okay, whatever Fina says. So where is that girl now? Perhaps you can bring her some cake, let her know what normal sweets taste like.",
          TalkActionId = {
            [1] = "200020:Explain02_End",
            [2] = "200021:AgreeHead"
