          },
          GUID = "194CC33A",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10106218,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100001:n(200021)"}},
TurnTo{TurnToDescription{"100001:n(200021)"}},
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "So, Outsider, I need money — for accommodation, information gathering, and some extra set aside in case I need to set off right away to find my family.",
          TalkActionId = {
            [1] = "200020:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101062/194CC33A"
        },
        [10106218] = {
          Camera = "228.775543,-141.707031,208.621094,0.000132,-21.591455,46.226685,45.0,103.803047,false,DoNotOverride,22.0",
          ContentTC = "……菲娜，準備休息吧。我和{nickname}還有其他事要聊——狩月人的雜事。",
          DialogueId = 10106218,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194CC364",
          LookAt = {
