LookAt{_delay{3},LookAtDescription{"200020:n(200021)"}}
}
]],
          SpeakNpcId = 200021,
          Subtitle = "...Time for bed, Fina. I have other matters to discuss with  — Phoxhunter stuff.",
          VoiceName = "voice/$Locale$/story/1002/101062/194CC364"
        },
        [10106219] = {
          Camera = "133.667862,436.431641,156.152344,0.000004,-4.200197,-71.19426,40.0,311.105316,false,DoNotOverride,1.670611",
