}]],
          SpeakNpcId = 200002,
          Subtitle = "Huh?! It's empty!",
          TalkActionId = {
            [1] = "200002:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B16"
        },
        [10108705] = {
          ContentTC = "（這是一個漂亮的雕花匣子，拿在手中沈甸甸的。但正如白所言，裡面空無一物。）",
          DialogueId = 10108705,
          DisableMouth = 1,
          GUID = "194E5B40",
          IsBlack = 1,
          NextDialogue = 10108706,
          Scripts = [[
PARA{
MoveTo{ActorId{100001},TargetPoint{"P10108706"},MoveSpeed{100},Visibility{"Show"}},
PlayNormalSound{EventPath{"event:/sfx/common/story/01/openbox"},PlayAs2D{true}}
}]],
          Subtitle = "(It's an intricately carved box, feeling surprisingly heavy in your hands. But as Snow said, it's empty inside.)",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B40"
        },
        [10108706] = {
          ContentTC = "（不，並不是空無一物！而是還殘留著什麽。那似乎是<H>一些濕滑的粉末</>——像未溶解的鹽粒，大部分已經散入水中，但還留了一小部分殘留在匣底。）",
          DialogueId = 10108706,
          DisableMouth = 1,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "194E5B6A",
          IsBlack = 1,
          LookAt = {
            [1] = "200002:p(P10108701)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10108707,
          Subtitle = "(Not completely empty, though! There's some sort of residue. Seems to be some slimy powder resembling salt. Most of it has dissolved into the water, but a small amount remains at the bottom of the box.)",
          TurnTo = {
            [1] = "100001:p(22)"
          },
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B6A"
        },
        [10108707] = {
          Camera = "98.9375,-272.827148,113.293945,0.001215,-14.999996,19.799967,30.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不……不是空的。它之前裝了東西，應該是……一種粉末。",
          DialogueId = 10108707,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "127.741211,-262.455078,99.574707,0.001215,-14.999996,19.799967,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194E5B94",
          NextDialogue = 10108708,
          SpeakNpcId = 100001,
          Subtitle = "No... it's not really empty. It previously held something... some sort of powder, perhaps.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101087/194E5B94"
