          SpeakNpcId = 100001,
          Subtitle = "I'm a stranger here, I can take you away — just like the day we went to the pit together.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101099/194F20C8"
