PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Give"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Once I find Berry, we can go to my hometown in the South, build little houses by the sea, and grow flowers around our homes. When spring comes and the flowers bloom, your eyes will heal.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101099/194F20F2"
        },
        [10109910] = {
          Camera = "91.175781,102.5,83.355469,0.000368,-1.19977,166.59407,50.0,175.542053,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "到時候天天大太陽曬著，說不定你還會懷念起冰湖城的雪……對了，可能會稍微打破一下你的夢想，你怕蟲子嗎，南方的蟲子會比這邊更大、更吵鬧。",
          DialogueId = 10109910,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "90.820312,101.058594,83.355469,0.000368,-1.19977,166.593994,50.0,175.542053,false,Manual,8.0",
          GUID = "194F211C",
          NextDialogue = 10109911,
          SpeakNpcId = 100001,
          Subtitle = "Every day, the sun will shine so brightly that you might even find yourself missing Icelake's snow... Oh, it might be a slight damper on your dream, but are you scared of bugs? The ones in the South are bigger and noisier.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 12,
          TurnTo = {
            [1] = "200027:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101099/194F211C"
        },
        [10109911] = {
