        [10110206] = {
          Camera = "74.595703,85.75,141.061523,0.000114,1.99839,-111.626167,35.0,100000.0,false,Disable,2.8",
          ContentTC = "停手停手，錢袋還你！我也是好幾天沒吃頓飽飯了，一時糊塗才……唉，我錯了我錯了！",
          DialogueId = 10110206,
          GUID = "194F51AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110206.T_Story_Recall_10110206'",
          NextDialogue = 10110207,
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Alright, alright, here's your money bag! I haven't had a decent meal in days, so I got desperate... I'm sorry!",
