          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC3DC"
        },
        [10110903] = {
          Camera = "64.572266,91.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          ContentTC = "賽琪會經常送花給我們，即使我們有的人已經不太聞得出花的香味，不太看得清花的輪廓，她還是會說，花可以給人帶來好運，堅持這麽做。",
          DialogueId = 10110903,
          FinalCamera = "64.572266,141.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          GUID = "194FC406",
          LookAt = {
            [1] = "200045:p(P10106801)"
          },
          NextDialogue = 10110904,
          SpeakNpcId = 200045,
          Subtitle = "Psyche often gave us flowers. Even though some of us can barely smell or see them clearly anymore, she kept doing it, saying flowers bring good luck.",
          TalkActionId = {
            [1] = "200045:Talk02_End"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC406"
        },
        [10110904] = {
          Camera = "-64.513672,-54.797607,154.447266,0.000147,-5.19662,21.383118,35.000008,170.88736,false,Manual,3.0",
          ContentTC = "……但當我想要回應的時候，已經來不及了。",
          DialogueId = 10110904,
          GUID = "194FC430",
          NextDialogue = 10110905,
          SpeakNpcId = 200045,
          Subtitle = "...But by the time I wanted to return her kindness, it was already too late.",
          TalkActionId = {
            [1] = "200045:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC430"
        },
        [10110905] = {
          Camera = "-230.103516,-78.412262,153.914062,0.000093,-5.797054,21.191561,35.000008,351.556366,false,Manual,4.0",
          ContentTC = "請你們把這朵花帶給她吧，這是她最喜歡的花。",
          DialogueId = 10110905,
          GUID = "194FC45A",
          LookAt = {
            [1] = "200045:n(100001)"
          },
          NextDialogue = 10110906,
          SpeakNpcId = 200045,
          Subtitle = "Please bring this flower to her. It's her favourite.",
          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC45A"
        },
        [10110906] = {
          Camera = "-7.181641,-249.865479,233.710938,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "請告訴她，修普諾斯之家的每個人，都在等著她……",
          DialogueId = 10110906,
          FinalCamera = "-4.027344,-306.261597,265.148438,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          GUID = "194FC484",
          NextDialogue = 10110907,
          SpeakNpcId = 200045,
          Subtitle = "And let her know that everyone at the Hypnos' House is waiting for her...",
          TalkActionId = {
            [1] = "200045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC484"
        },
        [10110907] = {
          Camera = "262.748047,-120.47818,147.644531,0.000102,-4.196898,153.589691,35.000008,434.590698,false,Manual,3.0",
          ContentTC = "我會的。我一定會救下她。",
          DialogueId = 10110907,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194FC4AE",
          NextDialogue = 10110908,
          SpeakNpcId = 100001,
          Subtitle = "I will. I'm going to do everything I can to save her.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC4AE"
        },
        [10110908] = {
          Camera = "51.148438,0.197876,149.753906,0.000102,-4.600037,179.58815,35.000011,140.0,false,DoNotOverride,22",
          ContentTC = "或者至少……阻止她做出違背自己心願的事。",
          DialogueId = 10110908,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "38.595703,0.288055,150.865234,0.000102,-4.600037,179.58815,35.000011,140.0,false,Manual,DoNotOverride,22",
          GUID = "194FC4D8",
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.1},TargetPosition{"-22.845703,1.761353,150.835938,0.000102,-4.600037,179.58815,35.000011,65.552429,false,DoNotOverride,22"},duration{0}},
CameraMoveTo{_delay{2.2},TargetPosition{"-27.648438,1.795654,150.466797,0.000102,-4.600037,179.58815,35.000011,65.552429,false,DoNotOverride,22"},duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Or at the very least... stop her from doing something she'd regret.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC4D8"
        },
        [10111001] = {
          ContentTC = "呼……呼……呼……",
          DialogueId = 10111001,
          Duration = 3,
          GUID = "194FD41A",
          SpeakNpcId = 200006,
          Subtitle = "Huff... Huff... Huff...",
