        },
        [10111002] = {
          ContentTC = "啊……",
          DialogueId = 10111002,
          Duration = 1,
          GUID = "194FD444",
          SpeakNpcId = 200006,
          Subtitle = "Ah... ",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD444"
        },
        [10111003] = {
          ContentTC = "對……不……",
          DialogueId = 10111003,
          Duration = 0.5,
          GUID = "194FD46E",
          SpeakNpcId = 200006,
          Subtitle = "I'm... sorr...",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD46E"
        },
        [10111004] = {
          ContentTC = "嗚呃——！！",
          DialogueId = 10111004,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "194FD498",
          SpeakNpcId = 100001,
          Subtitle = "Argh—!!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD498"
        },
        [10111005] = {
          ContentTC = "風太大了，我沒法靠近……！",
          DialogueId = 10111005,
          ExStoryInfo = "Player",
          GUID = "194FD499",
          SpeakNpcId = 100001,
          Subtitle = "The wind's too strong, can't get any closer...!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD499"
        },
        [10111006] = {
          ContentTC = "回來，危險！該死，這樣下去我們都會送命的……",
          DialogueId = 10111006,
          Duration = 4.5,
          GUID = "194FD500",
          SpeakNpcId = 200021,
          Subtitle = "It's dangerous! Stay back here! Damn it, we're all doomed if this keeps up...",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD500"
        },
        [10111007] = {
          ContentTC = "她失去理智了，應戰！",
          DialogueId = 10111007,
          Duration = 2.5,
          GUID = "194FD516",
          SpeakNpcId = 200021,
          Subtitle = "She's lost her mind... Be ready to fight!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD516"
        },
        [10111101] = {
          ContentTC = "賽琪，聽得見我的聲音嗎？",
          DialogueId = 10111101,
          ExStoryInfo = "Player",
          GUID = "194FE482",
          NextDialogue = 10111102,
          SpeakNpcId = 100001,
          Subtitle = "Psyche, can you hear me?",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE482"
        },
        [10111102] = {
          ContentTC = "回答我……",
          DialogueId = 10111102,
          ExStoryInfo = "Player",
          GUID = "194FE4AC",
          NextDialogue = 10111103,
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4AC"
        },
        [10111103] = {
          ContentTC = "你說過的，你明明還有那麽多想做的事……",
          DialogueId = 10111103,
          ExStoryInfo = "Player",
          GUID = "194FE4D6",
          NextDialogue = 10111104,
          SpeakNpcId = 100001,
          Subtitle = "You said it yourself, there's so much you want to do...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4D6"
        },
        [10111104] = {
          ContentTC = "你會離開這裡，去那些你前所未見的地方——",
          DialogueId = 10111104,
          ExStoryInfo = "Player",
          GUID = "194FE500",
          NextDialogue = 10111105,
          SpeakNpcId = 100001,
          Subtitle = "You'll leave Icelake for those unseen places—",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE500"
        },
        [10111105] = {
          ContentTC = "……你可以去一座小島，在那裡蓋幾間房子……",
          DialogueId = 10111105,
          ExStoryInfo = "Player",
          GUID = "194FE52A",
          NextDialogue = 10111106,
          SpeakNpcId = 100001,
          Subtitle = "...You'll go to a small island, where you can build a house by the sea...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE52A"
        },
        [10111106] = {
          ContentTC = "……在房子邊上種滿白色的花……",
          DialogueId = 10111106,
          ExStoryInfo = "Player",
          GUID = "194FE554",
          NextDialogue = 10111107,
          SpeakNpcId = 100001,
          Subtitle = "...and grow white flowers around it...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE554"
        },
        [10111107] = {
          ContentTC = "……一邊用大大的帽檐遮住太陽，一邊和友人說起冰湖城的雪……",
          DialogueId = 10111107,
