        [10113102] = {
          Camera = "-1578.376709,-656.11377,-24.818359,0.000068,-4.000004,20.828321,20.000008,1873.920044,false,Manual,4.0",
          ContentTC = "看你好好製定了計劃一計劃二，我還以為你不會沖動了。結果你還是那個你——倒也不錯，這才像你。",
          DialogueId = 10113102,
          GUID = "19512CCC",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10113103,
          Scripts = "CameraMoveTo{_delay{1},TargetPosition{\"-240.073883,130.292801,45.828125,0.000082,6.799965,5.978205,35.0,244.755096,false,Manual,4.0\"},duration{0}},",
          SpeakNpcId = 200021,
          Subtitle = "I thought you wouldn't act so recklessly anymore. Yet, you remain true to yourself, which isn't bad — This is you.",
          TalkActionId = {
            [1] = "100001:Crouch_End",
            [2] = "200021:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101131/19512CCC"
        },
        [10113103] = {
          Camera = "633.570557,243.739319,136.279297,0.000016,-7.999989,-172.621201,25.0,232.587921,false,DoNotOverride,2.0",
          ContentTC = "但是，我們已經送別了一個勇敢的朋友……我不能再看你去涉險。",
          DialogueId = 10113103,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "681.163269,249.893188,183.225586,0.000017,-12.0,-172.621384,25.0,232.587921,false,DoNotOverride,2.0",
          GUID = "19512CF6",
          NextDialogue = 10113104,
          SpeakNpcId = 200021,
          Subtitle = "We've just said goodbye to a brave young lady. I can't let you risk yourself as well.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101131/19512CF6"
        },
        [10113104] = {
          Camera = "-93.82695,167.397736,69.485352,-5.000005,10.599298,-16.499649,20.000008,65.358772,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "……剛才幫我圓場，謝了。",
          DialogueId = 10113104,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "-94.949982,139.65593,67.780273,-5.000005,10.799253,0.903312,20.000008,274.400574,false,Manual,4.0",
          GUID = "19512D20",
          NextDialogue = 10113106,
          SpeakNpcId = 100001,
          Subtitle = "...Thanks for covering for me back there.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101131/19512D20"
        },
        [10113106] = {
          Camera = "-57.476639,131.761963,80.688477,0.000004,13.197796,-11.293015,35.0,189.241562,false,Manual,4.0",
          ContentTC = "沒什麽好謝的，在這裡摸爬滾打了這麽多年，我早就從刺猬變成老鼠了，每天除了活下去不做他想，你可別像我一樣。",
          DialogueId = 10113106,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "19512D74",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10113107,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200021:p(stone)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "There's nothing to thank me for. After all these years, I've changed from a hedgehog to a rat, living only to see another day. Don't end up like me.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101131/19512D74"
        },
        [10113107] = {
          Camera = "10.66497,161.629562,248.601562,-15.000193,-59.999931,-45.621265,20.0,154.841125,false,Manual,2.0",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "刺猬有刺猬的驕傲，卑躬屈膝的事還是交給老鼠幹吧。",
          DialogueId = 10113107,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "-3.912712,176.5271,284.694336,-15.000193,-59.999931,-45.621265,20.0,154.841125,false,Manual,2.0",
          GUID = "19512D9E",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10113108,
          Scripts = [[
PARA{
CameraMoveTo{_delay{3.1},TargetPosition{"-64.077698,277.204651,376.257812,-15.000225,-59.99995,-45.621277,15.0,154.841125,false,Manual,22"},duration{0}},
CameraMoveTo{_delay{3.2},TargetPosition{"-82.694427,296.224976,422.373047,-15.000225,-59.99995,-45.621277,15.0,154.841125,false,Manual,22"},blend{"easeOutQuad"},duration{3}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "A hedgehog retains its dignity, so it's better to leave the grovelling to the rat.",
          TalkActionId = {
