        },
        [10113301] = {
          ContentTC = "再一次崩塌的夢裡，那個聲音從風中傳來。",
          DialogueId = 10113301,
          Duration = 3.5,
          GUID = "19514D72",
          NextDialogue = 10113302,
          Subtitle = "Once again, in the collapsing dream, that voice whispered through the wind.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514D72"
        },
        [10113302] = {
          ContentTC = "這一次，我終於可以聽清。",
          DialogueId = 10113302,
          Duration = 3.5,
          GUID = "19514D9C",
          NextDialogue = 10113303,
          Subtitle = "Only this time, I finally made it out.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514D9C"
        },
        [10113303] = {
          ContentTC = "像樹木的根須汲取著每一滴水，我竭盡全力試圖記住那個名字。",
          DialogueId = 10113303,
          Duration = 4,
          GUID = "19514DC6",
          NextDialogue = 10113304,
          Subtitle = "Like tree roots eagerly absorbing every drop of water, I endeavoured to engrave that name in my mind.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DC6"
        },
        [10113304] = {
          ContentTC = "……那個名字……",
          DialogueId = 10113304,
          Duration = 3,
          GUID = "19514DF0",
          Subtitle = "...That name is...",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DF0"
        },
        [10113401] = {
          Camera = "-1818.244629,451.75,65.15918,0.0,3.799989,1.999787,35.0,269.181396,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "我承受過痛苦，體會過憎恨。我曾為之疲憊，也曾為之悲嘆——",
          DialogueId = 10113401,
          FacialId = {
            [1] = "2000591:Happy02"
          },
          FinalCamera = "-1818.244629,451.75,77.947998,0.0,6.0,1.999786,35.0,921.225525,false,Manual,1.2",
          GUID = "19515DDA",
          NextDialogue = 10113402,
          Scripts = [[
PARA{
CameraMoveTo{_delay{3},TargetPosition{"-986.794189,356.464844,129.88501,0.000031,5.799336,133.697769,30.000002,425.998016,false,Manual,22.0"},duration{0}},
PlayAnimation{_delay{3.1},ActorId{2000591},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 2000591,
          Subtitle = "Pain and hatred have been my acquaintances. They've wearied and agrieved me—",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101134/19515DDA"
        },
        [10113402] = {
          Camera = "-1751.68335,1248.289062,55.207764,-0.0,4.000004,-50.000027,15.0,425.998016,false,DoNotOverride,1.2",
          ContentTC = "<H>但，我仍為曾誕生於世感到喜悅。</>",
          DialogueId = 10113402,
          FinalCamera = "-1650.423584,1127.605469,35.868652,-0.0,4.000004,-50.000027,15.0,425.998016,false,DoNotOverride,1.2",
          GUID = "19515E04",
          NextDialogue = 10113403,
          SpeakNpcId = 2000591,
          Subtitle = "Yet, I find joy in having existed in this world.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101134/19515E04"
        },
        [10113403] = {
          Camera = "-1283.367798,582.753906,176.219971,0.000078,-2.599427,-26.997437,35.0,144.372665,false,Manual,4.831013",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "這就是，我的選擇。",
          DialogueId = 10113403,
          FinalCamera = "-1286.140259,577.761719,176.219971,0.000078,-2.599427,-28.997461,35.0,896.028748,false,Manual,4.092557",
          GUID = "19515E2E",
          SpeakNpcId = 2000591,
          Subtitle = "This is my choice.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101134/19515E2E"
        },
        [10113501] = {
          Camera = "196.933594,49.747803,104.415039,0.000189,3.999731,-144.598633,35.0,149.900024,false,Manual,4.0194.328125,53.443115,103.287109,0.000189,3.999731,-144.598587,35.0,150.0,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "穢獸？！",
          DialogueId = 10113501,
          ExStoryInfo = "Player",
          FinalCamera = "175.269531,39.89624,107.285645,0.000189,3.999731,-144.598587,35.0,125.0,false,Manual,4.0",
          GUID = "19516EEA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "200021:n(100001)",
