        },
        [10113502] = {
          Camera = "238.0625,-87.837646,103.295898,0.000204,4.399468,158.005524,35.0,185.005707,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "你就把這個正在嗷嗷亂叫的破機器當做你想要保護的人，把這些穢獸當做要攻擊她的傢伙。",
          DialogueId = 10113502,
          FinalCamera = "240.769531,-81.229736,103.295898,0.000213,4.399468,158.005692,35.0,292.735229,false,Manual,5.0",
          GUID = "19516F14",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10113503,
          Scripts = "TurnTo{_delay{0.5},TurnToDescription{\"100001:n(200021)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Just think of this noisy piece of scrap as someone you want to protect, and these Filthoids are the baddies after her.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101135/19516F14"
        },
        [10113503] = {
          Camera = "135.984375,-44.101318,130.969727,0.000225,3.999998,147.005432,35.0,200.0,false,Manual,5.0",
          ContentTC = "想辦法保護它，別讓穢獸把它拆了。",
