          GUID = "19516F3E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10113504,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "Try to keep it safe — make sure it doesn't get banged up from Filthoid attacks.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101135/19516F3E"
        },
        [10113504] = {
          Camera = "-68.972656,221.981689,176.847656,0.000192,-13.999995,-67.401672,40.0,328.456238,false,Manual,5.0",
          ContentTC = "你好歹等我準備好再——",
          DialogueId = 10113504,
          ExStoryInfo = "Player",
          GUID = "19516F68",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10113505,
          SpeakNpcId = 100001,
          Subtitle = "But I'm not ready—",
          TalkActionId = {
            [1] = "100001:Angry01_Start",
            [2] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101135/19516F68"
        },
        [10113505] = {
          Camera = "875.300781,17.000244,70.82959,0.0,0.0,-179.999985,25.0,674.169678,false,Manual,2.0",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "我們狩月人就是會遇到很多突發情況嘛。別慌、別慌，我也來幫你一把就是了！",
          DialogueId = 10113505,
          FinalCamera = "1020.636719,17.000244,70.82959,0.0,0.0,-179.999985,25.0,674.169678,false,Manual,2.0",
          GUID = "19516F92",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "Well, we Phoxhunters are always dealing with unexpected situations. Don't panic, I've got your back!",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200021:p(45)"
          },
          VoiceName = "voice/$Locale$/story/1002/101135/19516F92"
        },
        [10113701] = {
          ContentTC = "呃，碎掉了。",
          DialogueId = 10113701,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19518F12",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10113702,
          SpeakNpcId = 100001,
          Subtitle = "Er, it broke.",
          VoiceName = "voice/$Locale$/story/1002/101137/19518F12"
        },
        [10113702] = {
          ContentTC = "廢品改裝的嘛，能用已經很不錯了！",
          DialogueId = 10113702,
          Duration = 2.5,
          GUID = "19518F3C",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200021,
          Subtitle = "Well, it is made from scrap, after all. I was surprised that it would work!",
          VoiceName = "voice/$Locale$/story/1002/101137/19518F3C"
        },
        [10113801] = {
          ContentTC = "任務完成",
          DialogueId = 10113801,
          Duration = 3.5,
          GUID = "19519F7A",
          Subtitle = "Quest Completed",
          VoiceName = "voice/$Locale$/story/1002/101138/19519F7A"
        },
        [10113901] = {
          Content = "本次技术性测试剧情流程已结束。",
          DialogueId = 10113901,
          Duration = 5,
          GUID = "1951AFE2",
          VoiceName = "voice/$Locale$/story/1002/101139/1951AFE2"
        },
        [10114001] = {
          ContentTC = "這麽快就回來了？不是去跟蹤恩里克了嗎？",
          DialogueId = 10114001,
          GUID = "1951C04A",
          SpeakNpcId = 200021,
          Subtitle = "Back already? Shouldn't you be following Henrik?",
          VoiceName = "voice/$Locale$/story/1002/101140/1951C04A"
        },
        [10114201] = {
          ContentTC = "你們要早點休息哦。",
          DialogueId = 10114201,
          GUID = "1951E11A",
          SpeakNpcId = 200020,
          Subtitle = "Rest early when you're done.",
          VoiceName = "voice/$Locale$/story/1002/101142/1951E11A"
        },
        [10114301] = {
          ContentTC = "如果恩里克叔叔同意的話，你可以再來找我玩嗎？",
          DialogueId = 10114301,
          GUID = "1951F182",
          SpeakNpcId = 200006,
          Subtitle = "If it's okay with Mr Henrik, could you come visit me again?",
          VoiceName = "voice/$Locale$/story/1002/101143/1951F182"
        },
        [10114401] = {
          ContentTC = "放老實點，別管與你無關的事。",
          DialogueId = 10114401,
          GUID = "195201EA",
          SpeakNpcId = 200005,
          Subtitle = "Keep your nose out of things that don't concern you.",
          VoiceName = "voice/$Locale$/story/1002/101144/195201EA"
        },
        [10114501] = {
