        [10114601] = {
          ContentTC = "拜托了，請跟我來！",
          DialogueId = 10114601,
          Duration = 4,
          GUID = "195222BA",
          SpeakNpcId = 200019,
          SpeakNpcName = "UI_Npc_Name_Boy_3",
          Subtitle = "Please help us...! Follow me!",
          VoiceName = "voice/$Locale$/story/1002/101146/195222BA"
        },
        [10114701] = {
          ContentTC = "這邊，恩里克先生的辦公室！",
          DialogueId = 10114701,
          Duration = 5,
          GUID = "19523322",
          SpeakNpcId = 200019,
          SpeakNpcName = "UI_Npc_Name_Boy_3",
          Subtitle = "Over here! Mr Henrik's in his office!",
          VoiceName = "voice/$Locale$/story/1002/101147/19523322"
        },
        [10114801] = {
          ContentTC = "先抓緊離開這兒吧。",
          DialogueId = 10114801,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952438A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Let's get out of here.",
          VoiceName = "voice/$Locale$/story/1002/101148/1952438A"
        },
        [10114901] = {
          ContentTC = "請一定要找到她，拜托了……",
          DialogueId = 10114901,
          GUID = "195253F2",
          SpeakNpcId = 200045,
          Subtitle = "Please find her... I'm begging you...",
          VoiceName = "voice/$Locale$/story/1002/101149/195253F2"
        },
        [10115001] = {
          ContentTC = "……賽琪殺了恩里克……為什麽……會這樣……",
          DialogueId = 10115001,
          GUID = "1952645A",
          NextDialogue = 10115002,
          SpeakNpcId = 700049,
          Subtitle = "Psyche killed Henrik... Why... How did this happen...?",
          VoiceName = "voice/$Locale$/story/1002/101150/1952645A"
        },
        [10115002] = {
          ContentTC = "賽琪永遠都在笑著……恩里克先生雖然話不多，但總是像父親一樣照料我們……他們明明都是那麽好的人啊……",
          DialogueId = 10115002,
          GUID = "19526484",
          SpeakNpcId = 700049,
          Subtitle = "Psyche was so sweet, always smiling... And even though Mr Henrik didn't talk much, he cared for us like a father... They were such good people...",
          VoiceName = "voice/$Locale$/story/1002/101150/19526484"
        },
        [10115101] = {
          ContentTC = "恩里克先生一直都太累了。或許對他來說，這樣的結局……也不錯。",
          DialogueId = 10115101,
          GUID = "195274C2",
          SpeakNpcId = 200019,
          Subtitle = "Mr Henrik must've been exhausted... Maybe this is somewhat a merciful release.",
          VoiceName = "voice/$Locale$/story/1002/101151/195274C2"
        },
        [10115201] = {
          ContentTC = "白，還記得賽琪是往哪個方向跑的嗎？",
          DialogueId = 10115201,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952852A",
          NextDialogue = 10115202,
          SpeakNpcId = 100001,
          Subtitle = "Snow, do you remember which way Psyche went?",
          VoiceName = "voice/$Locale$/story/1002/101152/1952852A"
        },
        [10115202] = {
          ContentTC = "當然記得，我的記憶不會出錯！她是往城門的方向跑的！",
          DialogueId = 10115202,
          Duration = 4,
          GUID = "19528554",
          NextDialogue = 10115203,
          SpeakNpcId = 200002,
          Subtitle = "Of course, I have a good memory! She ran towards the city gate!",
          VoiceName = "voice/$Locale$/story/1002/101152/19528554"
        },
        [10115203] = {
          ContentTC = "……她出城了？",
          DialogueId = 10115203,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952857E",
          NextDialogue = 10115204,
          SpeakNpcId = 100001,
          Subtitle = "...She left the city?",
          VoiceName = "voice/$Locale$/story/1002/101152/1952857E"
        },
        [10115204] = {
          ContentTC = "好，我們也跟上，去城外。",
          DialogueId = 10115204,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "195285A8",
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's head out and catch up to her.",
          VoiceName = "voice/$Locale$/story/1002/101152/195285A8"
        },
        [10115301] = {
          ContentTC = "好大的風！嗚哇，感覺要被吹飛了——",
          DialogueId = 10115301,
          Duration = 4,
          GUID = "19529592",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10115302,
          SpeakNpcId = 200002,
          Subtitle = "This wind is so strong! Whoa, I feel like it's going to blow me away—",
          VoiceName = "voice/$Locale$/story/1002/101153/19529592"
        },
        [10115302] = {
          ContentTC = "你們兩個也小心點！",
          DialogueId = 10115302,
          Duration = 4,
          GUID = "195295BC",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Be careful, you two!",
          VoiceName = "voice/$Locale$/story/1002/101153/195295BC"
        },
        [10115401] = {
