        [10117802] = {
          ContentTC = "有道理！那魔王小妹你有什麽主意嗎？",
          DialogueId = 10117802,
          Duration = 3,
          GUID = "19542FE4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10117803,
          SpeakNpcId = 200011,
          Subtitle = "Makes sense! Any suggestions, Demon King?",
          VoiceName = "voice/$Locale$/story/1002/101178/19542FE4"
        },
        [10117803] = {
          ContentTC = "剛才那個老爺爺說的「垃圾桶公主」就挺不錯的？",
          DialogueId = 10117803,
          Duration = 3,
          GUID = "1954300E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10117804,
          SpeakNpcId = 200002,
          Subtitle = "That old man back there called you \"Princess Rubbish Bin\"... That's a good one!",
          VoiceName = "voice/$Locale$/story/1002/101178/1954300E"
        },
        [10117804] = {
          ContentTC = "「緘默偵探☆垃圾桶公主」，氣勢是不是突然就上去啦！",
          DialogueId = 10117804,
          Duration = 3,
          GUID = "19543038",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10117805,
          SpeakNpcId = 200002,
          Subtitle = "\"Reticent Detective ☆ Princess Rubbish Bin\", has a nice ring to it, doesn't it?",
          VoiceName = "voice/$Locale$/story/1002/101178/19543038"
        },
        [10117805] = {
