          VoiceName = "voice/$Locale$/story/1002/101179/195440CA"
        },
        [10117906] = {
          Camera = "-97.681335,235.033142,214.595215,0.000114,-15.999267,-53.001629,35.0,124.611694,false,DoNotOverride,2.2",
          ContentTC = "好嘞，這樣就沒問題了！等我抓完小賊再回來收貨。見者有份，等小賊的事兒搞定，葡萄酒也分你一半！",
          DialogueId = 10117906,
          FacialId = {
            [1] = "200011:Smile02"
          },
          GUID = "195440F4",
          LookAt = {
            [1] = "100001:n(200011)",
            [2] = "200002:n(200011)"
          },
          NextDialogue = 10117907,
          SpeakNpcId = 200011,
          Subtitle = "There, all set! I'll come back for these later. Finders keepers — I'll share this wine with you once we've caught the thief!",
          TalkActionId = {
            [1] = "200011:SpecialHoldHelmet_Start",
            [2] = "200002:SpecialHappy_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101179/195440F4"
        },
        [10117907] = {
          ContentTC = "呃……這個就不用了！",
          DialogueId = 10117907,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "1954411E",
          SpeakNpcId = 100001,
          Subtitle = "Um... I think I'll pass, thanks.",
          VoiceName = "voice/$Locale$/story/1002/101179/1954411E"
        },
        [10118001] = {
          ContentTC = "才剛有個人爬上來，怎麽又來三個？",
          DialogueId = 10118001,
          Duration = 3,
          GUID = "1954508A",
          SpeakNpcId = 200055,
          Subtitle = "A young man just climbed up here, and now three others? What's all this about?",
          VoiceName = "voice/$Locale$/story/1002/101180/1954508A"
        },
        [10118101] = {
          ContentTC = "最近這是怎麽了，總有人在城裡飛檐走壁。冰湖城是有什麽運動賽嗎？爬得快有獎那種？",
          DialogueId = 10118101,
          GUID = "195460F2",
          NextDialogue = 10118102,
          SpeakNpcId = 200055,
          Subtitle = "Is Icelake having a parkour race or something? With prizes for the fastest runner?",
          VoiceName = "voice/$Locale$/story/1002/101181/195460F2"
        },
        [10118102] = {
          ContentTC = "呃……這麽說來，好像確實有個皎皎前輩設過類似的挑戰？",
          DialogueId = 10118102,
          GUID = "1954611C",
          NextDialogue = 10118103,
          SpeakNpcId = 200002,
          Subtitle = "Hmm... you know what — I heard that a Luno elder did once set up a race like that...",
          VoiceName = "voice/$Locale$/story/1002/101181/1954611C"
        },
        [10118103] = {
          ContentTC = "那你們快追吧！剛才那位選手都跑過去半天啦。",
          DialogueId = 10118103,
          GUID = "19546146",
          SpeakNpcId = 200055,
          Subtitle = "Well then, you better hurry! The other contestant's been gone a good while.",
          VoiceName = "voice/$Locale$/story/1002/101181/19546146"
        },
        [10118201] = {
          ContentTC = "啊，快看，就是前面屋頂上那傢伙！",
          DialogueId = 10118201,
          Duration = 3,
          GUID = "1954715A",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "Ah, there he is! On that roof!",
          VoiceName = "voice/$Locale$/story/1002/101182/1954715A"
        },
        [10118202] = {
          Camera = "-476.057983,-45.540398,533.046387,0.000058,-4.400117,156.809341,35.000008,241.278336,false,Manual,4.2",
          ContentTC = "你、你……至於追到這種地方來嗎？你說你那錢本來就是拿來分給別人的，那分老子一點怎麽了？",
          DialogueId = 10118202,
          GUID = "19547184",
          LookAt = {
            [1] = "200002:n(200053)",
            [2] = "200053:n(100001)",
            [3] = "100001:n(200053)",
            [4] = "200011:n(200053)"
          },
          NextDialogue = 10118203,
          Scripts = [[
PARA{
MoveTo{ActorId{100001},TargetPoint{"P101182Nvzhu1"},MoveSpeed{220},Visibility{"Show"}},
MoveTo{ActorId{200011},TargetPoint{"P101182Maer1"},MoveSpeed{240},Visibility{"Show"}},
MoveTo{ActorId{200002},TargetPoint{"P101182Bai1"},MoveSpeed{210},Visibility{"Show"}}
}]],
          SpeakNpcId = 200053,
          SpeakNpcName = "UI_Npc_Name_Man_12",
          Subtitle = "Wha... Did you really have to chase me all the way up here? You said you were going to share the money with the poor anyway, so why can't I get a piece of it?",
          TalkActionId = {
            [1] = "200053:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101182/19547184"
        },
        [10118203] = {
          Camera = "-845.377014,-25.232204,629.145264,0.000027,-33.600269,4.611965,28.874323,1077.120361,false,Manual,4.2",
          ContentTC = "你有困難我可以幫你，但直接上手搶，那就吃我一鏟！",
          DialogueId = 10118203,
          FacialId = {
            [1] = "200011:Angry01"
          },
          GUID = "195471AE",
          SpeakNpcId = 200011,
          Subtitle = "If you're hard up, I can help you. But you can't just grab money of people — that'll earn you a whack on the head with my shovel!",
          TalkActionId = {
            [1] = "200011:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101182/195471AE"
        },
        [10118204] = {
          ContentTC = "（青年似乎找不到反駁的話，氣急敗壞地跳下了墻。）",
          DialogueId = 10118204,
          DisableMouth = 1,
          GUID = "195471D8",
          Subtitle = "(The thief seems at a loss for words and jumps off the wall in frustration.)",
          VoiceName = "voice/$Locale$/story/1002/101182/195471D8"
        },
        [10118301] = {
          ContentTC = "又、又不見了？他是幽靈嗎？",
          DialogueId = 10118301,
          Duration = 3,
          GUID = "195481C2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200002,
          Subtitle = "He's disappeared again!? What is he, a ghost?",
          VoiceName = "voice/$Locale$/story/1002/101183/195481C2"
        },
        [10118302] = {
          ContentTC = "不……你們看，這面井蓋有被挪動過的痕跡。",
          DialogueId = 10118302,
          Duration = 3,
          GUID = "195481EC",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200011,
          Subtitle = "No... look, this manhole cover's been shifted.",
          VoiceName = "voice/$Locale$/story/1002/101183/195481EC"
        },
        [10118303] = {
          ContentTC = "以我的推測，他一定鉆進了下水道！",
          DialogueId = 10118303,
          Duration = 3,
          GUID = "19548216",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "He must've ducked into the sewers!",
          VoiceName = "voice/$Locale$/story/1002/101183/19548216"
        },
        [10118401] = {
          ContentTC = "這麽深的水……根本就過不去吧！他怎麽做到的？",
          DialogueId = 10118401,
          Duration = 3,
          GUID = "1954922A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10118402,
          SpeakNpcId = 200002,
          Subtitle = "This water's too deep... How did he get across?",
          VoiceName = "voice/$Locale$/story/1002/101184/1954922A"
        },
        [10118402] = {
          ContentTC = "別急，這種時候就該動用本“緘默偵探”的情報網了！",
          DialogueId = 10118402,
          Duration = 3,
          GUID = "19549254",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10118403,
          SpeakNpcId = 200011,
          Subtitle = "Don't worry — this is where the Reticent Detective's intel network shines!",
          VoiceName = "voice/$Locale$/story/1002/101184/19549254"
        },
        [10118403] = {
          ContentTC = "根據8號小桶產出的《下水道維修手冊》，這裡的水位是可以人為控製的！機關一定就在附近。",
          DialogueId = 10118403,
          Duration = 3,
          GUID = "1954927E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "According to the \"Sewer Maintenance Manual\" from Bin No. 8, the water level here is controllable! There's gotta be a switch nearby.",
          VoiceName = "voice/$Locale$/story/1002/101184/1954927E"
        },
        [10118501] = {
          ContentTC = "哇——真的有排水機關。垃圾桶公主☆緘默偵探，你好有本領！",
          DialogueId = 10118501,
          Duration = 3,
          GUID = "1954A292",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10118502,
          SpeakNpcId = 200002,
          Subtitle = "Wow, it worked! Princess Rubbish Bin ☆ Reticent Detective, you're incredible!",
          VoiceName = "voice/$Locale$/story/1002/101185/1954A292"
        },
        [10118502] = {
          ContentTC = "去掉前面那半，拜托了……嗚嗚。",
          DialogueId = 10118502,
          Duration = 3,
          GUID = "1954A2BC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118503,
          SpeakNpcId = 200011,
          Subtitle = "Please, remove the \"Princess Rubbish Bin\" part... I'm begging you...",
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2BC"
        },
        [10118503] = {
          ContentTC = "水位下降了一部分，找找看還有沒有類似的開關吧。",
          DialogueId = 10118503,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1954A2E6",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "The water level has dropped a bit. Let's see if there are more switches.",
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2E6"
        },
        [10118601] = {
          ContentTC = "快看，下邊真有路哎！",
          DialogueId = 10118601,
          Duration = 3,
          GUID = "1954B2FA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Hey, look! There's really a path down there!",
          VoiceName = "voice/$Locale$/story/1002/101186/1954B2FA"
        },
        [10118602] = {
          ContentTC = "對了，《下水道維修手冊》裡寫過，下水道偶爾會招來一些喜歡溫暖濕潤的穢獸棲身。",
          DialogueId = 10118602,
          Duration = 3,
          GUID = "1954B324",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "Oh, right — the Manual says sewers sometimes attract Filthoids that like warm, damp environments.",
          VoiceName = "voice/$Locale$/story/1002/101186/1954B324"
        },
        [10118603] = {
          ContentTC = "雖然這些穢獸是體格最弱小的那種，快跟貓貓狗狗差不多了，但如果成群結隊行動，還是會有點危險……",
          DialogueId = 10118603,
          Duration = 3,
          GUID = "1954B34E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118604,
          SpeakNpcId = 200011,
          Subtitle = "They're usually small — no bigger than cats or dogs — but a swarm could be trouble…",
          VoiceName = "voice/$Locale$/story/1002/101186/1954B34E"
        },
        [10118604] = {
          ContentTC = "我們準備好再前進吧！",
          DialogueId = 10118604,
          Duration = 3,
          GUID = "1954B378",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "Let's make sure we're prepared before we go any further.",
          VoiceName = "voice/$Locale$/story/1002/101186/1954B378"
        },
        [10118701] = {
          ContentTC = "乖乖站住！不許跑！",
          DialogueId = 10118701,
          Duration = 3,
          GUID = "1954C362",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118702,
          SpeakNpcId = 200011,
          Subtitle = "Hold it right there!",
          VoiceName = "voice/$Locale$/story/1002/101187/1954C362"
        },
        [10118702] = {
          ContentTC = "呼……呼……你們幾個腿長的……等等我……",
          DialogueId = 10118702,
          Duration = 3,
          GUID = "1954C38C",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Huff... Huff... Wait up... Not everyone is blessed with long legs, you know...",
          VoiceName = "voice/$Locale$/story/1002/101187/1954C38C"
        },
        [10118801] = {
          ContentTC = "咳、咳……嗆死我了……好卑鄙……",
          DialogueId = 10118801,
          Duration = 3,
          GUID = "1954D3CA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "*cough* *cough* I can't breathe... That is a low blow...",
          VoiceName = "voice/$Locale$/story/1002/101188/1954D3CA"
        },
        [10118901] = {
          ContentTC = "聽到腳步聲了，這邊這邊！",
          DialogueId = 10118901,
          Duration = 3,
          GUID = "1954E432",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "I hear footsteps — this way!",
          VoiceName = "voice/$Locale$/story/1002/101189/1954E432"
        },
        [10119001] = {
          ContentTC = "剛才有什麽飛過來了……",
          DialogueId = 10119001,
          Duration = 3,
          GUID = "1954F49A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10119002,
          SpeakNpcId = 200002,
          Subtitle = "Did something just whizz by?",
          VoiceName = "voice/$Locale$/story/1002/101190/1954F49A"
        },
        [10119002] = {
          ContentTC = "嗚啊……疼疼疼！是石頭！",
          DialogueId = 10119002,
          Duration = 3,
          GUID = "1954F4C4",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Ow... That was a rock!",
          VoiceName = "voice/$Locale$/story/1002/101190/1954F4C4"
        },
        [10119101] = {
          ContentTC = "他在高處！哼，這次我不會再被砸到——嗚哇！",
          DialogueId = 10119101,
          Duration = 3,
          GUID = "19550502",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10119102,
          SpeakNpcId = 200002,
          Subtitle = "He's up there! Hmph, you won't hit me this time — ow!",
          VoiceName = "voice/$Locale$/story/1002/101191/19550502"
        },
        [10119102] = {
          ContentTC = "真是的……這麽愛扔石頭，他是猴子變的嗎？",
          DialogueId = 10119102,
          Duration = 3,
          GUID = "1955052C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Ugh... What are you, a monkey? Always throwing rocks...",
          VoiceName = "voice/$Locale$/story/1002/101191/1955052C"
        },
        [10119201] = {
          ContentTC = "這些腳印是剛踩上去的，沿著這些濕漉漉的腳印追上去準沒錯。",
          DialogueId = 10119201,
          Duration = 3,
          GUID = "1955156A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "These footprints are fresh — it must be him! Let's follow them.",
          VoiceName = "voice/$Locale$/story/1002/101192/1955156A"
        },
        [10119301] = {
          ContentTC = "這是……新鮮的血跡？他受傷了？",
          DialogueId = 10119301,
          Duration = 3,
          GUID = "195525D2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10122001,
          SpeakNpcId = 200011,
          Subtitle = "Is that... blood? Did he get hurt?",
          VoiceName = "voice/$Locale$/story/1002/101193/195525D2"
        },
        [10119302] = {
          ContentTC = "他或許被什麽襲擊了……我們也謹慎一些。",
          DialogueId = 10119302,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195525FC",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Something might have attacked him... We should be extra careful.",
          VoiceName = "voice/$Locale$/story/1002/101193/195525FC"
        },
        [10119401] = {
          ContentTC = "果然……他驚擾了這裡的穢獸群，以至遭到了圍攻。",
          DialogueId = 10119401,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955363A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Just as I thought, he startled the Filthoids here and got attacked.",
          VoiceName = "voice/$Locale$/story/1002/101194/1955363A"
        },
        [10119501] = {
          ContentTC = "我跑不動了……我投降……",
          DialogueId = 10119501,
          Duration = 3,
          GUID = "10119501.0",
          NextDialogue = 10119502,
          SpeakNpcId = 200053,
          Subtitle = "I can't run any further... I surrender...",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Die"
        },
        [10119502] = {
          ContentTC = "哼哼，跑不動了吧！",
          DialogueId = 10119502,
          Duration = 3,
          GUID = "195546A2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10119503,
          SpeakNpcId = 200002,
          Subtitle = "Hmph, not so fast now, are you?",
          VoiceName = "voice/$Locale$/story/1002/101195/195546A2"
        },
        [10119503] = {
          ContentTC = "{nickname}，搭把手，一起按住他！",
          DialogueId = 10119503,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195546CC",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = ", come on, let's pin him down!",
          VoiceName = "voice/$Locale$/story/1002/101195/195546CC"
        },
        [10119601] = {
          ContentTC = "這扇門看起來沒壞，只是上了鎖……",
          DialogueId = 10119601,
          Duration = 3,
          GUID = "1955570A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10119602,
          SpeakNpcId = 200006,
          Subtitle = "Looks like this gate still works. But it's locked...",
          VoiceName = "voice/$Locale$/story/1002/101196/1955570A"
        },
        [10119602] = {
          ContentTC = "唉，都成廢礦了，有必要搞這麽多防盜措施嗎！",
          DialogueId = 10119602,
          Duration = 3,
          GUID = "19555734",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10119603,
          SpeakNpcId = 200002,
          Subtitle = "Seriously, why do they need all these security measures for an abandoned old pit?",
          VoiceName = "voice/$Locale$/story/1002/101196/19555734"
        },
        [10119603] = {
          ContentTC = "……也許是為了防止有人誤入此地，被穢獸傷到？",
          DialogueId = 10119603,
          Duration = 3,
          GUID = "1955575E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10119604,
          SpeakNpcId = 200006,
          Subtitle = "...Probably to keep curious folks from stumbling into a Filthoid attack.",
          VoiceName = "voice/$Locale$/story/1002/101196/1955575E"
        },
        [10119604] = {
          ContentTC = "讓我們碰碰運氣吧！看看這附近能不能找到鑰匙一類的東西。",
          DialogueId = 10119604,
          Duration = 3,
          GUID = "19555788",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Let's try our luck! Maybe there's a key lying around here somewhere.",
          VoiceName = "voice/$Locale$/story/1002/101196/19555788"
        },
        [10119701] = {
          ContentTC = "哇……原來礦坑裡還有這種好東西？要是讓瑪爾潔知道了，她還不得樂開花！",
          DialogueId = 10119701,
          Duration = 3,
          GUID = "19556772",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10119702,
          SpeakNpcId = 200002,
          Subtitle = "Wow... take a look at this! Margie would flip if she saw it!",
          VoiceName = "voice/$Locale$/story/1002/101197/19556772"
        },
        [10119702] = {
          ContentTC = "但是這礦石很硬吧，瑪爾潔小姐的鏟子說不定會被磕壞的。",
          DialogueId = 10119702,
          Duration = 3,
          GUID = "1955679C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "This ore's pretty tough, though. It might just break Miss Margie's shovel.",
          VoiceName = "voice/$Locale$/story/1002/101197/1955679C"
        },
        [10119801] = {
          ContentTC = "{nickname}，我也來幫忙吧！",
          DialogueId = 10119801,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195577DA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10119802,
          SpeakNpcId = 200006,
          Subtitle = "Let me help you, !",
          VoiceName = "voice/$Locale$/story/1002/101198/195577DA"
        },
        [10119802] = {
          ContentTC = "不用。賽琪，趁「魔王大人」沒看著……我們平分了怎麽樣？",
          DialogueId = 10119802,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19557804",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10119803,
          SpeakNpcId = 100001,
          Subtitle = "I've got this. Hey Psyche, while the Demon King isn't looking, how about we split the treasure?",
          VoiceName = "voice/$Locale$/story/1002/101198/19557804"
        },
        [10119803] = {
          ContentTC = "你拿著就好！可以給自己買點漂亮衣服什麽的，我……沒什麽需要用錢的地方。",
          DialogueId = 10119803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955782E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "I'm good. You can keep it all to buy yourself some nice clothes or something. I... don't really need the treasure.",
          VoiceName = "voice/$Locale$/story/1002/101198/1955782E"
        },
        [10119901] = {
          ContentTC = "這是什麽？",
          DialogueId = 10119901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19558842",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "What's this?",
          VoiceName = "voice/$Locale$/story/1002/101199/19558842"
        },
        [10120001] = {
          ContentTC = "唔……是開門的機關！藏得好嚴實。",
          DialogueId = 10120001,
          Duration = 3,
          GUID = "195598AA",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Ah, it's a hidden switch for the gate! Who'd have thought?",
          VoiceName = "voice/$Locale$/story/1002/101200/195598AA"
        },
        [10120101] = {
          ContentTC = "怎麽這麽多……呃……呃呃……",
          DialogueId = 10120101,
          Duration = 3,
          GUID = "1955A912",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120102,
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh... there are so many of them... Argh... aaaargh...",
          VoiceName = "voice/$Locale$/story/1002/101201/1955A912"
        },
        [10120102] = {
          ContentTC = "從我大腿上下來，白。你這樣我動不了了……你先回冰湖城吧，我不會笑話你的。",
          DialogueId = 10120102,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A93C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120103,
          SpeakNpcId = 100001,
          Subtitle = "Get off my leg, Snow — I can't walk like this... You can head back to Icelake if you're scared. I won't make fun of you.",
          VoiceName = "voice/$Locale$/story/1002/101201/1955A93C"
        },
        [10120103] = {
          ContentTC = "不不不不回去，沒沒沒沒有經歷過冒冒冒險的人生一定是不不不不不完整的！",
          DialogueId = 10120103,
          Duration = 3,
          GUID = "1955A966",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120104,
          SpeakNpcId = 200002,
          Subtitle = "N—No way. A life without s—some risks is not c—c—c—complete!",
          VoiceName = "voice/$Locale$/story/1002/101201/1955A966"
        },
        [10120104] = {
          ContentTC = "好呀，那我就陪著{nickname}和魔王大人一起，把人生變「完整」一點吧。",
          DialogueId = 10120104,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A990",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10120105,
          SpeakNpcId = 200006,
          Subtitle = "Alright then, I'll be right here with  and Miss Demon King to make our lives complete.",
          VoiceName = "voice/$Locale$/story/1002/101201/1955A990"
        },
        [10120105] = {
          ContentTC = "剛剛我應該沒有拖後腿……所以接下來，我想也不會有問題的！",
          DialogueId = 10120105,
          Duration = 3,
          GUID = "1955A9BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120106,
          SpeakNpcId = 200006,
          Subtitle = "I didn't slow us down earlier... so I believe I can keep going forward with you.",
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9BA"
        },
        [10120106] = {
          ContentTC = "嗯，我們繼續往前走吧。",
          DialogueId = 10120106,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A9E4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10120107,
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's move on.",
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9E4"
        },
        [10120107] = {
          ContentTC = "（只是一些尋常的穢獸，遠不如凈界島那一次來得兇險……）",
          DialogueId = 10120107,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955AA0E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10120108,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(These Filthoids are nothing compared to what happened to Berry and me on Purgatorio Island...)",
          VoiceName = "voice/$Locale$/story/1002/101201/1955AA0E"
        },
        [10120108] = {
          ContentTC = "（仔細回想貝蕾教過的防身技巧，謹慎地揮出每一次劍——可以做到的。）",
          DialogueId = 10120108,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955AA38",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Just go over the self-defence moves Berry once taught me and wield my sword carefully — I can do this.)",
          VoiceName = "voice/$Locale$/story/1002/101201/1955AA38"
        },
        [10120201] = {
