        [10120401] = {
          ContentTC = "那邊是淚湖欸，我們不是說好要進城嗎？",
          DialogueId = 10120401,
          GUID = "1955DA4A",
          NextDialogue = 10120402,
          SpeakNpcId = 200002,
          Subtitle = "Hey, that's Lamenting Lake. The city's this way!",
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA4A"
        },
        [10120402] = {
          ContentTC = "一個人亂轉很危險的！快回來，白在這兒等你！",
          DialogueId = 10120402,
          GUID = "1955DA74",
          SpeakNpcId = 200002,
          Subtitle = "Wandering off alone is dangerous. Come this way, I'll wait for you here.",
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA74"
        },
        [10120501] = {
          ContentTC = "你要去哪兒呀，我們不是說好要進城嗎？",
          DialogueId = 10120501,
          GUID = "1955EAB2",
          NextDialogue = 10120502,
          SpeakNpcId = 200002,
          Subtitle = "Where are you going? The city's this way!",
          VoiceName = "voice/$Locale$/story/1002/101205/1955EAB2"
        },
        [10120502] = {
          ContentTC = "那邊有好多好多穢獸，你會被吃掉的！快到白這邊來！",
          DialogueId = 10120502,
          GUID = "1955EADC",
          SpeakNpcId = 200002,
          Subtitle = "It's crawling with Filthoids over there. Come back here if you don't want to be their snacks!",
          VoiceName = "voice/$Locale$/story/1002/101205/1955EADC"
        },
        [10120601] = {
          ContentTC = "（這就是「城市」嗎，還是第一次見到……）",
          DialogueId = 10120601,
          DisableMouth = 1,
          GUID = "1955FB1A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10120602,
          SpeakNpcId = 100001,
          Subtitle = "(So... this is a \"city\"? Never seen or been to one before...)",
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB1A"
        },
        [10120602] = {
          ContentTC = "（可接下來去哪兒，完全沒有頭緒……還是先找到白和那位卡蜜拉女士吧。）",
          DialogueId = 10120602,
          DisableMouth = 1,
          GUID = "1955FB44",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(But I have no idea where to go... Guess I should find Snow and the lady called Camilla first.)",
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB44"
        },
        [10120701] = {
          ContentTC = "嗚哇哇，過不去了！怎麼回事，連下水道也在跟我們作對……",
          DialogueId = 10120701,
          GUID = "19560B82",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120702,
          SpeakNpcId = 200002,
          Subtitle = "Whoa! Now we're stuck!? Even the sewer's giving us trouble...",
          VoiceName = "voice/$Locale$/story/1002/101207/19560B82"
        },
        [10120702] = {
          ContentTC = "讓「緘默偵探」看看－－這裡有個水閥！他一定對水閥動了手腳！",
          DialogueId = 10120702,
          GUID = "19560BAC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120703,
          SpeakNpcId = 200011,
          Subtitle = "Let this Reticent Detective take a look... Huh, there's a water valve here! He must've done something to it!",
          VoiceName = "voice/$Locale$/story/1002/101207/19560BAC"
        },
        [10120703] = {
          ContentTC = "也就是說，這裡的水位是<H>水閥</>控制的……",
          DialogueId = 10120703,
          GUID = "19560BD6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "So the water level here is controlled by these valves...",
          VoiceName = "voice/$Locale$/story/1002/101207/19560BD6"
        },
        [10120801] = {
          ContentTC = "前面還有水閥！",
          DialogueId = 10120801,
          GUID = "19561BEA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "I see another valve up ahead!",
          VoiceName = "voice/$Locale$/story/1002/101208/19561BEA"
        },
        [10120901] = {
          ContentTC = "那個壞蛋剛剛就是鑽到這個洞裡去了，我們也跟上！",
          DialogueId = 10120901,
          GUID = "19562C52",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120902,
          SpeakNpcId = 200002,
          Subtitle = "That sneaky thief just slipped through this hole — come on, we're not letting him get away!",
          VoiceName = "voice/$Locale$/story/1002/101209/19562C52"
        },
        [10120902] = {
          ContentTC = "對了，8號小桶產出的《下水道維修手冊》裡寫過，下水道偶爾會招來一些喜歡溫暖潮濕的穢獸。",
          DialogueId = 10120902,
          GUID = "19562C7C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10118603,
          SpeakNpcId = 200011,
          Subtitle = "Wait... \"Sewers tend to attract Filthoids that love warm, damp places\" — I read about this in the Sewer Maintenance Manual from Bin No. 8.",
          VoiceName = "voice/$Locale$/story/1002/101209/19562C7C"
        },
        [10121001] = {
