          GUID = "19566DF2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(That board looks... off. Probably best not to step on it.)",
          VoiceName = "voice/$Locale$/story/1002/101213/19566DF2"
        },
        [10121302] = {
