          GUID = "19566DF4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = " I'm fine!  Ahem... I just wanted to, uh, check if this board was safe to step on.",
