        [10121603] = {
          Camera = "-1174.581055,810.613037,73.110962,0.0,0.0,-36.004082,40.0,851.326477,false,Manual,1.2",
          ContentTC = "瑪爾潔？你的屁股、膝蓋和腦袋還痛嗎？",
          DialogueId = 10121603,
          FinalCamera = "-1188.942383,790.815674,73.110962,0.0,0.0,-36.004082,40.0,851.326477,false,Manual,1.2",
          GUID = "19569F7E",
          NextDialogue = 10121604,
          SpeakNpcId = 100001,
          Subtitle = "Margie, how're your hips, knees, and head? Are you okay?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
