          GUID = "1956E0CA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "He probably ran into some Filthoids... We better stay sharp.",
          VoiceName = "voice/$Locale$/story/1002/101220/1956E0CA"
        },
        [10122101] = {
