          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "原來這裡探險的狩月人是用<H>引路燈</>和<H>指示牌</>為後面的人指引安全的道路嗎……",
          DialogueId = 10122302,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "1761.427734,411.505371,518.932861,0.000123,-12.201046,-168.596741,35.000008,464.479523,false,DoNotOverride,2.8",
          GUID = "1957122C",
          NextDialogue = 10122303,
          SpeakNpcId = 200006,
          Subtitle = "So this Phoxhunter used lamps and signposts to mark a safe path for those who come after them...?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101223/1957122C"
        },
        [10122303] = {
          Camera = "23.476318,138.433594,140.942383,0.000156,-2.000911,-106.794113,35.0,275.996185,false,Manual,2.8",
          ContentTC = "有餘力的話，我們也幫忙維護一下這些引路燈吧！",
          DialogueId = 10122303,
          FacialId = {
            [1] = "200006:Smile02"
          },
          FinalCamera = "32.779297,169.258789,142.067383,0.000156,-2.000911,-106.794113,35.000008,275.996185,false,DoNotOverride,2.8",
          GUID = "19571256",
          SpeakNpcId = 200006,
          Subtitle = "That's so kind. If we have the time, let's help maintain these lamps too!",
          TalkActionId = {
            [1] = "200006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101223/19571256"
        },
        [10122401] = {
          ContentTC = "燈又亮起來了耶~",
          DialogueId = 10122401,
          GUID = "1957226A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Yay, the lamp's glowing again~!",
          VoiceName = "voice/$Locale$/story/1002/101224/1957226A"
        },
        [10122402] = {
          ContentTC = "嗯，這樣大家應該就不會走錯路了吧。",
          DialogueId = 10122402,
          GUID = "19572294",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "This should make it easier for people to find their way.",
          VoiceName = "voice/$Locale$/story/1002/101224/19572294"
        },
        [10122501] = {
          ContentTC = "這樣一來就全部搞定啦，幹得漂亮！",
          DialogueId = 10122501,
          GUID = "195732D2",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Aaaand... all done! Nice work!",
          VoiceName = "voice/$Locale$/story/1002/101225/195732D2"
        },
        [10122601] = {
          ContentTC = "它好像很喜歡你呢，{nickname}。",
          DialogueId = 10122601,
          GUID = "1957433A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10122602,
          SpeakNpcId = 200006,
          Subtitle = "It seems to really like you, .",
          VoiceName = "voice/$Locale$/story/1002/101226/1957433A"
        },
        [10122602] = {
          ContentTC = "好可愛，讓我也摸一摸！",
          DialogueId = 10122602,
          GUID = "19574364",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Aww, it's so cute! I want to pet it too!",
          VoiceName = "voice/$Locale$/story/1002/101226/19574364"
        },
        [10122701] = {
          ContentTC = "「前有掠奪了很多財寶的穢獸，大家千萬不要靠近啊」－－告示牌寫好啦！",
          DialogueId = 10122701,
          GUID = "195753A2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10122702,
          SpeakNpcId = 200002,
          Subtitle = "\"Warning! Super scary treasure-hoarding Filthoids ahead! Do not approach!\" Pretty convincing, huh?",
          VoiceName = "voice/$Locale$/story/1002/101227/195753A2"
        },
        [10122702] = {
          ContentTC = "怎麼回事，總覺得更想去看看了……",
          DialogueId = 10122702,
          GUID = "195753CC",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...Are we sure a sign like this won't just make people more curious?",
          VoiceName = "voice/$Locale$/story/1002/101227/195753CC"
        },
        [10122801] = {
          ContentTC = "嗯？那些黃色的「刺」亮晶晶的，難道是……",
          DialogueId = 10122801,
          GUID = "1957640A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10122802,
          SpeakNpcId = 100001,
          Subtitle = "Those glowing yellow spikes... Could they be—",
          VoiceName = "voice/$Locale$/story/1002/101228/1957640A"
        },
        [10122802] = {
          ContentTC = "不是哦，恩里克叔叔說，群星綺晶是星星形狀的<H>紫色</>晶體……",
          DialogueId = 10122802,
          GUID = "19576434",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Probably not. Mr Henrik once said Crystallo of Stella is purple and shaped like stars.",
          VoiceName = "voice/$Locale$/story/1002/101228/19576434"
        },
        [10122901] = {
          ContentTC = "小心！！",
          DialogueId = 10122901,
          GUID = "19577472",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10122902,
          SpeakNpcId = 200006,
          Subtitle = "Watch out!!",
          VoiceName = "voice/$Locale$/story/1002/101229/19577472"
        },
        [10122902] = {
          ContentTC = "呼，還好沒事……咦，前面有路了！",
          DialogueId = 10122902,
          GUID = "1957749C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Phew... that was close. Wait... the path ahead is clear now!",
          VoiceName = "voice/$Locale$/story/1002/101229/1957749C"
        },
        [10123001] = {
          ContentTC = "對了，路上的那些引路燈是你點亮的，對吧？我替後面的狩月人謝謝你。",
          DialogueId = 10123001,
          GUID = "195784DA",
          NextDialogue = 10123002,
          Subtitle = "Those lamps along the path... that was you, wasn't it? Thoughtful of you — the other Phoxhunters will appreciate it.",
          VoiceName = "voice/$Locale$/story/1002/101230/195784DA"
        },
        [10123002] = {
          ContentTC = "這些小東西，就當是謝禮吧。",
          DialogueId = 10123002,
          GUID = "19578504",
          Subtitle = "Here — call it a thank-you gift.",
          VoiceName = "voice/$Locale$/story/1002/101230/19578504"
        },
        [10123101] = {
          ContentTC = "小僕從，快跟上來！",
          DialogueId = 10123101,
          GUID = "19579542",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10123102,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, hurry up!",
          VoiceName = "voice/$Locale$/story/1002/101231/19579542"
        },
        [10123102] = {
          ContentTC = "噓－－小點聲，讓他發現就不妙了。",
          DialogueId = 10123102,
          GUID = "1957956C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Shhh— Keep it down, or he will notice us.",
          VoiceName = "voice/$Locale$/story/1002/101231/1957956C"
        },
        [10123201] = {
          ContentTC = "都幾點了，接貨的怎麼還不來……",
          DialogueId = 10123201,
          GUID = "1957A5AA",
          Subtitle = "Ugh... What's taking him so long?",
          VoiceName = "voice/$Locale$/story/1002/101232/1957A5AA"
        },
        [10123301] = {
          ContentTC = "等等－－我們好像太近啦！",
          DialogueId = 10123301,
          GUID = "1957B612",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Wait—! We're way too close!",
          VoiceName = "voice/$Locale$/story/1002/101233/1957B612"
        },
        [10123401] = {
          ContentTC = "是你們？鬼鬼祟祟跟著我，想幹什麼？",
          DialogueId = 10123401,
          GUID = "1957C67A",
          IsBlack = 1,
          NextDialogue = 10123402,
          SpeakNpcId = 200005,
          Subtitle = "You again? Are you stalking me? What do you want?",
          VoiceName = "voice/$Locale$/story/1002/101234/1957C67A"
        },
        [10123402] = {
          ContentTC = "不不不不，我們只是回酒館路過的！",
          DialogueId = 10123402,
          GUID = "1957C6A4",
          IsBlack = 1,
          SpeakNpcId = 200002,
          Subtitle = "No, no! We were just, uh, heading back to the tavern! Total coincidence!",
          VoiceName = "voice/$Locale$/story/1002/101234/1957C6A4"
        },
        [10123403] = {
          ContentTC = "糟糕，被恩里克發現了！",
          DialogueId = 10123403,
          GUID = "10123403.0",
          IsBlack = 1,
          Subtitle = "Oh no... Henrik's spotted us!"
        },
        [10123404] = {
          ContentTC = "恩里克消失在了視線外……似乎是跟丟了。",
          DialogueId = 10123404,
          GUID = "1957C6A5",
          Subtitle = "Henrik has vanished... Looks like the trail has gone cold."
        },
        [10123405] = {
          ContentTC = "恩里克走進了一間花店，你們決定在一旁的咖啡廳稍作等待。",
          DialogueId = 10123405,
          GUID = "1957C6A6",
          Subtitle = "Henrik stepped into a flower shop, and you decided to wait at a nearby café."
        },
        [10123501] = {
          ContentTC = "慢慢走，排好隊——",
          DialogueId = 10123501,
          GUID = "1957D6E2",
          NextDialogue = 10123502,
          Subtitle = "Alright, kids~ Nice and slow, single file—",
          VoiceName = "voice/$Locale$/story/1002/101235/1957D6E2"
        },
        [10123502] = {
          ContentTC = "慢慢走，牽小手——",
          DialogueId = 10123502,
          GUID = "1957D70C",
          Subtitle = "Nice and slow, here we go~",
          VoiceName = "voice/$Locale$/story/1002/101235/1957D70C"
        },
        [10123601] = {
          ContentTC = "（恩里克停下了……得找個地方躲一下。）",
          DialogueId = 10123601,
          DisableMouth = 1,
          GUID = "1957E74A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(He stopped... We need to find a place to hide.)",
          VoiceName = "voice/$Locale$/story/1002/101236/1957E74A"
        },
        [10123602] = {
          ContentTC = "這玩意又壞了？！",
          DialogueId = 10123602,
          GUID = "1957E774",
          Subtitle = "Darn it... This thing's busted again!?",
          VoiceName = "voice/$Locale$/story/1002/101236/1957E774"
        },
        [10123701] = {
          ContentTC = "我有一個主意！我們藏在這個大傢伙裡面，就可以無聲無息地跟上去了！",
          DialogueId = 10123701,
          GUID = "1957F7B2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10123702,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, I've got an idea! We hide inside this big guy and follow him without making a sound!",
          VoiceName = "voice/$Locale$/story/1002/101237/1957F7B2"
        },
        [10123702] = {
          ContentTC = "那我問你，你要怎麼在士兵眼皮子底下鑽進去？",
          DialogueId = 10123702,
          GUID = "1957F7DC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10123703,
          SpeakNpcId = 100001,
          Subtitle = "...Then tell me how you're planning to sneak inside without the soldiers noticing?",
          VoiceName = "voice/$Locale$/story/1002/101237/1957F7DC"
        },
        [10123703] = {
          ContentTC = "這個……唔……誒，恩里克走了，快來快來！",
          DialogueId = 10123703,
          GUID = "1957F806",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10123501,
          SpeakNpcId = 200002,
          Subtitle = "Uh... well... um... Oh — look, Henrik's leaving! Let's go!",
          VoiceName = "voice/$Locale$/story/1002/101237/1957F806"
        },
        [10123801] = {
          ContentTC = "那家店……「牽念之花」，看名字好像是間花店。",
          DialogueId = 10123801,
          GUID = "1958081A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10123802,
          SpeakNpcId = 100001,
          Subtitle = "Flowers of Solicitude...? Looks like it's a flower shop.",
          VoiceName = "voice/$Locale$/story/1002/101238/1958081A"
        },
        [10123802] = {
          ContentTC = "他去買花了嗎……誒？！難道他是要去約會？",
          DialogueId = 10123802,
          GUID = "19580844",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "He went in there to buy flowers...? Wait—! Is he going on a date!?",
          VoiceName = "voice/$Locale$/story/1002/101238/19580844"
        },
        [10123901] = {
          ContentTC = "喂，你們兩個。",
          DialogueId = 10123901,
          GUID = "19581882",
          NextDialogue = 10123902,
          SpeakNpcName = "UI_Npc_Name_AlertWoker",
          Subtitle = "Hey, you two.",
          VoiceName = "voice/$Locale$/story/1002/101239/19581882"
        },
        [10123902] = {
          ContentTC = "對，就是你們兩個。你們倆，鬼鬼祟祟在人家屋頂坐著幹什麼？",
          DialogueId = 10123902,
          GUID = "195818AC",
          SpeakNpcName = "UI_Npc_Name_AlertWoker",
          Subtitle = "Yes, I'm talking to you. What exactly are you doing sneaking around on the roof?",
          VoiceName = "voice/$Locale$/story/1002/101239/195818AC"
        },
        [10123903] = {
          Camera = "-192.838379,86.913574,147.084473,0.000721,-6.203888,-37.222317,35.0,325.416962,false,Manual,1.997252",
          ContentTC = "哪有，我們明明是光明正大坐著看風景！你看今天晚上的太陽多好啊。",
          DialogueId = 10123903,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          GUID = "195818D6",
          NextDialogue = 10123904,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{200002},AnimationId{"Confident_End"},Duration{1}},
PlayAnimation{_delay{5},ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}},
CameraMoveTo{_delay{5.5},TargetPosition{"923.483887,-2454.475342,127.318726,0.000752,4.994986,122.379768,30.0,662.570679,false,Manual,1.997252"},duration{0}},
CameraMoveTo{_delay{5.6},TargetPosition{"884.15332,-2479.414307,127.318726,0.000752,4.994986,122.379768,30.0,662.570679,false,Manual,1.997252"},duration{4}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Sneaking around? Nah-uh! We're just admiring the lovely view! Look at that gorgeous sunlight—",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101239/195818D6"
        },
        [10123904] = {
          Camera = "56.511719,-167.835693,119.327148,0.000756,2.594707,118.379005,35.0,218.031204,false,Manual,3.0",
          ContentTC = "什麼太陽月亮的，我要修屋頂，麻煩讓一讓。",
          DialogueId = 10123904,
          GUID = "19581900",
          NextDialogue = 10123905,
          SpeakNpcName = "UI_Npc_Name_AlertWoker",
          Subtitle = "...It's nighttime. And I need to fix this roof. Move.",
          TalkActionId = {
            [1] = "200019:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101239/19581900"
        },
        [10123905] = {
          Camera = "-161.023438,20.044434,118.390259,0.000759,-2.805302,-37.617157,35.0,267.49585,false,Manual,3.0",
          ContentTC = "走吧。",
          DialogueId = 10123905,
          GUID = "1958192A",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Let's leave.",
          VoiceName = "voice/$Locale$/story/1002/101239/1958192A"
        },
        [10123906] = {
          ContentTC = "嗚嗚，我們好像跟丟了……",
          DialogueId = 10123906,
          GUID = "19581954",
          NextDialogue = 10123907,
          SpeakNpcId = 200002,
          Subtitle = "Aw... We totally lost him...",
          VoiceName = "voice/$Locale$/story/1002/101239/19581954"
        },
        [10123907] = {
          ContentTC = "去問問花店的店主碰碰運氣吧。",
          DialogueId = 10123907,
          GUID = "19581955",
          SpeakNpcId = 100001,
          Subtitle = "Let's check with the florist. Maybe they saw something.",
          VoiceName = "voice/$Locale$/story/1002/101239/19581955"
        },
        [10124000] = {
          ContentTC = "十分鍾後。",
          DialogueId = 10124000,
          GUID = "10124000.0",
          IsBlack = 1,
          Subtitle = "Ten minutes later."
        },
        [10124001] = {
          ContentTC = "你好你好！我們撿到一枚銀幣，是剛才那位叔叔掉的！我想還給他……",
          DialogueId = 10124001,
          GUID = "195828EA",
          NextDialogue = 10124002,
          SpeakNpcId = 200002,
          Subtitle = "Hello! We found this silver coin — pretty sure that man just dropped it! We wanted to return it to him...",
          VoiceName = "voice/$Locale$/story/1002/101240/195828EA"
        },
        [10124002] = {
          ContentTC = "咦，阿姨你怎麼在哭？不會是那傢伙說了什麼難聽話吧！",
          DialogueId = 10124002,
          GUID = "19582914",
          NextDialogue = 10124003,
          SpeakNpcId = 200002,
          Subtitle = "Wait— Are you crying? Did that guy say something mean to you?",
          VoiceName = "voice/$Locale$/story/1002/101240/19582914"
        },
        [10124003] = {
          ContentTC = "啊……沒有，眼睛裡進了紫露花的花粉而已。謝謝您。",
          DialogueId = 10124003,
          GUID = "1958293E",
          NextDialogue = 10124004,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "Ah... no, it's just some Dewiolet pollen in my eyes. Thank you for asking.",
          VoiceName = "voice/$Locale$/story/1002/101240/1958293E"
        },
        [10124004] = {
          ContentTC = "如果您說的是那位白衣服的先生，他現在……可能在東北方向的水潭那兒。",
          DialogueId = 10124004,
          GUID = "19582968",
          NextDialogue = 10124005,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "If you mean the gentleman in white... I believe he's by the pond, northeast of here.",
          VoiceName = "voice/$Locale$/story/1002/101240/19582968"
        },
        [10124005] = {
          ContentTC = "知道了，謝謝。",
          DialogueId = 10124005,
          GUID = "19582992",
          NextDialogue = 10124006,
          SpeakNpcId = 100001,
          Subtitle = "Got it. Thank you.",
          VoiceName = "voice/$Locale$/story/1002/101240/19582992"
        },
        [10124006] = {
          ContentTC = "等一下，您……",
          DialogueId = 10124006,
          GUID = "195829BC",
          NextDialogue = 10124007,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "Wait, you...",
          VoiceName = "voice/$Locale$/story/1002/101240/195829BC"
        },
        [10124007] = {
          ContentTC = "嗯？您叫我嗎？",
          DialogueId = 10124007,
          GUID = "195829E6",
          NextDialogue = 10124008,
          SpeakNpcId = 100001,
          Subtitle = "Hm? Are you talking to me?",
          VoiceName = "voice/$Locale$/story/1002/101240/195829E6"
        },
        [10124008] = {
          ContentTC = "……不，我也許認錯人了。抱歉……您收下這個吧。",
          DialogueId = 10124008,
          GUID = "19582A10",
          NextDialogue = 10124101,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "...No, I might have mistaken you for someone else. Sorry... Here, please take this.",
          VoiceName = "voice/$Locale$/story/1002/101240/19582A10"
        },
        [10124101] = {
          ContentTC = "這是……白送的？",
          DialogueId = 10124101,
          GUID = "19583952",
          NextDialogue = 10124102,
          SpeakNpcId = 100001,
          Subtitle = "You are giving me this... for free?",
          VoiceName = "voice/$Locale$/story/1002/101241/19583952"
        },
        [10124102] = {
          ContentTC = "嗯。您也有著紅寶石一樣的漂亮眼睛，與這朵紫露花很相稱……願您度過快樂的一天。",
          DialogueId = 10124102,
          GUID = "1958397C",
          NextDialogue = 10124103,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          Subtitle = "That's right. Your eyes sparkle like rubies, perfectly matching this flower... I hope you have a lovely day.",
          VoiceName = "voice/$Locale$/story/1002/101241/1958397C"
        },
        [10124103] = {
          ContentTC = "謝謝，那我就收下了。",
          DialogueId = 10124103,
          GUID = "195839A6",
          NextDialogue = 10124104,
          SpeakNpcId = 100001,
          Subtitle = "Thank you. Then... I'll gladly accept it.",
          VoiceName = "voice/$Locale$/story/1002/101241/195839A6"
        },
        [10124104] = {
          ContentTC = "竟然有意外收穫？小僕從真是魅力非凡！",
          DialogueId = 10124104,
          GUID = "195839D0",
          SpeakNpcId = 200002,
          Subtitle = "Whoa, a gift from a stranger? My Little Minion is way too charming!",
          VoiceName = "voice/$Locale$/story/1002/101241/195839D0"
        },
        [10124201] = {
          ContentTC = "應該就是這個水潭了……他果然在！",
          DialogueId = 10124201,
          GUID = "195849BA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "This should be the place... Yep, there he is!",
          VoiceName = "voice/$Locale$/story/1002/101242/195849BA"
        },
        [10124301] = {
          ContentTC = "這一定就是他的驚天大秘密！只是，這麼冷的水，就算是卡戎之民，下去撈也會著涼吧？",
          DialogueId = 10124301,
          GUID = "19585A22",
          NextDialogue = 10124302,
          Subtitle = "This has gotta be his horrible secret! But... that water's freezing. Even for a Charon, jumping in could be a bad idea.",
          VoiceName = "voice/$Locale$/story/1002/101243/19585A22"
        },
        [10124302] = {
          ContentTC = "那就只能交給萬能的皎皎了！白豁出去了－－欸，小僕從你這是在……",
          DialogueId = 10124302,
          GUID = "19585A4C",
          NextDialogue = 10124303,
          Subtitle = "Looks like the all-powerful Lunarian has to step in! Alright, I'll take this one for you— Wait, Little Minion, what are you doing...?",
          VoiceName = "voice/$Locale$/story/1002/101243/19585A4C"
        },
        [10124303] = {
          ContentTC = "只要這樣改裝一下釣竿……嗯，好了。",
          DialogueId = 10124303,
          GUID = "19585A76",
          NextDialogue = 10124304,
          Subtitle = "Just need to tweak the fishing rod a little... There. All set.",
          VoiceName = "voice/$Locale$/story/1002/101243/19585A76"
        },
        [10124304] = {
          ContentTC = "交給我吧。只要是水裡的，就算是鯊魚，我也能釣上來。",
          DialogueId = 10124304,
          GUID = "19585AA0",
          Subtitle = "I got this. If it's in the water, whether it's treasure or a shark, I'll reel it in.",
          VoiceName = "voice/$Locale$/story/1002/101243/19585AA0"
        },
        [10124401] = {
          ContentTC = "天啊，小僕從，莫非你就是艾利西安掌管水產的神？",
          DialogueId = 10124401,
          GUID = "19586A8A",
          NextDialogue = 10124402,
          Subtitle = "No way... Little Minion, are you actually the Elysian God of Fishing!?",
          VoiceName = "voice/$Locale$/story/1002/101244/19586A8A"
        },
        [10124402] = {
          ContentTC = "用石塊壘起的石堆，旁邊放著一束白花。看起來似乎有著某種紀念意義。",
          DialogueId = 10124402,
          GUID = "19586AB4",
          NextDialogue = 10124403,
          Subtitle = "A small cairn, carefully stacked. A bouquet of white flowers rests beside it, as if left in quiet remembrance.",
          VoiceName = "voice/$Locale$/story/1002/101244/19586AB4"
        },
        [10124403] = {
          ContentTC = "你看你看，這花像不像恩里克從花店買的那束？",
          DialogueId = 10124403,
          GUID = "19586ADE",
          Subtitle = "Ooh! Look! Doesn't this bouquet look just like the one Henrik bought at the flower shop?",
          VoiceName = "voice/$Locale$/story/1002/101244/19586ADE"
        },
