          VoiceName = "voice/$Locale$/story/1002/101306/195BD037"
        },
        [10130604] = {
          ContentTC = "穢獸異常凶險，雖然它現在停止了攻擊，但很可能只是暫時休眠。你們盡快去城內避難，這裡交給衛戍部隊應付。",
          DialogueId = 10130604,
          GUID = "195BD038",
          NextDialogue = 10113038,
          SpeakNpcId = 100304,
          Subtitle = "The Filthoid is highly dangerous. Although it's ceased attacking, it may only be in temporary dormancy. Return to the city immediately — the Escort will take it from here.",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101306/195BD038"
        },
        [10130605] = {
          Camera = "-161.636719,-90.765625,127.488281,0.00052,4.203223,-9.400385,35.0,132.664047,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "……不必了，長官。您出手之前，我們就已經解決了。您也無需再浪費子彈了。",
          DialogueId = 10130605,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "-161.636719,-90.765625,127.488281,0.000524,4.003215,-14.402719,35.0,319.412994,false,Manual,3.0",
          GUID = "195BD039",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "100304:n(200021)"
          },
          NextDialogue = 10113039,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200021},AnimationId{"Talk02_Start"},Duration{1}},
LookAt{_delay{1},LookAtDescription{"100001:n(200021)"}},
CameraMoveTo{_delay{3},TargetPosition{"-42.216797,-134.367188,154.807617,0.000533,-0.196989,-13.007848,35.0,126.183968,false,Manual,3.0"},duration{0}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "No need, ma'am. We took care of it before you got here. No point wasting more bullets.",
          TalkActionId = {
