          VoiceName = "voice/$Locale$/story/1002/110115/1B90EE8C"
        },
        [11011503] = {
          ContentTC = "好，要塞內大部分的自衛武器都被關停了，其他小隊應該會好過些。",
          DialogueId = 11011503,
          Duration = 3,
          GUID = "1B90EEB6",
          NextDialogue = 11011504,
          Scripts = [[
PARA{
