          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9121E6"
        },
        [11011816] = {
          Camera = "-321.081055,224.484375,96.840698,0.000115,5.19998,-80.196815,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "……我的好兄弟被你們豢養的怪物害死了。既然你提醒，那就在你身上開幾個洞，給他抵命吧。",
          DialogueId = 11011816,
          FinalCamera = "-314.964844,189.072266,100.109863,0.000115,5.19998,-80.196815,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912210",
          LookAt = {
            [1] = "110016:n(110017)",
            [2] = "110017:n(110016)"
          },
          NextDialogue = 11011817,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"110016:p(30)"}},
LookAt{_delay{0.7},LookAtDescription{"110016:n(110017)"}}
}]],
          SpeakNpcId = 110016,
          Subtitle = "...Your pet Filthoids killed a close buddy of mine. Reminded me just now — I ought to carve a few holes in you to honour his memory.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912210"
        },
        [11011817] = {
          Camera = "-422.004883,397.472656,125.112305,0.000134,-3.599892,-71.590111,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentTC = "住手。",
