          SpeakNpcId = 110017,
          SpeakNpcName = "UI_Npc_OldKarong",
          Subtitle = "Come back, Katya! Don't be silly!",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110118/1B9122E2"
        },
        [11011822] = {
          Camera = "-372.461914,137.933594,112.566528,0.000149,-3.400143,-71.792755,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "長官，我們雖然是卡戎之民，但我們不是神棄者同盟的成員。我們只是附近小鎮再本分不過的普通人。",
          DialogueId = 11011822,
          FinalCamera = "-372.461914,137.933594,121.304565,0.000149,-3.400143,-71.792755,30.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91230C",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11018302,
          Scripts = "SetLocation{ActorId{110017},TargetPoint{\"Fix11_Set\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110034,
          Subtitle = "Sir, we may be Charons but we are not part of The Forsakens. We're just ordinary folk living in a town nearby.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110016:n(110034)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B91230C"
        },
        [11011824] = {
          Camera = "-474.881836,186.248047,147.918213,0.00014,-7.60077,-47.196186,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "開什麽玩笑——同盟對自己的同胞下手？",
          DialogueId = 11011824,
          GUID = "1B912360",
          NextDialogue = 11018401,
          SpeakNpcId = 110016,
          Subtitle = "You can't be serious — The Forsakens are enslaving their own people?",
          VoiceName = "voice/$Locale$/story/1002/110118/1B912360"
        },
        [11011826] = {
          Camera = "-203.332031,-139.333984,134.157104,0.00013,-4.800441,125.003876,35.000008,391.636871,false,Manual,2.8",
          ContentTC = "…………",
          DialogueId = 11011826,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9123B4",
          LookAt = {
            [1] = "110022:n(110034)"
          },
          NextDialogue = 11011827,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9123B4"
        },
        [11011827] = {
          Camera = "-397.019531,164.720703,139.713013,0.000156,-7.600183,-69.580688,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "弗蘭克爺爺是我的恩人。",
          DialogueId = 11011827,
          GUID = "1B9123DE",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11011828,
          SpeakNpcId = 110034,
          Subtitle = "Mr Frank saved my life.",
          VoiceName = "voice/$Locale$/story/1002/110118/1B9123DE"
        },
        [11011828] = {
          ContentTC = "幾天前，我只是肚子痛歇息了一會兒，就被同盟的畜生毒打了幾十鞭子。奄奄一息的時候，是爺爺給了我水和食物，還有這條破袍子。",
          DialogueId = 11011828,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B912408",
          NextDialogue = 11011829,
          SpeakNpcId = 110034,
          Subtitle = "Just a few days ago, I had to take a break because my stomach was acting up, but those Forsaken rotters whipped me dozens of times and left me for dead. It was Mr Frank who gave me water, food, and this ragged robe to cover me up.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912408"
        },
        [11011829] = {
          Camera = "-180.152344,-181.611328,153.236694,0.000139,-8.80102,119.82122,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "如果不是他好心，我那個時候就已經斷氣了。所以，我願意替他抵命——請對我開槍吧。但是爺爺他是真心想幫您的，因為我們同您一樣無法原諒同盟的惡行。",
          DialogueId = 11011829,
          FacialId = {
            [1] = "110034:None"
          },
          FinalCamera = "-188.547852,-186.429688,153.236694,0.000147,-8.80102,119.82122,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912432",
          LookAt = {
            [1] = "110034:n(110022)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11011830,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{\"-334.542969,94.224609,124.2948,0.000144,-1.4012,-78.373749,35.000011,142.471191,false,Manual,2.8\"},duration{0}}",
          SpeakNpcId = 110034,
          Subtitle = "I would have died if not for Mr Frank. So if you must shoot him, could you please shoot me instead? He just wants to help, because none of us can forgive what The Forsakens did to us.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912432"
        },
        [11011830] = {
          Camera = "-340.931641,528.488281,131.870483,0.000145,-6.201326,-90.573792,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "地下水道四通八達，你們自己一定會迷路。爺爺經常被使喚去修理水閥，他對那邊很熟悉。如果您放他一條生路，他就可以帶你們去你們要去的地方。",
          DialogueId = 11011830,
          FinalCamera = "-326.59082,528.347656,131.870483,0.000145,-6.201326,-90.573792,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91245C",
          NextDialogue = 11011831,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110034:n(110043)"}},
LookAt{_delay{2},LookAtDescription{"110034:n(110022)"}}
}]],
          SpeakNpcId = 110034,
          Subtitle = "The sewer tunnels are like a maze. You'd easily get lost without help. The Forsakens always get Mr Frank to fix the sewer valves, so he knows the place like the back of his hand. Let him live and he'll get you where you need to go.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91245C"
        },
        [11011831] = {
          Camera = "-181.973633,-155.728516,141.303955,0.000168,-6.001311,124.018631,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "行了。馬爾科，放下槍——放下，這是命令。",
          DialogueId = 11011831,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912486",
          LookAt = {
            [1] = "110022:n(110016)",
            [2] = "110043:n(110022)"
          },
          NextDialogue = 11011832,
          Scripts = "SetLocation{ActorId{110034},TargetPoint{\"pKajiaset\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110022,
          Subtitle = "Alright. Marco, lower your gun — Holster it, that's an order.",
          TurnTo = {
            [1] = "110016:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912486"
        },
        [11011832] = {
          ContentTC = "萊昂，搜身。",
          DialogueId = 11011832,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9124B0",
          LookAt = {
