          ContentTC = "這句話可能對你很重要哦，確定不聽？",
          DialogueId = 11012458,
          Duration = 3,
          FinalCamera = "-27.294617,-48.557129,139.083374,0.000238,0.800252,66.985054,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918B64",
          NextOptions = {
            [1] = 11012462,
            [2] = 11012459
          },
          SpeakNpcId = 110009,
          Subtitle = "It may be extremely important to you. You sure you don't want to hear it?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918B64",
          bForbidSkipOptions = true
        },
        [11012459] = {
