          NextDialogue = 11012725,
          Scripts = "CameraMoveTo{_delay{6},TargetPosition{\"-59.618256,69.88916,100.448547,0.000189,-0.199339,64.083984,30.0,138.022522,false,Manual,8.0\"},duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "...Well, since we have , maybe {性别2:he|she} does have what it takes to lead us to victory.",
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B708"
        },
        [11012725] = {
          Camera = "431.175476,-72.250488,84.118408,0.000063,-1.799133,150.597992,30.0,501.809082,false,DoNotOverride,5.0",
          ContentTC = "嗯。準備好，我們就出發吧。",
          DialogueId = 11012725,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "423.409973,-86.030762,84.118408,0.000063,-1.799133,150.597992,30.0,501.809082,false,DoNotOverride,5.0",
          GUID = "1B91B732",
          NextDialogue = 11012726,
          SpeakNpcId = 110022,
          Subtitle = "Alright, prepare yourselves. We set off together.",
          TalkActionId = {
