          GUID = "1B91C47C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(A photo? Maybe I should have a look around for it when I can.)",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C47C"
        },
        [11012807] = {
          ContentTC = "到底掉哪兒去了……",
          DialogueId = 11012807,
          Duration = 3,
          GUID = "1B91C4A6",
          NextDialogue = 11012808,
          SpeakNpcId = 110010,
          Subtitle = "Where could it be...?",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C4A6"
        },
        [11012808] = {
          ContentTC = "嗯？地上那個好像就是……",
          DialogueId = 11012808,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C4D0",
          SpeakNpcId = 110022,
          Subtitle = "Hmm? What's that on the floor...?",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C4D0"
        },
        [11012809] = {
          ContentTC = "這是，年輕時的老師和……達芙涅？",
          DialogueId = 11012809,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Ex01_Pic.T_Guide_Ex01_Pic'}",
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C4FA",
          NextDialogue = 11012810,
          SpeakNpcId = 110022,
          Subtitle = "It's a younger Sir Avar with… Daphne?",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C4FA"
        },
        [11012810] = {
          ContentTC = "把照片交還給阿瓦爾老師吧。",
          DialogueId = 11012810,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C524",
          SpeakNpcId = 110022,
          Subtitle = "I should take it back to Sir Avar.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C524"
        },
        [11012811] = {
          Camera = "-265.872223,895.02594,147.338562,0.0,-4.599914,-87.177261,40.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "對了，我剛才撿到了這個……",
          DialogueId = 11012811,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C54E",
          LookAt = {
            [1] = "110022:n(110010)"
          },
          NextDialogue = 11012812,
          SpeakNpcId = 110022,
          Subtitle = "Sir, I found this...",
          TalkActionId = {
            [1] = "110022:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C54E"
        },
        [11012812] = {
          Camera = "-328.606415,569.80426,140.777832,0.000147,1.196164,62.629292,45.000027,100000.0,false,DoNotOverride,22.0",
          ContentTC = "哦！居然給你撿到了，謝啦。",
          DialogueId = 11012812,
          Duration = 0,
          GUID = "1B91C578",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012813,
          SpeakNpcId = 110010,
          Subtitle = "Oh, you found it! Thanks for bringing it back.",
          TalkActionId = {
            [1] = "110010:AgreeHead"
          },
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C578"
        },
        [11012813] = {
          Camera = "-260.496735,740.469788,158.7724,0.0,-7.403351,-102.964378,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentTC = "原來達芙涅她是您的……",
          DialogueId = 11012813,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C5A2",
          NextDialogue = 11012814,
          SpeakNpcId = 110022,
          Subtitle = "So, is Daphne your...",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C5A2"
        },
        [11012814] = {
          Camera = "-338.607697,582.601135,144.446533,0.00001,-0.600339,55.421577,30.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "啊，哦，她是從前鄰居家的小姑娘啊，哈哈……",
          DialogueId = 11012814,
          Duration = 0,
          GUID = "1B91C5CC",
          NextDialogue = 11012815,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110010},AnimationId{"Talk01_Start"},Duration{3}},
PlayAnimation{ActorId{110010},AnimationId{"Talk01_End"},Duration{2}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Oh, ah... She is just my neighbour's little girl. Haha...",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C5CC"
        },
        [11012815] = {
          Camera = "-886.352966,1603.910889,46.242737,0.000051,3.001615,-53.771996,35.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "……算了，不瞞你了。達芙涅是我女兒，你沒猜錯。",
          DialogueId = 11012815,
          Duration = 3,
          FinalCamera = "-876.272766,1611.296143,46.242737,0.000051,3.001615,-53.771996,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C5F6",
          NextDialogue = 11012816,
          Scripts = "PlayAnimation{_delay{2},ActorId{110010},AnimationId{\"Talk01_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "...I suppose it's time for the truth — You're right. Daphne is my daughter.",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C5F6"
        },
        [11012816] = {
          Camera = "-579.131714,395.651031,126.424561,0.000006,0.999987,44.224258,45.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "說起來還挺不好意思的，這是我跟那孩子一起拍的最後一張照片……那之後沒多久，她母親就帶著她離開了。「塞奧多爾」這個姓氏，是她母親的。",
          DialogueId = 11012816,
          Duration = 3,
          FinalCamera = "-587.124695,403.863434,126.424561,0.000006,0.999987,44.224018,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C620",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11012817,
          Scripts = [[
SEQ{
PlayAnimation{_delay{6},ActorId{110010},AnimationId{"Sigh_End"},Duration{0}},
PlayAnimation{_delay{2},ActorId{110010},AnimationId{"Talk01_Start"},Duration{4}},
PlayAnimation{ActorId{110010},AnimationId{"Talk01_End"},Duration{0}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "This is the last photo we took together before she and her mother left. Daphne took the last name \"Theodore\" from her mother.",
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C620"
        },
        [11012817] = {
          Camera = "-280.927521,1211.751587,190.038452,0.000039,-7.600156,-85.574547,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentTC = "不過這件事你別說出去啊，我們就是為了不讓人知道達芙涅是我女兒，才離婚的。",
          DialogueId = 11012817,
          Duration = 3,
          FinalCamera = "-270.015259,1212.595337,190.038452,0.000039,-7.600156,-85.574547,45.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C64A",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012818,
          Scripts = "PlayAnimation{_delay{4},ActorId{110010},AnimationId{\"Talk02_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "Don't tell anyone about this. We divorced specifically to keep people from knowing that Daphne is my daughter.",
          TalkActionId = {
            [1] = "110010:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C64A"
        },
        [11012818] = {
          Camera = "-331.020386,571.073792,139.486084,0.000067,0.800628,61.435661,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "當年首席煉金術師很喜歡達芙涅，說她會成為未來帝國最優秀的煉金術師。那時她早已宣布不再招收學生，卻為這孩子破例了。",
          DialogueId = 11012818,
          Duration = 3,
          FinalCamera = "-324.280945,583.456116,139.682922,0.000067,0.800628,61.435661,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C674",
          NextDialogue = 11012819,
          SpeakNpcId = 110010,
          Subtitle = "Back then, the chief alchemist thought the world of Daphne. She believed Daphne had what it took to become the Empire's finest. She'd long since stopped taking apprentices — but for Daphne, she made an exception.",
          TalkActionId = {
            [1] = "110022:Talk03_End",
            [2] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C674"
        },
        [11012819] = {
          Camera = "-256.828491,929.640686,152.787537,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "因為達芙涅是個天才？",
          DialogueId = 11012819,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C69E",
          NextDialogue = 11012820,
          SpeakNpcId = 110022,
          Subtitle = "Because of Daphne's talent?",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110010:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C69E"
        },
        [11012820] = {
          Camera = "-350.142548,666.156311,140.458618,0.000062,2.999812,49.027782,45.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "她確實在煉金術上很有天賦，但佩劍煉金院那種地方，最不缺的就是天才。首席煉金術師說，達芙涅是特別的，因為她擁有一些其他煉金術師沒有的東西。",
          DialogueId = 11012820,
          Duration = 3,
          FinalCamera = "-340.031555,677.799377,141.266479,0.000062,2.999812,49.027782,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C6C8",
          NextDialogue = 11012821,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8},TargetPosition{"-1224.551514,-56.273621,90.468933,-1.0,0.200131,36.623306,35.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-1236.708984,-39.920101,90.824463,-1.0,0.200131,36.623306,35.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "She's talented, but it's more than that. The Spathatoi is never short on talent. The chief alchemist said Daphne has a unique gift that sets her apart.",
          TalkActionId = {
            [1] = "110010:Talk03_Start",
            [2] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6C8"
        },
        [11012821] = {
          Camera = "-386.329163,1674.61145,67.646606,0.0,4.599599,-79.570862,35.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "這些話我也沒聽太明白，但有一點是明確的，達芙涅有很好的前途。所以，絕對不能有一個卡戎父親阻礙她的道路。",
          DialogueId = 11012821,
          Duration = 3,
          FinalCamera = "-386.329163,1674.61145,41.897461,0.0,4.599599,-79.570862,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C6F2",
          NextDialogue = 11012834,
          Scripts = [[
SEQ{
PlayAnimation{_delay{2},ActorId{110010},AnimationId{"Talk03_End"},Duration{2}},
PlayAnimation{_delay{4},ActorId{110010},AnimationId{"Talk02_Start"},Duration{6}},
PlayAnimation{ActorId{110010},AnimationId{"Talk02_End"},Duration{0}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "I never quite understood what she meant, but it's clear Daphne has a bright future ahead of her. And having a Charon for a father shouldn't be what holds her back.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F2"
        },
        [11012822] = {
          Camera = "-616.148438,313.40152,101.787903,0.000002,0.999468,49.427162,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "達芙涅知道嗎？",
          DialogueId = 11012822,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-576.944153,359.186676,102.839539,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C71C",
          NextDialogue = 11012823,
          SpeakNpcId = 110022,
          Subtitle = "Does Daphne know?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C71C"
        },
        [11012823] = {
          Camera = "-319.142975,642.300842,140.458618,0.00007,3.399658,61.429241,45.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "不知道。她打小心思就單純，也很黏我，怎麽能告訴她這個。",
          DialogueId = 11012823,
          Duration = 3,
          FinalCamera = "-305.392487,667.551331,142.16687,0.00007,3.399658,61.429241,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C746",
          NextDialogue = 11012824,
          SpeakNpcId = 110010,
          Subtitle = "No. She has a heart of gold and adores her old man. How can I tell her?",
          TalkActionId = {
            [1] = "110010:DisagreeHead"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C746"
        },
        [11012824] = {
          ContentTC = "所以我就裝作是一個拋妻棄女的壞父親，她走在路上叫我爸爸，我就會跟她說，「閉嘴，叫什麽爸爸、套什麽近乎呢，叫長官。」",
          DialogueId = 11012824,
          Duration = 3,
          GUID = "1B91C770",
          NextDialogue = 11012825,
          Scripts = [[
PARA{
PlayAnimation{_delay{15},ActorId{110022},AnimationId{"Talk03_End"},Duration{0}},
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"-256.828491,929.640686,152.787537,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-256.535095,917.831116,151.587341,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}}]],
          SpeakNpcId = 110010,
          Subtitle = "So, I play the part of a bad father who's done with family life. And when Daphne calls me dad, I tell her, \"Zip it. I'm not your father. Address me as your superior officer.\"",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C770"
        },
        [11012825] = {
          Camera = "-288.338318,672.926819,122.673157,0.000056,11.399967,65.427414,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentTC = "可她還是太懂事了，連罵我的話都罵不出口，只能和自己鬧別扭。",
          DialogueId = 11012825,
          Duration = 3,
          GUID = "1B91C79A",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextOptions = {
            [1] = 11012826,
            [2] = 11012829
          },
          SpeakNpcId = 110010,
          Subtitle = "But Daphne's such a sweet kid. She couldn't bring herself to curse at me, and always ended up blaming herself instead.",
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C79A"
        },
        [11012826] = {
          ContentTC = "她其實並不喜歡煉金院。您和夫人應該考慮一下她的想法。",
          DialogueId = 11012826,
          GUID = "1B91C7C4",
          NextDialogue = 11012827,
          Subtitle = "Actually, she doesn't like the Academy. Perhaps you and the missus should also take her preferences into consideration."
        },
        [11012827] = {
          Camera = "-604.107727,306.536285,101.833496,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "我已經知道了。這次她非要轉到龍莎特別行動隊來，還瞞過她母親和我，直接向富爾維斯遞交申請，可見她是真的不想待在煉金院了。",
          DialogueId = 11012827,
          Duration = 3,
          FinalCamera = "-622.919128,319.203278,101.787903,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C7EE",
          NextDialogue = 11012828,
          SpeakNpcId = 110010,
          Subtitle = "I knew about that already. She volunteered for the Lonza Fortress op — even went straight to Fulvis with the paperwork, without telling either of us. That girl had her mind made up from the start.",
          TalkActionId = {
            [1] = "110010:AgreeHead",
            [2] = "110010:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C7EE"
        },
        [11012828] = {
          Camera = "-264.298615,914.238342,151.455444,0.000002,-5.799711,-85.974731,35.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "……等回去，我和她母親好好談談吧。",
          DialogueId = 11012828,
          Duration = 3,
          GUID = "1B91C818",
          NextDialogue = 11012830,
          SpeakNpcId = 110010,
          Subtitle = "...I'll talk to her mother about this when we return.",
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C818"
        },
        [11012829] = {
          ContentTC = "您也犧牲了很多……辛苦了。",
          DialogueId = 11012829,
          GUID = "1B91C842",
          NextDialogue = 11012830,
          Subtitle = "You've made a huge sacrifice... You're a good father."
        },
        [11012830] = {
          Camera = "-288.338318,672.926819,122.673157,0.000055,11.399967,65.427475,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentTC = "……我倒是希望她再多記恨我一些，至少這樣，她自己會好過點。",
          DialogueId = 11012830,
          Duration = 3,
          GUID = "1B91C86C",
          NextDialogue = 11012831,
          SpeakNpcId = 110010,
          Subtitle = "...I'd rather she resent me if it spares her any pain.",
          TalkActionId = {
            [1] = "110010:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C86C"
        },
        [11012831] = {
          Camera = "-604.107727,306.536285,101.833496,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentTC = "唉，要是能回去的話，就請她去看戲吧。我是個大頭兵出身，以前從沒陪她進過歌劇院，就當把小時候的份也一起補上吧。",
          DialogueId = 11012831,
          Duration = 3,
          FinalCamera = "-622.919128,319.203278,101.787903,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C896",
          NextDialogue = 11012832,
          Scripts = "PlayAnimation{_delay{7},ActorId{110010},AnimationId{\"Confident_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "If we make it back, I'll take her to the opera house. When I was just a grunt, I never got the chance to take her to any fancy places. I guess it's time to make it up to her.",
          TalkActionId = {
            [1] = "110010:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C896"
        },
        [11012832] = {
          Camera = "-324.594086,581.971741,140.384827,0.000062,1.799953,62.62788,45.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "聽說迪斯瑪尼亞最近新上了一出戲，從北邊科賽托斯那邊傳來的，叫雪國什麽什麽……到時候我多買一張票，你也一起吧。",
          DialogueId = 11012832,
          Duration = 3,
          FinalCamera = "-320.052155,590.743225,140.695251,0.000062,1.799953,62.62788,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C8C0",
          NextDialogue = 11012833,
          SpeakNpcId = 110010,
          Subtitle = "I heard there's a new show in Dismania, coming from the northern province of Cocytus. It's called \"something... from the Snowfield\"... You know what — why don't you come along? I'll buy an extra ticket.",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C8C0"
        },
        [11012833] = {
          Camera = "-258.992004,740.77594,158.750488,1.000006,-7.603387,-103.364433,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentTC = "好。",
          DialogueId = 11012833,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C8EA",
          SpeakNpcId = 110022,
          Subtitle = "Sure.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C8EA"
        },
        [11012834] = {
          ContentTC = "可老師是<H>桂冠卡戎</>——和其他卡戎之民不一樣。",
          DialogueId = 11012834,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C6F3",
          NextDialogue = 11012835,
          RelatedWikiId = {
            [1] = 407003
          },
          SpeakNpcId = 110022,
          Subtitle = "But Sir Avar... you're not just any Charon — you're a Laurelled Charon.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F3"
        },
        [11012835] = {
          ContentTC = "也沒什麼不一樣的。時代變了，現在從元老院和軍團內部，到處都有人質疑桂冠卡戎的忠誠。",
          DialogueId = 11012835,
          Duration = 3,
          GUID = "1B91C6F4",
          NextDialogue = 11012836,
          SpeakNpcId = 110010,
          Subtitle = "Doesn't make much difference these days. Even in the Senate, even in the Legion — people have started to question where our loyalties lie.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F4"
        },
        [11012836] = {
          ContentTC = "指不定哪天一紙敕令下來，我們這些人就要回老家嘍。如果真有這麼一天，達芙涅的前程也可能受牽連……她母親是這麼想的。",
          DialogueId = 11012836,
          Duration = 3,
          GUID = "1B91C6F5",
          NextDialogue = 11012822,
          SpeakNpcId = 110010,
          Subtitle = "Wouldn't surprise me if one day an edict comes down and we all get sent back where we came from. If it comes to that... Daphne's future might go down with mine. Or so her mother feared.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F5"
        },
        [11012901] = {
          ContentTC = "是強敵，留意！",
          DialogueId = 11012901,
          Duration = 3,
          GUID = "1B91D412",
          SpeakNpcId = 110010,
          Subtitle = "This one is tough to deal with. Be cautious!",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D412"
        },
        [11012902] = {
          Camera = "355.686127,-321.117188,61.902191,0.000327,6.602033,105.412376,28.000011,288.624115,false,Manual,6.072517",
          ContentTC = "有埋伏！仔細防禦！",
          DialogueId = 11012902,
          FacialId = {
            [1] = "110010:Unhappy01"
          },
          FinalCamera = "317.624207,-183.041016,86.944946,0.000327,6.602033,105.412376,28.000011,139.773468,false,Manual,6.072517",
          GUID = "1B91D43C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 11012903,
          SpeakNpcId = 110010,
          Subtitle = "It's an ambush! Defend yourselves!",
          TalkActionId = {
            [1] = "110010:Angry02_Start",
            [2] = "110022:Explain02_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D43C"
        },
        [11012903] = {
          Camera = "-1147.589233,1035.804688,431.601532,0.000327,-8.59737,-43.590466,28.000006,667.895142,false,DoNotOverride,6.072517",
          ContentTC = "等等——機關，沒有啟動？",
          DialogueId = 11012903,
          FinalCamera = "-1147.589233,1035.804688,431.601532,0.000338,-9.796847,-36.989296,28.000006,667.895142,false,DoNotOverride,6.072517",
          GUID = "1B91D466",
          LookAt = {
            [1] = "110010:p(fix17_3)",
            [2] = "110022:p(fix1703)"
          },
          NextDialogue = 11012904,
          SpeakNpcId = 110010,
          Subtitle = "Wait... The defence system here is off?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D466"
        },
        [11012904] = {
          Camera = "-1936.596191,338.285156,1372.406128,0.000417,-36.596905,43.408157,14.543221,667.895142,false,DoNotOverride,6.072517",
          ContentTC = "中央控製室空無一人……同盟的「信使」已經撤離了？",
          DialogueId = 11012904,
          FinalCamera = "-1936.596191,338.285156,1245.097656,0.000417,-36.596905,43.408157,14.543221,667.895142,false,DoNotOverride,6.072517",
          GUID = "1B91D490",
          LookAt = {
            [1] = "110010:n(110010)",
            [2] = "110022:n(110022)"
          },
          NextDialogue = 11012905,
          SpeakNpcId = 110010,
          Subtitle = "The central control room is empty... Has the Messenger left already?",
          TalkActionId = {
            [1] = "110010:Angry02_End",
            [2] = "110022:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D490"
        },
        [11012905] = {
          Camera = "-465.542786,485.144531,216.598389,0.000173,-9.999267,-36.987988,28.000008,667.895142,false,Manual,6.072517",
          ContentTC = "{nickname2}，這裡不太對勁。按要塞原始的設計圖，中央控製室作為核心，擁有最頂尖的防禦系統，甚至配備了自毀裝置。",
          DialogueId = 11012905,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-487.617737,455.832031,216.598389,0.000173,-9.999267,-36.987988,28.000008,667.895142,false,Manual,6.072517",
          GUID = "1B91D4BA",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012906,
          Scripts = "PlayAnimation{_delay{2},ActorId{110010},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 110010,
          Subtitle = ", something's off here. The original blueprints of the fortress show this room should have the strongest defence system, including a self-destruct mechanism.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "110010:n(110022)",
            [2] = "110022:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D4BA"
        },
        [11012906] = {
          Camera = "27.647247,-73.736328,81.884186,0.000202,3.20034,2.81273,28.000008,239.526123,false,Manual,10.489336",
          ContentTC = "但現在……雖然門被鎖上了，但沒有任何防禦裝置啟動的跡象。你怎麽看？",
          DialogueId = 11012906,
          GUID = "1B91D4E4",
          NextOptions = {
            [1] = 11012907,
            [2] = 11012910
          },
          SpeakNpcId = 110010,
          Subtitle = "But they've only locked the door, and there's no sign of any defence systems engaging. What do you make of this?",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D4E4"
        },
        [11012907] = {
          ContentTC = "這是讓我們懈怠的招數，一定還有其他陷阱。",
          DialogueId = 11012907,
          GUID = "1B91D50E",
          NextDialogue = 11012908,
          Subtitle = "Probably a ruse to lower our guard. There might be other traps."
        },
        [11012908] = {
          Camera = "331.160645,61.759766,124.87442,0.0002,-8.599856,-136.788193,28.000008,242.574921,false,Manual,10.489336",
          ContentTC = "他們也許預料到了我們來這兒會格外慎重，所以陷阱也布置得很隱蔽？",
          DialogueId = 11012908,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91D538",
          NextDialogue = 11012909,
          SpeakNpcId = 110022,
          Subtitle = "They probably predicted we would be extra cautious around this place, so they cleverly concealed their real traps.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D538"
        },
        [11012909] = {
          Camera = "27.647247,-73.736328,81.884186,0.000202,3.20034,2.81273,28.000008,239.526123,false,Manual,10.489336",
          ContentTC = "嗯，中央控製室已是奪回要塞的最後一步。他們在前面做了那麽多陷阱，不至於在最後一步前功盡棄。",
          DialogueId = 11012909,
          GUID = "1B91D562",
          NextDialogue = 11012913,
          SpeakNpcId = 110010,
          Subtitle = "True. The central control room is key to regaining control of the fortress. It doesn't add up that they'd leave it undefended after all the elaborate traps we've encountered.",
          TalkActionId = {
            [1] = "110022:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D562"
        },
        [11012910] = {
          ContentTC = "也許我們想多了，神棄者同盟的人根本不會操作這個房間的機關。",
          DialogueId = 11012910,
          GUID = "1B91D58C",
          NextDialogue = 11012911,
          Subtitle = "Maybe we're overthinking it. Perhaps The Forsakens never figured out how to operate the controls in this room."
        },
        [11012911] = {
          Camera = "27.647247,-73.736328,81.884186,0.000202,3.20034,2.81273,28.000008,239.526123,false,Manual,10.489336",
          ContentTC = "他們在前面布設了那麽多機關，真的會在最後一步毫無防備嗎？",
          DialogueId = 11012911,
          GUID = "1B91D5B6",
          NextDialogue = 11012912,
          SpeakNpcId = 110010,
          Subtitle = "But given the number of traps they've set up along the way, it seems unlikely they'd ignore this crucial area.",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D5B6"
        },
        [11012912] = {
          Camera = "141.658112,-34.873047,95.20993,0.000202,4.799984,-8.390281,28.000008,123.13105,false,Manual,10.489336",
          ContentTC = "不過，就算這兒是陷阱，我們也咬著牙踩進來了，眼下還是要專註於任務。",
          DialogueId = 11012912,
          GUID = "1B91D5E0",
          NextDialogue = 11012913,
          SpeakNpcId = 110010,
          Subtitle = "Trap or not, we have our objectives. Proceed with caution and stay mission-focused.",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D5E0"
        },
        [11012913] = {
          Camera = "-398.193848,144.386719,348.024841,0.000283,-26.79845,-15.198461,17.000002,215.162598,false,DoNotOverride,2.8",
          ContentTC = "接下來我要用我的秘鑰接管控製臺。我們已經打進了中央控製室，只差這最後一步了。",
          DialogueId = 11012913,
          FinalCamera = "-334.236298,127.009766,314.548828,0.000283,-26.798424,-15.198519,17.000006,215.162598,false,DoNotOverride,2.8",
          GUID = "1B91D60A",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012914,
          SpeakNpcId = 110010,
          Subtitle = "I'm about to access the fortress's control panel with my key. If all goes well, that should complete our mission.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D60A"
        },
        [11012914] = {
          Camera = "409.771362,295.126953,174.385681,0.000203,-15.199752,-119.982185,28.000006,496.513092,false,Manual,10.489336",
          ContentTC = "明白。那我四處轉轉，排查一下有無可疑之處。",
          DialogueId = 11012914,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91D634",
          SpeakNpcId = 110022,
          Subtitle = "Understood. I'll take a look around for anything suspicious.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D634"
        },
        [11012915] = {
          ContentTC = "小心點，裡面可能還有敵人。",
          DialogueId = 11012915,
          Duration = 3,
          GUID = "1B91D65E",
          SpeakNpcId = 110010,
          Subtitle = "Be careful, there may be more enemies inside.",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D65E"
        },
        [11013001] = {
          ContentTC = "「十三軍團會在兩日內發起突襲。安東尼·富爾維斯向西比爾立下軍令狀，若他的槍管無法打破要塞的堅壁，就打破自己的腦殼。西比爾把一批精銳撥給了他。」",
          DialogueId = 11013001,
          Duration = 3,
          GUID = "1B91E47A",
          NextDialogue = 11013002,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"The 13th Legion will attack in two days. Antonius Fulvis has vowed before Sibylle that if his forces fail to breach the fortress, he would shoot himself with his own gun. Sibylle then assigned him the best troops.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E47A"
        },
        [11013002] = {
          ContentTC = "「軍團是一定要收復龍莎要塞的，守住要塞的事就別想了。當下最要緊的是快點從要塞撤離，以保存我們神棄者同盟的有生力量。」",
          DialogueId = 11013002,
          Duration = 3,
          GUID = "1B91E4A4",
          NextDialogue = 11013003,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"The Legion will do everything they can to take Lonza Fortress back. We should not attempt to defend the Fortress against such odds. Withdraw our forces and ensure the survival of The Forsakens.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E4A4"
        },
        [11013003] = {
          ContentTC = "「只是撤退的話，太可惜了。我們總得讓這些海伯利亞的走狗吃點苦頭。」",
          DialogueId = 11013003,
          Duration = 3,
          GUID = "1B91E4CE",
          NextDialogue = 11013004,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_UnsatisfiedVoice",
          Subtitle = "\"Merely retreating would squander a perfect opportunity. We should make the Hyperboreans pay dearly.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E4CE"
        },
        [11013004] = {
          ContentTC = "「這很好辦。交給阿瓦爾，他這次負責兩支先遣分隊的調度，那群蠢貨都很聽他話。」",
          DialogueId = 11013004,
          Duration = 3,
          GUID = "1B91E4F8",
          NextDialogue = 11013005,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"Easy. Leave it to Avar. He'll be commanding two vanguard squads in the operation. Those fools always listen to him.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E4F8"
        },
        [11013005] = {
          ContentTC = "「你們提前把機關備好，阿瓦爾自會拖延他們的進攻速度，讓那些傢伙都交代在這兒。」",
          DialogueId = 11013005,
          Duration = 3,
          GUID = "1B91E522",
          NextDialogue = 11013006,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"Avar will hold off their assault. Use this time to lay traps and fortify our defences. The fortress will become their graveyard.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E522"
        },
        [11013006] = {
          ContentTC = "「很快，我們就會從報紙上看到這樣的新聞——」",
          DialogueId = 11013006,
          Duration = 3,
          GUID = "1B91E54C",
          NextDialogue = 11013007,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"We'll soon read this headline in the news—\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E54C"
        },
        [11013007] = {
          ContentTC = "「『龍莎戰役中，十三軍團為了保衛吾皇神聖的土地浴血奮戰，先遣隊超過九成士官在這場戰役中陣亡。』」",
          DialogueId = 11013007,
          Duration = 3,
          GUID = "1B91E576",
          NextDialogue = 11013008,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"'During the battle in Lonza Fortress, the 13th Legion valiantly defended the Emperor's lands. The vanguard suffered ninety percent casualties in the fierce conflict...'\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E576"
        },
        [11013008] = {
          ContentTC = "「幸存的阿瓦爾中校對這些戰士的亡故表示悼念，並致以無上光榮的褒獎。」",
          DialogueId = 11013008,
          Duration = 3,
          GUID = "1B91E5A0",
          NextDialogue = 11013009,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"'Lieutenant Colonel Avar, one of the survivors, mourned the fallen and delivered a eulogy of unmatched honour.'\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E5A0"
        },
        [11013009] = {
          ContentTC = "「好個阿瓦爾！就按你們說的辦吧。只可惜這樣的哀榮便宜了這群豬玀。」",
          DialogueId = 11013009,
          Duration = 3,
          GUID = "1B91E5CA",
          NextDialogue = 11013010,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_UnsatisfiedVoice",
          Subtitle = "\"Good for Avar! Let's go with this plan then. Shame those dead dogs will receive posthumous honours, though.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E5CA"
        },
        [11013010] = {
          ContentTC = "……阿瓦爾？",
          DialogueId = 11013010,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91E5F4",
          SpeakNpcId = 110022,
          Subtitle = "...Avar?",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E5F4"
        },
        [11013101] = {
          ContentTC = "「海伯利亞的暴虐，我等卡戎之民早已不堪忍受。」",
          DialogueId = 11013101,
          Duration = 3,
          GUID = "1B91F4E2",
          NextDialogue = 11013102,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_Docs",
          Subtitle = "\"Charons like us can no longer stand Hyperborean tyranny.\"",
          VoiceName = "voice/$Locale$/story/1002/110131/1B91F4E2"
        },
        [11013102] = {
          ContentTC = "「我會向神棄者同盟獻上自己的忠誠，這是帝國應得的懲罰。」",
          DialogueId = 11013102,
          Duration = 3,
          GUID = "1B91F50C",
          NextDialogue = 11013103,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_Docs",
          Subtitle = "\"I hereby pledge my allegiance to The Forsakens. The Empire must be held accountable for its actions.\"",
          VoiceName = "voice/$Locale$/story/1002/110131/1B91F50C"
        },
        [11013103] = {
          ContentTC = "「——阿瓦爾·赫德蘭」",
          DialogueId = 11013103,
          Duration = 3,
          GUID = "1B91F536",
          NextDialogue = 11013104,
