        },
        [11013609] = {
          Camera = "-427.870239,2258.052734,924.980835,0.000026,-20.399008,-74.736588,35.000011,271.648438,false,DoNotOverride,2.652164",
          ContentTC = "先說說你為什麽用那些偽證栽贓我吧。你當上面都是傻子？",
          DialogueId = 11013609,
          Duration = 3,
          FinalCamera = "-427.870239,2258.052734,892.516418,0.000027,-20.399042,-74.737274,35.000011,271.648438,false,DoNotOverride,20.0",
          GUID = "1B92483A",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013610,
          SpeakNpcId = 110010,
          Subtitle = "Now, why bother making up all this false evidence? You really think the higher-ups are that stupid?",
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92483A"
        },
        [11013610] = {
          Camera = "-89.605194,-418.919922,28.023407,-10.014737,8.201615,53.252785,35.0,271.651154,false,DoNotOverride,20.0",
          ContentTC = "就是因為上面有很多聰明人，他們才一定會裝傻。阿瓦爾，動動你的腦子。既然我敢把事做絕，自然有想要我做絕的人。",
          DialogueId = 11013610,
          Duration = 3,
          GUID = "1B924864",
          NextDialogue = 11013611,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"-427.870239,2258.052734,892.516418,0.000025,-20.399035,-74.737183,35.000011,271.648438,false,DoNotOverride,20.0"},duration{0}},
CameraMoveTo{TargetPosition{"-412.960815,2203.416016,871.454102,0.000026,-20.399035,-74.737061,35.000011,271.648438,false,DoNotOverride,20.0"},duration{6}}
},
MoveTo{_delay{5},ActorId{110011},TargetPoint{"EX01_FixSimple_19point01"},MoveSpeed{105},Visibility{"Show"}}
}]],
          SpeakNpcId = 110011,
          Subtitle = "Of course not. They're actually smart enough to turn a blind eye and play along. Use your head, Avar. Why do you think I dare to make this bold move? It's naturally because someone wants me to.",
          VoiceName = "voice/$Locale$/story/1002/110136/1B924864"
        },
        [11013611] = {
          Camera = "199.207306,49.052734,103.883209,-0.001587,-1.196615,95.62352,35.0,439.465851,false,DoNotOverride,22.0",
          ContentTC = "反正你已經是個死人了，那麽我就再寬仁一次，讓你死得明白一點吧。",
          DialogueId = 11013611,
          Duration = 3,
          FinalCamera = "196.638626,75.138672,103.335693,-0.001587,-1.196615,95.62352,35.0,439.465851,false,DoNotOverride,22.0",
          GUID = "1B92488E",
          NextDialogue = 11013612,
          Scripts = "PlayAnimation{_delay{1},ActorId{110011},AnimationId{\"Talk03_Start\"},Duration{6}}",
          SpeakNpcId = 110011,
          Subtitle = "Since you're a goner already, I'll show some mercy so you won't die a fool.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92488E"
        },
        [11013612] = {
          Camera = "34.140366,-340.748047,894.160034,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0",
          ContentTC = "陛下即位之初——也就是塞維烏斯公爵擔任攝政的那段時間裡——他們偏離了海伯利亞長久以來的規則，為帝國這棵大樹嫁接了太多無用的枝葉。",
          DialogueId = 11013612,
          Duration = 3,
          FinalCamera = "195.783936,-345.769531,815.577393,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0",
          GUID = "1B9248B8",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013613,
          RelatedWikiId = {
            [1] = 201017
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{7},TargetPosition{"-742.495117,843.439453,633.784912,0.00004,-27.596544,-31.344604,30.0,271.651154,false,DoNotOverride,20.0"},duration{0}},CameraMoveTo{TargetPosition{"-832.090454,898.013672,688.620361,0.00004,-27.596523,-31.344666,30.0,271.651154,false,DoNotOverride,20.0"},duration{8}}
}]],
          SpeakNpcId = 110011,
          Subtitle = "When His Majesty was first crowned, Duke Servius was our Imperial Regent. But the Regency strayed from established Hyperborean traditions and grafted too many useless scions onto the great Imperial oak.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110010:n(110011)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B9248B8"
        },
        [11013613] = {
          Camera = "195.79921,146.666016,102.814026,-0.001556,-1.197421,101.018288,35.000011,216.948959,false,Manual,8.0",
          ContentTC = "他們竟然搞出什麼「桂冠卡戎」稱號，允許你們進入樞密院和軍團，甚至擔任要職——這太荒謬了。",
          DialogueId = 11013613,
          Duration = 3,
          FacialId = {
            [1] = "110011:Unhappy01"
          },
          FinalCamera = "194.398621,153.863281,102.660858,-0.001556,-1.197421,101.018288,35.000011,216.948959,false,Manual,8.0",
          GUID = "1B9248E2",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013614,
          RelatedWikiId = {
            [1] = 101008
          },
          Scripts = "LookAt{_delay{6.5},LookAtDescription{\"110011:n(110011)\"}}",
          SpeakNpcId = 110011,
          Subtitle = "Those fools let so-called Laurelled Charons into the Military Council and the Legion — even handed high office to some of you. It's absurd.",
          TalkActionId = {
            [1] = "110011:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9248E2"
        },
        [11013614] = {
          Camera = "-129.604523,471.810547,-28.501526,0.000752,21.988857,-30.575706,23.640343,100000.0,false,DoNotOverride,2.654159",
          ContentTC = "儘管如今陛下已經迷途知返，但這些糜爛的枝葉依舊存在。而我要做的，則是幫陛下一把，將這些糜爛徹底剪除。",
          DialogueId = 11013614,
          Duration = 3,
          FinalCamera = "-40.557144,495.207031,55.238251,-10.00088,13.201608,-42.578636,30.0,229.467407,false,DoNotOverride,22.0",
          GUID = "1B92490C",
          NextDialogue = 11013615,
          Scripts = [[
PARA{
PlayAnimation{_delay{12},ActorId{110011},AnimationId{"Angry02_Start"},Duration{10}},
PlayAnimation{_delay{16},ActorId{110011},AnimationId{"Angry02_End"},Duration{0}},
CameraMoveTo{_delay{10},TargetPosition{"46.070709,353.451172,80.537964,0.000758,-1.611453,15.627573,23.640345,100000.0,false,DoNotOverride,2.65416"},duration{0}}
}
]],
          SpeakNpcId = 110011,
          Subtitle = "Though His Majesty is now aware of these mistakes, they continue to plague us. I'm merely helping him prune the oak.",
          ToFinalCameraBlendTime = 12,
          TurnTo = {
            [1] = "110011:p(45)"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B92490C"
        },
        [11013615] = {
          Camera = "52.397644,381.144531,96.864655,0.0,-0.198417,-44.378803,30.000019,229.46875,false,Manual,22.0",
          ContentTC = "……鬧了半天，你是看不慣我是個卡戎之民啊。",
          DialogueId = 11013615,
          Duration = 3,
          FinalCamera = "60.468475,373.251953,96.8255,0.0,-0.198417,-44.378376,30.000019,229.46875,false,Manual,22.0",
          GUID = "1B924936",
          NextDialogue = 11013616,
          SpeakNpcId = 110010,
          Subtitle = "...So you went through all the trouble, just because you don't like Charons?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924936"
        },
        [11013616] = {
          Camera = "-819.513733,862.818359,733.592957,0.000003,-32.798332,-28.176556,30.0,229.467407,false,DoNotOverride,22.0",
          ContentTC = "那你早說，用不著上來就做這麽絕吧？只要你放我從這裡活著出去，我就想個辦法早日退休，再也不擋你的路。",
          DialogueId = 11013616,
          Duration = 3,
          FacialId = {
            [1] = "110011:None"
          },
          FinalCamera = "-931.609741,922.859375,815.540222,0.000003,-32.798332,-28.176556,30.0,229.467407,false,DoNotOverride,22.0",
          GUID = "1B924960",
          NextDialogue = 11013617,
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{110010},AnimationId{"Talk01_End"},Duration{0}},
PlayAnimation{_delay{4},ActorId{110011},AnimationId{"Talk03_Start"},Duration{10}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "You should've told me earlier. There's no need for such an elaborate ruse. Just let me off this time, and I'll retire early and stay out of your way forever.",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924960"
        },
        [11013617] = {
          Camera = "153.246658,302.361328,94.305695,-10.00189,5.400207,-63.975967,28.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "如果你想要我為你效忠，也可以。只要把這次泄露作戰情報的責任都推到{性别2:他|她}身上就行了。你我不但能全身而退，還能得一份揪出間諜的功勞。並且……",
          DialogueId = 11013617,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "157.790649,293.052734,95.28479,-10.00189,5.400207,-63.975967,28.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B92498A",
          NextDialogue = 11013618,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"549.498535,2849.632812,-810.490845,5.001147,-28.793985,-88.214127,50.0,100000.0,false,DoNotOverride,22.0"},duration{0}},CameraMoveTo{TargetPosition{"552.933838,2849.892578,-810.754639,5.001147,-28.793985,-88.214127,50.0,100000.0,false,DoNotOverride,22.0"},duration{10}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "If you need my loyalty, I can do that too. We can blame {性别2:him|her} for leaking our battle plans. Both of us walk away clean. Hell, we might even get a reward for uncovering a spy. And...",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92498A"
        },
        [11013618] = {
          Camera = "-13.393326,461.294922,163.357544,-0.000366,-19.199892,-42.771851,21.125469,100000.0,false,Manual,22.0",
          ContentTC = "並且，你會多一條聽話的狗。",
          DialogueId = 11013618,
          Duration = 3,
          FinalCamera = "-13.393326,461.294922,154.910889,-0.000366,-19.199892,-42.771851,21.125469,100000.0,false,Manual,22.0",
          GUID = "1B92498B",
          NextDialogue = 11013619,
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{110011},AnimationId{"Talk03_End"},Duration{0}},
PARA{LookAt{LookAtDescription{"110011:n(110010)"}},
TurnTo{TurnToDescription{"110011:n(110010)"}}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "You'll gain an old dog obedient enough to follow your orders.",
          TalkActionId = {
            [1] = "110010:Talk01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92498B"
        },
        [11013619] = {
          Camera = "168.977859,253.941406,61.364716,-8.000504,16.603903,108.03064,21.125483,146.883423,false,Manual,5.0",
          ContentTC = "哈，想不到你也挺下三濫的。不過，你也就只能想到這一步了。阿瓦爾，你以為你活著的那點用處，能比得上死了的你嗎？",
          DialogueId = 11013619,
          Duration = 3,
          FacialId = {
            [1] = "110011:Smile01",
            [2] = "110010:Think01"
          },
          FinalCamera = "168.977859,253.941406,58.862396,-8.000504,16.603903,108.03064,21.125483,146.883423,false,Manual,5.0",
          GUID = "1B9249B4",
          NextDialogue = 11013620,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{10},TargetPosition{"118.145653,292.558594,103.879425,-3.0,-0.795013,-46.971291,30.000008,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"124.55114,285.693359,103.749207,-3.0,-0.795013,-46.971291,30.000008,100000.0,false,DoNotOverride,22.0"},duration{5}}
}
	]],
          SpeakNpcId = 110011,
          Subtitle = "Hah, how quaint, Avar — didn't expect you to stoop this low too. But you don't know the half of it, Avar. You're worth far more to us dead than alive.",
          TalkActionId = {
            [1] = "110011:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9249B4"
        },
        [11013620] = {
          Camera = "156.654633,254.740234,116.599792,-8.003376,-6.396171,107.63237,35.0,146.883423,false,DoNotOverride,5.0",
          ContentTC = "動動你的腦子吧！如果全帝國都知道一個卡戎軍官背棄軍團，投靠神棄者同盟，害得一批帝國最年輕勇敢的精銳殞命——會發生什麽？",
          DialogueId = 11013620,
          Duration = 3,
          FacialId = {
            [1] = "110010:None"
          },
          FinalCamera = "148.843872,279.322266,115.388702,-8.003376,-6.396171,107.63237,35.0,146.883423,false,DoNotOverride,5.0",
          GUID = "1B9249DE",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013621,
          Scripts = [[
SEQ{
PlayAnimation{_delay{3},ActorId{110011},AnimationId{"Sigh_Start"},Duration{10}},
PlayAnimation{ActorId{110011},AnimationId{"Sigh_End"},Duration{3}}
}
]],
          SpeakNpcId = 110011,
          Subtitle = "Use your head! Imagine the uproar if it came out that a high-ranking Charon officer defected and joined The Forsakens, resulting in the deaths of many of our best young soldiers.",
          TalkActionId = {
            [1] = "110011:Talk02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B9249DE"
        },
        [11013621] = {
          Camera = "169.007309,92.732422,41.227081,-10.000513,6.204441,84.826546,21.125471,100000.0,false,DoNotOverride,22.0",
          ContentTC = "高層的桂冠卡戎本就飽受爭議，屆時他們還能留在現在的位子上？比如我們那位敬愛的長官——你知道有多少雙眼睛在盯著她，等著看她如何跌得粉身碎骨嗎？",
          DialogueId = 11013621,
          Duration = 3,
          FinalCamera = "139.76091,94.824219,46.366302,-10.000513,6.204441,84.826546,21.125471,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924A08",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013622,
          Scripts = [[
SEQ{
PlayAnimation{_delay{5},ActorId{110011},AnimationId{"Talk03_End"},Duration{5}},
PlayAnimation{ActorId{110011},AnimationId{"Talk02_Start"},Duration{0}}
}
]],
          SpeakNpcId = 110011,
          Subtitle = "Laurelled Charons in high office are already a thorn in plenty of sides. A scandal like this? It'll drag their names straight through the mud. Take our beloved superior — do you have any idea how many people wish to watch her crash and burn?",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A08"
        },
        [11013622] = {
          Camera = "9.816498,408.683594,91.287811,-0.001526,-0.599793,-38.348438,35.0,100000.0,false,Manual,22.0",
          ContentTC = "西比爾？你想把她趕下去……你的目標是「軍團長」？",
          DialogueId = 11013622,
          Duration = 3,
          FinalCamera = "11.8965,401.550781,91.224274,-0.001526,-0.599793,-38.34877,35.0,100000.0,false,Manual,22.0",
          GUID = "1B924A32",
          NextDialogue = 11013623,
          SpeakNpcId = 110010,
          Subtitle = "You mean Sibylle? You wish her gone... You're after her position and power?",
          TalkActionId = {
            [1] = "110011:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A32"
        },
        [11013623] = {
          Camera = "54.786392,-620.46875,9.960114,0.000071,7.403973,84.185303,22.000011,100000.0,false,DoNotOverride,22.0",
          ContentTC = "也許吧，也許還有更多。不過，對你來說，都不重要了。",
          DialogueId = 11013623,
          Duration = 3,
          FinalCamera = "27.690643,-617.716797,9.960114,0.000071,7.403973,84.185303,22.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1B924A5C",
          LookAt = {
            [1] = "110011:n(110011)"
          },
          NextDialogue = 11013624,
          Scripts = [[
PARA{
MoveTo{_delay{5},ActorId{110011},TargetPoint{"EX01_FixSimple_19point02"},MoveSpeed{65},Visibility{"Show"}},
CameraMoveTo{_delay{6},TargetPosition{"110.352188,24.90625,106.656708,0.000074,-3.195859,90.185249,40.000023,100000.0,false,DoNotOverride,22.0"},duration{0}}
}]],
          SpeakNpcId = 110011,
          Subtitle = "Perhaps. Maybe I want more. But that's no longer your concern.",
          TalkActionId = {
            [1] = "110011:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924A5C"
        },
        [11013624] = {
          Camera = "-62.074799,-566.730469,491.808014,-0.001556,-31.999592,75.647636,16.661533,100000.0,false,Manual,22.0",
          ContentTC = "等一下！",
          DialogueId = 11013624,
          Duration = 3,
          GUID = "1B924A86",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013625,
