        },
        [11016504] = {
          Camera = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,105.270081,false,Manual,22.0",
          ContentTC = "我會將那天的真相原原本本地告訴你，也希望你聽過之後，能憑借你心中的那份「正義」做出選擇。",
