        [11016903] = {
          Camera = "-349.862305,123.099609,120.742188,0.000104,1.202755,26.777416,35.000019,509.385437,false,Manual,22.0",
          ContentTC = "上頭加急走完了所有審核流程，到我手裡的，只有一張要你們命的紙。",
          DialogueId = 11016903,
          FacialId = {
            [1] = "110032:Angry01"
