          VoiceName = "voice/$Locale$/story/1002/110182/1B9539EE"
        },
        [11018204] = {
          ContentTC = "男人嶄新的軍裝被撕碎，透過襤褸的布條，無數爪跡和齒痕清晰可辨；顯然，他是被相當數量的穢獸撕咬致死的。他指節青白的手仍緊緊握著斷刃，似是最後一刻仍在與群獸角力。",
          DialogueId = 11018204,
          GUID = "1B953A18",
          NextDialogue = 11018205,
          Subtitle = "His uniform — freshly issued — is in tatters. Beneath the torn fabric, claw slashes and bite marks mar his body. He was clearly ripped apart by a swarm of Filthoids. In his lifeless grasp, a broken blade — knuckles pale and stiff — a silent testament that he fought to the bitter end.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A18"
        },
        [11018205] = {
