          DialogueId = 11018505,
          GUID = "1B956B7A",
          NextDialogue = 11018506,
          SpeakNpcId = 110020,
          Subtitle = "If I'd known he'd be that petty... maybe I would've let him win...",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B7A"
        },
        [11018506] = {
