          ExStoryInfo = "EXPlayer",
          GUID = "1B95BDAC",
          NextDialogue = 11019007,
          SpeakNpcId = 110022,
          Subtitle = "Wait... the Warden said something about... interrogation...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BDAC"
        },
        [11019007] = {
          ContentTC = "那位審訊官提到了「催眠藥劑」……",
          DialogueId = 11019007,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BDD6",
          NextDialogue = 11019008,
          SpeakNpcId = 110022,
          Subtitle = "That interrogator mentioned a hypnotic agent...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BDD6"
        },
        [11019008] = {
          ContentTC = "這裡……應該不是真實的世界。我想我現在正在夢中。",
          DialogueId = 11019008,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BE00",
          SpeakNpcId = 110022,
          Subtitle = "I'm probably not in a real world. This is a dream..",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BE00"
        },
        [11019009] = {
          ContentTC = "（「老師」和「達芙涅」都消失了……）",
          DialogueId = 11019009,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BE2A",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(\"Sir Avar\" and \"Daphne\"... They're gone...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BE2A"
        },
        [11019010] = {
