          DialogueId = 11019019,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BFCE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...This one's easy.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BFCE"
        },
        [11019020] = {
