          DialogueId = 11019022,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C04C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(No — stay calm. They're just illusions.)",
