          GUID = "1B95C0A0",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Filthoids...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C0A0"
        },
        [11019025] = {
