          ContentTC = "我們接管要塞的操作權限，不是為了開啟機關，而是為了關閉機關。",
          DialogueId = 11019314,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-1.82135,30.754875,43.375,5.000283,-6.998867,-165.188583,15.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95F034",
          NextDialogue = 11019315,
          SpeakNpcId = 110022,
          Subtitle = "We accessed the defence systems to shut them down — not to activate them.",
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110193/1B95F034"
        },
        [11019315] = {
