          Camera = "376.210938,-1350.273438,190.855469,0.000201,25.199463,-55.5868,35.000011,262.433014,false,DoNotOverride,10.0",
          ContentTC = "我出錢包下了這間包廂。帶兩個小朋友進去，想必是合規矩的吧？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001301,
          FinalCamera = "370.894531,-1342.501953,186.433594,0.000201,25.199463,-55.5868,35.000011,262.433014,false,DoNotOverride,10.0",
          GUID = "1E0B4372",
          LookAt = {
            [1] = "210004:n(220010)"
          },
          NextDialogue = 12001302,
          Scripts = "LookAt{_delay{3},LookAtDescription{\"210004:n(220013)\"}},",
          SpeakNpcId = 210004,
          Subtitle = "I paid for this suite in full. Bringing along two young ones shouldn't be a problem, right?",
          TalkActionId = {
            [1] = "210004:Confident_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4372"
        },
        [12001302] = {
          Camera = "460.166016,-1490.179199,238.054688,0.000203,2.199983,118.812393,35.000008,257.958527,false,Manual,10.0",
          ContentTC = "……女士，您確定要讓這種來歷不明、不三不四的人玷汙您的包廂嗎？您可別被他們看似無辜的外表騙到了！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001302,
          FacialId = {
            [1] = "220010:CM_Angry01"
          },
          FinalCamera = "464.386719,-1497.868164,237.734375,0.000203,2.199983,118.812393,35.000008,262.433014,false,Manual,10.0",
          GUID = "1E0B439C",
          LookAt = {
            [1] = "220010:n(210004)"
          },
          NextDialogue = 12001303,
          Scripts = "PlayAnimation{_delay{4},ActorId{220010},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 220010,
          Subtitle = "...Ma'am, are you sure you want shady little punks like them to dirty your private suite? Don't be fooled by their innocent appearances!",
          TalkActionId = {
            [1] = "220013:Sigh_End",
            [2] = "210004:Confident_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B439C"
        },
        [12001303] = {
          Camera = "557.857422,-581.538086,373.707031,0.00023,-12.400208,-101.401718,35.0,391.082153,false,DoNotOverride,7.0",
          ContentTC = "他們是什麼樣的人，我自有定數。還是說……你想質疑我的決定嗎？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001303,
          FacialId = {
            [1] = "210004:Angry01"
          },
          FinalCamera = "562.587891,-558.097656,378.964844,0.00023,-12.400208,-101.401718,35.0,391.082153,false,DoNotOverride,7.0",
          GUID = "1E0B43C6",
          NextDialogue = 12001304,
          SpeakNpcId = 210004,
          Subtitle = "I have my own judgment as to what kind of people they are. Or... are you questioning my judgment?",
          TalkActionId = {
            [1] = "210004:Confident_Start",
            [2] = "200002:Talk03_Start",
            [3] = "220010:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B43C6"
        },
        [12001304] = {
          Camera = "434.730469,-1369.897949,290.742188,0.000221,-14.599761,139.198776,35.0,391.082153,false,DoNotOverride,7.0",
          ContentTC = "不會的，女士。帶什麼人進去，當然是客人全權說了算。就算是您要把霧區的叫花子帶進去，蓋雷亞劇院也會竭誠為您服務。混小子，快給我閉嘴！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001304,
          GUID = "1E0B43F0",
          LookAt = {
            [1] = "220013:n(210004)",
            [2] = "220010:n(220013)"
          },
          NextDialogue = 12001305,
          Scripts = [[
PARA{
LookAt{_delay{2},LookAtDescription{"220010:n(220013)"}},
PlayAnimation{_delay{6.5},ActorId{220013},AnimationId{"Talk01_End"},Duration{1}},
LookAt{_delay{11},LookAtDescription{"220013:n(220010)"}}
}]],
          SpeakNpcId = 220013,
          Subtitle = "Of course not, ma'am. Whom you choose to bring into the suite is entirely up to you. Even if you invited ragamuffins from the slums, the Galea Theatre would still be honoured to serve you. Shut your cake hole, you idiot!",
          TalkActionId = {
            [1] = "220013:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B43F0"
        },
        [12001305] = {
