          DefaultLookAt = "TalkNpc",
          DialogueId = 12001305,
          DisableMouth = 1,
          GUID = "1E0B441A",
          NextDialogue = 12001306,
          SpeakNpcId = 220010,
          Subtitle = "...",
          TalkActionId = {
            [1] = "220010:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B441A"
        },
        [12001306] = {
