CameraMoveTo{TargetPosition{"337.462891,-1316.896973,210.441406,-5.000038,12.401437,-50.368782,45.000011,391.082153,false,DoNotOverride,7.0"},duration{8}}
},
PlayAnimation{_delay{8.01},ActorId{210004},AnimationId{"Zhiliu_Story_Special02_Start"},Duration{4}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Alright, calm yourselves. You've done your part. Now, here's what you should do: lead the way and show us inside.",
          TalkActionId = {
            [1] = "210004:Confident_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4444"
