}]],
          SpeakNpcId = 210004,
          Subtitle = "Watch your words. You never know what misfortune they might bring upon you.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B44C2"
        },
        [12001310] = {
          Camera = "31.415039,981.577148,873.933594,0.000125,-35.994133,-75.767517,25.0,30.607483,false,DoNotOverride,4.569996",
          ContentTC = "女士，多謝您剛才出手幫忙。",
          DialogueId = 12001310,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-24.272461,967.451172,851.3125,0.000125,-35.994137,-75.768639,25.0,30.607483,false,DoNotOverride,4.569996",
          GUID = "1E0B44EC",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12001311,
          SpeakNpcId = 100001,
          Subtitle = "Thank you for stepping in to help us earlier, ma'am.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B44EC"
        },
        [12001311] = {
          Camera = "-76.600586,-142.378418,145.878906,0.000066,2.400094,55.591667,35.000011,210.0,false,Manual,10.0",
          ContentTC = "呵呵……不用這麼拘謹。你可以直接稱呼我的名字。",
          DialogueId = 12001311,
          FacialId = {
            [1] = "210004:Smile01"
          },
          FinalCamera = "-73.668945,-138.096191,146.089844,0.000078,2.400094,55.59174,35.000008,210.0,false,Manual,10.0",
          GUID = "1E0B4516",
          NextDialogue = 12001312,
          Scripts = "PlayAnimation{_delay{3.3},ActorId{210004},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "Hehe... No need to be so formal. Just call me by my name.",
          TalkActionId = {
            [1] = "210004:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4516"
        },
        [12001312] = {
          Camera = "30.446289,185.356934,190.074219,0.000055,-11.799342,-98.808578,35.000008,267.576447,false,DoNotOverride,4.724111",
          ContentTC = "……止流女士？",
          DialogueId = 12001312,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E0B4540",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001313,
          SpeakNpcId = 100001,
          Subtitle = "...Lady Zhiliu, then?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4540"
        },
        [12001313] = {
          Camera = "-64.051758,0.427246,155.0625,0.000095,4.200347,23.600756,35.000008,201.567627,false,DoNotOverride,10.0",
          ContentTC = "女士是帝國常用的敬稱吧？我至今聽不慣。",
          DialogueId = 12001313,
          GUID = "1E0B456A",
          NextDialogue = 12001314,
          Scripts = "PlayAnimation{_delay{3},ActorId{210004},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "...That's not much of an improvement. \"Lady\" is more of an Empire term, isn't it? I've never really grown used to it.",
          TalkActionId = {
            [1] = "210004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B456A"
        },
        [12001314] = {
          ContentTC = "我常年行南闖北經商，手中姑且也是有些鋪子。你若是執意要加個後綴，不如叫我掌櫃，聽著順耳些。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001314,
          GUID = "1E0B4594",
          NextDialogue = 12001315,
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"24.381836,149.445801,168.28125,0.000089,-6.799255,-100.405937,35.000008,201.567627,false,Manual,10.0"},duration{0}},
LookAt{_delay{6.1},LookAtDescription{"200002:n(210004)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "I've spent years travelling these lands as a merchant, overseeing a few shops of my own. If you feel you must use a title, perhaps \"proprietress\" would be more fitting.",
          TalkActionId = {
            [1] = "210004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4594"
        },
        [12001315] = {
          Camera = "-228.251953,-342.149658,218.3125,0.000205,-10.998899,54.599339,35.0,210.445709,false,DoNotOverride,10.0",
          ContentTC = "那……止流掌櫃，您應該在等什麼人吧？我們在這兒，會不會打擾到您？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001315,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E0B45BE",
          NextDialogue = 12001316,
          Scripts = [[
PARA{
LookAt{_delay{5.1},LookAtDescription{"100001:n(200002)"}},
LookAt{_delay{6.1},LookAtDescription{"200002:n(210004)"}},
PlayAnimation{_delay{5},ActorId{100001},AnimationId{"Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Alright then... Proprietress Zhiliu, were you expecting someone? I hope we're not intruding.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B45BE"
        },
        [12001316] = {
          Camera = "22.512695,93.567383,162.910156,0.000092,-4.399099,-96.009109,35.000008,201.567627,false,Manual,10.0",
          ContentTC = "原來你在意的是這個呀，真可愛。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001316,
          GUID = "1E0B45E8",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(210004)"
          },
          NextDialogue = 12001317,
          SpeakNpcId = 210004,
          Subtitle = "That's what you've been worrying about? How adorably considerate of you.",
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B45E8"
        },
        [12001317] = {
          Camera = "-95.72168,25.02832,164.125,0.000175,-0.798128,7.808278,43.803249,210.445709,false,DoNotOverride,10.0",
          ContentTC = "沒關係的。那個人，大概是不會赴約了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001317,
          FinalCamera = "-108.598633,23.216797,163.859375,0.000175,1.201922,8.00806,43.803249,210.445709,false,DoNotOverride,10.0",
          GUID = "1E0B4612",
          LookAt = {
            [1] = "200002:n(100001)"
