LookAt{_delay{3},LookAtDescription{"210004:n(210004)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "It's okay. I don't think that person will be coming.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200002:n(210004)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4612"
        },
        [12001318] = {
          Camera = "-724.288086,-392.508057,357.445312,0.000203,-15.398278,26.595276,30.000002,210.445709,false,DoNotOverride,10.0",
          ContentTC = "一個人觀劇，也有幾分冷清。今天能有你們陪著，這間包廂熱鬧了不少，我反而應該向你們道謝才是。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001318,
          FinalCamera = "-722.753906,-375.015869,367.042969,0.000203,-15.398278,26.595276,30.0,210.445709,false,DoNotOverride,10.0",
          GUID = "1E0B463C",
          NextDialogue = 12001319,
          Scripts = [[
PARA{
LookAt{_delay{9},LookAtDescription{"210004:n(100001)"}},
PlayAnimation{_delay{7},ActorId{210004},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Watching a show on one's own can feel a bit lonely. Having you two here has brightened this suite considerably. If anything, I should be the one thanking you.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B463C"
        },
        [12001319] = {
          Camera = "-39.875977,-172.393066,112.152344,0.000143,-4.597844,106.196785,30.000008,106.771988,false,Manual,10.0",
          ContentTC = "小僕從，竟然有人會辜負這麼有錢又出手大方的漂亮姐姐，還讓她傷心……真是太沒眼光了！",
          DialogueId = 12001319,
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "1E0B4666",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001320,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"Confident_Start"},Duration{1}},
TurnTo{_delay{0.1},TurnToDescription{"100001:n(200002)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, can you believe someone would stand up such a rich, generous, and gorgeous lady? What a fool!",
          TalkActionId = {
            [1] = "210004:Talk02_End"
          },
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4666"
        },
        [12001320] = {
          Camera = "-157.03418,-238.744385,135.445312,0.000194,-1.198671,55.205051,29.855673,334.603516,false,DoNotOverride,10.0",
          ContentTC = "在我的家鄉，人與人之間的相遇相識被稱為「緣分」。緣分來之不易，既然出現了就不如珍惜，你覺得呢？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001320,
          FinalCamera = "2.482422,-380.777344,275.316406,0.000165,-21.198877,95.206535,29.855673,334.603516,false,DoNotOverride,10.0",
          GUID = "1E0B4690",
          LookAt = {
            [1] = "200002:n(210004)",
            [2] = "100001:n(210004)",
            [3] = "210004:n(210004)"
          },
          NextOptions = {
            [1] = 120013201,
            [2] = 120013202
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{9},ActorId{210004},AnimationId{"Zhiliu_Story_Special02_Start"},Duration{1}},
LookAt{_delay{6},LookAtDescription{"210004:n(100001)"}},
TurnTo{_delay{6.5},TurnToDescription{"210004:n(100001)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "In my homeland, we refer to the chance encounters between people as \"fate.\" Such moments are rare and precious. When it happens, we believe it's worth cherishing — wouldn't you agree?",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "100001:n(210004)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4690"
        },
        [12001321] = {
          Camera = "130.839844,-87.01416,151.46875,0.00015,-13.198083,176.609421,43.803253,210.445709,false,Manual,10.0",
          ContentTC = "白覺得止流姐姐說得很有道理！那白和{nickname}就不客氣啦～",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001321,
          FacialId = {
            [1] = "200002:Smile02"
          },
          GUID = "1E0B46BA",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12001322,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200002:n(210004)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Snow thinks this nice, pretty lady is absolutely right! So, Snow and  will stay! Thank you for having us~",
          TalkActionId = {
            [1] = "200002:Talk03_Start",
            [2] = "210004:Zhiliu_Story_Special02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B46BA"
        },
        [12001322] = {
          Camera = "-29.191406,-99.70166,165.839844,0.000196,-0.599062,67.805344,43.803253,150.779633,false,DoNotOverride,10.0",
          ContentTC = "{nickname}，這是你的名字嗎？真好聽。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001322,
          GUID = "1E0B46E4",
          LookAt = {
            [1] = "210004:n(100001)"
          },
          NextDialogue = 12001323,
          SpeakNpcId = 210004,
          Subtitle = "... Is that your name? It has such a lovely ring to it.",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          TurnTo = {
