            [2] = "100001:Unhappy01",
            [3] = "200002:Angry01"
          },
          GUID = "1E0B4B52",
          LookAt = {
            [1] = "220017:n(220014)",
            [2] = "220045:n(220014)"
          },
          NextDialogue = 12001350,
          SpeakNpcId = 220014,
          Subtitle = "Heh, a little power play, was it? Enough with the excuses. Show me the goods.",
          TalkActionId = {
            [1] = "220014:Talk03_Start",
            [2] = "220018:Talk01_End"
          },
          TurnTo = {
            [1] = "220017:n(220014)",
            [2] = "220045:n(220014)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B52"
        },
        [12001350] = {
          Camera = "144.626953,288.033691,17.613281,0.000053,6.199516,141.999878,35.000008,313.697113,false,Manual,3.5",
          ContentTC = "你要的月髓液，我帶來了。",
          DialogueId = 12001350,
          FacialId = {
            [1] = "220018:CM_Idle"
          },
          GUID = "1E0B4B7C",
          NextDialogue = 12001351,
          SpeakNpcId = 220018,
          Subtitle = "The Phoxichor you asked for — I have it.",
          TalkActionId = {
            [1] = "220018:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B7C"
        },
        [12001351] = {
          Camera = "-38.164062,434.716309,-32.25,0.0,4.803002,-86.580322,40.000011,316.356659,false,DoNotOverride,10.0",
          ContentTC = "白對這個人有點印象……卡蜜拉和我說過，他是這一片惡名昭彰的地下軍火商。他賣的東西貨不對板，還老是想黑吃黑！",
          DialogueId = 12001351,
          FacialId = {
            [1] = "220014:None"
          },
          GUID = "1E0B4BA6",
          NextDialogue = 12001352,
          Scripts = [[
SEQ{
LookAt{_delay{4},LookAtDescription{"200002:n(220014)"}},
LookAt{_delay{3.5},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{1},ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}},
LookAt{_delay{0.1},LookAtDescription{"200002:n(220018)"}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Wait, I know that guy... Camilla told me all about him. He's a notorious underground arms dealer around here. The stuff he peddles is always subpar, and he's always scheming to rip people off!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BA6"
        },
        [12001352] = {
          Camera = "63.847656,460.318359,7.578125,0.000011,9.802803,-126.5784,40.000011,240.677155,false,Manual,4.0",
          ContentTC = "我再確認一下。我要的可不是大街上隨處可見的普通貨色，而是95%以上純度的月髓原液，沒錯吧？",
          DialogueId = 12001352,
          GUID = "1E0B4BD0",
          NextDialogue = 12001353,
          SpeakNpcId = 220014,
          Subtitle = "Allow me to confirm one last time. I am not seeking just any common Phoxichor that can be procured from a street vendor. My requirement is for the highest grade, with a purity of no less than 95%. Is that understood?",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkR_Start",
            [2] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BD0"
        },
        [12001353] = {
          Camera = "-44.837891,371.257324,-0.773438,0.000035,26.402218,125.022018,25.0,158.270889,false,Manual,10.0",
          ContentTC = "符不符合要求，你可以自行檢查──但話說在前頭，我們這裡的規矩是先交錢，再驗貨。請先付錢吧，女士。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001353,
          GUID = "1E0B4BFA",
          NextOptions = {
            [1] = 12001354,
            [2] = 12001355,
            [3] = 12001356
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"637.140625,977.703125,1000.703125,-1.999998,-48.797268,-147.182938,35.000008,158.270889,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"661.132812,993.179199,1033.300781,-1.999999,-48.79726,-147.18251,35.000008,158.270889,false,Manual,10.0"},duration{8}}
}]],
          SpeakNpcId = 220018,
          Subtitle = "You're free to inspect it yourself. But let me make one thing clear — our policy is payment first. Pay up, ma'am, and then it's all yours to examine.",
          TalkActionId = {
            [1] = "220018:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BFA"
        },
        [12001354] = {
          ContentTC = "付錢後，你們拒絕售後該怎麼辦？",
          DialogueId = 12001354,
          GUID = "1E0B4C24",
          ImprPlusId = 1008,
          NextDialogue = 12001357,
          Subtitle = "But what if it's not good enough? Do you offer after-sale service?"
        },
        [12001355] = {
          ContentTC = "這不符合最基本的交易守則。",
          DialogueId = 12001355,
          GUID = "1E0B4C4E",
          ImprPlusId = 1007,
          NextDialogue = 12001357,
          Subtitle = "That goes against the most basic rules of fair trade."
        },
        [12001356] = {
          ContentTC = "以為我們都是傻子嗎？",
          DialogueId = 12001356,
          GUID = "1E0B4C78",
          ImprPlusId = 1010,
          NextDialogue = 12001357,
          Subtitle = "How gullible do you think we are?"
        },
        [12001357] = {
          Camera = "-75.988281,358.869629,53.726562,0.000057,3.402465,-176.978516,25.000006,158.270889,false,Manual,10.0",
          ContentTC = "老大，我們這麼多人，還裝什麼！直接打到她交錢得了！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001357,
          FinalCamera = "-75.574219,350.87207,53.726562,0.000057,3.402465,-176.978516,25.000006,158.270889,false,Manual,10.0",
          GUID = "1E0B4CA2",
          LookAt = {
            [1] = "220017:n(220018)",
            [2] = "220018:n(220017)"
          },
          NextDialogue = 12001358,
          Scripts = "PlayAnimation{_delay{3},ActorId{220017},AnimationId{\"Angry01_Start\"},Duration{1}}",
          SpeakNpcId = 220017,
          Subtitle = "Boss, why bother with this act? We've got the numbers — let's just beat her up and take the money!",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkR_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "220017:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4CA2"
        },
        [12001358] = {
          ContentTC = "唉……你們有沒有想過，面對這樣明目張膽的局，我為何願意孤身前來？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001358,
          FacialId = {
            [1] = "220014:Unhappy01"
          },
          GUID = "1E0B4CCC",
          LookAt = {
            [1] = "220017:n(220014)",
            [2] = "220014:n(220014)"
          },
          NextDialogue = 12001359,
          Scripts = [[
