        [12001506] = {
          Camera = "-123.306641,51.673828,57.578125,0.000084,-6.004364,82.614265,50.096283,616.28064,false,Manual,10.0",
          ContentTC = "（止流從懷中取出一樣小巧玲瓏的物品，並點燃了它。你依稀在書上看過它的描述，這或許是一隻鏤空香爐？）",
