          DialogueId = 12001506,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_IncenseBurner01.T_Guide_Chapter_IncenseBurner01'}",
