          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "1E0B8734",
          NextDialogue = 12001715,
          SpeakNpcId = 200002,
          Subtitle = "In any case — your adventures wouldn't be complete without the great Demon King at your side!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8734"
        },
