        },
        [12001736] = {
          Camera = "-175.340332,270.149841,203.560059,0.000172,-16.199083,-91.996391,54.999645,437.747101,false,Manual,10.0",
          ContentTC = "……什麼嘛，姐姐真小氣。不給就不給，我去別的地方找硬幣！",
