          DialogueId = 12001747,
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "1E0B8C9E",
          NextDialogue = 12001748,
          Scripts = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "What!? Where else would you find a helper as efficient, talented, and — most importantly — adorable as me!?",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8C9E"
        },
        [12001748] = {
