        [12010801] = {
          Camera = "304.855316,544.535767,34.631836,0.000097,7.994593,-130.562805,50.0,100000.0,false,Manual,22",
          ContentTC = "你們來了？玩得怎麼樣？",
          DialogueId = 12010801,
          FinalCamera = "279.991364,515.381226,40.009766,0.000097,7.994593,-129.962708,50.0,100000.0,false,Manual,22",
          GUID = "1E115A0A",
          LookAt = {
            [1] = "100001:n(210004)",
            [2] = "200002:n(210004)"
          },
          NextDialogue = 12010802,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 304003,
            [4] = 406004
          },
          SpeakNpcId = 210004,
          Subtitle = "You have come. So — how was your little tour?",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "210004:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A0A"
        },
        [12010802] = {
          Camera = "-683.570435,-204.253418,151.115234,0.000145,-5.40716,26.220837,35.000008,811.822876,false,Manual,6.0",
          ContentTC = "嗯，大家都很熱情好客。華胥的風光和人們，都和冰湖城大不一樣……",
          DialogueId = 12010802,
          GUID = "1E115A34",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010803,
          SpeakNpcId = 100001,
          Subtitle = "Everyone we met was so nice and welcoming. The sights and people of Huaxu... they're really nothing like Icelake.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A34"
        },
        [12010803] = {
          ContentTC = "剛剛這裡發生的事情我們都看到了！不愧是止流姐姐，三下五除二就把那些人擺平了！",
          DialogueId = 12010803,
          GUID = "1E115A5E",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010804,
          SpeakNpcId = 200002,
          Subtitle = "We also saw what happened down here — you calmed all those Starweavers and handled the whole situation with just a few words! You're amazing!",
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A5E"
        },
        [12010804] = {
          Camera = "-186.132004,148.349823,117.378906,0.000099,12.793374,-73.770279,35.0,167.978699,false,Manual,6.0",
          ContentTC = "呵呵，做生意就是琢磨如何和人打交道。這種小場面，我早就習以為常了。反倒是在冰湖城和你們結交，更為難得。",
          DialogueId = 12010804,
          GUID = "1E115A88",
          NextDialogue = 12010805,
          Scripts = [[
SEQ{
PlayFacial{ActorId{210004},FacialId{"Ahaha01"}},
PlayFacial{_delay{2},ActorId{210004},FacialId{"None"}},
LookAt{LookAtDescription{"210004:n(100001)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Hehe. Business is all about knowing how to deal with people — that's nothing new to me. What's rare... is meeting someone like you.",
          TalkActionId = {
            [1] = "210004:Confident_Start",
            [2] = "200002:Excited02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115A88"
        },
        [12010805] = {
          ContentTC = "好啦，該切入正題了。我這次雇傭你們，是為了解決<H>燭陰之災</>而做準備。至於這燭陰之災是何物……",
          DialogueId = 12010805,
          GUID = "1E115AB2",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010806,
          Scripts = "PlayAnimation{_delay{2},ActorId{210004},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "Now then — let's get to the point. The reason I hired you is to help us prepare for dealing with the Scourge of Zhuyin. As for what that truly is...",
          TalkActionId = {
            [1] = "210004:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115AB2"
        },
        [12010806] = {
          Camera = "-220.036377,-24.106567,165.826172,0.000193,-11.806978,37.620747,25.0,356.590881,false,Manual,6.0",
          ContentTC = "我們已經有所了解啦！",
          DialogueId = 12010806,
          GUID = "1E115ADC",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010807,
          SpeakNpcId = 200002,
          Subtitle = "Oh! We already got a bit of a crash course on that!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115ADC"
        },
        [12010807] = {
          ContentTC = "哦？說來聽聽。",
          DialogueId = 12010807,
          GUID = "1E115B06",
          NextDialogue = 12010808,
          SpeakNpcId = 210004,
          Subtitle = "Hm? Let's hear it.",
          TalkActionId = {
            [1] = "210004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B06"
        },
        [12010808] = {
          Camera = "-156.516678,87.370865,141.241211,0.000193,-1.207092,50.224213,35.000008,157.917465,false,Manual,6.0",
          ContentTC = "過來的路上，我們遭遇了玄色狴犴的襲擊。幸好有位過路的行商相助，我們擊退了它，沒有受傷。",
          DialogueId = 12010808,
          GUID = "1E115B30",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010809,
          Scripts = [[
SEQ{
PlayFacial{ActorId{100001},FacialId{"Sad01"}},
PlayFacial{_delay{3},ActorId{100001},FacialId{"None"}},
LookAt{LookAtDescription{"100001:n(210004)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "On our way here, we were attacked by a Sable Bi'an. Fortunately, a passing trader helped us out, and we managed to drive it off without getting hurt.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B30"
        },
        [12010809] = {
          Camera = "-77.715431,89.802849,133.813477,0.000236,-18.807245,30.218388,35.000008,141.948105,false,Manual,6.0",
          ContentTC = "行商姐姐告訴我們，就是這個什麼燭陰之災，會誕生很多像玄色狴犴一樣的壞東西，然後它們四處咬人，讓大家的日子很難過！",
          DialogueId = 12010809,
          FacialId = {
            [1] = "200002:Think02"
          },
          GUID = "1E115B5A",
          NextDialogue = 12010810,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "She told us the Scourge of Zhuyin creates all kinds of nasty beasts like that Sable Bi'an — and they go around biting people and making life miserable!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B5A"
        },
        [12010810] = {
          Camera = "-172.129272,202.076614,182.18457,0.000255,-10.007812,-82.578522,35.0,230.644745,false,Manual,6.0",
          ContentTC = "不錯。玄色狴犴出現之前，你們可曾看到或聽到什麼異象？",
          DialogueId = 12010810,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E115B84",
          NextDialogue = 12010811,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210004},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{ActorId{210004},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "That's about right. Tell me — before the Sable Bi'an emerged, did either of you notice anything out of place?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115B84"
        },
        [12010811] = {
          Camera = "-115.231911,95.112503,138.404297,0.000265,2.191896,62.419701,35.000008,144.229248,false,Manual,6.0",
          ContentTC = "好像……從虛空中傳來過某種異獸吼叫的聲音。",
          DialogueId = 12010811,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E115BAE",
          NextDialogue = 12010812,
          SpeakNpcId = 100001,
          Subtitle = "I think... there was a roar. It came from the void — sounded like some kind of beast.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115BAE"
        },
        [12010812] = {
          Camera = "-62.248718,279.597717,140.96582,0.000271,0.991805,-101.18074,35.0,357.667114,false,Manual,6.0",
          ContentTC = "是了。那便是數載前被封印的惡蛟，如今正在復蘇中的<H>燭陰</>發出的嘶吼。",
          DialogueId = 12010812,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E115BD8",
          NextDialogue = 12010813,
          RelatedWikiId = {
            [1] = 303011
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210004},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{ActorId{210004},AnimationId{"Talk02_End"},Duration{1}},
}]],
          SpeakNpcId = 210004,
          Subtitle = "Yes... That roar came from Zhuyin, the ancient evil jiaolong once sealed away. It is now stirring from its slumber.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115BD8"
        },
        [12010813] = {
          ContentTC = "燭陰是華胥遠古傳說中，與白龍神君相敵對的惡神。它失智、狂亂的力量泄露而出，使惡獸橫行。部分區域受其影響，也變得草木不生。",
          DialogueId = 12010813,
          FacialId = {
            [1] = "210004:Angry01"
          },
          GUID = "1E115C02",
          NextDialogue = 12010814,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{210004},AnimationId{"Talk03_Start"},Duration{1}},
LookAt{LookAtDescription{"210004:n(200002)"}},
LookAt{_delay{3},LookAtDescription{"210004:n(100001)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "According to Huaxu's oldest myths, Zhuyin is the evil foe of Lord Argent. Its mindless, frenzied power seeps into the realm, unleashing vicious beasts wherever it touches. In those tainted places, even plants refuse to grow.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C02"
        },
        [12010814] = {
          ContentTC = "一百年之前，在煙津渡區域，燭陰之災初顯端倪。時人只能倉皇應對，損失慘重，集結了眾多人力物力才將其降服。",
          DialogueId = 12010814,
          FacialId = {
            [1] = "210004:Think01"
          },
          GUID = "1E115C2C",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010815,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"210004:n(100001)\"}}",
          SpeakNpcId = 210004,
          Subtitle = "About a hundred years ago, the Scourge of Zhuyin was first witnessed at Mistwharf. Back then, the unprepared people of Huaxu only barely managed to contain it — at great cost and heavy loss.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C2C"
        },
        [12010815] = {
          ContentTC = "如今，燭陰再度從封印中復蘇。這次，我打算未雨綢繆，早做準備，避免重蹈上次的覆轍。",
          DialogueId = 12010815,
          FacialId = {
            [1] = "210004:Think01"
          },
          GUID = "1E115C56",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010816,
          SpeakNpcId = 210004,
          Subtitle = "Now, Zhuyin is awakening once more. This time, I intend to stay ahead of the disaster, lest we be caught off guard again.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C56"
        },
        [12010816] = {
          Camera = "-186.98848,-7.478424,161.543945,0.000262,-16.208401,29.619329,35.0,357.667114,false,Manual,6.0",
          ContentTC = "哇，對手真的是一條龍耶，魔王大人已經熱血沸騰起來了！那需要我和小僕從做什麼呢？",
          DialogueId = 12010816,
          FacialId = {
            [1] = "210004:None"
          },
          GUID = "1E115C80",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010817,
          SpeakNpcId = 200002,
          Subtitle = "Wow... fighting against a real loong! The Demon King is fired up already! So — what do you need us to do?",
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115C80"
        },
        [12010817] = {
          Camera = "-159.628098,156.141693,211.294922,0.000275,-23.008387,-83.780457,35.000008,179.894089,false,Manual,6.0",
          ContentTC = "華胥禁武。縱是走南闖北的織星客，也少有人精通防身的一招半式。",
          DialogueId = 12010817,
          GUID = "1E115CAA",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010818,
          SpeakNpcId = 210004,
          Subtitle = "Combats are forbidden in Huaxu. Even the most well-travelled Starweavers know little of how to defend themselves.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_End",
            [2] = "200002:Excited01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115CAA"
        },
        [12010818] = {
          ContentTC = "所以，這次我要委托你們的，便是孤身深入已徹底濁化的塵漠石海，將其中的<W>三片燭陰鱗</>取來，好為重新封印這個孽獸做準備。",
          DialogueId = 12010818,
          GUID = "1E115CD4",
          NextDialogue = 12010819,
          RelatedWikiId = {
            [1] = 301007
          },
          SpeakNpcId = 210004,
          Subtitle = "That is why I am entrusting you with this commission: you shall go alone into the tainted wastes of the Gritblight Expanse, and secure for me three Zhuyin Scales — for they are essential to the sealing ritual.",
          TalkActionId = {
            [1] = "210004:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115CD4"
        },
        [12010819] = {
          Camera = "-199.111633,-43.304016,157.180664,0.000239,-5.408567,52.814674,35.000008,332.602295,false,Manual,6.0",
          ContentTC = "止流掌櫃，可以問您一個問題嗎？",
          DialogueId = 12010819,
          GUID = "1E115CFE",
          NextDialogue = 12010820,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, may I ask you something?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115CFE"
        },
        [12010820] = {
          ContentTC = "這麼重要的任務，您為何放心交給我一個名不經傳的外來者去完成？",
          DialogueId = 12010820,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E115D28",
          NextDialogue = 12010821,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"Talk02_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "This commission... it sounds incredibly important. Why entrust it to an outsider like me?",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115D28"
        },
        [12010821] = {
          Camera = "-105.761864,145.154953,174.711914,0.00001,-19.008606,49.811211,35.0,101.71228,false,Manual,6.0",
          ContentTC = "我只是一個涉世未深的狩月人。比我身手更好的想必還有很多。",
          DialogueId = 12010821,
          GUID = "1E115D52",
          NextDialogue = 12010822,
          SpeakNpcId = 100001,
          Subtitle = "I'm just a green Phoxhunter — I'm sure there are many far more skilled than I am.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115D52"
        },
        [12010822] = {
          ContentTC = "那時候在劇院，當我觸碰香爐時，煙跡像是被吸引了一樣，朝我傾斜……您委托我，和這件事有關係嗎？",
          DialogueId = 12010822,
          GUID = "1E115D7C",
          NextDialogue = 12010823,
          SpeakNpcId = 100001,
          Subtitle = "Back at the theatre, when I touched that censer, the smoke shifted towards me... as if it was drawn in. Does that have something to do with why you chose me?",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115D7C"
        },
        [12010823] = {
          Camera = "-22.771553,316.24408,146.336914,0.000276,0.989838,-110.393227,120.000038,348.983032,false,Manual,6.0",
          ContentTC = "……你卻是敏銳。",
          DialogueId = 12010823,
          FacialId = {
            [1] = "210004:Zhiliu_SpecialDoubt"
          },
          FinalCamera = "-31.808182,319.469513,146.336914,0.000276,1.189867,-108.592857,120.000038,348.983032,false,Manual,6.0",
          GUID = "1E115DA6",
          NextDialogue = 12010824,
          SpeakNpcId = 210004,
          Subtitle = "...You're indeed perceptive.",
          TalkActionId = {
            [1] = "210004:Talk03ToThink_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120108/1E115DA6"
        },
        [12010824] = {
          ContentTC = "相信有人告誡過你了吧，你的能力很特殊，也很珍貴。而珍貴之物往往會引來覬覦。稍有不慎，就會為持有者招致災難。",
          DialogueId = 12010824,
          GUID = "1E115DD0",
          NextDialogue = 12010825,
          SpeakNpcId = 210004,
          Subtitle = "I'm sure someone has already warned you — your ability is rare... and precious. And precious things are always coveted. Handle them carelessly, and they only invite disaster.",
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115DD0"
        },
        [12010825] = {
          Camera = "-135.171982,109.97921,130.675781,0.000303,10.789028,-97.396179,25.000002,108.903717,false,Manual,6.0",
          ContentTC = "燭陰鱗並非常規手段可以采摘。需要一種高濃度活性物質與之共鳴，軟化其束縛。",
          DialogueId = 12010825,
          GUID = "1E115DFA",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010826,
          SpeakNpcId = 210004,
          Subtitle = "The Zhuyin Scales cannot be harvested through normal means. They require resonance with a highly concentrated active substance — only then can their bonds be softened for extraction.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115DFA"
        },
        [12010826] = {
          ContentTC = "我此次前往冰湖城，本是為了試試帝國煉金院的高純度月髓液是否可以生效，卻無意間發現了你的存在——彌足珍貴的「和鳴者」。",
          DialogueId = 12010826,
          GUID = "1E115E24",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010827,
          SpeakNpcId = 210004,
          Subtitle = "Originally, I travelled to Icelake to see if the Imperial Alchemy Academy's high-purity Phoxichor might suffice. But by sheer chance, I met you — someone who possesses the priceless power of Resonance.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115E24"
        },
        [12010827] = {
          Camera = "-63.153351,333.275513,163.25,0.000279,-12.610932,-89.191231,18.000004,386.075989,false,Manual,6.0",
          ContentTC = "我需要借助你的能力去軟化燭陰鱗。當然，你隨時擁有拒絕的權利。一切還是以你的安危為最優先。",
          DialogueId = 12010827,
          GUID = "1E115E4E",
          NextDialogue = 12010828,
          RelatedWikiId = {
            [1] = 203001
          },
          SpeakNpcId = 210004,
          Subtitle = "I need your ability to soften the Zhuyin Scales. Of course, the choice is yours. You may refuse — I would never force you to risk your safety.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115E4E"
        },
        [12010828] = {
          Camera = "-101.410286,105.261276,144.950195,0.000291,0.388911,66.010345,35.000008,115.940376,false,Manual,6.0",
          ContentTC = "不。止流掌櫃，感謝您的答案。這個任務，我接下了。",
          DialogueId = 12010828,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E115E78",
          NextDialogue = 12010829,
          SpeakNpcId = 100001,
          Subtitle = "Thank you for telling me all this, Proprietress Zhiliu. I take this commission.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115E78"
        },
        [12010829] = {
          Camera = "-135.763824,120.127022,133.164062,0.000261,7.987448,-98.385017,35.000011,132.596771,false,Manual,6.0",
          ContentTC = "……你有沒有想過，我對你伸出援手，或許也是看到了你的價值，從而別有用心？",
          DialogueId = 12010829,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E115EA2",
          NextDialogue = 12010830,
          SpeakNpcId = 210004,
          Subtitle = "...Have you ever considered that the reason I helped you back then might not have been out of kindness, but because I saw your worth... and had my own ulterior motive?",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "210004:Talk03ToTalkR_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115EA2"
        },
        [12010830] = {
          Camera = "-233.40567,-36.296333,167.799805,0.000267,-10.612488,39.615959,25.0,351.067688,false,Manual,6.0",
          ContentTC = "我想過，但這改變不了您幫助過我的事實。況且，我也有自己的私心。",
          DialogueId = 12010830,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "1E115ECC",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12010831,
          SpeakNpcId = 100001,
          Subtitle = "Actually, I have. But that doesn't change the fact that you did help me. And I have my own selfish reasons, too.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "210004:Talk03ToTalkR_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115ECC"
        },
        [12010831] = {
          Camera = "-143.548096,187.029388,180.547852,0.000277,-26.612356,2.415056,25.0,173.153748,false,Manual,6.0",
          ContentTC = "我在尋找自己的家人，但我一個人的力量過於渺小。為了達到這個目的，我會抓住一切可以憑借的外力。",
          DialogueId = 12010831,
          GUID = "1E115EF6",
          NextDialogue = 12010832,
          Scripts = "PlayFacial{_delay{1.5},ActorId{200002},FacialId{\"Sad03\"}}",
          SpeakNpcId = 100001,
          Subtitle = "I'm searching for my family. But I'm powerless to do it alone. To reach that goal, I'll cling to any strength I can find.",
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115EF6"
        },
        [12010832] = {
          ContentTC = "如果幫助您可以換取未來某些時刻的援手，我想這是一筆相當劃算的交易。",
          DialogueId = 12010832,
          GUID = "1E115F20",
          NextDialogue = 12010833,
          SpeakNpcId = 100001,
          Subtitle = "If helping you means I can count on your help someday... I'd say that's a trade well worth making.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F20"
        },
        [12010833] = {
          Camera = "-51.572311,328.859131,154.874023,0.000277,-4.212703,-99.382347,35.000011,410.635406,false,Manual,6.0",
          ContentTC = "更何況，您最初幫我解圍之時，我對您而言只是一個隨處可見的路人。您幫了我，我也想為您做點什麼。",
          DialogueId = 12010833,
          GUID = "1E115F4A",
          NextDialogue = 12010834,
          SpeakNpcId = 100001,
          Subtitle = "Besides, when we first met at the theatre, you didn't know I had this power. I was just a stranger to you. You didn't have to help me — and yet you did. Now... I want to return that favour.",
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F4A"
        },
        [12010834] = {
          Camera = "-127.131332,108.307777,133.397461,0.000372,7.585963,-100.998802,25.000006,108.903717,false,Manual,6.0",
          ContentTC = "呵呵……話都被你說盡了，我卻沒什麼可說的了。看來假以時日，你也會成為一個優秀的「商人」。",
          DialogueId = 12010834,
          FacialId = {
            [1] = "210004:Smile03"
          },
          GUID = "1E115F74",
          NextDialogue = 12010835,
          Scripts = "PlayFacial{_delay{3},ActorId{210004},FacialId{\"Smile01\"}}",
          SpeakNpcId = 210004,
          Subtitle = "Hehe... You've covered every perspective. I've nothing to add. Given time, you might just make an excellent \"merchant\" yourself.",
          TalkActionId = {
            [1] = "210004:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F74"
        },
        [12010835] = {
          ContentTC = "在你出發前，那邊桌子上有給你準備的盤纏。隨意花，不夠了再來向我要。",
          DialogueId = 12010835,
          FacialId = {
            [1] = "210004:None"
          },
          GUID = "1E115F9E",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(100001)"
          },
          SpeakNpcId = 210004,
          Subtitle = "Before you leave — there's a pouch on the table. It's for your travelling expenses. Spend it as you see fit. If you run short, feel free to come back for more.",
          TalkActionId = {
            [1] = "210004:Explain01L_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120108/1E115F9E"
        },
        [12010901] = {
          Camera = "276.747314,112.712646,37.357422,0.00115,11.20263,-175.58313,25.0,199.450333,false,Manual,4.0",
          ContentTC = "讓白掂量掂量……哇，沉甸甸的錢包，這麼多！止流老板太大氣了！",
          DialogueId = 12010901,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_FullMoneyBag.T_Guide_Chapter_FullMoneyBag'}",
          GUID = "1E116A72",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(200002)"
          },
          NextDialogue = 12010902,
          Scripts = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Please01_Loop\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Lemme see... Whoa, this pouch is heavy! Miss Zhiliu, you're really generous!",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116A72"
        },
        [12010902] = {
          Camera = "276.747314,112.712646,37.357422,0.00115,11.20263,-175.58313,25.0,199.450333,false,Manual,4.0",
          ContentTC = "只是些小錢罷了。你們放心支配，不必拘謹。",
          DialogueId = 12010902,
          FinalCamera = "276.747314,112.712646,37.357422,0.001156,11.002628,-173.182861,25.0,410.377594,false,Manual,4.0",
          GUID = "1E116A9C",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010903,
          SpeakNpcId = 210004,
          Subtitle = "Just a bit of pocket money. Feel free to use it however you see fit.",
          TalkActionId = {
            [1] = "210004:Explain01_Start"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1201/120109/1E116A9C"
        },
        [12010903] = {
          Camera = "117.907089,99.72242,100.063477,0.001367,9.598478,-161.603653,50.000008,218.943039,false,Manual,4.0",
          ContentTC = "采摘燭陰鱗需要用到<W>某種特製的工具</>，我先前托一些……道上的朋友準備了。",
          DialogueId = 12010903,
          GUID = "1E116AC6",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010904,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1.5},ActorId{210004},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{3.5},ActorId{210004},AnimationId{"Talk03_Start"},Duration{1}},
}]],
          SpeakNpcId = 210004,
          Subtitle = "You'll also need a special tool to collect the Zhuyin Scales. I arranged it through some... connections.",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116AC6"
        },
        [12010904] = {
          Camera = "-91.798035,-58.921486,145.460938,0.001206,-6.398227,74.011063,35.0,283.8638,false,Manual,4.0",
          ContentTC = "但由於玄色狴犴肆虐，通訊斷絕，至今還未送來。可能需要你親自去取。",
          DialogueId = 12010904,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E116AC7",
          NextOptions = {
            [1] = 120109041,
            [2] = 120109042
          },
          SpeakNpcId = 210004,
          Subtitle = "But with the Sable Bi'an rampaging, our usual lines of communication were cut off. It still hasn't been delivered. You'll likely have to go and fetch it yourself.",
          TalkActionId = {
            [1] = "200002:Please01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116AC7"
        },
        [12010905] = {
          Camera = "109.405472,216.004333,142.260742,0.001217,-4.798187,-140.989746,35.0,308.470398,false,Manual,4.0",
          ContentTC = "做生意，難免遇到些棘手的事宜，需要交由他人處理。",
          DialogueId = 12010905,
          GUID = "1E116B1A",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010906,
          SpeakNpcId = 210004,
          Subtitle = "In business, there are always... delicate matters best handled by certain \"professionals.\"",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B1A"
        },
        [12010906] = {
          ContentTC = "在華胥，那些見不得光……遊走於法理邊緣的生意，多在沉船林立的西岸黑市中達成交易。你去那裡，找一位叫做虬先生的人，他會交代你後續的步驟。",
          DialogueId = 12010906,
          GUID = "1E116B44",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12010907,
          RelatedWikiId = {
            [1] = 408012
          },
          Scripts = [[
SEQ{
PlayAnimation{_delay{2},ActorId{210004},AnimationId{"DisagreeHead"},Duration{1}},
LookAt{_delay{6},LookAtDescription{"210004:n(100001)"}},
}]],
          SpeakNpcId = 210004,
          Subtitle = "Here in Huaxu, the sorts of dealings that prefer to stay in the shadows usually happen at the black market among the shipwrecks on the western shore. Go there and find a man named Mr Qiu. He'll give you your next steps.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B44"
        },
        [12010907] = {
          Camera = "-96.494217,-40.735981,142.348633,0.00132,-4.398792,71.811882,35.000008,236.057159,false,Manual,4.0",
          ContentTC = "你是生面孔，難以取信於他們。",
          DialogueId = 12010907,
          GUID = "1E116B6E",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010908,
          SpeakNpcId = 210004,
          Subtitle = "But you are new faces. They won't trust you right away.",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B6E"
        },
        [12010908] = {
          Camera = "109.405472,216.004333,142.260742,0.001217,-4.798187,-140.989746,35.0,308.470398,false,Manual,4.0",
          ContentTC = "按照規矩，初次造訪黑市的人，要從沿海洞窟行出，腰上佩飾特定的掛墜。他們見著這「暗號」對上了，就會知道你是自己人。",
          DialogueId = 12010908,
          GUID = "1E116B98",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010909,
          SpeakNpcId = 210004,
          Subtitle = "By custom, first-time visitors to the black market have to come through the coastal cavern, wearing a special pendant at their waist. If the signal matches, they'll know you're one of ours.",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116B98"
        },
        [12010909] = {
          Camera = "-19.247467,268.217834,206.660156,0.001299,-34.998592,-66.185158,35.0,247.601944,false,Manual,4.0",
          ContentTC = "嗯嗯，白和小僕從要扮演危險角色……這感覺對味了！",
          DialogueId = 12010909,
          FacialId = {
            [1] = "200002:Smile02"
          },
          GUID = "1E116BC2",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12010910,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{200002},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"Talk01_Start"},Duration{2}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Alright! So my Little Minion and I get to play the badasses this time? That sounds like a job for us!",
          VoiceName = "voice/$Locale$/story/1201/120109/1E116BC2"
        },
        [12010910] = {
          Camera = "57.356339,167.022995,108.945312,0.001361,7.798546,-135.000778,50.000008,218.943039,false,Manual,4.0",
          ContentTC = "你們從百年春的正門出去，往右手邊就能遙看到沿海洞窟的入口。這也是通往黑市的捷徑。",
          DialogueId = 12010910,
          GUID = "1E116BEC",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12010911,
          SpeakNpcId = 210004,
          Subtitle = "Exit through EverSpring's main gate and look to the right. In the distance, you'll see the entrance to the coastal cavern — that's a shortcut to the black market.",
          TalkActionId = {
            [1] = "210004:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116BEC"
        },
        [12010911] = {
          ContentTC = "想必不用我再叮囑什麼了……{nickname}，我等著你平安歸來。",
          DialogueId = 12010911,
          GUID = "1E116C16",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          Scripts = "LookAt{_delay{4},LookAtDescription{\"210004:n(100001)\"}}",
          SpeakNpcId = 210004,
          Subtitle = "I trust I don't need to say more... I'll be waiting for your safe return, .",
          TalkActionId = {
            [1] = "210004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120109/1E116C16"
        },
        [12011001] = {
          ContentTC = "沿海洞窟……看來就是前面那裡了。",
          DialogueId = 12011001,
          Duration = 2,
          GUID = "1E117ADA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12011002,
          SpeakNpcId = 100001,
          Subtitle = "A coastal cave... looks like that's the place.",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117ADA"
        },
        [12011002] = {
          ContentTC = "白還記得和小僕從第一次探險，也是下洞窟，仿佛就像昨天剛剛發生一樣！",
          DialogueId = 12011002,
          Duration = 4,
          GUID = "1E117B04",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12011003,
          SpeakNpcId = 200002,
          Subtitle = "Do you remember our first adventure together, Little Minion? We went down into a cave that time too — it feels like it was just yesterday!",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B04"
        },
        [12011003] = {
          ContentTC = "誰想到轉眼間，我們就來到這麼遠的地方，肩負這麼激動人心的大使命——",
          DialogueId = 12011003,
          Duration = 4,
          GUID = "1E117B2E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12011004,
          SpeakNpcId = 200002,
          Subtitle = "And now look at us — all the way out here, so far from home, on some epic, destiny-shaping quest!",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B2E"
        },
        [12011004] = {
          ContentTC = "……嗯。那次遇到了奧特賽德，敲了他一頓竹杠。賽琪……也還在。",
          DialogueId = 12011004,
          Duration = 3,
          GUID = "1E117B58",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12011005,
          SpeakNpcId = 100001,
          Subtitle = "...Yeah. That time we ran into Outsider and kind of... shook him down. And Psyche... was still with us back then.",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B58"
        },
        [12011005] = {
          ContentTC = "白、白說錯話了……",
          DialogueId = 12011005,
          Duration = 2,
          GUID = "1E117B82",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 12011006,
          SpeakNpcId = 200002,
          Subtitle = "I—I'm sorry... I didn't mean to upset you...",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117B82"
        },
        [12011006] = {
          ContentTC = "沒關係。等我們回去，再到淚湖邊去，把華胥的見聞說給她聽吧。",
          DialogueId = 12011006,
          Duration = 5,
          GUID = "1E117BAC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "It's alright. Once we're back, let's visit Lamenting Lake and tell her everything we've seen in Huaxu.",
          VoiceName = "voice/$Locale$/story/1201/120110/1E117BAC"
        },
        [12011101] = {
          ContentTC = "喂——喂——有人嗎？",
          DialogueId = 12011101,
          Duration = 2,
          GUID = "1E118B42",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12011102,
          SpeakNpcId = 200002,
          Subtitle = "Hellooo—! Anyone here?",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118B42"
        },
        [12011102] = {
          ContentTC = "看，小僕從！這裡黑布隆冬的，說話還會有回音耶。你會怕黑嗎？",
          DialogueId = 12011102,
          Duration = 3,
          GUID = "1E118B6C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12011103,
          SpeakNpcId = 200002,
          Subtitle = "Whoa, it's so pitch black in here! And even our voices echo. Are you scared of the dark, Little Minion?",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118B6C"
        },
        [12011103] = {
          ContentTC = "不怕。但是我們說話聲音最好壓低些，當心引來什麼奇怪的東西。",
          DialogueId = 12011103,
          Duration = 3,
          GUID = "1E118B96",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Not really. But we'd better keep our voices down — no telling what we might attract.",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118B96"
        },
        [12011104] = {
          ContentTC = "……哇啊！！",
          DialogueId = 12011104,
          Duration = 2,
          GUID = "1E118BC0",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Waaaah!!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E118BC0"
        },
        [12011201] = {
          ContentTC = "呸、呸！好的不靈壞的靈，小僕從簡直是烏鴉嘴——",
          DialogueId = 12011201,
          Duration = 2,
          GUID = "1E119BAA",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 12011202,
          SpeakNpcId = 200002,
          Subtitle = "Ugh! Way to go, Little Minion! Thanks for jinxing us and drawing that thing here!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E119BAA"
        },
        [12011202] = {
          ContentTC = "又是玄色狴犴，它們的數量怎麼越來越多了！",
          DialogueId = 12011202,
          Duration = 2,
          GUID = "1E119BD4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Another Sable Bi'an... Where do they keep coming from!?",
          VoiceName = "voice/$Locale$/story/1201/120112/1E119BD4"
        },
        [12011301] = {
          ContentTC = "留神——",
          DialogueId = 12011301,
          Duration = 3,
          GUID = "1E11AC12",
          Subtitle = "Watch out—",
          VoiceName = "voice/$Locale$/story/1201/120113/1E11AC12"
        },
        [12011401] = {
          Camera = "189.114975,196.35614,114.457275,0.000174,-10.806698,-159.432999,25.000006,417.040405,false,Manual,22.0",
          ContentTC = "剛剛真是多謝你了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011401,
          FinalCamera = "189.114975,196.35614,114.457275,0.000178,-3.606934,-159.432861,25.000006,417.040405,false,Manual,22.0",
          GUID = "1E11BC7A",
          LookAt = {
            [1] = "210007:n(100001)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011402,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003
          },
          SpeakNpcId = 100001,
          Subtitle = "You saved us — thank you.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BC7A"
        },
        [12011402] = {
          Camera = "-28.935848,42.242939,103.689453,0.000091,5.793749,-179.624237,35.000011,179.031601,false,Manual,6.0",
          ContentTC = "不用，本是職責所在。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011402,
          GUID = "1E11BCA4",
          NextDialogue = 12011403,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "It's okay. I am merely fulfilling my duty.",
          TalkActionId = {
            [1] = "210007:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BCA4"
        },
        [12011403] = {
          Camera = "-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0",
          ContentTC = "……職責所在？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011403,
          FacialId = {
            [1] = "200002:Think02"
          },
          GUID = "1E11BCCE",
          LookAt = {
            [1] = "210007:n(200002)",
            [2] = "100001:n(200002)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011404,
          SpeakNpcId = 200002,
          Subtitle = "...Your duty?",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BCCE"
        },
        [12011404] = {
          Camera = "-65.706345,52.841057,121.108398,0.000078,-25.203888,24.986763,30.000002,118.231079,false,Manual,6.0",
          ContentTC = "唔，是卡戎，還很能打……你該不會是錦鯉皎皎提到的<H>應天尉</>吧？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011404,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E11BCF8",
          LookAt = {
            [1] = "100001:n(210007)"
          },
          NextDialogue = 12011405,
          RelatedWikiId = {
            [1] = 405010
          },
          SpeakNpcId = 200002,
          Subtitle = "Hmm, you're a Charon — and you fight really well... Wait, are you one of those Magistrates of Yingtian that Lunocarp mentioned?",
          TalkActionId = {
            [1] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BCF8"
        },
        [12011405] = {
          Camera = "-17.535795,38.415855,82.101318,0.00012,12.593161,179.576218,35.000011,179.03125,false,Manual,6.0",
          ContentTC = "……我奉命來此肅清玄色狴犴。如今眾敵環伺，職責未盡，恕我無暇閑聊。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011405,
          GUID = "1E11BD22",
          NextDialogue = 12011406,
          Scripts = "PlayAnimation{_delay{3},ActorId{210007},AnimationId{\"DisagreeHead\"},Duration{1}},",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...I was assigned to purge the Sable Bi'an here. With danger still looming, my duty remains. I have no time for idle chatter.",
          TalkActionId = {
            [1] = "210007:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BD22"
        },
        [12011406] = {
          Camera = "-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0",
          ContentTC = "奉誰的命？我們等會兒出去好好謝謝人家！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011406,
          GUID = "1E11BD4C",
          NextDialogue = 12011407,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Please01_Start\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Assigned by who? We'll go thank them properly once we're out of here!",
          TalkActionId = {
            [1] = "200002:Excited01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BD4C"
        },
        [12011407] = {
          Camera = "87.904099,67.988495,63.705566,0.000245,7.791149,173.780365,25.000006,308.831635,false,Manual,6.0",
          ContentTC = "大風九章，天命。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011407,
          GUID = "1E11BD76",
          NextDialogue = 12011408,
          Scripts = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Please01_End\"},Duration{1}},",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The Nine Chapters of Dafeng. The Mandate of Heaven.",
          TalkActionId = {
            [1] = "210007:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BD76"
        },
        [12011408] = {
          ContentTC = "對哦，好像確實有這麼一回事……那白和小僕從回頭要狠狠地奉幾根香！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011408,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1E11BDA0",
          NextDialogue = 12011409,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0"},duration{0}},  
PlayAnimation{_delay{2},ActorId{200002},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{_delay{0},ActorId{200002},AnimationId{"Excited02_Start"},Duration{1}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Oh, right — yeah, that's a thing... then we're definitely offering up a lot more incense once we're out!",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BDA0"
        },
        [12011409] = {
          Camera = "-51.653706,32.12328,121.247803,0.000206,-23.807735,39.170685,25.000006,119.064056,false,Manual,6.0",
          ContentTC = "說起來，剛剛續上的香，和玄色狴犴剛打一個照面就用完了。還真是不經用……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011409,
          FacialId = {
            [1] = "200002:Sad03"
          },
          GUID = "1E11BDCA",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 12011410,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"DisagreeHead\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Speaking of which — the incense we just replaced ran out the second we faced that beast. Total rip-off if you ask me...",
          TalkActionId = {
            [1] = "200002:Excited02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BDCA"
        },
        [12011410] = {
          Camera = "-65.107132,57.948006,89.911133,0.000238,13.191348,-170.82811,25.000006,142.201553,false,Manual,6.0",
          ContentTC = "若香已散盡，以我一人之力，恐難護得二位周全。二位若無要事，還請速速離去，尋一安穩之所。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011410,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E11BDF4",
          LookAt = {
            [1] = "210007:n(210007)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011411,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"-200.116669,-11.065613,123.176758,0.000067,-9.803622,38.17627,20.000008,277.233246,false,Manual,6.0"},duration{0}},
PlayAnimation{_delay{2},ActorId{210007},AnimationId{"DisagreeHead"},Duration{2}}
}]],
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "If your incense has burned out, I may not be able to keep you both safe on my own. If you have no urgent business here, I suggest you leave for safer ground.",
          TalkActionId = {
            [1] = "210007:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BDF4"
        },
        [12011411] = {
          Camera = "-35.692829,-53.15213,91.663574,0.000249,5.190643,81.783882,35.000011,238.308868,false,Manual,6.0",
          ContentTC = "謝謝，不過我們有一點自保能力，不用擔心。我們需要去洞窟對面辦一件事，希望不會給你添麻煩。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011411,
          GUID = "1E11BE1E",
          LookAt = {
            [1] = "210007:n(100001)"
          },
          NextDialogue = 12011412,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Explain01L_Start\"},Duration{1}},",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but we can protect ourselves. We have something to take care of on the far side of this cave — that's why we came in. I hope we haven't been a bother.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE1E"
        },
        [12011412] = {
          Camera = "77.085526,178.859253,127.048584,0.000261,-3.609953,-158.824905,35.000011,303.13736,false,Manual,6.0",
          ContentTC = "洞窟對面？據我所知，那裡除岸灘擱淺的沉船殘闕外，別無旁物。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011412,
          FacialId = {
            [1] = "210007:Think01"
          },
          GUID = "1E11BE48",
          NextDialogue = 12011413,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The far side? As far as I know, there's nothing there but some beached wreckage.",
          TalkActionId = {
            [1] = "210007:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE48"
        },
        [12011413] = {
          Camera = "77.085526,178.859253,127.048584,0.000261,-3.609953,-158.824905,35.000011,303.13736,false,Manual,6.0",
          ContentTC = "沒錯，就是那處沉船黑市！白和小僕從要去那裡談一樁大生意！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011413,
          FacialId = {
            [1] = "200002:Smile02"
          },
          GUID = "1E11BE72",
          NextDialogue = 12011414,
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"-228.367401,-38.505424,133.859619,0.00008,-16.40362,35.188114,30.0,306.177948,false,Manual,6.0\"},duration{0}},",
          SpeakNpcId = 200002,
          Subtitle = "Exactly! We're going to the black market among the shipwrecks! We have a big business deal to settle there!",
          TalkActionId = {
            [1] = "210007:Think_End",
            [2] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE72"
        },
        [12011414] = {
          Camera = "15.423389,62.95097,58.172363,0.000279,14.786286,-172.234375,35.000011,215.125885,false,Manual,6.0",
          ContentTC = "黑市、談生意？兩位若非要與雞鳴狗盜之輩為伍，我也無話可說。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011414,
          FacialId = {
            [1] = "210007:Angry01"
          },
          GUID = "1E11BE9C",
          LookAt = {
            [1] = "210007:n(210007)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011415,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The black market... for business? If you insist on mingling with swindlers and scoundrels, I have nothing more to say.",
          TalkActionId = {
            [1] = "210007:Talk03_Start",
            [2] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BE9C"
        },
        [12011415] = {
          Camera = "-20.366999,-42.464127,13.334961,0.000288,25.588646,77.37146,35.000011,257.516388,false,Manual,14.0",
          ContentTC = "怎、怎麼辦，小僕從？！我們好像被他誤解了……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011415,
          FacialId = {
            [1] = "200002:Shock02"
          },
          GUID = "1E11BEC6",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12011416,
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh... what do we do, Little Minion? He totally misunderstood us...",
          TalkActionId = {
            [1] = "200002:Shock03_Start",
            [2] = "100001:Explain01L_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BEC6"
        },
        [12011416] = {
          ContentTC = "事情不是你想的那樣。我們受止流掌櫃雇傭，為了解決玄色狴犴肆虐的問題，需要去黑市取一樣工具。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011416,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E11BEF0",
          LookAt = {
            [1] = "210007:n(100001)",
            [2] = "100001:n(210007)",
            [3] = "200002:n(210007)"
          },
          NextDialogue = 12011417,
          Scripts = "CameraMoveTo{_delay{1},TargetPosition{\"65.418396,174.380295,125.57373,0.000325,-3.813841,-158.644958,35.000011,319.544312,false,Manual,6.0\"},duration{0}},",
          SpeakNpcId = 100001,
          Subtitle = "It's not what you think. We're here on an assignment from Proprietress Zhiliu — to help deal with the Sable Bi'an outbreak. There's a tool we need to retrieve from the black market.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BEF0"
        },
        [12011417] = {
          Camera = "-74.738007,65.379562,128.82251,0.000274,-25.813593,17.363806,35.000011,115.267303,false,Manual,6.0",
          ContentTC = "就是，才不是去做什麼偷雞摸狗的事情呢！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011417,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E11BF1A",
          NextDialogue = 12011418,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Explain02_Start\"},Duration{1}},",
          SpeakNpcId = 200002,
          Subtitle = "Exactly! We're not doing anything shady, thank you very much!",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF1A"
        },
        [12011418] = {
          Camera = "-35.568024,20.937334,182.430664,0.000227,-24.613787,173.365738,35.000011,196.696289,false,Manual,6.0",
          ContentTC = "……抱歉。是我武斷了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011418,
          FacialId = {
            [1] = "210007:Sad01"
          },
          GUID = "1E11BF44",
          LookAt = {
            [1] = "210007:n(210007)"
          },
          NextDialogue = 12011419,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...My apologies. It was hasty of me to pass judgement.",
          TalkActionId = {
            [1] = "210007:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF44"
        },
        [12011419] = {
          ContentTC = "話雖如此，黑市之人魚龍混雜，你們需當心甄別，莫被欺瞞利用了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011419,
          FacialId = {
            [1] = "210007:None"
          },
          GUID = "1E11BF6E",
          NextDialogue = 12011420,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "Still, that place harbours all manner of folk. Beware of deceit and manipulation.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF6E"
        },
        [12011420] = {
          Camera = "189.114975,196.35614,114.457275,0.000178,-3.606934,-159.432861,25.000006,417.040405,false,Manual,22.0",
          ContentTC = "此地不安全，讓我護送你們過去吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011420,
          GUID = "1E11BF98",
          Scripts = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Explain02_End\"},Duration{1}},",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "This cavern is not safe. Allow me to escort you across.",
          TalkActionId = {
            [1] = "210007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E11BF98"
        },
        [12011501] = {
          ContentTC = "應天尉就是華胥的衛戍部隊吧！你們有工資拿嗎，待遇怎麼樣呀？",
          DialogueId = 12011501,
          Duration = 3,
          GUID = "1E11CCE2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12011502,
          SpeakNpcId = 200002,
          Subtitle = "So, Magistrates of Yingtian are kind of like the Escort of Huaxu, right? Do you guys get paid? Any special perks?",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CCE2"
        },
        [12011502] = {
          ContentTC = "……",
          DialogueId = 12011502,
          Duration = 1,
          GUID = "1E11CD0C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12011503,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD0C"
        },
        [12011503] = {
          ContentTC = "好啦好啦。白知道了，白不問這些了。",
          DialogueId = 12011503,
          Duration = 2,
          GUID = "1E11CD36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 12011504,
          SpeakNpcId = 200002,
          Subtitle = "Alright, alright, I get it. I won't pry.",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD36"
        },
        [12011504] = {
          ContentTC = "我為應天尉，只願濟蒼生，安黎元，並非為那些身外俗物。",
          DialogueId = 12011504,
          Duration = 2,
          GUID = "1E11CD60",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 12011505,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "As a Magistrate of Yingtian, I serve only to safeguard the people and bring peace to the land. I did not assume this role for worldly gain.",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD60"
        },
        [12011505] = {
          ContentTC = "……小僕從你聽，就是不發工資的意思咯？比帝國還摳門！",
          DialogueId = 12011505,
          Duration = 2,
          GUID = "1E11CD8A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Hear that, Little Minion? That means they don't get paid. Guess the higher-ups here are even more tight-fisted than those of the Empire, huh?",
          VoiceName = "voice/$Locale$/story/1201/120115/1E11CD8A"
        },
        [12011601] = {
          ContentTC = "前方恐有玄色狴犴蟄伏，由我開路。請兩位緊隨我身後。",
          DialogueId = 12011601,
          Duration = 3,
          GUID = "1E11DD4A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "There may be more Sable Bi'an lurking ahead. I'll take the lead. Please stay close behind me.",
          VoiceName = "voice/$Locale$/story/1201/120116/1E11DD4A"
        },
        [12011701] = {
          Camera = "185.545456,-74.591217,6.828125,0.000015,14.198753,155.402176,14.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "出口在前方。我便護送兩位到這裡為止。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011701,
          FinalCamera = "170.985962,-103.135139,6.828125,0.000016,13.998766,151.002472,14.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1E11EDB2",
          NextDialogue = 12011709,
          Scripts = [[
