          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "The exit lies just ahead. This is where I leave you.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120117/1E11EDB2"
        },
        [12011702] = {
          Camera = "29.643166,-184.535736,100.408203,0.000144,-18.606226,57.386753,25.000006,79.312019,false,Manual,6.0",
          ContentTC = "那傢伙，雖然說話冷冰冰的，但是心地還不錯嘛。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12011702,
          FinalCamera = "29.643166,-184.535736,100.408203,0.000124,7.393843,72.986702,25.000006,257.354767,false,Manual,6.0",
          GUID = "1E11EDDC",
          LookAt = {
