          SpeakNpcId = 100001,
          Subtitle = "Those Luno doodles are a dead giveaway. If someone comes asking, don't expect me to cover for you.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120120/1E1224A8"
        },
        [12012037] = {
          ContentTC = "時候不早了，我們趕緊去黑市吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012037,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E1224D2",
          SpeakNpcId = 100001,
          Subtitle = "It's getting late. Let's head to the black market.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120120/1E1224D2"
        },
        [12012040] = {
          ContentTC = "小僕從，這裡看起來很隱蔽，我們就把他藏在這個地方吧！",
          DialogueId = 12012040,
          Duration = 3,
          GUID = "1E1224D3",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, this places looks perfect, let's hide him here!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1224D3"
        },
        [12012101] = {
          Camera = "1756.186523,733.326172,500.082031,0.000011,-8.799899,-159.191101,28.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "兩位小朋友，迷路啦？這裡可不是你們該來的地方。快回去找你們的媽媽吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012101,
          FacialId = {
            [1] = "100001:Curious",
            [2] = "200002:Doubt01"
          },
          FinalCamera = "1486.267578,630.740234,455.382324,0.000011,-9.399911,-160.591064,28.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E122F52",
