}]],
          SpeakNpcId = 210008,
          Subtitle = "Well now — what are you two kids doing here? You sure you're in the right place? Best run home to your mothers while you still can.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120121/1E122F52"
        },
        [12012102] = {
          ContentTC = "白和{nickname}才不是什麼小朋友！放輕鬆，大家都是自己人。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012102,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E122F7C",
          LookAt = {
            [1] = "100001:n(210008)",
            [2] = "200002:n(210008)",
            [3] = "210008:n(100001)",
            [4] = "210058:n(100001)",
            [5] = "210059:n(100001)"
          },
          NextDialogue = 12012103,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"44.402344,53.082031,103.226074,0.000066,-8.399534,85.207184,35.000008,216.311829,false,Manual,2.8"},duration{0}},
