PlayFacial{_delay{3},ActorId{200002},FacialId{"Happy02"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "We're not little kids! Chill out — we're one of yours.",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
