        },
        [12012103] = {
          Camera = "107.163086,635.803711,119.184082,0.000074,0.000055,-101.398521,58.782524,664.486511,false,Manual,2.8",
          ContentTC = "自己人……我瞅著怎麼面生呢？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012103,
          FacialId = {
            [1] = "200002:None",
            [2] = "210008:Cin_Angry01"
