            [2] = "200002:n(210008)",
            [3] = "210008:n(100001)",
            [4] = "210058:n(100001)",
            [5] = "210059:n(100001)"
          },
          NextDialogue = 12012104,
          SpeakNpcId = 210008,
          Subtitle = "One of us, huh? Funny, I don't remember those faces.",
