  {
    MinKey = 12012607,
    MaxKey = 12013902,
    Loader = function()
      return {
        [12012607] = {
          Camera = "-205.837891,-1341.109863,120.132812,0.000046,-2.399493,-174.205383,65.0,685.305847,true,Manual,2.8",
          ContentTC = "帶了幫手是吧。今天不管多少人來，我都叫他吃不了兜著走！",
          DialogueId = 12012607,
          GUID = "1E128256",
          SpeakNpcId = 210009,
          Subtitle = "So you brought backup, huh? I don't care how many you've got — nobody messes with my business and walks away unscathed!",
          TalkActionId = {
            [1] = "100001:Angry01_Start",
            [2] = "210009:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120126/1E128256"
        },
        [12012608] = {
          ContentTC = "你控製力道，將對方製服，卻沒有留下傷口。",
          DialogueId = 12012608,
          GUID = "1E128280",
          Subtitle = "You held back just enough to subdue him without drawing blood.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128280"
        },
        [12012609] = {
          Camera = "944.539062,-331.335449,256.336914,0.000019,-7.799679,166.403183,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "夠了——不可怠慢貴客！",
          DialogueId = 12012609,
          GUID = "1E1282AA",
          NextDialogue = 12012610,
          SpeakNpcId = 210010,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Enough — mind your manners in front of our guest!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1282AA"
        },
        [12012610] = {
          ContentTC = "是我們沒有及時察覺您的到來，讓您看了這場鬧劇……我家主人<H>虬先生</>有請您移步沉船內部的會客廳，進行商談。",
          DialogueId = 12012610,
          GUID = "1E1282D4",
          NextDialogue = 12012611,
          RelatedWikiId = {
            [1] = 203005
          },
          SpeakNpcId = 210010,
          Subtitle = "We failed to notice your arrival and let this little farce unfold before you — our apologies. My master, Mr Qiu, invites you aboard the wreck to his parlour for a private discussion.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1282D4"
        },
        [12012611] = {
          ContentTC = "我怎麼知道，這不是為了調開我而使的計倆？",
          DialogueId = 12012611,
          GUID = "1E1282FE",
          NextDialogue = 12012612,
          SpeakNpcId = 100001,
          Subtitle = "How do I know this isn't just an excuse to trick me into leaving?",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1282FE"
        },
        [12012612] = {
          ContentTC = "您且安心。您的朋友就是我們的朋友。萬一朋友在我們的地盤上出了事，我們也不好向止流掌櫃交代。",
          DialogueId = 12012612,
          GUID = "1E128328",
          NextDialogue = 12012613,
          SpeakNpcId = 210010,
          Subtitle = "Rest assured — your friends are our friends. If anything were to happen to her on our turf, we'd have to answer to Proprietress Zhiliu as well.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128328"
        },
        [12012613] = {
          ContentTC = "是，是，都是朋友！原來是誤會一場啊！",
          DialogueId = 12012613,
          GUID = "1E128352",
          NextDialogue = 12012614,
          SpeakNpcId = 210009,
          Subtitle = "Y—Yes, of course! All friends here! Just a little misunderstanding, that's all!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128352"
        },
        [12012614] = {
          ContentTC = "咱今兒就把珍藏的藥材都拿出來，給小友賠罪。一定給她的傷口包紮仔細了，讓她賓至如歸呀。",
          DialogueId = 12012614,
          GUID = "1E12837C",
          NextDialogue = 12012615,
          SpeakNpcId = 210009,
          Subtitle = "We'll bring out our best medicine for the young lady — patch her up real good, make sure she's feeling right at home!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E12837C"
        },
        [12012615] = {
          ContentTC = "這樣處理，您滿意嗎？",
          DialogueId = 12012615,
          GUID = "1E1283A6",
          NextDialogue = 12012616,
          SpeakNpcId = 210010,
          Subtitle = "Does this arrangement meet your satisfaction?",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1283A6"
        },
        [12012616] = {
          ContentTC = "這傢伙變臉這麼快，真是氣人！",
          DialogueId = 12012616,
          GUID = "1E1283D0",
          NextDialogue = 12012617,
          SpeakNpcId = 200002,
          Subtitle = "How can someone put on a new face that fast? Ugh — makes me sick!",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1283D0"
        },
        [12012617] = {
          ContentTC = "你們……",
          DialogueId = 12012617,
          GUID = "1E1283FA",
          NextDialogue = 12012618,
          SpeakNpcId = 100001,
          Subtitle = "You...",
          VoiceName = "voice/$Locale$/story/1201/120126/1E1283FA"
        },
        [12012618] = {
          ContentTC = "算了。帶路吧，我之後再來看她。",
          DialogueId = 12012618,
          GUID = "1E128424",
          SpeakNpcId = 100001,
          Subtitle = "Fine. Lead the way. I'll come check on her later.",
          VoiceName = "voice/$Locale$/story/1201/120126/1E128424"
        },
        [12012701] = {
          Camera = "69.70105,1077.539062,187.139709,0.0,-5.999931,-101.595413,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "有朋自遠方來，幸甚至哉。",
          DialogueId = 12012701,
          GUID = "1E1291C2",
          NextDialogue = 12012702,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012,
            [4] = 203005
          },
          SpeakNpcId = 210012,
          Subtitle = "What a joy it is to welcome friends from afar.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1291C2"
        },
        [12012702] = {
          ContentTC = "你們黑市人，平時就是這樣行事嗎？",
          DialogueId = 12012702,
          GUID = "1E1291EC",
          NextDialogue = 12012703,
          SpeakNpcId = 100001,
          Subtitle = "Is this how you people do business in the black market?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1291EC"
        },
        [12012703] = {
          ContentTC = "小友恰好撞見了比較極端的個例，但我並不打算否認這種生存之道。",
          DialogueId = 12012703,
          GUID = "1E129216",
          NextDialogue = 12012704,
          SpeakNpcId = 210012,
          Subtitle = "You simply stumbled upon an extreme case. But I won't deny — it's one of many ways to survive.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129216"
        },
        [12012704] = {
          ContentTC = "竟然承認了……無恥！",
          DialogueId = 12012704,
          GUID = "1E129240",
          NextDialogue = 12012705,
          SpeakNpcId = 200002,
          Subtitle = "Wow, you're really just admitting it like it's nothing? That's... shameless!",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129240"
        },
        [12012705] = {
          ContentTC = "哈哈……要說到禮義廉恥，我倒是有一個問題想要請教。",
          DialogueId = 12012705,
          GUID = "1E12926A",
          NextDialogue = 12012706,
          SpeakNpcId = 210012,
          Subtitle = "Haha... speaking of shame, let me pose a question of my own.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12926A"
        },
        [12012706] = {
          ContentTC = "昔日華胥一隅，有群羊，又有一猛虎。猛虎捕食群羊，羔羊為虎所食，不得安生。",
          DialogueId = 12012706,
          GUID = "1E129294",
          NextDialogue = 12012707,
          SpeakNpcId = 210012,
          Subtitle = "Once, in a quiet corner of Huaxu, there was a flock of sheep — and a single tiger. The tiger hunted the sheep at his leisure, and the sheep cowered in constant fear.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129294"
        },
        [12012707] = {
          ContentTC = "此時一俠義之士路過，羔羊便向那俠士哭求，請他垂憐庇護，令羊群免受求生之苦。",
          DialogueId = 12012707,
          GUID = "1E1292BE",
          NextDialogue = 12012708,
          SpeakNpcId = 210012,
          Subtitle = "One day, a wandering hero passed by. The sheep wept and begged him to shield them from the beast.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1292BE"
        },
        [12012708] = {
          ContentTC = "俠士可憐羔羊羸弱，便回應羊群祈願，盡逐當地猛獸。又去了羔羊頂角，使它們不至於誤傷同類。俠義之士離去後，羊群睦然而居，繁衍壯大。",
          DialogueId = 12012708,
          GUID = "1E1292E8",
          NextDialogue = 12012709,
          SpeakNpcId = 210012,
          Subtitle = "Moved by their plight, the hero drove off every predator that threatened the sheep. He also dulled their horns, so they wouldn't wound each other by mistake. With the danger gone, the flock lived in harmony and flourished.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1292E8"
        },
        [12012709] = {
          ContentTC = "然，多年後一日，羊群中再次闖入一隻新的猛虎。羊群折了角，逃跑的功夫又日久生疏，最後全數夭於虎口。",
          DialogueId = 12012709,
          GUID = "1E129312",
          NextDialogue = 12012710,
          SpeakNpcId = 210012,
          Subtitle = "But years later, a new tiger came among them... Their horns were dulled, and the instinct to flee long forgotten — until at last, every one of them perished in the tiger's maw.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129312"
        },
        [12012710] = {
          ContentTC = "這個故事裡，你們認為何者犯了<H>最大的錯誤</>呢？",
          DialogueId = 12012710,
          GUID = "1E12933C",
          NextOptions = {
            [1] = 120127101,
            [2] = 120127102,
            [3] = 120127103,
            [4] = 120127104
          },
          SpeakNpcId = 210012,
          Subtitle = "So... tell me — who in this story do you believe made the gravest mistake?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12933C"
        },
        [12012711] = {
          ContentTC = "虎以羊為食，此乃天性使然。",
          DialogueId = 12012711,
          GUID = "1E129366",
          NextDialogue = 12012713,
          SpeakNpcId = 210012,
          Subtitle = "Tigers prey on sheep — that's simply nature's way.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129366"
        },
        [12012712] = {
          ContentTC = "哈哈……所見略同。",
          DialogueId = 12012712,
          GUID = "1E129390",
          NextDialogue = 12012713,
          SpeakNpcId = 210012,
          Subtitle = "Heh... it seems we see eye to eye.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129390"
        },
        [12012713] = {
          ContentTC = "故事裡的羔羊就能全然置身事外嗎？在天敵面前全無自保之力，只能垂首乞憐，寄希望於他人援手。",
          DialogueId = 12012713,
          GUID = "1E1293BA",
          NextDialogue = 12012716,
          SpeakNpcId = 210012,
          Subtitle = "The sheep, were they truly blameless? Faced with a natural predator, they had no means to protect themselves — only pitiful bleats and blind hope that someone else would save them.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1293BA"
        },
        [12012714] = {
          ContentTC = "你想說什麼？",
          DialogueId = 12012714,
          GUID = "1E1293E4",
          NextDialogue = 12012715,
          SpeakNpcId = 100001,
          Subtitle = "What are you trying to say?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1293E4"
        },
        [12012715] = {
          ContentTC = "既然小友心中尚無定數，那虯某就給一個答案吧：犯下最大錯誤的既非猛虎，也非俠士，而是看似最無辜的羊群。",
          DialogueId = 12012715,
          GUID = "1E12940E",
          NextDialogue = 12012716,
          SpeakNpcId = 210012,
          Subtitle = "If you haven't found your own answer, allow me to offer mine. The gravest mistake wasn't the tiger's, nor the hero's — but the sheep's, the ones who seemed the most innocent.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12940E"
        },
        [12012716] = {
          ContentTC = "正是它們放棄自保，向俠士搖尾乞憐，才招致了最終的滅亡。",
          DialogueId = 12012716,
          GUID = "1E129438",
          NextDialogue = 12012717,
          SpeakNpcId = 210012,
          Subtitle = "They gave up every means of defence, wagged their tails, and begged for rescue — thus sealing their fate.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129438"
        },
        [12012717] = {
          ContentTC = "物競天擇，適者生存，自然界本是如此。為什麼人類卻滿口仁義道德，以弱者自居，以順服為榮呢？",
          DialogueId = 12012717,
          GUID = "1E129462",
          NextDialogue = 12012718,
          SpeakNpcId = 210012,
          Subtitle = "Survival of the fittest — that is the law of nature. So why do humans take no shame in weakness and elevate submission as if it were some noble virtue?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129462"
        },
        [12012718] = {
          ContentTC = "在我看來，道德不過是弱者的遮羞布。逐利才是人之本性。",
          DialogueId = 12012718,
          GUID = "1E12948C",
          NextDialogue = 12012719,
          SpeakNpcId = 210012,
          Subtitle = "To me, morality is nothing more than a fig leaf for the powerless. The pursuit of profit — that is our true nature.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12948C"
        },
        [12012719] = {
          ContentTC = "但凡有人類這種生物的地方，便伴隨著支配與臣服。若有人自願拔去爪牙，拋下劍盾，把力量交給虛無縹緲的「規則」，那也怪不得我們這樣的人存在了。",
          DialogueId = 12012719,
          GUID = "1E1294B6",
          NextDialogue = 12012720,
          SpeakNpcId = 210012,
          Subtitle = "Wherever humans exist, so too does domination and submission. If someone willingly pulls out their claws, casts aside their shield and blade, and puts all their faith in some vague idea called \"rules\"... Then people like me are merely the consequence.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1294B6"
        },
        [12012720] = {
          ContentTC = "……聽你的意思，你追求的是一個人人都可以不受約束，肆意欺淩他人的世界。",
          DialogueId = 12012720,
          GUID = "1E1294E0",
          NextDialogue = 12012721,
          SpeakNpcId = 100001,
          Subtitle = "...So you're saying your ideal world is one where everyone's free to hurt each other with no limits at all?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1294E0"
        },
        [12012721] = {
          ContentTC = "但我不喜歡。我不想被人拿劍指著，也對拿劍指著別人沒興趣。",
          DialogueId = 12012721,
          GUID = "1E12950A",
          NextDialogue = 12012722,
          SpeakNpcId = 100001,
          Subtitle = "Well, I don't want to live under someone else's blade — and I've got no interest in holding one over anyone else either.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12950A"
        },
        [12012722] = {
          ContentTC = "哈哈！小友心思純粹，倒是襯得吾輩蠅營狗苟了。",
          DialogueId = 12012722,
          GUID = "1E129534",
          NextDialogue = 12012723,
          SpeakNpcId = 210012,
          Subtitle = "Heh... such a pure heart, my young friend. It does make my petty dealings seem all the more sordid by comparison.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129534"
        },
        [12012723] = {
          ContentTC = "閑聊到此為止吧。這就是止流掌櫃托付我打造的工具，你拿好了。",
          DialogueId = 12012723,
          GUID = "1E12955E",
          NextDialogue = 12012724,
          SpeakNpcId = 210012,
          Subtitle = "Alright, enough philosophy. This is the tool Proprietress Zhiliu commissioned — take it.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12955E"
        },
        [12012724] = {
          ContentTC = "讓白看看，怪模怪樣的……方盒子？",
          DialogueId = 12012724,
          GUID = "1E129588",
          NextDialogue = 12012725,
          SpeakNpcId = 200002,
          Subtitle = "Let me see... it's a weird-looking... square box, isn't it?",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129588"
        },
        [12012725] = {
          ContentTC = "它以失傳的機樞派技藝鍛造而成，光是湊齊所需材料便費了不少功夫。",
          DialogueId = 12012725,
          GUID = "1E1295B2",
          NextDialogue = 12012726,
          SpeakNpcId = 210012,
          Subtitle = "It was forged using the long-lost techniques of the Jishu Sect. Just gathering the materials took no small effort.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1295B2"
        },
        [12012726] = {
          ContentTC = "至於其中妙用……去請教它的鍛造者吧。公尚師傅想必已迫不及待地要顯擺自己的手藝了，他就在塵漠石海的入口處等著你們。",
          DialogueId = 12012726,
          GUID = "1E1295DC",
          NextDialogue = 12012727,
          SpeakNpcId = 210012,
          Subtitle = "As for how it works... ask its creator. Master Gongshang is likely itching to show it off. You'll find him waiting at the entrance to the Gritblight Expanse.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E1295DC"
        },
        [12012727] = {
          ContentTC = "沒什麼別的事，我告辭了。",
          DialogueId = 12012727,
          GUID = "1E129606",
          NextDialogue = 12012728,
          SpeakNpcId = 100001,
          Subtitle = "If that's all, then I'll take my leave.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129606"
        },
        [12012728] = {
          ContentTC = "小友留步片刻。",
          DialogueId = 12012728,
          GUID = "1E129630",
          NextDialogue = 12012729,
          SpeakNpcId = 210012,
          Subtitle = "Hold on, young friend.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129630"
        },
        [12012729] = {
          ContentTC = "順手帶上這支竹笛吧。狴犴造成的傷口並非普通人能承受，這支竹笛或許能發揮意想不到的功用。",
          DialogueId = 12012729,
          GUID = "1E12965A",
          NextDialogue = 12012730,
          SpeakNpcId = 210012,
          Subtitle = "Take this bamboo flute with you. Wounds left by the Bi'an are not something ordinary folk can easily endure. This flute may prove unexpectedly useful.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E12965A"
        },
        [12012730] = {
          ContentTC = "就當做是……我對你的「投資」好了。",
          DialogueId = 12012730,
          GUID = "1E129684",
          SpeakNpcId = 210012,
          Subtitle = "Think of it as... my little investment in you.",
          VoiceName = "voice/$Locale$/story/1201/120127/1E129684"
        },
        [12012801] = {
          ContentTC = "這個叫做虬先生的傢伙總是皮笑肉不笑的，真不想和他打交道……",
          DialogueId = 12012801,
          Duration = 2,
          GUID = "1E12A22A",
          NextDialogue = 12012802,
          SpeakNpcId = 200002,
          Subtitle = "That Mr Qiu guy always smiles like he doesn't mean it. I really don't want to deal with him...",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A22A"
        },
        [12012802] = {
          ContentTC = "這就怕了？",
          DialogueId = 12012802,
          Duration = 2,
          GUID = "1E12A254",
          NextDialogue = 12012803,
          SpeakNpcId = 100001,
          Subtitle = "You're scared of him already?",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A254"
        },
        [12012803] = {
          ContentTC = "你、你說什麼呢！光之魔王大人頂天立地，怎麼會有害怕的東西！",
          DialogueId = 12012803,
          Duration = 3,
          GUID = "1E12A27E",
          NextDialogue = 12012804,
          SpeakNpcId = 200002,
          Subtitle = "N—No way! The Demon King of Light fears nothing! I stand tall — no fear in sight!",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A27E"
        },
        [12012804] = {
          ContentTC = "好啦好啦，不拿你開玩笑了。",
          DialogueId = 12012804,
          Duration = 2,
          GUID = "1E12A2A8",
          NextDialogue = 12012805,
          SpeakNpcId = 100001,
          Subtitle = "Hehe. I was just teasing you.",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A2A8"
        },
        [12012805] = {
          ContentTC = "他們在照顧那個女孩。還好，他們還算信守承諾。",
          DialogueId = 12012805,
          Duration = 2,
          GUID = "1E12A2D2",
          NextDialogue = 12012806,
          SpeakNpcId = 100001,
          Subtitle = "They're tending to her... At least they kept their promise.",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A2D2"
        },
        [12012806] = {
          ContentTC = "誒，但是她的狀態看起來不太好……我們也去看看吧！",
          DialogueId = 12012806,
          Duration = 2,
          GUID = "1E12A2FC",
          SpeakNpcId = 200002,
          Subtitle = "But she looks awful... C'mon, let's check on her!",
          VoiceName = "voice/$Locale$/story/1201/120128/1E12A2FC"
        },
        [12012901] = {
          ContentTC = "沒想到她身子骨這麼弱……挨了狴犴一下便長臥不起了。",
          DialogueId = 12012901,
          GUID = "1E12B292",
          NextDialogue = 12012902,
          SpeakNpcId = 210008,
          Subtitle = "Didn't expect her to be this frail... One strike from the Bi'an, and she's been bedridden ever since.",
          VoiceName = "voice/$Locale$/story/1201/120129/1E12B292"
        },
        [12012902] = {
          ContentTC = "這下就算是神仙妙手來了，也無力回天了吧。",
          DialogueId = 12012902,
          GUID = "1E12B2BC",
          SpeakNpcId = 210009,
          Subtitle = "At this rate, not even a miracle could save her.",
          VoiceName = "voice/$Locale$/story/1201/120129/1E12B2BC"
        },
        [12013001] = {
          ContentTC = "什麼人，走路不看路的嗎？",
          DialogueId = 12013001,
          Duration = 2,
          GUID = "1E12C2FA",
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012
          },
          SpeakNpcId = 210008,
          Subtitle = "Hey—! Watch where you're going!",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C2FA"
        },
        [12013002] = {
          ContentTC = "我說，這裡可是黑市的地盤……嘁，真是怪人。",
          DialogueId = 12013002,
          Duration = 2,
          GUID = "1E12C324",
          SpeakNpcId = 210009,
          Subtitle = "You do realise this is black market territory...? Tch. What a weirdo.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C324"
        },
        [12013003] = {
          ContentTC = "……你受傷了。痛嗎？",
          DialogueId = 12013003,
          Duration = 2,
          GUID = "1E12C34E",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "...You are injured. Does it hurt?",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C34E"
        },
        [12013004] = {
          ContentTC = "不要緊，忍耐片刻就好。",
          DialogueId = 12013004,
          Duration = 2,
          GUID = "1E12C378",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "Be at ease — bear with it but a moment.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C378"
        },
        [12013005] = {
          ContentTC = "你看似多有勞累。",
          DialogueId = 12013005,
          Duration = 2,
          GUID = "1E12C3A2",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "You look weary.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C3A2"
        },
        [12013006] = {
          ContentTC = "我會為你調理，以免積勞成疾。",
          DialogueId = 12013006,
          Duration = 2,
          GUID = "1E12C3CC",
          SpeakNpcName = "UI_Npc_Name_QiZhiShuLi",
          Subtitle = "Let me ease your fatigue — before it takes deeper root.",
          VoiceName = "voice/$Locale$/story/1201/120130/1E12C3CC"
        },
        [12013101] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "如此，你的疲累應該已無大礙。",
          DialogueId = 12013101,
          GUID = "1E12D362",
          NextDialogue = 12013102,
          SpeakNpcId = 210013,
          Subtitle = "It is done. You'll get well soon.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D362"
        },
        [12013102] = {
          ContentTC = "這位受傷的姑娘，是你們的朋友嗎？",
          DialogueId = 12013102,
          GUID = "1E12D38C",
          NextDialogue = 12013103,
          SpeakNpcId = 210013,
          Subtitle = "Is this young lady a friend of yours?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D38C"
        },
        [12013103] = {
          ContentTC = "……抱歉，我還未介紹名姓。我是<H>祝由</>扶疏，以家族世代傳承的<H>枯榮之法</>，為惡疾纏身之人祛痛排濁。",
          DialogueId = 12013103,
          GUID = "1E12D3B6",
          NextDialogue = 12013104,
          RelatedWikiId = {
            [1] = 405012,
            [2] = 203006
          },
          SpeakNpcId = 210013,
          Subtitle = "...Forgive me. I have yet to introduce myself. I'm Fushu, a healer who uses Zhuyou therapy. I practise the Art of Ephemerality passed down through my line — to cleanse affliction and expel foulness that clings to the suffering.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D3B6"
        },
        [12013104] = {
          ContentTC = "你的意思是……你是一位醫生？",
          DialogueId = 12013104,
          GUID = "1E12D3E0",
          NextDialogue = 12013105,
          SpeakNpcId = 100001,
          Subtitle = "So... you're a doctor?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D3E0"
        },
        [12013105] = {
          ContentTC = "在華胥，枯榮之法與醫藥之學並非同一原理。但如果醫師這一稱呼會讓你覺得方便，倒也無妨——或者簡單一點，喚我「扶疏」便可。",
          DialogueId = 12013105,
          GUID = "1E12D40A",
          NextDialogue = 12013106,
          RelatedWikiId = {
            [1] = 304005
          },
          SpeakNpcId = 210013,
          Subtitle = "In Huaxu, the Art of Ephemerality and the practice of medicine do not share the same roots. Yet if calling me a doctor brings you ease, I shall not object. Or if you prefer, simply call me Fushu.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D40A"
        },
        [12013106] = {
          ContentTC = "二位認識這位姑娘嗎？",
          DialogueId = 12013106,
          GUID = "1E12D434",
          NextOptions = {
            [1] = 120131061,
            [2] = 120131062
          },
          SpeakNpcId = 210013,
          Subtitle = "Do you know this young lady?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D434"
        },
        [12013107] = {
          ContentTC = "我無法根治她的病痛。可否了解她的傷因何而起？",
          DialogueId = 12013107,
          GUID = "1E12D45E",
          NextDialogue = 12013108,
          SpeakNpcId = 210013,
          Subtitle = "I cannot cleanse this affliction entirely. May I inquire... how did she come by these wounds?",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D45E"
        },
        [12013108] = {
          ContentTC = "她的傷口是狴犴造成的，但她不是什麼壞人。",
          DialogueId = 12013108,
          GUID = "1E12D488",
          NextDialogue = 12013109,
          SpeakNpcId = 100001,
          Subtitle = "Her wounds were caused by a Bi'an. But she's not a criminal.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D488"
        },
        [12013109] = {
          ContentTC = "她是被黑市的壞傢伙陷害，才被大風九章懲罰的！你不要放棄她……",
          DialogueId = 12013109,
          GUID = "1E12D4B2",
          NextDialogue = 12013110,
          SpeakNpcId = 200002,
          Subtitle = "She was framed by some bad guys in the black market! That's why the Nine Chapters punished her! Please... don't give up on her.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D4B2"
        },
        [12013110] = {
          ContentTC = "我明白了。枯榮之術同樣源於大風九章，因此我的力量無法治愈狴犴的傷。我會將她帶回照料，尋找有無他法。",
          DialogueId = 12013110,
          GUID = "1E12D4DC",
          NextDialogue = 12013111,
          SpeakNpcId = 210013,
          Subtitle = "I see. The Art of Ephemerality is drawn from the same source as the Nine Chapters, and thus cannot mend wounds wrought by a Bi'an. I shall take her with me and seek out other remedies.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D4DC"
        },
        [12013111] = {
          ContentTC = "你……",
          DialogueId = 12013111,
          GUID = "1E12D506",
          NextDialogue = 12013112,
          SpeakNpcId = 210013,
          Subtitle = "You...",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D506"
        },
        [12013112] = {
          ContentTC = "誒，扶疏姐姐為什麼老盯著小僕從看呀，難道小僕從還有什麼沒治好的傷？",
          DialogueId = 12013112,
          GUID = "1E12D530",
          NextDialogue = 12013113,
          SpeakNpcId = 200002,
          Subtitle = "Huh? Why are you staring at my Little Minion like that, Miss Fushu? Wait... don't tell me my Little Minion's still got some hidden injury that needs treatment!",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D530"
        },
        [12013113] = {
          ContentTC = "抱歉，我並非有意。你身體並無大礙。只是，你攜帶的那支竹笛似是故人之物，對我意義重大。",
          DialogueId = 12013113,
          GUID = "1E12D55A",
          NextDialogue = 12013114,
          SpeakNpcId = 210013,
          Subtitle = "...Forgive my staring. It was unseemly of me. Your form is sound. Rather... it was that bamboo flute of yours. It resembles a relic once held by one dear to me.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D55A"
        },
        [12013114] = {
          ContentTC = "諒我冒昧，可否將這支竹笛轉讓與我？我會盡力給出相應的報酬。",
          DialogueId = 12013114,
          GUID = "1E12D584",
          NextOptions = {
            [1] = 120131141,
            [2] = 120131142,
            [3] = 120131143
          },
          SpeakNpcId = 210013,
          Subtitle = "If I might be so bold — would you part with it? I would repay you, by whatever means I may.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D584"
        },
        [12013115] = {
          ContentTC = "枯榮之術不圖回報。這是家訓，扶疏不敢違背。",
          DialogueId = 12013115,
          GUID = "1E12D5AE",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "The Art of Ephemerality is not to be bartered for gain. Such is the teaching of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D5AE"
        },
        [12013116] = {
          ContentTC = "不能平白受人恩惠。這是家訓，扶疏不敢違背。",
          DialogueId = 12013116,
          GUID = "1E12D5D8",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D5D8"
        },
        [12013117] = {
          ContentTC = "理應如此。",
          DialogueId = 12013117,
          GUID = "1E12D602",
          NextDialogue = 12013118,
          SpeakNpcId = 210013,
          Subtitle = "You speak with reason.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D602"
        },
        [12013118] = {
          ContentTC = "不能平白受人恩惠。這是家訓，扶疏不敢違背。",
          DialogueId = 12013118,
          GUID = "1E12D62C",
          NextDialogue = 12013119,
          SpeakNpcId = 210013,
          Subtitle = "To accept a gift unearned is a violation of the teachings of my line — one I dare not transgress.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D62C"
        },
        [12013119] = {
          ContentTC = "只是我現在身無長物，就當我賒了這筆賬吧。作為回報，日後你若有需要我的事，凡力所能及，扶疏在所不辭。",
          DialogueId = 12013119,
          GUID = "1E12D656",
          NextDialogue = 12013120,
          SpeakNpcId = 210013,
          Subtitle = "But I have nothing of worth on my person now. Thus let me offer this instead: should you ever call upon me, if it lies within my power — I shall not refuse.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D656"
        },
        [12013120] = {
          ContentTC = "它對我們只是一支普通的竹笛，遠不如對你而言的價值。來，給你。",
          DialogueId = 12013120,
          GUID = "1E12D680",
          NextDialogue = 12013121,
          SpeakNpcId = 100001,
          Subtitle = "To us, it's just a flute. But to you, it clearly means much more. Here — take it.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D680"
        },
        [12013121] = {
          ContentTC = "多謝。還請二位告知名姓吧，扶疏定不相忘。",
          DialogueId = 12013121,
          GUID = "1E12D6AA",
          NextOptions = {
            [1] = 120131211,
            [2] = 120131212
          },
          SpeakNpcId = 210013,
          Subtitle = "Much obliged. Might I know your names? I shall keep them close to heart.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6AA"
        },
        [12013122] = {
          ContentTC = "嗯，我讀過些風物誌，「公爵」應是海伯利亞帝國的貴族。只是這「下水道」……",
          DialogueId = 12013122,
          GUID = "1E12D6D4",
          NextDialogue = 12013123,
          SpeakNpcId = 210013,
          Subtitle = "Hmm... I have read some travel accounts from abroad. \"Duke\" appears to be a noble title in the Hyperborean Empire. As for the \"Sewers\"...",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6D4"
        },
        [12013123] = {
          ContentTC = "無事，興許是我的認知已經跟不上如今的時代了。",
          DialogueId = 12013123,
          GUID = "1E12D6FE",
          NextDialogue = 12013124,
          SpeakNpcId = 210013,
          Subtitle = "Never mind. Perhaps it is simply that I am out of touch with the times.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D6FE"
        },
        [12013124] = {
          ContentTC = "開個玩笑……我是{nickname}。這位皎皎叫白。",
          DialogueId = 12013124,
          GUID = "1E12D728",
          NextDialogue = 12013125,
          SpeakNpcId = 100001,
          Subtitle = "Just kidding. I'm  and this little Luno is Snow.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D728"
        },
        [12013125] = {
          ContentTC = "好的，{nickname}，白。",
          DialogueId = 12013125,
          GUID = "1E12D752",
          NextDialogue = 12013126,
          SpeakNpcId = 210013,
          Subtitle = "Understood. It's nice to meet you, , and Snow.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D752"
        },
        [12013126] = {
          ContentTC = "那我便不耽誤二位的行程了，回見。",
          DialogueId = 12013126,
          GUID = "1E12D77C",
          SpeakNpcId = 210013,
          Subtitle = "Then I shall delay you no longer. See you.",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D77C"
        },
        [12013127] = {
          ContentTC = "咳、咳……！",
          DialogueId = 12013127,
          Duration = 4,
          GUID = "1E12D7A6",
          Subtitle = "*cough* *cough*",
          VoiceName = "voice/$Locale$/story/1201/120131/1E12D7A6"
        },
        [12013201] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你……扶疏姐姐，你怎麼了？！",
          DialogueId = 12013201,
          GUID = "1E12E3CA",
          NextDialogue = 12013202,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 408012,
            [4] = 405012,
            [5] = 203006
          },
          SpeakNpcId = 200002,
          Subtitle = "Hey—! What's wrong, Miss Fushu!?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E3CA"
        },
        [12013202] = {
          ContentTC = "……無妨。",
          DialogueId = 12013202,
          GUID = "1E12E3F4",
          NextDialogue = 12013203,
          SpeakNpcId = 210013,
          Subtitle = "...It's nothing.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E3F4"
        },
        [12013203] = {
          ContentTC = "以自身氣血化如甘霖，引渡患者體內病穢傷痛凝成的濁氣，則為<H>枯榮</>。",
          DialogueId = 12013203,
          GUID = "1E12E41E",
          NextDialogue = 12013204,
          RelatedWikiId = {
            [1] = 304005
          },
          SpeakNpcId = 210013,
          Subtitle = "To perform the Art of Ephemerality is to draw upon one's own essence, pulling forth the miasma of pain and corruption from another's body.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E41E"
        },
        [12013204] = {
          ContentTC = "自燭陰之災以來，傷者眾多，我連日使用枯榮之法，氣血周轉不濟，從而失態了，請二位勿要介懷。",
          DialogueId = 12013204,
          GUID = "1E12E448",
          NextDialogue = 12013205,
          SpeakNpcId = 210013,
          Subtitle = "Since the resurgence of the Scourge of Zhuyin, those in need have only grown more numerous. I have used this technique each day; the strain has left my energy unbalanced — hence this brief faltering. Please... be not alarmed.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E448"
        },
        [12013205] = {
          ContentTC = "自身氣血……小僕從，這又是什麼意思？",
          DialogueId = 12013205,
          GUID = "1E12E472",
          NextDialogue = 12013206,
          SpeakNpcId = 200002,
          Subtitle = "One's own essence? What does that mean, Little Minion?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E472"
        },
        [12013206] = {
          ContentTC = "扶疏，你的意思是……枯榮之法就是以命換命？",
          DialogueId = 12013206,
          GUID = "1E12E49C",
          NextDialogue = 12013207,
          SpeakNpcId = 100001,
          Subtitle = "Fushu... Are you saying that this technique trades your life for theirs?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E49C"
        },
        [12013207] = {
          ContentTC = "你的家人……不會很擔心嗎？",
          DialogueId = 12013207,
          GUID = "1E12E4C6",
          NextDialogue = 12013208,
          SpeakNpcId = 100001,
          Subtitle = "What about your family? Aren't they worried about you?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E4C6"
        },
        [12013208] = {
          ContentTC = "……",
          DialogueId = 12013208,
          GUID = "1E12E4F0",
          NextDialogue = 12013209,
          SpeakNpcId = 210013,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E4F0"
        },
        [12013209] = {
          ContentTC = "家中傳下了排濁化清的秘法，只要休憩片刻就好。",
          DialogueId = 12013209,
          GUID = "1E12E51A",
          NextDialogue = 12013210,
          SpeakNpcId = 210013,
          Subtitle = "My family passed down a secret method of purification and renewal. A brief rest, and I shall be restored.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E51A"
        },
        [12013210] = {
          ContentTC = "哎呀氣死我了，那個叫煜明的傢伙也是，華胥的卡戎怎麼都不把自己的身體當一回事……簡直是一個模子刻出來的！",
          DialogueId = 12013210,
          GUID = "1E12E544",
          NextDialogue = 12013211,
          SpeakNpcId = 200002,
          Subtitle = "Ugh! This is so frustrating! She's just like that Yuming guy — why do all the Charons of Huaxu act like their own health doesn't matter!?",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E544"
        },
        [12013211] = {
          ContentTC = "枯榮流轉，月盈而虧。祛除病痛，自然也要付出等量的代價。",
          DialogueId = 12013211,
          GUID = "1E12E56E",
          NextDialogue = 12013212,
          SpeakNpcId = 210013,
          Subtitle = "Life waxes and wanes, like the moon in its cycle. To remove another's suffering is to take it into oneself. Such is the price.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E56E"
        },
        [12013212] = {
          ContentTC = "…………",
          DialogueId = 12013212,
          GUID = "1E12E598",
          NextDialogue = 12013213,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E598"
        },
        [12013213] = {
          ContentTC = "我要即刻出發尋找治愈這姑娘的法子，先失陪了。你們且去忙碌，若你們想看望她，可往北部杏林中的枯榮閣尋我。",
          DialogueId = 12013213,
          GUID = "1E12E5C2",
          RelatedWikiId = {
            [1] = 405013
          },
          SpeakNpcId = 210013,
          Subtitle = "I must depart at once to seek a remedy for this young lady. Forgive my abrupt leave-taking. Pray, continue on your path — and should you wish to see her again, you will find me at the Hall of Ephemerality, in the northern apricot grove.",
          VoiceName = "voice/$Locale$/story/1201/120132/1E12E5C2"
        },
        [12013301] = {
          ContentTC = "雖然她說休息一會兒就好，但剛才她都吐血了……真的不要緊嗎？",
          DialogueId = 12013301,
          GUID = "1E12F432",
          NextDialogue = 12013302,
          SpeakNpcId = 200002,
          Subtitle = "She said she just needed rest, but she coughed up blood... Is she really going to be okay?",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F432"
        },
        [12013302] = {
          ContentTC = "如果說枯榮之術就是消耗自己的生命救人，那她這樣也有一部分是因為我……",
          DialogueId = 12013302,
          GUID = "1E12F45C",
          NextDialogue = 12013303,
          SpeakNpcId = 100001,
          Subtitle = "If the Art of Ephemerality really draws on one's life to save another... then I'm partially responsible for what she's going through.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F45C"
        },
        [12013303] = {
          ContentTC = "等我們完成止流的差事，就去看看扶疏和那個女孩的情況吧。",
          DialogueId = 12013303,
          GUID = "1E12F486",
          NextDialogue = 12013304,
          SpeakNpcId = 100001,
          Subtitle = "Let's finish Proprietress Zhiliu's commission first. Then we'll check in on Fushu and the young lady.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F486"
        },
        [12013304] = {
          ContentTC = "說起來，小僕從用一支笛子換取了頂級醫生的諾言！這就是那個虬先生的意圖嗎？",
          DialogueId = 12013304,
          GUID = "1E12F4B0",
          NextDialogue = 12013305,
          SpeakNpcId = 200002,
          Subtitle = "We've got a top-tier healer on our side — and all it took was a bamboo flute! Was that Mr Qiu's plan from the start?",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F4B0"
        },
        [12013305] = {
          ContentTC = "天上不會掉麵包。他給我們的好處，以後肯定也會從我們這裡討回來。",
          DialogueId = 12013305,
          GUID = "1E12F4DA",
          NextDialogue = 12013306,
          SpeakNpcId = 100001,
          Subtitle = "Nothing comes without a price. Whatever he gave us, he'll collect on it later — with interest.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F4DA"
        },
        [12013306] = {
          ContentTC = "虬先生……我們還是對他警惕些吧。",
          DialogueId = 12013306,
          GUID = "1E12F504",
          SpeakNpcId = 100001,
          Subtitle = "We'd better stay wary of Mr Qiu.",
          VoiceName = "voice/$Locale$/story/1201/120133/1E12F504"
        },
        [12013401] = {
          Camera = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          ContentTC = "你們兩位腳程實在是太慢了——怎麼才來？我一直擱這兒盯著，瞪得我眼睛都酸了。",
          DialogueId = 12013401,
          FinalCamera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          GUID = "1E13049A",
          LookAt = {
            [1] = "100001:n(210014)",
            [2] = "200002:n(210014)"
          },
          NextDialogue = 12013402,
          SpeakNpcId = 210014,
          Subtitle = "Ah, you two sure took your time — I've been standing here so long, my eyes nearly grew weary from watching.",
          TalkActionId = {
            [1] = "210014:Disagree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E13049A"
        },
        [12013402] = {
          Camera = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
          ContentTC = "不好意思，剛剛被一些事情耽擱了。您就是公尚先生吧？",
          DialogueId = 12013402,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "1E1304C4",
          NextDialogue = 12013403,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, something came up along the way. You must be Master Gongshang.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1304C4"
        },
        [12013403] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          ContentTC = "哎呀，怎麼這麼見外呢，還叫什麼先生？來，快叫聲師父！",
          DialogueId = 12013403,
          FacialId = {
            [1] = "210014:CM_Happy01"
          },
          GUID = "1E1304EE",
          NextDialogue = 12013404,
          SpeakNpcId = 210014,
          Subtitle = "Aww, \"Master Gongshang\"? Why so formal? Come on — call me Shifu!",
          TalkActionId = {
            [1] = "210014:Explain01_Start",
            [2] = "100001:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1304EE"
        },
        [12013404] = {
          ContentTC = "咦——你們怎麼兩手空空，沒帶拜師禮嗎？",
          DialogueId = 12013404,
          FacialId = {
            [1] = "210014:CM_Idle",
            [2] = "100001:None"
          },
          GUID = "1E130518",
          NextDialogue = 12013405,
          SpeakNpcId = 210014,
          Subtitle = "Wait a second... how come you arrived empty-handed? Where's the proper token of respect one should present when acknowledging their Shifu?",
          TalkActionId = {
            [1] = "210014:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130518"
        },
        [12013405] = {
          Camera = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
          ContentTC = "……小僕從，搞技術的人，都是這麼熱情好客的嗎？",
          DialogueId = 12013405,
          FacialId = {
            [1] = "200002:Guilty"
          },
          GUID = "1E130542",
          NextDialogue = 12013406,
          SpeakNpcId = 200002,
          Subtitle = "...Little Minion, are all these tinkerer-types always this... over-the-top?",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130542"
        },
        [12013406] = {
          ContentTC = "那個，您是不是搞錯了什麼……我們是來請教這柄武器怎麼使用，但好像不是來拜師的……",
          DialogueId = 12013406,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "1E13056C",
          LookAt = {
            [1] = "100001:n(210014)",
            [2] = "200002:n(210014)"
          },
          NextDialogue = 12013407,
          SpeakNpcId = 100001,
          Subtitle = "Um, I think you might be mistaken... We're just here to learn how to use the weapon you made, not to become your apprentices...",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13056C"
        },
        [12013407] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          ContentTC = "竟然如此——",
          DialogueId = 12013407,
          FacialId = {
            [1] = "100001:None",
            [2] = "200002:None",
            [3] = "210014:CM_Sad01"
          },
          GUID = "1E130596",
          NextDialogue = 12013408,
          SpeakNpcId = 210014,
          Subtitle = "What!? Unbelievable—!",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "210014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130596"
        },
        [12013408] = {
          Camera = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
          ContentTC = "哇啊！他好像一下子蔫了——我們是不是說了什麼很打擊人的話？",
          DialogueId = 12013408,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E1305C0",
          NextDialogue = 12013409,
          SpeakNpcId = 200002,
          Subtitle = "Whoa! He totally deflated all of a sudden — did we say something wrong?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1305C0"
        },
        [12013409] = {
          ContentTC = "……您、您好？",
          DialogueId = 12013409,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E1305EA",
          NextDialogue = 12013410,
          SpeakNpcId = 100001,
          Subtitle = "Uh... are you alright, sir?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1305EA"
        },
        [12013410] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          ContentTC = "罷了。怪我病急亂投醫，一聽到有人願意繼承我機樞派的衣缽，便喜不自勝，情難自禁。",
          DialogueId = 12013410,
          GUID = "1E130614",
          NextDialogue = 12013411,
          SpeakNpcId = 210014,
          Subtitle = "Forget it. I got ahead of myself... When I heard there were two youngsters who would carry on the Jishu Sect's legacy, I was overjoyed and lost ahold of myself.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130614"
        },
        [12013411] = {
          ContentTC = "也怪我機樞派如今式微了，換以前風光的時候，弟子排著隊來拜師，那是挑花了眼也挑不過來！",
          DialogueId = 12013411,
          GUID = "1E13063E",
          NextDialogue = 12013412,
          SpeakNpcId = 210014,
          Subtitle = "Our sect has seen better days, you know. Back in our prime, young hopefuls would line up in droves, begging to be my apprentices — so many I could hardly keep track!",
          TalkActionId = {
            [1] = "210014:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13063E"
        },
        [12013412] = {
          Camera = "-123.167976,-244.147675,155.87207,0.000059,-18.800013,73.197205,35.0,557.472534,false,DoNotOverride,2.8",
          ContentTC = "再仔細看看兩位，也是一副四體不勤、天資不足的模樣。對於需要精密操作、聰慧頭腦、過人毅力等等集大成於一體的機括術來說，還是遠遠不夠啊。",
          DialogueId = 12013412,
          FacialId = {
            [1] = "100001:Unhappy01",
            [2] = "200002:Unhappy01"
          },
          FinalCamera = "-115.39222,-218.401855,146.717773,0.00006,-18.800013,73.197128,35.0,557.472534,false,DoNotOverride,2.8",
          GUID = "1E130668",
          LookAt = {
            [1] = "210014:n(100001)"
          },
          NextDialogue = 12013413,
          SpeakNpcId = 210014,
          Subtitle = "But now that I get a better look at you two... clumsy limbs, average smarts... Not exactly cut out for the mechanical brilliance and steady hand our sect demands.",
          TalkActionId = {
            [1] = "210014:Disagree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130668"
        },
        [12013413] = {
          Camera = "-139.459106,-137.644135,66.660156,0.00006,-13.600217,47.404423,35.000011,237.675415,false,DoNotOverride,2.8",
          ContentTC = "……你，你別把我們看扁了！我們今天偏要——",
          DialogueId = 12013413,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E130692",
          NextDialogue = 12013414,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Don't go thinking we're no good! Just watch — we'll show you!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130692"
        },
        [12013414] = {
          Camera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          ContentTC = "哦？你難道是想證明，自己其實很有悟性？",
          DialogueId = 12013414,
          FacialId = {
            [1] = "210014：CM_Shock01"
          },
          GUID = "1E1306BC",
          LookAt = {
            [1] = "210014:n(200002)"
          },
          NextDialogue = 12013415,
          SpeakNpcId = 210014,
          Subtitle = "Show me what? That you actually have talent?",
          TalkActionId = {
            [1] = "210014:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1306BC"
        },
        [12013415] = {
          ContentTC = "啟動這牽機方樞吧。讓我看看兩位的資質，能否達到我們機樞派的標準。",
          DialogueId = 12013415,
          FacialId = {
            [1] = "210014：CM_Idle"
          },
          GUID = "1E1306E6",
          LookAt = {
            [1] = "210014:n(100001)"
          },
          SpeakNpcId = 210014,
          Subtitle = "Very well — activate the Mechanical Nexus. Let's see if you're truly Jishu Sect material.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1306E6"
        },
        [12013416] = {
          Camera = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          ContentTC = "看見這些太虛符文了嗎？",
          DialogueId = 12013416,
          FinalCamera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          GUID = "1E130710",
          LookAt = {
            [1] = "100001:n(210014)",
            [2] = "210014:n(100001)",
            [3] = "200002:n(210014)"
          },
          NextDialogue = 12013417,
          SpeakNpcId = 210014,
          Subtitle = "See those Taixu runes?",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130710"
        },
        [12013417] = {
          Camera = "-139.459106,-137.644135,66.660156,0.00006,-13.600217,47.404423,35.000011,237.675415,false,DoNotOverride,2.8",
          ContentTC = "好難懂的名字……",
          DialogueId = 12013417,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E13073A",
          NextDialogue = 12013418,
          SpeakNpcId = 200002,
          Subtitle = "Oof... just hearing the name makes my head spin...",
          TalkActionId = {
            [1] = "210014:Explain01_End",
            [2] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13073A"
        },
        [12013418] = {
          Camera = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          ContentTC = "唉，孺子不可教也——太虛，無形無色，卻又四處充盈。這是鴻蒙之初的常態。",
          DialogueId = 12013418,
          FacialId = {
            [1] = "210014:CM_Sad01"
          },
          FinalCamera = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
          GUID = "1E130764",
          NextDialogue = 12013419,
          SpeakNpcId = 210014,
          Subtitle = "Such a slow-witted child. \"Taixu\" means that which is formless and without colour, yet it pervades all that exists. It is the primal Chaos, the breath of creation at the dawn of the world.",
          TalkActionId = {
            [1] = "210014:Disagree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130764"
        },
        [12013419] = {
          Camera = "-1551.53418,-586.06665,694.782227,0.000069,-29.399681,18.407328,35.000011,555.878662,false,DoNotOverride,2.8",
          ContentTC = "太虛被香所激化，乘風鼓動，變能成為大風九章運轉的介質；靜而不發，便能凝為浮盈空中的太虛符文。",
          DialogueId = 12013419,
          FacialId = {
            [1] = "210014:CM_Idle"
          },
          FinalCamera = "-1628.330078,-611.611572,740.382324,0.000072,-29.399687,18.407286,35.000011,555.878662,false,DoNotOverride,2.8",
          GUID = "1E13078E",
          NextDialogue = 12013420,
          SpeakNpcId = 210014,
          Subtitle = "When stirred by incense, the Taixu rides upon the wind and becomes the medium through which the Nine Chapters of Dafeng weave their power. When left undisturbed, it condenses into the Taixu runes drifting in the air.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120134/1E13078E"
        },
        [12013420] = {
          ContentTC = "但如今在這朔方之地，燭陰蒙塵，固而下之，太虛便凝成裹挾一切有形形體的塵漠。",
          DialogueId = 12013420,
          GUID = "1E1307B8",
          NextDialogue = 12013421,
          SpeakNpcId = 210014,
          Subtitle = "But here in this land, shrouded by the Scourge of Zhuyin, the Taixu has sunk downwards and congealed into the Gritblight, swallowing all that bears shape and form.",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1307B8"
        },
        [12013421] = {
          ContentTC = "而我這牽機方樞，其開天辟地之功效，便是能吸收太虛，使異狀歸於常態。",
          DialogueId = 12013421,
          GUID = "1E1307E2",
          SpeakNpcId = 210014,
          Subtitle = "This remarkable contraption I forged can be used to draw upon the Taixu and restore balance to the world.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1307E2"
        },
        [12013422] = {
          ContentTC = "算你勉強過關。下一關考驗，你能應付嗎？",
          DialogueId = 12013422,
          GUID = "1E13080C",
          SpeakNpcId = 210014,
          Subtitle = "Hmm... not bad. Now, let's see if you can handle the next trial.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E13080C"
        },
        [12013423] = {
          Camera = "628.248047,360.278137,60.518555,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "一套下來行雲流水，動作竟如此利索！我卻是沒什麼能再傳授你了。",
          DialogueId = 12013423,
          FacialId = {
            [1] = "210014:CM_Shock01"
          },
          FinalCamera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "1E130836",
          NextDialogue = 12013424,
          SpeakNpcId = 210014,
          Subtitle = "Steady hands, precise movements... You picked it up quicker than I'd expected. Truly, I have nothing more to teach you.",
          TalkActionId = {
            [1] = "210014:Shock_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130836"
        },
        [12013424] = {
          Camera = "-127.312958,25.078018,85.87793,0.000067,-13.821461,9.846305,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哎？那是不是意味著小僕從學成出師了？",
          DialogueId = 12013424,
          FacialId = {
            [1] = "210014:CM_Idle",
            [2] = "200002:Happy01"
          },
          GUID = "1E130860",
          NextDialogue = 12013425,
          SpeakNpcId = 200002,
          Subtitle = "Whoa~ Does that mean my Little Minion has mastered it?",
          TalkActionId = {
            [1] = "210014:Shock_End",
            [2] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130860"
        },
        [12013425] = {
          Camera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "出師……也罷。當今世道，還有人願意以我機樞派的名號為榮，不乏是一樁幸事。",
          DialogueId = 12013425,
          GUID = "1E13088A",
          NextDialogue = 12013426,
          SpeakNpcId = 210014,
          Subtitle = "Heh... so be it. In these times, to see anyone still willing to master something made by the Jishu Sect... that alone is enough to ease this old heart.",
          TalkActionId = {
            [1] = "210014:Sigh_Start",
            [2] = "200002:Excited01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E13088A"
        },
        [12013426] = {
          Camera = "-183.790024,-222.993271,212.301758,0.000059,-21.221882,58.649464,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "兩位，我便授予你們<H>機樞派榮譽學徒</>的頭銜。望你們博學篤志，切問近思。不要辜負我們機樞派上下求索、高天攬月之志。",
          DialogueId = 12013426,
          FacialId = {
            [1] = "100001:Smile01",
            [2] = "200002:Smile01"
          },
          GUID = "1E1308B4",
          NextDialogue = 12013427,
          SpeakNpcId = 210014,
          Subtitle = "Very well — I hereby grant you both the title of Honorary Learner of the Jishu Sect. Study with focus. Ask your questions boldly. And never forget — our craft has ever sought to touch the stars above.",
          TalkActionId = {
            [1] = "210014:Explain01_Start",
            [2] = "100001:Shy02_Start",
            [3] = "200002:Excited01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1308B4"
        },
        [12013427] = {
          Camera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "高處便是燭陰鱗所在之地。以我先前教你的法子，將附著於燭陰鱗之上的塵漠盡數吸收，便可進行采摘。",
          DialogueId = 12013427,
          GUID = "1E1308DE",
          NextDialogue = 12013428,
          SpeakNpcId = 210014,
          Subtitle = "See that path winding up ahead? That is where the Zhuyin Scales grow. Use the method I have shown you — draw out the Gritblight clinging to them, and you shall be able to harvest the scales.",
          TalkActionId = {
            [1] = "210014:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E1308DE"
        },
        [12013428] = {
          ContentTC = "我一把老身子骨了，不便與你們同行。你們且去吧。",
          DialogueId = 12013428,
          FacialId = {
            [1] = "210014:CM_Sad01"
          },
          GUID = "1E130908",
          SpeakNpcId = 210014,
          Subtitle = "As for me... I am far too old to be clambering about like in my younger days. Go on — I leave this to you.",
          TalkActionId = {
            [1] = "210014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120134/1E130908"
        },
        [12013429] = {
          ContentTC = "小僕從，你看！那邊有一個奇怪的東西，散發出邪惡的氣息！",
          DialogueId = 12013429,
          GUID = "1E130932",
          NextDialogue = 12013430,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, look! There's something weird over there... it's giving off some really wicked energy!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130932"
        },
        [12013430] = {
          ContentTC = "以白魔王大人的洞見……那一定就是他們說的那個什麼燭陰鱗了！",
          DialogueId = 12013430,
          GUID = "1E13095C",
          NextDialogue = 12013431,
          SpeakNpcId = 200002,
          Subtitle = "It must be the Zhuyin Scale they mentioned! Trust the Demon King's judgement!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E13095C"
        },
        [12013431] = {
          ContentTC = "快用公尚師傅教我們的方法試試吧！",
          DialogueId = 12013431,
          GUID = "1E130986",
          SpeakNpcId = 200002,
          Subtitle = "Quick — let's try that method Master Gongshang taught us!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130986"
        },
        [12013432] = {
          ContentTC = "魂兮遊離，循時索歸：山之陰，海之涯……",
          DialogueId = 12013432,
          GUID = "1E1309B0",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "The soul drifts untethered, returning with the turning of time: To the mountain's shadow... to the ocean's edge...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1309B0"
        },
        [12013433] = {
          ContentTC = "誰？什麼聲音？",
          DialogueId = 12013433,
          GUID = "1E1309DA",
          NextDialogue = 12013434,
          SpeakNpcId = 100001,
          Subtitle = "Who's there!?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E1309DA"
        },
        [12013434] = {
          ContentTC = "小僕從，別發呆了，打起精神來！",
          DialogueId = 12013434,
          GUID = "1E130A04",
          SpeakNpcId = 200002,
          Subtitle = "Little Minion! Focus!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A04"
        },
        [12013435] = {
          ContentTC = "（白聽不到剛才的聲音……難道說，又是與誡碑那時相同的情況？）",
          DialogueId = 12013435,
          GUID = "1E130A2E",
          NextDialogue = 120134351,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Snow didn't seem to hear it... Was it like what happened at the stele...?)",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A2E"
        },
        [12013436] = {
          ContentTC = "魂兮遊離，循時索歸：盈虧月下，若木長青……",
          DialogueId = 12013436,
          GUID = "1E130A58",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "The soul drifts untethered, returning with the turning of time: Beneath the waxing moon, by the evergreen wood...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A58"
        },
        [12013437] = {
          ContentTC = "好啦，還差最後一片燭陰鱗就可以收工啦！",
          DialogueId = 12013437,
          GUID = "1E130A82",
          SpeakNpcId = 200002,
          Subtitle = "Alright! Just one more scale, and we're done here!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A82"
        },
        [12013438] = {
          ContentTC = "比星鬥兮天闕，納陰靈兮墳塋。孰離合兮可為，蹇誰留兮他鄉？",
          DialogueId = 12013438,
          GUID = "1E130AAC",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = [[
Loftier than the stars towers the celestial gate. Restless souls drift towards graves' eternal shade. Who might decree the weaving of fates, of sunderings and partings?
Who roves forlorn, tarrying in lands beyond all chartings?]],
          VoiceName = "voice/$Locale$/story/1201/120134/1E130AAC"
        },
        [12013439] = {
          Camera = "234.427734,226.169922,38.391602,0.000054,8.448527,-130.795746,11.88,100000.0,false,Manual,2.8",
          ContentTC = "小僕從，你怎麼自顧自地往這個方向走了？這裡空蕩蕩的，什麼都沒有的樣子......",
          DialogueId = 12013439,
          GUID = "1E130AD6",
          NextDialogue = 12013457,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, why are you going this way? There's nothing here...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130AD6"
        },
        [12013440] = {
          ContentTC = "……小僕從，我相信你。這麼難懂的語句，絕對不是隨隨便便就能想出來的。",
          DialogueId = 12013440,
          GUID = "1E130B00",
          NextDialogue = 12013441,
          SpeakNpcId = 200002,
          Subtitle = "...Little Minion, I believe you. There's no way you could've made up something that cryptic.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B00"
        },
        [12013441] = {
          ContentTC = "但是，這個傢伙選擇和我們說話算是白費力氣了，壓根一個字都聽不懂嘛。",
          DialogueId = 12013441,
          GUID = "1E130B2A",
          NextDialogue = 12013442,
          SpeakNpcId = 200002,
          Subtitle = "But why would they bother speaking to us if we can't make heads or tails of it?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B2A"
        },
        [12013442] = {
          ContentTC = "——喂，想和我們說話的傢伙，無論你是誰，希望你可以說得再直白一點！",
          DialogueId = 12013442,
          GUID = "1E130B54",
          NextDialogue = 12013443,
          SpeakNpcId = 200002,
          Subtitle = "—Hey! Whoever you are up there! If you're gonna talk to us, at least say it in words we can actually understand!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B54"
        },
        [12013443] = {
          Camera = "1502.039062,552.960938,672.550781,0.000055,22.248343,-38.19368,11.88,100000.0,false,Manual,2.8",
          ContentTC = "……",
          DialogueId = 12013443,
          FinalCamera = "1502.039062,552.960938,672.550781,0.000055,22.248343,-38.19368,11.88,100000.0,false,Manual,2.8",
          GUID = "1E130B7E",
          SpeakNpcId = 100001,
          Subtitle = "...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130B7E"
        },
        [12013444] = {
          ContentTC = "……",
          DialogueId = 12013444,
          GUID = "1E130BA8",
          NextDialogue = 12013445,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130BA8"
        },
        [12013445] = {
          ContentTC = "群玄嘯鳴，災愆降世……",
          DialogueId = 12013445,
          GUID = "1E130BD2",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "The beasts howl in chorus. Calamity descends upon the mortal realm...",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130BD2"
        },
        [12013446] = {
          Camera = "234.427734,226.169922,38.391602,0.000054,8.448527,-130.795746,11.88,100000.0,false,Manual,2.8",
          ContentTC = "……！！",
          DialogueId = 12013446,
          GUID = "1E130BFC",
          NextDialogue = 12013447,
          SpeakNpcId = 100001,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130BFC"
        },
        [12013447] = {
          ContentTC = "哇——我只是隨便喊喊，沒想到真的奏效了，不愧是本魔王大人！",
          DialogueId = 12013447,
          GUID = "1E130C26",
          NextDialogue = 12013448,
          SpeakNpcId = 200002,
          Subtitle = "Whoa—! No way! I was just messing around, but it actually worked? Ha! That's the power of the Demon King!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130C26"
        },
        [12013448] = {
          ContentTC = "小僕從，所以那個聲音對你說了什麼？",
          DialogueId = 12013448,
          GUID = "1E130C50",
          NextDialogue = 12013449,
          SpeakNpcId = 200002,
          Subtitle = "So? What did that voice say this time?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130C50"
        },
        [12013449] = {
          ContentTC = "我不太確定……但是我好像看見了……很多玄色狴犴，在圍攻……百年春。而且，我有一種預感，這是即將發生的事情……<W>是預言</>！",
          DialogueId = 12013449,
          GUID = "1E130C7A",
          NextDialogue = 12013450,
          SpeakNpcId = 100001,
          Subtitle = "I... I'm not entirely sure, but I saw... countless Sable Bi'an... swarming EverSpring. And I've got a feeling... it wasn't just some dream. It felt like a prophecy — something that could happen at any moment!",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130C7A"
        },
        [12013450] = {
          ContentTC = "哎？！",
          DialogueId = 12013450,
          GUID = "1E130CA4",
          NextDialogue = 12013451,
          SpeakNpcId = 200002,
          Subtitle = "What!?",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CA4"
        },
        [12013451] = {
          ContentTC = "白，情況緊急，我們先趕回百年春看看吧。希望我的預感不要應驗……",
          DialogueId = 12013451,
          GUID = "1E130CCE",
          SpeakNpcId = 100001,
          Subtitle = "Snow, we need to get back to EverSpring now. Let's just hope I'm wrong... and this never comes to pass.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CCE"
        },
        [12013452] = {
          Camera = "244.181824,388.453522,209.890625,0.000027,-17.815693,-123.119537,35.0,647.922363,false,DoNotOverride,22.0",
          ContentTC = "看見眼前這些塵漠了嗎？這便是塵漠石海變成現今樣貌的罪魁禍首。",
          DialogueId = 12013452,
          FacialId = {
            [1] = "210014:CM_Sad01"
          },
          FinalCamera = "146.362381,214.138016,192.261719,0.000026,-18.815668,-124.320526,35.0,647.922363,false,DoNotOverride,22.0",
          GUID = "1E130CCF",
          NextDialogue = 12013453,
          SpeakNpcId = 210014,
          Subtitle = "See the Gritblight before us? This is what transformed the place into its current state.",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CCF"
        },
        [12013453] = {
          ContentTC = "試試用牽機方樞吸收塵漠吧。",
          DialogueId = 12013453,
          GUID = "1E130CD0",
          SpeakNpcId = 210014,
          Subtitle = "Give it a try, use the Mechanical Nexus to draw in the Gritblight.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD0"
        },
        [12013454] = {
          Camera = "628.248047,360.278137,60.518555,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "悟性不錯，孺子可教也！",
          DialogueId = 12013454,
          FacialId = {
            [1] = "210014:CM_Smile01"
          },
          FinalCamera = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "1E130CD1",
          NextDialogue = 12013455,
          SpeakNpcId = 210014,
          Subtitle = "Ah, that was quick! You show great promise.",
          TalkActionId = {
            [1] = "210014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD1"
        },
        [12013455] = {
          Camera = "37.220299,11.483425,-280.212891,0.000085,30.816399,-128.115143,23.740538,100000.0,false,DoNotOverride,2.8",
          ContentTC = "既然如此，不如再來試試我這匠心打造的獨家機樞機關吧！這其中的訣竅你能掌握嗎？",
          DialogueId = 12013455,
          FinalCamera = "-140.37941,-214.903625,-200.674316,0.000085,30.816399,-128.115158,23.740538,100000.0,false,DoNotOverride,2.8",
          GUID = "1E130CD2",
          NextDialogue = 12013456,
          SpeakNpcId = 210014,
          Subtitle = "Then perhaps you might try this unique device, a product of my personal craft. Do you have the wit to master its trick?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD2"
        },
        [12013456] = {
          ContentTC = "若能順利解開這道機關，其中的寶箱便作為見面禮贈予你二人了",
          DialogueId = 12013456,
          GUID = "1E130CD3",
          SpeakNpcId = 210014,
          Subtitle = "If you can successfully solve this puzzle, the treasure inside shall be my gift to you both.",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130CD3"
        },
        [12013457] = {
          ContentTC = "（白聽不到剛才的聲音……難道說，又是與誡碑那時相同的情況？）",
          DialogueId = 12013457,
          DisableMouth = 1,
          GUID = "1E130AD7",
          NextOptions = {
            [1] = 120134391
          },
          SpeakNpcId = 100001,
          Subtitle = "(Snow didn't seem to hear it... Was it like what happened at the stele...?)",
          VoiceName = "voice/$Locale$/story/1201/120134/1E130A2E"
        },
        [12013501] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "您二位終於出來了——奉我們家老板的命令，馮某已在此恭候多時了。",
          DialogueId = 12013501,
          FacialId = {
            [1] = "210010:Cin_Happy01",
            [2] = "100001:Unhappy01",
            [3] = "200002:Unhappy02"
          },
          GUID = "1E131502",
          LookAt = {
            [1] = "100001:n(210010)",
            [2] = "200002:n(210010)"
          },
          NextOptions = {
            [1] = 120135011,
            [2] = 120135012
          },
          SpeakNpcId = 210010,
          Subtitle = "Ah! There you are. I've been waiting here on behalf of my boss.",
          TalkActionId = {
            [1] = "210010:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131502"
        },
        [12013504] = {
          ContentTC = "哎，哎——貴客您別走啊！",
          DialogueId = 12013504,
          FacialId = {
            [1] = "210010:Cin_Smile01"
          },
          GUID = "1E131580",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12013505,
          SpeakNpcId = 210010,
          Subtitle = "Hey! Please — don't go! At least hear me out!",
          TurnTo = {
            [1] = "100001:p(120)"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131580"
        },
        [12013505] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          ContentTC = "找我什麼事？",
          DialogueId = 12013505,
          GUID = "1E1315AA",
          LookAt = {
            [1] = "200002:n(210010)"
          },
          NextDialogue = 12013506,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"100001:n(210010)"}},
PlayAnimation{ActorId{100001},AnimationId{"ConfidentLR_Start"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "What do you want?",
          TalkActionId = {
            [1] = "210010:Explain02_End"
          },
          TurnTo = {
            [1] = "100001:n(210010)"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1315AA"
        },
        [12013506] = {
          ContentTC = "白和小僕從的時間可是很寶貴的！只能給你一分鍾……不對，三十秒的時間！",
          DialogueId = 12013506,
          GUID = "1E1315D4",
          NextDialogue = 12013507,
          SpeakNpcId = 200002,
          Subtitle = "Our time's precious, you know! You've got one minute... no, thirty seconds! Make it count!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1315D4"
        },
        [12013507] = {
          ContentTC = "我們家老板看中了{nickname}的身手，想邀請兩位共襄義舉，參加一場圍獵行動。",
          DialogueId = 12013507,
          GUID = "1E1315FE",
          NextDialogue = 120135070,
          SpeakNpcId = 210010,
          Subtitle = "My boss was deeply impressed by your prowess, . He wishes to invite you both to join him on a hunting expedition.",
          TalkActionId = {
            [1] = "210010:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1315FE"
        },
        [12013509] = {
          ContentTC = "我們很熟嗎？",
          DialogueId = 12013509,
          GUID = "1E131652",
          NextDialogue = 12013510,
          SpeakNpcId = 100001,
          Subtitle = "Do we even know each other?",
          TalkActionId = {
            [1] = "100001:ConfidentLRToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131652"
        },
        [12013510] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "您這話說的，這不是不打不相識嗎？在馮某看來，已經和兩位一見如故，簡直是多年故交了！",
          DialogueId = 12013510,
          FacialId = {
            [1] = "210010:Cin_Smile01"
          },
          GUID = "1E13167C",
          LookAt = {
            [1] = "210010:n(100001)"
          },
          NextDialogue = 12013511,
          SpeakNpcId = 210010,
          Subtitle = "Oh, come now! As the saying goes, \"A good brawl makes for fast friends.\" In my eyes, we're practically old acquaintances already.",
          TalkActionId = {
            [1] = "100001:ConfidentLRToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13167C"
        },
        [12013511] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          ContentTC = "……",
          DialogueId = 12013511,
          GUID = "1E1316A6",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12013512,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "210010:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1316A6"
        },
        [12013512] = {
          ContentTC = "……",
          DialogueId = 12013512,
          GUID = "1E1316D0",
          NextDialogue = 12013513,
          SpeakNpcId = 200002,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120135/1E1316D0"
        },
        [12013513] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "好了好了。俗話說得好，無恒久之友，亦無恒久之敵。這天下熙熙，皆為利來利往。只有利益永流轉呀——",
          DialogueId = 12013513,
          GUID = "1E1316FA",
          LookAt = {
            [1] = "100001:n(210010)",
            [2] = "200002:n(210010)"
          },
          NextDialogue = 12013514,
          SpeakNpcId = 210010,
          Subtitle = "Alright, alright. Let me put it this way: \"There are no eternal friends, nor lasting foes — only the bond built on shared interests endures.\" That's the way of this world.",
          TalkActionId = {
            [1] = "210010:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1316FA"
        },
        [12013514] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          ContentTC = "聽你話裡的意思，你能拿出讓我心動的報酬？",
          DialogueId = 12013514,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "210010:Cin_Smile01"
          },
          GUID = "1E131724",
          NextDialogue = 12013515,
          SpeakNpcId = 100001,
          Subtitle = "So... you're saying there's something in it for me?",
          TalkActionId = {
            [1] = "100001:ConfidentLRToTalk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131724"
        },
        [12013515] = {
          Camera = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
          ContentTC = "錢自不用說。我們家老板一向出手慷慨。",
          DialogueId = 12013515,
          FacialId = {
            [1] = "200002:Curious"
          },
          GUID = "1E13174E",
          NextDialogue = 12013516,
          SpeakNpcId = 210010,
          Subtitle = "Of course. Money, for starters — our boss is nothing if not generous.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13174E"
        },
        [12013516] = {
          ContentTC = "還有一項報酬，想必是合您心意的……",
          DialogueId = 12013516,
          GUID = "1E131778",
          NextDialogue = 12013517,
          SpeakNpcId = 210010,
          Subtitle = "But there's another reward... one that might pique your interest even more.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E131778"
        },
        [12013517] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          ContentTC = "說來聽聽。",
          DialogueId = 12013517,
          FacialId = {
            [1] = "100001:Think01",
            [2] = "200002:Smile01"
          },
          GUID = "1E1317A2",
          NextDialogue = 12013518,
          SpeakNpcId = 100001,
          Subtitle = "Let's hear it then.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1317A2"
        },
        [12013518] = {
          ContentTC = "您或許不知，我們家老板的生意足跡遍布世界各地，與海伯利亞帝國也有盤根錯節的聯係……您可曾聽說過格林威治考古協會？",
          DialogueId = 12013518,
          GUID = "1E1317CC",
          NextDialogue = 12013519,
          RelatedWikiId = {
            [1] = 406005
          },
          SpeakNpcId = 210010,
          Subtitle = "You may not know this, but our boss's dealings stretch far and wide — all the way to the Hyperborean Empire. Ever heard of the Greenwich Archaeological Society?",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1317CC"
        },
        [12013519] = {
          Camera = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,50.0,374.245361,false,DoNotOverride,2.8",
          ContentTC = "哇，我聽卡蜜拉講過！那是一個號稱要讓古跡重見天日的組織，很有名的！",
          DialogueId = 12013519,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E1317F6",
          NextDialogue = 12013520,
          SpeakNpcId = 200002,
          Subtitle = "Oh! Camilla told me about them! They're famous for bringing ancient relics back to the light!",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1317F6"
        },
        [12013520] = {
          Camera = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
          ContentTC = "呵呵，我家老板就是它背後的投資人之一。",
