          ContentTC = "……你怎麼知道的？",
          DialogueId = 12013523,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "1E13189E",
          NextDialogue = 12013524,
          SpeakNpcId = 100001,
          Subtitle = "...How do you know about that?",
          TalkActionId = {
            [1] = "100001:Shock04_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13189E"
        },
        [12013524] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我如何知道這件事不要緊。要緊的是，考古協會提供的情報和人脈，在日後某一天說不定就能成為您達成心願的助力。",
          DialogueId = 12013524,
          GUID = "1E1318C8",
          NextDialogue = 120135070,
          SpeakNpcId = 210010,
          Subtitle = "That's not important. What matters is — the connections and information the Society holds might one day prove invaluable to your search.",
          TalkActionId = {
            [1] = "100001:Shock04_End",
            [2] = "210010:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E1318C8"
        },
        [12013526] = {
          Camera = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "人們總是對我們黑市中人有些偏見，馮某十分理解。",
          DialogueId = 12013526,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "210010:CM_Idle"
          },
          GUID = "1E13191C",
          NextDialogue = 12013528,
          SpeakNpcId = 210010,
          Subtitle = "I understand your misgivings. We black market folk have quite the reputation, I know.",
          TalkActionId = {
            [1] = "210010:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13191C"
        },
        [12013528] = {
          ContentTC = "但就算是我們，也會有一顆保衛家園的拳拳之心，偶爾想做些為民除害的好事！",
          DialogueId = 12013528,
          GUID = "1E131970",
          NextDialogue = 12013529,
          SpeakNpcId = 210010,
          Subtitle = "But even in our line of work, there are times when one must stand up for one's homeland... to rid it of certain threats.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E131970"
        },
        [12013529] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          ContentTC = "……聽起來更可疑了。",
          DialogueId = 12013529,
          FacialId = {
            [1] = "100001:Think01",
            [2] = "200002:Doubt01"
          },
          GUID = "1E13199A",
          NextDialogue = 12013530,
          SpeakNpcId = 100001,
          Subtitle = "...You only made it sound even fishier.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E13199A"
        },
        [12013530] = {
          Camera = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
          ContentTC = "況且，這行動是止流掌櫃囑托給我們老板的，也是化解燭陰之災的布局的一子呢。",
          DialogueId = 12013530,
          GUID = "1E1319C4",
          NextDialogue = 12013531,
          SpeakNpcId = 210010,
          Subtitle = "Well, full disclosure: this request came directly from Proprietress Zhiliu herself. This hunt is but one part of her plan to resolve the Scourge of Zhuyin. My boss is simply fulfilling her commission.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E1319C4"
        },
        [12013531] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          ContentTC = "……止流的委托？好吧。「獵物」是什麼？",
          DialogueId = 12013531,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E1319EE",
          NextDialogue = 12013532,
          SpeakNpcId = 100001,
          Subtitle = "...Zhiliu's request? Fine. I'll bite. So what exactly are we hunting?",
          VoiceName = "voice/$Locale$/story/1201/120135/1E1319EE"
        },
        [12013532] = {
          ContentTC = "這個馮某暫時無法透露，您可以視為玄色狴犴的同類。",
          DialogueId = 12013532,
          FacialId = {
            [1] = "210010:Cin_Smile01"
          },
          GUID = "1E131A18",
          NextDialogue = 12013533,
          SpeakNpcId = 210010,
          Subtitle = "I'm afraid I can't say just yet. Let's just say it shares kinship with the Sable Bi'an.",
          VoiceName = "voice/$Locale$/story/1201/120135/1E131A18"
        },
        [12013533] = {
          ContentTC = "等您看到了再決定也不遲。畢竟，您隨時有退出的權利。",
          DialogueId = 12013533,
          GUID = "1E131A42",
          NextDialogue = 120135070,
          SpeakNpcId = 210010,
          Subtitle = "When you see it with your own eyes, you can decide then. There's no obligation — you're free to walk away at any time.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120135/1E131A42"
        },
        [12013534] = {
          Camera = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
          ContentTC = "……我先跟你們去看看吧。",
          DialogueId = 12013534,
          GUID = "1E131A6C",
          NextDialogue = 12013535,
          SpeakNpcId = 100001,
          Subtitle = "...Alright. I'll come along and see for myself.",
          TalkActionId = {
