        [12014008] = {
          Camera = "-220.412903,-680.490723,295.292969,0.000105,-16.397665,79.819618,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你先前說收了我的竹笛，就答應幫我做一件事，沒錯吧？",
          DialogueId = 12014008,
          FinalCamera = "-256.274719,-674.050476,295.292969,0.000105,-16.397665,79.819618,30.000002,100000.0,false,DoNotOverride,2.8",
