        [12014010] = {
          Camera = "-8.599365,-111.106323,114.814453,0.000091,8.002468,157.225708,40.000011,192.971207,false,Manual,8.0",
          ContentTC = "那我希望你可以好好照顧自己。",
          DialogueId = 12014010,
          Duration = 3,
          FacialId = {
            [1] = "210013:None"
          },
          FinalCamera = "-12.785553,-121.060074,114.814453,0.000092,8.002468,157.225403,40.0,190.094833,false,Manual,8.0",
          GUID = "1E136884",
          NextDialogue = 12014011,
          Scripts = "PlayFacial{_delay{3.1},ActorId{210013},FacialId{\"Shock01\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Then here's my request: take good care of yourself.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136884"
        },
        [12014011] = {
          Camera = "212.972397,181.786407,310.055664,0.000055,-23.796507,-148.173798,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這種無關緊要的小事，怎能算作要求。你無需為此浪費一份承諾。",
          DialogueId = 12014011,
          FacialId = {
            [1] = "210013:None"
          },
          FinalCamera = "285.723572,226.953049,347.814453,0.000055,-23.796507,-148.173798,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1368AE",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014012,
          Scripts = [[
