          ContentTC = "這個世界上，肯定有某個人像我擔心她一樣擔心你。所以，照顧好自己，不要讓那個人難過。",
          DialogueId = 12014014,
          Duration = 1,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "-208.24704,-317.102356,133.03418,0.000073,-0.397701,79.626984,40.0,257.81076,false,Manual,10.0",
          GUID = "1E13692C",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "210013:n(210013)"
          },
          NextDialogue = 12014015,
          Scripts = [[
PARA{
SEQ{
