            [2] = "210013:Think_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E13692C"
        },
        [12014015] = {
          Camera = "-160.908493,-160.138596,126.569336,0.000092,7.202004,94.83432,45.000023,134.189529,false,Manual,10.0",
          ContentTC = "……抱歉，引起你的傷心事了。",
          DialogueId = 12014015,
