          GUID = "1E136956",
          NextDialogue = 12014016,
          SpeakNpcId = 210013,
          Subtitle = "...Forgive me. I didn't mean to stir old grief.",
          TalkActionId = {
            [1] = "210013:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136956"
