        [12014020] = {
          Camera = "-304.054077,-171.641968,145.578125,5.001599,-42.596004,111.247818,40.0,126.781067,false,Manual,6.839206",
          ContentTC = "阿娘，是你回來了嗎……女兒好冷……",
          DialogueId = 12014020,
          FinalCamera = "-308.513123,-160.168503,134.261719,5.001599,-42.596004,111.247818,40.0,111.219002,false,Manual,6.839206",
          GUID = "1E136A28",
          NextDialogue = 12014021,
          SpeakNpcId = 210056,
          Subtitle = "Mama... is that you? I'm so cold...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A28"
        },
        [12014021] = {
          Camera = "-66.014252,-35.105202,167.732422,5.00001,-18.596672,-167.155045,30.0,268.570251,false,Manual,6.839206",
          ContentTC = "……看來，只是夢中囈語。",
          DialogueId = 12014021,
          FinalCamera = "-63.524422,-45.636681,166.837891,5.000161,-18.996737,-171.154877,30.0,268.570251,false,Manual,6.839206",
          GUID = "1E136A52",
          NextDialogue = 12014022,
          SpeakNpcId = 210013,
          Subtitle = "...Just a dream, it seems.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A52"
        },
        [12014022] = {
          ContentTC = "她的傷勢現在怎麼樣了？",
          DialogueId = 12014022,
          GUID = "1E136A7C",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014023,
          SpeakNpcId = 100001,
          Subtitle = "How is she doing?",
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A7C"
        },
        [12014023] = {
          Camera = "-72.462227,-96.764427,124.28125,0.000125,9.403216,154.049149,35.000008,137.232391,false,Manual,6.0",
          ContentTC = "暫時穩定下來了。但狴犴的力量還在持續侵蝕她的筋脈，她一時半會恐怕無法醒轉。",
          DialogueId = 12014023,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "-74.948547,-101.871399,124.28125,0.000135,9.403216,152.449646,35.000011,127.589622,false,Manual,6.0",
          GUID = "1E136AA6",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12014024,
          SpeakNpcId = 210013,
          Subtitle = "She's stable for now. But the Bi'an's power still gnaws at her meridians. I fear it will be some time before she wakes.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AA6"
        },
        [12014024] = {
          ContentTC = "我在家姐的筆記中查閱到了一種名為「忘憂草」的草藥。它生長於此界和彼界交彙之地，藥性柔和，與狴犴的剛烈相克。",
          DialogueId = 12014024,
          GUID = "1E136AD0",
          NextDialogue = 12014025,
          RelatedWikiId = {
            [1] = 301009
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3.5},TargetPosition{"-1772.944702,-1120.462158,-1462.329102,0.000139,3.182055,123.224609,25.0,3248.383545,false,Manual,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-1772.944702,-1120.462158,-1462.329102,0.000142,-9.617889,115.826202,25.0,570.544434,false,Manual,2.8"},duration{20}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "In my sister's pharmic notes, there was mention of a herb called Wangyou. It grows at the liminal crossing of this world and the next — its gentle essence said to be the perfect foil for the Bi'an's brutal energy.",
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AD0"
        },
        [12014025] = {
          ContentTC = "以忘憂草入藥，或許能調和她體內的暴虐之力，讓她的病情好轉。",
          DialogueId = 12014025,
          GUID = "1E136AFA",
          LookAt = {
            [1] = "210013:n(210056)"
          },
          NextDialogue = 12014026,
          SpeakNpcId = 210013,
          Subtitle = "If we use this herb in her treatment, it may soothe the violent currents within her and steady her condition.",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AFA"
        },
        [12014026] = {
          Camera = "-511.522827,-152.21167,61.43457,0.000145,8.602684,16.252649,35.000008,335.979614,false,Manual,8.60223",
          ContentTC = "家姐研習的藥石之理與我的枯榮之術雖同為治病救人之法，但原理終是不同的。我對藥理只是略略懂得一些，但如今已經是唯一的法子了。",
          DialogueId = 12014026,
          FinalCamera = "-513.789429,-144.432739,61.43457,0.000145,8.602684,16.252649,35.000008,335.979614,false,Manual,8.60223",
          GUID = "1E136B24",
          LookAt = {
            [1] = "200002:n(210056)"
          },
          NextDialogue = 12014027,
          Scripts = "LookAt{_delay{11.8},LookAtDescription{\"210013:n(100001)\"}}",
          SpeakNpcId = 210013,
          Subtitle = "While my sister devoted her life to the study of herbs and medicines, I was raised in the Art of Ephemerality. Our ways share a purpose, but the paths diverge. I know little of her methods... but for now, this is the only path left to try.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B24"
        },
        [12014027] = {
          Camera = "-226.133133,-85.315811,163.748047,0.000056,-21.196583,11.054746,40.0,85.401657,false,Manual,10.0",
          ContentTC = "那還等什麼，我們趕緊走吧！",
          DialogueId = 12014027,
          FinalCamera = "-226.133133,-85.315811,163.748047,0.000056,-21.196583,11.054746,40.0,230.872345,false,Manual,10.0",
          GUID = "1E136B4E",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12014028,
          Scripts = "LookAt{_delay{1.8},LookAtDescription{\"100001:n(200002)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Then what are we waiting for? Let's go find it!",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "100001:Think_Start",
            [3] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B4E"
        },
        [12014028] = {
          Camera = "166.755264,-67.873413,51.71582,0.000071,12.00366,172.654205,40.0,353.210052,false,Manual,6.0",
          ContentTC = "你們來得恰巧，我正準備醒轉來後就出門采藥。若是來得晚一些，便只能錯過了。",
          DialogueId = 12014028,
          FacialId = {
            [1] = "200002:Nervous",
            [2] = "210013:Smile01"
          },
          FinalCamera = "165.051727,-80.381683,51.71582,0.000071,11.803659,170.854324,40.0,352.896423,false,Manual,6.0",
          GUID = "1E136B78",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 12014029,
          Scripts = "PlayAnimation{_delay{3.01},ActorId{210013},AnimationId{\"Baiheng_Story_Special02_Start\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "You arrived at just the right moment. I was about to set out to find it myself. Had you come any later... you might have missed me altogether.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "210013:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B78"
        },
        [12014029] = {
          Camera = "-121.7556,4.822418,91.928711,0.000113,-4.796657,-10.953535,35.0,104.130783,false,Manual,8.0",
          ContentTC = "……話說回來，那個什麼什麼此界彼界的玄乎地方，是哪兒來著？",
          DialogueId = 12014029,
          GUID = "1E136BA2",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014030,
          SpeakNpcId = 200002,
          Subtitle = "So — where's that place again? The one that's supposed to be between two worlds or something?",
          TalkActionId = {
            [1] = "200002:Shy03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BA2"
        },
        [12014030] = {
          Camera = "719.884644,1403.09314,144.785156,0.000114,-2.598074,-112.95311,35.000011,1652.77417,false,Manual,2.8",
          ContentTC = "這個地方名為「虞泉」。且不論你們初來乍到，就連土生土長的華胥人，終其一生也未必去過此處呢。",
          DialogueId = 12014030,
          FinalCamera = "784.508057,1375.722168,144.785156,0.000115,-2.598074,-112.953705,35.000011,755.125061,false,Manual,2.8",
          GUID = "1E136BCC",
          NextDialogue = 12014031,
          RelatedWikiId = {
            [1] = 408013
          },
          Scripts = [[
PARA{
LookAt{LookAtDescription{"210013:n(200002)"}},
LookAt{_delay{4.1},LookAtDescription{"210013:n(100001)"}},
}]],
          SpeakNpcId = 210013,
          Subtitle = "It's called the Spring of Yu. Even those born and raised in Huaxu may never see it for themselves — let alone newcomers like you.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BCC"
        },
        [12014031] = {
          Camera = "59.27887,-13.943413,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          ContentTC = "它由華胥獨特的水土蘊養出。以無處不在的香料做引，有些人臨終時的執念會化為一種叫做「無由生」的特殊生靈。",
          DialogueId = 12014031,
          FinalCamera = "60.464428,-21.080315,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          GUID = "1E136BF6",
          NextDialogue = 12014032,
          RelatedWikiId = {
            [1] = 303012
          },
          SpeakNpcId = 210013,
          Subtitle = "It is nurtured by Huaxu's unique soil and water. When mortals perish with lingering attachments in their hearts, the ever-present perfume acts as a conduit. Those yearnings give birth to spirits known as Wishen.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BF6"
        },
        [12014032] = {
          Camera = "-147.81781,5.32869,142.967773,0.000243,-4.796145,-93.967758,35.000011,86.214539,false,Manual,7.41853",
          ContentTC = "虞泉即為無由生的棲居之地。只有心思澄澈的兒童，或是受到它們邀請的人類，能夠踏入虞泉的界域。",
          DialogueId = 12014032,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-147.885712,4.413391,142.889648,0.000242,-4.796145,-93.967621,35.000008,80.332993,false,Manual,7.41853",
          GUID = "1E136C20",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014033,
          SpeakNpcId = 210013,
          Subtitle = "The Spring of Yu is their resting ground. Only children with a pure heart — or those they choose to invite — may step into its realm.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C20"
        },
        [12014033] = {
          Camera = "-294.044525,50.440552,165.479492,0.000202,-16.597221,-20.770725,40.0,289.488281,false,Manual,6.491352",
          ContentTC = "聽起來很神奇的樣子……！那我和小僕從可以去這個地方嗎？",
          DialogueId = 12014033,
          FacialId = {
            [1] = "200002:Happy02"
          },
          FinalCamera = "-294.044525,50.440552,165.479492,0.000197,-17.597284,-17.170553,40.0,289.488281,false,Manual,6.491352",
          GUID = "1E136C4A",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "200002:n(210013)"
          },
          NextDialogue = 12014034,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.1},ActorId{200002},AnimationId{"SpecialHappy_Start"},Duration{1}},
PlayFacial{_delay{2.5},ActorId{100001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Wow... that sounds so mysterious! So... can my Little Minion and I get in there?",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "100001:p(-75)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C4A"
        },
        [12014034] = {
          Camera = "139.226379,128.650238,49.652344,0.000156,11.202827,-146.769257,40.0,369.932373,false,Manual,6.0",
          ContentTC = "自然可以。跟緊了，我為你們引路。",
          DialogueId = 12014034,
          GUID = "1E136C74",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          Scripts = [[
SEQ{
LookAt{_delay{0.5},LookAtDescription{"210013:n(100001)"}},
PlayAnimation{_delay{1.1},ActorId{210013},AnimationId{"Baiheng_Story_Special01_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Of course. Stay close. I shall lead the way.",
          TalkActionId = {
            [1] = "200002:SpecialHappy_End",
            [2] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C74"
        },
        [12014201] = {
          ContentTC = "……未想到此處也被這些塵漠影響了。",
          DialogueId = 12014201,
          Duration = 3,
          GUID = "1E1387DA",
          NextDialogue = 12014202,
          SpeakNpcId = 210013,
          Subtitle = "...I hadn't foreseen that the Gritblight would touch even this sanctuary.",
          VoiceName = "voice/$Locale$/story/1201/120142/1E1387DA"
        },
        [12014202] = {
          ContentTC = "放心，我有辦法解決。",
          DialogueId = 12014202,
          Duration = 2,
          GUID = "1E138804",
          NextDialogue = 12014203,
          SpeakNpcId = 100001,
          Subtitle = "Don't worry. I've got this.",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138804"
        },
        [12014203] = {
          ContentTC = "哼哼，畢竟現在白和小僕從可是出師的機樞派榮譽學徒！你就看好了！",
          DialogueId = 12014203,
          Duration = 2,
          GUID = "1E13882E",
          NextDialogue = 12014204,
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh! After all, the great Demon King and her Little Minion are now proud honorary learners of the Jishu Sect! Just watch us!",
          VoiceName = "voice/$Locale$/story/1201/120142/1E13882E"
        },
        [12014204] = {
          ContentTC = "機樞派……？這個門派式微已久，你們怎與他們產生了交集？",
          DialogueId = 12014204,
          Duration = 2,
          GUID = "1E138858",
          NextDialogue = 12014205,
          SpeakNpcId = 210013,
          Subtitle = "The Jishu Sect...? That name has all but faded from memory. How did you come to be involved with them?",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138858"
        },
        [12014205] = {
          ContentTC = "哼哼，這就是小說裡常說的奇遇！",
          DialogueId = 12014205,
          Duration = 3,
          GUID = "1E138882",
          SpeakNpcId = 200002,
          Subtitle = "Heh! Just like one of those wild tales you hear in old legends — pure luck, I'd say!",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138882"
        },
        [12014301] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "呀，是白色妖怪！",
          DialogueId = 12014301,
          GUID = "1E139842",
          NextDialogue = 12014302,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! White monsters!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139842"
        },
        [12014302] = {
          ContentTC = "嗚、嗚哇——誰在說話？幽靈？！救命啊，小僕從！",
          DialogueId = 12014302,
          GUID = "1E13986C",
          NextDialogue = 12014303,
          SpeakNpcId = 200002,
          Subtitle = "Eek! Wh—Who's talking!? A ghost!? Little Minion, help!!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E13986C"
        },
        [12014303] = {
          ContentTC = "無需驚慌，小白。這就是我先前所說的<H>無由生</>。只是未受它們邀請的人看不到它們的身形。",
          DialogueId = 12014303,
          GUID = "1E139896",
          NextDialogue = 12014304,
          SpeakNpcId = 210013,
          Subtitle = "Calm yourself, Snow. This is a Wishen I spoke of. Those who have not been invited cannot see their form.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139896"
        },
        [12014304] = {
          ContentTC = "畏生，這二位是我的朋友。我們有事拜訪長老，可以請你現身，為{性别:他|她}們指明前路嗎？",
          DialogueId = 12014304,
          GUID = "1E1398C0",
          NextDialogue = 12014305,
          SpeakNpcId = 210013,
          Subtitle = "Wei Shen, these two are my friends. We seek an audience with Elder Wishen. Could you reveal yourself and show them the way?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1398C0"
        },
        [12014305] = {
          ContentTC = "扶疏的朋友？那也是畏生的朋友！",
          DialogueId = 12014305,
          GUID = "1E1398EA",
          NextDialogue = 12014306,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "Sure! Friends of Fushu are friends of mine!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1398EA"
        },
        [12014306] = {
          ContentTC = "哇……這就是無由生嗎？小傢伙長得圓溜溜的，還挺可愛的！",
          DialogueId = 12014306,
          GUID = "1E139914",
          NextDialogue = 12014307,
          SpeakNpcId = 200002,
          Subtitle = "Whoa... so this is a Wishen? It's all round and puffy — kinda cute, actually!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139914"
        },
        [12014307] = {
          ContentTC = "你怎不在祠台，跑到外面來了？",
          DialogueId = 12014307,
          GUID = "1E13993E",
          NextDialogue = 12014308,
          SpeakNpcId = 210013,
          Subtitle = "Why aren't you at the altar? What are you doing out here?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E13993E"
        },
        [12014308] = {
          ContentTC = "灰茫茫的塵漠從地裡生出來……灰茫茫的塵漠畔住了畏生的腳！畏生走不動，也跑不動……",
          DialogueId = 12014308,
          GUID = "1E139968",
          NextDialogue = 12014309,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "The Gritblight... it rose up from the ground... now my feet are stuck. I can't walk or run at all...",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139968"
        },
        [12014309] = {
          ContentTC = "沒能在天黑之前回家，阿娘要記掛了……",
          DialogueId = 12014309,
          GUID = "1E139992",
          NextDialogue = 12014310,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "I didn't make it home before dark... and Mama must be so worried...",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139992"
        },
        [12014310] = {
          ContentTC = "放心吧，我們帶你回家。包在白身上！",
          DialogueId = 12014310,
          GUID = "1E1399BC",
          NextDialogue = 12014311,
          SpeakNpcId = 200002,
          Subtitle = "Don't worry! We'll get you home safe and sound!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1399BC"
        },
        [12014311] = {
          ContentTC = "家……畏生的家丟了！哪裡都找不見阿娘，畏生沒有地方可以去！",
          DialogueId = 12014311,
          GUID = "1E1399E6",
          NextDialogue = 12014312,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "Home... I've lost it. I looked everywhere, but I can't find Mama... I don't have anywhere to go anymore!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1399E6"
        },
        [12014312] = {
          ContentTC = "嗚哇，它怎麼一下子激動了起來？",
          DialogueId = 12014312,
          GUID = "1E139A10",
          NextDialogue = 12014313,
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh... why did it get so upset all of a sudden?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A10"
        },
        [12014313] = {
          ContentTC = "小白，讓我來吧。",
          DialogueId = 12014313,
          GUID = "1E139A3A",
          NextDialogue = 12014314,
          SpeakNpcId = 210013,
          Subtitle = "Snow, let me handle this.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A3A"
        },
        [12014314] = {
          ContentTC = "在外面待了這麼久，你一定已經疲憊不堪了吧。我們先回祠台歇腳，可好？",
          DialogueId = 12014314,
          GUID = "1E139A64",
          NextDialogue = 12014315,
          SpeakNpcId = 210013,
          Subtitle = "You've lingered here far too long — you must be weary. Let us return to the altar, so you may find a moment of rest.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A64"
        },
        [12014315] = {
          ContentTC = "……嗯！",
          DialogueId = 12014315,
          GUID = "1E139A8E",
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "...Okay!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A8E"
        },
        [12014316] = {
          ContentTC = "姐姐帶畏生回家！",
          DialogueId = 12014316,
          GUID = "1E139A8F",
          Subtitle = "Wei Shen is going home!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A8F"
        },
        [12014401] = {
          Camera = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "——謝謝你們！",
          DialogueId = 12014401,
          FinalCamera = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E13A8AA",
          NextDialogue = 12014402,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "—Thank you!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8AA"
        },
        [12014402] = {
          Camera = "154.71994,121.273628,111.300293,0.000013,4.39925,164.604019,35.000008,170.252457,false,Manual,3.826119",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "無由生是由執念構成的生靈。",
          DialogueId = 12014402,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "148.449249,101.440178,111.300293,0.000014,4.799225,156.803726,35.000011,170.252457,false,Manual,3.826119",
          GUID = "1E13A8D4",
          LookAt = {
            [1] = "210013:n(100001)",
            [2] = "200002:n(210013)",
            [3] = "100001:n(210013)"
          },
          NextDialogue = 12014403,
          RelatedWikiId = {
            [1] = 303012
          },
          SpeakNpcId = 210013,
          Subtitle = "The Wishens are spirits woven from unfulfilled longings.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8D4"
        },
        [12014403] = {
          ContentTC = "這隻小無由生，大約是生前偷偷跑出家門玩耍，卻不慎失足墜亡。從那之後，「回家」成為了它的執念。",
          DialogueId = 12014403,
          Duration = 1,
          GUID = "1E13A8FE",
          NextDialogue = 12014404,
          SpeakNpcId = 210013,
          Subtitle = "This little one was likely a child who slipped away to play... and met a sudden end. Ever since, \"going home\" has lingered as its last, unfulfilled wish.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8FE"
        },
        [12014404] = {
          Camera = "69.47644,193.072845,103.465088,0.000062,22.596144,-171.999283,45.000023,78.807327,false,Manual,7.461847",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "可惜它年紀尚幼，不記得家的方位。光陰荏苒，它的親人大約也……無處可尋了。",
          DialogueId = 12014404,
          Duration = 1,
          FinalCamera = "66.714828,163.37291,100.481201,0.000061,24.395912,161.600143,45.000027,78.807327,false,Manual,7.461847",
          GUID = "1E13A928",
          LookAt = {
            [1] = "210013:p(BP_FixSimple_39_fushu)"
          },
          NextDialogue = 12014405,
          SpeakNpcId = 210013,
          Subtitle = "Sadly, it was far too young to remember where home lay. And now... so many seasons have passed, its family... is likely long gone.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A928"
        },
        [12014405] = {
          Camera = "95.111908,170.19989,184.635742,0.000034,-28.601601,178.796585,35.000011,248.150375,false,Manual,10.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "哇……無由生真的是幽靈！不過，好像沒有故事書裡寫的那麼可怕！還有點可憐……",
          DialogueId = 12014405,
          FacialId = {
            [1] = "200002:Curious"
          },
          FinalCamera = "94.933746,161.763794,184.635742,0.000033,-28.801596,176.59642,35.000011,248.150375,false,Manual,10.0",
          GUID = "1E13A952",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          NextDialogue = 12014406,
          Scripts = "PlayFacial{_delay{4.5},ActorId{200002},FacialId{\"Sad01\"}}",
          SpeakNpcId = 200002,
          Subtitle = "So Wishens really are ghosts... but not the scary kind from old stories. If anything... they're a little bit sad.",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A952"
        },
        [12014406] = {
          Camera = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "此處本還有兩隻無由生，恐怕也被塵漠波及了。去尋覓它們的蹤跡吧。",
          DialogueId = 12014406,
          FinalCamera = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E13A97C",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          Scripts = "PlayAnimation{_delay{4.5},ActorId{210013},AnimationId{\"Explain01_Start\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "There should be two more nearby. I fear the Gritblight has found them too. Come — let us search for their traces.",
          TalkActionId = {
            [1] = "200002:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A97C"
        },
        [12014501] = {
          ContentTC = "「一二三，木頭人……」",
          DialogueId = 12014501,
          Duration = 2,
          GUID = "1E13B912",
          NextDialogue = 12014502,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouShengSY",
          Subtitle = "\"One, two, three... Red Light!\"",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B912"
        },
        [12014502] = {
          ContentTC = "山洞中應是有一隻小無由生。但是落石堵住了通路……",
          DialogueId = 12014502,
          Duration = 3,
          GUID = "1E13B93C",
          NextDialogue = 12014503,
          SpeakNpcId = 210013,
          Subtitle = "There lies a little Wishen within the cave, yet the way has been sealed by fallen rocks...",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B93C"
        },
        [12014503] = {
          ContentTC = "了解！拆遷作業小隊上線嘍——",
          DialogueId = 12014503,
          Duration = 2,
          GUID = "1E13B966",
          SpeakNpcId = 200002,
          Subtitle = "Got it! Time for the Demon King's demolition crew to work their magic!",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B966"
        },
        [12014601] = {
          ContentTC = "「我們都是木頭人，不許說話不許動……」",
          DialogueId = 12014601,
          Duration = 3,
          GUID = "1E13C97A",
          NextDialogue = 12014602,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "\"We're all statues... no talking, no moving...\"",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C97A"
        },
        [12014602] = {
          ContentTC = "它在哪裡呢？",
          DialogueId = 12014602,
          Duration = 1,
          GUID = "1E13C9A4",
          NextDialogue = 12014605,
          SpeakNpcId = 200002,
          Subtitle = "Where could it be?",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9A4"
        },
        [12014603] = {
          ContentTC = "或許是這裡的氣味讓它感到陌生，所以不願意顯現身形。",
          DialogueId = 12014603,
          Duration = 3,
          GUID = "1E13C9CE",
          SpeakNpcId = 210013,
          Subtitle = "Maybe the unfamiliar scents here make it wary, so it hides away.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9CE"
        },
        [12014604] = {
          ContentTC = "點燃香爐試試吧，熟悉的香味能夠給它帶來安心感。",
          DialogueId = 12014604,
          Duration = 2,
          GUID = "1E13C9F8",
          SpeakNpcId = 210013,
          Subtitle = "Let's light the incense. The familiar fragrance may soothe it...",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9F8"
        },
        [12014605] = {
          ContentTC = ".....這裡的花苞受塵漠侵蝕，散發出一股異樣的香氣。我想，它恐怕是因此不願意顯現身形。",
          DialogueId = 12014605,
          GUID = "1E13C9F9",
          NextDialogue = 12014606,
          SpeakNpcId = 210013,
          Subtitle = "These buds have been tainted, giving off unfamiliar scents. That might be why it refuses to show itself.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9F9"
        },
        [12014606] = {
          ContentTC = "清除這些花苞試試看吧。",
          DialogueId = 12014606,
          GUID = "1E13CA11",
          SpeakNpcId = 210013,
          Subtitle = "Let's clear out these buds.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13CA11"
        },
        [12014701] = {
          ContentTC = "被你找到啦！",
          DialogueId = 12014701,
          Duration = 2,
          GUID = "1E13D9E2",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "You found me!",
          VoiceName = "voice/$Locale$/story/1201/120147/1E13D9E2"
        },
        [12014801] = {
          ContentTC = "「……我、我是木頭人！你看不到我，也不能打我！」",
          DialogueId = 12014801,
          Duration = 3,
          GUID = "1E13EA4A",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "\"I—I'm a statue! You can't see me, and you can't hit me either!\"",
          VoiceName = "voice/$Locale$/story/1201/120148/1E13EA4A"
        },
        [12014802] = {
          ContentTC = "祠台就在前面，我認得路了......謝謝你們！",
          DialogueId = 12014802,
          GUID = "1E13EA4B",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "I know the way... the altar is up ahead, thank you!",
          VoiceName = "voice/$Locale$/story/1201/120148/1E13EA4B"
        },
        [12014901] = {
          ContentTC = "那個石碑上好像寫著什麼字！",
          DialogueId = 12014901,
          Duration = 2,
          GUID = "1E13FAB2",
          SpeakNpcId = 200002,
          Subtitle = "Hey! There's something written on that stone tablet!",
          VoiceName = "voice/$Locale$/story/1201/120149/1E13FAB2"
        },
        [12014902] = {
          ContentTC = "<H>高高在上</>俯眾生，<H>漸漸低下</>歸於塵。無聲無息隨風去，誰能知曉它蹤跡？",
          DialogueId = 12014902,
          GUID = "1E13FADC",
          Subtitle = "Lofty above, watching all below. Drifting down, returning to soil. Silent and unseen, swept away on the wind... Tell me — can you find its trail?",
          VoiceName = "voice/$Locale$/story/1201/120149/1E13FADC"
        },
        [12015001] = {
          ContentTC = "別玩了，快跟著我們回去啦！",
          DialogueId = 12015001,
          Duration = 2,
          GUID = "1E140B1A",
          NextDialogue = 12015002,
          SpeakNpcId = 200002,
          Subtitle = "Come on, playtime's over! Let's go back!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B1A"
        },
        [12015002] = {
          ContentTC = "不行，還沒有玩夠！謎底，必須先解開謎底才可以！",
          DialogueId = 12015002,
          Duration = 3,
          GUID = "1E140B44",
          NextDialogue = 12015003,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Uh-uh! Not until you solve my riddle!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B44"
        },
        [12015003] = {
          ContentTC = "真是頭疼……這是什麼意思呢，{nickname}？",
          DialogueId = 12015003,
          Duration = 2,
          GUID = "1E140B6E",
          NextDialogue = 12015004,
          SpeakNpcId = 200002,
          Subtitle = "Ugh, this is giving me a headache... , any idea?",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B6E"
        },
        [12015004] = {
          ContentTC = "「高高在上，漸漸低下」.....我想，或許這些花苞需要用自上而下的順序擊打才可以？",
          DialogueId = 12015004,
          GUID = "1E140B6F",
          NextDialogue = 12015005,
          SpeakNpcId = 210013,
          Subtitle = "\"Lofty above, drifting down\"... I suppose, maybe we need to hit the buds from top to bottom?",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B6F"
        },
        [12015005] = {
          ContentTC = "有道理哦，小僕從，我們趕緊試試！",
          DialogueId = 12015005,
          GUID = "1E140B71",
          SpeakNpcId = 200002,
          Subtitle = "Ooh, that makes sense! Let's try it, Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B71"
        },
        [12015101] = {
          Camera = "428.628632,87.300842,126.54541,0.0,0.0,-179.794601,30.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "怎麼樣，你們現在有答案了嗎？",
