        },
        [12015602] = {
          Camera = "1049.913574,-119.71582,311.329102,0.0001,-14.398373,162.820862,30.0,248.711517,false,DoNotOverride,6.747885",
          ContentTC = "{nickname}，小白，可否搭把手？在露水散去前，我需要采摘十株忘憂草。",
          DialogueId = 12015602,
          Duration = 1,
          FinalCamera = "1015.789062,-208.617188,311.329102,0.000098,-13.998349,157.021118,30.0,248.711517,false,DoNotOverride,6.747885",
          GUID = "1E146DB4",
