          GUID = "1E1659E4",
          NextDialogue = 12018603,
          SpeakNpcId = 210012,
          Subtitle = "How is everything going?",
          VoiceName = "voice/$Locale$/story/1201/120186/1E1659E4"
        },
        [12018603] = {
          Camera = "32.268948,257.847717,186.833252,0.00014,-8.414738,-115.807419,35.000011,279.251068,false,Manual,6.0",
          ContentTC = "如您所料，那獵物負了傷，已被逼入了聽鴉原。這兒四面環海，呈孤島之勢，它逃不掉的。接下來只要甕中捉鱉就好了！",
          DialogueId = 12018603,
          FacialId = {
            [1] = "210010:CM_Idle"
          },
          GUID = "1E165A0E",
          NextDialogue = 12018604,
          SpeakNpcId = 210010,
          SpeakNpcName = "UI_CMName_Name_HeiShiXiaoDi",
          Subtitle = "Just as you foresaw — the prey's been wounded and driven into Crowsong Hollow. The place is ringed by the sea — like an island cut off from the world. There's no way out for it. Now we've only to close the net.",
          TalkActionId = {
            [1] = "210010:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A0E"
        },
        [12018604] = {
