        [12018606] = {
          Camera = "-103.426682,207.213165,221.943604,0.000147,-24.816774,-27.574326,35.000008,245.026596,false,Manual,22.0",
          ContentTC = "這地方，有什麼不妥嗎？",
          DialogueId = 12018606,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E165A8C",
          LookAt = {
            [1] = "100001:n(210012)"
          },
          NextDialogue = 12018607,
          SpeakNpcId = 100001,
          Subtitle = "Is there something wrong with that place?",
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A8C"
        },
        [12018607] = {
          Camera = "-14.455,160.474716,158.683838,0.000099,-0.817505,-128.967682,35.0,196.648346,false,Manual,6.0",
          ContentTC = "屬下尋思這裡是古戰場遺址，平時陰風陣陣的，路人都會繞著走。在這裡行動不容易受打擾……",
          DialogueId = 12018607,
          FacialId = {
            [1] = "210010:CM_Sad01"
          },
          GUID = "1E165AB6",
          NextDialogue = 12018608,
          SpeakNpcId = 210010,
          Subtitle = "Well, sir... it's part of the ancient battlefield — cold winds, eerie as can be. Nobody goes near it, so we thought it would be safer — less chance of interruption...",
          TalkActionId = {
            [1] = "210010:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165AB6"
        },
        [12018608] = {
          Camera = "-208.853943,31.453308,168.279785,0.00011,-6.41742,16.636448,25.0,316.576935,false,Manual,6.0",
          ContentTC = "這裡是黍離之戰的交戰場所沒錯。你可知此地更之前的用途嗎？",
          DialogueId = 12018608,
          GUID = "1E165AE0",
          LookAt = {
            [1] = "100001:n(210010)"
          },
          NextDialogue = 12018609,
          SpeakNpcId = 210012,
          Subtitle = "This was indeed the site of the Battle of Shuli. But do you know what it was before that?",
          TalkActionId = {
            [1] = "210012:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165AE0"
        },
        [12018609] = {
          ContentTC = "呃，確實沒聽說過……還請頭兒提點。",
          DialogueId = 12018609,
          GUID = "1E165B0A",
          NextDialogue = 12018610,
          SpeakNpcId = 210010,
          Subtitle = "Uh... no, sir. Please, enlighten us.",
          TalkActionId = {
            [1] = "210010:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B0A"
        },
        [12018610] = {
          Camera = "-2403.743896,115.38797,1248.473267,0.00005,-28.217525,2.442638,25.0,316.576935,false,Manual,22.0",
          ContentTC = "上古時期，機樞派的研究重地就立於此地。直至數百年前，懸衡派懷疑此地有叛亂嫌疑，引重兵前來鎮壓。",
          DialogueId = 12018610,
          FinalCamera = "-2292.674805,-508.969971,1248.90564,0.000039,-28.817556,18.043545,25.0,316.576935,false,Manual,22.0",
          GUID = "1E165B34",
          LookAt = {
            [1] = "210012:p(48_lookat)"
          },
          NextDialogue = 12018611,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4},TargetPosition{"101.46463,2433.009766,1018.791992,0.000078,-9.019374,-144.965591,14.0,316.576935,false,Manual,22.0"},duration{0}},
CameraMoveTo{_delay{4.1},TargetPosition{"-306.286438,2143.177002,1099.884155,0.000079,19.780664,-144.165909,14.0,316.576935,false,Manual,22.0"},duration{10}}
}]],
          SpeakNpcId = 210012,
          Subtitle = "Long ago, this place served as a key research ground for the Jishu Sect — until a few centuries past, when the Xuanheng Sect grew suspicious of rebellion and sent in a heavy force to put it down.",
          TalkActionId = {
            [1] = "210012:Talk03_Start",
            [2] = "210010:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B34"
        },
        [12018611] = {
          Camera = "-92.525726,134.76416,116.622314,0.000168,23.376129,15.452583,25.000002,141.235916,false,Manual,22.0",
          ContentTC = "最終交戰雙方全數折於此地，無一人生還。機樞派也自此式微。",
          DialogueId = 12018611,
          GUID = "1E165B5E",
          LookAt = {
            [1] = "210012:n(210012)"
          },
          NextDialogue = 12018612,
          SpeakNpcId = 210012,
          Subtitle = "In the end, both sides were lost — no survivors. From then on, the Jishu Sect faded into obscurity.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B5E"
        },
        [12018612] = {
          Camera = "-182.100525,11.012974,170.185303,0.000135,-6.422201,31.032133,25.0,57.624985,false,Manual,6.0",
          ContentTC = "人泯滅在曆史煙塵中，物卻還留著。",
          DialogueId = 12018612,
          FinalCamera = "-182.100525,11.012974,170.185303,0.000135,-6.422201,31.032133,25.0,257.755127,false,Manual,6.0",
          GUID = "1E165B88",
          LookAt = {
            [1] = "210012:p(48_lookat)"
          },
          NextDialogue = 12018613,
          Scripts = "LookAt{_delay{3},LookAtDescription{\"210012:n(210010)\"}}",
          SpeakNpcId = 210012,
          Subtitle = "Those who vanished into the mists of history... left behind what they had crafted.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_End"
          },
          ToFinalCameraBlendTime = 1.2,
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B88"
        },
        [12018613] = {
          ContentTC = "此地的機巧奧義已經失傳，萬一被不慎觸發，恐會帶來變數。",
          DialogueId = 12018613,
          GUID = "1E165BB2",
          LookAt = {
