        },
        [12018908] = {
          ContentTC = "呵呵……那就得仰仗{nickname}矯健的身手了。",
          DialogueId = 12018908,
          FacialId = {
            [1] = "210012:Ahaha01"
          },
          GUID = "1E168C18",
          SpeakNpcId = 210012,
          Subtitle = "Hehe... then we'll be counting on your nimble moves, .",
          TurnTo = {
            [1] = "210012:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120189/1E168C18"
        },
        [12019001] = {
          ContentTC = "我曾聽聞，機樞派以赤色為尊。",
          DialogueId = 12019001,
          GUID = "1E169B5A",
          NextDialogue = 12019002,
          SpeakNpcId = 210012,
          Subtitle = "I've heard the Jishu Sect revered the colour red above all others.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B5A"
        },
        [12019002] = {
          ContentTC = "也就是說，紅色的道路是安全的。",
          DialogueId = 12019002,
          GUID = "1E169B84",
          SpeakNpcId = 100001,
          Subtitle = "So the red path is the safer one — got it.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B84"
        },
        [12019050] = {
          ContentTC = "好像有些機關塊亮起來了......小僕從，這是什麼意思？",
          DialogueId = 12019050,
          GUID = "1E169B85",
          NextDialogue = 12019051,
          SpeakNpcId = 200002,
          Subtitle = "Look, some of the blocks lit up... What does that mean, Little Minion?",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B85"
        },
        [12019051] = {
          ContentTC = "用意很明顯了。順著機關塊亮起的順序前行，就能破解當下的困局。",
          DialogueId = 12019051,
          GUID = "1E169B86",
          NextDialogue = 12019052,
          SpeakNpcId = 210012,
          Subtitle = "The intent is quite clear. Proceed in the order the blocks illuminated, and you shall resolve our current predicament.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B86"
        },
        [12019052] = {
          ContentTC = "......這種事情不需要你提醒，我們小僕從也知道!",
          DialogueId = 12019052,
          GUID = "1E169B87",
          NextDialogue = 12019053,
          SpeakNpcId = 200002,
          Subtitle = "...We didn't need you to tell us that! My Little Minion already knew!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B87"
        },
        [12019053] = {
          ContentTC = "好，那我試試。",
          DialogueId = 12019053,
          GUID = "1E169B88",
          SpeakNpcId = 100001,
          Subtitle = "Alright, I'll give it a try.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B88"
        },
        [12019054] = {
          ContentTC = "哇啊啊啊啊，這些機關塊怎麼還會動，要是不小心踩空就摔下去了！",
          DialogueId = 12019054,
          GUID = "1E169B89",
          NextDialogue = 12019055,
          SpeakNpcId = 200002,
          Subtitle = "Whoaaaa, these blocks are moving! If we miss a step, we'll fall right down!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B89"
        },
        [12019055] = {
          ContentTC = "魔王大人英明一世，差點陰溝裡翻船......實在是太陰險了！",
          DialogueId = 12019055,
          GUID = "1E169B91",
          NextDialogue = 12019056,
          SpeakNpcId = 200002,
          Subtitle = "The great Demon King almost got bested by such a cheap trick... How treacherous!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B91"
        },
        [12019056] = {
          ContentTC = "呵呵。若是難度不升級，何談挑戰呢?",
          DialogueId = 12019056,
          GUID = "1E169B92",
          NextDialogue = 12019057,
          SpeakNpcId = 210012,
          Subtitle = "Heh. A predictable path can hardly be called a challenge, can it?",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B92"
        },
        [12019057] = {
          ContentTC = "哼，輪不到你來說！",
          DialogueId = 12019057,
          GUID = "1E169B93",
          SpeakNpcId = 200002,
          Subtitle = "Hmph! Nobody asked you!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B93"
        },
        [12019058] = {
          ContentTC = "呀！哪裡冒出來的傢伙，會動.......還打我們！",
          DialogueId = 12019058,
          GUID = "1E169B94",
          NextDialogue = 12019059,
          SpeakNpcId = 200002,
          Subtitle = "Ah! Where did these things come from?! They're moving... and they're attacking us!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B94"
        },
        [12019059] = {
          ContentTC = "想必是此地設計之初留下來的守備力量，用以防禦外來的入侵者。",
          DialogueId = 12019059,
          GUID = "1E169B95",
          NextDialogue = 12019060,
          SpeakNpcId = 210012,
          Subtitle = "Must be guardians left here since this place was built, meant to defend against intruders.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B95"
        },
        [12019060] = {
          ContentTC = "提起精神應對他們，{nickname}。",
          DialogueId = 12019060,
          GUID = "1E169B96",
          SpeakNpcId = 210012,
          Subtitle = "Stay sharp and deal with them, .",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B96"
        },
        [12019101] = {
          ContentTC = "咦，同時出現了兩座一模一樣的醒世碑……",
          DialogueId = 12019101,
          GUID = "1E16ABC2",
          NextDialogue = 12019102,
          SpeakNpcId = 200002,
          Subtitle = "Huh? Two identical Steles at the same time...?",
          VoiceName = "voice/$Locale$/story/1201/120191/1E16ABC2"
        },
        [12019102] = {
          ContentTC = "嗯……莫非是需要二人分處兩地，同時敲響。",
          DialogueId = 12019102,
          GUID = "1E16ABEC",
          NextDialogue = 12019103,
          SpeakNpcId = 210012,
          Subtitle = "Hmm... Perhaps they must be struck simultaneously from separate positions.",
          VoiceName = "voice/$Locale$/story/1201/120191/1E16ABEC"
        },
        [12019103] = {
          ContentTC = "{nickname}，且與我一試。",
          DialogueId = 12019103,
          GUID = "1E16AC16",
          SpeakNpcId = 210012,
          Subtitle = "Let's give it a try, . ",
          VoiceName = "voice/$Locale$/story/1201/120191/1E16AC16"
        },
        [12019201] = {
          ContentTC = "哇啊啊啊啊啊啊啊——白、白的屁股，摔得好痛！",
          DialogueId = 12019201,
          GUID = "1E16BC2A",
          NextDialogue = 12019202,
          SpeakNpcId = 200002,
          Subtitle = "Aaaahhhh—! My poor buns! They really took a critical hit!",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC2A"
        },
        [12019202] = {
          ContentTC = "虬先生不知道掉到哪裡去了……",
          DialogueId = 12019202,
          GUID = "1E16BC54",
          NextDialogue = 12019203,
          SpeakNpcId = 200002,
          Subtitle = "Where did Mr Qiu end up...?",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC54"
        },
        [12019203] = {
          ContentTC = "難道說，這個機關戰陣的用意就是把同行者分開……？",
          DialogueId = 12019203,
          GUID = "1E16BC7E",
          NextDialogue = 12019204,
          SpeakNpcId = 100001,
          Subtitle = "Could it be... this entire mechanism array was meant to separate anyone travelling together...?",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC7E"
        },
        [12019204] = {
          ContentTC = "等等，小僕從！前面有人！",
          DialogueId = 12019204,
          GUID = "1E16BCA8",
          SpeakNpcId = 200002,
          Subtitle = "Wait, Little Minion! There's someone up ahead!",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BCA8"
        },
        [12019301] = {
          ContentTC = "真好，有人來了！這下不僅是我一人困在這裡了。",
          DialogueId = 12019301,
          GUID = "1E16CC92",
          NextDialogue = 12019302,
          SpeakNpcId = 210021,
          SpeakNpcName = "UI_CMName_Name_SaTuoBuJi",
          Subtitle = "Haha... Finally, some company! I'm not alone in this pit anymore.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CC92"
        },
        [12019302] = {
          ContentTC = "我名刻舟，華胥一介飄零人是也。敢問兩位姓名？",
          DialogueId = 12019302,
          GUID = "1E16CCBC",
          NextDialogue = 12019303,
          RelatedWikiId = {
            [1] = 203007
          },
          SpeakNpcId = 210021,
          Subtitle = "The name's Kezhou, a Drifter from Huaxu. And you two are...?",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CCBC"
        },
        [12019303] = {
          ContentTC = "那……我是純白的救贖☆光之魔王大人，簡稱白。如你所見，是一名魔王！征服世界的事找我就對了！",
          DialogueId = 12019303,
          GUID = "1E16CCE6",
          NextDialogue = 12019304,
          SpeakNpcId = 200002,
          Subtitle = "Since you asked... Ahem! I am the Pure-White Redeemer ☆ Demon King of Light! You can call me Snow! As you can see, I'm a real Demon King, and my purpose is to conquer the world!",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CCE6"
        },
        [12019304] = {
          ContentTC = "這位是我的小僕從，{nickname}。{性别:他|她}是僅次於白的最厲害的人！",
          DialogueId = 12019304,
          GUID = "1E16CD10",
          NextDialogue = 12019305,
          SpeakNpcId = 200002,
          Subtitle = "And this is my Little Minion, . {性别:He|She}'s the second strongest fighter in the world — right after me!",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CD10"
        },
        [12019305] = {
          ContentTC = "哦哦……！原來如此！難怪我以隨身的槍戟劍林將此地翻來覆去轟了幾遍，都沒能撼動分毫……竟是要敲擊這裡。話說回來，這機樞派的造物可真結實。",
          DialogueId = 12019305,
          GUID = "120193141.0",
          SpeakNpcId = 210021,
          Subtitle = "Huh — so that's the trick! No wonder I battered this place with all the blades I carry, and it wouldn't budge an inch... turns out you just have to give the right spot a tap! Gotta hand it to the Jishu Sect — they built things to last.",
          VoiceName = "voice/$Locale$/story/1201/120193/120193141"
        }
      }
    end
  },
  {
    MinKey = 12019306,
    MaxKey = 12022304,
    Loader = function()
      return {
        [12019306] = {
          ContentTC = "幸會幸會……原來華胥之外的地方，還有如此拉風的職業！相逢即是有緣，何不結伴一程？",
          DialogueId = 12019306,
          GUID = "120193051.0",
          SpeakNpcId = 210021,
          Subtitle = "A pleasure... Seems like the world beyond Huaxu has no shortage of colourful characters! Since fate brought us together, why not share the road for a while?",
          VoiceName = "voice/$Locale$/story/1201/120193/120193051"
        },
        [12019307] = {
          ContentTC = "既然你如此仰慕魔王大人，那當然好！哼哼，還是華胥人有品位！",
          DialogueId = 12019307,
          GUID = "1E16CD8E",
          NextDialogue = 12019308,
          SpeakNpcId = 200002,
          Subtitle = "Oh-ho! So you admire this Great Demon King that much? Well then — of course! Heehee, Huaxu folks do have good taste!",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CD8E"
        },
        [12019308] = {
          ContentTC = "這樣吧，白冊封你為「黑白毛色的俠客，不羈的劍歌浪子，魔王國駐華胥外交大使」！",
          DialogueId = 12019308,
          GUID = "1E16CDB8",
          NextDialogue = 12019309,
          SpeakNpcId = 200002,
          Subtitle = "Listen well: I, Snow, hereby dub you the \"Black-and-White Blade Vagabond, Free-Spirited Swordsman, and Grand Ambassador of the Demon King's Court to Huaxu!\"",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CDB8"
        },
        [12019309] = {
          ContentTC = "哈哈……結交兩位，刻舟心中痛快不已！若不是困於此處，簡直想舞劍助興，與君暢飲至天明！",
          DialogueId = 12019309,
          GUID = "1E16CDE2",
          NextDialogue = 12019310,
          SpeakNpcId = 210021,
          Subtitle = "Haha... meeting you two has truly lifted my spirits! If we weren't stuck here, I'd be swinging my sword in celebration and drinking with you till dawn!",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CDE2"
        },
        [12019310] = {
          ContentTC = "對了，你們來時，有見過一名與我年歲相仿的男子嗎？我好不容易追他的蹤跡到這裡。他黑發，穿一身墨色衣服，很好認的！",
          DialogueId = 12019310,
          GUID = "1E16CE0C",
          NextDialogue = 12019311,
          SpeakNpcId = 210021,
          Subtitle = "By the way — did you happen to see a man about my age on your way here? Dark hair, dressed head to toe in black — he'd be hard to miss.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CE0C"
        },
        [12019311] = {
          ContentTC = "這樣的人，滿大街都是吧……",
          DialogueId = 12019311,
          GUID = "1E16CE36",
          NextDialogue = 12019312,
          SpeakNpcId = 200002,
          Subtitle = "Um... that describes about half of the people we met...",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CE36"
        },
        [12019312] = {
          ContentTC = "我們來的路上，沒見到別人。",
          DialogueId = 12019312,
          GUID = "1E16CE60",
          NextDialogue = 12019313,
          SpeakNpcId = 100001,
          Subtitle = "We didn't see anyone like that on the way here.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CE60"
        },
        [12019313] = {
          ContentTC = "唉……罷了。找了四年了，也不差這一時半會兒。那你們知道該如何從這兒出去嗎？",
          DialogueId = 12019313,
          GUID = "1E16CE8A",
          NextOptions = {
            [1] = 12019314
          },
          SpeakNpcId = 210021,
          Subtitle = "Ah... never mind. Four years of chasing — what's a little longer now? Anyway — do you two have any idea how to get out of here?",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CE8A"
        },
        [12019314] = {
          ContentTC = "（告知機關訣竅）",
          DialogueId = 12019314,
          GUID = "1E16CEB4",
          NextDialogue = 120193141,
          Subtitle = "(Tell him how the mechanism works)"
        },
        [12019315] = {
          ContentTC = "你好。",
          DialogueId = 12019315,
          GUID = "12019315",
          Subtitle = "Hello."
        },
        [12019316] = {
          ContentTC = "好暴力狂的發言！",
          DialogueId = 12019316,
          GUID = "1E16CF08",
          NextDialogue = 12019317,
          SpeakNpcId = 200002,
          Subtitle = "Whoa... That sounds really violent!",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CF08"
        },
        [12019317] = {
          ContentTC = "要是凡事都真能靠打一架解決就好了……那一切就簡單得多。",
          DialogueId = 12019317,
          GUID = "1E16CF32",
          NextDialogue = 12019318,
          SpeakNpcId = 210021,
          Subtitle = "If only every problem in life could be solved with a good fight... things would be so much simpler.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CF32"
        },
        [12019318] = {
          ContentTC = "唉，多說無益，我們還是趕緊逃出去吧。",
          DialogueId = 12019318,
          GUID = "1E16CF5C",
          SpeakNpcId = 210021,
          Subtitle = "Ah, enough talking — let's get out of here.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CF5C"
        },
        [12019401] = {
          ContentTC = "機關塊活過來了！{nickname}，不愧是你。",
          DialogueId = 12019401,
          GUID = "1E16DCFA",
          NextDialogue = 12019402,
          SpeakNpcId = 210021,
          Subtitle = "It really worked! Very impressive, .",
          VoiceName = "voice/$Locale$/story/1201/120194/1E16DCFA"
        },
        [12019402] = {
          ContentTC = "誒，它們排列的圖案……是什麼意思呢？",
          DialogueId = 12019402,
          GUID = "1E16DD24",
          NextDialogue = 12019403,
          SpeakNpcId = 200002,
          Subtitle = "Hey, look at those patterns... any idea what they're supposed to mean?",
          VoiceName = "voice/$Locale$/story/1201/120194/1E16DD24"
        },
        [12019403] = {
          ContentTC = "如果踩上對應的機關塊……或許可以到對岸去？",
          DialogueId = 12019403,
          GUID = "1E16DD4E",
          SpeakNpcId = 100001,
          Subtitle = "If I step on the right blocks... maybe I can cross to the other side.",
          VoiceName = "voice/$Locale$/story/1201/120194/1E16DD4E"
        },
        [12019501] = {
          ContentTC = "活動筋骨的時候到了！",
          DialogueId = 12019501,
          GUID = "1E16ED62",
          NextDialogue = 12019502,
          SpeakNpcId = 210021,
          Subtitle = "Finally — time to limber up!",
          VoiceName = "voice/$Locale$/story/1201/120195/1E16ED62"
        },
        [12019502] = {
          ContentTC = "此前被關在這，做什麼都不得勁……要說打架我可就不困了！{nickname}，你看好了！",
          DialogueId = 12019502,
          GUID = "1E16ED8C",
          SpeakNpcId = 210021,
          Subtitle = "I've been cooped up here so long I couldn't even get a proper swing in... but now? A fight's just the thing to wake me up! Watch close,  — this is what I'm made of!",
          VoiceName = "voice/$Locale$/story/1201/120195/1E16ED8C"
        },
        [12019601] = {
          ContentTC = "這些機關塊的排列……怎麼越來越複雜了？看得我頭暈眼花的。",
          DialogueId = 12019601,
          GUID = "1E16FDCA",
          NextDialogue = 12019602,
          SpeakNpcId = 210021,
          Subtitle = "These arrangements are getting more and more complicated... I can't make heads or tails of them anymore.",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FDCA"
        },
        [12019602] = {
          ContentTC = "哼哼……大個子只會用蠻力，還得我們小僕從來！",
          DialogueId = 12019602,
          GUID = "1E16FDF4",
          NextDialogue = 12019603,
          SpeakNpcId = 200002,
          Subtitle = "Hmph! Big guys like you are only muscles — this kind of brain work? Leave it to my Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FDF4"
        },
        [12019603] = {
          ContentTC = "對對，全仰仗你了，{nickname}！",
          DialogueId = 12019603,
          GUID = "1E16FE1E",
          NextDialogue = 12019604,
          SpeakNpcId = 210021,
          Subtitle = "Right, right... we're counting on you, !",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE1E"
        },
        [12019604] = {
          ContentTC = "……真拿你們沒辦法。",
          DialogueId = 12019604,
          GUID = "1E16FE48",
          SpeakNpcId = 100001,
          Subtitle = "...Fine.",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE48"
        },
        [12019605] = {
          ContentTC = "小僕從，空中懸著的那個球看起來有點奇怪。要不要用牽機方樞試試看？",
          DialogueId = 12019605,
          GUID = "1E16FE72",
          SpeakNpcId = 200002,
          Subtitle = "Hey, Little Minion — look at that orb floating up there. It's kinda suspicious, don't you think? Maybe try using the Mechanical Nexus on it?",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE72"
        },
        [12019606] = {
          ContentTC = "竟一下就飛躍過來了，暢快！",
          DialogueId = 12019606,
          GUID = "1E16FE9C",
          SpeakNpcId = 210021,
          Subtitle = "What a leap! That was thrilling!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE9C"
        },
        [12019610] = {
          ContentTC = "好眼熟.....小僕從，這不是公尚師傅教過我們的機關嗎？竟然在這裡也出現了！",
          DialogueId = 12019610,
          GUID = "1E16FE9F",
          NextDialogue = 12019611,
          SpeakNpcId = 200002,
          Subtitle = "This looks familiar... isn't this the mechanism Master Gongshang taught us?",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE9F"
        },
        [12019611] = {
          ContentTC = "我們趕緊用那個牽機方樞試試看吧！",
          DialogueId = 12019611,
          GUID = "1E16FF11",
          NextDialogue = 12019612,
          SpeakNpcId = 200002,
          Subtitle = "Let's try using that Mechanical Nexus right now!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF11"
        },
        [12019612] = {
          ContentTC = "千機......方什麼輸？這莫非是某柄上等寶劍的名字？",
          DialogueId = 12019612,
          GUID = "1E16FF12",
          NextDialogue = 12019613,
          SpeakNpcId = 210021,
          Subtitle = "The... Mechanical what? Is that the name of some top-tier sword?",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF12"
        },
        [12019613] = {
          ContentTC = "沒文化，這可是最新最勁的機樞派造物！你就站著瞧吧！",
          DialogueId = 12019613,
          GUID = "1E16FF13",
          SpeakNpcId = 200002,
          Subtitle = "So uncultured! It's the hottest invention from Jishu Sect! Just stand back and watch!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF13"
        },
        [12019616] = {
          ContentTC = "如此輕易就能化解謎題，跟你們可真是跟對人了！",
          DialogueId = 12019616,
          GUID = "1E16FF14",
          NextDialogue = 12019617,
          SpeakNpcId = 210021,
          Subtitle = "Solving puzzles is a breeze with you two! I knew I picked the right team!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF14"
        },
        [12019617] = {
          ContentTC = "哼哼，那可不！",
          DialogueId = 12019617,
          GUID = "1E16FF15",
          NextDialogue = 12019618,
          SpeakNpcId = 200002,
          Subtitle = "Hehe, you bet!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF15"
        },
        [12019618] = {
          ContentTC = "大個子，你要緊緊跟好我們。你要是走丟了，我們可幫不了你。",
          DialogueId = 12019618,
          GUID = "1E16FF16",
          NextDialogue = 12019619,
          SpeakNpcId = 200002,
          Subtitle = "Big guy, you'd better stick close. If you get lost, you're on your own!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF16"
        },
        [12019619] = {
          ContentTC = "(不妙，白好像越來越得意了......她的尾巴都要翹到天上了！)",
          DialogueId = 12019619,
          GUID = "1E16FF17",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Yikes, Snow's getting a bit full of herself... She's practically floating on air!)",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF17"
        },
        [12019701] = {
          ContentTC = "又出現了……這醒世碑需要兩人同時敲擊，之後腳下平台會翻轉，讓我們掉到不同的地方。",
          DialogueId = 12019701,
          GUID = "1E170E32",
          NextDialogue = 12019702,
          SpeakNpcId = 100001,
          Subtitle = "It's those Steles again... here's how it works: we'll have to strike them both at once. Then the platform will flip, dropping us in different places.",
          VoiceName = "voice/$Locale$/story/1201/120197/1E170E32"
        },
        [12019702] = {
          ContentTC = "那先就此別過啦。多謝兩位帶我一路，改日再會！",
          DialogueId = 12019702,
          GUID = "1E170E5C",
          SpeakNpcId = 210021,
          Subtitle = "Then this is goodbye. Thank you both for the company — until we cross paths again!",
          VoiceName = "voice/$Locale$/story/1201/120197/1E170E5C"
        },
        [12019800] = {
          Content = "虬先生就在前面。【废弃】",
          DialogueId = 12019800,
          GUID = "1E170E5D",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120198/1E170E5D"
        },
        [12019801] = {
          ContentTC = "將分開時的經曆告知了虬先生。",
          DialogueId = 12019801,
          GUID = "1E171E9A",
          SpeakNpcId = 100001,
          Subtitle = "You recount to Mr Qiu everything that happened while you were separated.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171E9A"
        },
        [12019802] = {
          ContentTC = "竟還有這般節外生枝……呵呵，這場捕獵，越來越趣味橫生了。",
          DialogueId = 12019802,
          GUID = "1E171EC4",
          NextDialogue = 12019803,
          SpeakNpcId = 210012,
          Subtitle = "So... even more twists to our little hunt... Heh. It grows more and more intriguing.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171EC4"
        },
        [12019803] = {
          ContentTC = "在這裡待久了，也有些膩味了。我們還是動身向前，趁早離開此地吧。",
          DialogueId = 12019803,
          GUID = "1E171EEE",
          SpeakNpcId = 210012,
          Subtitle = "I've had my fill of this place. Let's keep moving and be done with it.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171EEE"
        },
        [12019804] = {
          ContentTC = "呵呵……瞧你們使用這機樞派的寶貝，是越來越熟練了。怎麼樣，還喜歡不？",
          DialogueId = 12019804,
          Duration = 3,
          GUID = "1E171F18",
          SpeakNpcId = 210012,
          Subtitle = "Heh... you're getting rather good with these Jishu Sect trinkets. Quite the amusement, wouldn't you say?",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F18"
        },
        [12019805] = {
          ContentTC = "眼前看來就是最後的考驗了。走吧，{nickname}。該結束這一切了。",
          DialogueId = 12019805,
          Duration = 2,
          GUID = "1E171F42",
          SpeakNpcId = 210012,
          Subtitle = "Looks like this is the final trial. Come,  — it is time to bring it all to an end.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F42"
        },
        [12019810] = {
          ContentTC = "這個青銅大傢伙是什麼？！",
          DialogueId = 12019810,
          GUID = "1E171F43",
          SpeakNpcId = 100001,
          Subtitle = "What's this giant bronze guy?!",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F43"
        },
        [12019811] = {
          ContentTC = "此乃上古機樞派造物，名為<H>巨闕</>。",
          DialogueId = 12019811,
          GUID = "1E171F44",
          SpeakNpcId = 210012,
          Subtitle = "This is Terracolossus, the ancient creation of Jishu Sect.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F44"
        },
        [12019812] = {
          ContentTC = "傳聞中，機樞派曾想研製出能讓人類駕駛的巨大人形機傀，巨闕是這種嘗試留下的痕跡之一。",
          DialogueId = 12019812,
          GUID = "1E171F45",
          SpeakNpcId = 210012,
          Subtitle = "Legends say the Jishu Sect once sought to develop giant, humanoid-shaped mechapuppets pilotable for humans. I assume this thing witnessed that piece of history.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F45"
        },
        [12019813] = {
          ContentTC = "誒，聽起來還有點拉風呢......",
          DialogueId = 12019813,
          GUID = "1E171F46",
          SpeakNpcId = 200002,
          Subtitle = "Hey, that actually sounds kinda cool...",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F46"
        },
        [12019814] = {
          ContentTC = "要是有那種能駕駛的機傀存在，魔王大人也想試一試!",
          DialogueId = 12019814,
          GUID = "1E171F47",
          SpeakNpcId = 200002,
          Subtitle = "If such mechapuppets really exist, the Demon King would want to try!",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F47"
        },
        [12019901] = {
          ContentTC = "這場你追我逃的遊戲……該到此為止了。你說是嗎，應天尉？",
          DialogueId = 12019901,
          GUID = "1E172F02",
          NextDialogue = 12019902,
          RelatedWikiId = {
            [1] = 203005,
            [2] = 203004
          },
          SpeakNpcId = 210012,
          Subtitle = "This little game of cat and mouse... it ends here. Wouldn't you agree, dear Magistrate of Yingtian?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F02"
        },
        [12019902] = {
          ContentTC = "……",
          DialogueId = 12019902,
          GUID = "1E172F2C",
          NextDialogue = 12019903,
          SpeakNpcId = 210007,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F2C"
        },
        [12019903] = {
          ContentTC = "煜明……怎麼是你？！",
          DialogueId = 12019903,
          GUID = "1E172F56",
          NextDialogue = 12019904,
          SpeakNpcId = 100001,
          Subtitle = "Yuming!?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F56"
        },
        [12019904] = {
          ContentTC = "你所說的「狴犴」，難不成就是他？",
          DialogueId = 12019904,
          GUID = "1E172F80",
          NextDialogue = 12019905,
          SpeakNpcId = 100001,
          Subtitle = "The \"Bi'an\" you've been talking about — you meant him all along?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F80"
        },
        [12019905] = {
          ContentTC = "又玩文字遊戲是吧。對不起，我不乾了。",
          DialogueId = 12019905,
          GUID = "1E172FAA",
          NextDialogue = 12019906,
          SpeakNpcId = 100001,
          Subtitle = "That's it. I'm out.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172FAA"
        },
        [12019906] = {
          ContentTC = "就算是魔王大人，也是有底線的！",
          DialogueId = 12019906,
          GUID = "1E172FD4",
          NextDialogue = 12019907,
          SpeakNpcId = 200002,
          Subtitle = "Even the Demon King has lines she won't cross!",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172FD4"
        },
        [12019907] = {
          ContentTC = "小友先熄熄火氣。",
          DialogueId = 12019907,
          GUID = "1E172FFE",
          NextDialogue = 12019908,
          SpeakNpcId = 210012,
          Subtitle = "Easy now, young friend.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172FFE"
        },
        [12019908] = {
          ContentTC = "你們一個兩個怎麼都表現得如同我要取他性命？恰恰相反，我是想提供一個助他解脫大風九章束縛的機會。",
          DialogueId = 12019908,
          GUID = "1E173028",
          NextDialogue = 12019909,
          SpeakNpcId = 210012,
          Subtitle = "Why do you both act as though I intend to kill him? Quite the opposite — I mean to offer him a chance to break free of the Nine Chapters' shackles.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173028"
        },
        [12019909] = {
          ContentTC = "那你問過他的意見嗎？",
          DialogueId = 12019909,
          GUID = "1E173052",
          NextDialogue = 12019910,
          SpeakNpcId = 100001,
          Subtitle = "And did you ever ask him if he wanted that?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173052"
        },
        [12019910] = {
          ContentTC = "你的所作所為，已經危害到了蒼生社稷。還請速速收手。",
          DialogueId = 12019910,
          GUID = "1E17307C",
          NextDialogue = 12019911,
          SpeakNpcId = 210007,
          Subtitle = "Your actions have already endangered the people and the realm. I ask that you stand down.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E17307C"
        },
        [12019911] = {
          ContentTC = "呵呵……是我在危害蒼生社稷，還是這世道本身就分崩離析？大風九章引發的種種弊端，你便視而不見嗎？",
          DialogueId = 12019911,
          GUID = "1E1730A6",
          NextDialogue = 12019912,
          SpeakNpcId = 210012,
          Subtitle = "Hehe... tell me — am I the one endangering the realm, or is it the manners and morals of the age? Will you pretend not to see the cracks the Nine Chapters have wrought?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730A6"
        },
        [12019912] = {
          ContentTC = "若是能藉由你轉化為應天尉的原理，從中掌握對付玄色狴犴的後手，也助你重獲自由身。豈不是一樁美事？",
          DialogueId = 12019912,
          GUID = "1E1730D0",
          NextDialogue = 12019913,
          SpeakNpcId = 210012,
          Subtitle = "If I could decipher the means by which you became a Magistrate of Yingtian, I might forge a counter to the Sable Bi'an — and perhaps grant you the freedom you seek. Would that not be a fitting outcome for all?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730D0"
        },
        [12019913] = {
          ContentTC = "……此事非你所當慮。",
          DialogueId = 12019913,
          GUID = "1E1730FA",
          NextDialogue = 12019914,
          SpeakNpcId = 210007,
          Subtitle = "...This is not your burden to bear.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730FA"
        },
        [12019914] = {
          ContentTC = "他已經表達了不願意，那我就不能幫你。",
          DialogueId = 12019914,
          GUID = "1E173124",
          NextDialogue = 12019915,
          SpeakNpcId = 100001,
          Subtitle = "He's made himself clear. I won't help you.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173124"
        },
        [12019915] = {
          ContentTC = "又是無聊的仁義道德。嘖……本不想用這種手段。",
          DialogueId = 12019915,
          GUID = "1E17314E",
          SpeakNpcId = 210012,
          Subtitle = "Still clinging to your tiresome pretence of duty and honour, I see... Tsk. I had hoped it wouldn't come to this.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E17314E"
        },
        [12020001] = {
          ContentTC = "你……你乾什麼？！",
          DialogueId = 12020001,
          Duration = 2,
          GUID = "1E173F6A",
          SpeakNpcId = 200002,
          Subtitle = "Wh—What are you doing!?",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173F6A"
        },
        [12020002] = {
          ContentTC = "{nickname}，你不願對他出手，他卻是要對你亮出兵戈了。",
          DialogueId = 12020002,
          Duration = 3,
          GUID = "1E173F94",
          SpeakNpcId = 210012,
          Subtitle = ", you wouldn't raise your blade against him — but he was all too ready to strike at you.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173F94"
        },
        [12020003] = {
          ContentTC = "如何，那邊的應天尉？受害者已經出現了，你便只袖手旁觀嗎？這可不符合大風九章的規矩！",
          DialogueId = 12020003,
          Duration = 5,
          GUID = "1E173FBE",
          SpeakNpcId = 210012,
          Subtitle = "Well then, Magistrate of Yingtian — your victim stands before you. Will you stand by and do nothing? That is not what the Nine Chapters dictates.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173FBE"
        },
        [12020004] = {
          ContentTC = "……無恥！！明明你才是動手的那個！",
          DialogueId = 12020004,
          Duration = 3,
          GUID = "1E173FE8",
          SpeakNpcId = 200002,
          Subtitle = "...Shame on you!! You attacked my Little Minion first!",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173FE8"
        },
        [12020005] = {
          ContentTC = "哈哈哈……！只認古板的傷人事實，卻不論傷人動機和公理。應天尉，你所捍衛的便是這等死物嗎？",
          DialogueId = 12020005,
          Duration = 5,
          GUID = "1E174012",
          SpeakNpcId = 210012,
          Subtitle = "Hahaha...! Exactly. Punishing only those who have drawn blood, without regard for motive or for justice. Is this blind dogma what you fight to uphold?",
          VoiceName = "voice/$Locale$/story/1201/120200/1E174012"
        },
        [12020006] = {
          ContentTC = "……{nickname}，得罪了。這並非我願。",
          DialogueId = 12020006,
          Duration = 2,
          GUID = "1E17403C",
          SpeakNpcId = 210007,
          Subtitle = "...Forgive me, . This is not my will.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E17403C"
        },
        [12020101] = {
          ContentTC = "看好我的招式，仔細躲閃。",
          DialogueId = 12020101,
          Duration = 2,
          GUID = "1E174FD2",
          NextDialogue = 12020102,
          SpeakNpcId = 210007,
          Subtitle = "Watch my moves closely — and dodge carefully.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FD2"
        },
        [12020102] = {
          ContentTC = "我會盡力違抗大風九章的命令……別受傷了。",
          DialogueId = 12020102,
          Duration = 3,
          GUID = "1E174FFC",
          SpeakNpcId = 210007,
          Subtitle = "I'll resist the Nine Chapters' commands with all I have... Please — don't let yourself be hurt.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFC"
        },
        [12020103] = {
          ContentTC = "{nickname}，下一擊要來了.....當心。",
          DialogueId = 12020103,
          GUID = "1E174FFD",
          NextDialogue = 12020104,
          SpeakNpcId = 210007,
          Subtitle = ", the next strike... Be wary.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFD"
        },
        [12020104] = {
          ContentTC = "應天尉的攻勢也太猛了！大風九章的力量竟然這麼厲害.......",
          DialogueId = 12020104,
          GUID = "1E174FFF",
          NextDialogue = 12020105,
          SpeakNpcId = 200002,
          Subtitle = "The assault is too fierce! So this is the power of the Nine Chapters...",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFF"
        },
        [12020105] = {
          ContentTC = "怎麼辦，小僕從，你還好嗎?",
          DialogueId = 12020105,
          GUID = "1E174111",
          NextDialogue = 12020106,
          SpeakNpcId = 200002,
          Subtitle = "What do we do, Little Minion? Are you alright?!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174111"
        },
        [12020106] = {
          ContentTC = "放心，我還能應付。煜明，你沒事嗎？",
          DialogueId = 12020106,
          GUID = "1E174112",
          NextDialogue = 12020107,
          SpeakNpcId = 100001,
          Subtitle = "Don't worry, I can handle it. Yuming, are you okay?",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174112"
        },
        [12020107] = {
          ContentTC = "......你無需顧慮我。我會儘早結束此番鬧劇。",
          DialogueId = 12020107,
          GUID = "1E174113",
          SpeakNpcId = 210007,
          Subtitle = "Do not concern yourself with me. I shall put an end to this with all haste.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174113"
        },
        [12020108] = {
          ContentTC = "嗚，你們別再打了.....",
          DialogueId = 12020108,
          GUID = "1E174114",
          NextDialogue = 12020109,
          SpeakNpcId = 200002,
          Subtitle = "Stop it, please...",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174114"
        },
        [12020109] = {
          ContentTC = "兩個人明明好好的，結果不得不打起來，氣死我了！",
          DialogueId = 12020109,
          GUID = "1E174115",
          NextDialogue = 12020110,
          SpeakNpcId = 200002,
          Subtitle = "Why do you two have to fight like this? It's so frustrating!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174115"
        },
        [12020110] = {
          ContentTC = "都怪大風九章不懂事......不對，還是那個卑鄙的傢伙更壞!",
          DialogueId = 12020110,
          GUID = "1E174116",
          NextDialogue = 12020111,
          SpeakNpcId = 200002,
          Subtitle = "Stupid Nine Chapters... No, wait! That despicable guy is definitely worse!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174116"
        },
        [12020111] = {
          ContentTC = "哈哈，我可以將這句話當成是一種讚賞嗎?",
          DialogueId = 12020111,
          GUID = "1E174117",
          SpeakNpcId = 210012,
          Subtitle = "Heh. May I take that as a compliment?",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174117"
        },
        [12020201] = {
          ContentTC = "喂，你們這些鼠輩，怎麼聚首在這裡對付我師兄！！",
          DialogueId = 12020201,
          Duration = 2,
          GUID = "1E17603A",
          SpeakNpcId = 210021,
          Subtitle = "Hey! You lot - what the hell are you all doing here, ganging up on my shixiong!?",
          VoiceName = "voice/$Locale$/story/1201/120202/1E17603A"
        },
        [12020202] = {
          ContentTC = "頭兒，他要逃了……！",
          DialogueId = 12020202,
          Duration = 2,
          GUID = "1E176064",
          Subtitle = "Boss, he's trying to get away...!",
          VoiceName = "voice/$Locale$/story/1201/120202/1E176064"
        },
        [12020203] = {
          ContentTC = "都停手吧。",
          DialogueId = 12020203,
          Duration = 2,
          GUID = "1E17608E",
          SpeakNpcId = 210012,
          Subtitle = "Stand down.",
          VoiceName = "voice/$Locale$/story/1201/120202/1E17608E"
        },
        [12020204] = {
          ContentTC = "那不是前功盡棄了——",
          DialogueId = 12020204,
          Duration = 2,
          GUID = "1E1760B8",
          Subtitle = "If we let him—",
          VoiceName = "voice/$Locale$/story/1201/120202/1E1760B8"
        },
        [12020205] = {
          ContentTC = "無妨。",
          DialogueId = 12020205,
          Duration = 1,
          GUID = "1E1760E2",
          SpeakNpcId = 210012,
          Subtitle = "It's alright.",
          VoiceName = "voice/$Locale$/story/1201/120202/1E1760E2"
        },
        [12020301] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "唉……好不容易見到師兄一面，又被旁人打攪，讓他逃了去了。",
          DialogueId = 12020301,
          GUID = "1E1770A2",
          NextDialogue = 12020302,
          RelatedWikiId = {
            [1] = 203007,
            [2] = 203004,
            [3] = 203005
          },
          SpeakNpcId = 210021,
          Subtitle = "Finally got to see my shixiong again, only for you lot to ruin everything. Now he's slipped away once more.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770A2"
        },
        [12020302] = {
          ContentTC = "這桂花糕，在懷裡揣了半晌，揣得都冷了硬了。也不知道猴年馬月才能讓師兄吃上。",
          DialogueId = 12020302,
          GUID = "1E1770CC",
          NextDialogue = 12020303,
          SpeakNpcId = 210021,
          Subtitle = "This osmanthus cake... I've been carrying it around for so long, it's gone cold and hard. Who knows when I'll ever get to give it to him?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770CC"
        },
        [12020303] = {
          ContentTC = "原來你在找的人，就是煜明。",
          DialogueId = 12020303,
          GUID = "1E1770F6",
          NextDialogue = 12020304,
          SpeakNpcId = 100001,
          Subtitle = "So the one you've been looking for was Yuming.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770F6"
        },
        [12020304] = {
          ContentTC = "話說回來，你怎麼在這。我趕到之前，這裡都發生了什麼？",
          DialogueId = 12020304,
          GUID = "1E177120",
          NextDialogue = 12020305,
          SpeakNpcId = 210021,
          Subtitle = "Say... what are you doing here? What exactly happened here before I came?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177120"
        },
        [12020305] = {
          ContentTC = "（向刻舟講述之前發生的事情。）",
          DialogueId = 12020305,
          GUID = "1E17714A",
          IsBlack = 1,
          NextDialogue = 12020306,
          Subtitle = "(Fill him in)",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17714A"
        },
        [12020306] = {
          ContentTC = "這人怎麼如此過分！{nickname}，你被他算計，沒有受傷吧？！",
          DialogueId = 12020306,
          GUID = "1E177174",
          NextDialogue = 12020307,
          SpeakNpcId = 210021,
          Subtitle = "That bastard — he set you up, didn't he!? , are you hurt?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177174"
        },
        [12020307] = {
          ContentTC = "可惡，師兄受那重重規矩束縛，我行事可是無法無天……惹了我，橫豎也要讓他吃點教訓才是！",
          DialogueId = 12020307,
          GUID = "1E17719E",
          NextDialogue = 12020308,
          SpeakNpcId = 210021,
          Subtitle = "Damn it... my shixiong's tied down by those nonsense rules, but I'm not. Anyone who messes with him — I'll make sure they pay for it!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17719E"
        },
        [12020308] = {
          ContentTC = "白也看這伙人不爽很久了！我們聯手把這裡掀翻天吧！",
          DialogueId = 12020308,
          GUID = "1E1771C8",
          NextDialogue = 12020309,
          SpeakNpcId = 200002,
          Subtitle = "I've had it with those people too! Let's team up and turn this whole place upside down!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1771C8"
        },
        [12020309] = {
          ContentTC = "兩位，你們的交談我可都聽見了。我向你們賠禮道歉可好？",
          DialogueId = 12020309,
          GUID = "1E1771F2",
          NextDialogue = 12020310,
          SpeakNpcId = 210012,
          Subtitle = "Alright, alright — no need for all this fuss. I heard every word, clear as day. Consider this my most humble apology.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1771F2"
        },
        [12020310] = {
          ContentTC = "我勸你少說些話，我的氣可還沒消。",
          DialogueId = 12020310,
          GUID = "1E17721C",
          NextDialogue = 12020311,
          SpeakNpcId = 100001,
          Subtitle = "You'd better keep your mouth shut. I'm still mad at you.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17721C"
        },
        [12020311] = {
          ContentTC = "現在不對你出手，只是因為我不想變成和你一樣的渣滓。",
          DialogueId = 12020311,
          GUID = "1E177246",
          NextDialogue = 12020312,
          SpeakNpcId = 100001,
          Subtitle = "The only reason I'm not coming after you right now is because I refuse to stoop to your level.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177246"
        },
        [12020312] = {
          ContentTC = "好、好，小友寬宏大量。",
          DialogueId = 12020312,
          GUID = "1E177270",
          NextDialogue = 12020313,
          SpeakNpcId = 210012,
          Subtitle = "Fair enough. Such magnanimity is admirable, young friend.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177270"
        },
        [12020313] = {
          ContentTC = "小友的義氣著實讓人動容。虯某心服口服，甘願擔下任務失敗的責任，也要賣小友一個面子，放歸獵物。之後止掌櫃那邊，我會去交代。",
          DialogueId = 12020313,
          GUID = "1E17729A",
          NextDialogue = 12020314,
          SpeakNpcId = 210012,
          Subtitle = "And your loyalty... truly stirring. You have my respect. I'll gladly shoulder the blame for this failure: I'll let the \"prey\" go out of deference to you. As for Proprietress Zhiliu, I'll explain to her myself.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17729A"
        },
        [12020314] = {
          ContentTC = "這真是止流掌櫃的意思嗎？我不信你說的話。還有，我不想再聽到「獵物」這個詞。",
          DialogueId = 12020314,
          GUID = "1E1772C4",
          NextDialogue = 12020315,
          SpeakNpcId = 100001,
          Subtitle = "Are you saying this is all Proprietress Zhiliu's idea? I don't buy it. And another thing — stop calling him the \"prey.\"",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1772C4"
        },
        [12020315] = {
          ContentTC = "哈哈……正如我先前所說，止掌櫃自有她的考慮。",
          DialogueId = 12020315,
          GUID = "1E1772EE",
          NextDialogue = 12020316,
          SpeakNpcId = 210012,
          Subtitle = "Haha... as I told you before, the Proprietress has her own designs.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1772EE"
        },
        [12020316] = {
          ContentTC = "要不是你們這伙人橫插一杠，我和師兄早就重新聚首了！黑瞎子，你欠我的如何賠？",
          DialogueId = 12020316,
          GUID = "1E177318",
          NextDialogue = 12020317,
          SpeakNpcId = 210021,
          Subtitle = "If it weren't for you lot butting in, I'd have had a proper reunion with my shixiong! Old Fox — how exactly are you planning to make this right?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177318"
        },
        [12020317] = {
          ContentTC = "哦？依我看，那應天尉分明是刻意躲著你。若是他留下，你倆二人聯手，在場各位又有誰能抵擋？",
          DialogueId = 12020317,
          GUID = "1E177342",
          NextDialogue = 12020318,
          SpeakNpcId = 210012,
          Subtitle = "Oh? From what I saw, that Magistrate of Yingtian is avoiding you quite deliberately. If he'd stayed behind, and the two of you joined forces — who here could possibly stand in your way?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177342"
        },
        [12020318] = {
          ContentTC = "住口！要你在這邊囉嗦！",
          DialogueId = 12020318,
          GUID = "1E17736C",
          NextDialogue = 12020319,
          SpeakNpcId = 210021,
          Subtitle = "Shut it! Another word and I'll shut it for you myself!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17736C"
        },
        [12020319] = {
          ContentTC = "哈哈哈！",
          DialogueId = 12020319,
          GUID = "1E177396",
          NextDialogue = 12020320,
          SpeakNpcId = 210012,
          Subtitle = "Hahahaha!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177396"
        },
        [12020320] = {
          ContentTC = "我還有要事處理，便先行告退。",
          DialogueId = 12020320,
          GUID = "1E1773C0",
          NextDialogue = 12020321,
          SpeakNpcId = 210012,
          Subtitle = "But enough chatter. I have other matters to attend to. I'll take my leave for now.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1773C0"
        },
        [12020321] = {
          ContentTC = "這位朋友，我且提醒你一句。你師兄往那個方向撤離，再不去追怕是又要來不及了。",
          DialogueId = 12020321,
          GUID = "1E1773EA",
          NextDialogue = 12020322,
          SpeakNpcId = 210012,
          Subtitle = "A small piece of advice — Yuming slipped off that way. If you don't hurry, you'll lose him yet again.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1773EA"
        },
        [12020322] = {
          ContentTC = "小友，你也聽我一句勸告。不是所有人行事都如我這般坦蕩。知人知面，未必知心。",
          DialogueId = 12020322,
          GUID = "1E177414",
          SpeakNpcId = 210012,
          Subtitle = "And one last word for you, young friend — not everyone is as candid as I am. You may know a man's face... but never assume you know his heart.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177414"
        },
        [12020401] = {
          ContentTC = "他的自戀狂發言又增加了！",
          DialogueId = 12020401,
          Duration = 2,
          GUID = "1E17810A",
          NextDialogue = 12020402,
          SpeakNpcId = 200002,
          Subtitle = "There he goes again — so full of himself!",
          VoiceName = "voice/$Locale$/story/1201/120204/1E17810A"
        },
        [12020402] = {
          ContentTC = "最後那句話到底是什麼意思哇？神神秘秘的……",
          DialogueId = 12020402,
          Duration = 3,
          GUID = "1E178134",
          SpeakNpcId = 200002,
          Subtitle = "And what was that last thing he said supposed to mean, anyway? Talking in riddles, that guy...",
          VoiceName = "voice/$Locale$/story/1201/120204/1E178134"
        },
        [12020501] = {
          Camera = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "唉……",
          DialogueId = 12020501,
          FacialId = {
            [1] = "210021:Unhappy01"
          },
          FinalCamera = "-39.296875,19.130371,149.838379,0.000004,-2.785276,-161.556458,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E179172",
          LookAt = {
            [1] = "100001:n(210021)",
            [2] = "210021:n(100001)"
          },
          NextDialogue = 12020502,
          SpeakNpcId = 210021,
          Subtitle = "...",
          TalkActionId = {
            [1] = "210021:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120205/1E179172"
        },
        [12020502] = {
          ContentTC = "{nickname}，你是不是和師兄挺熟的？",
          DialogueId = 12020502,
          FacialId = {
            [1] = "210021:Think01"
          },
          GUID = "1E17919C",
          NextDialogue = 12020503,
          SpeakNpcId = 210021,
          Subtitle = ", you seem to know my shixiong pretty well.",
          TalkActionId = {
            [1] = "210021:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E17919C"
        },
        [12020503] = {
          ContentTC = "師兄成為應天尉是因為一場意外變故。但我能感覺到，他並不開心……",
          DialogueId = 12020503,
          FacialId = {
            [1] = "210021:Angry01"
          },
          GUID = "1E1791C6",
          NextDialogue = 12020504,
          SpeakNpcId = 210021,
          Subtitle = "I don't know if you've heard this — he became a Magistrate of Yingtian because of... an accident, a twist of fate. But I can tell — he's not at peace with it.",
          TalkActionId = {
            [1] = "210021:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E1791C6"
        },
        [12020504] = {
          Camera = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你下次要是見到他，幫我帶一句話，就說當年那件事不怪他，山外山的大家都希望他回來。",
          DialogueId = 12020504,
          GUID = "1E1791F0",
          NextDialogue = 12020505,
          SpeakNpcId = 210021,
          Subtitle = "When you meet him again, tell him something for me, will you? Tell him... what happened back then wasn't his fault. Everyone from the Outer Peaks misses him and hopes he'll come back home.",
          VoiceName = "voice/$Locale$/story/1201/120205/1E1791F0"
        },
        [12020505] = {
          Camera = "-286.9375,-213.182617,178.568115,0.000013,-9.985319,62.043591,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "當年？發生了什麼事情？",
          DialogueId = 12020505,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E17921A",
          NextDialogue = 12020506,
          SpeakNpcId = 100001,
          Subtitle = "What happened back then?",
          TalkActionId = {
            [1] = "210021:Talk02_End",
            [2] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E17921A"
        },
        [12020506] = {
          Camera = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這事挺麻煩的，三言兩語說不清楚。我還得趕著去追師兄，下次再和你講吧。",
          DialogueId = 12020506,
          FacialId = {
            [1] = "210021:Uninterested01"
          },
          GUID = "1E179244",
          NextDialogue = 12020507,
          SpeakNpcId = 210021,
          Subtitle = "Uh... it's a long story — too much to explain here. I've got to go after him. I'll tell you another time.",
          TalkActionId = {
            [1] = "210021:Talk01_Start",
            [2] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E179244"
        },
        [12020507] = {
          Camera = "254.949219,-102.718262,275.353027,0.000008,-18.585285,170.644135,30.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "{nickname}，你說，人活在這世上，為何不能隨性所動，興致來了便做自己想做的。偏偏要受這麼多約束呢？",
          DialogueId = 12020507,
          FacialId = {
            [1] = "210021:Unhappy01"
          },
          FinalCamera = "465.136719,-137.344727,314.913086,0.000008,-18.585264,170.644104,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E17926E",
          NextDialogue = 12020508,
          SpeakNpcId = 210021,
          Subtitle = "Tell me,  — why is it so hard for people just to follow their hearts? Why is it that every time we want to act on a whim, we're tied down by all sorts of rules?",
          TalkActionId = {
            [1] = "210021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120205/1E17926E"
        },
        [12020508] = {
          Camera = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我得走了。別忘了我們的約定啊！下次見面，可得把盞言歡，暢談至盡興才行！",
          DialogueId = 12020508,
          FacialId = {
            [1] = "210021:Smile01"
          },
          GUID = "1E179298",
          SpeakNpcId = 210021,
          Subtitle = "I have to go. But don't you forget — next time we meet, we'll drink until dawn and talk till we drop!",
          TalkActionId = {
            [1] = "210021:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E179298"
        },
        [12020601] = {
          ContentTC = "感覺出來逛了好久，不知道止流那邊怎麼樣了……",
          DialogueId = 12020601,
          Duration = 3,
          GUID = "1E17A1DA",
          NextDialogue = 12020602,
          SpeakNpcId = 200002,
          Subtitle = "Feels like we've been wandering around forever... I wonder how Proprietress Zhiliu is doing.",
          VoiceName = "voice/$Locale$/story/1201/120206/1E17A1DA"
        },
        [12020602] = {
          ContentTC = "小僕從，我們回百年春看看吧！",
          DialogueId = 12020602,
          Duration = 2,
          GUID = "1E17A204",
          SpeakNpcId = 200002,
          Subtitle = "C'mon, Little Minion! Let's head back to EverSpring and check in!",
          VoiceName = "voice/$Locale$/story/1201/120206/1E17A204"
        },
        [12020701] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這個動靜……發生什麼事情了嗎？",
          DialogueId = 12020701,
          GUID = "1E17B242",
          NextDialogue = 12020702,
          SpeakNpcId = 100001,
          Subtitle = "What was that noise...? What's going on?",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B242"
        },
        [12020702] = {
          ContentTC = "看來，是大當家在燭陰祭壇的布置已經完成了。",
          DialogueId = 12020702,
          GUID = "1E17B26C",
          NextDialogue = 12020703,
          RelatedWikiId = {
            [1] = 408015,
            [2] = 303011
          },
          SpeakNpcId = 210022,
          Subtitle = "It seems that Miss Zhiliu has completed her preparations at the Zhuyin Altar.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B26C"
        },
        [12020703] = {
          ContentTC = "她曾囑咐過，若您來尋她，讓您在大廳靜候。等到事成之後，她會回來見您。",
          DialogueId = 12020703,
          GUID = "1E17B296",
          NextDialogue = 12020704,
          SpeakNpcId = 210022,
          Subtitle = "She left word — if you came looking for her, you're to wait here in the main hall. Once the ritual is complete, she'll return to meet you.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B296"
        },
        [12020704] = {
          ContentTC = "等等，不需要我們去幫忙嗎？！",
          DialogueId = 12020704,
          GUID = "1E17B2C0",
          NextDialogue = 12020705,
          SpeakNpcId = 200002,
          Subtitle = "Wait, what!? We're just supposed to sit here and do nothing!?",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B2C0"
        },
        [12020705] = {
          ContentTC = "封印燭陰之行險阻重重，你們若是前去，可能會受傷……",
          DialogueId = 12020705,
          GUID = "1E17B2EA",
          NextDialogue = 12020706,
          SpeakNpcId = 210022,
          Subtitle = "Sealing Zhuyin is no simple task. If you go, you could be seriously hurt...",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B2EA"
        },
        [12020706] = {
          ContentTC = "吼——",
          DialogueId = 12020706,
          GUID = "1E17B314",
          NextDialogue = 12020707,
          Subtitle = "Roaaaar—!",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B314"
        },
        [12020707] = {
          ContentTC = "那邊的情況聽起來不太妙。讓我們去吧，多一人就是多一份助力。",
          DialogueId = 12020707,
          GUID = "1E17B33E",
          NextDialogue = 12020708,
          SpeakNpcId = 100001,
          Subtitle = "That doesn't sound good. We should go — every extra hand could make the difference.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B33E"
        },
        [12020708] = {
          ContentTC = "但，大當家的囑咐……",
          DialogueId = 12020708,
          GUID = "1E17B368",
          NextDialogue = 12020709,
          SpeakNpcId = 210022,
          Subtitle = "But... Miss Zhiliu said—",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B368"
        },
        [12020709] = {
          ContentTC = "哎呀，都到這種時候了，你還在猶豫什麼！",
          DialogueId = 12020709,
          GUID = "1E17B392",
          NextDialogue = 12020710,
          SpeakNpcId = 200002,
          Subtitle = "Oh, come on! In a situation this critical, you can't seriously be fussing over your boss's orders!",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B392"
        },
        [12020710] = {
          ContentTC = "……我明白了。您可以去塵漠石海最高處的位置，那裡通往燭陰祭壇的臨時道路已經搭建完畢。",
          DialogueId = 12020710,
          GUID = "1E17B3BC",
          NextDialogue = 12020711,
          SpeakNpcId = 210022,
          Subtitle = "...Very well. Head to the highest point of the Gritblight Expanse. A temporary path to the Zhuyin Altar has already been prepared.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B3BC"
        },
        [12020711] = {
          ContentTC = "白嗅到了征服惡龍的決戰氣息……等等，怎麼聽起來不像是魔王該乾的事情？！",
          DialogueId = 12020711,
          GUID = "1E17B3E6",
          NextDialogue = 12020712,
          SpeakNpcId = 200002,
          Subtitle = "I can already smell the final showdown with an evil loong— wait, this doesn't sound like a quest for the Demon King...",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B3E6"
        },
        [12020712] = {
          ContentTC = "……我們趕快過去吧。",
          DialogueId = 12020712,
          GUID = "1E17B410",
          SpeakNpcId = 100001,
          Subtitle = "...Let's get going.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B410"
        },
        [12020901] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "呼……千鈞一發之際，險險成功了。",
          DialogueId = 12020901,
          GUID = "1E17D312",
          NextDialogue = 12020902,
          RelatedWikiId = {
            [1] = 408015,
            [2] = 303011
          },
          SpeakNpcId = 210005,
          SpeakNpcName = "UI_Npc_Name_Goodshangren",
          Subtitle = "Whew... that was way too close.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D312"
        },
        [12020902] = {
          ContentTC = "還不能鬆懈，我能感受到上方的封印尚不穩固。",
          DialogueId = 12020902,
          GUID = "1E17D33C",
          NextDialogue = 12020903,
          SpeakNpcId = 210004,
          Subtitle = "Do not let your guard down. The upper seal is still unstable — I can feel it shifting.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D33C"
        },
        [12020903] = {
          ContentTC = "我要維持此處陣眼，暫時無法抽身。你們誰能上去檢查一下嗎？",
          DialogueId = 12020903,
          GUID = "1E17D366",
          NextDialogue = 12020904,
          SpeakNpcId = 210004,
          Subtitle = "I must maintain the formation here — I cannot leave my post. Can any of you go up and inspect the situation?",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D366"
        },
        [12020904] = {
          ContentTC = "止流掌櫃，我去吧。",
          DialogueId = 12020904,
          GUID = "1E17D390",
          NextDialogue = 12020905,
          SpeakNpcId = 100001,
          Subtitle = "Leave it to me, Proprietress Zhiliu.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D390"
        },
        [12020905] = {
          ContentTC = "……{nickname}，怎麼是你？",
          DialogueId = 12020905,
          GUID = "1E17D3BA",
          NextDialogue = 12020906,
          SpeakNpcId = 210004,
          Subtitle = "...? What are you doing here?",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D3BA"
        },
        [12020906] = {
          ContentTC = "你們的工作已經完成了。我分明囑咐過望春，讓你們在商會等候我歸來即可。",
          DialogueId = 12020906,
          GUID = "1E17D3E4",
          NextDialogue = 12020907,
          SpeakNpcId = 210004,
          Subtitle = "Your commission was already completed. I explicitly told Wangchun to have you wait in the chamber until I returned.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D3E4"
        },
        [12020907] = {
          ContentTC = "這裡的動靜太大，我放不下心來。不如來看看能做些什麼。",
          DialogueId = 12020907,
          GUID = "1E17D40E",
          NextDialogue = 12020908,
          SpeakNpcId = 100001,
          Subtitle = "Things seem heated in here — I couldn't just sit and do nothing. I had to see if there was anything I could help with.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D40E"
        },
        [12020908] = {
          ContentTC = "這是我們狩月人傾情提供的售後服務，包老板滿意！",
          DialogueId = 12020908,
          GUID = "1E17D438",
          NextDialogue = 12020909,
          SpeakNpcId = 200002,
          Subtitle = "Consider it premium after-sales service — Phoxhunter style! And we're good!",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D438"
        },
        [12020909] = {
          ContentTC = "您就放一百個心吧，止掌櫃。{nickname}身手可靈活了，尤其擅長旋轉跳躍，多高的障礙都不在話下！",
          DialogueId = 12020909,
          GUID = "1E17D462",
          NextDialogue = 12020910,
          SpeakNpcId = 200002,
          Subtitle = "You can count on us, Proprietress Zhiliu!  is nimble as can be — spins, flips, leaps — no obstacle too high for my Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D462"
        },
        [12020910] = {
          ContentTC = "若是你們堅持……",
          DialogueId = 12020910,
          GUID = "1E17D48C",
          NextDialogue = 12020911,
          SpeakNpcId = 210004,
          Subtitle = "...If you insist.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D48C"
        },
        [12020911] = {
          ContentTC = "{nickname}，拿住這枚銅錢。將它放至燭陰的額首處，剩下的我會操作。",
          DialogueId = 12020911,
          GUID = "1E17D4B6",
          NextDialogue = 12020912,
          SpeakNpcId = 210004,
          Subtitle = ", take this copper coin. Place it on Zhuyin's forehead — I'll handle the rest.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D4B6"
        },
        [12020912] = {
          ContentTC = "當心，別受傷了。",
          DialogueId = 12020912,
          GUID = "1E17D4E0",
          SpeakNpcId = 210004,
          Subtitle = "Be careful. Don't let yourself get hurt.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D4E0"
        },
        [12020913] = {
          ContentTC = "杜立，先帶著傷者下去吧。",
          DialogueId = 12020913,
          GUID = "1E13468F",
          SpeakNpcId = 210004,
          Subtitle = "Du Li, take the wounded and leave first.",
          VoiceName = "voice/$Locale$/story/1201/120138/1E13468F"
        },
        [12020914] = {
          ContentTC = "是，大當家！",
          DialogueId = 12020914,
          GUID = "1E134691",
          SpeakNpcId = 210004,
          SpeakNpcName = "UI_CMNpc_Name_Duli",
          Subtitle = "Yes, Miss Zhiliu!",
          VoiceName = "voice/$Locale$/story/1201/120138/1E134691"
        },
        [12021001] = {
          ContentTC = "魂兮遊離，北狩荒穢……彼我燭陰，罹殃千歲……",
          DialogueId = 12021001,
          Duration = 2,
          GUID = "1E17E37A",
          NextDialogue = 12021002,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "O soul adrift, to the north thou stray; to hunt the blight where shadows lay. Bound by Zhuyin, thee and I; bear the doom till time should die...",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E37A"
        },
        [12021002] = {
          ContentTC = "（……！又出現了，先前在塵漠石海聽到的那個聲音。）",
          DialogueId = 12021002,
          Duration = 2,
          GUID = "1E17E3A4",
          NextDialogue = 12021003,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...! That voice again. The same one I heard back in the Gritblight Expanse.)",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E3A4"
        },
        [12021003] = {
          ContentTC = "（果然，這就是燭陰的囈語嗎？）",
          DialogueId = 12021003,
          Duration = 2,
          GUID = "1E17E3CE",
          NextDialogue = 12021004,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(So it really was the whispers of Zhuyin...)",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E3CE"
        },
        [12021004] = {
          ContentTC = "怎麼了，{nickname}？",
          DialogueId = 12021004,
          Duration = 2,
          GUID = "1E17E3F8",
          NextDialogue = 12021005,
          SpeakNpcId = 210004,
          Subtitle = "What is it, ?",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E3F8"
        },
        [12021005] = {
          ContentTC = "不，沒什麼……",
          DialogueId = 12021005,
          Duration = 2,
          GUID = "1E17E422",
          SpeakNpcId = 100001,
          Subtitle = "...Nothing.",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E422"
        },
        [12021201] = {
          ContentTC = "魂魄佚散，疇昔傾頹……荒忽焉極，循時索歸……",
          DialogueId = 12021201,
          Duration = 2,
          GUID = "1E18044A",
          NextDialogue = 12021202,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "O scattered soul, the past doth wane; foundations crumble, lost in bane. Through realms forlorn, thine end awaits; Yet Time shall guide thee back to Fate.",
          VoiceName = "voice/$Locale$/story/1201/120212/1E18044A"
        },
        [12021202] = {
          ContentTC = "（燭陰的聲音，越來越清晰了……）",
          DialogueId = 12021202,
          Duration = 2,
          GUID = "1E180474",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(That voice... it's getting clearer.)",
          VoiceName = "voice/$Locale$/story/1201/120212/1E180474"
        },
        [12021301] = {
          ContentTC = "……汝乃何人？",
          DialogueId = 12021301,
          Duration = 2,
          GUID = "1E1814B2",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Who art thou?",
          VoiceName = "voice/$Locale$/story/1201/120213/1E1814B2"
        },
        [12021302] = {
          ContentTC = "汝亦是來加害於吾乎？",
          DialogueId = 12021302,
          Duration = 2,
          GUID = "1E1814DC",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Dost thou, too, come to bring me harm...?",
          VoiceName = "voice/$Locale$/story/1201/120213/1E1814DC"
        },
        [12021303] = {
          ContentTC = "不好，它發狂了！小僕從！！！",
          DialogueId = 12021303,
          Duration = 2,
          GUID = "1E181506",
          SpeakNpcId = 200002,
          Subtitle = "It's going berserk! Little Minion, watch out!!",
          VoiceName = "voice/$Locale$/story/1201/120213/1E181506"
        },
        [12021304] = {
          ContentTC = "聽得到我的聲音嗎？你是不是想對我們說什麼？",
          DialogueId = 12021304,
          Duration = 4,
          GUID = "1E181530",
          SpeakNpcId = 100001,
          Subtitle = "Can you hear me? You were trying to say something to us, weren't you?",
          VoiceName = "voice/$Locale$/story/1201/120213/1E181530"
        },
        [12021305] = {
          ContentTC = "吼————",
          DialogueId = 12021305,
          Duration = 2,
          GUID = "1E18155A",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Rrrrroaaaarrrrr—!",
          VoiceName = "voice/$Locale$/story/1201/120213/1E18155A"
        },
        [12021306] = {
          ContentTC = "燭陰已力竭了。",
          DialogueId = 12021306,
          Duration = 2,
          GUID = "1E181584",
          SpeakNpcId = 210004,
          Subtitle = "Zhuyin is spent — its power's almost gone.",
          VoiceName = "voice/$Locale$/story/1201/120213/1E181584"
        },
        [12021307] = {
          ContentTC = "最後一擊，要拜托你了，{nickname}。",
          DialogueId = 12021307,
          Duration = 4,
          GUID = "1E1815AE",
          SpeakNpcId = 210004,
          Subtitle = "We will be counting on you to deliver the final strike, .",
          VoiceName = "voice/$Locale$/story/1201/120213/1E1815AE"
        },
        [12022001] = {
          ContentTC = "——至此，大風九章已成！",
          DialogueId = 12022001,
          GUID = "1E18878A",
          NextDialogue = 12022002,
          RelatedWikiId = {
            [1] = 304003,
            [2] = 303008,
            [3] = 303011
          },
          SnapShot = "MEMORY",
          Subtitle = "Henceforth, the Nine Chapters of Dafeng stand complete!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E18878A"
        },
        [12022002] = {
          ContentTC = "華胥黎庶，自茲以往，將永離戰亂之苦，無受紛爭之擾！",
          DialogueId = 12022002,
          GUID = "1E1887B4",
          NextDialogue = 12022003,
          SnapShot = "MEMORY",
          Subtitle = "The folk of Huaxu shall dwell in peace — free from war's cruel hand and spared the scourge of strife!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1887B4"
        },
        [12022003] = {
          ContentTC = "太皓，執理。燭陰，執心。",
          DialogueId = 12022003,
          GUID = "1E1887DE",
          NextDialogue = 12022004,
          SnapShot = "MEMORY",
          Subtitle = "Taihao shall govern the law. Zhuyin shall govern the mind.",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1887DE"
        },
        [12022004] = {
          ContentTC = "二位尊神，將共禦大風九章，庇佑蒼生，護萬世安泰——",
          DialogueId = 12022004,
          GUID = "1E188808",
          NextDialogue = 12022005,
          SnapShot = "MEMORY",
          Subtitle = "Two revered deities, bound by covenant — together, ye shall watch o'er the Nine Chapters of Dafeng, safeguard the myriad beings, and shield the ages to come.",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188808"
        },
        [12022005] = {
          ContentTC = "心為一切混亂之肇始！",
          DialogueId = 12022005,
          GUID = "1E188832",
          NextDialogue = 12022006,
          SnapShot = "MEMORY",
          Subtitle = "The mind is the root of all chaos!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188832"
        },
        [12022006] = {
          ContentTC = "我泱泱華胥，卷入如今兵戈之亂，全因人心混沌所起！",
          DialogueId = 12022006,
          GUID = "1E18885C",
          NextDialogue = 12022007,
          SnapShot = "MEMORY",
          Subtitle = "'Tis the turmoil within men's hearts that hath plunged Huaxu into unending war!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E18885C"
        },
        [12022007] = {
          ContentTC = "今日，燭陰必須受封印。",
          DialogueId = 12022007,
          GUID = "1E188886",
          NextDialogue = 12022008,
          SnapShot = "MEMORY",
          Subtitle = "Upon this day, shall Zhuyin be sealed.",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188886"
        },
        [12022008] = {
          ContentTC = "唯有不受乾擾之理，方有資格執掌統禦之法！",
          DialogueId = 12022008,
          GUID = "1E1888B0",
          NextDialogue = 12022009,
          SnapShot = "MEMORY",
          Subtitle = "Only a law unswayed by mortal sentiment is fit to hold dominion o'er the world!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1888B0"
        },
        [12022009] = {
          ContentTC = "此舉不可！倘若心、理失衡， 後患無窮盡也！",
          DialogueId = 12022009,
          GUID = "1E1888DA",
          NextDialogue = 12022010,
          SnapShot = "MEMORY",
          Subtitle = "Nay! Ye must not! When mind and law stand sundered, ruin shall know no end!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1888DA"
        },
        [12022010] = {
          ContentTC = "退下！休要壞了正事！",
          DialogueId = 12022010,
          GUID = "1E188904",
          NextDialogue = 12022011,
          SnapShot = "MEMORY",
          Subtitle = "Back off! This rite must not be marred!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188904"
        },
        [12022011] = {
          ContentTC = "自爾後數百載，玄色狴犴生，災禍暗起……今日之果，皆為當日之因呐！",
          DialogueId = 12022011,
          GUID = "1E18892E",
          NextDialogue = 12022012,
          SnapShot = "MEMORY",
          Subtitle = "For centuries thereafter, the Sable Bi'an arose — calamity blooming in the shadows... The ruin we see today was sown in that distant hour!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E18892E"
        },
        [12022012] = {
          ContentTC = "夫燭陰者，由心而生。人心不滅，燭陰如何能滅？",
          DialogueId = 12022012,
          GUID = "1E188958",
          NextDialogue = 12022013,
          SnapShot = "MEMORY",
          Subtitle = "Zhuyin springs from the depths of the mortal heart. So long as human desire endures, how can Zhuyin be truly undone?",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188958"
        },
        [12022013] = {
          ContentTC = "以秘術暫封之，如揚湯止沸。俟燭陰掙脫封印，附骨之疽，必釀大患！",
          DialogueId = 12022013,
          GUID = "1E188982",
          NextDialogue = 12022014,
          SnapShot = "MEMORY",
          Subtitle = "To seal it by secret arts is but to ladle water upon a boiling pot — once spent, it shall rise anew, a hidden canker in the bone, sure to fester into grievous affliction!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188982"
        },
        [12022014] = {
          ContentTC = "……孰離合兮可為，蹇誰留兮他鄉？",
          DialogueId = 12022014,
          GUID = "1E1889AC",
          NextDialogue = 12022015,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_CMName_Name_ZhuYing",
          Subtitle = "...Who might decree the weaving of fates, of sunderings and partings? Who roves forlorn, tarrying in lands beyond all chartings?",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1889AC"
        },
        [12022015] = {
          ContentTC = "燭陰，剛剛那些是你的記憶嗎？！你究竟想告訴我什麼？",
          DialogueId = 12022015,
          GUID = "1E1889D6",
          NextDialogue = 12022016,
          SpeakNpcId = 100001,
          Subtitle = "Zhuyin! Were those your memories!? What is it you're trying to tell me!?",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1889D6"
        },
        [12022016] = {
          ContentTC = "萬事已矣，不可復挽矣。天下將趨不可避之大禍……",
          DialogueId = 12022016,
          GUID = "1E188A00",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_CMName_Name_ZhuYing",
          Subtitle = "All is done... beyond recall... A doom shall befall the world, inescapable, unbound...",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188A00"
        },
        [12022101] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "小僕從，你沒事吧？",
          DialogueId = 12022101,
          GUID = "1E1897F2",
          NextDialogue = 12022102,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion! You alright?",
          VoiceName = "voice/$Locale$/story/1201/120221/1E1897F2"
        },
        [12022102] = {
          ContentTC = "沒事。我好像看到了一些……畫面。",
          DialogueId = 12022102,
          GUID = "1E18981C",
          NextDialogue = 12022103,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine... I think I just saw... something. Like... memory fragments.",
          VoiceName = "voice/$Locale$/story/1201/120221/1E18981C"
        },
        [12022103] = {
          ContentTC = "諸位，趁它被束縛住，趕緊發動攻擊！能否拿下便在此一舉了！",
          DialogueId = 12022103,
          GUID = "1E189846",
          SpeakNpcId = 210004,
          Subtitle = "Everyone — strike now, while it's still restrained! This is our only chance to bring it down!",
          VoiceName = "voice/$Locale$/story/1201/120221/1E189846"
        },
        [12022201] = {
          ContentTC = "等等！",
          DialogueId = 12022201,
          GUID = "1E18A85A",
          NextDialogue = 12022202,
          SpeakNpcId = 100001,
          Subtitle = "Wait!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A85A"
        },
        [12022202] = {
          ContentTC = "就在剛剛，我好像從燭陰的記憶中瞥見了一些大風九章的內情……或許會和燭陰之災有關！",
          DialogueId = 12022202,
          GUID = "1E18A884",
          NextDialogue = 12022203,
          SpeakNpcId = 100001,
          Subtitle = "I saw something just now — in Zhuyin's memories. Fragments of the truth about the Nine Chapters... It might have something to do with the Scourge of Zhuyin!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A884"
        },
        [12022203] = {
          ContentTC = "我們也許可以和它談談！如果能平息它的憤怒，或許我們不必與它為敵！",
          DialogueId = 12022203,
          GUID = "1E18A8AE",
          NextDialogue = 12022204,
          SpeakNpcId = 100001,
          Subtitle = "Maybe we can talk to it! If we can calm its wrath, we might not have to fight!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A8AE"
        },
        [12022204] = {
          ContentTC = "不必了。",
          DialogueId = 12022204,
          GUID = "1E18A8D8",
          NextDialogue = 12022205,
          SpeakNpcId = 210004,
          Subtitle = "That won't be necessary.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A8D8"
        },
        [12022205] = {
          ContentTC = "看你的反應……你早就知道？",
          DialogueId = 12022205,
          GUID = "1E18A902",
          NextDialogue = 12022206,
          SpeakNpcId = 100001,
          Subtitle = "Zhiliu... you knew this all along, didn't you?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A902"
        },
        [12022206] = {
          ContentTC = "你窺見的或許為真……可那又怎樣？",
          DialogueId = 12022206,
          GUID = "1E18A92C",
          NextDialogue = 12022207,
          SpeakNpcId = 210004,
          Subtitle = "Perhaps what you saw is true. But what of it?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A92C"
        },
        [12022207] = {
          ContentTC = "<H>白龍神君</>的時代，該結束了。而我，將執起祂的權柄。",
          DialogueId = 12022207,
          GUID = "1E18A956",
          NextDialogue = 12022208,
          SpeakNpcId = 210004,
          Subtitle = "The age of the Lord Argent Sovereign ends here. And I shall claim Their mantle.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A956"
        },
        [12022208] = {
          ContentTC = "什麼……",
          DialogueId = 12022208,
          GUID = "1E18A980",
          SpeakNpcId = 100001,
          Subtitle = "What...?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A980"
        },
        [12022209] = {
          ContentTC = "真是遺憾……若不是事急從權，也不必對你用這種手段。",
          DialogueId = 12022209,
          GUID = "1E18A9AA",
          NextDialogue = 12022210,
          SpeakNpcId = 210004,
          Subtitle = "A pity... Were the hour less dire, I would not resort to such measures.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A9AA"
        },
        [12022210] = {
          ContentTC = "……止流！！放我出去！",
          DialogueId = 12022210,
          GUID = "1E18A9D4",
          NextDialogue = 12022211,
          SpeakNpcId = 100001,
          Subtitle = "...Zhiliu! Let me out!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A9D4"
        },
        [12022211] = {
          ContentTC = "秦虯先前對我說，你一片赤子之心，怕會影響到計劃的實行。",
          DialogueId = 12022211,
          GUID = "1E18A9FE",
          NextDialogue = 12022212,
          SpeakNpcId = 210004,
          Subtitle = "Qin Qiu once warned me that your heart is too pure. It would have gotten in the way.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A9FE"
        },
        [12022212] = {
          ContentTC = "我特意把你支走，未想到你還是來了。",
          DialogueId = 12022212,
          GUID = "1E18AA28",
          NextDialogue = 12022213,
          SpeakNpcId = 210004,
          Subtitle = "So I sent you away... yet still you returned.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AA28"
        },
        [12022213] = {
          ContentTC = "在冰湖城和你相處的那段日子，確實是難得的閑暇時光，如一夢黃粱。",
          DialogueId = 12022213,
          GUID = "1E18AA52",
          NextDialogue = 12022214,
          SpeakNpcId = 210004,
          Subtitle = "Those days in Icelake with you... they were a rare respite, as fleeting as a dream.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AA52"
        },
        [12022214] = {
          ContentTC = "倘若你沒有恰好出現在這裡，就好了。我們還能如往常一樣談天說笑。",
          DialogueId = 12022214,
          GUID = "1E18AA7C",
          NextDialogue = 12022215,
          SpeakNpcId = 210004,
          Subtitle = "If only you had not shown up here — we could have gone on as ever before — sharing idle words and quiet mirth.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AA7C"
        },
        [12022215] = {
          ContentTC = "可惜商人的行事準則裡，不存在如果。",
          DialogueId = 12022215,
          GUID = "1E18AAA6",
          NextDialogue = 12022216,
          SpeakNpcId = 210004,
          Subtitle = "But merchants have no \"if only.\"",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AAA6"
        },
        [12022216] = {
          ContentTC = "你到底想做什麼……",
          DialogueId = 12022216,
          GUID = "1E18AAD0",
          NextDialogue = 12022217,
          SpeakNpcId = 100001,
          Subtitle = "What are you trying to do...?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AAD0"
        },
        [12022217] = {
          ContentTC = "噓——這是為你好。雖然，可能不是以你喜歡的方式。",
          DialogueId = 12022217,
          GUID = "1E18AAFA",
          SpeakNpcId = 210004,
          Subtitle = "Ssh... It is for your own good — though perhaps not in the way you would choose.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AAFA"
        },
        [12022219] = {
          ContentTC = "（逐漸扭曲的嘶鳴聲）",
          DialogueId = 12022219,
          GUID = "1E18AB4E",
          Subtitle = "(Voice warping into twisted screams)",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AB4E"
        },
        [12022220] = {
          ContentTC = "喂，這裡發生什麼了？——放開{性别:他|她}！",
          DialogueId = 12022220,
          GUID = "1E18AB78",
          SpeakNpcId = 210021,
          Subtitle = "Hey! What the hell happened here!? Let {性别:him|her} go!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AB78"
        },
        [12022221] = {
          ContentTC = "嘖，撤。",
          DialogueId = 12022221,
          GUID = "1E18AB79",
          Subtitle = "Tsk. Retreat.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AB79"
        },
        [12022250] = {
          ContentTC = "一段時間後……",
          DialogueId = 12022250,
          GUID = "1E18AB8A",
          Subtitle = "After a while…"
        },
        [12022301] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "{nickname}，你受傷了嗎？",
          DialogueId = 12022301,
          GUID = "1E18B8C2",
          NextDialogue = 12022302,
          RelatedWikiId = {
            [1] = 203001,
            [2] = 203006,
            [3] = 203007
          },
          SpeakNpcId = 210013,
          Subtitle = ", are you hurt?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B8C2"
        },
        [12022302] = {
          ContentTC = "深呼吸，排清雜念，我來為你調養。",
          DialogueId = 12022302,
          GUID = "1E18B8EC",
          NextDialogue = 12022303,
          SpeakNpcId = 210013,
          Subtitle = "Steady now. Take a breath, and let your thoughts settle. I will help restore your energy.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B8EC"
        },
        [12022303] = {
          ContentTC = "我沒事，只是有點頭暈……扶疏，不要再消耗你的力量了，你答應過……",
          DialogueId = 12022303,
          GUID = "1E18B916",
          NextDialogue = 12022304,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine... just a little dizzy. Fushu, please — no more straining yourself to heal others. You promised me, remember?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B916"
        },
        [12022304] = {
          ContentTC = "安心，我自有分寸。當下還是以你的安危為重。",
          DialogueId = 12022304,
          GUID = "1E18B940",
          NextDialogue = 12022305,
          SpeakNpcId = 210013,
          Subtitle = "Worry not — I know my limits. In this moment, your safety is what matters most.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B940"
        }
      }
    end
  },
  {
    MinKey = 12022305,
    MaxKey = 12025407,
    Loader = function()
      return {
        [12022305] = {
          ContentTC = "可惡，今天怎麼總是遲來一步！要是當初學輕功時沒有偷懶就好了，都怪我總是睡到日上三竿才醒……",
          DialogueId = 12022305,
          GUID = "1E18B96A",
          NextDialogue = 12022306,
          SpeakNpcId = 210021,
          Subtitle = "Damn it... Why am I always a step too late today!? If only I hadn't slacked off so much during lightfoot training back then... serves me right!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B96A"
        },
        [12022306] = {
          ContentTC = "我還好……你們怎麼一起來了？",
          DialogueId = 12022306,
          GUID = "1E18B994",
          NextDialogue = 12022307,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay, don't worry... But how come you two came together?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B994"
        },
        [12022307] = {
          ContentTC = "我想明白了一些事情，正欲說與你聽。",
          DialogueId = 12022307,
          GUID = "1E18B9BE",
          NextDialogue = 12022308,
          SpeakNpcId = 210013,
          Subtitle = "I came to a realisation... and I wished to share it with you.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B9BE"
        },
        [12022308] = {
          ContentTC = "我去百年春沒有尋見你。聽旁人說你往此處來了，便來碰碰運氣，恰好在途中遇見了這位義士。",
          DialogueId = 12022308,
          GUID = "1E18B9E8",
          NextDialogue = 12022309,
          SpeakNpcId = 210013,
          Subtitle = "I looked for you at EverSpring, but you were not there. Someone mentioned you had come this way — so I followed, hoping to catch up. Along the road, I happened upon this swordsman.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B9E8"
        },
        [12022309] = {
          ContentTC = "聽鴉原一別後，我尋思師兄可能往塵漠石海的方向去了，便在這附近徘徊遊蕩。",
          DialogueId = 12022309,
          GUID = "1E18BA12",
          NextDialogue = 12022310,
          SpeakNpcId = 210021,
          Subtitle = "After we parted ways at Crowsong Hollow, I figured my shixiong might have headed towards the Gritblight Expanse, so I hung around the area, wandering and keeping watch.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA12"
        },
        [12022310] = {
          ContentTC = "不想那祭壇處突然刮起大風，天地震蕩。我便趕來瞧，結果竟碰上了你……若是來得早點就好了！",
          DialogueId = 12022310,
          GUID = "1E18BA3C",
          NextDialogue = 12022311,
          SpeakNpcId = 210021,
          Subtitle = "Then all of a sudden, the winds rose up and the ground itself began to quake near the altar. I came running to see what was going on... and there you were. If only I'd gotten here sooner!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA3C"
        },
        [12022311] = {
          ContentTC = "我和你說，剛剛發生的事情太可怕了！就算十個你來了也沒用！",
          DialogueId = 12022311,
          GUID = "1E18BA66",
          NextDialogue = 12022312,
          SpeakNpcId = 200002,
          Subtitle = "Nah — what just happened was way too scary! Even if there'd been ten of you, it wouldn't have made a difference!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA66"
        },
        [12022312] = {
          ContentTC = "那個女人，她不僅把本魔王和小僕從囚禁起來，還硬生生地吞了一條龍！那可是龍耶！",
          DialogueId = 12022312,
          GUID = "1E18BA90",
          NextDialogue = 12022313,
          SpeakNpcId = 200002,
          Subtitle = "That woman — she trapped me and my Little Minion in some magic cage... and she ate a whole loong! A real one!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA90"
        },
        [12022313] = {
          ContentTC = "白現在想想還心有餘悸……竟然和這樣的人相處了這麼久！",
          DialogueId = 12022313,
          GUID = "1E18BABA",
          NextDialogue = 12022314,
          SpeakNpcId = 200002,
          Subtitle = "I'm still getting chills just thinking about it... I can't believe we spent so long hanging around a creepy character like her!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BABA"
        },
        [12022314] = {
          ContentTC = "{nickname}，真有此事嗎？",
          DialogueId = 12022314,
          GUID = "1E18BAE4",
          NextOptions = {
            [1] = 12022315
          },
          SpeakNpcId = 210013,
          Subtitle = ", is that true?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BAE4"
        },
        [12022315] = {
          ContentTC = "（講述事情經過。）",
          DialogueId = 12022315,
          GUID = "1E18BB0E",
          NextDialogue = 12022327,
          Subtitle = "(Tell them what happened)"
        },
        [12022316] = {
          ContentTC = "她弄這麼一出，到底是何居心？",
          DialogueId = 12022316,
          GUID = "1E18BB38",
          NextDialogue = 12022317,
          SpeakNpcId = 210021,
          Subtitle = "But why go so far — what's she really after?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BB38"
        },
        [12022317] = {
          ContentTC = "我也回答不上來……",
          DialogueId = 12022317,
          GUID = "1E18BB62",
          NextDialogue = 12022318,
          SpeakNpcId = 100001,
          Subtitle = "I don't know...",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BB62"
        },
        [12022318] = {
          ContentTC = "依我看，她就是想霸占燭陰的力量，征服世界，成為大魔王！",
          DialogueId = 12022318,
          GUID = "1E18BB8C",
          NextDialogue = 12022319,
          SpeakNpcId = 200002,
          Subtitle = "If you ask me, she's out to grab that loong's power, take over the world, and crown herself as the ultimate Demon Lord!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BB8C"
        },
        [12022319] = {
          ContentTC = "征服世界……嗎……",
          DialogueId = 12022319,
          GUID = "1E18BBB6",
          NextDialogue = 12022320,
          SpeakNpcId = 100001,
          Subtitle = "Take over the world... huh.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BBB6"
        },
        [12022320] = {
          ContentTC = "她當時的確說了那樣的話……",
          DialogueId = 12022320,
          GUID = "1E18BBE0",
          NextDialogue = 12022321,
          SpeakNpcId = 100001,
          Subtitle = "She did say something like that...",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BBE0"
        },
        [12022321] = {
          ContentTC = "<H>白龍神君</>的時代，該結束了。而我，將執起祂的權柄。",
          DialogueId = 12022321,
          GUID = "1E18BC0A",
          NextDialogue = 12022322,
          SpeakNpcId = 210004,
          Subtitle = "The age of the Lord Argent Sovereign ends here. And I shall claim Their mantle.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BC0A"
        },
        [12022322] = {
          ContentTC = "她……想自己<H>成神</>嗎？",
          DialogueId = 12022322,
          GUID = "1E18BC34",
          NextDialogue = 12022323,
          SpeakNpcId = 100001,
          Subtitle = "She... she's trying to become a god?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BC34"
        },
        [12022323] = {
          ContentTC = "依你所述，若止流早在萬裡之外的「冰湖城」就已開始布局，那她的計劃恐怕比你我能猜到的更加周密。",
          DialogueId = 12022323,
