        },
        [12025605] = {
          ContentTC = "想要的話，我也可以給你臉上畫一個皎皎塗鴉喲！只要是小僕從的要求，白都會滿足！",
          DialogueId = 12025605,
          GUID = "1E1AD6D2",
          NextDialogue = 12025606,
          SpeakNpcName = "UI_Npc_Name_Bai",
          Subtitle = "If you like it, I can doodle something cute on your face too! Perks of being my minion!"
        },
        [12025606] = {
          ContentTC = "……謝了，白。我們還是趕緊走吧。",
          DialogueId = 12025606,
          GUID = "1E1AD6FC",
          SpeakNpcId = 100001,
          Subtitle = "...Thanks, Snow. Come on, we should get moving."
        },
        [12025701] = {
          ContentTC = "嘿，我說你們倆——還真是止流掌柜的客人。",
          DialogueId = 12025701,
          GUID = "1E1AE692",
          NextDialogue = 12025702,
          SpeakNpcId = 210118,
          Subtitle = "Hey, you two — so you really are Proprietress Zhiliu's guests, huh."
        },
        [12025702] = {
          ContentTC = "我天天在這兒望風，想混進黑市的人可真不少，各種藉口我都聽得耳朵起繭子了。但像你們這麼冒失的我還是頭一回見。",
          DialogueId = 12025702,
          GUID = "1E1AE6BC",
          NextDialogue = 12025703,
          SpeakNpcId = 210118,
          Subtitle = "I'm on the lookout here every day. People try to sneak into the market all the time — I've heard every excuse under the sun. But I've never seen anyone as reckless as you two."
        },
        [12025703] = {
          ContentTC = "既然你們現在已經是虬先生的座上賓了……嘿嘿，能不能幫我在老大面前美言兩句。就說他手下的張三，願意鞍前馬後為他老人家效勞！",
          DialogueId = 12025703,
          GUID = "1E1AE6E6",
          NextDialogue = 12025704,
          SpeakNpcId = 210118,
          Subtitle = "Since you're Mr Qiu's honoured guests now... heh, could you put in a good word for me with the boss? Just tell him that his man Zhang San is ready to work himself to the bone to serve him!"
        },
        [12025704] = {
          ContentTC = "你們說，我天天在這兒望著，連潮聲岩穴的對側都快望穿了，按照風水輪流轉的道理，也該輪到些能撈油水的位置了。",
          DialogueId = 12025704,
          GUID = "1E1AE710",
          NextDialogue = 12025705,
          SpeakNpcId = 210118,
          Subtitle = "I'm stuck keeping watch here every damn day — staring so long I'm starting to see the other side of Tidesong Cavern in my sleep. And hey, luck's supposed to turn, right? Shouldn't it be my turn to land a gig with some actual payoff?"
        },
        [12025705] = {
          ContentTC = "總不能苦活都給我一個人幹了吧，是不是這個理？",
          DialogueId = 12025705,
          GUID = "1E1AE73A",
          SpeakNpcId = 210118,
          Subtitle = "You can't keep dumping all the dirty work on one poor man, right? I mean, tell me I'm not wrong here."
        },
        [12025801] = {
          ContentTC = "小友，你來了，坐。",
          DialogueId = 12025801,
          GUID = "1E1AF6FA",
          NextDialogue = 12025802,
          SpeakNpcId = 210119,
          Subtitle = "Ah, you're here. Sit down, my young friend."
        },
        [12025802] = {
          ContentTC = "百年的陳皮，剛沏好的，潤潤嗓子再來與我分享旅途的見聞吧。",
          DialogueId = 12025802,
          GUID = "1E1AF724",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "I've just brewed a cup of tangerine peel tea, aged for centuries. Let it soothe your throat, then indulge me with tales of your travels."
        },
        [12025803] = {
          ContentTC = "你為什麼收藏這麼多古董？",
          DialogueId = 12025803,
          GUID = "1E1AF74E",
          NextDialogue = 12025804,
          Subtitle = "Why surround yourself with so many antiques?"
        },
        [12025804] = {
          ContentTC = "物慾深重，想要自然就要得到，這是所有活物最真實的本能。",
          DialogueId = 12025804,
          GUID = "1E1AF778",
          NextDialogue = 12025805,
          SpeakNpcId = 210119,
          Subtitle = "Desire shapes the very core of life. To yearn is to seek, and to seek is to claim — a drive as old as existence itself."
        },
        [12025805] = {
          ContentTC = "更何況，古董並非僅是眼前的死物，它們都曾經在他人的故事中活過，說是牽連著千百個春秋，也不為過。",
          DialogueId = 12025805,
          GUID = "1E1AF7A2",
          NextDialogue = 12025806,
          SpeakNpcId = 210119,
          Subtitle = "And these so-called \"antiques\" are far from mere lifeless trinkets. Each one has breathed another's story, a thread woven into countless ages of history."
        },
        [12025806] = {
          ContentTC = "聽著玄之又玄，怪難懂的。",
          DialogueId = 12025806,
          GUID = "1E1AF7CC",
          NextDialogue = 12025807,
          SpeakNpcId = 100001,
          Subtitle = "That sounds awfully abstract and cryptic."
        },
        [12025807] = {
          ContentTC = "這柄短劍，抵禦過外敵，刺殺過君主，最後是殉了主。這碎茶盞呢，迎接了遊子，送別了摯愛，最後是在賭書時被打翻在地。",
          DialogueId = 12025807,
          GUID = "1E1AF7F6",
          NextDialogue = 12025808,
          SpeakNpcId = 210119,
          Subtitle = "Take this dagger, for instance. It once repelled invaders, cut down monarchs, and ultimately perished by its master's side. And this cracked teacup? It welcomed weary travellers and saw off loved ones, only to be toppled in a wager of wit and verse."
        },
        [12025808] = {
          ContentTC = "當我觸碰到這些古物時，好像此間並非只有你我二人，而是有七八幕景，十二三人，幾百年事。這就是為什麼我要收集它們，絕不收手。",
          DialogueId = 12025808,
          GUID = "1E1AF820",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "When I hold these relics, it feels as though we're no longer alone in this room. Figures from ages past seem to gather with us — seven or eight scenes, each carrying centuries of memories. That, my young friend, is why I gather them... and why I shall never stop."
        },
        [12025809] = {
          ContentTC = "聽說你很貪得無厭。",
          DialogueId = 12025809,
          GUID = "1E1AF84A",
          NextDialogue = 12025810,
          Subtitle = "I've heard you're quite insatiable."
        },
        [12025810] = {
          ContentTC = "貪得無厭？我喜歡這個評價。",
          DialogueId = 12025810,
          GUID = "1E1AF874",
          NextDialogue = 12025811,
          SpeakNpcId = 210119,
          Subtitle = "Insatiable? I must say, I find that rather flattering."
        },
        [12025811] = {
          ContentTC = "我若不貪，便是暴殄天物，無數珍寶與秘密將被埋葬於過去，永世無人知曉。",
          DialogueId = 12025811,
          GUID = "1E1AF89E",
          NextDialogue = 12025812,
          SpeakNpcId = 210119,
          Subtitle = "Were I not \"insatiable,\" I'd be forsaking all the treasures this world holds. Countless relics and untold secrets would remain entombed in time, never to grace the light of day again."
        },
        [12025812] = {
          ContentTC = "人若不貪，便是有違這世間最樸素的道理：物慾，才是讓人前行的動力，讓萬物演進的根本。",
          DialogueId = 12025812,
          GUID = "1E1AF8C8",
          NextDialogue = 12025813,
          SpeakNpcId = 210119,
          Subtitle = "And if one suppresses desire, doesn't that defy the most fundamental truth of life? Desire propels us forward; it spurs every inch of progress."
        },
        [12025813] = {
          ContentTC = "可並不是所有人都這麼想。",
          DialogueId = 12025813,
          GUID = "1E1AF8F2",
          NextDialogue = 12025814,
          SpeakNpcId = 100001,
          Subtitle = "Not everyone sees it that way."
        },
        [12025814] = {
          ContentTC = "無所謂，你大可以說這是厚顏無恥的詭辯，但我更喜歡將它描述為，順應自我，隨心所欲。",
          DialogueId = 12025814,
          GUID = "1E1AF91C",
          NextDialogue = 12025815,
          SpeakNpcId = 210119,
          Subtitle = "It matters little. Call it brazen sophistry if you wish — I prefer to call it embracing one's nature and living true to oneself."
        },
        [12025815] = {
          ContentTC = "大部分人想成為虬先生，但是卻不會做虬先生，不敢做虬先生。最終連自己也做不成，只會躲在道理規矩背後謾罵我，可憐吶。",
          DialogueId = 12025815,
          GUID = "1E1AF946",
          NextDialogue = 12025802,
          SpeakNpcId = 210119,
          Subtitle = "Many wish to become like me, yet lack the courage to take the first step, let alone follow through. In their fear, they fail even to become their truest selves, hiding behind the safety of rules and morals while hurling insults my way from the shadows. Pitiful, isn't it?"
        },
        [12025816] = {
          ContentTC = "公尚師傅是誰？",
          DialogueId = 12025816,
          GUID = "1E1AF970",
          NextDialogue = 12025817,
          Subtitle = "Who is Master Gongshang?"
        },
        [12025817] = {
          ContentTC = "我資助的一位機樞派奇人。",
          DialogueId = 12025817,
          GUID = "1E1AF99A",
          NextDialogue = 12025818,
          SpeakNpcId = 210119,
          Subtitle = "A most singular craftsman of the Jishu Sect — one whom I now patronise."
        },
        [12025818] = {
          ContentTC = "俗語說「人無癖不可交」。他便是我所見之人中癖好最為深重，行事最為乖張的一位了。",
          DialogueId = 12025818,
          GUID = "1E1AF9C4",
          NextDialogue = 12025819,
          SpeakNpcId = 210119,
          Subtitle = "There's a saying: a man without his peculiarities is hardly worth keeping company with. And among all the people I've met, his obsessions run the deepest, and his manner is the most unconventional."
        },
        [12025819] = {
          ContentTC = "人不怕性情怪異，怕的是平庸。他那打造機樞的手藝，當世也沒幾位比得上的。要不是他看不上天梁司的做派，也不會流落民間受我資助。",
          DialogueId = 12025819,
          GUID = "1E1AF9EE",
          NextDialogue = 12025820,
          SpeakNpcId = 210119,
          Subtitle = "Strange temperaments don't trouble me — mediocrity does. In craftsmanship, there are few today who can match his skill. Had he not taken issue with the Ministry of Works' methods, he wouldn't have left their ranks, nor would he have needed my support."
        },
        [12025820] = {
          ContentTC = "這等性情的奇人，就算當著面罵我，我也只會一笑了之。",
          DialogueId = 12025820,
          GUID = "1E1AFA18",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "A character like that... he could hurl insults right to my face, and I'd simply laugh them off."
        },
        [12025821] = {
          ContentTC = "你和止流掌柜是合作關係嗎？",
          DialogueId = 12025821,
          GUID = "1E1AFA42",
          NextDialogue = 12025822,
          Subtitle = "Are you and Proprietress Zhiliu partners?"
        },
        [12025822] = {
          ContentTC = "你如果這樣定義各取所需，那便是。",
          DialogueId = 12025822,
          GUID = "1E1AFA6C",
          NextDialogue = 12025823,
          SpeakNpcId = 210119,
          Subtitle = "If you wish to call a relationship built on mutual interest a partnership, then yes."
        },
        [12025823] = {
          ContentTC = "那要是有一天她不再能提供你需要的東西，你會背叛她嗎？",
          DialogueId = 12025823,
          GUID = "1E1AFA96",
          NextDialogue = 12025824,
          SpeakNpcId = 100001,
          Subtitle = "And if one day she couldn't give you what you wanted anymore... would you betray her?"
        },
        [12025824] = {
          ContentTC = "哈哈，小友這個問題有些天真了！世上無恆久之友，也無恆久之敵。人與人之間的立場流動不定，又何來背不背叛一說呢？",
          DialogueId = 12025824,
          GUID = "1E1AFAC0",
          NextDialogue = 12025825,
          SpeakNpcId = 210119,
          Subtitle = "Hah. My young friend, that is a rather naive question. There are no eternal friends, nor eternal enemies. People's ties shift constantly — so what does \"betrayal\" really amount to?"
        },
        [12025825] = {
          ContentTC = "不過有一件事你大可放心。你們止流掌柜是個聰明人，她會用利益將別人緊緊和她捆綁在一條戰船上。你說的那一天，大抵是不會發生的。",
          DialogueId = 12025825,
          GUID = "1E1AFAEA",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "Still, this is not something you need worry about. Proprietress Zhiliu is a shrewd woman. She binds people to her through shared interests — firmly enough that the day you speak of is unlikely ever to come."
        },
        [12025826] = {
          ContentTC = "我先走了。",
          DialogueId = 12025826,
          GUID = "1E1AFB14",
          NextDialogue = 12025827,
          Subtitle = "I should get going."
        },
        [12025827] = {
          ContentTC = "慢走，不送。",
          DialogueId = 12025827,
          GUID = "1E1AFB3E",
          SpeakNpcId = 210119,
          Subtitle = "Go on, then. I won't see you out."
        },
        [12025828] = {
          DialogueId = 12025828,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12025827,
          GUID = "1E1AFB3F",
          NextOptions = {
            [1] = 12025803,
            [2] = 12025809,
            [3] = 12025816,
            [4] = 12025821,
            [5] = 51155701,
            [6] = 12025826
          }
        },
        [12025901] = {
          ContentTC = "恩人……謝……謝你…………",
          DialogueId = 12025901,
          GUID = "1E1B0762",
          NextDialogue = 12025902,
          SpeakNpcId = 210120,
          Subtitle = "Th—Thank you... for saving my life..."
        },
        [12025902] = {
          ContentTC = "（你眼前的姑娘面色蒼白，額頭上冒出豆大的汗珠，卻還在勉力向你道謝。被狴犴懲戒後，她明顯需要休息。）",
          DialogueId = 12025902,
          GUID = "1E1B078C",
          NextDialogue = 12025903,
          Subtitle = "(The young woman before you is pale as a ghost, sweat beading on her brow. Even so, she forces herself to thank you. After the Bi'an's punishment, she clearly needs rest.)"
        },
        [12025903] = {
          ContentTC = "您放心，您放心，大家都是朋友！我一定把她照顧得妥妥帖帖，一根毫毛都不會傷到！",
          DialogueId = 12025903,
          GUID = "1E1B07B6",
          NextDialogue = 12025904,
          SpeakNpcName = "UI_Npc_Name_Badshangren",
          Subtitle = "Don't worry, {性别：sir|ma'am} — we're all friends here! I'll take good care of her, not a single hair out of place! I swear it!"
        },
        [12025904] = {
          ContentTC = "哎呀，我的{性别：姑爺爺|姑奶奶}，算我求求您，趕緊去見虬先生吧，別讓他老人家久等。您們在這裡，她也沒法安心休息呀。",
          DialogueId = 12025904,
          GUID = "1E1B07E0",
          SpeakNpcName = "UI_Npc_Name_Badshangren",
          Subtitle = "Please... {性别：sir|ma'am}, I'm begging you here — please go see Mr Qiu first! Don't keep him waiting. With you standing here, the girl just can't calm down and rest, can she?"
        },
        [12026001] = {
          ContentTC = "這位榮譽學徒，有什麼想向我請教的？",
          DialogueId = 12026001,
          GUID = "1E1B17CA",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "So, my honorary learner — what is it you want to ask?"
        },
        [12026002] = {
          ContentTC = "可以再說明一下什麼是塵漠嗎？",
          DialogueId = 12026002,
          GUID = "1E1B17F4",
          NextDialogue = 12026003,
          Subtitle = "Could you explain what Gritblight is again?"
        },
        [12026003] = {
          ContentTC = "唉，遙想當初，過目不忘可是入門我機樞派的最基礎。資質愚鈍者，早在娃娃之時就被刷下去了。",
          DialogueId = 12026003,
          GUID = "1E1B181E",
          NextDialogue = 12026004,
          SpeakNpcId = 210121,
          Subtitle = "Ah... back in my day, a good memory was the most basic requirement for joining the Jishu Sect. The slow-witted were weeded out while they were still toddlers."
        },
        [12026004] = {
          ContentTC = "罷了罷了。做人不能強求，你有這份求知慾，也算是很珍貴了。我就再給你說明一次吧。",
          DialogueId = 12026004,
          GUID = "1E1B1848",
          NextDialogue = 12026005,
          SpeakNpcId = 210121,
          Subtitle = "Ah, never mind. Talent can't be forced. Since you're willing to learn, that's good enough. I'll explain it once more."
        },
        [12026005] = {
          ContentTC = "這空氣中瀰漫著一種名為太虛，看不見摸不著的物質。這時你就要問了，既然是看不見摸不著，那怎麼確定它存在呢？",
          DialogueId = 12026005,
          GUID = "1E1B1872",
          NextDialogue = 12026006,
          SpeakNpcId = 210121,
          Subtitle = "The air is suffused with something called Taixu, an unseen, intangible substance. And naturally, you'll ask: \"If we can't see it or touch it, how do we know it exists?\""
        },
        [12026006] = {
          ContentTC = "我們研究者自有各種手段去側面觀察它。這塵漠，便是太虛存在的最好佐證——",
          DialogueId = 12026006,
          GUID = "1E1B189C",
          NextDialogue = 12026007,
          SpeakNpcId = 210121,
          Subtitle = "Those of us who study it have ways to observe it indirectly. And Gritblight is the clearest proof that Taixu is real."
        },
        [12026007] = {
          ContentTC = "空氣中的太虛受燭陰之災影響，其性質發生轉變，固化成蒙於物體表面的粉末。這對一般生命有害的粉末便是塵漠。這樣一說，你可懂了？",
          DialogueId = 12026007,
          GUID = "1E1B18C6",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "When the Taixu in the air is disturbed by the Scourge of Zhuyin, its nature changes. It hardens into a fine powder that settles over everything — and that powder, harmful to ordinary life, is what we call Gritblight. Does it make sense to you now?"
        },
        [12026008] = {
          ContentTC = "可以再說明一下牽機方樞的用法嗎？",
          DialogueId = 12026008,
          GUID = "1E1B18F0",
          NextDialogue = 12026009,
          Subtitle = "Could you go over how to use the Mechanical Nexus again?"
        },
        [12026009] = {
          ContentTC = "嗯？我手寫的數百頁使用說明書與牽機方樞一併存放於秦虬那裡，他沒有交給你們嗎？",
          DialogueId = 12026009,
          GUID = "1E1B191A",
          NextDialogue = 12026010,
          SpeakNpcId = 210121,
          Subtitle = "Hm? I hand-wrote hundreds of pages of instructions and left them with the device at Qin Qiu's place. He didn't give them to you?"
        },
        [12026010] = {
          ContentTC = "沒有。他只讓我來請教你。",
          DialogueId = 12026010,
          GUID = "1E1B1944",
          NextDialogue = 12026011,
          SpeakNpcId = 100001,
          Subtitle = "No. He just sent me to ask you."
        },
        [12026011] = {
          ContentTC = "……那老東西，我就知道。他一定覺得你會字多不看，沒必要把這洋洋灑灑數十萬字的說明書交給你。我機樞派的榮譽學徒，能是這種品性的人嗎？",
          DialogueId = 12026011,
          GUID = "1E1B196E",
          NextDialogue = 12026012,
          SpeakNpcId = 210121,
          Subtitle = "...That old bastard. I knew it. He must've figured you wouldn't bother reading a manual that long, so he simply kept it from you. As if the Jishu Sect's honorary learner were so impatient and careless."
        },
        [12026012] = {
          ContentTC = "算了，我就簡單解說一下吧。很簡單，按下這個按鈕，對著塵漠，吸。完事了。",
          DialogueId = 12026012,
          GUID = "1E1B1998",
          NextDialogue = 12026013,
          SpeakNpcId = 210121,
          Subtitle = "Forget it. I'll make it simple for you. It's easy — press this button, point it at the Gritblight, and it'll suck it in. That's all."
        },
        [12026013] = {
          ContentTC = "就這樣？",
          DialogueId = 12026013,
          GUID = "1E1B19C2",
          NextDialogue = 12026014,
          SpeakNpcId = 100001,
          Subtitle = "That's it?"
        },
        [12026014] = {
          ContentTC = "就這樣。你莫非還要我從原理開始解說不成？",
          DialogueId = 12026014,
          GUID = "1E1B19EC",
          NextDialogue = 12026015,
          SpeakNpcId = 210121,
          Subtitle = "That's it. Or did you expect me to start explaining the theory behind it as well?"
        },
        [12026015] = {
          ContentTC = "沒有沒有，這樣就很好了。謝謝師父！",
          DialogueId = 12026015,
          GUID = "1E1B1A16",
          NextDialogue = 12026025,
          Subtitle = "No, no — this is perfect. Thank you, shifu!"
        },
        [12026016] = {
          ContentTC = "機樞派為什麼沒落了？",
          DialogueId = 12026016,
          GUID = "1E1B1A40",
          NextDialogue = 12026017,
          Subtitle = "Why has the Jishu Sect declined?"
        },
        [12026017] = {
          ContentTC = "我機樞派的人，首先要學會用辨證的思維看待事物——何為沒落？",
          DialogueId = 12026017,
          GUID = "1E1B1A6A",
          NextDialogue = 12026018,
          SpeakNpcId = 210121,
          Subtitle = "We in the Jishu Sect are taught to look at things from more than one angle. So — what exactly do you mean by \"decline\"?"
        },
        [12026018] = {
          ContentTC = "機樞派的造物從南向北遍布整個華胥，哪個碼頭見不到搬運貨物的木走馬？天梁司還高居華胥三大司之一，這能叫沒落嗎？",
          DialogueId = 12026018,
          GUID = "1E1B1A94",
          NextDialogue = 12026019,
          SpeakNpcId = 210121,
          Subtitle = "Our creations are found everywhere in Huaxu. At every dock you'll see wooden steeds hauling cargo. The Ministry of Works is still one of the three great ministries of Huaxu. And you call that \"decline\"?"
        },
        [12026019] = {
          ContentTC = "那個……機樞派沒落了招不到學生，好像是你和我說的？",
          DialogueId = 12026019,
          GUID = "1E1B1ABE",
          NextDialogue = 12026020,
          SpeakNpcId = 100001,
          Subtitle = "Um... but didn't you tell me the Jishu Sect had fallen on hard times and couldn't attract any new apprentices?"
        },
        [12026020] = {
          ContentTC = "聰明，這就是辨證思維的另一面了。",
          DialogueId = 12026020,
          GUID = "1E1B1AE8",
          NextDialogue = 12026021,
          SpeakNpcId = 210121,
          Subtitle = "Sharp kid — from that angle, you're not wrong."
        },
        [12026021] = {
          ContentTC = "世人失去了求知慾，無人願意考入機樞派，天梁司那些老東西只知道閉門造車，不再去窮事物之極理——這是沒落。",
          DialogueId = 12026021,
          GUID = "1E1B1B12",
          NextDialogue = 12026022,
          SpeakNpcId = 210121,
          Subtitle = "People have lost their desire to learn. No one wants to join the Jishu Sect anymore, and those hidebound old men in the Ministry of Works shut themselves away, tinkering all day but no longer seeking the highest principles — that, now, is decline."
        },
        [12026022] = {
          ContentTC = "現在我回答你的問題，機樞派為什麼沒落？是懸衡派那些傢伙幹的，因為他們害怕知識帶來的力量會超出他們的掌控，所以讓機樞派沒落了。就這麼簡單。",
          DialogueId = 12026022,
          GUID = "1E1B1B3C",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "Now then, to answer your question: why has the Jishu Sect declined? Because of the Xuanheng Sect. They fear the power that comes with knowledge may slip beyond their control, so they suppressed the Jishu Sect until it weakened. It's as simple as that."
        },
        [12026023] = {
          ContentTC = "還有好多問題，我想想。",
          DialogueId = 12026023,
          GUID = "1E1B1B66",
          NextDialogue = 12026024,
          Subtitle = "I've still got loads of questions... let me think."
        },
        [12026024] = {
          ContentTC = "打破砂鍋問到底，是個好苗子。好了，我要忙去了，你也不要疏忽了日常功課啊。",
          DialogueId = 12026024,
          GUID = "1E1B1B90",
          SpeakNpcId = 210121,
          Subtitle = "You keep digging until you truly grasp something — that's what I like to see. Now, I've work to do. Make sure you keep up with your daily practice."
        },
        [12026025] = {
          DialogueId = 12026025,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12026024,
          GUID = "1E1B1B91",
          NextOptions = {
            [1] = 12026002,
            [2] = 12026008,
            [3] = 12026016,
            [4] = 12026023
          }
        },
        [12026101] = {
          ContentTC = "瞧瞧是誰來了——原來是幫百年春化解危機的大英雄{nickname}！",
          DialogueId = 12026101,
          GUID = "1E1B2832",
          NextDialogue = 12026102,
          SpeakNpcId = 210122,
          Subtitle = "Look who it is — , the hero who helped lead EverSpring through the crisis!"
        },
        [12026102] = {
          ContentTC = "哪裡哪裡。我只是做了一些微小的工作，主要還是靠止流掌柜和大家的力量。",
          DialogueId = 12026102,
          GUID = "1E1B285C",
          NextDialogue = 12026103,
          SpeakNpcId = 100001,
          Subtitle = "You flatter me. I only played a small part — most of the credit goes to Proprietress Zhiliu and everyone else."
        },
        [12026103] = {
          ContentTC = "倒是你經歷了這些之後，現在還好嗎？",
          DialogueId = 12026103,
          GUID = "1E1B2886",
          NextDialogue = 12026104,
          SpeakNpcId = 100001,
          Subtitle = "And you? After all that's happened, how have you been?"
        },
        [12026104] = {
          ContentTC = "呵呵，說出來不怕你笑話……現在比起後怕，我心裡反而激盪著一種能夠保衛家園的興奮感，甚至感覺身體裡充滿了力量。",
          DialogueId = 12026104,
          GUID = "1E1B28B0",
          NextDialogue = 12026105,
          SpeakNpcId = 210122,
          Subtitle = "It may sound a little silly, but instead of feeling shaken afterward, I actually felt... exhilarated. There was a quiet thrill in being able to protect our home, as though a steady strength had taken root within me."
        },
        [12026105] = {
          ContentTC = "我甚至動了學幾招防身手段的念頭，這樣以後去別的危險地區行商，也不用光等著護衛來保護自己了。",
          DialogueId = 12026105,
          GUID = "1E1B28DA",
          NextDialogue = 12026106,
          SpeakNpcId = 210122,
          Subtitle = "I even found myself thinking about learning some basic self-defense, so that when I travel to more perilous regions for trade, I won't have to rely entirely on my escorts."
        },
        [12026106] = {
          ContentTC = "不過這種念頭終歸是不符合大風九章的吧……",
          DialogueId = 12026106,
          GUID = "1E1B2904",
          SpeakNpcId = 210122,
          Subtitle = "Although... thoughts like these do stray from the teachings of the Nine Chapters of Dafeng..."
        },
        [12026201] = {
          ContentTC = "怎麼了，{nickname}？有什麼事嗎？",
          DialogueId = 12026201,
          GUID = "1E1B389A",
          NextDialogue = 12026202,
          SpeakNpcId = 210123,
          Subtitle = "What is it, ? Was there something you wished to discuss?"
        },
        [12026202] = {
          ContentTC = "（止流的舉止一如往常，但你總覺得她有些不易察覺的疲憊……是錯覺嗎？）",
          DialogueId = 12026202,
          GUID = "1E1B38C4",
          NextDialogue = 12026213,
          Subtitle = "(Her composure seems unchanged, yet you sense a faint weariness beneath it — something easy to overlook. Perhaps it is only your imagination.)"
        },
        [12026203] = {
          ContentTC = "止流掌柜，你接下來有什麼安排？",
          DialogueId = 12026203,
          GUID = "1E1B38EE",
          NextDialogue = 12026204,
          Subtitle = "Proprietress Zhiliu, what will you do next?"
        },
        [12026204] = {
          ContentTC = "有了你采來的這些燭陰鱗，封印燭陰的準備也算是完畢了。接下來我便要先籌備此事，可能暫時無法分神接待你們了，先說一句抱歉。",
          DialogueId = 12026204,
          GUID = "1E1B3918",
          NextDialogue = 12026205,
          SpeakNpcId = 210123,
          Subtitle = "With the Zhuyin scales you recovered, the preparations for the sealing are complete. I must now turn to the matters that follow, and may not be able to receive you for a while. Allow me to offer my apologies in advance."
        },
        [12026205] = {
          ContentTC = "真的不需要我幫忙嗎？",
          DialogueId = 12026205,
          GUID = "1E1B3942",
          NextDialogue = 12026206,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure you don't need my help?"
        },
        [12026206] = {
          ContentTC = "呵呵，你倒是有心了。也不能總讓你一個人忙前忙後。若出現了難以搞定的事情，我會再來委託你們的。",
          DialogueId = 12026206,
          GUID = "1E1B396C",
          NextDialogue = 12026213,
          SpeakNpcId = 210123,
          Subtitle = "Heh... your offer is appreciated. But I cannot allow you to shoulder everything on your own. If a matter arises that truly requires your strength, I will seek your aid again."
        },
        [12026207] = {
          ContentTC = "剛剛百年春的危機真是兇險。",
          DialogueId = 12026207,
          GUID = "1E1B3996",
          NextDialogue = 12026208,
          Subtitle = "It was really dangerous back there."
        },
        [12026208] = {
          ContentTC = "嗯。這場危機化解也有你的一份功勞。多謝了，{nickname}。",
          DialogueId = 12026208,
          GUID = "1E1B39C0",
          NextDialogue = 12026209,
          SpeakNpcId = 210123,
          Subtitle = "Indeed. You played a part in resolving it as well. My thanks to you, ."
        },
        [12026209] = {
          ContentTC = "我沒做什麼，主要還是靠你組織起來了大家，你當時的應對好迅速。",
          DialogueId = 12026209,
          GUID = "1E1B39EA",
          NextDialogue = 12026210,
          SpeakNpcId = 100001,
          Subtitle = "I didn't do much. You were the one who brought everyone together — you handled everything so quickly and calmly."
        },
        [12026210] = {
          ContentTC = "呵呵，做事若是畏手畏腳，瞻前顧後，又怎能負起眾人之望呢？",
          DialogueId = 12026210,
          GUID = "1E1B3A14",
          NextDialogue = 12026213,
          SpeakNpcId = 210123,
          Subtitle = "Heh... if one hesitates at every turn, forever weighing each step, how could one hope to shoulder the expectations and responsibilities placed upon them?"
        },
        [12026211] = {
          ContentTC = "……",
          DialogueId = 12026211,
          GUID = "1E1B3A3E",
          NextDialogue = 12026212
        },
        [12026212] = {
          ContentTC = "我要先去籌備封印燭陰的相關事宜了。你現在得了空閒，去逛逛吧。有什麼開銷記在我帳上就行，不用對我客氣。",
          DialogueId = 12026212,
          GUID = "1E1B3A68",
          SpeakNpcId = 210123,
          Subtitle = "I must see to the remaining preparations for the sealing. You have some time to yourself now — feel free to look around as you wish. Should you incur any expenses, have them charged to my account; think nothing of the cost."
        },
        [12026213] = {
          DialogueId = 12026213,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12026212,
          GUID = "1E1B3A69",
          NextOptions = {
            [1] = 12026203,
            [2] = 12026207,
            [3] = 12026211
          }
        },
        [12026301] = {
          ContentTC = "恩人，你來看望我了……",
          DialogueId = 12026301,
          GUID = "1E1B4902",
          NextDialogue = 12026302,
          SpeakNpcId = 210124,
          Subtitle = "You... my lifesaver... you came to see me..."
        },
        [12026302] = {
          ContentTC = "你現在好點了嗎？",
          DialogueId = 12026302,
          GUID = "1E1B492C",
          NextDialogue = 12026303,
          SpeakNpcId = 100001,
          Subtitle = "Are you feeling any better now?"
        },
        [12026303] = {
          ContentTC = "多虧了您和扶疏大人為我採回來的藥，現在我的傷勢已經穩定，再過一兩天就能下床走動了。",
          DialogueId = 12026303,
          GUID = "1E1B4956",
          NextDialogue = 12026304,
          SpeakNpcId = 210124,
          Subtitle = "Thanks to the herbs you and Lady Fushu brought back for me, my injuries have started to settle. In another day or two, I might even be able to get out of bed and walk."
        },
        [12026304] = {
          ContentTC = "這一遭下來，不知道受了您的多少恩惠……除了言謝之外，我、我想不到別的方式可以報答你。以後有需要我做的，儘管開口，千萬不用客氣。",
          DialogueId = 12026304,
          GUID = "1E1B4980",
          SpeakNpcId = 210124,
          Subtitle = "After everything that's happened, you've shown me more kindness than I can even put into words... I... I really don't know how to repay you. If there's ever anything I can do for you, just say the word. I'll do my best."
        },
        [12026401] = {
          ContentTC = "如果你們在瀑布附近看到了受困的無由生，還請施以援手……多謝二位了。",
          DialogueId = 12026401,
          GUID = "1E1B596A",
          SpeakNpcId = 210125,
          Subtitle = "If you come across any Wishen stranded near the waterfall, please lend them your aid. My thanks to both of you."
        },
        [12026501] = {
          ContentTC = "多謝二位，失蹤的無由生都被救回來了！真是功德一樁吶！",
          DialogueId = 12026501,
          GUID = "1E1B69D2",
          SpeakNpcId = 210126,
          Subtitle = "My heartfelt thanks. With all the missing Wishen safely returned, we are deeply grateful for your help."
        },
        [12026601] = {
          ContentTC = "{nickname}，你來了。",
          DialogueId = 12026601,
          GUID = "1E1B7A3A",
          NextDialogue = 12026602,
          SpeakNpcId = 210127,
          Subtitle = ", you've come."
        },
        [12026602] = {
          ContentTC = "我性喜清淨，這枯榮閣中沒什麼可以用來招待你的，只有半壁醫書，一壺茗茶……希望不會使你感到枯燥。",
          DialogueId = 12026602,
          GUID = "1E1B7A64",
          NextDialogue = 12026603,
          SpeakNpcId = 210127,
          Subtitle = "I am accustomed to quietude, and here in the Hall of Ephemerality I have little with which to receive you — only these shelves of medical texts and a pot of tea. I hope it does not strike you as too dull."
        },
        [12026603] = {
          ContentTC = "你可以隨意走動，把這裡當做自己家一般便好。",
          DialogueId = 12026603,
          GUID = "1E1B7A8E",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "You may move about as you please. Please make yourself at ease here."
        },
        [12026604] = {
          ContentTC = "除了治病救人，你在閒暇時間還會做些什麼？",
          DialogueId = 12026604,
          GUID = "1E1B7AB8",
          NextDialogue = 12026605,
          Subtitle = "Apart from healing people, what do you do in your spare time?"
        },
        [12026605] = {
          ContentTC = "照料病人往往已占據我大部分時間。若是偷得浮生半日閒……我許是會研究家姐留下的醫書吧。",
          DialogueId = 12026605,
          GUID = "1E1B7AE2",
          NextDialogue = 12026606,
          SpeakNpcId = 210127,
          Subtitle = "Most of my days are taken up with tending to patients. Should I chance upon a rare moment of leisure... I would likely spend it reading the medical texts my elder sister left behind."
        },
        [12026606] = {
          ContentTC = "那不還是治病救人嗎？！",
          DialogueId = 12026606,
          GUID = "1E1B7B0C",
          NextDialogue = 12026607,
          SpeakNpcId = 100001,
          Subtitle = "Wouldn't that be basically the same as working?"
        },
        [12026607] = {
          ContentTC = "若是病人就在眼前，我往往心思急切，無法沉下心去研究藥理關聯。反倒是漫無目的翻開某頁醫書，細細研究其晦澀之語時，能體會到一種茅塞頓開的喜悅。",
          DialogueId = 12026607,
          GUID = "1E1B7B36",
          NextDialogue = 12026608,
          SpeakNpcId = 210127,
          Subtitle = "When a patient stands before me, my mind is seldom still, and I cannot quite settle myself to study the subtleties of medicine. Yet when I turn to some page of an old text and take my time with its more difficult passages, there often comes a moment of clarity — a quiet joy in its own right."
        },
        [12026608] = {
          ContentTC = "你就沒有這之外的愛好了嗎？",
          DialogueId = 12026608,
          GUID = "1E1B7B60",
          NextDialogue = 12026609,
          SpeakNpcId = 100001,
          Subtitle = "So you don't have any hobbies besides that?"
        },
        [12026609] = {
          ContentTC = "待我想想……撫上一首琴曲，或是與雲螭嬉戲，這都是我少時的樂趣。",
          DialogueId = 12026609,
          GUID = "1E1B7B8A",
          NextDialogue = 12026610,
          SpeakNpcId = 210127,
          Subtitle = "Let me think... Perhaps playing the zheng, or whiling away a little time with Yunchi — such were the quiet pleasures of my youth."
        },
        [12026610] = {
          ContentTC = "那下次彈首琴曲給我聽吧。",
          DialogueId = 12026610,
          GUID = "1E1B7BB4",
          NextDialogue = 12026611,
          SpeakNpcId = 100001,
          Subtitle = "Then can you play a piece for me next time?"
        },
        [12026611] = {
          ContentTC = "……是了，我怎麼忘了呢。最大的樂趣還是與友人共處，無論賞曲或是談天說地，都別有一份逸趣。",
          DialogueId = 12026611,
          GUID = "1E1B7BDE",
          NextDialogue = 12026612,
          SpeakNpcId = 210127,
          Subtitle = "...Indeed. How could I have forgotten? The greatest pleasure, I find, lies in the company of friends — whether we share music or speak at ease, there is a quiet delight in it."
        },
        [12026612] = {
          ContentTC = "{nickname}，你隨時可以來枯榮閣找我打發閒暇。我會很樂意你來訪。",
          DialogueId = 12026612,
          GUID = "1E1B7C08",
          NextDialogue = 12026613,
          SpeakNpcId = 210127,
          Subtitle = ", you are welcome to visit the Hall of Ephemerality whenever you have a moment to spare. Your company would be most welcome."
        },
        [12026613] = {
          ContentTC = "那就一言為定！",
          DialogueId = 12026613,
          GUID = "1E1B7C32",
          NextDialogue = 12026640,
          SpeakNpcId = 100001,
          Subtitle = "Then it's settled!"
        },
        [12026614] = {
          ContentTC = "我最近有些不舒服。",
          DialogueId = 12026614,
          GUID = "1E1B7C5C",
          NextDialogue = 12026615,
          Subtitle = "I've been feeling off lately."
        },
        [12026615] = {
          ContentTC = "怎麼了？哪裡痛，還是在煙津渡奔行時不慎受傷了？快把手遞給我，我幫你細細查探一番。",
          DialogueId = 12026615,
          GUID = "1E1B7C86",
          NextDialogue = 12026616,
          SpeakNpcId = 210127,
          Subtitle = "What troubles you? Do you feel pain anywhere — or did you perhaps injure yourself while making your way through Mistwharf? Let me see your hand. I shall examine it carefully."
        },
        [12026616] = {
          ContentTC = "噗嗤，扶疏，你好緊張。",
          DialogueId = 12026616,
          GUID = "1E1B7CB0",
          NextDialogue = 12026617,
          SpeakNpcId = 100001,
          Subtitle = "Haha... Fushu, you're so tense — you really do worry about me, don't you?"
        },
        [12026617] = {
          ContentTC = "沒有那麼嚴重，只是睡醒時常常感覺腰酸背痛而已。",
          DialogueId = 12026617,
          GUID = "1E1B7CDA",
          NextDialogue = 12026618,
          SpeakNpcId = 100001,
          Subtitle = "It's nothing serious. I just wake up with a stiff back and aching shoulders, that's all."
        },
        [12026618] = {
          ContentTC = "健康乃大事，就算是小病小痛也不可隨意對待。我這裡有一套強身健體的五禽戲可以傳授於你，助你活絡筋骨。",
          DialogueId = 12026618,
          GUID = "1E1B7D04",
          NextDialogue = 12026619,
          SpeakNpcId = 210127,
          Subtitle = "Health is no trifling matter; even minor discomforts should not be overlooked. I can instruct you in the Five-Animal Frolics, which help loosen the limbs and fortify the body."
        },
        [12026619] = {
          ContentTC = "為了充分領略五禽的形意，這套拳法須在雞犬鳴叫，夜色將褪未褪之時開始練習。待到旭陽將出，清風拂面，你必定能感受到鍛鍊帶來的身心舒暢……",
          DialogueId = 12026619,
          GUID = "1E1B7D2E",
          NextDialogue = 12026620,
          SpeakNpcId = 210127,
          Subtitle = "To grasp the essence of the Five Animals, practice should begin at cockcrow, while the world is still dim with the last of night. As the morning light strengthens and a gentle breeze stirs, you will feel the ease and clarity this training brings to both body and mind."
        },
        [12026620] = {
          ContentTC = "不、不用了！",
          DialogueId = 12026620,
          GUID = "1E1B7D58",
          NextDialogue = 12026621,
          SpeakNpcId = 100001,
          Subtitle = "I—I'm okay!"
        },
        [12026621] = {
          ContentTC = "我又想了想，我很好，再好不過了，我從來沒有這麼健康過！所以你的好意我就心領了，千萬不用實踐。",
          DialogueId = 12026621,
          GUID = "1E1B7D82",
          NextDialogue = 12026622,
          SpeakNpcId = 100001,
          Subtitle = "You know what — I just realised I'm actually fine, perfectly fine. I've never been this healthy in my life! Thank you for your kind advice, but there's really no need to put it into action..."
        },
        [12026622] = {
          ContentTC = "唉，你呀……",
          DialogueId = 12026622,
          GUID = "1E1B7DAC",
          NextDialogue = 12026623,
          SpeakNpcId = 210127,
          Subtitle = "*sigh*... ."
        },
        [12026623] = {
          ContentTC = "這次便讓你逃過去了。但若再遇到身體不適的情況，千萬不要硬撐，我會為你排憂解難。",
          DialogueId = 12026623,
          GUID = "1E1B7DD6",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "I shall let it pass this time. But should you feel unwell again, do not force yourself to bear it alone. Come to me, and I shall ease your troubles."
        },
        [12026624] = {
          ContentTC = "你離開往隙之後好像有什麼煩惱。",
          DialogueId = 12026624,
          GUID = "1E1B7E00",
          NextDialogue = 12026625,
          Subtitle = "You've seemed a bit off since you left the Oblivion Rift. Is something bothering you?"
        },
        [12026625] = {
          ContentTC = "這也被你察覺到了……多謝你牽掛著我。",
          DialogueId = 12026625,
          GUID = "1E1B7E2A",
          NextDialogue = 12026626,
          SpeakNpcId = 210127,
          Subtitle = "You perceived it... Thank you for your concern."
        },
        [12026626] = {
          ContentTC = "{nickname}，你也有對你而言意義重大的家人吧。倘若你犯下了言語過失，傷了那人的心，你會怎麼做？",
          DialogueId = 12026626,
          GUID = "1E1B7E54",
          NextDialogue = 12026627,
          SpeakNpcId = 210127,
          Subtitle = ", you too must have family who are dear to you. If you had, in a moment of carelessness, said something that caused them hurt... what would you do?"
        },
        [12026627] = {
          ContentTC = "既然是家人，肯定不會有化解不了的矛盾。我想如果有一天真的發生了那種事情，我會很努力地去道歉，那樣她一定會接受的。",
          DialogueId = 12026627,
          GUID = "1E1B7E7E",
          NextDialogue = 12026628,
          SpeakNpcId = 100001,
          Subtitle = "If it's family, there's nothing you can't work out. If something like that happened, I'd try my best to apologise — I'm sure she'd forgive me."
        },
        [12026628] = {
          ContentTC = "但若是伊人已逝，此時再想道歉，也無人聆聽……那又該如何是好？",
          DialogueId = 12026628,
          GUID = "1E1B7EA8",
          NextDialogue = 12026629,
          SpeakNpcId = 210127,
          Subtitle = "But if that person had already passed on, and there was no one left to hear your apology... what then?"
        },
        [12026629] = {
          ContentTC = "扶疏…………",
          DialogueId = 12026629,
          GUID = "1E1B7ED2",
          NextDialogue = 12026630,
          SpeakNpcId = 100001,
          Subtitle = "Fushu..."
        },
        [12026630] = {
          ContentTC = "抱歉。不小心竟將自己的愁緒強加於你了。",
          DialogueId = 12026630,
          GUID = "1E1B7EFC",
          NextDialogue = 12026631,
          SpeakNpcId = 210127,
          Subtitle = "Forgive me. I did not mean to burden you with my own sorrow."
        },
        [12026631] = {
          ContentTC = "沒關係，如果你有什麼不開心的，都可以來和我說，我隨時在這裡。",
          DialogueId = 12026631,
          GUID = "1E1B7F26",
          NextDialogue = 12026640,
          SpeakNpcId = 100001,
          Subtitle = "It's okay. If anything's ever bothering you, just come talk to me. I'm always there for you."
        },
        [12026632] = {
          ContentTC = "你真的是百年之前的人嗎？",
          DialogueId = 12026632,
          GUID = "1E1B7F50",
          NextDialogue = 12026633,
          Subtitle = "So you really are from a hundred years ago?"
        },
        [12026633] = {
          ContentTC = "嗯……如我先前所說，家姐為了延緩我的疾病進程，將我的軀體凍結。直至最近，我才被從百年的沉眠中喚醒。",
          DialogueId = 12026633,
          GUID = "1E1B7F7A",
          NextDialogue = 12026634,
          SpeakNpcId = 210127,
          Subtitle = "Mm... As I mentioned before, my elder sister placed my body in a deep sleep to arrest the course of my illness. Only recently was I awakened from that century of sleep."
        },
        [12026634] = {
          ContentTC = "這個世界會讓你感到陌生嗎？",
          DialogueId = 12026634,
          GUID = "1E1B7FA4",
          NextDialogue = 12026635,
          SpeakNpcId = 100001,
          Subtitle = "Does the world feel strange to you now?"
        },
        [12026635] = {
          ContentTC = "或許吧。我剛剛醒來時，只感覺這世上的雲捲雲舒，一草一木，都不再和我有半分關聯。",
          DialogueId = 12026635,
          GUID = "1E1B7FCE",
          NextDialogue = 12026636,
          SpeakNpcId = 210127,
          Subtitle = "Perhaps. When I first awoke, the world felt distant — as though all things beneath the sky no longer concerned me."
        },
        [12026636] = {
          ContentTC = "但隨著時間發展，我也慢慢結識了你這樣的友人。",
          DialogueId = 12026636,
          GUID = "1E1B7FF8",
          NextDialogue = 12026637,
          SpeakNpcId = 210127,
          Subtitle = "But as time passed, I came to meet companions such as yourself."
        },
        [12026637] = {
          ContentTC = "現今世間百態，抑或是醫理發展，都使我感到新奇。換個角度來看，也是一件幸事。",
          DialogueId = 12026637,
          GUID = "1E1B8022",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "The many changes in the world today, and the advances in medicine, are all new to me. In another light, that too may be considered a small blessing."
        },
        [12026638] = {
          ContentTC = "我先走了。",
          DialogueId = 12026638,
          GUID = "1E1B804C",
          NextDialogue = 12026639,
          Subtitle = "I should get going."
        },
        [12026639] = {
          ContentTC = "你且去忙吧，注意身體。",
          DialogueId = 12026639,
          GUID = "1E1B8076",
          SpeakNpcId = 210127,
          Subtitle = "Go and see to your affairs — and take care of your health."
        },
        [12026640] = {
          DialogueId = 12026640,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12026639,
          GUID = "1E1B8077",
          NextOptions = {
            [1] = 12026604,
            [2] = 12026614,
            [3] = 12026624,
            [4] = 12026632,
            [5] = 12026638
          }
        },
        [12026701] = {
          ContentTC = "咿呀，咿咿呀，咿！",
          DialogueId = 12026701,
          GUID = "1E1B8AA2",
          NextDialogue = 12026702,
          SpeakNpcId = 210128,
          Subtitle = "Eee-ya... eeee-ya, eee!"
        },
        [12026702] = {
          ContentTC = "（它跟在扶疏身邊，好像很開心的樣子。）",
          DialogueId = 12026702,
          GUID = "1E1B8ACC",
          SpeakNpcId = 100001,
          Subtitle = "(It drifts beside Fushu, looking content.)"
        },
        [12026801] = {
          ContentTC = "獵物已經入網，此時行事須格外慎重，切忌打草驚蛇。",
          DialogueId = 12026801,
          GUID = "1E1B9B0A",
          NextDialogue = 12026802,
          Subtitle = "The prey is already in the net. From here on, be doubly cautious — nothing that might alert them."
        },
        [12026802] = {
          ContentTC = "{nickname}，你若已經準備好了，我們就繼續向前吧。",
          DialogueId = 12026802,
          GUID = "1E1B9B34",
          Subtitle = "When you're ready, , we proceed."
        },
        [12026901] = {
          ContentTC = "如果我沒有猜錯，這上古機括戰陣，其真名為千樞狩陣。取千樞為引，萬隙囚光之意。",
          DialogueId = 12026901,
          GUID = "1E1BAB72",
          NextDialogue = 12026902,
          Subtitle = "If I'm not mistaken, this ancient array's true name is the Myriad-Snare Hunting Array — crafted with countless snares that close in on the prey, and with gaps so fine they shut out even the faintest trace of light."
        },
        [12026902] = {
          ContentTC = "古物於我們面前重煥生機……不覺得這景象很壯觀嗎？",
          DialogueId = 12026902,
          GUID = "1E1BAB9C",
          Subtitle = "To witness such a relic awaken before our very eyes... quite a sight, wouldn't you say?"
        },
        [12027001] = {
          ContentTC = "您可以去塵漠石海最高處的位置，那裡通往燭陰祭壇的臨時道路已經搭建完畢。",
          DialogueId = 12027001,
          GUID = "1E1BBBDA",
          NextDialogue = 12027002,
          SpeakNpcId = 210129,
          Subtitle = "You may proceed to the highest point of the Gritblight Expanse. The temporary path to the Zhuyin Altar has already been completed."
        },
        [12027002] = {
          ContentTC = "封印儀式一旦開啟，燭陰極有可能受刺激狂化。祭壇周圍危機四伏，不可大意。",
          DialogueId = 12027002,
          GUID = "1E1BBC04",
          NextDialogue = 12027003,
          SpeakNpcId = 210129,
          Subtitle = "Once the rite begins, Zhuyin may grow agitated and lash out. The area around the altar will be extremely dangerous, so please be very careful."
        },
        [12027003] = {
          ContentTC = "狩月人，您務必要小心，您的安危才是第一位的。我在這裡等待您順利歸來。",
          DialogueId = 12027003,
          GUID = "1E1BBC2E",
          SpeakNpcId = 210129,
          Subtitle = "Phoxhunter, please take care. Your safety is our utmost priority. I'll remain here and await your return."
        },
        [12027101] = {
          ContentTC = "姐姐不在菱生身邊了……但是姐姐現在很高興，菱生能感覺得到。",
          DialogueId = 12027101,
          GUID = "1E1BCC42",
          SpeakNpcId = 210130,
          Subtitle = "Sister Feng is no longer with me... but she's happy now. I can feel it."
        },
        [12030001] = {
          ContentTC = "那是不久之前，發生在冰湖城的一段故事——",
          DialogueId = 12030001,
          Duration = 4,
          GUID = "1E1DA80A",
          NextDialogue = 12030002,
          Subtitle = "Not long ago, in the frost-kissed city of Icelake, a small tale began to unfold...",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA80A"
        },
        [12030002] = {
          ContentTC = "當一隻小夜鶯，決定勇敢地飛出它溫暖的巢穴。",
          DialogueId = 12030002,
          Duration = 4,
          GUID = "1E1DA834",
          Subtitle = "It was the story of a little nightingale, who one day left her warm little nest... and flew into the wide, wide world.",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA834"
        },
        [12030003] = {
          Content = "菲娜坐在家里，看着故事书",
          DialogueId = 12030003,
          GUID = "1E1DA85E",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA85E"
        },
        [12030101] = {
          Content = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
          DialogueId = 12030101,
          GUID = "1E1DB872",
          NextDialogue = 12030102,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB872"
        },
        [12030102] = {
          Content = "唔……",
          DialogueId = 12030102,
          GUID = "1E1DB89C",
          NextDialogue = 12030103,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB89C"
        },
        [12030103] = {
          Content = "怎么了？",
          DialogueId = 12030103,
          GUID = "1E1DB8C6",
          NextDialogue = 12030104,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8C6"
        },
        [12030104] = {
          Content = "奥特赛德，菲娜……菲娜有一个愿望！",
          DialogueId = 12030104,
          GUID = "1E1DB8F0",
          NextDialogue = 12030105,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8F0"
        },
        [12030105] = {
          Content = "是吗？你说，是什么愿望？",
          DialogueId = 12030105,
          GUID = "1E1DB91A",
          NextDialogue = 12030106,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB91A"
        },
        [12030106] = {
          Content = "菲娜想出去看看。",
          DialogueId = 12030106,
          GUID = "1E1DB944",
          NextDialogue = 12030107,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB944"
        },
        [12030107] = {
          Content = "出去……？现在吗？",
          DialogueId = 12030107,
          GUID = "1E1DB96E",
          NextDialogue = 12030108,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB96E"
        },
        [12030108] = {
          Content = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
          DialogueId = 12030108,
          GUID = "1E1DB998",
          NextDialogue = 12030109,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB998"
        },
        [12030109] = {
          Content = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
          DialogueId = 12030109,
          GUID = "1E1DB9C2",
          NextDialogue = 12030110,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9C2"
        },
        [12030110] = {
          Content = "所以，你还是待在家里最安全。",
          DialogueId = 12030110,
          GUID = "1E1DB9EC",
          NextDialogue = 12030111,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9EC"
        },
        [12030111] = {
          Content = "呜……",
          DialogueId = 12030111,
          GUID = "1E1DBA16",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA16"
        },
        [12030112] = {
          ContentTC = "夜晚，菲娜家內部。\n 菲娜在睡覺，奧特賽德看到桌上菲娜放著的故事書",
          DialogueId = 12030112,
          GUID = "1E1DBA40",
          Subtitle = [[
At night, in Fina's home.
Fina sleeps peacefully. Outsider notices an open storybook on her desk.]],
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA40"
        },
        [12030201] = {
          Camera = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
          ContentTC = "「大魔法師總是說，巢穴外的世界充滿了危險，呆在巢穴裡才是最安全的……可是小小的巢穴雖然溫暖，卻只能看到一小片方形的天空。」",
          DialogueId = 12030201,
          FinalCamera = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
          GUID = "1E1DC8DA",
          LookAt = {
            [1] = "211002:p(pFeina_FixSimple02_LookAt01)"
          },
          NextDialogue = 12030202,
          Subtitle = "\"The Great Magician always said the world beyond the nest was dangerous — that only inside could the Little Nightingale be truly safe... But the nest, though warm and snug, held only a sliver of sky.\"",
          TalkActionId = {
            [1] = "211024:Feina_Story_Lieidle"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DC8DA"
        },
        [12030202] = {
          Camera = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
          ContentTC = "「有一天，從很遠很遠的地方漂流而來的獨角獸{性别:先生|小姐}來到了小夜鶯的巢穴，為小夜鶯捎來了遠方的故事……」",
          DialogueId = 12030202,
          FinalCamera = "-445.522095,482.669922,106.667969,0.000118,8.757859,54.209782,35.000008,212.663025,false,Manual,2.8",
          GUID = "1E1DC904",
          NextDialogue = 12030203,
          Subtitle = "\"Then one day, {性别:Mr|Miss} Unicorn came visiting — all the way from a faraway land — and spoke of wonders beyond the horizon...\"",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DC904"
        },
        [12030203] = {
          Camera = "-93.792816,296.109375,123.785156,0.000262,-14.836967,-25.180407,28.0,180.0,false,Manual,3.5",
          ContentTC = "「在巢穴之外那廣闊的世界裡，有枝條能掛在月亮上的大樹，有懷抱著一百座小島的大海……」",
          DialogueId = 12030203,
          FinalCamera = "-93.792816,296.109375,123.785156,0.000261,-34.236603,-38.179943,28.000006,63.699184,false,Manual,3.5",
          GUID = "1E1DC92E",
          NextDialogue = 12030204,
          Subtitle = "\"Of towering trees whose branches brushed the moon... Of oceans cradling a hundred islands in their arms...\"",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DC92E"
        }
      }
    end
  },
  {
