        [12030205] = {
          Camera = "-139.631927,210.423828,144.097656,0.000295,7.366509,66.22287,35.0,112.741165,false,Manual,4.0",
          ContentTC = "「想乘上柔軟的雲，和掠過高空的海燕並肩翱翔，和躍出海面的魚兒一起嬉戲……」",
          DialogueId = 12030205,
          GUID = "1E1DC982",
          NextDialogue = 12030206,
          Subtitle = "\"She dreamed of riding on clouds, gliding beside the sea-swallows in the sky... Of splashing through the waves with fish that danced and leapt...\"",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DC982"
        },
        [12030206] = {
