          SpeakNpcId = 211001,
          Subtitle = "On a bright and breezy morning, the little nightingale arrived at the legendary Kingdom of Rubbish! She tapped the gate with her beak — knock knock — \"Is anyone home?\"",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7E4E"
        },
        [12031308] = {
          Camera = "53.371582,-201.73291,119.283203,0.000088,-2.599857,109.347733,35.000011,198.553635,false,DoNotOverride,4.5",
          ContentTC = "「哦，原來是小夜鶯啊，歡迎歡迎！」——垃圾王國的大門在小夜鶯面前轟然打開！",
          DialogueId = 12031308,
          GUID = "1E1E7E78",
          NextDialogue = 12031309,
          Scripts = [[
