          SpeakNpcId = 211003,
          Subtitle = "Ahem! Fina — sorry to cut in, but... could we pick a different title for my character? \"Princess\" is a bit... embarrassing.",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7ECC"
        },
        [12031311] = {
