          SpeakNpcId = 100001,
          Subtitle = "Hi there.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F22B2"
        },
        [12032310] = {
          Camera = "90.268677,307.583374,138.179688,0.000137,-3.600889,-93.077568,28.0,274.79599,false,Manual,12.0",
          ContentTC = "嗚哇——這個白毛獨眼的可怕傢伙到底是誰啊，你的保鏢嗎？",
          DialogueId = 12032310,
          FinalCamera = "91.618958,332.695404,139.762695,0.00015,-3.600889,-93.077148,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F22DC",
          NextDialogue = 12032311,
          Scripts = [[
