          SpeakNpcId = 211012,
          Subtitle = "Whoa! Who's this scary one with the white hair and eyepatch!? Your bodyguard?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F22DC"
        },
        [12032311] = {
          Camera = "91.618958,332.695404,139.762695,0.00015,-3.600889,-93.077148,28.000006,274.79599,false,Manual,12.0",
          ContentTC = "你不要害怕，獨角獸{性别:先生|小姐}是我的朋友，是來和我一起幫助你的！卡珊德拉小姐，你為什麼想找會魔法的人呀？你遇到困難了嗎？",
          DialogueId = 12032311,
          FinalCamera = "92.618301,351.292145,140.934814,0.00015,-3.600889,-93.07692,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2306",
          NextDialogue = 12032312,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211001},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Don't be scared — {性别:Mr|Miss} Unicorn is my friend. We're here because we want to help you. Miss Cassandra, why did you need someone who knows magic? Are you in trouble?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2306"
        },
        [12032312] = {
          Camera = "169.509918,-103.683769,140.384277,0.000153,-6.000949,114.122322,28.000008,274.79599,false,Manual,12.0",
          ContentTC = "我才沒有害怕，我只是……",
          DialogueId = 12032312,
          FinalCamera = "179.292389,-125.529129,142.900146,0.000153,-6.000949,114.122322,28.000008,274.79599,false,Manual,12.0",
          GUID = "1E1F2330",
          NextDialogue = 12032313,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211012:n(211001)"}},
PlayFacial{ActorId{100001},FacialId{"None"}},
PlayAnimation{ActorId{211012},AnimationId{"Shock_End"},Duration{1}},
}]],
          SpeakNpcId = 211012,
          Subtitle = "I'm not scared! I just...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2330"
        },
        [12032313] = {
          ContentTC = "……如果我告訴你原因，你就會幫我嗎？",
          DialogueId = 12032313,
          GUID = "1E1F235A",
          NextDialogue = 12032314,
          SpeakNpcId = 211012,
          Subtitle = "...If I tell you the reason, would you really help?",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F235A"
        },
        [12032314] = {
          Camera = "-120.740486,142.964783,128.572998,0.000203,-1.00024,-16.275805,28.000006,153.150421,false,Manual,12.0",
          ContentTC = "當然啦，只要你想做的不是什麼壞事，我們會盡力幫你的！",
          DialogueId = 12032314,
          FinalCamera = "-89.13591,133.737701,127.997559,0.000203,-1.00024,-16.275805,28.000008,153.150421,false,Manual,12.0",
          GUID = "1E1F2384",
          NextDialogue = 12032315,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Of course! As long as it's not something bad, we'll do whatever we can!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2384"
        },
        [12032315] = {
          ContentTC = "唔……好吧。其實，遇到困難的不是我，是我的一個朋友。",
          DialogueId = 12032315,
          GUID = "1E1F23AE",
          NextDialogue = 12032316,
          SpeakNpcId = 211012,
          Subtitle = "Um... okay. Actually, it's not me who's in trouble — it's my friend.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F23AE"
        },
        [12032316] = {
          Camera = "203.592789,-234.095764,139.684326,0.000146,-4.000817,116.320793,28.000008,274.79599,false,Manual,12.0",
          ContentTC = "他的媽媽之前因為意外去世了，他的爸爸又在最近失蹤了……他這段時間一直很難過，結果學校裡還有人欺負他，說他是沒人要的小孩什麼的……",
          DialogueId = 12032316,
          FinalCamera = "217.068558,-261.337952,141.80957,0.000146,-4.000817,116.320793,28.000008,274.79599,false,Manual,12.0",
          GUID = "1E1F23D8",
          NextDialogue = 12032317,
          Scripts = [[
SEQ{
PlayFacial{ActorId{100001},FacialId{"None"}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "His mum died in an accident, and now his dad's gone missing too... He's been really down, and now the other kids at school are picking on him. They say awful things... like he's an orphan, and nobody loves him...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F23D8"
        },
        [12032317] = {
          Camera = "-26.852451,76.142693,129.977295,0.000147,-0.800874,-16.678049,28.0,274.79599,false,Manual,12.0",
          ContentTC = "什麼——這也太過分了！",
          DialogueId = 12032317,
          GUID = "1E1F2402",
          NextDialogue = 12032318,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Sad02"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "What!? That's horrible!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2402"
        },
        [12032318] = {
          Camera = "-26.852451,76.142693,129.977295,0.000147,-0.800874,-16.678049,28.0,274.79599,false,Manual,12.0",
          ContentTC = "所以……你打算用魔法做什麼？幫他報復那些人嗎？",
          DialogueId = 12032318,
          FinalCamera = "-26.852451,76.142693,133.725098,0.000153,1.59905,-52.277107,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F242C",
          NextDialogue = 12032319,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Talk01_Start\"},Duration{1}}\n",
          SpeakNpcId = 100001,
          Subtitle = "So... you want to use magic to get back at them?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F242C"
        },
        [12032319] = {
          Camera = "-242.433731,141.123764,141.605469,0.00018,-5.00073,-16.078661,28.0,274.79599,false,Manual,12.0",
          ContentTC = "當然不是，你們又進不了內城。而且，那些欺負人的家伙，他們的爸爸媽媽都很厲害的，搞不好會把我們都哢嚓掉！",
          DialogueId = 12032319,
          FinalCamera = "-199.410095,128.722565,137.687744,0.00018,-5.00073,-16.078661,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2456",
          NextDialogue = 12032320,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211012:n(100001)"}},
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_End"},Duration{1}},
PlayAnimation{ActorId{211012},AnimationId{"Disagree"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Nuh-uh! That wouldn't work anyway. You can't even get into the inner city. And those bullies — their families are rich and powerful. If they get mad, we're toast!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2456"
        },
        [12032320] = {
          ContentTC = "嗚……原來內城是這麼可怕的地方……",
          DialogueId = 12032320,
          GUID = "1E1F2480",
          NextDialogue = 12032321,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Think01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Whoa... so the inner city really is a scary place...",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2480"
        },
        [12032321] = {
          Camera = "-54.569389,-159.021255,138.489502,0.000182,-1.600675,68.320656,28.0,274.79599,false,Manual,12.0",
          ContentTC = "我想找會魔法的卡戎，是因為我的朋友曾經說過一個願望，他說他想要見到「蝴蝶精靈」。",
          DialogueId = 12032321,
          FinalCamera = "-47.614666,-141.681595,137.967529,0.000182,-1.600675,67.920319,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F24AA",
          NextDialogue = 12032322,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211012},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "The reason I was looking for a Charon who can use magic is... my friend once said he really wants to see a Butterfly Fairy.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F24AA"
        },
        [12032322] = {
          Camera = "-59.477188,150.637482,127.989502,0.000234,-0.800286,-34.870335,16.0,153.150421,false,Manual,12.0",
          ContentTC = "……不要這麼看著我，我可不是小孩子，我才不信這些！但是我的朋友他一直都相信「蝴蝶精靈」是真的，所以我想幫他實現願望。",
          DialogueId = 12032322,
          FinalCamera = "-68.546638,156.957001,128.143555,0.000234,-0.800286,-34.870335,16.0,153.150421,false,Manual,12.0",
          GUID = "1E1F24D4",
          NextDialogue = 12032323,
          Scripts = "PlayFacial{ActorId{100001},FacialId{\"Nervous\"}}",
          SpeakNpcId = 211012,
          Subtitle = "...Don't look at me like that! I'm not some silly little kid — I don't believe in that fairy-tale nonsense. But he does. And I just... wanted to cheer him up.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F24D4"
        },
        [12032323] = {
          ContentTC = "可我又不知道哪裡有蝴蝶精靈……所以……所以我就想，也許卡戎人可以用魔法變出蝴蝶精靈來……",
          DialogueId = 12032323,
          GUID = "1E1F24FE",
          NextDialogue = 12032324,
          SpeakNpcId = 211012,
          Subtitle = "Thing is, I've no idea where to find one... So I thought maybe... magic could summon one.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F24FE"
        },
        [12032324] = {
          Camera = "23.925068,57.94698,131.850098,0.000211,-1.400605,-16.076214,28.000011,121.007385,false,Manual,2.8",
          ContentTC = "原來是這樣……！",
          DialogueId = 12032324,
          FinalCamera = "39.95945,53.326424,131.442627,0.000211,-1.400605,-16.076214,28.000011,109.218246,false,Manual,2.8",
          GUID = "1E1F2528",
          NextDialogue = 12032325,
          Scripts = "PlayFacial{ActorId{100001},FacialId{\"None\"}}",
          SpeakNpcId = 211001,
          Subtitle = "I see now...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2528"
        },
        [12032325] = {
          Camera = "224.278809,-263.152527,136.943359,0.000176,-3.400635,116.920578,28.000008,274.79599,false,Manual,12.0",
          ContentTC = "哼，想笑話我就笑話吧……反正，求卡戎人幫忙已經夠丟臉了……",
          DialogueId = 12032325,
          FinalCamera = "236.240723,-286.707947,138.512939,0.000176,-3.400635,116.920578,28.000008,274.79599,false,Manual,12.0",
          GUID = "1E1F2552",
          NextDialogue = 12032326,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211012},AnimationId{"Confident_Start"},Duration{1}},
LookAt{LookAtDescription{"211012:n(211001)"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Hmph. Go ahead and laugh. Asking a Charon for help is already embarrassing enough...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2552"
        },
        [12032326] = {
          Camera = "-34.413658,253.57933,192.084717,0.000166,-17.40048,-63.677631,28.0,274.79599,false,Manual,12.0",
          ContentTC = "怎麼會丟臉呢？為朋友著想，這說明卡珊德拉小姐是個善良的人呀。每個人都會有需要別人幫忙的時候，我們互幫互助是應該的。",
          DialogueId = 12032326,
          FinalCamera = "-34.413658,253.57933,176.957031,0.000137,-13.80026,-64.077011,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F257C",
          NextDialogue = 12032327,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Why would that be embarrassing? Wanting to help a friend — that's a sign of kindness. Everyone needs help sometimes. That's what friends are for.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F257C"
        },
        [12032327] = {
          ContentTC = "咦……？",
          DialogueId = 12032327,
          GUID = "1E1F25A6",
          NextDialogue = 12032328,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Shock_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "...Huh?",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F25A6"
        },
        [12032328] = {
          Camera = "40.453804,161.041077,120.28833,0.000161,1.999504,-53.476494,28.0,274.79599,false,Manual,12.0",
          ContentTC = "讓菲娜來幫你吧，卡珊德拉小姐。我有許多的童話朋友，一定也能幫你邀請來蝴蝶精靈的！",
          DialogueId = 12032328,
          FinalCamera = "55.666523,140.499908,121.180908,0.000161,1.999504,-53.476067,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F25D0",
          NextDialogue = 12032329,
          Scripts = [[
PARA{
PlayFacial{ActorId{211001},FacialId{"Happy02"}},
PlayAnimation{ActorId{211001},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Let me help you, Miss Cassandra. I've got lots of fairy-tale friends — I'm sure one of them can help us call a Butterfly Fairy!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F25D0"
        },
        [12032329] = {
          Camera = "84.29216,-17.900318,125.307617,0.000159,-3.600363,111.523712,28.0,274.79599,false,Manual,12.0",
          ContentTC = "真的嗎……？你真的願意幫我？",
          DialogueId = 12032329,
          FinalCamera = "79.318932,-5.290113,124.455566,0.000161,-3.600329,111.523697,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F25FA",
          NextDialogue = 12032330,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Shock_End\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "Really...? You'd help me?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F25FA"
        },
        [12032330] = {
          Camera = "62.020981,146.839935,132.97998,0.000167,-1.600491,-57.275826,28.0,274.79599,false,Manual,12.0",
          ContentTC = "嗯！",
          DialogueId = 12032330,
          FinalCamera = "69.900589,134.576202,132.573242,0.000167,-1.600491,-57.275318,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2624",
          NextDialogue = 12032331,
          Scripts = "PlayAnimation{ActorId{211001},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 211001,
          Subtitle = "Mhm!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2624"
        },
        [12032331] = {
          Camera = "-27.262102,270.959961,186.104004,0.000174,-15.400416,-68.075371,28.0,274.79599,false,Manual,12.0",
          ContentTC = "那……那你要多少錢？",
          DialogueId = 12032331,
          FinalCamera = "-14.037029,238.10144,176.3479,0.000174,-15.400416,-68.075371,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F264E",
          NextDialogue = 12032332,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211012},AnimationId{"Talk02_Start"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"Blink"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Then... how much do you want?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F264E"
        },
        [12032332] = {
          Camera = "-14.037029,238.10144,176.3479,0.000174,-15.400416,-68.075371,28.000006,274.79599,false,Manual,12.0",
          ContentTC = "我不要你的錢。",
          DialogueId = 12032332,
          FinalCamera = "-20.75071,254.782547,181.300537,0.000177,-15.400416,-68.075386,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2678",
          NextDialogue = 12032333,
          Scripts = [[
SEQ{
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"DisagreeHead"},Duration{1}}
},
SEQ{
LookAt{LookAtDescription{"100001:n(211001)"}},
PlayFacial{ActorId{100001},FacialId{"Shy"}},
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I don't want any money.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2678"
        },
        [12032333] = {
          Camera = "245.334137,-220.686401,130.174316,0.000187,-1.400257,124.525352,28.000006,274.79599,false,Manual,12.0",
          ContentTC = "什麼……？那怎麼行，就算你是卡戎，我也不能白讓你幫忙。不要錢的話，你有什麼其他想要的嗎？糖果？玩偶？發卡？",
          DialogueId = 12032333,
          FinalCamera = "228.133057,-195.493896,129.428467,0.000187,-1.400257,124.325394,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F26A2",
          NextDialogue = 12032334,
          SpeakNpcId = 211012,
          Subtitle = "What...? That's not how it works. Even if you're a Charon, I can't let you help me for free. If you won't take money, then... what, candy? A doll? A hair clip?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F26A2"
        },
        [12032334] = {
          Camera = "-80.740562,151.478546,130.119385,0.00019,-2.400258,-22.474829,28.0,274.79599,false,Manual,12.0",
          ContentTC = "唔……那麼，我想要卡珊德拉小姐和我成為朋友。",
          DialogueId = 12032334,
          FinalCamera = "-57.840847,142.005096,129.080811,0.00019,-2.400258,-22.474977,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F26CC",
          NextDialogue = 12032335,
          Scripts = [[
SEQ{
PlayFacial{ActorId{211001},FacialId{"None"}},
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Um... if you really want to give me something... then I'd like you to be my friend.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F26CC"
        },
        [12032335] = {
          ContentTC = "啊？為什麼……",
          DialogueId = 12032335,
          GUID = "1E1F26F6",
          NextDialogue = 12032336,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100001:n(100001)"}},
PlayFacial{ActorId{100001},FacialId{"None"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "What? Why...?",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F26F6"
        },
        [12032336] = {
          Camera = "14.998245,105.034851,129.62207,0.000192,0.799692,-33.275356,28.0,153.150421,false,Manual,2.8",
          ContentTC = "雖然卡珊德拉小姐凶凶的、很容易生氣，但也是第一個主動和我說話的索拉之民呀！如果你能和我做朋友，我會很高興的！",
          DialogueId = 12032336,
          FinalCamera = "37.042255,90.568626,129.345703,0.000192,-0.600285,-33.27573,28.000006,117.743881,false,Manual,2.8",
          GUID = "1E1F2720",
          NextDialogue = 12032337,
          Scripts = "PlayFacial{ActorId{211001},FacialId{\"Happy01\"}}",
          SpeakNpcId = 211001,
          Subtitle = "Even though you're kind of grumpy, and not very polite... you're the first Solarian who's taken the initiative to talk to me. If we could be friends, that would make me really happy.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2720"
        },
        [12032337] = {
          Camera = "152.708511,-67.00544,132.65918,0.000203,-4.800018,110.524124,28.000006,222.0345,false,Manual,2.8",
          ContentTC = "我哪有……唔……算了，雖然不太明白這有什麼可高興的，但我可以當你的朋友。",
          DialogueId = 12032337,
          FinalCamera = "149.072327,-57.292805,131.78833,0.000203,-4.800018,110.524124,28.000006,222.0345,false,Manual,2.8",
          GUID = "1E1F274A",
          NextDialogue = 12032338,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Talk02_End\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "I'm not grum— ...Ugh, whatever. I don't really get why that would make you happy... But fine — we can be friends.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F274A"
        },
        [12032338] = {
          ContentTC = "不過你可不能到處炫耀啊，不然我也會被同學嘲笑的……",
          DialogueId = 12032338,
          GUID = "1E1F2774",
          NextDialogue = 12032339,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "Just don't go telling anyone, okay? They'd make fun of me at school...",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2774"
        },
        [12032339] = {
          Camera = "-62.638371,154.365982,124.664307,0.000202,-1.000117,-27.274698,28.000006,222.0345,false,Manual,2.8",
          ContentTC = "嗯，我會保密的！那麼，我該怎麼幫你呢？你的朋友在內城吧，我進不去那裡。",
          DialogueId = 12032339,
          FinalCamera = "-50.188278,147.94722,124.419922,0.000202,-1.000117,-27.274611,28.000006,222.0345,false,Manual,2.8",
          GUID = "1E1F279E",
          NextDialogue = 12032340,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I promise to keep it a secret! So... how do we help your friend? He's in the inner city, right? I can't get in there.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F279E"
        },
        [12032340] = {
          Camera = "196.052933,-242.947266,132.572754,0.0002,-1.600218,114.924568,28.0,153.150421,false,Manual,12.0",
          ContentTC = "三天後我們學校有活動，老師會帶我們一起到蓋雷亞劇院看歌劇。到時候我帶朋友偷偷溜出來找你！我們就在水仙平原旁邊那條通道碰頭吧。",
          DialogueId = 12032340,
          FinalCamera = "221.301102,-297.276489,134.245605,0.000202,-1.600183,114.924568,28.000006,220.298309,false,Manual,12.0",
          GUID = "1E1F27C8",
          NextDialogue = 12032341,
          SpeakNpcId = 211012,
          Subtitle = "In three days, our school's going to the Galea Theatre for an event. I'll sneak out with him then — meet us in the alley next to The Asphodel.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F27C8"
        },
        [12032341] = {
          ContentTC = "好呀，那我這幾天就開始研究邀請蝴蝶精靈的魔法。",
          DialogueId = 12032341,
          GUID = "1E1F27F2",
          NextDialogue = 12032342,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Explain02_Start"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Sounds perfect! I'll spend the next few days working on my magic — see if I can really summon a Butterfly Fairy!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F27F2"
        },
        [12032342] = {
          ContentTC = "那就說好了，不許反悔喔！誰反悔誰是小狗！",
          DialogueId = 12032342,
          GUID = "1E1F281C",
          SpeakNpcId = 211012,
          Subtitle = "It's a deal, then. No backsies!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F281C"
        },
        [12032343] = {
          ContentTC = "卡珊德拉離開",
          DialogueId = 12032343,
          GUID = "1E1F2846",
          Subtitle = "Cassandra walks away",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2846"
        },
        [12032351] = {
          Camera = "201.226318,92.827713,126.989258,0.000148,-2.401201,-134.690414,35.000008,260.417267,false,DoNotOverride,2.8",
          ContentTC = "菲娜真厲害，我還時刻準備著幫你出頭，沒想到你自己就把事情處理好了。",
          DialogueId = 12032351,
          FinalCamera = "169.578476,81.812721,126.355713,0.000155,-2.401173,-137.092133,35.000008,227.412735,false,DoNotOverride,3.8",
          GUID = "1E1F2996",
          LookAt = {
            [1] = "100001:n(211001)",
            [2] = "211001:n(100001)"
          },
          NextDialogue = 12032352,
          Scripts = [[
PARA{
PlayFacial{ActorId{100001},FacialId{"Smile01"}},
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Talk02_Start"}},
PlayAnimation{_delay{3},ActorId{100001},AnimationId{"Talk02_End"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Fina, that was impressive. I was ready to step in if things got ugly, but you handled it all on your own.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100001:n(211001)",
            [2] = "211001:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2996"
        },
        [12032352] = {
          Camera = "-55.655048,-51.176369,132.258789,0.000171,-4.801452,17.104628,35.000008,225.70079,false,DoNotOverride,12.0",
          ContentTC = "嘿嘿，就是因為獨角獸{性别:先生|小姐}在我身邊，我才有勇氣呀。",
          DialogueId = 12032352,
          FinalCamera = "-33.694485,-48.090378,130.718506,0.000171,-4.401305,19.904659,35.000008,225.70079,false,DoNotOverride,12.0",
          GUID = "1E1F29C0",
          NextDialogue = 12032353,
          Scripts = [[
PARA{
PlayFacial{ActorId{211001},FacialId{"Happy02"}},
SEQ{
PlayAnimation{ActorId{211001},AnimationId{"Shy02_Start"}},
PlayAnimation{_delay{5},ActorId{211001},AnimationId{"Shy02_End"}},
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Hehe... That's only because you were there for me. You gave me the courage, {性别:Mr|Miss} Unicorn!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F29C0"
        },
        [12032353] = {
          Camera = "71.708511,57.871662,139.033203,0.000193,-4.801329,-123.692604,35.000008,102.017906,false,DoNotOverride,12.0",
          ContentTC = "不過，和索拉之民打交道還是要謹慎一些……三天後我也和你一起去吧。菲娜只管做自己想做的事，其他的就交給我這個「保鏢」好了。",
          DialogueId = 12032353,
          FinalCamera = "57.958427,31.498777,136.702637,0.000196,-3.801266,-123.892723,35.000008,102.017906,false,DoNotOverride,12.0",
          GUID = "1E1F29EA",
          NextDialogue = 12032354,
          Scripts = [[
PARA{
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"Think01"}},
PlayAnimation{_delay{6},ActorId{100001},AnimationId{"Think_End"},Duration{1}}
},
SEQ{
CameraMoveTo{_delay{10.01},TargetPosition{"197.601944,102.248795,131.728516,0.000197,-4.201324,-130.892929,35.000008,300.145172,false,DoNotOverride,12.0"},duration{0}},
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Confident_Start"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"Confident01"}}
}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Still — best stay cautious around Solarians. I'll come with you when we meet them. You just focus on doing what you have to do — leave the rest to your trusty \"bodyguard.\"",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F29EA"
        },
        [12032354] = {
          Camera = "-32.313416,-47.220013,131.783447,0.000189,-4.601532,19.305601,35.000008,216.250549,false,DoNotOverride,12.0",
          ContentTC = "好呀！那麼，獨角獸{性别:先生|小姐}，我們三天後再見！我要抓緊時間回家練習魔法啦。",
          DialogueId = 12032354,
          FinalCamera = "-21.076063,-43.138649,130.895264,0.000188,-4.201529,20.105637,35.000008,216.250549,false,DoNotOverride,12.0",
          GUID = "1E1F2A14",
          Scripts = [[
PARA{
PlayFacial{ActorId{211001},FacialId{"Smile01"}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"}},
SEQ{
PlayAnimation{ActorId{211001},AnimationId{"Explain02_Start"}},
PlayAnimation{_delay{5},ActorId{211001},AnimationId{"Explain02_End"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Okay! Thank you, {性别:Mr|Miss} Unicorn! I'd better head home and start practising the spell. See you soon!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2A14"
        },
        [12032355] = {
          ContentTC = "解鎖並完成玩法第三關",
          DialogueId = 12032355,
          GUID = "1E1F2A3E",
          Subtitle = "Third mini-game unlocks. Completes the game to proceed.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2A3E"
        },
