        [12033006] = {
          Camera = "-181.509048,147.714844,149.226562,0.000195,-13.278214,93.431587,35.0,104.654732,false,Manual,2.8",
          ContentTC = "那是很久以前，我還住在一座大宅邸裡的時候的事。塞維歐的媽媽也是我的媽媽，塞維歐的爸爸，是……嗚……",
          DialogueId = 12033006,
          FinalCamera = "-87.040627,199.931641,112.960938,0.000192,4.52222,147.628799,35.0,104.654732,false,Manual,2.8",
