        },
        [12033902] = {
          Camera = "142.19931,-3.867684,97.571289,0.0001,-0.400755,86.011314,25.0,215.530014,false,Manual,4.0",
          ContentTC = "嗯，多虧了勇敢的菲娜呢。",
          DialogueId = 12033902,
          GUID = "1E20280C",
          NextDialogue = 12033903,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain01_Start\"}}",
          SpeakNpcId = 100001,
          Subtitle = "And it's all thanks to our brave little Fina.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20280C"
        },
        [12033903] = {
          Camera = "142.19931,-3.867684,97.571289,0.0001,-0.400755,86.011314,25.0,215.530014,false,Manual,4.0",
          ContentTC = "嘿嘿。",
          DialogueId = 12033903,
          FinalCamera = "142.19931,-3.867684,97.571289,0.0001,-0.400755,86.011314,25.0,215.530014,false,Manual,4.0",
