          SpeakNpcId = 211001,
          Subtitle = "Hehe...",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E202836"
        },
        [12033904] = {
          Camera = "-100.202446,59.787457,96.332031,0.000163,-4.201693,15.000897,25.0,390.397339,false,Manual,4.0",
          ContentTC = "塞維歐……你還好嗎？",
          DialogueId = 12033904,
          GUID = "1E202860",
          NextDialogue = 12033905,
          Scripts = [[
PARA{
LookAt{_delay{0},LookAtDescription{"211001:n(211015)"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Feina_Story_Wish_End"}},
PlayAnimation{_delay{0},ActorId{100001},AnimationId{"Explain01_End"}},
LookAt{_delay{0},LookAtDescription{"100001:n(211015)"}},
}]],
          SpeakNpcId = 211001,
          Subtitle = "Savio... are you alright?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E202860"
        },
        [12033905] = {
          Camera = "77.939064,65.692757,77.285156,0.000161,6.997931,155.598511,25.0,86.749496,false,Manual,4.0",
          ContentTC = "你——你就是塞拉菲娜姐姐，對不對？雖然你的頭髮變成藍色了，但是我認得出來！",
          DialogueId = 12033905,
          GUID = "1E20288A",
          NextDialogue = 12033906,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/1_0/0087_feina_activiy_story_01"}},
PlayFacial{ActorId{211015},FacialId{"Smile01"}},
PlayAnimation{_delay{0},ActorId{211015},AnimationId{"Explain02_Start"}}
}]],
          SpeakNpcId = 211015,
          Subtitle = "Y—You're Serafina... right? Your hair's blue now... but I remember your face!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20288A"
        },
        [12033906] = {
          Camera = "-26.948053,81.611237,83.803711,0.000156,-0.802212,7.594927,25.0,190.125488,false,Manual,4.0",
          ContentTC = "我……",
          DialogueId = 12033906,
          GUID = "1E2028B4",
          NextDialogue = 12033907,
          Scripts = [[
PARA{
PlayFacial{ActorId{211001},FacialId{"Sad01"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Shy02_Start"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2028B4"
        },
        [12033907] = {
          Camera = "188.955719,28.82197,97.71875,0.000149,-6.802458,149.992783,25.0,190.125488,false,Manual,4.0",
          ContentTC = "我還認得這隻蝴蝶……那一天，我找不到爸爸媽媽的時候，飛到我身邊來的蝴蝶精靈……就和它長得一模一樣。",
          DialogueId = 12033907,
          GUID = "1E2028DE",
          NextDialogue = 12033908,
          Scripts = "PlayFacial{ActorId{211001},FacialId{\"CM_Idle\"}},",
          SpeakNpcId = 211015,
          Subtitle = "And... this butterfly... The Butterfly Fairies that came when I couldn't find Mum and Dad all looked like this one.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2028DE"
        },
        [12033908] = {
          ContentTC = "我想起來了，塞拉菲娜姐姐，那一天你也在院子裡。是你變出了蝴蝶精靈來陪我玩，對不對？",
          DialogueId = 12033908,
          GUID = "1E202908",
          NextDialogue = 12033909,
          Scripts = "PlayAnimation{_delay{0},ActorId{211015},AnimationId{\"Explain02_End\"}}",
          SpeakNpcId = 211015,
          Subtitle = "I remember now — you were in the garden that day, too. You summoned the Butterfly Fairies to comfort me, didn't you?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E202908"
        },
        [12033909] = {
          Camera = "45.257626,67.690178,92.338867,0.000179,2.997155,-0.205472,35.0,119.632339,false,Manual,4.0",
          ContentTC = "……是的，塞維歐，是我。但是，我現在的名字是菲娜。",
          DialogueId = 12033909,
          GUID = "1E202932",
          NextDialogue = 12033910,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Shy02_End"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Explain02_Start"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "...Yes, Savio, that was me. But my name is Fina now.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E202932"
        },
        [12033910] = {
          Camera = "33.587769,17.520916,86.75293,0.000189,2.596879,109.192482,35.0,89.251617,false,Manual,4.0",
          ContentTC = "原來，那個時候，我不是一個人……謝謝你，塞——菲娜姐姐！可是你後來為什麼走了？你能回來嗎？",
          DialogueId = 12033910,
          GUID = "1E20295C",
          NextDialogue = 12033911,
          SpeakNpcId = 211015,
          Subtitle = "So I wasn't alone after all... Thank you, Se— I mean, Fina! But... why did you leave? Will you come back home?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20295C"
        },
        [12033911] = {
          Camera = "140.553329,-25.305544,97.136719,0.000184,0.796673,84.192825,35.0,89.251617,false,Manual,4.0",
          ContentTC = "因為我是一個卡戎人……那座大宅邸不歡迎我，所以我必須離開，而且不能回去。不過，我現在也找到了一個新的家，你不用擔心。",
          DialogueId = 12033911,
          GUID = "1E202986",
          NextDialogue = 12033912,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Explain02_End"}},
LookAt{LookAtDescription{"100001:n(211001)"}},
SEQ{
PlayFacial{ActorId{100001},FacialId{"Sad02"}},
PlayAnimation{_delay{5},ActorId{100001},AnimationId{"Explain02_Start"}},
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Because I'm a Charon... That mansion didn't have room for someone like me. I had to leave — I can't go back. But I have a new home now. Don't worry about me.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E202986"
        },
        [12033912] = {
          Camera = "-121.710831,53.883701,100.163086,0.00019,-4.003509,10.785311,35.0,286.216858,false,Manual,6.0",
          ContentTC = "那……那你知道爸爸媽媽去哪裡了嗎？為什麼他們不回來了？",
          DialogueId = 12033912,
          GUID = "1E2029B0",
          NextDialogue = 12033913,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_End\"}},",
          SpeakNpcId = 211015,
          Subtitle = "Then... do you know where Mum and Dad went? Why haven't they come home?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2029B0"
        },
        [12033913] = {
          ContentTC = "他們……嗚……",
          DialogueId = 12033913,
          GUID = "1E2029DA",
          NextDialogue = 12034001,
          Scripts = [[
PARA{
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Sad01"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Shy01_Start"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "They... they... *sniffles*",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2029DA"
        },
        [12033914] = {
          ContentTC = "主角走過來解圍",
          DialogueId = 12033914,
          GUID = "1E202A04",
          Subtitle = "The protagonist steps in",
          VoiceName = "voice/$Locale$/story/1201/120114/1E202A04"
        },
        [12034001] = {
          Camera = "139.785004,247.222656,148.624023,0.000206,-19.804255,-119.814819,25.0,286.216858,false,Manual,6.0",
          ContentTC = "塞維歐，我來告訴你吧，我知道他們去哪裡了。",
          DialogueId = 12034001,
          GUID = "1E20384A",
          NextDialogue = 12034002,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211015)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(100001)"}},
LookAt{_delay{0},LookAtDescription{"211015:n(100001)"}},
MoveTo{ActorId{100001},TargetPoint{"nvzhu_feina_37_walk"},MoveSpeed{100},Visibility{"Show"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Let me explain. I know where your parents went, Savio.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20384A"
        },
        [12034002] = {
          Camera = "-60.111835,138.167587,81.243164,0.000218,5.395651,-9.014689,25.0,255.333679,false,Manual,6.0",
          ContentTC = "這個世界上有一個我們看不見的可怕怪物，叫做「偏見」……它會讓本應相親相愛的人們互相憎惡、互相傷害。你們的爸爸媽媽就是被它帶走了。",
          DialogueId = 12034002,
          GUID = "1E203874",
          NextDialogue = 12034003,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_Start\"}}",
          SpeakNpcId = 100001,
          Subtitle = "There's a terrifying monster in this world — one we can't see. It's called Prejudice. It makes people who should care about each other hate and hurt one another. That's what took your mum and dad.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E203874"
        },
        [12034003] = {
          Camera = "116.961861,174.154648,120.447266,0.000223,-16.204643,-136.614212,25.0,255.333679,false,Manual,6.0",
          ContentTC = "那我要去把他們救回來！",
          DialogueId = 12034003,
          GUID = "1E20389E",
          NextDialogue = 12034004,
          Scripts = "PlayAnimation{_delay{0},ActorId{211015},AnimationId{\"Angry01_Start\"}}",
          SpeakNpcId = 211015,
          Subtitle = "Then I'll go fight it and bring them back!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20389E"
        },
        [12034004] = {
          Camera = "-29.829901,107.802788,74.746094,0.00025,12.194851,5.783125,25.000002,153.736694,false,Manual,6.0",
          ContentTC = "現在你還太小了，而且，那不是靠一個人就能打敗的敵人。",
          DialogueId = 12034004,
          GUID = "1E2038C8",
          NextDialogue = 12034005,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Explain02_End\"}}",
          SpeakNpcId = 100001,
          Subtitle = "You're brave — but you're still young. And Prejudice isn't a monster you can punch away.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2038C8"
        },
        [12034005] = {
          ContentTC = "因為那個可怕的怪物是靠吸食人們的信念長大的，現在這座城市裡有太多人受到它的蠱惑，成為了它的僕從，讓它變得很強很強。",
          DialogueId = 12034005,
          GUID = "1E2038F2",
          NextDialogue = 12034006,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Talk02_Start\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Because it feeds on people's doubts and fears. And it's grown strong because so many in this city have fallen under its spell.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2038F2"
        },
        [12034006] = {
          Camera = "159.328293,-18.95005,85.956055,0.00025,5.194987,100.784615,25.000002,138.543365,false,Manual,6.0",
          ContentTC = "但只要你不相信它、我不相信它，我們再告訴我們的朋友，讓大家一起勇敢起來，拒絕它的蠱惑……那麼它的力量就會變得越來越弱。",
          DialogueId = 12034006,
          GUID = "1E20391C",
          NextDialogue = 12034007,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211001)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(100001)"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"AgreeHead"}},
PlayFacial{ActorId{211001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "But if we choose not to believe in it — if you don't, and I don't — and if we help our friends to be brave enough to fight its spell... then little by little, it'll lose its power.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20391C"
        },
        [12034007] = {
          Camera = "45.170029,149.59169,119.630859,0.000216,-11.604067,-24.416609,25.0,163.981354,false,Manual,6.0",
          ContentTC = "然後，總有一天，它會徹底消失，再也不會有人被它帶走。",
          DialogueId = 12034007,
          GUID = "1E203946",
          NextDialogue = 12034008,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211015)"}},
LookAt{_delay{0},LookAtDescription{"211001:n(211015)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "And one day, when enough people stand against it... that monster will disappear. No one will be taken again.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E203946"
        },
        [12034008] = {
          ContentTC = "到那個時候，爸爸媽媽就會回來了嗎？",
          DialogueId = 12034008,
          GUID = "1E203970",
          NextDialogue = 12034009,
          Scripts = "PlayAnimation{_delay{0},ActorId{211015},AnimationId{\"Angry01_End\"}}",
          SpeakNpcId = 211015,
          Subtitle = "When that happens... will Mum and Dad come back?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E203970"
        },
        [12034009] = {
          Camera = "233.281982,106.357674,119.521484,0.000222,-13.803983,-176.218384,22.0,253.785858,false,Manual,6.0",
          ContentTC = "到那個時候……你就會擁有很多朋友、很多幸福和愛，即便爸爸媽媽不在，你也能好好地生活下去。",
          DialogueId = 12034009,
          GUID = "1E20399A",
          NextDialogue = 12034010,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Talk02_End\"}}",
          SpeakNpcId = 100001,
          Subtitle = "By then, you'll have many friends and a heart full of love and hope. Even if your parents don't return, you'll never be alone — you'll still have a good life.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20399A"
        },
        [12034010] = {
          Camera = "85.880272,91.637543,126.474609,0.000195,-26.403782,175.779465,22.0,117.791931,false,Manual,22.0",
          ContentTC = "唔……",
          DialogueId = 12034010,
          FinalCamera = "71.9813,92.660332,119.553711,0.000195,-26.403761,175.779602,22.0,117.791931,false,Manual,22.0",
          GUID = "1E2039C4",
          NextDialogue = 12034011,
          Scripts = [[
PARA{
LookAt{_delay{0},LookAtDescription{"211015:n(211015)"}},
PlayFacial{ActorId{211015},FacialId{"CM_Sad01"}}
}]],
          SpeakNpcId = 211015,
          Subtitle = "Umm...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2039C4"
        },
        [12034011] = {
          ContentTC = "那麼……菲娜也要到那個時候才能重新變成我的姐姐嗎？",
          DialogueId = 12034011,
          GUID = "1E2039EE",
          NextDialogue = 12034012,
          Scripts = [[
PARA{
LookAt{_delay{0},LookAtDescription{"211015:n(211001)"}},
PlayFacial{ActorId{211015},FacialId{"CM_Idle"}}
}]],
          SpeakNpcId = 211015,
          Subtitle = "...So does Fina have to wait until then to be my big sister again?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E2039EE"
        },
        [12034012] = {
          Camera = "-48.437469,142.583008,78.972656,0.000206,6.394313,-16.618864,22.0,218.840088,false,Manual,6.0",
          ContentTC = "嗯，我想是的……不過，在那之前，我可以當你的朋友——就像我和卡珊德拉小姐是朋友一樣！",
          DialogueId = 12034012,
          GUID = "1E203A18",
          NextDialogue = 12034013,
          Scripts = [[
PARA{
LookAt{_delay{0},LookAtDescription{"211015:n(211001)"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"AgreeHead"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Yeah, I think so... But until that day comes, I can be your friend — just like I'm friends with Miss Cassandra!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E203A18"
        },
        [12034013] = {
          Camera = "193.77005,92.50441,93.731445,0.000228,-8.205721,-167.416855,22.000006,201.064499,false,Manual,6.0",
          ContentTC = "卡珊德拉？",
          DialogueId = 12034013,
          GUID = "1E203A42",
          SpeakNpcId = 211015,
          Subtitle = "Cassandra...?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E203A42"
        },
        [12034014] = {
          ContentTC = "卡珊德拉和若乾帝國兵出現",
          DialogueId = 12034014,
          GUID = "1E203A6C",
          Subtitle = "Cassandra enters the frame with a group of Imperial soldiers",
          VoiceName = "voice/$Locale$/story/1201/120114/1E203A6C"
        },
        [12034101] = {
          Camera = "-205.291214,228.958771,119.550781,0.000071,-1.759341,11.196725,40.0,130.993866,false,Manual,5.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "所有人不許動，我們是治安署的！",
          DialogueId = 12034101,
          FinalCamera = "-205.172699,263.595032,126.101562,0.000074,-5.759399,3.396292,40.0,595.173035,false,Manual,5.0",
          GUID = "1E2048B2",
          LookAt = {
            [1] = "211015:n(100001)",
            [2] = [[

211001:n(100001)]]
          },
          NextDialogue = 12034102,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"100001:n(211012)\"}}",
          SpeakNpcName = "UI_FNNpc_Name_SoldierPSD",
          Subtitle = "Nobody move! Security Bureau!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2048B2"
        },
        [12034102] = {
          Camera = "986.973083,1585.42395,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
          CameraBlendCurve = "easeOutQuad",
          ContentTC = "嗯……？這些強盜……已經被製服了？",
          DialogueId = 12034102,
          FinalCamera = "977.238586,1591.515625,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
          GUID = "1E2048DC",
          NextDialogue = 12034103,
          SpeakNpcName = "UI_FNNpc_Name_SoldierPSD",
          Subtitle = "Wait... these bandits are already down?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E2048DC"
        },
        [12034103] = {
          Camera = "483.208221,510.672333,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "是的，我們是卡珊德拉小姐雇傭的狩月人，已經把強盜打倒了。",
          DialogueId = 12034103,
          FinalCamera = "486.036987,505.621124,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
          GUID = "1E204906",
          NextDialogue = 12034104,
          Scripts = [[
SEQ{
