PlayAnimation{_delay{3},ActorId{211001},AnimationId{"TilteHead_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Outsider, you're back! These are my new friends — come meet them!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AE16"
        },
        [12034720] = {
          Content = "下面这段茶会剧情希望能用动画的形式制作，但并不需要额外动作资源，打一个慢慢移动的全景镜头，五个角色站在一起做说话动作即可（效果不好的话也可以打空镜头放个暖色灯光）\n角色台词不显示在对话框里，作为背景音播放，每两句一组",
          DialogueId = 12034720,
          GUID = "1E20AE40",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AE40"
        },
        [12034801] = {
          ContentTC = "大魔法狗是什麼？",
          DialogueId = 12034801,
          GUID = "1E20BB8A",
          NextDialogue = 12034802,
          SpeakNpcId = 211012,
          Subtitle = "What's a MagicMutt?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BB8A"
        },
        [12034802] = {
          ContentTC = "是大魔法師哦。",
          DialogueId = 12034802,
          GUID = "1E20BBB4",
          NextDialogue = 12034803,
          SpeakNpcId = 211001,
          Subtitle = "No no — he's the Great Magician!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BBB4"
        },
        [12034803] = {
          ContentTC = "咳、咳……",
          DialogueId = 12034803,
          GUID = "1E20BBDE",
          NextDialogue = 12034804,
          SpeakNpcId = 211015,
          Subtitle = "*coughs*",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BBDE"
        },
        [12034804] = {
          ContentTC = "沒事吧？快喝點水——",
          DialogueId = 12034804,
          GUID = "1E20BC08",
          NextDialogue = 12034805,
          SpeakNpcId = 100001,
          Subtitle = "You okay? Here, drink some water.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BC08"
        },
        [12034805] = {
          ContentTC = "啾啾，白鳥先生！",
          DialogueId = 12034805,
          GUID = "1E20BC32",
          NextDialogue = 12034806,
          SpeakNpcId = 211001,
          Subtitle = "Chirp-chirp, I'm Mr White Bird!",
