          GUID = "1E20BC5C",
          SpeakNpcId = 211002,
          Subtitle = "Whoa, he's a big guy for sure...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BC5C"
        },
        [12034807] = {
