            [2] = "200002:n(200024)"
          },
          NextDialogue = 20000602,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Awesome! You're truly amazing!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C49A"
        },
        [20000602] = {
          Camera = "-160.725159,-13.358643,119.220985,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
          ContentTC = "說起來，我在路上也看到了和白，還有鐵匠前輩長得很相似的人。她們也是<H>皎皎</>嗎？",
          DialogueId = 20000602,
          Duration = 2,
          ExStoryInfo = "Player",
          FinalCamera = "-174.055298,-12.71582,117.098991,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
          GUID = "3211C4C4",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000603,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.6},TargetPosition{"-275.118378,-120.86499,74.379753,0.000004,3.39987,31.806273,25.0,279.088654,false,Manual,1.419143"},duration{0}},
CameraMoveTo{_delay{4.7},TargetPosition{"-287.599518,-128.604248,69.15966,0.000004,3.39987,31.807192,25.0,279.088654,false,Manual,1.419143"},duration{4}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I've seen many who resemble you and Snow. Are they also Lunos?",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C4C4"
        },
        [20000603] = {
          Camera = "-4.034668,-120.357422,84.402077,0.00001,-0.800252,111.203094,25.0,279.088654,false,Manual,4.45866",
          ContentTC = "年輕人，你是不是從什麼偏僻地方來的？",
          DialogueId = 20000603,
          Duration = 3,
          GUID = "3211C4EE",
          NextDialogue = 20000604,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Did you come from a remote village or something, kiddo?",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C4EE"
        },
        [20000604] = {
          Camera = "172.062653,-1154.075806,143.87851,0.0,0.0,89.999985,25.0,200.0,false,Disable,2.8",
          ContentTC = "是的……我的故鄉確實不算繁華。",
          DialogueId = 20000604,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          FinalCamera = "172.062653,-1154.075806,164.062302,-0.0,-0.999987,89.999985,25.0,200.0,false,Disable,2.8",
          GUID = "3211C518",
          NextDialogue = 20000605,
          SpeakNpcId = 100001,
          Subtitle = "Yes, my hometown isn't a big city.",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C518"
        },
        [20000605] = {
          Camera = "375.018433,-82.650635,97.525391,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
          ContentTC = "哈哈，難怪，難怪。畢竟在老朽走過的地方啊，有人類的地方就有皎皎。像你這樣沒見過我們一族的孩子，已經不多啦。",
          DialogueId = 20000605,
          Duration = 1.5,
          FacialId = {
            [1] = "200024:Ahaha02"
          },
          FinalCamera = "356.082672,-77.70874,94.312401,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
          GUID = "3211C542",
          NextOptions = {
            [1] = 200006051
          },
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Ha, that explains it. In all my travels, wherever there are humans, Lunos can always be found. It's quite uncommon to come across someone like you who's never heard of us.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C542"
        },
        [20000606] = {
          Camera = "155.926254,-348.624268,84.660477,0.0,-0.799986,116.795898,25.0,200.0,false,Disable,2.8",
          ContentTC = "我們皎皎之民呀，每個人都和白長得一樣可愛，而且擁有很長的壽命。",
          DialogueId = 20000606,
          Duration = 3,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "3211C56C",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)",
            [3] = "200024:n(200002)"
          },
          NextDialogue = 20000607,
          SpeakNpcId = 200002,
          Subtitle = "We share a similar appearance. Everyone is as attractive as me. And we live very long lives.",
          TurnTo = {
