          GUID = "3211C692",
          NextDialogue = 20000614,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Oh... that's quite the ambition.",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C692"
        },
        [20000614] = {
          Camera = "-147.118195,-74.93335,97.300194,0.000344,-2.603818,35.809223,50.0,210.030212,false,Manual,5.267603",
          ContentTC = "唉，普通皎皎確實沒什麼野心，她們就喜歡跟著人類，只要得到人類的誇獎就會開心得轉圈……但對白來說，這可遠遠不夠！",
          DialogueId = 20000614,
          Duration = 3,
          FacialId = {
            [1] = "200002:Syouganai01"
          },
          GUID = "3211C6BC",
          NextDialogue = 20000615,
          SpeakNpcId = 200002,
          Subtitle = "Unfortunately, most Lunos lack ambition. They'd rather follow the humans, and are content with just a few words of appreciation. But for me, I want so much more!",
          TalkActionId = {
