          DialogueId = 20000816,
          DisableMouth = 1,
          Duration = 3,
          FinalCamera = "-365.830078,-139.029053,130.748047,0.000005,-3.600124,20.403618,30.0,235.397522,false,Manual,2.018788",
          GUID = "3211E7E0",
          LookAt = {
