        [20004501] = {
          ContentTC = "我最親愛的孩子，謝謝你來到世界上。",
          DialogueId = 20004501,
          Duration = 4,
          GUID = "32144472",
          NextDialogue = 20004502,
          SnapShot = "HEART",
          Subtitle = "My dearest child, thank you for coming into the world.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA87"
        },
        [20004502] = {
          ContentTC = "你是我們一生的驕傲。",
          DialogueId = 20004502,
          Duration = 3,
          GUID = "3214449C",
          NextDialogue = 20004503,
          SnapShot = "HEART",
          Subtitle = "You are the pride of our lives.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA88"
        },
        [20004503] = {
          ContentTC = "賽琪，來拉鉤，我們要做一輩子的好朋友！",
          DialogueId = 20004503,
          Duration = 5,
          GUID = "321444C6",
          NextDialogue = 20004504,
          SnapShot = "HEART",
          Subtitle = "Psyche, pinky promise. We'll be best friends for life!",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA89"
        },
        [20004504] = {
          ContentTC = "我會記住你曾經活過。",
          DialogueId = 20004504,
          Duration = 3,
          GUID = "321444F0",
          NextDialogue = 20004505,
          SnapShot = "HEART",
          Subtitle = "I'll remember that you've lived in this world.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA90"
        },
        [20004505] = {
          ContentTC = "我們等你回來。",
          DialogueId = 20004505,
          Duration = 3,
          GUID = "3214451A",
          NextDialogue = 20004506,
          SnapShot = "HEART",
          Subtitle = "We'll wait for your return.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA91"
        },
        [20004506] = {
          ContentTC = "命運啊，求你憐憫我唯一一次，讓我幫她實現這個願望吧。",
          DialogueId = 20004506,
          Duration = 5,
          GUID = "32144544",
          NextDialogue = 20004507,
          SnapShot = "HEART",
          Subtitle = "Fate, please have mercy on me. Let me help her fulfil this wish.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA92"
        },
        [20004507] = {
          ContentTC = "帶上這朵花吧，它會給你帶來好運。",
          DialogueId = 20004507,
          Duration = 4,
          GUID = "3214456E",
          NextDialogue = 20004508,
          SnapShot = "HEART",
          Subtitle = "Take this flower with you. It will bring you good luck.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA93"
        },
        [20004508] = {
