          SpeakNpcId = 200074,
          Subtitle = "Oh! Speaking of which, we've got bad guys to catch! Icelake is WAY bigger than I expected — we need to hurry!",
          VoiceName = "voice/$Locale$/story/2001/200057/32150C9A"
        },
        [20005722] = {
          Camera = "345.16864,317.928711,137.46875,-0.000763,1.607089,136.417633,35.0,169,false,Manual,12.0",
          ContentTC = "你有頭緒嗎？",
          DialogueId = 20005722,
          FinalCamera = "311.653595,331.706055,134.34375,-0.000763,4.806766,132.015808,35.0,169.08606,false,Manual,12.0",
          GUID = "32150CC4",
          NextDialogue = 20005723,
          SpeakNpcId = 100001,
          Subtitle = "Do you have any idea?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150CC4"
        },
        [20005723] = {
          Camera = "427.671539,393.154297,128.347656,-0.000763,-6.992433,-162.983078,35.000008,216.630737,false,Manual,12.0",
          ContentTC = "我有頭豬──可靠的榛子。它嗅覺可靈敏啦，可以聞到附近魔靈們在哪裡出沒，應該能在附近逮到那些魔靈獵人!",
          DialogueId = 20005723,
          FinalCamera = "427.671539,393.154297,128.347656,-0.000763,-8.192443,-154.983536,35.000008,216.630737,false,Manual,12.0",
          GUID = "32150CEE",
          LookAt = {
            [1] = "200074:n(200086)"
          },
          Scripts = [[
PARA{
PlayFacial{_delay{2.1},ActorId{200074},FacialId{"Happy01"}},
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{"Confident_Start"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "I have my dear — Filbert! Filbert's nose is incredible — she can sniff out Geniemons from miles away! And those bad hunters must be around!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200074:p(45)"
          },
          VoiceName = "voice/$Locale$/story/2001/200057/32150CEE"
        },
        [20005801] = {
          ContentTC = "走吧，先往高處走，魔靈的氣味更容易傳到高處。",
          DialogueId = 20005801,
          GUID = "321519BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Alright, let's go higher. The scent spreads farther up there.",
          VoiceName = "voice/$Locale$/story/2001/200058/321519BA"
        },
        [20005802] = {
          ContentTC = "啊，榛子聞到了，在那裡！",
          DialogueId = 20005802,
          GUID = "321519E4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Oh! Filbert's onto something — over there!",
          VoiceName = "voice/$Locale$/story/2001/200058/321519E4"
        },
        [20005803] = {
          ContentTC = "是這裡……但沒有魔靈，只有……",
          DialogueId = 20005803,
          GUID = "32151A0E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "This should be the place. Strange, I don't see any Geniemons but—",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A0E"
        },
        [20005804] = {
          ContentTC = "這是他們陷阱的痕跡，好可惡，他們應該已經走了。",
          DialogueId = 20005804,
          GUID = "32151A38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005805,
          SpeakNpcId = 200074,
          Subtitle = "The trap they set up! Those baddies must have been here moments ago.",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A38"
        },
        [20005805] = {
          ContentTC = "那接下來我們去人少一點的地方，氣味會明顯一些。",
          DialogueId = 20005805,
          GUID = "32151A62",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Alright, let's try somewhere quieter. The scent will stand out more where there are fewer people.",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A62"
        },
        [20005901] = {
          ContentTC = "這裡這裡，{性别:大哥哥|大姐姐}別著急，慢點一點走，別滑倒啦。",
          DialogueId = 20005901,
          GUID = "32152A22",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "This way! Careful, {性别:Sir|Miss} — it's slippery here.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A22"
        },
        [20005902] = {
          ContentTC = "呃……這裡也是一樣，有人佈設過陷阱。",
          DialogueId = 20005902,
          GUID = "32152A4C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005903,
          SpeakNpcId = 200074,
          Subtitle = "Ugh... Another trap here.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A4C"
        },
        [20005903] = {
          ContentTC = "哼唧……",
          DialogueId = 20005903,
          GUID = "32152A76",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005904,
          SpeakNpcId = 200086,
          Subtitle = "Oink...",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A76"
        },
        [20005904] = {
          ContentTC = "榛子別喪氣，我們再試試下一處地方。",
          DialogueId = 20005904,
          GUID = "32152AA0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "It's okay, Filbert. Let's try another spot.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152AA0"
        },
        [20006001] = {
          Camera = "606.297791,-918.271484,784.640625,0.000207,-7.459188,79.056267,35.000015,174.116943,false,Manual,12.0",
          ContentTC = "這裡是……下水道入口？",
          DialogueId = 20006001,
          FinalCamera = "541.89978,-1160.757812,832.416992,0.000208,-8.459162,77.455727,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153A8A",
          NextDialogue = 20006002,
          SpeakNpcId = 100001,
          Subtitle = "Is this... the entrance to the sewers?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153A8A"
        },
        [20006002] = {
          Camera = "-38.9104,-306.495117,391.232422,0.000209,-8.45895,-1.344757,35.000015,174.116943,false,Manual,12.0",
          ContentTC = "嗯，這附近有很多水汽，而又沒什麼人，一定會有魔靈出沒的。",
          DialogueId = 20006002,
          FinalCamera = "-508.082397,-300.290039,450.730469,0.000209,-7.058932,-0.744781,35.000019,174.116943,false,Manual,12.0",
          GUID = "32153AB4",
          NextDialogue = 20006003,
          SpeakNpcId = 200074,
          Subtitle = "Yes. The water vapor and quietness here make this a perfect spot for Geniemons.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153AB4"
        },
        [20006003] = {
          Camera = "-768.485962,-608.558594,293.948242,0.000155,-2.058947,167.054123,35.000015,174.116943,false,Manual,12.0",
          ContentTC = "不過，剛剛那兩處地方的魔靈都被抓走了，有點擔心這裡也……",
          DialogueId = 20006003,
          FinalCamera = "-796.652222,-602.085938,292.908691,0.000155,-0.458948,167.453751,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153ADE",
          NextDialogue = 20006004,
          SpeakNpcId = 200074,
          Subtitle = "But... the two previous spots were already wiped clean. I've got a bad feeling about this one too...",
          TalkActionId = {
            [1] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153ADE"
        },
        [20006004] = {
          Camera = "-913.889771,-785.241211,282.312012,0.000156,-6.059081,28.454039,35.000015,174.116943,false,Manual,12.0",
          ContentTC = "啊，是還沒被收走的陷阱！裡面還有一隻魔靈！",
          DialogueId = 20006004,
          FinalCamera = "-932.27832,-741.113281,282.15332,0.000157,-6.459043,18.853708,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153B08",
          NextDialogue = 20006005,
          SpeakNpcId = 200002,
          Subtitle = "Look! They haven't taken this trap yet — and there's a Geniemon inside!",
          TalkActionId = {
            [1] = "200074:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B08"
        },
        [20006005] = {
          Camera = "-264.765686,-875.787109,308.994629,0.000174,-6.859033,150.453903,35.000015,733.116943,false,Manual,22.0",
          ContentTC = "太好了，這次總算趕上了。先把它放出來，再等那些魔靈獵人出現吧。",
          DialogueId = 20006005,
          FinalCamera = "-222.946228,-1021.376953,416.390625,0.000172,-15.459046,141.053696,35.000015,733.116943,false,Manual,22.0",
          GUID = "32153B32",
          SpeakNpcId = 200074,
          Subtitle = "Finally! We made it in time for once. Let's get it out first, then wait for those baddies to show up.",
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B32"
        },
        [20006006] = {
          ContentTC = "一陣手忙腳亂，困在陷阱裡的魔靈被救了出來，但它的態度好像……不是非常友好。",
          DialogueId = 20006006,
          GUID = "32153B5C",
          Subtitle = "After some scrambling, the trapped Geniemon is freed. However... it doesn't seem very friendly.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153B5C"
        },
        [20006007] = {
          Camera = "-348.273315,-725.485352,348.286133,0.000093,-9.591675,168.57576,35.0,1674.542114,false,Manual,22.0",
          ContentTC = "別害怕了小魔靈，本魔王大人以及小跟班，還有魔靈獵人獵人是來解救你們的，現在你自由了，遠離這裡吧！",
          DialogueId = 20006007,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32153B86",
          LookAt = {
            [1] = "200002:n(820000)"
          },
          NextDialogue = 20006008,
          SpeakNpcId = 200002,
          Subtitle = "Don't be scared, little one~ The great Demon King and my loyal Little Minion, and the Geniemon Hunter Hunter, are here to save you! Now, off you go — get out of here and take care!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153B86"
        },
        [20006008] = {
          Camera = "-1100.135376,-637.394531,335.55957,0.000086,-3.391571,1.375749,35.0,1674.542114,false,Manual,6.0",
          ContentTC = "咿咿呀——",
          DialogueId = 20006008,
          GUID = "32153BB0",
          NextDialogue = 20006009,
          SpeakNpcId = 820000,
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Yip—!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153BB0"
        },
        [20006009] = {
          Camera = "-619.304932,-686.379883,266.316895,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
          ContentTC = "不必如此激動，這都是我們應該做的──話說回來，有點眼熟欸？這隻魔靈是不是在冰湖城外就被我們救過一次？",
          DialogueId = 20006009,
          FinalCamera = "-646.760498,-696.469727,267.117676,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
          GUID = "32153BDA",
          NextDialogue = 20006010,
          SpeakNpcId = 200002,
          Subtitle = "You're welcome. We're happy to help... Wait, this one looks kind of familiar. Did we save it once outside the city?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153BDA"
        },
        [20006010] = {
          Camera = "-422.686035,-758.615234,323.150879,0.000171,-5.031971,158.176743,35.000019,294.116943,false,Manual,12.0",
          ContentTC = "你們也都快回家吧，可不要再被那些魔靈獵人抓到了哦，在我能被稱為真正的魔靈獵人獵人之前，你們還是要小心一點才是。",
          DialogueId = 20006010,
          GUID = "32153C04",
          LookAt = {
            [1] = "200074:n(820000)"
          },
          NextDialogue = 20006011,
          SpeakNpcId = 200074,
          Subtitle = "Now go home, and stay safe! Don't let those mean hunters catch you again. Until I'm a true, capable Geniemon Hunter Hunter, you'd better be extra careful.",
          TalkActionId = {
            [1] = "200074:Explain02_Start",
            [2] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153C04"
        },
        [20006011] = {
          Camera = "-781.993408,-607.023438,317.071777,0.00017,-1.2322,-155.023941,35.000019,174.116943,false,Manual,12.0",
          ContentTC = "看起來確實……很像。",
          DialogueId = 20006011,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "32153C2E",
          NextDialogue = 20006012,
          SpeakNpcId = 100001,
          Subtitle = "I think we did.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153C2E"
        },
        [20006012] = {
          Camera = "-823.676147,-643.197266,314.435547,0.00011,-1.391562,0.574502,35.000008,242.039719,false,Manual,3.5",
          ContentTC = "咿咿咿呀——",
          DialogueId = 20006012,
          GUID = "32153C58",
          NextDialogue = 20006013,
          SpeakNpcId = 820000,
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Yiiiip—!",
          VoiceName = "voice/$Locale$/story/2001/200060/32153C58"
        },
        [20006013] = {
          Camera = "-383.416382,-617.654297,369.226074,0.000175,-13.632108,-162.021347,35.000019,314.116943,false,Manual,2.8",
          ContentTC = "哎呀，別亂叫了，快走快走。下一次再被抓的話，可就不一定有這麼好的運氣了。",
          DialogueId = 20006013,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-444.914062,-637.505859,353.714355,0.000175,-13.432099,-162.221298,35.000019,324.116943,false,Manual,2.8",
          GUID = "32153C82",
          NextDialogue = 20006014,
          SpeakNpcId = 200002,
          Subtitle = "Alright, alright, enough yipping. Just go! You might not be this lucky next time.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153C82"
        },
        [20006014] = {
          Camera = "-615.953979,-649.889648,308.302246,0.000101,-13.6588,-149.769836,35.000023,174.116943,false,Manual,12.0",
          ContentTC = "我看……這隻魔靈不太聰明嘛，跟它說了這麼多，都還不走。",
          DialogueId = 20006014,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          FinalCamera = "-644.868896,-667.681641,299.754395,0.000098,-11.858697,-147.368286,35.000023,174.116943,false,Manual,12.0",
          GUID = "32153CAC",
          SpeakNpcId = 200002,
          Subtitle = "Hmm... I don't think this one is very bright. We explained everything, but it just won't leave.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153CAC"
        },
        [20006015] = {
          ContentTC = "啪嘰——",
          DialogueId = 20006015,
          GUID = "32153CD6",
          Subtitle = "*clack*—",
          VoiceName = "voice/$Locale$/story/2001/200060/32153CD6"
        },
        [20006016] = {
          Camera = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
          ContentTC = "欸？怎麼又鑽到陷阱裡去了？這隻魔靈，是不是太害怕我們，所以把陷阱當作是安全的地方了？",
          DialogueId = 20006016,
          FinalCamera = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
          GUID = "32153D00",
          NextDialogue = 20006017,
          SpeakNpcId = 200002,
          Subtitle = "Wait... Did it just slip back into the trap!? Is it so scared of us that it thinks the trap is safer?",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D00"
        },
        [20006017] = {
          Camera = "-760.560303,-565.728516,290.460938,0.000099,-1.191192,-176.627136,35.000011,174.459366,false,Manual,2.8",
          ContentTC = "唔，不應該呀，我們明明救過它，並且也沒有表現出敵意。魔靈們雖然不會說話，但是是能分清楚誰對它好，誰對它壞的。",
          DialogueId = 20006017,
          FacialId = {
            [1] = "200074:Sad01"
          },
          FinalCamera = "-784.401123,-567.131836,289.964355,0.000099,-1.191192,-176.427139,35.000011,138.232086,false,Manual,2.8",
          GUID = "32153D2A",
          NextDialogue = 20006018,
          SpeakNpcId = 200074,
          Subtitle = "That doesn't make sense... We rescued it, and we didn't do anything bad to it. Geniemons might not talk, but they can tell good from bad.",
          TalkActionId = {
            [1] = "200074:Think_Start",
            [2] = "200002:SpecialConfident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D2A"
        },
        [20006018] = {
          Camera = "-538.68689,-695.786133,229.021973,0.000027,5.603125,151.387604,35.000008,345.779022,false,Manual,12.0",
          ContentTC = "我想想……榛子有沒有像這樣，做的事我一開始完全無法理解的時候……",
          DialogueId = 20006018,
          FinalCamera = "-556.785034,-685.914062,231.044922,0.000028,5.603125,151.387619,35.000008,278.757599,false,Manual,12.0",
          GUID = "32153D54",
          NextDialogue = 20006019,
          SpeakNpcId = 200074,
          Subtitle = "Hmm... let me think — has Filbert ever done something that didn't make sense to me at first...?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D54"
        },
        [20006019] = {
          Camera = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,674.116943,false,Manual,22.0",
          ContentTC = "一次非得去看起來光禿禿的山谷裡，後來才知道是因為它聞到了山谷深處有許多漿果……一次是停在花店門口不走，等我買了花，它就開心地一口吃掉……",
          DialogueId = 20006019,
          FinalCamera = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,671.116943,false,Manual,22.0",
          GUID = "32153D7E",
          NextDialogue = 20006020,
          SpeakNpcId = 200074,
          Subtitle = "There was that one time she insisted on going into a valley that looked barren — turns out she'd sniffed out a hidden patch of berries deep inside. Then there was the time she wouldn't budge from a flower shop until I bought some flowers — just so she could eat them in one bite.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D7E"
        },
        [20006020] = {
          ContentTC = "還有一次，是它丟下我，拼命往山坡上跑，是因為附近的草叢裡有蛇……它想把蛇引開……",
          DialogueId = 20006020,
          GUID = "32153DA8",
          NextDialogue = 20006021,
          SpeakNpcId = 200074,
          Subtitle = "And that other time, when she suddenly took off, sprinting straight up a hill without looking back at me for once. Then I realised there was a snake in the grass, and she was leading it away.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153DA8"
        },
        [20006021] = {
          Camera = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
          ContentTC = "嗯……都是因為有很在意的事情……魔靈會在意什麼呢？食物……還有伙伴！",
          DialogueId = 20006021,
          FinalCamera = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
          GUID = "32153DD2",
          NextDialogue = 20006022,
          SpeakNpcId = 200074,
          Subtitle = "Every time she acted strange, it was because of something really important to her... What's important to a Geniemon? Food? And perhaps... their friends!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153DD2"
        },
        [20006022] = {
          Camera = "-800.104004,-669.561523,327.374512,0.000095,-2.797638,176.175522,35.000008,104.665184,false,Manual,12.0",
          ContentTC = "伙伴……我明白了！如果猜得沒錯的話，那些魔靈獵人的藏身之處就在下水道裡。",
          DialogueId = 20006022,
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "32153DFC",
          NextDialogue = 20006023,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"535.722229,-1070.53125,709.230469,0.000068,-6.997009,79.177307,35.0,174.116943,false,Manual,12.0\"},duration{0}},CameraMoveTo{_delay{0.5},TargetPosition{\"868.026001,153.00293,482.812988,0.000102,-2.791628,85.174393,35.000008,1674.542114,false,Manual,2.8\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Friends... That's it! If I'm right, those Geniemon hunters must be hiding in the sewers.",
          TalkActionId = {
            [1] = "200074:Think_End",
            [2] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153DFC"
        },
        [20006023] = {
          Camera = "-687.931763,-671.883789,322.655273,0.000069,-2.197053,176.775879,35.0,174.116943,false,Manual,12.0",
          ContentTC = "在這裡能嗅到其他被抓的魔靈的氣息，所以它才不願意離開。",
          DialogueId = 20006023,
          FacialId = {
            [1] = "100001:Confident02"
          },
          FinalCamera = "-771.952148,-667.40625,310.516113,0.000069,5.202958,177.175873,35.0,174.116943,false,Manual,12.0",
          GUID = "32153E26",
          NextDialogue = 20006024,
          SpeakNpcId = 100001,
          Subtitle = "This Geniemon can smell the scent of its captured friends from here — that's why it won't leave.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E26"
        },
        [20006024] = {
          Camera = "-821.866577,-728.666992,342.821289,0.000095,-11.597776,130.969742,35.000008,178.123947,false,Manual,2.8",
          ContentTC = "很有可能噢，那這樣一來的話，我們就可以在邊上等著，要是那些魔靈獵人出現了，就跟著他們，狠狠教訓他們一頓！",
          DialogueId = 20006024,
          FacialId = {
            [1] = "200074:Confident01"
          },
          FinalCamera = "-828.375366,-721.172852,340.748047,0.000093,-11.797785,130.969742,35.000008,178.123947,false,Manual,2.8",
          GUID = "32153E50",
          NextDialogue = 20006025,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200074:n(100001)"}},
LookAt{LookAtDescription{"100001:n(200074)"}},
PlayAnimation{ActorId{200074},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{_delay{5},
ActorId{200074},AnimationId{"Angry01_Start"},Duration{2}}}]],
          SpeakNpcId = 200074,
          Subtitle = "That makes so much sense! In that case, we can wait right here. And as long as those bad hunters show up, we can follow them and teach them a good lesson!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E50"
        },
        [20006025] = {
          Camera = "-788.137817,-637.754883,224.224121,0.000072,-2.597166,-0.625336,35.0,174.116943,false,Manual,12.0",
          ContentTC = "嗯嗯嗯！",
          DialogueId = 20006025,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-756.913574,-638.139648,223.32666,0.000072,-3.397097,-1.225342,35.0,174.116943,false,Manual,12.0",
          GUID = "32153E7A",
          NextDialogue = 20006026,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_PanBeikun",
          Subtitle = "Yiip—!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E7A"
        },
        [20006026] = {
          Camera = "-412.370728,-629.598633,225.119141,0.000073,3.802544,-175.221069,28.0,265.494751,false,Manual,12.0",
          ContentTC = "唔，該說這隻魔靈是聰明還是笨呢？能想著要去找伙伴，算得上是聰明吧，但又自己進到陷阱裡，有點笨笨的。",
          DialogueId = 20006026,
          FinalCamera = "-412.370728,-629.598633,241.541992,0.000073,0.002452,-175.420853,28.0,265.494751,false,Manual,12.0",
          GUID = "32153EA4",
          LookAt = {
            [1] = "200002:n(700251)"
          },
          NextDialogue = 20006027,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200074:n(200074)"}},
LookAt{LookAtDescription{"100001:n(100001)"}},
PlayAnimation{ActorId{200074},AnimationId{"Angry01_End"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "So, is this Geniemon smart or dumb? I mean, it's got the brains to want us to save its friends, but it also just walked right back into a trap...",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153EA4"
        },
        [20006027] = {
          Camera = "-700.815918,-705.999023,263.483887,0.000069,3.402636,153.177032,35.0,174.116943,false,Manual,12.0",
          ContentTC = "說不定它是看到我們，才故意又進到陷阱裡，讓我們好跟蹤呢。",
          DialogueId = 20006027,
          FinalCamera = "-755.168457,-688.192383,266.806152,0.000068,3.602624,148.576843,35.0,174.116943,false,Manual,12.0",
          GUID = "32153ECE",
          NextDialogue = 20006028,
          SpeakNpcId = 200074,
          Subtitle = "Maybe it did that on purpose? That way we can just follow the bad guys who come to collect the trapped Geniemon to their hideout.",
          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153ECE"
        },
        [20006028] = {
          Camera = "-486.203613,-623.530273,240.246582,0.000087,2.002625,-162.023193,35.0,174.116943,false,Manual,12.0",
          ContentTC = "真的假的？我覺得——",
          DialogueId = 20006028,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-531.324463,-638.469727,243.410156,0.000087,4.602584,-160.822952,35.0,174.116943,false,Manual,12.0",
          GUID = "32153EF8",
          NextDialogue = 20006029,
          SpeakNpcId = 200002,
          Subtitle = "Oh, really? That's—",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153EF8"
        },
        [20006029] = {
          ContentTC = "哎？不錯啊，真抓到了一隻。",
          DialogueId = 20006029,
          GUID = "32153F22",
          NextDialogue = 20006030,
          SpeakNpcId = 200075,
          Subtitle = "Oh? Not bad. Looks like we caught another one.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153F22"
        },
        [20006030] = {
          Camera = "-647.833496,-724.029297,337.969727,0.000094,-6.997679,159.175262,35.0,324.116943,false,Manual,12.0",
          ContentTC = "是魔靈獵人，快躲起來。",
          DialogueId = 20006030,
          GUID = "32153F4C",
          NextDialogue = 20006031,
          SpeakNpcId = 100001,
          Subtitle = "It's the Geniemon hunters! Quick, hide!",
          TurnTo = {
            [1] = "100001:n(200074)",
            [2] = "200074:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153F4C"
        },
        [20006031] = {
          ContentTC = "好!",
          DialogueId = 20006031,
          GUID = "32153F76",
          SpeakNpcId = 200074,
          Subtitle = "Got it!",
          VoiceName = "voice/$Locale$/story/2001/200060/32153F76"
        },
        [20006032] = {
          Camera = "-593.543457,-336.325195,269.372559,0.000176,-9.390683,-128.619858,35.000008,268.984894,false,Manual,12.0",
          ContentTC = "好想現在就揍他們一頓，不過算了，等會兒有他們好看的！",
          DialogueId = 20006032,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "-632.141357,-384.262695,260.398438,0.000174,-8.190715,-130.618393,35.000008,268.984894,false,Manual,12.0",
          GUID = "32153FA0",
          NextDialogue = 20006033,
          SpeakNpcId = 200002,
          Subtitle = "Ugh, I really want to punch 'em... Let's just take notes for now and settle the score with them later!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FA0"
        },
        [20006033] = {
          Camera = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
          ContentTC = "本來以為冰湖城裡的魔靈已經快被抓完了，沒想到還有收穫。",
          DialogueId = 20006033,
          GUID = "32153FCA",
          NextDialogue = 20006034,
          SpeakNpcId = 200075,
          Subtitle = "I thought we'd already captured all the Geniemons in Icelake, but looks like we scored another one.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153FCA"
        },
        [20006034] = {
          Camera = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          ContentTC = "還是得出城啊，出城才能抓到更多。也不知道那個騎豬的小女孩什麼時候才走。",
          DialogueId = 20006034,
          FinalCamera = "-443.855225,194.355469,326.509277,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          GUID = "32153FF4",
          NextDialogue = 20006035,
          SpeakNpcId = 200087,
          Subtitle = "We still need to head out of the city — that's where the real haul is. But that pig-riding brat is always out there messing with us.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FF4"
        },
        [20006035] = {
          ContentTC = "別急嘛，我就不相信了，捱上半個月，她還能在那裡守著。",
          DialogueId = 20006035,
          GUID = "3215401E",
          NextDialogue = 20006036,
          SpeakNpcId = 200075,
          Subtitle = "Don't worry, she'll leave. No way she's gonna camp out there forever.",
          TalkActionId = {
            [1] = "200075:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/3215401E"
        },
        [20006036] = {
          ContentTC = "也是，天寒地凍的還有穢獸，說不定明天她就哭著鼻子回家啦。",
          DialogueId = 20006036,
          GUID = "32154048",
          NextDialogue = 20006037,
          SpeakNpcId = 200087,
          Subtitle = "Right. With the cold and the Filthoids, I'd bet she'll be crying her way home in a day or two.",
          TalkActionId = {
            [1] = "200075:Talk02_End",
            [2] = "200087:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154048"
        },
        [20006037] = {
          ContentTC = "最好這樣！",
          DialogueId = 20006037,
          GUID = "32154072",
          SpeakNpcId = 200075,
          Subtitle = "Yeah! She better be!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154072"
        },
        [20006101] = {
          Camera = "-1302.360229,-832.505859,345.045898,0.000178,-0.789761,21.978495,35.0,1674.542114,false,Manual,2.8",
          ContentTC = "他們回下水道裡了，走，快跟上。",
          DialogueId = 20006101,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32154AF2",
          NextDialogue = 20006102,
          Scripts = "PARA{SEQ{TurnTo{TurnToDescription{\"200002:n(100001)\"}},PlayAnimation{_delay{0.1},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}},CameraMoveTo{_delay{2},TargetPosition{\"-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8\"},duration{0}}}",
          SpeakNpcId = 200002,
          Subtitle = "They're slipping back into the sewers! Come on, let's go!",
          VoiceName = "voice/$Locale$/story/2001/200061/32154AF2"
        },
        [20006102] = {
          Camera = "-691.08667,-817.638672,263.54541,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
          ContentTC = "小聲點，別興高采烈的，如果驚動了魔靈獵人，那隻魔靈要是會說話，一定會罵你笨蛋的。",
          DialogueId = 20006102,
          FinalCamera = "-710.927734,-796.919922,267.683105,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
          GUID = "32154B1C",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 20006103,
          Scripts = "LookAt{LookAtDescription{\"200074:n(200002)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Shh, keep it down. If we give ourselves away, that Geniemon we just saved would probably call you an idiot in its Geniemon language.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B1C"
        },
        [20006103] = {
          Camera = "-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8",
          ContentTC = "哼，才不會，我剛剛那麼關心它，一定給它留下了好印象！",
          DialogueId = 20006103,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "32154B46",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20006104,
          SpeakNpcId = 200002,
          Subtitle = "Hmph! No way. I was so nice to it — I must have made a good impression.",
          VoiceName = "voice/$Locale$/story/2001/200061/32154B46"
        },
        [20006104] = {
          Camera = "-832.142822,-728.967773,342.387207,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
          ContentTC = "噗哧……你們啊……雖然我年紀不大，但是帶著榛子也見過很多人了，但像你們這樣，在意魔靈想法的人可不多。",
          DialogueId = 20006104,
          FinalCamera = "-837.814453,-721.487305,340.496582,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
          GUID = "32154B70",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20006105,
          SpeakNpcId = 200074,
          Subtitle = "Haha... You two really are something. I've met plenty of people travelling with Filbert, but few people genuinely care about what Geniemons think.",
          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B70"
        },
        [20006105] = {
          ContentTC = "要是每個人都像你們一樣，意識到動物和魔靈也是有自己喜好的，就不會有魔靈獵人了！",
          DialogueId = 20006105,
          GUID = "32154B9A",
          NextDialogue = 20006106,
          SpeakNpcId = 200074,
          Subtitle = "If more people understood that Geniemons have their own thoughts and feelings, just like you do, we wouldn't have Geniemon hunters in the first place!",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200061/32154B9A"
        },
        [20006106] = {
          Camera = "-809.379883,-578.354492,277.954102,0.000212,5.809533,178.160782,35.000011,115.034302,false,Manual,2.8",
          ContentTC = "走吧走吧，這一次我一定要讓他們徹底知錯！",
          DialogueId = 20006106,
          FinalCamera = "-822.223877,-577.945312,279.260742,0.000213,5.809533,178.160782,35.000011,110.479393,false,Manual,2.8",
          GUID = "32154BC4",
          LookAt = {
            [1] = "200074:n(200074)"
          },
          SpeakNpcId = 200074,
          Subtitle = "Let's go. This time, I'll make sure they learn their lesson once and for all!",
          TalkActionId = {
            [1] = "200074:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154BC4"
        },
        [20006201] = {
          Camera = "-287.4375,38.861328,166.546265,0.000031,-8.400183,-1.804748,18.000004,100000.0,false,Manual,2.8",
          ContentTC = "唔，原來這裡的下水道這麼複雜。榛子，能聞到魔靈的味道嗎？",
          DialogueId = 20006201,
          GUID = "32155B5A",
          NextDialogue = 20006202,
          SpeakNpcId = 200074,
          Subtitle = "I didn't realise there would be so many tunnels in the sewers... Filbert, can you pick up a Geniemon's scent?",
          VoiceName = "voice/$Locale$/story/2001/200062/32155B5A"
        },
        [20006202] = {
          ContentTC = "哼唧……",
          DialogueId = 20006202,
          GUID = "32155B84",
          NextDialogue = 20006203,
          SpeakNpcId = 200086,
          Subtitle = "Oink...",
          VoiceName = "voice/$Locale$/story/2001/200062/32155B84"
        },
        [20006203] = {
          ContentTC = "味道太多了反而無法分辨方向？唔，只能先向前走了。",
          DialogueId = 20006203,
          GUID = "32155BAE",
          NextDialogue = 20006204,
          SpeakNpcId = 200074,
          Subtitle = "Too many overlapping smells? Hmm... Let's just keep moving then.",
          VoiceName = "voice/$Locale$/story/2001/200062/32155BAE"
        },
        [20006204] = {
          ContentTC = "跟著我走就好，我對這裡可熟悉了。",
          DialogueId = 20006204,
          GUID = "32155BD8",
          NextDialogue = 20006205,
          SpeakNpcId = 200002,
          Subtitle = "Just follow me. I know my way around here.",
          VoiceName = "voice/$Locale$/story/2001/200062/32155BD8"
        },
        [20006205] = {
          ContentTC = "咦，原來小白平常住在這種地方嗎？",
          DialogueId = 20006205,
          GUID = "32155C02",
          NextDialogue = 20006206,
          SpeakNpcId = 200074,
          Subtitle = "Huh? Why? Is this where you live?",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C02"
        },
        [20006206] = {
          ContentTC = "不……不是的，只是身為魔王大人，之前來過這裡巡視過幾次，遠來的魔靈獵人獵人喲，跟緊了。",
          DialogueId = 20006206,
          GUID = "32155C2C",
          NextDialogue = 20006207,
          SpeakNpcId = 200002,
          Subtitle = "O...Of course not. But as the great Demon King, I've inspected these tunnels many times. Now, keep up, foreign Geniemon Hunter Hunter!",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C2C"
        },
        [20006207] = {
          ContentTC = "好~",
          DialogueId = 20006207,
          GUID = "32155C56",
          SpeakNpcId = 200074,
          Subtitle = "Okay~",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C56"
        },
        [20006301] = {
          ContentTC = "啊，這個痕跡，之前巡視的時候可沒有見到過。",
          DialogueId = 20006301,
          GUID = "32156BC2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 20006302,
          SpeakNpcId = 200002,
          Subtitle = "Ah, this mark wasn't here last time I checked.",
          VoiceName = "voice/$Locale$/story/2001/200063/32156BC2"
        },
        [20006302] = {
          ContentTC = "看起來像是被抓的那個魔靈留下來的，跟著這個痕跡吧。",
          DialogueId = 20006302,
          GUID = "32156BEC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Looks like something the Geniemon we just saved might have left behind. Let's follow it.",
          VoiceName = "voice/$Locale$/story/2001/200063/32156BEC"
        },
        [20006401] = {
          ContentTC = "痕跡越來越新，應該不遠了……",
          DialogueId = 20006401,
          GUID = "32157C2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20006402,
          SpeakNpcId = 200074,
          Subtitle = "The marks are getting fresher... It shouldn't be far.",
          VoiceName = "voice/$Locale$/story/2001/200064/32157C2A"
        },
        [20006402] = {
          ContentTC = "我好像聽見有人在說話——",
