        },
        [51000443] = {
          ContentTC = "（如果日記上記錄的內容屬實，那麼失憶少女的真實身份，就已十分明了了。）",
          DialogueId = 51000443,
          GUID = "7FAC96B2",
          NextDialogue = 51000444,
          Subtitle = "(If the words in this diary are true... then the truth is clear at last.)"
        },
        [51000444] = {
          ContentTC = "（同樣水落石出的，還有愛爾莎夫人那個失蹤的女兒，安妮的下落……）",
          DialogueId = 51000444,
          GUID = "7FAC96B3",
          NextDialogue = 51000445,
          Subtitle = "(Not only has the lost girl's real identity come to light — so too has the fate of Elsa's daughter, Annie.)"
        },
        [51000445] = {
          ContentTC = "（……安妮已經不幸離世，而得到她衣物的另一位少女愛麗絲活了下來。儘管在雪山幸存，但連續高燒還是奪走了愛麗絲的記憶。）",
          DialogueId = 51000445,
          GUID = "7FAC96B4",
          Subtitle = "(...Annie has tragically passed away, while the other girl, Alice, who ended up with Annie's clothes, has survived. Although Alice made it through the ordeal in the snowy mountains, the severe fevers she suffered afterwards took away her memories.)"
        },
        [51000490] = {
          ContentTC = "……安妮，你在說什麽呢？媽媽準備了你最愛吃的北風莓沙拉和奶油布丁……",
          DialogueId = 51000490,
          GUID = "7FACA3E4",
          NextDialogue = 51000491,
          SpeakNpcId = 700006,
          Subtitle = "...Annie, what are you talking about? Mum's made your favourite, Borealberry Salad and Cream Pudding..."
        },
        [51000491] = {
          ContentTC = "回家吧，媽媽再也不兇你，再也不要你做什麽上流社會的淑女了，媽媽只要你好好的……",
          DialogueId = 51000491,
          GUID = "7FACA40E",
          NextDialogue = 51000492,
          SpeakNpcId = 700006,
          Subtitle = "Come back home, sweetheart. Mum won't be hard on you anymore, no more forcing you into being a lady of high society. All I want is for my baby to be safe..."
        },
        [51000492] = {
          ContentTC = "（女子的精神狀態不太好，聽起來，她似乎弄丟了自己的女兒。試著說服她冷靜下來吧。）",
          DialogueId = 51000492,
          GUID = "7FACA438",
          NextOptions = {
            [1] = 510004921
          },
          SpeakNpcId = 700006,
          Subtitle = "(The woman appears deeply distressed, seemingly having lost her daughter. Try to gently calm her down.)",
          bForbidSkipOptions = true
        },
        [51000493] = {
          ContentTC = "（你知道，你只是在和她開個小小的玩笑。接下來，得想辦法說服她冷靜下來。聽起來，她似乎弄丟了自己的女兒。）",
          DialogueId = 51000493,
          GUID = "7FACA462",
          NextOptions = {
            [1] = 510004921
          },
          RestartTag = 51000493,
          Subtitle = "(You're merely humouring her. Now, better gently coax her into calmness. It appears she has lost her daughter.)",
          bForbidSkipOptions = true
        },
        [51000501] = {
          ContentTC = "拜託你了……",
          DialogueId = 51000501,
          GUID = "7FACA5B2",
          NextOptions = {
            [1] = 510005011
          },
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000502] = {
          ContentTC = "天呐！你找到安妮了？",
          DialogueId = 51000502,
          GUID = "7FACA5DC",
          NextOptions = {
            [1] = 510005021
          },
          SpeakNpcId = 700006,
          Subtitle = "My goodness! Have you found Annie?",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000503] = {
          ContentTC = "……",
          DialogueId = 51000503,
          GUID = "7FACA606",
          NextDialogue = 51000504,
          SpeakNpcId = 700006,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700006:Shock_End"
          }
        },
        [51000504] = {
          ContentTC = "胡說……胡說，胡說！",
          DialogueId = 51000504,
          GUID = "7FACA630",
          NextDialogue = 51000591,
          SpeakNpcId = 700006,
          Subtitle = "Nonsense... That's utter nonsense!",
          TalkActionId = {
            [1] = "700006:Disagree"
          }
        },
        [51000505] = {
          ContentTC = "你說，孩子沒了母親可怎麼行呢……",
          DialogueId = 51000505,
          GUID = "7FACA65A",
          NextDialogue = 51000506,
          Scripts = [[
SEQ{
MoveTo{ActorId{700006},TargetPoint{"Point_510005_Aier2"},MoveSpeed{150},Visibility{"Show"}},
MoveTo{ActorId{700006},TargetPoint{"Point_510005_Aier"},MoveSpeed{150},Visibility{"Hide"}}
}]],
          SpeakNpcId = 700006,
          Subtitle = "How do you think a child can manage without her mother..."
        },
        [51000506] = {
          ContentTC = "（愛爾莎把錢袋往你懷裡一塞，像著了魔一樣朝某個方向走去。淚水與笑容交織在她憔悴的臉上，很快她的身影就消失在了遠方。）",
          DialogueId = 51000506,
          GUID = "7FACA684",
          NextDialogue = 51000507,
          Subtitle = "(She thrusts the coin pouch into your arms and walks away, as if spellbound. Tears and a smile mingle on her weary face, flickering faintly before she disappears into the distance.)"
        },
        [51000507] = {
          ContentTC = "（比起善意的謊言，人們更應該面對真相。時間是最好的藥劑，再過些日子，她就會好起來的……或許。）",
          DialogueId = 51000507,
          GUID = "7FACA6AE",
          Subtitle = "(A gentle lie might bring comfort for a time — but in the end, truth must be faced. Time will mend what it can... and perhaps, someday, she'll heal.)"
        },
        [51000590] = {
          ContentTC = "之前是我太疏忽，只知道拜托別人，傻傻地等，讓我的安妮等了那麽久，沒關系，都沒關系，我現在就啟程去找她……自己去找……",
          DialogueId = 51000590,
          GUID = "7FACB44C",
          NextDialogue = 51000505,
          SpeakNpcId = 700006,
          Subtitle = "I've been a terrible mother — how could I just wait here for others to help me? My Annie must've waited for me for so long... It's okay, I'll set off to find her now... I'll find my baby on my own..."
        },
        [51000591] = {
          ContentTC = "我的安妮……我的安妮那麽乖，她怎麽可能拋下自己的媽媽呢！你騙我，你騙我！",
          DialogueId = 51000591,
          GUID = "7FACB476",
          NextDialogue = 51000590,
          SpeakNpcId = 700006,
          Subtitle = "My Annie... My sweet Annie, she'd never leave her mother like this! You're lying, you dirty liar!"
        },
        [51000601] = {
          Camera = "-234.948181,323.855713,130.964355,0.00001,-3.599974,-48.399338,32.0,100000.0,false,Manual,2.8",
          ContentTC = "拜託你了……",
          DialogueId = 51000601,
          GUID = "7FACB61A",
          LookAt = {
            [1] = "700006:n(0)"
          },
          NextOptions = {
            [1] = 510006011
          },
          Scripts = "TurnTo{TurnToDescription{\"700006:n(100001)\"}}",
          SpeakNpcId = 700006,
          Subtitle = "I'm counting on you..."
        },
        [51000602] = {
          Camera = "-110.428955,187.104736,199.557129,0.00006,-12.599321,-55.19915,32.0,500.0,false,Manual,2.8",
          ContentTC = "……天啊，奇跡真的發生了……",
          DialogueId = 51000602,
          FinalCamera = "-95.131409,197.827637,199.557129,0.000059,-12.799316,-54.799076,32.0,500.0,false,Manual,2.8",
          GUID = "7FACB644",
          LookAt = {
            [1] = "700006:n(700196)"
          },
          NextDialogue = 51000603,
          Scripts = "MoveTo{ActorId{700196},TargetPoint{\"Point200203_Alice\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700006,
          Subtitle = "Oh my God, miracles do happen...",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          },
          ToFinalCameraBlendTime = 3
        },
        [51000603] = {
          ContentTC = "讓媽媽好好看看，媽媽想你想得都快發瘋了！嗯？你怎麽和以前不太一樣了？你變瘦了好多……",
          DialogueId = 51000603,
          FacialId = {
            [1] = "700006:CM_Happy01"
          },
          GUID = "7FACB66E",
          NextDialogue = 51000604,
          SpeakNpcId = 700006,
          Subtitle = "Let Mum have a good look at you, sweetie... I've missed you so much that I almost lost my mind! Hm? You seem a bit different... Much thinner than before..."
        },
        [51000604] = {
          Camera = "98.233093,31.165039,150.292969,0.000063,-2.599365,-39.19735,32.0,150.0,false,Manual,2.8",
          ContentTC = "沒關系的，沒關系的，媽媽準備了你最愛吃的北風莓沙拉和奶油布丁，回家吧，我的孩子，都過去了，都過去了……",
          DialogueId = 51000604,
          GUID = "7FACB698",
          NextDialogue = 51000605,
          SpeakNpcId = 700006,
          Subtitle = "It's okay, I've made your favourite Borealberry Salad and Cream Pudding; let's go home, my baby, everything's okay now...",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000605] = {
          ContentTC = "謝謝你，好心人，這是給你的報酬。我差點就以為我再也見不到我的安妮了。謝謝你，謝謝你……",
          DialogueId = 51000605,
          GUID = "7FACB6C2",
          NextDialogue = 51000690,
          SpeakNpcId = 700006,
          Subtitle = "Bless you, kind soul. This is for you. I thought I'd never see my Annie again. Thank you, thank you so much..."
        },
        [51000606] = {
          ContentTC = "我的寶貝女兒……只要不離開媽媽，媽媽為你做什麼都可以……",
          DialogueId = 51000606,
          GUID = "7FACB6EC",
          SpeakNpcId = 700006,
          Subtitle = "My precious daughter... As long as you don't leave me, I'll do anything for you..."
        },
        [51000690] = {
          ContentTC = "（女人喜極而泣，不停道謝著。淚水流幹後，就是幸福的未來……或許。）",
          DialogueId = 51000690,
          GUID = "7FACC4B4",
          Subtitle = "(Tears of joy stream down the woman's face as she utters her gratitude repeatedly. After the tears dry, a mother and a child will live happily ever after... hopefully.)"
        },
        [51000701] = {
          ContentTC = "……",
          DialogueId = 51000701,
          GUID = "7FACC682",
          NextOptions = {
            [1] = 510007011
          },
          SpeakNpcId = 700032,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          }
        },
        [51000702] = {
          ContentTC = "我……我腦袋很昏沉。說實話我不知道自己是誰，也不清楚這是哪裡……",
          DialogueId = 51000702,
          GUID = "7FACC6AC",
          NextDialogue = 51000703,
          SpeakNpcId = 700032,
          Subtitle = "I... I feel so foggy. Honestly, I don't even know who I am — or where this place is."
        },
        [51000703] = {
          ContentTC = "我是被一個好心的醫生從北邊雪山救回來的。她說我發了高燒，燒壞了腦子，所以才會失去記憶……",
          DialogueId = 51000703,
          GUID = "7FACC6D6",
          NextOptions = {
            [1] = 510007031,
            [2] = 510007032,
            [3] = 510007033
          },
          SpeakNpcId = 700032,
          Subtitle = "A kind-hearted doctor found me up in the northern mountains and brought me back. She said I had a terrible fever... and that it probably damaged my memory.",
          bForbidSkipOptions = true
        },
        [51000705] = {
          ContentTC = "這幾天我唯一能想起來的就是漫天的暴風雪，我在山上舉步維艱……但我大病初愈，現在的身體狀況估計連出城都難，可以拜托你幫我調查嗎？",
          DialogueId = 51000705,
          GUID = "7FACC72A",
          NextOptions = {
            [1] = 510007051,
            [2] = 51000002
          },
          SpeakNpcId = 700032,
          Subtitle = "The only thing I could remember these past few days was the relentless blizzard as I struggled to make my way across the mountain... But right now I'm in no condition to go anywhere. Could you help me with the investigation?",
          TalkActionId = {
            [1] = "700032:Explain01_Start"
          },
          bForbidSkipOptions = true
        },
        [51000706] = {
          ContentTC = "除了救我的好心人，你是唯一一個願意對我這樣一個身無分文的女孩子伸出援助之手的。除了謝謝，我不知道還能說什麽好……",
          DialogueId = 51000706,
          GUID = "7FACC754",
          NextDialogue = 51000790,
          SpeakNpcId = 700032,
          Subtitle = "Apart from the kind doctor who saved me, you are the only one willing to offer a helping hand to a penniless girl like me. I don't know what else to say but thank you...",
          TalkActionId = {
            [1] = "700032:Explain01_End"
          }
        },
        [51000707] = {
          ContentTC = "有結果嗎？",
          DialogueId = 51000707,
          GUID = "7FACC77E",
          SpeakNpcId = 700032,
          Subtitle = "Did you find anything?"
        },
        [51000790] = {
          ContentTC = "對了，這裡有一封信，是我從外套口袋裡找到的。雖然我對這封信一點印像都沒有……但這個線索可能會有用？",
          DialogueId = 51000790,
          GUID = "7FACD51C",
          NextDialogue = 51000791,
          SpeakNpcId = 700032,
          Subtitle = "Oh — this was in my coat pocket. I don't remember anything about it... but maybe it's important?"
        },
        [51000791] = {
          ContentTC = "（你開始思索最近遇到的兩個人——近乎瘋癲地尋找女兒的愛爾莎夫人，以及失憶的少女。當然，還有少女口袋裡那封寫給母親的信。）",
          DialogueId = 51000791,
          GUID = "7FACD546",
          NextDialogue = 51000792,
          Subtitle = "(The threads begin to connect between the two individuals you've recently come across — Ms Elsa, who's been driven near to madness in search of her daughter, and this amnesiac girl. And then there's the letter, seemingly penned to a mother.)"
        },
        [51000792] = {
          ContentTC = "（失憶的少女也許就是愛爾莎失蹤的女兒，安妮——你這樣猜測。）",
          DialogueId = 51000792,
          GUID = "7FACD570",
          NextDialogue = 51000793,
          Subtitle = "(The thought crosses your mind that the girl bereft of memory might very well be Elsa's missing daughter, Annie.)"
        },
        [51000793] = {
          ContentTC = "（你應該帶她去找愛爾莎確認的，但是，愛爾莎似乎會把每一個路過的年輕人當成安妮……也許還是先收集更多失憶少女身份的證據為好。）",
          DialogueId = 51000793,
          GUID = "7FACD59A",
          NextDialogue = 51000794,
          Subtitle = "(Intuition suggests bringing her to Elsa for recognition, yet Elsa's delusion leads her to see Annie in every youthful face... Gathering more substantial evidence of the girl's identity seems the prudent course at the moment.)"
        },
        [51000794] = {
          ContentTC = "（解鈴還須繫鈴人，看來想要探知少女的身世，還得先想辦法找到那位當初救下少女的醫生。）",
          DialogueId = 51000794,
          GUID = "7FACD59B",
          Subtitle = "(If anyone holds the key to this girl's past, it's the doctor who saved her back then.)"
        },
        [51000801] = {
          ContentTC = "你平安回來了，辛苦你了，有什麼發現嗎？",
          DialogueId = 51000801,
          GUID = "7FACD6EA",
          NextDialogue = 51000802,
          SpeakNpcId = 700032,
          Subtitle = "You've returned safely. Did you find anything?",
          TalkActionId = {
            [1] = "700032:Agree"
          }
        },
        [51000802] = {
          ContentTC = "（眼前的少女無依無靠，而愛爾莎夫人也因為愛女失蹤而精神失常……你不禁想，如果少女就是安妮該有多好。）",
          DialogueId = 51000802,
          GUID = "7FACD714",
          NextDialogue = 51000890,
          Subtitle = "(The girl standing before you is all alone, and Ms Elsa has been driven to the brink of madness by her daughter's disappearance... You find yourself wishing she were Annie.)"
        },
        [51000803] = {
          ContentTC = "……這是……！",
          DialogueId = 51000803,
          GUID = "7FACD73E",
          NextDialogue = 51000893,
          SpeakNpcId = 700032,
          Subtitle = "...What's this...",
          TalkActionId = {
            [1] = "700032:Shock_Start"
          }
        },
        [51000804] = {
          ContentTC = "我……我記起來了……",
          DialogueId = 51000804,
          GUID = "7FACD768",
          NextDialogue = 51000805,
          SpeakNpcId = 700032,
          Subtitle = "...It's all coming back to me now...",
          TalkActionId = {
            [1] = "700032:Shock_End"
          }
        },
        [51000805] = {
          ContentTC = "我叫愛麗絲，是一名來自伊瑟爾的考古學學生……",
          DialogueId = 51000805,
          GUID = "7FACD792",
          NextDialogue = 51000806,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "My name is Alice, I'm an archaeology student from Aethyrie...",
          TalkActionId = {
            [1] = "700032:Talk02_Start"
          }
        },
        [51000806] = {
          ContentTC = "當時我正在維德弗尼爾雪山勘查，卻恰巧遭遇了接連數日的暴風雪，很快我就迷失了方向……",
          DialogueId = 51000806,
          GUID = "7FACD7BC",
          NextDialogue = 51000807,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "I was conducting a survey in the Vidofnir Mountains when I got caught in a snowstorm that lasted for days, and soon I lost my way..."
        },
        [51000807] = {
          ContentTC = "後來，我遇見了奄奄一息的安妮，我們一起艱難生活了數日。我們鼓勵著彼此活下去，約好在暴風雪停歇後，我要去她在冰湖城的家做客……",
          DialogueId = 51000807,
          GUID = "7FACD7E6",
          NextDialogue = 51000808,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Later on, I met Annie, who was clinging to life by a mere thread. Together, we struggled to live on for several days. We encouraged each other to try to survive, and she invited me to visit her home in Icelake after the storm..."
        },
        [51000808] = {
          ContentTC = "可是她傷得太重了，最終還是沒能挺過去……最後她把衣服給了我，希望我再穿暖和一些，能活著走出雪山……",
          DialogueId = 51000808,
          GUID = "7FACD810",
          NextDialogue = 51000809,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "But... she was too badly hurt. She didn't make it. Before she passed, she gave me her coat. Said it might keep me warm enough to get through...",
          TalkActionId = {
            [1] = "700032:Talk02_End"
          }
        },
        [51000809] = {
          ContentTC = "安妮……",
          DialogueId = 51000809,
          GUID = "7FACD83A",
          NextDialogue = 51000810,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Annie...",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          }
        },
        [51000810] = {
          ContentTC = "謝謝你……我會永遠記住安妮的。",
          DialogueId = 51000810,
          GUID = "7FACD864",
          NextDialogue = 51000811,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Thank you... I will always remember Annie.",
          TalkActionId = {
            [1] = "700032:Explain02_End"
          }
        },
        [51000811] = {
          ContentTC = "（愛麗絲溫柔地撫摸著衣物，這是一個女孩保護了另一個女孩的見證。你告別愛麗絲，準備將事實轉告愛爾莎。）",
          DialogueId = 51000811,
          GUID = "7FACD88E",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "(Alice gently strokes the clothing which is a testament of one girl protecting the other. You bid farewell to Alice and get ready to tell Elsa the truth.)"
        },
        [51000812] = {
          ContentTC = "等身體養好了，我就打算開始下一段冒險了。",
          DialogueId = 51000812,
          GUID = "7FACD8B8",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_CMNpc_Name_Alice",
          Subtitle = "Once I've recovered, I will start my next adventure."
        },
        [51000813] = {
          ContentTC = "你的名字是安妮。我找到了你的母親，你口袋裡那封信就是寫給她的。",
          DialogueId = 51000813,
          GUID = "7FACD8E2",
          NextDialogue = 51000894,
          SpeakNpcId = 100001,
          Subtitle = "Your name is Annie. I've found your mother, and that letter you're carrying is meant for her."
        },
        [51000814] = {
          ContentTC = "謝謝你！她一定很擔心我。",
          DialogueId = 51000814,
          GUID = "7FACD90C",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Thank you! She must be worried about me."
        },
        [51000815] = {
          ContentTC = "等母親好些，我就帶她去看看大自然有多美！",
          DialogueId = 51000815,
          GUID = "7FACD936",
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Once my mother gets better, I'll take her to see the beauty in the great outdoors!"
        },
        [51000890] = {
          ContentTC = "（回憶起愛爾莎說過，她家只有母女倆相依為命，你腦海中突然閃過一個可怕的念頭——如果你<H>從未見過</>愛麗絲的日記……）",
          DialogueId = 51000890,
          GUID = "7FACE584",
          NextDialogue = 51000891,
          Subtitle = "(Recalling Elsa's words about how she and her daughter were the only two in their family, a dreadful thought crosses your mind — if you had never seen Alice's diary...)"
        },
        [51000891] = {
          ContentTC = "（少女將有一個溫暖的小家可以依靠，而愛爾莎的「女兒」也回來了。<H>這似乎是最完美的結局——只是，這兩個人同樣擁有知曉真相的權利……</>）",
          DialogueId = 51000891,
          GUID = "7FACE5AE",
          NextDialogue = 51000892,
          Subtitle = "(Then the girl would have a warm hearth to return to, and Elsa would have her \"daughter\" back. This seems like the perfect ending — except, they both have the right to know the truth...)"
        },
        [51000892] = {
          ContentTC = "（應該做出怎樣的選擇？將真相告知二人，還是這樣將錯就錯下去？）",
          DialogueId = 51000892,
          GUID = "7FACE5D8",
          NextOptions = {
            [1] = 510008921,
            [2] = 510008121
          },
          Subtitle = "(The dilemma stands: to unveil the harsh truth or perpetuate the comforting falsehood?)",
          bForbidSkipOptions = true
        },
        [51000893] = {
          ContentTC = "這是……我寫的……",
          DialogueId = 51000893,
          GUID = "7FACE602",
          NextDialogue = 51000804,
          SpeakNpcId = 700032,
          Subtitle = "This is... something I wrote..."
        },
        [51000894] = {
          ContentTC = "安妮……原來這就是我的名字啊。總覺得稍微有點陌生呢……",
          DialogueId = 51000894,
          GUID = "7FACE62C",
          NextDialogue = 51000895,
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Annie... So that's my name. Has a strange ring to it..."
        },
        [51000895] = {
          ContentTC = "抱歉，我都忘了……謝謝，真的謝謝你！帶我去找媽媽吧，她一定會重謝你的！",
          DialogueId = 51000895,
          GUID = "7FACE656",
          NextOptions = {
            [1] = 510008141
          },
          SpeakNpcId = 700032,
          SpeakNpcName = "UI_Npc_Name_Anni",
          Subtitle = "Sorry, I really don't remember a thing... Thank you, really, thank you so much! Could you take me to my mother? She will definitely give you a ton of thank-you gifts!",
          bForbidSkipOptions = true
        },
        [51000901] = {
          ContentTC = "陌生的客人！什麼風把您吹到了我這裡來？不過您要是想找點樂子，到馬丁這來看看准沒錯！",
          DialogueId = 51000901,
          GUID = "7FACE752",
          NextDialogue = 51000902,
          SpeakNpcId = 700022,
          Subtitle = "A new customer! What brings you here? But if you're looking for some fun, you've come to the right place with Martin!",
          TalkActionId = {
            [1] = "700022:Talk01_Start"
          }
        },
        [51000902] = {
          ContentTC = "（面前的男人對你行了一個花裡胡哨的大禮，然後變戲法一樣擺出一堆錯落的商品）",
          DialogueId = 51000902,
          GUID = "7FACE77C",
          NextDialogue = 51000903,
          SpeakNpcId = 700022,
          Subtitle = "(The man in front of you performs an extravagant bow, then magically displays a bunch of scattered goods.)"
        },
        [51000903] = {
          ContentTC = "隨意挑選，相信馬丁的品味！您見過的沒見過的都能在這裡找到，偶爾給自己的生活帶來點小驚喜！",
          DialogueId = 51000903,
          GUID = "7FACE7A6",
          SpeakNpcId = 700022,
          Subtitle = "Feel free to choose. Trust Martin's choice! You can find everything here, seen or unseen, occasionally spicing up your life!",
          TalkActionId = {
            [1] = "700022:Talk01_End"
          },
          TalkOptions = {
            [1] = 510009031,
            [2] = 510009032,
            [3] = 510009033
          }
        },
        [51000904] = {
          ContentTC = "你可真沒禮貌~會估價可不等於你是個有品味的人，甜心。",
          DialogueId = 51000904,
          GUID = "7FACE7D0",
          SpeakNpcId = 700022,
          Subtitle = "You're quite impolite. Being able to appraise doesn't mean you have good taste, sweetheart.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000905] = {
          ContentTC = "任由它們浪費難道不也是一種犯罪嗎？我只是想給他們都找一個家~",
          DialogueId = 51000905,
          GUID = "7FACE7FA",
          SpeakNpcId = 700022,
          Subtitle = "Isn't letting them go to waste also a crime? I just want to find a home for them all.",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000906] = {
          ContentTC = "哦~這可是商業機密。你想好用什麼來和我交換了嗎？",
          DialogueId = 51000906,
          GUID = "7FACE824",
          SpeakNpcId = 700022,
          Subtitle = "Nah-ah. That's a trade secret. So, have you thought about what you'd like to exchange with me?",
          TalkOptions = {
            [1] = 510009071
          }
        },
        [51000907] = {
          ContentTC = "（你看了看他的商品，遺憾地搖了搖頭）",
          DialogueId = 51000907,
          GUID = "7FACE84E",
          Subtitle = "(You look at his goods and sadly shake your head.) ",
          TalkOptions = {
            [1] = 510009072
          }
        },
        [51000908] = {
          ContentTC = "那我大概不是你需要的那種人，但我會等到你願意惠顧的那天的。",
          DialogueId = 51000908,
          GUID = "7FACE878",
          SpeakNpcId = 700022,
          Subtitle = "Then I'm probably not the person you need, but I'll wait for the day you extend your patronage."
        },
        [51000909] = {
          ContentTC = "我明白了！你是這個冰湖城裡很罕見的一種人……",
          DialogueId = 51000909,
          GUID = "7FACE8A2",
          NextDialogue = 51000910,
          SpeakNpcId = 700022,
          Subtitle = "I got it! You're a rare kind of person in Icelake…",
          TalkActionId = {
            [1] = "700022:Think_Start"
          }
        },
        [51000910] = {
          ContentTC = "你既不是來採購廉價物資的貧民窟居民，也不是對鄰居的私生活大有興趣的貴族老爺，你對馬丁無慾無求，甚至你從來沒聽過我的名字，對不對？",
          DialogueId = 51000910,
          GUID = "7FACE8CC",
          SpeakNpcId = 700022,
          Subtitle = "You're neither a slum dweller here to buy cheap supplies nor a noble interested in the private lives of your neighbors. You have no desire or need for Martin. You've never even heard my name, have you?",
          TalkActionId = {
            [1] = "700022:Think_End"
          },
          TalkOptions = {
            [1] = 510009101,
            [2] = 510009102,
            [3] = 510009103
          }
        },
        [51000911] = {
          ContentTC = "那請容我為您自我介紹！我是冰湖城的拾荒者之王，每個垃圾桶的知心兄弟，廢棄物品最好的代言者與推銷者。",
          DialogueId = 51000911,
          GUID = "7FACE8F6",
          NextDialogue = 51000990,
          SpeakNpcId = 700022,
          Subtitle = "Then allow me to introduce myself! I am the King of Scavengers in Icelake, the confidant brother of every rubbish bin, and the best spokesperson and promoter of discarded items. ",
          TalkActionId = {
            [1] = "700022:Confident_Start"
          }
        },
        [51000912] = {
          ContentTC = "事實上，垃圾桶裡隱藏著各式各樣的秘密，只要你足夠耐心，不辭辛苦……它們就會把這戶人家的心事源源不斷地告訴你。",
          DialogueId = 51000912,
          GUID = "7FACE920",
          SpeakNpcId = 700022,
          Subtitle = "In fact, rubbish bins hide all sorts of secrets. As long as you're patient enough and don't mind the hard work, they will continue to share with you the secrets of their households.",
          TalkActionId = {
            [1] = "700022:Confident_End"
          }
        },
        [51000913] = {
          ContentTC = "你好奇了？真不錯。我知道，慣常的商品可打動不了你們，但馬丁有自己的辦法。",
          DialogueId = 51000913,
          GUID = "7FACE94A",
          NextDialogue = 51000991,
          SpeakNpcId = 700022,
          Subtitle = "Now you get intrigued? That's great. I know ordinary goods won't impress you, but Martin has his ways.",
          TalkActionId = {
            [1] = "700022:Explain01_Start"
          }
        },
        [51000914] = {
          ContentTC = "如果你們能幫它們找到主人，或許就能更加瞭解這個城市，哪怕什麼也沒得到，至少你們滿足了自己的好奇心。",
          DialogueId = 51000914,
          GUID = "7FACE974",
          NextDialogue = 51000915,
          SpeakNpcId = 700022,
          Subtitle = "If you can help find their owners, you might understand this city better. Even if you get nothing, at least you satisfy your curiosity.",
          TalkActionId = {
            [1] = "700022:Explain01_End"
          }
        },
        [51000915] = {
          ContentTC = "（馬丁變出了一些無法具體名狀的東西，然後朝著你們擠了擠眼睛。）",
          DialogueId = 51000915,
          GUID = "7FACE99E",
          NextDialogue = 51000916,
          Subtitle = "(Martin produces some indescribable things and winks at you.)"
        },
        [51000916] = {
          ContentTC = "想試試嗎？",
          DialogueId = 51000916,
          GUID = "7FACE9C8",
          SpeakNpcId = 700022,
          Subtitle = "Want to give it a try?",
          TalkActionId = {
            [1] = "700022:Talk01_Start"
          }
        },
        [51000917] = {
          ContentTC = "祝您尋人順利，偵探閣下。",
          DialogueId = 51000917,
          GUID = "7FACE9F2",
          SpeakNpcId = 700022,
          Subtitle = "Good luck, Detective.",
          TalkActionId = {
            [1] = "700022:Talk01_End"
          }
        },
        [51000918] = {
          ContentTC = "進展得還順利嗎，偵探閣下？",
          DialogueId = 51000918,
          GUID = "7FACEA1C",
          SpeakNpcId = 700022,
          Subtitle = "Everything going well, Detective?"
        },
        [51000990] = {
          ContentTC = "我的名字想必已經無需重複，我就是馬丁。",
          DialogueId = 51000990,
          GUID = "7FACF5EC",
          NextDialogue = 51000912,
          SpeakNpcId = 700022,
          Subtitle = "My name probably speaks for itself. I am Martin."
        },
        [51000991] = {
          ContentTC = "我願意把「謎題」賣給你們，你們可以把它們當做「某人的心結」或者「失物」。",
          DialogueId = 51000991,
          GUID = "7FACF616",
          NextDialogue = 51000914,
          SpeakNpcId = 700022,
          Subtitle = "I'm willing to sell \"puzzles\" to you. You can treat them as \"someone's scars\" or \"lost items\"."
        },
        [51001001] = {
          Camera = "30.150391,500.332031,170.427734,0.000075,-9.398094,-93.777969,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（你遠遠地就看到一個商販打扮的人站在售票處，他和售票員似乎起了些摩擦）",
          DialogueId = 51001001,
          GUID = "7FACF7BA",
          LookAt = {
            [1] = "700021:n(700033)"
          },
          NextDialogue = 51001002,
          Subtitle = "(You see a person dressed as a vendor at the ticket counter, seemingly in a dispute with the ticket seller.)"
        },
        [51001002] = {
          Camera = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
          ContentTC = "我只是問問都不行嗎！你媽媽沒教你禮貌嗎？！",
          DialogueId = 51001002,
          GUID = "7FACF7E4",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001003,
          SpeakNpcId = 700033,
          Subtitle = "Can't I even ask? Didn't your mother teach you manners?!",
          TalkActionId = {
            [1] = "700033:Angry01_Start"
          }
        },
        [51001003] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentTC = "哦好的先生，那麼在我禮貌地告訴你票價後，你打算怎麼做？",
          DialogueId = 51001003,
          GUID = "7FACF80E",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001090,
          SpeakNpcId = 700021,
          Subtitle = "Oh alright, sir. So, after I politely tell you the ticket price, what do you plan to do?",
          TalkActionId = {
            [1] = "700021:Talk01_Start"
          }
        },
        [51001004] = {
          Camera = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
          ContentTC = "你你怎麼知道我沒……",
          DialogueId = 51001004,
          GUID = "7FACF838",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001005,
          SpeakNpcId = 700033,
          Subtitle = "H...How do you know I don't have...",
          TalkActionId = {
            [1] = "700033:Angry01_End"
          }
        },
        [51001005] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentTC = "滾吧住在窩棚板裡的大富豪。",
          DialogueId = 51001005,
          GUID = "7FACF862",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001091,
          SpeakNpcId = 700021,
          Subtitle = "Off you go, you shack-dwelling tycoon.",
          TalkActionId = {
            [1] = "700021:Talk01_End"
          }
        },
        [51001006] = {
          Camera = "319.767578,148.608398,91.180664,0.000064,-0.797267,-149.347275,35.0,400.0,false,Manual,2.8",
          ContentTC = "（商販哆嗦著嘴唇轉身就走，而售票員高傲地哼了一聲，不屑地瞥向你們。）",
          DialogueId = 51001006,
          GUID = "7FACF88C",
          LookAt = {
            [1] = "0:n(700033)"
          },
          NextDialogue = 51001007,
          Scripts = "MoveTo{ActorId{700033},TargetPoint{\"Point200202_Shangfan\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          Subtitle = "(The vendor leaves, lips trembling, while the ticket seller snorts arrogantly, glancing disdainfully at you.) "
        },
        [51001007] = {
          ContentTC = "你呢？你又有什麼事？我勸你不要浪費我的時間，不然你只能和他一樣灰溜溜地滾回自己的老鼠洞。",
          DefaultLookAt = "Self",
          DialogueId = 51001007,
          GUID = "7FACF8B6",
          LookAt = {
            [1] = "0:n(700021)"
          },
          SpeakNpcId = 700021,
          Subtitle = "What about you? What do you want? I advise you not to waste my time, or you'll slink back into your rat hole just like him.",
          TalkActionId = {
            [1] = "700021:Talk03_Start"
          },
          TalkOptions = {
            [1] = 510010071,
            [2] = 510010072
          },
          TurnTo = {
            [1] = "700021:n(0)"
          }
        },
        [51001008] = {
          ContentTC = "又一個！我不管你在虛張聲勢些什麼，在我對你發出誠摯的問候之前，你最好趕緊消失！",
          DialogueId = 51001008,
          GUID = "7FACF8E0",
          SpeakNpcId = 700021,
          Subtitle = "Not another one! Before I send you my sincerest regards, you'd better disappear quickly!",
          TalkActionId = {
            [1] = "700021:Talk03_End"
          }
        },
        [51001009] = {
          ContentTC = "你、你在說什麼，我可聽不懂！",
          DialogueId = 51001009,
          GUID = "7FACF90A",
          NextDialogue = 51001010,
          SpeakNpcId = 700021,
          Subtitle = "W...What are you talking about? I don't understand!",
          TalkActionId = {
            [1] = "700021:Talk03_End"
          }
        },
        [51001010] = {
          ContentTC = "（你拿出從馬丁那拿來的「廢品」，一罐用紙疊出來的五角星，你展開其中一顆，儼然是一張已經過期的廢票。）",
          DialogueId = 51001010,
          GUID = "7FACF934",
          Subtitle = "(You take out the \"scrap\" you got from Martin, a jar of pentagonal stars made of paper. You unfold one to find out it's clearly an expired ticket.)"
        },
        [51001012] = {
          ContentTC = "……",
          DialogueId = 51001012,
          GUID = "7FACF988",
          NextDialogue = 51001013,
          SpeakNpcId = 700021,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700021:Shock_Start"
          }
        },
        [51001013] = {
          ContentTC = "（她好像陷入了極度的震驚，很快，兩行眼淚從這個趾高氣昂的售票員臉上流了下來。）",
          DialogueId = 51001013,
          GUID = "7FACF9B2",
          NextDialogue = 51001014,
          Subtitle = "(She seems extremely shocked. Before you know it, tears are streaming down the face of this haughty ticket seller.)"
        },
        [51001014] = {
          ContentTC = "為什麼……為什麼要讓我再看到它？",
          DialogueId = 51001014,
          GUID = "7FACF9DC",
          NextDialogue = 51001015,
          SpeakNpcId = 700021,
          Subtitle = "Why... Why do you have to show this to me again?",
          TalkActionId = {
            [1] = "700021:Shock_End"
          }
        },
        [51001015] = {
          ContentTC = "為什麼要提醒我不能實現的夢？",
          DialogueId = 51001015,
          GUID = "7FACFA06",
          NextDialogue = 51001016,
          SpeakNpcId = 700021,
          Subtitle = "Why remind me of dreams that can't be fulfilled?",
          TalkActionId = {
            [1] = "700021:Disagree"
          }
        },
        [51001016] = {
          ContentTC = "每天，我看著火車轟鳴而來，又看著它呼嘯而去，我希望能和那些達官貴人一樣乘上去，但留給我的只有賣不完的票。",
          DialogueId = 51001016,
          GUID = "7FACFA30",
          NextDialogue = 51001017,
          SpeakNpcId = 700021,
          Subtitle = "Every day, I watch trains roar in and out. I hope to ride them like those high officials, but all I have are unsold tickets.",
          TalkActionId = {
            [1] = "700021:Explain02_Start"
          }
        },
        [51001017] = {
          ContentTC = "有的人活了一輩子都沒見過車票長什麼樣，我比他們的運氣好一些，好歹能每天都握著這張無法兌現的入場券。",
          DialogueId = 51001017,
          GUID = "7FACFA5A",
          NextDialogue = 51001018,
          SpeakNpcId = 700021,
          Subtitle = "Some people live their entire lives without seeing a ticket. I'm luckier because at least I get to hold an unfulfillable entry pass every day."
        },
        [51001018] = {
          ContentTC = "但我的好運也就到此為止了，這個世界上有的是連星星都無法實現的願望，我正是意識到這一點，才將它們丟棄……",
          DialogueId = 51001018,
          GUID = "7FACFA84",
          SpeakNpcId = 700021,
          Subtitle = "But that's where my luck ends. In this world, there are wishes even stars can't fulfil. I realised this, and that's why I threw them away...",
          TalkActionId = {
            [1] = "700021:Explain02_End"
          },
          TalkOptions = {
            [1] = 510010181,
            [2] = 510010182,
            [3] = 510010183,
            [4] = 510010184
          }
        },
        [51001019] = {
          ContentTC = "那麼誰來為我搭這條天梯呢？仙女教母嗎？",
          DialogueId = 51001019,
          GUID = "7FACFAAE",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "Then who will build this ladder to heaven for me? The Fairy Godmother?"
        },
        [51001020] = {
          ContentTC = "你說得對，我和他們又有什麼差別呢？",
          DialogueId = 51001020,
          GUID = "7FACFAD8",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "You're right. How am I any different from them?"
        },
        [51001021] = {
          ContentTC = "是啊……我還不能失去這份我痛恨又賴以生存的工作。",
          DialogueId = 51001021,
          GUID = "7FACFB02",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "You're right... I can't lose this job that I hate yet make a living from."
        },
        [51001022] = {
          ContentTC = "我是有些疾世憤俗，但還沒發瘋，不過也許那一天也不遠了。",
          DialogueId = 51001022,
          GUID = "7FACFB2C",
          NextDialogue = 51001023,
          SpeakNpcId = 700021,
          Subtitle = "I might be disillusioned with the world, but I'm not crazy yet, though that day might not be far off."
        },
        [51001023] = {
          ContentTC = "（售票員拿走了你手中的車票星星，找了個乾燥的地方將這些寄宿著心願的紙片付之一炬）",
          DialogueId = 51001023,
          GUID = "7FACFB56",
          NextDialogue = 51001024,
          SpeakNpcId = 700021,
          Subtitle = "(The ticket seller takes the ticket stars from your hand, finds a dry place, and sets these wish-bearing papers on fire.)"
        },
        [51001024] = {
          ContentTC = "我總是罵那些想離開的傢伙是做夢，",
          DialogueId = 51001024,
          GUID = "7FACFB80",
          NextDialogue = 51001025,
          SpeakNpcId = 700021,
          Subtitle = "I always scold those who want to leave as dreamers,",
          TalkActionId = {
            [1] = "700021:Explain01_Start"
          }
        },
        [51001025] = {
          ContentTC = "但也許該從夢中醒來的是我自己。",
          DialogueId = 51001025,
          GUID = "7FACFBAA",
          NextDialogue = 51001026,
          SpeakNpcId = 700021,
          Subtitle = "but maybe it's me who should wake up from the dream.",
          TalkActionId = {
            [1] = "700021:Explain01_End"
          }
        },
        [51001026] = {
          ContentTC = "（從此以後，潔西卡只是漠然地坐在售票廳裡，不管誰問她都能得到機械的回答，好像某種售票的機器。）",
          DialogueId = 51001026,
          GUID = "7FACFBD4",
          Subtitle = "(From then on, Jessica just sat indifferently in the ticket hall, giving mechanical responses to anyone who asked like a ticket machine.)"
        },
        [51001027] = {
          ContentTC = "……",
          DialogueId = 51001027,
          GUID = "7FACFBFE",
          SpeakNpcId = 700021,
          Subtitle = "..."
        },
        [51001090] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentTC = "是禮貌地掏出一筆鉅款向我買票，還是搓搓自己漏不出一個子兒的褲兜對我頤指氣使？",
          DialogueId = 51001090,
          GUID = "7FAD0654",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001004,
          SpeakNpcId = 700021,
          Subtitle = "Will you politely pull out a huge amount of money to buy a ticket, or will you fiddle with your empty pockets and boss me around?"
        },
        [51001091] = {
          Camera = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
          ContentTC = "這天氣正適合你一邊擦火柴一邊叫奶奶，在夢裡親奶奶帶你坐火車，到時候你想去哪去哪，再也不用在我跟前丟人現眼！",
          DialogueId = 51001091,
          GUID = "7FAD067E",
          LookAt = {
            [1] = "0:n(700021)"
          },
          NextDialogue = 51001006,
          SpeakNpcId = 700021,
          Subtitle = "This weather is just right for you to strike a match and call for grandma, dreaming that she takes you on a train. Go wherever you like in your dream, and stop shaming yourself in front of me!"
        },
        [51001092] = {
          ContentTC = "（不過好事是她再也不像從前一樣脾氣暴躁，罵罵咧咧了。）",
          DialogueId = 51001092,
          GUID = "7FAD06A8",
          Subtitle = "(But the good thing is she was no longer as temperamental and foul-mouthed as before.)"
        },
        [51001101] = {
          ContentTC = "（不知從何處遊蕩而來的穢獸叼著一個記事本，擊敗穢獸後，你將它撿了起來……）",
          DialogueId = 51001101,
          GUID = "7FAD0822",
          NextDialogue = 51001102,
          Subtitle = "(A Filthoid, wandering from nowhere, clutched a notebook in its jaws. After defeating the Filthoid, you picked up the notebook...)"
        },
        [51001102] = {
          ContentTC = "（如果日記上記錄的內容屬實，那麼失憶少女的真實身份，就已十分明了了。）",
          DialogueId = 51001102,
          GUID = "7FAD084C",
          NextDialogue = 51001103,
          Subtitle = "(If the words in this diary are true... then the truth is clear at last.)"
        },
        [51001103] = {
          ContentTC = "（……安妮已經不幸離世，而得到她衣物的另一位少女愛麗絲活了下來。儘管在雪山幸存，但連續高燒還是奪走了愛麗絲的記憶。）",
          DialogueId = 51001103,
          GUID = "7FAD0876",
          Subtitle = "(...Annie has tragically passed away, while the other girl, Alice, who ended up with Annie's clothes, has survived. Although Alice made it through the ordeal in the snowy mountains, the severe fevers she suffered afterwards took away her memories.)"
        },
        [51001201] = {
          ContentTC = "居然有狩月人能找到這裡，看來你和它們一樣，有著成為英雄的可能啊。",
          DialogueId = 51001201,
          GUID = "7FAD188A",
          NextDialogue = 51001212,
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001202] = {
          ContentTC = "嗯，除了我這怪老頭，應該也沒其他人會養金翎鳥了。",
          DialogueId = 51001202,
          GUID = "7FAD18B4",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Well, who else but this old geezer would bother keeping these birds nowadays.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001203] = {
          ContentTC = "吃？？你知道金翎鳥對礦工來說有多珍貴嗎！",
          DialogueId = 51001203,
          GUID = "7FAD18DE",
          NextDialogue = 51001204,
          SpeakNpcId = 700003,
          Subtitle = "Are you insane?? Do you have any idea how precious these birds are to a miner?!",
          TalkActionId = {
            [1] = "700003:Disagree"
          }
        },
        [51001204] = {
          ContentTC = "礦工們越加依賴煉金院鼓搗出來的那些高科技，反而忽視了傳統的探測手段。",
          DialogueId = 51001204,
          GUID = "7FAD1908",
          NextOptions = {
            [1] = 510012041,
            [2] = 510012042,
            [3] = 510012043
          },
          SpeakNpcId = 700003,
          Subtitle = "Miners today have grown so reliant on the high-tech gadgets from the Alchemy Academy, that they have forgotten the old ways.",
          bForbidSkipOptions = true
        },
        [51001205] = {
          ContentTC = "是啊，正因為它們對毒氣格外敏感，以前我們在進行地下工作的時候都會帶一隻在身邊，幫我們探測坑道是否安全。",
          DialogueId = 51001205,
          GUID = "7FAD1932",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Exactly, their amazing sensitivity to harmful gases made them a must-have for us miners in the old days. We'd always have one by our side underground to help detect whether the tunnels were safe.",
          TalkActionId = {
            [1] = "700003:Agree"
          }
        },
        [51001206] = {
          ContentTC = "不錯，真是不錯，現在像你這樣有獨特理解的年輕人可不多了。",
          DialogueId = 51001206,
          GUID = "7FAD195C",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Well said. Quite rare to find young folks with such insight these days.",
          TalkActionId = {
            [1] = "700003:Explain01_Start"
          }
        },
        [51001207] = {
          ContentTC = "哼，我做這些是為了礦工，不需要他人的理解。",
          DialogueId = 51001207,
          GUID = "7FAD1986",
          NextDialogue = 51001208,
          SpeakNpcId = 700003,
          Subtitle = "Hmph, I do what I do for us miners' sake. I don't need others' approval.",
          TalkActionId = {
            [1] = "700003:Explain01_End"
          }
        },
        [51001208] = {
          ContentTC = "沒有靈魂的工具會失靈，會背叛。傾注情感的伙伴才會陪你度過每一個難關。",
          DialogueId = 51001208,
          GUID = "7FAD19B0",
          NextDialogue = 51001209,
          SpeakNpcId = 700003,
          Subtitle = "Soulless tools may fail you, or even betray you. It's the companion you've always cherished that will stand by you through every trial.",
          TalkActionId = {
            [1] = "700003:Think_Start"
          }
        },
        [51001209] = {
          ContentTC = "等哪天煉金院的那些探測工具失靈了，也許還能靠這些伙伴們挽回更多礦工的生命……",
          DialogueId = 51001209,
          GUID = "7FAD19DA",
          NextDialogue = 51001210,
          SpeakNpcId = 700003,
          Subtitle = "Should the day come when the Academy's fancy tools give out, it may well be these loyal friends that save miners' lives...",
          TalkActionId = {
            [1] = "700003:Think_End"
          }
        },
        [51001210] = {
          ContentTC = "（老人看向一旁的土堆，嘴唇微動，努力地想要再說些什麼，最終只從嘴裡吐出一聲歎息。）",
          DialogueId = 51001210,
          GUID = "7FAD1A04",
          Subtitle = "(The old miner's gaze settles on a nearby mound, his lips trembling with unvoiced thoughts, culminating in nothing but a weary sigh.)"
        },
        [51001211] = {
          ContentTC = "（老人不發一語，只是每過一會，就從回憶中抽身，緩緩吐出一聲歎息。不知是對同伴的緬懷，還是對時代變遷的感歎。）",
          DialogueId = 51001211,
          GUID = "7FAD1A2E",
          Subtitle = "(In silence, the elder periodically snaps from his thoughts, letting out a lingering sigh. It's unclear whether it's a tribute to a fallen comrade or a lament for the changing times.)"
        },
        [51001212] = {
          ContentTC = "老人溫柔地注視著空中的一小片黑點，你順著他的視線遠眺，看到了一群離去的飛鳥。待到所有鳥群飛走後，老人才轉身繼續與你交談。",
          DialogueId = 51001212,
          GUID = "7FAD188B",
          NextOptions = {
            [1] = 510012011,
            [2] = 510012012
          },
          Subtitle = "The elder watched a dark speck in the sky with a soft gaze. You looked out and saw a distant flock of birds. The conversation resumed only after the last one had vanished.",
          bForbidSkipOptions = true
        },
        [51001301] = {
          ContentTC = "天殺的卡蜜拉！不識貨的瞎眼婆娘！",
          DialogueId = 51001301,
          GUID = "7FAD28F2",
          NextDialogue = 510013013,
          SpeakNpcId = 700014,
          Subtitle = "That blasted Camilla! Stupid hag! She has no idea what good stuff tastes like!"
        },
        [51001302] = {
          ContentTC = "我呸！老子罵兩句怎麽了！",
          DialogueId = 51001302,
          GUID = "7FAD291C",
          NextDialogue = 51001304,
          SpeakNpcId = 700014,
          Subtitle = "Pah! What's it to you?"
        },
        [51001303] = {
          ContentTC = "醫藥費！必須給我醫藥費！你快把我鼻子打歪了！",
          DialogueId = 51001303,
          GUID = "7FAD2946",
          NextDialogue = 51001304,
          SpeakNpcId = 700014,
          Subtitle = "Ugh! You must pay for this! Gimme your money! Nearly broke my nose, you!"
        },
        [51001304] = {
          ContentTC = "這麽著急替她出頭？哈，我知道了，你也是「卡蜜拉後援會」的蠢蛋之一！可悲啊，被那個虛偽的女人騙得團團轉！",
          DialogueId = 51001304,
          GUID = "7FAD2970",
          NextOptions = {
            [1] = 510013041,
            [2] = 510013042,
            [3] = 510013043
          },
          SpeakNpcId = 700014,
          Subtitle = "Jumping to her defence, are we? Ha, you must be one of those \"Camilla fan club\" idiots! Pathetic losers, all bamboozled by that two-faced witch!",
          bForbidSkipOptions = true
        },
        [51001305] = {
          ContentTC = "嘴巴剛剛不還挺能說的嗎，怎麽，腦袋終於被冷風吹醒，看清那婆娘了？",
          DialogueId = 51001305,
          GUID = "7FAD299A",
          SpeakNpcId = 700014,
          Subtitle = "Had a sharp tongue just now, didn't ya? What, did the cold finally clear your head enough to see through that hag?"
        },
        [51001306] = {
          ContentTC = "你，你說什麽……",
          DialogueId = 51001306,
          GUID = "7FAD29C4",
          NextDialogue = 510013061,
          SpeakNpcId = 700014,
          Subtitle = "Wh—What are you talking about..."
        },
        [51001307] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          ContentTC = "如果你貨比三家，就會發現卡蜜拉賣的酒和冰湖城格格不入。",
          DialogueId = 51001307,
          GUID = "7FAD29EE",
          LookAt = {
            [1] = "700014:n(100001)",
            [2] = "100001:n(700014)"
          },
          NextDialogue = 51001308,
          SpeakNpcId = 700014,
          Subtitle = "If you shopped around, you'd see Camilla's brew is an odd fit for Icelake.",
          TalkActionId = {
            [1] = "700014:Explain01_Start"
          }
        },
        [51001308] = {
          ContentTC = "冰湖城裡所有的酒館老板都和我有合作，我家的手藝有口皆碑，只有她拒絕加入，油鹽不進的傢伙！你就不覺得這裡面有貓膩嗎？！",
          DialogueId = 51001308,
          GUID = "7FAD2A18",
          NextDialogue = 51001309,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{700014},AnimationId{\"Explain02_End\"},Duration{0}}",
          SpeakNpcId = 700014,
          Subtitle = "I mean, in Icelake, every tavern owner except her is my client. My stuff's good enough to knock people out, but she always turns me down — what a stubborn mule! Doesn't that seem fishy to you?",
          TalkActionId = {
            [1] = "700014:Explain02_Start"
          }
        },
        [51001309] = {
          ContentTC = "事實是，我家的酒價錢只有卡蜜拉的一半，而且口味幾乎沒有差別，我敢保證！只要在我這裡嘗試一次，就能體會到「實惠」的味道。",
          DialogueId = 51001309,
          GUID = "7FAD2A42",
          NextOptions = {
            [1] = 510013091,
            [2] = 510013092
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"87.344482,-123.555176,125.176514,0.000141,5.699588,170.405472,35.000008,177.462952,false,Manual,5.0"},duration{0}},
LookAt{_delay{5.2},LookAtDescription{"100001:n(100001)"}},
PlayAnimation{_delay{5.5},ActorId{100001},AnimationId{"Think_Start"},Duration{0.5}},
PlayAnimation{_delay{5.5},ActorId{700014},AnimationId{"Talk01_End"},Duration{0.5}}
}]],
          SpeakNpcId = 700014,
          Subtitle = "Fact is, my booze is half the price of Camilla's and tastes just as good — I assure you! Try it, and you'll understand what a real bargain means.",
          TalkActionId = {
            [1] = "700014:Talk01_Start"
          }
        },
        [51001310] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          ContentTC = "哈哈，還是您有眼光，多謝惠顧！",
          DialogueId = 51001310,
          GUID = "7FAD2A6C",
          NextDialogue = 51001311,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{700014},AnimationId{\"Agree\"},Duration{1}}",
          SpeakNpcId = 700014,
          Subtitle = "Ha, now we're talking! Thanks for your patronage!",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51001311] = {
          Camera = "35.446289,521.132324,214.651123,0.000094,-12.499997,-89.999947,45.0,696.082092,false,Manual,5.0",
          ContentTC = "慢著！等一下。",
          DialogueId = 51001311,
          GUID = "7FAD2A96",
          LookAt = {
            [1] = "700014:n(200003)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001312,
          Scripts = [[
PARA{
MoveTo{_delay{1},ActorId{200003},TargetPoint{"PDien1"},MoveSpeed{60},Visibility{"Show"}},
SEQ{
CameraMoveTo{_delay{1},TargetPosition{"35.446289,521.132324,214.651123,0.000096,-10.999998,-89.999939,45.0,388.895966,false,Manual,5.0"},duration{3}},
CameraMoveTo{TargetPosition{"-104.617432,-216.151855,139.375488,0.000126,-2.100092,62.600006,35.0,384.123901,false,Manual,5.0"},duration{0}},
CameraMoveTo{TargetPosition{"-146.654297,-177.086426,138.553223,0.000128,-0.500031,40.001247,35.0,272.58197,false,Manual,5.0"},duration{2.5}}
},
TurnTo{_delay{2.5},TurnToDescription{"100001:n(200003)"}},
TurnTo{_delay{5},TurnToDescription{"700014:n(200003)"}},
LookAt{_delay{6.5},LookAtDescription{"200003:n(100001)"}},
PlayAnimation{_delay{6.7},ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Hold on a moment."
        },
        [51001312] = {
          ContentTC = "冰湖城的人啊，無論是誰，說的話你只信一半就好。",
          DialogueId = 51001312,
          GUID = "7FAD2AC0",
          NextDialogue = 51001315,
          SpeakNpcId = 200003,
          Subtitle = "Just a word of advice — always take what you hear in Icelake with a grain of salt."
        },
        [51001313] = {
          Camera = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
          ContentTC = "別算了啊，你不試試怎麽知道——",
          DialogueId = 51001313,
          GUID = "7FAD2AEA",
          NextDialogue = 51001314,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{700014},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 700014,
          Subtitle = "Come on, give it a try and you'll—",
          TalkActionId = {
            [1] = "700014:Talk01_Start",
            [2] = "100001:Think_End"
          }
        },
        [51001314] = {
          Camera = "35.446289,521.132324,214.651123,0.000094,-12.499997,-89.999947,45.0,696.082092,false,Manual,5.0",
          ContentTC = "不錯嘛，看來你還保持著最基本的戒心。",
          DialogueId = 51001314,
          GUID = "7FAD2B14",
          LookAt = {
            [1] = "700014:n(200003)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001315,
          Scripts = [[
PARA{
MoveTo{_delay{1},ActorId{200003},TargetPoint{"PDien1"},MoveSpeed{60},Visibility{"Show"}},
SEQ{
CameraMoveTo{_delay{1},TargetPosition{"35.446289,521.132324,214.651123,0.000096,-10.999998,-89.999939,45.0,388.895966,false,Manual,5.0"},duration{3}},
CameraMoveTo{TargetPosition{"-104.617432,-216.151855,139.375488,0.000126,-2.100092,62.600006,35.0,384.123901,false,Manual,5.0"},duration{0}},
CameraMoveTo{TargetPosition{"-122.449951,-202.495117,138.553223,0.000128,-1.900083,50.401207,35.0,272.58197,false,Manual,5.0"},duration{2.5}}
},
TurnTo{_delay{2.5},TurnToDescription{"100001:n(200003)"}},
TurnTo{_delay{5},TurnToDescription{"700014:n(200003)"}},
LookAt{_delay{6.5},LookAtDescription{"200003:n(100001)"}},
PlayAnimation{_delay{6.7},ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Not bad — I see you're keeping your wits about you."
        },
        [51001315] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          ContentTC = "你你、你想幹什麽！怎麽還擋著別人做生意？",
          DialogueId = 51001315,
          GUID = "7FAD2B3E",
          LookAt = {
            [1] = "200003:n(700014)"
          },
          NextDialogue = 51001316,
          SpeakNpcId = 700014,
          Subtitle = "Wh—What do you want!? I didn't go to your place and meddle in your business!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          }
        },
        [51001316] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          ContentTC = "別誤會，我對你的買賣沒什麽興趣，我來找你是要和你談談另一件事。",
          DialogueId = 51001316,
          GUID = "7FAD2B68",
          NextDialogue = 51001317,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "Don't get me wrong, I'm not interested in your business. I'm here to discuss something else with you.",
          TalkActionId = {
            [1] = "200003:Talk03_End",
            [2] = "700014:Angry01_End"
          },
          TurnTo = {
            [1] = "100001:p(-30)"
          }
        },
        [51001317] = {
          ContentTC = "最近總有人冒用我的名字到處販賣劣質的假貨，說什麽「這是水仙平原推出的新品」啦，「在水仙平原的吧臺上被一搶而光，想喝都喝不到」啦……",
          DialogueId = 51001317,
          GUID = "7FAD2B92",
          NextDialogue = 51001318,
          Scripts = "PlayAnimation{_delay{3},ActorId{200003},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "Recently, someone's been using my name to sell shoddy knock-offs, claiming they're \"the new special from The Asphodel\", or that they'd be \"sold out at the bar in a minute, impossible to snag a sip...\"",
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001318] = {
          ContentTC = "你也知道，做生意講究的無非就是個信譽，酒水的質量關乎水仙平原的臉面，我總不能任由他人到處抹黑。",
          DialogueId = 51001318,
          GUID = "7FAD2BBC",
          NextDialogue = 51001319,
          SpeakNpcId = 200003,
          Subtitle = "As you know, in business, brand image is everything. The quality of our drinks is the face of The Asphodel, and I can't just let someone drag our name through the mud.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51001319] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          ContentTC = "這、這……這和我有什麽關系？我可沒工夫多管你的閑事！",
          DialogueId = 51001319,
          GUID = "7FAD2BE6",
          NextDialogue = 51001320,
          Scripts = "PlayAnimation{_delay{3},ActorId{700014},AnimationId{\"Sigh_End\"},Duration{1}}",
          SpeakNpcId = 700014,
          Subtitle = "...Wh—What's that got to do with me? I don't have time for your problems!",
          TalkActionId = {
            [1] = "700014:Sigh_Start"
          }
        },
        [51001320] = {
          ContentTC = "讓開讓開，我要走了，你不做生意我還得做呢。",
          DialogueId = 51001320,
          GUID = "7FAD2C10",
          NextDialogue = 51001321,
          SpeakNpcId = 700014,
          Subtitle = "Outta my way. I've got business to run.",
          TalkActionId = {
            [1] = "700014:Confident_Start"
          }
        },
        [51001321] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          ContentTC = "走？就在不久前水仙平原拒絕與你合作的時候，我讓人保留了一份你售賣的酒水樣本，你猜怎麽樣？",
          DialogueId = 51001321,
          GUID = "7FAD2C3A",
          NextDialogue = 51001322,
          SpeakNpcId = 200003,
          Subtitle = "Not so fast. When The Asphodel turned you down, I kept a sample of your booze. And guess what—"
        },
        [51001322] = {
          ContentTC = "你帶來的的貨品和市面上那些冒充水仙平原的假貨成分一模一樣。這恐怕不僅僅是巧合這麽簡單吧？",
          DialogueId = 51001322,
          GUID = "7FAD2C64",
          NextDialogue = 51001323,
          SpeakNpcId = 200003,
          Subtitle = "Your booze exactly matches the knock-offs on the market. Seems more than coincidental, wouldn't you say?"
        },
        [51001323] = {
          Camera = "-209.837891,-298.262207,123.758301,0.000147,1.099674,42.806149,35.000008,408.143951,false,Manual,5.0",
          ContentTC = "什麽意思！你少血口噴人！我我我、我怎麽可能賣假貨！你就是怕我的酒搶了你的老主顧，才、才在這裡胡說八道！",
          DialogueId = 51001323,
          GUID = "7FAD2C8E",
          NextOptions = {
            [1] = 510013231,
            [2] = 510013232
          },
          Scripts = [[
PARA{

CameraMoveTo{_delay{5},TargetPosition{"87.344482,-123.555176,125.176514,0.000141,5.699588,170.405472,35.000008,177.462952,false,Manual,5.0"},duration{0}},
MoveTo{_delay{6},ActorId{200003},TargetPoint{"PDien1"},MoveSpeed{10},Visibility{"Hide"}},
TurnTo{_delay{6},TurnToDescription{"700014:p(60)"}},
LookAt{_delay{6},LookAtDescription{"100001:n(700014)"}},
LookAt{_delay{7},LookAtDescription{"100001:n(100001)"}},
PlayAnimation{_delay{7.2},ActorId{100001},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 700014,
          Subtitle = "What are you implying!? That's slander! I—I—I'm not selling fakes! You're just scared my booze will steal your regulars — that's why you're spouting nonsense here!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          bForbidSkipOptions = true
        },
        [51001324] = {
          Camera = "-126.292969,-236.144531,121.561768,0.000212,4.098496,38.002239,35.0,288.862579,false,Manual,5.0",
          ContentTC = "什麽假酒？罵誰賣假酒？我算看明白了，你們兩個就是一丘之貉，在這裡顛倒黑白……",
          DialogueId = 51001324,
          GUID = "7FAD2CB8",
          LookAt = {
            [1] = "700014:n(100001)"
          },
          NextDialogue = 51001325,
          SpeakNpcId = 700014,
          Subtitle = "Fake booze? You call my stuff fake? Now I see, you two are in cahoots, twisting the truth..."
        },
        [51001325] = {
          Camera = "186.59668,149.714844,103.179443,0.000225,1.098103,-121.993439,35.0,286.170746,false,Manual,5.0",
          ContentTC = "好！那我就讓你看看這是不是假貨！",
          DialogueId = 51001325,
          FinalCamera = "202.597412,139.721191,94.749023,0.000225,1.098103,-121.993439,35.0,166.090637,false,Manual,5.0",
          GUID = "7FAD2CE2",
          NextDialogue = 51001327,
          SpeakNpcId = 700014,
          Subtitle = "Fine! I'll show you this isn't fake!",
          TalkActionId = {
            [1] = "700014:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51001326] = {
          Camera = "-126.292969,-236.144531,121.561768,0.000212,4.098496,38.002239,35.0,288.862579,false,Manual,5.0",
          ContentTC = "喝……喝就喝，誰怕誰啊？",
          DialogueId = 51001326,
          GUID = "7FAD2D0C",
          LookAt = {
            [1] = "700014:n(100001)"
          },
          NextDialogue = 51001327,
          SpeakNpcId = 700014,
          Subtitle = "...Fine! That'll show her!"
        },
        [51001327] = {
          ContentTC = "（迪恩雙手抱住一桶酒，仰頭痛飲。）",
          DialogueId = 51001327,
          GUID = "7FAD2D36",
          IsBlack = 1,
          LookAt = {
            [1] = "200003:n(700014)",
            [2] = "100001:n(700014)"
          },
          NextDialogue = 51001328,
          Scripts = "MoveTo{ActorId{200003},TargetPoint{\"PDien1\"},MoveSpeed{100},Visibility{\"Show\"}}",
          Subtitle = "(Dean grabs a barrel of liquor and starts guzzling it down.)"
        },
        [51001328] = {
          Camera = "-58.997803,-300.757812,211.441162,0.000378,-35.900509,52.402233,35.000008,288.862579,false,Manual,5.0",
          ContentTC = "（可不等迪恩喝完，他仿佛就像是被人打了一拳，身形一晃重重砸在地上，灑在地上的液體仍然散發著濃郁的氣味。）",
          DialogueId = 51001328,
          FinalCamera = "-163.664062,-436.681641,303.508057,0.000378,-35.900513,52.404461,35.000008,288.862579,false,Manual,5.0",
          GUID = "7FAD2D60",
          LookAt = {
            [1] = "700014:n(700014)"
          },
          NextOptions = {
            [1] = 510013281
          },
          Subtitle = "(But before he can drain it, he staggers as if struck in the gut and then crashes heavily to the ground, his spilt drink reeking up the place.)",
          TalkActionId = {
            [1] = "700014:Onground02",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10
        },
        [51001329] = {
          Camera = "-139.912598,-187.989746,131.374023,0.00013,0.499936,50.203888,35.0,272.58197,false,Manual,5.0",
          ContentTC = "我說過，冰湖城可不是那種人人安居樂業的好地方，想要在這裡站穩腳跟處處都得留個心眼兒。",
          DialogueId = 51001329,
          GUID = "7FAD2D8A",
          LookAt = {
            [1] = "200003:n(100001)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 51001330,
          SpeakNpcId = 200003,
          Subtitle = "As I've always said, Icelake isn't some idyllic haven. Keeping your wits about you is the only way to survive here.",
          TurnTo = {
            [1] = "100001:p(30)"
          }
        },
        [51001330] = {
          ContentTC = "唉，要是就這麽放著不管他的小命可就不保了，還是先差人把他送進醫院，再和他清算總賬吧。",
          DialogueId = 51001330,
          GUID = "7FAD2DB4",
          NextDialogue = 51001331,
          SpeakNpcId = 200003,
          Subtitle = "*sigh* If we just leave him be, he might just kick it. I'll get him to a hospital, and settle the score with him later."
        },
        [51001331] = {
          ContentTC = "還有，雖然不像迪恩這麽「實惠」，但如果你想喝點一分錢一分貨的酒，水仙平原隨時歡迎你。",
          DialogueId = 51001331,
          GUID = "7FAD2DDE",
          SpeakNpcId = 200003,
          Subtitle = "By the way — unlike Dean's \"bargains\", if you're looking for quality that truly matches the price, The Asphodel welcomes you anytime."
        },
        [51001332] = {
          ContentTC = "要說哪的酒最好，還得是水仙平原啊。",
          DialogueId = 51001332,
          GUID = "7FAD2E08",
          NextDialogue = 51001333,
          SpeakNpcId = 790009,
          Subtitle = "The best brews? You'll find them at The Asphodel, no question.",
          TalkActionId = {
            [1] = "790009:Talk02_Start"
          }
        },
        [51001333] = {
          ContentTC = "這裡的酒氣味醇香，口味豐滿，最難能可貴的是入口綿甜幹凈，回味悠長。",
          DialogueId = 51001333,
          GUID = "7FAD2E32",
          NextDialogue = 51001334,
          SpeakNpcId = 790009,
          Subtitle = "Intoxicating aroma, full-bodied flavours, and what sets it apart most? The smooth, clean finish — it lingers on the tongue."
        },
        [51001334] = {
          ContentTC = "正所謂好酒是這世上最勾心的情人啊……不行，我得再來一杯……",
          DialogueId = 51001334,
          GUID = "7FAD2E5C",
          SpeakNpcId = 790009,
          Subtitle = "A fine drink is like a seductive lover... Ah, I think I need another refill...",
          TalkActionId = {
            [1] = "790009:Talk02_End"
          }
        },
        [51001335] = {
          ContentTC = "你不知道吧，水仙平原最厲害的地方可不止有這兒的飲品。",
          DialogueId = 51001335,
          GUID = "7FAD2E86",
          NextDialogue = 51001336,
          SpeakNpcId = 790010,
          Subtitle = "There's more to The Asphodel than just great drinks.",
          TalkActionId = {
            [1] = "790010:Talk03_Start"
          }
        },
        [51001336] = {
          ContentTC = "在水仙平原，你根本就不用擔心被卷進醉漢一時興起的茬架，或者被不知道哪來的瘋子打得頭破血流……",
          DialogueId = 51001336,
          GUID = "7FAD2EB0",
          NextDialogue = 51001337,
          SpeakNpcId = 790010,
          Subtitle = "Because you can enjoy a tipple here without having to worry about getting caught in a brawl with drunkards or getting whacked by some random lunatic..."
        },
        [51001337] = {
          ContentTC = "要知道這可是卡蜜拉的地盤，只要提起她的名字，哈，看誰還敢鬧事。",
          DialogueId = 51001337,
          GUID = "7FAD2EDA",
          SpeakNpcId = 790010,
          Subtitle = "After all, this is Camilla's turf. Her name alone keeps everyone in line — no one dares stir up trouble here.",
          TalkActionId = {
            [1] = "790010:Talk03_End"
          }
        },
        [51001338] = {
          ContentTC = "嗚嗚……嗚嗚嗚……",
          DialogueId = 51001338,
          GUID = "7FAD2F04",
          NextDialogue = 51001339,
          SpeakNpcId = 790011,
          Subtitle = "Boohoo... Boohoo...",
          TalkActionId = {
            [1] = "790011:Sigh_Start"
          }
        },
        [51001339] = {
          ContentTC = "愛！你告訴我什麽是愛的滋味？是我加入卡蜜拉後援會時的欣喜若狂？還是聽到她解散後援會話語時的心碎……",
          DialogueId = 51001339,
          GUID = "7FAD2F2E",
          NextDialogue = 51001340,
          SpeakNpcId = 790011,
          Subtitle = "Love... what does it really taste like!? Was it the rush of ecstasy when I joined Camilla's fan club, or the crushing heartbreak when I heard she disbanded it?"
        },
        [51001340] = {
          ContentTC = "嗚嗚……只有卡蜜拉大人的微笑才能將我這破碎的心重新粘連！",
          DialogueId = 51001340,
          GUID = "7FAD2F58",
          SpeakNpcId = 790011,
          Subtitle = "Boohoo... Only Lady Camilla's smile can piece back together my shattered heart!",
          TalkActionId = {
            [1] = "790011:Sigh_End"
          }
        },
        [51001401] = {
          ContentTC = "「下雨了，媽媽的花被澆壞了，所以天空在水坑裡賠給媽媽無數朵小花。」",
          DialogueId = 51001401,
          GUID = "7FAD395A",
          NextDialogue = 51001402,
          SpeakNpcId = 700017,
          Subtitle = "\"The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles.\"",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          }
        },
        [51001402] = {
          ContentTC = "——您知道嗎，這首詩叫做《道歉》，是我六歲的學生寫的。",
          DialogueId = 51001402,
          GUID = "7FAD3984",
          NextOptions = {
            [1] = 510014021,
            [2] = 510014022,
            [3] = 510014023
          },
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Apology\", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51001403] = {
          ContentTC = "（桑尼身邊的孩子們衣著華麗，像是群貴族出身的孩子。）",
          DialogueId = 51001403,
          GUID = "7FAD39AE",
          NextDialogue = 51001404,
          Subtitle = "(The children around Sunny are in finery, presumably from aristocratic families.)"
        },
        [51001404] = {
          ContentTC = "哈哈，不瞞您說，像這樣的詩還有很多，我也經常會被他們的奇思妙想打動。",
          DialogueId = 51001404,
          GUID = "7FAD39D8",
          NextDialogue = 51001405,
          SpeakNpcId = 700017,
          Subtitle = "Haha, actually, there are many more like this one, and their creativity never ceases to amaze me.",
          TalkActionId = {
            [1] = "700017:Explain01_Start"
          }
        },
        [51001405] = {
          ContentTC = "我始終覺得天馬行空的創造力與想像力——這才是一個孩子最珍貴的東西。",
          DialogueId = 51001405,
          GUID = "7FAD3A02",
          NextDialogue = 51001406,
          SpeakNpcId = 700017,
          Subtitle = "I've always believed that unfettered creativity and imagination are a child's most precious qualities.",
          TalkActionId = {
            [1] = "700017:Explain01_End"
          }
        },
        [51001406] = {
          ContentTC = "只不過對貴族而言，我這樣的老師是最不稱職的。",
          DialogueId = 51001406,
          GUID = "7FAD3A2C",
          NextOptions = {
            [1] = 510014061
          },
          RestartTag = 51001406,
          SpeakNpcId = 700017,
          Subtitle = "It's just that, to the nobility, a tutor like me is deemed quite incompetent.",
          bForbidSkipOptions = true
        },
        [51001407] = {
          ContentTC = "啊，上課時間要到了，抱歉不能再耽誤了。",
          DialogueId = 51001407,
          GUID = "7FAD3A56",
          NextDialogue = 51001408,
          SpeakNpcId = 700017,
          Subtitle = "Ah, it's nearly time for class. Excuse me, I have to go now."
        },
        [51001408] = {
          ContentTC = "（桑尼看了一眼時間，示意後匆忙離開了。）",
          DialogueId = 51001408,
          GUID = "7FAD3A80",
          SpeakNpcId = 700017,
          Subtitle = "(Sunny glanced at her pocket watch, excused herself, and hurried off.)"
        },
        [51001409] = {
          ContentTC = "哈哈，多謝你的肯定，我從來都沒有後悔過這個決定，哪怕我將失去這份工作。",
          DialogueId = 51001409,
          GUID = "7FAD3AAA",
          NextDialogue = 51001410,
          SpeakNpcId = 700017,
          Subtitle = "Haha, thank you. I've never once regretted my choice, even if it costs me my job.",
          TalkActionId = {
            [1] = "700017:Agree"
          }
        },
        [51001410] = {
          ContentTC = "在這之後，我的孩子們就不得不走上整日背誦《帝國律法》或者鑽研如何通過軍團考核的路了。",
          DialogueId = 51001410,
          GUID = "7FAD3AD4",
          NextDialogue = 51001411,
          SpeakNpcId = 700017,
          Subtitle = "In the future, my students will have to embark on a path filled with Imperial Law recitations and military test preparations."
        },
        [51001411] = {
          ContentTC = "這是最後一課，我得告訴他們：無論將要面對的現實如何殘酷與無趣，我會為他們的夢而驕傲，永遠。",
          DialogueId = 51001411,
          GUID = "7FAD3AFE",
          NextDialogue = 51001490,
          SpeakNpcId = 700017,
          Subtitle = "This being our final lesson, I must let them know — no matter the cruelty or drudgery of the reality ahead, I'll forever be proud of their dreams.",
          TalkActionId = {
            [1] = "700083:Think_End",
            [2] = "700084:Think_End",
            [3] = "700085:Confident_End"
          }
        },
        [51001412] = {
          ContentTC = "當然！我得到了世上最好的東西！",
          DialogueId = 51001412,
          GUID = "7FAD3B28",
          NextDialogue = 51001413,
          SpeakNpcId = 700017,
          Subtitle = "Absolutely! I've received the most amazing gift in the world!",
          TalkActionId = {
            [1] = "700017:Agree"
          }
        },
        [51001413] = {
          ContentTC = "「老師說我是天上的星星，她只是海上的倒影。",
          DialogueId = 51001413,
          GUID = "7FAD3B52",
          NextDialogue = 51001414,
          SpeakNpcId = 700017,
          Subtitle = "\"My teacher says I'm a star in the sky, and she's just my reflection in the sea at night.\"",
          TalkActionId = {
            [1] = "700017:Explain01_Start"
          }
        },
        [51001414] = {
          ContentTC = "可天和海離了一萬米，這樣不好。",
          DialogueId = 51001414,
          GUID = "7FAD3B7C",
          NextDialogue = 51001415,
          SpeakNpcId = 700017,
          Subtitle = "\"But heavens and seas are so far apart — that doesn't seem right.\""
        },
        [51001415] = {
          ContentTC = "所以我說：看！流星！」",
          DialogueId = 51001415,
          GUID = "7FAD3BA6",
          NextDialogue = 51001416,
          SpeakNpcId = 700017,
          Subtitle = "\"So I say: 'Look! A shooting star zooming by!'\"",
          TalkActionId = {
            [1] = "700017:Explain01_End"
          }
        },
        [51001416] = {
          ContentTC = "——您知道嗎，這首詩叫做《見面》，是我六歲的學生寫的。",
          DialogueId = 51001416,
          GUID = "7FAD3BD0",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Come to You\", and it's written by a six-year-old student of mine."
        },
