          GUID = "7FAEF578",
          NextDialogue = 51004109,
          SpeakNpcId = 700105,
          Subtitle = "...Yeah!",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004109] = {
          ContentTC = "多虧了有你在……你掄起拳頭的樣子真的很威風呢！",
          DialogueId = 51004109,
          GUID = "7FAEF5A2",
          NextOptions = {
            [1] = 510041091,
            [2] = 510041092
          },
          SpeakNpcId = 700105,
          Subtitle = "Thanks for helping me... You looked really cool throwing those punches!",
          bForbidSkipOptions = true
        },
        [51004110] = {
          ContentTC = "誒，是、是嗎？我只是……把以前偷偷在心裡想的話說出來了。",
          DialogueId = 51004110,
          GUID = "7FAEF5CC",
          NextDialogue = 51004111,
          SpeakNpcId = 700105,
          Subtitle = "R—Really? I... I just said the things that I'd wanted to say but couldn't.",
          TalkActionId = {
            [1] = "700105:Shock_Start"
          }
        },
        [51004111] = {
          ContentTC = "謝謝你，我長這麽大，還是頭一次心裡這麽暢快呢！",
          DialogueId = 51004111,
          GUID = "7FAEF5F6",
          NextDialogue = 51004112,
          SpeakNpcId = 700105,
          Subtitle = "Thank you so much. I've never felt so relieved and happy in my life!",
          TalkActionId = {
            [1] = "700105:Shock_End"
          }
        },
        [51004112] = {
          ContentTC = "不用謝，他們短時間應該不會來找你麻煩了，我送你回家吧。這是我的地址——如果他們再惹你，就來找我。",
          DialogueId = 51004112,
          GUID = "7FAEF620",
          NextDialogue = 51004113,
          SpeakNpcId = 100001,
          Subtitle = "You're welcome. Your classmates should leave you alone for a while. I'll walk you home. Here, this is my address — come find me if they give you trouble again."
        },
        [51004113] = {
          ContentTC = "我不想回家……！",
          DialogueId = 51004113,
          GUID = "7FAEF64A",
          NextDialogue = 51004114,
          SpeakNpcId = 700105,
          Subtitle = "I don't want to go home...!",
          TalkActionId = {
