        },
        [51004147] = {
          ContentTC = "他們一直都告訴我，卡戎是惡魔的孩子，是腦袋笨笨又一肚子壞水的，總是在做壞事的……",
          DialogueId = 51004147,
          GUID = "7FAEFBDE",
          NextDialogue = 51004148,
          SpeakNpcId = 700105,
          Subtitle = "They kept telling me that Charons are demon's children who are stupid, evil, and are always doing bad things...",
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004148] = {
          ContentTC = "這些話……其實也不是真的吧？",
          DialogueId = 51004148,
          GUID = "7FAEFC08",
          NextDialogue = 51004149,
          SpeakNpcId = 700105,
          Subtitle = "I don't think those words are true.",
