        },
        [51005814] = {
          ContentTC = "原來是這個啊，你人還怪好的，謝了哈。",
          DialogueId = 51005814,
          GUID = "7FB00D5C",
          NextDialogue = 51005815,
          SpeakNpcId = 700123,
          Subtitle = "Thanks. That's nice of you.",
          TalkActionId = {
