          DialogueId = 51006602,
          Duration = 2,
          GUID = "7FB08EA4",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 700145,
          Subtitle = "...Dammit. I got oil on my hands. I can hardly reload."
        },
        [51006603] = {
          ContentTC = "別裝彈了，{nickname}已經完成測試了。",
          DialogueId = 51006603,
          Duration = 2,
          GUID = "7FB08ECE",
