        [51006842] = {
          ContentTC = "願母神茵布拉賜福於你。",
          DialogueId = 51006842,
          GUID = "7FB0B604",
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
