            [2] = "230002:n(100001)"
          },
          NextDialogue = 51009102,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
          SpeakNpcId = 230002,
          Subtitle = "Ah, there you are, young one.",
          ToFinalCameraBlendTime = 10
        },
        [51009102] = {
          ContentTC = "老朽有些事情要找你，閑下來的話就來找老朽吧。",
          DialogueId = 51009102,
          FacialId = {
            [1] = "230002:Smile02"
          },
          GUID = "7FB228CC",
          NextDialogue = 51009103,
          SpeakNpcId = 230002,
          Subtitle = "There's something I'd like to discuss — drop by when you have a moment to spare."
        },
        [51009103] = {
          Camera = "-75.501465,184.568848,113.267334,0.000113,6.000218,-73.174103,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "前輩這突然是怎麼了？",
          DialogueId = 51009103,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB228F6",
          NextDialogue = 51009104,
          SpeakNpcId = 100001,
          Subtitle = "Is something wrong?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009104] = {
          Camera = "-0.50293,-143.24707,186.720215,0.000033,-20.097776,108.487289,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "就當是老朽多管閑事吧，看著初出茅廬的後輩就總想做點什麼。",
          DialogueId = 51009104,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          GUID = "7FB22920",
          NextDialogue = 51009105,
          SpeakNpcId = 230002,
          Subtitle = "Call it the meddling of an old-timer — but when I see a fledgling taking their first steps, I just can't help but lend a hand.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009105] = {
          Camera = "-12.577637,39.386719,106.859375,0.000067,-6.599274,139.219772,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "來自長輩的經驗之一，明天的冒險必須要在今天就做好準備，總之先跟老朽來一趟吧。",
          DialogueId = 51009105,
          FacialId = {
            [1] = "230002:Happy02"
          },
          FinalCamera = "-40.530518,54.445312,102.745117,0.000068,-5.199099,135.420181,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2294A",
          NextDialogue = 51009106,
          SpeakNpcId = 230002,
          Subtitle = "Here's a piece of advice from someone who's worked more forges than she can count: tomorrow's journey begins with today's preparation. Come. There's something I want to show you.",
          ToFinalCameraBlendTime = 30
        },
        [51009106] = {
          Camera = "-72.382324,317.592285,116.973633,0.000082,-1.397914,-90.974327,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "既然鐵匠前輩都這麼說了，我們就先準備一下吧！",
          DialogueId = 51009106,
          FacialId = {
            [1] = "230001:Smile01"
          },
          GUID = "7FB22974",
          LookAt = {
            [1] = "100001:n(230001)",
            [2] = "230001:n(100001)"
          },
          Scripts = [[
PARA{
LookAt{_delay{0},LookAtDescription{"230001:n(100001)"}},
LookAt{_delay{1.5},LookAtDescription{"100001:n(230001)"}},
}]],
          SpeakNpcId = 230001,
          Subtitle = "Well, if even Lunosmith says so, we'd best get ready!",
          TalkActionId = {
            [1] = "230001:Excited01_Start"
          }
        },
        [51009107] = {
          Camera = "-75.27478,43.773438,123.701057,0.000271,3.798657,-56.419697,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這是？",
          DialogueId = 51009107,
          GUID = "7FB2299E",
          LookAt = {
            [1] = "100001:n(230002)",
            [2] = "230001:n(230002)"
          },
          NextDialogue = 51009108,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
          SpeakNpcId = 100001,
          Subtitle = "What's this?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009108] = {
          Camera = "-62.247192,-183.929199,181.586136,0.000295,-20.401276,71.576736,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你來了啊，年輕人。爐溫正好，老朽也要活動活動筋骨了。",
          DialogueId = 51009108,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          GUID = "7FB229C8",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextDialogue = 51009109,
          SpeakNpcId = 230002,
          Subtitle = "Ah, you came. Good timing — the forge is just at the right temperature, and these old bones could use the stretch."
        },
        [51009109] = {
          ContentTC = "你的那把劍給了老朽不少靈感，這就給你露一手吧。",
          DialogueId = 51009109,
          FacialId = {
            [1] = "230002:Confident02"
          },
          GUID = "7FB229F2",
          SpeakNpcId = 230002,
          Subtitle = "That sword of yours gave me quite the spark of inspiration. Let me show you what these hands can still do.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009110] = {
          Camera = "8.336334,-29.466553,77.175323,0.000124,7.39872,94.000053,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "完成了！",
          DialogueId = 51009110,
          FacialId = {
            [1] = "230002:Happy02"
          },
          FinalCamera = "2.849762,-30.109863,88.122185,0.000128,-1.001312,89.199585,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB22A1C",
          LookAt = {
            [1] = "100001:n(230002)",
            [2] = "230001:n(230002)"
          },
          NextDialogue = 51009111,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
          SpeakNpcId = 230002,
          Subtitle = "It's done.",
          ToFinalCameraBlendTime = 10
        },
        [51009111] = {
          Camera = "-109.266235,212.040771,142.030579,0.000303,-12.201387,-63.418461,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哇——鐵匠前輩，好厲害！",
          DialogueId = 51009111,
          FacialId = {
            [1] = "230001:Smile02"
          },
          GUID = "7FB22A46",
          NextOptions = {
            [1] = 510091111,
            [2] = 510091112
          },
          SpeakNpcId = 230001,
          Subtitle = "Wow—! That was amazing!",
          TalkActionId = {
            [1] = "230001:Shock03_Start"
          }
        },
        [51009112] = {
          Camera = "-98.319763,-208.091797,193.145508,0.000145,-22.401394,63.002728,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "放心吧，這次是特別服務。",
          DialogueId = 51009112,
          GUID = "7FB22A70",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextDialogue = 51009114,
          SpeakNpcId = 230002,
          Subtitle = "Don't fret. This one's on the house — a special service, just this once.",
          TalkActionId = {
            [1] = "230001:Shock03_End"
          }
        },
        [51009113] = {
          Camera = "-98.319763,-208.091797,193.145508,0.000145,-22.401394,63.002728,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "當然，這就是專門為你打造的。",
          DialogueId = 51009113,
          GUID = "7FB22A9A",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextDialogue = 51009114,
          SpeakNpcId = 100001,
          Subtitle = "Of course. It was crafted for you, after all."
        },
        [51009114] = {
          Camera = "-24.090881,-40.348145,106.749283,0.00021,-8.600826,75.590508,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "雖然還比不上你原本的劍，但也算是老朽的得意之作了。",
          DialogueId = 51009114,
          FacialId = {
            [1] = "230002:Confident02"
          },
          GUID = "7FB22AC4",
          NextDialogue = 51009115,
          SpeakNpcId = 230002,
          Subtitle = "It may not outshine your original blade, but I'd say it's one of my finest."
        },
        [51009115] = {
          Camera = "-45.129822,68.886719,129.014465,0.000222,1.198575,-71.808838,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "謝謝前輩，不過為什麼突然會為我鍛造這個？我已經……",
          DialogueId = 51009115,
          FacialId = {
            [1] = "100001:Shy"
          },
          GUID = "7FB22AEE",
          NextDialogue = 51009116,
          SpeakNpcId = 100001,
          Subtitle = "Thank you, Lunosmith. But... why go out of your way to make this for me? I already—",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51009116] = {
          Camera = "-47.538391,-157.203125,145.923813,0.00021,-15.601462,76.384178,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "武器是每個踏上旅途的年輕人最重要的伙伴，當然要做到有備無患。",
          DialogueId = 51009116,
          FacialId = {
            [1] = "230002:Happy02"
          },
          GUID = "7FB22B18",
          NextDialogue = 51009117,
          SpeakNpcId = 230002,
          Subtitle = "A weapon is a young adventurer's most faithful companion. You should never be caught unprepared.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          }
        },
        [51009117] = {
          ContentTC = "老朽見過太多和你一樣的年輕人，不管默默無聞，還是成為了阿特拉西亞的傳奇，最開始也都只是些帶著好奇心和魯莽的毛頭小子。",
          DialogueId = 51009117,
          FacialId = {
            [1] = "230002:Ahaha02"
          },
          GUID = "7FB22B42",
          NextDialogue = 51009118,
          SpeakNpcId = 230002,
          Subtitle = "I've seen more youngsters like you than I can count — some faded into quiet obscurity, others became legends of Atlasia. But they all began the same: curious, reckless, full of fire and far too little caution."
        },
        [51009118] = {
          ContentTC = "一把可靠的武器，正是補足毛躁和稚嫩的良藥。",
          DialogueId = 51009118,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          GUID = "7FB22B6C",
          NextDialogue = 51009119,
          SpeakNpcId = 230002,
          Subtitle = "That's why a dependable weapon matters — it tempers the heat of youth and steadies hands not yet tested by time."
        },
        [51009119] = {
          Camera = "-11.187744,-30.125488,113.694717,0.000209,-16.401381,81.782051,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "雖然你可能不那麼需要，就算是當備用品也好，這把武器就交給你了，就當是老朽對年輕人的一句忠告吧。",
          DialogueId = 51009119,
          GUID = "7FB22B96",
          NextDialogue = 51009120,
          SpeakNpcId = 230002,
          Subtitle = "You may not need it now, but keep it close as a spare. Think of it as advice from an old-timer."
        },
        [51009120] = {
          Camera = "-36.630005,38.096924,125.536903,0.000215,5.798011,-71.413826,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "前輩……",
          DialogueId = 51009120,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB22BC0",
          NextDialogue = 51009121,
          SpeakNpcId = 100001,
          Subtitle = "I... I will. Thank you."
        },
        [51009121] = {
          Camera = "-23.448242,-113.345947,147.890976,0.000217,-16.601587,81.187027,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "以後要是有新的素材和圖譜就找老朽，到時候會給你鍛造新武器的。",
          DialogueId = 51009121,
          FacialId = {
            [1] = "230002:Confident02"
          },
          GUID = "7FB22BEA",
          NextDialogue = 51009122,
          SpeakNpcId = 230002,
          Subtitle = "If you come across any fine materials or new blueprints on your journey, bring them to me. I'll forge something new for you."
        },
        [51009122] = {
          ContentTC = "不過唯獨這一把……如果有一天，它不再鋒利、殘缺、甚至折斷，就把它帶回來，無論多少次老朽都會幫你重鍛。",
          DialogueId = 51009122,
          GUID = "7FB22C14",
          NextDialogue = 51009123,
          SpeakNpcId = 230002,
          Subtitle = "As for this one... if the day ever comes when it dulls, chips, or even breaks — bring it back to me. I'll reforge it, no matter how long it's been."
        },
        [51009123] = {
          Camera = "-72.498413,-159.67749,187.376312,0.000227,-25.601515,61.982807,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "希望無論什麼時候，只要握住它，你都會想起促使你踏上旅途的心情。",
          DialogueId = 51009123,
          FacialId = {
            [1] = "230002:Happy02"
          },
          GUID = "7FB22C3E",
          NextDialogue = 51009124,
          SpeakNpcId = 230002,
          Subtitle = "Just promise me this: whenever you hold it, remember what stirred your heart to set out in the first place."
        },
        [51009124] = {
          Camera = "-77.020996,37.951172,120.615501,0.000228,5.798578,-53.617523,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我會好好使用它的。",
          DialogueId = 51009124,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB22C68",
          NextDialogue = 51009125,
          SpeakNpcId = 100001,
          Subtitle = "I will wield it with care. You have my word.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009125] = {
          Camera = "7.467804,-22.984863,112.509064,0.000025,-21.401974,93.791664,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "喔，真是不錯的眼神，像你這樣的年輕人可不多見咯。",
          DialogueId = 51009125,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          FinalCamera = "6.965179,-18.811523,117.716042,0.000023,-25.002098,92.79113,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB22C92",
          NextDialogue = 51009126,
          SpeakNpcId = 230002,
          Subtitle = "Aww... That look in your eyes — you don't see that often in young folk anymore.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009126] = {
          ContentTC = "…………",
          DialogueId = 51009126,
          GUID = "7FB22CBC",
          LookAt = {
            [1] = "230002:n(230002)"
          },
          NextDialogue = 51009127,
          SpeakNpcId = 230002,
          Subtitle = "..."
        },
        [51009127] = {
          Camera = "-70.951233,159.355713,107.396042,0.000206,-7.602048,-68.41877,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "鐵匠前輩，你的表情有點怪怪的，是有什麼事嗎？",
          DialogueId = 51009127,
          FacialId = {
            [1] = "230001:Shock01"
          },
          GUID = "7FB22CE6",
          NextDialogue = 51009128,
          SpeakNpcId = 230001,
          Subtitle = "Er... Lunosmith? You've gone all quiet and weird. Is something wrong?",
          TalkActionId = {
            [1] = "230001:Explain02_Start"
          }
        },
        [51009128] = {
          Camera = "6.965179,-18.811523,117.716042,0.000023,-25.002098,92.79113,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "沒什麼，只是想起來一些往事罷了。",
          DialogueId = 51009128,
          FacialId = {
            [1] = "230002:Syouganai01"
          },
          GUID = "7FB22D10",
          LookAt = {
            [1] = "230002:n(230001)"
          },
          NextDialogue = 51009129,
          SpeakNpcId = 230002,
          Subtitle = "Mm? Oh, it's nothing. Just... an old memory.",
          TalkActionId = {
            [1] = "230001:Explain02_End"
          }
        },
        [51009129] = {
          ContentTC = "年輕人，能不能幫老朽一個忙？",
          DialogueId = 51009129,
          FacialId = {
            [1] = "230002:None"
          },
          GUID = "7FB22D3A",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextDialogue = 51009130,
          SpeakNpcId = 230002,
          Subtitle = "Say, young one... could you do me a favour?"
        },
        [51009130] = {
          Camera = "-47.573486,44.222656,131.574463,0.000207,1.597875,-67.619141,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "什麼忙？",
          DialogueId = 51009130,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB22D64",
          NextDialogue = 51009131,
          SpeakNpcId = 100001,
          Subtitle = "Of course. What is it?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51009131] = {
          Camera = "-40.003357,-158.163818,175.533508,0.000306,-22.201714,78.178841,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "如果在你冒險的途中，見到……或者聽說一把如火焰般赤紅的劍，記得告訴我。",
          DialogueId = 51009131,
          GUID = "7FB22D8E",
          NextDialogue = 51009132,
          SpeakNpcId = 230002,
          Subtitle = "If, on your journey, you happen to see — or hear of — a sword the colour of flame... let me know.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          }
        },
        [51009132] = {
          Camera = "-79.764465,168.026123,112.217056,0.000226,-5.602353,-64.817764,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那也是鐵匠前輩的作品嗎？",
          DialogueId = 51009132,
          GUID = "7FB22DB8",
          NextDialogue = 51009133,
          SpeakNpcId = 230001,
          Subtitle = "Is that one of your creations too?",
          TalkActionId = {
            [1] = "230001:Think_Start"
          }
        },
        [51009133] = {
          Camera = "-54.818481,-149.708496,145.451065,0.00023,-15.002154,70.382484,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "應該是吧，不過什麼時候鍛造的它，為誰鍛造的它……為什麼想不起來呢……",
          DialogueId = 51009133,
          FinalCamera = "-23.610504,-51.820557,117.260406,0.000222,-15.60216,74.782066,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB22DE2",
          NextDialogue = 51009134,
          SpeakNpcId = 230002,
          Subtitle = "I believe so. But when I forged it... who I made it for... I can't seem to recall.",
          ToFinalCameraBlendTime = 15
        },
        [51009134] = {
          ContentTC = "老朽對那把劍的印象只剩下那像在燃燒著一般的顏色，但總覺得必須要找到那把劍不可……",
          DialogueId = 51009134,
          GUID = "7FB22E0C",
          NextDialogue = 51009135,
          SpeakNpcId = 230002,
          Subtitle = "All I remember is that blazing red. Like fire. And a feeling... that I must find it."
        },
        [51009135] = {
          Camera = "4.024445,-18.40332,83.317413,0.00013,3.196528,91.587433,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "年輕人，只有一些傳聞也好，拜托你稍微注意一下。",
          DialogueId = 51009135,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          FinalCamera = "0.602966,-57.215332,91.756393,0.000139,-1.603605,87.387039,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB22E36",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextDialogue = 51009136,
          SpeakNpcId = 230002,
          Subtitle = "Even rumours would help. Please — keep an ear out for me.",
          ToFinalCameraBlendTime = 15
        },
        [51009136] = {
          Camera = "-74.956299,70.125977,132.865021,0.000285,-2.00201,-61.222034,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我明白了，會替前輩留意的。",
          DialogueId = 51009136,
          GUID = "7FB22E60",
          NextDialogue = 51009137,
          SpeakNpcId = 100001,
          Subtitle = "Understood. I'll keep watch.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009137] = {
          Camera = "-45.467529,-102.451904,136.414795,0.000299,-15.201719,72.779053,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "好了，長輩的嘮叨到此為止。新的奇跡即將開始，讓阿特拉西亞見證你的冒險吧。",
          DialogueId = 51009137,
          FacialId = {
            [1] = "230002:Happy02"
          },
          FinalCamera = "-109.385742,-261.364746,203.023361,0.000271,-18.801235,65.979637,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB22E8A",
          SpeakNpcId = 230002,
          Subtitle = "That's enough rambling from an old-timer. A new miracle's about to begin — may all of Atlasia bear witness to your journey.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009201] = {
          Camera = "438.621582,138.591309,121.772217,0.000022,0.399839,-164.795059,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "抱歉打擾到你，請容許我占用你英雄詩篇上那微不足道的一行用以自我介紹。",
          DialogueId = 51009201,
          GUID = "7FB2390A",
          LookAt = {
            [1] = "230003:n(100001)"
          },
          NextDialogue = 51009202,
          SpeakNpcId = 230003,
          Subtitle = "Forgive the intrusion — might I borrow but a single line from your heroic saga to introduce myself?",
          TalkActionId = {
            [1] = "230003:Explain02_Start"
          }
        },
        [51009202] = {
          Camera = "184.849121,-47.185059,77.377197,0.000079,-13.401609,165.810257,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "本人名叫阿米埃特，至於職業……本人所從事的事業比較難以用語言概括，因為那樣做比較有違美學。",
          DialogueId = 51009202,
          FinalCamera = "155.654297,64.67334,157.197266,0.000115,-0.001284,-158.590393,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23934",
          NextDialogue = 51009203,
          SpeakNpcId = 230003,
          Subtitle = "I am Amiette. As for my profession... well, that's rather difficult to define without offending the sensibilities of art itself.",
          TalkActionId = {
            [1] = "230003:Explain02_End"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009203] = {
          Camera = "155.654297,64.67334,157.197266,0.000115,-0.001284,-158.590393,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "如果一定要用一個詞去稱呼本人的職業，那還請叫做——藝術家。",
          DialogueId = 51009203,
          FinalCamera = "133.85498,-3.754883,152.920898,0.000117,0.198506,175.208954,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2395E",
          NextDialogue = 51009204,
          SpeakNpcId = 230003,
          Subtitle = "But if I must reduce it to a single label — then let it be... artist.",
          TalkActionId = {
            [1] = "230003:Confident_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009204] = {
          Camera = "-116.031738,-138.629395,169.49292,0.000161,-6.801338,43.0089,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "好可疑……",
          DialogueId = 51009204,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          FinalCamera = "-50.322266,-81.086426,160.310791,0.000161,-6.001311,41.20895,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23988",
          LookAt = {
            [1] = "100001:n(230003)"
          },
          NextDialogue = 51009205,
          SpeakNpcId = 100001,
          Subtitle = "That's... suspicious.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "230003:Confident_End"
          },
          ToFinalCameraBlendTime = 30
        },
        [51009205] = {
          Camera = "182.905762,56.904785,140.219238,0.000167,0.19811,-165.575302,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "請不必無端懷疑，本人在這裡徘徊面是因為一些<H>美學</>上的疑惑。",
          DialogueId = 51009205,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "209.431152,63.451172,140.220459,0.000167,-0.001858,-166.175751,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB239B2",
          NextDialogue = 51009206,
          SpeakNpcId = 230003,
          Subtitle = "There's no need for baseless mistrust, friend. I merely linger here, beset by a... crisis of aesthetics.",
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "230003:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009206] = {
          ContentTC = "不知道你有沒有這種感覺，朋友——最近的武器似乎都面注重殺傷力和成本，卻忽略了鍛造物應有的美學。",
          DialogueId = 51009206,
          GUID = "7FB239DC",
          NextDialogue = 51009207,
          SpeakNpcId = 230003,
          Subtitle = "Tell me — have you noticed? Modern weaponry is obsessed with damage output and cost-efficiency, yet utterly blind to beauty!",
          TalkActionId = {
            [1] = "230003:Explain01_End"
          }
        },
        [51009207] = {
          Camera = "-2849.924805,472.516602,-933.664307,0.000118,-4.801397,-111.175285,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "武器原本並非我主要的研究對象，面是你有沒有發現，如今這座城市的士兵變得越來越粗鄙了。",
          DialogueId = 51009207,
          FinalCamera = "-2585.590332,363.479004,-933.664307,0.000116,-5.401429,-115.973396,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23A06",
          NextDialogue = 51009208,
          SpeakNpcId = 230003,
          Subtitle = "Weaponry was never meant to be my canvas... but look around you — the soldiers of this city have grown hideously unrefined.",
          ToFinalCameraBlendTime = 15
        },
        [51009208] = {
          Camera = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我想正是海伯利亞的煉金院放棄了他們的美學追求，使用者才會如此粗俗，不成體統。而本人把他們的裝備在美學上加以矯正，卻遭到了不公的對待……",
          DialogueId = 51009208,
          GUID = "7FB23A30",
          NextDialogue = 51009209,
          SpeakNpcId = 230003,
          Subtitle = "I blame Hyperborea's Alchemy Academy. By forsaking aesthetic principles, they've cursed their wielders with vulgarity. And when I sought to correct their gear, I was treated most unfairly...",
          TalkActionId = {
            [1] = "230003:Explain02_Start"
          }
        },
        [51009209] = {
          Camera = "107.540039,43.087402,155.901123,0.000135,-9.202333,39.223675,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「矯正」？你做了什麼出格的事嗎？",
          DialogueId = 51009209,
          GUID = "7FB23A5A",
          NextDialogue = 51009210,
          SpeakNpcId = 100001,
          Subtitle = "\"Correct\"...? What did you do?",
          TalkActionId = {
            [1] = "100001:Think_Start"
