        },
        [51009210] = {
          Camera = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "出格？當然沒有，面是趁換崗的時候把他們的武器和配飾稍加修改，和他們對我下達監禁十五日的處罰相比，談何出格？",
          DialogueId = 51009210,
          GUID = "7FB23A84",
          NextDialogue = 51009211,
          SpeakNpcId = 230003,
          Subtitle = "Nothing excessive, I assure you. I merely made a few subtle improvements to their weapons and accessories during a shift change. Hardly worth fifteen days of confinement, wouldn't you say?",
          TalkActionId = {
            [1] = "230003:Angry01_Start"
          }
        },
        [51009211] = {
          ContentTC = "本人理解讓所有人擁有基本的美學素養是一項艱巨的偉大事業，但我們不應該因為前路艱險就停下腳步——",
          DialogueId = 51009211,
          GUID = "7FB23AAE",
          NextDialogue = 51009212,
          SpeakNpcId = 230003,
          Subtitle = "Yes, instilling basic aesthetic awareness in the general populace is a daunting task... but surely we can't let hardship stand in the way of beauty!",
          TalkActionId = {
            [1] = "230003:Angry01_End"
          }
        },
        [51009212] = {
          Camera = "355.351074,108.127441,146.656494,0.000137,-3.402848,-172.570343,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "本人以藝術名義起誓，上到傳說英雄的利劍，下到聊以防身的小刀，無關出身無關價格，其本身都應具備美的要素！",
          DialogueId = 51009212,
          GUID = "7FB23AD8",
          NextDialogue = 51009213,
          SpeakNpcId = 230003,
          Subtitle = "I swear, by the name of art itself — from the legendary sword of a hero to the humble blade of a back-alley brawler, beauty must be honoured! Regardless of price or provenance!",
          TalkActionId = {
            [1] = "230003:Agree"
          }
        },
        [51009213] = {
          Camera = "179.876953,-270.89502,193.723389,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哦？老朽好像聽到了些很有趣的話。",
          DialogueId = 51009213,
          FinalCamera = "170.026367,-235.211914,187.194336,0.00005,-10.001951,105.430725,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23B02",
          LookAt = {
