        [51009215] = {
          Camera = "77.210938,30.784668,120.665283,0.000054,-10.001801,93.224159,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "現在的武器總是粗枝大葉，錘鍛的造就的線條，淬煉形成的紋路，恰到好處的平衡，每一個環節都應該飽含鍛造者的心血才是。",
          DialogueId = 51009215,
          FacialId = {
            [1] = "230002:Happy01"
          },
          FinalCamera = "109.248535,35.82959,120.665283,0.000053,-10.801848,106.024544,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23B56",
          LookAt = {
            [1] = "230002:n(230002)"
          },
          NextDialogue = 51009216,
          SpeakNpcId = 230002,
          Subtitle = "These days, craftsmanship is all brute force. The blade's taper, the patterns forged through hammer and flame, the balance in the hand — every detail should reflect the smith's soul.",
          ToFinalCameraBlendTime = 30
        },
        [51009216] = {
          Camera = "192.502441,42.003906,148.640137,0.000075,-3.202395,-170.373978,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "線條？紋路？平衡？",
          DialogueId = 51009216,
          GUID = "7FB23B80",
          NextDialogue = 51009217,
          SpeakNpcId = 230003,
          Subtitle = "Taper? Patterns? Balance?",
          TalkActionId = {
            [1] = "230003:Think_Start"
          }
        },
        [51009217] = {
          ContentTC = "請等一等，這些和美學有什麼關係？",
