          DialogueId = 51009224,
          GUID = "7FB23CD0",
          LookAt = {
            [1] = "230002:n(230002)"
          },
          NextDialogue = 51009225,
          SpeakNpcId = 230003,
          Subtitle = "So — please, accept this exclusive dye recipe, along with a few trial samples.",
          TalkActionId = {
            [1] = "230003:Explain01_End"
          }
        },
        [51009225] = {
          Camera = "140.89209,77.023438,171.302979,0.000198,-10.586759,-153.78447,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentTC = "無論是武器，還是穿戴的飾品。面要用了它，您與美學真諦之間的距離，便不再遠不可及！",
