        [51009239] = {
          Camera = "38.538757,-183.397461,161.428268,0.000042,-13.602649,100.809677,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不太懂你們年輕人的審美，不過既然你都這麼說了，就用這個顏色吧。",
          DialogueId = 51009239,
          FinalCamera = "27.600983,-132.857178,154.2789,0.000026,-18.804384,103.619179,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23F46",
          NextDialogue = 51009240,
          SpeakNpcId = 230002,
          Subtitle = "Hmm. I'll never quite understand you young folk... but if you're set on it, then so be it.",
          ToFinalCameraBlendTime = 30
        },
        [51009240] = {
          ContentTC = "以後如果想要換成其他塗裝就收集好材料再來找老朽吧。",
          DialogueId = 51009240,
          GUID = "7FB23F70",
          NextDialogue = 51009242,
          SpeakNpcId = 230002,
          Subtitle = "If you fancy another palette later on, just bring me the right materials and we'll have another go."
        },
        [51009241] = {
          Camera = "38.538757,-183.397461,161.428268,0.000042,-13.602649,100.809677,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "倒也不急於一時，或許其他顏色效果會好一些也說不定，決定好了再來找老朽也不遲。",
          DialogueId = 51009241,
          FinalCamera = "27.600983,-132.857178,154.2789,0.000026,-18.804384,103.619179,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23F9A",
          NextDialogue = 51009242,
          SpeakNpcId = 230002,
          Subtitle = "No need to decide in haste. Try a few other shades — see how they suit you. Come find me once you've made up your mind.",
          ToFinalCameraBlendTime = 30
        },
        [51009242] = {
          ContentTC = "色彩的美學嗎……看來這條道路還需要老朽慢慢探索啊。",
          DialogueId = 51009242,
          GUID = "7FB23FC4",
          SpeakNpcId = 230002,
          Subtitle = "The aesthetics of colour, eh...? Looks like I've still got a fair bit to learn on that front."
        },
        [51009243] = {
          ContentTC = "那邊那位純白無瑕的英雄，請留步！",
          DialogueId = 51009243,
          GUID = "7FB23FEE",
          SpeakNpcId = 230003,
          Subtitle = "You there — the hero in immaculate white! A moment, if you please!"
        },
        [51009244] = {
          ContentTC = "對就是這邊，能夠來到我的面前，看來你我果然擁有美學上的共鳴。",
          DialogueId = 51009244,
          GUID = "7FB24018",
          SpeakNpcId = 230003,
          Subtitle = "Yes, yes — you! The very fact you've made it to me can mean only one thing: resonance. A deep, aesthetic bond between us!"
        },
        [51009301] = {
          ContentTC = "這次就選粉紅色的花吧！",
          DialogueId = 51009301,
          GUID = "7FB24972",
          NextDialogue = 51009302,
          SpeakNpcId = 700247,
          Subtitle = "This time, I'll go with pink ones!"
        },
        [51009302] = {
          ContentTC = "（女子面帶微笑地拿起她精心挑選的粉色花朵。抬起頭來時，她注意到了你。）",
          DialogueId = 51009302,
          GUID = "7FB2499C",
          NextDialogue = 51009303,
          Subtitle = "(The woman smiles as she picks up the carefully chosen pink blooms. Looking up, she notices you.)"
        },
        [51009303] = {
          ContentTC = "你好呀，你也是來買花的嗎？",
          DialogueId = 51009303,
          GUID = "7FB249C6",
          NextDialogue = 51009304,
          SpeakNpcId = 700247,
          Subtitle = "Hello there. Are you here to buy flowers too?"
        },
        [51009304] = {
          ContentTC = "要不要看看這一種，粉紅色的花可不多見喔。",
          DialogueId = 51009304,
          GUID = "7FB249F0",
          NextOptions = {
            [1] = 51009305,
            [2] = 51009310,
            [3] = 51009313
          },
          SpeakNpcId = 700247,
          Subtitle = "Take a look? Pink flowers like these are quite rare, you know."
        },
        [51009305] = {
          ContentTC = "可以送我嗎？",
          DialogueId = 51009305,
          GUID = "7FB24A1A",
          ImprPlusId = 1001,
          NextDialogue = 51009306,
          Subtitle = "Could I have them?"
        },
        [51009306] = {
          ContentTC = "呵呵，當然可以！",
          DialogueId = 51009306,
          GUID = "7FB24A44",
          NextDialogue = 51009307,
          SpeakNpcId = 700247,
          Subtitle = "Hehe, of course!"
        },
        [51009307] = {
          ContentTC = "（女子伸出手，輕巧地從貨架上多取了幾支花，一並結賬後遞給了你。）",
          DialogueId = 51009307,
          GUID = "7FB24A6E",
          NextDialogue = 51009308,
          Subtitle = "(She reaches out, deftly takes a few more stems from the shelf, pays for them along with her own, and hands them to you.)"
        },
        [51009308] = {
          ContentTC = "來，收好了。",
          DialogueId = 51009308,
          GUID = "7FB24A98",
          NextDialogue = 51009309,
          SpeakNpcId = 700247,
          Subtitle = "Here you are."
        },
        [51009309] = {
          ContentTC = "不用謝我，你就當作是沾了他的光吧。",
          DialogueId = 51009309,
          GUID = "7FB24AC2",
          NextDialogue = 51009317,
          SpeakNpcId = 700247,
          Subtitle = "No need to thank me. Just think of it as you sharing in his good fortune."
        },
        [51009310] = {
          ContentTC = "謝謝你，我也覺得很好看。",
          DialogueId = 51009310,
          GUID = "7FB24AEC",
          ImprPlusId = 1004,
          NextDialogue = 51009311,
          Subtitle = "Thank you, I think they're lovely too."
        },
        [51009311] = {
          ContentTC = "如果你喜歡的話，我也可以送給你哦。",
          DialogueId = 51009311,
          GUID = "7FB24B16",
          NextDialogue = 51009312,
          Subtitle = "You can have them if you like."
        },
        [51009312] = {
          ContentTC = "他一定也會很樂意的。",
          DialogueId = 51009312,
          GUID = "7FB24B40",
          NextDialogue = 51009317,
          Subtitle = "I'm sure he wouldn't have minded either."
        },
        [51009313] = {
          ContentTC = "哦不，我討厭粉紅色！",
          DialogueId = 51009313,
          GUID = "7FB24B6A",
          ImprPlusId = 1005,
          NextDialogue = 51009314,
          Subtitle = "Oh no, I can't stand pink!"
        },
        [51009314] = {
          ContentTC = "哎呀，那真是抱歉了。",
          DialogueId = 51009314,
          GUID = "7FB24B94",
          NextDialogue = 51009315,
          SpeakNpcId = 700247,
          Subtitle = "Oh dear, I'm so sorry to hear that."
        },
        [51009315] = {
          ContentTC = "也對，不是每個人都會喜歡粉紅色的吧……",
          DialogueId = 51009315,
          GUID = "7FB24BBE",
          NextDialogue = 51009316,
          SpeakNpcId = 700247,
          Subtitle = "Well, it's true. Not everyone likes pink, I suppose..."
        },
        [51009316] = {
          ContentTC = "這麼說來，或許他也不喜歡……不過沒關係啦！就當做他喜歡好了。",
          DialogueId = 51009316,
          GUID = "7FB24BE8",
          NextDialogue = 51009317,
          SpeakNpcId = 700247,
          Subtitle = "Now that you mention it, perhaps he didn't either... But never mind! Let's just pretend he did."
        },
        [51009317] = {
          ContentTC = "這花是用來送人的嗎？",
          DialogueId = 51009317,
          GUID = "7FB24C12",
          NextDialogue = 51009318,
          SpeakNpcId = 100001,
          Subtitle = "Are these flowers for someone?"
        },
        [51009318] = {
          ContentTC = "是呀。我有一位和你一樣頭上長著角的精靈朋友，這花就是要送給他的。",
          DialogueId = 51009318,
          GUID = "7FB24C3C",
          NextOptions = {
            [1] = 51009319,
            [2] = 51009321
          },
          SpeakNpcId = 700247,
          Subtitle = "Yes. I have a faerie friend, much like you with horns, and these are for him."
        },
        [51009319] = {
          ContentTC = "「精靈？」",
          DialogueId = 51009319,
          GUID = "7FB24C66",
          NextDialogue = 51009320,
          Subtitle = "Faerie?"
        },
        [51009320] = {
          ContentTC = "呵呵，那是他的說法。",
          DialogueId = 51009320,
          GUID = "7FB24C90",
          NextDialogue = 51009323,
          SpeakNpcId = 700247,
          Subtitle = "Oh, that's what he called himself."
        },
        [51009321] = {
          ContentTC = "我是卡戎。",
          DialogueId = 51009321,
          GUID = "7FB24CBA",
          NextDialogue = 51009322,
          Subtitle = "I'm Charon."
        },
        [51009322] = {
          ContentTC = "嗯，「精靈」是他的說法。",
          DialogueId = 51009322,
          GUID = "7FB24CE4",
          NextDialogue = 51009323,
          SpeakNpcId = 700247,
          Subtitle = "Well, \"faerie\" was his word for it."
        },
        [51009323] = {
          ContentTC = "說起來，外面起風了嗎？",
          DialogueId = 51009323,
          GUID = "7FB24D0E",
          NextOptions = {
            [1] = 51009324,
            [2] = 51009326,
            [3] = 51009328
          },
          SpeakNpcId = 700247,
          Subtitle = "Speaking of which,has the wind picked up outside?"
        },
        [51009324] = {
          ContentTC = "我沒注意。",
          DialogueId = 51009324,
          GUID = "7FB24D38",
          NextDialogue = 51009325,
          Subtitle = "I didn't notice."
        },
        [51009325] = {
          ContentTC = "這樣啊……沒關係，我等會兒自己出去確認一下。",
          DialogueId = 51009325,
          GUID = "7FB24D62",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "I see... No matter, I'll check for myself later."
        },
        [51009326] = {
          ContentTC = "正在颳大風。",
          DialogueId = 51009326,
          GUID = "7FB24D8C",
          NextDialogue = 51009327,
          Subtitle = "It's quite windy."
        },
        [51009327] = {
          ContentTC = "那就太好了。",
          DialogueId = 51009327,
          GUID = "7FB24DB6",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "That's wonderful."
        },
        [51009328] = {
          ContentTC = "沒有風我也可以製造風。",
          DialogueId = 51009328,
          GUID = "7FB24DE0",
          NextDialogue = 51009329,
          Subtitle = "I can make wind, even if there isn't any."
        },
        [51009329] = {
          ContentTC = "是嗎，原來你這麼厲害呀！謝謝你的好意。",
          DialogueId = 51009329,
          GUID = "7FB24E0A",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "Really? You're that powerful? That's very kind of you."
        },
        [51009330] = {
          ContentTC = "我得等到起風的時候，才能把花送給他呢。",
          DialogueId = 51009330,
          GUID = "7FB24E34",
          NextOptions = {
            [1] = 51009331,
            [2] = 51009333,
            [3] = 51009335
          },
          SpeakNpcId = 700247,
          Subtitle = "I need to wait for the wind to pick up before I can give him the flowers."
        },
        [51009331] = {
          ContentTC = "為什麼一定要等起風？",
          DialogueId = 51009331,
          GUID = "7FB24E5E",
          NextDialogue = 51009332,
          Subtitle = "Why do you need the wind?"
        },
        [51009332] = {
          ContentTC = "因為起風的時候，花才會往空中飄呀。",
          DialogueId = 51009332,
          GUID = "7FB24E88",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "Because when the wind blows, the flowers can float up into the sky."
        },
        [51009333] = {
          ContentTC = "莫非你的朋友是風精靈嗎？",
          DialogueId = 51009333,
          GUID = "7FB24EB2",
          NextDialogue = 51009334,
          Subtitle = "Is your friend a wind faerie, by any chance?"
        },
        [51009334] = {
          ContentTC = "呵呵，很有意思的想法！說不定真的是喔。",
          DialogueId = 51009334,
          GUID = "7FB24EDC",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "An interesting thought! Perhaps he is."
        },
        [51009335] = {
          ContentTC = "這是某種特殊的儀式嗎？",
          DialogueId = 51009335,
          GUID = "7FB24F06",
          NextDialogue = 51009336,
          Subtitle = "Is this some special kind of ritual?"
        },
        [51009336] = {
          ContentTC = "嗯……是傳遞思念的儀式。",
          DialogueId = 51009336,
          GUID = "7FB24F30",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "Well... it's a ritual for sending thoughts to someone."
        },
        [51009337] = {
          ContentTC = "我的那位朋友，在幾年前就去天上啦。",
          DialogueId = 51009337,
          GUID = "7FB24F5A",
          NextDialogue = 51009338,
          SpeakNpcId = 700247,
          Subtitle = "That friend of mine... he went up to the sky several years ago."
        },
        [51009338] = {
          ContentTC = "今天是每年一次的紀念日。",
          DialogueId = 51009338,
          GUID = "7FB24F84",
          NextOptions = {
            [1] = 51009339
          },
          RestartTag = 51009338,
          SpeakNpcId = 700247,
          Subtitle = "Today is the annual day of remembrance."
        },
        [51009339] = {
          ContentTC = "（提醒她卡戎人的習俗。）",
          DialogueId = 51009339,
          FailDialogue = 51009340,
          GUID = "7FB24FAE",
          ImprCheckId = 1071,
          NextDialogue = 51009341,
          Subtitle = "(Remind her of Charon customs.)"
        },
        [51009340] = {
          ContentTC = "（你一時記不起習俗的細節。）",
          DialogueId = 51009340,
          GUID = "7FB24FD8",
          Subtitle = "(For a moment, you can't quite recall the details of the custom.)"
        },
        [51009341] = {
          ContentTC = "在卡戎人的觀念中，霧海才是靈魂的歸去之地。如果要紀念他，將花送往水中更加合理。",
          DialogueId = 51009341,
          GUID = "7FB25002",
          NextDialogue = 51009342,
          SpeakNpcId = 100001,
          Subtitle = "In Charon belief, the Misty Sea is where souls go. If you wish to remember him, sending the flowers onto the water would make more sense."
        },
        [51009342] = {
          ContentTC = "嗯……我知道。但是，他不一樣。",
          DialogueId = 51009342,
          GUID = "7FB2502C",
          NextDialogue = 51009343,
          SpeakNpcId = 700247,
          Subtitle = "Well... I know. But he was different."
        },
        [51009343] = {
          ContentTC = "（女子沉默了片刻，看向窗外，眼神中流露著溫柔的懷念。）",
          DialogueId = 51009343,
          GUID = "7FB25056",
          NextDialogue = 51009344,
          Subtitle = "(The woman falls silent, gazing out the window, her eyes filled with a gentle nostalgia.)"
        },
        [51009344] = {
          ContentTC = "我第一次遇見他是在城外。我們年紀相仿，性格也很像，所以很快就成了好朋友。",
          DialogueId = 51009344,
          GUID = "7FB25080",
          NextDialogue = 51009345,
          SpeakNpcId = 700247,
          Subtitle = "I first met him outside the city. We were the same age, and our personalities just clicked, so we became fast friends."
        },
        [51009345] = {
          ContentTC = "他對我說自己從是天上來的「精靈」……呵呵，其實我早知道他是卡戎人，但每次看到他那麼努力地圓謊，實在是捨不得戳穿。",
          DialogueId = 51009345,
          GUID = "7FB250AA",
          NextDialogue = 51009346,
          SpeakNpcId = 700247,
          Subtitle = "He told me he was a \"faerie\" from the sky... Hehe, truthfully, I knew all along he was Charon. But every time I saw him trying so hard to keep up the story, I couldn't bear to spoil it for him."
        },
        [51009346] = {
          ContentTC = "而且，他確實就像故事裡的精靈一樣，知道許多我不知道的事，永遠有講不完的新奇見聞。",
          DialogueId = 51009346,
          GUID = "7FB250D4",
          NextOptions = {
            [1] = 51009347,
            [2] = 51009349
          },
          SpeakNpcId = 700247,
          Subtitle = "Besides, he really was just like a faerie from the stories — he knew so many things I didn't, and always had endless fascinating tales to tell."
        },
        [51009347] = {
          ContentTC = "聽起來是個很棒的朋友。",
          DialogueId = 51009347,
          GUID = "7FB250FE",
          NextDialogue = 51009348,
          Subtitle = "Sounds like a wonderful friend."
        },
        [51009348] = {
          ContentTC = "嗯！他是最棒的朋友。",
          DialogueId = 51009348,
          GUID = "7FB25128",
          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Yes! He's the best friend ever."
        },
        [51009349] = {
          ContentTC = "所以他從小到大一直在扮演精靈嗎？",
          DialogueId = 51009349,
          GUID = "7FB25152",
          NextDialogue = 51009350,
          Subtitle = "So he was playing the part of a faerie his whole life?"
        },
        [51009350] = {
          ContentTC = "呵呵，聽起來有點幼稚，對吧？",
          DialogueId = 51009350,
          GUID = "7FB2517C",
          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Sounds a bit childish when you put it like that, doesn't it?"
        },
        [51009351] = {
          ContentTC = "我心裡一直都有些苦惱——等到我們都長大，過了能理所當然地相信童話的年紀以後，要怎麼開口說破這件事？",
          DialogueId = 51009351,
          GUID = "7FB251A6",
          NextDialogue = 51009352,
          SpeakNpcId = 700247,
          Subtitle = "It always bothered me a little... wondering how we would finally talk about it, once we grew up and passed the age where believing in fairy tales came naturally."
        },
        [51009352] = {
          ContentTC = "無論是我先開口還是他先開口，想像一下都很尷尬呀……",
          DialogueId = 51009352,
          GUID = "7FB251D0",
          NextDialogue = 51009353,
          SpeakNpcId = 700247,
          Subtitle = "Whether I brought it up or he did, just imagining it felt so awkward..."
        },
        [51009353] = {
          ContentTC = "但最後我們並沒有走到那個時間點。他在成年之前便離開了。",
          DialogueId = 51009353,
          GUID = "7FB251FA",
          NextDialogue = 51009354,
          SpeakNpcId = 700247,
          Subtitle = "But in the end, we never reached that point. He left before we came of age."
        },
        [51009354] = {
          ContentTC = "你說，他會不會是想到了這一點，才故意選在那個時候離開的？呵呵，真是個溫柔的人啊……",
          DialogueId = 51009354,
          GUID = "7FB25224",
          NextDialogue = 51009355,
          SpeakNpcId = 700247,
          Subtitle = "Do you think... he might have chosen to leave at that precise time because he knew? What a gentle soul he was..."
        },
        [51009355] = {
          ContentTC = "（女子撫摸著柔軟的花瓣，輕輕垂下了眼眸。你分辨不出她臉上的情緒。）",
          DialogueId = 51009355,
          GUID = "7FB2524E",
          NextOptions = {
            [1] = 51009356,
            [2] = 51009358,
            [3] = 51009360
          },
          Subtitle = "(The woman strokes the soft petals, gently lowering her gaze. You can't quite decipher the emotion on her face.)"
        },
        [51009356] = {
          ContentTC = "抱歉，請節哀……",
          DialogueId = 51009356,
          GUID = "7FB25278",
          ImprPlusId = 1002,
          NextDialogue = 51009357,
          Subtitle = "Sorry for your loss."
        },
        [51009357] = {
          ContentTC = "沒關係，已經過去很多年啦。",
          DialogueId = 51009357,
          GUID = "7FB252A2",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "It's okay. It's been years."
        },
        [51009358] = {
          ContentTC = "你們都是非常溫柔的人。",
          DialogueId = 51009358,
          GUID = "7FB252CC",
          ImprPlusId = 1004,
          NextDialogue = 51009359,
          Subtitle = "You're both incredibly kind people."
        },
        [51009359] = {
          ContentTC = "呵呵，謝謝你。",
          DialogueId = 51009359,
          GUID = "7FB252F6",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "Then... thank you."
        },
        [51009360] = {
          ContentTC = "成年這個時間點……難道說，他是出現了穢蝕的徵兆？",
          DialogueId = 51009360,
          GUID = "7FB25320",
          ImprPlusId = 1003,
          NextDialogue = 51009361,
          Subtitle = "Coming of age... Did he start showing signs of Deterioration?"
        },
        [51009361] = {
          ContentTC = "嗯，我也這麼想。畢竟他離開的時候，剛好是快滿十八歲。",
          DialogueId = 51009361,
          GUID = "7FB2534A",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "Well, that's what I thought. After all, he left just before he turned eighteen."
        },
        [51009362] = {
          ContentTC = "他早就預料到了自己的結局……最後見面的那次，他對我說，自己將要回到天上的故鄉，從今往後不能再來找我。",
          DialogueId = 51009362,
          GUID = "7FB25374",
          NextDialogue = 51009363,
          SpeakNpcId = 700247,
          Subtitle = "He had foreseen his own fate. The last time we met, he told me he was returning to his homeland in the sky and wouldn't be able to visit me anymore."
        },
        [51009363] = {
          ContentTC = "那是他撒謊撒得最拙劣的一次……明明眼淚已經在眼眶裡打轉了，還拼命擠出一副微笑的表情，用愉快的語調對我說——",
          DialogueId = 51009363,
          GUID = "7FB2539E",
          NextDialogue = 51009364,
          SpeakNpcId = 700247,
          Subtitle = "It was the most poorly told lie of his life... His eyes were already brimming with tears, yet he forced a smile and said to me in the cheeriest voice—"
        },
        [51009364] = {
          ContentTC = "「請你不要感到難過。雖然我不能再來見你，但我會在雲端之上一直、一直注視著你……」",
          DialogueId = 51009364,
          GUID = "7FB253C8",
          NextDialogue = 51009365,
          SpeakNpcId = 700247,
          Subtitle = "\"Please don't be sad. Even though I can't come to see you anymore, I'll be watching over you from above the clouds, always...\""
        },
        [51009365] = {
          ContentTC = "「無論何時，只要你抬頭望向天空，你的思念就能夠隨風抵達我的身邊。」",
          DialogueId = 51009365,
          GUID = "7FB253F2",
          NextDialogue = 51009366,
          SpeakNpcId = 700247,
          Subtitle = "\"Whenever you look up at the sky, your thoughts will reach me on the wind.\""
        },
        [51009366] = {
          ContentTC = "（說到這裡，女子露出了微笑。不知是否是錯覺，她的眼中隱約閃過了一絲光亮——那究竟是淚光，還是從玻璃窗中灑下的陽光呢？）",
          DialogueId = 51009366,
          GUID = "7FB2541C",
          NextDialogue = 51009367,
          Subtitle = "(As she says this, the woman smiles. Is it a trick of the light, or is there a faint glimmer in her eyes—a tear, or perhaps a reflection from the sun through the window pane?)"
        },
        [51009367] = {
          ContentTC = "所以，你才會把花撒向天空……？",
          DialogueId = 51009367,
          GUID = "7FB25446",
          NextDialogue = 51009368,
          SpeakNpcId = 100001,
          Subtitle = "So, that's why you cast the flowers into the sky?"
        },
        [51009368] = {
          ContentTC = "嗯。既然那是他想要告訴我的故事，那麼我也願意相信，他的歸處不是霧海，而是遼闊的藍天。",
          DialogueId = 51009368,
          GUID = "7FB25470",
          NextDialogue = 51009369,
          SpeakNpcId = 700247,
          Subtitle = "Indeed. Since that was the story he wanted to tell me, I choose to believe that his final resting place isn't the Misty Sea, but the vast blue sky."
        },
        [51009369] = {
          ContentTC = "只要將花瓣撒向天空，他就能感受到我的思念。",
          DialogueId = 51009369,
          GUID = "7FB2549A",
          NextOptions = {
            [1] = 51009370,
            [2] = 51009371
          },
          SpeakNpcId = 700247,
          Subtitle = "As long as I scatter the petals to the wind, he'll feel my thoughts."
        },
        [51009370] = {
          ContentTC = "如果他能收到你的花就好了。",
          DialogueId = 51009370,
          GUID = "7FB254C4",
          NextDialogue = 51009372,
          Subtitle = "I hope he receives your flowers."
        },
        [51009371] = {
          ContentTC = "他一定會收到你的花的。",
          DialogueId = 51009371,
          GUID = "7FB254EE",
          NextDialogue = 51009372,
          Subtitle = "I'm sure he will receive them."
        },
        [51009372] = {
          ContentTC = "嗯，謝謝你！",
          DialogueId = 51009372,
          GUID = "7FB25518",
          NextDialogue = 51009373,
          SpeakNpcId = 700247,
          Subtitle = "...Thank you."
        },
        [51009373] = {
          ContentTC = "現在回想起來，他大概也早就知道我已經看穿了他的謊話吧。",
          DialogueId = 51009373,
          GUID = "7FB25542",
          NextDialogue = 51009374,
          SpeakNpcId = 700247,
          Subtitle = "Looking back now, I think he probably knew all along that I had seen through his little charade."
        },
        [51009374] = {
          ContentTC = "一個由謊言編織的故事，最後有了一個用謊言寫就的結局……不也算是恰如其分嗎？",
          DialogueId = 51009374,
          GUID = "7FB2556C",
          NextDialogue = 51009375,
          SpeakNpcId = 700247,
          Subtitle = "A story woven from lies, ending with a lie... doesn't that seem rather fitting, in a way?"
        },
        [51009375] = {
          ContentTC = "好啦，我要趁天還沒黑，去城外完成和他的約定。",
          DialogueId = 51009375,
          GUID = "7FB25596",
          NextDialogue = 51009376,
          SpeakNpcId = 700247,
          Subtitle = "Right, I'd best be off outside the city walls to keep my promise to him before it gets dark."
        },
        [51009376] = {
          ContentTC = "再見了，可愛的小精靈。祝願你的故事有一個真實而美滿的結局。",
          DialogueId = 51009376,
          GUID = "7FB255C0",
          SpeakNpcId = 700247,
          Subtitle = "Goodbye, little faerie. May your own story have a true and happy ending."
        },
        [51009377] = {
          ContentTC = "哎呀，小精靈，又見面了。今天的天色很美吧？",
          DialogueId = 51009377,
          GUID = "7FB255EA",
          SpeakNpcId = 700247,
          Subtitle = "Hello again, little faerie. Lovely weather we're having, isn't it?"
        },
        [51009401] = {
          ContentTC = "請留步，{性别:尊貴的先生|美麗的女士}！",
          DialogueId = 51009401,
          GUID = "7FB259DA",
          NextDialogue = 51009402,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A moment of your time, {性别:good sir|fair lady}!",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009402] = {
          ContentTC = "哦，我該用什麼形容你？",
          DialogueId = 51009402,
          GUID = "7FB25A04",
          NextDialogue = 51009403,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah... how does one even begin to capture your beauty?"
        },
        [51009403] = {
          ContentTC = "無言的狸貓為你吟唱詩篇，青綠的皓月將你鍍上黃金。海兔為你的王冠鑲上棕櫚果做的寶石，而我在無人途徑的垃圾桶旁歌頌你——",
          DialogueId = 51009403,
          GUID = "7FB25A2E",
          NextDialogue = 51009404,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A mute tanuki pens sonnets in your name; the verdant moon casts gold across your form. A sea hare crowns you with palmfruit jewels... while I, by a forgotten bin, sing your name to the stars—"
        },
        [51009404] = {
          ContentTC = "無論我的讚美能否俘獲您的垂眸，還請您……還請您……",
          DialogueId = 51009404,
          GUID = "7FB25A58",
          NextDialogue = 51009405,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Even if my words fall short of your splendour, I beg you... I implore you..."
        },
        [51009405] = {
          ContentTC = "噢！這幅非凡的儀表！您一定就是大名鼎鼎的狩月人{nickname}{性别:先生|小姐}吧！",
          DialogueId = 51009405,
          GUID = "7FB25A82",
          NextDialogue = 51009406,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! Such poise, such presence! You must be the illustrious Phoxhunter — {性别:Mr|Miss} !",
          TalkActionId = {
            [1] = "700306:Talk01_End"
          }
        },
        [51009406] = {
          ContentTC = "（我這麼有名了嗎？……不對，總覺得這句話後面不會接什麼好事……）",
          DialogueId = 51009406,
          GUID = "7FB25AAC",
          NextDialogue = 51009407,
          SpeakNpcId = 100001,
          Subtitle = "(Am I actually that well-known around here...? No — this is definitely heading somewhere strange...)"
        },
        [51009407] = {
          ContentTC = "初次見面，我叫費恩。老師已經等您很久了，請跟我來。",
          DialogueId = 51009407,
          GUID = "7FB25AD6",
          NextDialogue = 51009408,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          Subtitle = "A pleasure to meet you — I'm Fane. My teacher has been awaiting your arrival. This way, please.",
          TalkActionId = {
            [1] = "700306:Talk02_Start"
          }
        },
        [51009408] = {
          ContentTC = "老師？",
          DialogueId = 51009408,
          GUID = "7FB25B00",
          NextDialogue = 51009409,
          SpeakNpcId = 100001,
          Subtitle = "Teacher?",
          TalkActionId = {
            [1] = "700306:Talk02_End"
          }
        },
        [51009409] = {
          ContentTC = "不……唉我怎麼忘了老師不讓我在公開場合這麼叫她。不過如果是您的話應該沒問題吧……還請您不要外傳。",
          DialogueId = 51009409,
          GUID = "7FB25B2A",
          Scripts = "PlayOrStopBGM{_delay{8},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          Subtitle = "Oh — right... She asked me not to call her that in public. But I doubt she'll mind if it's you. Still... I'd appreciate it if you kept it just between us."
        },
        [51009410] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "老師，我把{nickname}{性别:小姐|先生}帶來了。",
          DialogueId = 51009410,
          GUID = "7FB25B54",
          LookAt = {
            [1] = "700306:n(700300)"
          },
          NextDialogue = 51009411,
          SpeakNpcId = 700306,
          Subtitle = "Ms Violetta, I've brought ."
        },
        [51009411] = {
          Camera = "-398.734863,102.79834,140.336914,0.000002,-0.59967,-17.199116,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你來了，年輕的狩月人。",
          DialogueId = 51009411,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25B7E",
          LookAt = {
            [1] = "700306:n(100001)"
          },
          NextDialogue = 51009412,
          SpeakNpcId = 700300,
          Subtitle = "You've come, young Phoxhunter.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009412] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "呀，真是個可愛的孩子。你的容貌讓我想起這座城市晶瑩的初雪，還有那點綴於初雪之上，鴿血般的石榴石，多讓人忍不住想要輕撫——",
          DialogueId = 51009412,
          GUID = "7FB25BA8",
          NextDialogue = 51009413,
          SpeakNpcId = 700300,
          Subtitle = "Ah... such a darling child. Your beauty reminds me of Icelake's first snow — that flawless glisten... and those garnets scattered across it, red as pigeon blood... so tender, one's hand longs to—",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009413] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "等等，你不要過來——",
          DialogueId = 51009413,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "-93.166504,20.057129,149.304932,-1.999999,-3.400054,-165.189987,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB25BD2",
          NextDialogue = 51009414,
          SpeakNpcId = 100001,
          Subtitle = "Wait — don't come any closer!",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 1
        },
        [51009414] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗬嗬，原來你不喜歡這樣的親密接觸。失禮了，很抱歉用這種看起來很可疑的方式邀請你，請容許我先自我介紹一下。",
          DialogueId = 51009414,
          GUID = "7FB25BFC",
          NextDialogue = 51009415,
          SpeakNpcId = 700300,
          Subtitle = "Hehe, not a fan of warm greetings, I see. My apologies — this must all seem terribly dubious. Allow me to introduce myself properly.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009415] = {
          ContentTC = "我叫薇奧萊塔，一名歌劇演員。",
          DialogueId = 51009415,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB25C26",
          NextDialogue = 51009416,
          SpeakNpcId = 700300,
          Subtitle = "I'm Violetta — an opera singer.",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009416] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（他們唱歌劇的說話怎麼一個比一個怪啊！）",
          DialogueId = 51009416,
          GUID = "7FB25C50",
          NextDialogue = 51009417,
          SpeakNpcId = 100001,
          Subtitle = "(Why do you opera singers talk like that...?)",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009417] = {
          Camera = "-142.214844,78.577148,148.40918,0.000003,-0.599971,-20.395008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "如果你見過我，應該是在劇院裡，或者是在附近的劇目海報上。",
          DialogueId = 51009417,
          GUID = "7FB25C7A",
          NextOptions = {
            [1] = 510093271,
            [2] = 510093272
          },
          SpeakNpcId = 700300,
          Subtitle = "If I seem familiar, perhaps you've seen me on stage... or glimpsed one of my posters nearby."
        },
        [51009418] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我想起來了，「來自盧卡的夢幻之聲，顛覆常識的百變容顏」，劇院的宣傳標語好像是這麼寫的。",
          DialogueId = 51009418,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB25CA4",
          NextDialogue = 51009420,
          SpeakNpcId = 100001,
          Subtitle = "I remember now — \"A dream-born voice from Luca, a visage that shifts like mist.\" That's what the posters said, right?",
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51009419] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「來自盧卡的夢幻之聲，顛覆常識的百變容顏」——薇奧萊塔老師是如今冰湖城炙手可熱的歌者。如果您去蓋雷亞劇院，就能看到畫著老師肖像的大幅海報。",
          DialogueId = 51009419,
          GUID = "7FB25CCE",
          LookAt = {
            [1] = "100001:n(700306)"
          },
          NextDialogue = 51009420,
          SpeakNpcId = 700306,
          Subtitle = "\"A dream-born voice from Luca, a visage that shifts like mist\" — that's her. Ms Violetta is the most sought-after diva in Icelake. You'll find her posters all over the Galea Theatre.",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009420] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "原來他們是這樣形容我的。雖然有些誇張，但是我喜歡。",
          DialogueId = 51009420,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB25CF8",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009421,
          SpeakNpcId = 700300,
          Subtitle = "So that's what they say about me. A bit extravagant... but I rather like the sound of it.",
          TalkActionId = {
            [1] = "700306:Talk01_End",
            [2] = "700300:Confident_Start"
          }
        },
        [51009421] = {
          ContentTC = "我喜歡看著人們為我的表演喝彩，喜歡聽到他們在街頭巷尾討論某個唱段。",
          DialogueId = 51009421,
          GUID = "7FB25D22",
          NextDialogue = 51009422,
          SpeakNpcId = 700300,
          Subtitle = "I love the applause — and the chatter my performances stir in every corner of the city."
        },
        [51009422] = {
          ContentTC = "每一次不同的舞台樣貌，又或者是單純突發奇想的臨場發揮，都會在接下來的一個月占據所有的娛樂報刊——我很享受這樣的感覺。",
          DialogueId = 51009422,
          GUID = "7FB25D4C",
          NextDialogue = 51009423,
          SpeakNpcId = 700300,
          Subtitle = "Every role I play, every off-script whim... they ignite the gossip columns for weeks. I thrive on that kind of attention."
        },
        [51009423] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不好意思……所以委托的內容是？",
          DialogueId = 51009423,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25D76",
          NextDialogue = 51009424,
          SpeakNpcId = 100001,
          Subtitle = "Sorry to interrupt... but what's the job, exactly?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009424] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "啊呀，看來多餘的話說的太多了。",
          DialogueId = 51009424,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25DA0",
          NextDialogue = 51009425,
          SpeakNpcId = 700300,
          Subtitle = "Ah, forgive me — I've let my flourishes run away with me again.",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700300:Explain02_Start"
          }
        },
        [51009425] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "實際上，雖然我很享受站在所有人的視線中心，也已經習慣了這麼做。不過有些特殊的情況還是很難應付……",
          DialogueId = 51009425,
          GUID = "7FB25DCA",
          NextDialogue = 51009426,
          SpeakNpcId = 700300,
          Subtitle = "Truth is, while I do enjoy being the centre of attention — and have grown quite used to it — there are... certain situations even I find troublesome.",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009426] = {
          ContentTC = "請你看看這個。",
          DialogueId = 51009426,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Letter.T_Guide_ChapterFire_Letter'}",
          GUID = "7FB25DF4",
          NextDialogue = 51009427,
          SpeakNpcId = 700300,
          Subtitle = "Here — take a look at this.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009427] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "一封情書？看內容像是薇奧萊塔女士的劇迷寫的。",
          DialogueId = 51009427,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25E1E",
          NextDialogue = 51009428,
          SpeakNpcId = 100001,
          Subtitle = "A love letter? Looks like it's from one of your fans.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009428] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "太過受歡迎有時候也是一種煩惱，我理解大家對我的熱情，雖然我沒有辦法接受他們的心意，但我也會盡量禮貌地回應。",
          DialogueId = 51009428,
          GUID = "7FB25E48",
          NextDialogue = 51009429,
          SpeakNpcId = 700300,
          Subtitle = "Popularity can be a heavy crown. I understand their affection — and while I can't reciprocate those feelings, I do my best to respond with kindness.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009429] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我曾不止一次收到過類似的信件，也都盡量給出了回復，不過這次……我收到了整整一箱。",
          DialogueId = 51009429,
          GUID = "7FB25E72",
          NextDialogue = 51009430,
          SpeakNpcId = 700300,
          Subtitle = "I've received such letters before — many, in fact — and I've replied where I could. But this time, I've been sent an entire box.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009430] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這……這麼多？！",
          DialogueId = 51009430,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB25E9C",
          NextDialogue = 51009431,
          SpeakNpcId = 100001,
          Subtitle = "An entire box of letters...!?",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009431] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗯，而且都是同一個人寄來的。一開始是信箱，然後是馬車裡，再往後是門縫，窗台的花盆下……",
          DialogueId = 51009431,
          GUID = "7FB25EC6",
          NextDialogue = 51009432,
          SpeakNpcId = 700300,
          Subtitle = "Yes — all from the same admirer. It began with the mailbox... then my carriage, then the doorframe, flowerpots, windowsills...",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "100001:Shock_End"
          }
        },
        [51009432] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "幾乎宅邸的每個角落都會在我不經意間塞滿類似的信件。",
          DialogueId = 51009432,
          GUID = "7FB25EF0",
          NextDialogue = 51009433,
          SpeakNpcId = 700300,
          Subtitle = "They slip them in wherever they can — whenever my back is turned.",
          TalkActionId = {
            [1] = "700300:Talk01_End"
          }
        },
        [51009433] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這件事是不是應該交給衛戍部隊來處理？",
          DialogueId = 51009433,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB25F1A",
          NextDialogue = 51009434,
          SpeakNpcId = 100001,
          Subtitle = "Shouldn't this be something for the Escort to deal with?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009434] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我也在第一時間這樣想過，可是作為萬眾矚目的明星總會有這樣或者那樣的不便。",
          DialogueId = 51009434,
          GUID = "7FB25F44",
          NextDialogue = 51009435,
          SpeakNpcId = 700300,
          Subtitle = "That was my first thought as well. But public figures... walk a fine line.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009435] = {
          ContentTC = "也許一些小小的插曲會讓我在茶餘飯後的閑談中占據更多的分量，不過作為一名演員，我還是希望大家對我的討論盡量集中於舞台上的演繹，還望你能理解。",
          DialogueId = 51009435,
          GUID = "7FB25F6E",
          NextDialogue = 51009436,
          SpeakNpcId = 700300,
          Subtitle = "A bit of harmless gossip might make me the talk of teatimes... but as a performer, I'd rather the town whisper about my stagecraft — not my romances.",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009436] = {
          Camera = "124.308105,149.785156,166.572021,0.000009,-4.799984,-153.390015,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "好吧，我明白了。對於送信的人，薇奧萊塔女士有什麼線索嗎？",
          DialogueId = 51009436,
          GUID = "7FB25F98",
          NextDialogue = 51009437,
          SpeakNpcId = 100001,
          Subtitle = "Fair enough. Do you have any clues about the sender?"
        },
        [51009437] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "關於這個，剛才忘記說了。實際上我已經知道了送信人的住址，雖然是匿名信，但對方並沒有隱瞞自己身份的意思。",
          DialogueId = 51009437,
          GUID = "7FB25FC2",
          NextDialogue = 51009438,
          SpeakNpcId = 700300,
          Subtitle = "Ah, yes — I forgot to mention. I actually do know where he lives. The letters are unsigned, but he's made no real effort to hide his identity.",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009438] = {
          ContentTC = "如果連求愛信都不得不隱藏自己的身份，那麼這位可憐的先生又如何能夠等來對方的回應呢？",
          DialogueId = 51009438,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB25FEC",
          NextDialogue = 51009439,
          SpeakNpcId = 700300,
          Subtitle = "If one must hide even their name in a love letter... what hope is there for a reply?"
        },
        [51009439] = {
          Camera = "-642.584961,260.924316,353.573975,0.000005,-21.200073,-26.393641,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你只需要找到他，然後小小地「警告」一下就好。",
          DialogueId = 51009439,
          GUID = "7FB26016",
          NextOptions = {
            [1] = 510093491,
            [2] = 510093492
          },
          SpeakNpcId = 700300,
          Subtitle = "I only ask that you find him... and deliver a gentle \"warning.\""
        },
        [51009440] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那就拜托你了。",
          DialogueId = 51009440,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB26040",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          Subtitle = "How reassuring. I knew you were the right one to ask.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009441] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你知道的，如果我給予這樣的人太多的關注，就會讓他誤以為自己有資格吸引我的注意，並因此變本加厲。",
          DialogueId = 51009441,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2606A",
          NextDialogue = 51009442,
          SpeakNpcId = 700300,
          Subtitle = "You see, someone like that... even a moment of attention might feel like victory. And that can turn dangerous.",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009442] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "的確有點道理。",
          DialogueId = 51009442,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB26094",
          NextDialogue = 51009443,
          SpeakNpcId = 100001,
          Subtitle = "I see. That makes sense."
        },
        [51009443] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那就拜托你了。",
          DialogueId = 51009443,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB260BE",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          Subtitle = "Then I'll leave it in your hands.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009444] = {
          ContentTC = "哦，對了。我把這個交給你，應該會用得上。",
          DialogueId = 51009444,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          GUID = "7FB260E8",
          NextDialogue = 51009445,
          SpeakNpcId = 700300,
          Subtitle = "Oh — and before you go, take this. It may come in handy.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009445] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這根發帶……",
          DialogueId = 51009445,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB26112",
          NextDialogue = 51009446,
          SpeakNpcId = 100001,
          Subtitle = "This ribbon...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009446] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "怎麼了嗎？",
          DialogueId = 51009446,
          GUID = "7FB2613C",
          NextDialogue = 51009447,
          SpeakNpcId = 700300,
          Subtitle = "Is something wrong?"
        },
        [51009447] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不，沒什麼。我去去就回。",
          DialogueId = 51009447,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26166",
          SpeakNpcId = 100001,
          Subtitle = "No... it's nothing. I'll be back soon.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009448] = {
          Camera = "695.307617,-554.236328,471.275024,0.000054,-20.794161,139.593384,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "薇奧萊塔女士說的地址就是這裡，不過附近好像沒什麼住宅的樣子。",
          DialogueId = 51009448,
          GUID = "7FB26190",
          NextDialogue = 51009449,
          SpeakNpcId = 100001,
          Subtitle = "This is the address Ms Violetta gave me. Doesn't exactly look like a residential area, though...",
          TalkActionId = {
            [1] = "700313:Think_Start"
          }
        },
        [51009449] = {
          ContentTC = "旁邊有個衛兵，過去打聽一下吧。",
          DialogueId = 51009449,
          GUID = "7FB261BA",
          NextDialogue = 51009450,
          SpeakNpcId = 100001,
          Subtitle = "There's a guard nearby — maybe he'll know something."
        },
        [51009450] = {
          Camera = "232.955078,593.629395,162.682861,0.000058,-3.794279,-115.003006,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你好，我想和你打聽點事情。",
          DialogueId = 51009450,
          GUID = "7FB261E4",
          NextDialogue = 51009451,
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"Questpoint_Nvzhu_20023002\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Hey — mind if I ask you something?"
        },
        [51009451] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我在忙，等我有空再說吧。奇怪，這裡應該是這樣啊……這唱機怎麼了……",
          DialogueId = 51009451,
          GUID = "7FB2620E",
          NextDialogue = 51009452,
          SpeakNpcId = 700313,
          Subtitle = "Bit tied up right now — can it wait? ...Huh, that's odd. What's up with this phonograph?"
        },
        [51009452] = {
          Camera = "408.029297,-87.160217,216.346191,0.000075,-13.994142,150.79335,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（男人焦頭爛額地擺弄著地上的一台舊唱機。）",
          DialogueId = 51009452,
          GUID = "7FB26238",
          NextDialogue = 51009453,
          Subtitle = "(The soldier frowns at an old phonograph at his feet, fiddling with the dials in frustration.)"
        },
        [51009453] = {
          ContentTC = "它壞掉了嗎？",
          DialogueId = 51009453,
          GUID = "7FB26262",
          NextDialogue = 51009454,
          SpeakNpcId = 100001,
          Subtitle = "Is it broken?"
        },
        [51009454] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "應該也不算壞掉……但有些年頭了，偶爾會失靈。我明明記得這麼來一下就行啊……",
          DialogueId = 51009454,
          GUID = "7FB2628C",
          NextOptions = {
            [1] = 510093641
          },
          SpeakNpcId = 700313,
          Subtitle = "Not broken, exactly... just old. Sometimes it acts up. I swear a good smack used to fix it...",
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009455] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你會折騰這東西？那這樣，如果你能幫我修好我一定知無不言。",
          DialogueId = 51009455,
          GUID = "7FB262B6",
          NextDialogue = 51009456,
          SpeakNpcId = 700313,
          Subtitle = "You know how to work these? Alright — fix it for me, and I'll answer whatever you need.",
          TalkActionId = {
            [1] = "700313:Talk01_End"
          }
        },
        [51009456] = {
          Camera = "96.858398,213.679291,148.014893,0.00006,-3.794279,-114.800949,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "一言為定。",
          DialogueId = 51009456,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB262E0",
          SpeakNpcId = 100001,
          Subtitle = "Deal.",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Talk01_End"
          }
        },
        [51009457] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這樣應該就可以了。",
          DialogueId = 51009457,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "7FB2630A",
          NextDialogue = 51009458,
          SpeakNpcId = 100001,
          Subtitle = "There — that should do it.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009458] = {
          Camera = "490.863281,-71.149292,246.487061,0.000077,-14.394158,157.593735,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "有兩下子啊，這樣總算能聽我的錄音帶了。啊，薇奧萊塔女士的歌喉——",
          DialogueId = 51009458,
          GUID = "7FB26334",
          NextDialogue = 51009459,
          SpeakNpcId = 700313,
          Subtitle = "Not bad! Now I can finally enjoy my tapes again... Ahh, Ms Violetta's voice — it's just—",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700313:Shock_Start"
          }
        },
        [51009459] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你知道薇奧萊塔？",
          DialogueId = 51009459,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2635E",
          NextDialogue = 51009460,
          SpeakNpcId = 100001,
          Subtitle = "Wait — you know Violetta?",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Shock_End"
          }
        },
        [51009460] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這冰湖城有誰不知道嗎？她的首部唱片都已經炒到了天價，我攢了三個月的薪水還買不起！唉，只能先聽便宜錄音帶解解饞。",
          DialogueId = 51009460,
          GUID = "7FB26388",
          NextDialogue = 51009461,
          SpeakNpcId = 700313,
          Subtitle = "Who in Icelake doesn't? Her debut album's a collector's item! I've been saving for three months and still can't afford one... Guess these budget tapes will have to do for now.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009461] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那就好說了，我要問的事剛好和薇奧萊塔女士有關。",
          DialogueId = 51009461,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB263B2",
          SpeakNpcId = 100001,
          Subtitle = "Perfect. Because what I wanted to ask is actually about Ms Violetta.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009462] = {
          ContentTC = "（再三叮囑對方務必保密後，向衛兵大概說明了薇奧萊塔女士遭遇騷擾的事。）",
          DialogueId = 51009462,
          GUID = "7FB263DC",
          Subtitle = "(After swearing the guard to secrecy, you explain the situation: Ms Violetta has been receiving unwanted letters from an obsessed admirer.)"
        },
        [51009463] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "什麼？居然有這種事？！這真的是太不成體統了！如果犯人真的住在這片街區，我一定幫你把他揪出來好好教訓一頓！",
          DialogueId = 51009463,
          GUID = "7FB26406",
          NextDialogue = 51009464,
          SpeakNpcId = 700313,
          Subtitle = "What!? That's outrageous! If that creep's squatting on my beat, I'll drag him out myself — give him a piece of my mind!",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700313:Angry01_Start"
          }
        },
        [51009464] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "倒也不用這麼誇張……",
          DialogueId = 51009464,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB26430",
          NextDialogue = 51009465,
          SpeakNpcId = 100001,
          Subtitle = "That... won't be necessary.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51009465] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "怎麼就誇張了？我生平最見不得這種危害社會治安的敗類，你放心，這一代的住戶我都或多或少打過交道，只要有點線索我一定能把犯人抓到！",
          DialogueId = 51009465,
          GUID = "7FB2645A",
          NextDialogue = 51009466,
          SpeakNpcId = 700313,
          Subtitle = "Sure it is! I can't stand lowlifes who disrupt public peace. I know every face on this block — just give me something to go on, and I'll smoke him out.",
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009466] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "線索的話……這封信你有什麼頭緒嗎？",
          DialogueId = 51009466,
          GUID = "7FB26484",
          NextDialogue = 51009467,
          SpeakNpcId = 100001,
          Subtitle = "I've got this letter here... See if anything jumps out?",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009467] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "什麼信？我看看。",
          DialogueId = 51009467,
          GUID = "7FB264AE",
          NextDialogue = 51009468,
          SpeakNpcId = 700313,
          Subtitle = "A letter? Alright, let's take a look.",
          TalkActionId = {
            [1] = "700313:Confident_End"
          }
        },
        [51009468] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "…………",
          DialogueId = 51009468,
          FinalCamera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB264D8",
          NextDialogue = 51009469,
          SpeakNpcId = 700313,
          Subtitle = "...",
          ToFinalCameraBlendTime = 1
        },
        [51009469] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "…………",
          DialogueId = 51009469,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26502",
          NextDialogue = 51009470,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009470] = {
          ContentTC = "怎麼了，你為什麼不說話？",
          DialogueId = 51009470,
          GUID = "7FB2652C",
          NextDialogue = 51009471,
          SpeakNpcId = 100001,
          Subtitle = "What's with the sudden silence?"
        },
        [51009471] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這……這對嗎？這不對吧？我覺得這封信言辭懇切情感真摯，和騷擾信天差地別。",
          DialogueId = 51009471,
          GUID = "7FB26556",
          NextDialogue = 51009472,
          SpeakNpcId = 700313,
          Subtitle = "No... no way. This letter — it's heartfelt and... sincere! How could this be harassment?",
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009472] = {
          Camera = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "看來寄信的人已經找到了。剛才好像有人說要把犯人好好教訓一頓？",
          DialogueId = 51009472,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB26580",
          NextDialogue = 51009473,
          SpeakNpcId = 100001,
          Subtitle = "Looks like we've found our guy. Weren't you just going on about giving someone a piece of your mind?"
        },
        [51009473] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這是誤會，一定是誤會。我發誓我對薇奧萊塔女士一片真心——不是說薇奧萊塔女士最喜歡熱情洋溢的表白嗎？她怎麼會說那是騷擾啊？",
          DialogueId = 51009473,
          GUID = "7FB265AA",
          NextDialogue = 51009474,
          SpeakNpcId = 700313,
          Subtitle = "This is all a huge misunderstanding! It was all from the heart! I swear — my feelings for Ms Violetta are real! Ms Violetta adores bold declarations of love — why would she see this as anything but romantic!?"
        },
        [51009474] = {
          ContentTC = "……難道是<H>那傢伙在騙我</>……",
          DialogueId = 51009474,
          GUID = "7FB265D4",
          NextDialogue = 51009475,
          SpeakNpcId = 700313,
          Subtitle = "Wait a sec... was I tricked by that Phoxhunter...?"
        },
        [51009475] = {
          ContentTC = "等一下，我明白了！是你！你根本不是薇奧萊塔女士派來的，你是來拆散我們的！",
          DialogueId = 51009475,
          GUID = "7FB265FE",
          NextDialogue = 51009476,
          SpeakNpcId = 700313,
          Subtitle = "Oh, I get it now — it's you! You're not here on Ms Violetta's behalf — you're trying to drive a wedge between us!",
          TalkActionId = {
            [1] = "700313:Angry01_Start"
          }
        },
        [51009476] = {
          ContentTC = "你有什麼證據證明是薇奧萊塔女士讓你來的？依我看你就是在挑撥離間！",
          DialogueId = 51009476,
          GUID = "7FB26628",
          NextDialogue = 51009477,
          SpeakNpcId = 700313,
          Subtitle = "Got any proof she sent you? I bet you're just here to stir the pot!"
        },
        [51009477] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "居然試圖用這樣的手段來破壞薇奧萊塔女士和追隨者之間的信任，我必須要好好教訓一下你！",
          DialogueId = 51009477,
          GUID = "7FB26652",
          NextDialogue = 51009478,
          SpeakNpcId = 700313,
          Subtitle = "Trying to poison the sacred bond between Ms Violetta and her loyal fans!? Not on my watch — I'll make you regret it!"
        },
        [51009478] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你這人怎麼……",
          DialogueId = 51009478,
          GUID = "7FB2667C",
          NextDialogue = 51009479,
          SpeakNpcId = 100001,
          Subtitle = "What's your problem...?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51009479] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（還是先想辦法讓這個自說自話的傢伙冷靜一下吧。）",
          DialogueId = 51009479,
          GUID = "7FB266A6",
          SpeakNpcId = 100001,
          Subtitle = "(Alright. Best calm this delusional man down first.)"
        },
        [51009480] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "薇奧萊塔女士，是我……是我太弱小……",
          DialogueId = 51009480,
          GUID = "7FB266D0",
          NextDialogue = 51009481,
          SpeakNpcId = 700313,
          Subtitle = "Ms Violetta... I'm sorry... I was just... not strong enough to protect you...",
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009481] = {
          Camera = "172.162109,534.255371,170.810547,0.000068,-3.594264,-113.598976,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "鬧夠了？看看這個吧。",
          DialogueId = 51009481,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "7FB266FA",
          NextDialogue = 51009482,
          SpeakNpcId = 100001,
          Subtitle = "Are you done? Here. Take a look at this.",
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "700313:Stop01_End"
          }
        },
        [51009482] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這是，薇奧萊塔女士的緞帶？她從十多年前第一次公開演出開始就一直帶著的……",
          DialogueId = 51009482,
          GUID = "7FB26724",
          NextDialogue = 51009483,
          SpeakNpcId = 700313,
          Subtitle = "This... this is her ribbon. She's worn it since her debut, over ten years ago...",
          TalkActionId = {
            [1] = "700313:Shock_Start"
          }
        },
        [51009483] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這也能認出來？",
          DialogueId = 51009483,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB2674E",
          NextDialogue = 51009484,
          SpeakNpcId = 100001,
          Subtitle = "You recognised it that quickly?",
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51009484] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "怎麼可能認不出來！我跟你說這些乾嗎……",
          DialogueId = 51009484,
          GUID = "7FB26778",
          NextDialogue = 51009485,
          SpeakNpcId = 700313,
          Subtitle = "Of course I did... Ugh. Why am I even wasting my breath?",
          TalkActionId = {
            [1] = "700313:Shock_End"
          }
        },
        [51009485] = {
          ContentTC = "既然你拿著這個，那看來我是真的被拒絕了。我不會再去騷擾薇奧萊塔女士了，祝你們幸福。",
          DialogueId = 51009485,
          GUID = "7FB267A2",
          NextOptions = {
            [1] = 510093951,
            [2] = 510093952
          },
          SpeakNpcId = 700313,
          Subtitle = "If she gave you this... then I guess I've got no chance. I won't bother her again. Hope you two are happy together."
        },
        [51009486] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不要再說了，就讓一顆熾烈的心在角落默默哭泣吧！",
          DialogueId = 51009486,
          GUID = "7FB267CC",
          NextDialogue = 51009487,
          SpeakNpcId = 700313,
          Subtitle = "Say no more. Let a broken heart weep alone in the dark...",
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009487] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（衛兵不再回答，只是一味流淚……還是讓他自己安靜一會兒吧。）",
          DialogueId = 51009487,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB267F6",
          SpeakNpcId = 100001,
          Subtitle = "(He won't say another word... just keeps sobbing. Best to give him some space.)"
        },
        [51009488] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "薇奧萊塔女士，我回來了。",
          DialogueId = 51009488,
          GUID = "7FB26820",
          NextDialogue = 51009489,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta — I'm back.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009489] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "辛苦你了，看起來問題已經解決了。",
          DialogueId = 51009489,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB2684A",
          NextDialogue = 51009490,
          SpeakNpcId = 700300,
          Subtitle = "Thank you. I take it the matter's been settled?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Talk02_Start"
          }
        },
        [51009490] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗯，他不會再來騷擾你了。這條緞帶也還給你，如果沒有它，恐怕還要再被糾纏一段時間。",
          DialogueId = 51009490,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26874",
          NextDialogue = 51009491,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. He won't be bothering you again. Here's your ribbon — I doubt it would've gone so smoothly without it.",
          TalkActionId = {
            [1] = "700300:Talk02_End",
            [2] = "100001:Give"
          }
        },
        [51009491] = {
          ContentTC = "聽說這條緞帶，你從十幾年前就一直戴著？",
          DialogueId = 51009491,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2689E",
          NextDialogue = 51009492,
          SpeakNpcId = 100001,
          Subtitle = "I heard you've worn this since your debut... over a decade ago?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009492] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "是的，這是一位友人留給我的紀念，她才華橫溢，但卻不受命運垂憐……",
          DialogueId = 51009492,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268C8",
          NextDialogue = 51009493,
          SpeakNpcId = 700300,
          Subtitle = "Yes. It was a keepsake from a dear friend of mine. She was brilliant, yet ill-favoured by fate...",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Sigh_Start"
          }
        },
        [51009493] = {
          ContentTC = "出於某些原因，她無法實現自己的夢想了，不過我可以，所以我希望能夠讓她也一起在舞台上閃耀。",
          DialogueId = 51009493,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268F2",
          NextDialogue = 51009494,
          SpeakNpcId = 700300,
          Subtitle = "She never got the chance to realise her dream... but I did. I only hoped to share the spotlight with her.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009494] = {
          ContentTC = "所以在我第一次公演的時候，我親自設計了一張海報，在黑白的畫面裡，只有一抹紫色格外亮眼——",
          DialogueId = 51009494,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2691C",
          NextDialogue = 51009495,
          SpeakNpcId = 700300,
          Subtitle = "When I debuted, I designed my own poster — black and white, save for one vivid streak of violet.",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009495] = {
          ContentTC = "你應該聽說過「千面的薇奧萊塔」這個稱呼，我有著足以讓自己變成另一個人的化妝技術，在每場演出都會根據角色用不同的容貌登台。",
          DialogueId = 51009495,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26946",
          NextDialogue = 51009496,
          SpeakNpcId = 700300,
          Subtitle = "You've likely heard the name \"Violetta of a Thousand Faces.\" With my skills in makeup, I can become anyone for the stage — taking on a different face for every role I play."
        },
        [51009496] = {
          ContentTC = "但唯獨這條緞帶，我每次都會戴上。久而久之，<H>它也就成了我獨有的標誌</>。",
          DialogueId = 51009496,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26970",
          NextDialogue = 51009497,
          SpeakNpcId = 700300,
          Subtitle = "But one thing never changes: this ribbon. I wear it every time. It's become my signature.",
          TalkActionId = {
            [1] = "700300:Talk02_End"
          }
        },
        [51009497] = {
          Camera = "6.950195,47.361328,152.822266,0.000007,-4.600037,-165.990051,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "原來如此……",
          DialogueId = 51009497,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "7FB2699A",
          NextDialogue = 51009498,
          SpeakNpcId = 100001,
          Subtitle = "I see..."
        },
        [51009498] = {
          ContentTC = "老師！",
          DialogueId = 51009498,
          GUID = "7FB269C4",
          LookAt = {
            [1] = "100001:n(700306)",
            [2] = "700300:n(700306)"
          },
          NextDialogue = 51009499,
          SpeakNpcId = 700306,
          Subtitle = "Ms Violetta!"
        },
        [51009499] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "費恩，我應該教過你不要大呼小叫。",
          DialogueId = 51009499,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB269EE",
          NextDialogue = 51009500,
          SpeakNpcId = 700300,
          Subtitle = "Fane — have I not taught you to mind your volume?",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009500] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "對不起……但是老師你必須看看這個！",
          DialogueId = 51009500,
          GUID = "7FB26A18",
          NextDialogue = 51009501,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"}},
SEQ{
MoveTo{ActorId{700306},TargetPoint{"QuestPoint_Fane_2002300701"},MoveSpeed{250},Visibility{"Show"}},
MoveTo{ActorId{700306},TargetPoint{"QuestPoint_Fane_2002300702"},MoveSpeed{250},Visibility{"Show"}},
TurnTo{TurnToDescription{"700306:n(700300)"}}
}
}]],
          SpeakNpcId = 700306,
          Subtitle = "Sorry... but you have to see this!"
        },
