          SpeakNpcId = 200003,
          Subtitle = "Putini...",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009807] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這個名字怎麼了？",
          DialogueId = 51009807,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29C76",
          NextDialogue = 51009808,
          SpeakNpcId = 100001,
          Subtitle = "Does that name mean anything to you?",
          TalkActionId = {
            [1] = "100001:ScratchHead_End"
          }
        },
        [51009808] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "單論名字好像沒什麼特別的，不過箱子裡的那個聲音確實提到了前幾天歌劇院的演出對嗎？",
          DialogueId = 51009808,
          GUID = "7FB29CA0",
          NextDialogue = 51009809,
          SpeakNpcId = 200003,
          Subtitle = "Not by itself. But didn't that voice in the crate mention an opera that just played at the theatre?"
        },
        [51009809] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗯，還專門問過我那個女主角唱的怎麼樣。",
          DialogueId = 51009809,
          GUID = "7FB29CCA",
          NextDialogue = 51009810,
          SpeakNpcId = 100001,
          Subtitle = "Yeah — she even asked how the lead did.",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009810] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "實際上我從酒館的客人那裡聽到了這樣一則傳聞……",
          DialogueId = 51009810,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29CF4",
          NextDialogue = 51009811,
          SpeakNpcId = 200003,
          Subtitle = "Funny thing, that. There's been some talk in the tavern...",
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009811] = {
          ContentTC = "他們中曾經有人觀看過《普蒂妮》的彩排，當時的女主角並不是正式公演時登台的這位。",
          DialogueId = 51009811,
          GUID = "7FB29D1E",
          NextDialogue = 51009812,
          SpeakNpcId = 200003,
          Subtitle = "One of the regulars caught the dress rehearsal for Putini. Said the lead wasn't the same actress who performed on opening night."
        },
        [51009812] = {
          ContentTC = "據他說那是一個更年輕的，但很有天賦的演員，但正式演出登台的，卻還是以前的主演。",
          DialogueId = 51009812,
          GUID = "7FB29D48",
          NextDialogue = 51009813,
          SpeakNpcId = 200003,
          Subtitle = "They said the rehearsal lead was younger — even more talented. But in the end, the role went to the usual star."
        },
        [51009813] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你是說……",
          DialogueId = 51009813,
          GUID = "7FB29D72",
          NextDialogue = 51009814,
          SpeakNpcId = 100001,
          Subtitle = "You mean—",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009814] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "只是些傳聞罷了，並沒有直接的證據能把這兩件事聯係起來。",
          DialogueId = 51009814,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29D9C",
          NextDialogue = 51009815,
          SpeakNpcId = 200003,
          Subtitle = "It's just hearsay. Nothing solid to connect these dots."
        },
        [51009815] = {
          ContentTC = "不過，我對事情的真相也很好奇，如果你有空的話，可以繼續調查一下。",
          DialogueId = 51009815,
          GUID = "7FB29DC6",
          NextDialogue = 51009816,
          SpeakNpcId = 200003,
          Subtitle = "Still... if you've got time, maybe dig a little deeper. I'd like to know the truth too."
        },
        [51009816] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（看來卡蜜拉也感到有些奇怪。不過可以確定的是，吉賽爾的確有些反常。）",
          DialogueId = 51009816,
          GUID = "7FB29DF0",
          NextDialogue = 51009817,
          SpeakNpcId = 100001,
          Subtitle = "(So Camilla's in the dark too... But one thing's for sure — Giselle was acting strange.)",
          TalkActionId = {
            [1] = "200003:Talk02_End"
          }
        },
        [51009817] = {
          ContentTC = "（箱子裡的那個女孩會是那位沒能登台的演員嗎……吉賽爾是否從一開始就知情？）",
          DialogueId = 51009817,
          GUID = "7FB29E1A",
          NextDialogue = 51009818,
          SpeakNpcId = 100001,
          Subtitle = "(That girl in the crate... could she have been the one from the dress rehearsal? And if so — did Giselle know the whole time?)"
        },
        [51009818] = {
          ContentTC = "（在這裡想也不會有什麼結果，再去找吉賽爾問問吧。）",
          DialogueId = 51009818,
          GUID = "7FB29E44",
          SpeakNpcId = 100001,
          Subtitle = "(...No use guessing. I'll have to ask Giselle myself.)"
        },
        [51009819] = {
          Camera = "-459.554443,-130.776611,223.984375,0.000025,-13.400024,3.198126,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我說過，我早就說過！",
          DialogueId = 51009819,
          FacialId = {
            [1] = "700307:CM_Angry01"
          },
          GUID = "7FB29E6E",
          NextDialogue = 51009820,
          SpeakNpcId = 700307,
          Subtitle = "I told you so — I've been saying this from the start!",
          TalkActionId = {
            [1] = "700307:Angry01_Start"
          }
        },
        [51009820] = {
          ContentTC = "就不該找那種來曆不明的女人當家庭教師！就不該讓羅莎琳去學什麼聲樂！",
          DialogueId = 51009820,
          GUID = "7FB29E98",
          NextDialogue = 51009821,
          SpeakNpcId = 700307,
          Subtitle = "We never should've hired that dubious woman as a tutor! And we never should've let Rosalind take those blasted singing lessons!"
        },
        [51009821] = {
          ContentTC = "明明是你說要給她找點事做，不讓她一天到晚想著到處亂跑！",
          DialogueId = 51009821,
          FacialId = {
            [1] = "700308:CM_Sad01"
          },
          GUID = "7FB29EC2",
          NextDialogue = 51009822,
          SpeakNpcId = 700308,
          Subtitle = "You were the one who said she needed something to keep her busy — so she wouldn't be out roaming around all day!",
          TalkActionId = {
            [1] = "700308:Explain01_Start"
          }
        },
        [51009822] = {
          ContentTC = "是我說的，但我是讓她有點事做才能老實待在家裡，而不是變本加厲地往外跑搞得自己被綁匪盯上！",
          DialogueId = 51009822,
          GUID = "7FB29EEC",
          NextDialogue = 51009823,
          SpeakNpcId = 700307,
          Subtitle = "I meant something to keep her home — not something that'd send her running off again and getting herself kidnapped!",
          TalkActionId = {
            [1] = "700307:Angry01_End",
            [2] = "700308:Explain01_End"
          }
        },
        [51009823] = {
          ContentTC = "還有你們，這群廢物衛戍部隊！你們到底是乾什麼吃的？好不容易查到這裡有線索，就是因為你們效率太低，才讓綁匪跑了！",
          DialogueId = 51009823,
          GUID = "7FB29F16",
          NextDialogue = 51009824,
          Scripts = [[
PARA{
TurnTo{TurnToDescription{"700307:n(700313)"}},
TurnTo{TurnToDescription{"700308:n(700313)"}}
}]],
          SpeakNpcId = 700307,
          Subtitle = "And you Escort grunts — what use are you!? We finally had a lead, and you lot were too slow — now the kidnappers are gone!"
        },
        [51009824] = {
          ContentTC = "……",
          DialogueId = 51009824,
          GUID = "7FB29F40",
          NextDialogue = 51009825,
          SpeakNpcId = 700313,
          Subtitle = "..."
        },
        [51009825] = {
          ContentTC = "該死，我為什麼要在大街上對你們這些沒腦子的傢伙發脾氣！我要用其他的渠道去找。",
          DialogueId = 51009825,
          GUID = "7FB29F6A",
          NextDialogue = 51009826,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"700307:n(700307)"}},
LookAt{LookAtDescription{"700308:n(700308)"}},
MoveTo{ActorId{700307},MoveSpeed{150},TargetPoint{"MagnusMPoint_20023205"}},
MoveTo{ActorId{700308},MoveSpeed{150},TargetPoint{"MagnusFPoint_20023205"}}
}]],
          SpeakNpcId = 700307,
          Subtitle = "Ugh — why am I even wasting my breath on imbeciles like you? I'll find my daughter myself!"
        },
        [51009826] = {
          Camera = "-238.418213,-514.537842,220.403809,0.000037,-12.999988,72.598557,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……呼，可算走了。",
          DialogueId = 51009826,
          GUID = "7FB29F94",
          NextDialogue = 51009827,
          SpeakNpcId = 700313,
          Subtitle = "...Phew. He's finally gone."
        },
        [51009827] = {
          Camera = "77.355469,-517.516235,186.296875,0.000047,-11.199768,98.997734,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "抱歉，閑雜人等請止步。",
          DialogueId = 51009827,
          GUID = "7FB29FBE",
          NextDialogue = 51009828,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023205"}},
TurnTo{TurnToDescription{"100001:n(700313)"}}
}]],
          SpeakNpcId = 700313,
          Subtitle = "Please stay back — this area's off-limits."
        },
        [51009828] = {
          Camera = "-445.371338,-206.447021,167.490234,0.00006,-10.999575,13.197603,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不好意思，我只是聽到有爭吵聲，這裡發生了什麼？",
          DialogueId = 51009828,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB29FE8",
          NextDialogue = 51009829,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I heard yelling. Is everything okay?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009829] = {
          ContentTC = "我們收到舉報，有人實施了綁架並把受害人囚禁於此，不過等衛戍部隊趕到後這裡已經沒有人了。",
          DialogueId = 51009829,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2A012",
          NextDialogue = 51009830,
          SpeakNpcId = 700313,
          Subtitle = "We received a report of a kidnapping. The victim was supposedly held here, but the place was already empty when we arrived.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009830] = {
          ContentTC = "我們已經封鎖了這間住宅，如果你只是來看熱鬧的，就請不要繼續靠近了。",
          DialogueId = 51009830,
          GUID = "7FB2A03C",
          NextDialogue = 51009831,
          SpeakNpcId = 700313,
          Subtitle = "This property's on lockdown. If you're just here out of curiosity, I'll have to ask you to move along."
        },
        [51009831] = {
          ContentTC = "好吧，剛才那二位是？",
          DialogueId = 51009831,
          GUID = "7FB2A066",
          NextDialogue = 51009832,
          SpeakNpcId = 100001,
          Subtitle = "Who were those two just now?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009832] = {
          ContentTC = "馬格努斯伯爵和他的夫人，受害人的父母。雖然我能理解女兒被人綁架的焦急，不過這二位還真是和傳聞一樣的臭脾氣……",
          DialogueId = 51009832,
          GUID = "7FB2A090",
          NextDialogue = 51009833,
          SpeakNpcId = 700313,
          Subtitle = "The victim's parents — the Earl and Countess of Magnus. I get that they're worried, but they really do live up to their reputation...",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009833] = {
          ContentTC = "而且據說他們對女兒的控製欲也很強，說不定羅莎琳小姐就是受不了他們才往外跑。",
          DialogueId = 51009833,
          GUID = "7FB2A0BA",
          NextDialogue = 51009834,
          SpeakNpcId = 700313,
          Subtitle = "Word is they were always breathing down their daughter's neck. Maybe Miss Rosalind ran off just to get some air..."
        },
        [51009834] = {
          ContentTC = "咳……閑話說太多了。總之還請配合我們執行公務，如果有什麼線索也請告知衛戍部隊。",
          DialogueId = 51009834,
          GUID = "7FB2A0E4",
          NextDialogue = 51009835,
          SpeakNpcId = 700313,
          Subtitle = "Ahem... that's enough gossip. If you have any information, please report it to the Escort."
        },
        [51009835] = {
          Camera = "-99.088623,-74.42334,133.572266,0.000056,-4.199521,-40.602531,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（吉賽爾和……箱子小姐，似乎都不在這裡了。）",
          DialogueId = 51009835,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2A10E",
          NextDialogue = 51009836,
          SpeakNpcId = 100001,
          Subtitle = "(Giselle and Miss Crate... they're both gone.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009836] = {
          ContentTC = "（綁架……？會和吉賽爾留在水仙平原的那封信有關嗎？）",
          DialogueId = 51009836,
          GUID = "7FB2A138",
          NextDialogue = 51009837,
          SpeakNpcId = 100001,
          Subtitle = "(A kidnapping... could it have something to do with that letter Giselle left at the tavern?)"
        },
        [51009837] = {
          ContentTC = "（暫時沒有其他頭緒，平時如果有空就多留意一下吧。）",
          DialogueId = 51009837,
          GUID = "7FB2A162",
          SpeakNpcId = 100001,
          Subtitle = "(No leads for now. Guess I'll just have to stay sharp and see what turns up.)"
        },
        [51009838] = {
          ContentTC = "噠……噠噠……",
          DialogueId = 51009838,
          GUID = "7FB2A163",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Da... Da da..."
        },
        [51009850] = {
          Camera = "-1567.962891,-185.177612,2329.811035,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          ContentTC = "（這兩天冰湖城發生了好多事，還涉及到綁架案之類的……）",
          DialogueId = 51009850,
          FinalCamera = "-1614.97168,-559.773193,2467.275635,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A384",
          NextDialogue = 51009851,
          Scripts = "SetTag{Tag{\"Huozai04Tag\"},Value{\"Value_1\"}}",
          SpeakNpcId = 100001,
          Subtitle = "(So much has happened in Icelake these past few days... and now, there's even been a kidnapping.)",
          ToFinalCameraBlendTime = 5
        },
        [51009851] = {
          Camera = "389.291016,-7961.245117,-744.026855,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          ContentTC = "（仔細想想，其中<H>幾件事</>似乎和案件有千絲萬縷的聯係。）",
          DialogueId = 51009851,
          FinalCamera = "712.783569,-8322.950195,-679.47168,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3AE",
          NextDialogue = 51009852,
          SpeakNpcId = 100001,
          Subtitle = "(Now that I think about it, some of these events might be more closely connected than they seemed.)",
          ToFinalCameraBlendTime = 5
        },
        [51009852] = {
          Camera = "1489.815308,3777.302246,3313.351074,0.000015,-35.199669,-107.997414,20.0,100000.0,false,Manual,2.8",
          ContentTC = "（先簡單梳理一下吧……）",
          DialogueId = 51009852,
          FinalCamera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3D8",
          SpeakNpcId = 100001,
          Subtitle = "(Time to lay everything out... and start connecting the dots.)",
          ToFinalCameraBlendTime = 5
        },
        [51009853] = {
          Camera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          ContentTC = "（十六年前的綁架案另有隱情，而薇奧萊塔女士很可能知道真相……吉賽爾綁架了她的學生，為的是與薇奧萊塔單獨見面……）",
          DialogueId = 51009853,
          GUID = "7FB2A402",
          NextDialogue = 51009854,
          SpeakNpcId = 100001,
          Subtitle = "(There was more to the kidnapping sixteen years ago... and Violetta may be the one who knows the truth. Giselle took her student just to force a meeting.)"
        },
        [51009854] = {
          ContentTC = "（如果推斷沒錯，現在吉賽爾應該已經見到薇奧萊塔了。）",
          DialogueId = 51009854,
          GUID = "7FB2A42C",
          NextDialogue = 51009855,
          SpeakNpcId = 100001,
          Subtitle = "(If my deductions are right, she should be with Violetta right now.)"
        },
        [51009855] = {
          ContentTC = "（我還記得信上的那個地點，必須快點過去……希望沒有什麼不好的事發生。）",
          DialogueId = 51009855,
          GUID = "7FB2A456",
          SpeakNpcId = 100001,
          Subtitle = "(The letter mentioned the location. I need to hurry... let's hope I'm not too late.)"
        },
        [51009856] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentTC = "看來你還算準時。",
          DialogueId = 51009856,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2A480",
          NextDialogue = 51009857,
          SpeakNpcId = 700302,
          Subtitle = "Right on time, huh.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009857] = {
          ContentTC = "……",
          DialogueId = 51009857,
          GUID = "7FB2A4AA",
          NextDialogue = 51009858,
          SpeakNpcId = 700300,
          Subtitle = "..."
        },
        [51009858] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentTC = "都到了這個場合，你還打算一言不發嗎？我可不是迂腐的法官，如果你想聽到「你有權保持沉默」這種話，那可能要失望了。",
          DialogueId = 51009858,
          GUID = "7FB2A4D4",
          NextDialogue = 51009859,
          SpeakNpcId = 700302,
          Subtitle = "What's with the silence? This isn't a courtroom. If you're waiting for a \"You have the right to remain silent,\" don't hold your breath."
        },
        [51009859] = {
          ContentTC = "你想讓我說什麼？先來讓我聽聽吧，用這種卑劣的手段，你想得到的是怎樣的答案？",
          DialogueId = 51009859,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB2A4FE",
          NextDialogue = 51009860,
          SpeakNpcId = 700300,
          Subtitle = "And what would you have me say? Go on, enlighten me. After a despicable stunt like this, what kind of answer do you expect to hear?"
        },
        [51009860] = {
          Camera = "148.300781,-316.230469,157.037598,0.999999,-5.400179,115.588638,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你是在跟我裝糊塗嗎？還是說，你覺得你做過的惡行也像你的臉一樣，可以被你高超的化妝技術輕易遮蓋掉？",
          DialogueId = 51009860,
          GUID = "7FB2A528",
          NextDialogue = 51009861,
          SpeakNpcId = 700302,
          Subtitle = "Still playing dumb, are we? Or do you actually believe your crimes are as easy to cover up as your real face? You really think a bit of powder and paint can hide everything?"
        },
        [51009861] = {
          ContentTC = "也罷，那我來幫你回憶一下吧。",
          DialogueId = 51009861,
          GUID = "7FB2A552",
          NextDialogue = 51009862,
          SpeakNpcId = 700302,
          Subtitle = "Fine. Then let me jog your memory."
        },
        [51009862] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentTC = "十六年前，冰湖城發生了一起綁架案，一個叫西格的年輕人綁架了時任格雷姆礦場負責人法布瑞斯·魯斯福德的女兒——艾諾拉·魯斯福德。",
          DialogueId = 51009862,
          GUID = "7FB2A57C",
          NextDialogue = 51009863,
          SpeakNpcId = 700302,
          Subtitle = "Sixteen years ago, in Icelake, a young man named Sig kidnapped the daughter of Fabrice Ruthford — then overseer of Glevum Pit. Her name was Enola."
        },
        [51009863] = {
          ContentTC = "在抵抗抓捕的過程中，西格不慎點燃了房屋，導致了艾諾拉喪生，而他也因此被判處死刑。",
          DialogueId = 51009863,
          GUID = "7FB2A5A6",
          NextDialogue = 51009864,
          SpeakNpcId = 700302,
          Subtitle = "When the Escort cornered him, he resisted — and accidentally set the house on fire in the struggle. Enola died in the flames. And Sig was sentenced to death."
        },
        [51009864] = {
          Camera = "-314.688477,142.042969,142.037598,1.000012,-0.599793,-21.008369,40.559872,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那起陳年舊事我的確有所耳聞。真是一出令人扼腕的悲劇，願那個可憐的女孩安息。",
          DialogueId = 51009864,
          GUID = "7FB2A5D0",
          NextDialogue = 51009865,
          SpeakNpcId = 700300,
          Subtitle = "I've heard of that tragedy. A pity, truly. May that poor girl rest in peace.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009865] = {
          ContentTC = "——但我只是近年來才來到冰湖城，那起案件，又和我有什麼關係呢？",
          DialogueId = 51009865,
          GUID = "7FB2A5FA",
          NextDialogue = 51009866,
          SpeakNpcId = 700300,
          Subtitle = "But I only arrived in Icelake a few years ago. What could any of this possibly have to do with me?"
        },
        [51009866] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentTC = "當然是因為，那場火災有一個幸存者。",
          DialogueId = 51009866,
          GUID = "7FB2A624",
          NextDialogue = 51009867,
          SpeakNpcId = 700302,
          Subtitle = "Because someone survived that fire.",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009867] = {
          ContentTC = "根據一位知情人的說法，在火災現場除了西格和艾諾拉以外，還有一個人——西格的妹妹，維爾莉特。一個與當年的艾諾拉年歲相仿的女孩。",
          DialogueId = 51009867,
          GUID = "7FB2A64E",
          NextDialogue = 51009868,
          SpeakNpcId = 700302,
          Subtitle = "A witness said there were three people in the house that night — Sig, Enola... and Sig's sister, Violet. A girl around the same age as Enola."
        },
        [51009868] = {
          ContentTC = "在混亂的火災現場，那位知情人救出了當時也在屋子裡的維爾莉特……或者說，他<H>以為</>自己救出了維爾莉特。",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302,
          Subtitle = "In the chaos, that witness managed to pull a girl from the flames — a girl he thought was Violet. But was she really?"
        },
        [51009869] = {
          ContentTC = "到此為止，我說的沒錯吧？十六年前殺害了維爾莉特，又假扮成她，利用她的身份蒙騙多納特逃出了冰湖城的你，艾諾拉·魯斯福德！",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          Subtitle = "Tell me I'm wrong. Sixteen years ago, you killed Violet in that fire — then took her name, and tricked Donat into helping you escape Icelake. Didn't you, Enola Ruthford?",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……嗬，有趣的劇本，是不多見的懸疑題材呢。",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          Subtitle = "...Heh. Now there's a compelling tale. Good mysteries are so rare these days.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          ContentTC = "說下去，我喜歡聽。",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          Subtitle = "Please, do go on. I'm dying to hear how it ends.",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這些年我一直在調查那樁案件，燒焦的屍體，幸存的維爾莉特，這一切都太過巧合。",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          Subtitle = "I spent years combing through that case. A body burnt beyond recognition... a lone survivor... it was all just a little too convenient.",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          ContentTC = "這一切似乎都有著某種關聯，但破碎的關鍵詞之間缺少一條能將這一切連起來的線。",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302,
          Subtitle = "All the pieces were there, but the thread connecting them all together was missing."
        },
        [51009874] = {
          ContentTC = "如果不是我在衛戍部隊期間給法布瑞斯那個傢伙當過幾天護衛，並且湊巧聽到了她女兒的歌聲——",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302,
          Subtitle = "As luck would have it, back when I was assigned to guard Fabrice Ruthford, I once heard his daughter sing."
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "恐怕我永遠都不會把這些和你聯係起來，「千面的薇奧萊塔」。",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302,
          Subtitle = "That voice... I'd recognise it anywhere. And that's when I knew who you really were, \"Violetta of a Thousand Faces.\""
        },
        [51009876] = {
          ContentTC = "我用各種方法試圖調查你的生活習慣，比如……找一些人以送信的名義觀察你。",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          Subtitle = "I tried to study your habits — even arranged for false letters to be delivered, just to keep tabs on you.",
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          ContentTC = "原來那個衛兵是你派來的。",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          Subtitle = "Ah, so he was one of yours.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          ContentTC = "不，他的確是你的劇迷，我也只是稍稍煽動了一下罷了。多虧了他，我才最終確定了你的身份。",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302,
          Subtitle = "Not quite. He really was a fan. I just gave him a gentle nudge. And thanks to him, I got the answer I needed."
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,false,DoNotOverride,2.8",
          ContentTC = "即便如此，我還是有一件事沒有搞清楚。",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302,
          Subtitle = "Still, there's one thing I don't understand."
        },
        [51009880] = {
          ContentTC = "在火災中和維爾莉特調換身份，這種方法沒有西格和維爾莉特的配合難以實施，你到底是怎麼說服他們的？",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          Subtitle = "Swapping places with Violet — it couldn't have been possible unless both Sig and the girl went along with it. How did you convince them?",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我還以為你要問什麼呢……這種事不是很簡單嗎？",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          Subtitle = "That's your big mystery? The answer's simple.",
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          ContentTC = "我可是那個法布瑞斯的女兒，既然你曾經在父親的手下工作過，就應該知道觸碰他逆鱗的後果。",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          Subtitle = "You used to serve under my father. Then you should know what it meant to defy him.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          ContentTC = "可憐的西格早就做好了犧牲自己的準備，但按父親的作風，維爾莉特也無法幸免。",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300,
          Subtitle = "Poor Sig was already prepared to throw his life away — but knowing my father, Violet was as good as dead too."
        },
        [51009884] = {
          ContentTC = "而我則告訴他們：唯一的辦法，就是在拿到贖金後盡可能拖延時間，同時想辦法製造混亂讓維爾莉特逃跑。",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300,
          Subtitle = "So I offered them a way out: Once the ransom was collected, stall as long as possible while creating a distraction to buy some time for Violet."
        },
        [51009885] = {
          ContentTC = "真是可笑，驚慌失措的他居然真的獨自去拖延衛戍部隊，期待一個重病的小姑娘在火災中逃出生天……",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          Subtitle = "Pathetic, isn't it? In his panic, he actually ran off on his own to hold off the Escort, hoping that a sickly little girl might somehow escape a blazing house...",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          ContentTC = "我抓住了這個機會，殺死了那個礙事的小可憐，用她的身份擺脫了那棟破房子，也擺脫了我的父親，擺脫了所有阻止我踏上舞台的一切。",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300,
          Subtitle = "I took my chance. Killed that poor wretch who stood in my way. Took her name, left behind the dump — and my father. Left behind everything that ever stood between me and the stage."
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……",
          DialogueId = 51009887,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302,
          Subtitle = "..."
        },
        [51009888] = {
          ContentTC = "啊呀，得到了自己十幾年來日思夜想的真相，你看起來並不開心，吉賽爾女士。",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300,
          Subtitle = "What's the matter, Giselle? You've chased this truth for years... and now that you have it, you don't look the least bit satisfied."
        },
        [51009889] = {
          ContentTC = "不可理喻……就為了這種理由？就為了這種理由害死了兩個人？！你把人命當成什麼了！",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          Subtitle = "You're insane... All of this — just for the spotlight!? You killed two people! Two innocent lives!",
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          ContentTC = "那麼你打算怎麼做？去滿世界宣揚薇奧萊塔的惡毒手段讓我身敗名裂？又或者……現在就為他們兩人報仇？",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          Subtitle = "So what will it be? Drag my sins into the light? Or take your revenge, right here and now?",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          ContentTC = "……我原本只是想揭露這一切，然後把你交給衛戍部隊。",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302,
          Subtitle = "...I only ever meant to reveal the truth... and turn you in to the Escort."
        },
        [51009892] = {
          ContentTC = "（吉賽爾從腰間拔出短劍，她憤怒的神情，讓你似乎感覺自己聽到了攥緊劍柄柄，又或者是幾乎要把牙齒咬碎的碾磨聲。）",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          Subtitle = "(Giselle draws a dagger. Her fury thickens the air — you can almost hear her teeth grinding, the hilt creaking under the pressure of her grip.)",
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          ContentTC = "（如果再不阻止她，那柄利刃毫無疑問會在下一刻劃開這冰湖城最美妙的歌喉。無論如何，一場命案是你不願看到的。）",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1,
          Subtitle = "(If no one stops her, that dagger will silence the finest voice in Icelake. Whatever the truth... you can't just stand by and watch someone commit murder.)"
        },
        [51009894] = {
          ContentTC = "{nickname}？你為什麼會在這裡？",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300,
          Subtitle = "? What are you doing here?"
        },
        [51009895] = {
          ContentTC = "閃開，我無法容忍這樣的敗類繼續活在世上！",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          Subtitle = "Get out of my way. I won't let a monster like her walk free!",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          ContentTC = "（吉賽爾似乎因憤怒失去了理智，得想辦法讓她冷靜下來。）",
          DialogueId = 51009896,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2AB10",
          SpeakNpcId = 100001,
          Subtitle = "(She's lost it... I have to bring her back to her senses.)"
        },
        [51009897] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "冷靜下來，吉賽爾，或許事情並不是你想的那樣。",
          DialogueId = 51009897,
          GUID = "7FB2AB3A",
          NextDialogue = 51009898,
          SpeakNpcId = 100001,
          Subtitle = "Giselle, calm down. There might be more to this than you think.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009898] = {
          ContentTC = "你聽到她剛才說的那些話了嗎？這讓我怎麼冷靜？！",
          DialogueId = 51009898,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2AB64",
          NextDialogue = 51009899,
          SpeakNpcId = 700302,
          Subtitle = "Did you not hear what she just said!? How am I supposed to calm down!?",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009899] = {
          ContentTC = "有我們兩個在這裡，她跑不掉的。所以，至少先冷靜下來讓我問她幾個問題！",
          DialogueId = 51009899,
          GUID = "7FB2AB8E",
          NextDialogue = 51009900,
          SpeakNpcId = 100001,
          Subtitle = "She's not going anywhere — not with us here. Just take a breath. I have a few questions for her."
        },
        [51009900] = {
          Camera = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,false,DoNotOverride,2.8",
          ContentTC = "…………",
          DialogueId = 51009900,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2ABB8",
          NextDialogue = 51009901,
          SpeakNpcId = 700302,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009901] = {
          ContentTC = "你問吧。",
          DialogueId = 51009901,
          GUID = "7FB2ABE2",
          NextDialogue = 51009902,
          SpeakNpcId = 700302,
          Subtitle = "Fine. Go ahead.",
          TalkActionId = {
            [1] = "700302:Talk03_Start",
            [2] = "100001:Talk02R_End"
          },
          TurnTo = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          }
        },
        [51009902] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "在那之前，薇奧萊塔女士，這個東西你有印象嗎？",
          DialogueId = 51009902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2AC0C",
          NextDialogue = 51009903,
          SpeakNpcId = 100001,
          Subtitle = "Before that — Ms Violetta, does this look familiar?",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009903] = {
          ContentTC = "那是……",
          DialogueId = 51009903,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2AC36",
          NextDialogue = 51009904,
          SpeakNpcId = 700300,
          Subtitle = "That's...",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009904] = {
          ContentTC = "（薇奧萊塔下意識地將手伸向自己腦後，在確認到熟悉的觸感後愣在了原地。）",
          DialogueId = 51009904,
          GUID = "7FB2AC60",
          NextDialogue = 51009905,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          Subtitle = "(Violetta's hand drifts instinctively to the back of her head. Her fingers find the familiar texture — and she freezes.)"
        },
        [51009905] = {
          ContentTC = "看你的反應，我想的果然沒錯……這條緞帶，是你放在西格墓前的吧？",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001,
          Subtitle = "Huh... just as I thought. You left this ribbon at Sig's grave, didn't you?"
        },
        [51009906] = {
          ContentTC = "你曾經告訴過我，這條緞帶來自你的一位摯友，你是為了她的夢想才站上舞台的。",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          Subtitle = "You once told me it belonged to a dear friend — and that you took to the stage to fulfil her dream.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          ContentTC = "你還真是個天真的傻瓜，居然連那麼肉麻的謊言也會相信。",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300,
          Subtitle = "You're a naive fool. I can't believe you actually fell for such sentimental drivel."
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "或許吧，所以我去找多納特借來了這條緞帶，並且確認了它的來曆。",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          Subtitle = "Maybe. Which is why I borrowed this ribbon from Donat — to find out the truth.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          ContentTC = "多納特告訴了我維爾莉特的事。他說那是個才華橫溢的姑娘，如果不是貧窮和罹患重病，她也許會成為一名優秀的劇作家。",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001,
          Subtitle = "He told me about Violet. About how gifted she was. If not for poverty and illness, she might've been a great playwright."
        },
        [51009910] = {
          ContentTC = "雖然命運沒能眷顧那個女孩，但她從未放棄。即便幾乎不能下床行動，她也還是用另外的方式追尋著自己的夢想。",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001,
          Subtitle = "Fate dealt her a cruel hand, but she never gave up. Even when she could barely leave her bed, she still found a way to pursue her dream."
        },
        [51009911] = {
          ContentTC = "她希望能讓世界上最好的演員表演她創作的作品，把她在生命的最後寫下的她最滿意的故事傳遍整個阿特拉西亞。",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001,
          Subtitle = "She dreamed of the world's greatest actor performing her work — of her final, proudest piece reaching every corner of Atlasia."
        },
        [51009912] = {
          ContentTC = "那部作品的名字是——",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          Subtitle = "And that piece was—",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……三幕劇《普蒂妮》。後來被改編為同名歌劇。",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          Subtitle = "...Putini. A three-act play. Later adapted into the opera.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗯，你已經意識到了，繼續說謊只會讓你的處境更危險。所以……",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          Subtitle = "Good. You get it now — lying any further would only make things worse. So...",
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "說的也是，劇本總該有結局的。",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "I suppose you're right. Every play must end eventually.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "在這種時候說懸疑劇的經典台詞嗎……",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "...Is this really the time for theatrics?",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          ContentTC = "如果每一部懸疑劇的觀眾都如你一樣敏銳，那些劇作家也無需絞盡腦汁思考如何把劇本再改簡單些了。",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300,
          Subtitle = "Well, if every audience were as sharp as you, mystery playwrights wouldn't have to twist themselves in knots to dumb things down."
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你們在說什麼？這是什麼意思？",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          Subtitle = "What are you two talking about? What's going on here?",
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "很簡單，吉賽爾。如果薇奧萊塔真的只把維爾莉特當做隨意丟棄的工具，她怎麼會給自己取一個和維爾莉特如此相似的名字呢？",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          Subtitle = "It's simple, Giselle. If she really saw Violet as nothing but a pawn, why would she take a name so close to hers?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          ContentTC = "我繼續說我的猜測吧：十六年前，西格為了籌到錢給維爾莉特治病，綁架了艾諾拉·魯斯福德……也就是如今的薇奧萊塔。",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          Subtitle = "Let me tell you the version I see: Sixteen years ago, Sig kidnapped Enola Ruthford — the girl who would one day call herself Violetta — to raise money for his sister's treatment.",
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          ContentTC = "在被綁架的期間，艾諾拉結識了生病臥床的維爾莉特。你們就是在那時成為了摯友。",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001,
          Subtitle = "While she was held captive, Enola met the bedridden Violet. And somewhere in that brief time, the two became close friends."
        },
        [51009922] = {
          ContentTC = "但好景不長……",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001,
          Subtitle = "But it didn't last long."
        },
        [51009923] = {
          ContentTC = "維爾莉特察覺到了自己已經時日無多，她不希望哥哥為了虛無縹緲的可能性一錯再錯，於是寫信給哥哥的好友多納特，希望他阻止西格。",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001,
          Subtitle = "Violet knew her time was running out. She didn't want her brother sinking deeper down the wrong path. So she wrote to Donat — a trusted friend of Sig's — hoping he'd intervene."
        },
        [51009924] = {
          ContentTC = "如她所想，多納特最終還是找到了吉賽爾，向你舉報了西格綁架了艾諾拉的事。不過我猜，那個時候恐怕維爾莉特已經……",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001,
          Subtitle = "And Donat did. He reported the kidnapping... to you, Giselle. But by then, I suspect Violet was already—"
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "啊……說來好笑，明明是被人綁架，但那段時光卻是我出生以來最快樂的回憶。",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          Subtitle = "Ah... strange, isn't it? I was kidnapped, yet somehow... those were the happiest days of my life.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          ContentTC = "雖然把我綁在了房間裡，但西格並沒有打算傷害我，甚至並未對我有過多的關注，只是在屋子裡匆忙地走來走去。",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300,
          Subtitle = "Sig kept me tied up in a room, but he never meant me harm. He barely paid me any attention — just paced endlessly around the house."
        },
        [51009927] = {
          ContentTC = "當時的我清楚地知道屋子裡還有第三個人，那是個女孩子，總會在心情好的時候哼著歌……",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300,
          Subtitle = "I knew there was someone else — a girl — in the house. I could hear her humming softly, on days when her mood was light..."
        },
        [51009928] = {
          ContentTC = "或許是因為西格實在無法同時照顧兩個無法自理的人，所以幾天後，他給我解了綁，允許我在一樓自由行動。",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300,
          Subtitle = "Perhaps Sig realised he couldn't possibly tend to two helpless people at once. So a few days in, he untied me — let me move around the ground floor as I pleased."
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我總是在他外出的時候去二樓和維爾莉特偷偷見面，我們會一起聊她寫的故事。她會把她的想法告訴我，而我則把存在於她想象中的畫面表演出來。",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300,
          Subtitle = "And whenever he left the house, I'd steal upstairs to see Violet. She'd tell me the stories she was writing... and I'd act them out — bringing the characters to life."
        },
        [51009930] = {
          ContentTC = "「親愛的人兒，請不要為我悲傷！在這個無眠之夜，我將遠航——」",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"My dearest, weep no tears for me — on this sleepless night, I set off in silver light.\""
        },
        [51009931] = {
          ContentTC = "「風兒鼓起船帆，我撐起木槳——燈塔映在海裡啊，月光多明亮！」",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"The wind fills my sail, the tide kisses my oar. The lighthouse aglow, 'neath the moon — oh, so bright!\""
        },
        [51009932] = {
          ContentTC = "謝謝你，艾諾拉……你演得很好，很好。嗬嗬……我想象中的普蒂妮啊，她就是你的樣子……熱烈，勇敢，心兒永遠向著自由……",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Thank you, Enola... that was beautiful. Truly. Hehe... Whenever I imagined Putini, she always looked like you — bold, radiant, and forever chasing her freedom..."
        },
        [51009933] = {
          ContentTC = "謝謝！這個是我自己瞎唱的……不過我認識一位很優秀的作曲家！他叫卡瓦拉多西。我們可以拜托他把《普蒂妮》改編成歌劇——",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Thanks! I did a bit of improvising... But I know a brilliant composer — his name's Cavaradossi. Maybe we could ask him to adapt Putini into an opera—"
        },
        [51009934] = {
          ContentTC = "……不過我應該沒有機會演唱了。",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "...Not that I'll ever get the chance to sing it."
        },
        [51009935] = {
          ContentTC = "我已經十八歲了。父親已經給我安排好了婚事，就在兩個月後。對方也是煉金院的年輕長官。",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "I'm eighteen now. My father's already arranged my marriage — two months from now, to some young officer from the Alchemy Academy."
        },
        [51009936] = {
          ContentTC = "我想我接下來的一生，不是要待在小房間裡做個瓷娃娃一樣的漂亮擺件，就是要和那些該死的月髓液罐子打一輩子交道了。",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Guess I'll spend the rest of my life as a pretty trophy collecting dust in a parlour... or elbow-deep in those wretched Phoxichor canisters."
        },
        [51009937] = {
          ContentTC = "不，不……艾諾拉，不應該是這樣的——你有著雲雀一樣的歌喉……你不屬於小房間……而是更大的，更大的舞台……",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "No, no... Enola, this isn't how it should be. You have a voice as sweet as a lark's... You don't belong in some parlour... You belong on a grand stage — the grandest there is."
        },
        [51009938] = {
          ContentTC = "每一個熱愛歌唱的人……都有資格在舞台上熠熠發光……無論是索拉還是卡戎，是富有還是貧窮……",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Everyone who loves to sing... deserves their moment in the spotlight... Solarian or Charon, rich or poor..."
        },
        [51009939] = {
          ContentTC = "我會想辦法讓哥哥放你離開。我的身體已經沒有辦法了，我不知道還有沒有機會把《普蒂妮》的最後一幕寫完……",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "I'll talk to my brother. I'll find a way to help you escape. My body's already giving out... and I may never finish the final act of Putini..."
        },
        [51009940] = {
          ContentTC = "但艾諾拉，請你答應我，一定要走上舞台，把我們的《普蒂妮》唱給所有人……",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "But Enola — promise me that you'll take the stage, and share our Putini with the world..."
        },
        [51009941] = {
          ContentTC = "「每一個熱愛歌唱的人，都有資格在舞台上熠熠發光。無論他們是索拉還是卡戎，是富有還是貧窮。」這是維爾莉特的遺願，也是我一生的箴言。",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300,
          Subtitle = "\"Everyone who loves to sing deserves their moment in the spotlight. Solarian or Charon, rich or poor...\" That was Violet's final wish — and it became the truth I live by."
        },
        [51009942] = {
          ContentTC = "……後來，當我在維爾莉特病逝後，在頹廢的西格面前唱出終於完稿的《普蒂妮》最後一幕時，他的眼裡充滿驚訝，卻又像是在一片死灰中稍稍燃起了火星。",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300,
          Subtitle = "...After she passed, I sang the finished final act of Putini for Sig. He was hollowed by grief — but when he heard it, his eyes lit with disbelief... and for a moment, I saw hope flicker in the ashes."
        },
        [51009943] = {
          ContentTC = "我們仍有彌補維爾莉特的機會，她的快樂、她的憂傷、她的希望、她的思念全都寄存在這部作品裡。我想讓這部作品聞名世界——我可以做到，我也必須做到。",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300,
          Subtitle = "We still have a chance to honour her. Violet poured her joy, sorrow, hope, and longing into that script. I want the world to hear it — I need to make sure they do."
        },
        [51009944] = {
          ContentTC = "她和我都是為舞台而生的，即便病魔就這樣讓一位天才陨落，我也要帶著她的靈魂踏上舞台。",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300,
          Subtitle = "We were both born for the stage. Illness took her far too soon, but I'll carry her soul in every role I play — in every spotlight I step into."
        },
        [51009945] = {
          ContentTC = "所以為了讓你能夠擺脫你父親的控製，以及實現維爾莉特的遺願，西格決定配合你演一出戲。",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001,
          Subtitle = "So to help you escape your father's grip — and to fulfil Violet's last wish — Sig agreed to play his part in the act."
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不……不可能，如果真的是這樣，那她剛剛又為什麼……",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          Subtitle = "No... That can't be... If that's true, then why did she just—?",
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          ContentTC = "你帶著預設好的答案而來，吉賽爾。如果薇奧萊塔女士沒有順著你的意思說下去，她害怕她的學生羅莎琳會遭遇不測。",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001,
          Subtitle = "You came here convinced of her guilt, Giselle. And Ms Violetta couldn't risk provoking you — not with her student Rosalind's safety at stake."
        },
        [51009948] = {
          ContentTC = "什……",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          Subtitle = "What—?",
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我有個請求……我不會逃跑的，所以陪我去一個地方走走，可以嗎？",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700300,
          Subtitle = "I have a request... I won't run, I promise. Just — come with me. There's somewhere I need to go."
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentTC = "可以，但最好不要想耍什麼花樣。",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          Subtitle = "Fine. But don't think you can pull any tricks.",
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這裡已經重建了，但在我眼裡，它的每一寸磚石都還是當年的樣子。",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          Subtitle = "It's all been rebuilt... But to me, every brick, every stone still looks just as it did back then.",
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          ContentTC = "維爾莉特，我又來看你了……和我們的作品一起。",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          Subtitle = "Violet... I came back to see you. And I brought our work with me.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          ContentTC = "已經有聰明的傢伙知道了我們的故事，但不知道為什麼，我並不害怕，反而有些輕鬆。也許是因為我終於可以堂堂正正對你說……西格的事，對不起。",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300,
          Subtitle = "Someone with a sharp eye pieced together our story. Strangely, I'm not scared. I feel... relieved. Maybe because, at long last, I can say this to you properly: I'm sorry. About Sig."
        },
        [51009954] = {
          ContentTC = "（薇奧萊塔的指尖在牆壁上輕輕拂過，像是在和多年不見老友訴說著過往的經曆。或許是發覺已經到了應當離別的時候，她才會選擇在此刻回到這裡。）",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          Subtitle = "(Violetta's fingers graze the wall, as if sharing memories with an old friend she hasn't seen in years. Perhaps the time for farewell has come, and that's what brought her back here.)",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "謝謝你們縱容我的任性……",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          Subtitle = "Thank you... for indulging me.",
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          ContentTC = "所以，薇奧萊塔，你主動擔下罪行還有另一個原因——西格的死並不在你的預料之中，對嗎？",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          Subtitle = "So, Violetta... You went along with the accusations for another reason, didn't you? Because Sig's death — that wasn't part of your plan.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          ContentTC = "……法布瑞斯·魯斯福德，那是個冷酷無情的男人。那些礦工因為他幾乎食不果腹，手下的衛戍部隊也因為他的殘暴管理苦不堪言。",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          Subtitle = "Fabrice Ruthford... He was a ruthless, heartless man. The miners under him starved. His Escort officers weren't much better off.",
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "就連自己的親生女兒，那個男人也不留情面地否定她的一切，踐踏她的夢想，禁錮她的自由，強迫那個可憐的孩子按照他規劃好的無趣的人生去成長。",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          Subtitle = "He showed no mercy — not even to his own daughter. He dismissed everything she was, crushed her dreams, caged her spirit... and forced her into the lifeless future he had planned.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          ContentTC = "可就是這樣一個冷酷無情的人，卻因為親生女兒的死，越過了所有的審判流程親自將綁架犯處決——即使那會讓他被名利場上的敵人抓住把柄，最終被解職。",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300,
          Subtitle = "And yet... when his daughter \"died,\" the same heartless man threw aside all legal procedure and executed the kidnapper with his own hands — knowing full well it would cost him his career."
        },
        [51009960] = {
          ContentTC = "我設想過無數種方案，要怎麼在逃出他的掌控之後，再想辦法悄悄把書信送到法庭上去，這樣就能把西格救出來。但我唯獨沒想到……",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300,
          Subtitle = "I thought of countless ways to slip the truth to the court once I was free. I thought I could save Sig in secret. But the one thing I never imagined—"
        },
        [51009961] = {
          ContentTC = "你的父親比你想象中愛你……",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          Subtitle = "...Was that your father loved you more than you ever knew.",
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          ContentTC = "……後來，我無數次想要說出實情，但海伯利亞只是起點，她的作品還需要我傳遍整個世界——我必須遵守我的承諾，至少我必須要這麼想。",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          Subtitle = "...There were so many times I wanted to reveal the truth. But Hyperborea was only the beginning — her story needed to reach the world. I had to keep my promise... or at least, keep trying.",
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          ContentTC = "所以當你找上我的時候，我反而感到有些輕鬆……我已經有了很多學生，他們都是擁有天賦的孩子，他們可以代替我把《普蒂妮》帶上更多更廣闊的舞台。",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          Subtitle = "So when you came to me, Giselle... I felt oddly relieved. I've trained many gifted children over the years. They can carry Putini farther and wider than I ever could.",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          ContentTC = "而你，只需要在這裡承認吉賽爾的指控，就可以洗去西格身上本不屬於他的罪名。",
          DialogueId = 51009964,
          GUID = "7FB2B638",
          NextDialogue = 51009965,
          SpeakNpcId = 100001,
          Subtitle = "And all you had to do... was let Giselle believe it was true. So you could finally clear Sig's name."
        },
        [51009965] = {
          ContentTC = "……我會跟你走的，吉賽爾。但必須在你放了羅莎琳·馬格努斯之後。",
          DialogueId = 51009965,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2B662",
          NextDialogue = 51009966,
          SpeakNpcId = 700300,
          Subtitle = "...I'll go with you, Giselle. But only after you release Rosalind Magnus."
        },
        [51009966] = {
          ContentTC = "不管是為了我自己，還是為了西格和維爾莉特，她都絕對不能有事。",
          DialogueId = 51009966,
          GUID = "7FB2B68C",
          NextDialogue = 51009967,
          SpeakNpcId = 700300,
          Subtitle = "For my sake... and for Sig and Violet... she must not come to harm."
        },
        [51009967] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……她已經離開冰湖城了。",
          DialogueId = 51009967,
          GUID = "7FB2B6B6",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009968,
          SpeakNpcId = 700302,
          Subtitle = "...She's already left Icelake.",
          TalkActionId = {
            [1] = "700302:Talk01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009968] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "什麼？",
          DialogueId = 51009968,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2B6E0",
          NextDialogue = 51009969,
          SpeakNpcId = 700300,
          Subtitle = "What?",
          TalkActionId = {
            [1] = "700300:Shock_Start"
          }
        },
        [51009969] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentTC = "既然你作為聲樂老師和她的父母打過交道，就應該知道她所面臨的處境。",
          DialogueId = 51009969,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2B70A",
          NextDialogue = 51009970,
          SpeakNpcId = 700302,
          Subtitle = "You were her vocal teacher. You should know what she was up against."
        },
        [51009970] = {
          ContentTC = "雛鳥為了擺脫囚籠不惜折斷翅膀，作為師徒，你們兩個倒是如出一轍。",
          DialogueId = 51009970,
          GUID = "7FB2B734",
          NextDialogue = 51009971,
          SpeakNpcId = 700302,
          Subtitle = "A fledgling willing to break her own wings just to escape the cage... The two of you really are cut from the same cloth."
        },
        [51009971] = {
          ContentTC = "原來你從一開始就在騙我……",
          DialogueId = 51009971,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B75E",
          NextDialogue = 51009972,
          SpeakNpcId = 700300,
          Subtitle = "So all this time... you were lying to me.",
          TalkActionId = {
            [1] = "700300:Shock_End"
          }
        },
        [51009972] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我也不會想到會和你關係如此密切的人會突然跑過來雇我「綁架」她，我只是利用下這小小的巧合罷了。",
          DialogueId = 51009972,
          GUID = "7FB2B788",
          NextDialogue = 51009973,
          SpeakNpcId = 700302,
          Subtitle = "It wasn't my plan. I didn't expect someone close to you would come to hire me to \"kidnap\" her. I just... took the chance when it came.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009973] = {
          ContentTC = "怎麼樣，我的演技是不是也還不錯？是時候考慮接下來要不要轉行了。",
          DialogueId = 51009973,
          GUID = "7FB2B7B2",
          NextDialogue = 51009974,
          SpeakNpcId = 700302,
          Subtitle = "Pretty convincing performance, wasn't it? Maybe it's time I tried the stage."
        },
        [51009974] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentTC = "吉賽爾不打算做狩月人了？",
          DialogueId = 51009974,
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "7FB2B7DC",
          NextDialogue = 51009975,
          SpeakNpcId = 100001,
          Subtitle = "You don't want to be a Phoxhunter anymore?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009975] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗬，也多虧了馬格努斯家大小姐的綁架案鬧得滿城風雨，接下來很長一段時間我也得避避風頭了。",
          DialogueId = 51009975,
          GUID = "7FB2B806",
          NextDialogue = 51009976,
          SpeakNpcId = 700302,
          Subtitle = "Heh. Thanks to the big stir over Lady Magnus's kidnapping, I'll be laying low for a good while anyway."
        },
        [51009976] = {
          ContentTC = "至於薇奧萊塔……",
          DialogueId = 51009976,
          GUID = "7FB2B830",
          NextDialogue = 51009977,
          SpeakNpcId = 700302,
          Subtitle = "As for Violetta...",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009977] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentTC = "{nickname}，你來做決定吧。既然你比我先一步查清真相，就由你來選擇怎麼處置她吧。",
          DialogueId = 51009977,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2B85A",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009978,
          SpeakNpcId = 700302,
