          DialogueId = 51010907,
          GUID = "7FB350EE",
          NextDialogue = 51010908,
          Subtitle = "You served?"
        },
        [51010908] = {
          ContentTC = "是啊，我當初可是優秀士兵，一個頂三個！",
          DialogueId = 51010908,
          GUID = "7FB35118",
          NextDialogue = 51010909,
          SpeakNpcId = 700009,
          Subtitle = "That's me! One soldier, work of three. Top of my unit!"
