          DialogueId = 51010916,
          GUID = "7FB35268",
          NextDialogue = 51010917,
          SpeakNpcId = 700009,
          Subtitle = "All this time, and I still haven't said a single word to her."
        },
        [51010917] = {
          ContentTC = "貿然搭話又怕嚇到心愛的姑娘，我只好先讓空空皎皎幫我傳下話。唉，可我真是太倒黴了，每次空空皎皎去傳話的時候，都趕上她不在家。",
          DialogueId = 51010917,
          GUID = "7FB35292",
          NextOptions = {
            [1] = 51010918
          },
          SpeakNpcId = 700009,
          Subtitle = "I'm worried I'll scare her off if I just go up to her. So, I asked Lunolaze to pass on a message. But I've got the worst luck. Every time Lunolaze goes, she's not in."
        },
        [51010918] = {
          ContentTC = "你看上去不拘小節，卻很懂得尊重對方。",
          DialogueId = 51010918,
          GUID = "7FB352BC",
          ImprPlusId = 1002,
