          GUID = "7FB35364",
          NextDialogue = 51010923,
          SpeakNpcId = 700009,
          Subtitle = "Ahem."
        },
        [51010923] = {
          ContentTC = "「我對你的感情，一直升溫，比冬天的溫室，還要溫暖。」",
          DialogueId = 51010923,
          GUID = "7FB3538E",
          NextOptions = {
            [1] = 51010924
