        [51010924] = {
          ContentTC = "……",
          DialogueId = 51010924,
          GUID = "7FB353B8",
          NextDialogue = 51010925,
          Subtitle = "..."
        },
        [51010925] = {
          ContentTC = "「你什麼時候能發現，我的心像果子，就等著你來采摘。」",
          DialogueId = 51010925,
          GUID = "7FB353E2",
          NextDialogue = 51010926,
          SpeakNpcId = 700009,
