        [51010927] = {
          ContentTC = "……怎麼樣，有可以潤色的地方嗎？",
          DialogueId = 51010927,
          GUID = "7FB35436",
          NextOptions = {
            [1] = 51010928
          },
          SpeakNpcId = 700009,
          Subtitle = "...So, what do you reckon? Anything I can improve?"
