        [51010931] = {
          ContentTC = "我的愛對方還沒回應，唉，最大優惠您要等等了。",
          DialogueId = 51010931,
          GUID = "7FB354DE",
          SpeakNpcId = 700009,
          Subtitle = "She still hasn't replied... so that discount'll have to wait, I'm afraid."
        },
        [51011001] = {
          ContentTC = "請留步，很抱歉突然叫住您。",
