        },
        [51100018] = {
          ContentTC = "歲月不饒人吶，要是放在年輕那會，站起來拍拍褲子也沒事了，有膽子大的，還會趁狴犴執法的時候合照一張，夠吹好幾天了。",
          DialogueId = 51100018,
          GUID = "7FEC6CB4",
          NextDialogue = 51100019,
          SpeakNpcId = 700319,
          Subtitle = "Time shows mercy to none. In my youth, I'd have dusted myself off — bold lads even posed for pictures mid-enforcement, then bragged for days on end.",
          TalkActionId = {
            [1] = "700319:Sigh_Start"
          }
        },
        [51100019] = {
          ContentTC = "但到了我這歲數，被黑狴犴咬一口，也就是兩眼一閉，來生再做好漢，被白狴犴這一救，我這老骨頭真要癱在床上個把月嘍……",
          DialogueId = 51100019,
          GUID = "7FEC6CDE",
          NextDialogue = 51100020,
          SpeakNpcId = 700319,
          Subtitle = "These days? One bite from a Sable Bi'an and it's straight to the afterlife — clean, at least. But an Argent one saving me? Leaves me half-dead and bedridden for months!",
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100020] = {
          ContentTC = "哦對了，我可沒有說狴犴不好的意思，要是有個三長兩短，那也是太皓的安排！太皓的安排怎麼會錯呢？你說呢，年輕人？",
          DialogueId = 51100020,
          GUID = "7FEC6D08",
          NextOptions = {
            [1] = 51100021,
            [2] = 51100023,
            [3] = 51100025
          },
          SpeakNpcId = 700319,
          Subtitle = "Oh, don't mistake me — I lay no blame on our noble protectors! If anything befalls me, well... it's Taihao's will. And They make no mistakes, eh, youngster?"
        },
        [51100021] = {
          ContentTC = "回家吧老先生，回家吧，現在外面太危險了。",
          DialogueId = 51100021,
          GUID = "7FEC6D32",
          ImprPlusId = 1207,
          NextDialogue = 51100022,
          Subtitle = "Go home, sir. It's too dangerous out here."
        },
        [51100022] = {
          ContentTC = "我也想哇，可如果在這裡掉頭，我就疑似對太皓不忠了！",
          DialogueId = 51100022,
          GUID = "7FEC6D5C",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "Nothing I'd like more — yet to turn back now would be to betray Taihao Themselves!",
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100023] = {
          ContentTC = "這麼危險，還要堅持要出門，一定是有非常重要的事情吧？",
          DialogueId = 51100023,
          GUID = "7FEC6D86",
          ImprPlusId = 1209,
          NextDialogue = 51100024,
          Subtitle = "If you're braving danger like this, then it must be for something that's very important to you."
        },
        [51100024] = {
          ContentTC = "沒想到你年紀輕輕，卻是個知心人。人生中，總有幾件事是不能退縮的。",
          DialogueId = 51100024,
          GUID = "7FEC6DB0",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "Didn't expect such wisdom from one so young. Aye... there are things in life a man simply cannot back down from.",
          TalkActionId = {
            [1] = "700319:Agree"
          }
        },
        [51100025] = {
          ContentTC = "廢話那麼多，你不會是想碰瓷我吧？",
          DialogueId = 51100025,
          GUID = "7FEC6DDA",
          ImprPlusId = 1210,
          NextDialogue = 51100026,
          Subtitle = "Cut the crap. You're not faking an injury to shake me down, are you?"
        },
        [51100026] = {
          ContentTC = "胡說八道！碰瓷也得挑對象啊，老夫挑誰，也不會挑你這樣滿身繃帶還在外面四處奔波的人啊！",
          DialogueId = 51100026,
          GUID = "7FEC6E04",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "What rot! If I were out to swindle someone, it wouldn't be you — just look at you! A weary traveller swathed in bandages! What's there to gain?",
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100027] = {
          ContentTC = "總之，接下來前往塵漠石海的路只靠老夫自己是萬萬不可能了。",
          DialogueId = 51100027,
          GUID = "7FEC6E2E",
          NextDialogue = 51100028,
          SpeakNpcId = 700319,
          Subtitle = "Truth is, I can't reach the Gritblight Expanse on my own."
        },
        [51100028] = {
          ContentTC = "所以啊，老夫候在這路邊，就盼望著太皓保佑，送個古道熱腸、身手了得，還不畏懼石海晶塵的勇士，把我安安全全地送到地方去……",
          DialogueId = 51100028,
          GUID = "7FEC6E58",
          NextDialogue = 51100029,
          SpeakNpcId = 700319,
          Subtitle = "So here I wait, praying Taihao might send me a kind, able soul — one bold enough to brave the Expanse and see me through.",
          TalkActionId = {
            [1] = "700319:Confident_Start"
          }
        },
        [51100029] = {
          ContentTC = "現在看來，那個人必定是你無疑了！",
          DialogueId = 51100029,
          GUID = "7FEC6E82",
          NextDialogue = 51100030,
          SpeakNpcId = 700319,
          Subtitle = "And clearly, that soul is you!"
        },
        [51100030] = {
          ContentTC = "真是太皓保佑！太皓保佑啊！",
          DialogueId = 51100030,
          GUID = "7FEC6EAC",
          NextDialogue = 51100031,
          SpeakNpcId = 700319,
          Subtitle = "By Taihao's grace! Truly, by Their grace!"
        },
        [51100031] = {
          ContentTC = "不過你放心，老夫不是不懂事的人。",
          DialogueId = 51100031,
          GUID = "7FEC6ED6",
          NextDialogue = 51100032,
          SpeakNpcId = 700319,
          Subtitle = "Have no worry — I'll not take your kindness for naught."
        },
        [51100032] = {
          ContentTC = "請神辦事要獻貢品，請人辦事要給酬勞，把我送到地方，我一定會好好感謝你的！",
          DialogueId = 51100032,
          GUID = "7FEC6F00",
          NextOptions = {
            [1] = 51100033
          },
          RestartTag = 51100032,
          SpeakNpcId = 700319,
          Subtitle = "When you ask the gods for favour, you bring offerings. When you ask a person, you pay your dues. See me there safely, and you'll be well rewarded.",
          TalkActionId = {
            [1] = "700319:Confident_End"
          }
        },
        [51100033] = {
          ContentTC = "到底要不要付出時間和精力，護送老人前往一個危險之地呢。",
          DialogueId = 51100033,
          FailDialogue = 51100034,
          GUID = "7FEC6F2A",
          ImprCheckId = 1072,
          NextDialogue = 51100036,
          Subtitle = "Should I really spend time and energy escorting this old man through danger?"
        },
        [51100034] = {
          ContentTC = "（很遺憾，你現在有更重要的事要做，你決定稍後再來。）",
          DialogueId = 51100034,
          GUID = "7FEC6F54",
          NextDialogue = 51100035,
          Subtitle = "(You've more urgent matters to attend to. Perhaps later.)"
        },
        [51100035] = {
          ContentTC = "在太皓回應我的祈願前，我會一直等待並心懷期待……",
          DialogueId = 51100035,
          GUID = "7FEC6F7E",
          SpeakNpcId = 700319,
          Subtitle = "Until Taihao hears my prayer, I'll wait here... hope steady in my heart."
        },
        [51100036] = {
          ContentTC = "我就知道太皓一定會眷顧我的！",
          DialogueId = 51100036,
          GUID = "7FEC6FA8",
          SpeakNpcId = 700319,
          Subtitle = "I knew it — Taihao has smiled upon me!"
        },
        [51100037] = {
          ContentTC = "塵漠石海一直都是這麼陰森可怖的嗎？",
          DialogueId = 51100037,
          Duration = 4,
          GUID = "7FEC6FD2",
          NextDialogue = 51100038,
          SpeakNpcId = 100001,
          Subtitle = "Has the Gritblight Expanse always been this bleak and frightening?"
        },
        [51100038] = {
          ContentTC = "唉……一言難盡啊。",
          DialogueId = 51100038,
          Duration = 2,
          GUID = "7FEC6FFC",
          NextDialogue = 51100039,
          SpeakNpcId = 700319,
          Subtitle = "Ah... that's a tale and a half."
        },
        [51100039] = {
          ContentTC = "很久以前，石海只是一片普通的石林，但自從燭陰之災興起，那裡就被塵漠吞沒了。",
          DialogueId = 51100039,
          Duration = 8,
          GUID = "7FEC7026",
          NextDialogue = 51100040,
          SpeakNpcId = 700319,
          Subtitle = "Long ago, this was but an ordinary stone forest. Then came the Scourge of Zhuyin, and the Gritblight swallowed it whole."
        },
        [51100040] = {
          ContentTC = "所有的植物都被黑紫色的晶體所包裹，一旦被纏上，就像被裹進琥珀的昆蟲，從此不再生長，生機被定格在那一刻。",
          DialogueId = 51100040,
          Duration = 10,
          GUID = "7FEC7050",
          NextDialogue = 51100041,
          SpeakNpcId = 700319,
          Subtitle = "All the trees and grasses were wrapped in dark-violet crystal. Once caught, they were like insects in amber — frozen at that moment, life sealed away."
        },
        [51100041] = {
          ContentTC = "即使是能跑能跳的動物，在那待久了也會變成「活化石」。",
          DialogueId = 51100041,
          Duration = 6,
          GUID = "7FEC707A",
          NextDialogue = 51100042,
          SpeakNpcId = 700319,
          Subtitle = "Even the beasts, if they lingered too long, became \"living fossils\"."
        },
        [51100042] = {
          ContentTC = "甚至有傳聞說，玄色狴犴的本質，就是被塵漠侵蝕的白色狴犴……",
          DialogueId = 51100042,
          Duration = 8,
          GUID = "7FEC70A4",
          SpeakNpcId = 700319,
          Subtitle = "Some even whisper the Sable Bi'an were once Argent Bi'an — corrupted by the Gritblight's taint..."
        },
        [51100043] = {
          ContentTC = "這地方荒無人煙，少有人來，只要不在這裡逗留太久，反而不會碰到野獸與狴犴，老夫就是打著這個主意才打算從這裡抄近路。",
          DialogueId = 51100043,
          DisableMouth = 0,
          GUID = "7FEC70CE",
          IsBlack = 0,
          NextDialogue = 51100044,
          SpeakNpcId = 700319,
          Subtitle = "This place is desolate. So long as we don't linger, we're unlikely to cross paths with beasts or Bi'an. That's precisely why I chose this route.",
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100044] = {
          ContentTC = "用華胥人的話，這就是所謂的「燈下黑」吧？",
          DialogueId = 51100044,
          DisableMouth = 0,
          GUID = "7FEC70F8",
          IsBlack = 0,
          NextDialogue = 51100045,
          SpeakNpcId = 100001,
          Subtitle = "It's called \"hiding in plain sight\" in Huaxu, right?",
          bAllowClickSkipScript = false
        },
        [51100045] = {
          ContentTC = "喲，還挺懂行的！",
          DialogueId = 51100045,
          DisableMouth = 0,
          GUID = "7FEC7122",
          IsBlack = 0,
          NextDialogue = 51100046,
          SpeakNpcId = 700319,
          Subtitle = "Hah! Sharp one, aren't you!",
          bAllowClickSkipScript = false
        },
        [51100046] = {
          ContentTC = "實不相瞞，這近路我抄了不少次了，沒想到這回翻了車。",
          DialogueId = 51100046,
          DisableMouth = 0,
          GUID = "7FEC714C",
          IsBlack = 0,
          NextDialogue = 51100047,
          SpeakNpcId = 700319,
          Subtitle = "Truth be told, I've cut through here many a time. Never thought I'd take a tumble last time.",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100047] = {
          ContentTC = "那天不知怎麼的，總覺得這塵漠石海比從前都要大，我走啊走，走啊走，一直走到天黑都沒能走出去。",
          DialogueId = 51100047,
          DisableMouth = 0,
          GUID = "7FEC7176",
          IsBlack = 0,
          NextDialogue = 51100048,
          SpeakNpcId = 700319,
          Subtitle = "That day, the Expanse felt vaster than ever. I walked and walked, till nightfall — yet found no way out.",
          bAllowClickSkipScript = false
        },
        [51100048] = {
          ContentTC = "這地方平時就陰森，太陽一下山更是伸手不見五指，我老眼昏花，在這裡迷路，來來回回打轉都摸不出去！",
          DialogueId = 51100048,
          DisableMouth = 0,
          GUID = "7FEC71A0",
          IsBlack = 0,
          NextDialogue = 51100049,
          SpeakNpcId = 700319,
          Subtitle = "Even in daylight it's a gloomy place. Once the sun sets, you can scarce see your own hand. With these old eyes, I wandered in circles, lost in the dark.",
          TalkActionId = {
            [1] = "700319:Talk02_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100049] = {
          ContentTC = "最後體力不支，一個倒栽蔥撞到後腦勺……迷迷糊糊的時候，好像看到好幾隻狴犴在我面前跳來跳去……",
          DialogueId = 51100049,
          DisableMouth = 0,
          GUID = "7FEC71CA",
          IsBlack = 0,
          NextDialogue = 51100050,
          SpeakNpcId = 700319,
          Subtitle = "At last I toppled, struck the back of my skull. In the haze, I swear I saw a pack of Bi'an darting to and fro before me...",
          bAllowClickSkipScript = false
        },
        [51100050] = {
          ContentTC = "哦！我還聽到有「人」同我說話，能有執法狴犴陪伴在側的，那必然只有白龍神太皓，我這是聽到神旨啦！",
          DialogueId = 51100050,
          DisableMouth = 0,
          GUID = "7FEC71F4",
          IsBlack = 0,
          NextDialogue = 51100051,
          SpeakNpcId = 700319,
          Subtitle = "Ah, and I heard a voice! To have Argent Bi'an at their side — surely it could only have been Lord Argent Themselves! I must have heard divine words that night!",
          bAllowClickSkipScript = false
        },
        [51100051] = {
          ContentTC = "等我再醒來，已經被送出了塵漠石海，除了後腦勺上一個大包，哪兒都好好的，太皓保佑！太皓保佑啊！",
          DialogueId = 51100051,
          DisableMouth = 0,
          GUID = "7FEC721E",
          IsBlack = 0,
          NextOptions = {
            [1] = 51100054,
            [2] = 51100052
          },
          SpeakNpcId = 700319,
          Subtitle = "When I came to, I'd been carried clear of the Expanse — save a lump on my head, I was sound and whole. All by Taihao's grace!",
          bAllowClickSkipScript = false
        },
        [51100052] = {
          ContentTC = "大難不死，不管是不是太皓搭救，也算是因禍得福了。",
          DialogueId = 51100052,
          GUID = "7FEC7248",
          ImprPlusId = 1209,
          NextDialogue = 51100053,
          Subtitle = "Sounds like a narrow escape. Whether or not it was Taihao, you could call it a blessing in disguise."
        },
        [51100053] = {
          ContentTC = "大難不死和因禍得福我愛聽，中間那句多餘了吧。",
          DialogueId = 51100053,
          DisableMouth = 0,
          GUID = "7FEC7272",
          IsBlack = 0,
          NextDialogue = 51100056,
          SpeakNpcId = 700319,
          Subtitle = "\"Blessing in disguise,\" I'll take — but must you spoil it with such doubt?",
          bAllowClickSkipScript = false
        },
        [51100054] = {
          ContentTC = "在頭部遭到重擊的情況下，不排除是腦震盪造成的幻覺。",
          DialogueId = 51100054,
          GUID = "7FEC729C",
          ImprPlusId = 1208,
          NextDialogue = 51100055,
          Subtitle = "A knock to the head like that... could well have been a concussion. You might've been seeing things."
        },
        [51100055] = {
          ContentTC = "去去去！怎麼不盼著老人家好啊？",
          DialogueId = 51100055,
          DisableMouth = 0,
          GUID = "7FEC72C6",
          IsBlack = 0,
          NextDialogue = 51100056,
          SpeakNpcId = 700319,
          Subtitle = "Bah, listen to you! What kind of youngster jinxes an elder like that?",
          bAllowClickSkipScript = false
        },
        [51100056] = {
          ContentTC = "你別不信！那一定是太皓顯靈，祂還給了我一件信物，讓我下回在塵漠石海遇見麻煩，可以吹響這件寶物，祂一定會顯靈。",
          DialogueId = 51100056,
          DisableMouth = 0,
          GUID = "7FEC72F0",
          IsBlack = 0,
          NextDialogue = 51100057,
          SpeakNpcId = 700319,
          Subtitle = "I'm telling you — it was Taihao! They even left me a keepsake! Said that next time I was in peril within the Expanse, I need only blow upon it, and Taihao would appear!",
          bAllowClickSkipScript = false
        },
        [51100057] = {
          ContentTC = "喏，就是這個！",
          DialogueId = 51100057,
          DisableMouth = 0,
          GUID = "7FEC731A",
          IsBlack = 0,
          NextDialogue = 51100058,
          SpeakNpcId = 700319,
          Subtitle = "Here! Look — this is it!",
          TalkActionId = {
            [1] = "700319:Give"
          },
          bAllowClickSkipScript = false
        },
        [51100058] = {
          ContentTC = "（你仔細翻看一番，但無論你如何辨認，這都只是一片普通的樹葉而已。）",
          DialogueId = 51100058,
          DisableMouth = 0,
          GUID = "7FEC7344",
          IsBlack = 0,
          NextDialogue = 51100059,
          Subtitle = "(You turn the object over in your hand. Every detail shows it is nothing more than an ordinary leaf.)",
          bAllowClickSkipScript = false
        },
        [51100059] = {
          ContentTC = "如果我現在摘下一片葉子，打亂次序，你還能分辨出哪片是太皓的信物嗎？",
          DialogueId = 51100059,
          DisableMouth = 0,
          GUID = "7FEC736E",
          IsBlack = 0,
          NextDialogue = 51100060,
          SpeakNpcId = 100001,
          Subtitle = "If I plucked another leaf this very moment and shuffled them about, could you truly tell which one Taihao gave you?",
          bAllowClickSkipScript = false
        },
        [51100060] = {
          ContentTC = "年輕人，你本末倒置啦！或許這的確只是一片普通的樹葉，但如果這是太皓摘下的樹葉，那再普通也不普通了。",
          DialogueId = 51100060,
          DisableMouth = 0,
          GUID = "7FEC7398",
          IsBlack = 0,
          NextDialogue = 51100061,
          SpeakNpcId = 700319,
          Subtitle = "You miss the point, youngster! Aye, it may be but a leaf — yet if plucked by Taihao, it is anything but ordinary.",
          TalkActionId = {
            [1] = "700319:Explain01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100061] = {
          ContentTC = "況且，你得吹響它，白龍神君是否回應咱們，那才是檢驗神跡的唯一方法！",
          DialogueId = 51100061,
          DisableMouth = 0,
          GUID = "7FEC73C2",
          IsBlack = 0,
          NextDialogue = 51100062,
          SpeakNpcId = 700319,
          Subtitle = "Still, only by calling upon Lord Argent with it can one prove it a true divine grace.",
          bAllowClickSkipScript = false
        },
        [51100062] = {
          ContentTC = "只是老夫年紀大了，缺了幾顆牙齒，怎麼吹都漏風，只得勞煩你，幫我吹響這葉笛啦！",
          DialogueId = 51100062,
          DisableMouth = 0,
          GUID = "7FEC73EC",
          IsBlack = 0,
          NextOptions = {
            [1] = 51100063
          },
          SpeakNpcId = 700319,
          Subtitle = "Problem is, I'm short a few teeth — can't get the sound right no matter how I try. So I'll have to trouble you to blow it for me!",
          TalkActionId = {
            [1] = "700319:Explain01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100063] = {
          ContentTC = "你從沒嘗試過把樹葉當成樂器吹奏，但你決定賭一下自己天賦異稟的可能。",
          DialogueId = 51100063,
          GUID = "7FEC7416",
          ImprCheckId = 1073,
          NextDialogue = 51100065,
          Subtitle = "You've never tried playing a leaf like a flute, but maybe — just maybe — you've a knack for it. You decide to give it a try."
        },
        [51100064] = {
          ContentTC = "（你憋紅了臉，但樹葉並不配合，空氣中瀰漫著尷尬的沉默。）",
          DialogueId = 51100064,
          GUID = "7FEC7440",
          Subtitle = "(You puff until your cheeks ache, but the leaf will not sing. An awkward silence hangs in the air.)"
        },
        [51100065] = {
          ContentTC = "（樹葉發出了清脆的響聲，與某種鳥類的鳴叫十分相似。）",
          DialogueId = 51100065,
          DisableMouth = 0,
          GUID = "7FEC746A",
          IsBlack = 0,
          NextDialogue = 51100066,
          Subtitle = "(The leaf trills a clear note, uncannily like a bird's call.)",
          bAllowClickSkipScript = false
        },
        [51100066] = {
          ContentTC = "（空氣一時十分安靜，你與老者面面相覷。）",
          DialogueId = 51100066,
          DisableMouth = 0,
          GUID = "7FEC7494",
          IsBlack = 0,
          NextDialogue = 51100067,
          Subtitle = "(The air falls still. You and the old man look at each other in bewilderment.)",
          bAllowClickSkipScript = false
        },
        [51100067] = {
          ContentTC = "誰呀，打擾我的好夢？",
          DialogueId = 51100067,
          DisableMouth = 0,
          GUID = "7FEC74BE",
          IsBlack = 0,
          NextDialogue = 51100068,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Who is it? I was sleeping!",
          bAllowClickSkipScript = false
        },
        [51100068] = {
          ContentTC = "（一道聲音不知從哪裡傳來，好像是剛睡醒一般，不知是不是錯覺，你總覺得這聲音十分耳熟。）",
          DialogueId = 51100068,
          DisableMouth = 0,
          GUID = "7FEC74E8",
          IsBlack = 0,
          NextDialogue = 51100069,
          Subtitle = "(A voice drifts from nowhere, groggy as though roused from slumber. Something about it feels oddly familiar.)",
          bAllowClickSkipScript = false
        },
        [51100069] = {
          ContentTC = "？",
          DialogueId = 51100069,
          DisableMouth = 0,
          GUID = "7FEC7512",
          IsBlack = 0,
          NextDialogue = 51100070,
          SpeakNpcId = 100001,
          Subtitle = "...?",
          bAllowClickSkipScript = false
        },
        [51100070] = {
          ContentTC = "就是這個聲音！年輕人，我就說我是被白龍神君眷顧的人吧！",
          DialogueId = 51100070,
          DisableMouth = 0,
          GUID = "7FEC753C",
          IsBlack = 0,
          NextDialogue = 51100071,
          SpeakNpcId = 700319,
          Subtitle = "That voice! You hear it too, don't you? It is Lord Argent — I told you I was favoured!",
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100071] = {
          ContentTC = "老先生，我覺得你還是……",
          DialogueId = 51100071,
          DisableMouth = 0,
          GUID = "7FEC7566",
          IsBlack = 0,
          NextDialogue = 51100072,
          SpeakNpcId = 100001,
          Subtitle = "Sir, I think you might wan—",
          bAllowClickSkipScript = false
        },
        [51100072] = {
          ContentTC = "噓，噤聲！咳咳……太皓在上，小老兒冒昧，攪擾了您安眠，在此給您賠不是了！",
          DialogueId = 51100072,
          DisableMouth = 0,
          GUID = "7FEC7590",
          IsBlack = 0,
          NextDialogue = 51100073,
          SpeakNpcId = 700319,
          Subtitle = "Shh! Quiet! Ahem... O Taihao above, this old soul begs forgiveness for disturbing Your rest!",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100073] = {
          ContentTC = "太皓？你稱我為太皓？",
          DialogueId = 51100073,
          DisableMouth = 0,
          GUID = "7FEC75BA",
          IsBlack = 0,
          NextDialogue = 51100074,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Taihao? You call me Taihao?",
          bAllowClickSkipScript = false
        },
        [51100074] = {
          ContentTC = "正是哇！還是小老兒唐突，直呼神名，冒犯您了？",
          DialogueId = 51100074,
          DisableMouth = 0,
          GUID = "7FEC75E4",
          IsBlack = 0,
          NextDialogue = 51100075,
          SpeakNpcId = 700319,
          Subtitle = "Ah! Forgive my presumption, Lord Argent!",
          TalkActionId = {
            [1] = "700319:Talk02_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100075] = {
          ContentTC = "哈哈，你說得倒沒錯，我……吾的意思就是如此，區區凡人，怎可直呼吾名？",
          DialogueId = 51100075,
          DisableMouth = 0,
          GUID = "7FEC760E",
          IsBlack = 0,
          NextDialogue = 51100076,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hah! Right... yes, precisely what I meant! A mere mortal should know better than to bandy my name about so freely!",
          bAllowClickSkipScript = false
        },
        [51100076] = {
          ContentTC = "哎喲白龍神君說得沒錯，是小老兒冒犯了！",
          DialogueId = 51100076,
          DisableMouth = 0,
          GUID = "7FEC7638",
          IsBlack = 0,
          NextDialogue = 51100077,
          SpeakNpcId = 700319,
          Subtitle = "Ah, You are right, my Lord — it was my transgression entirely!",
          TalkActionId = {
            [1] = "700319:Talk02_End"
          },
          bAllowClickSkipScript = false
        },
        [51100077] = {
          ContentTC = "無妨，吾氣量寬宏，就原諒你這一回！那人間的凡夫俗子，今日來這鳥……偏僻之地攪擾本座清靜，到底所為何事啊？",
          DialogueId = 51100077,
          DisableMouth = 0,
          GUID = "7FEC7662",
          IsBlack = 0,
          NextDialogue = 51100078,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "No matter — I am magnanimous enough to forgive you this once! Now then, mortal... what brings you to this rotten—ahem... this remote place, disturbing my peace?",
          bAllowClickSkipScript = false
        },
        [51100078] = {
          ContentTC = "嘿嘿嘿，小老兒倒沒有什麼了不得的大事，只是上次承蒙您關照，小老兒才有命從這鬼地方獲救，內心著實感激不已！",
          DialogueId = 51100078,
          DisableMouth = 0,
          GUID = "7FEC768C",
          IsBlack = 0,
          NextDialogue = 51100079,
          SpeakNpcId = 700319,
          Subtitle = "Nothing grand, my Lord — last time, You saved me from this wretched place, and I have been grateful ever since!",
          bAllowClickSkipScript = false
        },
        [51100079] = {
          ContentTC = "實不相瞞，小老兒歸鄉後日夜敬香禱告，祭祀不停，只盼著再聆聽一次白龍神君的教誨，就心滿意足嘍……",
          DialogueId = 51100079,
          DisableMouth = 0,
          GUID = "7FEC76B6",
          IsBlack = 0,
          NextDialogue = 51100080,
          SpeakNpcId = 700319,
          Subtitle = "Since returning home, I have prayed day and night, offered incense and gifts — all in hope of hearing Your wisdom once more...",
          bAllowClickSkipScript = false
        },
        [51100080] = {
          ContentTC = "只是不管小老兒怎麼祝禱，白龍神君都沒有回應，小老兒惶恐不已，生怕是哪裡做錯了，惹得您不喜，這才不避艱險，來討您一個示下……",
          DialogueId = 51100080,
          DisableMouth = 0,
          GUID = "7FEC76E0",
          IsBlack = 0,
          NextDialogue = 51100081,
          SpeakNpcId = 700319,
          Subtitle = "But no matter how I prayed, You gave no answer. I feared I had angered You — so I braved these perils to seek Your guidance in person...",
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100081] = {
          ContentTC = "哦！我……吾想起來了！是你！上回你磕到腦袋，抓著吾的袖口滿嘴胡言亂語，險些吐吾身上，都不記得了？",
          DialogueId = 51100081,
          DisableMouth = 0,
          GUID = "7FEC770A",
          IsBlack = 0,
          NextDialogue = 51100082,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! Yes, yes, I recall now! You're the one who cracked your head! You clung to my sleeve, babbling nonsense — near spewed all over me! Don't you remember?",
          bAllowClickSkipScript = false
        },
        [51100082] = {
          ContentTC = "所以你就是撞到頭產生幻——",
          DialogueId = 51100082,
          DisableMouth = 0,
          GUID = "7FEC7734",
          IsBlack = 0,
          NextDialogue = 51100083,
          SpeakNpcId = 100001,
          Subtitle = "So it really was a concuss—",
          bAllowClickSkipScript = false
        },
        [51100083] = {
          ContentTC = "哎呀！哎呀呀！竟對白龍神君如此大不敬！小老兒真是罪該萬死！",
          DialogueId = 51100083,
          DisableMouth = 0,
          GUID = "7FEC775E",
          IsBlack = 0,
          NextDialogue = 51100084,
          SpeakNpcId = 700319,
          Subtitle = "How outrageous of me! Such disrespect to Lord Argent! I deserve death for this transgression!",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100084] = {
          ContentTC = "怪不得從那以後您都不愛搭理我，那著實是我咎由自取呀！",
          DialogueId = 51100084,
          DisableMouth = 0,
          GUID = "7FEC7788",
          IsBlack = 0,
          NextDialogue = 51100085,
          SpeakNpcId = 700319,
          Subtitle = "No wonder You've shunned me since — it was entirely my fault!",
          bAllowClickSkipScript = false
        },
        [51100085] = {
          ContentTC = "幸好小老兒來這一趟，否則冒犯了您都不曉得！難為您還肯回應我的葉笛聲，如此重諾，真不愧是慈愛公平寬容和藹善心悲憫的白龍神君！",
          DialogueId = 51100085,
          DisableMouth = 0,
          GUID = "7FEC77B2",
          IsBlack = 0,
          NextDialogue = 51100086,
          SpeakNpcId = 700319,
          Subtitle = "Thank heavens I came today — else I'd never have known my offence against You! And yet You still answered my call... so merciful, so benevolent, so boundless in grace!",
          bAllowClickSkipScript = false
        },
        [51100086] = {
          ContentTC = "？",
          DialogueId = 51100086,
          DisableMouth = 0,
          GUID = "7FEC77DC",
          IsBlack = 0,
          NextDialogue = 51100087,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...?",
          bAllowClickSkipScript = false
        },
        [51100087] = {
          ContentTC = "哈哈哈哈哈哈哈哈哈哈哈哈哈……好！說得好！有眼光！",
          DialogueId = 51100087,
          DisableMouth = 0,
          GUID = "7FEC7806",
          IsBlack = 0,
          NextDialogue = 51100088,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hahahahaha! Well said! You've quite the eye for greatness!",
          bAllowClickSkipScript = false
        },
        [51100088] = {
          ContentTC = "噗……",
          DialogueId = 51100088,
          DisableMouth = 0,
          GUID = "7FEC7830",
          IsBlack = 0,
          NextDialogue = 51100089,
          SpeakNpcId = 100001,
          Subtitle = "Pffft...",
          bAllowClickSkipScript = false
        },
        [51100089] = {
          ContentTC = "笑什麼笑！這可是在白龍神君面前！",
          DialogueId = 51100089,
          DisableMouth = 0,
          GUID = "7FEC785A",
          IsBlack = 0,
          NextDialogue = 51100090,
          SpeakNpcId = 700319,
          Subtitle = "What are you laughing at? Mind your manners — you stand before Lord Argent!",
          bAllowClickSkipScript = false
        },
        [51100090] = {
          ContentTC = "人之性情稟賦，不可強行扭轉，既然愛笑，就隨他笑吧。",
          DialogueId = 51100090,
          DisableMouth = 0,
          GUID = "7FEC7884",
          IsBlack = 0,
          NextDialogue = 51100091,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ahem... Human nature cannot be bent by force. If {性别:he|she} wishes to laugh, let {性别:him|her}.",
          bAllowClickSkipScript = false
        },
        [51100091] = {
          ContentTC = "白龍神君真是仁慈！可凡是身在華胥者，皆要受到大風九章的約束，人的性情稟賦，依稀可能大概，還是得受此管教，不可隨心而行吧……",
          DialogueId = 51100091,
          DisableMouth = 0,
          GUID = "7FEC78AE",
          IsBlack = 0,
          NextDialogue = 51100092,
          SpeakNpcId = 700319,
          Subtitle = "How merciful You are, my Lord! Still, all in Huaxu are bound by the Nine Chapters. Even nature must walk their path, must it not?",
          bAllowClickSkipScript = false
        },
        [51100092] = {
          ContentTC = "哦？那大風九章第九條，不也說要「垂聆天憲，恭肅為敬」？你先是冒犯於我，我念你神志不清，不予追究。",
          DialogueId = 51100092,
          DisableMouth = 0,
          GUID = "7FEC78D8",
          IsBlack = 0,
          NextDialogue = 51100093,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh? And does not the Ninth Admonition say: \"Attend to Heaven's edict with a reverent mind and a solemn heart\"? You offended me once — I forgave you, knowing your mind was muddled.",
          bAllowClickSkipScript = false
        },
        [51100093] = {
          ContentTC = "現在你神思清明，卻又頂撞於我，該當何罪！",
          DialogueId = 51100093,
          DisableMouth = 0,
          GUID = "7FEC7902",
          IsBlack = 0,
          NextDialogue = 51100094,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "But now, with your wits clear, you dare disrespect me again — what punishment do you deserve?",
          bAllowClickSkipScript = false
        },
        [51100094] = {
          ContentTC = "這、這……",
          DialogueId = 51100094,
          DisableMouth = 0,
          GUID = "7FEC792C",
          IsBlack = 0,
          SpeakNpcId = 700319,
          Subtitle = "I... I...",
          bAllowClickSkipScript = false
        },
        [51100095] = {
          ContentTC = "白龍神君發怒了！我要被狴犴執法了！救命啊！我只是嘴硬，其實也不想丟了老命啊！",
          DialogueId = 51100095,
          GUID = "7FEC7956",
          NextDialogue = 51100096,
          SpeakNpcId = 700319,
          Subtitle = "Lord Argent is angry! The Argent Bi'an have come to pass judgement! Save me! I was only exaggerating when I said I deserved death!"
        },
        [51100096] = {
          ContentTC = "冷靜點，仔細觀察，這些狴犴的目標另有其人。",
          DialogueId = 51100096,
          GUID = "7FEC7980",
          NextDialogue = 51100097,
          SpeakNpcId = 100001,
          Subtitle = "Calm yourself. Look closely — they're not here for you."
        },
        [51100097] = {
          ContentTC = "{nickname}，又見面了！",
          DialogueId = 51100097,
          GUID = "7FEC79AA",
          NextDialogue = 51100098,
          SpeakNpcId = 700318,
          Subtitle = ", we meet again!"
        },
        [51100098] = {
          ContentTC = "這狴犴倒是會趕巧，只是同樣的對手我已打到厭倦，勞煩你一回，幫我將它們驅趕乾淨吧！",
          DialogueId = 51100098,
          GUID = "7FEC79D4",
          SpeakNpcId = 700318,
          Subtitle = "These Bi'an sure know when to show themselves — but I've grown bored of crossing blades with the same old foes. Mind lending a hand? Drive them off for me."
        },
        [51100104] = {
          ContentTC = "究竟怎麼了！白龍神君呢！白龍神君難道不保佑我了嗎！",
          DialogueId = 51100104,
          GUID = "7FEC7AD0",
          NextDialogue = 51100105,
          SpeakNpcId = 700319,
          Subtitle = "What just happened!? Where is Lord Argent? Am I forsaken!?"
        },
        [51100105] = {
          ContentTC = "這半路殺出的沒頭沒腦沒由來的傢伙又是誰？",
          DialogueId = 51100105,
          GUID = "7FEC7AFA",
          NextDialogue = 51100106,
          SpeakNpcId = 700319,
          Subtitle = "And who is this stranger, springing from nowhere?"
        },
        [51100106] = {
          ContentTC = "這一切的一切的……到底怎麼回事！",
          DialogueId = 51100106,
          GUID = "7FEC7B24",
          NextOptions = {
            [1] = 51100110,
            [2] = 51100107,
            [3] = 51100108,
            [4] = 51100109
          },
          SpeakNpcId = 700319,
          Subtitle = "All of this... what in Taihao's name is going on!?"
        },
        [51100107] = {
          ContentTC = "你的一切症狀都符合腦震盪的反應，你從來沒碰到過真正的白龍神君。",
          DialogueId = 51100107,
          GUID = "7FEC7B4E",
          ImprPlusId = 1208,
          NextDialogue = 51100111,
          Subtitle = "All your symptoms point to a concussion. You never met the real Lord Argent at all."
        },
        [51100108] = {
          ContentTC = "當時你並非由白龍神君拯救，但你被這位過路人救下，撿回一條命，也是好事。",
          DialogueId = 51100108,
          GUID = "7FEC7B78",
          ImprPlusId = 1209,
          NextDialogue = 51100111,
          Subtitle = "It wasn't Lord Argent who saved you — it was this man who happened by. Either way, you lived. That's blessing enough, isn't it?"
        },
        [51100109] = {
          ContentTC = "我也不是你和白龍神君祈禱來的，但報酬我一樣要收。",
          DialogueId = 51100109,
          GUID = "7FEC7BA2",
          ImprPlusId = 1206,
          NextDialogue = 51100111,
          Subtitle = "I wasn't sent by Lord Argent to protect you either — but I'm still charging you for my trouble."
        },
        [51100110] = {
          ContentTC = "你猜我之前在笑什麼？",
          DialogueId = 51100110,
          GUID = "7FEC7BCC",
          ImprPlusId = 1210,
          NextDialogue = 51100111,
          Subtitle = "Wanna guess what I was laughing at earlier?"
        },
        [51100111] = {
          ContentTC = "我是誰？飄零人刻舟是也！當然，你要是還願意稱我為太皓，也不是不能照單全收！",
          DialogueId = 51100111,
          GUID = "7FEC7BF6",
          NextDialogue = 51100112,
          SpeakNpcId = 700318,
          Subtitle = "Who am I? Kezhou — a Drifter, nothing more. But if you'd prefer to keep calling me Taihao... I won't stop you!"
        },
        [51100112] = {
          ContentTC = "或者，你也可以把剛才的誇人話對著你救命恩人再說一遍？慈悲公允寬和……還有什麼來著？",
          DialogueId = 51100112,
          GUID = "7FEC7C20",
          NextDialogue = 51100113,
          SpeakNpcId = 700318,
          Subtitle = "Or better yet, you could say those pretty words to me again. What was it? Merciful, benevolent, and... what was the last one again?"
        },
        [51100113] = {
          ContentTC = "誒，老頭兒，你還真的挺擅長誇人的！當初救下你時，你連自己是誰都說不出來，但那好聽的話還是一籮筐一籮筐的，不比清醒時說的差！",
          DialogueId = 51100113,
          GUID = "7FEC7C4A",
          NextDialogue = 51100114,
          SpeakNpcId = 700318,
          Subtitle = "You've quite the knack for flattery, old man. That day I pulled you back from death's door, you couldn't even remember your own name — yet still your tongue rolled out praises as smooth as today."
        },
        [51100114] = {
          ContentTC = "那、那我昏迷前看到的那些狴犴是……",
          DialogueId = 51100114,
          GUID = "7FEC7C74",
          NextDialogue = 51100115,
          SpeakNpcId = 700319,
          Subtitle = "Th—Then... those Bi'an I saw before blacking out... they were...?"
        },
        [51100115] = {
          ContentTC = "看來你還不知道，常被狴犴「陪伴」的除了白龍神和應天尉，還有可能是被窮追不捨的飄零人。",
          DialogueId = 51100115,
          GUID = "7FEC7C9E",
          NextDialogue = 51100116,
          SpeakNpcId = 700318,
          Subtitle = "Oh, you didn't know? Lord Argent and the Magistrates of Yingtian aren't the only ones with Bi'an at their side. Now and then, a Drifter finds them trailing along too."
        },
        [51100116] = {
          ContentTC = "你你你你你你——",
          DialogueId = 51100116,
          GUID = "7FEC7CC8",
          NextDialogue = 51100117,
          SpeakNpcId = 700319,
          Subtitle = "Y—Y—Y—You—!"
        },
        [51100117] = {
          ContentTC = "怪不得怪不得！白龍神君才不會說什麼人之天賦性情，只有你們這些法外狂徒，才滿嘴的歪理邪說！",
          DialogueId = 51100117,
          GUID = "7FEC7CF2",
          NextDialogue = 51100118,
          SpeakNpcId = 700319,
          Subtitle = "No wonder! Lord Argent would never speak of \"human nature\" — only you outlaws spout such twisted drivel!"
        },
        [51100118] = {
          ContentTC = "可恨我一時被蒙蔽了雙眼，竟沒識出你的本來面目！",
          DialogueId = 51100118,
          GUID = "7FEC7D1C",
          NextDialogue = 51100119,
          SpeakNpcId = 700319,
          Subtitle = "Curse my blindness — I failed to see you for what you are!"
        },
        [51100119] = {
          ContentTC = "喂！這麼說就過分了吧！這老頭兒，翻臉如翻書一般，你自己上下打量打量，能全須全尾地站在這，你還得謝我呢！",
          DialogueId = 51100119,
          GUID = "7FEC7D46",
          NextDialogue = 51100120,
          SpeakNpcId = 700318,
          Subtitle = "Hey! That's no way to talk to the man who just saved your life. What happened to all those grateful words? You're still breathing because of me, mind you!"
        },
        [51100120] = {
          ContentTC = "懶得和你掰扯，{nickname}，你怎麼說？",
          DialogueId = 51100120,
          GUID = "7FEC7D70",
          NextOptions = {
            [1] = 51100125,
            [2] = 51100121
          },
          SpeakNpcId = 700318,
          Subtitle = "Unbelievable, this guy. What do you think, ?"
        },
        [51100121] = {
          ContentTC = "還是應該謝謝刻舟。",
          DialogueId = 51100121,
          GUID = "7FEC7D9A",
          ImprPlusId = 1207,
          NextDialogue = 51100122,
          Subtitle = "I think you owe Kezhou a thank you."
        },
        [51100122] = {
          ContentTC = "刻舟戲弄你確實不對，但不管怎麼說，他是你的救命恩人，算上那枚葉子，他甚至準備多救你幾次，不能和解嗎？",
          DialogueId = 51100122,
          GUID = "7FEC7DC4",
          NextDialogue = 51100123,
          SpeakNpcId = 100001,
          Subtitle = "He may've teased you pretending to be the Loong God, but whichever way you look at it, he saved your life. Even the leaf he gave you — it meant he was prepared to help again if you were in danger. Can't you give him that much credit?"
        },
        [51100123] = {
          ContentTC = "我自小被白龍神君和大風九章庇護長大，若沒有狴犴奉天執法，還沒遇見你，我就已經命喪玄色狴犴之口了。",
          DialogueId = 51100123,
          GUID = "7FEC7DEE",
          NextDialogue = 51100124,
          SpeakNpcId = 700319,
          Subtitle = "I was raised under the protection of Lord Argent and the Nine Chapters. Without the Argent Bi'an enforcing the law, I'd have perished to a Sable Bi'an's fangs long before meeting you."
        },
        [51100124] = {
          ContentTC = "這飄零人或許救我一次，兩次，三次，但和白龍神君相比，實在微不足道。我尊奉白龍神君，自然要和這群法外狂徒劃清關係。",
          DialogueId = 51100124,
          GUID = "7FEC7E18",
          NextDialogue = 51100129,
          SpeakNpcId = 700319,
          Subtitle = "This Drifter may have saved me once, twice, even thrice — yet compared with Lord Argent, it is nothing. I revere Them, and thus must keep my distance from the lawless."
        },
        [51100125] = {
          ContentTC = "這未嘗不是神的旨意。",
          DialogueId = 51100125,
          GUID = "7FEC7E42",
          ImprPlusId = 1208,
          NextDialogue = 51100126,
          Subtitle = "Maybe this was Taihao's plan all along."
        },
        [51100126] = {
          ContentTC = "老先生認為生死都是太皓的安排，那麼被飄零人救下自然也是白龍神君的旨意，從這個角度想，你理應坦然接受救命恩人是法外狂徒。",
          DialogueId = 51100126,
          GUID = "7FEC7E6C",
          NextDialogue = 51100127,
          SpeakNpcId = 100001,
          Subtitle = "If you truly believe life and death lie in the Loong God's hands, then being saved by a Drifter must also be part of Their will. Isn't that worth making peace with?"
        },
        [51100127] = {
          ContentTC = "嗯？乍一聽把我都繞進去了，但飄零人，絕無可能被什麼條條框框束縛。我救他，只是舉手之勞，我戲弄他，也是因我看不慣他盲信。",
          DialogueId = 51100127,
          GUID = "7FEC7E96",
          NextDialogue = 51100128,
          SpeakNpcId = 700318,
          Subtitle = "Hah! Nearly had me there — but no. A Drifter's bound by no rules and no orders. I saved him simply because I chose to — and teased him because I can't stomach blind faith."
        },
        [51100128] = {
          ContentTC = "我便弄不明白，這些人做什麼要把自己邁出去的一步歸功於上天的推動？ 人非草木，自己會動。你瞧他篤信白龍神，不也找了你護衛左右？",
          DialogueId = 51100128,
          GUID = "7FEC7EC0",
          NextDialogue = 51100129,
          SpeakNpcId = 700318,
          Subtitle = "That's what I don't get — why credit Heaven for what you choose to do? People aren't stones. We move because we will it. Look at this old man: claims to trust in Lord Argent's protection — yet still hires you to keep him safe."
        },
        [51100129] = {
          ContentTC = "放誕無禮！",
          DialogueId = 51100129,
          GUID = "7FEC7EEA",
          NextDialogue = 51100130,
          SpeakNpcId = 700319,
          Subtitle = "Insolence!"
        },
        [51100130] = {
          ContentTC = "朽木腦袋！",
          DialogueId = 51100130,
          GUID = "7FEC7F14",
          NextDialogue = 51100131,
          SpeakNpcId = 700318,
          Subtitle = "Blockhead!"
        },
        [51100131] = {
          ContentTC = "……我盡力了，看來是不會出現握手言和的畫面了。",
          DialogueId = 51100131,
          GUID = "7FEC7F3E",
          NextDialogue = 51100132,
          SpeakNpcId = 100001,
          Subtitle = "...Well, I tried. Looks like these two won't be shaking hands anytime soon."
        },
        [51100132] = {
          ContentTC = "切！我才不願將大好光陰浪費在這裡，走吧，{nickname}，今日你我一定要好好切磋一場！",
          DialogueId = 51100132,
          GUID = "7FEC7F68",
          NextDialogue = 51100133,
          SpeakNpcId = 700318,
          Subtitle = "Tch. No point wasting daylight bickering with someone that stubborn. Come on,  — let's have ourselves a proper spar instead!"
        },
        [51100133] = {
          ContentTC = "等等！",
          DialogueId = 51100133,
          GUID = "7FEC7F92",
          NextDialogue = 51100134,
          SpeakNpcId = 700319,
          Subtitle = "Wait!"
        },
        [51100134] = {
          ContentTC = "（老者將兩份酬勞分別交給了你與刻舟。）",
          DialogueId = 51100134,
          GUID = "7FEC7FBC",
          NextDialogue = 51100135,
          Subtitle = "(The old man produces two coin pouches — one pressed into your hand, the other into Kezhou's.)"
        },
        [51100135] = {
          ContentTC = "大風九章第二條，「夫人根基，定文為信」，我答應要給少年人酬勞，自然不會言而無信。",
          DialogueId = 51100135,
          GUID = "7FEC7FE6",
          NextDialogue = 51100136,
          SpeakNpcId = 700319,
          Subtitle = "The Second Admonition of the Nine Chapters teaches: A man is measured by the strength of his word. I promised this youngster a reward, and so I must keep my word."
        },
        [51100136] = {
          ContentTC = "大風九章第六條，「以我及人，制宜為義」，我雖厭憎你，但確實承你恩惠，這酬勞，就當做你我兩清，從此井水不犯河水。",
          DialogueId = 51100136,
          GUID = "7FEC8010",
          NextDialogue = 51100137,
          SpeakNpcId = 700319,
          Subtitle = "The Sixth Admonition teaches: \"Let compassion and righteousness guide your mind and every deed.\" Though I despise you, Drifter, I cannot deny the fact you saved me. Take this — and let our accounts be settled. From here on, we walk separate roads."
        },
        [51100137] = {
          ContentTC = "（說完這句話，老者便不願再假手他人，一個人遲緩卻堅定地踏上了回程的道路，你不便跟上，默默目送他遠去。）",
          DialogueId = 51100137,
          GUID = "7FEC803A",
          NextDialogue = 51100138,
          Subtitle = "(Without another word, the old man turns away. Step by step, he makes for home. You do not follow — only watch as his figure fades into the distance.)"
        },
        [51100138] = {
          ContentTC = "說起來，最近許久不見你人影，為何出現在這裡？",
          DialogueId = 51100138,
          GUID = "7FEC8064",
          NextDialogue = 51100139,
          SpeakNpcId = 100001,
          Subtitle = "Come to think of it, I haven't seen you in a while. What brings you here?"
        },
        [51100139] = {
          ContentTC = "燭陰之災日益泛濫，這地方本來有懸衡派的香塔鎮著，但最近越來越不頂用了，這老頭兒會在裡面迷路也並非偶然。",
          DialogueId = 51100139,
          GUID = "7FEC808E",
          NextDialogue = 51100140,
          SpeakNpcId = 700318,
          Subtitle = "The Scourge of Zhuyin grows worse by the day. There used to be a Xuanheng incense tower here to keep the ley lines in check. But lately, it's failing. No wonder that old man got lost."
        },
        [51100140] = {
          ContentTC = "被塵漠侵蝕的地域愈發擴大，這才讓他走到天黑也走不出來。",
          DialogueId = 51100140,
          GUID = "7FEC80B8",
          NextDialogue = 51100141,
          SpeakNpcId = 700318,
          Subtitle = "The Gritblight's spreading faster. That's why he wandered till nightfall without finding the way out."
        },
        [51100141] = {
          ContentTC = "我想著師兄說不定會奉命前來調查，才總是守在這裡，沒想到碰到這老頭迷失其中，這人嘴皮子利索，倒也有趣。可惜……",
          DialogueId = 51100141,
          GUID = "7FEC80E2",
          NextDialogue = 51100142,
          SpeakNpcId = 700318,
          Subtitle = "I thought my Shixiong might be sent to investigate, so I lingered here. Never thought I'd run into a sharp-tongued old fossil. Amusing sort... pity, really."
        },
        [51100142] = {
          ContentTC = "（刻舟將錢袋子拋了拋，最終丟進你的懷中。）",
          DialogueId = 51100142,
          GUID = "7FEC810C",
          NextDialogue = 51100143,
          Subtitle = "(Kezhou tosses the coin pouch lightly, weighs it in hand — then flings it into your arms.)"
        },
        [51100143] = {
          ContentTC = "這東西能換來好幾瓶絕頂佳釀，我本應高興……但我救人本不圖報酬，不如給你。",
          DialogueId = 51100143,
          GUID = "7FEC8136",
          NextDialogue = 51100144,
          SpeakNpcId = 700318,
          Subtitle = "That'd buy a good few bottles of fine wine. Should've been a lovely little gain — but I never save lives for coin. You take it."
        },
        [51100144] = {
          ContentTC = "說來好笑，高高在上的龍神救人，換來的就是頂禮膜拜，感恩戴德，而飄零人救人，卻總是冷嘲熱諷，潦草打發。",
          DialogueId = 51100144,
          GUID = "7FEC8160",
          NextOptions = {
            [1] = 51100146,
            [2] = 51100145
          },
          SpeakNpcId = 700318,
          Subtitle = "Funny, isn't it? When the lofty Loong God saves a man, He's praised and worshipped. But when a Drifter does the same... we get scorn and a cold shoulder."
        },
        [51100145] = {
          ContentTC = "但你們救下的生命都是等價的。",
          DialogueId = 51100145,
          GUID = "7FEC818A",
          ImprPlusId = 1207,
          NextDialogue = 51100147,
          Subtitle = "But it still counts — doesn't matter what others think."
        },
        [51100146] = {
          ContentTC = "你覺得問心無愧，那就是值得。",
          DialogueId = 51100146,
          GUID = "7FEC81B4",
          ImprPlusId = 1209,
          NextDialogue = 51100147,
          Subtitle = "It's still worth it, for conscience's sake."
        },
        [51100147] = {
          ContentTC = "哈！我就知道你是同道中人，不消你說，我自然明白！",
          DialogueId = 51100147,
          GUID = "7FEC81DE",
          NextDialogue = 51100148,
          SpeakNpcId = 700318,
          Subtitle = "Ha! I knew you were a kindred spirit. Say no more — I get it!"
        },
        [51100148] = {
          ContentTC = "不管了，少思慮那些三天以後才會發生的事情，趁著良辰美景，不如對劍高歌！我想想，此情此景，再沒比這一句更合適的了——",
          DialogueId = 51100148,
          GUID = "7FEC8208",
          NextDialogue = 51100149,
          SpeakNpcId = 700318,
          Subtitle = "Bah — dwelling on it won't change a thing. Come, let's cross swords and sing it out! Hah... can't think of a verse more fitting than this—"
        },
        [51100149] = {
          ContentTC = "夢亦妄生顛倒想，",
          DialogueId = 51100149,
          GUID = "7FEC8232",
          NextDialogue = 51100150,
          SpeakNpcId = 700318,
          Subtitle = "Dreams are but illusions, twisting thought awry;"
        },
        [51100150] = {
          ContentTC = "何如明月自由人！",
          DialogueId = 51100150,
          GUID = "7FEC825C",
          SpeakNpcId = 700318,
          Subtitle = "Better by far, to live free beneath the moonlit sky!"
        },
        [51101001] = {
          ContentTC = "這次借的也不是一筆小數目啊……",
          DialogueId = 51101001,
          GUID = "7FED0DFA",
          SpeakNpcId = 700320,
          Subtitle = "Not a small sum you're borrowing again..."
        },
        [51101002] = {
          ContentTC = "那邊兩個人好像在吵什麼東西，小僕從小僕從，我們快去阻止他們吧！",
          DialogueId = 51101002,
          GUID = "7FED0E24",
          SpeakNpcId = 900003,
          Subtitle = "Hey — those two look like they're squabbling over something! Little Minion, quick, let's break it up!"
        },
        [51101003] = {
          ContentTC = "來，這裡是您的借貸契書，確認無誤就在這裡簽字畫押吧。",
          DialogueId = 51101003,
          GUID = "7FED0E4E",
          NextDialogue = 51101004,
          SpeakNpcId = 700320,
          Subtitle = "Here's the loan agreement. If everything looks right, sign and make your marks here."
        },
        [51101004] = {
          ContentTC = "這次借的也不是一筆小數目啊。怎麼，又想上哪裡去看看了？",
          DialogueId = 51101004,
          GUID = "7FED0E78",
          NextDialogue = 51101005,
          SpeakNpcId = 700320,
          Subtitle = "Not a small sum you're taking again — off on another trip, are you?"
        },
        [51101005] = {
          ContentTC = "哈哈，還是您懂我！這次啊，我想再去維德弗尼爾山那兒走一趟。山裡的孩子許久沒見我，怕是早就在盼著我了。",
          DialogueId = 51101005,
          GUID = "7FED0EA2",
          NextDialogue = 51101006,
          SpeakNpcId = 700321,
          Subtitle = "Hah, you know me too well! Heading back to the Vidofnir Mountains — the little ones up there haven't seen me in a while. Bet they're already waiting for me."
        },
        [51101006] = {
          ContentTC = "您還是一點沒變啊。按照規定，這樣一筆數額的借款必須留下貴重抵押物，您能接受嗎？",
          DialogueId = 51101006,
          GUID = "7FED0ECC",
          NextDialogue = 51101007,
          SpeakNpcId = 700320,
          Subtitle = "Still the same as ever, I see. Right — for a sum this size, EverSpring requires a collateral of value. That all right with you?"
        },
        [51101007] = {
          ContentTC = "曉得，就和以前一樣嘛。",
          DialogueId = 51101007,
          GUID = "7FED0EF6",
          NextDialogue = 51101008,
          SpeakNpcId = 700321,
          Subtitle = "Naturally — same as always."
        },
        [51101008] = {
          ContentTC = "什麼嘛，原來只是借錢啊，沒意思沒意思……",
          DialogueId = 51101008,
          GUID = "7FED0F20",
          NextDialogue = 51101009,
          SpeakNpcId = 900003,
          Subtitle = "Meh, just another guy borrowing money. Boooring..."
        },
        [51101009] = {
          ContentTC = "（白掃興地嘆了口氣，剛拉著你準備轉身離開，就聽到遠處那名男子遠遠叫住了你們。他一跑一喘地趕到你的面前。）",
          DialogueId = 51101009,
          GUID = "7FED0F4A",
          NextDialogue = 51101010,
          Subtitle = "(Snow sighs in disappointment and tugs you away — but a voice from behind makes you pause. Gasping, a man rushes to catch up.)"
        },
        [51101010] = {
          ContentTC = "呼……呼……二位留步。",
          DialogueId = 51101010,
          GUID = "7FED0F74",
          NextDialogue = 51101011,
          SpeakNpcId = 700321,
          Subtitle = "Huff... huff... Wait, please!"
        },
        [51101011] = {
          ContentTC = "自我介紹一下，我叫趙謙，是名織星客。",
          DialogueId = 51101011,
          GUID = "7FED0F9E",
          NextDialogue = 51101012,
          SpeakNpcId = 700321,
          Subtitle = "Allow me to introduce myself — Zhao Qian, a Starweaver by trade."
        },
        [51101012] = {
          ContentTC = "聽聞二位少俠是百年春請來的武力高強的貴客，那個……若是二位得閒，可否請二位保護我走一遭，取一趟貨？我會給報酬的！",
          DialogueId = 51101012,
          GUID = "7FED0FC8",
          NextOptions = {
            [1] = 51101013,
            [2] = 51101015
          },
          SpeakNpcId = 700321,
          Subtitle = "I hear you're the honoured guests EverSpring invited for your strength. If you can spare the time, may I trouble you to escort me in collecting some goods? I will see you properly rewarded."
        },
        [51101013] = {
          ContentTC = "那我就幫幫你吧。",
          DialogueId = 51101013,
          GUID = "7FED0FF2",
          ImprPlusId = 1207,
          NextDialogue = 51101014,
          Subtitle = "Sure, I'll help you."
        },
        [51101014] = {
          ContentTC = "太好了。放心，報酬絕對虧待不了你們。",
          DialogueId = 51101014,
          GUID = "7FED101C",
          NextDialogue = 51101017,
          SpeakNpcId = 700321,
          Subtitle = "Wonderful — I promise the pay won't disappoint."
        },
        [51101015] = {
          ContentTC = "你都要借錢了，還請得起護衛嗎？",
          DialogueId = 51101015,
          GUID = "7FED1046",
          ImprPlusId = 1206,
          NextDialogue = 51101016,
          Subtitle = "You're already in debt. Can you really afford to hire bodyguards?"
        }
      }
    end
  },
  {
    MinKey = 51101016,
    MaxKey = 51103041,
    Loader = function()
      return {
        [51101016] = {
          ContentTC = "古話說得好，千金散盡還復來嘛。錢這東西啊，只是個身外之物。要是為了省錢誤了生意，那才是撿了芝麻丟了西瓜。",
          DialogueId = 51101016,
          GUID = "7FED1070",
          NextDialogue = 51101017,
          SpeakNpcId = 700321,
          Subtitle = "As the saying goes — spend freely, and fortune circles back. Money's nothing but worldly fluff. Save a pouch of coins but lose a deal? That is poor business sense."
        },
        [51101017] = {
          ContentTC = "燭陰之災的遺禍還遍布煙津渡，我人受點傷是小，貨物丟了可就麻煩大了。",
          DialogueId = 51101017,
          GUID = "7FED109A",
          NextDialogue = 51101018,
          SpeakNpcId = 700321,
          Subtitle = "Mistwharf is still reeling from the aftermath of Zhuyin's Scourge. I can take a few bruises myself, but if the goods go missing, that's real trouble."
        },
        [51101018] = {
          ContentTC = "我聽錦鯉皎皎說，織星客都是一群跑到大陸各個地方做生意的傢伙，那你也一定去過很多地方吧？",
          DialogueId = 51101018,
          GUID = "7FED10C4",
          NextDialogue = 51101019,
          SpeakNpcId = 900003,
          Subtitle = "I heard from Lunocarp that Starweavers travel all over the continent. So you've been to loads of places, right?"
        },
        [51101019] = {
          ContentTC = "算不上多吧，也就去過各個國家的主要城市而已，阿特拉西亞大陸上，還有很多邊邊角角的村鎮我沒去過呢。",
          DialogueId = 51101019,
          GUID = "7FED10EE",
          NextDialogue = 51101020,
          SpeakNpcId = 700321,
          Subtitle = "Perhaps not as many as you think — only the major cities. Still plenty of small towns across Atlasia I've yet to visit."
        },
        [51101020] = {
          ContentTC = "那事情結束後，除了工錢，你還要跟本魔王大人講講你在其他國家碰到的好玩的事哦！",
          DialogueId = 51101020,
          GUID = "7FED1118",
          NextDialogue = 51101021,
          SpeakNpcId = 900003,
          Subtitle = "Then the great Demon King wants a bonus! When we're done, you'd better tell us all the fun things you've seen abroad!"
        },
        [51101021] = {
          ContentTC = "好嘞，沒問題。那我們現在出發吧，先去農家處取我之前定好的一批蜜餞果子。",
          DialogueId = 51101021,
          GUID = "7FED1142",
          SpeakNpcId = 700321,
          Subtitle = "Haha, no problem. Let's get moving — first stop, the fruit farmer. I've got a batch of candied fruit waiting."
        },
        [51101022] = {
          ContentTC = "是玄色狴犴，有勞二位少俠了。",
          DialogueId = 51101022,
          Duration = 4,
          GUID = "7FED116C",
          NextDialogue = 51101023,
          SpeakNpcId = 700321,
          Subtitle = "Ah, Sable Bi'an... I'll count on you two to drive them off."
        },
        [51101023] = {
          ContentTC = "哼哼，你就在本魔王大人身後躲好吧——小僕從，揍扁它們！",
          DialogueId = 51101023,
          Duration = 7,
          GUID = "7FED1196",
          SpeakNpcId = 200002,
          Subtitle = "Hm-hmm~! Stay tucked behind the great Demon King — Little Minion, squash them flat!"
        },
        [51101024] = {
          ContentTC = "身手果真了得！我們接著趕路吧，就在前方不遠了。",
          DialogueId = 51101024,
          Duration = 7,
          GUID = "7FED11C0",
          SpeakNpcId = 700321,
          Subtitle = "That was splendid! Come, we're nearly there."
        },
        [51101025] = {
          ContentTC = "二位在此稍事休息，我去找農家付個錢。",
          DialogueId = 51101025,
          GUID = "7FED11EA",
          NextDialogue = 51101026,
          SpeakNpcId = 700321,
          Subtitle = "Rest a bit. I need to settle the bill with the farmer."
        },
        [51101026] = {
          ContentTC = "一段時間後……",
          DialogueId = 51101026,
          GUID = "7FED1214",
          NextDialogue = 51101027,
          Subtitle = "A short while later..."
        },
        [51101027] = {
          ContentTC = "取好了，這蜜餞果子可是我們華胥的特產，來嘗一口唄。",
          DialogueId = 51101027,
          GUID = "7FED123E",
          NextDialogue = 51101028,
          SpeakNpcId = 700321,
          Subtitle = "Got them. These candied fruits are a Huaxu specialty — here, have a taste."
        },
        [51101028] = {
          ContentTC = "咳，好甜……",
          DialogueId = 51101028,
          GUID = "7FED1268",
          NextDialogue = 51101029,
          SpeakNpcId = 100001,
          Subtitle = "*cough*... It's... really sweet..."
        },
        [51101029] = {
          ContentTC = "慢點嚼，剛進口是會有點齁，吃到後面就習慣了。",
          DialogueId = 51101029,
          GUID = "7FED1292",
          NextDialogue = 51101030,
          SpeakNpcId = 700321,
          Subtitle = "Slowly — the first bite's always a bit much, but you'll grow used to it."
        },
        [51101030] = {
          ContentTC = "唔，感覺是個挑人的零食呀，那個維什麼什麼山的人會買嗎？",
          DialogueId = 51101030,
          GUID = "7FED12BC",
          NextDialogue = 51101031,
          SpeakNpcId = 900003,
          Subtitle = "Hmm... Feels like one of those snacks only a niche crowd would like. Are the folks in, uh... Vid-something Mountains really going to buy these?"
        },
        [51101031] = {
          ContentTC = "嘿嘿，維德弗尼爾山脈那邊既沒多少水果，也沒什麼調味，更重要的是蜜餞耐儲存不怕變質，在那兒很受歡迎呢。",
          DialogueId = 51101031,
          GUID = "7FED12E6",
          NextDialogue = 51101032,
          SpeakNpcId = 700321,
          Subtitle = "Haha — up in the Vidofnir Mountains, there's barely any fruit, nor spices. Candied fruit's a favourite treat there, and what's more, it keeps well."
        },
        [51101032] = {
          ContentTC = "好了，吃完我們就去下一個地方吧。",
          DialogueId = 51101032,
          GUID = "7FED1310",
          SpeakNpcId = 700321,
          Subtitle = "Right, we'll head to the next stop when you're done."
        },
        [51101033] = {
          ContentTC = "一段時間後……",
          DialogueId = 51101033,
          GUID = "7FED133A",
          NextDialogue = 51101034,
          Subtitle = "A short while later..."
        },
        [51101034] = {
          ContentTC = "誒？你怎麼抱了一堆石頭回來呀。",
          DialogueId = 51101034,
          GUID = "7FED1364",
          NextDialogue = 51101035,
          SpeakNpcId = 900003,
          Subtitle = "Eh? Why'd you lug back a whole pile of rocks?"
        },
        [51101035] = {
          ContentTC = "這可不是普通的石頭，而是在煙津渡南邊的湖裡撈出來打磨後的溫涼玉。",
          DialogueId = 51101035,
          GUID = "7FED138E",
          NextDialogue = 51101036,
          SpeakNpcId = 700321,
          Subtitle = "These aren't just rocks — they're Temperjade, polished from pebbles dredged out of the lake south of Mistwharf."
        },
        [51101036] = {
          ContentTC = "我這次準備從西北邊的冰原借道去維德弗尼爾山，那冰原又亂又冷，每天都有人凍死在那。",
          DialogueId = 51101036,
          GUID = "7FED13B8",
          NextDialogue = 51101037,
          SpeakNpcId = 700321,
          Subtitle = "I'm heading through the northwest icefields to reach Vidofnir. That place is brutal — biting cold and dangerous. People freeze to death all the time."
        },
        [51101037] = {
          ContentTC = "而溫涼玉燒過之後就會發熱一段時間，正好放在懷裡暖和暖和身子。我在那賣過很多次了，搶手得很。",
          DialogueId = 51101037,
          GUID = "7FED13E2",
          NextDialogue = 51101038,
          SpeakNpcId = 700321,
          Subtitle = "Once heated, Temperjade retains warmth for a long while. Keep one close, and it'll ward off the cold. They're always in demand up there — I've traded them many times before."
        },
        [51101038] = {
          ContentTC = "這次買了不少，希望能幫到更多人吧……",
          DialogueId = 51101038,
          GUID = "7FED140C",
          NextDialogue = 51101039,
          SpeakNpcId = 700321,
          Subtitle = "Bringing a large batch this time — hoping they'll help more people survive the cold."
        },
        [51101039] = {
          ContentTC = "好了好了，不說這些讓人難過的事了，趕緊把東西搬到碼頭上吧。",
          DialogueId = 51101039,
          GUID = "7FED1436",
          SpeakNpcId = 700321,
          Subtitle = "...But enough of that — it only weighs on the heart. Come, let's bring the goods to the docks."
        },
        [51101040] = {
          ContentTC = "辛苦啦，這一路上多虧了你們，才走得這麼順利。",
          DialogueId = 51101040,
          GUID = "7FED1460",
          NextDialogue = 51101041,
          SpeakNpcId = 700321,
          Subtitle = "Many thanks — we've made it this far without a hitch, all thanks to you."
        },
        [51101041] = {
          ContentTC = "來，我看看兜里的錢還剩多少……算了不數了，全給你們當報酬吧，畢竟拉著你們跟我跑東跑西的，天都黑了。",
          DialogueId = 51101041,
          GUID = "7FED148A",
          NextDialogue = 51101042,
          SpeakNpcId = 700321,
          Subtitle = "Let's see... how much I've still got... eh, no point counting. Just take the lot. After running around with me all day, you've earned it."
        },
        [51101042] = {
          ContentTC = "這麼大方，那我就不客氣啦！",
          DialogueId = 51101042,
          GUID = "7FED14B4",
          NextDialogue = 51101043,
          SpeakNpcId = 900003,
          Subtitle = "Ooh, that's generous of you! Thanks!"
        },
        [51101043] = {
          ContentTC = "100，200，300……這也沒多少嘛。",
          DialogueId = 51101043,
          GUID = "7FED14DE",
          NextDialogue = 51101044,
          SpeakNpcId = 900003,
          Subtitle = "One hundred, two hundred, three... huh, that's all?"
        },
        [51101044] = {
          ContentTC = "啊哈哈……抱歉抱歉。我身上也只剩下一點路費了。",
          DialogueId = 51101044,
          GUID = "7FED1508",
          NextDialogue = 51101045,
          SpeakNpcId = 700321,
          Subtitle = "Ahaha... forgive me. I've barely enough left to see me down the road."
        },
        [51101045] = {
          ContentTC = "感覺你做織星客也有段時間了，為什麼還要借錢做生意呢？",
          DialogueId = 51101045,
          GUID = "7FED1532",
          NextDialogue = 51101046,
          SpeakNpcId = 100001,
          Subtitle = "You've been a Starweaver for quite some time, haven't you? How come you still need to borrow money for your runs?"
        },
        [51101046] = {
          ContentTC = "對哦，白見過的那些借錢的傢伙都是一個個嘴上哭著窮，實際上藏了不少好寶貝！快，讓白看看你壓箱底的小金庫！",
          DialogueId = 51101046,
          GUID = "7FED155C",
          NextDialogue = 51101047,
          SpeakNpcId = 900003,
          Subtitle = "Right! I heard people who borrow money are all pretending to be poor — they're secretly sitting on treasure! Come on, show us your secret stash!"
        },
        [51101047] = {
          ContentTC = "好機靈的皎皎，那就給你們看看吧，要是有喜歡的，儘管拿去。",
          DialogueId = 51101047,
          GUID = "7FED1586",
          NextDialogue = 51101048,
          SpeakNpcId = 700321,
          Subtitle = "Sharp little Luno, aren't you? All right — there you go. Take anything that catches your eye."
        },
        [51101048] = {
          ContentTC = "這都是些什麼哇，一塊碎掉的小珍珠……還有一朵乾巴巴的花？想拿這些垃圾敷衍魔王大人，拿回去拿回去！",
          DialogueId = 51101048,
          GUID = "7FED15B0",
          NextOptions = {
            [1] = 51101049,
            [2] = 51101051
          },
          SpeakNpcId = 900003,
          Subtitle = "What's this? A cracked tiny pearl... and a dried-up flower? Are you trying to fob off the Demon King with rubbish!? Keep them!"
        },
        [51101049] = {
          ContentTC = "我想，這些東西的價值，在於它們背後的故事，對嗎？",
          DialogueId = 51101049,
          GUID = "7FED15DA",
          ImprPlusId = 1209,
          NextDialogue = 51101050,
          Subtitle = "I'm guessing their worth lies in the stories behind them, right?"
        },
        [51101050] = {
          ContentTC = "好眼力！",
          DialogueId = 51101050,
          GUID = "7FED1604",
          NextDialogue = 51101053,
          SpeakNpcId = 700321,
          Subtitle = "Very perceptive!"
        },
        [51101051] = {
          ContentTC = "看來不打你一頓，你是不會承認自己其實是億萬富翁了。",
          DialogueId = 51101051,
          GUID = "7FED162E",
          ImprPlusId = 1210,
          NextDialogue = 51101052,
          Subtitle = "Guess I'll have to rough you up 'til you admit you're secretly loaded."
        },
        [51101052] = {
          ContentTC = "少俠收手，收手。聽我說完。",
          DialogueId = 51101052,
          GUID = "7FED1658",
          NextDialogue = 51101053,
          SpeakNpcId = 700321,
          Subtitle = "Easy now, friend — hear me out."
        },
        [51101053] = {
          ContentTC = "這些是我賺到的最貴重的寶貝了，二位且聽我慢慢道來。",
          DialogueId = 51101053,
          GUID = "7FED1682",
          NextDialogue = 51101054,
          SpeakNpcId = 700321,
          Subtitle = "These are the most precious things I've ever gained. Let me tell you their stories."
        },
        [51101054] = {
          ContentTC = "這珍珠，是我在盧卡一位畫家手裡買到的。我本想在那裡買點顏料帶回華胥賣，卻在畫具店前碰到了一位徘徊的年輕人。",
          DialogueId = 51101054,
          GUID = "7FED16AC",
          NextDialogue = 51101055,
          SpeakNpcId = 700321,
          Subtitle = "This pearl came from a painter I once met in Luca. I was there to buy pigments to resell in Huaxu, when I noticed a young man loitering outside an art shop."
        },
        [51101055] = {
          ContentTC = "一把沒剩幾根毛的畫筆插在他亂糟糟的頭髮里，全身上下沒有一處不沾著五顏六色的顏料，盧卡潮濕的空氣讓我離得老遠都能聞到他身上散發出來的異味。",
          DialogueId = 51101055,
          GUID = "7FED16D6",
          NextDialogue = 51101056,
          SpeakNpcId = 700321,
          Subtitle = "His clothes were stained with paint, worn-out brushes sticking out of messy hair — looked like he hadn't washed in days. Thanks to Luca's damp air, you could smell him from metres away."
        },
        [51101056] = {
          ContentTC = "嘔呃……",
          DialogueId = 51101056,
          GUID = "7FED1700",
          NextDialogue = 51101057,
          SpeakNpcId = 900003,
          Subtitle = "Eww..."
        },
        [51101057] = {
          ContentTC = "哈哈哈，我當時也差不多這個反應。可能藝術家多少都會有些另類，我這種粗人是理解不了，但我能理解他眼神中的渴望。",
          DialogueId = 51101057,
          GUID = "7FED172A",
          NextDialogue = 51101058,
          SpeakNpcId = 700321,
          Subtitle = "Haha, that was my first reaction too. Artists can be a strange bunch — I don't really get art, but I recognised that look in his eyes."
        },
        [51101058] = {
          ContentTC = "他就那樣在店門口從左邊走到右邊，抬頭看看店內的顏料，又從右邊走到左邊，看看店內的畫布。",
          DialogueId = 51101058,
          GUID = "7FED1754",
          NextDialogue = 51101059,
          SpeakNpcId = 700321,
          Subtitle = "He kept pacing back and forth in front of the shop, peeking at pigments and canvases."
        },
        [51101059] = {
          ContentTC = "最後他摸了摸口袋，嘆了口氣就轉身要走，我這時候很快啊，立馬過去攔住了他。",
          DialogueId = 51101059,
          GUID = "7FED177E",
          NextDialogue = 51101060,
          SpeakNpcId = 700321,
          Subtitle = "Eventually, he checked his pockets, sighed, and turned to leave. I acted fast — stopped him on the spot."
        },
        [51101060] = {
          ContentTC = "聊了一會我發現，我果然聽不懂他講的光澤、飽和、構圖之類的專業術語。但我能聽懂他是一位上不起學、買不起畫具卻想追求藝術的苦孩子。",
          DialogueId = 51101060,
          GUID = "7FED17A8",
          NextDialogue = 51101061,
          SpeakNpcId = 700321,
          Subtitle = "We spoke for a while. Most of what he said — the jargon about colours and composition — I couldn't follow. But I could tell he was chasing a dream he couldn't afford."
        },
        [51101061] = {
          ContentTC = "那不是我第一次去盧卡，也不是我第一次碰到窮畫家，但卻是我第一次看到一個閃閃發光的人。",
          DialogueId = 51101061,
          GUID = "7FED17D2",
          NextDialogue = 51101062,
          SpeakNpcId = 700321,
          Subtitle = "It wasn't my first time in Luca, or the first time I'd met a penniless artist. But it was the first time I saw someone shine like that."
        },
        [51101062] = {
          ContentTC = "閃閃發光？盧卡的顏料這麼厲害，都能反光了！",
          DialogueId = 51101062,
          GUID = "7FED17FC",
          NextDialogue = 51101063,
          SpeakNpcId = 900003,
          Subtitle = "What? Luca's paints actually glow?"
        },
        [51101063] = {
          ContentTC = "不，我說的是眼神中的那種感覺。我喜歡他那充滿朝氣與希望的樣子，就像華胥的年輕人一樣。",
          DialogueId = 51101063,
          GUID = "7FED1826",
          NextDialogue = 51101064,
          SpeakNpcId = 700321,
          Subtitle = "No — I mean the light in his eyes. Reminded me of the kids back in Huaxu. Bright-eyed, full of fire."
        },
        [51101064] = {
          ContentTC = "也許是我羨慕那個樣子，也許是我太久沒回華胥了，結果就是我把那趟賺到的錢基本都給了他，他過意不去，就把他媽媽的珍珠手鍊給了我。",
          DialogueId = 51101064,
          GUID = "7FED1850",
          NextDialogue = 51101065,
          SpeakNpcId = 700321,
          Subtitle = "Maybe I envied that spark... or maybe I'd just been away from home too long. Either way, I gave him most of what I made on that trip. He felt deeply indebted, so he gave me his mother's pearl bracelet."
        },
        [51101065] = {
          ContentTC = "後來我去盧卡做生意都會順路看看他，每次看到他獲得新的成就，都能讓我感到十分欣慰。",
          DialogueId = 51101065,
          GUID = "7FED187A",
          NextDialogue = 51101066,
          SpeakNpcId = 700321,
          Subtitle = "After that, every time I passed through Luca, I'd check in on him. He's come a long way — I'm proud of him."
        },
        [51101066] = {
          ContentTC = "唯一可惜的是他送我的手鍊，被一場暴風雨卷進了海里，就剩下這一顆了。",
          DialogueId = 51101066,
          GUID = "7FED18A4",
          NextDialogue = 51101067,
          SpeakNpcId = 700321,
          Subtitle = "Sadly, I lost the bracelet at sea in a storm. This one pearl's all that's left."
        },
        [51101067] = {
          ContentTC = "（趙謙訕訕的笑著，隨後又用手小心翼翼地捧起那朵泛黃枯死的花。）",
          DialogueId = 51101067,
          GUID = "7FED18CE",
          NextDialogue = 51101068,
          Subtitle = "(Zhao Qian gives a wry smile, then gently cups the withered flower in his hands.)"
        },
        [51101068] = {
          ContentTC = "這朵花的故事說起來倒也簡單，那時我在赫墨的沙漠中碰到了一名脫水的小姑娘。",
          DialogueId = 51101068,
          GUID = "7FED18F8",
          NextDialogue = 51101069,
          SpeakNpcId = 700321,
          Subtitle = "This one's simpler — I met a girl half-dead from thirst in Khemet's desert."
        },
        [51101069] = {
          ContentTC = "那地方偏得很，來不及送到附近的大型聚落，所以求醫問路，安置小姑娘都比較麻煩。費了好一番功夫才救了回來。",
          DialogueId = 51101069,
          GUID = "7FED1922",
          NextDialogue = 51101070,
          SpeakNpcId = 700321,
          Subtitle = "We were too far from any proper town to call for help. It took quite an effort, but in the end I managed to save her."
        },
        [51101070] = {
          ContentTC = "後來我從小姑娘那了解到，她癱倒的那片沙漠經常有人脫水而死，但為了生存，人們還是一個接一個地走入茫茫黃沙。",
          DialogueId = 51101070,
          GUID = "7FED194C",
          NextDialogue = 51101071,
          SpeakNpcId = 700321,
          Subtitle = "She told me she wasn't the first to fall in that desert. Many had perished of thirst before her. Yet, desperate to find a way of living, they still walked into those merciless sands one after another."
        },
        [51101071] = {
          ContentTC = "我救不了他們所有人，但花點錢僱人多找點水源還是能做到的。這朵花，便是小姑娘從那些水源蔓延出的綠洲中採下的。",
          DialogueId = 51101071,
          GUID = "7FED1976",
          NextDialogue = 51101072,
          SpeakNpcId = 700321,
          Subtitle = "I couldn't save them all. But I could hire others to search for water. This flower — the girl took it from an oasis born of those efforts."
        },
        [51101072] = {
          ContentTC = "這麼一想，我這大半輩子雖然跑過不少地方，但賺的錢基本都在路上花掉了啊，哈哈哈哈哈。",
          DialogueId = 51101072,
          GUID = "7FED19A0",
          NextDialogue = 51101073,
          SpeakNpcId = 700321,
          Subtitle = "Funny thing — I've travelled far and wide, but most of what I've earned got spent along the way, heh heh..."
        },
        [51101073] = {
          ContentTC = "不過錢嘛，沒了還能再賺，為了理想辛苦點也是值得的。",
          DialogueId = 51101073,
          GUID = "7FED19CA",
          NextDialogue = 51101074,
          SpeakNpcId = 700321,
          Subtitle = "Money comes and goes — but if it's for that dream, it's worth it."
        },
        [51101074] = {
          ContentTC = "理想？",
          DialogueId = 51101074,
          GUID = "7FED19F4",
          NextDialogue = 51101075,
          SpeakNpcId = 900003,
          Subtitle = "What dream?"
        },
        [51101075] = {
          ContentTC = "嗯，織星客最早的理想，也是最天真的理想。",
          DialogueId = 51101075,
          GUID = "7FED1A1E",
          NextDialogue = 51101076,
          SpeakNpcId = 700321,
          Subtitle = "The very first dream of the Starweavers — a pretty naive one, really."
        },
        [51101076] = {
          ContentTC = "你們看我指的這是什麼？",
          DialogueId = 51101076,
          GUID = "7FED1A48",
          NextDialogue = 51101077,
          SpeakNpcId = 700321,
          Subtitle = "Do you know what this is?"
        },
        [51101077] = {
          ContentTC = "我知道我知道，是星星！",
          DialogueId = 51101077,
          GUID = "7FED1A72",
          NextDialogue = 51101078,
          SpeakNpcId = 900003,
          Subtitle = "I know, I know — stars!"
        },
        [51101078] = {
          ContentTC = "我把它連起來呢？",
          DialogueId = 51101078,
          GUID = "7FED1A9C",
          NextDialogue = 51101079,
          SpeakNpcId = 700321,
          Subtitle = "Right. But if you connect them — what do they become?"
        },
        [51101079] = {
          ContentTC = "唔嗯……",
          DialogueId = 51101079,
          GUID = "7FED1AC6",
          NextDialogue = 51101080,
          SpeakNpcId = 900003,
          Subtitle = "Umm..."
        },
        [51101080] = {
          ContentTC = "連起來是天象儀座，我們常常用它來確認方向。而這裡連起來便是織星者座，也是我們織星客名稱的由來。",
          DialogueId = 51101080,
          GUID = "7FED1AF0",
          NextDialogue = 51101081,
          SpeakNpcId = 700321,
          Subtitle = "They form the Astrolabe Constellation, the one we use to guide our way. And over there — that's the Starweaver Constellation, from which our trade takes its name."
        },
        [51101081] = {
          ContentTC = "阿特拉西亞大陸上的各個國家，城鎮，就像這天上的星星一樣，有的璀璨耀眼，有的黯淡無光。但它們都在那裡。",
          DialogueId = 51101081,
          GUID = "7FED1B1A",
          NextDialogue = 51101082,
          SpeakNpcId = 700321,
          Subtitle = "The nations and towns of Atlasia are like those stars — some bright, some dim, yet each with its place."
        },
        [51101082] = {
          ContentTC = "也許看上去距離很遠，彼此孤立，但只要連接起來，便會組成全新的「星座」。而我們織星客的足跡便是將這些「星星」連起來的線。",
          DialogueId = 51101082,
          GUID = "7FED1B44",
          NextDialogue = 51101083,
          SpeakNpcId = 700321,
          Subtitle = "On their own they may seem far apart. But draw the lines between them, and they form a constellation. Our journeys are those lines."
        },
        [51101083] = {
          ContentTC = "遙遠的過去，這片土地第一次響起人類的啼哭，他們一無所有，只有頭頂這片星空。",
          DialogueId = 51101083,
          GUID = "7FED1B6E",
          NextDialogue = 51101084,
          SpeakNpcId = 700321,
          Subtitle = "Long ago, when humankind first cried out on this land, they had nothing but the sky above."
        },
        [51101084] = {
          ContentTC = "未來的某天，也許人類又會回到一無所有的狀態，但那些被織星客連起來的「線」並不會因此斷掉。",
          DialogueId = 51101084,
          GUID = "7FED1B98",
          NextDialogue = 51101085,
          SpeakNpcId = 700321,
          Subtitle = "And one day, maybe we'll find ourselves with nothing again... but the lines we've woven will still remain."
        },
        [51101085] = {
          ContentTC = "商品、文明與知識，將沿著這些線送到大陸的各個角落，送到那些需要它們的人手中。我們大地上的「群星」，也會變得越來越耀眼。",
          DialogueId = 51101085,
          GUID = "7FED1BC2",
          NextDialogue = 51101086,
          SpeakNpcId = 700321,
          Subtitle = "Goods, stories, knowledge — all carried along those paths, reaching every corner of the continent, to those who need them. And just like that, the \"stars\" on the ground will grow ever brighter."
        },
        [51101086] = {
          ContentTC = "（趙謙說著說著笑了起來——恰巧碰上岸邊傳來的，悠長的鳴笛聲。你想起他說過的「閃閃發光的人」，而此時此刻眼前的這位織星客，眼底似乎也有什麼在閃閃發光。）",
          DialogueId = 51101086,
          GUID = "7FED1BEC",
          NextDialogue = 51101087,
          Subtitle = "(As he speaks, he smiles — just as a ship's whistle echoes in the distance. A moment ago he called a young painter someone who \"shines.\" But now, you see that same light shining in his eyes.)"
        },
        [51101087] = {
          ContentTC = "船到了，我也該走了。希望未來的某天，我們能在這片大陸的某個角落重逢。",
          DialogueId = 51101087,
          GUID = "7FED1C16",
          NextDialogue = 51101088,
          SpeakNpcId = 700321,
          Subtitle = "My ship has come. Time I set out. May our paths cross again, somewhere upon this continent."
        },
        [51101088] = {
          ContentTC = "後會有期。",
          DialogueId = 51101088,
          GUID = "7FED1C40",
          NextOptions = {
            [1] = 51101089
          },
          SpeakNpcId = 700321,
          Subtitle = "Until we meet again."
        },
        [51101089] = {
          ContentTC = "後會有期。",
          DialogueId = 51101089,
          GUID = "7FED1C6A",
          Subtitle = "Until we meet again."
        },
        [51101090] = {
          ContentTC = "哦呦，這碼頭上貨的地方怎麼被這些小傢伙占住了。咱們一塊趕走它們吧。",
          DialogueId = 51101090,
          GUID = "7FED1C94",
          NextDialogue = 51101091,
          SpeakNpcId = 700321,
          Subtitle = "Uuh... where'd these little critters come from? They've taken over the loading spot. Let's drive them off together."
        },
        [51101091] = {
          ContentTC = "去去，呼略，去去，我們要往這放東西呢。",
          DialogueId = 51101091,
          GUID = "7FED1CBE",
          SpeakNpcId = 700321,
          Subtitle = "Shoo, shoo — out of the way. We need to unload our goods here."
        },
        [51102001] = {
          Camera = "645.011719,215.524414,95.914062,0.000001,-6.599854,-162.398209,35.0,651.573547,false,Manual,2.8",
          ContentTC = "二位英雄請留步。",
          DialogueId = 51102001,
          GUID = "7FEDB20A",
          NextDialogue = 51102002,
          SpeakNpcId = 700322,
          Subtitle = "A moment, if you please, noble heroes.",
          TalkActionId = {
            [1] = "700322:Explain01_Start"
          }
        },
        [51102002] = {
          Camera = "-156.484375,-67.136719,113.200684,0.000001,-9.999662,14.205973,35.0,299.776581,false,Manual,2.8",
          ContentTC = "什麼事？",
          DialogueId = 51102002,
          GUID = "7FEDB234",
          LookAt = {
            [1] = "700322:n(100001)"
          },
          NextDialogue = 51102003,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51102003] = {
          Camera = "-27.642578,-571.077148,131.51416,0.000049,-9.599796,81.000999,35.0,631.937927,false,Manual,2.8",
          ContentTC = "說來唐突，閣下可曾聽聞玄天口諭？",
          DialogueId = 51102003,
          GUID = "7FEDB25E",
          NextDialogue = 51102004,
          SpeakNpcId = 700322,
          Subtitle = "Pardon the suddenness... but have you ever heard tell of the Oracle of Xuantian?"
        },
        [51102004] = {
          Camera = "-7.996094,1.37793,50.615234,0.000117,-8.999327,37.795189,35.0,145.872787,false,Manual,2.8",
          ContentTC = "玄天口諭？那是什麼東西？",
          DialogueId = 51102004,
          GUID = "7FEDB288",
          LookAt = {
            [1] = "700322:n(700363)"
          },
          NextDialogue = 51102005,
          SpeakNpcId = 700363,
          Subtitle = "The Oracle of Xuantian? What's that supposed to be?",
          TalkActionId = {
            [1] = "700363:Shy03_Start"
          }
        },
        [51102005] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "即是於思緒中迴蕩之聲，其聲若……若來自九霄天外，如同嚴父，又似慈母……",
          DialogueId = 51102005,
          GUID = "7FEDB2B2",
          NextDialogue = 51102006,
          SpeakNpcId = 700322,
          Subtitle = "A voice that speaks not to the ears, but within the mind... as though cast down from realms beyond the stars — stern as a father, gentle as a mother..."
        },
        [51102006] = {
          Camera = "-156.484375,-67.136719,113.200684,0.000001,-9.999662,14.205973,35.0,299.776581,false,Manual,2.8",
          ContentTC = "（那個聲音，難道他說的是……）",
          DialogueId = 51102006,
          GUID = "7FEDB2DC",
          NextDialogue = 51102007,
          SpeakNpcId = 100001,
          Subtitle = "(That voice... Could he mean...?)"
        },
        [51102007] = {
          Camera = "-156.484375,-67.136719,113.200684,0.000001,-9.999662,14.205973,35.0,299.776581,false,Manual,2.8",
          ContentTC = "你也聽到過那個聲音？",
          DialogueId = 51102007,
          GUID = "7FEDB306",
          LookAt = {
            [1] = "700322:n(100001)"
          },
          NextDialogue = 51102008,
          SpeakNpcId = 100001,
          Subtitle = "You've heard it too?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51102008] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "什麼叫「也」？敢情還真聽過？",
          DialogueId = 51102008,
          GUID = "7FEDB330",
          NextDialogue = 51102009,
          SpeakNpcId = 700322,
          Subtitle = "\"Too\"? You mean... you've really heard it!?"
        },
        [51102009] = {
          Camera = "-239.767578,-371.516602,182.77832,0.000116,-17.599176,51.401344,35.0,565.41864,false,Manual,2.8",
          ContentTC = "嗯？明明是你先問的，你怎麼好像一幅很驚訝的樣子？",
          DialogueId = 51102009,
          GUID = "7FEDB35A",
          LookAt = {
            [1] = "700322:n(700363)"
          },
          NextDialogue = 51102010,
          SpeakNpcId = 700363,
          Subtitle = "Huh? You're the one who brought it up — why act so shocked?",
          TalkActionId = {
            [1] = "700363:Shy03_End"
          }
        },
        [51102010] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "沒沒沒，只是確信了您就是在下苦苦等候的英雄，一時有感而發。",
          DialogueId = 51102010,
          GUID = "7FEDB384",
          NextDialogue = 51102011,
          SpeakNpcId = 700322,
          Subtitle = "Uh... I mean, only now am I certain. You must be the hero I've long awaited. Forgive my excitement.",
          TalkActionId = {
            [1] = "700322:Explain01_End"
          }
        },
        [51102011] = {
          Camera = "-27.642578,-571.077148,131.51416,0.000049,-9.599796,81.000999,35.0,631.937927,false,Manual,2.8",
          ContentTC = "咱們言歸正傳，在下偶得天機，如今時機已到，便與英雄透露一二……",
          DialogueId = 51102011,
          GUID = "7FEDB3AE",
          SpeakNpcId = 700322,
          Subtitle = "But let's not stray from the moment. A divine insight has come to me — and the time has come to pass it on."
        },
        [51102012] = {
          Camera = "15.212891,-75.541016,90.239258,0.000013,-5.598753,28.601549,35.0,133.830734,false,Manual,2.8",
          ContentTC = "什麼天機，說來聽聽？",
          DialogueId = 51102012,
          GUID = "7FEDB3D8",
          LookAt = {
            [1] = "700322:n(100001)"
          },
          NextDialogue = 51102013,
          SpeakNpcId = 100001,
          Subtitle = "What kind of insight? Come on, let's hear it.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51102013] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "莫急莫急，這第一句，「重山疊水之外，孤帆朽木之間」。",
          DialogueId = 51102013,
          GUID = "7FEDB402",
          NextDialogue = 51102014,
          SpeakNpcId = 700322,
          Subtitle = "All in good time. The first verse goes: \"Beyond mountains piled and rivers layered, between lone sail and rotted hull.\"",
          TalkActionId = {
            [1] = "700322:Explain02_Start"
          }
        },
        [51102014] = {
          Camera = "15.212891,-75.541016,90.239258,0.000013,-5.598753,28.601549,35.0,133.830734,false,Manual,2.8",
          ContentTC = "聽起來像是在說黑市旁的那艘沉船……那裡有什麼？",
          DialogueId = 51102014,
          GUID = "7FEDB42C",
          NextDialogue = 51102015,
          SpeakNpcId = 100001,
          Subtitle = "That sounds like that old wreck near the black market... What's supposed to be there?"
        },
        [51102015] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "英雄果然聰慧，在下正是得這第一條口諭才走訪此間。",
          DialogueId = 51102015,
          GUID = "7FEDB456",
          NextDialogue = 51102016,
          SpeakNpcId = 700322,
          Subtitle = "Just as I thought — such keen intuition. That very verse is what led me here.",
          TalkActionId = {
            [1] = "700322:Explain02_End"
          }
        },
        [51102016] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "在下觀得二位儀表堂堂器宇不凡，又有霞光普照，定是財運亨通之人。這預言所示之處，應是二位的財源所在了。",
          DialogueId = 51102016,
          GUID = "7FEDB480",
          NextDialogue = 51102017,
          SpeakNpcId = 700322,
          Subtitle = "The moment I laid eyes on you — such presence, such radiance — I knew you were marked by boundless fortune. Surely this place is where your riches lie in wait."
        },
        [51102017] = {
          Camera = "-7.996094,1.37793,50.615234,0.000117,-8.999327,37.795189,35.0,145.872787,false,Manual,2.8",
          ContentTC = "那我們就四處走走看看，見到可疑的地方就挖開，說不定能找到什麼寶藏呢！",
          DialogueId = 51102017,
          GUID = "7FEDB4AA",
          LookAt = {
            [1] = "700322:n(700363)"
          },
          NextDialogue = 51102018,
          SpeakNpcId = 700363,
          Subtitle = "Then let's have a poke around! If anything looks fishy, we'll dig — maybe we'll even find treasure!",
          TalkActionId = {
            [1] = "700363:Excited01_Start"
          }
        },
        [51102018] = {
          Camera = "-27.642578,-571.077148,131.51416,0.000049,-9.599796,81.000999,35.0,631.937927,false,Manual,2.8",
          ContentTC = "如果真要那麼簡單就能找到寶藏，恐怕他也不會在這抓人幫忙了。",
          DialogueId = 51102018,
          GUID = "7FEDB4D4",
          LookAt = {
            [1] = "700322:n(100001)"
          },
          NextDialogue = 51102019,
          SpeakNpcId = 100001,
          Subtitle = "If treasure were that easy to find, he wouldn't be roping us into it, would he?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700363:Excited01_End"
          }
        },
        [51102019] = {
          Camera = "-27.642578,-571.077148,131.51416,0.000049,-9.599796,81.000999,35.0,631.937927,false,Manual,2.8",
          ContentTC = "此言差矣，生死有命富貴在天，在下豈有篡天改命之能？該是二位的命數，在下不過指點一二，只求與鴻運之人結緣罷了。",
          DialogueId = 51102019,
          GUID = "7FEDB4FE",
          NextDialogue = 51102020,
          SpeakNpcId = 700322,
          Subtitle = "Ah, but there you misjudge me. Fortune is heaven's to bestow — I merely follow its tide, nudging it where I may. To cross paths with the truly blessed... that alone is reward enough.",
          TalkActionId = {
            [1] = "700322:Disagree"
          }
        },
        [51102020] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "若二位不信，在下這卦分文不取，等二位去一探究竟再回來不遲。",
          DialogueId = 51102020,
          GUID = "7FEDB528",
          NextOptions = {
            [1] = 51102021,
            [2] = 51102023
          },
          SpeakNpcId = 700322,
          Subtitle = "But if you remain unconvinced, take this reading as a gift. Go and see for yourselves — return only if it proves worth the telling.",
          TalkActionId = {
            [1] = "700322:Explain01_Start"
          }
        },
        [51102021] = {
          ContentTC = "好吧，如果有什麼發現我會告訴你。",
          DialogueId = 51102021,
          GUID = "7FEDB552",
          ImprPlusId = 1207,
          NextDialogue = 51102022,
          Subtitle = "Alright. If we do find something, I'll let you know."
        },
        [51102022] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "多謝二位英雄。",
          DialogueId = 51102022,
          GUID = "7FEDB57C",
          SpeakNpcId = 700322,
          Subtitle = "My heartfelt thanks, noble heroes.",
          TalkActionId = {
            [1] = "700322:Explain01_End"
          }
        },
        [51102023] = {
          ContentTC = "好吧，不過要是真有寶藏，你不會管我要分成吧？",
          DialogueId = 51102023,
          GUID = "7FEDB5A6",
          ImprPlusId = 1206,
          NextDialogue = 51102024,
          Subtitle = "Fine — but if there really is treasure, don't expect a cut."
        },
        [51102024] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "那自然不會。",
          DialogueId = 51102024,
          GUID = "7FEDB5D0",
          SpeakNpcId = 700322,
          Subtitle = "Perish the thought.",
          TalkActionId = {
            [1] = "700322:Explain01_End"
          }
        },
        [51102025] = {
          Camera = "-115.849609,-257.954102,150.429199,0.000071,-17.399326,54.601627,35.0,425.215027,false,Manual,2.8",
          ContentTC = "這是……五枚銅幣？",
          DialogueId = 51102025,
          GUID = "7FEDB5FA",
          LookAt = {
            [1] = "700322:n(100001)",
            [2] = "700363:n(100001)"
          },
          NextDialogue = 51102026,
          SpeakNpcId = 100001,
          Subtitle = "...Five copper coins?",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51102026] = {
          Camera = "645.011719,215.524414,95.914062,0.000001,-6.599854,-162.398209,35.0,651.573547,false,Manual,2.8",
          ContentTC = "哦，果真有所收穫，看來喻示所言非虛。",
          DialogueId = 51102026,
          GUID = "7FEDB624",
          LookAt = {
            [1] = "700363:n(700322)"
          },
          NextDialogue = 51102027,
          SpeakNpcId = 700322,
          Subtitle = "Ah — a sign, just as foretold! The oracle spoke true after all.",
          TalkActionId = {
            [1] = "700322:Agree"
          }
        },
        [51102027] = {
          Camera = "-115.849609,-257.954102,150.429199,0.000071,-17.399326,54.601627,35.0,425.215027,false,Manual,2.8",
          ContentTC = "好小氣，這真的是寶藏嗎，不會是哪個小朋友偷偷藏的零花錢吧？",
          DialogueId = 51102027,
          GUID = "7FEDB64E",
          LookAt = {
            [1] = "700322:n(700363)"
          },
          NextDialogue = 51102028,
          SpeakNpcId = 700363,
          Subtitle = "This is the treasure? No way! Are you sure it's not just some kid's pocket money?",
          TalkActionId = {
            [1] = "700363:Angry01_Start"
          }
        },
        [51102028] = {
          Camera = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
          ContentTC = "這……英雄莫怪，這一遭乃是必經之路，興許下一程就有收穫了呢？",
          DialogueId = 51102028,
          GUID = "7FEDB678",
          NextDialogue = 51102029,
          SpeakNpcId = 700322,
          Subtitle = "W—Well... every journey begins with a step! Perhaps the next stop holds greater reward.",
          TalkActionId = {
            [1] = "700322:Talk01_Start"
          }
        },
        [51102029] = {
          Camera = "15.212891,-75.541016,90.239258,0.000013,-5.598753,28.601549,35.0,133.830734,false,Manual,2.8",
          ContentTC = "總感覺你在騙我……",
          DialogueId = 51102029,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FEDB6A2",
          LookAt = {
            [1] = "700322:n(100001)"
          },
          NextDialogue = 51102030,
          SpeakNpcId = 100001,
          Subtitle = "I'm starting to think you're just stringing us along...",
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "700363:Angry01_End"
          }
        },
        [51102030] = {
          Camera = "-27.642578,-571.077148,131.51416,0.000047,-8.999784,79.401276,35.0,631.937927,false,Manual,2.8",
          ContentTC = "話不能這麼說，在下只是遇到有緣人便多言幾句，並無意強求。",
          DialogueId = 51102030,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FEDB6CC",
          NextDialogue = 51102031,
          SpeakNpcId = 700322,
          Subtitle = "Now, now — don't say that. I merely speak when fate guides me to the right souls. I've no mind to pressure you."
        },
        [51102031] = {
          Camera = "-27.642578,-571.077148,131.51416,0.000047,-8.999784,79.401276,35.0,631.937927,false,Manual,2.8",
          ContentTC = "這第二句，「枯骨獨臥折戟側，苔深猶照石海空」。是否要前去尋這地方，英雄自便就是。",
          DialogueId = 51102031,
          GUID = "7FEDB6F6",
          NextDialogue = 51102032,
          SpeakNpcId = 700322,
          Subtitle = "The second verse runs thus: \"Where brittle bones lie by broken blades, moss gleams beneath a stonebound sea.\" Whether or not to seek it — that choice is yours.",
          TalkActionId = {
            [1] = "700322:Talk01_End"
          }
        },
        [51102032] = {
          Camera = "-156.484375,-67.136719,113.200684,0.000001,-9.999662,14.205973,35.0,299.776581,false,Manual,2.8",
          ContentTC = "（折戟……石海……？聽起來有些熟悉，有時間的話還是去看看吧。）",
          DialogueId = 51102032,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FEDB720",
          SpeakNpcId = 100001,
          Subtitle = "(Broken blades... stone sea...? That does ring a bell. Might be worth a look, if time allows.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51102033] = {
          Camera = "-149.505859,1027.396973,-1193.769531,0.00001,4.000114,168.796509,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那個神秘兮兮的傢伙說的地方應該就在這附近……",
          DialogueId = 51102033,
          GUID = "7FEDB74A",
          LookAt = {
            [1] = "700363:n(100001)"
          },
          NextDialogue = 51102034,
          Scripts = "SetVisibility{ActorId{210087},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "This should be the spot that odd fellow spoke of...",
          TalkActionId = {
            [1] = "100001:Talk03ToTalkL_Start"
          }
        },
        [51102034] = {
          Camera = "-489.546875,1160.666992,-1151.067383,0.000046,-12.999803,-22.002632,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這個地方好陰森，真的會有寶藏嗎？",
          DialogueId = 51102034,
          GUID = "7FEDB774",
          NextDialogue = 51102035,
          SpeakNpcId = 700363,
          Subtitle = "This place gives me the creeps... Are we sure there's treasure here?",
          TalkActionId = {
            [1] = "700363:Bai_Circle_Start"
          }
        },
        [51102035] = {
          Camera = "-149.505859,1027.396973,-1193.769531,0.00001,4.000114,168.796509,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "如果真有寶藏，就不會有人把這件事告訴別人了吧？",
          DialogueId = 51102035,
          GUID = "7FEDB79E",
          NextDialogue = 51102036,
          SpeakNpcId = 100001,
          Subtitle = "If there were, I doubt anyone would be tipping us off about it.",
          TalkActionId = {
            [1] = "100001:Talk03ToTalkL_End"
          }
        },
        [51102036] = {
          Camera = "-376.947266,534.023438,-1147.687012,0.000055,-7.799748,81.195419,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "吼——",
          DialogueId = 51102036,
          GUID = "7FEDB7C8",
          Scripts = "SetVisibility{ActorId{210087},Visibility{\"Show\"}}",
          SpeakNpcId = 210087,
          SpeakNpcName = "UI_Npc_Name_XuanSeBiAn",
          Subtitle = "Roaaaar—!",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51102037] = {
          ContentTC = "又是這些大黑狗，到底是從哪裡冒出來的！",
          DialogueId = 51102037,
          GUID = "7FEDB7F2",
          NextDialogue = 51102038,
          SpeakNpcId = 700363,
          Subtitle = "Ugh, not these mangy mutts again! Where do they keep crawling out from!?"
        },
        [51102038] = {
          ContentTC = "快躲到我身後。",
          DialogueId = 51102038,
          GUID = "7FEDB81C",
          SpeakNpcId = 100001,
          Subtitle = "Get behind me."
        },
        [51102039] = {
          Camera = "-354.792969,1106.128906,-1192.614258,0.000058,-11.599819,-22.20047,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "真是的，怎麼突然冒出來這麼多怪物，還好我們很強，要是一般人來這可就糟了。",
          DialogueId = 51102039,
          GUID = "7FEDB846",
          LookAt = {
            [1] = "700363:n(100001)"
          },
          NextDialogue = 51102040,
          SpeakNpcId = 700363,
          Subtitle = "Whew! Lucky we're tough — any regular folks would've been monster snacks by now!",
          TalkActionId = {
            [1] = "700363:Angry01_Start"
          }
        },
        [51102040] = {
          Camera = "125.566406,965.652344,-1111.134766,0.000054,-12.199892,167.597137,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "很強的是……「我們」？",
          DialogueId = 51102040,
          GUID = "7FEDB870",
          NextDialogue = 51102041,
          SpeakNpcId = 100001,
          Subtitle = "\"We\"? Since when?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51102041] = {
          Camera = "-407.277344,1005.297363,-1174.481445,0.000019,-13.000062,18.001871,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "啊這個……還是不要找什麼寶藏了，我們快離開這吧？",
          DialogueId = 51102041,
          GUID = "7FEDB89A",
          NextDialogue = 51102042,
          SpeakNpcId = 700363,
          Subtitle = "Uh... maybe we should skip the treasure-hunting and just go home?",
          TalkActionId = {
            [1] = "700363:Angry01_End"
          }
        },
        [51102042] = {
          Camera = "-1358.679688,548.598145,-979.144531,0.000016,-9.200011,23.799543,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不著急，我們在這附近稍微走走吧，我有點好奇之前遇到的那個傢伙到底想做什麼。",
          DialogueId = 51102042,
          GUID = "7FEDB8C4",
          SpeakNpcId = 100001,
          Subtitle = "No rush. Let's look around — I want to know what that guy's really up to.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51102043] = {
          Camera = "-15.613281,332.233398,273.983398,0.000018,-29.799984,-91.399025,35.0,282.505707,false,Manual,2.8",
          ContentTC = "嗯？這是什麼？",
          DialogueId = 51102043,
          GUID = "7FEDB8EE",
          NextDialogue = 51102044,
          Scripts = "SetVisibility{ActorId{700322},Visibility{\"Hide\"}}",
          SpeakNpcId = 700363,
          Subtitle = "Huh? What's this?"
        },
        [51102044] = {
          Camera = "444.105469,-373.708008,196.07666,0.000038,-9.999697,143.80011,35.0,696.120667,false,Manual,2.8",
          ContentTC = "小僕從小僕從你快過來看，好像真的有寶藏誒！",
          DialogueId = 51102044,
          GUID = "7FEDB918",
          NextDialogue = 51102045,
          SpeakNpcId = 700363,
          Subtitle = "Little Minion, quick — come look! I think we've found real treasure this time!",
          TalkActionId = {
            [1] = "700363:Excited01_Start"
          }
        },
        [51102045] = {
          Camera = "444.105469,-373.708008,196.07666,0.000038,-9.999697,143.80011,35.0,696.120667,false,Manual,2.8",
          ContentTC = "那我們就不客氣地收下啦！",
          DialogueId = 51102045,
          GUID = "7FEDB942",
          NextDialogue = 51102046,
          SpeakNpcId = 700363,
          Subtitle = "Well then — don't mind if we help ourselves!",
          TalkActionId = {
            [1] = "700363:Excited01_End"
          }
        },
        [51102046] = {
          Camera = "231.78125,-321.335938,167.96875,0.000082,-9.999294,125.396858,35.0,422.409485,false,Manual,2.8",
          ContentTC = "且慢。",
          DialogueId = 51102046,
          GUID = "7FEDB96C",
          NextDialogue = 51102047,
          SpeakNpcId = 700322,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Not so fast.",
          TurnTo = {
            [1] = "100001:n(700322)",
            [2] = "700363:n(700322)"
          }
        },
        [51102047] = {
          Camera = "415.392578,629.603516,188.165527,0.000093,-3.999048,-126.200905,35.0,819.580994,false,Manual,2.8",
          ContentTC = "二位英雄，恐怕這些財物不能讓你們帶走。",
          DialogueId = 51102047,
          GUID = "7FEDB996",
          NextDialogue = 51102048,
          Scripts = "SetVisibility{ActorId{700322},Visibility{\"Show\"}}",
          SpeakNpcId = 700322,
          Subtitle = "I'm afraid I cannot let you walk off with those spoils.",
          TalkActionId = {
            [1] = "700322:Confident_Start",
            [2] = "100001:Shock_Start",
            [3] = "700363:Shock_Start"
          }
        },
        [51102048] = {
          Camera = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
          ContentTC = "你在這裡幹什麼？",
          DialogueId = 51102048,
          GUID = "7FEDB9C0",
          NextDialogue = 51102049,
          SpeakNpcId = 100001,
          Subtitle = "What are you doing here?",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51102049] = {
          Camera = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
          ContentTC = "既然凶獸已驅，在下自然是取回應得之物。",
          DialogueId = 51102049,
          GUID = "7FEDB9EA",
          NextDialogue = 51102050,
          SpeakNpcId = 700322,
          Subtitle = "Now that the beasts are dealt with, I've simply come to reclaim what's rightfully mine.",
          TalkActionId = {
            [1] = "700363:Shock_End"
          }
        },
        [51102050] = {
          Camera = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
          ContentTC = "多虧二位英雄「碰巧」來此除凶驅禍，不然在下埋在此處的積蓄怕是無法取回了。",
          DialogueId = 51102050,
          GUID = "7FEDBA14",
          NextDialogue = 51102051,
          SpeakNpcId = 700322,
          Subtitle = "Thanks to you valiant souls ever so \"conveniently\" clearing out the danger, I can now retrieve the stash I buried here.",
          TalkActionId = {
            [1] = "700322:Confident_End"
          }
        },
        [51102051] = {
          Camera = "-113.234375,-79.991211,166.837891,0.000162,-10.798952,72.195564,35.0,148.932434,false,Manual,2.8",
          ContentTC = "如果是這樣，一開始就實話實說不就好了？",
          DialogueId = 51102051,
          GUID = "7FEDBA3E",
          NextDialogue = 51102052,
          SpeakNpcId = 100001,
          Subtitle = "If that's all it was, you could've just told us from the start.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51102052] = {
          Camera = "534.162109,-171.324219,313.386719,0.000211,-18.79907,165.795944,35.0,672.763,false,Manual,2.8",
          ContentTC = "此言差矣，在下若是尋求幫助，豈不是要憑空折損一筆報酬。",
          DialogueId = 51102052,
          GUID = "7FEDBA68",
          NextDialogue = 51102053,
          SpeakNpcId = 700322,
          Subtitle = "Ah, but then I'd have had to pay for your help. Why part with coin when fate might lend a hand for free?",
          TalkActionId = {
            [1] = "700322:Disagree"
          }
        },
        [51102053] = {
          Camera = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
          ContentTC = "有道理……等等，這不就是讓我們打白工嘛？！",
          DialogueId = 51102053,
          GUID = "7FEDBA92",
          NextDialogue = 51102054,
          SpeakNpcId = 700363,
          Subtitle = "Makes sense... wait a sec! You tricked us into doing your dirty work for nothing!?",
          TalkActionId = {
            [1] = "700363:Angry02_Start"
          }
        },
        [51102054] = {
          Camera = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
          ContentTC = "是又如何？這些本就是在下的財產，二位總不能在大風九章之下強取豪奪吧？",
          DialogueId = 51102054,
          GUID = "7FEDBABC",
          NextDialogue = 51102055,
          SpeakNpcId = 700322,
          Subtitle = "And if I did? These goods are mine by right. Surely you wouldn't defy the Nine Chapters of Dafeng and take them by force... would you?",
          TalkActionId = {
            [1] = "700322:Angry01_Start"
          }
        },
        [51102055] = {
          Camera = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
          ContentTC = "你的財產？怕不是用你那套招搖撞騙得來的不義之財。",
          DialogueId = 51102055,
          GUID = "7FEDBAE6",
          NextDialogue = 51102056,
          SpeakNpcId = 100001,
          Subtitle = "Your property? I'd say it's more like the spoils of a swindler's game.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51102056] = {
          Camera = "-24.017578,125.793945,181.728516,0.000098,-3.3992,-116.801804,35.0,238.547546,false,Manual,2.8",
          ContentTC = "這位英雄可不要憑空污人清白，未來之事皆無定數，在下不過是提出一種猜測，總有人願意花些小錢為未來的發達買單。",
          DialogueId = 51102056,
          GUID = "7FEDBB10",
          NextDialogue = 51102057,
          SpeakNpcId = 700322,
          Subtitle = "Now, now — no need for baseless slander. The future is unknowable. I merely offer speculation... and there'll always be those willing to pay a little for a chance at riches."
        },
        [51102057] = {
          Camera = "-24.017578,125.793945,181.728516,0.000098,-3.3992,-116.801804,35.0,238.547546,false,Manual,2.8",
          ContentTC = "至於能否兌現……就不在在下的能力範圍之內了。",
          DialogueId = 51102057,
          GUID = "7FEDBB3A",
          NextDialogue = 51102058,
          SpeakNpcId = 700322,
          Subtitle = "As for whether those dreams come true... well, that's in fate's hands."
        },
        [51102058] = {
          Camera = "534.162109,-171.324219,313.386719,0.000211,-18.79907,165.795944,35.0,672.763,false,Manual,2.8",
          ContentTC = "誠然，在下的做法有些不確定性，但既然大風九章從未降下裁決，英雄又如何能稱之為招搖撞騙呢？",
          DialogueId = 51102058,
          GUID = "7FEDBB64",
          NextDialogue = 51102059,
          SpeakNpcId = 700322,
          Subtitle = "Admittedly, my methods may seem a touch... speculative. But if the Nine Chapters have never ruled against me — can you truly call it fraud?",
          TalkActionId = {
            [1] = "700322:Angry01_End"
          }
        },
        [51102059] = {
          Camera = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
          ContentTC = "居然還一臉得意地解釋起來了！這傢伙惹我生氣了！",
          DialogueId = 51102059,
          FacialId = {
            [1] = "700363:Angry01"
          },
          GUID = "7FEDBB8E",
          NextDialogue = 51102060,
          SpeakNpcId = 700363,
          Subtitle = "He's actually proud of himself! Ugh! This guy's driving me up the wall!",
          TalkActionId = {
            [1] = "700363:Angry02_End"
          }
        },
        [51102060] = {
          Camera = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
          ContentTC = "……",
          DialogueId = 51102060,
          GUID = "7FEDBBB8",
          NextDialogue = 51102061,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51102061] = {
          Camera = "-129.705078,-259.818359,233.538086,0.000134,-20.598783,73.194275,35.0,346.317627,false,Manual,2.8",
          ContentTC = "小僕從你怎麼不說話，你倒是想想辦法啊。",
          DialogueId = 51102061,
          GUID = "7FEDBBE2",
          SpeakNpcId = 700363,
          Subtitle = "Little Minion, don't just stand there — do something!",
          TurnTo = {
            [1] = "700363:n(100001)"
          }
        },
        [51102062] = {
          ContentTC = "識相點就趕緊離開吧，若是再糾纏，恐怕大風九章就要對二位出手了。",
          DialogueId = 51102062,
          GUID = "7FEDBC0C",
          SpeakNpcId = 700322,
          Subtitle = "Best make yourselves scarce. Keep meddling, and the Nine Chapters may take an interest in you."
        },
        [51102063] = {
          ContentTC = "怎麼還不走？賴在這幹嘛？",
          DialogueId = 51102063,
          GUID = "7FEDBC36",
          SpeakNpcId = 700322,
          Subtitle = "Still here? Have you nowhere else to be?"
        },
        [51102064] = {
          ContentTC = "二位最好離那個箱子遠點，不然在下就要叫人了！",
          DialogueId = 51102064,
          GUID = "7FEDBC60",
          SpeakNpcId = 700322,
          Subtitle = "I suggest you step away from that chest — or I'll be forced to call for aid!"
        },
        [51102065] = {
          ContentTC = "在下真的要叫人了！",
          DialogueId = 51102065,
          GUID = "7FEDBC8A",
          SpeakNpcId = 700322,
          Subtitle = "I'll summon help — don't test me!"
        },
        [51102066] = {
          Camera = "-75.28125,-74.974609,175.415527,0.000164,-17.598877,87.793106,35.0,129.289429,false,Manual,2.8",
          ContentTC = "原來如此……",
          DialogueId = 51102066,
          GUID = "7FEDBCB4",
          NextDialogue = 51102067,
          SpeakNpcId = 100001,
          Subtitle = "Ah, I see...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51102067] = {
          Camera = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
          ContentTC = "什……什麼原來如此？",
          DialogueId = 51102067,
          GUID = "7FEDBCDE",
          NextDialogue = 51102068,
          SpeakNpcId = 700322,
          Subtitle = "S—See what, exactly?",
          TalkActionId = {
            [1] = "700322:Talk03_Start"
          }
        },
        [51102068] = {
          Camera = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
          ContentTC = "我本來還好奇你為什麼要這麼大費周章，還要自己跳出來親自解說一番……",
          DialogueId = 51102068,
          GUID = "7FEDBD08",
          LookAt = {
            [1] = "100001:n(700322)"
          },
          NextDialogue = 51102069,
          SpeakNpcId = 100001,
          Subtitle = "I was wondering why you'd go to such lengths — even showing up yourself to warn us away...",
          TurnTo = {
            [1] = "700363:n(700322)"
          }
        },
        [51102069] = {
          Camera = "46.033203,-537.740234,203.479492,0.000243,-11.398854,99.396233,35.0,611.363647,false,Manual,2.8",
          ContentTC = "看來大風九章並沒有認可這埋在荒郊野外的不義之財為你所有，所以你才要專門在我面前長篇大論試圖勸退我們。",
          DialogueId = 51102069,
          GUID = "7FEDBD32",
          NextDialogue = 51102070,
          SpeakNpcId = 100001,
          Subtitle = "Turns out the Nine Chapters don't recognise this stash as yours — that's why you kept bluffing, trying to scare us off.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51102070] = {
          Camera = "46.033203,-537.740234,203.479492,0.000243,-11.398854,99.396233,35.0,611.363647,false,Manual,2.8",
          ContentTC = "只要我像這樣觸碰到這個箱子，就會知道大風九章並不會生效，也就是說——這就是我撿到的。",
          DialogueId = 51102070,
          GUID = "7FEDBD5C",
          NextDialogue = 51102071,
          SpeakNpcId = 100001,
          Subtitle = "All I need to do is touch the chest... and when nothing happens, that proves it — I can claim it freely, without breaking the Nine Chapters.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51102071] = {
          Camera = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
          ContentTC = "真的誒，什麼事都沒有發生……",
          DialogueId = 51102071,
          GUID = "7FEDBD86",
          NextDialogue = 51102072,
          SpeakNpcId = 700363,
          Subtitle = "Whoa, you're right — nothing happened at all!",
          TalkActionId = {
            [1] = "700363:Shock03_Start"
          }
        },
        [51102072] = {
          Camera = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
          ContentTC = "怪不得煜明說這黑市都是些雞鳴狗盜之徒，大風九章竟被這樣曲解利用……",
          DialogueId = 51102072,
          GUID = "7FEDBDB0",
          NextDialogue = 51102073,
          SpeakNpcId = 100001,
          Subtitle = "No wonder Yuming said the black market's full of swindlers. Even the Nine Chapters can be bent for the sake of silver..."
        },
        [51102073] = {
          Camera = "-24.017578,125.793945,181.728516,0.000098,-2.399199,-116.801994,35.0,238.547546,false,Manual,2.8",
          ContentTC = "你……你……",
          DialogueId = 51102073,
          GUID = "7FEDBDDA",
          NextDialogue = 51102074,
          SpeakNpcId = 700322,
          Subtitle = "You... you...!",
          TalkActionId = {
            [1] = "700322:Talk03_End"
          }
        },
        [51102074] = {
          Camera = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
          ContentTC = "如何，要試試在大風九章之下強取豪奪嗎？",
          DialogueId = 51102074,
          GUID = "7FEDBE04",
          NextDialogue = 51102075,
          SpeakNpcId = 100001,
          Subtitle = "What now? Going to rob us under the watchful eye of the Nine Chapters?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51102075] = {
          Camera = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
          ContentTC = "就算你真的敢動手，你也打不過我們小僕從的哦~",
          DialogueId = 51102075,
          GUID = "7FEDBE2E",
          NextDialogue = 51102076,
          SpeakNpcId = 700363,
          Subtitle = "Even if you try, you wouldn't last a second against my Little Minion~!",
          TalkActionId = {
            [1] = "700363:Shock03_End"
          }
        },
        [51102076] = {
          Camera = "444.105469,-373.708008,196.07666,0.000038,-9.999697,143.80011,35.0,696.120667,false,Manual,2.8",
          ContentTC = "你們……不要再讓在下見到你們！否則肯定讓你們吃不了兜著走！",
          DialogueId = 51102076,
          GUID = "7FEDBE58",
          NextDialogue = 51102077,
          SpeakNpcId = 700322,
          Subtitle = "Tch... mark my words. Should we meet again, you will not walk away so easily!",
          TalkActionId = {
            [1] = "700322:Angry01_Start"
          }
        },
        [51102077] = {
          Camera = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
          ContentTC = "哦是嗎？如果下次再見你沒能讓我們吃不了兜著走，大風九章會不會覺得你在說謊呢？",
          DialogueId = 51102077,
          GUID = "7FEDBE82",
          NextDialogue = 51102078,
          SpeakNpcId = 100001,
          Subtitle = "Oh really? And if we do walk away easily — will the Nine Chapters condemn you a liar?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51102078] = {
          Camera = "534.162109,-171.324219,313.386719,0.000211,-18.79907,165.795944,35.0,672.763,false,Manual,2.8",
          ContentTC = "你……我……哎！",
          DialogueId = 51102078,
          GUID = "7FEDBEAC",
          NextDialogue = 51102079,
          SpeakNpcId = 700322,
          Subtitle = "You... I... Ugh!",
          TalkActionId = {
            [1] = "700322:Angry01_End"
          }
        },
        [51102079] = {
          Camera = "100.279297,-863.963867,265.523926,0.00021,-8.998719,99.399925,35.0,1009.015198,false,Manual,2.8",
          ContentTC = "哼，讓你騙我們！寶箱~寶箱~看看裡面有多少好東西吧。",
          DialogueId = 51102079,
          GUID = "7FEDBED6",
          NextDialogue = 51102080,
          SpeakNpcId = 700363,
          Subtitle = "Hmph! Serves you right! Now then, Mr Treasure Box~ Let's see what goodies you've been hiding!",
          TalkActionId = {
            [1] = "700363:BaiTX_Story_Pride_Start"
          }
        },
        [51102080] = {
          Camera = "-113.234375,-79.991211,166.837891,0.000161,-10.19894,72.195618,35.0,148.932434,false,Manual,2.8",
          ContentTC = "（到頭來還是沒搞清楚那個聲音是什麼。）",
          DialogueId = 51102080,
          GUID = "7FEDBF00",
          NextDialogue = 51102081,
          SpeakNpcId = 100001,
          Subtitle = "(Still no closer to knowing what that voice really was...)",
          TalkActionId = {
            [1] = "100001:Confident_End"
          }
        },
        [51102081] = {
          Camera = "-113.234375,-79.991211,166.837891,0.000161,-10.19894,72.195618,35.0,148.932434,false,Manual,2.8",
          ContentTC = "（不過沒想到會有人靠鑽大風九章的空子牟利……這是拋下劍盾，將力量交予「規則」的結果？）",
          DialogueId = 51102081,
          GUID = "7FEDBF2A",
          NextDialogue = 51102082,
          SpeakNpcId = 100001,
          Subtitle = "(But to think someone would exploit the Nine Chapters for profit... Is this the price of laying down sword and shield, and handing power to \"rules\" alone?)"
        },
        [51102082] = {
          Camera = "423.552734,881.602539,168.477539,0.000161,-0.198916,-119.004143,35.0,936.815369,false,Manual,2.8",
          ContentTC = "（虬先生……這也是你想讓我看到的嗎？）",
          DialogueId = 51102082,
          GUID = "7FEDBF54",
          SpeakNpcId = 100001,
          Subtitle = "(Mr Qiu... is this what you meant for me to see?)"
        },
        [51102083] = {
          ContentTC = "二位英雄請留步。",
          DialogueId = 51102083,
          GUID = "7FEDBF7E",
          SpeakNpcId = 700322,
          Subtitle = "A moment, if you please, noble heroes."
        },
        [51103001] = {
          Camera = "-544.789062,-142.763672,309.863281,0.000017,-20.213533,11.708329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（行至附近，你突然感覺懷中的牽機方樞震動了起來。）",
          DialogueId = 51103001,
          GUID = "7FEE561A",
          NextDialogue = 51103002,
          Subtitle = "(Just before reaching your destination, the Mechanical Nexus in your arms begins to tremble unexpectedly.)"
        },
        [51103002] = {
          Camera = "-231.298828,240.494141,220.422852,0.000012,-20.813593,-48.089558,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "小僕從，什麼聲音？是什麼東西在震？！",
          DialogueId = 51103002,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "7FEE5644",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextOptions = {
            [1] = 51103003,
            [2] = 51103005
          },
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, what's that noise? Something's shaking!"
        },
        [51103003] = {
          ContentTC = "（震動似乎遵循著什麼規律，仔細查看一下吧。）",
          DialogueId = 51103003,
          GUID = "7FEE5645",
          ImprPlusId = 1203,
          NextDialogue = 51103004,
          Subtitle = "(The vibrations seem to follow some kind of pattern. Best take a closer look.)"
        },
        [51103004] = {
          ContentTC = "（你用平生所學的所有知識分析了一下震動的聲音，最終一無所獲。）",
          DialogueId = 51103004,
          GUID = "7FEE566E",
          IsBlack = 1,
          NextDialogue = 51103007,
          Subtitle = "(You summon every scrap of knowledge you've ever learnt to analyse the vibration's rhythm... and come up with absolutely nothing.)"
        },
        [51103005] = {
          ContentTC = "（這玩意該不會要爆炸了吧，趕緊扔掉！）",
          DialogueId = 51103005,
          GUID = "7FEE566F",
          ImprPlusId = 1205,
          NextDialogue = 51103006,
          Subtitle = "(Is this thing about to blow!? Toss it — quick!)"
        },
        [51103006] = {
          ContentTC = "（你一把將牽機方樞丟出去老遠，但預想之中的爆炸並沒有發生。確認它就只是在單純地震動之後，你將它重新撿了起來。）",
          DialogueId = 51103006,
          GUID = "7FEE5698",
          IsBlack = 1,
          NextDialogue = 51103007,
          Subtitle = "(You fling the Mechanical Nexus as far as you can. No explosion follows. Realising it's only quivering, you cautiously retrieve it.)"
        },
        [51103007] = {
          Camera = "-544.789062,-142.763672,309.863281,0.000017,-20.213533,11.708329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "沒看到關閉震動的機關，難道是壞了嗎？等會去找公尚師傅幫忙看看吧。",
          DialogueId = 51103007,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FEE56C2",
          NextDialogue = 51103008,
          SpeakNpcId = 100001,
          Subtitle = "I don't see any switch to stop the vibration. Is it faulty? We should probably have Master Gongshang take a look.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51103008] = {
          ContentTC = "這個東西原來品質這麼差哦，還沒用幾次就這樣了……",
          DialogueId = 51103008,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "7FEE56EC",
          NextDialogue = 51103009,
          SpeakNpcId = 200002,
          Subtitle = "What shoddy workmanship — we've barely used it and it's already on the fritz!",
          TalkActionId = {
            [1] = "100001:ScratchHead_End"
          }
        },
        [51103009] = {
          ContentTC = "（打定主意後，你轉身準備離開，沒走幾步，你就感到牽機方樞的震動減弱了。）",
          DialogueId = 51103009,
          GUID = "7FEE5716",
          NextDialogue = 51103010,
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"TargetPoint200306_1\"},MoveSpeed{70},Visibility{\"Show\"}}",
          Subtitle = "(Decision made, you turn to leave — but after a few steps, you feel the vibrations begin to fade.)"
        },
        [51103010] = {
          Camera = "532.106445,-37.09668,232.477539,0.000057,-18.413574,-177.48764,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……",
          DialogueId = 51103010,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FEE5740",
          NextDialogue = 51103011,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          TurnTo = {
            [1] = "200002:n(100001)"
          }
        },
        [51103011] = {
          ContentTC = "剛才我面向那邊的時候，這牽機方樞的震動明顯比其他方向要強一些。難道這震動，是在為我指明方向？",
          DialogueId = 51103011,
          GUID = "7FEE576A",
          NextDialogue = 51103012,
          SpeakNpcId = 100001,
          Subtitle = "When I headed that way, the Nexus shook much harder than in any other direction. Could it be... leading me somewhere?"
        },
        [51103012] = {
          ContentTC = "哇——小僕從，那個方向該不會藏著什麼大寶貝？！我們趕緊去看看吧！",
          DialogueId = 51103012,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "7FEE5794",
          SpeakNpcId = 200002,
          Subtitle = "Oho! Little Minion, could it be pointing us to a grand treasure? Let's dash over and see!",
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          }
        },
        [51103013] = {
          Camera = "-273.101562,182.818359,178.920898,0.00004,-6.843535,-26.529842,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "公尚師傅，你怎麼在這？",
          DialogueId = 51103013,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FEE57BE",
          LookAt = {
            [1] = "100001:n(700323)",
            [2] = "200002:n(700323)"
          },
          NextDialogue = 51103014,
          SpeakNpcId = 100001,
          Subtitle = "Master Gongshang!? What are you doing here!?"
        },
        [51103014] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "大驚小怪的幹什麼？",
          DialogueId = 51103014,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FEE57E8",
          LookAt = {
            [1] = "700323:n(100001)"
          },
          NextDialogue = 51103015,
          SpeakNpcId = 700323,
          Subtitle = "Why the shock?"
        },
        [51103015] = {
          ContentTC = "我腿腳不好，懶得走動。察覺你們到了附近，便用牽機方樞指引你們過來。如何？這只是它千般妙用中的一種，要論其中更多門道……",
          DialogueId = 51103015,
          GUID = "7FEE5812",
          NextDialogue = 51103016,
          SpeakNpcId = 700323,
          Subtitle = "I sensed you nearby. But these old legs don't take kindly to long walks, so I used the Mechanical Nexus to guide you over. Clever, isn't it? And that's just one of its many marvels — there's plenty m—"
        },
        [51103016] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "還以為有什麼大寶貝，原來是你……沒勁。",
          DialogueId = 51103016,
          GUID = "7FEE583C",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 51103017,
          SpeakNpcId = 200002,
          Subtitle = "Pah! We thought it was some grand treasure calling us... and it's just you? Boooring.",
          TalkActionId = {
            [1] = "200002:Sigh_Start"
          }
        },
        [51103017] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "叫我們過來，就是為了說這些嗎？",
          DialogueId = 51103017,
          GUID = "7FEE5866",
          NextDialogue = 51103018,
          SpeakNpcId = 100001,
          Subtitle = "You dragged us all the way here just to flaunt your inventions?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51103018] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "唉，連機關的使用說明都不願意聽完。現在的年輕人，沉不下心來研究學問，著實浮躁啊。",
          DialogueId = 51103018,
          GUID = "7FEE5890",
          LookAt = {
            [1] = "200002:n(700323)"
          },
          NextDialogue = 51103019,
          SpeakNpcId = 700323,
          Subtitle = "... Can't even endure a proper tutorial. Young folk these days — so impatient, always in a rush. How disheartening.",
          TalkActionId = {
            [1] = "200002:Sigh_End"
          }
        },
        [51103019] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我們小僕從日理萬機，你再不說正題，我們可就要走了。",
          DialogueId = 51103019,
          GUID = "7FEE58BA",
          NextDialogue = 51103020,
          SpeakNpcId = 200002,
          Subtitle = "My Little Minion's got a jam-packed schedule! No time to waste on your droning — get to the point, or we're off.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          }
        },
        [51103020] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哎哎，可別走——",
          DialogueId = 51103020,
          GUID = "7FEE58E4",
          NextDialogue = 51103021,
          SpeakNpcId = 700323,
          Subtitle = "Now, now — no need to be so hasty."
        },
        [51103021] = {
          ContentTC = "你二位怎麼說也是機樞派榮譽學徒了。既然與我機樞派有緣，那我這引路人可得擔起責任，讓你們一品機樞之樂。",
          DialogueId = 51103021,
          GUID = "7FEE590E",
          NextDialogue = 51103022,
          SpeakNpcId = 700323,
          Subtitle = "As an Honorary Learner of the Jishu Sect, your ties with us run deep — and as your mentor, it's my duty to introduce you to the true joy of our craft."
        },
        [51103022] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我在這裡布置了數處機樞機關，皆為匠心打造，各有精妙設計。怎麼樣，是不是心動了，想趕緊體驗一把？",
          DialogueId = 51103022,
          GUID = "7FEE5938",
          NextOptions = {
            [1] = 51103023,
            [2] = 51103024
          },
          SpeakNpcId = 700323,
          Subtitle = "I've prepared several contraptions here — each a little masterpiece of precision and wit. Well then? Tempted to try your hand?"
        },
        [51103023] = {
          ContentTC = "呃，這個嘛……",
          DialogueId = 51103023,
          GUID = "7FEE5939",
          ImprPlusId = 1204,
          NextDialogue = 51103025,
          Subtitle = "Um... well..."
        },
        [51103024] = {
          ContentTC = "沒什麼更實質性的好處嗎？",
          DialogueId = 51103024,
          GUID = "7FEE5940",
          ImprPlusId = 1201,
          NextDialogue = 51103025,
          Subtitle = "What's in it for us? Any prizes?"
        },
        [51103025] = {
          Camera = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "唉，就知道你們年輕人會這樣。",
          DialogueId = 51103025,
          GUID = "7FEE5962",
          NextDialogue = 51103026,
          SpeakNpcId = 700323,
          Subtitle = "... Young ones these days. Just as I thought.",
          TalkActionId = {
            [1] = "700323:Disagree"
          }
        },
        [51103026] = {
          ContentTC = "根據我收徒這麼多年來的碰壁經驗，沒什麼好處，你們年輕人是不會上鉤的。放心，獎勵我早就準備好了。",
          DialogueId = 51103026,
          GUID = "7FEE598C",
          NextDialogue = 51103027,
          SpeakNpcId = 700323,
          Subtitle = "Years of butting heads with unwilling pupils have taught me one thing: without a little bait, none of you ever bite. Rest assured — there will be rewards."
        },
        [51103027] = {
          Camera = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那就勉強答應你吧。",
          DialogueId = 51103027,
          GUID = "7FEE59B6",
          SpeakNpcId = 100001,
          Subtitle = "Then... I guess we'll give it a shot.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [51103028] = {
          ContentTC = "我們現在玩的這個很簡單，找到附近的機樞球，用你手裡的牽機方樞把它們引到這個坑裡就行，試試看吧。",
          DialogueId = 51103028,
          Duration = 12,
          GUID = "7FEE59E0",
          SpeakNpcId = 700323,
          Subtitle = "This first one's simple — seek out the nearby Jishu spheres and use the Nexus to guide them into the pit. Go on, have a go."
        },
        [51103029] = {
          ContentTC = "不錯，一點就通。",
          DialogueId = 51103029,
          Duration = 5,
          GUID = "7FEE5A0A",
          SpeakNpcId = 700323,
          Subtitle = "Not bad — you're a quick study. Come on then, onto the next."
        },
        [51103030] = {
