        },
        [51104019] = {
          ContentTC = "我騙你們兩個小毛孩做什麼。",
          DialogueId = 51104019,
          GUID = "7FEEFD1E",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104020,
          SpeakNpcId = 700328,
          Subtitle = "What would I lie to a couple of kids for?",
          TalkActionId = {
            [1] = "700328:Talk01_Start"
          }
        },
        [51104020] = {
          ContentTC = "小武，快說謝謝叔叔！",
          DialogueId = 51104020,
          GUID = "7FEEFD48",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)",
            [3] = "700326:n(700327)"
          },
          NextDialogue = 51104021,
          SpeakNpcId = 700326,
          Subtitle = "Let's thank this kind sir, Wu!",
          TalkActionId = {
            [1] = "700326:Talk01_Start"
          }
        },
        [51104021] = {
          ContentTC = "哎，莫著急謝，先聽謎面。山腰懸玉鉤，樹杪掛銀舟。圓缺妝檯鏡，陰晴刈麥秋。",
          DialogueId = 51104021,
          GUID = "7FEEFD72",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextOptions = {
            [1] = 51104022,
            [2] = 51104024,
            [3] = 51104026
          },
          SpeakNpcId = 700328,
          Subtitle = "Hold your thanks — riddle first: \"A jade sickle upon slopes, A silver boat caught in the boughs. Full, then thin — a boudoir mirror gleams and pales; clouded or clear, it watches over ripening fields come harvest-time.\"",
          TalkActionId = {
            [1] = "700326:Talk01_End"
          }
        },
        [51104022] = {
          ContentTC = "盤子",
          DialogueId = 51104022,
          GUID = "7FEEFD9C",
          NextDialogue = 51104023,
          Subtitle = "A plate"
        },
        [51104023] = {
          ContentTC = "感覺不太對勁……",
          DialogueId = 51104023,
          GUID = "7FEEFDC6",
          NextOptions = {
            [1] = 51104201,
            [2] = 51104026
          },
          SpeakNpcId = 100001,
          Subtitle = "That doesn't seem quite right..."
        },
        [51104024] = {
          ContentTC = "天之樹",
          DialogueId = 51104024,
          GUID = "7FEEFDF0",
