        [51104026] = {
          ContentTC = "月亮",
          DialogueId = 51104026,
          GUID = "7FEEFE44",
          NextDialogue = 51104027,
          Subtitle = "The moon"
        },
        [51104027] = {
          ContentTC = "答案是……",
          DialogueId = 51104027,
          GUID = "7FEEFE6E",
          NextDialogue = 51104028,
          SpeakNpcId = 100001,
          Subtitle = "The answer is..."
        },
        [51104028] = {
          ContentTC = "我知道我知道，是月亮！",
          DialogueId = 51104028,
          GUID = "7FEEFE98",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104029,
          SpeakNpcId = 700326,
          Subtitle = "I know! It's the moon!",
          TalkActionId = {
            [1] = "700326:Confident_Start"
          }
        },
        [51104029] = {
          ContentTC = "老爺子這謎題是不是出的太簡單了……來吧，給你們的桂花糕。兄弟倆一人一半，不許搶。",
          DialogueId = 51104029,
          GUID = "7FEEFEC2",
          NextDialogue = 51104030,
          SpeakNpcId = 700328,
          Subtitle = "Ha, seems the old man made that one too easy. Here you go. Split it fair — no fighting over it!",
          TalkActionId = {
            [1] = "700328:Give",
            [2] = "700326:Confident_End"
          }
        },
        [51104030] = {
          ContentTC = "吃桂花糕咯！",
          DialogueId = 51104030,
          GUID = "7FEEFEEC",
          Scripts = [[
PARA{
MoveTo{ActorId{700327},TargetPoint{"P51104030XiaoWu"},MoveSpeed{220},Visibility{"Show"}},
MoveTo{ActorId{700326},TargetPoint{"P51104030XiaoWen"},MoveSpeed{220},Visibility{"Show"}}
}]],
          SpeakNpcId = 700327,
