        },
        [51105048] = {
          ContentTC = "今日前來，有什麼急事嗎，還是身體不適，需我以枯榮之術醫治？",
          DialogueId = 51105048,
          GUID = "7FEF3BF4",
          NextDialogue = 51105049,
          SpeakNpcId = 700330,
          Subtitle = "Do you come on urgent business, or has some affliction led you here — that I might tend to it with the Art of Ephemerality?"
        },
        [51105049] = {
          ContentTC = "你將靈靈的事情告知扶疏。",
          DialogueId = 51105049,
          GUID = "7FEF3C1E",
          IsBlack = 1,
          NextDialogue = 51105050,
          Subtitle = "You tell Fushu all about Lingling."
        },
        [51105050] = {
          ContentTC = "竟是如此……這種牽掛家人的心情，我倒是十分理解。既然需要我的援手，我自然沒有二話。",
          DialogueId = 51105050,
          GUID = "7FEF3C48",
          NextDialogue = 51105051,
          SpeakNpcId = 700330,
          Subtitle = "I see... Such longing for one's kin — it is a feeling I know well. You have asked my aid, and so you shall have it.",
          TalkActionId = {
            [1] = "700330:Confident_End"
          }
        },
        [51105051] = {
          ContentTC = "只是……我現在有些放不下的要緊事，無法前往那女孩身邊",
          DialogueId = 51105051,
          GUID = "7FEF3C72",
          NextDialogue = 51105052,
          SpeakNpcId = 700330,
          Subtitle = "However... there are matters I cannot set aside at present, and thus I cannot accompany the girl myself."
        },
        [51105052] = {
          ContentTC = "但我可以在一件物品上施以祝由秘法，最好是和那無由生與女孩都有關聯的東西，只要她帶在身上就能看見無由生。",
          DialogueId = 51105052,
          GUID = "7FEF3C9C",
          NextDialogue = 51105053,
          SpeakNpcId = 700330,
          Subtitle = "But I can weave the Art of Zhuyou into an object — ideally one tied to both the child and the Wishen. So long as she keeps it with her, she shall be able to see the Wishen.",
          TalkActionId = {
            [1] = "700330:Explain02_Start"
          }
        },
        [51105053] = {
          ContentTC = "若你有頭緒，就請把東西交予我施法，如何？",
          DialogueId = 51105053,
          GUID = "7FEF3CC6",
          NextDialogue = 51105054,
          SpeakNpcId = 700330,
          Subtitle = "If you have such an item in mind, bring it to me — and I shall begin the process. Will that suffice?"
        },
        [51105054] = {
          ContentTC = "當然好，辛苦你了，扶疏。",
          DialogueId = 51105054,
          GUID = "7FEF3CF0",
          SpeakNpcId = 100001,
          Subtitle = "Of course. Thank you, Fushu."
        },
        [51105055] = {
          ContentTC = "這些應該夠了，回去找扶疏吧。",
          DialogueId = 51105055,
          GUID = "7FEF3D1A",
          SpeakNpcId = 100001,
          Subtitle = "That should do it. Time to give them to Fushu."
