          NextDialogue = 51115003,
          SpeakNpcId = 701019,
          Subtitle = "Huh!?",
          TalkActionId = {
            [1] = "701019:Shock_Start"
          }
        },
        [51115003] = {
          ContentTC = "你、你聽到什麼了？",
          DialogueId = 51115003,
          GUID = "7FF6072E",
          NextDialogue = 51115004,
          SpeakNpcId = 701019,
          Subtitle = "H—How much did you hear!?",
          TalkActionId = {
            [1] = "701019:Shock_End"
          }
        },
        [51115004] = {
          ContentTC = "聽到你在盤算做一些壞事。",
          DialogueId = 51115004,
          GUID = "7FF60758",
          NextDialogue = 51115005,
          SpeakNpcId = 100001,
          Subtitle = "Enough to know you're plotting something dodgy.",
          TalkActionId = {
            [1] = "701019:Explain01_Start"
          }
        },
        [51115005] = {
          ContentTC = "才不是壞事呢，我是要報仇！",
          DialogueId = 51115005,
          GUID = "7FF60782",
          NextDialogue = 51115006,
          SpeakNpcId = 701019,
          Subtitle = "Nah-uh — it's revenge!"
