        [51115006] = {
          ContentTC = "報什麼仇？找誰報仇？",
          DialogueId = 51115006,
          GUID = "7FF607AC",
          NextDialogue = 51115007,
          SpeakNpcId = 100001,
          Subtitle = "Revenge? For what? And on whom?"
        },
        [51115007] = {
          ContentTC = "我們商隊的貨品供應商呀！跟他們合作真是氣死人啦！",
          DialogueId = 51115007,
          GUID = "7FF607D6",
          NextOptions = {
            [1] = 51115008,
            [2] = 51115009
          },
          SpeakNpcId = 701019,
          Subtitle = "Our caravan's suppliers! Working with them is enough to make anyone lose their mind!",
          TalkActionId = {
            [1] = "701019:Explain01_End"
          }
        },
        [51115008] = {
          ContentTC = "工作中難免有糟心事，氣壞自己就得不償失了，還是放寬心吧。",
          DialogueId = 51115008,
          GUID = "7FF60800",
          ImprPlusId = 1209,
          NextDialogue = 51115010,
          Subtitle = "Work always has its headaches. Don't let it eat you up — try to take it easy."
        },
        [51115009] = {
          ContentTC = "如果有人欺負你，大風九章應該會懲罰他們吧？",
          DialogueId = 51115009,
          GUID = "7FF6082A",
          ImprPlusId = 1208,
          NextDialogue = 51115010,
          Subtitle = "If they're mistreating you, shouldn't the Nine Chapters of Dafeng deal with them?"
        },
        [51115010] = {
          ContentTC = "嗨呀，你是不知道，這些人狡猾的很！",
          DialogueId = 51115010,
          GUID = "7FF60854",
          NextDialogue = 51115011,
          SpeakNpcId = 701019,
          Subtitle = "You've no idea — those people are slippery as eels!",
          TalkActionId = {
            [1] = "701019:Talk01_Start"
          }
        },
        [51115011] = {
          ContentTC = "開工的時候吧，總是說著什麼「相信貴方的實力」、「能力越大責任越大」，然後把困難的部分「讓」給我們做。",
          DialogueId = 51115011,
          GUID = "7FF6087E",
          NextDialogue = 51115012,
          SpeakNpcId = 701019,
          Subtitle = "At first it's all \"we trust your abilities\", \"let the most capable take the lead\" — and somehow we end up doing all the hard bits."
        },
        [51115012] = {
          ContentTC = "出了岔子呢，又總是念著「唇齒相依」、「同舟共濟」云云，支使我們幫忙收拾爛攤子，給他們善後。",
          DialogueId = 51115012,
          GUID = "7FF608A8",
          NextDialogue = 51115013,
          SpeakNpcId = 701019,
          Subtitle = "And the moment something goes wrong, suddenly it's \"we're all in this together\", \"we rely on each other\" — and they dump the whole mess back on us to fix."
        },
        [51115013] = {
          ContentTC = "要是拒絕這些呀，他們就會鬧彆扭，在各種地方偷懶，雖然誰都看得出是故意的，但這種事情也沒法證明……",
          DialogueId = 51115013,
          GUID = "7FF608D2",
          NextDialogue = 51115014,
          SpeakNpcId = 701019,
          Subtitle = "If you refuse, they start dragging their feet — obviously on purpose — but there's no way to prove it..."
        },
        [51115014] = {
          ContentTC = "當面問的話，他們就會裝出一副特別愧疚的樣子，連聲說「真是太對不住了下次一定注意」之類的鬼話……真是氣煞我也！",
          DialogueId = 51115014,
          GUID = "7FF608FC",
          NextDialogue = 51115015,
          SpeakNpcId = 701019,
          Subtitle = "Ask them outright and they switch to \"oh we're so sorry\", \"it won't happen again, promise\" — utter rubbish! It drives me up the wall!",
          TalkActionId = {
            [1] = "701019:Talk01_End"
          }
        },
        [51115015] = {
          ContentTC = "要不換一家合作呢？",
          DialogueId = 51115015,
          GUID = "7FF60926",
          NextDialogue = 51115016,
          SpeakNpcId = 100001,
          Subtitle = "Why not just work with someone else?"
        },
        [51115016] = {
          ContentTC = "我倒是想……可是我們商隊進的貨品比較罕有，只有這一家能供應。",
          DialogueId = 51115016,
          GUID = "7FF60950",
          NextDialogue = 51115017,
          SpeakNpcId = 701019,
          Subtitle = "I'd love to... but the stuff we deal in is rare. They're the only ones who can get hold of it.",
          TalkActionId = {
            [1] = "701019:Talk02_Start"
          }
        },
        [51115017] = {
          ContentTC = "不過，我是不會就這麼忍著的！我已經在寫復仇計劃了，待我準備妥當，定要叫那幫老東西跪下求饒，呵呵呵……",
          DialogueId = 51115017,
          GUID = "7FF6097A",
          NextDialogue = 51115018,
          SpeakNpcId = 701019,
          Subtitle = "Still, I'm not putting up with it! I've already started drafting my revenge plan — once I'm done, those old geezers will be begging on their knees. Heh-heh..."
        },
        [51115018] = {
          ContentTC = "具體什麼計劃？",
          DialogueId = 51115018,
          GUID = "7FF609A4",
          NextDialogue = 51115019,
          SpeakNpcId = 100001,
          Subtitle = "And what exactly are you planning?"
        },
        [51115019] = {
          ContentTC = "可多啦，我給你念幾條——",
          DialogueId = 51115019,
          GUID = "7FF609CE",
          NextDialogue = 51115020,
          SpeakNpcId = 701019,
          Subtitle = "Oh, loads! Let me read you a few:"
        },
        [51115020] = {
          ContentTC = "一，把他們的桌子砍掉一截腿，讓他們沒法平穩地寫字！",
          DialogueId = 51115020,
          GUID = "7FF609F8",
          NextDialogue = 51115021,
          SpeakNpcId = 701019,
          Subtitle = "First — shave a bit off one of their desk legs so the whole thing wobbles!"
        },
        [51115021] = {
          ContentTC = "二，在他們的茶里放瀉藥，讓他們上不了班！",
          DialogueId = 51115021,
          GUID = "7FF60A22",
          NextDialogue = 51115022,
          SpeakNpcId = 701019,
          Subtitle = "Second — slip some laxatives into their tea so they can't make it to work!"
        },
        [51115022] = {
          ContentTC = "三，在他們祈求財運的盆栽里澆開水，讓他們發不了財！",
          DialogueId = 51115022,
          GUID = "7FF60A4C",
          NextDialogue = 51115023,
          SpeakNpcId = 701019,
          Subtitle = "Third — pour boiling water into the pot of their wealth plants, so their luck dries up and they start losing money!",
          TalkActionId = {
            [1] = "701019:Talk02_End"
          }
        },
        [51115023] = {
          ContentTC = "……聽起來都沒有什麼殺傷力。而且，這些應該也是大風九章禁止的內容吧？",
          DialogueId = 51115023,
          GUID = "7FF60A76",
          NextDialogue = 51115024,
          SpeakNpcId = 100001,
          Subtitle = "...None of that sounds particularly harmful. And I'm pretty sure the Nine Chapters forbid things like that."
        },
        [51115024] = {
          ContentTC = "不然你以為我為什麼還沒行動！不過無妨，這都還只是初稿呢。",
          DialogueId = 51115024,
          GUID = "7FF60AA0",
          NextDialogue = 51115025,
          SpeakNpcId = 701019,
          Subtitle = "I know! Why do you think I haven't done any of it yet? Anyway, it's only a draft.",
          TalkActionId = {
            [1] = "701019:Think_Start"
          }
        },
        [51115025] = {
          ContentTC = "古語有云：「勤能補拙」！只要我寫得足夠多，一定可以發現一個能完美地躲過大風九章的復仇方法。",
          DialogueId = 51115025,
          GUID = "7FF60ACA",
          NextDialogue = 51115026,
          SpeakNpcId = 701019,
          Subtitle = "As the old saying goes: \"Diligence makes up for dull wits\"! If I write down enough ideas, I'm bound to think of a revenge plan that slips past the Nine Chapters!"
        },
        [51115026] = {
          ContentTC = "你看，我已經寫了這麼多了！",
          DialogueId = 51115026,
          GUID = "7FF60AF4",
          NextDialogue = 51115027,
          SpeakNpcId = 701019,
          Subtitle = "Look — I've already filled this much!",
          TalkActionId = {
            [1] = "701019:Think_End"
          }
        },
        [51115027] = {
          ContentTC = "（少女翻動著手中的簿子——用黑色墨水寫就的字跡力透紙背，據你目測足足有七八十頁。）",
          DialogueId = 51115027,
          GUID = "7FF60B1E",
          NextDialogue = 51115028,
          Subtitle = "(She flips through the notebook. The writing is pressed so hard the ink has bled straight through the pages. By your guess, there must be seventy or eighty of them.)"
