        [51115031] = {
          ContentTC = "古語有云：「君子報仇，十年不晚」！",
          DialogueId = 51115031,
          GUID = "7FF60BC6",
          NextDialogue = 51115032,
          SpeakNpcId = 701019,
          Subtitle = "They say revenge is a dish best served cold!"
