        [51115033] = {
          ContentTC = "你怎麼知道？！",
          DialogueId = 51115033,
          GUID = "7FF60C1A",
          NextDialogue = 51115034,
          SpeakNpcId = 701019,
          Subtitle = "How did you know!?",
          TalkActionId = {
            [1] = "701019:Shock_Start"
          }
        },
        [51115034] = {
          ContentTC = "上一個欺負我的供貨商就是在我的復仇計劃寫到一半的時候散伙了。",
          DialogueId = 51115034,
          GUID = "7FF60C44",
          NextDialogue = 51115035,
          SpeakNpcId = 701019,
          Subtitle = "The last supplier who pushed me around shut down halfway through my revenge plan!",
          TalkActionId = {
            [1] = "701019:Shock_End"
          }
