        [51115035] = {
          ContentTC = "所以你真正的計劃其實是把他們熬死嗎……",
          DialogueId = 51115035,
          GUID = "7FF60C6E",
          NextDialogue = 51115036,
          SpeakNpcId = 100001,
          Subtitle = "So your real plan is... just outlasting them?"
        },
        [51115036] = {
          ContentTC = "那還能怎麼辦嘛，我腦子比較笨，只能靠日積月累了。古語有云：「不積跬步，無以至千里」！",
          DialogueId = 51115036,
          GUID = "7FF60C98",
          NextOptions = {
            [1] = 51115037,
            [2] = 51115042,
            [3] = 51115045
          },
          SpeakNpcId = 701019,
          Subtitle = "What else can I do? I'm not very clever — I just have to keep at it. As the old saying goes: \"Slow and steady wins the race.\" So I'll just keep writing!"
        },
        [51115037] = {
          ContentTC = "你可以去找止流尋求幫助。",
          DialogueId = 51115037,
          GUID = "7FF60CC2",
          ImprPlusId = 1207,
          NextDialogue = 51115038,
          Subtitle = "You could ask Zhiliu for help."
