        [51115038] = {
          ContentTC = "止、止流大當家？！不不不，她那麼忙，哪有時間聽我訴苦呢……",
          DialogueId = 51115038,
          GUID = "7FF60CEC",
          NextDialogue = 51115039,
          SpeakNpcId = 701019,
          Subtitle = "P—Proprietress Zhiliu!? No, no — absolutely not... She's far too busy to listen to me whinge..."
        },
        [51115039] = {
          ContentTC = "我認識她，其實她人很和善，也很關心你們這些行商。",
          DialogueId = 51115039,
          GUID = "7FF60D16",
          NextDialogue = 51115040,
          SpeakNpcId = 100001,
          Subtitle = "I know her. She's very kind — and she really does care about traders like you."
        },
        [51115040] = {
          ContentTC = "真的嗎……？那我考慮考慮，打打腹稿……",
          DialogueId = 51115040,
          GUID = "7FF60D40",
          NextDialogue = 51115041,
          SpeakNpcId = 701019,
          Subtitle = "Really...? Then... I'll think about it... Maybe practise what to say first..."
