        [51116020] = {
          ContentTC = "呦——！！",
          DialogueId = 51116020,
          GUID = "7FF6AE08",
          NextDialogue = 51116021,
          SpeakNpcName = "UI_CMNpc_Yanjindu_Name_Deer",
          Subtitle = "Brrh—!!"
