        [51117004] = {
          ContentTC = "我說什麼？",
          DialogueId = 51117004,
          GUID = "7FF74F78",
          NextDialogue = 51117005,
          Subtitle = "Huh?"
        },
        [51117005] = {
          ContentTC = "你說那個白色的影子到底是什麼？",
          DialogueId = 51117005,
          GUID = "7FF74FA2",
          NextDialogue = 51117006,
          SpeakNpcId = 701021,
          Subtitle = "What do you think the white shadow is?",
