          }
        },
        [51117021] = {
          ContentTC = "啊……？",
          DialogueId = 51117021,
          GUID = "7FF75242",
          NextDialogue = 51117022,
          SpeakNpcId = 701021,
          Subtitle = "Huh...?"
        },
        [51117022] = {
          ContentTC = "小寵物……是說小貓小狗嗎？可是我們看到的那個影子會瞬間消失誒！",
          DialogueId = 51117022,
          GUID = "7FF7526C",
          NextDialogue = 51117023,
          SpeakNpcId = 701021,
          Subtitle = "A pet? Like a cat or a dog? But the shadow disappears so fast!",
          TalkActionId = {
            [1] = "701021:Talk02_Start"
          }
        },
        [51117023] = {
          ContentTC = "對呀，而且它有時候飛得特別快，比我們家的小貓被擀麵杖嚇得跳起來的速度還快。",
          DialogueId = 51117023,
          GUID = "7FF75296",
          NextDialogue = 51117024,
          SpeakNpcId = 701022,
          Subtitle = "Yeah! And sometimes it moves even faster than our cat when it leaps up after getting scared by the rolling pin!",
          TalkActionId = {
            [1] = "701022:Think_Start",
            [2] = "701021:Talk02_End"
          }
        },
        [51117024] = {
          ContentTC = "不信的話，你們就敲門問問看。",
          DialogueId = 51117024,
          GUID = "7FF752C0",
          NextDialogue = 51117025,
          SpeakNpcId = 100001,
          Subtitle = "If you don't believe me, you could always knock on the door and ask.",
