          DialogueId = 51118005,
          GUID = "7FF7F3B2",
          NextDialogue = 51118006,
          Subtitle = "Are you all right?"
        },
        [51118006] = {
          ContentTC = "啊，我沒事，我只是太困了……謝謝你，{性别：大哥哥|大姐姐}。",
          DialogueId = 51118006,
          GUID = "7FF7F3DC",
          LookAt = {
