        [51125815] = {
          ContentTC = "千星板是什麼？",
          DialogueId = 51125815,
          GUID = "7FFCF506",
          NextDialogue = 51125816,
          Subtitle = "What's a Stellapass?"
        },
        [51125816] = {
          ContentTC = "千星板可是咱們織星客們賴以生存的傳家寶呢！在一望無際的大海上，只有它能觀測天上的星星的方位，給船隻導航指路，怎麼都不會跑偏。",
          DialogueId = 51125816,
          GUID = "7FFCF530",
          NextDialogue = 51125817,
          SpeakNpcId = 701042,
          Subtitle = "It's the Starweavers' lifeline — a marvel our ancestors left us. Out on the open sea, it reads the stars and keeps us steady, so we never lose our course."
        },
        [51125817] = {
          ContentTC = "華胥四周的海域紊亂，沒有千星板的正確指引，織星客們很容易在亂流之間迷路，所以啊，我們每回遠航之前，都需要仔細檢查千星板的情況。",
          DialogueId = 51125817,
          GUID = "7FFCF55A",
          NextOptions = {
            [1] = 51125818,
            [2] = 51125822
          },
          SpeakNpcId = 701042,
          Subtitle = "The seas around Huaxu are wild — without the Stellapass to guide us, we'd be swept off course in no time. That's why we always carry out a full check before every long voyage."
        },
        [51125818] = {
          ContentTC = "你說的保養是什麼意思？",
          DialogueId = 51125818,
          GUID = "7FFCF584",
          NextDialogue = 51125819,
          Subtitle = "What's that \"maintenance\" you mentioned?"
        },
        [51125819] = {
          ContentTC = "保養嗎？其實就是讓機樞派的老師傅們幫咱們看看千星板是否出現一些零件鬆動之類的情況，雖然大多數情況都沒什麼問題，但是在海上航行，難免會有浪濤大時磕碰。",
          DialogueId = 51125819,
          GUID = "7FFCF5AE",
          NextDialogue = 51125820,
          SpeakNpcId = 701042,
          Subtitle = "Maintenance? It just means having the Jishu Sect masters inspect it, to see if any parts have come loose. Usually it's fine — but out at sea, with all the pitching and rolling, a few bumps are hard to avoid."
        },
        [51125820] = {
          ContentTC = "我們這種普通工匠能看出問題但不會修，只有去機樞派找有專門檢測器材的老師傅們幫著看看，但是頻率不需要太高，大概四五年一次就好。",
          DialogueId = 51125820,
          GUID = "7FFCF5D8",
          NextDialogue = 51125821,
          SpeakNpcId = 701042,
          Subtitle = "We regular mechanics can identify problems, but we can't repair them. Only the Jishu Sect has the proper tools for that. No need to trouble them too often — once every four or five years is enough."
        },
        [51125821] = {
          ContentTC = "不過即使是過去找他們，也需要給到日常測量的一些數據，方便給出更好的判斷。",
          DialogueId = 51125821,
          GUID = "7FFCF602",
          SpeakNpcId = 701042,
          Subtitle = "And when we do, we have to bring along our daily readings — it helps them make a proper assessment."
        },
        [51125822] = {
          ContentTC = "千星板在哪，我怎麼沒看到？",
          DialogueId = 51125822,
          GUID = "7FFCF62C",
          NextDialogue = 51125823,
          Subtitle = "Where's the Stellapass? I don't see it."
        },
        [51125823] = {
          ContentTC = "哈哈，笨傢伙，就在咱們腳下呀，咱們這種用來出海的大船，千星板都是裝在船艙里的，只有最大的那塊板會倒置朝向天空，方便觀測星空。",
          DialogueId = 51125823,
          GUID = "7FFCF656",
          NextDialogue = 51125824,
          SpeakNpcId = 701042,
          Subtitle = "Ha! It's right beneath our feet, silly. On ships like this, the Stellapass is built into the hold — only the main plate is turned upward to face the sky, so it can read the stars."
        },
        [51125824] = {
          ContentTC = "用你們外國人能聽懂的話來形容，大概有些像那種大型的吊燈，我們在海上的時候，每時每刻都需要有人在船艙里值班記錄千星板轉動的幅度，不然就容易偏航呢。",
          DialogueId = 51125824,
          GUID = "7FFCF680",
          SpeakNpcId = 701042,
          Subtitle = "If I had to put it in your terms, it's a bit like a massive chandelier. Out at sea, there's always someone below keeping watch on how it turns — otherwise, we'd drift off course."
        },
        [51125825] = {
          ContentTC = "沒什麼要問的。",
          DialogueId = 51125825,
          GUID = "7FFCF6AA",
          NextDialogue = 51125826,
          Subtitle = "That's all I wanted to ask."
