        [51126031] = {
          ContentTC = "我一定會成為有龍氏的，一定！",
          DialogueId = 51126031,
          GUID = "7FFD1876",
          SpeakNpcId = 701045,
          Subtitle = "I'll be a Loongscion yet — just you wait and see!"
        },
        [51126101] = {
          ContentTC = "既然如此，早知道就早些來走這流程，拿了身份，我上次那筆大單也不至於因為資金周轉不過來丟了……",
          DialogueId = 51126101,
          GUID = "7FFD23F2",
          NextDialogue = 51126102,
          SpeakNpcId = 701046,
          Subtitle = "If I'd known sooner, I would've joined right away. With EverSpring supporting me, I wouldn't have lost that big deal just for lacking a bit of capital..."
        },
        [51126102] = {
          ContentTC = "這位朋友，你也是來申請成為織星客的嗎？",
          DialogueId = 51126102,
          GUID = "7FFD241C",
          NextOptions = {
            [1] = 51126103,
            [2] = 51126107
          },
          SpeakNpcId = 701046,
          Subtitle = "Ah, my friend — are you here to apply to become a Starweaver as well?"
