        [51126110] = {
          ContentTC = "多謝你的好意，但我暫時還不打算申請。",
          DialogueId = 51126110,
          GUID = "7FFD256C",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but I don't have such plans at the moment."
        },
        [51126111] = {
          ContentTC = "沒想到成為織星客還有如此多的便利！百年春真是家大業大啊。",
          DialogueId = 51126111,
          GUID = "7FFD2596",
          NextDialogue = 51126112,
          SpeakNpcId = 701046,
          Subtitle = "I never realized being a Starweaver came with so many perks. EverSpring truly is remarkable."
