        [51126113] = {
          ContentTC = "你還真是織星客的鐵桿招牌。",
          DialogueId = 51126113,
          GUID = "7FFD25EA",
          NextDialogue = 51126114,
          Subtitle = "You're quite the spokesperson for them, you know."
        },
        [51126114] = {
          ContentTC = "你要是知道加入織星客後可以獲得百年春多大的扶持，你也會像我現在這樣的。",
