        [51127508] = {
          ContentTC = "你這酒鬼，喝多了吧？",
          DialogueId = 51127508,
          GUID = "7FFE0AC8",
          NextDialogue = 51127509,
          SpeakNpcId = 100001,
          Subtitle = "You're drunk."
        },
        [51127509] = {
          ContentTC = "我喝多？我才沒喝多，你才喝多了呢，你快回來，我和你講……嗝！嗝！嗝！我和你講蛟人……嗝！",
          DialogueId = 51127509,
          GUID = "7FFE0AF2",
          SpeakNpcId = 701066,
          Subtitle = "Me? Drunk? Nah — hic! — not me! Come here, I'll tell you all about the... hic!... the Jiao... hic!"
