          GUID = "9693A44C",
          SpeakNpcId = 920001,
          Subtitle = "Ugh, just take that and lemme off the hook!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill03"
        },
        [60149007] = {
          ContentTC = "你使那麽大勁幹啥呢！",
          DialogueId = 60149007,
          Duration = 2.5,
          GUID = "9693A476",
          SpeakNpcId = 920001,
          Subtitle = "Oww! That hurt!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01"
        },
        [60149008] = {
          ContentTC = "可惡，以後走夜路小心點！",
          DialogueId = 60149008,
          Duration = 3.2,
          GUID = "9693A4A0",
          SpeakNpcId = 920001,
          Subtitle = "Ugh, this is not over! Better watch your back at night!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02"
        },
        [60149009] = {
          ContentTC = "啊啊啊啊啊，我要生氣了！",
          DialogueId = 60149009,
          Duration = 3.4,
          GUID = "9693A4CA",
          SpeakNpcId = 920001,
          Subtitle = "RAAAARGH!! Now I'm mad!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03"
        },
        [60149010] = {
          ContentTC = "笨笨笨蛋，追不上我吧，桀桀桀桀桀桀~",
          DialogueId = 60149010,
          Duration = 6,
          GUID = "9693A4F4",
          SpeakNpcId = 920001,
          Subtitle = "You ju...ju...jumbo dumbo are too stupid to catch me! HYA-HYA-HYA!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill04"
        },
        [60149011] = {
          ContentTC = "這次是我大意了，下次我一定要把你打得抱頭大哭，嗚……",
          DialogueId = 60149011,
          Duration = 10.4,
          GUID = "9693A51E",
          SpeakNpcId = 920001,
          Subtitle = "I've mucked it all up! You'll get yours next time — just you wait! Boohoo...",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_death"
        },
        [60149012] = {
          ContentTC = "東西南北四條街，打聽打聽誰是爹，道上誰不知道我打劫皎皎的名號！",
          DialogueId = 60149012,
          Duration = 6.9,
          GUID = "9693A548",
          SpeakNpcId = 920001,
          Subtitle = "North, south, east and west! I'm your pappy and I'm da best! Ask around and you will know, give your money to this Luno!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r01"
        },
        [60149013] = {
          ContentTC = "跟我鬥，你還是太年輕了呀~",
          DialogueId = 60149013,
          Duration = 5.7,
          GUID = "9693A572",
          SpeakNpcId = 920001,
          Subtitle = "Hah, tenderfoot! You're gettin' pawned!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r02"
        },
        [60149014] = {
          ContentTC = "哼，我打打打劫皎皎可不是好惹的。",
          DialogueId = 60149014,
          Duration = 4.8,
          GUID = "9693A59C",
          SpeakNpcId = 920001,
          Subtitle = "Hmph, this Lulu Lunoloot is not someone you can mess with!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r03"
        },
        [60149015] = {
          ContentTC = "呼，呼……你咋還不累呢，吃啥玩意長大的啊。",
          DialogueId = 60149015,
          Duration = 8.8,
          GUID = "9693A5C6",
          SpeakNpcId = 920001,
          Subtitle = "Huff... huff... Ain't you tired yet? What did they feed you?",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r04"
        },
        [60150001] = {
          ContentTC = "離我遠點！",
          DialogueId = 60150001,
          Duration = 3,
          GUID = "9694478A",
          SpeakNpcId = 200053,
          Subtitle = "Back off!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack01"
        },
        [60150002] = {
          ContentTC = "非要吃點苦頭？",
          DialogueId = 60150002,
          Duration = 3,
          GUID = "969447B4",
          SpeakNpcId = 200053,
          Subtitle = "You asked for this!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack02"
        },
        [60150003] = {
          ContentTC = "我跑不動了……我投降……",
          DialogueId = 60150003,
          Duration = 5,
          GUID = "969447DE",
          SpeakNpcId = 200053,
          Subtitle = "I can't run any further... I surrender...",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Die"
        },
        [60150004] = {
          ContentTC = "別逞能了！",
          DialogueId = 60150004,
          Duration = 3,
          GUID = "96944808",
          SpeakNpcId = 200053,
          Subtitle = "Give it up!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill01"
        },
        [60150005] = {
          ContentTC = "別追了!",
          DialogueId = 60150005,
          Duration = 3,
          GUID = "96944832",
          SpeakNpcId = 200053,
          Subtitle = "Quit it!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill02"
        },
        [60150006] = {
          ContentTC = "追不上的你們！",
          DialogueId = 60150006,
          Duration = 4,
          GUID = "9694485C",
          SpeakNpcId = 200053,
          Subtitle = "No way you can catch me!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill03"
        },
        [60160001] = {
          Content = "开启锯轮攻击！（待包装）",
          DialogueId = 60160001,
          Duration = 4,
          GUID = "969AB02A",
          SpeakNpcId = 920001
        },
        [60160002] = {
          Content = "持续轰炸目标！（待包装）",
          DialogueId = 60160002,
          Duration = 4,
          GUID = "969AB054",
          SpeakNpcId = 920001
        },
        [60160003] = {
          Content = "列车，提速，狂暴模式！！（待包装）",
          DialogueId = 60160003,
          Duration = 4,
          GUID = "969AB07E",
          SpeakNpcId = 920001
        },
        [60160004] = {
          Content = "连锁型-炸弹攻击！（待包装）",
          DialogueId = 60160004,
          Duration = 4,
          GUID = "969AB0A8",
          SpeakNpcId = 920001
        },
        [60160005] = {
          Content = "追踪型-炸弹攻击！（待包装）",
          DialogueId = 60160005,
          Duration = 4,
          GUID = "969AB0D2",
          SpeakNpcId = 920001
        },
        [60170001] = {
          ContentTC = "死……死！",
          DialogueId = 60170001,
          Duration = 1.5,
          GUID = "96A118CA",
          Subtitle = "Die... DIIIEEE!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01"
        },
        [60170002] = {
          ContentTC = "吼……呃……啊啊啊啊……",
          DialogueId = 60170002,
          Duration = 1.5,
          GUID = "96A118F4",
          Subtitle = "Raaagh... Ughhh... AAAARRRGH!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill06"
        },
        [60170003] = {
          ContentTC = "嘎嗷嗷嗷……吼……吼！！",
          DialogueId = 60170003,
          Duration = 4,
          GUID = "96A1191E",
          Subtitle = "GRRRRR... Roar... ROOOAAAR!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill08"
        },
        [60180001] = {
          ContentTC = "近吾者，必罹天劫！",
          DialogueId = 60180001,
          Duration = 3,
          GUID = "9834E965",
          Subtitle = "Draw nigh, and be smitten by divine ire!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleStart"
        },
        [60180002] = {
          ContentTC = "吼————",
          DialogueId = 60180002,
          Duration = 3,
          GUID = "9834E966",
          Subtitle = "GRRRAAAUGH!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Condemn"
        },
        [60180003] = {
          ContentTC = "俱往矣……",
          DialogueId = 60180003,
          Duration = 3,
          GUID = "9834E967",
          Subtitle = "All... is naught.",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleEnd"
        },
        [60180004] = {
          ContentTC = "晦暝臨世。",
          DialogueId = 60180004,
          Duration = 4,
          GUID = "9834E968",
          Subtitle = "Behold... the world's eve falleth.",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill05"
        },
        [60180005] = {
          ContentTC = "曀曀其陰，虺虺其雷——",
          DialogueId = 60180005,
          Duration = 5,
          GUID = "9834E969",
          Subtitle = "Heavens doth blacken, thunder rolls damnation!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill06"
        },
        [60180006] = {
          ContentTC = "吼————",
          DialogueId = 60180006,
          Duration = 3,
          GUID = "9834E970",
          Subtitle = "ROOOAAAR—!",
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill07"
        },
        [60200101] = {
          ContentTC = "不好，我們被敵人發現了！",
          DialogueId = 60200101,
          Duration = 4,
          GUID = "96B46312",
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh, we've been spotted by the enemy!",
          VoiceName = "voice/$Locale$/story/0/602001/96B46312",
          bTurnOffVoice = true
        },
        [60200201] = {
          ContentTC = "發現敵人，在他們呼叫同伴前阻止他們吧。",
          DialogueId = 60200201,
          Duration = 4,
          GUID = "96B4737A",
          SpeakNpcId = 200002,
          Subtitle = "Enemies in sight; stop them before they call for backup.",
          VoiceName = "voice/$Locale$/story/0/602002/96B4737A",
          bTurnOffVoice = true
        },
        [60200301] = {
          ContentTC = "當心，敵人要去呼叫同伴了！再這樣下去就麻煩啦。",
          DialogueId = 60200301,
          Duration = 4,
          GUID = "96B483E2",
          SpeakNpcId = 200002,
          Subtitle = "Watch out, the enemy's about to call for backup! Things will get sticky if we don't nip this in the bud.",
          VoiceName = "voice/$Locale$/story/0/602003/96B483E2",
          bTurnOffVoice = true
        },
        [60200401] = {
          ContentTC = "他們要去呼叫同伴，快想想辦法阻止一下呀！",
          DialogueId = 60200401,
          Duration = 4,
          GUID = "96B4944A",
          SpeakNpcId = 200002,
          Subtitle = "They're going to call for backup! Do something! Now!",
          VoiceName = "voice/$Locale$/story/0/602004/96B4944A",
          bTurnOffVoice = true
        },
        [60200501] = {
          ContentTC = "真是的，我們躲藏得這麼好居然都被發現了，沒辦法，快點解決掉他們吧。",
          DialogueId = 60200501,
          Duration = 4,
          GUID = "96B4A4B2",
          SpeakNpcId = 200002,
          Subtitle = "Ugh, thought we hid well. Eh, let's sort them out quickly.",
          VoiceName = "voice/$Locale$/story/0/602005/96B4A4B2",
          bTurnOffVoice = true
        },
        [60210101] = {
          ContentTC = "委託人只能幫我們爭取到一點點時間，我們趁現在快把那三台奇奇怪怪的裝置拆掉吧！",
          DialogueId = 60210101,
          Duration = 4,
          GUID = "9687C88C",
          SpeakNpcId = 200002,
          Subtitle = "The client's only bought us a teeny bit of time — so let's bust those weird-looking thingies before it's too late!",
          VoiceName = "voice/$Locale$/story/0/602101/9687C88C",
          bTurnOffVoice = true
        },
        [60210201] = {
          ContentTC = "好耶，全都拆掉了，委託圓滿完成！",
          DialogueId = 60210201,
          Duration = 3,
          GUID = "9687C892",
          SpeakNpcId = 200002,
          Subtitle = "Yay! All down! Commission accomplished~!",
          VoiceName = "voice/$Locale$/story/0/602102/9687C892",
          bTurnOffVoice = true
        },
        [60210301] = {
          ContentTC = "委託人說沒時間了，我們也快撤吧！",
          DialogueId = 60210301,
          Duration = 3,
          GUID = "9687C896",
          SpeakNpcId = 200002,
          Subtitle = "The client says time's up! Let's get out of here before it gets messy!",
          VoiceName = "voice/$Locale$/story/0/602103/9687C896",
          bTurnOffVoice = true
        },
        [60220101] = {
          ContentTC = "什麼什麼，第一場比賽這就開始了嗎？",
          DialogueId = 60220101,
          Duration = 4,
          GUID = "9687C89A",
          NextDialogue = 60220102,
          SpeakNpcId = 200002,
          Subtitle = "Wait, what, the first match is starting already?",
          VoiceName = "voice/$Locale$/story/0/602201/9687C89A",
          bTurnOffVoice = true
        },
        [60220102] = {
          ContentTC = "我看看哇……第一場我們要做的是淘汰「神奇的同盟」這支隊伍的種子選手！",
          DialogueId = 60220102,
          Duration = 3,
          GUID = "9687C89E",
          NextDialogue = 60220103,
          SpeakNpcId = 200002,
          Subtitle = "Let me see… Our first task is to eliminate the star player of the \"The Fork Shakens\" team!",
          VoiceName = "voice/$Locale$/story/0/602201/9687C89E",
          bTurnOffVoice = true
        },
        [60220103] = {
          ContentTC = "但我們根本不知道其他人藏在哪嘛！去周圍找找線索吧。",
          DialogueId = 60220103,
          Duration = 3,
          GUID = "9687C8A2",
          SpeakNpcId = 200002,
          Subtitle = "But we've no idea where the others are hiding! Let's look around for clues.",
          VoiceName = "voice/$Locale$/story/0/602201/9687C8A2",
          bTurnOffVoice = true
        },
        [60220201] = {
          ContentTC = "知道他們的種子選手藏在哪了！去打敗啊不是，淘汰他們吧~",
          DialogueId = 60220201,
          Duration = 3,
          GUID = "9687C8A6",
          SpeakNpcId = 200002,
          Subtitle = "We know where their star player is hiding! Let's go defeat — oops, I mean eliminate them!",
          VoiceName = "voice/$Locale$/story/0/602202/9687C8A6",
          bTurnOffVoice = true
        },
        [60220301] = {
          ContentTC = "下場好像是個搶地盤的比賽耶，我們快過去吧。",
          DialogueId = 60220301,
          Duration = 3,
          GUID = "9687C8AA",
          SpeakNpcId = 200002,
          Subtitle = "The next round seems to be a territory battle! Let's hurry over!",
          VoiceName = "voice/$Locale$/story/0/602203/9687C8AA",
          bTurnOffVoice = true
        },
        [60220401] = {
          ContentTC = "把他們從指定區域趕走！這場比賽的勝利必將屬於我們「軍團長天下第一」。",
          DialogueId = 60220401,
          Duration = 4,
          GUID = "9687C8AE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Drive them out of the designated zone! Victory will surely belong to us, \"Chief's the Best\"!",
          VoiceName = "voice/$Locale$/story/0/602204/9687C8AE",
          bTurnOffVoice = true
        },
        [60220501] = {
          ContentTC = "軍團的驕傲，靠你們了。",
          DialogueId = 60220501,
          Duration = 4,
          GUID = "9687C8B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "The pride of the legion rests on you.",
          VoiceName = "voice/$Locale$/story/0/602205/9687C8B2",
          bTurnOffVoice = true
        },
        [60220601] = {
          ContentTC = "可惡，居然如此難纏，看來不是保留實力的時候了。",
          DialogueId = 60220601,
          Duration = 4,
          GUID = "9687C8B6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Ugh, they're so stubborn! Guess it's time to get serious.",
          VoiceName = "voice/$Locale$/story/0/602206/9687C8B6",
          bTurnOffVoice = true
        },
        [60220701] = {
          ContentTC = "雖然輸了……但下場比賽，我們還有機會！",
          DialogueId = 60220701,
          Duration = 3,
          GUID = "9687C8BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Even though we lost… there's still next round! We still have a chance!",
          VoiceName = "voice/$Locale$/story/0/602207/9687C8BA",
          bTurnOffVoice = true
        },
        [60220801] = {
          ContentTC = "終於到第三場比賽了呀，快去獎箱那裡吧，絕不能讓其他人搶走！",
          DialogueId = 60220801,
          Duration = 4,
          GUID = "9687C8BE",
          SpeakNpcId = 200002,
          Subtitle = "Finally, the third match! Quick, to the prize chest, we can't let anyone else grab it!",
          VoiceName = "voice/$Locale$/story/0/602208/9687C8BE",
          bTurnOffVoice = true
        },
        [60220901] = {
          ContentTC = "開始了開始了！從這群傢伙手裡奪回鑰匙，打開最後的寶箱吧。",
          DialogueId = 60220901,
          Duration = 3,
          GUID = "9687C8C2",
          NextDialogue = 60220902,
          SpeakNpcId = 200002,
          Subtitle = "It's starting now! Snatch the keys back from these guys and unlock the final treasure chest!",
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C2",
          bTurnOffVoice = true
        },
        [60220902] = {
          ContentTC = "一群異教徒，妄想染指神賜的寶物。準備好承受祂的怒火了嗎？",
          DialogueId = 60220902,
          Duration = 4,
          GUID = "9687C8C4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          Subtitle = "Heretics! How dare you covet treasures bestowed by the gods. Ready to face divine wrath?",
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C4",
          bTurnOffVoice = true
        },
        [60221001] = {
          ContentTC = "去吧，神最虔誠的信徒們，為祂摘下名為勝利的果實。",
          DialogueId = 60221001,
          Duration = 4,
          GUID = "9687C8C6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          Subtitle = "Go, devout followers! Pluck the fruit of victory in Its name.",
          VoiceName = "voice/$Locale$/story/0/602210/9687C8C6",
          bTurnOffVoice = true
        },
        [60221101] = {
          ContentTC = "為了軍團的榮耀，前進！",
          DialogueId = 60221101,
          Duration = 4,
          GUID = "9687C8CA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "For the glory of the legion, advance!",
          VoiceName = "voice/$Locale$/story/0/602211/9687C8CA",
          bTurnOffVoice = true
        },
        [60221201] = {
          ContentTC = "如我所料，大賽最重要的還是第三場。現在，該我們大顯身手了。",
          DialogueId = 60221201,
          Duration = 4,
          GUID = "9687C8CE",
          SpeakNpcId = 930004,
          Subtitle = "Just as I predicted — the third match is where it really counts. Now, it's our time to shine!",
          VoiceName = "voice/$Locale$/story/0/602212/9687C8CE",
          bTurnOffVoice = true
        },
        [60221301] = {
          ContentTC = "這樣就打開第一把鎖了，剩下的也繼續加油吧！",
          DialogueId = 60221301,
          Duration = 3,
          GUID = "9687C8D2",
          SpeakNpcId = 200002,
          Subtitle = "One lock opened! Keep it up, we can get the rest too!",
          VoiceName = "voice/$Locale$/story/0/602213/9687C8D2",
          bTurnOffVoice = true
        },
        [60221401] = {
          ContentTC = "寶箱開啦，好耶！是我們贏囉~",
          DialogueId = 60221401,
          Duration = 3,
          GUID = "9687C8D6",
          SpeakNpcId = 200002,
          Subtitle = "The chest is open, yayyy! We won!",
          VoiceName = "voice/$Locale$/story/0/602214/9687C8D6",
          bTurnOffVoice = true
        },
        [60221501] = {
          ContentTC = "看那邊看那邊，主辦方往賽場裡丟進來一把新鑰匙！",
          DialogueId = 60221501,
          Duration = 4,
          GUID = "9687C8DA",
          SpeakNpcId = 200002,
          Subtitle = "Look, look over there! The organizers just threw a new key into the arena!",
          VoiceName = "voice/$Locale$/story/0/602215/9687C8DA",
          bTurnOffVoice = true
        },
        [60221601] = {
          ContentTC = "為了軍團的榮耀，前進！",
          DialogueId = 60221601,
          Duration = 4,
          GUID = "9687C8DE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930005,
          Subtitle = "For the glory of the legion, advance!",
          VoiceName = "voice/$Locale$/story/0/602216/9687C8DE",
          bTurnOffVoice = true
        },
        [60230101] = {
          ContentTC = "趕快去找藥劑台吧。",
          DialogueId = 60230101,
          Duration = 4,
          GUID = "96910001",
          SpeakNpcId = 200002,
          Subtitle = "Hurry, let's find the Potion Station!",
          VoiceName = "voice/$Locale$/story/0/602301/96910001",
          bTurnOffVoice = true
        },
        [60230201] = {
          ContentTC = "對了對了，要讓藥劑台回收血清的話，就得在它附近打倒敵人才行！",
          DialogueId = 60230201,
          Duration = 4,
          GUID = "96910029",
          NextDialogue = 60230202,
          SpeakNpcId = 200002,
          Subtitle = "Oh yeah! To make the station collect the serum, we gotta defeat enemies near it!",
          VoiceName = "voice/$Locale$/story/0/602302/96910029",
          bTurnOffVoice = true
        },
        [60230202] = {
          ContentTC = "把藥劑台裝滿就能完成委託了，加油加油。",
          DialogueId = 60230202,
          Duration = 4,
          GUID = "96910191",
          SpeakNpcId = 200002,
          Subtitle = "Fill up the Potion Station to complete the commission! Go, go, go!",
          VoiceName = "voice/$Locale$/story/0/602302/96910191",
          bTurnOffVoice = true
        },
        [60230301] = {
          ContentTC = "噓……我聽到一些奇怪的動靜，好像有大傢伙要來了！",
          DialogueId = 60230301,
          Duration = 4,
          GUID = "96910321",
          SpeakNpcId = 200002,
          Subtitle = "Shh… I hear something weird, sounds like a big guy's coming!",
          VoiceName = "voice/$Locale$/story/0/602303/96910321",
          bTurnOffVoice = true
        },
        [60230401] = {
          ContentTC = "哇啊啊，有個大傢伙帶著一大片毒霧衝過來了，藥劑台裡的血清一下子就會被它侵蝕乾淨的，快解決掉它吧！",
          DialogueId = 60230401,
          Duration = 4,
          GUID = "969104B1",
          SpeakNpcId = 200002,
          Subtitle = "Whoaaa, a huge thing is charging over with Toxic Smog! It'll corrupt all the serum in the station! Take it down, quick!",
          VoiceName = "voice/$Locale$/story/0/602304/969104B1",
          bTurnOffVoice = true
        },
        [60300101] = {
          ContentTC = "噓……我好像聽到了魔靈的聲音！我們快去找一找，趕緊救它們出來吧！",
          DialogueId = 60300101,
          Duration = 4,
          GUID = "96F47952",
          SpeakNpcId = 200002,
          Subtitle = "Shh... I think I heard the crying of a Geniemon! Let's go rescue it!",
          VoiceName = "voice/$Locale$/story/0/603001/96F47952",
          bTurnOffVoice = true
        },
