          DialogueId = 71003902,
          GUID = "B1C035AC",
          SpeakNpcId = 800006
        },
        [71003903] = {
          Content = "又是齿轮响动的声音，不远处的两个通道也开启了（待包装）",
          DialogueId = 71003903,
          GUID = "B1C035D6",
          SpeakNpcId = 800006
        },
        [71003904] = {
          Content = "齿轮转动，室内的全部通道均已开启，努力击杀敌人吧（待包装）",
          DialogueId = 71003904,
          GUID = "B1C03600",
          SpeakNpcId = 800006
        },
        [71003905] = {
          Content = "所有通道均已关闭，剩余的敌人将在不久后溃散（待包装）",
          DialogueId = 71003905,
          GUID = "B1C0362A",
          SpeakNpcId = 800006
        },
        [71004101] = {
          ContentTC = "（廢棄飛艇不知何時成了山間部分動物的大號儲物箱，翻找一下也許能發現些有用的物資。）",
          DialogueId = 71004101,
          GUID = "B1C05652",
          SpeakNpcId = 800006,
          Subtitle = "(The wrecked airship looks like it's been turned into a stash by the local wildlife. There might still be something worth salvaging.)"
        },
        [71004102] = {
          ContentTC = "（翻動物資的聲響將周圍的敵人吸引了過來，擊退他們吧。）",
          DialogueId = 71004102,
          GUID = "B1C056A6",
          SpeakNpcId = 800006,
          Subtitle = "(Your rummaging noises have attracted hostile creatures nearby. Prepare to defend yourself.)"
        },
        [71004103] = {
          ContentTC = "（敵人退去，現在可以清點下你方才收集的物資了。）",
          DialogueId = 71004103,
          GUID = "B1C056D0",
          SpeakNpcId = 800006,
          Subtitle = "(With the danger cleared, you finally have time to take stock of your findings.)"
        },
        [71004201] = {
          ContentTC = "唔嗯嗯嗯嗯，好結實……",
          DialogueId = 71004201,
          GUID = "B1C066BA",
          SpeakNpcId = 818038,
          Subtitle = "Mmm-hmm... Yep. Nice and tough..."
        },
        [71004202] = {
          ContentTC = "你在幹什麼？",
          DialogueId = 71004202,
          GUID = "B1C066E4",
          NextDialogue = 71004203,
          SpeakNpcId = 100001,
          Subtitle = "What are you doing?"
        },
        [71004203] = {
          ContentTC = "我最近在研究穢獸的生態，你要不要幫我找點死掉的穢獸樣本呀。",
          DialogueId = 71004203,
          GUID = "B1C066E5",
          NextOptions = {
            [1] = 710042031,
            [2] = 710042032
          },
          SpeakNpcId = 818038,
          Subtitle = "I'm studying the local Filthoids! Could you help me gather some specimens?"
        },
        [71004204] = {
          ContentTC = "好，那就交給你了！我先休息一下，一直一個人收集樣本差點累死我……",
          DialogueId = 71004204,
          GUID = "B1C0670E",
          SpeakNpcId = 818038,
          Subtitle = "Brilliant! I'll leave the rest to you — my legs are jelly after crawling around all day..."
        },
        [71004205] = {
          ContentTC = "嗚哇哇哇，周圍怎麼還有活的穢獸呀，別過來別過來，是我研究你們不是你們研究我！",
          DialogueId = 71004205,
          GUID = "B1C06738",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 818038,
          Subtitle = "Aaaah! Why are there still live ones!? I'm the researcher here — you're the sample! Not the other way round! Shoo!"
        },
        [71004206] = {
          ContentTC = "謝啦謝啦，現在樣本集齊了，我也該去繼續研究了，下次見嘍！",
          DialogueId = 71004206,
          GUID = "B1C0678C",
          SpeakNpcId = 818038,
          Subtitle = "Thanks a bunch! That wraps up my samples. Back to the lab I go — see you around!"
        },
        [71004301] = {
          ContentTC = "（這一帶總能撿到些漂亮的貝殼，打碎那些衝上岸的箱子找找看吧。）",
          DialogueId = 71004301,
          GUID = "B1C07722",
          SpeakNpcId = 800006,
          Subtitle = "(This stretch of shoreline is known for its lovely seashells. A few crates have washed up with the tide — smash them open and see what's inside.)"
        },
        [71004302] = {
          ContentTC = "（你在箱子底部找到了些被壓住的貝殼。）",
          DialogueId = 71004302,
          GUID = "B1C0774C",
          SpeakNpcId = 800006,
          Subtitle = "(Among the debris, you uncover a few intact shells.)"
        },
        [71004303] = {
          ContentTC = "（你早就聽聞部份穢獸會躲藏在陰暗的箱子內襲擊他人，但不幸的是，這一次它們撞上你了。擊敗它們，拿到你應得的戰利品吧。）",
          DialogueId = 71004303,
          GUID = "B1C07776",
          SpeakNpcId = 800006,
          Subtitle = "(Tales speak of Filthoids hiding in crates to ambush the unwary. Looks like this batch picked the wrong target. Deal with them and claim your prize.)"
        },
        [71004401] = {
          ContentTC = "（遊蕩的穢獸擠滿了四周，先擊退它們，再去捕獲魔靈吧。）",
          DialogueId = 71004401,
          GUID = "B1C0878A",
          SpeakNpcId = 800006,
          Subtitle = "(The area is swarming with Filthoids. Clear them out to save the Geniemon.)"
        },
        [71004402] = {
          ContentTC = "（爭鬥的聲響引來了不屈的災厄，不詳的化身終於降臨於此。擊敗它吧，就像過去的無數次一樣。）",
          DialogueId = 71004402,
          GUID = "B1C087B4",
          SpeakNpcId = 800006,
          Subtitle = "(The sound of battle draws an indomitable calamity — the avatar of doom descends. Defeat it, just as you have countless times before.)"
        },
        [71004403] = {
          ContentTC = "附近暫時安全了，趁現在捕獲魔靈吧。 ）",
          DialogueId = 71004403,
          GUID = "B1C087DE",
          SpeakNpcId = 800006,
          Subtitle = "(The area is secure for now. You've saved the Geniemon!)"
        },
        [71004501] = {
          ContentTC = "（敵人站在要回收的物資前，擊敗他們吧。）",
          DialogueId = 71004501,
          GUID = "B1C097F2",
          SpeakNpcId = 800006,
          Subtitle = "(The path to the supplies is blocked. Eliminate the enemies to proceed.)"
        },
        [71004502] = {
          ContentTC = "（不詳的化身終於降臨於此，擊敗它後再回收物資吧。）",
          DialogueId = 71004502,
          GUID = "B1C0981C",
          SpeakNpcId = 800006,
          Subtitle = "(The avatar of doom descends upon the area. Defeat it to proceed.)"
        },
        [71004503] = {
          ContentTC = "（附近暫時安全了，趁現在回收所有物資吧。）",
          DialogueId = 71004503,
          GUID = "B1C09846",
          SpeakNpcId = 800006,
          Subtitle = "(The area is temporarily secure. Gather the supplies while you still can.)"
        },
        [71004601] = {
          ContentTC = "（面前擺放著大量的物資箱，打開它們搜尋有用的物資吧。）",
          DialogueId = 71004601,
          GUID = "B1C0A85A",
          SpeakNpcId = 800006,
