        [71005141] = {
          ContentTC = "看來只有一種方法能讓你說真話了。",
          DialogueId = 71005141,
          GUID = "B1C0FF78",
          SpeakNpcId = 100001,
          Subtitle = "I think I've heard enough. Time to reel the truth out of you."
        },
        [71005142] = {
          ContentTC = "我錯了我錯了，我就是看到常常有人隨便講幾句話，就把一大波人耍得團團轉，所以就想驗證一下試試……",
          DialogueId = 71005142,
          GUID = "B1C0FFA2",
          NextDialogue = 71005143,
          SpeakNpcId = 818045,
          Subtitle = "Alright, alright! You got me. I've seen how folks fall for a few smooth words and a bit of showmanship... So I figured — why not give it a try myself?"
        },
        [71005143] = {
          ContentTC = "折騰了你半天真是抱歉。這些是我的賠禮，對不起了。",
          DialogueId = 71005143,
          GUID = "B1C0FFCC",
          SpeakNpcId = 818045,
          Subtitle = "Anyway — sorry for the mischief. Here. Consider this an apology."
        },
        [71005201] = {
          ContentTC = "幸福硬幣，有魔法的幸福硬幣，大哥哥大姐姐們，來買一枚吧。",
          DialogueId = 71005201,
          GUID = "B1C10ACA",
          SpeakNpcId = 818046,
          Subtitle = "Lucky coins! Real magic lucky coins! Come get one while they last!"
        },
        [71005202] = {
          ContentTC = "（待你靠近後，女孩立刻從懷中掏出幾枚銅幣遞到了你的面前。）",
          DialogueId = 71005202,
          GUID = "B1C10AF4",
          NextDialogue = 71005203,
          SpeakNpcId = 800006,
          Subtitle = "(As you draw closer, the girl hurriedly fishes a few copper coins from her pocket and holds them out to you.)"
        },
        [71005203] = {
          ContentTC = "{性别:大哥哥|大姐姐}，你好你好，要買幸福硬幣嗎？這是媽媽留給我的，她說一枚煩惱消散，兩枚幸福常伴，三枚……三枚想做什麼都能做到！",
          DialogueId = 71005203,
          GUID = "B1C10B1E",
          NextDialogue = 71005204,
          SpeakNpcId = 818046,
          Subtitle = "Hi there, {性别:Sir|Miss}! Would you like a lucky coin? My mum gave them to me! She said — one coin takes away your worries, two keeps happiness close, and three... three can make any wish come true!"
        },
        [71005204] = {
          ContentTC = "……",
          DialogueId = 71005204,
          GUID = "B1C10B48",
          NextDialogue = 71005205,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [71005205] = {
          ContentTC = "它們都被媽媽施過魔法了，真的很有用，不騙你！不信的話你去問問其他人嘛，問完再來看看要不要買唄。去吧去吧，我就在這等你。",
          DialogueId = 71005205,
          GUID = "B1C10B49",
          SpeakNpcId = 818046,
          Subtitle = "They're really magic! Mum cast a spell on them herself — I swear I'm not lying! If you don't believe me, you can ask around! Go on! I'll be right here waiting."
        },
        [71005206] = {
          ContentTC = "（你注意到老人的腳邊擺放著幾枚幸福硬幣，於是你與他攀談了起來。）",
          DialogueId = 71005206,
          GUID = "B1C10B72",
          NextDialogue = 71005207,
          SpeakNpcId = 800006,
          Subtitle = "(You spot a few \"lucky coins\" lying at the feet of an old man. You walk over to speak with him.)"
        },
        [71005207] = {
          ContentTC = "幸福硬幣？哈哈，真有這好東西我還會在這破地方餓肚子？",
          DialogueId = 71005207,
          GUID = "B1C10B73",
          NextDialogue = 71005208,
          SpeakNpcId = 818047,
          Subtitle = "Lucky coins? Heh... If they really worked, do you think I'd still be starving out here on this street corner?"
        },
        [71005208] = {
          ContentTC = "這話不要告訴那小女孩啊。她那麼小就沒有親人了，怪可憐的……很多東西就算是假的，也能給人點盼頭，你說對吧。",
          DialogueId = 71005208,
          GUID = "B1C10B74",
          SpeakNpcId = 818047,
          Subtitle = "But don't go repeating that to the little girl, alright? She's got no family left. Poor thing... Sometimes, even when something isn't real, it still gives people something to hold on to. You get what I mean?"
        },
        [71005209] = {
          ContentTC = "（你注意到男孩手中正把玩著幾枚幸福硬幣，於是你與他攀談了起來。）",
          DialogueId = 71005209,
          GUID = "B1C10B9C",
          NextDialogue = 71005210,
          SpeakNpcId = 800006,
          Subtitle = "(You see a boy turning a few \"lucky coins\" over in his hands. You walk over to speak with him.)"
        },
        [71005210] = {
          ContentTC = "你看我左手的幸福硬幣和右手的銅幣有什麼不一樣嗎？",
