          NextDialogue = 72002302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002302] = {
          ContentTC = "花朵們都很善良，所有收到她們的人都會開心。",
          DialogueId = 72002302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400DAC",
          NextDialogue = 72002303,
          SpeakNpcId = 820000,
          Subtitle = "Flowers are so kind. They always make people smile."
        },
        [72002303] = {
          ContentTC = "是不是這些花背著我們，和收到的人說悄悄話。",
          DialogueId = 72002303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400DD6",
          NextDialogue = 72002304,
          SpeakNpcId = 820000,
          Subtitle = "Do you think they whisper little secrets to them when we're not looking?"
        },
        [72002304] = {
