        [72002602] = {
          ContentTC = "哼哼，謝謝你幫我建好了房子。",
          DialogueId = 72002602,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4403EE4",
          NextDialogue = 72002603,
          SpeakNpcId = 820000,
          Subtitle = "Mm~ Thank you for building a cabin for me."
        },
        [72002603] = {
          ContentTC = "如果哪一天你長得和我一樣高，我就邀請你住進來，我們做鄰居。",
          DialogueId = 72002603,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4403F0E",
          NextDialogue = 72002604,
          SpeakNpcId = 820000,
