          NextDialogue = 72003003,
          SpeakNpcId = 820000,
          Subtitle = "Whoa, you're amazing! Whoosh—swish—BAM! You wiped out all the rats!"
        },
        [72003003] = {
          ContentTC = "那麼，這個寶箱就送給你啦。",
