        },
        [72003402] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這裡是我的寶庫！面有通過智慧的考驗才能進入！",
          DialogueId = 72003402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C224",
          NextDialogue = 72003403,
          SpeakNpcId = 820000,
          Subtitle = "This is my treasure trove! Only those who pass the trial of wisdom may enter!"
        },
        [72003403] = {
          ContentTC = "在這座要塞裡！哪一種顏色意味著你可以通過！",
          DialogueId = 72003403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C24E",
          SpeakNpcId = 820000,
          Subtitle = "So tell me — here, in this fortress... What colour lets you through?",
          TalkOptions = {
            [1] = 72003404,
            [2] = 72003405,
            [3] = 72003406
          }
        },
        [72003404] = {
          ContentTC = "藍色！",
          DialogueId = 72003404,
          GUID = "B440C278",
          ImprPlusId = 1003,
          Subtitle = "Blue!"
        },
        [72003405] = {
          ContentTC = "紅色！",
          DialogueId = 72003405,
          GUID = "B440C2A2",
          ImprPlusId = 1016,
          Subtitle = "Red!"
        },
        [72003406] = {
          ContentTC = "橙色！",
          DialogueId = 72003406,
          GUID = "B440C2CC",
          ImprPlusId = 1016,
          Subtitle = "Orange!"
        },
        [72003407] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "沒錯！你選擇了可以通過的顏色！所以我允許你通過！",
          DialogueId = 72003407,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C2F6",
          NextDialogue = 72003409,
          SpeakNpcId = 820000,
          Subtitle = "That's right! You picked the right colour — so in you go!"
