        [72100202] = {
          ContentTC = "好似做了個久遠的美夢……",
          DialogueId = 72100202,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECB64",
          NextDialogue = 72100203,
          SpeakNpcId = 830001,
          Subtitle = "Feels like I had a long, beautiful dream..."
        },
        [72100203] = {
          ContentTC = "夢見孩提時，娘親牽著我的手去渡口買糖人。",
          DialogueId = 72100203,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECB8E",
          NextDialogue = 72100204,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I dreamed of when I was a child, holding my mother's hand, going to the wharf to buy a sugar figurine.",
          bAllowClickSkipScript = false
        },
        [72100204] = {
          DialogueId = 72100204,
          DialoguePanelType = "AllHide",
