        },
        [72100902] = {
          ContentTC = "你喜歡什麼顏色？豆綠還是鶴灰？",
          DialogueId = 72100902,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E3C",
          NextDialogue = 72100903,
          SpeakNpcId = 830001,
          Subtitle = "What's your favourite colour? Light green, or crane-gray?"
        },
        [72100903] = {
          ContentTC = "我啊，我喜歡雲水藍，就像我的身體一樣藍。",
          DialogueId = 72100903,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E66",
          NextDialogue = 72100904,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I love cloud-water blue. Just like my... body.",
          bAllowClickSkipScript = false
