          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101002] = {
          ContentTC = "塵漠鋪天蓋地，分不清方向，也辨別不了來路……",
          DialogueId = 72101002,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4EA4",
          NextDialogue = 72101003,
          SpeakNpcId = 830001,
          Subtitle = "The Gritblight blots out the sky. No sense of direction, can't even tell where I came from..."
        },
        [72101003] = {
          ContentTC = "還好有你為我指明方向。謝謝你，遠道而來的朋友。",
          DialogueId = 72101003,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4ECE",
          NextDialogue = 72101004,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Lucky to have you show me the way. Thank you, friend from afar.",
          bAllowClickSkipScript = false
        },
        [72101004] = {
