          Duration = 3,
          GUID = "C848398E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80004204,
          SpeakNpcId = 700142,
          Subtitle = "Wow... So the stone here is actually a lamp! The fog was dispersed when the lights came on.",
          VoiceName = "voice/$Locale$/story/1201/120114/C848398E"
        },
        [80004204] = {
          ContentTC = "我們再去找找別的石頭吧。",
          DialogueId = 80004204,
          Duration = 3,
          GUID = "C84839B8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let's go look for more stones.",
          VoiceName = "voice/$Locale$/story/1201/120114/C84839B8"
        },
        [80004205] = {
          ContentTC = "霧氣會讓人迷失方向，要緊跟在小夜鶯身邊才安全哦。",
          DialogueId = 80004205,
          Duration = 3,
          GUID = "C84839E2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "The fog can be disorientating, so stay close to the Little Nightingale to be safe.",
          VoiceName = "voice/$Locale$/story/1201/120114/C84839E2"
        },
        [80004206] = {
          ContentTC = "終於走出迷霧了！快看，森林的出口就在前面。",
          DialogueId = 80004206,
          Duration = 3,
          GUID = "C8483A0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Finally getting out of this foggy place! Look, the exit of the forest is just up ahead.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A0C"
        },
        [80004207] = {
          ContentTC = "走出森林之後，會見到怎樣的風景呢？好期待呀！",
          DialogueId = 80004207,
          Duration = 3,
          GUID = "C8483A36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "What wonders await beyond the forest? I can't wait to see!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A36"
        },
        [80004208] = {
          ContentTC = "咦，那是……大魔法師、獨角獸{性别:先生|小姐}和蝴蝶小姐！大家都在等我們呢。",
          DialogueId = 80004208,
          Duration = 3,
          GUID = "C8483A60",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80004209,
          SpeakNpcId = 700142,
          Subtitle = "Oh, Great Magician, {性别:Mr|Miss} Unicorn... and Miss Butterfly! Everyone is waiting for us!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A60"
        },
        [80004209] = {
          ContentTC = "小夜鶯，我們趕快過去和它們會合吧！",
          DialogueId = 80004209,
          Duration = 3,
          GUID = "C8483A8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Little Nightingale, let's go join them!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A8A"
        },
        [80004210] = {
          Camera = "-393.173828,-198.093201,117.472694,0.000079,-4.382597,17.344532,35.000008,348.827637,false,Manual,20.0",
          ContentTC = "看來這裡就是故事的終點啦！",
          DialogueId = 80004210,
          GUID = "C8483AB4",
          NextDialogue = 80004211,
          Scripts = [[
