          SpeakNpcId = 211001,
          Subtitle = "I never could've solved every puzzle without you — thank you, everyone, for guiding me all the way to the end.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483ADE"
        },
        [80004212] = {
          Camera = "-772.461914,-661.862793,33.008789,0.000118,3.216575,64.14006,35.000011,2400.0,false,Manual,20.0",
          ContentTC = "看呀，這裡有柔軟的草地，繽紛的花兒，還有拂過臉頰的暖暖的風……就讓我們舉辦一場愉快的野餐會，為這個故事畫上圓滿的結局吧！",
          DialogueId = 80004212,
          GUID = "C8483B08",
          Scripts = [[
PARA{
SEQ{
