CameraMoveTo{_delay{10.01},TargetPosition{"-254.532227,-124.837219,119.342606,0.000121,-2.983181,2.740541,35.000011,247.487625,false,Manual,20.0"},duration{0}},
CameraMoveTo{_delay{0.01},TargetPosition{"-233.603516,-126.783081,110.153168,0.000123,0.016741,3.740588,35.000011,93.779053,false,Manual,20.0"},duration{6}}
},
PlayFacial{_delay{10},ActorId{211001},FacialId{"Satisfy01"}},
PlayAnimation{_delay{4},ActorId{211001},AnimationId{"Feina_Story_Wish_Start"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Look — soft grass beneath us, flowers splashed in every color, and a warm breeze brushing our cheeks… Let's lay out a cheerful picnic right here to draw a happy ending to this story!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B08"
        },
        [80004250] = {
          ContentTC = "好像不該選這個顏色……再換一種顏料試試看吧！",
          DialogueId = 80004250,
          Duration = 3,
          GUID = "C8483B09",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Hmm… maybe this wasn't the right color — let's swap the pigment and try again!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B09"
        },
        [80004251] = {
          ContentTC = "它好像更適合另一種顏色哦。",
          DialogueId = 80004251,
          Duration = 3,
          GUID = "C8483B0A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "It looks like it's longing for a different colour.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0A"
        },
        [80004252] = {
          ContentTC = "哎呀，剛才塗好的顏色已經不見了……",
          DialogueId = 80004252,
          Duration = 3,
          GUID = "C8483B0B",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004253,
          SpeakNpcId = 700142,
          Subtitle = "Oh no, the colour I just painted is gone...",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0B"
        },
        [80004253] = {
          ContentTC = "看來要快一點塗完才行呢！",
          DialogueId = 80004253,
          Duration = 3,
          GUID = "C8483B0C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "I'll have to paint faster before the next vanish!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0C"
        },
        [80004254] = {
          Camera = "-4.021118,-147.850586,140.854248,0.000064,-3.469995,89.231857,35.0,160.025635,false,Manual,12.0",
          ContentTC = "（好像還沒有把小夜鶯的羽毛收集全......要再回去找找看嗎？）",
          DialogueId = 80004254,
          Duration = 12,
          GUID = "C8483B0D",
          Scripts = [[
