}
}]],
          SpeakNpcId = 211001,
          Subtitle = "(Still missing some feathers... Should we head back and search again?)"
        },
        [80010100] = {
          Content = "嗯，荣幸之至。",
          DialogueId = 80010100,
          GUID = "C84C0108",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0108"
        },
        [80010101] = {
          Content = "这是为了维系您与我之间的友谊，而有意为之的邀约，对吗？",
          DialogueId = 80010101,
          GUID = "C84C0132",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0132"
        },
        [80010102] = {
          Content = "好，那么我愿与您共饮。",
          DialogueId = 80010102,
          GUID = "C84C015C",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C015C"
        },
        [80010103] = {
          Content = "唔，咳……",
          DialogueId = 80010103,
          GUID = "C84C0186",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0186"
        },
        [80010104] = {
          Content = "没什么，请继续讲吧。",
          DialogueId = 80010104,
          GUID = "C84C01B0",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C01B0"
        },
        [80010105] = {
          Content = "不，只是……",
          DialogueId = 80010105,
          GUID = "C84C01DA",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C01DA"
        },
        [80010106] = {
          Content = "嗯。被您看穿了呢。",
          DialogueId = 80010106,
          GUID = "C84C0204",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0204"
        },
        [80010107] = {
          Content = "酒的味道，颇有些……浓烈。长久以来，受到家族较多管束的缘故，我极少品尝这种饮品。",
          DialogueId = 80010107,
          GUID = "C84C022E",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C022E"
        },
        [80010108] = {
          Content = "但既然您饱含诚意的邀请了，那回绝就过于失礼。",
          DialogueId = 80010108,
          GUID = "C84C0258",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0258"
        },
        [80010109] = {
          Content = "您不必为此介怀。对宾客投其所好或许是尽地主之谊的必要礼节，但适逢其时的好意本身已经足以慰藉风尘。",
          DialogueId = 80010109,
          GUID = "C84C0282",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0282"
        },
        [80010110] = {
          Content = "而且，我也在逐步学会适应“外面的一切”。",
          DialogueId = 80010110,
          GUID = "C84C02AC",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C02AC"
        },
        [80010111] = {
          Content = "第一次抵达北境的时候，在冰天雪地的荒原上，也曾有一位年迈的猎人给了我同样的东西。",
          DialogueId = 80010111,
          GUID = "C84C02D6",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C02D6"
        },
        [80010112] = {
          Content = "“烈酒”。",
          DialogueId = 80010112,
          GUID = "C84C0300",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0300"
        },
        [80010113] = {
          Content = "远比您调制的这杯更辛辣，更苦涩，甚至让人难以保持清醒的意志。",
          DialogueId = 80010113,
          GUID = "C84C032A",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C032A"
        },
        [80010114] = {
          Content = "但却非常温暖。像一小簇火苗，让几乎冻僵的我们再次有了活着的知觉。",
          DialogueId = 80010114,
          GUID = "C84C0354",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0354"
        },
        [80010115] = {
          Content = "是的，这没什么值得隐瞒的。",
          DialogueId = 80010115,
          GUID = "C84C037E",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C037E"
        },
        [80010116] = {
          Content = "您这个玩笑……我并不觉得非常有趣。",
          DialogueId = 80010116,
          GUID = "C84C03A8",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03A8"
        },
        [80010117] = {
          Content = "我是一名漂泊之人，如您所见。",
          DialogueId = 80010117,
          GUID = "C84C03D2",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03D2"
        },
        [80010118] = {
          Content = "也许您已经从希尔妲那里听说过，我们的故土，是迪斯玛尼亚——也许您会更加熟悉它的另一个称呼，“皇都”。",
          DialogueId = 80010118,
          GUID = "C84C03FC",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03FC"
        },
        [80010119] = {
          Content = "在那里，我和家族发生了一些冲突，致使流落至此。",
          DialogueId = 80010119,
          GUID = "C84C0426",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0426"
        },
        [80010120] = {
          Content = "请谅解。您是与我订立过重要契约的人，按照礼节，我本应坦诚以待。",
          DialogueId = 80010120,
          GUID = "C84C0450",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0450"
        },
        [80010121] = {
          Content = "但关于这件事，请容许我保守秘密——",
          DialogueId = 80010121,
          GUID = "C84C047A",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C047A"
        },
        [80010122] = {
          Content = "我对您虽无戒备之心，但出于对您安全的顾虑，还是建议您不要牵涉过深为好。",
          DialogueId = 80010122,
          GUID = "C84C04A4",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C04A4"
        },
        [80010123] = {
          Content = "时间有些迟了，谢谢您今日的邀请。回见。",
          DialogueId = 80010123,
          GUID = "C84C04CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C04CE"
        },
        [80010201] = {
          Content = "与您共度的时光称得上令人欢悦，虽然我还不能很好地适应它的味道。",
          DialogueId = 80010201,
          GUID = "C84C119A",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C119A"
        },
        [80010202] = {
          Content = "嗯……的确没有呢。",
          DialogueId = 80010202,
          GUID = "C84C11C4",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C11C4"
        },
        [80010203] = {
          Content = "请不要误会，我并非在对您的邀约敷衍了事。",
          DialogueId = 80010203,
          GUID = "C84C11EE",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C11EE"
        },
        [80010204] = {
          Content = "只是希尔妲不允许我对食物拥有偏好。她每日都会要求厨师奉上和此前完全不同的菜肴，而这些餐点里，喜爱的也好，厌弃的也好，她都会要求我一视同仁地品尝。",
          DialogueId = 80010204,
          GUID = "C84C1218",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1218"
        },
        [80010205] = {
          Content = "久而久之，我也就没有什么“喜爱的味道”了。",
          DialogueId = 80010205,
          GUID = "C84C1242",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1242"
        },
        [80010206] = {
          Content = "呵呵……您或许误解她了。她不是无礼之徒，此举也绝非傲慢地越俎代庖。",
          DialogueId = 80010206,
          GUID = "C84C126C",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C126C"
        },
        [80010207] = {
          Content = "呵呵……如果您是我，想必就不会说出这样的话了。",
          DialogueId = 80010207,
          GUID = "C84C1296",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1296"
        },
        [80010208] = {
          Content = "希尔妲是个敏锐的姑娘。她非常清楚，对我而言，拥有喜好，便意味着危险。",
          DialogueId = 80010208,
          GUID = "C84C12C0",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C12C0"
        },
        [80010209] = {
          Content = "比如……我来问您一个问题。您看这杯酒——",
          DialogueId = 80010209,
          GUID = "C84C12EA",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C12EA"
        },
        [80010210] = {
          Content = "假设我喜爱浸泡了罗勒叶和迷迭香的酒，每次都会一饮而尽，",
          DialogueId = 80010210,
          GUID = "C84C1314",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1314"
        },
        [80010211] = {
          Content = "而您又是一名受雇于主，混迹于一众家仆之中，想要夺取我性命的“窥伺者”，",
          DialogueId = 80010211,
          GUID = "C84C133E",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C133E"
        },
        [80010212] = {
          Content = "您要如何忍住，不把那漂亮而致命的毒液涂抹在罗勒叶之上呢？",
          DialogueId = 80010212,
          GUID = "C84C1368",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1368"
        },
        [80010213] = {
          Content = "哦？我只是做个简单的比喻。难道您真的……",
          DialogueId = 80010213,
          GUID = "C84C1392",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1392"
        },
        [80010214] = {
          Content = "呵呵，别太紧张。我不会怀疑您。",
          DialogueId = 80010214,
          GUID = "C84C13BC",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C13BC"
        },
        [80010215] = {
          Content = "的确……",
          DialogueId = 80010215,
          GUID = "C84C13E6",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C13E6"
        },
        [80010216] = {
          Content = "在我身边环绕着的人……或许更应该称呼他们是兽群。",
          DialogueId = 80010216,
          GUID = "C84C1410",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1410"
        },
        [80010217] = {
          Content = "他们像是一群秃鹫，随时在等待着我停止挣扎的一刻，然后分食。",
          DialogueId = 80010217,
          GUID = "C84C143A",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C143A"
        },
        [80010218] = {
          Content = "迪斯玛尼亚的每一粒灵魂，包括我自己，都是污浊的。",
          DialogueId = 80010218,
          GUID = "C84C1464",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1464"
        },
        [80010219] = {
          Content = "呵呵……也许对您而言，漂泊在外意味着异邦的风土，喧哗而有趣的人们，焕然一新的人生。但至于我……",
          DialogueId = 80010219,
          GUID = "C84C148E",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C148E"
        },
        [80010220] = {
          Content = "陌生的土地给了我片刻喘息，但我终究要到故乡。不过，并非因为我有多怀念它。",
          DialogueId = 80010220,
          GUID = "C84C14B8",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C14B8"
        },
        [80010221] = {
          Content = "而是我全部的爱与憎恨，思念与愤怒，都在那个地方。",
          DialogueId = 80010221,
          GUID = "C84C14E2",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C14E2"
        },
        [80010222] = {
          Content = "我该走了。还有……",
          DialogueId = 80010222,
          GUID = "C84C150C",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C150C"
        },
        [80010223] = {
          Content = "尝得出，相比上次，您在调和时有意减淡了口味。",
          DialogueId = 80010223,
          GUID = "C84C1536",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1536"
        },
        [80010224] = {
          Content = "多谢您，将我的无意之言记挂在心。",
          DialogueId = 80010224,
          GUID = "C84C1560",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1560"
        },
        [80010301] = {
          Content = "尝得出，您调制饮品的手艺愈发娴熟，甚至达到了希尔妲五成的水准。",
          DialogueId = 80010301,
          GUID = "C84C2202",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2202"
        },
        [80010302] = {
          Content = "我不像希尔妲那样，擅长社交上的体面辞令。我的意思是，以她为基准的话，五成也已经很了不起了。",
          DialogueId = 80010302,
          GUID = "C84C222C",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C222C"
        },
        [80010303] = {
          Content = "如果说有什么值得特别留意的……",
          DialogueId = 80010303,
          GUID = "C84C2256",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2256"
        },
        [80010304] = {
          Content = "那就是您过于平等地糅合了所有原料，反而让人无法品尝出它的基底——也就是，调制者最想要呈现的味道。",
          DialogueId = 80010304,
          GUID = "C84C2280",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2280"
        },
        [80010305] = {
          Content = "您近日心绪也有些乱。也许，忧虑太多纷杂的事，不如选择一件最重要的，细细研磨。",
          DialogueId = 80010305,
          GUID = "C84C22AA",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22AA"
        },
        [80010306] = {
          Content = "啊……",
          DialogueId = 80010306,
          GUID = "C84C22D4",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22D4"
        },
        [80010307] = {
          Content = "杯子……粘上了……抱歉，我并非有意弄脏它。",
          DialogueId = 80010307,
          GUID = "C84C22FE",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22FE"
        },
        [80010308] = {
          Content = "只是赴约之前，我刚刚完成那幅画。没有希尔妲提醒，我忘记手指沾了些颜料。",
          DialogueId = 80010308,
          GUID = "C84C2328",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2328"
        },
        [80010309] = {
          Content = "…………",
          DialogueId = 80010309,
          GUID = "C84C2352",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2352"
        },
        [80010310] = {
          Content = "是您的话，倒无妨。",
          DialogueId = 80010310,
          GUID = "C84C237C",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C237C"
        },
        [80010311] = {
          Content = "过去吗？呵呵……如果这是真正的过去，就好了。",
          DialogueId = 80010311,
          GUID = "C84C23A6",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23A6"
        },
        [80010312] = {
          Content = "父亲、母亲……",
          DialogueId = 80010312,
          GUID = "C84C23D0",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23D0"
        },
        [80010313] = {
          Content = "其实我从未见过他们。",
          DialogueId = 80010313,
          GUID = "C84C23FA",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23FA"
        },
        [80010314] = {
          Content = "在我的居所，他们存在过的痕迹——连同他们的画像——都已经被残忍粗暴地抹去了。我只能通过老仆人的只言片语，去想象他们的样子。",
          DialogueId = 80010314,
          GUID = "C84C2424",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2424"
        },
        [80010315] = {
          Content = "年岁尚小的时候啊，我每天都在想，我总会与他们相见的。就在未来的某一天……",
          DialogueId = 80010315,
          GUID = "C84C244E",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C244E"
        },
        [80010316] = {
          Content = "到那天，我们就可以像这样，邀来最优秀的画师，来为我们画一幅家族肖像。像那些可爱的三口之家一样。",
          DialogueId = 80010316,
          GUID = "C84C2478",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2478"
        },
        [80010317] = {
          Content = "但真正到了我能够把心中所思绘制在画布上的年纪，我才知道，我画的不是过去，亦非未来。",
          DialogueId = 80010317,
          GUID = "C84C24A2",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24A2"
        },
        [80010318] = {
          Content = "而是从未存在过，将来也不会存在的……",
          DialogueId = 80010318,
          GUID = "C84C24CC",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24CC"
        },
        [80010319] = {
          Content = "“泡影”。",
          DialogueId = 80010319,
          GUID = "C84C24F6",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24F6"
        },
        [80010320] = {
          Content = "嗯。也许您早已猜到，在我记事之前，他们已经是墓园的白骨。",
          DialogueId = 80010320,
          GUID = "C84C2520",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2520"
        },
        [80010321] = {
          Content = "抱歉，我不小心自顾自地说起来了，连带您的心情也变糟糕了吧。",
          DialogueId = 80010321,
          GUID = "C84C254A",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C254A"
        },
        [80010322] = {
          Content = "您认真地准备了饮品和茶点，想必并非打算听我喋喋不休地叨念些不快的旧事。",
          DialogueId = 80010322,
          GUID = "C84C2574",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2574"
        },
        [80010323] = {
          Content = "我们来聊些其他的吧，比如珀西·巴莱德的诗集。",
          DialogueId = 80010323,
          GUID = "C84C259E",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C259E"
        },
        [80010401] = {
          Content = "……您又邀请了我呢。真是奇怪。",
          DialogueId = 80010401,
          GUID = "C84C326A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C326A"
        },
        [80010402] = {
          Content = "我认为，我并不是一个可以给您带来欢愉的攀谈对象。",
          DialogueId = 80010402,
          GUID = "C84C3294",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3294"
        },
        [80010403] = {
          Content = "我今天读了一句诗：“好奇心会杀死一只知更鸟”……",
          DialogueId = 80010403,
          GUID = "C84C32BE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C32BE"
        },
        [80010404] = {
          Content = "罢了，既然您再度问起，那么我讲一个故事吧。",
          DialogueId = 80010404,
          GUID = "C84C32E8",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C32E8"
        },
        [80010405] = {
          Content = "很久很久之前，有一个年轻的姑娘，她从出生起就住在一座黄金的牢笼里……",
          DialogueId = 80010405,
          GUID = "C84C3312",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3312"
        },
        [80010406] = {
          Content = "她似乎拥有世上的一切：她有一百顶镶着璀璨钻石的冠冕，有一百件皎洁珍珠编织的衣衫，有一百名仆人每天献上沾着晨露的鲜花……",
          DialogueId = 80010406,
          GUID = "C84C333C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C333C"
        },
        [80010407] = {
          Content = "但有一件东西是她始终得不到的：那就是黄金牢笼外的任何事物，哪怕是一滴雨，一缕风。",
          DialogueId = 80010407,
          GUID = "C84C3366",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3366"
        },
        [80010408] = {
          Content = "一个夜晚，一条陌生的龙闯进了黄金的牢笼。",
          DialogueId = 80010408,
          GUID = "C84C3390",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3390"
        },
        [80010409] = {
          Content = "她不知道那条龙硕大的身躯是如何钻进狭窄的栅栏，只知道它带来了她梦寐以求的一切——诗集，油彩，琴弦，剑术……以及她日思夜想的，牢笼之外的故事。",
          DialogueId = 80010409,
          GUID = "C84C33BA",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C33BA"
        },
        [80010410] = {
          Content = "虽然身在牢笼之中，但她却从龙带来的故事里，看到了广阔的天空，触摸到旷野的清风，奔跑在金色的麦田，听到了广场上吟游诗人的歌谣。",
          DialogueId = 80010410,
          GUID = "C84C33E4",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C33E4"
        },
        [80010411] = {
          Content = "她是如此感谢龙带给她的一切……",
          DialogueId = 80010411,
          GUID = "C84C340E",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C340E"
        },
        [80010412] = {
          Content = "直到有一天，她无意间从传言中得知，正是那条龙，在她还在襁褓中时，灭亡了她的城市，杀死了她的亲生父亲……是的，它是一条恶龙。",
          DialogueId = 80010412,
          GUID = "C84C3438",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3438"
        },
        [80010413] = {
          Content = "然后，恶龙将她锁进了这座黄金的监牢。",
          DialogueId = 80010413,
          GUID = "C84C3462",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3462"
        },
        [80010414] = {
          Content = "少女将愤怒熔铸成刺剑，等待着恶龙再次踏着月色来访，她发誓将以利刃贯穿恶龙的心脏。但最后，她却犹疑了。她颤抖着询问传言的虚实，她渴望得到错误的答案。",
          DialogueId = 80010414,
          GUID = "C84C348C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C348C"
        },
        [80010415] = {
          Content = "但恶龙却亲口承认了一切。最后，她的剑只触及恶龙坚硬的鳞片。",
          DialogueId = 80010415,
          GUID = "C84C34B6",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C34B6"
        },
        [80010416] = {
          Content = "不久之后，黄金囚笼里的吃穿用度，全部变了模样。每日奉上的鲜花，花蕾中再也不是晨露，而是毒刺。",
          DialogueId = 80010416,
          GUID = "C84C34E0",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C34E0"
        },
        [80010417] = {
          Content = "终于有一天，一位聪明的女仆想方设法找到黄金的钥匙，打开了囚笼的门……女仆对少女说，她自由了。",
          DialogueId = 80010417,
          GUID = "C84C350A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C350A"
        },
        [80010418] = {
          Content = "但是少女知道，恶龙焚城的火焰在她的心底燃烧着，记忆的余烬环绕着她，将她投入深渊。她永远不会得到自由了。",
          DialogueId = 80010418,
          GUID = "C84C3534",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3534"
        },
        [80010419] = {
          Content = "嗯，很久之后我才得知，那两场<C=#FF0000>盛大的谋杀</C>。",
          DialogueId = 80010419,
          GUID = "C84C355E",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C355E"
        },
        [80010420] = {
          Content = "从那之后，我的梦中永远是鲜血淋漓的身体，痛苦扭曲的面庞……每一晚，每一晚。",
          DialogueId = 80010420,
          GUID = "C84C3588",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3588"
        },
        [80010421] = {
          Content = "在用小刀划破自己皮肤的时候，我已经是那么痛了。那么被利剑贯穿的父亲，被埋在废墟中的母亲，该有多痛啊……",
          DialogueId = 80010421,
          GUID = "C84C35B2",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C35B2"
        },
        [80010422] = {
          Content = "呵呵，您知道吗？您眼前的芙罗拉，并不是什么优雅高贵的贵族小姐……",
          DialogueId = 80010422,
          GUID = "C84C35DC",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C35DC"
        },
        [80010423] = {
          Content = "她只是一个献祭生命也在所不惜的，复仇的恶鬼啊。",
          DialogueId = 80010423,
          GUID = "C84C3606",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3606"
        },
        [80010424] = {
          Content = "呵呵……呵呵呵。",
          DialogueId = 80010424,
          GUID = "C84C3630",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3630"
        },
        [80010425] = {
          Content = "{NickName}，我想，您拥有一位过于优秀的骑士。",
          DialogueId = 80010425,
          GUID = "C84C365A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C365A"
        },
        [80010426] = {
          Content = "贝蕾妮卡小姐，她把您护佑得多周全啊，无论是身体，还是灵魂。",
          DialogueId = 80010426,
          GUID = "C84C3684",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3684"
        },
        [80010427] = {
          Content = "“新的人生”……好漂亮的愿望，就像孩子们吹出的肥皂泡……",
          DialogueId = 80010427,
          GUID = "C84C36AE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C36AE"
        },
        [80010428] = {
          Content = "呵呵……呵呵呵。",
          DialogueId = 80010428,
          GUID = "C84C36D8",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C36D8"
        },
        [80010429] = {
          Content = "{NickName}，您真的是一个过于天真的家伙。",
          DialogueId = 80010429,
          GUID = "C84C3702",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3702"
        },
        [80010430] = {
          Content = "以至于，您可以笃定地认为，您有资格对抗我所对抗的东西。",
          DialogueId = 80010430,
          GUID = "C84C372C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C372C"
        },
        [80010431] = {
          Content = "您不知道，那是一个怎样的<C=#FF0000>“怪物”</C>……",
          DialogueId = 80010431,
          GUID = "C84C3756",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3756"
        },
        [80010432] = {
          Content = "…………",
          DialogueId = 80010432,
          GUID = "C84C3780",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3780"
        },
        [80010433] = {
          Content = "失礼了，我今天说了太多错误的言辞。",
          DialogueId = 80010433,
          GUID = "C84C37AA",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37AA"
        },
        [80010434] = {
          Content = "把这一切都忘了吧。或者，请您只当它是从某本小说里读来的传奇故事。",
          DialogueId = 80010434,
          GUID = "C84C37D4",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37D4"
        },
        [80010435] = {
          Content = "以及，不要再邀请我赴约了。这样，我还可以视您为一名值得尊敬的受托人。",
          DialogueId = 80010435,
          GUID = "C84C37FE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37FE"
        },
        [80010436] = {
          Content = "只是这样……就好。",
          DialogueId = 80010436,
          GUID = "C84C3828",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3828"
        },
        [80010501] = {
          Content = "我应该说过，请您不要再邀请我。",
          DialogueId = 80010501,
          GUID = "C84C42D2",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C42D2"
        },
        [80010502] = {
          Content = "如果事关我们的契约，谈判桌远比这里更加合适。",
          DialogueId = 80010502,
          GUID = "C84C42FC",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C42FC"
        },
        [80010503] = {
          Content = "呵……",
          DialogueId = 80010503,
          GUID = "C84C4326",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4326"
        },
        [80010504] = {
          Content = "我想，上次我已经给了您清楚的回答。",
          DialogueId = 80010504,
          GUID = "C84C4350",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4350"
        },
        [80010505] = {
          Content = "回去吧。我的前路没有过去，也没有未来。只有紧紧闭锁的漆黑深渊。",
          DialogueId = 80010505,
          GUID = "C84C437A",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C437A"
        },
        [80010506] = {
          Content = "即使是您放声呼喊，也无法将我从那里带回。",
          DialogueId = 80010506,
          GUID = "C84C43A4",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43A4"
        },
        [80010507] = {
          Content = "…………",
          DialogueId = 80010507,
          GUID = "C84C43CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43CE"
        },
        [80010508] = {
          Content = "…………",
          DialogueId = 80010508,
          GUID = "C84C43F8",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43F8"
        },
        [80010509] = {
          Content = "你……",
          DialogueId = 80010509,
          GUID = "C84C4422",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4422"
        },
        [80010510] = {
          Content = "哪来的笨蛋{性别：先生|小姐}，幼稚鬼，秽兽一样的脑袋！你以为你是什么人？传奇小说里的屠龙勇士，神眷之子？少做白日梦了！我们的契约只是要你帮我找东西，可没约定过这种事！",
          DialogueId = 80010510,
          GUID = "C84C444C",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C444C"
        },
        [80010511] = {
          Content = "你知道我的仇人是什么家伙吗？别犯蠢了，他一秒钟，一句话，就足以要你的命。",
          DialogueId = 80010511,
          GUID = "C84C4476",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4476"
        },
        [80010512] = {
          Content = "……失礼了。",
          DialogueId = 80010512,
          GUID = "C84C44A0",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44A0"
        },
        [80010513] = {
          Content = "您……在说些什么。",
          DialogueId = 80010513,
          GUID = "C84C44CA",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CA"
        },
        [80010514] = {
          Content = "我希望可以成为芙罗拉的朋友，而非仅仅是受托人。不……甚至不只是朋友，而是可以共享哀乐，共享命运的人。",
          DialogueId = 80010514,
          GUID = "C84C44CB",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CB"
        },
        [80010515] = {
          Content = "所以，如果我没有可以将芙罗拉带回的绳索，那就让我也一起跳下去吧。",
          DialogueId = 80010515,
          GUID = "C84C44CC",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CC"
        },
        [80010516] = {
          Content = "我不是什么诸神眷顾的屠龙勇者，但我可以和你一起战斗至最后一刻。",
          DialogueId = 80010516,
          GUID = "C84C44CD",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CD"
        },
        [80010517] = {
          Content = "哪怕最终你的剑折断了，至少还有人可以陪你一起躺在血泊里，而不是让你孤独一人面对死亡。",
          DialogueId = 80010517,
          GUID = "C84C44CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CE"
        },
        [80010518] = {
          Content = "…………",
          DialogueId = 80010518,
          GUID = "C84C44F4",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44F4"
        },
        [80010519] = {
          Content = "真是……愚蠢啊。",
          DialogueId = 80010519,
          GUID = "C84C451E",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C451E"
        },
        [80010520] = {
          Content = "说到这份上，我要用什么办法才能甩掉你呢……",
          DialogueId = 80010520,
          GUID = "C84C4548",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4548"
        },
        [80010521] = {
          Content = "我没有过去，也没有未来。",
          DialogueId = 80010521,
          GUID = "C84C4572",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4572"
        },
        [80010522] = {
          Content = "除了千疮百孔的灵魂，一无所有。",
          DialogueId = 80010522,
          GUID = "C84C459C",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C459C"
        },
        [80010523] = {
          Content = "既然你来了……那就和我一起，行走在鲜血淋漓的“现在”吧。",
          DialogueId = 80010523,
          GUID = "C84C45C6",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C45C6"
        },
        [80010524] = {
          Content = "直到那漆黑之物杀死我们，或者我们杀死它。",
          DialogueId = 80010524,
          GUID = "C84C45F0",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C45F0"
        },
        [80020100] = {
          ContentTC = "沒有委託的話，我們似乎不需要那麼多的閒聊。當然，如果委託的內容就是談話，那麼也沒問題，支付一點傭金，我們就可以友好相處。",
          DialogueId = 80020100,
          GUID = "C85269A8",
          SpeakNpcId = 93102,
          Subtitle = "Unless you have a task for me, we don't need to engage in much small talk. However, if your task is to have a chat, then a small service fee will buy my temporary companionship.",
          VoiceName = "voice/$Locale$/inv/Xier/001/C85269A8"
        },
        [80020201] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentTC = "呼，真羡慕您，居然有閒心邀請人來喝點什麼。",
          DialogueId = 80020201,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8527A3A",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020202,
          SpeakNpcId = 93102,
          Subtitle = "I must say, I envy you for having the leisure to throw a little tea party.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A3A"
        },
        [80020202] = {
          ContentTC = "而我呢，剛剛完成一份委託，從更北邊的地方回來。感覺渾身的骨頭都快散架啦，需要睡上一整個晚上連帶白天才能復活。",
          DialogueId = 80020202,
          GUID = "C8527A64",
          NextOptions = {
            [1] = 800202021,
            [2] = 800202022
          },
          SpeakNpcId = 93102,
          Subtitle = "I've just completed a grueling assignment up north and feel like I'm falling apart. I'll probably need a full night and day of sleep to recover.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A64"
        },
        [80020203] = {
          ContentTC = "不用，都坐下了。來上一杯再去睡覺吧。",
          DialogueId = 80020203,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527A8E",
          NextDialogue = 80020205,
          SpeakNpcId = 93102,
          Subtitle = "It's fine. I'm already seated — might as well have a drink with you before heading to bed.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A8E"
        },
        [80020204] = {
          ContentTC = "唔，要不您幫我完成一次委託試試？",
          DialogueId = 80020204,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527AB8",
          NextDialogue = 80020205,
          SpeakNpcId = 93102,
          Subtitle = "Perhaps you can handle a commission for me next time.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527AB8"
        },
        [80020205] = {
          ContentTC = "唉，下次再遇到這個雇主的委託還是直接拒絕好了。雖然給得報酬足夠多，但還是有點危險。",
          DialogueId = 80020205,
          GUID = "C8527AE2",
          NextDialogue = 80020206,
          SpeakNpcId = 93102,
          Subtitle = "Mm, maybe I should just reject further commissions from this client. The pay is good but hardly worth the danger.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527AE2"
        },
        [80020206] = {
          ContentTC = "她讓我帶著她的親筆信回到故鄉，向她的一些熱衷於暴力的親屬們遞交一封滿是髒話與挑釁的信件，好讓憤怒沖昏他們的頭腦。",
          DialogueId = 80020206,
          GUID = "C8527B0C",
          NextDialogue = 80020207,
          SpeakNpcId = 93102,
          Subtitle = "She had me deliver a rather colourful letter to her violence-prone relatives back home, designed to make them see red.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B0C"
        },
        [80020207] = {
          ContentTC = "但是身為信差的我得要在遞信結束的那一刻立刻逃走，避免被那些從來都是鼻孔朝天，沒被人罵過的暴力分子們當場射殺。",
          DialogueId = 80020207,
          FacialId = {
            [1] = "93102:Uninterested01"
          },
          GUID = "C8527B36",
          NextDialogue = 80020208,
          SpeakNpcId = 93102,
          Subtitle = "I had to bolt the second I delivered the letter; otherwise, the phrase \"shoot the messenger\" might have become more than just metaphorical — I bet those savages have never been on the receiving end of the kind words used in that letter.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B36"
        },
        [80020208] = {
          ContentTC = "然後在雪地裡走上一整夜，免得那些傢伙想在幾處必經之路上攔下我。雖然讓他們流血很簡單，但是幹掉他們也沒人給我加傭金……",
          DialogueId = 80020208,
          GUID = "C8527B60",
          NextDialogue = 80020209,
          SpeakNpcId = 93102,
          Subtitle = "Then it was a whole night's trekking through the snow to dodge ambushes. Sure, I could easily handle them, but there's no extra pay for that...",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B60"
        },
        [80020209] = {
          ContentTC = "嗯？您幹嘛瞪圓了眼睛？",
          DialogueId = 80020209,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8527B8A",
          NextOptions = {
            [1] = 800202091,
            [2] = 800202092
          },
          SpeakNpcId = 93102,
          Subtitle = "Hmm? You look astonished. What's wrong?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B8A"
        },
        [80020210] = {
          ContentTC = "那當然是的，至少現在是的。",
          DialogueId = 80020210,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527BB4",
          NextDialogue = 80020212,
          SpeakNpcId = 93102,
          Subtitle = "Of course, at least for now.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527BB4"
        },
        [80020211] = {
          ContentTC = "沒事，過去有過更危險的經歷。",
          DialogueId = 80020211,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527BDE",
          NextDialogue = 80020212,
          SpeakNpcId = 93102,
          Subtitle = "Not really. I've been through worse.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527BDE"
        },
        [80020212] = {
          ContentTC = "在我成為芙羅拉小姐的女僕之前呢，確實還短暫地幹過另外一份工作，現在的很多用得上用不上的技巧都是在那時候習得的。",
          DialogueId = 80020212,
          GUID = "C8527C08",
          NextDialogue = 80020213,
          SpeakNpcId = 93102,
          Subtitle = "Before I was Miss Flora's maid, I briefly held a different position where I acquired many of the skills I use today, whether necessary or not.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C08"
        },
        [80020213] = {
          ContentTC = "比如快速拆解槍械的方法啊、如何從花草中萃取出毒藥啊、能夠在三秒內將人擊暈又不至於有生命危險的格鬥術啊……",
          DialogueId = 80020213,
          GUID = "C8527C32",
          NextDialogue = 80020214,
          SpeakNpcId = 93102,
          Subtitle = "Like how to swiftly dismantle firearms, extract poison from plants, or knock someone out in three seconds without serious harm...",
          TalkActionId = {
            [1] = "93102:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C32"
        },
        [80020214] = {
          ContentTC = "算了，既然您身為我的長期合作對象，那麼也沒有必要向您隱瞞，實際上，我過去是一名密探。",
          DialogueId = 80020214,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C8527C5C",
          NextDialogue = 80020215,
          SpeakNpcId = 93102,
          Subtitle = "Well, you are my long-term client, so I'll just be upfront with you — I used to be an agent.",
          TalkActionId = {
            [1] = "93102:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C5C"
        },
        [80020215] = {
          ContentTC = "也有人管我們叫做特工，間諜，不過稱呼並不重要，總的來說，就是一群在陰影之中，不能以真面目示人的傢伙們。",
          DialogueId = 80020215,
          GUID = "C8527C86",
          NextDialogue = 80020216,
          SpeakNpcId = 93102,
          Subtitle = "Some called us spies. But the title doesn't matter. Essentially, we were a nameless group, always cloaked in disguise and shadow.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C86"
        },
        [80020216] = {
          ContentTC = "即便您和他們擦肩而過，您也只會覺得他們是匆忙的行路人，而實際上，他們也許正準備去製造一場混亂，或是去傳遞秘密消息。",
          DialogueId = 80020216,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527CB0",
          NextOptions = {
            [1] = 800202161,
            [2] = 800202162
          },
          SpeakNpcId = 93102,
          Subtitle = "You might brush past one on the street, thinking they're just an ordinary passerby, when in reality, they could be on their way to create chaos or deliver secret messages.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527CB0"
        },
        [80020217] = {
          ContentTC = "我也曾經有過這樣的憧憬，不過事實並非如此。",
          DialogueId = 80020217,
          FacialId = {
            [1] = "93102:Sad01"
          },
          GUID = "C8527CDA",
          NextDialogue = 80020219,
          SpeakNpcId = 93102,
          Subtitle = "I once romanticised it as well, but reality is another story.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527CDA"
        },
        [80020218] = {
          ContentTC = "嗯，聽上去很刺激，實際上困難如影隨形。",
          DialogueId = 80020218,
          FacialId = {
            [1] = "93102:Sad01"
          },
          GUID = "C8527D04",
          NextDialogue = 80020219,
          SpeakNpcId = 93102,
          Subtitle = "Indeed, it may sound exciting, but it's actually packed with challenges and risks.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D04"
        },
        [80020219] = {
          ContentTC = "大部分密探都是隸屬于軍團，沒法掙脫，只能聽從軍團的命令，甚至可能要對自己的親人痛下殺手。",
          DialogueId = 80020219,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527D2E",
          NextDialogue = 80020220,
          SpeakNpcId = 93102,
          Subtitle = "Most agents are stuck with their legion, forced to follow orders — some even involve killing their own family.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D2E"
        },
        [80020220] = {
          ContentTC = "至於我嘛，受不了這麼多條條框框，所以想了個法子逃走了。",
          DialogueId = 80020220,
          GUID = "C8527D58",
          NextDialogue = 80020221,
          SpeakNpcId = 93102,
          Subtitle = "I couldn't stand all those rules and restrictions, so I figured out a way to break free.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D58"
        },
        [80020221] = {
          ContentTC = "逃走的過程當然不是輕描淡寫，不過嘛，您的這杯飲料沒法換到我的那段經歷。",
          DialogueId = 80020221,
          FacialId = {
            [1] = "93102:Syouganai01"
          },
          GUID = "C8527D82",
          NextDialogue = 80020222,
          SpeakNpcId = 93102,
          Subtitle = "The escape was another heart-stopping story. This drink's not enough for me to share it, though.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D82"
        },
        [80020222] = {
          ContentTC = "我該睡覺啦，睡醒了還要幫芙羅拉小姐準備明天的早餐，她得有三四天沒吃到我做的甜點了。",
          DialogueId = 80020222,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527DAC",
          NextDialogue = 80020223,
          SpeakNpcId = 93102,
          Subtitle = "I should go to bed now. I'll need to prepare breakfast for Miss Flora tomorrow. It's been days since she had my dessert.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527DAC"
        },
        [80020223] = {
          ContentTC = "作為這杯飲料的答謝，到時候我也會給您分上一塊蛋糕。",
          DialogueId = 80020223,
          FacialId = {
            [1] = "93102:Satisfy01"
          },
          GUID = "C8527DD6",
          NextDialogue = 80020224,
          SpeakNpcId = 93102,
          Subtitle = "And as a thank-you for this drink, I'll save a piece of cake for you.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527DD6"
        },
        [80020224] = {
          ContentTC = "那麼，晚安。",
          DialogueId = 80020224,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527E00",
          SpeakNpcId = 93102,
          Subtitle = "Good night, then.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527E00"
        },
        [80020301] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentTC = "今天難得有一些閒置時間，可以陪您多喝幾杯。",
          DialogueId = 80020301,
          FacialId = {
            [1] = "93102:Satisfy01"
          },
          GUID = "C8528AA2",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020302,
          SpeakNpcId = 93102,
          Subtitle = "I've finally got some free time today. I'm all yours if you're up for a few more drinks.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528AA2"
        },
        [80020302] = {
          ContentTC = "等喝完後，我就打算出門逛上一逛。之前接了那麼多委託，富餘的銀幣總是有那麼幾枚的。",
          DialogueId = 80020302,
          GUID = "C8528ACC",
          NextOptions = {
            [1] = 800203021,
            [2] = 800203022
          },
          SpeakNpcId = 93102,
          Subtitle = "And after we're done here, I'm going to hit the shops — I've got some extra silver coins to squander from all those commissions I took.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528ACC"
        },
        [80020303] = {
          ContentTC = "好啊，我可以為您選幾件合身的衣服。",
          DialogueId = 80020303,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528AF6",
          NextDialogue = 80020305,
          SpeakNpcId = 93102,
          Subtitle = "Sure, I can help pick out something that suits you.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528AF6"
        },
        [80020304] = {
          ContentTC = "會啊，我還會吃飯、睡覺——很正常。",
          DialogueId = 80020304,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528B20",
          NextDialogue = 80020305,
          SpeakNpcId = 93102,
          Subtitle = "Like I'd breathe, have meals, and sleep.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B20"
        },
        [80020305] = {
          ContentTC = "逛街對我來說是最簡單直接的放鬆方式了：既不需要太多思考，還能呼吸新鮮空氣，並且還能穿著自己喜歡的衣服——我可沒多少這樣的機會。",
          DialogueId = 80020305,
          GUID = "C8528B4A",
          NextDialogue = 80020306,
          SpeakNpcId = 93102,
          Subtitle = "Shopping is my way to unwind. It's thoughtless, gets me some fresh air, and I can wear what I like — a rare opportunity for me.",
          TalkActionId = {
            [1] = "93102:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B4A"
        },
        [80020306] = {
          ContentTC = "工作的時候，我要麼穿著女僕裝，要麼是那種又厚實，口袋又多的大風衣，來裝下可能會用到的各種小工具。",
          DialogueId = 80020306,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528B74",
          NextDialogue = 80020307,
          SpeakNpcId = 93102,
          Subtitle = "At work, I'm typically in my maid's uniform or a bulky trench coat filled with pockets for various mission-essential gadgets.",
          TalkActionId = {
            [1] = "93102:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B74"
        },
        [80020307] = {
          ContentTC = "以及為了不引人注意，執行委託的時候我會把頭髮束起來，您也知道，紅色頭髮很顯眼的。",
          DialogueId = 80020307,
          GUID = "C8528B9E",
          NextDialogue = 80020308,
          SpeakNpcId = 93102,
          Subtitle = "And to keep a low profile during a mission, I'd tie up my hair. You know, red hair tends to draw unnecessary attention.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B9E"
        },
        [80020308] = {
          ContentTC = "但出門逛街的時候就不用在意這些，可以穿更加淺色的罩衫。",
          DialogueId = 80020308,
          FacialId = {
            [1] = "93102:Happy01"
          },
          GUID = "C8528BC8",
          NextDialogue = 80020309,
          SpeakNpcId = 93102,
          Subtitle = "But when I'm out shopping, I can let loose a bit and wear lighter-coloured clothes.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528BC8"
        },
        [80020309] = {
          ContentTC = "淺色的衣服會和頭髮的顏色很相襯，不過和芙羅拉小姐一起出門的時候，我會再戴一頂帽子。",
          DialogueId = 80020309,
          GUID = "C8528BF2",
          NextDialogue = 80020310,
          SpeakNpcId = 93102,
          Subtitle = "Light colours really complement my hair. Though when I'm out with Miss Flora, I still tend to wear a hat.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528BF2"
        },
        [80020310] = {
          ContentTC = "但是鞋子我會無論如何都選暗紅色的，唔，打個比方的話，就像是紅色基底的蛋糕總是要綴上些紅色莓果一樣。",
          DialogueId = 80020310,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528C1C",
          NextDialogue = 80020311,
          SpeakNpcId = 93102,
          Subtitle = "I always wear dark red shoes. You know, like a red velvet cake needs to be topped with red berries.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C1C"
        },
        [80020311] = {
          ContentTC = "再配上從織星者那裡買到的香薰呀，帶著東方紋路的首飾呀，感覺整個人的心情都會好上許多。",
          DialogueId = 80020311,
          GUID = "C8528C46",
          NextDialogue = 80020312,
          SpeakNpcId = 93102,
          Subtitle = "I'd also dab on some fragrances and wear exotic accessories from the Starweavers — they really lift my spirits.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C46"
        },
        [80020312] = {
          ContentTC = "而像您這樣，有著淺色的銀髮，就最好搭上明亮的衣服，想必也會顯得更有活力一點。",
          DialogueId = 80020312,
          GUID = "C8528C70",
          NextOptions = {
            [1] = 800203121,
            [2] = 800203122
          },
          SpeakNpcId = 93102,
          Subtitle = "With your light silver hair, you'd look more vibrant in bright colours too.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C70"
        },
        [80020313] = {
          ContentTC = "誒？我還以為很容易理解呢。",
          DialogueId = 80020313,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8528C9A",
          NextDialogue = 80020315,
          SpeakNpcId = 93102,
          Subtitle = "Hmm? I thought it was pretty straightforward.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C9A"
        },
        [80020314] = {
          ContentTC = "對吧，您也可以試試這樣。",
          DialogueId = 80020314,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528CC4",
          NextDialogue = 80020315,
          SpeakNpcId = 93102,
          Subtitle = "Right? You should try it too.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528CC4"
        },
        [80020315] = {
          ContentTC = "不過，我最初注意這些也是因為密探的工作。密探們多少都要學習一些易容術，要讓自己看起來是另外一個人。",
          DialogueId = 80020315,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8528CEE",
          NextDialogue = 80020316,
          SpeakNpcId = 93102,
          Subtitle = "Actually, my fascination with this started during my career as an agent. We had to master the art of disguise, looking completely unlike ourselves.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528CEE"
        }
      }
    end
  },
  {
    MinKey = 80020316,
    MaxKey = 80040115,
    Loader = function()
      return {
        [80020316] = {
          ContentTC = "於是我就從最基礎的開始學起，街邊賣花的小姑娘呀、首飾比衣服還重的貴婦呀、看起來會被風吹倒的老人呀，必要時還會扮演一些「公主」或者「王子」。",
          DialogueId = 80020316,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C8528D18",
          NextOptions = {
            [1] = 800203161
          },
          SpeakNpcId = 93102,
          Subtitle = "I started with the basics: playing a street flower girl, a heavy-jewelled lady, an elderly woman teetering in the breeze, and even a \"prince\" or \"princess\" at times.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D18"
        },
        [80020317] = {
          ContentTC = "是啊，只要不開口說話就不會被認出來，甚至有幾位貴族小姐送了我手帕，挺有趣的。",
          DialogueId = 80020317,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528D42",
          NextDialogue = 80020318,
          SpeakNpcId = 93102,
          Subtitle = "Mm-hmm, it was quite convincing as long as I remained silent. There were even a few noble ladies who gave me their handkerchiefs — it was adorable.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D42"
        },
        [80020318] = {
          ContentTC = "而這樣次數多了以後，我發現，當易容成其他人的時候，心情也會受到影響。甚至，一條裙子，一件耳飾，都可以是心情變好的契機。",
          DialogueId = 80020318,
          GUID = "C8528D6C",
          NextDialogue = 80020319,
          SpeakNpcId = 93102,
          Subtitle = "Over time, I realised that disguising myself as someone else could also change my mood. Even a dress or a piece of jewellery can be a factor in brightening my day.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D6C"
        },
        [80020319] = {
          ContentTC = "所以在那之後，就開始自然而然地喜歡去逛街，並且買上幾件新衣服了。",
          DialogueId = 80020319,
          GUID = "C8528D96",
          NextDialogue = 80020320,
          SpeakNpcId = 93102,
          Subtitle = "So, after that, I fell in love with shopping for new outfits.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D96"
        },
        [80020320] = {
          ContentTC = "唔，我喝完了，走吧。讓我來為您搭配一套衣服，就當是這杯飲料的謝禮了。",
          DialogueId = 80020320,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8528DC0",
          SpeakNpcId = 93102,
          Subtitle = "Well, I've finished my drink. Let's go hit the shops. I'll help you put together an outfit as a thank-you.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528DC0"
        },
        [80020401] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentTC = "謝謝邀請，嗯，謝謝。",
          DialogueId = 80020401,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8529B0A",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020402,
          SpeakNpcId = 93102,
          Subtitle = "Thanks for inviting me... Mm, thank you.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B0A"
        },
        [80020402] = {
          ContentTC = "喝完這杯，我打算去修剪一些花朵。",
          DialogueId = 80020402,
          GUID = "C8529B34",
          NextOptions = {
            [1] = 800204021,
            [2] = 800204022
          },
          SpeakNpcId = 93102,
          Subtitle = "After this drink, I'm off to trim the flowers.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B34"
        },
        [80020403] = {
          ContentTC = "其實相反，正是因為心情糟糕，所以才想要拿起剪刀。",
          DialogueId = 80020403,
          FacialId = {
            [1] = "93102:Disappoint01"
          },
          GUID = "C8529B5E",
          NextDialogue = 80020405,
          SpeakNpcId = 93102,
          Subtitle = "Quite the opposite, actually. I want to pick up the shears precisely because I'm not in the best spirits.",
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B5E"
        },
        [80020404] = {
          ContentTC = "其實並不是為了工作，而是排解壓力。",
          DialogueId = 80020404,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529B88",
          NextDialogue = 80020405,
          SpeakNpcId = 93102,
          Subtitle = "It's not about work, actually; it's more about stress relief.",
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B88"
        },
        [80020405] = {
          ContentTC = "每當我壓力太大的時候，就會想要拿起剪刀，對著看起來快要枯萎的花朵隨意來上幾下，仿佛能夠把自己不那麼振作的情緒也能剪掉。",
          DialogueId = 80020405,
          GUID = "C8529BB2",
          NextDialogue = 80020406,
          SpeakNpcId = 93102,
          Subtitle = "When I feel the pressure mounting, I find snipping away at dying flowers quite cathartic — as if I'm trimming away my own gloom.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529BB2"
        },
        [80020406] = {
          ContentTC = "怎麼？感覺奇怪嗎？這不過是一種發洩情緒的方法罷了。畢竟我也不是靠動動嘴皮子就能夠完成委託。",
          DialogueId = 80020406,
          GUID = "C8529BDC",
          NextDialogue = 80020407,
          SpeakNpcId = 93102,
          Subtitle = "I hope you wouldn't find that strange. It's just my way of blowing off steam. After all, the assignments I take normally require much more than making conversations.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529BDC"
        },
        [80020407] = {
          ContentTC = "當我還在做密探的時候，聽說過一些同僚有更加病態的壓力抒發方式。",
          DialogueId = 80020407,
          FacialId = {
            [1] = "93102:Unhappy02"
          },
          GUID = "C8529C06",
          NextDialogue = 80020408,
          SpeakNpcId = 93102,
          Subtitle = "Back when I was an agent, some of my colleagues had... let's say, darker ways of unwinding.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C06"
        },
        [80020408] = {
          ContentTC = "完成一次耗時一秒的刺殺，可能要花上一個月制定計劃，一週提前準備，一天的漫長等待。而失敗了，可能就要面對一輩子的漫長刑期。",
          DialogueId = 80020408,
          GUID = "C8529C30",
          NextDialogue = 80020409,
          SpeakNpcId = 93102,
          Subtitle = "An assassination that lasts only seconds might require a month of planning, a week of prep, and a whole day of agonising wait — and failure could mean a lifetime behind bars.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C30"
        },
        [80020409] = {
          ContentTC = "而我面臨這種壓力時，胡亂剪上那麼一兩朵花，已經是很克制的舉動了，不是嗎？",
          DialogueId = 80020409,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C8529C5A",
          NextOptions = {
            [1] = 800204091,
            [2] = 800204092
          },
          SpeakNpcId = 93102,
          Subtitle = "Considering that kind of pressure, randomly cutting several flowers seems quite mild, doesn't it?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C5A"
        },
        [80020410] = {
          ContentTC = "嗯，也不是煩心事。",
          DialogueId = 80020410,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529C84",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "Well, it's not really a bother.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C84"
        },
        [80020411] = {
          ContentTC = "您好像有點抓不住對話的重點？",
          DialogueId = 80020411,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529CAE",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "It seems you're missing the point of this conversation, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CAE"
        },
        [80020412] = {
          ContentTC = "我只是有點懷念一位，嗯……很重要的人。",
          DialogueId = 80020412,
          GUID = "C8529CD8",
          NextDialogue = 80020413,
          SpeakNpcId = 93102,
          Subtitle = "I was just thinking of... um, someone important.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CD8"
        },
        [80020413] = {
          ContentTC = "她與我同樣，也是密探，但她始終覺得我不適合這個職業。於是那時候，我就滿心想向她證明，我不僅能夠勝任，並且一定能做到最好。",
          DialogueId = 80020413,
          GUID = "C8529D02",
          NextDialogue = 80020414,
          SpeakNpcId = 93102,
          Subtitle = "She was a fellow agent, but she always thought I wasn't cut out for the job. So I made so much effort trying to prove to her that I was not only competent but exceptional.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D02"
        },
        [80020414] = {
          ContentTC = "事實證明，她才是對的。",
          DialogueId = 80020414,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8529D2C",
          NextDialogue = 80020415,
          SpeakNpcId = 93102,
          Subtitle = "In the end, it turned out she was right.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D2C"
        },
        [80020415] = {
          ContentTC = "我做不到像她那樣把任務置於最優先，不去考慮其他的一切。",
          DialogueId = 80020415,
          GUID = "C8529D56",
          NextDialogue = 80020416,
          SpeakNpcId = 93102,
          Subtitle = "I couldn't put missions above all else like she could.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D56"
        },
        [80020416] = {
          ContentTC = "不過我又多少有點慶倖，自己沒有真的和她那樣，走上另外一條道路吧。",
          DialogueId = 80020416,
          FacialId = {
            [1] = "93102:Happy01"
          },
          GUID = "C8529D80",
          NextDialogue = 80020417,
          SpeakNpcId = 93102,
          Subtitle = "Yet, there's a part of me that's relieved that I didn't end up walking her path.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D80"
        },
        [80020417] = {
          ContentTC = "之前我離開軍團的時候，和她失去了聯繫，現在在這裡的生活逐漸安穩，我有點……好奇她現在過得好不好。",
          DialogueId = 80020417,
          GUID = "C8529DAA",
          NextOptions = {
            [1] = 800204171
          },
          SpeakNpcId = 93102,
          Subtitle = "We lost touch when I left the Legion. Now that I'm settling in here, I find myself... wondering how she's doing.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DAA"
        },
        [80020418] = {
          ContentTC = "欸？嗯……",
          DialogueId = 80020418,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8529DD4",
          NextDialogue = 80020419,
          SpeakNpcId = 93102,
          Subtitle = "Huh? Well...",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DD4"
        },
        [80020419] = {
          ContentTC = "您說得對，與其在這裡打算剪上幾朵花，不如現在就去見她。",
          DialogueId = 80020419,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529DFE",
          SpeakNpcId = 93102,
          Subtitle = "You're right. Instead of trimming flowers here, perhaps I should just go see her in person.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DFE"
        },
        [80020501] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentTC = "剛剛回到這裡，您就湊上來邀我來上一杯。說，是不是偷偷學了我的密探手法，暗地裡觀察我？",
          DialogueId = 80020501,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C852AB72",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextOptions = {
            [1] = 800205011,
            [2] = 800205012
          },
          SpeakNpcId = 93102,
          Subtitle = "You approached me as soon as I returned, inviting me for a drink. Please be honest with me — have you picked up some of my old agent tricks and been keeping tabs on me?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AB72"
        },
        [80020503] = {
          ContentTC = "算了，不拿您開玩笑了。您其實是好奇我有沒有見到那位重要的人吧？",
          DialogueId = 80020503,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ABC6",
          NextDialogue = 80020504,
          SpeakNpcId = 93102,
          Subtitle = "I was only teasing you. You came over because you're curious if I've met that lady who's important to me, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABC6"
        },
        [80020504] = {
          ContentTC = "實話說，沒有。她因為一些緣由被調離了帝都，所以我只是從其他人口中打聽到了她的去向。",
          DialogueId = 80020504,
          GUID = "C852ABF0",
          NextDialogue = 80020505,
          SpeakNpcId = 93102,
          Subtitle = "Truth be told, no. She was reassigned away from the capital for certain reasons, so I've only caught snippets about her from others.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABF0"
        },
        [80020505] = {
          ContentTC = "她去了南方的一個小城，不像這裡都是冰雪，而是一個能經常曬曬太陽，聽聽樂曲的地方。",
          DialogueId = 80020505,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AC1A",
          NextDialogue = 80020506,
          SpeakNpcId = 93102,
          Subtitle = "She's in a small town in the south — nothing like the icy grip here, but a place where she can enjoy bright sunlight and some music often.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC1A"
        },
        [80020506] = {
          ContentTC = "其實我是鬆了一口氣的，因為我確實不太知道該如何面對她……但是聽起來她過得並不壞，那麼我也能夠放心了。",
          DialogueId = 80020506,
          GUID = "C852AC44",
          NextDialogue = 80020507,
          SpeakNpcId = 93102,
          Subtitle = "To be honest, I was relieved. Because I wasn't sure how I would face her... But knowing she's doing well gives me some peace of mind.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC44"
        },
        [80020507] = {
          ContentTC = "這樣一來，我和軍團、和密探這個身份的最後一絲線，終於扯斷了。",
          DialogueId = 80020507,
          GUID = "C852AC6E",
          NextOptions = {
            [1] = 800205071,
            [2] = 800205072
          },
          SpeakNpcId = 93102,
          Subtitle = "This means the last ties between me, the Legion, and my past life as an agent have finally been severed.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC6E"
        },
        [80020508] = {
          ContentTC = "嗯，是的，終於解開了。",
          DialogueId = 80020508,
          GUID = "C852AC98",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "Yes, finally.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC98"
        },
        [80020509] = {
          ContentTC = "之前會吧，現在已經完全不會了。",
          DialogueId = 80020509,
          GUID = "C852ACC2",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "The old me would, but no, not anymore.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACC2"
        },
        [80020510] = {
          ContentTC = "這個重要的人其實是我的一位至親，正是因為她的緣故，我才會想要加入軍團，也正是因為她，我才想要離開。",
          DialogueId = 80020510,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C852ACEC",
          NextDialogue = 80020511,
          SpeakNpcId = 93102,
          Subtitle = "She's actually a close family member of mine. She was the reason that I joined the Legion, and the reason I decided to leave.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACEC"
        },
        [80020511] = {
          ContentTC = "她並不希望看到我從事這份過於危險的職業，但我拼命想證明給她看，我可以做好，並且能夠為她分擔一些煩惱。",
          DialogueId = 80020511,
          GUID = "C852AD16",
          NextDialogue = 80020512,
          SpeakNpcId = 93102,
          Subtitle = "She never wanted me to stay in such a dangerous profession, but I was desperate to show her that I could handle it — maybe even share some of her burdens.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD16"
        },
        [80020512] = {
          ContentTC = "諷刺的是，我和她分別受到了保護芙羅拉小姐和除去芙羅拉小姐的任務。",
          DialogueId = 80020512,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AD40",
          NextDialogue = 800205121,
          SpeakNpcId = 93102,
          Subtitle = "It was the irony of fate that she and I received conflicting missions — hers to eliminate Miss Flora, mine to protect her.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD40"
        },
        [80020513] = {
          ContentTC = "於是我帶著芙羅拉小姐，在她的暗殺計畫開始之前就想辦法逃了出來，奔波逃亡。那時我沒精力回憶在軍團的日子，也盡力不去想和她相關的一切。",
          DialogueId = 80020513,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AD6A",
          NextDialogue = 80020514,
          SpeakNpcId = 93102,
          Subtitle = "So I took Miss Flora and fled before her assassination attempt could commence. At that time, I didn't have the leisure to dwell on my days in the Legion or anything related to her.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6A"
        },
        [80020514] = {
          ContentTC = "正是因為近期安定了一些，又有您願意聽我講這些瑣事，這件事在我心中才會越紮越深，難以忍受，最終才有了前一段時間的失態。",
          DialogueId = 80020514,
          GUID = "C852AD6B",
          NextOptions = {
            [1] = 800205141,
            [2] = 800205142
          },
          SpeakNpcId = 93102,
          Subtitle = "It's only because things have settled down recently, and you've been there for me to unload these old stories, that this whole thing had become a thorn in my heart, which led to my recent discomposure.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6B"
        },
        [80020515] = {
          ContentTC = "我唯一確定的是，遲早要面臨這場與她的徹底告別。之前的我多少在試圖逃避面對這個現實。",
          DialogueId = 80020515,
          GUID = "C852ADBE",
          NextDialogue = 80020516,
          SpeakNpcId = 93102,
          Subtitle = "What I knew for sure was that eventually, I had to confront a complete farewell with her, which was something I had been trying to run away from.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADBE"
        },
        [80020516] = {
          ContentTC = "而現在，當它來臨的時候，這種感覺並不壞，我甚至開始慶倖，終於不用再被它們糾纏了。",
          DialogueId = 80020516,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ADE8",
          NextDialogue = 80020517,
          SpeakNpcId = 93102,
          Subtitle = "Now that it's finally happened, it doesn't feel so bad. I'm even relieved that it'll no longer haunt me.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADE8"
        },
        [80020517] = {
          ContentTC = "我現在想做許多事情，修剪花朵，烘焙甜點，逛街買上七八件新裝，再跳上一支舞。",
          DialogueId = 80020517,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AE12",
          NextDialogue = 80020518,
          SpeakNpcId = 93102,
          Subtitle = "I've got so much I want to do now — trim flowers, bake a cake, shop for new outfits, maybe even dance a little.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE12"
        },
        [80020518] = {
          ContentTC = "不過，我現在最想做的事情還是謝謝您，讓我真正的擺脫了過去最掛心的一件事。",
          DialogueId = 80020518,
          GUID = "C852AE3C",
          NextOptions = {
            [1] = 800205181,
            [2] = 800205182
          },
          SpeakNpcId = 93102,
          Subtitle = "But what I want to do most at the moment is thank you for helping me truly move on.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE3C"
        },
        [80020519] = {
          ContentTC = "同時我也得告訴您，既然知曉了我的這些過去，那麼就意味著未來的某一天，軍團試圖抓捕我和芙羅拉小姐的時候，您也無法置身事外。",
          DialogueId = 80020519,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AE66",
          NextDialogue = 80020520,
          SpeakNpcId = 93102,
          Subtitle = "But I must also remind you: now that you know my past, it means that one day when the Legion comes after me and Miss Flora, you won't be able to stay out of it.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE66"
        },
        [80020520] = {
          ContentTC = "怎麼樣？怕了嗎？會不會覺得我給了您一顆包裹毒藥的蜜糖？",
          DialogueId = 80020520,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C852AE90",
          NextDialogue = 80020521,
          SpeakNpcId = 93102,
          Subtitle = "I hope you're not too scared. Do you feel like I've handed you a sugar-coated poison?",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE90"
        },
        [80020521] = {
          ContentTC = "請放心，我，希爾妲，萬能的女僕，會負起責任，一直一直在您身邊保護您的。",
          DialogueId = 80020521,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AEBA",
          SpeakNpcId = 93102,
          Subtitle = "Please rest assured that, I, Hilda, the all-capable maid, will always ensure your safety.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AEBA"
        },
        [80020522] = {
          ContentTC = "謝謝——收到來自我的感謝，很奇怪嗎？這話可是真誠的。",
          DialogueId = 80020522,
          FacialId = {
            [1] = "93102:Happy02"
          },
          GUID = "C852AE65",
          NextDialogue = 80020519,
          SpeakNpcId = 93102,
          Subtitle = "Thank you — is it so strange to hear that from me? I mean it sincerely.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE65"
        },
        [80030100] = {
          ContentTC = "寶貴的假期除了用來睡覺，與你一起度過也不錯。",
          DialogueId = 80030100,
          GUID = "C878DD68",
          Subtitle = "This holiday is precious, and spending it with you is just as enjoyable as sleeping.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C878DD68"
        },
        [80030101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "休息充足後再喝杯飲料……呼，不工作就是舒爽啊。",
          DialogueId = 80030101,
          GUID = "C858D272",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030102,
          SpeakNpcId = 94202,
          Subtitle = "Nothing beats having a refreshing drink after a good rest. It's so wonderful to have a break from work!",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D272"
        },
        [80030102] = {
          ContentTC = "哦對了，來這兒之前勤務員塞給我一個包裹，還沒拆開，讓我來看看……",
          DialogueId = 80030102,
          GUID = "C858D29C",
          NextDialogue = 80030103,
          SpeakNpcId = 94202,
          Subtitle = "Speaking of which, I got a package before I came here. Let me take a look.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D29C"
        },
        [80030103] = {
          ContentTC = "應該是我托屬下買的睡衣和助眠熏香送到了吧……嗯，待會兒就再去好好補一覺……",
          DialogueId = 80030103,
          GUID = "C858D2C6",
          NextDialogue = 80030104,
          SpeakNpcId = 94202,
          Subtitle = "This must be the pyjamas and incense my subordinate bought me as a sleep aid. Perfect, I'll go back home and take another rest.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2C6"
        },
        [80030104] = {
          ContentTC = "嗯？這是……《十三軍團駐地週邊觀賞植物優化建議書》？《為了增強士兵士氣購入娛樂設施申請函》？",
          DialogueId = 80030104,
          GUID = "C858D2F0",
          NextDialogue = 80030105,
          SpeakNpcId = 94202,
          Subtitle = "Huh? \"Proposal on the Optimisation of Ornamental Plants of the 13th Legion\"? \"Application for Purchasing Recreational Facilities to Enhance Soldiers' Morale\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2F0"
        },
        [80030105] = {
          ContentTC = "原來是工作上的事啊。雖然內容看起來沒什麼問題，但還是之後再說吧，沒人能打擾我的假期。軍團長也許可以，不過她現在不會出現在這裡。",
          DialogueId = 80030105,
          GUID = "C858D31A",
          NextOptions = {
            [1] = 800301051,
            [2] = 800301052
          },
          SpeakNpcId = 94202,
          Subtitle = "Urgh, it's always about work. Let's talk about this later. I won't let my holiday be spoiled by anything or anyone, except the Chief. But I doubt she'll show up here.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D31A"
        },
        [80030106] = {
          ContentTC = "思考出這樣實用的準則可是很不容易的。",
          DialogueId = 80030106,
          GUID = "C858D344",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "It's not easy to come up with such practical principles as these.",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D344"
        },
        [80030107] = {
          ContentTC = "可不要亂說，這怎麼能叫偷懶呢。",
          DialogueId = 80030107,
          FacialId = {
            [1] = "94202:Blink"
          },
          GUID = "C858D36E",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "Whoa, how could you call this \"slacking off\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D36E"
        },
        [80030108] = {
          ContentTC = "這是我——蘭迪·霍華德自創的「霍氏高效節能模式」，是嘔心瀝血的成果。",
          DialogueId = 80030108,
          GUID = "C858D398",
          NextDialogue = 80030109,
          SpeakNpcId = 94202,
          Subtitle = "This is the \"Howard High-Efficiency Energy-Saving Mode\", created by yours truly, Randy Howard.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D398"
        },
        [80030109] = {
          ContentTC = "休息的時候，把腦子裡和工作相關的東西摘除地一乾二淨，這樣才不會在休息結束時恐懼工作。",
          DialogueId = 80030109,
          GUID = "C858D3C2",
          NextDialogue = 80030110,
          SpeakNpcId = 94202,
          Subtitle = "When you take a break, clear your mind of all work so that you can start working again in a good mood. That way, you won't dread getting back to work.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3C2"
        },
        [80030110] = {
          ContentTC = "經過了多年的實踐和不斷地完善，非常實用。",
          DialogueId = 80030110,
          GUID = "C858D3EC",
          NextDialogue = 80030111,
          SpeakNpcId = 94202,
          Subtitle = "After years of practising and optimising this method, I've got it working perfectly.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3EC"
        },
        [80030111] = {
          ContentTC = "讓我短時間內就能想出最「節能」的辦法，來應對各種事件。",
          DialogueId = 80030111,
          GUID = "C858D416",
          NextDialogue = 80030112,
          SpeakNpcId = 94202,
          Subtitle = "This has helped me to figure out the most energy-saving solution to different problems in seconds.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D416"
        },
        [80030112] = {
          ContentTC = "就比如現在，這場另有目的的會談。",
          DialogueId = 80030112,
          GUID = "C858D417",
          NextDialogue = 80030113,
          SpeakNpcId = 94202,
          Subtitle = "Such as this conversation with an ulterior motive.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D417"
        },
        [80030113] = {
          ContentTC = "啊，你在說什麼，聽不懂呢。",
          DialogueId = 80030113,
          GUID = "80030113.0",
          NextDialogue = 80030114,
          SpeakNpcId = 790008,
          Subtitle = "Huh? I'm not following."
        },
        [80030114] = {
          ContentTC = "這時候才裝傻也太遲了吧。",
          DialogueId = 80030114,
          GUID = "C858D418",
          NextDialogue = 80030115,
          SpeakNpcId = 94202,
          Subtitle = "A bit too late to play dumb, don't you think?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D418"
        },
        [80030115] = {
          ContentTC = "……貝蕾妮卡怎麼樣了！",
          DialogueId = 80030115,
          GUID = "80030115.0",
          NextDialogue = 80030116,
          SpeakNpcId = 790008,
          Subtitle = "...Tell me, how's Berenica doing now?!"
        },
        [80030116] = {
          ContentTC = "哦？原來零號的名字叫貝蕾妮卡啊。",
          DialogueId = 80030116,
          GUID = "C858D419",
          NextDialogue = 80030117,
          SpeakNpcId = 94202,
          Subtitle = "Hah, so that's No. 0's name — Berenica.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D419"
        },
        [80030117] = {
          ContentTC = "你這時候裝傻也有點晚。",
          DialogueId = 80030117,
          GUID = "80030117.0",
          NextDialogue = 80030118,
          SpeakNpcId = 790008,
          Subtitle = "A bit late to play dumb too, I'd say."
        },
        [80030118] = {
          ContentTC = "聰明人之間說話，總是要先裝幾句傻的。",
          DialogueId = 80030118,
          GUID = "C858D41A",
          NextDialogue = 80030119,
          SpeakNpcId = 94202,
          Subtitle = "Well, playing dumb is how smart people start a conversation.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41A"
        },
        [80030119] = {
          ContentTC = "不過嘛，你這個問題，問我也是白問。第一，就算我說了也不一定是真的，你無法確認。",
          DialogueId = 80030119,
          GUID = "C858D41B",
          NextDialogue = 80030120,
          SpeakNpcId = 94202,
          Subtitle = "But honestly, your question's moot. For starters, even if I did tell you something, there's no way you could verify it.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41B"
        },
        [80030120] = {
          ContentTC = "第二，根據「霍氏高效節能模式」，工作是工作，生活是生活。",
          DialogueId = 80030120,
          GUID = "C858D41C",
          NextDialogue = 80030121,
          SpeakNpcId = 94202,
          Subtitle = "Secondly, in the principle of the \"Howard High-Efficiency Energy-Saving Mode\", I keep work and life separate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41C"
        },
        [80030121] = {
          ContentTC = "生活可以融入我的工作，但工作決不能闖入我的生活，現在的我，是在休假中赴約的，這是我得到的最「節能」的辦法。",
          DialogueId = 80030121,
          GUID = "C858D41D",
          NextDialogue = 80030122,
          SpeakNpcId = 94202,
          Subtitle = "Life might blend into work, but work must never intrude on my life. Right now, I'm technically on vacation, and that's the most \"energy-efficient\" way I operate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41D"
        },
        [80030122] = {
          ContentTC = "所以不管是現在還是未來的會談，我們怕是都不能在零號的話題上有所進展了，但如果是生活相關的，那倒是有很多可以聊。",
          DialogueId = 80030122,
          GUID = "C858D41E",
          NextDialogue = 80030123,
          SpeakNpcId = 94202,
          Subtitle = "So, this conversation and any future talks about No. 0 aren't gonna get anywhere; but if you want to chat about life and other fun stuff, I'm all ears.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41E"
        },
        [80030123] = {
          ContentTC = "那我們沒什麼好談的了，你走吧。",
          DialogueId = 80030123,
          GUID = "C858D41F",
          NextDialogue = 80030124,
          SpeakNpcId = 790008,
          Subtitle = "Then it seems we're done here. You can leave.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41F"
        },
        [80030124] = {
          ContentTC = "雖然沒法告訴你她的下落，但我可以向你保證的是，她很安全。",
          DialogueId = 80030124,
          GUID = "C858D421",
          NextDialogue = 80030125,
          SpeakNpcId = 94202,
          Subtitle = "While I can't disclose her whereabouts, I can assure you, she's safe.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D421"
        },
        [80030125] = {
          ContentTC = "從你嘴裡聽到的保證，我無法確認。",
          DialogueId = 80030125,
          GUID = "C858D422",
          NextDialogue = 80030126,
          SpeakNpcId = 790008,
          Subtitle = "There's no way I could verify that.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D422"
        },
        [80030126] = {
          ContentTC = "哈哈哈哈，聰明人學得就是快呀。",
          DialogueId = 80030126,
          GUID = "C858D423",
          NextDialogue = 80030127,
          SpeakNpcId = 94202,
          Subtitle = "Hahaha, smart people are all quick learners.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D423"
        },
        [80030127] = {
          ContentTC = "哎，難得我一片好心了，真是令人悲痛欲絕，甚至明天無法正常休息……",
          DialogueId = 80030127,
          GUID = "C858D4BE",
          NextDialogue = 80030128,
          SpeakNpcId = 94202,
          Subtitle = "*sigh* It's sad to see good intentions go unappreciated — so much so that I might not be able to rest properly tomorrow...",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4BE"
        },
        [80030128] = {
          ContentTC = "對哦，我應該試試能不能休假中插入病假：因為生病，沒有得到休息，所以延長休假，想想也是很正常的邏輯！",
          DialogueId = 80030128,
          GUID = "C858D4E8",
          NextDialogue = 80030129,
          SpeakNpcId = 94202,
          Subtitle = "Oh, wait! Maybe I should try to extend my holiday by taking sick leave. Like, I need a prolonged holiday 'cause my illness had prevented me from getting proper rest. That makes perfect sense, doesn't it?!",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4E8"
        },
        [80030129] = {
          ContentTC = "也不是不可以……病假理由就寫周身上下不明原因疼痛，尤其是心臟疼痛劇烈。",
          DialogueId = 80030129,
          GUID = "C858D512",
          NextDialogue = 80030130,
          SpeakNpcId = 94202,
          Subtitle = "And the reason I'll use will be... I feel achy all over, especially in my heart.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D512"
        },
        [80030130] = {
          ContentTC = "原因就寫成在做民意調查時發生了衝突，經私下調節已解決。也許還能領到工傷撫恤……嗯，今天算來對了。",
          DialogueId = 80030130,
          GUID = "C858D53C",
          NextDialogue = 80030131,
          SpeakNpcId = 94202,
          Subtitle = "Because of a conflict during a public opinion survey... but it has been resolved through private negotiations. Maybe I'll even get compensation out of it. Today has been very fruitful.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D53C"
        },
        [80030131] = {
          ContentTC = "你一杯茶的功夫，就多了這麼多假期，你可真是我的好朋友！",
          DialogueId = 80030131,
          GUID = "C858D566",
          NextDialogue = 80030132,
          SpeakNpcId = 94202,
          Subtitle = "You just extended my holiday in mere seconds. My friend, you're the best!",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D566"
        },
        [80030132] = {
          ContentTC = "期待下一次的請假理由……咳，我是說下一次的見面。",
          DialogueId = 80030132,
          GUID = "C858D590",
          SpeakNpcId = 94202,
          Subtitle = "I'm looking forward to my next excuse for... Ahem... I mean, our next meeting.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D590"
        },
        [80030201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "看來你終於願意跟我聊聊生活相關的話題了呀。",
          DialogueId = 80030201,
          GUID = "C858E2DA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030202,
          SpeakNpcId = 94202,
          Subtitle = "Looks like you're finally up for some casual chats, huh?",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E2DA"
        },
        [80030202] = {
          ContentTC = "哎呀，雖然前來冰湖城是公務，但是赴約可不是，不要覺得我只是順便來這一趟。為了和你喝上一杯，我可是又申請了假期。",
          DialogueId = 80030202,
          GUID = "C858E304",
          NextDialogue = 80030203,
          SpeakNpcId = 94202,
          Subtitle = "I'm still on a mission, so I couldn't meet up with you during working hours. I requested leave especially to grab a drink with you.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E304"
        },
        [80030203] = {
          ContentTC = "理由嘛，就說被內城的貴族小姐邀請去跳了幾支舞好了。",
          DialogueId = 80030203,
          GUID = "C858E32E",
          NextDialogue = 80030204,
          SpeakNpcId = 94202,
          Subtitle = "And my reason for this leave... I told them I was invited to a dance by a young lady of nobility.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E32E"
        },
        [80030204] = {
          ContentTC = "別奇怪，年輕軍官和貴族小姐傳出些浪漫故事也不是一次兩次，內部也都是睜一只眼閉一只眼。畢竟要是成了，軍團的勢力也會有所增長，不是壞事。",
          DialogueId = 80030204,
          GUID = "C858E358",
          NextDialogue = 80030205,
          SpeakNpcId = 94202,
          Subtitle = "Oh don't be surprised. It's quite common for young officers and noble ladies to have romantic affairs. The Legion turns a blind eye to them. After all, having relations with \"the nobility\" can bolster the Legion's influence.",
          VoiceName = "voice/$Locale$/inv/Landi/0/C858E358"
        },
        [80030205] = {
          ContentTC = "而我這樣風度翩翩的紳士，因為這樣的緣由而延長假期，可太正常不過了。",
          DialogueId = 80030205,
          GUID = "C858E382",
          NextOptions = {
            [1] = 800302051,
            [2] = 800302052
          },
          SpeakNpcId = 94202,
          Subtitle = "As a gentleman, I had to take longer leave for this reason. I think it makes perfect sense.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E382"
        },
        [80030206] = {
          ContentTC = "啊，你這話說得我心好痛，我得繼續延長假期檢查檢查。",
          DialogueId = 80030206,
          GUID = "C858E3AC",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Your words are like a dagger in my heart. I might have to extend my leave to recover from that burn.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3AC"
        },
        [80030207] = {
          ContentTC = "嗯嗯，我就當做你是真心實意在誇讚我了。",
          DialogueId = 80030207,
          GUID = "C858E3D6",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Thank you, I'll take that as a compliment.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3D6"
        },
        [80030208] = {
          ContentTC = "不過，我也是很晚才知道，紳士這個詞真正用起來，更多是用來挖苦，極少是用來讚美的。",
          DialogueId = 80030208,
          GUID = "C858E400",
          NextDialogue = 80030209,
          SpeakNpcId = 94202,
          Subtitle = "I'm aware by the way, that \"gentleman\" is often used sarcastically, not as praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E400"
        },
        [80030209] = {
          ContentTC = "而小時候，我的姐姐們總和我說，成為紳士是一個小男孩的終極目標，人生意義。",
          DialogueId = 80030209,
          GUID = "C858E42A",
          NextOptions = {
            [1] = 800302091,
            [2] = 800302092
          },
          SpeakNpcId = 94202,
          Subtitle = "When I was little, my sisters told me that being a gentleman is the ultimate goal for a man.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E42A"
        },
        [80030210] = {
          ContentTC = "也許你這個推論是基於對我的良好印象，但是很遺憾，並非如此。",
          DialogueId = 80030210,
          GUID = "C858E454",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "Maybe you're making that assumption based on your high opinion of me, but unfortunately, they're not lovely ladies, not at all.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E454"
        },
        [80030211] = {
          ContentTC = "誰都有年輕的時候嘛，天真，可愛。",
          DialogueId = 80030211,
          GUID = "C858E47E",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "I was just like any ordinary kid. Dumb and naive.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E47E"
        },
        [80030212] = {
          ContentTC = "雖然這些算是童年的傷疤，揭開就會帶來疼痛，但是既然我已經是請假之交，那麼給你講講她們也無妨啦。",
          DialogueId = 80030212,
          GUID = "C858E4A8",
          NextDialogue = 80030213,
          SpeakNpcId = 94202,
          Subtitle = "Look, I really don't feel like talking about my sisters. They tormented me during my childhood. But since you're my holiday buddy, I will tell you this.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4A8"
        },
        [80030213] = {
          ContentTC = "我可是在她們的「關愛」下長大的！想要在她們的魔爪……咳，關愛下生存，練就了一身本領……",
          DialogueId = 80030213,
          GUID = "C858E4D2",
          NextOptions = {
            [1] = 800302131,
            [2] = 800302132
          },
          SpeakNpcId = 94202,
          Subtitle = "I grew up with their \"love\". To survive their clutches... ahem, I mean love, I had to develop many skills.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4D2"
        },
        [80030214] = {
          ContentTC = "有愛，但不多。",
          DialogueId = 80030214,
          GUID = "C858E4FC",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, love. Tough love.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4FC"
        },
        [80030215] = {
          ContentTC = "不辛苦，命苦。",
          DialogueId = 80030215,
          GUID = "C858E526",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, it was rather bitter.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E526"
        },
        [80030216] = {
          ContentTC = "那時候她們成天和我說，紳士要在見面時親吻女士的手背，還應當遵循原則與禮儀，隱藏內心的真實想法。",
          DialogueId = 80030216,
          GUID = "C858E550",
          NextDialogue = 80030217,
          SpeakNpcId = 94202,
          Subtitle = "Back then, they told me that a gentleman should kiss a lady's dress when they meet, and that one should adhere to principles and etiquette to conceal their true thoughts and feelings.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E550"
        },
        [80030217] = {
          ContentTC = "那時候我才六歲甚至五歲，雖然心裡有些不情願，但還是為了成為一個合格紳士，向見到的每一位女士搭話。",
          DialogueId = 80030217,
          GUID = "C858E57A",
          NextDialogue = 80030218,
          SpeakNpcId = 94202,
          Subtitle = "When I was five or six years old, I acted like a gentleman to every woman I met, even though I didn't want to.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E57A"
        },
        [80030218] = {
          ContentTC = "你可以想像一下，在邊上看著的姐姐們笑成了什麼樣子。好在她們在第二天，就和我說，紳士並不用做到這一步。",
          DialogueId = 80030218,
          GUID = "C858E5A4",
          NextDialogue = 80030219,
          SpeakNpcId = 94202,
          Subtitle = "You can imagine how my sisters watched me and laughed. Later on, they told me that gentlemen didn't really have to do that.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5A4"
        },
        [80030219] = {
          ContentTC = "但不好的是，她們又告訴我，紳士應該親吻女士的裙擺……",
          DialogueId = 80030219,
          GUID = "C858E5CE",
          NextDialogue = 80030220,
          SpeakNpcId = 94202,
          Subtitle = "They should actually kiss the back of a lady's hand. Not her dress.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5CE"
        },
        [80030220] = {
          ContentTC = "算了，越是回憶我的心就越痛，先乾上一杯吧，為了我那不堪回首的童年時代。",
          DialogueId = 80030220,
          GUID = "C858E5F8",
          SpeakNpcId = 94202,
          Subtitle = "Anyway, let's not talk about this. Here's a toast to my miserable childhood.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5F8"
        },
        [80030401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "來了來了，我不會失約的。",
          DialogueId = 80030401,
          GUID = "C85903AA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030402,
          SpeakNpcId = 94202,
          Subtitle = "I'm here. I couldn't stand you up now, could I?",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903AA"
        },
        [80030402] = {
          ContentTC = "喏，這是改進好的「軍用合金控溫容器」，我提前試過，不會有問題的……哈欠……",
          DialogueId = 80030402,
          GUID = "C85903D4",
          NextDialogue = 80030403,
          SpeakNpcId = 94202,
          Subtitle = "Check this out. The Military Alloy Temperature Control Vessel - Ultimate Type. I've tried it, and it works like a charm... *yawn*",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903D4"
        },
        [80030403] = {
          ContentTC = "不過我現在困得不行，得要先找一個地方睡上一覺。假期額度快用完了，明天可不能黑著眼圈去給西比爾長官彙報工作。",
          DialogueId = 80030403,
          GUID = "C85903FE",
          NextOptions = {
            [1] = 800304031,
            [2] = 800304032
          },
          SpeakNpcId = 94202,
          Subtitle = "I'm feeling a bit drowsy at the moment, I need to find a place to get some shut-eye. I've nearly run out of annual leave, and I can't report to Chief Sibylle tomorrow with dark rings around my eyes.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903FE"
        },
        [80030404] = {
          ContentTC = "你感覺還挺敏銳的嘛，確實有一些煩惱。",
          DialogueId = 80030404,
          GUID = "C8590428",
          NextDialogue = 80030405,
          SpeakNpcId = 94202,
          Subtitle = "You're very perceptive. Yes, there's something on my mind.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590428"
        },
        [80030405] = {
          ContentTC = "既然被你察覺了，那我也不瞞著了，其實是做了噩夢。",
          DialogueId = 80030405,
          GUID = "C8590452",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "I won't keep it from you. Basically, I had a nightmare.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590452"
        },
        [80030406] = {
          ContentTC = "怎麼會，像我這麼怕麻煩的人，是會回絕掉大部分邀請的。",
          DialogueId = 80030406,
          GUID = "C859047C",
          NextDialogue = 80030407,
          SpeakNpcId = 94202,
          Subtitle = "Of course not. You know how lazy I am. I turn most invitations down.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C859047C"
        },
        [80030407] = {
          ContentTC = "實話說，是因為昨天做了噩夢，心情有些糟糕。",
          DialogueId = 80030407,
          GUID = "C85904A6",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "To be honest, I had a nightmare last night, so I'm feeling a bit off today.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904A6"
        },
        [80030408] = {
          ContentTC = "唉，和之前許多次噩夢一樣，是關於我那個麻煩老爹的……",
          DialogueId = 80030408,
          GUID = "C85904D0",
          NextOptions = {
            [1] = 800304081
          },
          SpeakNpcId = 94202,
          Subtitle = "Well, like many of my nightmares, this one was about my dad.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904D0"
        },
        [80030409] = {
          ContentTC = "嗯，他曾經也是帝國的軍人。不過現在嘛……已經在床上躺了有些年頭了。",
          DialogueId = 80030409,
          GUID = "C85904FA",
          NextDialogue = 80030410,
          SpeakNpcId = 94202,
          Subtitle = "He used to be a soldier in the Empire, but... he's been bedridden for years now.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904FA"
        },
        [80030410] = {
          ContentTC = "在我被姐姐們欺騙著，想要成為紳士的年紀，老爹就已經是軍團裡的士官了。那時他在前線的時間多，在家的時間少，和我現在差不多吧。",
          DialogueId = 80030410,
          GUID = "C8590524",
          NextDialogue = 80030411,
          SpeakNpcId = 94202,
          Subtitle = "Back when I was tricked by my sisters into becoming a gentleman, he was a sergeant in the Legion. He spent more time on the front lines than at home, just like me now.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590524"
        },
        [80030411] = {
          ContentTC = "不過和我現在不一樣的是，他非常看重自己身上的軍裝。似乎對於他來說，軍隊才是自己的家，而我和姐姐們在的地方，不過是可以任意挑剔的旅店罷了。",
          DialogueId = 80030411,
          GUID = "C859054E",
          NextDialogue = 80030412,
          SpeakNpcId = 94202,
          Subtitle = "But the difference between us is that he was proud of being a soldier. He treated the Legion as his home and his actual home as nothing more than a hotel where he could complain as much as he liked.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859054E"
        },
        [80030412] = {
          ContentTC = "每次他回到家，總是要發上一些牢騷，有時候是皇帝的畫像沒有掛正，有時候是姐姐們回家太晚。",
          DialogueId = 80030412,
          GUID = "C8590578",
          NextDialogue = 80030413,
          SpeakNpcId = 94202,
          Subtitle = "Whenever he came home, he'd complain about something or other, like the Emperor's portrait not being hung up properly, or my sisters coming home too late.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590578"
        },
        [80030413] = {
          ContentTC = "但是每一次都會有一個保留節目，就是發起一場對我的檢閱。",
          DialogueId = 80030413,
          GUID = "C85905A2",
          NextDialogue = 80030414,
          SpeakNpcId = 94202,
          Subtitle = "And he'd always check up on me last.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905A2"
        },
        [80030414] = {
          ContentTC = "又長高了幾釐米，又看了幾本書，又記住了幾座要塞的名字，又學會了幾種求生技能，他會一一問一遍。",
          DialogueId = 80030414,
          GUID = "C85905CC",
          NextDialogue = 80030415,
          SpeakNpcId = 94202,
          Subtitle = "He'd check how much taller I'd got, how many books I'd read, how many forts I'd learned the names of, and what new survival skills I'd acquired.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905CC"
        },
        [80030415] = {
          ContentTC = "我也試過和他討論其他話題，但是他對於「成為軍人」以外的所有事情都毫無興趣。",
          DialogueId = 80030415,
          GUID = "C85905F6",
          NextDialogue = 80030416,
          SpeakNpcId = 94202,
          Subtitle = "I tried talking to him about other things, but he wasn't interested in anything other than \"being a soldier.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905F6"
        },
        [80030416] = {
          ContentTC = "有一次，我為了迎合他，像現在製造小工具那樣，小心用木頭刻了一把手槍，滿心歡喜等著他的誇獎。",
          DialogueId = 80030416,
          GUID = "C8590620",
          NextDialogue = 80030417,
          SpeakNpcId = 94202,
          Subtitle = "Once, to try to please him, I painstakingly carved a wooden pistol for him and eagerly awaited his praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590620"
        },
        [80030417] = {
          ContentTC = "但他只是把手槍「梆」地一下砸在桌子上，板起臉來：「少做這些浪費時間的閒事，多把心思放在如何成為一個優秀的軍人上。」",
          DialogueId = 80030417,
          GUID = "C859064A",
          NextDialogue = 80030418,
          SpeakNpcId = 94202,
          Subtitle = "But with a stren face he just snatched it from me, \"Don't waste your time on things like this. Think about how you can become a better soldier from now on.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859064A"
        },
        [80030418] = {
          ContentTC = "那時候我的心裡突然多了一種東西，像是屋子外面的風一樣，冷，刀割一樣，又摸不到，還無法停止。",
          DialogueId = 80030418,
          GUID = "C8590674",
          NextDialogue = 80030419,
          SpeakNpcId = 94202,
          Subtitle = "At that moment, I felt something change within me. Something cold, bitter, intangible and unstoppable, like the howling wind outside our home.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590674"
        },
        [80030419] = {
          ContentTC = "後來我才逐漸意識到，那也許是恨意，雖然沒有十分強烈，但是已經足夠讓我覺得面前的這個人討厭，陌生。",
          DialogueId = 80030419,
          GUID = "C859069E",
          NextDialogue = 80030420,
          SpeakNpcId = 94202,
          Subtitle = "Later, I gradually realised that it was hatred. Although it was weak to begin with, it was still strong enough to make me feel that the person in front of me was nothing more than a stranger.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859069E"
        },
        [80030420] = {
          ContentTC = "在那過後，我就不再試圖迎合他了，也不管他的檢閱，也不管他罵我是「廢物」或者什麼更難聽的話。",
          DialogueId = 80030420,
          GUID = "C85906C8",
          NextDialogue = 80030421,
          SpeakNpcId = 94202,
          Subtitle = "So after that, I stopped trying to be the son he wanted me to be. I ignored his check-ups on me, no matter how much he scolded me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906C8"
        },
        [80030421] = {
          ContentTC = "直到有一天，他突然被送了回來——在戰鬥中為了保護下屬，被彈片擊中了腦袋，雖然活著，但是沒了意識。",
          DialogueId = 80030421,
          GUID = "C85906F2",
          NextDialogue = 80030422,
          SpeakNpcId = 94202,
          Subtitle = "Years passed... He was shot in the head while protecting one of his subordinates. He was sent home with a purple heart. Although he was still alive, he had fallen into a coma.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906F2"
        },
        [80030422] = {
          ContentTC = "他沒什麼額外的積蓄，所有的薪水都寄回了家裡，和他一起被送回來的，除了鋥亮的勳章以外，就只有一把斷成兩截的木槍。",
          DialogueId = 80030422,
          GUID = "C859071C",
          NextDialogue = 80030423,
          SpeakNpcId = 94202,
          Subtitle = "When he came back, he had nothing but shiny medals, his slender savings, and a wooden pistol that was broken in two.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859071C"
        },
        [80030423] = {
          ContentTC = "我原來以為這是因為他對我失望透頂，但是他的那些下屬告訴我，這把木槍他隨身帶著，是他在戰場上倒下時折斷的。",
          DialogueId = 80030423,
          GUID = "C8590746",
          NextDialogue = 80030424,
          SpeakNpcId = 94202,
          Subtitle = "I thought he was disappointed in me because of that broken pistol, but his subordinates told me that he carried it with him at all times and that it broke when he fell on the battlefield.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590746"
        },
        [80030424] = {
          ContentTC = "他似乎在心底裡認可我。但是我無法接受這樣的認可。",
          DialogueId = 80030424,
          GUID = "C8590770",
          NextDialogue = 80030425,
          SpeakNpcId = 94202,
          Subtitle = "It seems that he did love me after all. But his way of expressing it was unrecognisable. Maddening.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590770"
        },
        [80030425] = {
          ContentTC = "如果真的為我感到驕傲，我更希望他能夠親口說出來，哪怕最簡單的一句鼓勵也好，而不是一直在逼迫著我幹著不想幹的事情。",
          DialogueId = 80030425,
          GUID = "C859079A",
          NextDialogue = 80030426,
          SpeakNpcId = 94202,
          Subtitle = "If he was proud of me, he should've told me. A few words of encouragement would've been enough, but instead, he just forced me to do things I didn't enjoy.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859079A"
        },
        [80030426] = {
          ContentTC = "雖然老爹已經不會再爬起來敲我的腦殼，我還是按照他一直以來的要求，加入了軍團。",
          DialogueId = 80030426,
          GUID = "C85907C4",
          NextDialogue = 80030427,
          SpeakNpcId = 94202,
          Subtitle = "Although he'd never push me to do anything again, I still joined the army, just like he wanted.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907C4"
        },
        [80030427] = {
          ContentTC = "我好奇那到底是一個怎樣的地方，能讓老爹變成一個沉默寡言的傢伙，也想證明，哪怕沒有按照他的呵斥，我也能混出一個不錯的日子。",
          DialogueId = 80030427,
          GUID = "C85907EE",
          NextDialogue = 80030428,
          SpeakNpcId = 94202,
          Subtitle = "I was curious about the Legion, the place that had turned my father into a detached man. I also wanted to prove that I could live a great life without his scolding.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907EE"
        },
        [80030428] = {
          ContentTC = "不過對他和對我來說都很不幸的是，當我加入軍團後，才發現他說得其實沒錯。",
          DialogueId = 80030428,
          GUID = "C8590818",
          NextDialogue = 80030429,
          SpeakNpcId = 94202,
          Subtitle = "Unfortunately for both of us, I found out that he was right all along. He was protecting me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590818"
        },
        [80030429] = {
          ContentTC = "我們和軍團的大多數人不一樣。我們從戰場的屍骸堆中爬出來，跪著接過他們施捨的勳章。",
          DialogueId = 80030429,
          GUID = "C8590842",
          NextDialogue = 80030430,
          SpeakNpcId = 94202,
          Subtitle = "We're unlike most people in the Legion. We crawled out of piles of corpses on the battlefield, and kneel down to receive the medals they bestowed upon us like charity.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590842"
        },
        [80030430] = {
          ContentTC = "體面的工作，優渥的生活，甚至生存本身——我們的一切都維繫在那些小小的勳章上。父親為了我們的家，奉上了自己的一切。",
          DialogueId = 80030430,
          GUID = "C859086C",
          NextDialogue = 80030431,
          SpeakNpcId = 94202,
          Subtitle = "A decent job, a great life, and a means of survival. Everything about us is determined by those small medals. For the sake of our family, my dad devoted himself to them.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859086C"
        },
        [80030431] = {
          ContentTC = "他去服從，去忍耐，去壓抑感情，讓自己習慣哀嚎和哭泣，讓自己成為這匹巨獸口中的一枚獠牙。",
          DialogueId = 80030431,
          GUID = "C8590896",
          NextDialogue = 80030432,
          SpeakNpcId = 94202,
          Subtitle = "He obeyed, endured, suppressed his feelings, pushed back the tears, and turned himself into a husk of a man.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590896"
        },
        [80030432] = {
          ContentTC = "我做不到這些，但又要一筆錢養活自己，維持家庭現有的體面，所以就只能這樣懸在半空，做一個廢物。",
          DialogueId = 80030432,
          GUID = "C85908C0",
          NextOptions = {
            [1] = 800304321
          },
          SpeakNpcId = 94202,
          Subtitle = "I can't do that, but I need money to support myself and maintain my family's decent lifestyle. So, I'm a happy loser now, as you can see.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908C0"
        },
        [80030433] = {
          ContentTC = "……",
          DialogueId = 80030433,
          GUID = "C85908EA",
          NextDialogue = 80030434,
          SpeakNpcId = 94202,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908EA"
        },
        [80030434] = {
          ContentTC = "你確實很敏銳。說實話，我到底在幹什麼，也是在消沉了很久之後才想明白。",
          DialogueId = 80030434,
          GUID = "C8590914",
          NextDialogue = 80030435,
          SpeakNpcId = 94202,
          Subtitle = "You have a keen eye. But to be frank, I have no idea what I want to do. After a long bout of depression, I've finally realised that —",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590914"
        },
        [80030435] = {
          ContentTC = "雖然我的選擇和老爹的期望有一些差距，但是我並不覺得這是一件壞事。",
          DialogueId = 80030435,
          GUID = "C859093E",
          NextOptions = {
            [1] = 800304351,
            [2] = 800304352
          },
          SpeakNpcId = 94202,
          Subtitle = "Even though I haven't lived up to my dad's expectations, I'm happy with the life I have.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859093E"
        },
        [80030436] = {
          ContentTC = "希望如此吧，這樣一來，這場噩夢應該就能結束了。",
          DialogueId = 80030436,
          GUID = "C8590968",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "I hope so. If that happens, my nightmares may finally end.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590968"
        },
        [80030437] = {
          ContentTC = "真是好飲料啊，喝完了後，一定不會再做噩夢的。",
          DialogueId = 80030437,
          GUID = "C8590992",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "That tastes good. This will help me sleep without nightmares.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590992"
        },
        [80030438] = {
          ContentTC = "謝了，我的請假之交，只不過現在為了明天不請假，必須得回去補上一覺了。",
          DialogueId = 80030438,
          GUID = "C85909BC",
          NextDialogue = 80030439,
          SpeakNpcId = 94202,
          Subtitle = "Thanks, holiday buddy, but I need some sleep now, or else I'll have to take more leave tomorrow.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909BC"
        },
        [80030439] = {
          ContentTC = "別擔心，下次見面的時候，我還是你熟悉的那個蘭迪。萬一我又做噩夢了，就勞煩你再給我調製一杯飲料吧。",
          DialogueId = 80030439,
          GUID = "C85909E6",
          SpeakNpcId = 94202,
          Subtitle = "Don't worry, I'll be the regular Randy you know the next time we meet. And if I have another nightmare, please make me one more cup of this delicious drink.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909E6"
        },
        [80030501] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "一杯熱飲，多加點糖。另外，我還從帝都帶了一些甜點來，我趁著休假排隊買的，你可以嚐嚐。",
          DialogueId = 80030501,
          GUID = "C8591412",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextOptions = {
            [1] = 800305011,
            [2] = 800305012
          },
          SpeakNpcId = 94202,
          Subtitle = "A hot drink with extra sugar, please. I brought some desserts from the Imperial Capital. I queued up to buy them during my break. Want to try some?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591412"
        },
        [80030502] = {
          ContentTC = "是啊，所以想喝點甜的，作為接下來邀請的鋪墊。",
          DialogueId = 80030502,
          GUID = "C859143C",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "I sure am. I'm in the mood for a sweet drink as a prelude to my invitation.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859143C"
        },
        [80030503] = {
          ContentTC = "絕無此事！雖然我確實想要向你發出一則邀請，但是這並不能被稱作企圖！",
          DialogueId = 80030503,
          GUID = "C8591466",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "Ooh! I want to ask a small favour of you, but I wouldn't call it a \"plan.\"",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591466"
        },
        [80030504] = {
          ContentTC = "咳咳……嗯，雖然有點突然，但是要不要和我跳一支舞？",
          DialogueId = 80030504,
          GUID = "C8591490",
          NextDialogue = 80030505,
          SpeakNpcId = 94202,
          Subtitle = "Ahem... Maybe this is a little sudden, but do you want to attend a dance with me?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591490"
        },
        [80030505] = {
          ContentTC = "就是，軍團總要和一些地方勢力打好關係，比如之前和你說過的，去內城參加一些必要但是很煩人的社交儀式。",
          DialogueId = 80030505,
          GUID = "C85914BA",
          NextDialogue = 80030506,
          SpeakNpcId = 94202,
          Subtitle = "Like I mentioned to you before, the Legion needs to maintain ties with local nobility. So, I need to attend annoying social balls in the inner city from time to time.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914BA"
        },
        [80030506] = {
          ContentTC = "我好不想去啊，就算是給我算因公出差，應付那些老爺夫人也是怪麻煩的。",
          DialogueId = 80030506,
          GUID = "C85914E4",
          NextDialogue = 80030507,
          SpeakNpcId = 94202,
          Subtitle = "I really don't want to go. The trip is paid for, but dealing with nobility is such a headache.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914E4"
        },
        [80030507] = {
          ContentTC = "所以呢，我想了一個一勞永逸的方法，那就是帶著一位足夠美麗的女士一同入場，和我共舞一曲。",
          DialogueId = 80030507,
          GUID = "C859150E",
          NextDialogue = 80030508,
          SpeakNpcId = 94202,
          Subtitle = "So, I have a perfect solution. I can take a gorgeous lady with me as my partner.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859150E"
        },
        [80030508] = {
          ContentTC = "這樣一來，就不會有人湊上來，向我介紹那些他們自己可能也沒見過幾面的遠方女性親眷了吧。",
          DialogueId = 80030508,
          GUID = "C8591538",
          NextOptions = {
            [1] = 800305081,
            [2] = 800305082
          },
          SpeakNpcId = 94202,
          Subtitle = "That way, no one will try to introduce me to a female relative I've never met before.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591538"
        },
        [80030509] = {
          ContentTC = "就……我覺得……你也許可以嘗試一下男扮……",
          DialogueId = 80030509,
          GUID = "C8591562",
          NextOptions = {
            [1] = 800305091,
            [2] = 800305092
          },
          SpeakNpcId = 94202,
          Subtitle = "Well... I was thinking... maybe... you could try to disguise yourself as a lady.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591562"
        },
        [80030510] = {
          ContentTC = "哎呀，這不是因為邀請的是我嘛。",
          DialogueId = 80030510,
          GUID = "C859158C",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "I can't. I'm the one who's been invited.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859158C"
        },
        [80030511] = {
          ContentTC = "哎呀，我也是實在沒有辦法，才想出了這個主意。",
          DialogueId = 80030511,
          GUID = "C85915B6",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "Sorry, but you're my last hope. I'm really clutching at straws here!",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915B6"
        },
        [80030512] = {
          ContentTC = "我們都喝了這麼多頓酒了，你在我心裡早就是比姐姐們還要親近的兄弟了，否則我也不會想到你。",
          DialogueId = 80030512,
          GUID = "C85915E0",
          NextDialogue = 80030513,
          SpeakNpcId = 94202,
          Subtitle = "We've had so many drinks together, and you're my closest friend. I'm even closer to you than my siblings, so I'm begging you for help.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915E0"
        },
        [80030513] = {
          ContentTC = "所以在這種關頭，幫我一把，我接下來半年月俸都分你一半！",
          DialogueId = 80030513,
          GUID = "C859160A",
          NextDialogue = 80030514,
          SpeakNpcId = 94202,
          Subtitle = "If you help me in my time of need, I'll give you half of my salary for the next six months. And, if Chief Sibylle tries to arrest you next time, I'll come forward and protect you!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859160A"
        },
        [80030514] = {
          ContentTC = "你要是實在不樂意，等舞會回來，換我穿舞裙給你看好不好。",
          DialogueId = 80030514,
          GUID = "C8591634",
          NextOptions = {
            [1] = 800305141,
            [2] = 800305142
          },
          SpeakNpcId = 94202,
          Subtitle = "If that's not enough, I'll dress up like a lady and entertain you after the ball. What do you say?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591634"
        },
        [80030515] = {
          ContentTC = "別……別誤會，不不不不是這樣的，我沒有那樣的興趣，你怎麼會往那個方向去想？",
          DialogueId = 80030515,
          GUID = "C859165E",
          NextDialogue = 80030516,
          SpeakNpcId = 94202,
          Subtitle = "No, no, no! You've got the wrong idea! What makes you think that?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859165E"
        },
        [80030516] = {
          ContentTC = "好兄弟一起吃飯，一起玩耍，一起上廁所，一起穿裙子之類的，很正常吧。",
          DialogueId = 80030516,
          GUID = "C8591688",
          NextOptions = {
            [1] = 800305161
          },
          SpeakNpcId = 94202,
          Subtitle = "I mean, it's normal, right? Best buds do everything together — hang out, share meals, hit the restroom, try on dresses...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591688"
        },
        [80030517] = {
          ContentTC = "唉，你別笑啊，我可是很認真地在發愁呢，給個答覆吧。要是不答應的話，我得想想其他辦法了……",
          DialogueId = 80030517,
          GUID = "C85916B2",
          NextOptions = {
            [1] = 800305171,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "Hey, don't laugh at me. I'm really in a bind here. Please just give me your answer. If you say \"no,\" I'll have to find another solution.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916B2"
        },
        [80030518] = {
          ContentTC = "你可以再考慮考慮，實在不行……",
          DialogueId = 80030518,
          GUID = "C85916DC",
          NextDialogue = 80030519,
          SpeakNpcId = 94202,
          Subtitle = "Just think about it...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916DC"
        },
        [80030519] = {
          ContentTC = "等等？你答應了？太好了！你簡直就是我異父異母的親兄弟！",
          DialogueId = 80030519,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591706",
          NextDialogue = 80030520,
          SpeakNpcId = 94202,
          Subtitle = "Huh? Really? That's fantastic! You're a lifesaver!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591706"
        },
        [80030520] = {
          ContentTC = "這次是我欠了你一個天大的人情，我得要想請假理由那樣，想各種方法還掉才是。",
          DialogueId = 80030520,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591730",
          NextDialogue = 80030521,
          SpeakNpcId = 94202,
          Subtitle = "You've done me a huge favour. I'll repay you however I can.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591730"
        },
        [80030521] = {
          ContentTC = "不過，那也得等舞會結束再說了。現在呀，我得趁著你還沒反悔，先回去準備衣服啦。",
          DialogueId = 80030521,
          GUID = "C859175A",
          NextDialogue = 80030522,
          SpeakNpcId = 94202,
          Subtitle = "But let's talk about this after the ball. I need to go home and prepare my outfit before you change your mind.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859175A"
        },
        [80030522] = {
          ContentTC = "回頭見，我的請假之交，休息之友。",
          DialogueId = 80030522,
          GUID = "C8591784",
          SpeakNpcId = 94202,
          Subtitle = "I'll see you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591784"
        },
        [80030523] = {
          ContentTC = "嗚，你要不要再考慮考慮，舞會結束後，我會像編造請假理由那樣，想出各種方法來報答你的！",
          DialogueId = 80030523,
          GUID = "C85917AE",
          NextDialogue = 80030524,
          SpeakNpcId = 94202,
          Subtitle = "Please give it plenty of consideration. After the ball, I'll find many creative ways to repay you, just like how I come up with excuses to take time off.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85917AE"
        },
        [80030524] = {
          ContentTC = "不過，我覺得現在得安靜下來，留出一些空間讓你思考才是。不過，我還是希望你能答應，也相信你一定會答應的！",
          DialogueId = 80030524,
          GUID = "C85917D8",
          NextDialogue = 80030525,
          SpeakNpcId = 94202,
          Subtitle = "Take as much time as you need. I really need your help, and I'm certain that you'll come through for me.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85917D8"
        },
        [80030525] = {
          ContentTC = "那麼，我先回去了，等你的好消息，我的請假之交，休息之友。",
          DialogueId = 80030525,
          GUID = "C8591802",
          SpeakNpcId = 94202,
          Subtitle = "I'll be awaiting your answer. See you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591802"
        },
        [80030526] = {
          ContentTC = "沒錯，你顯然也意識到了，沒有比你更適合的舞伴了……所以，你能不能幫幫我，解開這個困境。",
          DialogueId = 80030526,
          GUID = "C8591856",
          NextOptions = {
            [1] = 800305261
          },
          SpeakNpcId = 94202,
          Subtitle = "Yes, you're my best dancing partner, after all. The question is, are you willing to do me this favour?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591856"
        },
        [80030527] = {
          ContentTC = "嗯……？",
          DialogueId = 80030527,
          GUID = "C8591880",
          NextDialogue = 80030528,
          SpeakNpcId = 94202,
          Subtitle = "What?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591880"
        },
        [80030528] = {
          ContentTC = "啊？！怎麼可能，你怎麼能這麼想？我真想要幫你綁了立功的話，第一次坐在這裡的時候就可以動手了！",
          DialogueId = 80030528,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C85918AA",
          NextDialogue = 80030529,
          SpeakNpcId = 94202,
          Subtitle = "Why on earth would you think that? If I really wanted to arrest you, I could've done that the first time we met.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918AA"
        },
        [80030529] = {
          ContentTC = "根本不用專門請假到這裡這麼多次後，再編造出一個舞會來誘捕你。",
          DialogueId = 80030529,
          GUID = "C85918D4",
          NextDialogue = 80030530,
          SpeakNpcId = 94202,
          Subtitle = "I don't see the point in using my precious leave to come here and organise something like a \"secret arrest ball\".",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918D4"
        },
        [80030530] = {
          ContentTC = "更何況，即便想要引誘你也不會選擇用邀請你跳舞這種方式吧，萬一被拒絕了怎麼辦？",
          DialogueId = 80030530,
          GUID = "C85918FE",
          NextDialogue = 80030531,
          SpeakNpcId = 94202,
          Subtitle = "And what if you turn me down? How would my plan work in that case?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918FE"
        },
        [80030531] = {
          ContentTC = "啊啊，你是在開玩笑吧，不然我只能理解為，在你眼裡，我是一個又壞又蠢的煩人傢伙。",
          DialogueId = 80030531,
          GUID = "C8591928",
          NextOptions = {
            [1] = 800305311,
            [2] = 800305312
          },
          SpeakNpcId = 94202,
          Subtitle = "You must be kidding. Do you seriously think I'm a scheming fool like that?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591928"
        },
        [80030532] = {
          ContentTC = "還好還好，如果真的被誤會成打算背叛重要的朋友，換取前途的無恥之徒的話，我會因為太過心痛而請一個月的病假的。",
          DialogueId = 80030532,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591952",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          Subtitle = "Alright then. If you really did misunderstand me and think I was a shameless jerk who'd betray his friends like that, I'd need a month's leave to recover from such heartbreak.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591952"
        },
        [80030533] = {
          ContentTC = "喂喂喂，至少否定一下後半句吧！要是我當真了怎麼辦！",
          DialogueId = 80030533,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C859197C",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          Subtitle = "Hey, at least deny that I betrayed my friends for personal gain, or else you'll hurt my feelings!",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859197C"
        },
        [80030534] = {
          ContentTC = "不過我現在有一點可以肯定，那麼就是，你其實從一開始，就根本沒有擔心有什麼危險。",
          DialogueId = 80030534,
          GUID = "C85919A6",
          NextDialogue = 80030535,
          SpeakNpcId = 94202,
          Subtitle = "But now there's one thing I'm sure of — You're not afraid of risk at all.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919A6"
        },
        [80030535] = {
          ContentTC = "而是單純地惡作劇，設想了一個最壞的可能，想看我的反應。",
          DialogueId = 80030535,
          GUID = "C85919D0",
          NextOptions = {
            [1] = 800305351,
            [2] = 800305352
          },
          SpeakNpcId = 94202,
          Subtitle = "So, you were messing with me to see my reaction.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919D0"
        },
        [80030536] = {
          ContentTC = "我原來以為只有我會有這種捉弄人不正經的習慣，怎麼你也這麼惡趣味。也不知道和誰學來的。",
          DialogueId = 80030536,
          GUID = "C85919FA",
          NextDialogue = 80030537,
          SpeakNpcId = 94202,
          Subtitle = "I didn't know you love mean tricks like me. Where did you pick that up?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919FA"
        },
        [80030537] = {
          ContentTC = "我確實有那麼一瞬間慌了幾秒，雖然理智上知道不可能，但是感性上還是在擔心，萬一你是真的這麼覺得呢？",
          DialogueId = 80030537,
          GUID = "C8591A24",
          NextDialogue = 80030538,
          SpeakNpcId = 94202,
          Subtitle = "I panicked for a moment then. Although deep down I knew it was impossible, I was still worried. What if you really thought that way?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A24"
        },
        [80030538] = {
          ContentTC = "所以，作為惡作劇的補償，你必須答應我的邀請。",
          DialogueId = 80030538,
          GUID = "C8591A4E",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "So, to make up for your trick, you must help me.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A4E"
        },
        [80030539] = {
          ContentTC = "哈？",
          DialogueId = 80030539,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591A78",
          NextDialogue = 80030540,
          SpeakNpcId = 94202,
          Subtitle = "What?!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A78"
        },
        [80030540] = {
          ContentTC = "好吧，你說得沒錯！我一直想要逮捕你，白天，夜裡，只要是大腦沒有在休假，就在謀劃逮捕你的計畫。只是因為我一直都是偷懶耍滑，遲遲都沒有實踐。",
          DialogueId = 80030540,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591AA2",
          NextDialogue = 80030541,
          SpeakNpcId = 94202,
          Subtitle = "Okay, fine, you're right. I've been wanting to arrest you for ages. Every morning, I wake up and think about how to carry out my devious plan, but I procrastinate too much to actually do it.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591AA2"
        },
        [80030541] = {
          ContentTC = "難得這次想認真幹活，卻被識破了，怎麼辦呀——",
          DialogueId = 80030541,
          GUID = "C8591ACC",
          NextDialogue = 80030542,
          SpeakNpcId = 94202,
          Subtitle = "This time, I was hoping to fulfil my duty but failed. What do I do?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591ACC"
        },
        [80030542] = {
          ContentTC = "看來我遲早會被軍團掃地出門，流落在冰湖城的嚴寒街道上，又冷，又餓，無家可歸……",
          DialogueId = 80030542,
          GUID = "C8591AF6",
          NextDialogue = 80030543,
          SpeakNpcId = 94202,
          Subtitle = "One day, I'll be fired by the Legion and end up homeless and destitute on the cold streets of Icelake.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591AF6"
        },
        [80030543] = {
          ContentTC = "你真的能夠眼睜睜看著我成為街頭的雪雕嗎？",
          DialogueId = 80030543,
          GUID = "C8591B20",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "Do you really want to see me turn into an ice sculpture on the street?",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B20"
        },
        [80030544] = {
          ContentTC = "你可以再考慮考慮，實在不行……",
          DialogueId = 80030544,
          GUID = "C8591B4A",
          NextDialogue = 80030545,
          SpeakNpcId = 94202,
          Subtitle = "Maybe you can think twice before answering me...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B4A"
        },
        [80030545] = {
          ContentTC = "等等？你答應了？太好了！你簡直……簡直……簡直是我異父異母的親姐妹！",
          DialogueId = 80030545,
          GUID = "C8591B74",
          NextDialogue = 80030546,
          SpeakNpcId = 94202,
          Subtitle = "... Huh? Really? That's fantastic! You're my lifesaver!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B74"
        },
        [80030546] = {
          ContentTC = "這次是我欠了你一個天大的人情，我得要想請假理由那樣，想各種方法還掉才是。",
          DialogueId = 80030546,
          GUID = "C8591B9E",
          NextDialogue = 80030547,
          SpeakNpcId = 94202,
          Subtitle = "You've done me a huge favour. I'll repay you however I can.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B9E"
        },
        [80030547] = {
          ContentTC = "不過，那也得等舞會結束再說了。現在呀，我得趁著你還沒反悔，先回去準備衣服啦。",
          DialogueId = 80030547,
          GUID = "C8591BC8",
          NextDialogue = 80030548,
          SpeakNpcId = 94202,
          Subtitle = "But let's talk about this after the ball. I need to go home and prepare my outfit before you change your mind.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591BC8"
        },
        [80030548] = {
          ContentTC = "回頭見，我的請假之交，休息之友。",
          DialogueId = 80030548,
          GUID = "C8591BF2",
          SpeakNpcId = 94202,
          Subtitle = "I'll see you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591BF2"
        },
        [80040101] = {
          Camera = "-52.422852,-88.373047,123.091431,0.000216,-4.998045,54.58065,40.000011,196.024292,false,Manual,4.967944",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "這樣就做好了，貝蕾嚐嚐看吧！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040101,
          Duration = 8,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-52.422852,-88.373047,123.091431,0.000229,2.801914,39.180523,40.000011,120.906364,false,Manual,4.967944",
          GUID = "C85F3B12",
          NextDialogue = 80040102,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/cook_finish\"},PlayAs2D{true}}",
          SpeakNpcId = 790008,
          Subtitle = "There we go. Try this, Berry.",
          TalkActionId = {
            [1] = "790008:Give"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B12"
        },
        [80040102] = {
          Camera = "-29.085938,-97.268799,150.180298,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786",
          ContentTC = "唔，好……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040102,
          FacialId = {
            [1] = "790007:Iyada01"
          },
          GUID = "C85F3B3C",
          NextDialogue = 80040103,
          SpeakNpcId = 790007,
          Subtitle = "Hmm, okay...",
          TalkActionId = {
            [1] = "790007:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B3C"
        },
        [80040103] = {
          Camera = "-199.146484,-426.681641,234.483765,0.000222,-15.191071,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentTC = "對了，你剛才怎麼非得和我搶湯勺？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040103,
          FinalCamera = "-186.857422,-430.990479,234.483765,0.000221,-15.191064,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B66",
          NextDialogue = 80040104,
          SpeakNpcId = 790007,
          Subtitle = "So, why were you so eager to take the ladle from me earlier?",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B66"
        },
        [80040104] = {
          Camera = "-24.671387,-68.66333,139.902344,0.000222,-5.191469,35.319683,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentTC = "還不是因為你想把石榴扔進魚湯裡一起煮。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040104,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "-24.671387,-68.66333,139.902344,0.000222,-4.591458,35.919678,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B90",
          NextDialogue = 80040105,
          SpeakNpcId = 790008,
          Subtitle = "Because you were about to add pomegranates to the fish soup!",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B90"
        },
        [80040105] = {
          ContentTC = "不可以嗎？我記得小時候你也很喜歡石榴的。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040105,
          FacialId = {
            [1] = "790007:Shock02"
          },
          GUID = "C85F3BBA",
          NextDialogue = 80040106,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Shock_Start\"},Duration{2}},PlayAnimation{ActorId{790007},AnimationId{\"Shock_End\"},Duration{1}}}",
          SpeakNpcId = 790007,
          Subtitle = "What's wrong with that? I remember you used to love pomegranates when you were little.",
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3BBA"
        },
        [80040106] = {
          Camera = "98.562256,-40.027588,134.129395,-0.000519,-2.40243,174.925446,40.0,252.474731,false,Manual,18.208658",
          ContentTC = "去年路過那顆石榴樹的時候，你還摘了滿滿一大袋，可惜爬山的時候一不小心，石榴全都滾到山下去了，你說「好可惜」。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040106,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "104.528809,-40.557373,134.380737,-0.000519,-2.40243,174.925446,40.0,252.474731,false,Manual,18.208658",
          GUID = "C85F3BE4",
          NextDialogue = 80040107,
          Scripts = [[
PARA{
SEQ{PlayAnimation{ActorId{790007},AnimationId{"Explain01_Start"},Duration{2}},PlayAnimation{ActorId{790007},AnimationId{"Explain01_End"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{"Disagree"},Duration{1}}},
SEQ{
CameraMoveTo{_delay{10},TargetPosition{"-29.085938,-97.268799,147.981201,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786"},duration{0}},
CameraMoveTo{TargetPosition{"-29.085938,-97.268799,150.180298,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786"},duration{8}}
}
}]],
          SpeakNpcId = 790007,
          Subtitle = "Remember last year when we walked past that big pomegranate tree? You picked a whole bag of them. Too bad they all rolled down the hill when you slipped. You said it was such a waste.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3BE4"
        },
        [80040107] = {
          ContentTC = "所以這次石榴結果的時候，我專門摘了來……你已經不喜歡了嗎？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040107,
          FacialId = {
            [1] = "790008:Smile01"
          },
          GUID = "C85F3C0E",
          NextDialogue = 80040108,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"-187.269043,-90.881348,151.269409,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205"},duration{0}},
CameraMoveTo{TargetPosition{"-178.94751,-87.67041,150.519897,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205"},duration{8}}
}]],
          SpeakNpcId = 790007,
          Subtitle = "So this time, I picked some just for you... Don't you like them anymore?",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C0E"
        },
        [80040108] = {
          ContentTC = "不是石榴的問題。主要是石榴和魚一起煮，味道會很奇怪吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040108,
          GUID = "C85F3C38",
          NextDialogue = 80040109,
          SpeakNpcId = 790008,
          Subtitle = "It's not about the pomegranates. It's just that pomegranates and fish might not taste good together, don't you think?",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C38"
        },
        [80040109] = {
          Camera = "21.563721,-75.783936,229.640259,-0.000637,-35.195148,81.889259,40.0,256.07196,false,DoNotOverride,3.614923",
          ContentTC = "可是你不是說漿果蘸牛奶味道很好嗎？淨界島買牛奶不太方便，但換成湯也一樣吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040109,
          FacialId = {
            [1] = "790007:Shock01"
          },
          FinalCamera = "10.167236,-74.255371,229.640259,-0.000639,-35.195141,79.688759,40.0,256.07196,false,DoNotOverride,3.614923",
          GUID = "C85F3C62",
          NextDialogue = 80040110,
          SpeakNpcId = 790007,
          Subtitle = "But you like berries dipped in milk... It's hard to buy milk here on this island, so I thought soup would work just as well.",
