        [80040138] = {
          Camera = "-433.807861,306.72583,200.69043,0.000452,21.596996,-168.54541,35.0,1486.565063,false,Manual,1.2",
          ContentTC = "……島外面啊。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040138,
          FinalCamera = "-433.807861,306.72583,200.69043,0.000451,26.996834,-173.544968,35.0,1486.565063,false,Manual,1.2",
          GUID = "C85F4124",
          SpeakNpcId = 790007,
          Subtitle = "...The world beyond this island, mm.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F4124"
        },
        [80040201] = {
          Camera = "32.020996,-408.154297,83.524414,0.000112,2.699038,107.178726,35.000008,497.258331,false,Manual,1.2",
          ContentTC = "到家了。貝蕾，快坐下！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040201,
          FinalCamera = "42.265381,-405.020264,83.524414,0.000113,2.699038,108.578911,35.000008,497.258331,false,Manual,1.2",
          GUID = "C85F4B7A",
          NextDialogue = 80040202,
          SpeakNpcId = 790008,
          Subtitle = "Home at last. Quick, Berry, take a seat!",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4B7A"
        },
        [80040202] = {
          ContentTC = "哎？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040202,
          FacialId = {
            [1] = "790007:Shock02"
          },
          GUID = "C85F4BA4",
          NextDialogue = 80040204,
          SpeakNpcId = 790007,
          Subtitle = "Huh?",
          TalkActionId = {
            [1] = "790008:Explain02_End",
            [2] = "790007:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4BA4"
        },
        [80040204] = {
          Camera = "-63.011719,2.983643,162.785645,-0.000092,-22.699921,59.573631,35.000008,497.258331,false,DoNotOverride,1.2",
          ContentTC = "你剛才受傷了吧？把手給我，我給你包一下。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040204,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "-58.447266,0.387207,162.785645,-0.000093,-22.699913,61.973614,35.000008,497.258331,false,DoNotOverride,1.2",
          GUID = "C85F4BF8",
          NextDialogue = 80040205,
          SpeakNpcId = 790008,
          Subtitle = "You got hurt, didn't you? Let me see your hand... I'll bandage you up.",
          TalkActionId = {
            [1] = "790007:Shock_End",
            [2] = "790008:Give"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4BF8"
        },
        [80040205] = {
          Camera = "70.48291,90.591064,138.916016,-0.000092,-4.699709,-155.827911,40.0,263.346649,false,Manual,2.991984",
          ContentTC = "不用了，只是破了點皮。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040205,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "71.906494,87.417725,138.916016,-0.000092,-4.699709,-157.628006,40.0,263.346649,false,Manual,2.991984",
          GUID = "C85F4C22",
          NextDialogue = 80040206,
          SpeakNpcId = 790007,
          Subtitle = "It's okay. Just a scratch.",
          TalkActionId = {
            [1] = "790007:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4C22"
        },
        [80040206] = {
          Camera = "188.85791,-544.567139,199.893921,-0.000091,-9.499379,114.963852,40.0,657.361633,false,Manual,2.991984",
          ContentTC = "聽我的。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040206,
          GUID = "C85F4C4C",
          NextDialogue = 80040207,
          SpeakNpcId = 790008,
          Subtitle = "Don't fight me on this.",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4C4C"
        },
        [80040207] = {
          ContentTC = "……嗯。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040207,
          GUID = "C85F4C76",
          NextDialogue = 80040208,
          SpeakNpcId = 790007,
          Subtitle = "...Okay.",
          TalkActionId = {
            [1] = "790007:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4C76"
        },
        [80040208] = {
          Camera = "-202.862793,-154.904297,120.652222,-0.000091,-1.500019,57.155331,40.0,286.969482,false,Manual,2.991984",
          ContentTC = "說過很多次了吧，遇到危險的時候先保護自己。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040208,
          FinalCamera = "-202.862793,-154.904297,120.652222,-0.000092,-0.500004,57.155106,40.0,286.969482,false,Manual,2.991984",
          GUID = "C85F4CA0",
          NextDialogue = 80040209,
          SpeakNpcId = 790008,
          Subtitle = "How many times have I told you? Always protect yourself first when there's danger.",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4CA0"
        },
        [80040209] = {
          ContentTC = "像剛才那只海雕，你直接躲開不就好了嗎！為什麼非得正面攔住它，被它抓那一下子——還疼不疼？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040209,
          GUID = "C85F4CCA",
          NextDialogue = 80040210,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-90.239258,-23.222412,118.679077,-0.000091,6.299606,53.554245,40.0,286.969482,false,DoNotOverride,2.991984\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-83.696533,-27.761963,118.679077,-0.000092,6.099605,56.553841,40.0,286.969482,false,DoNotOverride,2.991984\"},duration{5}}}",
          SpeakNpcId = 790008,
          Subtitle = "Like with that sea eagle just now — why didn't you just dodge? Why did you have to confront it head-on and get scratched... Does it still hurt?",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4CCA"
        },
        [80040210] = {
          Camera = "43.03418,84.666992,133.484863,-0.000092,-1.89996,-156.048233,40.0,225.258224,false,Manual,5.068474",
          ContentTC = "那時你就在我身後。如果躲開，它會傷到你。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040210,
          FinalCamera = "43.81665,82.903076,133.484863,-0.000092,-1.89996,-156.848312,40.0,225.258224,false,Manual,5.068474",
          GUID = "C85F4CF4",
          NextDialogue = 80040211,
          SpeakNpcId = 790007,
          Subtitle = "You were right behind me. If I had dodged, it would have hurt you.",
          TalkActionId = {
            [1] = "790008:Explain01_End",
            [2] = "790007:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4CF4"
        },
        [80040211] = {
          Camera = "178.106689,-626.217896,240.31897,-0.007873,-11.413813,102.367813,45.0,725.684692,false,Manual,1.2",
          ContentTC = "我當然也會躲呀！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040211,
          FinalCamera = "185.991943,-624.489014,240.318481,-0.007874,-11.413813,102.368073,45.0,725.684692,false,Manual,1.2",
          GUID = "C85F4D1E",
          NextDialogue = 80040212,
          SpeakNpcId = 790008,
          Subtitle = "I could have dodged it too!",
          TalkActionId = {
            [1] = "790008:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4D1E"
        },
        [80040212] = {
          Camera = "59.757324,90.571777,133.248779,-0.007874,-2.413208,-153.836533,45.0,255.283401,false,Manual,6.056871",
          ContentTC = "下次再說吧。",
          DialogueId = 80040212,
          FinalCamera = "45.11499,83.288818,132.60022,-0.007873,-2.213193,-153.236618,45.0,255.283401,false,Manual,6.056871",
          GUID = "C85F4D48",
          LookAt = {
            [1] = "790007:n(790007)"
          },
          NextDialogue = 80040213,
          SpeakNpcId = 790007,
          Subtitle = "I'll be more careful next time.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4D48"
        },
        [80040213] = {
          Camera = "-98.115723,8.075684,129.975586,-0.007874,0.586638,40.149609,45.000011,255.283401,false,DoNotOverride,6.056871",
          ContentTC = "唉，你總在說「下次」。",
          DialogueId = 80040213,
          FacialId = {
            [1] = "790008:Doubt01"
          },
          GUID = "C85F4D72",
          LookAt = {
            [1] = "790008:n(790008)"
          },
          NextDialogue = 80040214,
          SpeakNpcId = 790008,
          Subtitle = "*sighs* You always say that.",
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4D72"
        },
        [80040214] = {
          Camera = "-98.115723,8.075684,129.975586,-0.007874,0.586638,40.149609,45.000011,255.283401,false,DoNotOverride,6.056871",
          ContentTC = "小時候村子裡的大人欺負我們，你寧願和他們一群人打架也不肯服軟說點好聽的，最後老是鼻青臉腫地回家。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040214,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "-108.532959,-0.711182,129.83606,-0.007874,0.586638,40.149609,45.000011,255.283401,false,DoNotOverride,6.056871",
          GUID = "C85F4D9C",
          NextDialogue = 80040215,
          Scripts = "PARA{SEQ{PlayAnimation{_delay{2},ActorId{790008},AnimationId{\"Disagree\"},Duration{1}},PlayAnimation{ActorId{790008},AnimationId{\"Talk02_Start\"},Duration{2}}},SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-388.886475,214.343506,68.213867,-0.007874,5.1855,-35.831512,30.0,370.505707,false,Manual,1.829457\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-382.625,223.01416,68.213867,-0.007873,5.1855,-36.231453,30.0,370.505707,false,Manual,1.829457\"},duration{5}}}}",
          SpeakNpcId = 790008,
          Subtitle = "When we were kids, some bad grown-ups often picked on us. But you'd rather fight them head-on than back down with smart words, and you always ended up bruised and battered.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4D9C"
        },
        [80040215] = {
          Camera = "-73.259277,59.861328,149.804077,-0.007874,-21.015713,10.774378,30.0,370.505707,false,DoNotOverride,1.829457",
          ContentTC = "那時，你也總在說「下次不會了」，但是真到了下次，又是「對不起，下次一定」。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040215,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-72.304443,55.513428,149.803955,-0.007873,-21.015713,15.775083,30.0,370.505707,false,DoNotOverride,1.829457",
          GUID = "C85F4DC6",
          NextDialogue = 80040216,
          SpeakNpcId = 790008,
          Subtitle = "You'd always promise to be more careful next time, but every \"next time\" turned out to be another \"Sorry, I'll be more careful next time.\"",
          TalkActionId = {
            [1] = "790008:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4DC6"
        },
        [80040216] = {
          Camera = "5.696533,131.451904,130.387329,-0.007873,-1.815492,-128.821289,40.0,258.118256,false,Manual,4.735452",
          ContentTC = "我不像你。你很會說話，你會和不同的人說不同的話，但我學不會……人們太複雜了，我搞不懂他們每個人說的話背後，到底藏著些什麼意思。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040216,
          FacialId = {
            [1] = "790007:Unhappy01"
          },
          FinalCamera = "2.290283,134.191895,130.387329,-0.007874,-1.815492,-126.620598,40.0,258.118256,false,Manual,4.735452",
          GUID = "C85F4DF0",
          NextDialogue = 80040217,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Disagree\"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 790007,
          Subtitle = "I'm not like you. You're good with words and always know what to say to different people. But I can't do that... People are too complicated. I never really understand what they really mean.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4DF0"
        },
        [80040217] = {
          Camera = "-339.73584,234.869629,66.47876,-0.007874,-5.015469,-65.61985,40.0,357.85144,false,Manual,4.735452",
          ContentTC = "對我來說，唯一能解決問題的就是手裡的武器。如果沒有，那就用拳頭，用牙齒。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040217,
          FacialId = {
            [1] = "790007:Iyada01"
          },
          FinalCamera = "-339.73584,234.869629,66.47876,-0.007874,6.984585,-55.618538,40.0,357.85144,false,Manual,4.735452",
          GUID = "C85F4E1A",
          NextDialogue = 80040218,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Explain02_End\"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{\"Angry01_Start\"},Duration{2}}}",
          SpeakNpcId = 790007,
          Subtitle = "For me, the only way to solve problems is with what I have in my hands. If not weapons, then fists or teeth.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4E1A"
        },
        [80040218] = {
          Camera = "-424.4104,724.855713,8.373779,-0.007843,4.783946,-66.01899,40.0,766.54895,false,Manual,1.2",
          ContentTC = "沒關係，你不用學，你不會說，我就替你說。你總像盾牌一樣護著我，那我來當你的唇舌也沒什麼問題吧？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040218,
          FacialId = {
            [1] = "790007:None"
          },
          GUID = "C85F4E44",
          NextDialogue = 80040219,
          SpeakNpcId = 790008,
          Subtitle = "It's okay. If you're not great with words, I'll speak for you, just like you've always protected me like a shield.",
          TalkActionId = {
            [1] = "790007:Angry01_End",
            [2] = "790008:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4E44"
        },
        [80040219] = {
          Camera = "-424.4104,724.855713,8.373779,-0.007843,4.783946,-66.01899,40.0,766.54895,false,Manual,1.2",
          ContentTC = "但你一定答應我——千萬改掉這個壞習慣，好嗎？你現在已經那麼厲害，已經再也不用拼命了，那樣多疼啊！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040219,
          FinalCamera = "-434.378906,747.266113,6.320801,-0.007843,4.783933,-66.019035,40.000011,766.54895,false,Manual,1.2",
          GUID = "C85F4E6E",
          NextDialogue = 80040220,
          Scripts = "PARA{SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Confident_End\"},Duration{1}},PlayAnimation{ActorId{790008},AnimationId{\"Explain02_Start\"},Duration{2}}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-237.577637,-56.880371,136.112793,-0.007843,-3.616394,23.585123,40.0,252.407059,false,Manual,3.041301\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-239.688965,-52.041992,136.112915,-0.007843,-3.616394,22.384497,40.0,252.407059,false,Manual,3.041301\"},duration{5}}}}",
          SpeakNpcId = 790008,
          Subtitle = "But you have to promise me to break this charging head-on habit, okay? You're strong now, you don't have to put yourself in danger anymore — it must hurt a lot.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4E6E"
        },
        [80040220] = {
          Camera = "-94.835938,54.04541,128.02002,-0.007843,0.983943,-124.007088,40.0,252.407059,false,DoNotOverride,3.041301",
          ContentTC = "疼沒什麼，忍一忍就過去了。「不怕痛的人就沒有弱點」……這樣的戰鬥方式最高效。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040220,
          FinalCamera = "-94.835938,54.04541,128.02002,-0.007843,2.583935,-123.607208,40.0,252.407059,false,DoNotOverride,3.041301",
          GUID = "C85F4E98",
          NextDialogue = 80040221,
          SpeakNpcId = 790007,
          Subtitle = "Pain is nothing; it'll pass if I just bear it for a while. \"Those who don't fear pain have no weaknesses\"... This way of fighting is the most efficient.",
          TalkActionId = {
            [1] = "790007:Disagree",
            [2] = "790008:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4E98"
        },
        [80040221] = {
          Camera = "-395.181152,219.987061,63.147217,-0.007843,6.183937,-36.005211,30.0,386.208527,false,Manual,3.041301",
          ContentTC = "……好吧！我懂了。既然這種戰鬥方式這麼好用，那我也得好好學著。下次遇到危險，我也卯足勁兒往上沖好了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040221,
          FacialId = {
            [1] = "790008:Confident02"
          },
          FinalCamera = "-391.083008,225.627441,63.147217,-0.007843,6.183937,-36.405159,30.0,386.208527,false,Manual,3.041301",
          GUID = "C85F4EC2",
          NextDialogue = 80040222,
          SpeakNpcId = 790008,
          Subtitle = "...Fine! If it works so well, guess I should learn it too. Next time there's danger, I'll just charge right in.",
          TalkActionId = {
            [1] = "790008:Angry01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4EC2"
        },
        [80040222] = {
          Camera = "-109.587891,12.95166,125.755493,-0.007873,7.584364,-131.99675,35.0,386.208527,false,DoNotOverride,3.041301",
          ContentTC = "你——我和你不一樣！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040222,
          FacialId = {
            [1] = "790007:Shock01"
          },
          FinalCamera = "-59.141113,68.984863,115.716064,-0.007874,4.584334,-132.397003,35.0,386.208527,false,DoNotOverride,3.041301",
          GUID = "C85F4EEC",
          NextDialogue = 80040223,
          SpeakNpcId = 790007,
          Subtitle = "You... No, it's different for you!",
          TalkActionId = {
            [1] = "790008:Angry01_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4EEC"
        },
        [80040223] = {
          Camera = "-313.623535,-68.812988,127.089478,-0.007873,-2.815766,17.007097,35.0,386.208527,false,DoNotOverride,3.041301",
          ContentTC = "沒什麼不一樣的。你看，我這麼說讓你很擔心對吧？要知道我的擔心一丁點都不比你少。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040223,
          FacialId = {
            [1] = "790008:None",
            [2] = "790007:None"
          },
          FinalCamera = "-313.623535,-68.812988,127.089478,-0.007874,-0.415774,17.007204,35.0,386.208527,false,DoNotOverride,3.041301",
          GUID = "C85F4F16",
          NextDialogue = 80040224,
          SpeakNpcId = 790008,
          Subtitle = "What's the difference? Just saying that worries you, doesn't it? You should know how your habit worries me, too.",
          TalkActionId = {
            [1] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4F16"
        },
        [80040224] = {
          Camera = "-313.623535,-68.812988,127.089478,-0.007874,-0.415774,17.007204,35.0,386.208527,false,DoNotOverride,3.041301",
          ContentTC = "所以，就當是為了我——多在意自己一點，好不好？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040224,
          FacialId = {
            [1] = "790008:Satisfy01"
          },
          GUID = "C85F4F40",
          NextDialogue = 80040225,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-360.918457,599.776611,232.019409,-0.007874,-12.815278,-65.194618,35.0,680.022278,false,Manual,1.219374\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-368.207275,615.547363,235.971558,-0.007874,-12.815278,-65.194618,35.0,680.022278,false,Manual,1.219374\"},duration{5}}}",
          SpeakNpcId = 790008,
          Subtitle = "So, at least for my sake — take good care of yourself, okay?",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4F40"
        },
        [80040225] = {
