          SpeakNpcId = 790004,
          Subtitle = "But I know that even though {性别:he|she} was right in front of me, {性别:he|she} was actually very far away, as far as Icelake is from the ocean.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF34"
        },
        [80080307] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "所以即使{性别:他|她}拉住我，我也無法回握住{性别:他|她}。就像我拼命看著{性别:他|她}，卻什麽都看不到一樣。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080307,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FF5E",
          LookAt = {
            [1] = "790004:n(790005)"
          },
          NextDialogue = 80080308,
          SpeakNpcId = 790004,
          Subtitle = "So even though {性别:he|she} reached out, I couldn't really grasp {性别:his|her} hand, just as I tried so hard to look at {性别:him|her}, but couldn't see anything.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF5E"
        },
        [80080308] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……賽琪，我要告訴你一件事。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080308,
          GUID = "C878FF88",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080309,
          SpeakNpcId = 790005,
          Subtitle = "...Psyche, there's something I want you to know.",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790005:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF88"
        },
        [80080309] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "抑制穢蝕的藥物，已經完成了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080309,
          GUID = "C878FFB2",
          NextDialogue = 80080310,
          SpeakNpcId = 790005,
          Subtitle = "The development of anti-deterioration medication is finished.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FFB2"
        },
        [80080310] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那麽快？我以為您會花更長時間研究……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080310,
          FacialId = {
            [1] = "790004:Shock01"
          },
          GUID = "C878FFDC",
          NextDialogue = 80080311,
          SpeakNpcId = 790004,
          Subtitle = "Already? I thought the research would take longer...",
          TalkActionId = {
            [1] = "790004:Alright_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FFDC"
        },
        [80080311] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "很多年前我就研究過，但因為海莉的死擱置了。現在為了你……為了你們，我才會把它再度拾起來。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080311,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C8790006",
          LookAt = {
            [1] = "790005:n(790004)"
          },
          NextDialogue = 80080312,
          SpeakNpcId = 790005,
          Subtitle = "I started the research years ago but put it aside after Hayley's death. I only picked it up again for you... for all of you.",
          TalkActionId = {
            [1] = "790005:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790006"
        },
        [80080312] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "好在此前的理論都還好好刻在我腦子裡，只要有了最關鍵的<H>群星綺晶</>，我就可以復現實驗的大部分步驟……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080312,
          GUID = "C8790030",
          NextDialogue = 80080313,
          SpeakNpcId = 790005,
          Subtitle = "Fortunately, all the previous theoretical data is still fresh in my mind, and with that piece of the Crystallo of Stella, I managed to replicate most of the experimental steps...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790030"
        },
        [80080313] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "太好了！您的研究成功了……但，這是一件喜事吧？恩里克叔叔，您的聲音為什麽聽起來那麽難過？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080313,
          GUID = "C879005A",
          NextDialogue = 80080314,
          SpeakNpcId = 790004,
          Subtitle = "That's great! Your research succeeded! But... this is good news, right? Why do you still look so sad...?",
          TalkActionId = {
            [1] = "790004:Alright_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879005A"
        },
        [80080314] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "唉，我也不知道你能不能聽懂……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080314,
          GUID = "C8790084",
          NextDialogue = 80080315,
          SpeakNpcId = 790005,
          Subtitle = "*sigh* It's complicated...",
          TalkActionId = {
            [1] = "790005:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790084"
        },
        [80080315] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "綺晶是一種極不穩定的物質。在特定的藥物輔助下，它可以抑制穢蝕的進程，但也有可能加速穢蝕的進程……而兩者的合成方式僅有極細微的差別。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080315,
          GUID = "C87900AE",
          NextDialogue = 80080316,
          SpeakNpcId = 790005,
          Subtitle = "Crystallo is highly unstable. Under specific medicinal catalysts, it can suppress the process of deterioration, or accelerate it... The conditions triggering each process are only minutely different.",
          TalkActionId = {
            [1] = "790005:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87900AE"
        },
        [80080316] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "關於綺晶的所有華胥藥學論著都在海伯利亞失傳了，我無法從理論層面判斷自己的每一步是否都正確。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080316,
          GUID = "C87900D8",
          NextDialogue = 80080317,
          SpeakNpcId = 790005,
          Subtitle = "Sadly, all the relevant pharmacological texts from Huaxu were lost in Hyperborea, and I can't verify each step of my work purely through theory.",
          TalkActionId = {
            [1] = "790005:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87900D8"
        },
        [80080317] = {
          Camera = "271.882812,218.0,222.382812,0.0,0.0,-172.398712,35.0,500.0,false,Manual,2.8",
          ContentTC = "唯一的辦法，只有臨床實驗……可是我不敢將未經驗證的藥物用在你們身上。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080317,
          FinalCamera = "271.882812,268.0,222.382812,0.0,0.0,-172.398712,35.0,300.0,false,Manual,2.8",
          GUID = "C8790102",
          NextDialogue = 80080318,
          SpeakNpcId = 790005,
          Subtitle = "The only option is clinical trials... but I can't bring myself to test an unverified new drug on you.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790102"
        },
        [80080318] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603367,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "或許就是因為恩里克叔叔這麽善良……穢蝕抑制藥物才一直得不到驗證吧？我願意協助您的研究。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080318,
          GUID = "C879012C",
          NextDialogue = 80080319,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 790004,
          Subtitle = "Perhaps your kindness is why the research on the anti-deterioration drug hasn't progressed further. Dr Henrik, please allow me to help you with the clinical trials.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879012C"
        },
        [80080319] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "修普諾斯之家的建立是為了拂去痛苦……如果拿你們做實驗，那我跟軍團做的事又有什麽區別？！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080319,
          GUID = "C8790156",
          NextDialogue = 80080320,
          SpeakNpcId = 790005,
          Subtitle = "Hypnos' House was founded to alleviate suffering... If I use you for experiments, how am I any different from the Legion!?",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790005:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790156"
        },
        [80080320] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不是這樣的……恩里克叔叔一直在照顧我們，減輕我們的痛苦，但這些痛苦並沒有消失，只是由您獨自背負起來了而已。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080320,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C8790180",
          NextDialogue = 80080321,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"DisagreeHead\"},Duration{1}},PlayAnimation{ActorId{790004},AnimationId{\"Talk02_Start\"},Duration{2}}}",
          SpeakNpcId = 790004,
          Subtitle = "It's not like that... You've been taking care of us, going out of your way to ease our pain, but the pain hasn't disappeared — you've simply taken it upon yourself.",
          TalkActionId = {
            [1] = "790005:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790180"
        },
        [80080321] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "所以，讓我也代替您承擔一些吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080321,
          GUID = "C87901AA",
          NextDialogue = 80080322,
          SpeakNpcId = 790004,
          Subtitle = "So, please let me share some of that burden.",
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901AA"
        },
        [80080322] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你說得輕松，你知道喝下那杯藥劑對你來說意味著什麽嗎？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080322,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C87901D4",
          NextDialogue = 80080323,
          SpeakNpcId = 790005,
          Subtitle = "It's more complicated than you might think... Do you realise what could happen if you take that medicine?",
          TalkActionId = {
            [1] = "790005:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901D4"
        },
        [80080323] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我不知道我理解的對不對……您的意思是不是，它可能有用，也可能沒用？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080323,
          GUID = "C87901FE",
          NextDialogue = 80080324,
          Scripts = "SEQ{LookAt{LookAtDescription{\"790004:n(790004)\"}},LookAt{_delay{2},LookAtDescription{\"790004:n(790005)\"}}}",
          SpeakNpcId = 790004,
          Subtitle = "... I'm not sure if I get this right. Do you mean it might work, but also might not?",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901FE"
        },
        [80080324] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……五成希望。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080324,
          GUID = "C8790228",
          NextDialogue = 80080325,
          SpeakNpcId = 790005,
          Subtitle = "There's a fifty-fifty chance.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790228"
        },
        [80080325] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "一半的可能，你會痊愈，獲得第二次生命。另一半的可能……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080325,
          GUID = "C8790252",
          NextDialogue = 80080326,
          SpeakNpcId = 790005,
          Subtitle = "You could recover and gain a second chance at life, or...",
          TalkActionId = {
            [1] = "790005:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790252"
        },
        [80080326] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你的穢蝕狀況會快速惡化……它會連你生命最後的幾天也全部掠奪。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080326,
          GUID = "C879027C",
          NextDialogue = 80080327,
          SpeakNpcId = 790005,
          Subtitle = "Your condition could deteriorate rapidly... You might even be robbed of your last moments.",
          TalkActionId = {
            [1] = "790005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879027C"
        },
        [80080327] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "…………",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080327,
          GUID = "C87902A6",
          LookAt = {
            [1] = "790004:n(790004)"
          },
          NextDialogue = 80080328,
          SpeakNpcId = 790004,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902A6"
        },
        [80080328] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "恩里克叔叔，我已經做好決定了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080328,
          GUID = "C87902D0",
          LookAt = {
            [1] = "790004:n(790005)"
          },
          NextDialogue = 80080329,
          SpeakNpcId = 790004,
          Subtitle = "Dr Henrik, I've made up my mind.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902D0"
        },
        [80080329] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "穢蝕抑制藥物，是減輕我們所有人痛苦的一個可能。就算只有萬分之一的希望，我也願意協助您完成這項藥物的研究。更何況……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080329,
          GUID = "C87902FA",
          NextDialogue = 80080330,
          SpeakNpcId = 790004,
          Subtitle = "The anti-deterioration drug is a chance to ease the pain of us all. Even if the chances of success are slim to none, I'd still like to help with your research. Besides...",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902FA"
        },
        [80080330] = {
          Camera = "-127.080078,-30.343323,142.15625,0.000079,-5.799957,57.598873,50.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我，我感覺我變了……變得不再是過去的我自己。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080330,
          GUID = "C8790324",
          NextDialogue = 80080331,
          SpeakNpcId = 790004,
          Subtitle = "I feel like I've changed... I'm not who I used to be.",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790324"
        },
        [80080331] = {
          Camera = "-87.792969,98.007385,119.857422,0.000075,6.799897,-100.99704,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「變了」……？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080331,
          GUID = "C879034E",
          NextDialogue = 80080332,
          SpeakNpcId = 790005,
          Subtitle = "What do you mean?",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879034E"
        },
        [80080332] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "自從認識了一個人，經歷了一場冒險之後，我就變了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080332,
          GUID = "C8790378",
          NextDialogue = 80080333,
          SpeakNpcId = 790004,
          Subtitle = "I've changed ever since I met someone and went on an adventure.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790378"
        },
        [80080333] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "現在的我變貪心了許多許多……我開始渴望能再多一些時間，再多一些……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080333,
          GUID = "C87903A2",
          NextDialogue = 80080334,
          SpeakNpcId = 790004,
          Subtitle = "I've become much greedier... I now yearn for more time, more of everything...",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903A2"
        },
        [80080334] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我開始渴望可以牽起一個人的手，一起逃離冰湖城，到很遠、很遠的地方……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080334,
          GUID = "C87903CC",
          NextDialogue = 80080335,
          SpeakNpcId = 790004,
          Subtitle = "I wish to hold someone's hand and escape Icelake, to travel to far-off lands...",
          TalkActionId = {
            [1] = "790004:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903CC"
        },
        [80080335] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我開始渴望可以長到爸爸媽媽的年紀……可以變成滿臉皺紋的老婆婆……可以坐在廣場上，一邊給鳥兒餵食，一邊和城裡的孩子們講述年輕時的故事……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080335,
          GUID = "C87903F6",
          NextDialogue = 80080336,
          SpeakNpcId = 790004,
          Subtitle = "I wish to grow older... so that one day I'll become a wrinkled old lady, sitting in the square, feeding birds and sharing stories of my youth with children...",
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903F6"
        },
        [80080336] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我曾以為，我只要過好最後的日子就已經足夠了。但是現在的我想要……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080336,
          GUID = "C8790420",
          NextDialogue = 80080337,
          SpeakNpcId = 790004,
          Subtitle = "I once thought that making the most of my last days was enough. But now, I want more...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790420"
        },
        [80080337] = {
          Camera = "-115.541016,2.555298,138.173828,0.000146,-6.001127,46.597878,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「活下去」。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080337,
          GUID = "C879044A",
          NextDialogue = 80080338,
          SpeakNpcId = 790004,
          Subtitle = "I want to LIVE.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879044A"
        },
        [80080338] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "所以，恩里克叔叔，請答應我的請求吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080338,
          GUID = "C8790474",
          NextDialogue = 80080339,
          SpeakNpcId = 790004,
          Subtitle = "So, Dr Henrik, please allow me to help with the research.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790474"
        },
        [80080339] = {
          Camera = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「既然我註定不能像人一樣地活著，那麽我希望像人一樣地死去……」",
          DialogueId = 80080339,
          GUID = "C879049E",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080340,
          SpeakNpcId = 790005,
          Subtitle = "\"If fate decides I can't live like a person, then at least let me die like one...\"",
          TalkActionId = {
            [1] = "790005:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879049E"
        },
        [80080340] = {
          Camera = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這是海莉——我的女兒，在最後一夜對我傾訴的願望。你們如此相似，但又如此不同……",
          DialogueId = 80080340,
          GUID = "C87904C8",
          LookAt = {
            [1] = "790005:n(790004)"
          },
          NextDialogue = 80080341,
          SpeakNpcId = 790005,
          Subtitle = "That was Hayley — my daughter's last wish. You and her are so alike, yet so different...",
          TalkActionId = {
            [1] = "790005:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87904C8"
        },
        [80080341] = {
          Camera = "-137.392578,-0.853027,138.126953,0.000042,13.199668,-95.195374,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「像人一樣地活下去」——我明白你的願望了。",
          DialogueId = 80080341,
          GUID = "C87904F2",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080342,
          SpeakNpcId = 790005,
          Subtitle = "\"To live like a person\" — I understand your wish now.",
          TalkActionId = {
            [1] = "790005:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87904F2"
        },
        [80080342] = {
          Camera = "-123.386719,-265.981384,183.080078,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentTC = "命運啊……求你憐憫我唯一一次……讓我幫她實現這個願望吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080342,
          FinalCamera = "-123.013672,-238.728149,177.398438,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "C879051C",
          SpeakNpcId = 790005,
          Subtitle = "Fate, grant me mercy just this once... allow me to help her fulfil this wish.",
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "790005:p(180)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879051C"
        },
        [80090100] = {
          ContentTC = "嘻嘻，今天要玩什麼？",
          DialogueId = 80090100,
          GUID = "C87F4608",
          Subtitle = "Heehee, what mischief shall we get into today?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4608"
        },
        [80090101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "……",
          DialogueId = 80090101,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4632",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090102,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4632"
        },
        [80090102] = {
          ContentTC = "……",
          DialogueId = 80090102,
          GUID = "C87F465C",
          NextDialogue = 80090103,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F465C"
        },
        [80090103] = {
          ContentTC = "……喂！我剛才喝完飲料突然消失了，你怎麼跟沒事人似的！",
          DialogueId = 80090103,
          GUID = "C87F4686",
          NextDialogue = 80090104,
          SpeakNpcId = 92301,
          Subtitle = "...Hey! Didn't you see I suddenly vanished after finishing my drink? How could you just act like nothing happened?!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4686"
        },
        [80090104] = {
          ContentTC = "光天化日之下，「惡魔大盜」神秘失蹤！你就不覺得很奇怪、很擔心嗎！",
          DialogueId = 80090104,
          GUID = "C87F46B0",
          NextOptions = {
            [1] = 80090105,
            [2] = 80090107
          },
          SpeakNpcId = 92301,
          Subtitle = "Right in broad daylight, Demon Tabethe the Red Hand mysteriously disappeared! Aren't you at least a bit curious or worried?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F46B0"
        },
        [80090105] = {
          ContentTC = "剛才這裡多了一把椅子，那是你變的吧。",
          DialogueId = 80090105,
          GUID = "C87F46DA",
          NextDialogue = 80090106,
          Subtitle = "There was an extra chair here... It was you, wasn't it?"
        },
        [80090106] = {
          ContentTC = "什麼！你居然看破了我的偽裝絕技！",
          DialogueId = 80090106,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F4704",
          NextDialogue = 80090109,
          SpeakNpcId = 92301,
          Subtitle = "What?! You saw through my awesome disguise?!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4704"
        },
        [80090107] = {
          ContentTC = "擔心？塔比瑟變成椅子逗我開心，我欣慰才是。",
          DialogueId = 80090107,
          GUID = "C87F472E",
          NextDialogue = 80090108,
          Subtitle = "Why would I be worried? If anything, I appreciate that you turned into a chair just to entertain me."
        },
        [80090108] = {
          ContentTC = "噫，你也太自作多情了，我只是想嚇唬你！嚇——唬！",
          DialogueId = 80090108,
          GUID = "C87F4758",
          NextDialogue = 80090109,
          SpeakNpcId = 92301,
          Subtitle = "Pff, get over yourself — I was just trying to spook you! BOO! Get it?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4758"
        },
        [80090109] = {
          ContentTC = "……嘁，這次算我失手了，下次我一定變成你想不到的東西！",
          DialogueId = 80090109,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4782",
          NextDialogue = 80090110,
          SpeakNpcId = 92301,
          Subtitle = "Hmph, I slipped up this time. But next time, I'll turn into something you'd never expect!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4782"
        },
        [80090110] = {
          ContentTC = "變什麼好呢……酒桶？吊燈？大錘？",
          DialogueId = 80090110,
          GUID = "C87F47AC",
          NextDialogue = 80090111,
          SpeakNpcId = 92301,
          Subtitle = "What to turn into next... Maybe a barrel? A chandelier? Or even a big hammer?",
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F47AC"
        },
        [80090111] = {
          ContentTC = "哇哦，你好有本領。",
          DialogueId = 80090111,
          GUID = "C87F47D6",
          NextDialogue = 80090112,
          SpeakNpcId = 790008,
          Subtitle = "Wow, you're really good at this.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F47D6"
        },
        [80090112] = {
          ContentTC = "那當然！聽說我這本事叫做……泥，泥什麼來著……泥台？……擬態！對對，「擬態」！",
          DialogueId = 80090112,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4800",
          NextDialogue = 80090113,
          SpeakNpcId = 92301,
          Subtitle = "Of course! I heard this trick of mine is called... caramel... camel... camel-something... Ah — camouflage! That's it!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4800"
        },
        [80090113] = {
          ContentTC = "所以你什麼都能變？",
          DialogueId = 80090113,
          GUID = "C87F482A",
          NextDialogue = 80090114,
          SpeakNpcId = 790008,
          Subtitle = "So you can turn into anything?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F482A"
        },
        [80090114] = {
          ContentTC = "嘻嘻，可不是！看好了——",
          DialogueId = 80090114,
          GUID = "C87F4854",
          NextDialogue = 80090144,
          SpeakNpcId = 92301,
          Subtitle = "Hehe, you bet! Watch this—",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4854"
        },
        [80090115] = {
          Camera = "159.880188,-5.018555,149.99321,0.000005,1.39885,175.800934,30.000002,159.585938,false,Manual,3.0",
          ContentTC = "我會提出一個你無法拒絕的條件，你最好深思熟慮之後再回答我。",
          DialogueId = 80090115,
          GUID = "C87F487E",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090116,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "I'll make an offer you can't refuse. Think it over before you respond.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F487E"
        },
        [80090116] = {
          ContentTC = "叫醒我的是生意，叫醒你的是什麼？",
          DialogueId = 80090116,
          GUID = "C87F48A8",
          NextOptions = {
            [1] = 80090117,
            [2] = 80090119
          },
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What wakes me is business; what about you?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F48A8"
        },
        [80090117] = {
          ContentTC = "噗嗤——叫醒我的是惡魔大盜的萬丈光芒！",
          DialogueId = 80090117,
          GUID = "C87F48D2",
          NextDialogue = 80090118,
          Subtitle = "Haha — what wakes me is the blinding brilliance of Demon Tabethe the Red Hand!"
        },
        [80090118] = {
          ContentTC = "嘻嘻，嘴真甜，比你調的飲料還甜！",
          DialogueId = 80090118,
          FacialId = {
            [1] = "790052:Happy01"
          },
          GUID = "C87F48FC",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hehe, you're so sweet — sweeter than this drink you made!",
          TalkActionId = {
            [1] = "790052:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F48FC"
        },
        [80090119] = {
          ContentTC = "噗嗤——我告卡蜜拉了！",
          DialogueId = 80090119,
          GUID = "C87F4926",
          NextDialogue = 80090120,
          Subtitle = "Haha — I'm going to tell on you to Camilla!"
        },
        [80090120] = {
          ContentTC = "我才不怕她嘞！沒人能抓到惡魔大盜！",
          DialogueId = 80090120,
          FacialId = {
            [1] = "790052:Confident01"
          },
          GUID = "C87F4950",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "I'm not scared of her! No one can catch Demon Tabethe the Red Hand!",
          TalkActionId = {
            [1] = "790052:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4950"
        },
        [80090121] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "不過我也不是什麼都會變，太大和太小的東西都不行。貓咪可以，老鼠就不可以。木桶可以，路燈架子就不可以。",
          DialogueId = 80090121,
          GUID = "C87F497A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090122,
          SpeakNpcId = 92301,
          Subtitle = "But I can't turn into anything too big or too small. I can do a cat, but not a mouse; a barrel, but not a lamppost.",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F497A"
        },
        [80090122] = {
          ContentTC = "但這就足夠了，大部分人根本發現不了我的完美偽裝！我隨便變個罐子箱子垃圾桶什麼的，那些壞小偷啊，就只能乖乖地被我收拾了！",
          DialogueId = 80090122,
          GUID = "C87F49A4",
          NextOptions = {
            [1] = 80090123,
            [2] = 80090131
          },
          SpeakNpcId = 92301,
          Subtitle = "That's enough to fool most people, though. I can just turn into a bin or a crate, and those rotten thieves won't know what hit them!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F49A4"
        },
        [80090123] = {
          ContentTC = "……完了，以後可有得頭疼了。",
          DialogueId = 80090123,
          GUID = "C87F49CE",
          NextDialogue = 80090124,
          Subtitle = "...Oh boy, this might be a problem someday."
        },
        [80090124] = {
          ContentTC = "你嘀嘀咕咕什麼呢？",
          DialogueId = 80090124,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F49F8",
          NextDialogue = 80090125,
          SpeakNpcId = 92301,
          Subtitle = "What are you mumbling about?",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F49F8"
        },
        [80090125] = {
          ContentTC = "沒什麼，誇你很厲害的意思。",
          DialogueId = 80090125,
          GUID = "C87F4A22",
          NextDialogue = 80090126,
          SpeakNpcId = 790008,
          Subtitle = "Nothing, I just meant you are awesome.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A22"
        },
        [80090126] = {
          ContentTC = "但之後還是別變箱子罐子垃圾桶了，萬一被人路過隨手打爛了然後翻翻找找有用的東西可怎麼辦……",
          DialogueId = 80090126,
          GUID = "C87F4A4C",
          NextDialogue = 80090127,
          SpeakNpcId = 790008,
          Subtitle = "But maybe avoid turning into bins or crates next time. Wouldn't want someone accidentally smashing you while looking for something useful...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A4C"
        },
        [80090127] = {
          ContentTC = "誰手這麼欠啊？",
          DialogueId = 80090127,
          GUID = "C87F4A76",
          NextDialogue = 80090128,
          SpeakNpcId = 92301,
          Subtitle = "Who would do that?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A76"
        },
        [80090128] = {
          ContentTC = "呃……一些特別富有好奇心的路過市民？",
          DialogueId = 80090128,
          GUID = "C87F4AA0",
          NextDialogue = 80090129,
          SpeakNpcId = 790008,
          Subtitle = "Er... some overly curious passersby, perhaps?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4AA0"
        },
        [80090129] = {
          ContentTC = "有用的就收起來，沒用的就利用完丟掉，壞大人都一個樣！",
          DialogueId = 80090129,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4ACA",
          NextDialogue = 80090130,
          SpeakNpcId = 92301,
          Subtitle = "Always taking what's useful and tossing the rest — typical bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4ACA"
        },
        [80090130] = {
          ContentTC = "路過市民可沒想傷害任何人！不過，你一直掛在嘴上的「壞大人」是什麼？",
          DialogueId = 80090130,
          GUID = "C87F4AF4",
          NextDialogue = 80090136,
          SpeakNpcId = 790008,
          Subtitle = "Those passersby wouldn't mean to hurt anyone! Anyway, who are those \"bad grown-ups\" you always talk about?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4AF4"
        },
        [80090131] = {
          ContentTC = "聽起來很厲害，還好你沒什麼壞心思。",
          DialogueId = 80090131,
          GUID = "C87F4B1E",
          NextDialogue = 80090132,
          Subtitle = "Sounds impressive; good thing you're not a baddy."
        },
        [80090132] = {
          ContentTC = "什麼意思？",
          DialogueId = 80090132,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F4B48",
          NextDialogue = 80090133,
          SpeakNpcId = 92301,
          Subtitle = "What do you mean?",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B48"
        },
        [80090133] = {
          ContentTC = "我是說，要是那些有點小聰明但心思很壞的傢伙有這種本事，那整座城都要雞飛狗跳了。",
          DialogueId = 80090133,
          GUID = "C87F4B72",
          NextDialogue = 80090134,
          SpeakNpcId = 790008,
          Subtitle = "I mean, imagine if someone smart but nasty had your skills — the whole town would be in chaos.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B72"
        },
        [80090134] = {
          ContentTC = "哼哼，我也這麼覺得！我和那些壞大人可不是一路人。等等，你難道是想說本「惡魔大盜」不夠聰明？",
          DialogueId = 80090134,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F4B9C",
          NextDialogue = 80090135,
          SpeakNpcId = 92301,
          Subtitle = "Mm-hmm, I thought so too! I'm nothing like those bad grown-ups. Wait, are you saying I'm not smart?",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B9C"
        },
        [80090135] = {
          ContentTC = "沒有沒有，塔比瑟是很聰明的好惡魔。不過這些不重要，我更好奇，「那些壞大人」是什麼？",
          DialogueId = 80090135,
          GUID = "C87F4BC6",
          NextDialogue = 80090136,
          SpeakNpcId = 790008,
          Subtitle = "Of course not, Tabethe is very smart. Anyway, I've been curious about these \"bad grown-ups\" you always talk about. Who are they?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4BC6"
        },
        [80090136] = {
          ContentTC = "就是欺負弱小的壞蛋大人！我最先碰到的壞大人就是孤兒院那些照顧小孩的……嘖，說是照顧，其實和看犯人沒啥兩樣。",
          DialogueId = 80090136,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4BF0",
          NextDialogue = 80090137,
          SpeakNpcId = 92301,
          Subtitle = "Any bullies who pick on the weak! The first time I met bad grown-ups was at the orphanage. Those caretakers... well, calling them \"caretakers\" is a stretch — they were more like jailers.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4BF0"
        },
        [80090137] = {
          ContentTC = "小時候我餓著肚子去廚房找東西吃，被那些壞大人們發現了的話，就會挨打。壞死了！明明是他們不給我東西吃在先！",
          DialogueId = 80090137,
          GUID = "C87F4C1A",
          NextDialogue = 80090138,
          SpeakNpcId = 92301,
          Subtitle = "Back then, when they caught me sneaking food in the kitchen, they'd beat me. Ugh, those monsters! I only did it because they never fed me enough!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4C1A"
        },
        [80090138] = {
          ContentTC = "要是現在再讓我遇到他們，我就把他們一個個倒立著捆起來掛在房頂，讓他們瞪大眼看著我把廚房的東西吃光光！",
          DialogueId = 80090138,
          GUID = "C87F4C44",
          NextOptions = {
            [1] = 80090139,
            [2] = 80090140
          },
          SpeakNpcId = 92301,
          Subtitle = "If I ran into them now, I'd hang them upside down from the ceiling and make them watch as I eat up all the food in the kitchen!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4C44"
        },
        [80090139] = {
          ContentTC = "都過去了。現在的塔比瑟已經不會被壞大人打了。",
          DialogueId = 80090139,
          GUID = "C87F4C6E",
          NextDialogue = 80090141,
          Subtitle = "There, there. Those bad grown-ups can't hurt you anymore."
        },
        [80090140] = {
          ContentTC = "對，這些壞傢伙就該給點顏色瞧瞧。",
          DialogueId = 80090140,
          GUID = "C87F4C98",
          NextDialogue = 80090141,
          Subtitle = "Sounds great! Those baddies so deserve that."
        },
        [80090141] = {
          ContentTC = "哼！就是就是！",
          DialogueId = 80090141,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4CC2",
          NextDialogue = 80090142,
          SpeakNpcId = 92301,
          Subtitle = "Hmph! Exactly!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4CC2"
        },
        [80090142] = {
          ContentTC = "飲料喝完了，「壞大人」的事下次再講，現在快陪我出去玩！",
          DialogueId = 80090142,
          GUID = "C87F4CEC",
          NextDialogue = 80090143,
          SpeakNpcId = 92301,
          Subtitle = "Alright, I've finished my drink. I'll tell you more about those bad grown-ups next time. Now, let's go play outside!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4CEC"
        },
        [80090143] = {
          ContentTC = "嘻嘻嘻，我們來玩捉迷藏吧，這次我可不會再被你輕鬆找到了！",
          DialogueId = 80090143,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F4D16",
          SpeakNpcId = 92301,
          Subtitle = "Hehehe, wanna play hide and seek? I bet you won't find me so easily this time!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4D16"
        },
        [80090144] = {
          DialogueId = 80090144,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "C87F4D17",
          IsBlack = 1
        },
        [80090201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "嗯~喝起來有點鹹鹹的，不過好好喝喔，就像海風味的棉花糖一樣！",
          DialogueId = 80090201,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F569A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090202,
          SpeakNpcId = 92301,
          Subtitle = "Mmm, this drink's a bit salty but so yummy — like sea breeze-flavored cotton candy!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F569A"
        },
        [80090202] = {
          ContentTC = "總感覺在很久很久以前我好像喝過類似的飲料，那時候我和爸爸媽媽一起乘上的船還沒有沉，我也還沒有漂到鎮上被孤兒院收養……",
          DialogueId = 80090202,
          GUID = "C87F56C4",
          NextDialogue = 80090203,
          SpeakNpcId = 92301,
          Subtitle = "It kind of reminds me of something I drank long ago... back when I was still with my mom and dad, before our ship sank and I ended up at that orphanage...",
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F56C4"
        },
        [80090203] = {
          ContentTC = "但如果再讓我選，還不如自己一個人流浪呢！壞大人們連吃的都不願多給，更別說飲料了。",
          DialogueId = 80090203,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F56EE",
          NextDialogue = 80090204,
          SpeakNpcId = 92301,
          Subtitle = "But honestly, I'd choose wandering on my own over staying with those bad grown-ups! They were stingy with food, not to mention anything as nice as a drink.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F56EE"
        },
        [80090204] = {
          ContentTC = "就算是流浪好歹也能在垃圾桶裡撿點吃的，總比在壞大人魔爪下餓肚子強多了！",
          DialogueId = 80090204,
          GUID = "C87F5718",
          NextDialogue = 80090205,
          SpeakNpcId = 92301,
          Subtitle = "At least being on the streets, I could scavenge for something to eat — beats starving under the watch of those bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5718"
        },
        [80090205] = {
          ContentTC = "等到長大點了，就會有群貴客時不時帶走一些和我一樣沒人要的長角小孩，說是被有錢人領養了。",
          DialogueId = 80090205,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F5742",
          NextDialogue = 80090206,
          SpeakNpcId = 92301,
          Subtitle = "When I got a bit older, groups of rich visitors would come by now and then, taking away some unwanted kids with horns like me. People at the orphanage said they were adopted by rich families.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5742"
        },
        [80090206] = {
          ContentTC = "我不想要別的爸爸媽媽，但有錢人家一定不缺吃的，我想去，但壞大人說我調皮搗蛋又不老實，貴客才不會看上我咧！",
          DialogueId = 80090206,
          GUID = "C87F576C",
          NextDialogue = 80090207,
          SpeakNpcId = 92301,
          Subtitle = "I didn't want new parents, but I thought being in a rich home meant I'd never go hungry again, so I wanted them to take me. But those bad grown-ups said no rich people would want a naughty troublemaker like me.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F576C"
        },
        [80090207] = {
          ContentTC = "哼！那又怎麼樣，要是乖乖聽話我就不是塔比瑟了！反正這鬼地方我是一天也待不下去了，於是我就趁著貴客不注意，變成了他的手提箱。",
          DialogueId = 80090207,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5796",
          NextDialogue = 80090208,
          SpeakNpcId = 92301,
          Subtitle = "Hmph! As if I'd ever behave just to be chosen! I couldn't stand that awful place for another day, so during their visit, I transformed into one of their suitcases.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5796"
        },
        [80090208] = {
          ContentTC = "看來所謂的有錢人也不怎麼聰明嘛！貴客把我拎起來就走，什麼也沒發現，就是苦了我的耳朵，被當成提手拎了一路，差點就掉在地上啦！",
          DialogueId = 80090208,
          GUID = "C87F57C0",
          NextOptions = {
            [1] = 80090209,
            [2] = 80090211
          },
          SpeakNpcId = 92301,
          Subtitle = "Turns out those rich folks weren't too bright — they just picked me up and walked away, completely clueless. It was rough on my ears, though — they were pulled as the handles, and I almost got dropped along the way!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F57C0"
        },
        [80090209] = {
          ContentTC = "噫，聽著就痛！以後我一定好好保護你的耳朵！",
          DialogueId = 80090209,
          GUID = "C87F57EA",
          NextDialogue = 80090210,
          Subtitle = "Oof, that must've hurt a lot! I'll take extra care of your ears from now on!"
        },
        [80090210] = {
          ContentTC = "……這話怎麼好像聽著怪怪的……算了，這個不是重點！",
          DialogueId = 80090210,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F5814",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          Subtitle = "...Thanks, sounds a bit weird though...",
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5814"
        },
        [80090211] = {
          ContentTC = "塔比瑟居然能從那種地方逃出來，未來的「惡魔大盜」的人非同一般！",
          DialogueId = 80090211,
          GUID = "C87F583E",
          NextDialogue = 80090212,
          Subtitle = "Managing to escape from that place proves Demon Tabethe the Red Hand was awesome even as a kid!"
        },
        [80090212] = {
          ContentTC = "嘻嘻，那當然！可惜那時候我還不太熟練，否則我才不會把耳朵變成臉對著提手呢。",
          DialogueId = 80090212,
          GUID = "C87F5868",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          Subtitle = "Hehe, you bet! Too bad I wasn't as skilled back then, or I wouldn't have turned my ears into the handles.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5868"
        },
        [80090213] = {
          ContentTC = "其實我本來是想悄悄混在那幾個被領養的孩子裡的，想著如果能被有錢人領養，我就再也不用餓肚子了吧。",
          DialogueId = 80090213,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5892",
          NextDialogue = 80090214,
          SpeakNpcId = 92301,
          Subtitle = "Actually, I was planning to sneak in with those kids getting adopted, hoping I'd never starve again with a rich family.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5892"
        },
        [80090214] = {
          ContentTC = "但是貴客渾身上下都是奇怪的消毒水味兒，嗆得我鼻子痛！而且，不知道為什麼，我總覺得……他看孩子們的眼神，有點瘮人……",
          DialogueId = 80090214,
          GUID = "C87F58BC",
          NextDialogue = 80090215,
          SpeakNpcId = 92301,
          Subtitle = "But those rich people reeked of disinfectant — it stung my nose! And the way they looked at those kids... I don't know why, but it gave me the creeps...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F58BC"
        },
        [80090215] = {
          ContentTC = "就像是……廚師大叔看魚，看鴨子的那種眼神！",
          DialogueId = 80090215,
          GUID = "C87F58E6",
          NextDialogue = 80090216,
          SpeakNpcId = 92301,
          Subtitle = "It was like... a chef sizing up fish or ducks!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F58E6"
        },
        [80090216] = {
          ContentTC = "好大人少見，壞大人我可見太多啦！與其去相信他們，還不如靠我自己呢。所以我最後沒有混進孩子的隊伍裡，一個人悄悄逃掉了。",
          DialogueId = 80090216,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5910",
          NextDialogue = 80090217,
          SpeakNpcId = 92301,
          Subtitle = "I've seen too many bad grown-ups to trust them — I might be better off on my own. So I didn't join those kids, and ended up running away by myself.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5910"
        },
        [80090217] = {
          ContentTC = "這就是塔比瑟成為惡魔大盜的第一步！",
          DialogueId = 80090217,
          GUID = "C87F593A",
          NextOptions = {
            [1] = 80090218,
            [2] = 80090220
          },
          SpeakNpcId = 92301,
          Subtitle = "And that was my first step towards becoming Demon Tabethe the Red Hand!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F593A"
        },
        [80090218] = {
          ContentTC = "我想塔比瑟並不是壞孩子，你只是……很特別。",
          DialogueId = 80090218,
          GUID = "C87F5964",
          NextDialogue = 80090219,
          Subtitle = "I think you're not a bad kid, Tabethe. You're just... very special."
        },
        [80090219] = {
          ContentTC = "我不是壞，而是很特別嗎？還沒人這麼說過我……特別的孩子，特別的孩子……嘻嘻！",
          DialogueId = 80090219,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F598E",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          Subtitle = "Not bad, just special? No one's ever put it that way before... A special kid, special... Hehe!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F598E"
        },
        [80090220] = {
          ContentTC = "「貴客」聽起來就很可疑，塔比瑟做出了冷靜的判斷。",
          DialogueId = 80090220,
          GUID = "C87F59B8",
          NextDialogue = 80090221,
          Subtitle = "Those rich visitors sounded really sketchy; you made a smart call, Tabethe."
        },
        [80090221] = {
          ContentTC = "就是就是！你也這麼覺得吧！",
          DialogueId = 80090221,
          GUID = "C87F59E2",
          NextDialogue = 80090222,
          SpeakNpcId = 92301,
          Subtitle = "Exactly, you got it!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F59E2"
        },
        [80090222] = {
          ContentTC = "不過那時候我光顧著自己逃了。要是我有現在的本事，一定悄悄跟在他們屁股後面，看看他們是不是在做壞事！",
          DialogueId = 80090222,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5A0C",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          Subtitle = "Back then, I was just focused on getting away. If I were as good at my disguise tricks then, I would've secretly followed them to see what they were really up to!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A0C"
        },
        [80090223] = {
          ContentTC = "能安全逃出來，塔比瑟已經做得很好了，恭喜你獲得了自由。",
          DialogueId = 80090223,
          GUID = "C87F5A36",
          NextDialogue = 80090224,
          SpeakNpcId = 790008,
          Subtitle = "Getting out safely on your own was already something. Congratulations on earning your freedom, Tabethe.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A36"
        },
        [80090224] = {
          ContentTC = "是呀，恭喜我自己！好不容易又呼吸到新鮮空氣，第一次發現夜空並不一直都是黑黢黢的，那些透過髒玻璃看起來沒精打采的星星，原來也可以這麼明亮。",
          DialogueId = 80090224,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F5A60",
          NextDialogue = 80090225,
          SpeakNpcId = 92301,
          Subtitle = "Yeah, I did great! Breathing fresh air again was so awesome. For the first time, I realised the night sky wasn't always so dark, and the dim stars I'd seen through dirty glass were actually bright and beautiful.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A60"
        },
        [80090225] = {
          ContentTC = "我躺在草地上，伴著星星睡了一大覺，轉天醒來，是個大晴天！之後我就一直住在那個海邊小鎮，再也沒有「壞大人」打我了！",
          DialogueId = 80090225,
          GUID = "C87F5A8A",
          NextDialogue = 80090226,
          SpeakNpcId = 92301,
          Subtitle = "I slept under the stars that night, right on the grass — and woke up to a beautiful sunny day! Since that day, I've been living in that little seaside town, free from those bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A8A"
        },
        [80090226] = {
          ContentTC = "我還在那裡遇到了一個人……",
          DialogueId = 80090226,
          GUID = "C87F5AB4",
          NextDialogue = 80090227,
          SpeakNpcId = 92301,
          Subtitle = "And I met someone there...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5AB4"
        },
        [80090227] = {
          ContentTC = "塔比瑟終於碰到好人了嗎？",
          DialogueId = 80090227,
          GUID = "C87F5ADE",
          NextDialogue = 80090228,
          SpeakNpcId = 790008,
          Subtitle = "Did you finally meet someone kind?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5ADE"
        },
        [80090228] = {
          ContentTC = "大好人！但我今天有點累了……「惡魔大盜」也會累的！",
          DialogueId = 80090228,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F5B08",
          NextDialogue = 80090229,
          SpeakNpcId = 92301,
          Subtitle = "Yep, a really, really kind person! But I'm a bit tired now... even Demon Tabethe the Red Hand needs her rest!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5B08"
        },
        [80090229] = {
          ContentTC = "等你下次準備好新飲料了，我再講給你聽！",
          DialogueId = 80090229,
          GUID = "C87F5B32",
          SpeakNpcId = 92301,
          Subtitle = "Next time you whip up a new drink, I'll tell you all about it!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5B32"
        },
        [80090301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "這次的飲料也很美味！嘻嘻嘻，你可真瞭解我的口味！",
          DialogueId = 80090301,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F6702",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090302,
          SpeakNpcId = 92301,
          Subtitle = "Yum-yum! This drink's so good — just like all the other drinks you've made! Hehe, you know exactly what I like.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6702"
        },
        [80090302] = {
          ContentTC = "本大盜昨天晚上是躺著草地看著夜空睡著的，天空從湛藍色逐漸變深，星星一顆顆掛在上面，和撒著糖霜的藍莓奶蓋一模一樣！",
          DialogueId = 80090302,
          GUID = "C87F672C",
          NextDialogue = 80090303,
          SpeakNpcId = 92301,
          Subtitle = "I fell asleep on the grass under the stars last night. The sky turned from bright blue to dark navy, with stars twinkling like frosting on a blueberry smoothie!",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F672C"
        },
        [80090303] = {
          ContentTC = "除了逃出孤兒院的那晚，我其實很少在草地上睡得這麼安穩。",
          DialogueId = 80090303,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6756",
          NextDialogue = 80090304,
          SpeakNpcId = 92301,
          Subtitle = "Except for the night I escaped the orphanage, I almost never had such a sound night's sleep on the grass.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6756"
        },
        [80090304] = {
          ContentTC = "……因為，剛到小鎮的時候，我做了很多不好的事……",
          DialogueId = 80090304,
          GUID = "C87F6780",
          NextDialogue = 80090305,
          SpeakNpcId = 92301,
          Subtitle = "...Because when I first got to the town, I did a lot of bad stuff...",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6780"
        },
        [80090305] = {
          ContentTC = "所以大人們不喜歡我，叫我「惡魔」……",
          DialogueId = 80090305,
          GUID = "C87F67AA",
          NextOptions = {
            [1] = 80090306,
            [2] = 80090308
          },
          SpeakNpcId = 92301,
          Subtitle = "The grown-ups there hated me for that. They called me a \"demon\"...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F67AA"
        },
        [80090306] = {
          ContentTC = "是不是惡作劇沒掌握好分寸？",
          DialogueId = 80090306,
          GUID = "C87F67D4",
          NextDialogue = 80090307,
          Subtitle = "Did you maybe go too far with your pranks?"
        },
        [80090307] = {
          ContentTC = "是他們太笨了！唔……好吧，你說的對。",
          DialogueId = 80090307,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F67FE",
          NextDialogue = 80090310,
          SpeakNpcId = 92301,
          Subtitle = "They could've handled it if they were smarter! Well... you're right, it was my fault.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F67FE"
        },
        [80090308] = {
          ContentTC = "是不是偷吃了小鎮上所有的海魚？",
          DialogueId = 80090308,
          GUID = "C87F6828",
          NextDialogue = 80090309,
          Subtitle = "Did you polish off all the fish in town?"
        },
        [80090309] = {
          ContentTC = "我哪有那麼能吃！唔，不過你也說對了一部分……",
          DialogueId = 80090309,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F6852",
          NextDialogue = 80090310,
          SpeakNpcId = 92301,
          Subtitle = "I'm not that big of an eater! Well, you got part of it right though...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6852"
        },
        [80090310] = {
          ContentTC = "我一直靠偷吃小攤上的食物過活。小販們氣得想打我，我就學他們氣急敗壞的樣子，還對他們做鬼臉，也沒覺得有什麼不對。",
          DialogueId = 80090310,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F687C",
          NextDialogue = 80090311,
          SpeakNpcId = 92301,
          Subtitle = "I had been living off stealing food from the street stalls. The vendors were so mad they tried to beat me, but I just mimicked their angry faces to piss them off. I didn't think what I did was wrong back then.",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F687C"
        },
        [80090311] = {
          ContentTC = "「分我一點你們又餓不死，小氣鬼！」",
          DialogueId = 80090311,
          GUID = "C87F68A6",
          NextDialogue = 80090312,
          SpeakNpcId = 92301,
          Subtitle = "\"I just took a little, it's not like you'd starve! Tightwad!\"",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68A6"
        },
        [80090312] = {
          ContentTC = "直到遇見了她……",
          DialogueId = 80090312,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F68D0",
          NextDialogue = 80090313,
          SpeakNpcId = 92301,
          Subtitle = "Until I met her...",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68D0"
        },
        [80090313] = {
          ContentTC = "她是魚攤攤主的女兒，看見我偷她家東西，不僅不打我，分海魚給我吃，還問我家人在哪，如果走丟了可以在她家先住一晚，我第一次遇到這麼好的人。",
          DialogueId = 80090313,
          GUID = "C87F68FA",
          NextDialogue = 80090314,
          SpeakNpcId = 92301,
          Subtitle = "She was the fishmonger's daughter. She caught me stealing from her dad's stall but didn't tell on me; instead, she gave me fish to fill my belly, asked if I was separated from my family, and even offered me a place to stay for the night. She was the first truly kind person I'd ever met.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68FA"
        },
        [80090314] = {
          ContentTC = "後來發生了許多事……她沒有家了，只能去孤兒院，那可不行！我受過的罪，才不會讓她也受一遍！我要帶著她一起生活！",
          DialogueId = 80090314,
          GUID = "C87F6924",
          NextDialogue = 80090315,
          SpeakNpcId = 92301,
          Subtitle = "A lot happened after that... She ended up without a home and had to go to the orphanage — like I'd let her go through what I had! I decided I'd be her family!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6924"
        },
        [80090315] = {
          ContentTC = "我們一起在大太陽下傻笑，在海邊撩起水花濺到對方身上，在泥濘的小路上跑來跑去，我會變成各種小動物逗她開心。",
          DialogueId = 80090315,
          GUID = "C87F694E",
          NextDialogue = 80090316,
          SpeakNpcId = 92301,
          Subtitle = "We'd giggle under the hot sun, splash each other by the sea, and race down muddy paths together. I'd turn into little animals just to make her laugh.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F694E"
        },
        [80090316] = {
          ContentTC = "她還叫我「塔比瑟姐姐」！雖然和我一起饑一頓飽一頓地過日子，她卻一直說自己很幸福。",
          DialogueId = 80090316,
          GUID = "C87F6978",
          NextDialogue = 80090317,
          SpeakNpcId = 92301,
          Subtitle = "She was like a little sister to me — she'd call me Big Sis Tabethe. Even though we didn't always have enough food, she always said she was happy.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6978"
        }
      }
    end
  },
  {
    MinKey = 80090317,
