    Loader = function()
      return {
        [80090317] = {
          ContentTC = "也是因為她，我才決定不再拿好大人的東西了，我要做個「惡魔大盜」，專門去懲罰那些壞大人！",
          DialogueId = 80090317,
          GUID = "C87F69A2",
          NextOptions = {
