          },
          GUID = "C87F6D14",
          NextDialogue = 80090339,
          SpeakNpcId = 92301,
          Subtitle = "Ever since then, I'd only take stuff from bad thieves and mean grown-ups. It felt great, and it wouldn't hurt good people.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6D14"
        },
        [80090339] = {
