          NextDialogue = 80140406,
          SpeakNpcId = 790026,
          Subtitle = "Dennis! Slow down! Wait for me!",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8332"
        },
        [80140406] = {
          Camera = "-57.349121,46.69873,86.0,0.0,0.0,30.20026,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "呃……天太冷了，我想趕快回家睡覺。",
          DialogueId = 80140406,
          FacialId = {
            [1] = "790027:CM_Sad01"
          },
          GUID = "C89F835C",
          NextDialogue = 80140407,
          SpeakNpcId = 790027,
          Subtitle = "Ugh... it's freezing out here. I just want to get home and sleep.",
          TalkActionId = {
            [1] = "790027:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F835C"
        },
        [80140407] = {
          Camera = "226.189453,553.110352,113.588379,0.000044,-4.199979,-87.397324,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "不是吧，這才幾點？別那麼急嘛，陪我對一會兒戲！今天老師教的那段我還背得不怎麼熟練。",
          DialogueId = 80140407,
          FacialId = {
            [1] = "790027:CM_Smile01"
          },
          GUID = "C89F8386",
          NextDialogue = 80140408,
          SpeakNpcId = 790026,
          Subtitle = "Oh, come on, it's not even that late! Practise with me for a bit. I still haven't memorised the lines Ms Violetta taught us today.",
          TalkActionId = {
            [1] = "790027:Talk03_End",
            [2] = "790026:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8386"
        },
        [80140408] = {
          Camera = "602.087891,-88.831787,85.242676,0.000014,-0.400024,133.199921,35.000008,525.224243,false,Manual,2.8",
          ContentTC = "又來……？啊——好好好，陪你練就是了，別動手啊！",
          DialogueId = 80140408,
          FinalCamera = "510.33252,8.879395,84.308105,0.000014,-0.400024,133.199921,35.000008,2024.230103,false,Manual,2.8",
          GUID = "C89F83B0",
          NextDialogue = 80140409,
          Scripts = "MoveTo{ActorId{790026},MoveSpeed{60},TargetPoint{\"P80140426\"}}",
          SpeakNpcId = 790027,
          Subtitle = "Ow! Not again... Alright, alright! I'll do it. No need to start throwing punches, just saying...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F83B0"
        },
        [80140409] = {
          ContentTC = "（他們兩個真是一點也沒變。）",
          DialogueId = 80140409,
          GUID = "C89F83DA",
          NextDialogue = 80140410,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(Those two... they haven't changed a bit.)",
          TalkActionId = {
            [1] = "790025:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F83DA"
        },
        [80140410] = {
          Camera = "136.138672,760.375244,255.158691,0.000026,-19.999907,-75.596756,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "說起來，下個月的演出劇目定了嗎？",
          DialogueId = 80140410,
          FinalCamera = "-128.058105,642.81958,243.39624,0.000037,-18.99983,-43.396786,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F8404",
          NextDialogue = 80140411,
          SpeakNpcId = 790026,
          Subtitle = "By the way, has the play for next month been decided yet?",
          TalkActionId = {
            [1] = "790026:Think_Start"
          },
          ToFinalCameraBlendTime = 35,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8404"
        },
        [80140411] = {
          ContentTC = "團長說是《雨日》。",
          DialogueId = 80140411,
          GUID = "C89F842E",
          NextDialogue = 80140412,
          SpeakNpcId = 790027,
          Subtitle = "The director said we'll be performing Rainy Days.",
          TalkActionId = {
            [1] = "790027:Explain01_Start",
            [2] = "790026:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F842E"
        },
        [80140412] = {
          ContentTC = "《雨日》的人氣也就一般般吧？靠它出人頭地可不容易。唉，要是能再演《雪國的孩子》就好了。那部劇在冰湖城可受歡迎了……",
          DialogueId = 80140412,
          GUID = "C89F8458",
          NextDialogue = 80140413,
          SpeakNpcId = 790026,
          Subtitle = "Rainy Days isn't exactly a crowd-pleaser, is it? It's hard to make a name for yourself with that one. *sigh* ...If only we could put on Children From the Snowfield again. That was such a hit in Icelake...",
          TalkActionId = {
            [1] = "790026:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8458"
        },
        [80140413] = {
          ContentTC = "就是啊！我也好想再演一次無名的妖精，那可是我最得意的角色，雖然唱段又多又難，但完整演下來的感覺真是太棒了。",
          DialogueId = 80140413,
          GUID = "C89F8482",
          NextDialogue = 80140414,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790027},AnimationId{"Agree"},Duration{1}},
PlayAnimation{ActorId{790027},AnimationId{"Explain02_Start"},Duration{3},_delay{1}},
PlayAnimation{ActorId{790027},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 790027,
          Subtitle = "Exactly! I'd love to play the Nameless Fairy again. That was my best role! Sure, the singing parts were tough, but performing it all the way through felt incredible.",
          TalkActionId = {
            [1] = "790026:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8482"
        },
        [80140414] = {
          Camera = "245.842773,452.263184,118.095703,0.000008,-6.0,-87.99778,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "欸——真的嗎？我覺得我們這一屆裡還是費恩演得最好啊。",
          DialogueId = 80140414,
          FacialId = {
            [1] = "790026:CM_Shock01"
          },
          GUID = "C89F84AC",
          NextDialogue = 80140415,
          SpeakNpcId = 790026,
          Subtitle = "Really? Personally, I think Fane is the best among us.",
          TalkActionId = {
            [1] = "790026:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F84AC"
        },
        [80140415] = {
          Camera = "132.975586,162.901611,104.536133,0.000011,-0.800081,44.600689,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你瞎說，終幕的那幾段明明是我唱得更好！",
          DialogueId = 80140415,
          FacialId = {
            [1] = "790027:CM_Angry01"
          },
          GUID = "C89F84D6",
          LookAt = {
            [1] = "790025:n(790025)"
          },
          NextDialogue = 80140416,
          SpeakNpcId = 790027,
          Subtitle = "No, he is not! Those final arias in the last act? I nailed them better than he did!",
          TalkActionId = {
            [1] = "790027:Angry01_Start",
            [2] = "790026:Shock_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F84D6"
        },
        [80140416] = {
          Camera = "-499.695312,1424.604492,320.095459,0.000023,-18.799973,-178.997177,35.000008,446.117035,false,Manual,1.236337",
          ContentTC = "……",
          DialogueId = 80140416,
          GUID = "C89F8500",
          NextDialogue = 80140417,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "...",
          TalkActionId = {
            [1] = "790027:Angry01_End"
          },
          TurnTo = {
            [1] = "790025:p(150)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8500"
        },
        [80140417] = {
          ContentTC = "……其實我和費恩都不是演得最好的。",
          DialogueId = 80140417,
          GUID = "C89F852A",
          NextDialogue = 80140418,
          SpeakNpcId = 790027,
          Subtitle = "...Actually, neither Fane nor I is the best.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F852A"
        },
        [80140418] = {
          ContentTC = "……",
          DialogueId = 80140418,
          GUID = "C89F8554",
          LookAt = {
            [1] = "790025:n(790026)"
          },
          NextDialogue = 80140419,
          SpeakNpcId = 790026,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8554"
        },
        [80140419] = {
          ContentTC = "嗯，是啊。要說《雪國的孩子》，沒有人能唱得比帕西法爾更好。也不知道他現在到底去哪裡了……",
          DialogueId = 80140419,
          GUID = "C89F857E",
          NextDialogue = 80140420,
          SpeakNpcId = 790026,
          Subtitle = "Yeah, you're right. When it comes to Children From the Snowfield, no one could outshine Parsifal. I just wonder... where is he now?",
          TurnTo = {
            [1] = "790025:p(-50)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F857E"
        },
        [80140420] = {
          Camera = "220.45752,2492.598633,1532.584961,0.000103,-41.999317,-110.678604,24.770275,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（我在這裡。）",
          DialogueId = 80140420,
          FinalCamera = "309.450684,2728.375977,1759.494141,0.000103,-41.999317,-110.678604,24.770275,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F85A8",
          LookAt = {
            [1] = "790025:n(790026)"
          },
          NextDialogue = 80140421,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0081_scene_alchemyacademy\"}}",
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(I'm right here.)",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F85A8"
        },
        [80140421] = {
          ContentTC = "（我在這裡啊……）",
          DialogueId = 80140421,
          GUID = "C89F85D2",
          NextDialogue = 80140422,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(Right in front of you...)",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F85D2"
        },
        [80140422] = {
          ContentTC = "（我……）",
          DialogueId = 80140422,
          GUID = "C89F85FC",
          NextDialogue = 80140423,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(I...)",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F85FC"
        },
        [80140423] = {
          Camera = "121.94873,146.241211,123.842773,0.00001,-6.600128,46.39674,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "帕西法爾……",
          DialogueId = 80140423,
          GUID = "C89F8626",
          NextDialogue = 80140424,
          SpeakNpcId = 790027,
          Subtitle = "Parsifal...",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8626"
        },
        [80140424] = {
          Camera = "149.733398,593.0,86.0,0.0,0.0,-72.599388,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哦，忘了不該在你面前提他。上次團長說起他的時候，你還在破口大罵，差點把道具都砸了。",
          DialogueId = 80140424,
          FacialId = {
            [1] = "790026:CM_Sad01"
          },
          GUID = "C89F8650",
          LookAt = {
            [1] = "790027:n(790027)"
          },
          NextDialogue = 80140425,
          SpeakNpcId = 790026,
          Subtitle = "Oh, right. I shouldn't have mentioned him in front of you. Last time the director brought him up, you got so mad you nearly smashed the props.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8650"
        },
        [80140425] = {
          Camera = "43.179199,176.508789,110.248047,0.000011,-3.59994,23.599939,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……那時我確實很生氣。如果不是他跟老師欺騙觀眾，《雪國的孩子》就不會停演，我們那麼久的排練也不會付諸東流。可是……",
          DialogueId = 80140425,
          FacialId = {
            [1] = "790026:CM_Shock01"
          },
          GUID = "C89F867A",
          LookAt = {
            [1] = "790026:n(790027)"
          },
          NextDialogue = 80140426,
          SpeakNpcId = 790027,
          Subtitle = "Yeah... I was furious back then. If not for him and Ms Violetta deceiving the audience, Children From the Snowfield wouldn't have been cancelled. All those rehearsals wouldn't have gone to waste..",
          TurnTo = {
            [1] = "790027:p(90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F867A"
        },
        [80140426] = {
          ContentTC = "可是後來很多次我問自己──他真的不該上台嗎？錯的到底是違反了「卡戎之民不能上台演出」這一規則的帕西法爾，還是這條規則本身？",
          DialogueId = 80140426,
          GUID = "C89F86A4",
          LookAt = {
            [1] = "790027:n(790026)"
          },
          NextDialogue = 80140427,
          SpeakNpcId = 790027,
          Subtitle = " But.. I've asked myself many times since then — was he really wrong for stepping on that stage? Was it his fault for breaking the rule that says \"Charons can't perform,\" or... was the rule itself at fault?",
          TurnTo = {
            [1] = "790027:n(790026)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86A4"
        },
        [80140427] = {
          ContentTC = "我們之所以站在舞台上是為了什麼——是<H>至高無上的藝術</>……",
          DialogueId = 80140427,
          GUID = "C89F86CE",
          NextDialogue = 80140428,
          SpeakNpcId = 790027,
          Subtitle = "Why do we stand on the stage? To honour the unparalleled value of art.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86CE"
        },
        [80140428] = {
          ContentTC = "可是為什麼人們不去看表演本身，而是死死盯著那個表演的人有沒有長角？如果我們大家一起站在帷幕後面，那帕西法爾與我們又有什麼區別？",
          DialogueId = 80140428,
          GUID = "C89F86F8",
          NextDialogue = 80140429,
          SpeakNpcId = 790027,
          Subtitle = "But why do people care more about whether a performer has horns than about the performance itself? If we all stood behind the curtain, how would Parsifal be any different from the rest of us?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86F8"
        },
        [80140429] = {
          Camera = "184.165039,231.606201,98.688477,0.00003,4.399932,43.401665,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哦，還是有區別的。他比我唱得更好。",
          DialogueId = 80140429,
          FacialId = {
            [1] = "790027:CM_Idle"
          },
          GUID = "C89F8722",
          NextDialogue = 80140430,
          SpeakNpcId = 790027,
          Subtitle = "Oh, there is one difference — he sings better than I do.",
          TalkActionId = {
            [1] = "790027:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8722"
        },
        [80140430] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "真是難得，竟然能從你嘴裡聽到這種話。看來我們莽撞的丹尼斯終於長大啦。",
          DialogueId = 80140430,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F874C",
          NextDialogue = 80140431,
          SpeakNpcId = 790026,
          Subtitle = "Wow, it's rare to hear you say something like that. Looks like our reckless little Dennis is finally growing up!",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F874C"
        },
        [80140431] = {
          Camera = "96.443359,130.570557,116.894043,0.000003,-3.99997,42.200706,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "喂，不要突然擺出團長的樣子教訓我啊。",
          DialogueId = 80140431,
          FacialId = {
            [1] = "790027:CM_Angry01"
          },
          GUID = "C89F8776",
          NextDialogue = 80140432,
          SpeakNpcId = 790027,
          Subtitle = "Hey, don't start acting like the director and giving me lectures, alright?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8776"
        },
        [80140432] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這是誇獎，才不是教訓！如果帕西法爾那傢伙突然跑回來，我才要狠狠教訓他，誰叫他連封信都沒留就不知道跑哪兒去了，我是真的很想他呀。",
          DialogueId = 80140432,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          GUID = "C89F87A0",
          NextDialogue = 80140433,
          SpeakNpcId = 790026,
          Subtitle = "That wasn't a lecture — it was a compliment! But if Parsifal ever comes back, I'll give him a real telling-off. Vanishing without so much as a note... What was he thinking? *sigh* I really miss him.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87A0"
        },
        [80140433] = {
          Camera = "-1153.268066,1960.390137,235.713867,0.000035,-6.800218,-58.593773,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（蘇珊娜，丹尼斯……）",
          DialogueId = 80140433,
          GUID = "C89F87CA",
          NextDialogue = 80140434,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Paxi",
          Subtitle = "(Susanna... Dennis...)",
          TalkActionId = {
            [1] = "790025:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87CA"
        },
        [80140434] = {
          Camera = "185.86377,442.624756,59.498047,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          ContentTC = "話說回來，你還記得老師說過的嗎？「雖然不是現在，但未來的某一天，我們的藝術一定會迎來一個更加純粹的時代，那時將不再有索拉和卡戎之別。」",
          DialogueId = 80140434,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          FinalCamera = "199.419434,397.746582,69.291504,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F87F4",
          NextDialogue = 80140435,
          SpeakNpcId = 790026,
          Subtitle = "Do you remember what Ms Violetta used to say? \"Someday — not now, but in the future — our art will usher in a purer era, one free of prejudice or discrimination, with no divide between Solas and Charons.\"",
          TalkActionId = {
            [1] = "790025:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87F4"
        },
        [80140435] = {
          ContentTC = "我想，雖然老師和帕西法爾一時間被人們唾罵，讓劇團蒙受恥辱……但是正因為有他們這樣的人存在，那個新時代才會到來。",
          DialogueId = 80140435,
          GUID = "C89F881E",
          NextDialogue = 80140436,
          SpeakNpcId = 790026,
          Subtitle = "I believe that even though Ms Violetta and Parsifal were scorned by so many, which brought shame upon the troupe... it's people like them who will bring about that brighter future.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F881E"
        },
        [80140436] = {
          ContentTC = "到那時他們就不再是「恥辱」，而是比大家更早醒來的「英雄」。",
          DialogueId = 80140436,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F8848",
          NextDialogue = 80140437,
          SpeakNpcId = 790026,
          Subtitle = "When that day arrives, they won't be remembered as \"disgraces.\" They'll be seen as \"heroes\" — visionaries who woke up before the rest of us.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8848"
        },
        [80140437] = {
          Camera = "-475.065918,1530.032227,242.341553,0.000032,-7.199647,-170.999466,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "…………",
          DialogueId = 80140437,
          GUID = "C89F8872",
          NextDialogue = 80140438,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Paxi",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8872"
        },
        [80140438] = {
          Camera = "52.178223,609.198242,243.78833,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "讓我們祝福他吧！也許他已經去了卡戎之民也能上台表演的地方，像是盧卡或伊瑟爾。",
          DialogueId = 80140438,
          FinalCamera = "-116.030762,898.193115,370.702637,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F889C",
          NextDialogue = 80140439,
          SpeakNpcId = 790026,
          Subtitle = "Let's wish him well, wherever he is! Maybe he's already found somewhere Charons can stand on stage — like Luca or Aethyrie.",
          TalkActionId = {
            [1] = "790026:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F889C"
        },
        [80140439] = {
          ContentTC = "說不定下次我們去這些國家巡演的時候，就會發現他已經搖身一變，成了老師那樣的大明星呢！",
          DialogueId = 80140439,
          GUID = "C89F88C6",
          LookAt = {
            [1] = "790025:n(790025)"
          },
          NextDialogue = 80140440,
          SpeakNpcId = 790026,
          Subtitle = "Who knows? Next time we tour those countries, we might find he's already become a superstar, just like Ms Violetta!",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F88C6"
        },
        [80140440] = {
          ContentTC = "嗯。希望我們還有機會和他站上同一個舞台。",
          DialogueId = 80140440,
          GUID = "C89F88F0",
          LookAt = {
            [1] = "790027:n(790027)",
            [2] = "790026:n(790026)"
          },
          NextDialogue = 80140454,
          SpeakNpcId = 790027,
          Subtitle = "Yeah. I hope we get to share the stage with him again someday.",
          TalkActionId = {
            [1] = "790026:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F88F0"
        },
        [80140441] = {
          Camera = "644.496094,-490.569336,714.540771,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
          ContentTC = "如果──如果你我以人類的模樣相識，此時此刻有說有笑地離開劇場的，會是我們四個人嗎？",
          DialogueId = 80140441,
          FinalCamera = "644.496094,-490.569336,603.562866,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F891A",
          LookAt = {
            [1] = "790029:n(790028)"
          },
          NextDialogue = 80140442,
          SpeakNpcId = 790029,
          Subtitle = "If we had met as humans... would it have been the four of us leaving the theatre together, laughing and chatting?",
          TalkActionId = {
            [1] = "790029:Explain02_Start",
            [2] = "790028:Tuosi02_Emo_Idle_Pose"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F891A"
        },
        [80140442] = {
          ContentTC = "蘇珊娜絕對不會放過你這個免費的伴奏，而以你的脾氣，一定會一口答應。最後八成就會變成大家陪著她一起在天寒地凍的街道上排練吧。",
          DialogueId = 80140442,
          GUID = "C89F8944",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_02.T_Story_Recall_110304_02'",
          NextDialogue = 80140443,
          SpeakNpcId = 790029,
          Subtitle = "Susanna wouldn't let you off the hook as her free accompanist. And knowing you, you'd agree without hesitation. Before we knew it, we'd all be out there, rehearsing on the freezing streets just to humour her.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8944"
        },
        [80140443] = {
          ContentTC = "不過，你是有家人的。你那個一本正經的姐姐一定會來催你回家。也說不定，你反而會拉著她一起加入我們——嗯，這個可能性更大一些。",
          DialogueId = 80140443,
          GUID = "C89F896E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_01.T_Story_Recall_110304_01'",
          NextDialogue = 80140444,
          SpeakNpcId = 790029,
          Subtitle = "Oh wait... you had family. Your no-nonsense big sister would probably show up to drag you home. Or maybe... maybe you'd convince her to join us instead — yes, that's more like how it would end up.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F896E"
        },
        [80140444] = {
          ContentTC = "不。不可能。事到如今，我還在幻想什麼？",
          DialogueId = 80140444,
          GUID = "C89F8998",
          IsBlack = 1,
          NextDialogue = 80140445,
          SpeakNpcId = 790029,
          Subtitle = "No. That's never going to happen. What am I thinking, now that things have come to this?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8998"
        },
        [80140445] = {
          ContentTC = "那個舞台、那些劇本、那些朋友，都是屬於帕西法爾的，早已不屬於我。",
          DialogueId = 80140445,
          GUID = "C89F89C2",
          IsBlack = 1,
          NextDialogue = 80140446,
          SpeakNpcId = 790029,
          Subtitle = "That stage, those scripts, those friends... they belong to Parsifal. I no longer have them.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F89C2"
        },
        [80140446] = {
          ContentTC = "但是——",
          DialogueId = 80140446,
          GUID = "C89F89EC",
          IsBlack = 1,
          NextDialogue = 80140447,
          SpeakNpcId = 790029,
          Subtitle = "But—",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F89EC"
        },
        [80140447] = {
          Camera = "612.479492,-311.0,51.0,-0.0,6.400003,149.998077,35.0,407.658783,false,DoNotOverride,1.2",
          ContentTC = "在這裡，還有一場非常重要的演出，只有我能完成。",
          DialogueId = 80140447,
          GUID = "C89F8A16",
          NextDialogue = 80140448,
          Scripts = "PlayAnimation{_click{false},_delay{5},ActorId{790029},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 790029,
          Subtitle = "Here, there's one final performance. One only I can deliver.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A16"
        },
        [80140448] = {
          Camera = "101.459473,-124.397461,114.37085,0.00001,19.398399,147.190094,35.000008,407.658783,false,DoNotOverride,1.2",
          ContentTC = "我找到了一些顏料和油漆，足以讓我的樣子和你相差無幾。你們的秘密基地也已經見到了。再加上你給的鏈子……",
          DialogueId = 80140448,
          FinalCamera = "33.354004,-80.496094,142.904297,0.00001,19.398399,147.190094,35.000008,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F8A40",
          NextDialogue = 80140449,
          Scripts = [[
SEQ{
PlayAnimation{_click{false},ActorId{790029},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_click{false},_delay{5},ActorId{790029},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_click{false},ActorId{790029},AnimationId{"Agree"},Duration{1},_delay{1}}
}]],
          SpeakNpcId = 790029,
          Subtitle = "I've gathered paints and oils, enough to make myself look almost identical to you. I've seen your secret hideout. And with the harmonica chain you left me...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A40"
        },
        [80140449] = {
          Camera = "-1737.0,1331.0,973.443848,-0.000001,29.000006,-64.800743,35.0,407.658783,false,DoNotOverride,1.2",
          ContentTC = "演員、服裝、道具、布景都已就位——接下來，就只需等待帷幕拉開。",
          DialogueId = 80140449,
          FinalCamera = "-1737.0,1331.0,973.443848,-0.000001,30.999987,-64.80072,35.0,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F8A6A",
          LookAt = {
            [1] = "790029:n(790029)"
          },
          NextDialogue = 80140450,
          SpeakNpcId = 790029,
          Subtitle = "The performer, the costume, the props, the set — all ready. Now, all that's left is for the curtain to rise.",
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "790029:p(-90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A6A"
        },
        [80140450] = {
          Camera = "613.405762,312.25,52.490479,0.000005,6.699862,-153.800339,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "放心吧，布魯斯。答應你的，我定然會做到。",
          DialogueId = 80140450,
          FinalCamera = "640.817383,256.542969,52.490479,0.000005,6.699862,-153.800339,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F8A94",
          Scripts = [[
SEQ{
MoveTo{_click{false},ActorId{790029},MoveSpeed{95},TargetPoint{"P80140449"}},
CameraMoveTo{_click{false},_delay{4},TargetPosition{"58.193848,40.453125,189.723633,0.0,2.899996,-130.398499,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
LookAt{_click{false},LookAtDescription{"790029:n(790028)"}}
}]],
          SpeakNpcId = 790029,
          Subtitle = "Don't worry, Blues. I'll keep my promise and see it through.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A94"
        },
        [80140451] = {
          ContentTC = "我是驕傲的演員，在此獻上最後的歌聲。",
          DialogueId = 80140451,
          Duration = 4,
          GUID = "C89F8ABE",
          Subtitle = "I am a proud performer, delivering my swan song.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8ABE"
        },
        [80140452] = {
          ContentTC = "然後，謝幕退場。",
          DialogueId = 80140452,
          Duration = 3,
          GUID = "C89F8AE8",
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0081_scene_alchemyacademy\"}}",
          Subtitle = "And in the end, I take my bow and leave the stage.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8AE8"
        },
        [80140453] = {
          Camera = "-1100.918945,1811.1875,204.0,0.0,-4.200006,-54.398975,35.000008,100000.0,false,DoNotOverride,2.8",
