          GUID = "C89F82B5",
          NextDialogue = 80140403,
          ToFinalCameraBlendTime = 7
        },
        [80140454] = {
          Camera = "-580.74707,2433.777832,1315.769531,0.000017,-44.999565,-77.270569,21.224024,100000.0,false,DoNotOverride,2.8",
