        },
        [80210114] = {
          Camera = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
          ContentTC = "蠢死啦，我只答應你演一遍的。",
          DialogueId = 80210114,
          FacialId = {
            [1] = "790066:CM_Idle"
          },
          GUID = "C8CC2FD4",
          NextDialogue = 80210115,
          SpeakNpcId = 790066,
          Subtitle = "So lame. I only agreed to do this once.",
          TalkActionId = {
            [1] = "790066:Sigh_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2FD4"
        },
        [80210115] = {
          Camera = "-154.820312,-313.032227,46.03125,0.000064,4.999999,61.640118,22.063116,681.604492,false,Manual,2.8",
          ContentTC = "你們……這是在幹什麼。",
          DialogueId = 80210115,
          FinalCamera = "-182.828125,-367.04541,41.943359,0.000061,3.999984,62.639935,22.063116,681.604492,false,Manual,2.8",
          GUID = "C8CC2FFE",
          NextDialogue = 80210116,
          SpeakNpcId = 790067,
          Subtitle = "Hey you two... what are you doing?",
          TalkActionId = {
            [1] = "790066:Sigh_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2FFE"
        },
        [80210116] = {
          Camera = "274.847656,276.966309,232.944336,0.00018,-20.000671,-141.973434,30.0,445.724579,false,Manual,4.0",
          ContentTC = "這都不知道，我們這是在模仿飄零人對話呀。",
          DialogueId = 80210116,
          FinalCamera = "262.335938,267.178223,227.157227,0.00018,-20.000671,-141.973434,30.0,248.094116,false,Manual,4.0",
          GUID = "C8CC3028",
          LookAt = {
            [1] = "790067:n(790065)"
          },
          NextDialogue = 80210117,
          SpeakNpcId = 790065,
          Subtitle = "You don't get it? We're acting out a scene from Drifter!",
          TalkActionId = {
            [1] = "790067:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "790065:n(790067)",
            [2] = "790066:n(790067)"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3028"
        },
        [80210117] = {
          ContentTC = "這場對話是之前最流行的飄零人小說里，最有名的一段台詞了，每當讀到這裡的時候，我都恨不得鑽進書裡去。",
          DialogueId = 80210117,
          GUID = "C8CC3052",
          NextDialogue = 80210118,
          SpeakNpcId = 790065,
          Subtitle = "This is the most famous dialogue from the most popular Drifter novel. Every time I read this part, I wish I could jump into the book.",
          TalkActionId = {
            [1] = "790065:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3052"
        },
        [80210118] = {
          ContentTC = "要不是每天被阿媽揪著耳朵讀書，我肯定去奔赴那山外山學得一身好本領，快意恩仇！",
          DialogueId = 80210118,
          GUID = "C8CC307C",
          LookAt = {
            [1] = "790065:n(790066)"
          },
          NextDialogue = 80210119,
          SpeakNpcId = 790065,
          Subtitle = "If Mom didn't drag me by the ear to study every day, I'd have gone to Outer Peaks already — learned real skills, fought for justice!",
          TalkActionId = {
            [1] = "790065:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC307C"
        },
        [80210119] = {
          Camera = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
          ContentTC = "你要是和我一樣早早做完功課，阿媽才懶得管你呢。",
          DialogueId = 80210119,
          GUID = "C8CC30A6",
          LookAt = {
            [1] = "790066:n(790065)"
          },
          NextDialogue = 80210120,
          SpeakNpcId = 790066,
          Subtitle = "If you finished your homework early like I do, Mom wouldn't bother you.",
          TalkActionId = {
            [1] = "790066:Confident_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC30A6"
        },
        [80210120] = {
          Camera = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
          ContentTC = "阿媽是偏心，她的那把佩劍，你拿來砍柴殺魚她都不會說什麼。而我想要拿起來舞一個劍花，她都要說我是玩物喪志呢。",
          DialogueId = 80210120,
          GUID = "C8CC30D0",
          NextDialogue = 80210121,
          SpeakNpcId = 790065,
          Subtitle = "She's biased. She lets you use her sword to chop wood and clean fish. But when I try to spin it just once, she says that I'm wasting my spirit on trifles.",
          TalkActionId = {
            [1] = "790065:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC30D0"
        },
        [80210121] = {
          Camera = "-97.171875,135.871094,124.923828,0.000072,-11.800135,-56.803616,25.0,226.88681,false,Manual,2.8",
          ContentTC = "那當然了，我這可都是幹得是正事，給阿媽幫忙的。你拿起劍來舞來舞去，不傷到自己都算是好的。",
          DialogueId = 80210121,
          GUID = "C8CC30FA",
          NextDialogue = 80210122,
          SpeakNpcId = 790066,
          Subtitle = "Of course. I'm doing real work — helping Mom. You'd hurt yourself just swinging that thing around.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC30FA"
        },
        [80210122] = {
          Camera = "112.191406,49.433105,156.642578,0.000145,-12.799466,173.017639,35.0,178.705887,false,Manual,2.8",
          ContentTC = "要我說啊，阿媽就是沒讀過飄零人小說，否則才不會由著你拿著這把劍幹雜活。",
          DialogueId = 80210122,
          FinalCamera = "80.292969,53.341797,149.338867,0.000145,-12.799466,173.017639,35.000011,149.474472,false,Manual,2.8",
          GUID = "C8CC3124",
          NextDialogue = 80210123,
          SpeakNpcId = 790065,
          Subtitle = "I'm telling you, if Mom had ever read Drifter, she wouldn't let you use this sword for chores.",
          TalkActionId = {
            [1] = "790065:Talk02_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3124"
        },
        [80210123] = {
          ContentTC = "應該給我才是，讓我練習劍譜，等我長大了就可以保護阿姐你和阿媽。",
          DialogueId = 80210123,
          GUID = "C8CC314E",
          NextDialogue = 80210124,
          SpeakNpcId = 790065,
          Subtitle = "She should've given it to me. Let me practice from the manual. Then once I'm grown, I can protect you and Mom.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC314E"
        },
        [80210124] = {
          Camera = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
          ContentTC = "你就是小說看多啦，現在有大風九章，根本不需要飄零人保護大家的。",
          DialogueId = 80210124,
          GUID = "C8CC3178",
          NextDialogue = 80210125,
          SpeakNpcId = 790066,
          Subtitle = "You've read too many novels. With the Nine Chapters of Dafeng now, no one needs a Drifter anymore.",
          TalkActionId = {
            [1] = "790066:Confident_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3178"
        },
        [80210125] = {
          Camera = "160.730469,298.234375,220.72168,0.000052,-13.400564,-69.973022,35.000011,125.0,false,Manual,2.8",
          ContentTC = "說得是啊，現在這個時日，確實已經沒多少個飄零人了。",
          DialogueId = 80210125,
          FinalCamera = "165.699219,284.596191,217.265625,0.000052,-13.400564,-69.973022,35.000011,110.763969,false,Manual,2.8",
          GUID = "C8CC31A2",
          NextDialogue = 80210126,
          SpeakNpcId = 790067,
          Subtitle = "She's right. These days... there aren't many drifters left.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC31A2"
        },
        [80210126] = {
          Camera = "393.839844,444.308105,335.135742,0.000015,-26.198637,-130.560333,35.000011,240.726898,false,Manual,2.8",
          ContentTC = "啊，不好意思，大哥哥，剛剛我只顧著和弟弟說話了，忘了你還在邊上。",
          DialogueId = 80210126,
          GUID = "C8CC31CC",
          LookAt = {
            [1] = "790065:n(790067)",
            [2] = "790066:n(790067)"
          },
          NextDialogue = 80210127,
          SpeakNpcId = 790066,
          Subtitle = "Ah, sorry, mister! I was too busy talking with my brother and forgot you were still here.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC31CC"
        },
        [80210127] = {
          Camera = "153.617188,127.562012,157.194336,0.000101,-18.800348,-103.577133,35.000011,187.821686,false,Manual,2.8",
          ContentTC = "請問你來這裡是……找阿媽嗎？她吩咐過，不見來客的。",
          DialogueId = 80210127,
          GUID = "C8CC31F6",
          LookAt = {
            [1] = "790067:n(790066)"
          },
          NextDialogue = 80210128,
          SpeakNpcId = 790066,
          Subtitle = "Did you... come for Mom? She said she isn't receiving guests.",
          TalkActionId = {
            [1] = "790066:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC31F6"
        },
        [80210128] = {
          Camera = "-2.984375,-178.594238,79.739258,0.000157,10.398853,55.621544,40.0,463.63916,false,Manual,2.8",
          ContentTC = "嗯，看得出來，她之前佩劍不離身，現在這把佩劍卻在你們手上，那我自然明白她是什麼意思。",
          DialogueId = 80210128,
          FinalCamera = "13.074219,-155.074219,84.959961,0.000157,10.398853,55.621544,40.0,463.63916,false,Manual,2.8",
          GUID = "C8CC3220",
          NextDialogue = 80210129,
          SpeakNpcId = 790067,
          Subtitle = "Well, I can see that. She used to never let this blade leave her side. Now that you two have it... I understand what she means.",
          TalkActionId = {
            [1] = "790067:AgreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3220"
        },
        [80210129] = {
          Camera = "274.847656,276.966309,232.944336,0.00018,-20.000671,-141.973434,30.0,445.724579,false,Manual,4.0",
          ContentTC = "你認識阿媽？能和我講講她年輕時候的事情嗎？我總懷疑她是一位大俠，否則怎麼會有這麼一把好劍。",
          DialogueId = 80210129,
          FinalCamera = "262.335938,267.178223,227.157227,0.00018,-20.000671,-141.973434,30.0,248.094116,false,Manual,4.0",
          GUID = "C8CC324A",
          LookAt = {
            [1] = "790067:n(790065)"
          },
          NextDialogue = 80210130,
          SpeakNpcId = 790065,
          Subtitle = "You know Mom? Can you tell us about her young age? I've always thought she must've been a great hero — why else would she have a sword like this?",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC324A"
        },
        [80210130] = {
          ContentTC = "每次我纏著她，她卻又什麼都不肯說。",
          DialogueId = 80210130,
          GUID = "C8CC3274",
          NextDialogue = 80210131,
          SpeakNpcId = 790065,
          Subtitle = "Whenever I ask, she just stays quiet.",
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3274"
        },
        [80210131] = {
          Camera = "105.101562,49.699219,200.319336,0.000131,-3.00042,53.422153,35.000011,175.117645,false,Manual,2.8",
          ContentTC = "那，我也是受人所託來找她，但既然她無意相見，那麼我也不便多說。",
          DialogueId = 80210131,
          FinalCamera = "112.863281,60.17041,199.636719,0.000131,-3.00042,53.422176,35.000011,175.117645,false,Manual,2.8",
          GUID = "C8CC329E",
          LookAt = {
            [1] = "790067:n(790065)"
          },
          NextDialogue = 80210132,
          SpeakNpcId = 790067,
          Subtitle = "I was asked to come to her. But since she doesn't wish to meet... it's not my place to say more.",
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC329E"
        },
        [80210132] = {
          Camera = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
          ContentTC = "什麼嘛，沒勁。我看你這副行頭，又背著劍，還以為能看到阿媽出手呢。",
          DialogueId = 80210132,
          GUID = "C8CC32C8",
          NextDialogue = 80210133,
          SpeakNpcId = 790065,
          Subtitle = "Aww, boring. With that outfit and that sword on your back, I thought we might get to see her draw it again.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC32C8"
        },
        [80210133] = {
          Camera = "393.839844,444.308105,335.135742,0.000015,-26.198637,-130.560333,35.000011,240.726898,false,Manual,2.8",
          ContentTC = "哈哈，假以時日，會見到的。那麼，在下告辭。",
          DialogueId = 80210133,
          FacialId = {
            [1] = "790067:Smile02"
          },
          FinalCamera = "359.804688,403.016113,308.810547,0.000015,-26.198637,-130.560333,35.000011,290.796356,false,Manual,2.8",
          GUID = "C8CC32F2",
          LookAt = {
            [1] = "790067:n(790067)"
          },
          NextDialogue = 80210134,
          SpeakNpcId = 790067,
          Subtitle = "Haha, in time, perhaps you will. Well then... I take my leave.",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "790067:p(180)"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC32F2"
        },
        [80210134] = {
          Camera = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
          ContentTC = "真的假的。喂，阿姐，聽見了沒，快別用阿媽的劍殺雞了，以後還會用的，鏽了怎麼辦。",
          DialogueId = 80210134,
          FacialId = {
            [1] = "790065:CM_Happy01"
          },
          GUID = "C8CC331C",
          LookAt = {
            [1] = "790065:n(790066)"
          },
          NextDialogue = 80210135,
          SpeakNpcId = 790065,
          Subtitle = "Seriously?! Hey, sis — you hear that? Stop using Mom's sword on chickens! She might need it again someday. What if it rusts?",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC331C"
        },
        [80210135] = {
          Camera = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
          ContentTC = "一驚一乍的，以後的事，以後再說。",
          DialogueId = 80210135,
          GUID = "C8CC3346",
          LookAt = {
            [1] = "790066:n(790065)"
          },
          NextDialogue = 80210136,
          SpeakNpcId = 790066,
          Subtitle = "Don't be so dramatic. We'll worry about that later.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3346"
        },
        [80210136] = {
          Camera = "71.171875,-18.830078,134.579102,0.000001,10.798099,59.223282,35.000011,265.938843,false,Manual,2.8",
          ContentTC = "倒是這位大哥哥，不妨坐下來歇息一會兒再走？",
          DialogueId = 80210136,
          FinalCamera = "71.171875,-18.830078,134.579102,0.0,10.798091,56.999958,35.000011,265.938843,false,Manual,2.8",
          GUID = "C8CC3370",
          LookAt = {
            [1] = "790065:n(790067)",
            [2] = "790066:n(790067)"
          },
          NextDialogue = 80210137,
          SpeakNpcId = 790066,
          Subtitle = "How about you, mister? Won't you sit and rest a while before you go?",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC3370"
        },
        [80210137] = {
          Camera = "-152.511719,-805.267578,105.516602,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
          ContentTC = "這可不行，我身後可是一直有一群小狗在追著，停留不得，就不打擾你們了。",
          DialogueId = 80210137,
          FacialId = {
            [1] = "790067:None"
          },
          FinalCamera = "-218.78125,-1024.449219,87.90332,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
          GUID = "C8CC339A",
          Scripts = "MoveTo{ActorId{790067},TargetPoint{\"BP_NewTargetPoint_150301\"},MoveSpeed{150}}",
          SpeakNpcId = 790067,
          Subtitle = "Can't do that. There's always a pack of little hounds on my tail — can't stay in one place too long. I won't trouble you further.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC339A"
        },
        [80210201] = {
          Camera = "-3911.427734,-2583.495605,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
          ContentTC = "俠客愛憎分明，情天恨海，是非多多。更有好事者把這些糾纏寫成書冊，人人愛看。",
          DialogueId = 80210201,
          FinalCamera = "-3781.285156,-2732.086426,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
          GUID = "C8CC3E1A",
          NextDialogue = 80210202,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "Heroes live by love and vengeance, storms of passion and conflict. And where there is drama, there are those who eagerly write it all down. Their tales are devoured by all.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E1A"
        },
        [80210202] = {
          ContentTC = "人人皆嚮往能策馬紅塵，但身在其中者，往往是另外一番愁滋味。",
          DialogueId = 80210202,
          GUID = "C8CC3E44",
          NextDialogue = 80210203,
          Subtitle = "Everyone dreams of galloping through the world of dust — yet those who truly ride it know only the weight of the wind and the loneliness of the road.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E44"
        },
        [80210203] = {
          Camera = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          ContentTC = "你回來了，鳴鸞。",
          DialogueId = 80210203,
          FacialId = {
            [1] = "790067:Smile01"
          },
          FinalCamera = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          GUID = "C8CC3E6E",
          LookAt = {
            [1] = "790067:n(790068)",
            [2] = "790068:n(790067)"
          },
          NextDialogue = 80210204,
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          SpeakNpcId = 790067,
          Subtitle = "You're back, Mingluan.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E6E"
        },
        [80210204] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          ContentTC = "我回來了，刻舟。",
          DialogueId = 80210204,
          FacialId = {
            [1] = "790068:CM_Smile01"
          },
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC3E98",
          NextDialogue = 80210205,
          SpeakNpcId = 790068,
          Subtitle = "I'm back, Kezhou.",
          TalkActionId = {
            [1] = "790068:Agree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3E98"
        },
        [80210205] = {
          Camera = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
          ContentTC = "那麼結果呢？",
          DialogueId = 80210205,
          FinalCamera = "-361.898438,-71.477051,182.797852,0.0001,-12.798893,15.006591,20.0,592.475586,false,Manual,4.0",
          GUID = "C8CC3EC2",
          NextDialogue = 80210206,
          SpeakNpcId = 790067,
          Subtitle = "And the results?",
          TalkActionId = {
            [1] = "790067:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3EC2"
        },
        [80210206] = {
          ContentTC = "自然是有一些的。",
          DialogueId = 80210206,
          GUID = "C8CC3EEC",
          NextDialogue = 80210207,
          SpeakNpcId = 790068,
          Subtitle = "There were some, naturally.",
          TalkActionId = {
            [1] = "790068:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3EEC"
        },
        [80210207] = {
          Camera = "109.556641,-109.840332,171.128906,0.000122,-10.598042,137.795868,20.0,275.546844,false,Manual,4.0",
          ContentTC = "我踏足了五個國家，悟出了五門新功夫。",
          DialogueId = 80210207,
          FinalCamera = "32.886719,-42.50415,154.229492,0.000131,-5.197801,142.396057,20.0,155.23967,false,Manual,4.0",
          GUID = "C8CC3F16",
          NextDialogue = 80210208,
          SpeakNpcId = 790068,
          Subtitle = "I set foot in five kingdoms... comprehended five new types of kung fu.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F16"
        },
        [80210208] = {
          Camera = "1812.060547,3093.102783,-750.477539,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
          ContentTC = "我先是西出了華胥，踏入了赫墨的瀚海。",
          DialogueId = 80210208,
          FinalCamera = "1251.640625,3319.118652,-659.09082,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
          GUID = "C8CC3F40",
          NextDialogue = 80210209,
          SpeakNpcId = 790068,
          Subtitle = "First, I went west out of Huaxu, into the great desert of Khemet.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F40"
        },
        [80210209] = {
          Camera = "-1200.404297,23490.853516,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
          ContentTC = "之前我聽人說赫墨的瀚海是萬里黃沙，酷熱無比。於是便拿定主意，夜半披星趕路。",
          DialogueId = 80210209,
          FinalCamera = "-1074.800781,23130.9375,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
          GUID = "C8CC3F6A",
          NextDialogue = 80210210,
          SpeakNpcId = 790068,
          Subtitle = "I'd heard it was a burning sea of sand, endless and scorching. So I decided to travel by night, under the stars.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F6A"
        },
        [80210210] = {
          ContentTC = "但我沒料到夜半的沙漠卻又奇寒無比，如果不做些什麼必將凍斃其中，成為一具無名的白骨。",
          DialogueId = 80210210,
          GUID = "C8CC3F94",
          NextDialogue = 80210211,
          SpeakNpcId = 790068,
          Subtitle = "But I hadn't expected the desert cold to bite so deep. Had I done nothing, I would've frozen — just another nameless skeleton under the dunes.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3F94"
        },
        [80210211] = {
          Camera = "-23017.669922,21547.728516,8057.0,0.000038,14.399909,168.238129,22.934771,13322.412109,false,Manual,4.0",
          ContentTC = "正當我煩惱該如何自救之時，我看到遠處的地平上有幾顆綠星忽閃忽閃，卻又漸漸變大。",
          DialogueId = 80210211,
          FinalCamera = "-23384.009766,19835.208984,8057.0,0.000038,14.399909,166.236816,22.934771,13322.412109,false,Manual,4.0",
          GUID = "C8CC3FBE",
          NextDialogue = 80210212,
          SpeakNpcId = 790068,
          Subtitle = "Just as I wondered how to survive… I saw flickers of green on the horizon. Small at first, then growing.",
          TalkActionId = {
            [1] = "790067:Talk02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3FBE"
        },
        [80210212] = {
          ContentTC = "那些綠星都是成對的，並且遠遠地也能透著股肅殺之氣，像是典籍上提到的貪狼星。我突然醒悟過來，這並非是什麼星星，而是狼的眼睛。",
          DialogueId = 80210212,
          GUID = "C8CC3FE8",
          NextDialogue = 80210213,
          SpeakNpcId = 790068,
          Subtitle = "Those green lights came in pairs, cold and fierce — like the Greedywolf Star in the old texts. Then I realized… they weren't stars. They were eyes.",
          TalkActionId = {
            [1] = "790068:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC3FE8"
        },
        [80210213] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          ContentTC = "可憐。",
          DialogueId = 80210213,
          GUID = "C8CC4012",
          NextDialogue = 80210214,
          SpeakNpcId = 790067,
          Subtitle = "How pitiful.",
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4012"
        },
        [80210214] = {
          Camera = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
          ContentTC = "誰可憐。",
          DialogueId = 80210214,
          FinalCamera = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
          GUID = "C8CC403C",
          NextDialogue = 80210215,
          SpeakNpcId = 790068,
          Subtitle = "Who's pitiful?",
          TalkActionId = {
            [1] = "790068:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC403C"
        },
        [80210215] = {
          ContentTC = "自然不是你可憐。",
          DialogueId = 80210215,
          GUID = "C8CC4066",
          NextDialogue = 80210216,
          SpeakNpcId = 790067,
          Subtitle = "Certainly not you.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4066"
        },
        [80210216] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          ContentTC = "那你錯怪我了，那些小狗崽子安然無恙，我只是拍暈了幾隻，把它們拖到沙丘的背風處，當做墊背，靠著它們的體溫囫圇了一個晚上。",
          DialogueId = 80210216,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4090",
          NextDialogue = 80210217,
          SpeakNpcId = 790068,
          Subtitle = "Then you misjudge me. Those pups are fine. I just knocked a few out, dragged them into the lee of a dune, and used them as blankets. Their warmth got me through the night.",
          TalkActionId = {
            [1] = "790068:Disagree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4090"
        },
        [80210217] = {
          ContentTC = "了結它們倒也不難，但真要如此的話，我活不過第一個晚上。",
          DialogueId = 80210217,
          GUID = "C8CC40BA",
          NextDialogue = 80210218,
          SpeakNpcId = 790068,
          Subtitle = "Killing them would've been easy. But had I done that… I wouldn't have lasted the first night.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC40BA"
        },
        [80210218] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000083,-19.79907,13.007248,30.000008,125.0,false,Manual,2.8",
          ContentTC = "於你來說，幾隻野狼自然不是對手，但是我記得你的掌風素來剛猛凌厲，號稱降龍，沒想到居然能控制到恰好擊暈活物而留其性命的地步。",
          DialogueId = 80210218,
          FinalCamera = "-29.367188,-76.549561,193.577148,0.000083,-19.79907,13.007559,30.000008,125.0,false,Manual,2.8",
          GUID = "C8CC40E4",
          NextDialogue = 80210219,
          SpeakNpcId = 790067,
          Subtitle = "Wolves are nothing to you, I know. But your palm strikes have always been fierce — they call you \"Dragon-Subduer\". I'm surprised you held back enough to spare them.",
          TalkActionId = {
            [1] = "790067:Talk01_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC40E4"
        },
        [80210219] = {
          ContentTC = "這應該便是你悟出的第一門功夫吧。",
          DialogueId = 80210219,
          GUID = "C8CC410E",
          NextDialogue = 80210220,
          SpeakNpcId = 790067,
          Subtitle = "That must be the first kung fu you comprehended.",
          TalkActionId = {
            [1] = "790067:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC410E"
        },
        [80210220] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          ContentTC = "不愧是刻舟刻大俠，立刻意識到關節所在。在那過後每晚我都是如此過夜，擊暈野狼取暖。從而悟出了一套新的掌法，我稱之為狼眠掌。",
          DialogueId = 80210220,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4138",
          NextDialogue = 80210221,
          SpeakNpcId = 790068,
          Subtitle = "As sharp as ever, Kezhou. You see right to the heart of it. Every night after, I did the same, knocked out wolves for warmth. And from that I grasped a new palm technique. I call it the Wolf-Slumber Palm.",
          TalkActionId = {
            [1] = "790068:Agree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4138"
        },
        [80210221] = {
          Camera = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          ContentTC = "好，好個狼眠掌，當浮一大白。",
          DialogueId = 80210221,
          FacialId = {
            [1] = "790067:Smile02"
          },
          FinalCamera = "-156.203125,50.284424,160.674805,0.000084,-5.398062,-15.405737,33.0,343.677704,false,Manual,3.0",
          GUID = "C8CC4162",
          NextDialogue = 80210222,
          SpeakNpcId = 790067,
          Subtitle = "Impressive, the Wolf-Slumber Palm. That calls for a drink.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4162"
        },
        [80210222] = {
          ContentTC = "那麼第二門功夫，應當就是在海伯利亞帝國了。讓我猜猜你悟出了什麼……有類迅捷劍術的快劍？還是如同冰湖城堅冰一樣厚重的長拳？",
          DialogueId = 80210222,
          GUID = "C8CC418C",
          NextDialogue = 80210223,
          SpeakNpcId = 790067,
          Subtitle = "The second one must've been in the Hyperborean Empire. Let me guess... something swift, like a rapier? Or a heavy fist, solid as the city of Icelake?",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC418C"
        },
        [80210223] = {
          Camera = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          ContentTC = "想不到你人一直在華胥，卻還知道海伯利亞還有個冰湖城。",
          DialogueId = 80210223,
          FinalCamera = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          GUID = "C8CC41B6",
          NextDialogue = 80210224,
          SpeakNpcId = 790068,
          Subtitle = "I'm surprised you've heard of Icelake, stuck here in Huaxu as you are.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC41B6"
        },
        [80210224] = {
          ContentTC = "最近交了個朋友，在冰湖城居住，所以多少知道一些。",
          DialogueId = 80210224,
          FacialId = {
            [1] = "790067:Smile01"
          },
          GUID = "C8CC41E0",
          NextDialogue = 80210225,
          SpeakNpcId = 790067,
          Subtitle = "Made a friend lately who lives there. Picked up a thing or two.",
          TalkActionId = {
            [1] = "790067:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC41E0"
        },
        [80210225] = {
          ContentTC = "原來如此，不過你猜錯了，我著急趕路，直接去了盧卡。",
          DialogueId = 80210225,
          GUID = "C8CC420A",
          NextDialogue = 80210226,
          SpeakNpcId = 790068,
          Subtitle = "I see, but wrong guess. I was in a hurry. Went straight to Luca.",
          TalkActionId = {
            [1] = "790067:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC420A"
        },
        [80210226] = {
          ContentTC = "在前往盧卡的路上，我遭遇了傳說中的海中精怪，被稱作塞壬的異獸。它們貌似嬋娟，但是卻能以歌聲攝人心魄。",
          DialogueId = 80210226,
          GUID = "C8CC4234",
          NextDialogue = 80210227,
          SpeakNpcId = 790068,
          Subtitle = "On the way, I met a legendary creature of the sea. A beast they call a Siren. Beautiful as the moon... but its song steals your mind.",
          TalkActionId = {
            [1] = "790068:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4234"
        },
        [80210227] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          ContentTC = "那豈不是和百年前的前輩莫抱琴一般，能以傳音入密的功夫亂人心神？",
          DialogueId = 80210227,
          GUID = "C8CC425E",
          NextDialogue = 80210228,
          SpeakNpcId = 790067,
          Subtitle = "So it's like Master Mo Baoqin, a century ago? Using secret tone arts to shatter one's focus?",
          TalkActionId = {
            [1] = "790068:Talk03_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC425E"
        },
        [80210228] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          ContentTC = "確實如出一轍。只是我當時沒有想到這些，只顧著跳入水中，閉息凝神，又抓住了路過的巨鯨，才堪堪逃得性命。",
          DialogueId = 80210228,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4288",
          NextDialogue = 80210229,
          SpeakNpcId = 790068,
          Subtitle = "Just like that. But in the moment, I didn't think — just dove deep, held my breath, and grabbed onto a passing whale. Barely escaped with my life.",
          TalkActionId = {
            [1] = "790068:Agree"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4288"
        },
        [80210229] = {
          ContentTC = "但也因此，我的閉氣功夫見長不少，幾乎不再懼怕毒霧之類的雕蟲小技。而我將這套法門喚作長鯨心法。",
          DialogueId = 80210229,
          GUID = "C8CC42B2",
          NextDialogue = 80210230,
          SpeakNpcId = 790068,
          Subtitle = "But because of that, my breath control improved. I hardly fear poison or petty tricks like that anymore. I call this method the Whaleheart Art.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC42B2"
        },
        [80210230] = {
          ContentTC = "然後呢？",
          DialogueId = 80210230,
          GUID = "C8CC42DC",
          NextDialogue = 80210231,
          SpeakNpcId = 790067,
          Subtitle = "And then?",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC42DC"
        },
        [80210231] = {
          ContentTC = "我在盧卡也沒有停留太久，於是去了傳頌會的雅什尼亞，在那裡我……",
          DialogueId = 80210231,
          GUID = "C8CC4306",
          NextDialogue = 80210232,
          SpeakNpcId = 790068,
          Subtitle = "And I didn't stay long either. Then I went to Yashnia, home of the Elysian Church... there I—",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4306"
        },
        [80210232] = {
          Camera = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          ContentTC = "稍等，我打斷一下。",
          DialogueId = 80210232,
          FacialId = {
            [1] = "790067:None"
          },
          GUID = "C8CC4330",
          NextDialogue = 80210233,
          SpeakNpcId = 790067,
          Subtitle = "Wait. Let me interrupt.",
          TalkActionId = {
            [1] = "790068:Confident_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4330"
        },
        [80210233] = {
          ContentTC = "你可以打斷，但需要自罰一杯。",
          DialogueId = 80210233,
          GUID = "C8CC435A",
          NextDialogue = 80210234,
          SpeakNpcId = 790068,
          Subtitle = "Of course, but you owe me a drink.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC435A"
        },
        [80210234] = {
          ContentTC = "罰就罰，沒問題，我只是想問你，她呢？你最終找到她了嗎？",
          DialogueId = 80210234,
          GUID = "C8CC4384",
          NextDialogue = 80210235,
          SpeakNpcId = 790067,
          Subtitle = "Fine. But just tell me... what about her? Did you find her in the end?",
          TalkActionId = {
            [1] = "790067:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4384"
        },
        [80210235] = {
          Camera = "-54.832031,-48.86377,169.512695,0.000115,-10.397644,109.791862,20.0,116.948799,false,Manual,4.0",
          ContentTC = "……",
          DialogueId = 80210235,
          FacialId = {
            [1] = "790068:CM_Idle"
          },
          GUID = "C8CC43AE",
          NextDialogue = 80210236,
          SpeakNpcId = 790068,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790068:Confident_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC43AE"
        },
        [80210236] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          ContentTC = "你說過，不找到她是不會回華胥的。",
          DialogueId = 80210236,
          FinalCamera = "-22.458984,-65.278564,190.244141,0.000084,-19.79907,13.007616,30.000008,115.331322,false,Manual,2.8",
          GUID = "C8CC43D8",
          NextDialogue = 80210237,
          SpeakNpcId = 790067,
          Subtitle = "You said you wouldn't return without finding her.",
          TalkActionId = {
            [1] = "790067:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC43D8"
        },
        [80210237] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          ContentTC = "我累了。",
          DialogueId = 80210237,
          FacialId = {
            [1] = "790068:CM_Sad01"
          },
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC4402",
          NextDialogue = 80210238,
          SpeakNpcId = 790068,
          Subtitle = "I'm tired.",
          TalkActionId = {
            [1] = "790068:Disagree"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4402"
        },
        [80210238] = {
          ContentTC = "我無時無刻不在想著她。沙礫里，海浪里，森林裡，聖塔旁，絮語河上，我都尋覓過她，但是卻又尋她不見。",
          DialogueId = 80210238,
          GUID = "C8CC442C",
          NextDialogue = 80210239,
          SpeakNpcId = 790068,
          Subtitle = "She's on my mind all the time. In the sand, the waves, the forests, by the Sacred Tower, on Whisper River. I searched... but never found a trace.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC442C"
        },
        [80210239] = {
          ContentTC = "於是我在想，她會不會是回到了華胥這個傷心地。但，依舊沒有人見過她。",
          DialogueId = 80210239,
          GUID = "C8CC4456",
          NextDialogue = 80210240,
          SpeakNpcId = 790068,
          Subtitle = "So I wondered, maybe she returned to Huaxu, to all the pain here. But, still, no one's ever seen her.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4456"
        },
        [80210240] = {
          Camera = "55.90625,-152.534912,193.577148,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
          ContentTC = "可憐。",
          DialogueId = 80210240,
          FinalCamera = "57.841797,-147.262451,191.289062,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
          GUID = "C8CC4480",
          NextDialogue = 80210241,
          SpeakNpcId = 790067,
          Subtitle = "How pitiful.",
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4480"
        },
        [80210241] = {
          Camera = "118.96875,-145.442871,164.535156,0.000056,-5.398397,129.398148,33.0,376.434326,false,Manual,3.0",
          ContentTC = "誰可憐。",
          DialogueId = 80210241,
          FinalCamera = "107.117188,-131.01001,162.773438,0.000061,-5.398397,129.398041,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC44AA",
          NextDialogue = 80210242,
          SpeakNpcId = 790068,
          Subtitle = "Who is?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC44AA"
        },
        [80210242] = {
          Camera = "-2.816406,-67.810547,183.550781,0.000092,-19.198992,12.008528,30.000008,92.276848,false,Manual,2.8",
          ContentTC = "天下有情人。",
          DialogueId = 80210242,
          GUID = "C8CC44D4",
          NextDialogue = 80210243,
          SpeakNpcId = 790067,
          Subtitle = "All who love in vain.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC44D4"
        },
        [80210243] = {
          Camera = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          ContentTC = "哈哈。",
          DialogueId = 80210243,
          FacialId = {
            [1] = "790068:CM_Smile01"
          },
          FinalCamera = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
          GUID = "C8CC44FE",
          NextDialogue = 80210244,
          SpeakNpcId = 790068,
          Subtitle = "Heh...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC44FE"
        },
        [80210244] = {
          ContentTC = "要說可憐，你也同樣，我遠離華胥不受大風九章羈絆，而你的話，恐怕在來見我之前，剛剛和應天尉交過手吧。",
          DialogueId = 80210244,
          GUID = "C8CC4528",
          NextDialogue = 80210245,
          SpeakNpcId = 790068,
          Subtitle = "If we're talking pitiful... you're no different. I wander free, beyond the reach of the Nine Chapters. But you probably just crossed blades with Magistrates before coming to see me.",
          TalkActionId = {
            [1] = "790068:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4528"
        },
        [80210245] = {
          Camera = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          ContentTC = "那是自然，但也早就習慣如此了，正如你習慣了漂泊異鄉一樣。",
          DialogueId = 80210245,
          FinalCamera = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          GUID = "C8CC4552",
          NextDialogue = 80210246,
          SpeakNpcId = 790067,
          Subtitle = "Obviously. But I'm used to it by now. Just as you're used to life abroad.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4552"
        },
        [80210246] = {
          Camera = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          ContentTC = "剛剛你打斷我的話，罰酒一杯，該喝了。等你喝完我就上路繼續找她，這次我反其道行之，先從海路到伊瑟爾。",
          DialogueId = 80210246,
          FinalCamera = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
          GUID = "C8CC457C",
          NextDialogue = 80210247,
          SpeakNpcId = 790068,
          Subtitle = "You interrupted me. Drink your penalty. Once you finish, I set out again to look for her. This time I'll try the reverse. Start by sea to Aethyrie.",
          TalkActionId = {
            [1] = "790068:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC457C"
        },
        [80210247] = {
          Camera = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
          ContentTC = "我剛剛已經罰完了。",
          DialogueId = 80210247,
          FinalCamera = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
          GUID = "C8CC45A6",
          NextDialogue = 80210248,
          SpeakNpcId = 790067,
          Subtitle = "I already drank it.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC45A6"
        },
        [80210248] = {
          ContentTC = "什麼時候？我怎麼沒瞧見。",
          DialogueId = 80210248,
          GUID = "C8CC45D0",
          NextDialogue = 80210249,
          SpeakNpcId = 790068,
          Subtitle = "When? I didn't see.",
          TalkActionId = {
            [1] = "790068:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC45D0"
        },
        [80210249] = {
          ContentTC = "在你說到聖塔旁，絮語河上的時候。",
          DialogueId = 80210249,
          GUID = "C8CC45FA",
          NextDialogue = 80210250,
          SpeakNpcId = 790067,
          Subtitle = "Just when you spoke of the Sacred Tower and Whisper River.",
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC45FA"
        },
        [80210250] = {
          ContentTC = "真的假的？唉，可能是我太想見她了。",
          DialogueId = 80210250,
          GUID = "C8CC4624",
          NextDialogue = 80210251,
          SpeakNpcId = 790068,
          Subtitle = "Really? I didn't even notice. Maybe I just want to see her too much.",
          TalkActionId = {
            [1] = "790068:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4624"
        },
        [80210251] = {
          Camera = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
          ContentTC = "騙你的，我還沒喝。",
          DialogueId = 80210251,
          FacialId = {
            [1] = "790067:Smile01"
          },
          GUID = "C8CC464E",
          NextDialogue = 80210252,
          SpeakNpcId = 790067,
          Subtitle = "Not really, I haven't drunk yet.",
          TalkActionId = {
            [1] = "790067:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC464E"
        },
        [80210252] = {
          Camera = "32.886719,-42.50415,154.229492,0.000131,-5.197801,142.396057,20.0,155.23967,false,Manual,4.0",
          ContentTC = "你小子，從小就喜歡騙人，一直沒變。",
          DialogueId = 80210252,
          GUID = "C8CC4678",
          NextDialogue = 80210253,
          SpeakNpcId = 790068,
          Subtitle = "You little... you've loved tricking people since we were boys. Some things never change.",
          TalkActionId = {
            [1] = "790067:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4678"
        },
        [80210253] = {
          Camera = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
          ContentTC = "而你就沒有識破的時候。",
          DialogueId = 80210253,
          FinalCamera = "-246.677734,73.932129,171.296875,0.000083,-6.598113,-14.604773,33.0,343.677704,false,Manual,3.0",
          GUID = "C8CC46A2",
          NextDialogue = 80210254,
          SpeakNpcId = 790067,
          Subtitle = "And you still fall for it every time.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC46A2"
        },
        [80210254] = {
          ContentTC = "哈哈哈哈。",
          DialogueId = 80210254,
          FacialId = {
            [1] = "790067:Smile02"
          },
          GUID = "C8CC46CC",
          NextDialogue = 80210255,
          SpeakNpcId = 790067,
          Subtitle = "Hahaha...",
          TalkActionId = {
            [1] = "790068:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC46CC"
        },
        [80210255] = {
          Camera = "-17.587891,-73.812012,162.646484,0.000131,-7.797698,121.197479,20.0,155.23967,false,Manual,4.0",
          ContentTC = "那麼，我出發了，後會有期。",
          DialogueId = 80210255,
          FacialId = {
            [1] = "790068:CM_Idle"
          },
          GUID = "C8CC46F6",
          NextDialogue = 80210256,
          SpeakNpcId = 790068,
          Subtitle = "Well then, I'm off. Till we meet again.",
          TalkActionId = {
            [1] = "790068:Salute_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC46F6"
        },
        [80210256] = {
          Camera = "-786.357422,-477.311035,427.586914,0.000243,-19.797138,31.996326,20.0,1022.357056,false,Manual,4.0",
          ContentTC = "後會有期。",
          DialogueId = 80210256,
          FacialId = {
            [1] = "790067:None"
          },
          FinalCamera = "-968.662109,-591.214844,504.962891,0.000238,-17.997028,31.397633,20.0,1022.357056,false,Manual,4.0",
          GUID = "C8CC4720",
          LookAt = {
            [1] = "790068:n(790068)"
          },
          NextDialogue = 80210257,
          Scripts = "MoveTo{_delay{3},ActorId{790068},TargetPoint{\"BP_NewTargetPoint_15032\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 790067,
          Subtitle = "Till we meet again.",
          TalkActionId = {
            [1] = "790068:Salute_End",
            [2] = "790067:Story_HoldFist_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC4720"
        },
        [80210257] = {
          ContentTC = "這第二位也就此離去……那麼接下來是第三位。",
          DialogueId = 80210257,
          GUID = "C8CC474A",
          SpeakNpcId = 790067,
          Subtitle = "And so the second one departs... now for the third.",
          TalkActionId = {
            [1] = "790067:Story_HoldFist_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/002/C8CC474A"
        },
        [80210301] = {
          Camera = "-1168.496094,1264.441406,313.365234,0.000131,-4.398683,-49.787758,30.000002,1615.87854,false,Manual,2.8",
          ContentTC = "俠客大多是吃主，玩主。想來也是正常的，好馬，好劍，好衣裳，總是大俠的標配。",
          DialogueId = 80210301,
          FacialId = {
            [1] = "790071:Smile01"
          },
          FinalCamera = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
          GUID = "C8CC4E82",
          LookAt = {
            [1] = "790071:n(790069)",
            [2] = "790069:n(790071)"
          },
          NextDialogue = 80210302,
          Scripts = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
          Subtitle = "A true hero is, above all, a connoisseur of fine living. A noble steed, a peerless blade, and elegant robes are the rightful marks of the righteous.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4E82"
        },
        [80210302] = {
          ContentTC = "至於酒食，更是極為精細。以至於提起俠客，總是感覺他們好酒，大塊吃肉。而如果一個俠客明言不喝酒，就多少覺得他的劍意少了三分老辣。",
          DialogueId = 80210302,
          GUID = "C8CC4EAC",
          NextDialogue = 80210303,
          Subtitle = "But none are pursued with more fastidious care than food and drink. So much so that the very image of a hero is steeped in vintage wine and generously roasted meats. Should a swordsman refuse wine, one feels the edge of his blade is blunted — lacking that seasoned cunning.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4EAC"
        },
        [80210303] = {
          Camera = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
          ContentTC = "小二，一斤黃酒，七個油豆腐，辣醬要多！",
          DialogueId = 80210303,
          FinalCamera = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC4ED6",
          NextDialogue = 80210304,
          SpeakNpcId = 790071,
          Subtitle = "One catty of yellow wine, seven fried tofu puffs, and extra chili paste!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4ED6"
        },
        [80210304] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentTC = "好嘞，我這就吩咐給您做。",
          DialogueId = 80210304,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC4F00",
          NextDialogue = 80210305,
          SpeakNpcId = 790069,
          Subtitle = "Right away, sir! I'll put the order in.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4F00"
        },
        [80210305] = {
          ContentTC = "一斤黃酒，七個油豆腐，辣醬要多！",
          DialogueId = 80210305,
          GUID = "C8CC4F2A",
          NextDialogue = 80210306,
          SpeakNpcId = 790069,
          Subtitle = "One catty of yellow wine, seven fried tofu puffs, and extra chili paste!",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4F2A"
        },
        [80210306] = {
          Camera = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
          ContentTC = "謝了。順便問下，你可聽說過一位飄零人，名喚鐵掌移山劉緯甫，年紀應該有六七十了。",
          DialogueId = 80210306,
          FinalCamera = "-444.984375,-72.832031,49.90918,0.00003,6.600196,30.607128,20.0,400.820953,false,Manual,2.8",
          GUID = "C8CC4F54",
          NextDialogue = 80210307,
          SpeakNpcId = 790071,
          Subtitle = "Thanks. By the way, have you heard of a Drifter named Liu Weifu, the Iron Palm? He'd be in his sixties or seventies by now.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4F54"
        },
        [80210307] = {
          ContentTC = "沒聽說過。我這輩子都沒見過飄零人呢。",
          DialogueId = 80210307,
          GUID = "C8CC4F7E",
          NextDialogue = 80210308,
          SpeakNpcId = 790069,
          Subtitle = "Can't say I have. Never met a Drifter in my life.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4F7E"
        },
        [80210308] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentTC = "那你現在見過了。",
          DialogueId = 80210308,
          FinalCamera = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC4FA8",
          NextDialogue = 80210309,
          SpeakNpcId = 790071,
          Subtitle = "Well, you're looking at one right now.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4FA8"
        },
        [80210309] = {
          ContentTC = "您是飄零人？",
          DialogueId = 80210309,
          GUID = "C8CC4FD2",
          NextDialogue = 80210310,
          SpeakNpcId = 790069,
          Subtitle = "You're a Drifter?",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4FD2"
        },
        [80210310] = {
          ContentTC = "我是啊，怎麼，看著不像？",
          DialogueId = 80210310,
          GUID = "C8CC4FFC",
          NextDialogue = 80210311,
          SpeakNpcId = 790071,
          Subtitle = "Obviously. What, I don't look the part?",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC4FFC"
        },
        [80210311] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentTC = "是不像，我聽說飄零人啊都是喜歡大口喝酒大口吃肉的，沒見過點油豆腐的。",
          DialogueId = 80210311,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC5026",
          NextDialogue = 80210312,
          SpeakNpcId = 790069,
          Subtitle = "Not really. I heard Drifters drink wine by the bowl and eat meat by the chunk. Never seen one order tofu puffs.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5026"
        },
        [80210312] = {
          Camera = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
          ContentTC = "這叫什麼話，飄零人又不是野狼野狗就愛吃肉，那吃得精細起來也是自有一套講究的。",
          DialogueId = 80210312,
          FinalCamera = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC5050",
          NextDialogue = 80210313,
          SpeakNpcId = 790071,
          Subtitle = "What kind of nonsense is that? We're not wild dogs tearing into raw meat. When we eat with purpose, we have our own refinements.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5050"
        },
        [80210313] = {
          Camera = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
          ContentTC = "那野狼野狗也不止吃肉，還吃其他東西呢……",
          DialogueId = 80210313,
          FinalCamera = "-462.796875,-83.355469,47.517578,0.0,6.600196,30.608337,20.0,466.554138,false,Manual,2.8",
          GUID = "C8CC507A",
          NextDialogue = 80210314,
          SpeakNpcId = 790069,
          Subtitle = "Well, dogs eat more than just meat, actually…",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC507A"
        },
        [80210314] = {
          ContentTC = "打住，打住，我油豆腐好沒？幫我催一催。",
          DialogueId = 80210314,
          GUID = "C8CC50A4",
          NextDialogue = 80210315,
          SpeakNpcId = 790071,
          Subtitle = "That's enough. Are my tofu puffs ready? Hurry them up, will you?",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC50A4"
        },
        [80210315] = {
          ContentTC = "得嘞，卯金叔，油豆腐快點。",
          DialogueId = 80210315,
          GUID = "C8CC50CE",
          NextDialogue = 80210316,
          SpeakNpcId = 790069,
          Subtitle = "You got it! Uncle Maojin, hurry with those tofu puffs!",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC50CE"
        },
        [80210316] = {
          ContentTC = "莫催，就好了。",
          DialogueId = 80210316,
          GUID = "C8CC50F8",
          NextDialogue = 80210317,
          SpeakNpcId = 790070,
          Subtitle = "No rush. Almost done.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC50F8"
        },
        [80210317] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentTC = "行。客官您再等等。不過，剛剛您說飄零人吃起來自有一套，要不多講講唄，反正現在店裡也沒人，想聽。",
          DialogueId = 80210317,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC5122",
          NextDialogue = 80210318,
          SpeakNpcId = 790069,
          Subtitle = "Right. Sir, it'll just be a moment. But since you mentioned that Drifters \"eat with purpose,\" could you tell me more? The place is empty — I'd love to hear.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5122"
        },
        [80210318] = {
          Camera = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
          ContentTC = "也罷，我今天來找的這位飄零人前輩，當年也以做得一手好菜聞名，被稱作庖俠。",
          DialogueId = 80210318,
          FinalCamera = "-208.675781,31.691406,134.121582,0.000012,-19.999954,47.00246,20.0,150.472961,false,Manual,2.8",
          GUID = "C8CC514C",
          NextDialogue = 80210319,
          SpeakNpcId = 790071,
          Subtitle = "Fine. The master I'm looking for today was also famous in his day for his cooking. They called him the \"Gourmet Knight.\"",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC514C"
        },
        [80210319] = {
          ContentTC = "他老人家最知名的一手是「若木無覓銜燭龍」，號稱是把維繫大風九章的那白龍斬了做宴席。",
          DialogueId = 80210319,
          GUID = "C8CC5176",
          NextDialogue = 80210320,
          SpeakNpcId = 790071,
          Subtitle = "His most legendary dish was called \"The Untamable Loong Beyond Reach.\" Rumor was, he slew the Argent Loong that guarded the Nine Chapters and served it at a feast.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5176"
        },
        [80210320] = {
          ContentTC = "實際上呢，是用各種飛禽走獸的肉分別以掌力擊碎，再絞製成型。這樣一來，一口下去可以嘗出百般滋味，所以敢自稱是龍肉。",
          DialogueId = 80210320,
          GUID = "C8CC51A0",
          NextDialogue = 80210321,
          SpeakNpcId = 790071,
          Subtitle = "In truth, he used his palm strength to tenderize meats from all kinds of birds and beasts, ground them fine, and reshaped them. One bite released manifold flavors — so he called it \"Loong Meat.\"",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC51A0"
        },
        [80210321] = {
          ContentTC = "然後再又以極其滑嫩的豆腐作為基底，與諸多畜類的脊髓骨髓一同炒製，讓它們的香味滲入豆腐中，號稱龍髓。",
          DialogueId = 80210321,
          GUID = "C8CC51CA",
          NextDialogue = 80210322,
          SpeakNpcId = 790071,
          Subtitle = "Then he'd stir-fry incredibly silken tofu with marrow from various animals, letting their richness soak in. He called that \"Loong Marrow.\"",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC51CA"
        },
        [80210322] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentTC = "客官您說笑了，豆腐就是豆腐，怎麼能號稱是龍髓呢。要這麼說，我們店賣的油豆腐，也能叫炸龍髓了。",
          DialogueId = 80210322,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC51F4",
          NextDialogue = 80210323,
          SpeakNpcId = 790069,
          Subtitle = "You're having a laugh, sir. It's just tofu. How could anyone call it Loong Marrow? By that logic, our fried tofu puffs could be called \"Fried Loong Marrow.\"",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC51F4"
        },
        [80210323] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentTC = "哎，我也是聽師父說過而已。那位鐵掌移山劉緯甫早早金盆洗手，如今沒人知道他身在何方。",
          DialogueId = 80210323,
          FinalCamera = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC521E",
          NextDialogue = 80210324,
          SpeakNpcId = 790071,
          Subtitle = "Ah, I only know what my master told me. They say the Iron Palm retired long ago. No one knows where he is now.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC521E"
        },
        [80210324] = {
          Camera = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
          ContentTC = "說半天說得我都流口水了，原來您沒吃過啊。行了那別說這些虛無縹緲的了，來嘗嘗這個吧，我們店招牌的油豆腐。",
          DialogueId = 80210324,
          FinalCamera = "-847.84375,934.597656,274.614746,0.000131,-6.0,-49.78775,30.000002,1361.954834,false,Manual,2.8",
          GUID = "C8CC5248",
          NextDialogue = 80210325,
          SpeakNpcId = 790069,
          Subtitle = "All this talk is making my mouth water, and you've never even tasted it? Enough fantasy — try these. Our signature fried tofu puffs.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5248"
        },
        [80210325] = {
          ContentTC = "……我來嘗嘗。",
          DialogueId = 80210325,
          GUID = "C8CC5272",
          SpeakNpcId = 790071,
          Subtitle = "Let me taste it.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5272"
        },
        [80210326] = {
          ContentTC = "啊……燙，但……好好吃。",
          DialogueId = 80210326,
          GUID = "C8CC529C",
          IsBlack = 1,
          LookAt = {
            [1] = "790071:n(790069)",
            [2] = "790069:n(790071)"
          },
          NextDialogue = 80210327,
          Scripts = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
          SpeakNpcId = 790071,
          Subtitle = "Ah! Hot, but so savory",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC529C"
        },
        [80210327] = {
          ContentTC = "嘶哈——",
          DialogueId = 80210327,
          GUID = "C8CC52C6",
          IsBlack = 1,
          NextDialogue = 80210328,
          SpeakNpcId = 790071,
          Subtitle = "Whew—",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC52C6"
        },
        [80210328] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentTC = "表皮被炸得酥脆，咬下去嘎吱作響，而裡面的豆腐卻軟嫩綿滑，卻又不至於立刻散掉，得要相當的力道和巧勁才能做到這個地步。",
          DialogueId = 80210328,
          FinalCamera = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC52F0",
          NextDialogue = 80210329,
          SpeakNpcId = 790071,
          Subtitle = "The outside is fried crisp — it crackles when you bite, but the inside is tender, smooth, yet firm enough to hold together. That takes serious skill and control.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC52F0"
        },
        [80210329] = {
          Camera = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          ContentTC = "算你識貨，我們卯金叔做得油豆腐可是遠近聞名，想來啊，不比那什麼「若木無覓銜燭龍」差。",
          DialogueId = 80210329,
          FinalCamera = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
          GUID = "C8CC531A",
          NextDialogue = 80210330,
          SpeakNpcId = 790069,
          Subtitle = "You've got taste. Uncle Maojin's tofu puffs are famous all around. I'd say they're no worse than that \"Untamable Loong\" nonsense.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC531A"
        },
        [80210330] = {
          ContentTC = "等等……莫非……",
          DialogueId = 80210330,
          FacialId = {
            [1] = "790071:Shock01"
          },
          GUID = "C8CC5344",
          NextDialogue = 80210331,
          SpeakNpcId = 790071,
          Subtitle = "Wait, could it be…",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5344"
        },
        [80210331] = {
          Camera = "-291.878906,37.308594,153.111328,0.000122,-8.597596,-25.187979,30.000013,264.169495,false,Manual,2.8",
          ContentTC = "就你個瓜娃兒話多，莫要和客人擺龍門陣，又有油豆腐弄好了，上菜。",
          DialogueId = 80210331,
          FinalCamera = "-241.59375,9.6875,154.276855,0.000128,-8.597521,-24.999588,30.000013,185.753601,false,Manual,2.8",
          GUID = "C8CC536E",
          NextDialogue = 80210332,
          Scripts = "MoveTo{ActorId{790070},TargetPoint{\"BP_NewTargetPoint_150303_1\"},MoveSpeed{150}}",
          SpeakNpcId = 790070,
          Subtitle = "Talkative little rascal. Stop pestering the customer. Another batch of tofu puffs is ready — serve them.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC536E"
        },
        [80210332] = {
          ContentTC = "得嘞。",
          DialogueId = 80210332,
          Duration = 5,
          GUID = "C8CC5398",
          LookAt = {
            [1] = "790069:n(790069)"
          },
          NextDialogue = 80210333,
          Scripts = "MoveTo{ActorId{790069},TargetPoint{\"BP_NewTargetPoint_150303_2\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 790069,
          Subtitle = "Right away!",
          TurnTo = {
            [1] = "790070:n(790071)"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5398"
        },
        [80210333] = {
          Camera = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
          ContentTC = "嘗出來了？",
          DialogueId = 80210333,
          FinalCamera = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
          GUID = "C8CC53C2",
          LookAt = {
            [1] = "790071:n(790070)"
          },
          NextDialogue = 80210334,
          SpeakNpcId = 790070,
          Subtitle = "You taste it?",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "790070:n(790071)"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC53C2"
        },
        [80210334] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentTC = "嘗出來了，前輩的手藝果然名不虛傳，難怪我師父這麼多年一直念念不忘。",
          DialogueId = 80210334,
          FacialId = {
            [1] = "790071:Smile01"
          },
          FinalCamera = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC53EC",
          NextDialogue = 80210335,
          SpeakNpcId = 790071,
          Subtitle = "Yes. Your skill lives up to its reputation. No wonder my master could never forget it.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC53EC"
        },
        [80210335] = {
          Camera = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
          ContentTC = "淨說這些虛的幹啥子嘞，你吃東西是為自己吃的還是為你師父吃的？講你自己的想法。",
          DialogueId = 80210335,
          FinalCamera = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
          GUID = "C8CC5416",
          NextDialogue = 80210336,
          SpeakNpcId = 790070,
          Subtitle = "Enough with the flattery. You eating for yourself or for your master? Speak your own mind.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5416"
        },
        [80210336] = {
          Camera = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
          ContentTC = "好吃！",
          DialogueId = 80210336,
          FinalCamera = "-314.59375,-444.601562,82.464844,0.000134,1.999995,62.002323,20.0,592.152588,false,Manual,2.8",
          GUID = "C8CC5440",
          NextDialogue = 80210337,
          SpeakNpcId = 790071,
          Subtitle = "It's delicious!",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5440"
        },
        [80210337] = {
          ContentTC = "對頭，那好吃的話應該怎麼樣？",
          DialogueId = 80210337,
          GUID = "C8CC546A",
          NextDialogue = 80210338,
          SpeakNpcId = 790070,
          Subtitle = "There, see? So if it's good, what should you do?",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC546A"
        },
        [80210338] = {
          ContentTC = "再來七塊！",
          DialogueId = 80210338,
          GUID = "C8CC5494",
          NextDialogue = 80210339,
          SpeakNpcId = 790071,
          Subtitle = "Seven more!",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5494"
        },
        [80210339] = {
          ContentTC = "嘞就對嘛。",
          DialogueId = 80210339,
          GUID = "C8CC54BE",
          NextDialogue = 80210340,
          SpeakNpcId = 790070,
          Subtitle = "Now you're talking.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC54BE"
        },
        [80210340] = {
          Camera = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
          ContentTC = "好了，吃的問題解決了，現在告訴我，你師父是哪個？",
          DialogueId = 80210340,
          FinalCamera = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
          GUID = "C8CC54E8",
          NextDialogue = 80210341,
          SpeakNpcId = 790070,
          Subtitle = "Well, now that you're fed — who's your master?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC54E8"
        },
        [80210341] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentTC = "宴山亭。",
          DialogueId = 80210341,
          FinalCamera = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC5512",
          NextDialogue = 80210342,
          SpeakNpcId = 790067,
          Subtitle = "Yan Shanting.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5512"
        },
        [80210342] = {
          Camera = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
          ContentTC = "喔，原來是他，是為了論劍而來吧？沒想到他還記得這事。",
          DialogueId = 80210342,
          FinalCamera = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
          GUID = "C8CC553C",
          NextDialogue = 80210343,
          SpeakNpcId = 790070,
          Subtitle = "Oh, him. Here for the Art of the Sword, then? Didn't think he'd remember.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC553C"
        },
        [80210343] = {
          Camera = "-104.40625,-155.425781,163.111328,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
          ContentTC = "師父念念不忘，敢問劉前輩會參加嗎？",
          DialogueId = 80210343,
          FacialId = {
            [1] = "790071:Smile01"
          },
          FinalCamera = "-102.179688,-128.832031,153.394531,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
          GUID = "C8CC5566",
          NextDialogue = 80210344,
          SpeakNpcId = 790071,
          Subtitle = "He never forgot. Will you be participating, Master Liu?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5566"
        },
        [80210344] = {
          Camera = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
          ContentTC = "這裡沒有劉前輩，我早已放下刀，這裡只有卯金叔。",
          DialogueId = 80210344,
          FinalCamera = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
          GUID = "C8CC5590",
          NextDialogue = 80210345,
          SpeakNpcId = 790070,
          Subtitle = "\"Master Liu\" isn't here anymore. I put down the blade long ago. Here is only Uncle Maojin.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5590"
        },
        [80210345] = {
          ContentTC = "好了，莫要再問，再要七個油豆腐是吧，我這就繼續。",
          DialogueId = 80210345,
          GUID = "C8CC55BA",
          NextDialogue = 80210346,
          SpeakNpcId = 790070,
          Subtitle = "Enough questions. You want seven more tofu puffs? I'll make them.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC55BA"
        },
        [80210346] = {
          Camera = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
          ContentTC = "……再來七個，打包帶走，我也讓我朋友嘗一嘗。",
          DialogueId = 80210346,
          FacialId = {
            [1] = "790071:Smile01"
          },
          FinalCamera = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
          GUID = "C8CC55E4",
          NextDialogue = 80210347,
          SpeakNpcId = 790071,
          Subtitle = "Make it seven to go. I'll let my friends try them.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC55E4"
        },
        [80210347] = {
          Camera = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
          ContentTC = "要得，但切記，只許跟朋友說這是卯金叔做的，要是多說一句，我把你舌頭割下來做成滷菜。",
          DialogueId = 80210347,
          FinalCamera = "-544.378906,-565.476562,74.48877,0.000132,1.999995,51.004082,20.0,592.152588,false,Manual,2.8",
          GUID = "C8CC560E",
          NextDialogue = 80210348,
          SpeakNpcId = 790070,
          Subtitle = "Fine. But remember, tell them Uncle Maojin made it. One extra word, I'll cut out your tongue and braise it.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC560E"
        },
        [80210348] = {
          ContentTC = "那是自然，那麼後生拜別前輩。",
          DialogueId = 80210348,
          GUID = "C8CC5638",
          SpeakNpcId = 790071,
          Subtitle = "Understood. Then I take my leave, master.",
          VoiceName = "voice/$Locale$/inv/Kezhou/003/C8CC5638"
        },
        [80210401] = {
          Camera = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
          ContentTC = "一大早的，還沒睡醒呢就把人吵起來，是要去哪兒？",
          DialogueId = 80210401,
          FacialId = {
            [1] = "790008:Doubt01"
          },
          FinalCamera = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
          GUID = "C8CC5EEA",
          LookAt = {
            [1] = "790008:n(790067)",
            [2] = "790067:n(790008)"
          },
          NextDialogue = 80210402,
          SpeakNpcId = 790008,
          Subtitle = "It's early in the morning, where are we even going?",
          TalkActionId = {
            [1] = "790008:Confident_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC5EEA"
        },
        [80210402] = {
          Camera = "15.414062,815.271973,212.397461,0.000014,-4.60016,-71.792816,40.310993,430.446808,false,Manual,2.8",
          ContentTC = "比武論劍，二十年一次。",
          DialogueId = 80210402,
          FacialId = {
            [1] = "790067:Confident01"
          },
          FinalCamera = "28.40625,774.96582,208.994141,0.000013,-4.60016,-72.792603,40.310993,430.446808,false,Manual,2.8",
          GUID = "C8CC5F14",
          NextDialogue = 80210403,
          SpeakNpcId = 790067,
          Subtitle = "The Grand Blade-Meet. Happens once every twenty years.",
          TalkActionId = {
            [1] = "790067:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC5F14"
        },
        [80210403] = {
          Camera = "-748.292969,-30.820801,161.345703,0.000053,0.0,31.808994,40.310993,975.20166,false,Manual,2.8",
          ContentTC = "說這個我就不困了，誰和誰啊？",
          DialogueId = 80210403,
          FinalCamera = "-626.019531,45.025391,161.345703,0.000053,0.0,31.809633,40.310993,872.170044,false,Manual,2.8",
          GUID = "C8CC5F3E",
          NextDialogue = 80210404,
          SpeakNpcId = 790008,
          Subtitle = "Now I'm awake. Who's fighting?",
          TalkActionId = {
            [1] = "790008:Confident_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC5F3E"
        },
        [80210404] = {
          ContentTC = "華胥有頭有臉的飄零人理應都會來，之前已經舉行過七八次了，大家會在山巔互相比試，直到分出勝負。",
          DialogueId = 80210404,
          GUID = "C8CC5F68",
          NextDialogue = 80210405,
          SpeakNpcId = 790067,
          Subtitle = "Any Drifter in Huaxu with a reputation ought to come. They've held this seven or eight times already — up on the mountain peak, they spar until only one stands victorious.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC5F68"
        },
        [80210405] = {
          Camera = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
          ContentTC = "那麼這次，會有多少人參加？",
          DialogueId = 80210405,
          FinalCamera = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
          GUID = "C8CC5F92",
          NextDialogue = 80210406,
          SpeakNpcId = 790008,
          Subtitle = "How many will show up this time?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC5F92"
        },
        [80210406] = {
          Camera = "-26.566406,613.213379,186.345703,0.000053,0.0,-59.788727,40.310993,251.490341,false,Manual,2.8",
          ContentTC = "等到了你就知道了。",
          DialogueId = 80210406,
          FinalCamera = "-14.558594,592.585449,193.345703,0.000053,0.0,-59.788727,40.310993,213.980072,false,Manual,2.8",
          GUID = "C8CC5FBC",
          SpeakNpcId = 790067,
          Subtitle = "You'll see when we get there.",
          TalkActionId = {
            [1] = "790067:Talk03_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC5FBC"
        },
        [80210407] = {
          Camera = "976.125,1795.242676,518.382812,0.000097,-9.999997,-118.000748,26.65424,2016.868164,false,Manual,2.8",
          ContentTC = "跟著刻舟到了一處相當荒僻的山間，想來這就是他們此前比武論劍之地了。",
          DialogueId = 80210407,
          FinalCamera = "882.355469,1518.284668,467.509766,0.000097,-9.999964,-118.000748,26.65424,1751.967041,false,Manual,2.8",
          GUID = "C8CC5FE6",
          NextDialogue = 80210408,
          Subtitle = "Following Kezhou deep into a remote stretch of mountains — the site of the contest, it seemed.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC5FE6"
        },
        [80210408] = {
          ContentTC = "但見滿目新綠，飛泉直下。是適合比試的場地，只是，似乎有些過於冷清……",
          DialogueId = 80210408,
          GUID = "C8CC6010",
          NextDialogue = 80210409,
          Subtitle = "Before lay slopes lush with new growth, cascading springs — a fine arena for a contest, yet... it felt too still, too quiet.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6010"
        },
        [80210409] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "怎麼只有我們倆，不是說有頭有臉的飄零人都會來嗎？",
          DialogueId = 80210409,
          FacialId = {
            [1] = "790008:Doubt01"
          },
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC603A",
          LookAt = {
            [1] = "790067:n(790008)"
          },
          NextDialogue = 80210410,
          SpeakNpcId = 790008,
          Subtitle = "Why is it just us? I thought you said every Drifter with a name would be here.",
          TalkActionId = {
            [1] = "790008:Sigh_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC603A"
        },
        [80210410] = {
          Camera = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
          ContentTC = "說來慚愧，現在有頭有臉的飄零人也不剩幾位了，正所謂江湖兒女日漸少。",
          DialogueId = 80210410,
          FacialId = {
            [1] = "790067:Sad01"
          },
          FinalCamera = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
          GUID = "C8CC6064",
          NextDialogue = 80210411,
          SpeakNpcId = 790067,
          Subtitle = "A shame to say it, but there aren't many left worth the title these days. We Drifters grow fewer with each passing year",
          TalkActionId = {
            [1] = "790008:Sigh_End",
            [2] = "790067:Talk01_Start"
          },
          ToFinalCameraBlendTime = 40,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6064"
        },
        [80210411] = {
          ContentTC = "且不說這次，就是上一次參加比武論劍的飄零人，僅有四位而已。",
          DialogueId = 80210411,
          FacialId = {
            [1] = "790008:None"
          },
          GUID = "C8CC608E",
          LookAt = {
            [1] = "790008:n(790067)"
          },
          NextDialogue = 80210412,
          SpeakNpcId = 790067,
          Subtitle = "Even last time, only four showed up.",
          TalkActionId = {
            [1] = "790067:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC608E"
        },
        [80210412] = {
          ContentTC = "第一位呢，便是我的師父宴山亭。雖然他已經離世，但是在離世前對這比武論劍念念不忘，讓我代他出戰。",
          DialogueId = 80210412,
          FacialId = {
            [1] = "790067:None"
          },
          GUID = "C8CC60B8",
          NextDialogue = 80210413,
          SpeakNpcId = 790067,
          Subtitle = "The first was my master, Yan Shanting. Though he's passed, his last wish was for me to stand in his place here.",
          TalkActionId = {
            [1] = "790067:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC60B8"
        },
        [80210413] = {
          ContentTC = "於是我就走訪了各處，找到了另外三位當年參加了比武論劍的高手。",
          DialogueId = 80210413,
          GUID = "C8CC60E2",
          NextDialogue = 80210414,
          SpeakNpcId = 790067,
          Subtitle = "So then, I sought out the other three masters who fought.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC60E2"
        },
        [80210414] = {
          ContentTC = "我先找了其中一位善於用劍的女俠，也是上次論劍時奪得魁首的天下第一。但卻連面也沒見到。",
          DialogueId = 80210414,
          GUID = "C8CC610C",
          NextDialogue = 80210415,
          SpeakNpcId = 790067,
          Subtitle = "First, a swordswoman of great skill — the one who won last time, unmatched among Huaxu. But I didn't even see her.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC610C"
        },
        [80210415] = {
          ContentTC = "我師父一直說她愛劍成痴，大部分時候甚至不願意拔劍，只以劍鞘傷人，又早早歸隱，遠離江湖，所以並沒有被大風九章盯上。",
          DialogueId = 80210415,
          GUID = "C8CC6136",
          NextDialogue = 80210416,
          SpeakNpcId = 790067,
          Subtitle = "My master told me she loved the sword too deeply — often she wouldn't even draw it, fighting with the sheath instead. However, she left the world of blood and dust, hid herself away, so the Nine Chapters never caught her.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6136"
        },
        [80210416] = {
          ContentTC = "現如今，卻把自己的佩劍拿去當孩子的玩物，想必是不願踏足江湖，只想躲進小樓，遠離紛擾，那麼我也沒有多打擾她。",
          DialogueId = 80210416,
          GUID = "C8CC6160",
          NextDialogue = 80210417,
          SpeakNpcId = 790067,
          Subtitle = "Now, interesting enough, she lets her children play with her prized blade. She wants no part of the clash of blades — only peace behind closed doors, so I didn't disturb her.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6160"
        },
        [80210417] = {
          ContentTC = "師父一直說她有大智慧，我此前都不明白，這次見了……不，這次沒見到她，但是也已經明白師父為什麼會這麼說了。",
          DialogueId = 80210417,
          GUID = "C8CC618A",
          NextDialogue = 80210418,
          SpeakNpcId = 790067,
          Subtitle = "My master called her the wisest of them. I never understood. Well, now I know his reasons even without seeing her this time.",
          TalkActionId = {
            [1] = "790067:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC618A"
        },
        [80210418] = {
          Camera = "478.570312,-143.509766,121.444336,0.000169,2.99999,132.400314,42.362053,217.393646,false,Manual,2.8",
          ContentTC = "嗯，換做是我的話，我應該也會同樣做。",
          DialogueId = 80210418,
          FinalCamera = "472.527344,-136.883301,121.911133,0.00017,2.99999,132.400513,42.362053,217.393646,false,Manual,2.8",
          GUID = "C8CC61B4",
          NextDialogue = 80210419,
          SpeakNpcId = 790008,
          Subtitle = "I think... I would've done the same.",
          TalkActionId = {
            [1] = "790008:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC61B4"
        },
        [80210419] = {
          Camera = "925.164062,204.170898,224.050781,0.000123,-9.999943,-150.992493,26.65424,679.187683,false,Manual,2.8",
          ContentTC = "再一位呢，喚作鳴鸞，比我年長一點，自幼就被認定是習武的天才，年少成名，以弱冠之齡便能參加比武論劍。",
          DialogueId = 80210419,
          FinalCamera = "742.019531,445.837402,225.842773,0.000124,-9.999943,-129.189941,26.65424,679.187683,false,Manual,2.8",
          GUID = "C8CC61DE",
          NextDialogue = 80210420,
          SpeakNpcId = 790067,
          Subtitle = "The next was Mingluan, a little older than me. A prodigy since childhood — he became famous young, fighting in this contest before he'd even come of age.",
          TalkActionId = {
            [1] = "790067:Talk02R_Start"
          },
          ToFinalCameraBlendTime = 40,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC61DE"
        },
        [80210420] = {
          ContentTC = "他本有一位紅顏知己，劍法同樣精微，一直與他快意恩仇，人人都覺得他們是一對璧人，天作之合。",
          DialogueId = 80210420,
          GUID = "C8CC6208",
          NextDialogue = 80210421,
          SpeakNpcId = 790067,
          Subtitle = "He had a beloved once, a master of the sword herself. They roamed together, righting wrongs. Everyone thought they were destined.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6208"
        },
        [80210421] = {
          ContentTC = "但是再多的快意恩仇也會讓人厭倦，那位紅顏知己厭倦了終日飄零，不得不躲避應天尉追殺的生活。",
          DialogueId = 80210421,
          GUID = "C8CC6232",
          NextDialogue = 80210422,
          SpeakNpcId = 790067,
          Subtitle = "But even a righteous life wears on you. She grew tired — always drifting, always hiding from Magistrates.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6232"
        },
        [80210422] = {
          ContentTC = "於是他們相約，在某日一起離開華胥，去大陸的其他地方，過安穩日子。",
          DialogueId = 80210422,
          GUID = "C8CC625C",
          NextDialogue = 80210423,
          SpeakNpcId = 790067,
          Subtitle = "So, they promised to leave Huaxu together, find a quiet life elsewhere.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC625C"
        },
        [80210423] = {
          ContentTC = "只是他們許約的那一日，偏偏又是論劍的日子。而鳴鸞被年少盛名所累，想要等到比武結束後，奪了第一的名號後與那位知己再一同離開華胥。",
          DialogueId = 80210423,
          GUID = "C8CC6286",
          NextDialogue = 80210424,
          SpeakNpcId = 790067,
          Subtitle = "But the day they set was the same day as the contest. Chained by his pride, Mingluan insisted on fighting one last time to win the title, then leave with her.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6286"
        },
        [80210424] = {
          ContentTC = "但高手對決，又怎麼會幾招內分出勝負，他們鬥了三個日夜。等鳴鸞比試結束，前去赴約時，眼前所見只有江上數峰青山，不見人影。",
          DialogueId = 80210424,
          GUID = "C8CC62B0",
          NextDialogue = 80210425,
          SpeakNpcId = 790067,
          Subtitle = "But the fights between masters isn't decided quickly. They fought for three days and nights. When he finally went to meet her, only empty mountains looked back over the river.",
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC62B0"
        },
        [80210425] = {
          ContentTC = "應當是那位紅顏知己見他仍然是放不下名聲，感到失望而獨自離開。",
          DialogueId = 80210425,
          GUID = "C8CC62DA",
          NextDialogue = 80210426,
          SpeakNpcId = 790067,
          Subtitle = "She must have seen that he couldn't let go of his fame, and left alone.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC62DA"
        },
        [80210426] = {
          ContentTC = "鳴鸞最初不以為意，但是很快便思念成疾，察覺到這世界上有比所謂的「天下第一」更重要的事物。",
          DialogueId = 80210426,
          GUID = "C8CC6304",
          NextDialogue = 80210427,
          SpeakNpcId = 790067,
          Subtitle = "At first he didn't mind. But soon, longing became sickness. He realized something mattered more than being \"First in the Realm\".",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6304"
        },
        [80210427] = {
          ContentTC = "於是他也離開了華胥，尋覓至今，卻還是沒有尋到。",
          DialogueId = 80210427,
          GUID = "C8CC632E",
          NextDialogue = 80210428,
          SpeakNpcId = 790067,
          Subtitle = "So he too left Huaxu, searching for her even now. Still hasn't found her.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC632E"
        },
        [80210428] = {
          ContentTC = "所以這一次比武論劍，他不參加。",
          DialogueId = 80210428,
          GUID = "C8CC6358",
          NextDialogue = 80210429,
          SpeakNpcId = 790067,
          Subtitle = "So of course, he won't be coming.",
          TalkActionId = {
            [1] = "790067:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6358"
        },
        [80210429] = {
          Camera = "523.363281,229.195312,121.128906,0.000162,1.999995,-122.399033,42.362053,406.334045,false,Manual,2.8",
          ContentTC = "至於最後一位，被稱作庖俠，妙手調羹的本領是一絕，所製作的「若木無覓銜燭龍」更是舉世無雙。",
          DialogueId = 80210429,
          FinalCamera = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
          GUID = "C8CC6382",
          NextDialogue = 80210430,
          SpeakNpcId = 790067,
          Subtitle = "The last was called the Gourmet Knight — a master of the kitchen. His \"Untamable Loong Beyond Reach\" was a legend.",
          TalkActionId = {
            [1] = "790067:Talk03_Start"
          },
          ToFinalCameraBlendTime = 40,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6382"
        },
        [80210430] = {
          ContentTC = "但在他某次設宴招待客人時，卻被歹人在飯菜中下了毒，青花的瓷盤本來盛的是珍果佳餚，卻沾染了血。",
          DialogueId = 80210430,
          GUID = "C8CC63AC",
          NextDialogue = 80210431,
          SpeakNpcId = 790067,
          Subtitle = "But once, at a feast he prepared, someone poisoned the dishes. Blue-and-white porcelain that should've held delicacies... was stained with blood.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC63AC"
        },
        [80210431] = {
          ContentTC = "這毒雖然不是他下的，但畢竟飯菜都經過他手，於是也被大風九章認定為有罪。",
          DialogueId = 80210431,
          GUID = "C8CC63D6",
          NextDialogue = 80210432,
          SpeakNpcId = 790067,
          Subtitle = "Though it wasn't his doing, the food had passed through his hands. The Nine Chapters declared him guilty.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC63D6"
        },
        [80210432] = {
          ContentTC = "他的武藝，要應對應天尉倒也不難。但一旦反抗，那簡直如同是自認有罪，所以他就束手就擒，受到懲罰，跛了一足。",
          DialogueId = 80210432,
          GUID = "C8CC6400",
          NextDialogue = 80210433,
          SpeakNpcId = 790067,
          Subtitle = "He could've fought the Magistrates — but resisting would've been like admitting guilt. So he surrendered. They broke his leg, and his spirit.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6400"
        },
        [80210433] = {
          ContentTC = "等他重回自由身時，也是心灰意冷，不再以飄零人自居，專心磨練廚藝去了，炸油豆腐是一絕。",
          DialogueId = 80210433,
          GUID = "C8CC642A",
          NextDialogue = 80210434,
          SpeakNpcId = 790067,
          Subtitle = "When he was free again, he'd lost all heart. He left the Drifter life behind, and now he just cooks. Makes the best fried tofu you'll ever taste.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC642A"
        },
        [80210434] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "難道說前幾天你帶給我的油豆腐就是……",
          DialogueId = 80210434,
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC6454",
          NextDialogue = 80210435,
          SpeakNpcId = 790008,
          Subtitle = "Wait, the tofu you brought me the other day, was it...?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6454"
        },
        [80210435] = {
          Camera = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
          ContentTC = "不，不是，我什麼都沒說，你什麼都沒聽見。",
          DialogueId = 80210435,
          FacialId = {
            [1] = "790067:Nervous"
          },
          FinalCamera = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
          GUID = "C8CC647E",
          NextDialogue = 80210436,
          SpeakNpcId = 790067,
          Subtitle = "No, absolutely not. I didn't answer questions and you didn't ask.",
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC647E"
        },
        [80210436] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "噢……我懂了。",
          DialogueId = 80210436,
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC64A8",
          NextDialogue = 80210437,
          SpeakNpcId = 790008,
          Subtitle = "Oh... I see.",
          TalkActionId = {
            [1] = "790008:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC64A8"
        },
        [80210437] = {
          ContentTC = "不過這麼一來……豈不是只有你代表宴山亭師父來參加比武？",
          DialogueId = 80210437,
          GUID = "C8CC64D2",
          NextDialogue = 80210438,
          SpeakNpcId = 790008,
          Subtitle = "So then... that means only you are here for your master?",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC64D2"
        },
        [80210438] = {
          Camera = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
          ContentTC = "沒錯，這次比武論劍，只有我代表師父參加。",
          DialogueId = 80210438,
          FacialId = {
            [1] = "790067:None"
          },
          FinalCamera = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
          GUID = "C8CC64FC",
          NextDialogue = 80210439,
          SpeakNpcId = 790067,
          Subtitle = "Yes. It's just me this time, representing my master.",
          TalkActionId = {
            [1] = "790067:Talk03_End",
            [2] = "790067:AgreeHead"
          },
          ToFinalCameraBlendTime = 40,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC64FC"
        },
        [80210439] = {
          ContentTC = "這就是現在飄零人的現狀啊，曾幾何時他們聚嘯山林，沒有什麼特意需要遵從的法條，只需要遵從內心與手中劍。",
          DialogueId = 80210439,
          GUID = "C8CC6526",
          NextDialogue = 80210440,
          SpeakNpcId = 790067,
          Subtitle = "This is what's become of the Drifters. Once, we gathered freely — no code to follow but our hearts and our blades.",
          TalkActionId = {
            [1] = "790067:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6526"
        },
        [80210440] = {
          ContentTC = "刀光劍影里有著一個又一個快意恩仇的故事。",
          DialogueId = 80210440,
          GUID = "C8CC6550",
          NextDialogue = 80210441,
          SpeakNpcId = 790067,
          Subtitle = "Our stories were written in flashes of steel.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6550"
        },
        [80210441] = {
          ContentTC = "在大風九章之下，沒有所謂的路見不平拔刀相助，大家都畏懼觸發法條，被應天尉盯上。",
          DialogueId = 80210441,
          GUID = "C8CC657A",
          NextDialogue = 80210442,
          SpeakNpcId = 790067,
          Subtitle = "But under the Nine Chapters, no one draws a blade for justice anymore. Everyone fears breaking rules, drawing the eyes of the Magistrates.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC657A"
        },
        [80210442] = {
          ContentTC = "即便是號稱自由自在的飄零人，也無法免於受到大風九章的羈絆。",
          DialogueId = 80210442,
          GUID = "C8CC65A4",
          NextDialogue = 80210443,
          SpeakNpcId = 790067,
          Subtitle = "Even those who call themselves free can't escape the Nine Chapters' grasp.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC65A4"
        },
        [80210443] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "所以，你才會想要推翻大風九章？",
          DialogueId = 80210443,
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC65CE",
          NextDialogue = 80210444,
          SpeakNpcId = 790008,
          Subtitle = "Is that the reason you want to overthrow it?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC65CE"
        },
        [80210444] = {
          Camera = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
          ContentTC = "只能說是原因之一吧，還有其他的新仇舊恨。",
          DialogueId = 80210444,
          FinalCamera = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
          GUID = "C8CC65F8",
          NextDialogue = 80210445,
          SpeakNpcId = 790067,
          Subtitle = "It's one reason. There are others — old grudges, new wounds.",
          TalkActionId = {
            [1] = "790067:Talk01_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC65F8"
        },
        [80210445] = {
          ContentTC = "有時候我也在想，有大風九章在，至少大部分人能夠安居，去反對它是不是真的有意義。",
          DialogueId = 80210445,
          GUID = "C8CC6622",
          NextDialogue = 80210446,
          SpeakNpcId = 790067,
          Subtitle = "Sometimes I wonder, if it keeps peace for most, is fighting it really right?",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6622"
        },
        [80210446] = {
          ContentTC = "但這次為了準備論劍拜訪了諸位前輩，看他們也都過得不盡如人意，那麼在一片祥和之下，到底有多少不平之事，又有誰知道。",
          DialogueId = 80210446,
          GUID = "C8CC664C",
          NextDialogue = 80210447,
          SpeakNpcId = 790067,
          Subtitle = "But meeting those masters, seeing how they've ended up… I wonder how many unseen injustices lie beneath this \"peace\".",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC664C"
        },
        [80210447] = {
          ContentTC = "我作為飄零人，就不應該袖手旁觀。雖說江湖兒女日漸少，但也有句話說得好嘛，天下風雲出我輩。",
          DialogueId = 80210447,
          GUID = "C8CC6676",
          NextDialogue = 80210448,
          SpeakNpcId = 790067,
          Subtitle = "As a Drifter, I can't stand aside. Yes, our numbers thin — but just as it is said, new storms rise from our generation.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6676"
        },
        [80210448] = {
          ContentTC = "長劍在手，人在江湖，即便如孤鶩飄零，也能為天下之先，一覽他人未見之景，是好事。",
          DialogueId = 80210448,
          GUID = "C8CC66A0",
          NextDialogue = 80210449,
          SpeakNpcId = 790067,
          Subtitle = "A sword in hand, a heart in the world. Even a lone Drifter can lead the way, see further than others. That's not a bad fate.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC66A0"
        },
        [80210449] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "行應行之路，竟未竟之志。我想，我大概明白所謂的飄零人為什麼能延續至今了。",
          DialogueId = 80210449,
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC66CA",
          NextDialogue = 80210450,
          SpeakNpcId = 790008,
          Subtitle = "Walk the path you must; finish what others could not. I think I understand now why Drifters never truly fade away.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC66CA"
        },
        [80210450] = {
          ContentTC = "並且我也相信，此後比武論劍之人，肯定不會像今天那樣，只有你孤身一人的。",
          DialogueId = 80210450,
          GUID = "C8CC66F4",
          NextDialogue = 80210451,
          SpeakNpcId = 790008,
          Subtitle = "And I believe, next time, you won't be the only one here.",
          TalkActionId = {
            [1] = "790008:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC66F4"
        },
        [80210451] = {
          Camera = "795.160156,-371.187988,113.348633,0.000152,1.999995,146.999313,42.362053,398.766113,false,Manual,2.8",
          ContentTC = "哈哈哈哈，好，好，好，說得好。",
          DialogueId = 80210451,
          FacialId = {
            [1] = "790067:Smile01"
          },
          FinalCamera = "862.960938,-289.070312,112.585938,0.000152,1.999995,156.599838,42.362053,398.766113,false,Manual,2.8",
          GUID = "C8CC671E",
          NextDialogue = 80210452,
          SpeakNpcId = 790067,
          Subtitle = "Haha! Well said!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC671E"
        },
        [80210452] = {
          ContentTC = "不過嘛，我可沒有為沒有人論劍感到難過，不如說，這可是大好事——",
          DialogueId = 80210452,
          GUID = "C8CC6748",
          NextDialogue = 80210453,
          SpeakNpcId = 790067,
          Subtitle = "But don't think I'm sad about no one showing up. In fact — it's perfect!",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6748"
        },
        [80210453] = {
          Camera = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
          ContentTC = "我宣布，因為其他三位比武者的缺席，宴山亭的弟子刻舟，正式成為華胥第一飄零人。",
          DialogueId = 80210453,
          FinalCamera = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
          GUID = "C8CC6772",
          NextDialogue = 80210454,
          SpeakNpcId = 790067,
          Subtitle = "I now declare: due to the absence of the other three participants, I, Kezhou, disciple of Yan Shanting, is hereby number one among Huaxu's Drifters!",
          TalkActionId = {
            [1] = "790067:Confident_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6772"
        },
        [80210454] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "就這麼宣布了？",
          DialogueId = 80210454,
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC679C",
          NextDialogue = 80210455,
          SpeakNpcId = 790008,
          Subtitle = "Just like that?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC679C"
        },
        [80210455] = {
          Camera = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
          ContentTC = "那不然呢？我師父就讓我這麼做的。我記得清清楚楚，當時他和我說，如果上一屆的參加者們不想參加比武，那麼也不用強行勸說。",
          DialogueId = 80210455,
          FinalCamera = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
          GUID = "C8CC67C6",
          NextDialogue = 80210456,
          SpeakNpcId = 790067,
          Subtitle = "Why not? My master told me to. He said if the others didn't want to fight, don't force them.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC67C6"
        },
        [80210456] = {
          ContentTC = "畢竟，如果參加人數少了，那麼贏到最後的可能性也會跟著變大，說不定只要比試一場就能奪冠了。",
          DialogueId = 80210456,
          GUID = "C8CC67F0",
          NextDialogue = 80210457,
          SpeakNpcId = 790067,
          Subtitle = "After all, fewer fighters means a better chance to win. Maybe only one match to victory!",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC67F0"
        },
        [80210457] = {
          ContentTC = "師父還是太保守了，實際上一場都沒比試，這才叫真正的天下無敵！",
          DialogueId = 80210457,
          GUID = "C8CC681A",
          NextDialogue = 80210458,
          SpeakNpcId = 790067,
          Subtitle = "Though my master was too conservative. I didn't even have to fight one! Now that's what I call unrivaled!",
          TalkActionId = {
            [1] = "790067:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC681A"
        },
        [80210458] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "我還以為你會再低落一會兒。",
          DialogueId = 80210458,
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC6844",
          NextDialogue = 80210459,
          SpeakNpcId = 790008,
          Subtitle = "I thought you'd be more upset.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6844"
        },
        [80210459] = {
          Camera = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
          ContentTC = "黯然神傷刻舟求劍這種事情，不適合我，有其他人做就行了。",
          DialogueId = 80210459,
          FinalCamera = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
          GUID = "C8CC686E",
          NextDialogue = 80210460,
          SpeakNpcId = 790067,
          Subtitle = "Moping and sighing? Not for me. Let others play the mournful hero.",
          TalkActionId = {
            [1] = "790067:DisagreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC686E"
        },
        [80210460] = {
          ContentTC = "我要做的，是斬落師父，師兄，以及諸位前輩們為之鬱結的大風九章。",
          DialogueId = 80210460,
          GUID = "C8CC6898",
          NextDialogue = 80210461,
          SpeakNpcId = 790067,
          Subtitle = "What I'll do, is cut down the Nine Chapters — the thing that weighed on my master, my seniors, the Drifters... all of them!",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6898"
        },
        [80210461] = {
          ContentTC = "等到這件事告一段落後，我大概也能和那些飄零人小說中描寫的一樣，退隱山林了。",
          DialogueId = 80210461,
          GUID = "C8CC68C2",
          NextDialogue = 80210462,
          SpeakNpcId = 790067,
          Subtitle = "When it's done, maybe I'll retreat to the mountains like in those old tales.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC68C2"
        },
        [80210462] = {
          Camera = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          ContentTC = "依你的性格，我感覺你閒不下來。",
          DialogueId = 80210462,
          FinalCamera = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
          GUID = "C8CC68EC",
          NextDialogue = 80210463,
          SpeakNpcId = 790008,
          Subtitle = "With your personality? I doubt you'll stay retired.",
          TalkActionId = {
            [1] = "790008:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC68EC"
        }
      }
    end
  },
  {
    MinKey = 80210463,
    MaxKey = 80220436,
    Loader = function()
      return {
        [80210463] = {
          Camera = "377.449219,42.706543,179.00293,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
          ContentTC = "確實，那就等那時再說吧。",
          DialogueId = 80210463,
          FinalCamera = "377.128906,35.079102,177.938477,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
          GUID = "C8CC6916",
          NextDialogue = 80210464,
          SpeakNpcId = 790067,
          Subtitle = "True. I'll figure it out then.",
          TalkActionId = {
            [1] = "790067:AgreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6916"
        },
        [80210464] = {
          Camera = "855.464844,-598.185059,132.694336,0.0,0.0,136.606979,26.65424,695.636841,false,Manual,2.8",
          ContentTC = "今日拔得頭籌成為第一飄零人，應該開心過活，不去管那以後的事。來吧，朋友，且歌且醉，且醉且歌！",
          DialogueId = 80210464,
          FinalCamera = "1130.59375,-914.811523,132.694336,0.0,0.0,133.406891,26.65424,275.423279,false,Manual,2.8",
          GUID = "C8CC6940",
          NextDialogue = 80210465,
          SpeakNpcId = 790067,
          Subtitle = "Today, I've won. I should live joyfully — leave tomorrow for tomorrow. Come, friend! Let's s drink! And sing! And sing 'til we drink again!",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6940"
        },
        [80210465] = {
          ContentTC = "那些曾經鋒芒畢露的，生死相許的，快意恩仇的，都早已成為風中一縷輕塵。",
          DialogueId = 80210465,
          GUID = "C8CC696A",
          NextDialogue = 80210466,
          Subtitle = "All that once was — the gleaming blades, vows sworn in life and death, righteous passions — had long faded to dust on the wind.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC696A"
        },
        [80210466] = {
          ContentTC = "最終都只剩下滿頭霜雪與輕嘆一聲，少年子弟江湖老。",
          DialogueId = 80210466,
          GUID = "C8CC6994",
          Subtitle = "All that remained was hair iced by time, and a soft sigh: so youth is lost to the world's wear.",
          VoiceName = "voice/$Locale$/inv/Kezhou/004/C8CC6994"
        },
        [80210467] = {
          DialogueId = 80210467,
          Duration = 1,
          GUID = "C8CC6995",
          IsBlack = 1
        },
        [80220101] = {
          Content = "……",
          DialogueId = 80220101,
          GUID = "C8D29652",
          NextDialogue = 80220102,
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29652"
        },
        [80220102] = {
          ContentTC = "師兄？",
          DialogueId = 80220102,
          GUID = "C8D2967C",
          NextDialogue = 80220103,
          Subtitle = "Shixiong?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2967C"
        },
        [80220103] = {
          ContentTC = "是不夏啊。",
          DialogueId = 80220103,
          GUID = "C8D296A6",
          NextDialogue = 80220104,
          Subtitle = "Buxia.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D296A6"
        },
        [80220104] = {
          ContentTC = "老遠就聽到笛聲了，果然是你。",
          DialogueId = 80220104,
          GUID = "C8D296D0",
          NextDialogue = 80220105,
          Subtitle = "I heard the flute from far away. Thought it might be you.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D296D0"
        },
        [80220105] = {
          ContentTC = "你找我有事？",
          DialogueId = 80220105,
          GUID = "C8D296FA",
          NextDialogue = 80220106,
          Subtitle = "Do you need something?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D296FA"
        },
        [80220106] = {
          ContentTC = "其實是……師兄，幫忙看看它吧。",
          DialogueId = 80220106,
          GUID = "C8D29724",
          NextDialogue = 80220107,
          Subtitle = "Actually... Shixiong, could you take a look at this little one?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29724"
        },
        [80220107] = {
          ContentTC = "我和刻舟師兄在山外山外面發現了這隻小狐狸，它被野獸咬傷了。",
          DialogueId = 80220107,
          GUID = "C8D2974E",
          NextDialogue = 80220108,
          Subtitle = "Kezhou and I found it just outside the Outer Peaks. It was bitten by something out there.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2974E"
        },
        [80220108] = {
          ContentTC = "刻舟師兄粗枝大葉，完全不知道怎麼處理它身上的傷，就只能來找師兄你了。放著不管的話，它很快便會死掉的。",
          DialogueId = 80220108,
          GUID = "C8D29778",
          NextDialogue = 80220109,
          Subtitle = "Kezhou's hopeless at this sort of thing, so I came to you. If we leave it, it won't last long.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29778"
        },
        [80220109] = {
          ContentTC = "……",
          DialogueId = 80220109,
          GUID = "C8D297A2",
          NextDialogue = 80220110,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D297A2"
        },
        [80220110] = {
          ContentTC = "師兄？",
          DialogueId = 80220110,
          GUID = "C8D297CC",
          NextDialogue = 80220111,
          Subtitle = "What is it, Shixiong?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D297CC"
        },
        [80220111] = {
          ContentTC = "沒什麼。讓我來看看吧。",
          DialogueId = 80220111,
          GUID = "C8D297F6",
          NextDialogue = 80220112,
          Subtitle = "Nothing. Let me see.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D297F6"
        },
        [80220112] = {
          ContentTC = "我們發現它的時候，它就那麼蜷在巖石的縫隙之間，死死地盯著外面。我們在附近找到了幾隻斷了氣的大狐狸，順著它們的血跡才找到了這個小傢伙。",
          DialogueId = 80220112,
          GUID = "C8D29820",
          NextDialogue = 80220113,
          Subtitle = "When we found it, it was curled up in a crack between the rocks, peering out helplessly. There were adult foxes dead nearby. We followed the blood trail and found this little one.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29820"
        },
        [80220113] = {
          ContentTC = "刻舟師兄把它抱起來的時候，它沒有叫，也沒有害怕。或者說……它太小了，小到甚至不明白髮生了什麼，只能這麼顫抖著被帶來這裡。",
          DialogueId = 80220113,
          GUID = "C8D2984A",
          NextDialogue = 80220114,
          Subtitle = "When Kezhou picked it up, it didn't cry out or struggle. Or rather... it's so young it doesn't even understand. It just trembled the whole way here.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2984A"
        },
        [80220114] = {
          ContentTC = "……傷口處理好了。",
          DialogueId = 80220114,
          GUID = "C8D29874",
          NextDialogue = 80220115,
          Subtitle = "...All right. That should hold.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29874"
        },
        [80220115] = {
          ContentTC = "讓刻舟去砍些木材回來，我給它搭個窩避雨。",
          DialogueId = 80220115,
          GUID = "C8D2989E",
          NextDialogue = 80220116,
          Subtitle = "Get Kezhou to cut some wood. I'll put together a little shelter to keep the rain off.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2989E"
        },
        [80220116] = {
          ContentTC = "師兄你的意思是……我們可以養它嗎？",
          DialogueId = 80220116,
          GUID = "C8D298C8",
          NextDialogue = 80220117,
          Subtitle = "Wait— do you mean... we can keep it?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D298C8"
        },
        [80220117] = {
          ContentTC = "太好了，我這就去！嗯嗯，還得給它取個名字……就叫你「小橙子」吧！小狐狸！",
          DialogueId = 80220117,
          GUID = "C8D298F2",
          NextDialogue = 80220118,
          Subtitle = "That's great! I'll go tell him right now! Oh— and it needs a name. Hmm... let's call you Little Tangerine!",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D298F2"
        },
        [80220118] = {
          ContentTC = "一年後",
          DialogueId = 80220118,
          GUID = "C8D2991C",
          NextDialogue = 80220119,
          Subtitle = "One year later",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2991C"
        },
        [80220119] = {
          ContentTC = "不夏？",
          DialogueId = 80220119,
          GUID = "C8D29946",
          NextDialogue = 80220120,
          Subtitle = "Buxia?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29946"
        },
        [80220120] = {
          ContentTC = "……",
          DialogueId = 80220120,
          GUID = "C8D29970",
          NextDialogue = 80220121,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29970"
        },
        [80220121] = {
          ContentTC = "不夏。",
          DialogueId = 80220121,
          GUID = "C8D2999A",
          NextDialogue = 80220122,
          Subtitle = "Buxia.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2999A"
        },
        [80220122] = {
          ContentTC = "師兄！你回來啦？",
          DialogueId = 80220122,
          GUID = "C8D299C4",
          NextDialogue = 80220123,
          Subtitle = "Shixiong! You're back already?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D299C4"
        },
        [80220123] = {
          ContentTC = "你的耳朵？",
          DialogueId = 80220123,
          GUID = "C8D299EE",
          NextDialogue = 80220124,
          Subtitle = "Your hearing...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D299EE"
        },
        [80220124] = {
          ContentTC = "沒事沒事，只是有一隻耳朵偶爾聽不清而已，另一隻好著呢！……嗯，一定是耳朵告訴我，我又該睡大覺了！",
          DialogueId = 80220124,
          GUID = "C8D29A18",
          NextDialogue = 80220125,
          Subtitle = "I'm fine — one ear just doesn't behave sometimes. The other's fine! ...Guess that's my body telling me it's time to sleep~",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A18"
        },
        [80220125] = {
          ContentTC = "……不要怠惰。若不是你與刻舟偷懶被發現，師父也不會罰你們在這裡抄書三天，磨礪心性。你與刻舟天賦有別，若繼續和他一般，遲早會被拖累。",
          DialogueId = 80220125,
          GUID = "C8D29A42",
          NextDialogue = 80220126,
          Subtitle = "...You shouldn't be wasting time. If you and Kezhou hadn't been caught slacking, Shifu wouldn't have you copying texts for three days. You're not like him. He can afford that pace. You can't. Keep messing about with him and you'll only fall behind.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A42"
        },
        [80220126] = {
          ContentTC = "至於你的耳朵，我想還是得早日去皓京尋得藥師來瞧瞧。",
          DialogueId = 80220126,
          GUID = "C8D29A6C",
          NextDialogue = 80220127,
          Subtitle = "And about your hearing — we should go to Haojing. Let a physician have a look.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A6C"
        },
        [80220127] = {
          ContentTC = "知道啦知道啦——師兄還那麼年輕，就像師父那個老頭子一樣嘮嘮叨叨的。",
          DialogueId = 80220127,
          GUID = "C8D29A96",
          NextDialogue = 80220128,
          Subtitle = "All right, all right — honestly, Shixiong, you're starting to sound like Shifu, always nagging. Sometimes I forget you're still young.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29A96"
        },
        [80220128] = {
          ContentTC = "對了對了，小橙子怎麼樣了？昨天下了那麼大的雨，我有點擔心……",
          DialogueId = 80220128,
          GUID = "C8D29AC0",
          NextDialogue = 80220129,
          Subtitle = "Oh— right! How's Little Tangerine? That storm last night was awful... I couldn't stop worrying.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29AC0"
        },
        [80220129] = {
          ContentTC = "今天我去後山看它，此前給它造的小窩被山石砸壞了。它蜷縮在那些折斷的木板下面，任憑雨水滲過縫隙流淌在它身上。",
          DialogueId = 80220129,
          GUID = "C8D29AEA",
          NextDialogue = 80220130,
          Subtitle = "I went to the rear hills today to check on it. The shelter I built was crushed by a falling rock. It was huddled under the broken boards, soaked through.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29AEA"
        },
        [80220130] = {
          ContentTC = "我把窩修補好了，又放了些乾草。但它還是老樣子，蜷在那兒發抖。",
          DialogueId = 80220130,
          GUID = "C8D29B14",
          NextDialogue = 80220131,
          Subtitle = "I fixed the shelter and laid down some dry grass. Still, it just huddled there, shaking.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B14"
        },
        [80220131] = {
          ContentTC = "唉……這叫我怎麼放心得下呀。",
          DialogueId = 80220131,
          GUID = "C8D29B3E",
          NextDialogue = 80220132,
          Subtitle = "Aw... how am I not supposed to worry?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B3E"
        },
        [80220132] = {
          ContentTC = "你們在幹什麼？不夏，你的書抄完了？",
          DialogueId = 80220132,
          GUID = "C8D29B68",
          NextDialogue = 80220133,
          Subtitle = "What are you two doing? Buxia — have you finished copying out those texts?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B68"
        },
        [80220133] = {
          ContentTC = "啊，師父，我……我們只是在商量武學！今天早上煜明師兄使出了一招槍，特別好看前所未見，我看了就也想學一學，所以正在和他討教……沒幹什麼，嘿嘿。",
          DialogueId = 80220133,
          GUID = "C8D29B92",
          NextDialogue = 80220134,
          Subtitle = "Ah... Shifu! W—We were talking about training! This morning Shixiong showed me a spear technique. I'd never seen anything like it, so I asked him for a few pointers. That's all! Really! Hehe...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29B92"
        },
        [80220134] = {
          ContentTC = "是的。",
          DialogueId = 80220134,
          GUID = "C8D29BBC",
          NextDialogue = 80220135,
          Subtitle = "...Yes.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29BBC"
        },
        [80220135] = {
          ContentTC = "唉，你們倆，一個說謊的時候話會變多，一個說謊的時候話會變少。當為師是你們倆養的那小狐狸一樣不通人言嗎？",
          DialogueId = 80220135,
          GUID = "C8D29BE6",
          NextDialogue = 80220136,
          Subtitle = "Hmph. One of you talks more when she lies; the other talks less. Do you really think I'm as clueless as that little fox you've been keeping?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29BE6"
        },
        [80220136] = {
          ContentTC = "原來……師父都知道了呀。",
          DialogueId = 80220136,
          GUID = "C8D29C10",
          NextDialogue = 80220137,
          Subtitle = "Ah... so you knew all along, Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C10"
        },
        [80220137] = {
          ContentTC = "為師只是老了不是傻了！一年前你們把這小東西撿來的時候我就知道了，畢竟它也時不時到處撒歡。",
          DialogueId = 80220137,
          GUID = "C8D29C3A",
          NextDialogue = 80220138,
          Subtitle = "I may be old, but I'm not blind. I knew the minute you brought it back a year ago. It's been darting about ever since.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C3A"
        },
        [80220138] = {
          ContentTC = "這幾天沒有見它，特意尋過來看一看，發現你們倆在這邊愁眉苦臉，想問問怎麼回事，沒想到還和我不老實。",
          DialogueId = 80220138,
          GUID = "C8D29C64",
          NextDialogue = 80220139,
          Subtitle = "I hadn't seen it for days, so I came to have a look. Then I find the two of you here, looking all troubled. Thought I'd ask what was wrong. Didn't expect you to try and pull the wool over my eyes.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C64"
        },
        [80220139] = {
          ContentTC = "哎呀，這不是因為師父一直仙風道骨，是武林耆宿，想著你可能更喜歡什麼鶴呀鹿呀之類的動物，不喜歡狐狸，所以不敢告訴你嘛。",
          DialogueId = 80220139,
          GUID = "C8D29C8E",
          NextDialogue = 80220140,
          Subtitle = "Well, it's just... you always seem so serene, so otherworldly, Shifu! I figured a venerable elder like you would prefer cranes or deer, not a fox. So I didn't dare bring it up...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29C8E"
        },
        [80220140] = {
          ContentTC = "還在饒舌，又是跟刻舟學的吧。為師什麼時候講究那些了。說吧，遇到什麼問題了？",
          DialogueId = 80220140,
          GUID = "C8D29CB8",
          NextDialogue = 80220141,
          Subtitle = "Still running your mouth. You picked that up from Kezhou too, didn't you? Since when have I ever been so particular? Go on — what's the problem?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29CB8"
        },
        [80220141] = {
          ContentTC = "（不夏和煜明把「小橙子」的事告訴了宴山亭。）",
          DialogueId = 80220141,
          GUID = "C8D29CE2",
          NextDialogue = 80220142,
          Subtitle = "(Buxia and Yuming explain what happened to Little Tangerine.)",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29CE2"
        },
        [80220142] = {
          ContentTC = "哈哈，我當是什麼事。要是我，我就把它拎起來，拎到它來的地方去。山外山不是它的家，外面的山林才是。",
          DialogueId = 80220142,
          GUID = "C8D29D0C",
          NextDialogue = 80220143,
          Subtitle = "Ha! I thought it was something serious. If it were me, I'd scoop it up and take it straight back to where it came from. The Outer Peaks isn't its home. It belongs out in the wild.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D0C"
        },
        [80220143] = {
          ContentTC = "那……那怎麼行！它餓的時候誰來餵食，冷的時候誰來給它往窩裡多塞點棉絮？",
          DialogueId = 80220143,
          GUID = "C8D29D36",
          NextDialogue = 80220144,
          Subtitle = "Th—That won't do! No one's going to feed it out there! And when it gets cold, who's going to add more bedding to its den?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D36"
        },
        [80220144] = {
          ContentTC = "你看，就是因為你總做這些，它才一直長不大的。",
          DialogueId = 80220144,
          GUID = "C8D29D60",
          NextDialogue = 80220145,
          Subtitle = "That's exactly the problem. You keep doing everything for it, so it never learns to fend for itself.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D60"
        },
        [80220145] = {
          ContentTC = "你們給它搭了避雨的窩，卻沒有教會它如何度過寒冬。給了它果腹之物，卻沒有教會它如何捕獵。",
          DialogueId = 80220145,
          GUID = "C8D29D8A",
          NextDialogue = 80220146,
          Subtitle = "You built it a shelter to keep the rain off, but you never taught it how to make it through winter. You fed it, but you never taught it how to hunt.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29D8A"
        },
        [80220146] = {
          ContentTC = "它餓了冷了都等著你們照顧，要如何自己謀生？要是哪天沒我的傻徒兒盯著，一場大雨就能要了它的小命啦。",
          DialogueId = 80220146,
          GUID = "C8D29DB4",
          NextDialogue = 80220147,
          Subtitle = "Now when it's hungry or cold, it just waits for you. How's it supposed to survive on its own? If one day my silly disciples slip up and fail to watch over it, one night of heavy rain would be enough to finish it.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29DB4"
        },
        [80220147] = {
          ContentTC = "那、那師父的意思是……",
          DialogueId = 80220147,
          GUID = "C8D29DDE",
          NextDialogue = 80220148,
          Subtitle = "S—So... you're saying...?",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29DDE"
        },
        [80220148] = {
          ContentTC = "縱是你再不舍，它終究還是要回歸山林的。它是頭小野獸，一味地庇護只會讓它失去生存的能力。",
          DialogueId = 80220148,
          GUID = "C8D29E08",
          NextDialogue = 80220149,
          Subtitle = "No matter how reluctant you are, it has to go back to the wild. That's where it belongs. Coddle it, and you'll only rob it of the chance to learn how to live.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E08"
        },
        [80220149] = {
          ContentTC = "……我明白了。讓我和兩位師兄商量商量……",
          DialogueId = 80220149,
          GUID = "C8D29E32",
          NextDialogue = 80220150,
          Subtitle = "...I understand. Let me talk it over with my two Shixiong first...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E32"
        },
        [80220150] = {
          ContentTC = "…………",
          DialogueId = 80220150,
          GUID = "C8D29E5C",
          NextDialogue = 80220151,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E5C"
        },
        [80220151] = {
          ContentTC = "煜明，你有心事。",
          DialogueId = 80220151,
          GUID = "C8D29E86",
          NextDialogue = 80220152,
          Subtitle = "Yuming. Something's on your mind.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29E86"
        },
        [80220152] = {
          ContentTC = "沒有。",
          DialogueId = 80220152,
          GUID = "C8D29EB0",
          NextDialogue = 80220153,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29EB0"
        },
        [80220153] = {
          ContentTC = "就兩個字？又在扯謊。",
          DialogueId = 80220153,
          GUID = "C8D29EDA",
          NextDialogue = 80220154,
          Subtitle = "Only one word this time? That means you're lying again.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29EDA"
        },
        [80220154] = {
          ContentTC = "……徒兒愚鈍。",
          DialogueId = 80220154,
          GUID = "C8D29F04",
          NextDialogue = 80220155,
          Subtitle = "...Sorry, Shifu. I was foolish.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F04"
        },
        [80220155] = {
          ContentTC = "也許那日我們收養小橙子並非明智之舉，但如今錯已鑄成。",
          DialogueId = 80220155,
          GUID = "C8D29F2E",
          NextDialogue = 80220156,
          Subtitle = "Maybe we shouldn't have taken Little Tangerine in that day. But we did.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F2E"
        },
        [80220156] = {
          ContentTC = "如您所言，它和我們一起生活許久，已經失去了獨自生存的能力。此時若選擇放歸野外，只怕它……",
          DialogueId = 80220156,
          GUID = "C8D29F58",
          NextDialogue = 80220157,
          Subtitle = "You're right — it's been with us too long. It wouldn't last on its own. If we release it back into the wild now... I'm afraid it will—",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F58"
        },
        [80220157] = {
          ContentTC = "可能會凍死餓死。你說的這些，我又如何不知。但為師只有一句話，做就別怕，怕就別做。",
          DialogueId = 80220157,
          GUID = "C8D29F82",
          NextDialogue = 80220158,
          Subtitle = "Freeze to death. Or starve to death. Of course I know that. But listen: if you choose to do it, don't flinch. If you can't bear it, don't even start.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29F82"
        },
        [80220158] = {
          ContentTC = "任何選擇都伴隨著所失和所得。就像咱們飄零人，丟下了大風九章，便是選擇自己庇護自己。這無關對錯，只關抉擇。",
          DialogueId = 80220158,
          GUID = "C8D29FAC",
          NextDialogue = 80220159,
          Subtitle = "With every choice, you gain something — and you lose something. Like us Drifters: we left the protection of the Nine Chapters and chose to rely on ourselves. It isn't about right or wrong. It's simply a choice.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29FAC"
        },
        [80220159] = {
          ContentTC = "為師唯一要的，便是你在做出抉擇之前細細思量，莫要讓自己後悔才是。",
          DialogueId = 80220159,
          GUID = "C8D29FD6",
          NextDialogue = 80220160,
          Subtitle = "All I want is for you to think before you choose. Live without regret.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D29FD6"
        },
        [80220160] = {
          ContentTC = "謹遵教誨。",
          DialogueId = 80220160,
          GUID = "C8D2A000",
          Subtitle = "Understood, Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/001/C8D2A000"
        },
        [80220201] = {
          ContentTC = "……",
          DialogueId = 80220201,
          GUID = "C8D2A6BA",
          NextDialogue = 80220202,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A6BA"
        },
        [80220202] = {
          ContentTC = "這是什麼？不夏她……變成了妖物？！",
          DialogueId = 80220202,
          GUID = "C8D2A6E4",
          NextDialogue = 80220203,
          Subtitle = "Wh—What is that!? That's... Buxia!? She's turned into a monster!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A6E4"
        },
        [80220203] = {
          ContentTC = "……不要……別過來，我不想死！",
          DialogueId = 80220203,
          GUID = "C8D2A70E",
          NextDialogue = 80220204,
          Subtitle = "N—No... stay back! I don't want to die!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A70E"
        },
        [80220204] = {
          ContentTC = "莫非這便是……神君的懲罰……因為我們背棄了祂的恩澤？！",
          DialogueId = 80220204,
          GUID = "C8D2A738",
          NextDialogue = 80220205,
          Subtitle = "Could this be... Lord Argent's punishment? For betraying their grace?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A738"
        },
        [80220205] = {
          ContentTC = "爹爹、爹爹！嗚嗚……求你醒醒，求你說句話啊……",
          DialogueId = 80220205,
          GUID = "C8D2A762",
          NextDialogue = 80220206,
          Subtitle = "Dad... Dad! ...Please... wake up! Say something... Dad...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A762"
        },
        [80220206] = {
          ContentTC = "師兄……救我……我，不想……",
          DialogueId = 80220206,
          GUID = "C8D2A78C",
          NextDialogue = 80220207,
          Subtitle = "Shixiong... help... I don't want to...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A78C"
        },
        [80220207] = {
          ContentTC = "…………",
          DialogueId = 80220207,
          GUID = "C8D2A7B6",
          NextDialogue = 80220208,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A7B6"
        },
        [80220208] = {
          ContentTC = "是你讓我看到這些的嗎……太皓？",
          DialogueId = 80220208,
          GUID = "C8D2A7E0",
          NextDialogue = 80220209,
          Subtitle = "Did you show me all this... Taihao?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A7E0"
        },
        [80220209] = {
          ContentTC = "非吾所為。吾無意窺伺凡人心神。",
          DialogueId = 80220209,
          GUID = "C8D2A80A",
          NextDialogue = 80220210,
          Subtitle = "Not I. I have no desire to pry into mortal minds.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A80A"
        },
        [80220210] = {
          ContentTC = "你為什麼會出現在我心中？我非但是一介凡人，還是一介飄零人。",
          DialogueId = 80220210,
          GUID = "C8D2A834",
          NextDialogue = 80220211,
          Subtitle = "Then why are you here? I'm only mortal. And I'm a Drifter — one who turned away from you.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A834"
        },
        [80220211] = {
          ContentTC = "汝心懷渴盼，欲吾解其惑。吾觀汝非池中物，故應此願。",
          DialogueId = 80220211,
          GUID = "C8D2A85E",
          NextDialogue = 80220212,
          Subtitle = "Your heart called, and I answered. You are not one meant for confinement.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A85E"
        },
        [80220212] = {
          ContentTC = "……原來我內心深處，竟真的期盼著你的回應。",
          DialogueId = 80220212,
          GUID = "C8D2A888",
          NextDialogue = 80220213,
          Subtitle = "...I didn't know my heart had reached for you.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A888"
        },
        [80220213] = {
          ContentTC = "汝眼前種種，乃舊魘縛身，不得解脫。",
          DialogueId = 80220213,
          GUID = "C8D2A8B2",
          NextDialogue = 80220214,
          Subtitle = "What you beheld was an old nightmare. It yet binds you.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A8B2"
        },
        [80220214] = {
          ContentTC = "……我知道。",
          DialogueId = 80220214,
          GUID = "C8D2A8DC",
          NextDialogue = 80220215,
          Subtitle = "...I know.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A8DC"
        },
        [80220215] = {
          ContentTC = "此其墓乎？",
          DialogueId = 80220215,
          GUID = "C8D2A906",
          NextDialogue = 80220216,
          Subtitle = "Is this the place of her final rest?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A906"
        },
        [80220216] = {
          ContentTC = "她……變成了那樣，我甚至無法撿回她的遺骨。我只能尋得她的一些舊衣物，葬在這裡。",
          DialogueId = 80220216,
          GUID = "C8D2A930",
          NextDialogue = 80220217,
          Subtitle = "She... changed into something else. I couldn't even recover her body. All I had left were a few of her old clothes.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A930"
        },
        [80220217] = {
          ContentTC = "之所以選擇這裡，而非山外山……",
          DialogueId = 80220217,
          GUID = "C8D2A95A",
          NextDialogue = 80220218,
          Subtitle = "And I buried them here, not at the Outer Peaks...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A95A"
        },
        [80220218] = {
          ContentTC = "是因為她的最後一句話是，「如果當時我選擇了大風九章，那麼結果會不會不一樣。」",
          DialogueId = 80220218,
          GUID = "C8D2A984",
          NextDialogue = 80220219,
          Subtitle = "...because of her last words: \"If I hadn't turned my back on the Nine Chapters of Dafeng... would it have ended differently?\"",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A984"
        },
        [80220219] = {
          ContentTC = "祖師扶風教誨過，醫者對一切病患都應一視同仁，縱是飄零人也一樣。但凡有一線生機，我又怎會不救她！",
          DialogueId = 80220219,
          GUID = "C8D2A9AE",
          NextDialogue = 80220220,
          Subtitle = "Founding Master Fufeng taught us this: a physician makes no distinction among the sick — not even Drifters. So long as there's a shred of hope, how could I refuse to treat her?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A9AE"
        },
        [80220220] = {
          ContentTC = "但那是穢蝕，是絕症，一旦開始發作，便再無半分轉圜餘地！她快要變成妖物了，你們還是趁這個機會趕緊逃命吧！",
          DialogueId = 80220220,
          GUID = "C8D2A9D8",
          NextDialogue = 80220221,
          Subtitle = "But it was Deterioration... an incurable affliction! Once it takes hold, there's no turning it back. She's about to become something inhuman. Go — while you still can. Run for your lives!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2A9D8"
        },
        [80220221] = {
          ContentTC = "唉，若非你們飄零人執意脫離大風九章庇佑，又何至於此！",
          DialogueId = 80220221,
          GUID = "C8D2AA02",
          NextDialogue = 80220222,
          Subtitle = "... If you Drifters hadn't been so set on turning your backs on the Nine Chapters' protection, it wouldn't have come to this...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA02"
        },
        [80220222] = {
          ContentTC = "為師唯一要的，便是你在做出抉擇之前細細思量，莫要讓自己後悔才是。",
          DialogueId = 80220222,
          GUID = "C8D2AA2C",
          NextDialogue = 80220223,
          Subtitle = "All I want is for you to think before you choose. Live without regret.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA2C"
        },
        [80220223] = {
          ContentTC = "……選擇。",
          DialogueId = 80220223,
          GUID = "C8D2AA56",
          NextDialogue = 80220224,
          Subtitle = "...Choice.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA56"
        },
        [80220224] = {
          ContentTC = "太皓，如果我們選擇了大風九章，那麼結果會不會不一樣？",
          DialogueId = 80220224,
          GUID = "C8D2AA80",
          NextDialogue = 80220225,
          Subtitle = "Taihao... if we had chosen the Nine Chapters of Dafeng, would things have turned out differently?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AA80"
        },
        [80220225] = {
          ContentTC = "汝等飄零人渴求無拘，卻不知鳶無線而墜，川無堤不海。",
          DialogueId = 80220225,
          GUID = "C8D2AAAA",
          NextDialogue = 80220226,
          Subtitle = "You Drifters crave freedom, yet you forget this: a kite without its line will fall, and a river without its banks will flood.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AAAA"
        },
        [80220226] = {
          ContentTC = "往事已矣，來日可期。迷途知返，猶未晚也。",
          DialogueId = 80220226,
          GUID = "C8D2AAD4",
          NextDialogue = 80220227,
          Subtitle = "What is past cannot be changed. What lies ahead is yet unwritten. To turn back from the wrong road is not too late.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AAD4"
        },
        [80220227] = {
          ContentTC = "言盡於此，汝其慎思。",
          DialogueId = 80220227,
          GUID = "C8D2AAFE",
          NextDialogue = 80220228,
          Subtitle = "I have spoken. Consider well.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AAFE"
        },
        [80220228] = {
          ContentTC = "太皓的幻影消失在了天際。",
          DialogueId = 80220228,
          GUID = "C8D2AB28",
          NextDialogue = 80220229,
          Subtitle = "Taihao's apparition fades into the heavens.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AB28"
        },
        [80220229] = {
          ContentTC = "嗚……",
          DialogueId = 80220229,
          GUID = "C8D2AB52",
          NextDialogue = 80220230,
          Subtitle = "Yip...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AB52"
        },
        [80220230] = {
          ContentTC = "……你還活著。原來那日，你是逃出了山外山嗎……",
          DialogueId = 80220230,
          GUID = "C8D2AB7C",
          NextDialogue = 80220231,
          Subtitle = "...Tangerine? You're still alive. So you made it out of the Outer Peaks that day...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AB7C"
        },
        [80220231] = {
          ContentTC = "嗚……嗚嗚……",
          DialogueId = 80220231,
          GUID = "C8D2ABA6",
          NextDialogue = 80220232,
          Subtitle = "Yip... yip...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ABA6"
        },
        [80220232] = {
          ContentTC = "你在哭嗎？",
          DialogueId = 80220232,
          GUID = "C8D2ABD0",
          NextDialogue = 80220233,
          Subtitle = "Are you... crying?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ABD0"
        },
        [80220233] = {
          ContentTC = "是在哭她，哭師父，哭那些無辜的死難者——還是哭竟然心生叛意的我？",
          DialogueId = 80220233,
          GUID = "C8D2ABFA",
          NextDialogue = 80220234,
          Subtitle = "Is it for Buxia? For our Shifu? For the innocents who died? Or is it for me... because I started to waver?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ABFA"
        },
        [80220234] = {
          ContentTC = "嗚嗚……",
          DialogueId = 80220234,
          GUID = "C8D2AC24",
          NextDialogue = 80220235,
          Subtitle = "Yip...",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AC24"
        },
        [80220235] = {
          ContentTC = "你是打算讓我帶你回山外山嗎？",
          DialogueId = 80220235,
          GUID = "C8D2AC4E",
          NextDialogue = 80220236,
          Subtitle = "Do you want me to take you back to the Outer Peaks?",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AC4E"
        },
        [80220236] = {
          ContentTC = "嗚嗚！",
          DialogueId = 80220236,
          GUID = "C8D2AC78",
          NextDialogue = 80220237,
          Subtitle = "Yip!",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2AC78"
        },
        [80220237] = {
          ContentTC = "抱歉，我已經回不去了。",
          DialogueId = 80220237,
          GUID = "C8D2ACA2",
          NextDialogue = 80220238,
          Subtitle = "I'm sorry. I can't go back.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ACA2"
        },
        [80220238] = {
          ContentTC = "（不過……這隻已經被馴服了的小野獸，如果不回山外山的話，恐怕是活不下去的。）",
          DialogueId = 80220238,
          GUID = "C8D2ACCC",
          NextDialogue = 80220239,
          Subtitle = "(It's grown used to humans sheltering it. Away from the Outer Peaks... it wouldn't last long.)",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ACCC"
        },
        [80220239] = {
          ContentTC = "山外山的方向在那邊。接下來的路，便由你自己選擇吧。",
          DialogueId = 80220239,
          GUID = "C8D2ACF6",
          Subtitle = "The Outer Peaks are that way. Whether you go back or not... that's your choice.",
          VoiceName = "voice/$Locale$/inv/Yuming/002/C8D2ACF6"
        },
        [80220301] = {
          ContentTC = "……哈、哈……",
          DialogueId = 80220301,
          GUID = "C8D2B722",
          NextDialogue = 80220302,
          Subtitle = "...Huff... huff...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B722"
        },
        [80220302] = {
          ContentTC = "在山外山的時候不聲不響，當狗倒是挺有本事。",
          DialogueId = 80220302,
          GUID = "C8D2B74C",
          NextDialogue = 80220303,
          Subtitle = "You were quiet back at the Outer Peaks. Who knew you'd be so good at wagging your tail for them.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B74C"
        },
        [80220303] = {
          ContentTC = "……束手就擒吧。",
          DialogueId = 80220303,
          GUID = "C8D2B776",
          NextDialogue = 80220304,
          Subtitle = "...Surrender.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B776"
        },
        [80220304] = {
          ContentTC = "束手就擒……好一個束手就擒！若旁人不知，怕不是真當我是罪人。",
          DialogueId = 80220304,
          GUID = "C8D2B7A0",
          NextDialogue = 80220305,
          Subtitle = "\"Surrender\"? That's rich. If people didn't know better, they'd think I was the criminal here.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B7A0"
        },
        [80220305] = {
          ContentTC = "你已犯戕身害命之罪，自為罪人，就此悔過才是正途。",
          DialogueId = 80220305,
          GUID = "C8D2B7CA",
          NextDialogue = 80220306,
          Subtitle = "You've wounded people and taken lives. That makes you a criminal. Repent — it's the only way left.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B7CA"
        },
        [80220306] = {
          ContentTC = "悔過？可笑！那老賊曲解契約，坑害勞苦欺壓鄰里，我不過是替天行道。",
          DialogueId = 80220306,
          GUID = "C8D2B7F4",
          NextDialogue = 80220307,
          Subtitle = "Repent? Don't make me laugh. That old rotter twisted the loan agreement and bled innocent folk dry. I simply carried out justice in Heaven's name.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B7F4"
        },
        [80220307] = {
          ContentTC = "僭權徇私，無可謂替天行道。天道既存，無需凡人替之。",
          DialogueId = 80220307,
          GUID = "C8D2B81E",
          NextDialogue = 80220308,
          Subtitle = "Abusing power is no justice. The Heavenly Way has no need of mortals acting in its name.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B81E"
        },
        [80220308] = {
          ContentTC = "天道既存？呸！我倒要問問，那老賊靠一紙陰陽契詐取錢財，害得無數人傾家蕩產時，你的天道又在哪裡？大風九章又在哪裡？",
          DialogueId = 80220308,
          GUID = "C8D2B848",
          NextDialogue = 80220309,
          Subtitle = "Is that so? Then tell me — when that crafty rotter used a rigged loan agreement to swindle people out of everything they had, where was your \"Heavenly Way\"? Where were the Nine Chapters?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B848"
        },
        [80220309] = {
          ContentTC = "大風九章非一蹴而就，也非不可更改。這等惡性當如何裁斷，太皓神君自有定奪，不容你我僭越。",
          DialogueId = 80220309,
          GUID = "C8D2B872",
          NextDialogue = 80220310,
          Subtitle = "The Nine Chapters weren't forged overnight, and they aren't beyond change. How such evil is dealt with is for Lord Argent to decide — not you, not me. We have no right to overstep.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B872"
        },
        [80220310] = {
          ContentTC = "……哈，冠冕堂皇。來吧，那就讓我領教一番你這應天尉的本事！",
          DialogueId = 80220310,
          GUID = "C8D2B89C",
          NextDialogue = 80220311,
          Subtitle = "...Heh. Pretty words. Come on, then. Let me see what a Magistrate of Yingtian is really worth.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B89C"
        },
        [80220311] = {
          ContentTC = "煜明與飄零人兵刃相向。飄零人沒幾招就敗下陣來。\n長槍刺向飄零人，卻未刺破他的胸膛——\n而一枚斷成兩截的玉帶鉤，從他的胸前掉落。",
          DialogueId = 80220311,
          GUID = "C8D2B8C6",
          NextDialogue = 80220312,
          Subtitle = "Yuming clashes steel with the Drifter. The Drifter goes down in a few exchanges.\nA spear drives for his chest — but doesn't pierce.\nA jade belt clasp, snapped clean in two, falls free.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B8C6"
        },
        [80220312] = {
          ContentTC = "那是……師父的……",
          DialogueId = 80220312,
          GUID = "C8D2B8F0",
          NextDialogue = 80220313,
          Subtitle = "That's... Shifu's...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B8F0"
        },
        [80220313] = {
          ContentTC = "那日不夏穢蝕，他為掩護大家逃離而辭世。而我在血泊裡撿起了他留下的這枚玉帶鉤。",
          DialogueId = 80220313,
          GUID = "C8D2B91A",
          NextDialogue = 80220314,
          Subtitle = "When Deterioration took Buxia, he stayed behind so the rest of us could get out. I found that clasp lying in his blood.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B91A"
        },
        [80220314] = {
          ContentTC = "我將它小心翼翼地粘在一起，想留個念想……結果……該碎的東西還是要碎的。",
          DialogueId = 80220314,
          GUID = "C8D2B944",
          NextDialogue = 80220315,
          Subtitle = "I pieced it back together as carefully as I could, just to keep a piece of him. But... I guess what's broken can never truly be mended.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B944"
        },
        [80220315] = {
          ContentTC = "飄零人無人不敬宴山亭，他告訴大家什麼是恣意，什麼是無拘，什麼是雖千萬人吾往矣，什麼是一諾千金。",
          DialogueId = 80220315,
          GUID = "C8D2B96E",
          NextDialogue = 80220316,
          Subtitle = "Among us Drifters, everyone looked up to Yan Shanting. He lived free. He stayed true to himself, no matter how many stood against him. A man of his word.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B96E"
        },
        [80220316] = {
          ContentTC = "但你呢？應天尉大人，他昔日的愛徒——竟選擇背棄飄零人，向那條破龍搖尾乞憐！",
          DialogueId = 80220316,
          GUID = "C8D2B998",
          NextDialogue = 80220317,
          Subtitle = "But look at you now... Mr Magistrate of Yingtian. His prized disciple — turned back on the Drifters, just to go wagging your tail for that dumb loong!",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B998"
        },
        [80220317] = {
          ContentTC = "…………",
          DialogueId = 80220317,
          GUID = "C8D2B9C2",
          NextDialogue = 80220318,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B9C2"
        },
        [80220318] = {
          ContentTC = "……你走吧。你既接下這一槍，便是上天要你命不該絕。",
          DialogueId = 80220318,
          GUID = "C8D2B9EC",
          NextDialogue = 80220319,
          Subtitle = "...Go. If you survived that strike, then Heaven has not decreed your end.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2B9EC"
        },
        [80220319] = {
          ContentTC = "……哼。",
          DialogueId = 80220319,
          GUID = "C8D2BA16",
          NextDialogue = 80220320,
          Subtitle = "...Hmph.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA16"
        },
        [80220320] = {
          ContentTC = "飄零人瞪了煜明一眼，轉頭奔去，直到消失在煜明的視線之外……",
          DialogueId = 80220320,
          GUID = "C8D2BA40",
          NextDialogue = 80220321,
          Subtitle = "The Drifter glares at Yuming, then turns and runs, vanishing into the rain...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA40"
        },
        [80220321] = {
          ContentTC = "——本應如此。",
          DialogueId = 80220321,
          GUID = "C8D2BA6A",
          NextDialogue = 80220322,
          Subtitle = "That should have been the end.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA6A"
        },
        [80220322] = {
          ContentTC = "但身後忽地有鼓鼓烈風吹來。未及煜明反應，飄零人已無氣息。",
          DialogueId = 80220322,
          GUID = "C8D2BA94",
          NextDialogue = 80220323,
          Subtitle = "But a violent wind surges from behind. Before Yuming can react, the Drifter goes slack and collapses.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BA94"
        },
        [80220323] = {
          ContentTC = "不止何時從身後趕來的狴犴以利爪貫穿了飄零人的胸口。",
          DialogueId = 80220323,
          GUID = "C8D2BABE",
          NextDialogue = 80220324,
          Subtitle = "A Bi'an is already on him. Its claws drive straight through his chest.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BABE"
        },
        [80220324] = {
          ContentTC = "吼——",
          DialogueId = 80220324,
          GUID = "C8D2BAE8",
          NextDialogue = 80220325,
          Subtitle = "ROAR—!",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BAE8"
        },
        [80220325] = {
          ContentTC = "…………",
          DialogueId = 80220325,
          GUID = "C8D2BB12",
          NextDialogue = 80220326,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB12"
        },
        [80220326] = {
          ContentTC = "煜明。",
          DialogueId = 80220326,
          GUID = "C8D2BB3C",
          NextDialogue = 80220327,
          Subtitle = "Yuming.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB3C"
        },
        [80220327] = {
          ContentTC = "…………",
          DialogueId = 80220327,
          GUID = "C8D2BB66",
          NextDialogue = 80220328,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB66"
        },
        [80220328] = {
          ContentTC = "師父……",
          DialogueId = 80220328,
          GUID = "C8D2BB90",
          NextDialogue = 80220329,
          Subtitle = "Shifu...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BB90"
        },
        [80220329] = {
          ContentTC = "煜明，你又長高了，也長壯了。",
          DialogueId = 80220329,
          GUID = "C8D2BBBA",
          NextDialogue = 80220330,
          Subtitle = "Yuming. Look at you — taller, broader in the shoulders.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BBBA"
        },
        [80220330] = {
          ContentTC = "師父，我很多年前就不長個子了。",
          DialogueId = 80220330,
          GUID = "C8D2BBE4",
          NextDialogue = 80220331,
          Subtitle = "But Shifu, I stopped growing years ago.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BBE4"
        },
        [80220331] = {
          ContentTC = "你這個孽徒！師父我好不容易想說句肉麻一點的開場白，你就在這裡拆台。",
          DialogueId = 80220331,
          GUID = "C8D2BC0E",
          NextDialogue = 80220332,
          Subtitle = "You brat! I was ready for a mushy reunion, and you just had to spoil it.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC0E"
        },
        [80220332] = {
          ContentTC = "你怎麼了？一臉苦相，又在發愁？",
          DialogueId = 80220332,
          GUID = "C8D2BC38",
          NextDialogue = 80220333,
          Subtitle = "What's wrong? That miserable look again. What's on your mind?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC38"
        },
        [80220333] = {
          ContentTC = "……沒有……",
          DialogueId = 80220333,
          GUID = "C8D2BC62",
          NextDialogue = 80220334,
          Subtitle = "...Nothing.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC62"
        },
        [80220334] = {
          ContentTC = "扯謊。說過多少次了，你這孩子，一說謊就兩個字兩個字往外蹦。",
          DialogueId = 80220334,
          GUID = "C8D2BC8C",
          NextDialogue = 80220335,
          Subtitle = "You're lying again. Every time you lie, you can barely string two words together. You can't fool me.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BC8C"
        },
        [80220335] = {
          ContentTC = "師父，您是來訓斥徒兒的嗎？",
          DialogueId = 80220335,
          GUID = "C8D2BCB6",
          NextDialogue = 80220336,
          Subtitle = "Shifu... Have you come to scold me?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BCB6"
        },
        [80220336] = {
          ContentTC = "徒兒辜負了您的期待，與昔日舊友兵刃相向。",
          DialogueId = 80220336,
          GUID = "C8D2BCE0",
          NextDialogue = 80220337,
          Subtitle = "I failed you. I crossed blades with old allies.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BCE0"
        },
        [80220337] = {
          ContentTC = "我背叛了您，背棄了飄零人，皈依了大風九章。如今，我已無面目見您。",
          DialogueId = 80220337,
          GUID = "C8D2BD0A",
          NextDialogue = 80220338,
          Subtitle = "I turned my back on you. On the Drifters. I chose the Nine Chapters of Dafeng. I don't know how I can face you now.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD0A"
        },
        [80220338] = {
          ContentTC = "死腦筋。我宴山亭聰明一世，怎就教出來你這塊榆木疙瘩。",
          DialogueId = 80220338,
          GUID = "C8D2BD34",
          NextDialogue = 80220339,
          Subtitle = "Still stubborn as a mule, I see. I've prided myself on my wits all my life — how did I end up with a disciple as thick as you?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD34"
        },
        [80220339] = {
          ContentTC = "徒兒愚鈍。",
          DialogueId = 80220339,
          GUID = "C8D2BD5E",
          NextDialogue = 80220340,
          Subtitle = "...I'm sorry, Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD5E"
        },
        [80220340] = {
          ContentTC = "我只問你一句，你可曾後悔過？",
          DialogueId = 80220340,
          GUID = "C8D2BD88",
          NextDialogue = 80220341,
          Subtitle = "Answer me one thing. Have you ever regretted it?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BD88"
        },
        [80220341] = {
          ContentTC = "煜明……不知。",
          DialogueId = 80220341,
          GUID = "C8D2BDB2",
          NextDialogue = 80220342,
          Subtitle = "I... I don't know.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BDB2"
        },
        [80220342] = {
          ContentTC = "那為師換個問法，若往日再起，你是否還會像當初那樣成為應天尉？",
          DialogueId = 80220342,
          GUID = "C8D2BDDC",
          NextDialogue = 80220343,
          Subtitle = "Then I'll ask it another way. If you could turn back time, would you still choose to become a Magistrate of Yingtian?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BDDC"
        },
        [80220343] = {
          ContentTC = "……會。",
          DialogueId = 80220343,
          GUID = "C8D2BE06",
          NextDialogue = 80220344,
          Subtitle = "...Yes.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE06"
        },
        [80220344] = {
          ContentTC = "為何？",
          DialogueId = 80220344,
          GUID = "C8D2BE30",
          NextDialogue = 80220345,
          Subtitle = "Why?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE30"
        },
        [80220345] = {
          ContentTC = "大風九章之下，我們失去了灑脫，失去了快意恩仇，失去了一部分正義。可……<H>壞的規則也好過沒有規則</>。",
          DialogueId = 80220345,
          GUID = "C8D2BE5A",
          NextDialogue = 80220346,
          Subtitle = "Under the Nine Chapters of Dafeng, we gave up some freedom, and the right to act on right and wrong as we saw fit. But... flawed rules are still better than none.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE5A"
        },
        [80220346] = {
          ContentTC = "若無大風九章，世道失序，人間只會變得更糟。縱有飄零人懲惡揚善，也不過杯水車薪。",
          DialogueId = 80220346,
          GUID = "C8D2BE84",
          NextDialogue = 80220347,
          Subtitle = "Without the Nine Chapters, the world would fall apart. Even the Drifters, punishing evil and righting wrongs, can only do so much.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BE84"
        },
        [80220347] = {
          ContentTC = "更何況，我已不想再看到不夏的事情重演一次。",
          DialogueId = 80220347,
          GUID = "C8D2BEAE",
          NextDialogue = 80220348,
          Subtitle = "And I... I don't want what happened to Buxia to happen to anyone again.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BEAE"
        },
        [80220348] = {
          ContentTC = "……我不想再有下一位大英雄宴山亭死去了。",
          DialogueId = 80220348,
          GUID = "C8D2BED8",
          NextDialogue = 80220349,
          Subtitle = "...I don't want to watch another man like you die, even as a hero.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BED8"
        },
        [80220349] = {
          ContentTC = "哈哈……哈哈！你既已遵循本心，又何須多言。縱然身不由己，但若讓你重來一世仍會堅持曾經的抉擇，旁人又說得什麼？",
          DialogueId = 80220349,
          GUID = "C8D2BF02",
          NextDialogue = 80220350,
          Subtitle = "Ha... haha! If you've followed your own heart, what more is there to say? Choice or no choice back then, give you another chance and you'd still decide the same. So who has the right to judge?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF02"
        },
        [80220350] = {
          ContentTC = "哪怕如今的我已與曾經的師父勢不兩立？",
          DialogueId = 80220350,
          GUID = "C8D2BF2C",
          NextDialogue = 80220351,
          Subtitle = "Even if the man I am now stands against you... against the Shifu I once looked up to?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF2C"
        },
        [80220351] = {
          ContentTC = "垂髫尊父母，弱冠循師長，不惑事權貴，耳順系子女。可若人的一生如此遵從他人所制定好的路途，不曾自己做出選擇，又怎麼說是活過。",
          DialogueId = 80220351,
          GUID = "C8D2BF56",
          NextDialogue = 80220352,
          Subtitle = "When we're young, we follow our parents. When we come of age, our teachers. Later, those in power. Later still, our children. But if a man spends his whole life walking a road laid out by others — never once choosing for himself — then he's never truly lived.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF56"
        },
        [80220352] = {
          ContentTC = "為師從來只教你<H>行無悔之事</>，可從未教過你跟在師父後面亦步亦趨，做那跟屁蟲。",
          DialogueId = 80220352,
          GUID = "C8D2BF80",
          NextDialogue = 80220353,
          Subtitle = "I taught you only one thing: live without regret. I never taught you to follow me blindly and nod along to everything I say.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BF80"
        },
        [80220353] = {
          ContentTC = "煜明，你可記得我為何要反抗大風九章？",
          DialogueId = 80220353,
          GUID = "C8D2BFAA",
          NextDialogue = 80220354,
          Subtitle = "Yuming, do you remember why I rebelled against the Nine Chapters?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BFAA"
        },
        [80220354] = {
          ContentTC = "為了不讓世人困於囚籠，永無自立之本？",
          DialogueId = 80220354,
          GUID = "C8D2BFD4",
          NextDialogue = 80220355,
          Subtitle = "So people wouldn't be trapped in a cage, never learning to stand on their own?",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BFD4"
        },
        [80220355] = {
          ContentTC = "不，是為了在天道之外，奪取<H>另一種選擇的權利</>。",
          DialogueId = 80220355,
          GUID = "C8D2BFFE",
          NextDialogue = 80220356,
          Subtitle = "No. It was to seize, beyond the Heavenly Way, the right to choose another path.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2BFFE"
        },
        [80220356] = {
          ContentTC = "山外山雖與大風九章為敵，卻向來任意來去。這是因為飄零人應當是人生的另一種可能，而不應成為另一個樊籠。",
          DialogueId = 80220356,
          GUID = "C8D2C028",
          NextDialogue = 80220357,
          Subtitle = "The Outer Peaks stands against the Nine Chapters, yet it has always let people come and go freely. A Drifter should be a choice you make — not just another cage.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C028"
        },
        [80220357] = {
          ContentTC = "不要再懲罰自己了，煜明。因為……",
          DialogueId = 80220357,
          GUID = "C8D2C052",
          NextDialogue = 80220358,
          Subtitle = "Stop punishing yourself, Yuming.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C052"
        },
        [80220358] = {
          ContentTC = "你是我的驕傲。",
          DialogueId = 80220358,
          GUID = "C8D2C07C",
          NextDialogue = 80220359,
          Subtitle = "I'm proud of you.",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C07C"
        },
        [80220359] = {
          ContentTC = "師父……",
          DialogueId = 80220359,
          GUID = "C8D2C0A6",
          NextDialogue = 80220360,
          Subtitle = "Shifu...",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C0A6"
        },
        [80220360] = {
          ContentTC = "徒兒……謹遵教誨！",
          DialogueId = 80220360,
          GUID = "C8D2C0D0",
          Subtitle = "I won't forget what you taught me...!",
          VoiceName = "voice/$Locale$/inv/Yuming/003/C8D2C0D0"
        },
        [80220401] = {
          ContentTC = "煜明？是你在吹奏嗎？",
          DialogueId = 80220401,
          GUID = "C8D2C78A",
          NextDialogue = 80220402,
          Subtitle = "Yuming? Was that you?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C78A"
        },
        [80220402] = {
          ContentTC = "{nickname}……別來無恙。",
          DialogueId = 80220402,
          GUID = "C8D2C7B4",
          NextDialogue = 80220403,
          Subtitle = "... It's been a while.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C7B4"
        },
        [80220403] = {
          ContentTC = "沒想到你還會這一手，以前從來沒見過。",
          DialogueId = 80220403,
          GUID = "C8D2C7DE",
          NextDialogue = 80220404,
          Subtitle = "I didn't know you could play the flute. I've never seen you do that before.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C7DE"
        },
        [80220404] = {
          ContentTC = "雖未能為所有百姓排憂解難，倒也確實事務繁忙，無暇抽身。",
          DialogueId = 80220404,
          GUID = "C8D2C808",
          NextDialogue = 80220405,
          Subtitle = "I can't say I've done all I should for the people of Huaxu... but I've kept busy. There was always something that needed seeing to.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C808"
        },
        [80220405] = {
          ContentTC = "如今燭陰歸位，辯法回歸，人神共治，我等太皓代行之人反倒落得清閒。",
          DialogueId = 80220405,
          GUID = "C8D2C832",
          NextDialogue = 80220406,
          Subtitle = "Now things have settled. Zhuyin has returned to their place, and the Trial by Disputation has resumed. With mortals and gods governing together again, those of us acting in Taihao's stead have, at last, found ourselves with time to spare.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C832"
        },
        [80220406] = {
          ContentTC = "怎麼聽起來好像有些落寞……",
          DialogueId = 80220406,
          GUID = "C8D2C85C",
          NextDialogue = 80220407,
          Subtitle = "You sound... a little lonely.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C85C"
        },
        [80220407] = {
          ContentTC = "見笑了。",
          DialogueId = 80220407,
          GUID = "C8D2C886",
          NextDialogue = 80220408,
          Subtitle = "Forgive me. I'm being sentimental.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C886"
        },
        [80220408] = {
          ContentTC = "山外山……算是你的故鄉吧。",
          DialogueId = 80220408,
          GUID = "C8D2C8B0",
          NextDialogue = 80220409,
          Subtitle = "The Outer Peaks... that was your home, right?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C8B0"
        },
        [80220409] = {
          ContentTC = "你是打算回去看看他們？",
          DialogueId = 80220409,
          GUID = "C8D2C8DA",
          NextDialogue = 80220410,
          Subtitle = "Were you thinking of going back to see everyone?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C8DA"
        },
        [80220410] = {
          ContentTC = "……並未。",
          DialogueId = 80220410,
          GUID = "C8D2C904",
          NextDialogue = 80220411,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C904"
        },
        [80220411] = {
          ContentTC = "我……只是路過。我為應天尉太久，與他們早已殊途。",
          DialogueId = 80220411,
          GUID = "C8D2C92E",
          NextDialogue = 80220412,
          Subtitle = "I... was only passing through. I've been a Magistrate of Yingtian for too long now. We're not on the same road anymore.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C92E"
        },
        [80220412] = {
          ContentTC = "比賽一事，我已完成止流囑託，往後便不再見了吧。",
          DialogueId = 80220412,
          GUID = "C8D2C958",
          NextDialogue = 80220413,
          Subtitle = "I've done what Zhiliu asked of me. After that, we won't have any reason to cross paths again.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C958"
        },
        [80220413] = {
          ContentTC = "那真是太可惜了。我來找你，原本是刻舟讓我給你帶個話——",
          DialogueId = 80220413,
          GUID = "C8D2C982",
          NextDialogue = 80220414,
          Subtitle = "That's a shame. I came looking for you because Kezhou asked me to pass on a message—",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C982"
        },
        [80220414] = {
          ContentTC = "他說什麼？",
          DialogueId = 80220414,
          GUID = "C8D2C9AC",
          NextDialogue = 80220415,
          Subtitle = "What was it?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C9AC"
        },
        [80220415] = {
          ContentTC = "你看，這不是還是很關心山外山的人們嘛。",
          DialogueId = 80220415,
          GUID = "C8D2C9D6",
          NextDialogue = 80220416,
          Subtitle = "See? You do still care about them.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2C9D6"
        },
        [80220416] = {
          ContentTC = "…………！",
          DialogueId = 80220416,
          GUID = "C8D2CA00",
          NextDialogue = 80220417,
          Subtitle = "...!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA00"
        },
        [80220417] = {
          ContentTC = "呵呵。",
          DialogueId = 80220417,
          GUID = "C8D2CA2A",
          NextDialogue = 80220418,
          Subtitle = "Heh.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA2A"
        },
        [80220418] = {
          ContentTC = "你笑了？這在你們華胥好像是叫什麼——鐵做的木頭也會開花？",
          DialogueId = 80220418,
          GUID = "C8D2CA54",
          NextDialogue = 80220419,
          Subtitle = "You smiled. That's a rare sight. Like the local saying goes — \"Even ironwood blooms.\" Did I get that right?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA54"
        },
        [80220419] = {
          ContentTC = "我只是覺得，你開起玩笑來像我和刻舟的師父。",
          DialogueId = 80220419,
          GUID = "C8D2CA7E",
          NextDialogue = 80220420,
          Subtitle = "It's just... your jokes remind me of my Shifu.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CA7E"
        },
        [80220420] = {
          ContentTC = "聽刻舟說那是個糟老頭子。唉，你這究竟算是誇我還是算在陰陽怪氣。",
          DialogueId = 80220420,
          GUID = "C8D2CAA8",
          NextDialogue = 80220421,
          Subtitle = "Kezhou says he was a grumpy old man. Honestly... is that meant as a compliment, or are you taking a jab at me?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CAA8"
        },
        [80220421] = {
          ContentTC = "……{nickname}。",
          DialogueId = 80220421,
          GUID = "C8D2CAD2",
          NextDialogue = 80220422,
          Subtitle = "....",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CAD2"
        },
        [80220422] = {
          ContentTC = "怎麼了？",
          DialogueId = 80220422,
          GUID = "C8D2CAFC",
          NextDialogue = 80220423,
          Subtitle = "What is it?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CAFC"
        },
        [80220423] = {
          ContentTC = "依你所見，我此前所踐行之路，能稱之為正確嗎？",
          DialogueId = 80220423,
          GUID = "C8D2CB26",
          NextDialogue = 80220424,
          Subtitle = "Do you think... the path I chose was right?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CB26"
        },
        [80220424] = {
          ContentTC = "這個問題……問我？",
          DialogueId = 80220424,
          GUID = "C8D2CB50",
          NextDialogue = 80220425,
          Subtitle = "You're asking me?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CB50"
        },
        [80220425] = {
          ContentTC = "的確。",
          DialogueId = 80220425,
          GUID = "C8D2CB7A",
          NextDialogue = 80220426,
          Subtitle = "I am.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CB7A"
        },
        [80220426] = {
          ContentTC = "這個問題，你不是早就應該自己得到答案了嗎？",
          DialogueId = 80220426,
          GUID = "C8D2CBA4",
          NextDialogue = 80220427,
          Subtitle = "Isn't that something you already figured out?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CBA4"
        },
        [80220427] = {
          ContentTC = "師父曾說：前路荒蕪，砥礪前行，皆是前人未至之處。",
          DialogueId = 80220427,
          GUID = "C8D2CBCE",
          NextDialogue = 80220428,
          Subtitle = "My Shifu once said, \"The road ahead may be desolate, but to press on is to walk where none have trodden.\"",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CBCE"
        },
        [80220428] = {
          ContentTC = "吾等須一日三省，問天、問人、問心。三省無愧，即是前程。",
          DialogueId = 80220428,
          GUID = "C8D2CBF8",
          NextDialogue = 80220429,
          Subtitle = "He also said we should reflect three times a day — before Heaven, before others, and before our own hearts. If we can face all three with a clear conscience, then the path ahead is worth walking.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CBF8"
        },
        [80220429] = {
          ContentTC = "本以為塵埃落定後，又要重新經歷這三問，會無比漫長痛苦。就像過去的日子裡，不夏、刻舟、師父、太皓……他們的身影總出現在我眼前，令我整夜無眠。",
          DialogueId = 80220429,
          GUID = "C8D2CC22",
          NextDialogue = 80220430,
          Subtitle = "I thought that once everything had settled, I'd have to face it all again — the same slow, painful reckoning. That I'd see Buxia, Kezhou, my Shifu... even Taihao, keeping me awake in the dark.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CC22"
        },
        [80220430] = {
          ContentTC = "但當真邁開腳步，反倒也沒有如舊日般迷惘了。",
          DialogueId = 80220430,
          GUID = "C8D2CC4C",
          NextDialogue = 80220431,
          Subtitle = "But when I finally took that step forward... I found I wasn't as lost anymore.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CC4C"
        },
        [80220431] = {
          ContentTC = "只是向他人尋求答案的習慣一時半會還沒改過來？",
          DialogueId = 80220431,
          GUID = "C8D2CC76",
          NextDialogue = 80220432,
          Subtitle = "So you just haven't shaken the old habit of looking to others for answers yet?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CC76"
        },
        [80220432] = {
          ContentTC = "經年如此，莫要見怪。",
          DialogueId = 80220432,
          GUID = "C8D2CCA0",
          NextDialogue = 80220433,
          Subtitle = "It's been with me a long time... I'll try.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CCA0"
        },
        [80220433] = {
          ContentTC = "看開一點，連龍神都說要改變了，屬於一個人的改變又有什麼好奇怪的？",
          DialogueId = 80220433,
          GUID = "C8D2CCCA",
          NextDialogue = 80220434,
          Subtitle = "Take it easy. Even Lord Argent says they should embrace change. So what's wrong with a mortal doing the same?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CCCA"
        },
        [80220434] = {
          ContentTC = "……說的也是。你說話很像我的師父，讓我豁然開朗。",
          DialogueId = 80220434,
          GUID = "C8D2CCF4",
          NextDialogue = 80220435,
          Subtitle = "...You're right. The way you talk really does remind me of my Shifu. You've cleared my head.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CCF4"
        },
        [80220435] = {
          ContentTC = "說了不要把我比作老頭子了。",
          DialogueId = 80220435,
          GUID = "C8D2CD1E",
          NextDialogue = 80220436,
          Subtitle = "Come on. I told you — don't go making me out to be an old man.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CD1E"
        },
        [80220436] = {
          ContentTC = "嗚嗷——",
          DialogueId = 80220436,
          GUID = "C8D2CD48",
          NextDialogue = 80220437,
          Subtitle = "Awooo!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CD48"
        }
      }
    end
  },
  {
    MinKey = 80220437,
    MaxKey = 90000041,
    Loader = function()
      return {
        [80220437] = {
          ContentTC = "什麼聲音……狐狸叫？",
          DialogueId = 80220437,
          GUID = "C8D2CD72",
          NextDialogue = 80220438,
          Subtitle = "Was that... a fox?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CD72"
        },
        [80220438] = {
          ContentTC = "……是你？小橙子？！",
          DialogueId = 80220438,
          GUID = "C8D2CD9C",
          NextDialogue = 80220439,
          Subtitle = "...Little Tangerine!?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CD9C"
        },
        [80220439] = {
          ContentTC = "嗷嗷——嗷嗚！",
          DialogueId = 80220439,
          GUID = "C8D2CDC6",
          NextDialogue = 80220440,
          Subtitle = "Awoo! Awooo!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CDC6"
        },
        [80220440] = {
          ContentTC = "你沒有回山外山。還有，你還活著。",
          DialogueId = 80220440,
          GUID = "C8D2CDF0",
          NextDialogue = 80220441,
          Subtitle = "You didn't go back to the Outer Peaks... You're still alive.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CDF0"
        },
        [80220441] = {
          ContentTC = "嗷嗚！",
          DialogueId = 80220441,
          GUID = "C8D2CE1A",
          NextDialogue = 80220442,
          Subtitle = "Awoo!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CE1A"
        },
        [80220442] = {
          ContentTC = "你已經長得這麼大了，也比過去精神得多。當年我以為，如果你不回山外山，一定會凍死餓死在野外……看來竟是我想錯了。",
          DialogueId = 80220442,
          GUID = "C8D2CE44",
          NextDialogue = 80220443,
          Subtitle = "Look at you — all grown up, full of life. Back then, I thought that if you didn't return to the Outer Peaks, you'd freeze or starve out here... Guess I was wrong.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CE44"
        },
        [80220443] = {
          ContentTC = "生命每個選擇得到的結果，原是無定數的。一切，都要自己走上那條路後方才知曉。",
          DialogueId = 80220443,
          GUID = "C8D2CE6E",
          NextDialogue = 80220444,
          Subtitle = "I see... You never know how a choice will end until you walk it through.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CE6E"
        },
        [80220444] = {
          ContentTC = "嗷嗚！嗷嗚！",
          DialogueId = 80220444,
          GUID = "C8D2CE98",
          NextDialogue = 80220445,
          Subtitle = "Awoo! Awooo!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CE98"
        },
        [80220445] = {
          ContentTC = "那是山外山的方向。你是想喊我一起回去看看？",
          DialogueId = 80220445,
          GUID = "C8D2CEC2",
          NextDialogue = 80220446,
          Subtitle = "That way leads to the Outer Peaks. Are you asking me to go back with you... to visit?",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CEC2"
        },
        [80220446] = {
          ContentTC = "嗷嗚！",
          DialogueId = 80220446,
          GUID = "C8D2CEEC",
          NextDialogue = 80220447,
          Subtitle = "Awoo!",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CEEC"
        },
        [80220447] = {
          ContentTC = "……我明白了。那麼，{nickname}，後會有期。",
          DialogueId = 80220447,
          GUID = "C8D2CF16",
          NextDialogue = 80220448,
          Subtitle = "...I see. Then, ... until we meet again.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CF16"
        },
        [80220448] = {
          ContentTC = "去吧，他們在等你。",
          DialogueId = 80220448,
          GUID = "C8D2CF40",
          Subtitle = "Go on. They're waiting for you.",
          VoiceName = "voice/$Locale$/inv/Yuming/004/C8D2CF40"
        },
        [80230101] = {
          ContentTC = "龍淵上卿拔擢儀式即刻開始——諸位受太皓青睞者，請依序入覲——",
          DialogueId = 80230101,
          GUID = "C8D8FEF2",
          NextDialogue = 80230102,
          Subtitle = "The selection rite for the High Chancellor of Loongyuan is about to begin. Those favoured by Taihao, step forward in due order.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D8FEF2"
        },
        [80230102] = {
          DialogueId = 80230102,
          GUID = "C8D8FF1C",
          NextDialogue = 80230103,
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D8FF1C"
        },
        [80230103] = {
          ContentTC = "我乃現任龍淵上卿，目前協理天禮司。今日代行太皓旨意，特來考教諸君氣量、心智與覺悟。",
          DialogueId = 80230103,
          GUID = "C8D8FF46",
          NextDialogue = 80230104,
          Subtitle = "I am the current High Chancellor of Loongyuan, presently serving with the Ministry of Rites. By Taihao's decree, I am here to examine your spirit, judgment, and resolve.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D8FF46"
        },
        [80230104] = {
          ContentTC = "今日於執律閣內，我等一舉一動，一言一行，都將由祂見證。纖毫必現，心念亦無可隱遁。",
          DialogueId = 80230104,
          GUID = "C8D8FF70",
          NextDialogue = 80230105,
          Subtitle = "Within this Hall of Adjudication today, every gesture and every word shall be laid bare before Taihao's divine gaze. Nothing, however slight, shall escape Their regard, nor can even a single thought remain concealed.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D8FF70"
        },
        [80230105] = {
          ContentTC = "最終裁決非我所能定奪。唯有太皓之神意，方能決斷誰人有資格承此重任。",
          DialogueId = 80230105,
          GUID = "C8D8FF9A",
          NextDialogue = 80230106,
          Subtitle = "The final judgment does not rest with me. Only Taihao's divine will may decide who is worthy to bear this charge.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D8FF9A"
        },
        [80230106] = {
          ContentTC = "望諸君謹記此間神聖，摒除雜念，以爾等本心與真知應對考問。現在，儀式開始——",
          DialogueId = 80230106,
          GUID = "C8D8FFC4",
          NextDialogue = 80230107,
          Subtitle = "Bear in mind the sanctity of this place. Cast aside all stray thoughts, and answer with a true heart and clear understanding. Now — let the ceremony begin.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D8FFC4"
        },
        [80230107] = {
          ContentTC = "上前來。先介紹一下自己吧，家住何處，姓甚名誰？",
          DialogueId = 80230107,
          GUID = "C8D8FFEE",
          NextDialogue = 80230108,
          Subtitle = "Step forward. Introduce yourself — where are you from, and what is your name?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D8FFEE"
        },
        [80230108] = {
          ContentTC = "回大人，我名顧硯，乃本地人士，祖上數代都長居皓京腳下的椒蘭村中。",
          DialogueId = 80230108,
          GUID = "C8D90018",
          NextDialogue = 80230109,
          Subtitle = "Your Excellency, my name is Gu Yan. I was born and raised here, and my family has lived in Jiaolan Village for generations, beneath the walls of Haojing.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90018"
        },
        [80230109] = {
          ContentTC = "不必這麼拘謹。龍淵上卿的吉兆降於你身時，你的家人想必高興得緊吧？",
          DialogueId = 80230109,
          GUID = "C8D90042",
          NextDialogue = 80230110,
          Subtitle = "There's no need to stand on ceremony. When you were marked by an auspicious sign as a candidate for the High Chancellorship of Loongyuan, your family must have been beside themselves with joy.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90042"
        },
        [80230110] = {
          ContentTC = "那是當然！狴犴剛銜著吉訊到來時，家母她老人家還沒想到會發生什麼。等她後知後覺反應過來顧家竟然要出一位龍淵上卿了，高興得差點昏厥過去。",
          DialogueId = 80230110,
          GUID = "C8D9006C",
          NextDialogue = 80230111,
          Subtitle = "Naturally! When the Bi'an first arrived bearing the glad tidings, my mother had not yet grasped what it meant. But once it dawned on her that our family was to produce a High Chancellor of Loongyuan, she was so overjoyed she nearly fainted.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9006C"
        },
        [80230111] = {
          ContentTC = "事後，家母把那日飄落的香花都一瓣瓣拾了起來，精心裝裱，說要作為之後子子孫孫的傳家寶供起來呢。",
          DialogueId = 80230111,
          GUID = "C8D90096",
          NextDialogue = 80230112,
          Subtitle = "Afterwards, she gathered every fragrant petal that had drifted down that day, preserving them with great care. She said they would be enshrined as a family heirloom, to be passed down to our posterity.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90096"
        },
        [80230112] = {
          ContentTC = "呵呵，獲得太皓的青睞只是第一步。接下來，你們還要通過三道試煉，才能加身龍淵上卿之殊榮。",
          DialogueId = 80230112,
          GUID = "C8D900C0",
          NextDialogue = 80230113,
          Subtitle = "Heh. To receive Taihao's favour is only the first step. You must still pass three trials before the honour of the High Chancellorship of Loongyuan may be conferred upon you.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D900C0"
        },
        [80230113] = {
          ContentTC = "那麼，閒談就到此為止。請對答——",
          DialogueId = 80230113,
          GUID = "C8D900EA",
          NextDialogue = 80230114,
          Subtitle = "That is enough small talk. Now, answer me this—",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D900EA"
        },
        [80230114] = {
          ContentTC = "華胥人生而知大風九章。但你可曾想過，大風九章究其根本為何物？",
          DialogueId = 80230114,
          GUID = "C8D90114",
          NextDialogue = 80230115,
          Subtitle = "The people of Huaxu grow up reciting the Nine Chapters of Dafeng. But have you ever asked yourself what they truly are, at their core?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90114"
        },
        [80230115] = {
          ContentTC = "……自然是太皓神力的流溢。",
          DialogueId = 80230115,
          GUID = "C8D9013E",
          NextDialogue = 80230116,
          Subtitle = "...They are, without question, an emanation of Taihao's divine power.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9013E"
        },
        [80230116] = {
          ContentTC = "大風九章有如日月輪轉，江河奔流，是天地自然之理。它存在於此，亙古如斯。縱地裂山崩，江水為竭，冬雷夏雪，滄海桑田，它仍如日月般恆久不變。",
          DialogueId = 80230116,
          GUID = "C8D90168",
          NextDialogue = 80230117,
          Subtitle = "The Nine Chapters of Dafeng are like the eternal courses of the sun and moon, like rivers flowing to the sea — the natural order written into Heaven and earth. They have existed thus since time immemorial. Even should heaven and earth be overturned, mountains shattered and seas run dry, they would endure unchanged.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90168"
        },
        [80230117] = {
          ContentTC = "我等尊奉大風九章，就和魚得水逝而相忘乎水，鳥乘風飛而不知有風是一樣的道理。",
          DialogueId = 80230117,
          GUID = "C8D90192",
          NextDialogue = 80230118,
          Subtitle = "We honour the Nine Chapters of Dafeng as fish honour water, or birds the wind — living within them, scarcely aware of their presence.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90192"
        },
        [80230118] = {
          ContentTC = "你對神君的虔誠，祂與我等皆已知悉。先下去歇息，回家靜候吧。",
          DialogueId = 80230118,
          GUID = "C8D901BC",
          NextDialogue = 80230119,
          Subtitle = "Your reverence is plain to see. Taihao knows it, and so do I. You may withdraw for now. Go home, and await word.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D901BC"
        },
        [80230119] = {
          ContentTC = "下一位。",
          DialogueId = 80230119,
          GUID = "C8D901E6",
          NextDialogue = 80230120,
          Subtitle = "Next.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D901E6"
        },
        [80230120] = {
          DialogueId = 80230120,
          GUID = "C8D90210",
          NextDialogue = 80230121,
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90210"
        },
        [80230121] = {
          ContentTC = "晚輩止流，見過大人。",
          DialogueId = 80230121,
          GUID = "C8D9023A",
          NextDialogue = 80230122,
          Subtitle = "Your Excellency. My name is Zhiliu.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9023A"
        },
        [80230122] = {
          ContentTC = "止流，你要回答的問題，與上個人相同——「大風九章究其根本為何物？」",
          DialogueId = 80230122,
          GUID = "C8D90264",
          NextDialogue = 80230123,
          Subtitle = "Zhiliu. Your question is the same as that put to the previous candidate — what, at their core, are the Nine Chapters of Dafeng?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90264"
        },
        [80230123] = {
          ContentTC = "……您問的是大風九章的「本質」……",
          DialogueId = 80230123,
          GUID = "C8D9028E",
          NextDialogue = 80230124,
          Subtitle = "...You ask after their essence.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9028E"
        },
        [80230124] = {
          ContentTC = "止流心中確有拙見。但若有冒犯，還請大人和神君寬恕晚輩無知。",
          DialogueId = 80230124,
          GUID = "C8D902B8",
          NextDialogue = 80230125,
          Subtitle = "I do have a view of my own. Should it prove presumptuous, I ask for your and Taihao's forbearance.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D902B8"
        },
        [80230125] = {
          ContentTC = "哦？那依你之見，這「本質」該如何解讀？",
          DialogueId = 80230125,
          GUID = "C8D902E2",
          NextDialogue = 80230126,
          Subtitle = "Oh? Then speak. How do you understand this \"essence\"?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D902E2"
        },
        [80230126] = {
          ContentTC = "太皓非自然之天道，而是順應民心而生。",
          DialogueId = 80230126,
          GUID = "C8D9030C",
          NextDialogue = 80230127,
          Subtitle = "Taihao is not a primordial law of nature. They were brought into being in response to the will of the people.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9030C"
        },
        [80230127] = {
          ContentTC = "昔日華胥子民久罹戰禍，厭倦紛爭，故而先祖矩、颺回應眾人對和平的盼望，以無上偉力鑄就大風九章之基石。",
          DialogueId = 80230127,
          GUID = "C8D90336",
          NextDialogue = 80230128,
          Subtitle = "In ages past, the people of Huaxu suffered long beneath the scourge of war. Weary of strife, they yearned for peace. It was in response to that longing that the forebears, Ju and Yang, laid the foundation of the Nine Chapters of Dafeng, endowing them with immense power.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90336"
        },
        [80230128] = {
          ContentTC = "神與萬民實為相互成就，缺一不可。萬民自願收兵止戈，將裁定善惡之權柄託付於太皓，以己身信守誡律，如此才造就了今日的華胥。",
          DialogueId = 80230128,
          GUID = "C8D90360",
          NextDialogue = 80230129,
          Subtitle = "The divine and the people complete one another. Neither can stand alone. The people laid down their arms of their own will, entrusting Taihao with the authority to judge good and evil, and binding themselves to Their precepts. Thus was Huaxu brought into being as it stands today.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90360"
        },
        [80230129] = {
          ContentTC = "與此同時，太皓回應萬民心願，使允諾的和平化為現實，澤被蒼生。於是生生不息，往復循環。故而大風九章的本質，實為雙方達成的<H>誓約</>。",
          DialogueId = 80230129,
          GUID = "C8D9038A",
          NextDialogue = 80230130,
          Subtitle = "In turn, Taihao answered the people's hopes, giving form to the promised peace and extending Their grace to all living things. Thus the cycle continues, unbroken and unending. For this reason, the Nine Chapters of Dafeng are, in essence, a covenant — a pledge freely entered into by both sides.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9038A"
        },
        [80230130] = {
          ContentTC = "……好一個誓約之說，你這解讀卻是大膽。",
          DialogueId = 80230130,
          GUID = "C8D903B4",
          NextDialogue = 80230131,
          Subtitle = "...A covenant, is it? A daring interpretation.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D903B4"
        },
        [80230131] = {
          ContentTC = "我且問你，你說太皓回應萬民心願，但那些太皓照耀不到的民心，又該如何看待呢？",
          DialogueId = 80230131,
          GUID = "C8D903DE",
          NextDialogue = 80230132,
          Subtitle = "Then let me ask you this. You claim that Taihao answers the wishes of the people, but what of those Their grace does not reach?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D903DE"
        },
        [80230132] = {
          ContentTC = "近來有些對大風九章的坊間雜言，其中不乏飄零人的推波助瀾，相信你也有所耳聞——不必忌諱這個話題。",
          DialogueId = 80230132,
          GUID = "C8D90408",
          NextDialogue = 80230133,
          Subtitle = "There have been whispers of late concerning the Nine Chapters, some stirred by the Drifters. I trust you have heard them. There is no need for reserve. Just speak from your heart.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90408"
        },
        [80230133] = {
          ContentTC = "回大人，不同人的內心有千萬種聲音，神明統合了眾人的心願後，卻只能保有一種聲音。人人遂心所願的世界，大約是不存在的。",
          DialogueId = 80230133,
          GUID = "C8D90432",
          NextDialogue = 80230134,
          Subtitle = "Within each person reside countless voices. Even when a god gathers the wishes of the many, they can preserve but a single voice. A world in which all are satisfied, I fear, does not exist.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90432"
        },
        [80230134] = {
          ContentTC = "凝聚多數之共識，規訓少數之異見，這是構建秩序的代價，亦為社稷存續的根基。",
          DialogueId = 80230134,
          GUID = "C8D9045C",
          NextDialogue = 80230135,
          Subtitle = "To bind the many by a shared consensus, and to discipline the dissent of the few — that is the price of order, and the foundation upon which the state endures.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9045C"
        },
        [80230135] = {
          ContentTC = "有點意思……再說一遍你的名字，叫什麼來著？",
          DialogueId = 80230135,
          GUID = "C8D90486",
          NextDialogue = 80230136,
          Subtitle = "Interesting... Say your name again — what was it?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90486"
        },
        [80230136] = {
          ContentTC = "止流，不吝賜教。",
          DialogueId = 80230136,
          GUID = "C8D904B0",
          NextDialogue = 80230137,
          Subtitle = "Zhiliu. Your Excellency.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D904B0"
        },
        [80230137] = {
          ContentTC = "止狂瀾，斷萬流……是個寓意不錯的名字。回去等消息吧。",
          DialogueId = 80230137,
          GUID = "C8D904DA",
          NextDialogue = 80230138,
          Subtitle = "Zhiliu — to still the raging tide, to sever all rampant currents... A name of fine portent. Go, and await word.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D904DA"
        },
        [80230138] = {
          ContentTC = "止流，我見你有眼緣，便多叮囑你一句。",
          DialogueId = 80230138,
          GUID = "C8D90504",
          NextDialogue = 80230139,
          Subtitle = "Zhiliu. I find you agreeable, and so I will offer you one final word.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D90504"
        },
        [80230139] = {
          ContentTC = "——治國乃修羅之道，你須承擔百般惡名，漠視萬民冤屈。你下定決心了嗎？",
          DialogueId = 80230139,
          GUID = "C8D9052E",
          Subtitle = "To govern a state is to walk a brutal path. You must shoulder every stain of infamy and turn a cold eye to the grievances of the many. Tell me — have you resolved yourself to this?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/001/C8D9052E"
        },
        [80230201] = {
          ContentTC = "大風九章出錯了——有冤情！我要伸冤！",
          DialogueId = 80230201,
          GUID = "C8D90F5A",
          NextDialogue = 80230202,
          Subtitle = "The Nine Chapters of Dafeng made a mistake — an innocent person was condemned! I demand justice!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D90F5A"
        },
        [80230202] = {
          ContentTC = "這位大人，求您了，聽聽我要說的話吧，只需要耽誤您一點時間——",
          DialogueId = 80230202,
          GUID = "C8D90F84",
          NextDialogue = 80230203,
          Subtitle = "Please, sir, please ma'am — just hear me out... it'll only take a few moments of your time...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D90F84"
        },
        [80230203] = {
          ContentTC = "請您稍留片刻——",
          DialogueId = 80230203,
          GUID = "C8D90FAE",
          NextDialogue = 80230204,
          Subtitle = "Please... I'll be concise...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D90FAE"
        },
        [80230204] = {
          DialogueId = 80230204,
          GUID = "C8D90FD8",
          NextDialogue = 80230205,
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D90FD8"
        },
        [80230205] = {
          ContentTC = "出什麼事了？",
          DialogueId = 80230205,
          GUID = "C8D91002",
          NextDialogue = 80230206,
          Subtitle = "What's the matter?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91002"
        },
        [80230206] = {
          ContentTC = "——！",
          DialogueId = 80230206,
          GUID = "C8D9102C",
          NextDialogue = 80230207,
          Subtitle = "—!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9102C"
        },
        [80230207] = {
          ContentTC = "我先前身患重病，被一位澤生閣的醫師所救。治好我的那位醫師，她甚至未收分文，卻被狴犴懲處身亡了！",
          DialogueId = 80230207,
          GUID = "C8D91056",
          NextDialogue = 80230208,
          Subtitle = "Ma'am... it started when I fell gravely ill. A physician from Zesheng Pharmacy saved my life — and she didn't even take a single coin. But... she was condemned to death by a Bi'an!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91056"
        },
        [80230208] = {
          ContentTC = "求求你們，至少——至少把清譽還給她吧！她是個一心救人的醫師啊，大風九章判她的藥害了我，但那只是暫時的藥效變化而已。",
          DialogueId = 80230208,
          GUID = "C8D91080",
          NextDialogue = 80230209,
          Subtitle = "I'm begging you... at least clear her name! She was a good physician who only ever tried to save lives. The Nine Chapters of Dafeng judged that her medicine harmed me, but in truth, it was only a temporary side effect!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91080"
        },
        [80230209] = {
          ContentTC = "我病情複雜，當時看了很多醫師都只是擺擺手表示無能為力，只有她提出用以毒攻毒的險方一試。",
          DialogueId = 80230209,
          GUID = "C8D910AA",
          NextDialogue = 80230210,
          Subtitle = "My illness was complicated. No one would take my case — every physician I went to turned me away. Only she dared suggest a desperate measure.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D910AA"
        },
        [80230210] = {
          ContentTC = "服藥後可能出現驚厥，甚至短暫的呼吸停止，這些後果她都與我詳細說過。我甘願承擔這風險，卻沒想到最終反倒牽連了她。",
          DialogueId = 80230210,
          GUID = "C8D910D4",
          NextDialogue = 80230211,
          Subtitle = "She told me all the possible risks — that there could be convulsions, even brief stoppages of breathing. I told her I was willing to take the risk. I just... never thought it would cost her her life.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D910D4"
        },
        [80230211] = {
          ContentTC = "你的意思是，大風九章錯判了治療過程，使治你的人含冤而死，是嗎？",
          DialogueId = 80230211,
          GUID = "C8D910FE",
          NextDialogue = 80230212,
          Subtitle = "So you're saying the Nine Chapters of Dafeng misjudged the treatment, and the one who treated you died under false blame. Is that it?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D910FE"
        },
        [80230212] = {
          ContentTC = "就是這樣！我還好端端地站在這裡呢，不然還有死人詐屍的道理嗎？",
          DialogueId = 80230212,
          GUID = "C8D91128",
          NextDialogue = 80230213,
          Subtitle = "Exactly! I'm standing right here, aren't I? The dead don't rise and walk again.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91128"
        },
        [80230213] = {
          ContentTC = "我還活著，救我的人卻因此去世了。我……我沒有辦法接受這種事。",
          DialogueId = 80230213,
          GUID = "C8D91152",
          NextDialogue = 80230214,
          Subtitle = "I lived... and the person who saved me died for it. I... I can't accept that.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91152"
        },
        [80230214] = {
          ContentTC = "我明白了。這件事情我不敢保證什麼，但我會盡力而為。",
          DialogueId = 80230214,
          GUID = "C8D9117C",
          NextDialogue = 80230215,
          Subtitle = "I understand. I can't give you any guarantees, but I will do what I can.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9117C"
        },
        [80230215] = {
          ContentTC = "——謝謝您！謝謝！",
          DialogueId = 80230215,
          GUID = "C8D911A6",
          NextDialogue = 80230216,
          Subtitle = "Thank you, ma'am... thank you truly.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D911A6"
        },
        [80230216] = {
          ContentTC = "……其實我知道這件事情非常難，您可能也沒辦法做到什麼。我在這裡站了好幾天了，只有您一個人願意停下來聽我說話……",
          DialogueId = 80230216,
          GUID = "C8D911D0",
          NextDialogue = 80230217,
          Subtitle = "...I know it's almost impossible to right this wrong. There's probably nothing you can do to change it. I've stood here for days, but you're the only one who stopped.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D911D0"
        },
        [80230217] = {
          ContentTC = "哪怕是為了這點善意，我也要感謝您……",
          DialogueId = 80230217,
          GUID = "C8D911FA",
          NextDialogue = 80230218,
          Subtitle = "Even if nothing comes of this... thank you for your kindness.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D911FA"
        },
        [80230218] = {
          ContentTC = "呵呵，只是無足掛齒的小事而已。",
          DialogueId = 80230218,
          GUID = "C8D91224",
          NextDialogue = 80230219,
          Subtitle = "Heh. Think nothing of it.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91224"
        },
        [80230219] = {
          DialogueId = 80230219,
          GUID = "C8D9124E",
          NextDialogue = 80230220,
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9124E"
        },
        [80230220] = {
          ContentTC = "各位既已到齊，接下來便開始第二道試煉——",
          DialogueId = 80230220,
          GUID = "C8D91278",
          NextDialogue = 80230221,
          Subtitle = "All are present. We shall begin the second trial.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91278"
        },
        [80230221] = {
          ContentTC = "……有冤……我要申冤！",
          DialogueId = 80230221,
          GUID = "C8D912A2",
          NextDialogue = 80230222,
          Subtitle = "The Nine Chapters made a mistake... I demand justice...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D912A2"
        },
        [80230222] = {
          ContentTC = "那女孩怎麼還在執律閣下鬧個不停？既讓路人煩擾不堪，也擾了太皓清淨。大人，不如請應天尉將她清退吧！",
          DialogueId = 80230222,
          GUID = "C8D912CC",
          NextDialogue = 80230223,
          Subtitle = "Why is that girl still making such a racket beneath the walls of the Hall of Adjudication? She's disturbing passers-by and disrupting the sanctity of this place. Your Excellency, shall we have the Magistrates of Yingtian remove her?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D912CC"
        },
        [80230223] = {
          ContentTC = "稍安勿躁，她便是你們今日的試題。",
          DialogueId = 80230223,
          GUID = "C8D912F6",
          NextDialogue = 80230224,
          Subtitle = "Patience. She is today's trial.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D912F6"
        },
        [80230224] = {
          ContentTC = "（嘈雜的議論聲）",
          DialogueId = 80230224,
          GUID = "C8D91320",
          NextDialogue = 80230225,
          Subtitle = "(Murmurs ripple through the crowd.)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91320"
        },
        [80230225] = {
          ContentTC = "大風九章作為經年累月運轉的龐大體系，哪怕是萬分之一的機率，也會產生紕漏。",
          DialogueId = 80230225,
          GUID = "C8D9134A",
          NextDialogue = 80230226,
          Subtitle = "The Nine Chapters of Dafeng are a vast system, long in operation. Even the smallest margin of error can give rise to flaws over such a long span of time and on such a scale.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9134A"
        },
        [80230226] = {
          ContentTC = "如何輔助太皓妥善處理這些紕漏，是治理國家的重要一環，也是今日為諸位所設置的考察。諸位有想法，都可以暢所欲言。",
          DialogueId = 80230226,
          GUID = "C8D91374",
          NextDialogue = 80230227,
          Subtitle = "How one assists Taihao in resolving such flaws is an essential part of governing. This is your trial for today. If you have an answer, speak.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91374"
        },
        [80230227] = {
          ContentTC = "大人，大風九章的正義早已深入人心。這種雜音，不予理會就是。",
          DialogueId = 80230227,
          GUID = "C8D9139E",
          NextDialogue = 80230228,
          Subtitle = "Your Excellency, the legitimacy of the Nine Chapters has long taken root among the people. Such noise is not worth our attention and can be safely ignored.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9139E"
        },
        [80230228] = {
          ContentTC = "千里之堤，潰於蟻穴。如果長期放任不管，只會助長了山外山那等勢力的氣焰，造成隱患。",
          DialogueId = 80230228,
          GUID = "C8D913C8",
          NextDialogue = 80230229,
          Subtitle = "For want of a nail, a kingdom is lost. Leave it to fester, and you embolden forces like the Outer Peaks, allowing hidden threats to grow.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D913C8"
        },
        [80230229] = {
          ContentTC = "依我看，不外乎威逼利誘二種做法！給出足夠強力的威脅，或者足夠動人的利益交換，再頑固的人也會敗下陣來。",
          DialogueId = 80230229,
          GUID = "C8D913F2",
          NextDialogue = 80230230,
          Subtitle = "It's simple. There are two ways: threats, or inducements. Make the threat sharp enough, or the offer sweet enough, and even the stubborn will yield.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D913F2"
        },
        [80230230] = {
          ContentTC = "人非草木。你若是輕視了人心，引起對方反彈，非但平息不了風波，只會讓事情更加棘手。",
          DialogueId = 80230230,
          GUID = "C8D9141C",
          NextDialogue = 80230231,
          Subtitle = "People have hearts. Disregard them, and backlash is inevitable. You won't calm anything — you'll only deepen it.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9141C"
        },
        [80230231] = {
          ContentTC = "（嘈雜的議論聲）",
          DialogueId = 80230231,
          GUID = "C8D91446",
          NextDialogue = 80230232,
          Subtitle = "(Murmurs ripple through the crowd.)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91446"
        },
        [80230232] = {
          ContentTC = "我有一法，且讓我試試吧。",
          DialogueId = 80230232,
          GUID = "C8D91470",
          NextDialogue = 80230233,
          Subtitle = "I have a way. Let me handle it.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91470"
        },
        [80230233] = {
          DialogueId = 80230233,
          GUID = "C8D9149A",
          NextDialogue = 80230234,
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9149A"
        },
        [80230234] = {
          ContentTC = "好心的姐姐，是您……您來見我了！",
          DialogueId = 80230234,
          GUID = "C8D914C4",
          NextDialogue = 80230235,
          Subtitle = "Ma'am... you came back!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D914C4"
        },
        [80230235] = {
          ContentTC = "這麼快就回來，難不成……您有什麼辦法了？",
          DialogueId = 80230235,
          GUID = "C8D914EE",
          NextDialogue = 80230236,
          Subtitle = "Does that mean you've found a solution?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D914EE"
        },
        [80230236] = {
          ContentTC = "抱歉，你的訴求，我恐怕沒法滿足。",
          DialogueId = 80230236,
          GUID = "C8D91518",
          NextDialogue = 80230237,
          Subtitle = "I'm sorry. I cannot grant your request.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91518"
        },
        [80230237] = {
          ContentTC = "……",
          DialogueId = 80230237,
          GUID = "C8D91542",
          NextDialogue = 80230238,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91542"
        },
        [80230238] = {
          ContentTC = "大風九章關乎華胥萬民生息，萬民信賴是其運轉的根基。不可因為零星錯案動搖根基，因小失大。這是利弊取捨的一環。",
          DialogueId = 80230238,
          GUID = "C8D9156C",
          NextDialogue = 80230239,
          Subtitle = "The Nine Chapters of Dafeng underpin the order of Huaxu. It stands on the people's trust. We cannot endanger the whole for the sake of the few. That is the price such order demands.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9156C"
        },
        [80230239] = {
          ContentTC = "但我可以承諾的是，此事風波平息後，澤生閣會獲得扶持。此外，我還能為你個人申請一筆補償金，聊以慰藉。",
          DialogueId = 80230239,
          GUID = "C8D91596",
          NextDialogue = 80230240,
          Subtitle = "What I can promise is this: once this matter fades, Zesheng Pharmacy will be quietly backed. As for you, I can apply for compensation — something to ease the hurt, if only a little.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91596"
        },
        [80230240] = {
          ContentTC = "這些聽起來似乎很好，可是姐姐……我不想要這樣。",
          DialogueId = 80230240,
          GUID = "C8D915C0",
          NextDialogue = 80230241,
          Subtitle = "It all sounds reasonable... but it's not what I want.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D915C0"
        },
        [80230241] = {
          ContentTC = "要是沒有救我的那位醫師，我現在已經是黃土之下的一縷亡魂了。對死人來說，錢還能花到哪裡去呢？",
          DialogueId = 80230241,
          GUID = "C8D915EA",
          NextDialogue = 80230242,
          Subtitle = "Without the physician, I'd already be dead and buried. What use is money to the dead?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D915EA"
        },
        [80230242] = {
          ContentTC = "同樣的道理，對於救下我卻失去了性命的那位醫師，這些身外之物也沒有意義了。我唯一能為她爭的，只有生後的清白而已。",
          DialogueId = 80230242,
          GUID = "C8D91614",
          NextDialogue = 80230243,
          Subtitle = "Similarly, these worldly things mean nothing to her anymore. The only thing left I can do for her is clear her name, even in death.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91614"
        },
        [80230243] = {
          ContentTC = "拿了這些錢，我或許能過上更好的生活，但是我的良心呢？它以後要是痛了起來，我再也找不到藥方去治療它了。",
          DialogueId = 80230243,
          GUID = "C8D9163E",
          NextDialogue = 80230244,
          Subtitle = "If I take the money, perhaps my life would be easier. But what of my conscience? If it ever turns against me, there will be no cure for that pain.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9163E"
        },
        [80230244] = {
          ContentTC = "姐姐，大風九章的運轉，真的要以一個個人的冤屈被掩埋為代價嗎？",
          DialogueId = 80230244,
          GUID = "C8D91668",
          NextDialogue = 80230245,
          Subtitle = "Ma'am... must the Nine Chapters of Dafeng truly be sustained by burying one injustice after another?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91668"
        },
        [80230245] = {
          ContentTC = "……你這性子和我年輕時倒有幾分相似。那有些話，我也只說與你我二人聽。",
          DialogueId = 80230245,
          GUID = "C8D91692",
          NextDialogue = 80230246,
          Subtitle = "...You remind me of my younger self. Let's talk in private. There are things I will only say to someone like you.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91692"
        },
        [80230246] = {
          DialogueId = 80230246,
          GUID = "C8D916BC",
          NextDialogue = 80230247,
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D916BC"
        },
        [80230247] = {
          ContentTC = "止流少卿，未想到你三言兩語就擺平了那少女，使她簽下了放棄伸冤的契書。有什麼訣竅呀？也教教我們吧！",
          DialogueId = 80230247,
          GUID = "C8D916E6",
          NextDialogue = 80230248,
          Subtitle = "Chancellor Zhiliu! You handled that effortlessly — with just a few words, you even had her withdraw her petition. That was impressive. How did you do it? What's your secret?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D916E6"
        },
        [80230248] = {
          ContentTC = "過譽了。我還未通過全部試煉，當不起這一聲稱呼。只是耐心為她分析了其中利弊而已。",
          DialogueId = 80230248,
          GUID = "C8D91710",
          NextDialogue = 80230249,
          Subtitle = "You flatter me. I've yet to pass every trial and am hardly worthy of the title \"Chancellor.\" As for the girl, I only laid out the realities for her.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91710"
        },
        [80230249] = {
          ContentTC = "若無其他要事，我先告退了。",
          DialogueId = 80230249,
          GUID = "C8D9173A",
          NextDialogue = 80230250,
          Subtitle = "If there is nothing else, I will take my leave.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9173A"
        },
        [80230250] = {
          DialogueId = 80230250,
          GUID = "C8D91764",
          NextDialogue = 80230251,
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91764"
        },
        [80230251] = {
          ContentTC = "你們知道嗎？聽說那個止流啊，從前也受過大風九章的冤屈。",
          DialogueId = 80230251,
          GUID = "C8D9178E",
          NextDialogue = 80230252,
          Subtitle = "You know... I heard Miss Zhiliu was once wronged by the Nine Chapters herself.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9178E"
        },
        [80230252] = {
          ContentTC = "曾經她也在執律閣下那個位置四處奔走，甚至是這附近居民茶餘飯後的談資呢。",
          DialogueId = 80230252,
          GUID = "C8D917B8",
          NextDialogue = 80230253,
          Subtitle = "She stood down there too, in the square beneath the Hall — just like that girl — asking for justice. It was once the locals' favourite bit of gossip.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D917B8"
        },
        [80230253] = {
          ContentTC = "沒想到今天她能眼都不眨地擺平和曾經的自己一樣的人。這就是成大事者嗎？",
          DialogueId = 80230253,
          GUID = "C8D917E2",
          NextDialogue = 80230254,
          Subtitle = "And today... she handled it like it meant nothing. Like she'd never been in that position herself. Is that what it takes to accomplish great things?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D917E2"
        },
        [80230254] = {
          ContentTC = "唉……恐怕她就是下一位龍淵上卿了，我們也羨慕不來，畢竟學不了她的心狠手辣。恐怕只有修羅心腸的人，才能站在那個位置吧。",
          DialogueId = 80230254,
          GUID = "C8D9180C",
          NextDialogue = 80230255,
          Subtitle = "I suppose she'll be the next High Chancellor of Loongyuan. There's little to envy — we simply couldn't do what she does. Perhaps only someone who's learned to strip their heart of all softness can bear the weight of that office.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D9180C"
        },
        [80230255] = {
          ContentTC = "呵呵……只有修羅心腸，才能治大國嗎？",
          DialogueId = 80230255,
          GUID = "C8D91836",
          Subtitle = "Heh... Is that the price of governing a state — to strip one's heart of all softness?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/002/C8D91836"
        },
        [80230301] = {
          ContentTC = "接下來便是最後一道試煉了，先提前恭賀你一聲。邁過此關，你便能以龍淵上卿的頭銜榮登執律閣巔。",
          DialogueId = 80230301,
          GUID = "C8D91FC2",
          NextDialogue = 80230302,
          Subtitle = "The final trial shall begin shortly. Allow me to offer my congratulations in advance. Pass this trial, and you will ascend to the summit of the Hall of Adjudication, where you shall be granted the High Chancellorship of Loongyuan.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D91FC2"
        },
        [80230302] = {
          ContentTC = "這最後一道試煉，其名為「問心」。",
          DialogueId = 80230302,
          GUID = "C8D91FEC",
          NextDialogue = 80230303,
          Subtitle = "This final trial is called \"On the Heart\".",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D91FEC"
        },
        [80230303] = {
          ContentTC = "在太皓的神力照耀之下，你的過往心魔將如影照形，歷歷可見。",
          DialogueId = 80230303,
          GUID = "C8D92016",
          NextDialogue = 80230304,
          Subtitle = "Under Taihao's divine radiance, what once haunted you will take form before you — clear, like a shadow cast by light.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92016"
        },
        [80230304] = {
          ContentTC = "對於爾等大毅力者，必能斬斷過往，踏過心中軟弱，從而執起「承九鼎，濟蒼黎」之重任。",
          DialogueId = 80230304,
          GUID = "C8D92040",
          NextDialogue = 80230305,
          Subtitle = "Those with true resolve will sever themselves from the past, overcome the heart's weakness, and take up a grave charge: to bear the pillars of the realm, and to bring succour to all the people.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92040"
        },
        [80230305] = {
          ContentTC = "止流，你可準備好了？",
          DialogueId = 80230305,
          GUID = "C8D9206A",
          NextDialogue = 80230306,
          Subtitle = "Zhiliu. Are you ready?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9206A"
        },
        [80230306] = {
          ContentTC = "從很久之前，我就已明確此心志向，不會再隨外物而動。",
          DialogueId = 80230306,
          GUID = "C8D92094",
          NextDialogue = 80230307,
          Subtitle = "I made my choice long ago. Nothing beyond my own will will sway my heart again.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92094"
        },
        [80230307] = {
          ContentTC = "很好。我沒有看走眼。",
          DialogueId = 80230307,
          GUID = "C8D920BE",
          NextDialogue = 80230308,
          Subtitle = "Good. My judgment of you was sound.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D920BE"
        },
        [80230308] = {
          ContentTC = "止流，甫一見面，我便看出你是那些人裡最出類拔萃的一個苗子。",
          DialogueId = 80230308,
          GUID = "C8D920E8",
          NextDialogue = 80230309,
          Subtitle = "From the moment we first met, I knew you stood apart from the rest.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D920E8"
        },
        [80230309] = {
          ContentTC = "那麼試煉正式開始。無關人士便先清退了，我在執律閣外靜候你的佳音。",
          DialogueId = 80230309,
          GUID = "C8D92112",
          NextDialogue = 80230310,
          Subtitle = "Very well. Let the trial commence. All others will withdraw. I shall await the outcome beyond these doors.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92112"
        },
        [80230310] = {
          DialogueId = 80230310,
          GUID = "C8D9213C",
          NextDialogue = 80230311,
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9213C"
        },
        [80230311] = {
          ContentTC = "——！",
          DialogueId = 80230311,
          GUID = "C8D92166",
          NextDialogue = 80230312,
          Subtitle = "—!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92166"
        },
        [80230312] = {
          ContentTC = "……",
          DialogueId = 80230312,
          GUID = "C8D92190",
          NextDialogue = 80230313,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92190"
        },
        [80230313] = {
          DialogueId = 80230313,
          GUID = "C8D921BA",
          NextDialogue = 80230314,
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D921BA"
        },
        [80230314] = {
          ContentTC = "嗚……嗚嗚……為什麼……",
          DialogueId = 80230314,
          GUID = "C8D921E4",
          NextDialogue = 80230315,
          Subtitle = "Why...?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D921E4"
        },
        [80230315] = {
          ContentTC = "（果然……不出所料。）",
          DialogueId = 80230315,
          GUID = "C8D9220E",
          NextDialogue = 80230316,
          Subtitle = "(...Of course.)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9220E"
        },
        [80230316] = {
          ContentTC = "你已經忘記了嗎……<H>我們</>那些夜不能寐的晚上？",
          DialogueId = 80230316,
          GUID = "C8D92238",
          NextDialogue = 80230317,
          Subtitle = "Have you forgotten... the nights we couldn't sleep?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92238"
        },
        [80230317] = {
          ContentTC = "你忘記了嗎……在山洞裡飢餓如蛆附骨的感覺，身體上下的每一處，每一根髮絲都在叫囂著好餓、好餓……",
          DialogueId = 80230317,
          GUID = "C8D92262",
          NextDialogue = 80230318,
          Subtitle = "Have you forgotten the time in that cave — the hunger gnawing at every inch of our skin, sinking deep into our bones? Our every nerve screaming in agony — I'm hungry... so hungry...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92262"
        },
        [80230318] = {
          ContentTC = "你忘記了嗎……那個歹徒，他滿是繭子的手緊緊鉗住<H>我們</>脖子的那一刻，無論我們怎麼掙扎，怎麼奮力踢腿，都阻止不了分毫……",
          DialogueId = 80230318,
          GUID = "C8D9228C",
          NextDialogue = 80230319,
          Subtitle = "Have you forgotten... the moment that brute's calloused hand closed around our throat? No matter how we struggled, how our arms and legs flailed, it wouldn't loosen, not even a little...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9228C"
        },
        [80230319] = {
          ContentTC = "空氣逐漸消失，一切閃著光的畫面都變得稀薄，冰冷的死亡即將把我們拽入霧中……",
          DialogueId = 80230319,
          GUID = "C8D922B6",
          NextDialogue = 80230320,
          Subtitle = "The air thinning... the world around us dimming... cold death almost drawing us into the fog...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D922B6"
        },
        [80230320] = {
          ContentTC = "以及……你忘了嗎，<H>他</>衝上來，撞開歹徒，讓空氣一下子全部涌回來的那個時刻。",
          DialogueId = 80230320,
          GUID = "C8D922E0",
          NextDialogue = 80230321,
          Subtitle = "And... have you forgotten the moment he rushed in — drove the brute away — and air rushed back into our lungs all at once?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D922E0"
        },
        [80230321] = {
          ContentTC = "他曾經那樣對你，不計回報地去救你，卻只落得了身死名滅的下場。",
          DialogueId = 80230321,
          GUID = "C8D9230A",
          NextDialogue = 80230322,
          Subtitle = "He saved your life without expecting anything in return... only to end up dead, his name tarnished and forgotten.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9230A"
        },
        [80230322] = {
          ContentTC = "現在，你要背叛他，背叛我們曾經發下的誓言，投向<H>他們</>那邊嗎？",
          DialogueId = 80230322,
          GUID = "C8D92334",
          NextDialogue = 80230323,
          Subtitle = "And now — you would turn on him... betray the vow we once swore... and join their side?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92334"
        },
        [80230323] = {
          ContentTC = "…………",
          DialogueId = 80230323,
          GUID = "C8D9235E",
          NextDialogue = 80230324,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9235E"
        },
        [80230324] = {
          ContentTC = "（是的……是的……你不需要去銘記。因為遺忘明顯更加甜美。）",
          DialogueId = 80230324,
          GUID = "C8D92388",
          NextDialogue = 80230325,
          Subtitle = "(Yes... yes... you don't have to remember. It's easier to just forget.)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92388"
        },
        [80230325] = {
          ContentTC = "（你即將成為萬人之上的止流大人！這些過去的紛擾無法撼動你，和你即將獲得的地位相比，他們顯得那麼不起眼，那麼無足輕重，甚至不如一根輕飄飄的鴻毛。）",
          DialogueId = 80230325,
          GUID = "C8D923B2",
          NextDialogue = 80230326,
          Subtitle = "(You're about to rise above everyone else. The pain and woes of the past can't touch you anymore. From where you'll stand, it will all seem insignificant.)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D923B2"
        },
        [80230326] = {
          ContentTC = "（倒不如說，銘記只是軟弱的證明。軟弱者用無謂的良心將自己束縛住，於是他們屈服了。他們的膝蓋承受不住大地的重力，永遠匍匐在塵埃之中。）",
          DialogueId = 80230326,
          GUID = "C8D923DC",
          NextDialogue = 80230327,
          Subtitle = "(Clinging to memory is a form of weakness. The weak let conscience weigh them down. They can't bear the weight — so they bend, and they stay in the dust forever.)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D923DC"
        },
        [80230327] = {
          ContentTC = "（那些軟弱者沉浸在自己的夢中，同時世界毫無變化。而你，你顯然更加堅毅，更加勇敢——你懂得取捨，於是你能成大器。有幾人能有成為修羅的大毅力呢？）",
          DialogueId = 80230327,
          GUID = "C8D92406",
          NextDialogue = 80230328,
          Subtitle = "(They drown in their illusions and fantasies, and nothing ever changes because they're too cowardly to act. But you — you're tougher. Braver. You understand what must be given up for something of greater value. That's why you'll achieve greatness. How many have it in them to strip their hearts of all softness?)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92406"
        },
        [80230328] = {
          ContentTC = "（不要聽他的！！止流，你與那些冷眼旁觀的人有何區別？）",
          DialogueId = 80230328,
          GUID = "C8D92430",
          NextDialogue = 80230329,
          Subtitle = "(Don't listen to him!! Zhiliu — how is it any different from those heartless bystanders?)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92430"
        },
        [80230329] = {
          ContentTC = "（止流，你想好了，你也要成為他們的幫凶嗎？！）",
          DialogueId = 80230329,
          GUID = "C8D9245A",
          NextDialogue = 80230330,
          Subtitle = "(Do you really want to become an accomplice to those higher-ups?)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9245A"
        },
        [80230330] = {
          ContentTC = "（若是踏出這一步，你還是昨日之你嗎？）",
          DialogueId = 80230330,
          GUID = "C8D92484",
          NextDialogue = 80230331,
          Subtitle = "(If you make that choice... will you still be the same person you were yesterday?)",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92484"
        },
        [80230331] = {
          DialogueId = 80230331,
          GUID = "C8D924AE",
          NextDialogue = 80230332,
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D924AE"
        },
        [80230332] = {
          ContentTC = "救命，誰來救救我……這裡好黑……我好害怕……我，我不能待在這個地方！",
          DialogueId = 80230332,
          GUID = "C8D924D8",
          NextDialogue = 80230333,
          Subtitle = "Help... someone, please... It's so dark... I'm scared... I—I can't stay here. I can't!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D924D8"
        },
        [80230333] = {
          DialogueId = 80230333,
          GUID = "C8D92502",
          NextDialogue = 80230334,
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92502"
        },
        [80230334] = {
          ContentTC = "你知道嗎……自從幾年前有意識地去控制後，怕黑便不再能影響我的一舉一動了。",
          DialogueId = 80230334,
          GUID = "C8D9252C",
          NextDialogue = 80230335,
          Subtitle = "You know... I learned to control my fear of the dark years ago. Since then, the dark has had no hold on me.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9252C"
        },
        [80230335] = {
          ContentTC = "當我意識到無論恐懼抑或痛苦都於事無補之時，我便捨棄了這些情緒。",
          DialogueId = 80230335,
          GUID = "C8D92556",
          NextDialogue = 80230336,
          Subtitle = "When I understood that fear and pain could change nothing, I cast them aside.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92556"
        },
        [80230336] = {
          ContentTC = "因為我突然發現，人擁有的時間過於短暫——短暫到無法償換自己欲求之物，這一生便匆匆結束了。",
          DialogueId = 80230336,
          GUID = "C8D92580",
          NextDialogue = 80230337,
          Subtitle = "In that moment, it dawned on me that a person's life is short — too short to secure what they truly want before it ends.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92580"
        },
        [80230337] = {
          ContentTC = "從那一天起，我便下定決心。這世上的任何事情，無論是良心還是過往，都不再能絆住我的腳步。因為我還有要去完成的事情。",
          DialogueId = 80230337,
          GUID = "C8D925AA",
          NextDialogue = 80230338,
          Subtitle = "From that day on, I made my choice: to let neither my conscience nor my past slow me down. There is still something I must accomplish.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D925AA"
        },
        [80230338] = {
          ContentTC = "我很抱歉只能讓你待在黑暗之中……但是不會有誰來救你了，你只能憑自己的力量走出這裡。",
          DialogueId = 80230338,
          GUID = "C8D925D4",
          NextDialogue = 80230339,
          Subtitle = "I'm sorry to leave you here in the dark... You should know this: no one is coming to save you. You'll have to find your own way out.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D925D4"
        },
        [80230339] = {
          ContentTC = "我言盡於此。",
          DialogueId = 80230339,
          GUID = "C8D925FE",
          NextDialogue = 80230340,
          Subtitle = "That is all I have to say.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D925FE"
        },
        [80230340] = {
          DialogueId = 80230340,
          GUID = "C8D92628",
          NextDialogue = 80230341,
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92628"
        },
        [80230341] = {
          ContentTC = "傳吉訊——",
          DialogueId = 80230341,
          GUID = "C8D92652",
          NextDialogue = 80230342,
          Subtitle = "Proclaim the decree—",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D92652"
        },
        [80230342] = {
          ContentTC = "皓京人士止流，現榮升為龍淵上卿——願其承九鼎，濟蒼黎，不負太皓之望，傳大風於萬代——",
          DialogueId = 80230342,
          GUID = "C8D9267C",
          Subtitle = "Zhiliu of Haojing is hereby elevated to High Chancellor of Loongyuan, charged with bearing the pillars of the realm and bringing succour to all the people. May she prove worthy of Taihao's trust, and aid in carrying the Dafeng forward through the ages.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/003/C8D9267C"
        },
        [80230401] = {
          ContentTC = "龍淵上卿每四載選拔一任，同時在任者寥寥無幾，關於其選拔過程的記載往往殘缺不全。如今竟從親歷者口中聽到這麼多細節，妙哉，妙哉！",
          DialogueId = 80230401,
          GUID = "C8D9302A",
          NextDialogue = 80230402,
          Subtitle = "The High Chancellorship of Loongyuan is decided only once every four years. Those who have held the office are few, and the records they leave behind are thinner still. So to hear the account from someone who stood at the centre of it all — that is a rare indulgence!",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9302A"
        },
        [80230402] = {
          ContentTC = "能旁觀這段活生生的歷史，我的心事又了了一樁。",
          DialogueId = 80230402,
          GUID = "C8D93054",
          NextDialogue = 80230403,
          Subtitle = "To witness history, not as ink on a page, but as lived experience... it settles a curiosity I have carried for quite some time.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93054"
        },
        [80230403] = {
          ContentTC = "……要是這些往事能讓你消停片刻，少做些節外生枝的事情，那也不枉我費這麼多口舌。",
          DialogueId = 80230403,
          GUID = "C8D9307E",
          NextDialogue = 80230404,
          Subtitle = "...If revisiting old tales keeps you from stirring up new trouble, then this conversation has served its purpose.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9307E"
        },
        [80230404] = {
          ContentTC = "秦虬，我提醒你一句。{nickname}是我的座上賓，我不希望{性别：他|她}出什麼意外。你行事最好有些分寸。",
          DialogueId = 80230404,
          GUID = "C8D930A8",
          NextDialogue = 80230405,
          Subtitle = "Qin Qiu — be clear on this.  is my honoured guest. I will not have {性别：him|her} harmed. Do not overstep.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D930A8"
        },
        [80230405] = {
          ContentTC = "哈哈！你從冰湖城不遠千里請回來的那位小友確實有趣，使我忍不住捉弄一番。",
          DialogueId = 80230405,
          GUID = "C8D930D2",
          NextDialogue = 80230406,
          Subtitle = "Ha! Of course not. That young friend you brought back from Icelake is rather interesting. I merely indulged a passing impulse to tease {性别：him|her} a little.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D930D2"
        },
        [80230406] = {
          ContentTC = "不過，止流掌柜對某人如此上心，倒是難得一見的光景。",
          DialogueId = 80230406,
          GUID = "C8D930FC",
          NextDialogue = 80230407,
          Subtitle = "Still... it is uncommon to see you take such pains over someone else. You are not known for unnecessary attachments.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D930FC"
        },
        [80230407] = {
          ContentTC = "這次計劃的實情，你真不打算對{性别：他|她}托出一二嗎？",
          DialogueId = 80230407,
          GUID = "C8D93126",
          NextDialogue = 80230408,
          Subtitle = "Which makes one wonder. About this arrangement of yours — you truly intend to tell {性别：him|her} nothing at all?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93126"
        },
        [80230408] = {
          ContentTC = "……我自有我的打算，勸你不要有什麼額外心思。",
          DialogueId = 80230408,
          GUID = "C8D93150",
          NextDialogue = 80230409,
          Subtitle = "...My arrangements are not your concern. Do not involve yourself further.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93150"
        },
        [80230409] = {
          ContentTC = "世人皆知我虬某陰險狡詐，無孔不鑽，而你止流掌柜行事光明磊落，手段高明。",
          DialogueId = 80230409,
          GUID = "C8D9317A",
          NextDialogue = 80230410,
          Subtitle = "People say many things about me — that I am cunning, that I will use any means to get what I desire. And you, Proprietress Zhiliu, are spoken of rather differently: you act in the open, with admirable finesse.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9317A"
        },
        [80230410] = {
          ContentTC = "殊不知論心狠手辣，我可連你的皮毛都夠不上。",
          DialogueId = 80230410,
          GUID = "C8D931A4",
          NextDialogue = 80230411,
          Subtitle = "Yet when it comes to true ruthlessness... I find I scarcely measure up to you.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D931A4"
        },
        [80230411] = {
          ContentTC = "可我看你不是很喜歡那位小友嗎？為了所謂的大計，把自己逼到眾叛親離的那一天，這對你而言真的值得嗎？",
          DialogueId = 80230411,
          GUID = "C8D931CE",
          NextDialogue = 80230412,
          Subtitle = "You do seem to value that young friend. But if this design of yours is seen through, you may find yourself standing alone. Even {性别：him|her} may turn away. Tell me — will it truly be worth the cost?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D931CE"
        },
        [80230412] = {
          ContentTC = "秦虬，勿對自己不了解的事情妄加評論，我以為這是為人的基本。",
          DialogueId = 80230412,
          GUID = "C8D931F8",
          NextDialogue = 80230413,
          Subtitle = "Do not pass judgment on what you do not understand. I would have thought that was the bare minimum of decency.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D931F8"
        },
        [80230413] = {
          ContentTC = "你我不過暫且利益一致，各取所需。無論是你所言的「大計」，抑或是我的目的，你都不了解分毫。",
          DialogueId = 80230413,
          GUID = "C8D93222",
          NextDialogue = 80230414,
          Subtitle = "For now, our interests align. We each take what we require. That is all. Do not pretend to understand my aims — or this \"design\" you keep circling. You do not.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93222"
        },
        [80230414] = {
          ContentTC = "怎麼生氣了？這麼開不起玩笑，消消氣消消氣。",
          DialogueId = 80230414,
          GUID = "C8D9324C",
          NextDialogue = 80230415,
          Subtitle = "Ah... did I touch a nerve? Come now. No need to bristle.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9324C"
        },
        [80230415] = {
          ContentTC = "止流大當家——您在這裡嗎？",
          DialogueId = 80230415,
          GUID = "C8D93276",
          NextDialogue = 80230416,
          Subtitle = "Miss Zhiliu — are you here?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93276"
        },
        [80230416] = {
          ContentTC = "呵呵，你的助手來找你了。看來比起在這裡討人嫌，我也該告辭了。",
          DialogueId = 80230416,
          GUID = "C8D932A0",
          NextDialogue = 80230417,
          Subtitle = "Heh. Your assistant has come looking for you. I suppose that's my cue to take my leave, before I overstay what little welcome I enjoy.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D932A0"
        },
        [80230417] = {
          ContentTC = "您這龍淵上卿大忙人，就不用在我這個見不得光的閒人身上浪費時間了。",
          DialogueId = 80230417,
          GUID = "C8D932CA",
          NextDialogue = 80230418,
          Subtitle = "After all, the High Chancellor of Loongyuan has better uses for her time than indulging an old man best kept in the shadows.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D932CA"
        },
        [80230418] = {
          ContentTC = "那便不送了。",
          DialogueId = 80230418,
          GUID = "C8D932F4",
          NextDialogue = 80230419,
          Subtitle = "See yourself out.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D932F4"
        },
        [80230419] = {
          DialogueId = 80230419,
          GUID = "C8D9331E",
          NextDialogue = 80230420,
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9331E"
        },
        [80230420] = {
          ContentTC = "止流大當家，百年春那裡有些舉棋不定的事，需要您去拿一下主意。",
          DialogueId = 80230420,
          GUID = "C8D93348",
          NextDialogue = 80230421,
          Subtitle = "Miss Zhiliu, there's a matter at EverSpring they can't resolve. They need you to make the call.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93348"
        },
        [80230421] = {
          ContentTC = "好。",
          DialogueId = 80230421,
          GUID = "C8D93372",
          NextDialogue = 80230422,
          Subtitle = "Very well.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93372"
        },
        [80230422] = {
          ContentTC = "大當家，您看起來好像有點累了……？",
          DialogueId = 80230422,
          GUID = "C8D9339C",
          NextDialogue = 80230423,
          Subtitle = "You look tired. Are you feeling unwell?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9339C"
        },
        [80230423] = {
          ContentTC = "……呵呵，沒什麼大礙。秦虬還是如以往一般問東問西，為了應付他，我不得已說了太多話。",
          DialogueId = 80230423,
          GUID = "C8D933C6",
          NextDialogue = 80230424,
          Subtitle = "...Heh. Nothing serious. Qin Qiu hasn't changed. Still prying into matters that don't concern him. Dealing with that took more words than I would have liked.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D933C6"
        },
        [80230424] = {
          ContentTC = "不過，倒是聊到了你我在執律閣下相識的過往。沒想到一轉眼也是數年過去了。",
          DialogueId = 80230424,
          GUID = "C8D933F0",
          NextDialogue = 80230425,
          Subtitle = "We ended up speaking of how you and I first met beneath the Hall of Adjudication. Hard to believe it's been so many years.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D933F0"
        },
        [80230425] = {
          ContentTC = "哇，你們竟然聊到了那麼久遠的往事！",
          DialogueId = 80230425,
          GUID = "C8D9341A",
          NextDialogue = 80230426,
          Subtitle = "You spoke of things that far back?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9341A"
        },
        [80230426] = {
          ContentTC = "那時候為了給救我的醫師伸冤，我在執律閣底下站了那麼多天，看夠了別人的冷眼，其實已經不抱什麼希望了。",
          DialogueId = 80230426,
          GUID = "C8D93444",
          NextDialogue = 80230427,
          Subtitle = "Back then, when I was trying to clear that physician's name, I was met with nothing but indifference. People looked past me, as though I weren't even there. After a while, I stopped expecting anything at all.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93444"
        },
        [80230427] = {
          ContentTC = "您來勸說我時，我雖然勉強反駁了幾句，但心中已經生出恐怕只能到這裡為止了的念頭。",
          DialogueId = 80230427,
          GUID = "C8D9346E",
          NextDialogue = 80230428,
          Subtitle = "When you came to speak to me, I forced myself to argue — but in my heart, I already knew there was nothing I could change.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9346E"
        },
        [80230428] = {
          ContentTC = "卻沒想到您當時會對我說……",
          DialogueId = 80230428,
          GUID = "C8D93498",
          NextDialogue = 80230429,
          Subtitle = "I never expected you to say what you did...",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93498"
        },
        [80230429] = {
          ContentTC = "我以無窮藏派秘法遮蔽了我們的聲音。接下來的這些話，包括現在的這份無力感，你都必須牢牢銘記，然後再也不和旁人提起。",
          DialogueId = 80230429,
          GUID = "C8D934C2",
          NextDialogue = 80230430,
          Subtitle = "I have used a secret art of the Wuqiongzang Sect to cloak our voices. What I am about to say — and this sense of powerlessness gnawing at you now — you must remember it all, and speak of it to no one.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D934C2"
        },
        [80230430] = {
          ContentTC = "我曾經與你一樣，為了清白之人的冤屈，在這執律閣下四處奔走。很快，我意識到這一行為無異於以卵擊石。",
          DialogueId = 80230430,
          GUID = "C8D934EC",
          NextDialogue = 80230431,
          Subtitle = "I once stood where you stand, beneath the Hall, pleading for someone who had been wronged. Before long, I understood it was futile. ",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D934EC"
        },
        [80230431] = {
          ContentTC = "蚍蜉之力，如何撼樹？大風九章是一整個龐大的不以個人意志為轉移的體系。",
          DialogueId = 80230431,
          GUID = "C8D93516",
          NextDialogue = 80230432,
          Subtitle = "No single person was ever going to change the system. The Nine Chapters of Dafeng are too vast, too intricate, to bend to any single will.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93516"
        },
        [80230432] = {
          ContentTC = "現在這樣做，除了讓你的良心好受一點，此外毫無作用。到了最後，世界照常運轉，不會產生絲毫變化。而你會在日復一日中背離當初的執著。",
          DialogueId = 80230432,
          GUID = "C8D93540",
          NextDialogue = 80230433,
          Subtitle = "At present, all your efforts serve only to soothe your conscience. Beyond that, they change nothing. The world will go on as it always has, without the slightest shift. And little by little, the resolve that brought you here will wear away.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93540"
        },
        [80230433] = {
          ContentTC = "所以——你現在需要暫時妥協，但我可以承諾你一件事。",
          DialogueId = 80230433,
          GUID = "C8D9356A",
          NextDialogue = 80230434,
          Subtitle = "So for now, you must compromise. But there is one thing I can promise you.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9356A"
        },
        [80230434] = {
          ContentTC = "大風九章宣告終結的一天將會來臨。我會不惜代價使這錯置顛倒的一切重新歸位……你願意相信我嗎？",
          DialogueId = 80230434,
          GUID = "C8D93594",
          NextDialogue = 80230435,
          Subtitle = "One day, the Nine Chapters of Dafeng will be brought to an end. No matter the cost, I will set things right again. Will you trust me?",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93594"
        },
        [80230435] = {
          DialogueId = 80230435,
          GUID = "C8D935BE",
          NextDialogue = 80230436,
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D935BE"
        },
        [80230436] = {
          ContentTC = "時間過得真快，沒想到您當年對我許下的承諾，眼看著就要實現了……不過大當家，您最近疲於奔波，面容都憔悴了許多，還是要以自己的身體為重啊！",
          DialogueId = 80230436,
          GUID = "C8D935E8",
          NextDialogue = 80230437,
          Subtitle = "Time really does fly... It feels as though, all at once, the promise you made back then is almost within reach. But Miss Zhiliu — you've been pushing yourself hard. You look worn. Please, take care of yourself.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D935E8"
        },
        [80230437] = {
          ContentTC = "放心，我心中有數。",
          DialogueId = 80230437,
          GUID = "C8D93612",
          NextDialogue = 80230438,
          Subtitle = "Don't worry. I know my limits.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93612"
        },
        [80230438] = {
          ContentTC = "大當家，你知道嗎？有很多人怕你，懼你，在背後腹誹於你。",
          DialogueId = 80230438,
          GUID = "C8D9363C",
          NextDialogue = 80230439,
          Subtitle = "Many people fear you, Miss Zhiliu. They speak ill of you when you're not around.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D9363C"
        },
        [80230439] = {
          ContentTC = "那些人說你鐵石心腸，行事如同修羅，只會做做表面的慈善工夫，但只有我知道……您是什麼樣的人。",
          DialogueId = 80230439,
          GUID = "C8D93666",
          NextDialogue = 80230440,
          Subtitle = "They say you're hard as iron — ruthless, unfeeling. That any mercy you show is merely for show. But I know better. I know what kind of person you truly are.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93666"
        },
        [80230440] = {
          ContentTC = "我非常佩服您的那份決心！跟在您身邊越久，我越感謝，那一天遇到的是您。",
          DialogueId = 80230440,
          GUID = "C8D93690",
          NextDialogue = 80230441,
          Subtitle = "I truly admire your resolve. The longer I remain by your side, the more grateful I am that it was you I met that day beneath the Hall.",
          VoiceName = "voice/$Locale$/inv/Zhiliu/004/C8D93690"
        },
        [80230441] = {
          ContentTC = "呵呵……怎麼突然說這麼多。你要是謝我啊，等百年春那邊的事解決了也不遲。",
          DialogueId = 80230441,
