        [120155051] = {
          ContentTC = "不知道你在說什麼……",
          DialogueId = 120155051,
          GUID = "120155051.0",
          NextDialogue = 12015507,
          Subtitle = "Not really..."
        },
        [120155052] = {
          ContentTC = "扶疏也是百年之前的人？！",
          DialogueId = 120155052,
          GUID = "120155052.0",
          NextDialogue = 12015509,
          Subtitle = "Fushu's more than a hundred years old!?"
        },
        [120186141] = {
          ContentTC = "他們也不是故意的。",
          DialogueId = 120186141,
          GUID = "120186141.0",
          ImprPlusId = 1202,
          NextDialogue = 12018616,
          Subtitle = "They were just trying to help."
        },
        [120186142] = {
          ContentTC = "罰他們三天工資！",
          DialogueId = 120186142,
          GUID = "120186142.0",
          ImprPlusId = 1205,
          NextDialogue = 12018619,
          Subtitle = "Dock three days' pay from each of them!"
        },
        [120193051] = {
          ContentTC = "幸會幸會……原來華胥之外的地方，還有如此拉風的職業！相逢即是有緣，何不結伴一程？",
          DialogueId = 120193051,
          GUID = "120193050",
          NextDialogue = 12019307,
          SpeakNpcId = 210021,
          Subtitle = "A pleasure... Seems like the world beyond Huaxu has no shortage of colourful characters! Since fate brought us together, why not share the road for a while?",
          VoiceName = "voice/$Locale$/story/1201/120193/120193050"
        },
        [120193141] = {
          ContentTC = "你好。",
          DialogueId = 120193141,
          GUID = "1E16CD3A",
          NextDialogue = 12019316,
          Subtitle = "Hello.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CD3A"
        },
        [120223281] = {
          ContentTC = "我不想看著華胥陷入禍亂，我想看看有什麼我能做的。",
          DialogueId = 120223281,
          GUID = "120223281.0",
          ImprPlusId = 1204,
          NextDialogue = 12022329,
          Subtitle = "I don't want to stand by and watch Huaxu fall apart. I want to see what I can do."
        },
        [120223282] = {
          ContentTC = "今天實在是發生了太多事情，我只想回冰湖城……",
          DialogueId = 120223282,
          GUID = "120223282.0",
          ImprPlusId = 1201,
          NextDialogue = 12022329,
          Subtitle = "Too much has happened today... I just want to go back to Icelake."
        },
        [120230021] = {
          ContentTC = "感覺那個人有點可憐……",
          DialogueId = 120230021,
          GUID = "120230021.0",
          ImprPlusId = 1204,
          NextDialogue = 12023003,
          Subtitle = "He did seem... a little pitiful."
        },
        [120230022] = {
          ContentTC = "雖然他的想法可能有錯，但也不應該這樣對待他。",
          DialogueId = 120230022,
          GUID = "120230022.0",
          ImprPlusId = 1202,
          NextDialogue = 12023003,
          Subtitle = "Maybe he was wrong, but it didn't feel right to cast him out like that."
        },
        [120230023] = {
          ContentTC = "為了防止人心動搖，適當的手段也是應該的。",
          DialogueId = 120230023,
          GUID = "120230023.0",
          ImprPlusId = 1201,
          NextDialogue = 12023003,
          Subtitle = "Sometimes harsh measures are necessary to keep people in line."
        },
        [120230024] = {
          ContentTC = "做得好，就該這樣！",
          DialogueId = 120230024,
          GUID = "120230024.0",
          ImprPlusId = 1205,
          NextDialogue = 12023003,
          Subtitle = "That was badass! He had it coming."
        },
        [120233101] = {
          ContentTC = "講述經過",
          DialogueId = 120233101,
          GUID = "120233101.0",
          NextDialogue = 12023311,
          Subtitle = "Fill her in"
        },
        [120233131] = {
          ContentTC = "試圖辯解",
          DialogueId = 120233131,
          GUID = "120233131.0",
          NextDialogue = 12023314,
          Subtitle = "Try to explain"
        },
