        },
        [510034142] = {
          ContentTC = "但我們誰都知道暗流正在醞釀，正在壯大，終有一天，它會吞噬我們現有的一切。在這之前，我會乘上火車前往預兆的源頭。",
          DialogueId = 510034142,
          GUID = "510034142.0",
          SpeakNpcId = 700015,
          Subtitle = "But we all know a dark tide is rising, gaining strength. One day it will consume everything we cherish. But before that day comes, I shall journey to the source that has been prophesied.",
          TalkActionId = {
            [1] = "700093:Talk01_End"
          }
        },
        [510034143] = {
          ContentTC = "冬天的寒冷已經不再困擾我了，謝謝你，狩月人。",
          DialogueId = 510034143,
          GUID = "510034143.0",
          SpeakNpcId = 700080,
          Subtitle = "I no longer have to worry about the cold winter. Thank you so much, Phoxhunter.",
          TalkActionId = {
            [1] = "700094:Explain02_Start"
          }
        },
        [510035031] = {
          ContentTC = "（艾瑪匆忙將花放在指定地點，並按流程獻上了感謝致辭，但她的走神還是引起了老師的嘀咕。）",
          DialogueId = 510035031,
          Duration = 3,
          GUID = "510035031.0",
          Subtitle = [[
Emma quickly places the floral tribute at the designated location and offers an acknowledgement speech according to the program agenda.
However, her teacher is displeased with her momentary distraction.]]
        },
        [510035041] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "好了，下面就是自由活動時間，半個小時後還在雕像下集合，千萬別走太遠了。",
          DialogueId = 510035041,
          GUID = "510035041.0",
          NextDialogue = 510035042,
          SpeakNpcId = 700086,
          Subtitle = "Alright. We'll have a short break now. Feel free to explore this place, but do not stray too far. We will regather in half an hour beneath the statue.",
          TalkActionId = {
            [1] = "700086:Sigh_End",
            [2] = "700086:Explain01_Start"
          }
        },
        [510035042] = {
          Camera = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（紀念活動結束後，艾瑪還是一個人發呆，時不時喃喃自語著什麽。）",
          DialogueId = 510035042,
          GUID = "510035042.0",
          Subtitle = "(The memorial event has ended. However, Emma lingers alone, mumbling absentmindedly to herself.)",
          TalkActionId = {
            [1] = "700016:Confident_Start"
          }
        },
        [510035051] = {
          ContentTC = "這麼敷衍老師可不行，當心被她記小本本哦。",
          DialogueId = 510035051,
          GUID = "510035051.0",
          ImprPlusId = 1001,
          NextDialogue = 510035054,
          Subtitle = "You're totally spacing out. Pretty sure your teacher's putting you on the naughty list."
        },
        [510035052] = {
          ContentTC = "你是不是有比參加紀念儀式更想去做的事呀？",
          DialogueId = 510035052,
          GUID = "510035052.0",
          ImprPlusId = 1004,
          NextDialogue = 510035055,
          Subtitle = "Is there something you'd rather be doing instead of participating in this memorial ceremony?"
        },
        [510035053] = {
          ContentTC = "在這種正式場合走神是對被紀念者的不敬。",
          DialogueId = 510035053,
          GUID = "510035053.0",
          ImprPlusId = 1002,
          NextDialogue = 510035056,
          Subtitle = "Tuning out on an occasion like this is quite disrespectful, especially to those being memorialised."
        },
        [510035054] = {
          ContentTC = "老師才不會呢！雖然啰嗦，但對我們她可有耐心了！",
          DialogueId = 510035054,
          GUID = "510035054",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextDialogue = 51003506,
          SpeakNpcId = 700016,
          Subtitle = "No, she won't! Miss Lisse nags from time to time, but she's actually very patient with us!"
        },
        [510035055] = {
          ContentTC = "哎呀！這麽明顯嗎？",
          DialogueId = 510035055,
          GUID = "510035055",
          NextDialogue = 51003506,
          SpeakNpcId = 700016,
          Subtitle = "Oh! Am I being that obvious?"
        },
        [510035056] = {
