          DialogueId = 510055071,
          GUID = "510055071.0",
          SpeakNpcId = 700117,
          Subtitle = "While you're out fishing, I'll brainstorm some enhancements to the recipe."
        },
        [510056011] = {
          ContentTC = "（留意到北風莓的果皮上沾有血漬。）",
          DialogueId = 510056011,
          GUID = "510056011.0",
          ImprPlusId = 1003,
