          DialogueId = 510056012,
          GUID = "510056012.0",
          ImprPlusId = 1004,
          NextDialogue = 51005603,
          Subtitle = "(You notice the bloodstains on Marcus's clothes.)"
        },
        [510057121] = {
          ContentTC = "（誠實地表達對食物的喜愛，一定能收獲所有人的贊美。）",
          DialogueId = 510057121,
          GUID = "510057121.0",
          ImprPlusId = 1002,
          NextDialogue = 51005713,
