        },
        [510057122] = {
          ContentTC = "（撒謊說好吃但不夠有特色，勸馬庫斯養好身體後再找下一份工作。）",
          DialogueId = 510057122,
          GUID = "510057122.0",
          ImprPlusId = 1004,
          NextDialogue = 51005716,
          Subtitle = "(Lie to Marcus by saying that the dish is good but ordinary. Advise him to take good care of himself first and find another job once he gets better.)"
        },
        [510058021] = {
          ContentTC = "城裡所有箱子不都是給我的嗎？",
          DialogueId = 510058021,
          GUID = "510058021.0",
          ImprPlusId = 1005,
          NextDialogue = 51005803,
