          DialogueId = 510070012,
          GUID = "510070012.0",
          ImprPlusId = 1005,
          NextDialogue = 51007003,
          Subtitle = "You can't even throw a comeback?"
        },
        [510070051] = {
          ContentTC = "讓一下，我有辦法讓她好好說話。",
