          DialogueId = 510071162,
          GUID = "510071162.0",
          ImprPlusId = 1005,
          NextDialogue = 51007119,
          Subtitle = "(Unfolds another star and reads the message aloud.)"
        },
        [510073021] = {
          ContentTC = "欲望就是搞清楚你想要什麼。",
          DialogueId = 510073021,
          GUID = "510073021.0",
          ImprPlusId = 1001,
          NextDialogue = 510073024,
          Subtitle = "Passion is the will to unravel what you really want."
